@RestController
@RequestMapping("/api/entities")
public class EntityREST {

    private static final Logger logger = LoggerFactory.getLogger(EntityREST.class);

    @Autowired
    private AtlasTypeRegistry typeRegistry;

    @Autowired
    private AtlasEntityStore entityStore;

    @GetMapping("/{guid}")
    public ResponseEntity<AtlasEntity> getEntityByGuid(@PathVariable String guid) {
        logger.info("Fetching entity with GUID: {}", guid);
        AtlasEntity entity = entityStore.getByGuid(guid);
        return ResponseEntity.ok(entity);
    }

    @GetMapping("/unique-attributes")
    public ResponseEntity<List<String>> getUniqueAttributes() {
        logger.info("Fetching unique attributes");
        List<String> uniqueAttributes = typeRegistry.getUniqueAttributes();
        return ResponseEntity.ok(uniqueAttributes);
    }

    @PostMapping
    public ResponseEntity<AtlasEntity> createEntity(@RequestBody AtlasEntity entity) {
        logger.info("Creating entity: {}", entity);
        AtlasEntity createdEntity = entityStore.create(entity);
        return ResponseEntity.status(HttpStatus.CREATED).body(createdEntity);
    }

    @PutMapping("/{guid}")
    public ResponseEntity<AtlasEntity> updateEntity(@PathVariable String guid, @RequestBody AtlasEntity entity) {
        logger.info("Updating entity with GUID: {}", guid);
        AtlasEntity updatedEntity = entityStore.update(guid, entity);
        return ResponseEntity.ok(updatedEntity);
    }

    @PatchMapping("/{guid}")
    public ResponseEntity<AtlasEntity> partiallyUpdateEntity(@PathVariable String guid, @RequestBody Map<String, Object> updates) {
        logger.info("Partially updating entity with GUID: {}", guid);
        AtlasEntity updatedEntity = entityStore.partialUpdate(guid, updates);
        return ResponseEntity.ok(updatedEntity);
    }

    @DeleteMapping("/{guid}")
    public ResponseEntity<Void> deleteEntity(@PathVariable String guid) {
        logger.info("Deleting entity with GUID: {}", guid);
        entityStore.delete(guid);
        return ResponseEntity.noContent().build();
    }

    @PostMapping("/{guid}/classifications")
    public ResponseEntity<Void> addClassification(@PathVariable String guid, @RequestBody String classification) {
        logger.info("Adding classification '{}' to entity with GUID: {}", classification, guid);
        entityStore.addClassification(guid, classification);
        return ResponseEntity.noContent().build();
    }

    @DeleteMapping("/{guid}/classifications/{classification}")
    public ResponseEntity<Void> removeClassification(@PathVariable String guid, @PathVariable String classification) {
        logger.info("Removing classification '{}' from entity with GUID: {}", classification, guid);
        entityStore.removeClassification(guid, classification);
        return ResponseEntity.noContent().build();
    }
}

