class Jsr303FacetValidatingInteraction {

    private Mockery context;
    private Validator validator;
    private Jsr303PropertyValidationFacet validationFacet;

    @Before
    public void setUp() {
        context = new Mockery();
        ValidatorFactory factory = Validation.buildDefaultValidatorFactory();
        validator = factory.getValidator();
        validationFacet = new Jsr303PropertyValidationFacet(validator);
    }

    @After
    public void tearDown() {
        context.assertIsSatisfied();
    }

    @Test
    public void testValidProperty() {
        DomainObject obj = new DomainObject();
        obj.setValidProperty("Valid Value");

        Set<ConstraintViolation<DomainObject>> violations = validationFacet.validate(obj);

        assertTrue("Expected no violations", violations.isEmpty());
    }

    @Test
    public void testInvalidProperty() {
        DomainObject obj = new DomainObject();
        obj.setInvalidProperty("Invalid Value");

        Set<ConstraintViolation<DomainObject>> violations = validationFacet.validate(obj);

        assertEquals("Expected one violation", 1, violations.size());
        assertEquals("Invalid value for property", violations.iterator().next().getMessage());
    }

    @Test
    public void testCustomValidation() {
        DomainObject obj = new DomainObject();
        obj.setCustomValidatedProperty("Invalid Custom Value");

        Set<ConstraintViolation<DomainObject>> violations = validationFacet.validate(obj);

        assertEquals("Expected one violation", 1, violations.size());
        assertEquals("Custom validation failed", violations.iterator().next().getMessage());
    }
}

public class BytesUtil {

    public static void writeByte(byte[] array, int offset, byte value) {
        array[offset] = value;
    }

    public static byte readByte(byte[] array, int offset) {
        return array[offset];
    }

    public static void writeShort(byte[] array, int offset, short value) {
        array[offset] = (byte) (value >> 8);
        array[offset + 1] = (byte) value;
    }

    public static short readShort(byte[] array, int offset) {
        return (short) ((array[offset] << 8) | (array[offset + 1] & 0xFF));
    }

    public static void writeInt(byte[] array, int offset, int value) {
        array[offset] = (byte) (value >> 24);
        array[offset + 1] = (byte) (value >> 16);
        array[offset + 2] = (byte) (value >> 8);
        array[offset + 3] = (byte) value;
    }

    public static int readInt(byte[] array, int offset) {
        return (array[offset] << 24) | ((array[offset + 1] & 0xFF) << 16) |
               ((array[offset + 2] & 0xFF) << 8) | (array[offset + 3] & 0xFF);
    }

    public static void writeLong(byte[] array, int offset, long value) {
        for (int i = 0; i < 8; i++) {
            array[offset + i] = (byte) (value >> (56 - i * 8));
        }
    }

    public static long readLong(byte[] array, int offset) {
        long value = 0;
        for (int i = 0; i < 8; i++) {
            value = (value << 8) | (array[offset + i] & 0xFF);
        }
        return value;
    }

    public static void writeVInt(byte[] array, int offset, int value) {
        if ((value & ~0x7F) == 0) {
            array[offset] = (byte) value;
        } else if ((value & ~0x3FFF) == 0) {
            array[offset] = (byte) (0x80 | (value & 0x7F));
            array[offset + 1] = (byte) (value >> 7);
        } else if ((value & ~0x1FFFFF) == 0) {
            array[offset] = (byte) (0xC0 | (value & 0x7F));
            array[offset + 1] = (byte) (value >> 7);
            array[offset + 2] = (byte) (value >> 14);
        } else {
            array[offset] = (byte) (0xE0 | (value & 0x7F));
            array[offset + 1] = (byte) (value >> 7);
            array[offset + 2] = (byte) (value >> 14);
            array[offset + 3] = (byte) (value >> 21);
        }
    }

    public static int readVInt(byte[] array, int offset) {
        int value = array[offset] & 0x7F;
        if ((array[offset] & 0x80) != 0) {
            value |= (array[offset + 1] & 0xFF) << 7;
            if ((array[offset] & 0xC0) == 0x80) {
                return value;
            }
            value |= (array[offset + 2] & 0xFF) << 14;
            if ((array[offset] & 0xE0) == 0xC0) {
                return value;
            }
            value |= (array[offset + 3] & 0xFF) << 21;
        }
        return value;
    }

    public static void writeString(byte[] array, int offset, String value) {
        byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
        writeVInt(array, offset, bytes.length);
        System.arraycopy(bytes, 0, array, offset + 1, bytes.length);
    }

    public static String readString(byte[] array, int offset) {
        int length = readVInt(array, offset);
        return new String(array, offset + 1, length, StandardCharsets.UTF_8);
    }

    public static void writeIntArray(byte[] array, int offset, int[] values) {
        writeVInt(array, offset, values.length);
        for (int i = 0; i < values.length; i++) {
            writeInt(array, offset + 1 + i * 4, values[i]);
        }
    }

    public static int[] readIntArray(byte[] array, int offset) {
        int length = readVInt(array, offset);
        int[] values = new int[length];
        for (int i = 0; i < length; i++) {
            values[i] = readInt(array, offset + 1 + i * 4);
        }
        return values;
    }

    public static void writeBooleanArray(byte[] array, int offset, boolean[] values) {
        writeVInt(array, offset, values.length);
        for (int i = 0; i < values.length; i++) {
            array[offset + 1 + i] = (byte) (values[i] ? 1 : 0);
        }
    }

    public static boolean[] readBooleanArray(byte[] array, int offset) {
        int length = readVInt(array, offset);
        boolean[] values = new boolean[length];
        for (int i = 0; i < length; i++) {
            values[i] = array[offset + 1 + i] != 0;
        }
        return values;
    }

    public static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xFF & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static byte[] hexToBytes(String hex) {
        int length = hex.length();
        byte[] bytes = new byte[length / 2];
        for (int i = 0; i < length; i += 2) {
            bytes[i / 2] = (byte) ((Character.digit(hex.charAt(i), 16) << 4)
                                 + Character.digit(hex.charAt(i + 1), 16));
        }
        return bytes;
    }

    public static int compare(byte[] a, byte[] b) {
        int minLength = Math.min(a.length, b.length);
        for (int i = 0; i < minLength; i++) {
            int cmp = Byte.compare(a[i], b[i]);
            if (cmp != 0) {
                return cmp;
            }
        }
        return Integer.compare(a.length, b.length);
    }

    public static boolean compareSubArray(byte[] array, int offset, byte[] subArray) {
        if (offset + subArray.length > array.length) {
            return false;
        }
        for (int i = 0; i < subArray.length; i++) {
            if (array[offset + i] != subArray[i]) {
                return false;
            }
        }
        return true;
    }

    public static int sizeOfLong(long value) {
        if (value == 0) return 1;
        int size = 0;
        while (value != 0) {
            size++;
            value >>>= 8;
        }
        return size;
    }
}

