class CopyOnAccessInMemoryStateInternalsTest {

    private CopyOnAccessInMemoryStateInternals stateInternals;

    @BeforeEach
    void setUp() {
        stateInternals = new CopyOnAccessInMemoryStateInternals();
    }

    @Test
    void testBagState() {
        BagState<String> bagState = stateInternals.getBagState("bagKey");
        bagState.add("value1");
        bagState.add("value2");
        assertTrue(bagState.contains("value1"));
        assertTrue(bagState.contains("value2"));
        assertEquals(2, bagState.size());
    }

    @Test
    void testValueState() {
        ValueState<Integer> valueState = stateInternals.getValueState("valueKey");
        valueState.update(42);
        assertEquals(42, valueState.value());
        valueState.clear();
        assertNull(valueState.value());
    }

    @Test
    void testSetState() {
        SetState<String> setState = stateInternals.getSetState("setKey");
        setState.add("value1");
        setState.add("value2");
        assertTrue(setState.contains("value1"));
        assertTrue(setState.contains("value2"));
        assertEquals(2, setState.size());
        setState.clear();
        assertEquals(0, setState.size());
    }

    @Test
    void testMapState() {
        MapState<String, Integer> mapState = stateInternals.getMapState("mapKey");
        mapState.put("key1", 1);
        mapState.put("key2", 2);
        assertEquals(1, mapState.get("key1"));
        assertEquals(2, mapState.get("key2"));
        assertEquals(2, mapState.size());
        mapState.remove("key1");
        assertNull(mapState.get("key1"));
        assertEquals(1, mapState.size());
    }

    @Test
    void testCommitStateChanges() {
        BagState<String> bagState = stateInternals.getBagState("commitBagKey");
        bagState.add("value1");
        stateInternals.commit();
        assertTrue(bagState.contains("value1"));
        bagState.clear();
        assertFalse(bagState.contains("value1"));
        stateInternals.commit();
        assertFalse(bagState.contains("value1"));
    }

    @Test
    void testWatermarkHoldStates() {
        WatermarkHoldState<Long> watermarkState = stateInternals.getWatermarkHoldState("watermarkKey");
        watermarkState.update(100L);
        assertEquals(100L, watermarkState.getCurrentWatermark());
        stateInternals.commit();
        watermarkState.update(200L);
        assertEquals(200L, watermarkState.getCurrentWatermark());
        stateInternals.commit();
        assertEquals(200L, watermarkState.getCurrentWatermark());
    }

    @Test
    void testStateAfterOperations() {
        ValueState<String> valueState = stateInternals.getValueState("operationKey");
        valueState.update("initialValue");
        assertEquals("initialValue", valueState.value());
        valueState.update("newValue");
        assertEquals("newValue", valueState.value());
        valueState.clear();
        assertNull(valueState.value());
    }
}

