class ChecksumTransferTest {

    private ProxyRepository proxyRepository;

    @BeforeEach
    void setUp() {
        proxyRepository = new ProxyRepository();
    }

    @Test
    void testDisabledConnectors() {
        proxyRepository.setConnectorsEnabled(false);
        assertThrows(ConnectorDisabledException.class, () -> {
            proxyRepository.downloadArtifact("groupId:artifactId:version");
        });
    }

    @Test
    void testValidChecksum() {
        proxyRepository.setChecksumPolicy(ChecksumPolicy.FAIL);
        proxyRepository.uploadArtifact("groupId:artifactId:version", "valid-checksum");
        boolean result = proxyRepository.downloadArtifact("groupId:artifactId:version");
        assertTrue(result);
        assertTrue(proxyRepository.isChecksumValid("groupId:artifactId:version", "valid-checksum"));
    }

    @Test
    void testMissingChecksum() {
        proxyRepository.setChecksumPolicy(ChecksumPolicy.FAIL);
        proxyRepository.uploadArtifact("groupId:artifactId:version", null);
        assertThrows(ChecksumMissingException.class, () -> {
            proxyRepository.downloadArtifact("groupId:artifactId:version");
        });
    }

    @Test
    void testIncorrectChecksum() {
        proxyRepository.setChecksumPolicy(ChecksumPolicy.FAIL);
        proxyRepository.uploadArtifact("groupId:artifactId:version", "incorrect-checksum");
        assertThrows(ChecksumValidationException.class, () -> {
            proxyRepository.downloadArtifact("groupId:artifactId:version");
        });
    }

    @Test
    void testChecksumPolicyIgnore() {
        proxyRepository.setChecksumPolicy(ChecksumPolicy.IGNORE);
        proxyRepository.uploadArtifact("groupId:artifactId:version", "invalid-checksum");
        boolean result = proxyRepository.downloadArtifact("groupId:artifactId:version");
        assertTrue(result);
        assertFalse(proxyRepository.isChecksumValid("groupId:artifactId:version", "invalid-checksum"));
    }

    @Test
    void testChecksumPolicyFix() {
        proxyRepository.setChecksumPolicy(ChecksumPolicy.FIX);
        proxyRepository.uploadArtifact("groupId:artifactId:version", "invalid-checksum");
        boolean result = proxyRepository.downloadArtifact("groupId:artifactId:version");
        assertTrue(result);
        assertTrue(proxyRepository.isChecksumValid("groupId:artifactId:version", "fixed-checksum"));
    }

    @Test
    void testLocalChecksumPresentRemoteAbsent() {
        proxyRepository.uploadArtifact("groupId:artifactId:version", "valid-checksum");
        proxyRepository.setRemoteResourceAbsent(true);
        boolean result = proxyRepository.downloadArtifact("groupId:artifactId:version");
        assertFalse(result);
        assertTrue(proxyRepository.isLocalChecksumValid("groupId:artifactId:version", "valid-checksum"));
    }
}

public class SQLTemplateParserTokenManager {
    private Stack<String> stateStack;
    private String currentState;
    private StringBuilder literalValue;
    private StringBuffer stringBuffer;

    public SQLTemplateParserTokenManager() {
        stateStack = new Stack<>();
        currentState = "INITIAL";
        literalValue = new StringBuilder();
        stringBuffer = new StringBuffer();
    }

    public void pushState(String newState) {
        stateStack.push(currentState);
        currentState = newState;
    }

    public void popState() {
        if (!stateStack.isEmpty()) {
            currentState = stateStack.pop();
        }
    }

    public boolean isCurrentState(String requiredState) {
        return currentState.equals(requiredState);
    }

    public void escapeCharacter(char character) {
        // Simple escape logic, could be improved
        if (character == '\'') {
            stringBuffer.append("''");
        } else {
            stringBuffer.append(character);
        }
    }

    public void addLiteralValue(String value) {
        literalValue.append(value);
    }

    public String getLiteralValue() {
        return literalValue.toString();
    }

    public String getCurrentState() {
        return currentState;
    }

    public String getStringBufferContent() {
        return stringBuffer.toString();
    }
}

