public abstract class AbstractTestTransactionLifecycle {

    protected abstract Dataset createDataset();

    protected abstract boolean isTransactionSupported();

    @Test
    public void testBeginTransaction() {
        Dataset dataset = createDataset();
        assertTrue(dataset.beginTransaction());
    }

    @Test
    public void testCommitTransaction() {
        Dataset dataset = createDataset();
        dataset.beginTransaction();
        assertTrue(dataset.commitTransaction());
    }

    @Test
    public void testAbortTransaction() {
        Dataset dataset = createDataset();
        dataset.beginTransaction();
        assertTrue(dataset.abortTransaction());
    }

    @Test
    public void testReadTransaction() {
        Dataset dataset = createDataset();
        dataset.beginTransaction();
        assertEquals("READ", dataset.getTransactionType());
        dataset.commitTransaction();
    }

    @Test
    public void testWriteTransaction() {
        Dataset dataset = createDataset();
        dataset.beginTransaction();
        dataset.writeData("data");
        assertEquals("WRITE", dataset.getTransactionType());
        dataset.commitTransaction();
    }

    @Test
    public void testReadPromoteTransaction() {
        Dataset dataset = createDataset();
        dataset.beginTransaction();
        dataset.readData("data");
        assertTrue(dataset.promoteTransaction());
        assertEquals("READ_PROMOTE", dataset.getTransactionType());
        dataset.commitTransaction();
    }

    @Test
    public void testReadCommittedPromoteTransaction() {
        Dataset dataset = createDataset();
        dataset.beginTransaction();
        dataset.readData("data");
        assertTrue(dataset.commitTransaction());
        dataset.beginTransaction();
        assertTrue(dataset.promoteTransaction());
        assertEquals("READ_COMMITTED_PROMOTE", dataset.getTransactionType());
        dataset.commitTransaction();
    }

    @Test
    public void testInvalidCommitWithoutBegin() {
        Dataset dataset = createDataset();
        assertThrows(IllegalStateException.class, dataset::commitTransaction);
    }

    @Test
    public void testInvalidAbortWithoutBegin() {
        Dataset dataset = createDataset();
        assertThrows(IllegalStateException.class, dataset::abortTransaction);
    }

    @Test
    public void testConcurrentTransactions() {
        Dataset dataset = createDataset();
        assertTrue(dataset.beginTransaction());
        assertThrows(IllegalStateException.class, () -> {
            dataset.beginTransaction();
        });
        dataset.commitTransaction();
    }

    @Test
    public void testTransactionSupport() {
        assertTrue(isTransactionSupported());
    }
}

