public class CompositeCollectionTest extends AbstractCollectionTest {

    @Test
    public void testAdd() {
        CompositeCollection composite = new CompositeCollection();
        assertTrue(composite.add("element1"));
        assertTrue(composite.add("element2"));
        assertFalse(composite.add("element1")); // should not add duplicate
        assertEquals(2, composite.size());
    }

    @Test
    public void testRemove() {
        CompositeCollection composite = new CompositeCollection();
        composite.add("element1");
        composite.add("element2");
        assertTrue(composite.remove("element1"));
        assertFalse(composite.remove("element1")); // should not remove non-existent
        assertEquals(1, composite.size());
    }

    @Test
    public void testContains() {
        CompositeCollection composite = new CompositeCollection();
        composite.add("element1");
        assertTrue(composite.contains("element1"));
        assertFalse(composite.contains("element2"));
    }

    @Test
    public void testIsEmpty() {
        CompositeCollection composite = new CompositeCollection();
        assertTrue(composite.isEmpty());
        composite.add("element1");
        assertFalse(composite.isEmpty());
    }

    @Test
    public void testSize() {
        CompositeCollection composite = new CompositeCollection();
        assertEquals(0, composite.size());
        composite.add("element1");
        composite.add("element2");
        assertEquals(2, composite.size());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testUnsupportedOperation() {
        CompositeCollection composite = new CompositeCollection();
        composite.clear(); // should not throw
        composite.add("element1");
        composite.remove("element1");
        composite.removeAll(null); // should throw
    }

    @Test
    public void testRetainAll() {
        CompositeCollection composite = new CompositeCollection();
        composite.add("element1");
        composite.add("element2");
        CompositeCollection toRetain = new CompositeCollection();
        toRetain.add("element1");
        assertTrue(composite.retainAll(toRetain));
        assertEquals(1, composite.size());
        assertTrue(composite.contains("element1"));
        assertFalse(composite.contains("element2"));
    }

    @Test
    public void testRemoveAll() {
        CompositeCollection composite = new CompositeCollection();
        composite.add("element1");
        composite.add("element2");
        CompositeCollection toRemove = new CompositeCollection();
        toRemove.add("element1");
        assertTrue(composite.removeAll(toRemove));
        assertEquals(1, composite.size());
        assertFalse(composite.contains("element1"));
        assertTrue(composite.contains("element2"));
    }

    @Test
    public void testClear() {
        CompositeCollection composite = new CompositeCollection();
        composite.add("element1");
        composite.add("element2");
        composite.clear();
        assertTrue(composite.isEmpty());
        assertEquals(0, composite.size());
