    public ShiroHttpSession(Session shiroSession) {
        this.shiroSession = shiroSession;
    }

    @Override
    public long getCreationTime() {
        return shiroSession.getStartTimestamp().getTime();
    }

    @Override
    public String getId() {
        return shiroSession.getId().toString();
    }

    @Override
    public long getLastAccessedTime() {
        return shiroSession.getLastAccessTime().getTime();
    }

    @Override
    public void setMaxInactiveInterval(int interval) {
        shiroSession.setTimeout(interval * 1000L);
    }

    @Override
    public int getMaxInactiveInterval() {
        return (int) (shiroSession.getTimeout() / 1000);
    }

    @Override
    public boolean isNew() {
        return shiroSession.getAttribute("isNew") == null;
    }

    @Override
    public void setAttribute(String name, Object value) {
        attributes.put(name, value);
        shiroSession.setAttribute(name, value);
        notifyBindingListeners(name, value);
    }

    @Override
    public Object getAttribute(String name) {
        return attributes.get(name);
    }

    @Override
    public void removeAttribute(String name) {
        attributes.remove(name);
        shiroSession.removeAttribute(name);
        notifyBindingListeners(name, null);
    }

    @Override
    public Enumeration<String> getAttributeNames() {
        return new Enumeration<String>() {
            private final Iterator<String> iterator = attributes.keySet().iterator();

            @Override
            public boolean hasMoreElements() {
                return iterator.hasNext();
            }

            @Override
            public String nextElement() {
                return iterator.next();
            }
        };
    }

    @Override
    public void invalidate() {
        shiroSession.stop();
        attributes.clear();
    }

    private void notifyBindingListeners(String name, Object value) {
        if (value instanceof HttpSessionBindingListener) {
            HttpSessionBindingListener listener = (HttpSessionBindingListener) value;
            listener.valueBound(new HttpSessionBindingEvent(this, name));
        }
    }
}

