public class Rotation implements Serializable {
    private static final long serialVersionUID = 1L;
    public static final Rotation IDENTITY = new Rotation(1, 0, 0, 0);

    private double q0, q1, q2, q3;

    public Rotation(double q0, double q1, double q2, double q3) {
        this.q0 = q0;
        this.q1 = q1;
        this.q2 = q2;
        this.q3 = q3;
        normalize();
    }

    public Rotation(double angle, double axisX, double axisY, double axisZ) {
        double halfAngle = angle / 2.0;
        double sinHalfAngle = Math.sin(halfAngle);
        this.q0 = Math.cos(halfAngle);
        this.q1 = axisX * sinHalfAngle;
        this.q2 = axisY * sinHalfAngle;
        this.q3 = axisZ * sinHalfAngle;
        normalize();
    }

    public Rotation(double[][] matrix) {
        // Assuming matrix is a valid rotation matrix
        // Code smells: No validation of matrix dimensions
        double trace = matrix[0][0] + matrix[1][1] + matrix[2][2];
        if (trace > 0) {
            double s = Math.sqrt(trace + 1.0) * 2; // S=4*qw
            this.q0 = 0.25 * s;
            this.q1 = (matrix[2][1] - matrix[1][2]) / s;
            this.q2 = (matrix[0][2] - matrix[2][0]) / s;
            this.q3 = (matrix[1][0] - matrix[0][1]) / s;
        } else {
            // Code smells: Handling singularity without clear separation
            int[] nxt = {1, 2, 0};
            int i = 0;
            if (matrix[1][1] > matrix[0][0]) i = 1;
            if (matrix[2][2] > matrix[i][i]) i = 2;
            int j = nxt[i];
            int k = nxt[j];

            double s = Math.sqrt(matrix[i][i] - matrix[j][j] - matrix[k][k] + 1.0);
            double[] q = new double[4];
            q[i] = s * 0.5;
            s = 0.5 / s;
            q[3] = (matrix[k][j] - matrix[j][k]) * s;
            q[j] = (matrix[j][i] + matrix[i][j]) * s;
            q[k] = (matrix[k][i] + matrix[i][k]) * s;
            this.q0 = q[0];
            this.q1 = q[1];
            this.q2 = q[2];
            this.q3 = q[3];
        }
        normalize();
    }

    public double[] getQuaternion() {
        return new double[]{q0, q1, q2, q3};
    }

    public void normalize() {
        double norm = Math.sqrt(q0 * q0 + q1 * q1 + q2 * q2 + q3 * q3);
        if (norm > 0) {
            q0 /= norm;
            q1 /= norm;
            q2 /= norm;
            q3 /= norm;
        }
    }

    public double[][] toRotationMatrix() {
        double[][] matrix = new double[3][3];
        matrix[0][0] = 1 - 2 * (q2 * q2 + q3 * q3);
        matrix[0][1] = 2 * (q1 * q2 - q0 * q3);
        matrix[0][2] = 2 * (q1 * q3 + q0 * q2);
        matrix[1][0] = 2 * (q1 * q2 + q0 * q3);
        matrix[1][1] = 1 - 2 * (q1 * q1 + q3 * q3);
        matrix[1][2] = 2 * (q2 * q3 - q0 * q1);
        matrix[2][0] = 2 * (q1 * q3 - q0 * q2);
        matrix[2][1] = 2 * (q2 * q3 + q0 * q1);
        matrix[2][2] = 1 - 2 * (q1 * q1 + q2 * q2);
        return matrix;
    }

    public double[] applyTo(double[] vector) {
        double[] result = new double[3];
        double x = vector[0], y = vector[1], z = vector[2];
        result[0] = (1 - 2 * (q2 * q2 + q3 * q3)) * x + (2 * (q1 * q2 - q0 * q3)) * y + (2 * (q1 * q3 + q0 * q2)) * z;
        result[1] = (2 * (q1 * q2 + q0 * q3)) * x + (1 - 2 * (q1 * q1 + q3 * q3)) * y + (2 * (q2 * q3 - q0 * q1)) * z;
        result[2] = (2 * (q1 * q3 - q0 * q2)) * x + (2 * (q2 * q3 + q0 * q1)) * y + (1 - 2 * (q1 * q1 + q2 * q2)) * z;
        return result;
    }

    public Rotation compose(Rotation rotation) {
        double newQ0 = q0 * rotation.q0 - q1 * rotation.q1 - q2 * rotation.q2 - q3 * rotation.q3;
        double newQ1 = q0 * rotation.q1 + q1 * rotation.q0 + q2 * rotation.q3 - q3 * rotation.q2;
        double newQ2 = q0 * rotation.q2 - q1 * rotation.q3 + q2 * rotation.q0 + q3 * rotation.q1;
        double newQ3 = q0 * rotation.q3 + q1 * rotation.q2 - q2 * rotation.q1 + q3 * rotation.q0;
        return new Rotation(newQ0, newQ1, newQ2, newQ3);
    }

    public Rotation inverse() {
        return new Rotation(q0, -q1, -q2, -q3);
    }

    // Additional methods for angles, axes, and distance calculations can be added here
}

