    @Before
    public void setUp() {
        tester = new WicketTester();
        resourceAggregator = new ResourceAggregator();
    }

    @Test
    public void testDirectDependencies() {
        resourceAggregator.addResource("resource1.js");
        resourceAggregator.addResource("resource2.js");
        IHeaderResponse response = tester.getHeaderResponse();
        resourceAggregator.renderResources(response);

        assertTrue(response.getHeaderItems().contains(new HeaderItem("resource1.js")));
        assertTrue(response.getHeaderItems().contains(new HeaderItem("resource2.js")));
    }

    @Test
    public void testTransitiveDependencies() {
        resourceAggregator.addResource("resourceA.js", "resourceB.js");
        resourceAggregator.addResource("resourceB.js", "resourceC.js");
        IHeaderResponse response = tester.getHeaderResponse();
        resourceAggregator.renderResources(response);

        assertTrue(response.getHeaderItems().contains(new HeaderItem("resourceA.js")));
        assertTrue(response.getHeaderItems().contains(new HeaderItem("resourceB.js")));
        assertTrue(response.getHeaderItems().contains(new HeaderItem("resourceC.js")));
    }

    @Test
    public void testBundlingOfResources() {
        resourceAggregator.addResource("bundle1.js", "resource1.js", "resource2.js");
        IHeaderResponse response = tester.getHeaderResponse();
        resourceAggregator.renderResources(response);

        assertTrue(response.getHeaderItems().contains(new HeaderItem("bundle1.js")));
    }

    @Test(expected = CircularDependencyException.class)
    public void testCircularDependencies() {
        resourceAggregator.addResource("resourceX.js", "resourceY.js");
        resourceAggregator.addResource("resourceY.js", "resourceX.js");
        resourceAggregator.renderResources(tester.getHeaderResponse());
    }

    @Test
    public void testPriorityRendering() {
        resourceAggregator.addResource("highPriority.js", 1);
        resourceAggregator.addResource("lowPriority.js", 2);
        IHeaderResponse response = tester.getHeaderResponse();
        resourceAggregator.renderResources(response);

        assertEquals("highPriority.js should be rendered first", 
                     response.getHeaderItems().get(0), new HeaderItem("highPriority.js"));
        assertEquals("lowPriority.js should be rendered second", 
                     response.getHeaderItems().get(1), new HeaderItem("lowPriority.js"));
    }

    @Test(expected = DuplicateResourceException.class)
    public void testDuplicateResourceDefinitions() {
        resourceAggregator.addResource("duplicate.js");
        resourceAggregator.addResource("duplicate.js");
        resourceAggregator.renderResources(tester.getHeaderResponse());
    }
}

public class Ordering implements Comparator<Object>, Serializable, XMLSerializable {
    private String sortSpecification;
    private boolean ascending;
    private boolean caseSensitive;
    private boolean nullsFirst;

    public Ordering(String sortSpecification, boolean ascending, boolean caseSensitive, boolean nullsFirst) {
        this.sortSpecification = sortSpecification;
        this.ascending = ascending;
        this.caseSensitive = caseSensitive;
        this.nullsFirst = nullsFirst;
    }

    @Override
    public int compare(Object o1, Object o2) {
        if (o1 == null && o2 == null) return 0;
        if (o1 == null) return nullsFirst ? -1 : 1;
        if (o2 == null) return nullsFirst ? 1 : -1;

        String str1 = o1.toString();
        String str2 = o2.toString();

        int comparison = caseSensitive ? str1.compareTo(str2) : str1.compareToIgnoreCase(str2);
        return ascending ? comparison : -comparison;
    }

    public List<Object> orderList(List<Object> list) {
        list.sort(this);
        return list;
    }

    public Collection<Object> createOrderedCollection(Collection<Object> collection) {
        List<Object> list = new ArrayList<>(collection);
        return orderList(list);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Ordering)) return false;
        Ordering other = (Ordering) obj;
        return ascending == other.ascending &&
               caseSensitive == other.caseSensitive &&
               nullsFirst == other.nullsFirst &&
               Objects.equals(sortSpecification, other.sortSpecification);
    }

    @Override
    public int hashCode() {
        return Objects.hash(sortSpecification, ascending, caseSensitive, nullsFirst);
    }

    @Override
    public String toXML() {
        // Implementation for XML serialization
        return "<Ordering sortSpecification=\"" + sortSpecification + "\" ascending=\"" + ascending + 
               "\" caseSensitive=\"" + caseSensitive + "\" nullsFirst=\"" + nullsFirst + "\" />";
    }
}

