public class CorsFilter implements Filter {
    private List<String> allowedOrigins;
    private List<String> allowedMethods;
    private List<String> allowedHeaders;
    private boolean allowCredentials;

    @Override
    public void init(FilterConfig filterConfig) throws ServletException {
        // Initialize allowed origins, methods, headers, and credentials support
        allowedOrigins = Arrays.asList("http://example.com", "http://anotherdomain.com");
        allowedMethods = Arrays.asList("GET", "POST", "OPTIONS");
        allowedHeaders = Arrays.asList("Content-Type", "Authorization");
        allowCredentials = true;
    }

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {
        HttpServletRequest httpRequest = (HttpServletRequest) request;
        HttpServletResponse httpResponse = (HttpServletResponse) response;

        String origin = httpRequest.getHeader("Origin");
        if (isOriginAllowed(origin)) {
            httpResponse.setHeader("Access-Control-Allow-Origin", origin);
            httpResponse.setHeader("Access-Control-Allow-Methods", String.join(", ", allowedMethods));
            httpResponse.setHeader("Access-Control-Allow-Headers", String.join(", ", allowedHeaders));
            if (allowCredentials) {
                httpResponse.setHeader("Access-Control-Allow-Credentials", "true");
            }
        } else {
            logInvalidCorsRequest(origin);
        }

        if ("OPTIONS".equalsIgnoreCase(httpRequest.getMethod())) {
            httpResponse.setStatus(HttpServletResponse.SC_OK);
            return;
        }

        chain.doFilter(request, response);
    }

    private boolean isOriginAllowed(String origin) {
        return allowedOrigins.contains(origin);
    }

    private void logInvalidCorsRequest(String origin) {
        System.out.println("Invalid CORS request from origin: " + origin);
    }

    @Override
    public void destroy() {
        // Cleanup resources if necessary
    }
}

