            logger.info("Loaded properties from {}", resourcePath);
        } catch (IOException e) {
            logger.error("Failed to load properties from {}", resourcePath, e);
        }
    }

    @Override
    public void run() {
        while (true) {
            try {
                Thread.sleep(reloadInterval);
                File file = new File(resourcePath);
                if (file.lastModified() > lastModified) {
                    loadProperties();
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                logger.warn("Reload thread interrupted", e);
                break;
            }
        }
    }

    @Override
    public void destroy() {
        super.destroy();
        logger.info("PropertiesRealm destroyed");
    }
}

