public class TitleBuffer {
    private StringBuilder titleBuilder;

    public TitleBuffer() {
        titleBuilder = new StringBuilder();
    }

    public TitleBuffer append(Object obj) {
        if (obj == null) {
            return this;
        }
        if (obj instanceof String) {
            String str = (String) obj;
            if (!str.isEmpty()) {
                titleBuilder.append(str);
            }
        } else {
            try {
                String title = (String) obj.getClass().getMethod("title").invoke(obj);
                if (title != null && !title.isEmpty()) {
                    titleBuilder.append(title);
                }
            } catch (Exception e) {
                // Ignoring exceptions for non-title objects
            }
        }
        return this;
    }

    public TitleBuffer append(String str) {
        if (str != null && !str.isEmpty()) {
            titleBuilder.append(str);
        }
        return this;
    }

    public TitleBuffer appendWithDefault(Object obj, String defaultValue) {
        if (obj == null) {
            titleBuilder.append(defaultValue);
        } else {
            append(obj);
        }
        return this;
    }

    public TitleBuffer truncate(int wordCount) {
        String[] words = titleBuilder.toString().split("\\s+");
        if (words.length > wordCount) {
            titleBuilder = new StringBuilder(String.join(" ", java.util.Arrays.copyOf(words, wordCount)));
        }
        return this;
    }

    @Override
    public String toString() {
        return titleBuilder.toString();
    }
}

