public class JavaCharStream {
    private char[] buffer;
    private int bufferSize;
    private int bufferPosition;
    private int line;
    private int column;
    private Reader reader;

    public JavaCharStream(Reader reader, int bufferSize) {
        this.reader = reader;
        this.bufferSize = bufferSize;
        this.buffer = new char[bufferSize];
        this.bufferPosition = 0;
        this.line = 1;
        this.column = 0;
        fillBuffer();
    }

    private void fillBuffer() {
        try {
            int charsRead = reader.read(buffer);
            if (charsRead == -1) {
                buffer[0] = '\0'; // End of stream
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public char readChar() {
        if (bufferPosition >= buffer.length) {
            fillBuffer();
            bufferPosition = 0;
        }
        char ch = buffer[bufferPosition++];
        if (ch == '\n') {
            line++;
            column = 0;
        } else {
            column++;
        }
        return ch;
    }

    public int getLine() {
        return line;
    }

    public int getColumn() {
        return column;
    }

    public void backup(int amount) {
        bufferPosition -= amount;
        if (bufferPosition < 0) {
            bufferPosition = 0;
        }
    }

    public String getImage() {
        return new String(buffer, 0, bufferPosition);
    }

    public void reinitialize(Reader newReader) {
        this.reader = newReader;
        this.bufferPosition = 0;
        this.line = 1;
        this.column = 0;
        fillBuffer();
    }

    // Code smell: No handling for escape sequences or Unicode in readChar
    // Code smell: No proper resource management (closing the reader)
}

