public class StoreQueueCursor extends AbstractPendingMessageCursor {
    private PersistentMessageCursor persistentCursor;
    private NonPersistentMessageCursor nonPersistentCursor;
    private int pendingMessageCount;
    private int batchSize;
    private boolean auditingEnabled;
    private boolean cachingEnabled;
    private boolean memoryManagementEnabled;
    private boolean prioritizeMessages;

    public StoreQueueCursor(int batchSize, boolean auditingEnabled, boolean cachingEnabled, boolean memoryManagementEnabled, boolean prioritizeMessages) {
        this.batchSize = batchSize;
        this.auditingEnabled = auditingEnabled;
        this.cachingEnabled = cachingEnabled;
        this.memoryManagementEnabled = memoryManagementEnabled;
        this.prioritizeMessages = prioritizeMessages;
        this.persistentCursor = new PersistentMessageCursor();
        this.nonPersistentCursor = new NonPersistentMessageCursor();
        this.pendingMessageCount = 0;
    }

    public void start() {
        persistentCursor.start();
        nonPersistentCursor.start();
    }

    public void stop() {
        persistentCursor.stop();
        nonPersistentCursor.stop();
    }

    public void addMessage(Message message, boolean persistent) {
        if (persistent) {
            persistentCursor.addMessage(message);
        } else {
            nonPersistentCursor.addMessage(message);
        }
        pendingMessageCount++;
    }

    public void clear() {
        persistentCursor.clear();
        nonPersistentCursor.clear();
        pendingMessageCount = 0;
    }

    public Iterator<Message> iterator() {
        return new MessageIterator();
    }

    public void removeMessage(Message message) {
        if (persistentCursor.contains(message)) {
            persistentCursor.removeMessage(message);
        } else {
            nonPersistentCursor.removeMessage(message);
        }
        pendingMessageCount--;
    }

    public void reset() {
        persistentCursor.reset();
        nonPersistentCursor.reset();
    }

    public void garbageCollect() {
        if (memoryManagementEnabled) {
            persistentCursor.garbageCollect();
            nonPersistentCursor.garbageCollect();
        }
    }

    private class MessageIterator implements Iterator<Message> {
        private Iterator<Message> currentIterator;

        public MessageIterator() {
            currentIterator = prioritizeMessages ? persistentCursor.iterator() : nonPersistentCursor.iterator();
        }

        public boolean hasNext() {
            return currentIterator.hasNext();
        }

        public Message next() {
            return currentIterator.next();
        }
    }
}

