public class ArrayTree<K> {
    private K[] elements;
    private int size;
    private Comparator<? super K> comparator;

    @SuppressWarnings("unchecked")
    public ArrayTree(Comparator<? super K> comparator) {
        this.elements = (K[]) new Object[10];
        this.size = 0;
        this.comparator = comparator;
    }

    public void insert(K key) {
        if (contains(key)) return;
        ensureCapacity();
        int index = findInsertIndex(key);
        System.arraycopy(elements, index, elements, index + 1, size - index);
        elements[index] = key;
        size++;
    }

    public void remove(K key) {
        int index = findIndex(key);
        if (index == -1) return;
        System.arraycopy(elements, index + 1, elements, index, size - index - 1);
        elements[--size] = null;
        if (size < elements.length / 4) resize(elements.length / 2);
    }

    public boolean contains(K key) {
        return findIndex(key) != -1;
    }

    public K get(int index) {
        if (index < 0 || index >= size) throw new IndexOutOfBoundsException();
        return elements[index];
    }

    public K getFirst() {
        if (isEmpty()) throw new IllegalStateException("Collection is empty");
        return elements[0];
    }

    public K getLast() {
        if (isEmpty()) throw new IllegalStateException("Collection is empty");
        return elements[size - 1];
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int getSize() {
        return size;
    }

    public List<K> getAllKeys() {
        return Arrays.asList(Arrays.copyOf(elements, size));
    }

    public void print() {
        for (int i = 0; i < size; i++) {
            System.out.print(elements[i] + " ");
        }
        System.out.println();
    }

    private void ensureCapacity() {
        if (size == elements.length) {
            resize(elements.length * 2);
        }
    }

    @SuppressWarnings("unchecked")
    private void resize(int newCapacity) {
        K[] newArray = (K[]) new Object[newCapacity];
        System.arraycopy(elements, 0, newArray, 0, size);
        elements = newArray;
    }

    private int findInsertIndex(K key) {
        int low = 0, high = size - 1;
        while (low <= high) {
            int mid = (low + high) / 2;
            int cmp = comparator.compare(key, elements[mid]);
            if (cmp < 0) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    private int findIndex(K key) {
        int low = 0, high = size - 1;
        while (low <= high) {
            int mid = (low + high) / 2;
            int cmp = comparator.compare(key, elements[mid]);
            if (cmp == 0) {
                return mid;
            } else if (cmp < 0) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return -1;
