public class SubtreeSpecificationDialog extends JDialog {
    private JTextField baseEntryField;
    private JTextField minDistanceField;
    private JTextField maxDistanceField;
    private JTable exclusionTable;
    private JButton okButton;
    private List<String> exclusions;

    public SubtreeSpecificationDialog(Frame owner) {
        super(owner, "Subtree Specification", true);
        exclusions = new ArrayList<>();
        initializeUI();
    }

    private void initializeUI() {
        setLayout(new GridLayout(0, 2));

        add(new JLabel("Base Entry:"));
        baseEntryField = new JTextField();
        add(baseEntryField);

        add(new JLabel("Minimum Distance:"));
        minDistanceField = new JTextField();
        add(minDistanceField);

        add(new JLabel("Maximum Distance:"));
        maxDistanceField = new JTextField();
        add(maxDistanceField);

        add(new JLabel("Exclusions:"));
        exclusionTable = new JTable(); // Placeholder for actual table model
        add(new JScrollPane(exclusionTable));

        JButton addExclusionButton = new JButton("Add Exclusion");
        addExclusionButton.addActionListener(new ActionListener() {
            public void actionPerformed(ActionEvent e) {
                addExclusion();
            }
        });
        add(addExclusionButton);

        okButton = new JButton("OK");
        okButton.setEnabled(false);
        okButton.addActionListener(new ActionListener() {
            public void actionPerformed(ActionEvent e) {
                if (validateInput()) {
                    dispose();
                }
            }
        });
        add(okButton);

        baseEntryField.addCaretListener(e -> validateInput());
        minDistanceField.addCaretListener(e -> validateInput());
        maxDistanceField.addCaretListener(e -> validateInput());

        pack();
        setLocationRelativeTo(owner);
    }

    private void addExclusion() {
        String exclusion = JOptionPane.showInputDialog(this, "Enter exclusion:");
        if (exclusion != null && !exclusion.trim().isEmpty()) {
            exclusions.add(exclusion);
            // Update exclusionTable here
        }
    }

    private boolean validateInput() {
        boolean isValid = !baseEntryField.getText().trim().isEmpty() &&
                          isNumeric(minDistanceField.getText()) &&
                          isNumeric(maxDistanceField.getText()) &&
                          Integer.parseInt(minDistanceField.getText()) <= Integer.parseInt(maxDistanceField.getText());
        okButton.setEnabled(isValid);
        return isValid;
    }

    private boolean isNumeric(String str) {
        try {
            Integer.parseInt(str);
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    public String getSubtreeSpecification() {
        return String.format("Base Entry: %s, Min Distance: %s, Max Distance: %s, Exclusions: %s",
                baseEntryField.getText(),
                minDistanceField.getText(),
                maxDistanceField.getText(),
                exclusions.toString());
    }
}

class CircleStreamBufferTest {

    private CircleStreamBuffer circleStreamBuffer;

    @BeforeEach
    void setUp() {
        circleStreamBuffer = new CircleStreamBuffer(10); // Buffer size of 10 bytes
    }

    @Test
    void testWriteAndRead() throws IOException {
        String data = "Hello";
        InputStream inputStream = new ByteArrayInputStream(data.getBytes(StandardCharsets.UTF_8));
        OutputStream outputStream = circleStreamBuffer.getOutputStream();

        byte[] buffer = new byte[5];
        int bytesRead = inputStream.read(buffer);
        outputStream.write(buffer, 0, bytesRead);
        outputStream.flush();

        byte[] readBuffer = new byte[5];
        int bytesReadFromBuffer = circleStreamBuffer.getInputStream().read(readBuffer);
        assertEquals(data, new String(readBuffer, 0, bytesReadFromBuffer, StandardCharsets.UTF_8));
    }

    @Test
    void testWriteLargerThanBuffer() throws IOException {
        String data = "HelloWorld!";
        InputStream inputStream = new ByteArrayInputStream(data.getBytes(StandardCharsets.UTF_8));
        OutputStream outputStream = circleStreamBuffer.getOutputStream();

        byte[] buffer = new byte[12];
        int bytesRead = inputStream.read(buffer);
        outputStream.write(buffer, 0, bytesRead);
        outputStream.flush();

        byte[] readBuffer = new byte[10];
        int bytesReadFromBuffer = circleStreamBuffer.getInputStream().read(readBuffer);
        assertEquals("World!", new String(readBuffer, 0, bytesReadFromBuffer, StandardCharsets.UTF_8));
    }

    @Test
    void testReadEmptyBuffer() throws IOException {
        InputStream inputStream = circleStreamBuffer.getInputStream();
        byte[] readBuffer = new byte[5];
        int bytesRead = inputStream.read(readBuffer);
        assertEquals(-1, bytesRead);
    }

    @Test
    void testCloseInputStream() throws IOException {
        OutputStream outputStream = circleStreamBuffer.getOutputStream();
        InputStream inputStream = circleStreamBuffer.getInputStream();

        inputStream.close();
        assertThrows(IOException.class, inputStream::read);
    }

    @Test
    void testCloseOutputStream() throws IOException {
        OutputStream outputStream = circleStreamBuffer.getOutputStream();
        outputStream.close();
        assertThrows(IOException.class, () -> outputStream.write(new byte[1]));
    }

    @Test
    void testCharacterEncoding() throws IOException {
        String data = "こんにちは"; // "Hello" in Japanese
        InputStream inputStream = new ByteArrayInputStream(data.getBytes(StandardCharsets.UTF_8));
        OutputStream outputStream = circleStreamBuffer.getOutputStream();

        byte[] buffer = new byte[15];
        int bytesRead = inputStream.read(buffer);
        outputStream.write(buffer, 0, bytesRead);
        outputStream.flush();

        byte[] readBuffer = new byte[15];
        int bytesReadFromBuffer = circleStreamBuffer.getInputStream().read(readBuffer);
        assertEquals(data, new String(readBuffer, 0, bytesReadFromBuffer, StandardCharsets.UTF_8));
    }
}

