public class UtilHttp {

    public static Map<String, Object> combineMaps(Map<String, Object> params, Map<String, Object> attrs, Map<String, Object> sessionData, Map<String, Object> context) {
        Map<String, Object> combined = new HashMap<>();
        combined.putAll(params);
        combined.putAll(attrs);
        combined.putAll(sessionData);
        combined.putAll(context);
        return combined;
    }

    public static Map<String, String[]> extractRequestParameters(HttpServletRequest request) {
        Map<String, String[]> parameters = new HashMap<>(request.getParameterMap());
        // Code smell: Potentially not handling multi-row form data properly
        return parameters;
    }

    public static String canonicalizeParameterValue(String value) {
        // Code smell: Not handling null or empty values
        return value.trim().replaceAll("[<>]", "");
    }

    public static void manageSessionAttributes(HttpSession session, String locale, String timeZone, String currency) {
        session.setAttribute("locale", locale);
        session.setAttribute("timeZone", timeZone);
        session.setAttribute("currency", currency);
    }

    public static String generateUrl(String baseUrl, Map<String, String> queryParams) {
        StringBuilder url = new StringBuilder(baseUrl);
        if (!queryParams.isEmpty()) {
            url.append("?");
            queryParams.forEach((key, value) -> url.append(key).append("=").append(value).append("&"));
            url.deleteCharAt(url.length() - 1); // Remove last '&'
        }
        return url.toString();
    }

    public static void streamContent(HttpServletResponse response, String contentType, String content) throws IOException {
        response.setContentType(contentType);
        response.getWriter().write(content);
    }

    public static void setNoCacheHeaders(HttpServletResponse response) {
        response.setHeader("Cache-Control", "no-cache, no-store, must-revalidate");
        response.setHeader("Pragma", "no-cache");
        response.setDateHeader("Expires", 0);
    }

    public static boolean isSpiderUserAgent(String userAgent) {
        // Code smell: Hardcoded user agent checks
        return userAgent.contains("bot") || userAgent.contains("spider");
    }

    public static boolean isJavaScriptEnabled(HttpServletRequest request) {
        return request.getParameter("jsEnabled") != null;
    }

    public static void storeParameterMapInSession(HttpSession session, Map<String, String[]> paramMap) {
        session.setAttribute("paramMap", paramMap);
    }

    public static Map<String, String[]> restoreParameterMapFromSession(HttpSession session) {
        return (Map<String, String[]>) session.getAttribute("paramMap");
    }

    public static String generateUniqueId() {
        return UUID.randomUUID().toString();
    }
}

