class AbstractQueryBuilder {
    protected Map<String, String> variableNodeMap;
    protected Set<String> prefixes;
    protected StringBuilder queryBuilder;

    public AbstractQueryBuilder() {
        this.variableNodeMap = new HashMap<>();
        this.prefixes = new HashSet<>();
        this.queryBuilder = new StringBuilder();
    }

    public abstract void addPrefix(String prefix, String uri);

    public abstract void addWhereClause(String clause);

    public abstract void addVariable(String variable, String node);

    public abstract String buildQuery();

    protected String createNode(String value) {
        return "<" + value + ">";
    }

    protected String createLiteral(String value) {
        return "\"" + value + "\"";
    }

    protected String createVariable(String variable) {
        return "?" + variable;
    }

    public void assignVariable(String variable, String node) {
        variableNodeMap.put(variable, node);
