        return variableNodeMap.get(variable);
    }

    public void clear() {
        variableNodeMap.clear();
        queryBuilder.setLength(0);
    }

    public abstract AbstractQueryBuilder clone();

    public abstract void rewriteQuery();
}

public class JavaCharStream {
    private char[] buffer;
    private int bufferSize;
    private int currentPos;
    private int line;
    private int column;
    private Reader reader;
    private boolean eof;

    public JavaCharStream(InputStream inputStream, String encoding) throws UnsupportedEncodingException {
        this.reader = new InputStreamReader(inputStream, encoding);
        this.bufferSize = 1024;
        this.buffer = new char[bufferSize];
        this.currentPos = 0;
        this.line = 1;
        this.column = 0;
        this.eof = false;
        fillBuffer();
    }

    public JavaCharStream(Reader reader) {
        this.reader = reader;
        this.bufferSize = 1024;
        this.buffer = new char[bufferSize];
        this.currentPos = 0;
        this.line = 1;
        this.column = 0;
        this.eof = false;
        fillBuffer();
    }

    private void fillBuffer() {
        try {
            int read = reader.read(buffer);
            if (read == -1) {
                eof = true;
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public char readChar() {
        if (currentPos >= buffer.length && !eof) {
            expandBuffer();
        }
        if (eof && currentPos >= buffer.length) {
            return '\0'; // End of file
        }
        char ch = buffer[currentPos++];
        updatePosition(ch);
        return ch;
    }

    private void expandBuffer() {
        char[] newBuffer = new char[bufferSize * 2];
        System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
        buffer = newBuffer;
        bufferSize *= 2;
        fillBuffer();
    }

    private void updatePosition(char ch) {
        if (ch == '\n') {
            line++;
            column = 0;
        } else {
            column++;
        }
    }

    public int getLine() {
        return line;
    }

    public int getColumn() {
        return column;
    }

    public void reinitialize(InputStream inputStream, String encoding) throws UnsupportedEncodingException {
        this.reader = new InputStreamReader(inputStream, encoding);
        this.currentPos = 0;
        this.line = 1;
        this.column = 0;
        this.eof = false;
        fillBuffer();
    }

    public void reinitialize(Reader reader) {
        this.reader = reader;
        this.currentPos = 0;
        this.line = 1;
        this.column = 0;
        this.eof = false;
        fillBuffer();
    }
}

public class SearchAction {

    private RepositorySearchService searchService;
    private List<ManagedRepository> managedRepositories;
    private String groupId;
    private String artifactId;
    private String version;
    private String className;
    private String osgiBundleProperties;
    private List<SearchResult> searchResults;
    private int currentPage;
    private int totalPages;

    public SearchAction(RepositorySearchService searchService) {
        this.searchService = searchService;
        this.currentPage = 1;
    }

    public void prepareSearchEnvironment() {
        // Initialize search fields and managed repositories
        this.managedRepositories = fetchManagedRepositories();
        clearSearchFields();
    }

    public void clearSearchFields() {
        this.groupId = null;
        this.artifactId = null;
        this.version = null;
        this.className = null;
        this.osgiBundleProperties = null;
        this.searchResults = null;
        this.currentPage = 1;
    }

    public void performSearch() {
        try {
            searchResults = searchService.search(groupId, artifactId, version, className, osgiBundleProperties, currentPage);
            totalPages = calculateTotalPages(searchResults.size());
        } catch (SearchException e) {
            handleError(e);
        }
    }

    private int calculateTotalPages(int resultCount) {
        // Assuming a fixed page size of 10
        return (int) Math.ceil(resultCount / 10.0);
    }

    private void handleError(SearchException e) {
        // Log the error and notify the user
        System.err.println("Search error: " + e.getMessage());
    }

    private List<ManagedRepository> fetchManagedRepositories() {
        // Fetch the list of managed repositories from the service
        return searchService.getManagedRepositories();
    }

    // Getters and setters for search fields and results

    public List<SearchResult> getSearchResults() {
