public class Identifier implements Comparable<Identifier> {
    private final String className;
    private final String memberName;
    private final String[] parameterNames;
    private final Type type;
    private final Depth depth;

    public enum Type {
        CLASS, PROPERTY, COLLECTION, ACTION
    }

    public enum Depth {
        SHALLOW, MEDIUM, DEEP
    }

    private Identifier(String className, String memberName, String[] parameterNames, Type type, Depth depth) {
        this.className = className;
        this.memberName = memberName;
        this.parameterNames = parameterNames;
        this.type = type;
        this.depth = depth;
    }

    public static Identifier createClassIdentifier(String className) {
        return new Identifier(className, null, null, Type.CLASS, Depth.SHALLOW);
    }

    public static Identifier createPropertyIdentifier(String className, String propertyName) {
        return new Identifier(className, propertyName, null, Type.PROPERTY, Depth.SHALLOW);
    }

    public static Identifier createCollectionIdentifier(String className, String collectionName) {
        return new Identifier(className, collectionName, null, Type.COLLECTION, Depth.SHALLOW);
    }

    public static Identifier createActionIdentifier(String className, String actionName, String[] parameterNames) {
        return new Identifier(className, actionName, parameterNames, Type.ACTION, Depth.SHALLOW);
    }

    public String getClassName() {
        return className;
    }

    public String getMemberName() {
        return memberName;
    }

    public String[] getParameterNames() {
        return parameterNames;
    }

    public String toIdentityString() {
        StringBuilder sb = new StringBuilder();
        sb.append(className);
        if (memberName != null) {
            sb.append(".").append(memberName);
        }
        if (parameterNames != null && parameterNames.length > 0) {
            sb.append("(");
            for (int i = 0; i < parameterNames.length; i++) {
                sb.append(parameterNames[i]);
                if (i < parameterNames.length - 1) {
                    sb.append(", ");
                }
            }
            sb.append(")");
        }
        return sb.toString();
    }

    @Override
    public int compareTo(Identifier other) {
        return this.toIdentityString().compareTo(other.toIdentityString());
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Identifier)) return false;
        Identifier that = (Identifier) o;
        return Objects.equals(className, that.className) &&
               Objects.equals(memberName, that.memberName) &&
               Objects.equals(parameterNames, that.parameterNames);
    }

    @Override
    public int hashCode() {
        return Objects.hash(className, memberName, parameterNames);
    }

