public class LVByteBufferColumnPage extends ColumnPage {
    private ByteBuffer buffer;
    private int numberOfRows;
    private int totalLength;

    public LVByteBufferColumnPage(int initialCapacity) {
        this.buffer = ByteBuffer.allocate(initialCapacity);
        this.numberOfRows = 0;
        this.totalLength = 0;
    }

    public void addBytes(byte[] data) {
        ensureCapacity(data.length);
        buffer.put(data);
        numberOfRows++;
        totalLength += data.length;
    }

    private void ensureCapacity(int additionalLength) {
        if (buffer.remaining() < additionalLength) {
            ByteBuffer newBuffer = ByteBuffer.allocate(buffer.capacity() + additionalLength);
            buffer.flip();
            newBuffer.put(buffer);
            buffer = newBuffer;
        }
    }

