public class Base64 {
    private static final String BASE64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    private static final String URL_SAFE_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    private static final int DEFAULT_LINE_LENGTH = 76;
    private static final String DEFAULT_SEPARATOR = "\n";

    private StringBuilder buffer = new StringBuilder();

    public String encode(byte[] data) {
        return encode(data, false, DEFAULT_LINE_LENGTH, DEFAULT_SEPARATOR);
    }

    public String encode(byte[] data, boolean urlSafe, int lineLength, String separator) {
        Base64.Encoder encoder = urlSafe ? Base64.getUrlEncoder() : Base64.getEncoder();
        String encoded = encoder.encodeToString(data);
        return chunkedOutput(encoded, lineLength, separator);
    }

    public byte[] decode(String base64) {
        return Base64.getDecoder().decode(base64);
    }

    public String encode(String data) {
        return encode(data.getBytes());
    }

    public String encode(String data, boolean urlSafe, int lineLength, String separator) {
        return encode(data.getBytes(), urlSafe, lineLength, separator);
    }

    public static boolean isValidBase64(String base64) {
        return base64.matches("^[A-Za-z0-9+/]*={0,2}$");
    }

    public static boolean isBase64Character(char c) {
        return BASE64_CHARS.indexOf(c) != -1 || c == '=' || c == '-';
    }

    private String chunkedOutput(String encoded, int lineLength, String separator) {
        StringBuilder chunked = new StringBuilder();
        for (int i = 0; i < encoded.length(); i += lineLength) {
            int end = Math.min(i + lineLength, encoded.length());
            chunked.append(encoded, i, end).append(separator);
        }
        return chunked.toString().trim();
    }

    public static int encodeInt(int value) {
        return Base64.getEncoder().encodeToString(new byte[]{(byte) value}).charAt(0);
    }

    public static byte[] toByteArray(String base64) {
        return Base64.getDecoder().decode(base64);
    }
}

