@TriggerSerially
@Processor
@Capability("Enforce Order")
public class EnforceOrder extends AbstractProcessor {

    public static final PropertyDescriptor GROUP_IDENTIFIER = new PropertyDescriptor.Builder()
            .name("Group Identifier")
            .description("Identifier for the group of FlowFiles to be ordered.")
            .required(true)
            .addValidator(StandardValidators.NON_EMPTY_VALIDATOR)
            .build();

    public static final PropertyDescriptor ORDER_ATTRIBUTE = new PropertyDescriptor.Builder()
            .name("Order Attribute")
            .description("Attribute used to determine the order of FlowFiles.")
            .required(true)
            .addValidator(StandardValidators.NON_EMPTY_VALIDATOR)
            .build();

    public static final PropertyDescriptor INITIAL_ORDER_VALUE = new PropertyDescriptor.Builder()
            .name("Initial Order Value")
            .description("Initial order value for the FlowFiles.")
            .required(true)
            .addValidator(StandardValidators.INTEGER_VALIDATOR)
            .build();

    public static final PropertyDescriptor MAX_ORDER_VALUE = new PropertyDescriptor.Builder()
            .name("Maximum Order Value")
            .description("Maximum order value for the FlowFiles.")
            .required(true)
            .addValidator(StandardValidators.INTEGER_VALIDATOR)
            .build();

    public static final PropertyDescriptor WAIT_TIMEOUT = new PropertyDescriptor.Builder()
            .name("Wait Timeout")
            .description("Time to wait for the next FlowFile before routing to waiting.")
            .required(true)
            .addValidator(StandardValidators.TIME_PERIOD_VALIDATOR)
            .build();

    public static final PropertyDescriptor INACTIVE_TIMEOUT = new PropertyDescriptor.Builder()
            .name("Inactive Timeout")
            .description("Time to consider a group inactive before cleanup.")
            .required(true)
            .addValidator(StandardValidators.TIME_PERIOD_VALIDATOR)
            .build();

    public static final PropertyDescriptor BATCH_LIMIT = new PropertyDescriptor.Builder()
            .name("Batch Limit")
            .description("Maximum number of FlowFiles to process in a batch.")
            .required(true)
            .addValidator(StandardValidators.INTEGER_VALIDATOR)
            .build();

    public static final Relationship SUCCESS_RELATIONSHIP = new Relationship.Builder()
            .name("success")
            .description("FlowFiles that are processed successfully.")
            .build();

    public static final Relationship FAILURE_RELATIONSHIP = new Relationship.Builder()
            .name("failure")
            .description("FlowFiles that failed processing.")
            .build();

    public static final Relationship WAITING_RELATIONSHIP = new Relationship.Builder()
            .name("waiting")
            .description("FlowFiles that are waiting for their turn.")
            .build();

    public static final Relationship OVERTOOK_RELATIONSHIP = new Relationship.Builder()
            .name("overtook")
            .description("FlowFiles that overtook others in order.")
            .build();

    public static final Relationship SKIPPED_RELATIONSHIP = new Relationship.Builder()
            .name("skipped")
            .description("FlowFiles that were skipped due to order.")
            .build();

    private final Map<String, Queue<FlowFile>> flowFileGroups = new ConcurrentHashMap<>();
    private final Map<String, Integer> expectedOrder = new ConcurrentHashMap<>();
    private final Map<String, Long> lastActiveTime = new ConcurrentHashMap<>();
    private ProcessorLog logger;

    @Override
    protected void init(ProcessorInitializationContext context) {
        logger = context.getLogger();
    }

    @OnScheduled
    public void onScheduled(ProcessorContext context) {
        // Initialization logic if needed
    }

    @OnStopped
    public void onStopped() {
        // Cleanup logic if needed
    }

    @Override
    public void onTrigger(ProcessorContext context, ProcessSession session) throws ProcessException {
        // Main processing logic
        List<FlowFile> flowFiles = session.get(10); // Fetch up to 10 FlowFiles
        if (flowFiles.isEmpty()) {
            return;
        }

        for (FlowFile flowFile : flowFiles) {
            String groupId = flowFile.getAttribute(GROUP_IDENTIFIER.getName());
            int orderValue = Integer.parseInt(flowFile.getAttribute(ORDER_ATTRIBUTE.getName()));

            flowFileGroups.putIfAbsent(groupId, new LinkedList<>());
            Queue<FlowFile> queue = flowFileGroups.get(groupId);

            if (expectedOrder.getOrDefault(groupId, INITIAL_ORDER_VALUE.getDefaultValue()) == orderValue) {
                queue.offer(flowFile);
                expectedOrder.put(groupId, orderValue + 1);
                session.transfer(flowFile, SUCCESS_RELATIONSHIP);
            } else if (orderValue < expectedOrder.get(groupId)) {
                session.transfer(flowFile, SKIPPED_RELATIONSHIP);
            } else {
                session.transfer(flowFile, WAITING_RELATIONSHIP);
            }

            lastActiveTime.put(groupId, System.currentTimeMillis());
        }

        cleanupInactiveGroups();
    }

    private void cleanupInactiveGroups() {
        long currentTime = System.currentTimeMillis();
        long inactiveTimeoutMillis = Long.parseLong(INACTIVE_TIMEOUT.getDefaultValue());

        lastActiveTime.entrySet().removeIf(entry -> currentTime - entry.getValue() > inactiveTimeoutMillis);
    }

    @Override
    public Set<Relationship> getRelationships() {
        return Set.of(SUCCESS_RELATIONSHIP, FAILURE_RELATIONSHIP, WAITING_RELATIONSHIP, OVERTOOK_RELATIONSHIP, SKIPPED_RELATIONSHIP);
    }

    @Override
    public List<PropertyDescriptor> getSupportedPropertyDescriptors() {
        return List.of(GROUP_IDENTIFIER, ORDER_ATTRIBUTE, INITIAL_ORDER_VALUE, MAX_ORDER_VALUE, WAIT_TIMEOUT, INACTIVE_TIMEOUT, BATCH_LIMIT);
    }
}

