    private StateMachine<RMAppAttemptState, RMAppAttemptEvent, RMAppAttemptEventType> createStateMachine() {
        StateMachineFactory<RMAppAttemptImpl, RMAppAttemptState, RMAppAttemptEvent, RMAppAttemptEventType> factory =
                new StateMachineFactory<>(RMAppAttemptState.NEW)
                        .addTransition(RMAppAttemptState.NEW, RMAppAttemptState.SUBMITTED, RMAppAttemptEventType.SUBMIT)
                        .addTransition(RMAppAttemptState.SUBMITTED, RMAppAttemptState.RUNNING, RMAppAttemptEventType.REGISTER)
                        .addTransition(RMAppAttemptState.RUNNING, RMAppAttemptState.FINISHED, RMAppAttemptEventType.FINISH)
                        .addTransition(RMAppAttemptState.RUNNING, RMAppAttemptState.FAILED, RMAppAttemptEventType.FAIL);
        return factory.make();
    }

    @Override
    public void handle(RMAppAttemptEvent event) {
        lock.writeLock().lock();
        try {
            stateMachine.doTransition(event.getType());
            // Handle specific event logic here
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void recover() {
        lock.readLock().lock();
        try {
            // Recovery logic here
        } finally {
            lock.readLock().unlock();
        }
    }

