public abstract class BaseDataStreamMarshaller<T> implements DataStreamMarshaller<T> {
    private Map<Long, T> cache = new HashMap<>();

    protected abstract Class<T> getType();

    protected abstract T createObject() throws IOException;

    @Override
    public void marshal(T obj, DataOutputStream out) throws IOException {
        try {
            if (obj == null) {
                out.writeBoolean(false);
                return;
            }
            out.writeBoolean(true);
            // Serialize fields
            marshalFields(obj, out);
        } catch (IOException e) {
            handleException(e);
        }
    }

    protected abstract void marshalFields(T obj, DataOutputStream out) throws IOException;

    @Override
    public T unmarshal(DataInputStream in) throws IOException {
        try {
            if (!in.readBoolean()) {
                return null;
            }
            long id = in.readLong();
            if (cache.containsKey(id)) {
                return cache.get(id);
            }
            T obj = createObject();
            unmarshalFields(obj, in);
            cache.put(id, obj);
            return obj;
        } catch (IOException e) {
            handleException(e);
            return null;
        }
    }

    protected abstract void unmarshalFields(T obj, DataInputStream in) throws IOException;

    protected void handleException(IOException e) {
        e.printStackTrace();
    }

    protected void writeLong(DataOutputStream out, long value) throws IOException {
        out.writeLong(value);
    }

    protected long readLong(DataInputStream in) throws IOException {
        return in.readLong();
    }

    protected void writeString(DataOutputStream out, String value) throws IOException {
        if (value == null) {
            out.writeBoolean(false);
        } else {
            out.writeBoolean(true);
            out.writeUTF(value);
        }
    }

    protected String readString(DataInputStream in) throws IOException {
        if (!in.readBoolean()) {
            return null;
        }
        return in.readUTF();
    }

    protected void writeByteArray(DataOutputStream out, byte[] array) throws IOException {
        if (array == null) {
            out.writeInt(-1);
        } else {
            out.writeInt(array.length);
            out.write(array);
        }
    }

    protected byte[] readByteArray(DataInputStream in) throws IOException {
        int length = in.readInt();
        if (length == -1) {
            return null;
        }
        byte[] array = new byte[length];
        in.readFully(array);
        return array;
    }
}

public class NettyServer {
    private final int port;
    private final String host;
    private final boolean enableCompression;
    private EventLoopGroup bossGroup;
    private EventLoopGroup workerGroup;
    private Channel serverChannel;
    private final List<Channel> acceptedChannels = new ArrayList<>();

    public NettyServer(String host, int port, boolean enableCompression) {
        this.host = host;
        this.port = port;
        this.enableCompression = enableCompression;
    }

    public void start() {
        bossGroup = new NioEventLoopGroup();
        workerGroup = new NioEventLoopGroup();
        try {
            ServerBootstrap bootstrap = new ServerBootstrap();
            bootstrap.group(bossGroup, workerGroup)
                    .channel(NioServerSocketChannel.class)
                    .option(ChannelOption.SO_BACKLOG, 128)
                    .handler(new LoggingHandler(LogLevel.INFO))
                    .childHandler(new ChannelInitializer<SocketChannel>() {
                        @Override
                        protected void initChannel(SocketChannel ch) {
                            ch.pipeline().addLast(new HttpServerCodec());
                            // Add additional handlers here
                        }
                    });

            ChannelFuture future = bootstrap.bind(new InetSocketAddress(host, port)).sync();
            serverChannel = future.channel();
            acceptedChannels.add(serverChannel);
            serverChannel.closeFuture().sync();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            // Handle exception
        } finally {
            shutdown();
        }
    }

    public void stop() {
        shutdown();
    }

    private void shutdown() {
        if (serverChannel != null) {
            acceptedChannels.forEach(Channel::close);
            acceptedChannels.clear();
        }
        if (workerGroup != null) {
            workerGroup.shutdownGracefully();
        }
        if (bossGroup != null) {
            bossGroup.shutdownGracefully();
        }
    }
}

