public class TestInterProcessSemaphore {
    private TestingServer server;
    private CuratorFramework client;
    private InterProcessSemaphore semaphore;

    @Before
    public void setUp() throws Exception {
        server = new TestingServer();
        client = CuratorFrameworkFactory.newClient(server.getConnectString(), new ExponentialBackoffRetry(1000, 3));
        client.start();
        semaphore = new InterProcessSemaphore(client, "/semaphore");
    }

    @After
    public void tearDown() throws Exception {
        client.close();
        server.close();
    }

    @Test
    public void testAcquireAfterLostServer() throws Exception {
        server.stop();
        assertFalse(semaphore.acquire());
        server.start();
        assertTrue(semaphore.acquire());
    }

    @Test
    public void testThreadedLeaseIncrease() throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(10);
        for (int i = 0; i < 10; i++) {
            executor.submit(() -> {
                semaphore.acquire();
            });
        }
        executor.shutdown();
        assertTrue(semaphore.getLeaseCount() > 10);
    }

    @Test
    public void testClientClose() throws Exception {
        semaphore.acquire();
        client.close();
        client = CuratorFrameworkFactory.newClient(server.getConnectString(), new ExponentialBackoffRetry(1000, 3));
        client.start();
        assertTrue(semaphore.acquire());
    }

    @Test
    public void testMaxPerSession() throws Exception {
        for (int i = 0; i < 5; i++) {
            assertTrue(semaphore.acquire());
        }
        assertFalse(semaphore.acquire());
    }

    @Test
    public void testRelease1AtATime() throws Exception {
        semaphore.acquire();
        semaphore.acquire();
        semaphore.release();
        assertEquals(1, semaphore.getLeaseCount());
    }

    @Test
    public void testReleaseInChunks() throws Exception {
        CountDownLatch latch = new CountDownLatch(5);
        ExecutorService executor = Executors.newFixedThreadPool(5);
        for (int i = 0; i < 5; i++) {
            executor.submit(() -> {
                semaphore.acquire();
                semaphore.release();
                latch.countDown();
            });
        }
        latch.await();
        assertEquals(0, semaphore.getLeaseCount());
    }

    @Test
    public void testThreads() throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(10);
        for (int i = 0; i < 10; i++) {
            executor.submit(() -> {
                semaphore.acquire();
                semaphore.release();
            });
        }
        executor.shutdown();
        assertEquals(0, semaphore.getLeaseCount());
    }

    @Test
    public void testSimple() throws Exception {
        assertTrue(semaphore.acquire());
        assertFalse(semaphore.acquire());
        semaphore.release();
        assertTrue(semaphore.acquire());
    }

    @Test
    public void testGetParticipantNodes() throws Exception {
        semaphore.acquire();
        assertEquals(1, semaphore.getParticipantNodes().size());
    }

    @Test
    public void testChildReaperCleansUpLockNodes() throws Exception {
        semaphore.acquire();
        // Simulate orphaned nodes
        semaphore.release();
        assertTrue(semaphore.getOrphanedNodes().isEmpty());
    }

    @Test
    public void testNoOrphanedNodes() throws Exception {
        semaphore.acquire();
        semaphore.release();
        assertTrue(semaphore.getOrphanedNodes().isEmpty());
    }

    @Test
    public void testInterruptAcquire() throws Exception {
        Thread thread = new Thread(() -> {
            try {
                semaphore.acquire();
            } catch (InterruptedException e) {
                // Handle interruption
            }
        });
        thread.start();
        thread.interrupt();
        thread.join();
        assertFalse(semaphore.isAcquired());
    }
}

