        broker = new BrokerService();
        broker.start();
        ActiveMQConnectionFactory factory = new ActiveMQConnectionFactory("tcp://localhost:61616");
        connection = factory.createConnection();
        connection.start();
        session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
    }

    public void tearDown() throws Exception {
        if (session != null) {
            session.close();
        }
        if (connection != null) {
            connection.close();
        }
        if (broker != null) {
            broker.stop();
        }
    }

    public MessageProducer createProducer(String destinationName) throws JMSException {
        Destination destination = session.createQueue(destinationName);
        return session.createProducer(destination);
    }

    public MessageConsumer createConsumer(String destinationName) throws JMSException {
        Destination destination = session.createQueue(destinationName);
        return session.createConsumer(destination);
    }

    public void sendMessage(String destinationName, String messageText) throws JMSException {
        MessageProducer producer = createProducer(destinationName);
        TextMessage message = session.createTextMessage(messageText);
        producer.send(message);
    }

    public String receiveMessage(String destinationName) throws JMSException {
        MessageConsumer consumer = createConsumer(destinationName);
        Message message = consumer.receive(1000);
        return message instanceof TextMessage ? ((TextMessage) message).getText() : null;
    }

    public void assertNoMessagesInQueue(String destinationName) throws JMSException {
        Queue queue = session.createQueue(destinationName);
        QueueBrowser browser = session.createBrowser(queue);
        Enumeration<?> messages = browser.getEnumeration();
        if (messages.hasMoreElements()) {
            throw new AssertionError("Messages found in queue: " + destinationName);
        }
    }

    public void deleteTemporaryDestination(TemporaryDestination destination) throws JMSException {
        destination.delete();
    }

    public void recursiveDelete(File file) {
        if (file.isDirectory()) {
            for (File subFile : file.listFiles()) {
                recursiveDelete(subFile);
            }
        }
        file.delete();
    }
}

