public class AggregationCache {
    private final int bufferSize;
    private ByPassChecker byPassChecker;

    public AggregationCache(int bufferSize) {
        this.bufferSize = bufferSize;
        this.byPassChecker = new ByPassChecker();
    }

    public ByPassChecker getByPassChecker() {
        return byPassChecker;
    }

    public class ByPassChecker {
        private Object lastKey;
        private int bypassCount;

        public ByPassChecker() {
            this.lastKey = null;
            this.bypassCount = 0;
        }

        public boolean shouldBypassAggregation(Object newKey) {
            if (lastKey == null || !lastKey.equals(newKey)) {
                lastKey = newKey;
                return false;
            }
            bypassCount++;
            return true;
        }

        public void updateState(int currentBufferSize) {
            if (currentBufferSize >= bufferSize) {
                lastKey = null; // Reset lastKey when buffer size limit is reached
            }
        }

        public int getBypassCount() {
            return bypassCount;
        }
    }
}

public class BeanUtilsBean {
    private static final Logger logger = Logger.getLogger(BeanUtilsBean.class.getName());

    private static ThreadLocal<BeanUtilsBean> threadLocalInstance = ThreadLocal.withInitial(BeanUtilsBean::new);

    public static BeanUtilsBean getInstance() {
        return threadLocalInstance.get();
    }

    public void copyProperties(Object dest, Object orig) {
        if (dest == null || orig == null) {
            logger.warning("Destination or origin is null");
            return;
        }
        PropertyDescriptor[] origDescriptors = getPropertyDescriptors(orig.getClass());
        for (PropertyDescriptor origDescriptor : origDescriptors) {
            String propertyName = origDescriptor.getName();
            if (isReadable(origDescriptor) && isWritable(dest.getClass(), propertyName)) {
                try {
                    Method readMethod = origDescriptor.getReadMethod();
                    Object value = readMethod.invoke(orig);
                    PropertyDescriptor destDescriptor = new PropertyDescriptor(propertyName, dest.getClass());
                    Method writeMethod = destDescriptor.getWriteMethod();
                    writeMethod.invoke(dest, value);
                } catch (Exception e) {
                    logger.severe("Error copying property: " + propertyName + " - " + e.getMessage());
                }
            }
        }
    }

    private PropertyDescriptor[] getPropertyDescriptors(Class<?> beanClass) {
        // Implementation omitted for brevity
        return new PropertyDescriptor[0];
    }

    private boolean isReadable(PropertyDescriptor descriptor) {
        return descriptor.getReadMethod() != null;
    }

    private boolean isWritable(Class<?> beanClass, String propertyName) {
        try {
            PropertyDescriptor descriptor = new PropertyDescriptor(propertyName, beanClass);
            return descriptor.getWriteMethod() != null;
        } catch (Exception e) {
            return false;
        }
    }

    public void populate(Object bean, Map<String, ?> properties) {
        if (bean == null || properties == null) {
            logger.warning("Bean or properties map is null");
            return;
        }
        for (Map.Entry<String, ?> entry : properties.entrySet()) {
            String propertyName = entry.getKey();
            Object value = entry.getValue();
            try {
                PropertyDescriptor descriptor = new PropertyDescriptor(propertyName, bean.getClass());
                Method writeMethod = descriptor.getWriteMethod();
                if (writeMethod != null) {
                    writeMethod.invoke(bean, value);
                }
            } catch (Exception e) {
                logger.severe("Error populating property: " + propertyName + " - " + e.getMessage());
            }
        }
    }
}

