public class TimerInterceptor extends BaseInterceptor {
    private static final Logger logger = Logger.getLogger(TimerInterceptor.class.getName());

    private final AtomicLong addTime = new AtomicLong();
    private final AtomicInteger addCount = new AtomicInteger();
    private final AtomicLong bindTime = new AtomicLong();
    private final AtomicInteger bindCount = new AtomicInteger();
    private final AtomicLong compareTime = new AtomicLong();
    private final AtomicInteger compareCount = new AtomicInteger();
    private final AtomicLong deleteTime = new AtomicLong();
    private final AtomicInteger deleteCount = new AtomicInteger();
    private final AtomicLong getRootDSETime = new AtomicLong();
    private final AtomicInteger getRootDSECount = new AtomicInteger();
    private final AtomicLong entryExistenceTime = new AtomicLong();
    private final AtomicInteger entryExistenceCount = new AtomicInteger();
    private final AtomicLong lookupTime = new AtomicLong();
    private final AtomicInteger lookupCount = new AtomicInteger();
    private final AtomicLong modifyTime = new AtomicLong();
    private final AtomicInteger modifyCount = new AtomicInteger();
    private final AtomicLong moveTime = new AtomicLong();
    private final AtomicInteger moveCount = new AtomicInteger();
    private final AtomicLong renameTime = new AtomicLong();
    private final AtomicInteger renameCount = new AtomicInteger();
    private final AtomicLong searchTime = new AtomicLong();
    private final AtomicInteger searchCount = new AtomicInteger();
    private final AtomicLong unbindTime = new AtomicLong();
    private final AtomicInteger unbindCount = new AtomicInteger();

    private static final int LOG_THRESHOLD = 1000;

    @Override
    public void add() {
        long startTime = System.nanoTime();
        // Call the actual add operation
        long duration = System.nanoTime() - startTime;
        logOperation(addTime, addCount, duration, "add");
    }

    @Override
    public void bind() {
        long startTime = System.nanoTime();
        // Call the actual bind operation
        long duration = System.nanoTime() - startTime;
        logOperation(bindTime, bindCount, duration, "bind");
    }

    @Override
    public void compare() {
        long startTime = System.nanoTime();
        // Call the actual compare operation
        long duration = System.nanoTime() - startTime;
        logOperation(compareTime, compareCount, duration, "compare");
    }

    @Override
    public void delete() {
        long startTime = System.nanoTime();
        // Call the actual delete operation
        long duration = System.nanoTime() - startTime;
        logOperation(deleteTime, deleteCount, duration, "delete");
    }

    @Override
    public void getRootDSE() {
        long startTime = System.nanoTime();
        // Call the actual getRootDSE operation
        long duration = System.nanoTime() - startTime;
        logOperation(getRootDSETime, getRootDSECount, duration, "getRootDSE");
    }

    @Override
    public void entryExists() {
        long startTime = System.nanoTime();
        // Call the actual entryExists operation
        long duration = System.nanoTime() - startTime;
        logOperation(entryExistenceTime, entryExistenceCount, duration, "entryExists");
    }

    @Override
    public void lookup() {
        long startTime = System.nanoTime();
        // Call the actual lookup operation
        long duration = System.nanoTime() - startTime;
        logOperation(lookupTime, lookupCount, duration, "lookup");
    }

    @Override
    public void modify() {
        long startTime = System.nanoTime();
        // Call the actual modify operation
        long duration = System.nanoTime() - startTime;
        logOperation(modifyTime, modifyCount, duration, "modify");
    }

    @Override
    public void move() {
        long startTime = System.nanoTime();
        // Call the actual move operation
        long duration = System.nanoTime() - startTime;
        logOperation(moveTime, moveCount, duration, "move");
    }

    @Override
    public void rename() {
        long startTime = System.nanoTime();
        // Call the actual rename operation
        long duration = System.nanoTime() - startTime;
        logOperation(renameTime, renameCount, duration, "rename");
    }

    @Override
    public void search() {
        long startTime = System.nanoTime();
        // Call the actual search operation
        long duration = System.nanoTime() - startTime;
        logOperation(searchTime, searchCount, duration, "search");
    }

    @Override
    public void unbind() {
        long startTime = System.nanoTime();
        // Call the actual unbind operation
        long duration = System.nanoTime() - startTime;
        logOperation(unbindTime, unbindCount, duration, "unbind");
    }

    private void logOperation(AtomicLong totalTime, AtomicInteger count, long duration, String operation) {
        totalTime.addAndGet(duration);
        count.incrementAndGet();
        if (count.get() % LOG_THRESHOLD == 0) {
            logger.info("Average time for " + operation + ": " + (totalTime.get() / count.get()) + " ns");
        }
    }
}

