public class Int8Datum extends NumericDatum {
    private long value;

    public Int8Datum(long value) {
        this.value = value;
    }

    public Int8Datum(byte[] bytes) {
        if (bytes.length != 8) {
            throw new IllegalArgumentException("Byte array must be of length 8.");
        }
        this.value = ((long) bytes[0] << 56) | ((long) (bytes[1] & 255) << 48) |
                     ((long) (bytes[2] & 255) << 40) | ((long) (bytes[3] & 255) << 32) |
                     ((long) (bytes[4] & 255) << 24) | ((long) (bytes[5] & 255) << 16) |
                     ((long) (bytes[6] & 255) << 8) | ((long) (bytes[7] & 255));
    }

    public boolean toBoolean() {
        return value != 0;
    }

    public char toChar() {
        return (char) value;
    }

    public short toShort() {
        return (short) value;
    }

    public int toInt() {
        return (int) value;
    }

    public long toLong() {
        return value;
    }

    public byte toByte() {
        return (byte) value;
    }

    public float toFloat() {
        return (float) value;
    }

    public double toDouble() {
        return (double) value;
    }

    public String toString() {
        return Long.toString(value);
    }

    public Int8Datum add(NumericDatum other) {
        return new Int8Datum(this.value + other.toLong());
    }

    public Int8Datum subtract(NumericDatum other) {
        return new Int8Datum(this.value - other.toLong());
    }

    public Int8Datum multiply(NumericDatum other) {
        return new Int8Datum(this.value * other.toLong());
    }

    public Int8Datum divide(NumericDatum other) {
        if (other.toLong() == 0) {
            throw new ArithmeticException("Division by zero.");
        }
        return new Int8Datum(this.value / other.toLong());
    }

    public Int8Datum modulus(NumericDatum other) {
        return new Int8Datum(this.value % other.toLong());
    }

    public int compareTo(Datum other) {
        if (other instanceof Int8Datum) {
            return Long.compare(this.value, ((Int8Datum) other).value);
        }
        throw new IllegalArgumentException("Cannot compare with non-Int8Datum.");
    }

    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Int8Datum)) return false;
        Int8Datum other = (Int8Datum) obj;
        return this.value == other.value;
    }

    public int hashCode() {
        return Long.hashCode(value);
    }

    public int size() {
        return Long.BYTES;
    }
}

