public class MultiKeyMap<K1, K2, K3, K4, K5, V> extends AbstractMap<Object, V> implements Serializable {
    private final Map<MultiKey<K1, K2, K3, K4, K5>, V> map;

    public MultiKeyMap() {
        this.map = new HashMap<>();
    }

    public V put(K1 key1, K2 key2, K3 key3, K4 key4, K5 key5, V value) {
        validateKeys(key1, key2, key3, key4, key5);
        return map.put(new MultiKey<>(key1, key2, key3, key4, key5), value);
    }

    public V get(K1 key1, K2 key2, K3 key3, K4 key4, K5 key5) {
        validateKeys(key1, key2, key3, key4, key5);
        return map.get(new MultiKey<>(key1, key2, key3, key4, key5));
    }

    public boolean containsKey(K1 key1, K2 key2, K3 key3, K4 key4, K5 key5) {
        validateKeys(key1, key2, key3, key4, key5);
        return map.containsKey(new MultiKey<>(key1, key2, key3, key4, key5));
    }

    public V remove(K1 key1, K2 key2, K3 key3, K4 key4, K5 key5) {
        validateKeys(key1, key2, key3, key4, key5);
        return map.remove(new MultiKey<>(key1, key2, key3, key4, key5));
    }

    private void validateKeys(K1 key1, K2 key2, K3 key3, K4 key4, K5 key5) {
        if (key1 == null || key2 == null || key3 == null || key4 == null || key5 == null) {
            throw new IllegalArgumentException("Keys cannot be null");
        }
    }

    @Override
    public int size() {
        return map.size();
    }

    private static class MultiKey<K1, K2, K3, K4, K5> {
        private final K1 key1;
        private final K2 key2;
        private final K3 key3;
        private final K4 key4;
        private final K5 key5;

        public MultiKey(K1 key1, K2 key2, K3 key3, K4 key4, K5 key5) {
            this.key1 = key1;
            this.key2 = key2;
            this.key3 = key3;
            this.key4 = key4;
            this.key5 = key5;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof MultiKey)) return false;
            MultiKey<?, ?, ?, ?, ?> multiKey = (MultiKey<?, ?, ?, ?, ?>) o;
            return Objects.equals(key1, multiKey.key1) &&
                   Objects.equals(key2, multiKey.key2) &&
                   Objects.equals(key3, multiKey.key3) &&
                   Objects.equals(key4, multiKey.key4) &&
                   Objects.equals(key5, multiKey.key5);
        }

        @Override
        public int hashCode() {
            return Objects.hash(key1, key2, key3, key4, key5);
        }
    }
}

public class DhlServices {
    private String apiUrl;
    private String username;
    private String password;

    public DhlServices(String apiUrl, String username, String password) {
        this.apiUrl = apiUrl;
        this.username = username;
        this.password = password;
    }

    public String estimateShippingRates(String xmlRequest) throws Exception {
        return sendRequest("EstimateShippingRates", xmlRequest);
    }

    public String registerAccount(String xmlRequest) throws Exception {
        return sendRequest("RegisterAccount", xmlRequest);
    }

    public String confirmShipment(String xmlRequest) throws Exception {
        return sendRequest("ConfirmShipment", xmlRequest);
    }

    private String sendRequest(String action, String xmlRequest) throws Exception {
        URL url = new URL(apiUrl + "/" + action);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("POST");
        connection.setRequestProperty("Content-Type", "application/xml");
        connection.setRequestProperty("Authorization", "Basic " + encodeCredentials(username, password));
        connection.setDoOutput(true);

        try (OutputStream os = connection.getOutputStream()) {
            os.write(xmlRequest.getBytes());
            os.flush();
        }

        if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
            throw new IOException("HTTP error code: " + connection.getResponseCode());
        }

        try (BufferedReader br = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            StringBuilder response = new StringBuilder();
            String line;
            while ((line = br.readLine()) != null) {
                response.append(line);
            }
            return response.toString();
        }
    }

    private String encodeCredentials(String username, String password) {
        return java.util.Base64.getEncoder().encodeToString((username + ":" + password).getBytes());
    }

    public Document createXmlDocument() throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        return builder.newDocument();
    }

    public void saveXmlDocument(Document doc, String filePath) throws Exception {
        TransformerFactory transformerFactory = TransformerFactory.newInstance();
        Transformer transformer = transformerFactory.newTransformer();
        transformer.setOutputProperty(OutputKeys.INDENT, "yes");
        DOMSource source = new DOMSource(doc);
        StreamResult result = new StreamResult(new File(filePath));
        transformer.transform(source, result);
    }

    public String extractValueFromResponse(String xmlResponse, String tagName) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.parse(new ByteArrayInputStream(xmlResponse.getBytes()));
        NodeList nodeList = doc.getElementsByTagName(tagName);
        return nodeList.getLength() > 0 ? nodeList.item(0).getTextContent() : null;
    }
}

