public class IdentityZNode {
    private static final Logger logger = LoggerFactory.getLogger(IdentityZNode.class);
    private ZooKeeper zooKeeper;

    public IdentityZNode(ZooKeeper zooKeeper) {
        this.zooKeeper = zooKeeper;
    }

    public void createIdentity(String identityPath, String data) {
        try {
            if (zooKeeper.exists(identityPath, false) == null) {
                zooKeeper.create(identityPath, data.getBytes(), null, null);
            } else {
                logger.warn("Identity already exists at path: " + identityPath);
            }
        } catch (KeeperException | InterruptedException e) {
            logger.warn("Failed to create identity at path: " + identityPath, e);
        }
    }

    public String getIdentity(String identityPath) {
        try {
            byte[] data = zooKeeper.getData(identityPath, false, null);
            return new String(data);
        } catch (KeeperException | InterruptedException e) {
            logger.warn("Failed to retrieve identity at path: " + identityPath, e);
            return null;
        }
    }

    public void updateIdentity(String identityPath, String data) {
        try {
            if (zooKeeper.exists(identityPath, false) != null) {
                zooKeeper.setData(identityPath, data.getBytes(), -1);
            } else {
                logger.warn("Identity does not exist at path: " + identityPath);
            }
        } catch (KeeperException | InterruptedException e) {
            logger.warn("Failed to update identity at path: " + identityPath, e);
        }
    }

    public void deleteIdentity(String identityPath) {
        try {
            if (zooKeeper.exists(identityPath, false) != null) {
                zooKeeper.delete(identityPath, -1);
            } else {
                logger.warn("Identity does not exist at path: " + identityPath);
            }
        } catch (KeeperException | InterruptedException e) {
            logger.warn("Failed to delete identity at path: " + identityPath, e);
        }
    }

    private String constructNodePath(String basePath, String identity) {
        return basePath + "/" + identity;
    }

