public class BuildContextGenerator extends AbstractContextGenerator {
    private Dictionary<String, String> unigramDict;
    private Dictionary<String, String> bigramDict;
    private Dictionary<String, String> trigramDict;

    public BuildContextGenerator(Dictionary<String, String> unigramDict, Dictionary<String, String> bigramDict, Dictionary<String, String> trigramDict) {
        this.unigramDict = unigramDict;
        this.bigramDict = bigramDict;
        this.trigramDict = trigramDict;
    }

    public String[] getContextFeatures(Parse[] parses, int index) {
        List<String> features = new ArrayList<>();
        if (index < 0 || index >= parses.length) {
            return features.toArray(new String[0]);
        }

        Parse currentParse = parses[index];
        String head = currentParse.getHead();

        // Check for unigrams
        if (unigramDict.get(head) != null) {
            features.add("unigram:" + head);
        }

        // Check for bigrams
        if (index > 0) {
            String previousHead = parses[index - 1].getHead();
            if (bigramDict.get(previousHead + " " + head) != null) {
                features.add("bigram:" + previousHead + " " + head);
            }
        }

        // Check for trigrams
        if (index > 1) {
            String previousHead = parses[index - 1].getHead();
            String twoBackHead = parses[index - 2].getHead();
            if (trigramDict.get(twoBackHead + " " + previousHead + " " + head) != null) {
                features.add("trigram:" + twoBackHead + " " + previousHead + " " + head);
            }
        }

        // Additional features based on surrounding constituents
        if (currentParse.isPunctuation()) {
            features.add("punctuation:" + head);
        }
        if (currentParse.isSentenceEnd()) {
            features.add("sentence_end:" + head);
        }

        // Matching brackets and quotes
        if (currentParse.isOpeningBracket()) {
            features.add("opening_bracket:" + head);
        }
        if (currentParse.isClosingBracket()) {
            features.add("closing_bracket:" + head);
        }
        if (currentParse.isQuote()) {
            features.add("quote:" + head);
        }

        return features.toArray(new String[0]);
    }
}

