public class EndpointMessageListener implements MessageListener {

    private static final Logger logger = LoggerFactory.getLogger(EndpointMessageListener.class);

    private JmsOperations jmsOperations;
    private JmsBinding jmsBinding;
    private Processor processor;
    private boolean eagerLoadProperties;
    private boolean disableReplies;
    private String replyDestination;

    public EndpointMessageListener(JmsOperations jmsOperations, JmsBinding jmsBinding, Processor processor,
                                   boolean eagerLoadProperties, boolean disableReplies, String replyDestination) {
        this.jmsOperations = jmsOperations;
        this.jmsBinding = jmsBinding;
        this.processor = processor;
        this.eagerLoadProperties = eagerLoadProperties;
        this.disableReplies = disableReplies;
        this.replyDestination = replyDestination;
    }

    @Override
    public void onMessage(Message message) {
        try {
            JmsExchange exchange = createExchange(message);
            processor.process(exchange);
            if (!disableReplies) {
                sendReply(exchange);
            }
        } catch (Exception e) {
            logger.error("Error processing message", e);
        }
    }

    private JmsExchange createExchange(Message message) throws Exception {
        JmsExchange exchange = new JmsExchange();
        jmsBinding.fromMessage(message, exchange, eagerLoadProperties);
        return exchange;
    }

    private void sendReply(JmsExchange exchange) {
        if (replyDestination != null) {
            jmsOperations.send(replyDestination, exchange.getReplyMessage());
        }
    }
}

public class MediaFileView extends MediaFileBase {
    private String currentDirectory;
    private List<MediaFile> mediaFiles;
    private String sortOption;
    private int pageSize;
    private int currentPage;

    public MediaFileView(String initialDirectory) {
        this.currentDirectory = initialDirectory;
        this.mediaFiles = new ArrayList<>();
        this.sortOption = "name"; // default sort option
        this.pageSize = 10; // default page size
        this.currentPage = 1;
        prepareView();
    }

    private void prepareView() {
        loadMediaFiles();
        sortMediaFiles();
    }

    private void loadMediaFiles() {
        File dir = new File(currentDirectory);
        if (dir.exists() && dir.isDirectory()) {
            File[] files = dir.listFiles();
            if (files != null) {
                for (File file : files) {
                    if (isMediaFile(file)) {
                        mediaFiles.add(new MediaFile(file));
                    }
                }
            }
        }
    }

    private boolean isMediaFile(File file) {
        String[] mediaExtensions = {".mp4", ".mp3", ".jpg", ".png"};
        for (String ext : mediaExtensions) {
            if (file.getName().toLowerCase().endsWith(ext)) {
                return true;
            }
        }
        return false;
    }

    private void sortMediaFiles() {
        if ("name".equals(sortOption)) {
            Collections.sort(mediaFiles, Comparator.comparing(MediaFile::getName));
        } else if ("date".equals(sortOption)) {
            Collections.sort(mediaFiles, Comparator.comparing(MediaFile::getDateCreated));
        }
    }

    public void createDirectory(String directoryName) {
        File newDir = new File(currentDirectory, directoryName);
        if (!newDir.exists()) {
            newDir.mkdir();
        } else {
            throw new IllegalArgumentException("Directory already exists.");
        }
    }

    public void deleteDirectory(String directoryName) {
        File dirToDelete = new File(currentDirectory, directoryName);
        if (dirToDelete.exists() && dirToDelete.isDirectory()) {
            deleteRecursively(dirToDelete);
        } else {
            throw new IllegalArgumentException("Directory does not exist.");
        }
    }

    private void deleteRecursively(File file) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File subFile : files) {
                deleteRecursively(subFile);
            }
        }
        file.delete();
    }

    public void moveSelectedFiles(List<MediaFile> selectedFiles, String targetDirectory) {
        File targetDir = new File(currentDirectory, targetDirectory);
        if (!targetDir.exists() || !targetDir.isDirectory()) {
            throw new IllegalArgumentException("Target directory does not exist.");
        }
        for (MediaFile mediaFile : selectedFiles) {
            File sourceFile = mediaFile.getFile();
            File destFile = new File(targetDir, sourceFile.getName());
            sourceFile.renameTo(destFile);
        }
    }

    public List<MediaFile> searchMediaFiles(String filter) {
        List<MediaFile> filteredFiles = new ArrayList<>();
        for (MediaFile mediaFile : mediaFiles) {
            if (mediaFile.getName().contains(filter)) {
                filteredFiles.add(mediaFile);
            }
        }
        return filteredFiles;
    }

    public void setSortOption(String sortOption) {
        this.sortOption = sortOption;
        sortMediaFiles();
    }

    public void setPageSize(int pageSize) {
        this.pageSize = pageSize;
    }

    public List<MediaFile> getCurrentPageFiles() {
        int start = (currentPage - 1) * pageSize;
        int end = Math.min(start + pageSize, mediaFiles.size());
        return mediaFiles.subList(start, end);
    }

    public void nextPage() {
        if ((currentPage * pageSize) < mediaFiles.size()) {
            currentPage++;
        }
    }

    public void previousPage() {
        if (currentPage > 1) {
            currentPage--;
        }
    }

    public int getTotalPages() {
        return (int) Math.ceil((double) mediaFiles.size() / pageSize);
    }

    public String getCurrentDirectory() {
        return currentDirectory;
    }

    public void setCurrentDirectory(String currentDirectory) {
        this.currentDirectory = currentDirectory;
        prepareView();
    }
}

