public class ScriptVerbalizer {
    private RutaVerbalizer rutaVerbalizer;

    public ScriptVerbalizer(RutaVerbalizer rutaVerbalizer) {
        this.rutaVerbalizer = rutaVerbalizer;
    }

    public String verbalizeForEachBlock(ForEachBlock block) {
        StringBuilder sb = new StringBuilder();
        sb.append("ForEach ").append(block.getVariable()).append(" in ").append(block.getCollection()).append(" {");
        for (Rule rule : block.getRules()) {
            sb.append(verbalizeRule(rule));
        }
        sb.append("}");
        return sb.toString();
    }

    public String verbalizeRule(Rule rule) {
        StringBuilder sb = new StringBuilder();
        sb.append("Rule: ").append(rule.getName()).append(" -> ");
        for (RuleElement element : rule.getElements()) {
            sb.append(verbalizeRuleElement(element)).append(", ");
        }
        sb.setLength(sb.length() - 2); // Remove last comma
        sb.append(";");
        return sb.toString();
    }

    public String verbalizeRuleElement(RuleElement element) {
        StringBuilder sb = new StringBuilder();
        sb.append(element.getType()).append(" ");
        if (element.hasCondition()) {
            sb.append("if ").append(verbalizeCondition(element.getCondition())).append(" ");
        }
        sb.append("then ").append(verbalizeAction(element.getAction()));
        return sb.toString();
    }

    public String verbalizeCondition(Condition condition) {
        return condition.getExpression(); // Simplified for brevity
    }

    public String verbalizeAction(Action action) {
        return action.getDescription(); // Simplified for brevity
    }
}

