public class RouteText {
    private final Map<String, List<Predicate<String>>> routingStrategies = new HashMap<>();
    private final List<String> unmatchedLines = new ArrayList<>();

    public void addRoutingStrategy(String relationship, String condition, String matchType) {
        Predicate<String> predicate = createPredicate(condition, matchType);
        routingStrategies.computeIfAbsent(relationship, k -> new ArrayList<>()).add(predicate);
    }

    private Predicate<String> createPredicate(String condition, String matchType) {
        switch (matchType.toLowerCase()) {
            case "starts with":
                return line -> line.startsWith(condition);
            case "ends with":
                return line -> line.endsWith(condition);
            case "contains":
                return line -> line.contains(condition);
            case "equals":
                return line -> line.equals(condition);
            case "regex":
                Pattern pattern = Pattern.compile(condition);
                return line -> pattern.matcher(line).find();
            default:
                throw new IllegalArgumentException("Invalid match type: " + matchType);
        }
    }

    public void routeLine(String line) {
        boolean matched = false;
        for (Map.Entry<String, List<Predicate<String>>> entry : routingStrategies.entrySet()) {
            for (Predicate<String> predicate : entry.getValue()) {
                if (predicate.test(line)) {
                    routeToRelationship(entry.getKey(), line);
                    matched = true;
                    break;
                }
            }
            if (matched) break;
        }
        if (!matched) {
            unmatchedLines.add(line);
            routeToUnmatched(line);
        }
    }

    private void routeToRelationship(String relationship, String line) {
        // Implement the logic to route the line to the specified relationship
        System.out.println("Routing to " + relationship + ": " + line);
    }

    private void routeToUnmatched(String line) {
        // Implement the logic to handle unmatched lines
        System.out.println("Unmatched line: " + line);
    }

    public List<String> getUnmatchedLines() {
        return unmatchedLines;
    }

    public static void main(String[] args) {
        RouteText routeText = new RouteText();
        routeText.addRoutingStrategy("RelationshipA", "Hello", "starts with");
        routeText.addRoutingStrategy("RelationshipB", "World", "ends with");
        routeText.addRoutingStrategy("RelationshipC", "Java", "contains");
        routeText.addRoutingStrategy("RelationshipD", "\\d+", "regex");

        routeText.routeLine("Hello there!");
        routeText.routeLine("This is a World");
        routeText.routeLine("I love Java programming");
        routeText.routeLine("12345 is a number");
        routeText.routeLine("No match here");

        System.out.println("Unmatched lines: " + routeText.getUnmatchedLines());
    }
}

