public class RomanianStemmer extends AbstractSnowballStemmer {
    private static final String[] STANDARD_SUFFIXES = {"e", "i", "ul", "le", "elor"};
    private static final String[] VERB_SUFFIXES = {"ez", "eaza", "ezi", "eaza", "am", "at", "a"};
    private static final String[] VOWEL_SUFFIXES = {"a", "e", "i", "o", "u"};

    private int position;
    private boolean suffixRemoved;

    public RomanianStemmer() {
        super();
        this.position = 0;
        this.suffixRemoved = false;
    }

    @Override
    public String stem(String word) {
        position = word.length();
        suffixRemoved = false;

        applyStandardSuffixes(word);
        applyVerbSuffixes(word);
        applyVowelSuffixes(word);

        return word.substring(0, position);
    }

    private void applyStandardSuffixes(String word) {
        for (String suffix : STANDARD_SUFFIXES) {
            if (word.endsWith(suffix)) {
                position -= suffix.length();
                suffixRemoved = true;
                break;
            }
        }
    }

    private void applyVerbSuffixes(String word) {
        for (String suffix : VERB_SUFFIXES) {
            if (word.endsWith(suffix)) {
                position -= suffix.length();
                suffixRemoved = true;
                break;
            }
        }
    }

    private void applyVowelSuffixes(String word) {
        for (String suffix : VOWEL_SUFFIXES) {
            if (word.endsWith(suffix)) {
                position -= suffix.length();
                suffixRemoved = true;
                break;
            }
        }
    }
}

