public class ServiceJavascriptBuilder extends ServiceModelVisitor {
    private StringBuilder code;
    private Set<String> nameConflicts;
    private Map<String, String> serializers;
    private Map<String, String> deserializers;

    public ServiceJavascriptBuilder() {
        this.code = new StringBuilder();
        this.nameConflicts = new HashSet<>();
        this.serializers = new HashMap<>();
        this.deserializers = new HashMap<>();
    }

    @Override
    public void visitService(ServiceModel service) {
        code.append("function ").append(service.getName()).append("Service() {\n");
        for (OperationModel operation : service.getOperations()) {
            visitOperation(operation);
        }
        code.append("}\n");
    }

    private void visitOperation(OperationModel operation) {
        String functionName = operation.getName();
        if (nameConflicts.contains(functionName)) {
            functionName += "_" + UUID.randomUUID().toString().substring(0, 8);
        }
        nameConflicts.add(functionName);

        code.append("    this.").append(functionName).append(" = function(params, successCallback, errorCallback) {\n");
        code.append("        var xhr = new XMLHttpRequest();\n");
        code.append("        xhr.open('POST', '").append(operation.getEndpoint()).append("', true);\n");
        code.append("        xhr.setRequestHeader('Content-Type', 'application/json');\n");
        code.append("        xhr.onreadystatechange = function() {\n");
        code.append("            if (xhr.readyState === 4) {\n");
        code.append("                if (xhr.status === 200) {\n");
        code.append("                    successCallback(JSON.parse(xhr.responseText));\n");
        code.append("                } else {\n");
        code.append("                    errorCallback(xhr.status, xhr.statusText);\n");
        code.append("                }\n");
        code.append("            }\n");
        code.append("        };\n");
        code.append("        xhr.send(JSON.stringify(").append(generateSerializer(operation)).append("));\n");
        code.append("    };\n");
    }

    private String generateSerializer(OperationModel operation) {
        // Placeholder for serializer logic
        String inputMessage = operation.getInputMessage();
        if (!serializers.containsKey(inputMessage)) {
            serializers.put(inputMessage, "serialize" + inputMessage);
        }
        return serializers.get(inputMessage) + "(params);";
    }

    public String getGeneratedCode() {
        return code.toString();
    }
}

