public class HtmlConverter extends JCasAnnotator_ImplBase {

    public static final String PARAM_INPUT_VIEW = "InputView";
    public static final String PARAM_OUTPUT_VIEW = "OutputView";
    public static final String PARAM_REPLACE_LINE_BREAKS = "ReplaceLineBreaks";
    public static final String PARAM_HANDLE_WHITESPACE = "HandleWhitespace";
    public static final String PARAM_HTML_ENTITY_CONVERSION = "HtmlEntityConversion";

    @ConfigurationParameter(name = PARAM_INPUT_VIEW, mandatory = true)
    private String inputView;

    @ConfigurationParameter(name = PARAM_OUTPUT_VIEW, mandatory = true)
    private String outputView;

    @ConfigurationParameter(name = PARAM_REPLACE_LINE_BREAKS, mandatory = false, defaultValue = "true")
    private boolean replaceLineBreaks;

    @ConfigurationParameter(name = PARAM_HANDLE_WHITESPACE, mandatory = false, defaultValue = "true")
    private boolean handleWhitespace;

    @ConfigurationParameter(name = PARAM_HTML_ENTITY_CONVERSION, mandatory = false, defaultValue = "true")
    private boolean htmlEntityConversion;

    @Override
    public void process(JCas jcas) {
        JCas inputJCas = jcas.getView(inputView);
        JCas outputJCas = jcas.createView(outputView);

        String htmlContent = inputJCas.getDocumentText();
        String convertedText = convertHtmlToText(htmlContent);

        outputJCas.setDocumentText(convertedText);
        manageAnnotations(inputJCas, outputJCas);
    }

    private String convertHtmlToText(String html) {
        if (htmlEntityConversion) {
            html = convertHtmlEntities(html);
        }
        if (replaceLineBreaks) {
            html = html.replaceAll("<br\\s*/?>", "\n");
        }
        if (handleWhitespace) {
            html = html.replaceAll("\\s+", " ");
        }
        return html.replaceAll("<[^>]+>", ""); // Remove HTML tags
    }

    private String convertHtmlEntities(String html) {
        // Basic conversion for common HTML entities
        return html.replace("&amp;", "&")
                   .replace("&lt;", "<")
                   .replace("&gt;", ">")
                   .replace("&quot;", "\"")
                   .replace("&apos;", "'");
    }

    private void manageAnnotations(JCas inputJCas, JCas outputJCas) {
        // Logic to map annotations from inputJCas to outputJCas
        // This part may contain code smells due to complexity and lack of separation of concerns
        for (Annotation annotation : JCasUtil.select(inputJCas, Annotation.class)) {
            // Create corresponding annotation in outputJCas
            Annotation newAnnotation = new Annotation(outputJCas, annotation.getBegin(), annotation.getEnd());
            newAnnotation.addToIndexes();
        }
    }
}

