        byte[] data = "Garbage Collection Test".getBytes();
        blobStore.writeBlob(identifier, data);
        blobStore.deleteBlob(identifier);

        assertNull(blobStore.readBlob(identifier));
    }

    @Test
    public void testResourceManagement() throws IOException {
        String identifier = UUID.randomUUID().toString();
        byte[] data = "Resource Management Test".getBytes();
        blobStore.writeBlob(identifier, data);
        blobStore.close();

        assertThrows(IllegalStateException.class, () -> blobStore.readBlob(identifier));
    }

    protected void addFileToBlobStore(String filePath) throws IOException {
        File file = new File(filePath);
        String identifier = UUID.randomUUID().toString();
        try (FileInputStream fis = new FileInputStream(file)) {
            byte[] data = new byte[(int) file.length()];
            fis.read(data);
            blobStore.writeBlob(identifier, data);
        }
    }

    protected byte[] readBlobFully(String identifier) throws IOException {
        return blobStore.readBlob(identifier);
    }

    public static void main(String[] args) {
        // Example usage of the blob store
        BlobStore blobStore = new InMemoryBlobStore(); // Replace with actual implementation
        String identifier = UUID.randomUUID().toString();
        byte[] data = "Example Blob Data".getBytes();

        blobStore.writeBlob(identifier, data);
        byte[] retrievedData = blobStore.readBlob(identifier);
        System.out.println(new String(retrievedData));
    }
}

