public class SoapBindingFactory extends AbstractBindingFactory {

    @Override
    public BindingInfo createBindingInfo(Service service, Binding binding) {
        SoapBindingInfo soapBindingInfo = new SoapBindingInfo();
        configureSoapBinding(soapBindingInfo, binding);
        return soapBindingInfo;
    }

    private void configureSoapBinding(SoapBindingInfo soapBindingInfo, Binding binding) {
        if (isSoap11(binding)) {
            soapBindingInfo.setProtocol("SOAP 1.1");
        } else if (isSoap12(binding)) {
            soapBindingInfo.setProtocol("SOAP 1.2");
        } else {
            throw new IllegalArgumentException("Unsupported SOAP version");
        }
        setupOperations(soapBindingInfo, binding);
        setupHeaders(soapBindingInfo, binding);
        setupMessageParts(soapBindingInfo, binding);
        configureInterceptors(soapBindingInfo);
        configureMtom(soapBindingInfo);
        configureWsAddressing(soapBindingInfo);
    }

    private boolean isSoap11(Binding binding) {
        // Logic to determine if the binding is SOAP 1.1
        return binding.getVersion().equals("SOAP 1.1");
    }

    private boolean isSoap12(Binding binding) {
        // Logic to determine if the binding is SOAP 1.2
        return binding.getVersion().equals("SOAP 1.2");
