public class XMLChar {
    private static final int[] VALID_XML_CHARS = new int[65536]; // Array to categorize Unicode characters

    static {
        // Initialize VALID_XML_CHARS array with character validity
        for (int i = 0; i < VALID_XML_CHARS.length; i++) {
            VALID_XML_CHARS[i] = isValidXMLChar(i) ? 1 : 0; // 1 for valid, 0 for invalid
        }
    }

    public static boolean isValidXMLChar(int ch) {
        return (ch >= 0x20 && ch <= 0xD7FF) || (ch >= 0xE000 && ch <= 0xFFFD) || (ch >= 0x10000 && ch <= 0x10FFFF);
    }

    public static boolean isSpace(int ch) {
        return ch == 0x20 || ch == 0x9 || ch == 0xA || ch == 0xD;
    }

    public static boolean isNameStartChar(int ch) {
        return (ch >= 0xC0 && ch <= 0xD6) || (ch >= 0xD8 && ch <= 0xF6) || (ch >= 0xF8 && ch <= 0x2FF) ||
               (ch >= 0x300 && ch <= 0xD7FF) || (ch >= 0xE000 && ch <= 0xFFFD) || (ch >= 0x10000 && ch <= 0x10FFFF);
    }

    public static boolean isNameChar(int ch) {
        return isNameStartChar(ch) || isDigit(ch) || ch == '-' || ch == '_' || ch == '.' || ch == ':';
    }

    public static boolean isDigit(int ch) {
        return ch >= 0x30 && ch <= 0x39;
    }

    public static boolean isNCName(String name) {
        if (name.isEmpty() || !isNameStartChar(name.codePointAt(0))) {
            return false;
        }
        for (int i = 1; i < name.length(); i++) {
            if (!isNameChar(name.codePointAt(i))) {
                return false;
            }
        }
        return true;
    }

    public static boolean isNMTOKEN(String token) {
        for (int i = 0; i < token.length(); i++) {
            if (!isNameChar(token.codePointAt(i))) {
                return false;
            }
        }
        return !token.isEmpty();
    }

