public class PorterStemmer {
    private StringBuilder buffer;
    private int currentIndex;
    private static final int INC = 50;

    public PorterStemmer() {
        buffer = new StringBuilder(INC);
        currentIndex = 0;
    }

    public void add(char ch) {
        if (currentIndex == buffer.length()) {
            buffer.append(new char[INC]);
        }
        buffer.setCharAt(currentIndex++, ch);
    }

    public void reset() {
        currentIndex = 0;
    }

    public String stem(String word) {
        reset();
        for (char ch : word.toCharArray()) {
            add(ch);
        }
        currentIndex = word.length();
        if (currentIndex <= 2) return word;
        step1();
        step2();
        step3();
        step4();
        step5();
        return buffer.substring(0, currentIndex);
    }

    private void step1() {
        if (buffer.substring(0, currentIndex).endsWith("sses")) {
            currentIndex -= 2;
        } else if (buffer.substring(0, currentIndex).endsWith("ies")) {
            currentIndex -= 2;
        } else if (buffer.charAt(currentIndex - 1) == 's') {
            currentIndex--;
        }
    }

    private void step2() {
        if (buffer.substring(0, currentIndex).endsWith("ed") && containsVowel()) {
            currentIndex -= 2;
        } else if (buffer.substring(0, currentIndex).endsWith("ing") && containsVowel()) {
            currentIndex -= 3;
        }
    }

    private void step3() {
        if (buffer.substring(0, currentIndex).endsWith("y") && containsVowel()) {
            buffer.setCharAt(currentIndex - 1, 'i');
        }
    }

    private void step4() {
        if (currentIndex > 1) {
            if (buffer.substring(0, currentIndex).endsWith("ation")) {
                currentIndex -= 4;
            } else if (buffer.substring(0, currentIndex).endsWith("ator")) {
                currentIndex -= 3;
            }
        }
    }

    private void step5() {
        if (currentIndex > 1 && buffer.charAt(currentIndex - 1) == 'e') {
            if (!hasConsonantSequence()) {
                currentIndex--;
            }
        }
    }

    private boolean containsVowel() {
        for (int i = 0; i < currentIndex; i++) {
            char ch = buffer.charAt(i);
            if (isVowel(ch)) {
                return true;
            }
        }
        return false;
    }

    private boolean isVowel(char ch) {
        return "aeiou".indexOf(ch) >= 0;
    }

    private boolean hasConsonantSequence() {
        // Implement logic to check for consonant sequences
        return true; // Placeholder
    }

    public static void main(String[] args) {
        PorterStemmer stemmer = new PorterStemmer();
        try (BufferedReader reader = new BufferedReader(new FileReader("input.txt"))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] words = line.split("\\s+");
                for (String word : words) {
                    String stemmedWord = stemmer.stem(word);
                    System.out.print(stemmedWord + " ");
                }
                System.out.println();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

