public class IPLookupService {
    private DatabaseReader cityReader;
    private DatabaseReader countryReader;
    private DatabaseReader ispReader;
    private DatabaseReader anonymousIpReader;
    private DatabaseReader domainReader;

    public IPLookupService(String cityDbPath, String countryDbPath, String ispDbPath, String anonymousIpDbPath, String domainDbPath) throws IOException {
        this.cityReader = new DatabaseReader.Builder(new File(cityDbPath)).build();
        this.countryReader = new DatabaseReader.Builder(new File(countryDbPath)).build();
        this.ispReader = new DatabaseReader.Builder(new File(ispDbPath)).build();
        this.anonymousIpReader = new DatabaseReader.Builder(new File(anonymousIpDbPath)).build();
        this.domainReader = new DatabaseReader.Builder(new File(domainDbPath)).build();
    }

    public Map<String, Object> lookup(String ipAddress) {
        Map<String, Object> result = new HashMap<>();
        try {
            InetAddress ip = InetAddress.getByName(ipAddress);
            result.put("city", getCityInfo(ip));
            result.put("country", getCountryInfo(ip));
            result.put("isp", getIspInfo(ip));
            result.put("anonymous", isAnonymousIp(ip));
            result.put("domain", getDomainInfo(ip));
        } catch (IOException | GeoIp2Exception e) {
            e.printStackTrace();
        }
        return result;
    }

    private Map<String, Object> getCityInfo(InetAddress ip) throws GeoIp2Exception, IOException {
        CityResponse response = cityReader.city(ip);
        Map<String, Object> cityInfo = new HashMap<>();
        cityInfo.put("city", response.getCity().getName());
        cityInfo.put("latitude", response.getLocation().getLatitude());
        cityInfo.put("longitude", response.getLocation().getLongitude());
        return cityInfo;
    }

    private Map<String, Object> getCountryInfo(InetAddress ip) throws GeoIp2Exception, IOException {
        CountryResponse response = countryReader.country(ip);
        Map<String, Object> countryInfo = new HashMap<>();
        countryInfo.put("country", response.getCountry().getName());
        countryInfo.put("countryCode", response.getCountry().getIsoCode());
        return countryInfo;
    }

    private Map<String, Object> getIspInfo(InetAddress ip) throws GeoIp2Exception, IOException {
        IspResponse response = ispReader.isp(ip);
        Map<String, Object> ispInfo = new HashMap<>();
        ispInfo.put("isp", response.getIsp());
        ispInfo.put("organization", response.getOrganization());
        return ispInfo;
    }

    private boolean isAnonymousIp(InetAddress ip) throws GeoIp2Exception, IOException {
        AnonymousIpResponse response = anonymousIpReader.anonymousIp(ip);
        return response.isAnonymous();
    }

    private String getDomainInfo(InetAddress ip) throws GeoIp2Exception, IOException {
        DomainResponse response = domainReader.domain(ip);
        return response.getDomain();
    }

    public void close() throws IOException {
        cityReader.close();
        countryReader.close();
        ispReader.close();
        anonymousIpReader.close();
        domainReader.close();
    }
}

