    public void writeObject(JsonGenerator jsonGenerator, Object object) throws IOException {
        if (object == null) {
            jsonGenerator.writeNull();
            return;
        }
        if (object instanceof Collection) {
            writeCollection(jsonGenerator, (Collection<?>) object);
        } else if (object instanceof Map) {
            writeMap(jsonGenerator, (Map<?, ?>) object);
        } else if (object.getClass().isArray()) {
            writeArray(jsonGenerator, object);
        } else {
            writePrimitive(jsonGenerator, object);
        }
    }

    private void writeCollection(JsonGenerator jsonGenerator, Collection<?> collection) throws IOException {
        jsonGenerator.writeStartArray();
        for (Object item : collection) {
            writeObject(jsonGenerator, item);
        }
        jsonGenerator.writeEndArray();
    }

    private void writeMap(JsonGenerator jsonGenerator, Map<?, ?> map) throws IOException {
        jsonGenerator.writeStartObject();
        for (Map.Entry<?, ?> entry : map.entrySet()) {
            jsonGenerator.writeFieldName(String.valueOf(entry.getKey()));
            writeObject(jsonGenerator, entry.getValue());
        }
        jsonGenerator.writeEndObject();
    }

    private void writeArray(JsonGenerator jsonGenerator, Object array) throws IOException {
        jsonGenerator.writeStartArray();
        for (int i = 0; i < java.lang.reflect.Array.getLength(array); i++) {
            writeObject(jsonGenerator, java.lang.reflect.Array.get(array, i));
        }
        jsonGenerator.writeEndArray();
    }

    private void writePrimitive(JsonGenerator jsonGenerator, Object object) throws IOException {
        jsonGenerator.writeObject(object);
    }

    @Override
    public void writeObjects(JsonGenerator jsonGenerator, Iterable<?> objects) throws IOException {
        jsonGenerator.writeStartArray();
        for (Object object : objects) {
            writeObject(jsonGenerator, object);
        }
        jsonGenerator.writeEndArray();
    }

    // Additional methods for handling custom adapters and filtering can be added here
}

