public class SymmLQTest {

    @Test
    public void saundersTest() {
        // Test configurations
        int[] sizes = {10, 50, 100, 500};
        for (int size : sizes) {
            double[][] matrix = generateSymmetricPositiveDefiniteMatrix(size);
            double[] b = generateRandomVector(size);
            double[] x0 = new double[size]; // Initial guess

            SymmLQ solver = new SymmLQ(matrix, b);
            solver.setInitialGuess(x0);
            solver.setPreconditioner(new SomePreconditioner());

            double[] solution = solver.solve();
            assertArrayEquals(expectedSolution(matrix, b), solution, 1e-5);
            assertTrue(checkResidualNorm(matrix, b, solution) < 1e-5);
        }
    }

    @Test
    public void testNonSquareMatrix() {
        double[][] matrix = {{1, 2}, {3, 4}, {5, 6}};
        double[] b = {1, 2, 3};
        assertThrows(IllegalArgumentException.class, () -> {
            new SymmLQ(matrix, b);
        });
    }

    @Test
    public void testDimensionMismatch() {
        double[][] matrix = {{1, 2}, {2, 1}};
        double[] b = {1, 2, 3};
        assertThrows(IllegalArgumentException.class, () -> {
            new SymmLQ(matrix, b);
        });
    }

    @Test
    public void testPerformanceWithPreconditioning() {
        int size = 1000;
        double[][] matrix = generateSymmetricPositiveDefiniteMatrix(size);
        double[] b = generateRandomVector(size);
        SymmLQ solver = new SymmLQ(matrix, b);
        solver.setPreconditioner(new SomePreconditioner());

        long startTime = System.nanoTime();
        double[] solution = solver.solve();
        long endTime = System.nanoTime();

        assertTrue(checkResidualNorm(matrix, b, solution) < 1e-5);
        System.out.println("Time with preconditioning: " + (endTime - startTime) + " ns");
    }

    @Test
    public void testPerformanceWithoutPreconditioning() {
        int size = 1000;
        double[][] matrix = generateSymmetricPositiveDefiniteMatrix(size);
        double[] b = generateRandomVector(size);
        SymmLQ solver = new SymmLQ(matrix, b);

        long startTime = System.nanoTime();
        double[] solution = solver.solve();
        long endTime = System.nanoTime();

        assertTrue(checkResidualNorm(matrix, b, solution) < 1e-5);
        System.out.println("Time without preconditioning: " + (endTime - startTime) + " ns");
    }

    @Test
    public void testInitialGuessImpact() {
        int size = 50;
        double[][] matrix = generateSymmetricPositiveDefiniteMatrix(size);
        double[] b = generateRandomVector(size);
        double[] initialGuess = new double[size]; // Zero initial guess

