public class InjectorImpl implements Injector {
    private final Map<Class<?>, Object> instanceMap = new ConcurrentHashMap<>();
    private final Map<String, Object> parameterMap = new ConcurrentHashMap<>();
    private final ReentrantLock lock = new ReentrantLock();

    @Override
    public <T> T getInstance(Class<T> clazz) {
        lock.lock();
        try {
            if (instanceMap.containsKey(clazz)) {
                return clazz.cast(instanceMap.get(clazz));
            }
            T instance = createInstance(clazz);
            instanceMap.put(clazz, instance);
            return instance;
        } finally {
            lock.unlock();
        }
    }

    @Override
    public void bindInstance(Class<?> clazz, Object instance) {
        lock.lock();
        try {
            instanceMap.put(clazz, instance);
        } finally {
            lock.unlock();
        }
    }

    @Override
    public void bindParameter(String name, Object value) {
        lock.lock();
        try {
            parameterMap.put(name, value);
        } finally {
            lock.unlock();
        }
    }

    @Override
    public boolean isInjectable(Class<?> clazz) {
        return instanceMap.containsKey(clazz);
    }

    @Override
    public boolean isInjectable(String name) {
        return parameterMap.containsKey(name);
    }

    @Override
    public Injector createChildInjector() {
        return new InjectorImpl();
    }

    private <T> T createInstance(Class<T> clazz) {
