    public Object getAnnotation(String name) throws JMSException {
        return annotations.get(name);
    }

    @Override
    public int getDeliveryCount() throws JMSException {
        return deliveryCount;
    }

    @Override
    public void incrementDeliveryCount() throws JMSException {
        deliveryCount++;
    }

    @Override
    public void serialize(MessageProducer producer, Session session) throws JMSException {
        Message message = session.createMessage();
        message.setJMSMessageID(messageId);
        message.setJMSCorrelationID(correlationId);
        message.setJMSTimestamp(timestamp);
        message.setJMSPriority(priority);
        message.setLongProperty("JMS_Expiration", expiration);
        for (Map.Entry<String, Object> entry : properties.entrySet()) {
            message.setObjectProperty(entry.getKey(), entry.getValue());
        }
        producer.send(message);
    }

    @Override
    public AmqpJmsMessageFacade copy() throws JMSException {
        AmqpJmsMessageFacade copy = new AmqpJmsMessageFacade(connection);
        copy.setMessageId(messageId);
        copy.setCorrelationId(correlationId);
        copy.setTimestamp(timestamp);
        copy.setPriority(priority);
        copy.setExpiration(expiration);
        copy.properties.putAll(properties);
        copy.annotations.putAll(annotations);
        copy.deliveryCount = deliveryCount;
        return copy;
    }
}

public class PerceptronTrainer extends AbstractEventTrainer {
    private double tolerance;
    private double stepSizeDecrease;
    private int maxIterations;
    private boolean averageParameters;
    private double[] weights;
    private double bias;

    public PerceptronTrainer(double tolerance, double stepSizeDecrease, int maxIterations, boolean averageParameters) {
        this.tolerance = tolerance;
        this.stepSizeDecrease = stepSizeDecrease;
        this.maxIterations = maxIterations;
        this.averageParameters = averageParameters;
    }

    @Override
    protected void validateTrainingParameters() {
        if (tolerance <= 0 || stepSizeDecrease <= 0 || maxIterations <= 0) {
            throw new IllegalArgumentException("Invalid training parameters");
        }
    }

    @Override
    protected void configureTrainingSettings() {
        // Configuration logic can be added here if needed
    }

    @Override
    public PerceptronModel train(List<double[]> trainingData, List<Integer> labels) {
        int numFeatures = trainingData.get(0).length;
        weights = new double[numFeatures];
        bias = 0.0;

        double[] accumulatedWeights = new double[numFeatures];
        double accumulatedBias = 0.0;

        for (int iteration = 0; iteration < maxIterations; iteration++) {
            boolean hasError = false;

            for (int i = 0; i < trainingData.size(); i++) {
                double[] features = trainingData.get(i);
                int label = labels.get(i);
                double prediction = predict(features);

                if (label * prediction <= 0) {
                    hasError = true;
                    for (int j = 0; j < numFeatures; j++) {
                        weights[j] += stepSizeDecrease * label * features[j];
                        accumulatedWeights[j] += weights[j];
                    }
                    bias += stepSizeDecrease * label;
                    accumulatedBias += bias;
                }
            }

            if (!hasError) {
                break;
            }

            if (averageParameters) {
                for (int j = 0; j < numFeatures; j++) {
                    weights[j] = accumulatedWeights[j] / (iteration + 1);
                }
                bias = accumulatedBias / (iteration + 1);
            }
        }

        return new PerceptronModel(weights, bias);
    }

    private double predict(double[] features) {
        double sum = bias;
        for (int i = 0; i < features.length; i++) {
            sum += weights[i] * features[i];
        }
        return sum >= 0 ? 1 : -1;
    }

    @Override
    public void displayTrainingProgress(int iteration) {
        System.out.println("Iteration: " + iteration + ", Weights: " + java.util.Arrays.toString(weights) + ", Bias: " + bias);
    }

    @Override
    public void displayTrainingStatistics() {
        System.out.println("Final Weights: " + java.util.Arrays.toString(weights));
        System.out.println("Final Bias: " + bias);
    }
}

