        if (method == null) {
            method = loadMethod(functionName);
        }
        if (method != null) {
            return method.invoke(null, args);
        }
        throw new NoSuchMethodException("Function " + functionName + " not found.");
    }

    public void processElement(String elementName, Object element) throws Exception {
        Method method = methodCache.get(elementName);
        if (method == null) {
            method = loadMethod(elementName);
        }
        if (method != null) {
            method.invoke(null, element);
        } else {
            throw new NoSuchMethodException("Element processing method " + elementName + " not found.");
        }
    }

    private Method loadMethod(String methodName) {
        try {
            Class<?> clazz = Class.forName("YourClassName"); // Replace with actual class name
            Method method = clazz.getMethod(methodName);
            methodCache.put(methodName, method);
