public class DbDataStore {
    private Connection connection;
    private String tableName;

    public DbDataStore(String dbUrl, String user, String password, String tableName) throws SQLException {
        this.connection = DriverManager.getConnection(dbUrl, user, password);
        this.tableName = tableName;
        checkSchema();
    }

    private void checkSchema() throws SQLException {
        // Implement schema check logic here
        Statement stmt = connection.createStatement();
        ResultSet rs = stmt.executeQuery("SELECT * FROM " + tableName + " LIMIT 1");
        // Handle schema validation
        rs.close();
        stmt.close();
    }

    public void addRecord(Map<String, Object> record) throws SQLException {
        StringBuilder sql = new StringBuilder("INSERT INTO " + tableName + " (");
        StringBuilder values = new StringBuilder("VALUES (");
        List<Object> params = new ArrayList<>();

        for (String key : record.keySet()) {
            sql.append(key).append(", ");
            values.append("?, ");
            params.add(record.get(key));
        }

        sql.setLength(sql.length() - 2); // Remove last comma
        values.setLength(values.length() - 2); // Remove last comma
        sql.append(") ").append(values).append(")");

        try (PreparedStatement pstmt = connection.prepareStatement(sql.toString())) {
            for (int i = 0; i < params.size(); i++) {
                pstmt.setObject(i + 1, params.get(i));
            }
            pstmt.executeUpdate();
        }
    }

    public Map<String, Object> getRecord(int id) throws SQLException {
        String sql = "SELECT * FROM " + tableName + " WHERE id = ?";
        try (PreparedStatement pstmt = connection.prepareStatement(sql)) {
            pstmt.setInt(1, id);
            ResultSet rs = pstmt.executeQuery();
            if (rs.next()) {
                Map<String, Object> record = new HashMap<>();
                ResultSetMetaData metaData = rs.getMetaData();
                for (int i = 1; i <= metaData.getColumnCount(); i++) {
                    record.put(metaData.getColumnName(i), rs.getObject(i));
                }
                return record;
            }
        }
        return null;
    }

    public void updateRecord(int id, Map<String, Object> updates) throws SQLException {
        StringBuilder sql = new StringBuilder("UPDATE " + tableName + " SET ");
        List<Object> params = new ArrayList<>();

        for (String key : updates.keySet()) {
            sql.append(key).append(" = ?, ");
            params.add(updates.get(key));
        }

        sql.setLength(sql.length() - 2); // Remove last comma
        sql.append(" WHERE id = ?");
        params.add(id);

        try (PreparedStatement pstmt = connection.prepareStatement(sql.toString())) {
            for (int i = 0; i < params.size(); i++) {
                pstmt.setObject(i + 1, params.get(i));
            }
            pstmt.executeUpdate();
        }
    }

    public void deleteRecord(int id) throws SQLException {
        String sql = "DELETE FROM " + tableName + " WHERE id = ?";
        try (PreparedStatement pstmt = connection.prepareStatement(sql)) {
            pstmt.setInt(1, id);
            pstmt.executeUpdate();
        }
    }

    public void close() throws SQLException {
        if (connection != null && !connection.isClosed()) {
            connection.close();
        }
    }
}

public class AntPathMatcher implements PatternMatcher {

    private String pathSeparator = "/";

    public boolean isPattern(String path) {
        return path.contains("*") || path.contains("?");
    }

    public boolean match(String pattern, String path) {
        String[] patternParts = pattern.split(pathSeparator);
        String[] pathParts = path.split(pathSeparator);
        return matchParts(patternParts, pathParts, 0, 0);
    }

    private boolean matchParts(String[] patternParts, String[] pathParts, int patternIndex, int pathIndex) {
        if (patternIndex == patternParts.length && pathIndex == pathParts.length) {
            return true;
        }
        if (patternIndex == patternParts.length || pathIndex == pathParts.length) {
            return false;
        }

        String patternPart = patternParts[patternIndex];
        if (patternPart.equals("*")) {
            for (int i = pathIndex; i <= pathParts.length; i++) {
                if (matchParts(patternParts, pathParts, patternIndex + 1, i)) {
                    return true;
                }
            }
        } else if (patternPart.equals("?")) {
            return matchParts(patternParts, pathParts, patternIndex + 1, pathIndex + 1);
        } else {
            if (patternPart.equals(pathParts[pathIndex])) {
                return matchParts(patternParts, pathParts, patternIndex + 1, pathIndex + 1);
            }
        }
        return false;
    }

    public String extractPathWithinPattern(String pattern, String path) {
        if (!match(pattern, path)) {
            return null;
        }
        String[] patternParts = pattern.split(pathSeparator);
        String[] pathParts = path.split(pathSeparator);
        StringBuilder extractedPath = new StringBuilder();
        for (int i = 0; i < pathParts.length; i++) {
            if (i < patternParts.length && !patternParts[i].equals("*")) {
                extractedPath.append(pathParts[i]).append(pathSeparator);
            }
        }
        return extractedPath.toString().isEmpty() ? extractedPath.toString() : extractedPath.substring(0, extractedPath.length() - 1);
    }

    public void setPathSeparator(String pathSeparator) {
        this.pathSeparator = pathSeparator;
    }
}

public class Struct {
    private final Map<String, Object> fields;
