    public Struct(Map<String, Class<?>> schema) {
        this.fields = new HashMap<>();
        this.schema = schema;
    }

    public void set(String fieldName, Object value) {
        if (!schema.containsKey(fieldName)) {
            throw new IllegalArgumentException("Field does not exist: " + fieldName);
        }
        if (value != null && !schema.get(fieldName).isInstance(value)) {
            throw new IllegalArgumentException("Invalid type for field: " + fieldName);
        }
        fields.put(fieldName, value);
    }

    public Object get(String fieldName) {
        return fields.get(fieldName);
    }

    public boolean hasField(String fieldName) {
        return fields.containsKey(fieldName);
    }

    public void validate() {
        for (String fieldName : schema.keySet()) {
            if (!fields.containsKey(fieldName)) {
                throw new IllegalStateException("Missing required field: " + fieldName);
            }
        }
    }

    public ByteBuffer serialize() {
        ByteBuffer buffer = ByteBuffer.allocate(1024); // Arbitrary size for example
        for (Map.Entry<String, Object> entry : fields.entrySet()) {
            // Serialization logic based on type
            // This is a placeholder for actual serialization logic
            buffer.put(entry.getKey().getBytes());
            if (entry.getValue() instanceof Integer) {
                buffer.putInt((Integer) entry.getValue());
            } else if (entry.getValue() instanceof String) {
                byte[] strBytes = ((String) entry.getValue()).getBytes();
                buffer.putInt(strBytes.length);
                buffer.put(strBytes);
            }
            // Add more types as needed
        }
        buffer.flip();
        return buffer;
    }

    @Override
    public String toString() {
        return "Struct{" + "fields=" + fields + '}';
    }

    @Override
    public int hashCode() {
        return Objects.hash(fields);
    }

    @Override
