public class XMLPersistenceManager extends AbstractPersistenceManager {
    private static final Logger logger = Logger.getLogger(XMLPersistenceManager.class.getName());
    private String storageDirectory;

    public XMLPersistenceManager(String storageDirectory) {
        this.storageDirectory = storageDirectory;
        initializePersistenceContext();
    }

    private void initializePersistenceContext() {
        File dir = new File(storageDirectory);
        if (!dir.exists()) {
            dir.mkdirs();
        }
    }

    public void storeNodeState(String nodeId, String state) {
        try (FileOutputStream fos = new FileOutputStream(getNodeFilePath(nodeId))) {
            fos.write(state.getBytes());
        } catch (IOException e) {
            logger.severe("Error storing node state: " + e.getMessage());
        }
    }

    public String loadNodeState(String nodeId) {
        try (FileInputStream fis = new FileInputStream(getNodeFilePath(nodeId))) {
            byte[] data = new byte[(int) new File(getNodeFilePath(nodeId)).length()];
            fis.read(data);
            return new String(data);
        } catch (IOException e) {
            logger.severe("Error loading node state: " + e.getMessage());
            return null;
        }
    }

    public void storePropertyState(String propertyId, String state) {
        try (FileOutputStream fos = new FileOutputStream(getPropertyFilePath(propertyId))) {
            fos.write(state.getBytes());
        } catch (IOException e) {
            logger.severe("Error storing property state: " + e.getMessage());
        }
    }

    public String loadPropertyState(String propertyId) {
        try (FileInputStream fis = new FileInputStream(getPropertyFilePath(propertyId))) {
            byte[] data = new byte[(int) new File(getPropertyFilePath(propertyId)).length()];
            fis.read(data);
            return new String(data);
        } catch (IOException e) {
            logger.severe("Error loading property state: " + e.getMessage());
            return null;
        }
    }

    public boolean nodeExists(String nodeId) {
        return new File(getNodeFilePath(nodeId)).exists();
    }

    public boolean propertyExists(String propertyId) {
        return new File(getPropertyFilePath(propertyId)).exists();
    }

    private String getNodeFilePath(String nodeId) {
        return storageDirectory + File.separator + nodeId + ".xml";
    }

    private String getPropertyFilePath(String propertyId) {
        return storageDirectory + File.separator + propertyId + ".xml";
    }
}

