    public ClusterAccessor(HelixDataAccessor dataAccessor) {
        this.dataAccessor = dataAccessor;
        this.cache = new ClusterCache();
    }

    public void createCluster(String clusterName, ClusterConfig config) {
        // Code smell: No validation of clusterName or config
        dataAccessor.createCluster(clusterName, config);
        initializeCluster(clusterName, config);
    }

    private void initializeCluster(String clusterName, ClusterConfig config) {
        // Code smell: Method does too much, could be split
        List<Resource> resources = config.getResources();
        for (Resource resource : resources) {
            dataAccessor.addResource(clusterName, resource);
        }
        List<Participant> participants = config.getParticipants();
        for (Participant participant : participants) {
            dataAccessor.addParticipant(clusterName, participant);
        }
    }

    public void updateCluster(String clusterName, ClusterDelta delta) {
        // Code smell: No error handling for invalid deltas
        dataAccessor.updateCluster(clusterName, delta);
    }

    public void dropCluster(String clusterName) {
        if (!canDropCluster(clusterName)) {
            // Code smell: Silent failure, should throw exception
            return;
        }
        dataAccessor.dropCluster(clusterName);
    }

    private boolean canDropCluster(String clusterName) {
        // Code smell: Logic could be more robust
        return dataAccessor.getActiveParticipants(clusterName).isEmpty();
    }

    public ClusterState readClusterState(String clusterName) {
        return cache.getClusterState(clusterName);
    }

    public void validateCluster(String clusterName) {
        // Code smell: No feedback mechanism for validation errors
        if (!dataAccessor.isClusterValid(clusterName)) {
            // Log error
        }
    }

    public void manageStateModelDefinitions(String clusterName, Map<String, StateModelDefinition> definitions) {
        for (Map.Entry<String, StateModelDefinition> entry : definitions.entrySet()) {
            dataAccessor.addStateModelDefinition(clusterName, entry.getKey(), entry.getValue());
        }
    }

    // Logging method for errors
    private void logError(String message) {
        // Code smell: No logging framework used
        System.err.println(message);
    }
}

