    void testIssueSingleToken() {
        TokenRequest request = new TokenRequest("user1", "password1", TokenType.BEARER);
        TokenResponse response = tokenIssueOperation.issueToken(request);

        assertNotNull(response);
        assertEquals(TokenType.BEARER, response.getTokenType());
        assertNotNull(response.getToken());
    }

    @Test
    void testIssueMultipleTokens() {
        TokenRequest request1 = new TokenRequest("user1", "password1", TokenType.BEARER);
        TokenRequest request2 = new TokenRequest("user2", "password2", TokenType.BEARER);

        TokenResponse response1 = tokenIssueOperation.issueToken(request1);
        TokenResponse response2 = tokenIssueOperation.issueToken(request2);

        assertNotNull(response1);
        assertNotNull(response2);
        assertNotEquals(response1.getToken(), response2.getToken());
    }

    @Test
    void testInvalidEndpoint() {
        serviceEndpoint = new ServiceEndpoint("http://invalid-endpoint");
        tokenIssueOperation = new TokenIssueOperation(tokenProvider, serviceEndpoint);

        TokenRequest request = new TokenRequest("user1", "password1", TokenType.BEARER);
        assertThrows(TokenIssueException.class, () -> {
            tokenIssueOperation.issueToken(request);
        });
    }

    @Test
    void testTokenLifetime() {
        TokenRequest request = new TokenRequest("user1", "password1", TokenType.BEARER);
        TokenResponse response = tokenIssueOperation.issueToken(request);

        assertNotNull(response);
        assertTrue(response.getLifetime() > 0);
    }

    @Test
    void testContextHandling() {
        TokenRequest request = new TokenRequest("user1", "password1", TokenType.BEARER);
        request.setContext("someContextData");

        TokenResponse response = tokenIssueOperation.issueToken(request);

        assertNotNull(response);
        assertEquals("someContextData", response.getContext());
    }
}

