public class NetworkConnectionServiceImpl implements NetworkConnectionService {
    private static final Logger logger = Logger.getLogger(NetworkConnectionServiceImpl.class.getName());
    private final ConcurrentHashMap<String, ConnectionFactory> connectionFactories = new ConcurrentHashMap<>();
    private final AtomicBoolean isClosed = new AtomicBoolean(false);
    private final NameResolver nameResolver;

    public NetworkConnectionServiceImpl(NameResolver nameResolver) {
        this.nameResolver = nameResolver;
    }

    @Override
    public void registerConnectionFactory(String name, ConnectionFactory factory) {
        if (isClosed.get()) {
            logger.warning("Attempt to register a connection factory after service is closed.");
            return;
        }
        connectionFactories.put(name, factory);
        logger.info("Registered connection factory: " + name);
        processRegistrationEvent(name);
    }

    @Override
    public void unregisterConnectionFactory(String name) {
        if (isClosed.get()) {
            logger.warning("Attempt to unregister a connection factory after service is closed.");
            return;
        }
        connectionFactories.remove(name);
        logger.info("Unregistered connection factory: " + name);
    }

    @Override
    public void openConnection(String name) {
        if (isClosed.get()) {
            logger.warning("Attempt to open a connection after service is closed.");
            return;
        }
        ConnectionFactory factory = connectionFactories.get(name);
        if (factory != null) {
            factory.open();
            logger.info("Opened connection for: " + name);
        } else {
            logger.warning("No connection factory found for: " + name);
        }
    }

    @Override
    public void close() {
        if (isClosed.compareAndSet(false, true)) {
            connectionFactories.clear();
            logger.info("NetworkConnectionServiceImpl closed and resources released.");
        }
    }

    private void processRegistrationEvent(String name) {
        // Placeholder for event processing logic
        logger.info("Processing registration event for: " + name);
    }
}

