public class TestRoutingTable {

    private RoutingTableProvider routingTableProvider;
    private HelixManager mockHelixManager;
    private NotificationContext mockNotificationContext;

    @Before
    public void setUp() {
        mockHelixManager = Mockito.mock(HelixManager.class);
        mockNotificationContext = new NotificationContext();
        routingTableProvider = new RoutingTableProvider(mockHelixManager);
    }

    @Test
    public void testNullView() {
        routingTableProvider.onExternalViewChange(null);
        assertTrue(routingTableProvider.getInstances().isEmpty());
    }

    @Test
    public void testEmptyView() {
        ExternalView emptyView = new ExternalView();
        routingTableProvider.onExternalViewChange(emptyView);
        assertTrue(routingTableProvider.getInstances().isEmpty());
    }

    @Test
    public void testAddInstance() {
        ExternalView view = new ExternalView();
        view.addInstance("instance1", InstanceState.MASTER);
        routingTableProvider.onExternalViewChange(view);
        assertEquals(1, routingTableProvider.getInstances().size());
        assertTrue(routingTableProvider.getInstances().contains("instance1"));
    }

    @Test
    public void testRetrieveMasterInstances() {
        ExternalView view = new ExternalView();
        view.addInstance("instance1", InstanceState.MASTER);
        view.addInstance("instance2", InstanceState.SLAVE);
        routingTableProvider.onExternalViewChange(view);
        assertEquals(1, routingTableProvider.getMasterInstances().size());
        assertTrue(routingTableProvider.getMasterInstances().contains("instance1"));
    }

    @Test
    public void testMultiThreadedAccess() throws InterruptedException {
        Runnable task = () -> {
            ExternalView view = new ExternalView();
            view.addInstance("instance" + Thread.currentThread().getId(), InstanceState.MASTER);
            routingTableProvider.onExternalViewChange(view);
        };

        Thread thread1 = new Thread(task);
        Thread thread2 = new Thread(task);
        thread1.start();
        thread2.start();
        thread1.join();
        thread2.join();

        assertTrue(routingTableProvider.getInstances().size() >= 2);
    }

    @Test
    public void testStateUnitGroupDeletion() {
        ExternalView view = new ExternalView();
        view.addInstance("instance1", InstanceState.MASTER);
        routingTableProvider.onExternalViewChange(view);
        routingTableProvider.deleteStateUnitGroup("instance1");
        assertFalse(routingTableProvider.getInstances().contains("instance1"));
    }
}

