public class SchemaBuilder {
    private static final Logger logger = LoggerFactory.getLogger(SchemaBuilder.class);
    private ServerRuntime runtime;

    public SchemaBuilder(ServerRuntime runtime) {
        this.runtime = runtime;
    }

    public void rebuildSchema() {
        try {
            if (shouldSkipSchemaCreation()) {
                logger.info("Skipping schema creation based on system properties.");
                return;
            }
            DataMap dataMap = runtime.getDataMap("myDataMap");
            List<ObjEntity> entities = dataMap.getObjEntities();
            for (ObjEntity entity : entities) {
                if (isSupportedEntity(entity)) {
                    createTable(entity);
                }
            }
        } catch (Exception e) {
            logger.error("Error during schema rebuild: ", e);
        }
    }

    private boolean shouldSkipSchemaCreation() {
        return Boolean.getBoolean("skip.schema.creation");
    }

    private boolean isSupportedEntity(ObjEntity entity) {
        // Code smell: This method could be more descriptive or could use a better naming convention
        return entity.getDbEntity() != null && entity.getDbEntity().getTableType() == TableType.TABLE;
    }

    private void createTable(ObjEntity entity) {
        try {
            Table table = entity.getDbEntity().getTable();
            String sql = generateCreateTableSQL(table);
            logger.info("Executing SQL: {}", sql);
            // Execute SQL (pseudo-code)
            // executeSQL(sql);
        } catch (Exception e) {
            logger.error("Failed to create table for entity: " + entity.getName(), e);
        }
    }

    private String generateCreateTableSQL(Table table) {
        // Code smell: This method could be more modular and handle different table types
        StringBuilder sql = new StringBuilder("CREATE TABLE " + table.getName() + " (");
        // Add columns (pseudo-code)
        // for (Column column : table.getColumns()) {
