public class Asn1FlagsTest {

    public static final int FLAG_ONE = 0b0001;
    public static final int FLAG_TWO = 0b0010;
    public static final int FLAG_THREE = 0b0100;
    public static final int FLAG_FOUR = 0b1000;

    public enum TestEnum {
        FLAG_ONE(FLAG_ONE),
        FLAG_TWO(FLAG_TWO),
        FLAG_THREE(FLAG_THREE),
        FLAG_FOUR(FLAG_FOUR);

        private final int value;

        TestEnum(int value) {
            this.value = value;
        }

        public int getValue() {
            return value;
        }
    }

    private int flags;

    public void setFlag(int flag) {
        flags |= flag;
    }

    public void clearFlag(int flag) {
        flags &= ~flag;
    }

    public boolean isFlagSet(int flag) {
        return (flags & flag) != 0;
    }

    public void setFlag(TestEnum flag) {
        setFlag(flag.getValue());
    }

    public void clearFlag(TestEnum flag) {
        clearFlag(flag.getValue());
    }

    public boolean isFlagSet(TestEnum flag) {
        return isFlagSet(flag.getValue());
    }

    @Test
    public void testSetFlag() {
        setFlag(FLAG_ONE);
        assertTrue(isFlagSet(FLAG_ONE));
        setFlag(FLAG_TWO);
        assertTrue(isFlagSet(FLAG_TWO));
    }

    @Test
    public void testClearFlag() {
        setFlag(FLAG_ONE);
        clearFlag(FLAG_ONE);
        assertFalse(isFlagSet(FLAG_ONE));
    }

    @Test
    public void testIsFlagSet() {
        setFlag(FLAG_THREE);
        assertTrue(isFlagSet(FLAG_THREE));
        assertFalse(isFlagSet(FLAG_FOUR));
    }

    @Test
    public void testSetFlagEnum() {
        setFlag(TestEnum.FLAG_FOUR);
        assertTrue(isFlagSet(TestEnum.FLAG_FOUR));
    }

    @Test
    public void testClearFlagEnum() {
        setFlag(TestEnum.FLAG_FOUR);
        clearFlag(TestEnum.FLAG_FOUR);
        assertFalse(isFlagSet(TestEnum.FLAG_FOUR));
    }

    @Test
    public void testByteArrayToFlags() {
        byte[] byteArray = new byte[]{0b0000_0001, 0b0000_0010};
        int flagValue = byteArray[0] | (byteArray[1] << 8);
        setFlag(flagValue);
        assertTrue(isFlagSet(FLAG_ONE));
        assertTrue(isFlagSet(FLAG_TWO));
    }
}

public class Token implements Cloneable {
    private String text;
    private String type;
    private int startOffset;
    private int endOffset;
    private int length;
    private boolean isFlagged;
    private Payload payload;

    public Token(String text) {
        this.text = text;
        this.startOffset = 0;
        this.endOffset = text.length();
        this.length = text.length();
        this.type = "default";
        this.isFlagged = false;
    }

    public Token(String text, String type, int startOffset, int endOffset) {
        this.text = text;
        this.type = type;
        this.startOffset = startOffset;
        this.endOffset = endOffset;
        this.length = endOffset - startOffset;
        this.isFlagged = false;
    }

    public Token(String text, String type, int startOffset, int endOffset, boolean isFlagged) {
        this.text = text;
        this.type = type;
        this.startOffset = startOffset;
        this.endOffset = endOffset;
        this.length = endOffset - startOffset;
        this.isFlagged = isFlagged;
    }

    public String getText() {
        return text;
    }

    public void setText(String text) {
        this.text = text;
        this.length = text.length();
        this.endOffset = startOffset + length;
    }

    public String getType() {
        return type;
    }

    public void setType(String type) {
        this.type = type;
    }

    public int getStartOffset() {
        return startOffset;
    }

    public void setStartOffset(int startOffset) {
        this.startOffset = startOffset;
        this.length = endOffset - startOffset;
    }

    public int getEndOffset() {
        return endOffset;
    }

    public void setEndOffset(int endOffset) {
        this.endOffset = endOffset;
        this.length = endOffset - startOffset;
    }

    public int getLength() {
        return length;
    }

    public boolean isFlagged() {
        return isFlagged;
    }

    public void setFlagged(boolean flagged) {
        isFlagged = flagged;
    }

    public Payload getPayload() {
        return payload;
    }

    public void setPayload(Payload payload) {
        this.payload = payload;
    }

    @Override
    public Token clone() {
        try {
            return (Token) super.clone();
        } catch (CloneNotSupportedException e) {
            throw new RuntimeException("Clone not supported", e);
        }
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Token)) return false;
        Token other = (Token) obj;
        return text.equals(other.text) && type.equals(other.type) &&
               startOffset == other.startOffset && endOffset == other.endOffset &&
               isFlagged == other.isFlagged && (payload != null ? payload.equals(other.payload) : other.payload == null);
    }

    @Override
    public String toString() {
        return "Token{" +
                "text='" + text + '\'' +
                ", type='" + type + '\'' +
                ", startOffset=" + startOffset +
                ", endOffset=" + endOffset +
                ", length=" + length +
                ", isFlagged=" + isFlagged +
                ", payload=" + payload +
                '}';
    }
}

