        }
    }

    @Override
    public void writeUTF(String value) throws JMSException {
        ensureOutputStream();
        try {
            objectOutputStream.writeUTF(value);
        } catch (IOException e) {
            throw new JMSException("Error writing UTF: " + e.getMessage());
        }
    }

    @Override
    public void clearBody() throws JMSException {
        body = new byte[0];
        bodyLength = 0;
        closeStreams();
    }

    @Override
    public int getBodyLength() throws JMSException {
        return bodyLength;
    }

    private void ensureOutputStream() throws JMSException {
        if (objectOutputStream == null) {
            try {
                outputStream = new ByteArrayOutputStream();
                objectOutputStream = new ObjectOutputStream(outputStream);
            } catch (IOException e) {
                throw new JMSException("Error initializing output stream: " + e.getMessage());
            }
        }
    }

    private void closeStreams() {
        try {
            if (objectOutputStream != null) {
                objectOutputStream.close();
                objectOutputStream = null;
            }
            if (outputStream != null) {
                body = outputStream.toByteArray();
                bodyLength = body.length;
                outputStream.close();
                outputStream = null;
            }
        } catch (IOException e) {
            // Log error but do not throw
        }
    }

    // Additional methods for reading from the byte array would go here
}

