public class RequestHandler extends HttpServlet {
    private static final Logger logger = Logger.getLogger(RequestHandler.class.getName());
    private Map<String, String> requestMappings = new HashMap<>();
    private Set<String> securedPaths = new HashSet<>();

    @Override
    public void init() throws ServletException {
        loadConfiguration();
    }

    private void loadConfiguration() {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document doc = builder.parse(getServletContext().getResourceAsStream("/WEB-INF/config.xml"));
            NodeList mappings = doc.getElementsByTagName("mapping");
            for (int i = 0; i < mappings.getLength(); i++) {
                Element mapping = (Element) mappings.item(i);
                String path = mapping.getAttribute("path");
                String handler = mapping.getAttribute("handler");
                requestMappings.put(path, handler);
            }
            NodeList secured = doc.getElementsByTagName("secured");
            for (int i = 0; i < secured.getLength(); i++) {
                securedPaths.add(secured.item(i).getTextContent());
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error loading configuration", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        processRequest(request, response);
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        processRequest(request, response);
    }

    private void processRequest(HttpServletRequest request, HttpServletResponse response) throws IOException, ServletException {
        String path = request.getRequestURI();
        if (securedPaths.contains(path) && !isUserAuthenticated(request)) {
            response.sendRedirect("/login");
            return;
        }

        String handler = requestMappings.get(path);
        if (handler != null) {
            try {
                Class<?> clazz = Class.forName(handler);
                HttpServlet servlet = (HttpServlet) clazz.getDeclaredConstructor().newInstance();
                servlet.service(request, response);
                trackVisit(path);
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Error processing request", e);
                response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
            }
        } else {
            response.sendError(HttpServletResponse.SC_NOT_FOUND);
        }
    }

    private boolean isUserAuthenticated(HttpServletRequest request) {
        HttpSession session = request.getSession(false);
        return session != null && session.getAttribute("user") != null;
    }

    private void trackVisit(String path) {
        // Logic to track server hits and visits
        logger.info("Visited path: " + path);
    }

    public String createUrl(String base, Map<String, String> params) {
        StringBuilder url = new StringBuilder(base);
        if (!params.isEmpty()) {
            url.append("?");
            params.forEach((key, value) -> url.append(key).append("=").append(value).append("&"));
            url.setLength(url.length() - 1); // Remove last '&'
        }
        return url.toString();
    }

    public Map<String, String> parseQueryString(String query) {
        Map<String, String> params = new HashMap<>();
        String[] pairs = query.split("&");
        for (String pair : pairs) {
            String[] keyValue = pair.split("=");
            if (keyValue.length == 2) {
                params.put(keyValue[0], keyValue[1]);
            }
        }
        return params;
    }
}

