public class RangeToken extends Token implements Serializable {
    private List<int[]> ranges;

    public RangeToken() {
        this.ranges = new ArrayList<>();
    }

    public void addRange(int start, int end) {
        ranges.add(new int[]{start, end});
        compactRanges();
    }

    public void compactRanges() {
        Collections.sort(ranges, (a, b) -> Integer.compare(a[0], b[0]));
        List<int[]> compacted = new ArrayList<>();
        for (int[] range : ranges) {
            if (compacted.isEmpty() || compacted.get(compacted.size() - 1)[1] < range[0]) {
                compacted.add(range);
            } else {
                compacted.get(compacted.size() - 1)[1] = Math.max(compacted.get(compacted.size() - 1)[1], range[1]);
            }
        }
        ranges = compacted;
    }

    public boolean contains(int value) {
        for (int[] range : ranges) {
            if (value >= range[0] && value <= range[1]) {
                return true;
            }
        }
        return false;
    }

    public void mergeRanges() {
        compactRanges();
    }

    public void subtractRange(int start, int end) {
        List<int[]> newRanges = new ArrayList<>();
        for (int[] range : ranges) {
            if (end < range[0] || start > range[1]) {
                newRanges.add(range);
            } else {
                if (start > range[0]) {
                    newRanges.add(new int[]{range[0], start - 1});
                }
                if (end < range[1]) {
                    newRanges.add(new int[]{end + 1, range[1]});
                }
            }
        }
        ranges = newRanges;
    }

    public List<int[]> intersectWith(RangeToken other) {
        List<int[]> intersections = new ArrayList<>();
        for (int[] range1 : ranges) {
            for (int[] range2 : other.ranges) {
                int start = Math.max(range1[0], range2[0]);
                int end = Math.min(range1[1], range2[1]);
                if (start <= end) {
                    intersections.add(new int[]{start, end});
                }
            }
        }
        return intersections;
    }

    public RangeToken complement() {
        RangeToken complement = new RangeToken();
        int lastEnd = Integer.MIN_VALUE;
        for (int[] range : ranges) {
            if (lastEnd + 1 < range[0]) {
                complement.addRange(lastEnd + 1, range[0] - 1);
            }
            lastEnd = range[1];
        }
        if (lastEnd < Integer.MAX_VALUE) {
            complement.addRange(lastEnd + 1, Integer.MAX_VALUE);
        }
        return complement;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (int[] range : ranges) {
            sb.append("[").append(range[0]).append(", ").append(range[1]).append("] ");
        }
        return sb.toString().trim();
    }
}

