public class Tika {
    private Detector detector;
    private Parser parser;
    private Translator translator;
    private int maxStringLength = Integer.MAX_VALUE;
    private static final String VERSION = "1.0";

    public Tika() {
        this.detector = new DefaultDetector();
        this.parser = new DefaultParser();
        this.translator = new DefaultTranslator();
    }

    public Tika(Detector detector, Parser parser, Translator translator) {
        this.detector = detector;
        this.parser = parser;
        this.translator = translator;
    }

    public String detect(InputStream input) {
        return detector.detect(input);
    }

    public String detect(File file) {
        return detector.detect(file);
    }

    public String detect(URL url) {
        return detector.detect(url);
    }

    public String detect(byte[] data) {
        return detector.detect(data);
    }

    public Reader parse(InputStream input) throws Exception {
        return parser.parse(input);
    }

    public String parseToString(InputStream input) throws Exception {
        Reader reader = parse(input);
        return readToString(reader);
    }

    public String parseToString(InputStream input, int lengthLimit) throws Exception {
        Reader reader = parse(input);
        return readToString(reader, lengthLimit);
    }

    public String translate(String text, String targetLanguage) {
        return translator.translate(text, targetLanguage);
    }

    public void setMaxStringLength(int length) {
        this.maxStringLength = length;
    }

    public int getMaxStringLength() {
        return maxStringLength;
    }

    public String getVersion() {
        return VERSION;
    }

    private String readToString(Reader reader) throws IOException {
        StringBuilder sb = new StringBuilder();
        char[] buffer = new char[1024];
        int bytesRead;
        while ((bytesRead = reader.read(buffer)) != -1) {
            sb.append(buffer, 0, bytesRead);
            if (sb.length() > maxStringLength) {
                break;
            }
        }
        return sb.toString();
    }

    private String readToString(Reader reader, int lengthLimit) throws IOException {
        StringBuilder sb = new StringBuilder();
        char[] buffer = new char[1024];
        int bytesRead;
        while ((bytesRead = reader.read(buffer)) != -1) {
            sb.append(buffer, 0, bytesRead);
            if (sb.length() > lengthLimit) {
                break;
            }
        }
        return sb.toString();
    }
}

public final class ConfigurationGenerator extends ServiceableGenerator {
    private AuthenticationManager authManager;
    private XPathProcessor xpathProcessor;
    private Map<String, String> userRoles;

    public ConfigurationGenerator(AuthenticationManager authManager, XPathProcessor xpathProcessor) {
        this.authManager = authManager;
        this.xpathProcessor = xpathProcessor;
        this.userRoles = new HashMap<>();
    }

    public void addUser(String username, String role) {
        userRoles.put(username, role);
        authManager.addUser(username, role);
    }

    public void deleteUser(String username) {
        userRoles.remove(username);
        authManager.deleteUser(username);
    }

    public void changeUserRole(String username, String newRole) {
        if (userRoles.containsKey(username)) {
            userRoles.put(username, newRole);
            authManager.changeUserRole(username, newRole);
        }
    }

    public String generateXMLConfiguration() {
        try {
            DocumentBuilderFactory docFactory = DocumentBuilderFactory.newInstance();
            DocumentBuilder docBuilder = docFactory.newDocumentBuilder();
            Document doc = docBuilder.newDocument();

            Element rootElement = doc.createElement("Configuration");
            doc.appendChild(rootElement);

            for (Map.Entry<String, String> entry : userRoles.entrySet()) {
                Element userElement = doc.createElement("User");
                userElement.setAttribute("username", entry.getKey());
                userElement.setAttribute("role", entry.getValue());
                rootElement.appendChild(userElement);
            }

            TransformerFactory transformerFactory = TransformerFactory.newInstance();
            Transformer transformer = transformerFactory.newTransformer();
            transformer.setOutputProperty(OutputKeys.INDENT, "yes");
            DOMSource source = new DOMSource(doc);
            StreamResult result = new StreamResult(new StringWriter());
            transformer.transform(source, result);
            return result.getWriter().toString();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

