public class TestCapacityByteArrayOutputStream {
    private CapacityByteArrayOutputStream stream;

    @Before
    public void setUp() {
        stream = new CapacityByteArrayOutputStream(10);
    }

    @Test
    public void testWriteSingleByte() {
        stream.write(65); // ASCII for 'A'
        assertArrayEquals(new byte[]{65}, stream.toByteArray());
    }

    @Test
    public void testWriteByteArray() {
        byte[] bytes = {66, 67, 68}; // ASCII for 'B', 'C', 'D'
        stream.write(bytes);
        assertArrayEquals(new byte[]{66, 67, 68}, stream.toByteArray());
    }

    @Test
    public void testWriteLargerArray() {
        byte[] bytes = new byte[15]; // Larger than initial capacity
        for (int i = 0; i < 15; i++) {
            bytes[i] = (byte) (65 + i); // ASCII 'A' to 'O'
        }
        stream.write(bytes);
        assertArrayEquals(bytes, stream.toByteArray());
    }

    @Test
    public void testResetStream() {
        stream.write(65);
        stream.reset();
        assertArrayEquals(new byte[]{}, stream.toByteArray());
    }

    @Test
    public void testReplaceBytes() {
        stream.write(new byte[]{65, 66, 67}); // 'A', 'B', 'C'
        stream.replace(1, (byte) 90); // Replace 'B' with 'Z'
        assertArrayEquals(new byte[]{65, 90, 67}, stream.toByteArray());
    }

    @Test
    public void testStreamSize() {
        stream.write(new byte[]{65, 66, 67});
        assertEquals(3, stream.size());
    }

    @Test
    public void testContentIntegrityAfterReset() {
        stream.write(new byte[]{65, 66, 67});
        stream.reset();
        stream.write(new byte[]{68, 69}); // 'D', 'E'
        assertArrayEquals(new byte[]{68, 69}, stream.toByteArray());
    }
}

