public class MapUtils {

    public static <K, V> V getValue(Map<K, V> map, K key, V defaultValue) {
        return map.getOrDefault(key, defaultValue);
    }

    public static String getString(Map<?, ?> map, Object key, String defaultValue) {
        return (String) getValue(map, key, defaultValue);
    }

    public static Boolean getBoolean(Map<?, ?> map, Object key, Boolean defaultValue) {
        return (Boolean) getValue(map, key, defaultValue);
    }

    public static Number getNumber(Map<?, ?> map, Object key, Number defaultValue) {
        return (Number) getValue(map, key, defaultValue);
    }

    public static Byte getByte(Map<?, ?> map, Object key, Byte defaultValue) {
        return (Byte) getValue(map, key, defaultValue);
    }

    public static Short getShort(Map<?, ?> map, Object key, Short defaultValue) {
        return (Short) getValue(map, key, defaultValue);
    }

    public static Integer getInteger(Map<?, ?> map, Object key, Integer defaultValue) {
        return (Integer) getValue(map, key, defaultValue);
    }

    public static Long getLong(Map<?, ?> map, Object key, Long defaultValue) {
        return (Long) getValue(map, key, defaultValue);
    }

    public static Float getFloat(Map<?, ?> map, Object key, Float defaultValue) {
        return (Float) getValue(map, key, defaultValue);
    }

    public static Double getDouble(Map<?, ?> map, Object key, Double defaultValue) {
        return (Double) getValue(map, key, defaultValue);
    }

    public static Properties toProperties(Map<?, ?> map) {
        Properties properties = new Properties();
        for (Map.Entry<?, ?> entry : map.entrySet()) {
            properties.put(entry.getKey().toString(), entry.getValue().toString());
        }
        return properties;
    }

    public static void printMap(Map<?, ?> map) {
        for (Map.Entry<?, ?> entry : map.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }

    public static <K, V> Map<V, K> invertMap(Map<K, V> map) {
        Map<V, K> invertedMap = new HashMap<>();
        for (Map.Entry<K, V> entry : map.entrySet()) {
            invertedMap.put(entry.getValue(), entry.getKey());
        }
        return invertedMap;
    }

    public static <K, V> void safeAdd(Map<K, V> map, K key, V value) {
        if (!map.containsKey(key)) {
            map.put(key, value);
        }
    }

    public static <K, V> Map<K, V> synchronizedMap(Map<K, V> map) {
        return Collections.synchronizedMap(map);
    }

    public static <K, V> Map<K, V> unmodifiableMap(Map<K, V> map) {
        return Collections.unmodifiableMap(map);
    }

    public static <K, V> Map<K, V> transformedMap(Map<K, V> map, Function<V, V> transformer) {
        return map.entrySet().stream()
                .collect(Collectors.toMap(Map.Entry::getKey, e -> transformer.apply(e.getValue())));
    }

    public static <K, V> Map<K, V> predicatedMap(Map<K, V> map, Predicate<V> predicate) {
        return map.entrySet().stream()
                .filter(e -> predicate.test(e.getValue()))
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
    }

    public static boolean isEmpty(Map<?, ?> map) {
        return map == null || map.isEmpty();
    }

    public static <K, V> void populateMap(Map<K, V> map, Collection<K> keys, Function<K, V> valueProvider) {
        for (K key : keys) {
            map.put(key, valueProvider.apply(key));
        }
    }

    public static int size(Map<?, ?> map) {
        return map == null ? 0 : map.size();
    }

    @Deprecated
    public static <K, V> void addMultiValue(Map<K, List<V>> map, K key, V value) {
        map.computeIfAbsent(key, k -> new ArrayList<>()).add(value);
    }

    @Deprecated
    public static <K, V> List<V> getMultiValues(Map<K, List<V>> map, K key) {
        return map.getOrDefault(key, Collections.emptyList());
    }
}

