        } catch (IndexOutOfBoundsException e) {
            // expected
        }
    }

    @Test
    public void testTuple4Equality() {
        Tuple4<Integer, String, Double, Boolean> tuple1 = new Tuple4<>(1, "test", 3.14, true);
        Tuple4<Integer, String, Double, Boolean> tuple2 = new Tuple4<>(1, "test", 3.14, true);
        Tuple4<Integer, String, Double, Boolean> tuple3 = new Tuple4<>(1, "test", 3.14, false);
        assertTrue(tuple1.equals(tuple2));
        assertFalse(tuple1.equals(tuple3));
    }

    @Test
    public void testTupleNFunctionality() {
        TupleN<Object> tuple = new TupleN<>(1, "test", 3.14, true);
        assertEquals(4, tuple.size());
        assertEquals(1, tuple.get(0));
        assertEquals("test", tuple.get(1));
        assertEquals(3.14, tuple.get(2));
        assertEquals(true, tuple.get(3));
        try {
            tuple.get(4);
            fail("Expected IndexOutOfBoundsException");
        } catch (IndexOutOfBoundsException e) {
            // expected
        }
    }

    @Test
    public void testTupleNEquality() {
        TupleN<Object> tuple1 = new TupleN<>(1, "test", 3.14, true);
        TupleN<Object> tuple2 = new TupleN<>(1, "test", 3.14, true);
        TupleN<Object> tuple3 = new TupleN<>(1, "test", 3.14, false);
        assertTrue(tuple1.equals(tuple2));
        assertFalse(tuple1.equals(tuple3));
    }

    @Test
    public void testTupleFactory() {
        Tuple2<Integer, String> pair = TupleFactory.createPair(1, "test");
        assertEquals(2, pair.size());
        assertEquals(Integer.valueOf(1), pair.get(0));
        assertEquals("test", pair.get(1));

        Tuple3<Integer, String, Double> tuple3 = TupleFactory.createTuple3(1, "test", 3.14);
        assertEquals(3, tuple3.size());

        Tuple4<Integer, String, Double, Boolean> tuple4 = TupleFactory.createTuple4(1, "test", 3.14, true);
        assertEquals(4, tuple4.size());

        TupleN<Object> tupleN = TupleFactory.createTupleN(1, "test", 3.14, true);
        assertEquals(4, tupleN.size());
    }
