public class CatalogProtocolHandler implements CatalogProtocolService.BlockingInterface {
    private static final Logger logger = Logger.getLogger(CatalogProtocolHandler.class.getName());
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    private List<String> databases = new ArrayList<>();
    private List<String> tablespaces = new ArrayList<>();
    private List<String> tables = new ArrayList<>();
    private List<String> indexes = new ArrayList<>();
    private List<String> functions = new ArrayList<>();

    @Override
    public void createTablespace(String name) {
        lock.writeLock().lock();
        try {
            if (!tablespaces.contains(name)) {
                tablespaces.add(name);
                logger.info("Created tablespace: " + name);
            } else {
                logger.warning("Tablespace already exists: " + name);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public void dropTablespace(String name) {
        lock.writeLock().lock();
        try {
            if (tablespaces.remove(name)) {
                logger.info("Dropped tablespace: " + name);
            } else {
                logger.warning("Tablespace not found: " + name);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public boolean tablespaceExists(String name) {
        lock.readLock().lock();
        try {
            return tablespaces.contains(name);
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public List<String> getAllTablespaces() {
        lock.readLock().lock();
        try {
            return new ArrayList<>(tablespaces);
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public void createDatabase(String name) {
        lock.writeLock().lock();
        try {
            if (!databases.contains(name)) {
                databases.add(name);
                logger.info("Created database: " + name);
            } else {
                logger.warning("Database already exists: " + name);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public void dropDatabase(String name) {
        lock.writeLock().lock();
        try {
            if (databases.remove(name)) {
                logger.info("Dropped database: " + name);
            } else {
                logger.warning("Database not found: " + name);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public boolean databaseExists(String name) {
        lock.readLock().lock();
        try {
            return databases.contains(name);
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public List<String> getAllDatabases() {
        lock.readLock().lock();
        try {
            return new ArrayList<>(databases);
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public void createTable(String dbName, String tableName) {
        lock.writeLock().lock();
        try {
            if (databaseExists(dbName) && !tables.contains(tableName)) {
                tables.add(tableName);
                logger.info("Created table: " + tableName + " in database: " + dbName);
            } else {
                logger.warning("Table already exists or database not found: " + tableName);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public void dropTable(String dbName, String tableName) {
        lock.writeLock().lock();
        try {
            if (tables.remove(tableName)) {
                logger.info("Dropped table: " + tableName + " from database: " + dbName);
            } else {
                logger.warning("Table not found: " + tableName);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public boolean tableExists(String dbName, String tableName) {
        lock.readLock().lock();
        try {
            return tables.contains(tableName);
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public List<String> getAllTables(String dbName) {
        lock.readLock().lock();
        try {
            return new ArrayList<>(tables);
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public void createIndex(String tableName, String indexName) {
        lock.writeLock().lock();
        try {
            if (!indexes.contains(indexName)) {
                indexes.add(indexName);
                logger.info("Created index: " + indexName + " on table: " + tableName);
            } else {
                logger.warning("Index already exists: " + indexName);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public void dropIndex(String indexName) {
        lock.writeLock().lock();
        try {
            if (indexes.remove(indexName)) {
                logger.info("Dropped index: " + indexName);
            } else {
                logger.warning("Index not found: " + indexName);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public boolean indexExists(String indexName) {
        lock.readLock().lock();
        try {
            return indexes.contains(indexName);
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public List<String> getIndexInfo(String indexName) {
        lock.readLock().lock();
        try {
            if (indexes.contains(indexName)) {
                return List.of("Index Info for: " + indexName);
            } else {
                logger.warning("Index not found: " + indexName);
                return new ArrayList<>();
            }
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public void createFunction(String name) {
        lock.writeLock().lock();
        try {
            if (!functions.contains(name)) {
                functions.add(name);
                logger.info("Created function: " + name);
            } else {
                logger.warning("Function already exists: " + name);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public void dropFunction(String name) {
        lock.writeLock().lock();
        try {
            if (functions.remove(name)) {
                logger.info("Dropped function: " + name);
            } else {
                logger.warning("Function not found: " + name);
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public boolean functionExists(String name) {
        lock.readLock().lock();
        try {
            return functions.contains(name);
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public List<String> getFunctionMetadata(String name) {
        lock.readLock().lock();
        try {
            if (functions.contains(name)) {
                return List.of("Function Metadata for: " + name);
            } else {
                logger.warning("Function not found: " + name);
                return new ArrayList<>();
            }
        } finally {
            lock.readLock().unlock();
        }
    }
}

public abstract class AbstractRuleElement implements RuleElement {
    protected List<Condition> conditions;
    protected List<Action> actions;
    protected int quantifier;
    protected RuleBlock parentBlock;
    protected RuleContainer container;
    protected List<InlinedRuleBlock> inlinedConditionBlocks;
    protected List<InlinedRuleBlock> inlinedActionBlocks;
    protected MatchingContext matchingContext;
    protected boolean earlyExit;

    public AbstractRuleElement() {
        // Initialization logic
    }

    public abstract boolean evaluateMatches();

    public void applyActions() {
        for (Action action : actions) {
            action.execute();
        }
    }

    public void processInlinedRules() {
        for (InlinedRuleBlock inlinedBlock : inlinedConditionBlocks) {
            inlinedBlock.evaluate();
        }
        for (InlinedRuleBlock inlinedBlock : inlinedActionBlocks) {
            inlinedBlock.execute();
        }
    }

    public void setConditions(List<Condition> conditions) {
        this.conditions = conditions;
    }

    public List<Condition> getConditions() {
        return conditions;
    }

    public void setActions(List<Action> actions) {
