        return quantifier;
    }

    public void setParentBlock(RuleBlock parentBlock) {
        this.parentBlock = parentBlock;
    }

    public RuleBlock getParentBlock() {
        return parentBlock;
    }

    public void setContainer(RuleContainer container) {
        this.container = container;
    }

    public RuleContainer getContainer() {
        return container;
    }

    public void setInlinedConditionBlocks(List<InlinedRuleBlock> inlinedConditionBlocks) {
        this.inlinedConditionBlocks = inlinedConditionBlocks;
    }

    public List<InlinedRuleBlock> getInlinedConditionBlocks() {
        return inlinedConditionBlocks;
    }

    public void setInlinedActionBlocks(List<InlinedRuleBlock> inlinedActionBlocks) {
        this.inlinedActionBlocks = inlinedActionBlocks;
    }

    public List<InlinedRuleBlock> getInlinedActionBlocks() {
        return inlinedActionBlocks;
    }

    public void setMatchingContext(MatchingContext matchingContext) {
        this.matchingContext = matchingContext;
    }

    public MatchingContext getMatchingContext() {
        return matchingContext;
    }

    public void setEarlyExit(boolean earlyExit) {
        this.earlyExit = earlyExit;
    }

    public boolean isEarlyExit() {
        return earlyExit;
    }
}

@Path("/webhdfs/v1")
public class NamenodeWebHdfsMethods {

    private Configuration conf;
    private FileSystem fs;

    public NamenodeWebHdfsMethods() {
        conf = new Configuration();
        try {
            fs = FileSystem.get(conf);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    @POST
    @Path("/create/{path}")
    public Response createFile(@PathParam("path") String path) {
        try {
            Path filePath = new Path(path);
            if (fs.createNewFile(filePath)) {
                return Response.status(Response.Status.CREATED).entity("File created").build();
            } else {
                return Response.status(Response.Status.CONFLICT).entity("File already exists").build();
            }
        } catch (IOException e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity(e.getMessage()).build();
        }
    }

    @GET
    @Path("/read/{path}")
    public Response readFile(@PathParam("path") String path) {
        try {
            Path filePath = new Path(path);
            if (fs.exists(filePath)) {
                return Response.ok(fs.open(filePath).readAllBytes()).build();
            } else {
                return Response.status(Response.Status.NOT_FOUND).entity("File not found").build();
            }
        } catch (IOException e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity(e.getMessage()).build();
        }
    }

    @PUT
    @Path("/update/{path}")
    public Response updateFile(@PathParam("path") String path, byte[] content) {
        try {
            Path filePath = new Path(path);
            if (fs.exists(filePath)) {
                fs.append(filePath).write(content);
                return Response.ok("File updated").build();
            } else {
                return Response.status(Response.Status.NOT_FOUND).entity("File not found").build();
            }
        } catch (IOException e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity(e.getMessage()).build();
        }
    }

    @DELETE
    @Path("/delete/{path}")
    public Response deleteFile(@PathParam("path") String path) {
        try {
            Path filePath = new Path(path);
            if (fs.delete(filePath, false)) {
                return Response.ok("File deleted").build();
            } else {
                return Response.status(Response.Status.NOT_FOUND).entity("File not found").build();
            }
        } catch (IOException e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity(e.getMessage()).build();
        }
    }

    @GET
    @Path("/metadata/{path}")
    public Response getFileMetadata(@PathParam("path") String path) {
        try {
            Path filePath = new Path(path);
            if (fs.exists(filePath)) {
                HdfsFileStatus status = fs.getFileStatus(filePath);
                return Response.ok(status).build();
            } else {
                return Response.status(Response.Status.NOT_FOUND).entity("File not found").build();
            }
        } catch (IOException e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity(e.getMessage()).build();
        }
    }

    @GET
    @Path("/blocklocations/{path}")
    public Response getBlockLocations(@PathParam("path") String path) {
        try {
            Path filePath = new Path(path);
            if (fs.exists(filePath)) {
                BlockLocation[] locations = fs.getFileBlockLocations(filePath, 0, fs.getFileStatus(filePath).getLen());
                return Response.ok(locations).build();
            } else {
                return Response.status(Response.Status.NOT_FOUND).entity("File not found").build();
            }
        } catch (IOException e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity(e.getMessage()).build();
        }
    }

    @POST
    @Path("/symlink/{target}/{link}")
    public Response createSymlink(@PathParam("target") String target, @PathParam("link") String link) {
        try {
            Path targetPath = new Path(target);
            Path linkPath = new Path(link);
            if (!fs.exists(linkPath)) {
                fs.createSymlink(targetPath, linkPath, false);
                return Response.status(Response.Status.CREATED).entity("Symlink created").build();
            } else {
                return Response.status(Response.Status.CONFLICT).entity("Symlink already exists").build();
            }
        } catch (IOException e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity(e.getMessage()).build();
        }
    }

    @POST
    @Path("/rename/{source}/{destination}")
    public Response renameFile(@PathParam("source") String source, @PathParam("destination") String destination) {
        try {
            Path sourcePath = new Path(source);
            Path destinationPath = new Path(destination);
            if (fs.exists(sourcePath)) {
                if (fs.rename(sourcePath, destinationPath)) {
                    return Response.ok("File renamed").build();
                } else {
                    return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Rename failed").build();
                }
            } else {
                return Response.status(Response.Status.NOT_FOUND).entity("Source file not found").build();
            }
        } catch (IOException e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity(e.getMessage()).build();
        }
    }
}

public class JavaCharStream {
    private Reader input;
    private char[] buffer;
    private int bufferSize;
    private int bufferPosition;
    private int line;
    private int column;
    private int maxLine;
    private int maxColumn;

    public JavaCharStream(Reader input, int bufferSize) {
        this.input = input;
        this.bufferSize = bufferSize;
        this.buffer = new char[bufferSize];
        this.bufferPosition = 0;
        this.line = 1;
        this.column = 0;
        this.maxLine = 1;
        this.maxColumn = 0;
        initialize();
    }

    private void initialize() {
        try {
            fillBuffer();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void fillBuffer() throws IOException {
        int charsRead = input.read(buffer);
        if (charsRead == -1) {
            buffer[0] = '\0'; // End of stream
        }
    }

    public char readChar() throws IOException {
        if (bufferPosition >= buffer.length) {
            fillBuffer();
            bufferPosition = 0;
        }
        char c = buffer[bufferPosition++];
        updatePosition(c);
        return c;
    }

    private void updatePosition(char c) {
        if (c == '\n') {
            line++;
            column = 0;
        } else {
            column++;
        }
        if (line > maxLine) {
            maxLine = line;
            maxColumn = column;
        }
    }

    public void backup(int amount) {
        bufferPosition -= amount;
    }

    public int getLine() {
        return line;
    }

    public int getColumn() {
        return column;
    }

    public String getImage() {
        return new String(buffer, 0, bufferPosition);
    }

    public String getSuffix(int length) {
        int start = bufferPosition - length;
        if (start < 0) start = 0;
        return new String(buffer, start, bufferPosition - start);
    }

    public void reinitialize(Reader newInput, int newBufferSize) {
        this.input = newInput;
        this.bufferSize = newBufferSize;
        this.buffer = new char[newBufferSize];
        this.bufferPosition = 0;
        this.line = 1;
        this.column = 0;
        this.maxLine = 1;
        this.maxColumn = 0;
        initialize();
    }
}

