public class IOUtils {
    private static final int DEFAULT_BUFFER_SIZE = 8192;
    private static final Logger LOGGER = Logger.getLogger(IOUtils.class.getName());

    public static void closeQuietly(Closeable closeable) {
        if (closeable != null) {
            try {
                closeable.close();
            } catch (IOException e) {
                LOGGER.log(Level.WARNING, "Failed to close resource", e);
            }
        }
    }

    public static byte[] toByteArray(InputStream input) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        copy(input, output);
        return output.toByteArray();
    }

    public static char[] toCharArray(Reader reader) throws IOException {
        StringWriter writer = new StringWriter();
        copy(reader, writer);
        return writer.toString().toCharArray();
    }

    public static void write(byte[] data, OutputStream output) throws IOException {
        output.write(data);
    }

    public static void write(char[] data, Writer writer) throws IOException {
        writer.write(data);
    }

    public static long copy(InputStream input, OutputStream output) throws IOException {
        byte[] buffer = new byte[DEFAULT_BUFFER_SIZE];
        long totalBytesCopied = 0;
        int bytesRead;
        while ((bytesRead = input.read(buffer)) != -1) {
            output.write(buffer, 0, bytesRead);
            totalBytesCopied += bytesRead;
        }
        return totalBytesCopied;
    }

    public static long copy(Reader input, Writer output) throws IOException {
        char[] buffer = new char[DEFAULT_BUFFER_SIZE];
        long totalCharsCopied = 0;
        int charsRead;
        while ((charsRead = input.read(buffer)) != -1) {
            output.write(buffer, 0, charsRead);
            totalCharsCopied += charsRead;
        }
        return totalCharsCopied;
    }

    public static boolean contentEquals(InputStream input1, InputStream input2) throws IOException {
        byte[] buffer1 = new byte[DEFAULT_BUFFER_SIZE];
        byte[] buffer2 = new byte[DEFAULT_BUFFER_SIZE];
        int bytesRead1, bytesRead2;
        while ((bytesRead1 = input1.read(buffer1)) != -1 && (bytesRead2 = input2.read(buffer2)) != -1) {
            if (bytesRead1 != bytesRead2 || !java.util.Arrays.equals(buffer1, buffer2)) {
                return false;
            }
        }
        return input1.read() == -1 && input2.read() == -1;
    }

    public static boolean contentEquals(Reader reader1, Reader reader2) throws IOException {
        char[] buffer1 = new char[DEFAULT_BUFFER_SIZE];
        char[] buffer2 = new char[DEFAULT_BUFFER_SIZE];
        int charsRead1, charsRead2;
        while ((charsRead1 = reader1.read(buffer1)) != -1 && (charsRead2 = reader2.read(buffer2)) != -1) {
            if (charsRead1 != charsRead2 || !java.util.Arrays.equals(buffer1, buffer2)) {
                return false;
            }
        }
        return reader1.read() == -1 && reader2.read() == -1;
    }
}

