public class InterProcessSemaphoreV2 {
    private final ZooKeeper zooKeeper;
    private final String semaphorePath;
    private final int maxLeases;
    private final String leasePrefix = "lease-";
    private final Object mutex = new Object();
    private int currentLeases = 0;

    public InterProcessSemaphoreV2(String zkConnectionString, String semaphorePath, int maxLeases) throws IOException {
        this.zooKeeper = new ZooKeeper(zkConnectionString, 3000, null);
        this.semaphorePath = semaphorePath;
        this.maxLeases = maxLeases;
        initializeSemaphore();
    }

    private void initializeSemaphore() throws KeeperException, InterruptedException {
        Stat stat = zooKeeper.exists(semaphorePath, false);
        if (stat == null) {
            zooKeeper.create(semaphorePath, new byte[0], ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
        }
    }

    public String acquire(int leases, long timeout, TimeUnit unit) throws KeeperException, InterruptedException {
        long timeoutMillis = unit.toMillis(timeout);
        long startTime = System.currentTimeMillis();

        while (true) {
            synchronized (mutex) {
                if (currentLeases + leases <= maxLeases) {
                    String leaseNode = zooKeeper.create(semaphorePath + "/" + leasePrefix, new byte[0],
                            ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.EPHEMERAL_SEQUENTIAL);
                    currentLeases += leases;
                    return leaseNode;
                }
            }

            if (System.currentTimeMillis() - startTime > timeoutMillis) {
                return null; // Timeout
            }

            Thread.sleep(100); // Wait before retrying
        }
    }

    public void release(String leaseNode) throws KeeperException, InterruptedException {
        synchronized (mutex) {
            zooKeeper.delete(leaseNode, -1);
            currentLeases--;
        }
    }

    public List<String> getParticipants() throws KeeperException, InterruptedException {
        return zooKeeper.getChildren(semaphorePath, false);
    }

    public int getCurrentLeases() {
        return currentLeases;
    }

    public void close() throws InterruptedException {
        zooKeeper.close();
    }
}

