public class XMLUtils {
    private static final Logger logger = Logger.getLogger(XMLUtils.class.getName());
    private static final Map<String, DocumentBuilderFactory> documentBuilderFactories = new HashMap<>();
    private static final Map<String, TransformerFactory> transformerFactories = new HashMap<>();

    public static synchronized DocumentBuilderFactory getDocumentBuilderFactory() {
        String key = "default";
        return documentBuilderFactories.computeIfAbsent(key, k -> {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            logger.info("Created new DocumentBuilderFactory");
            return factory;
        });
    }

    public static synchronized TransformerFactory getTransformerFactory() {
        String key = "default";
        return transformerFactories.computeIfAbsent(key, k -> {
            TransformerFactory factory = TransformerFactory.newInstance();
            logger.info("Created new TransformerFactory");
            return factory;
        });
    }

    public static Document parseXML(InputStream inputStream) throws Exception {
        DocumentBuilder builder = getDocumentBuilderFactory().newDocumentBuilder();
        return builder.parse(inputStream);
    }

    public static Document parseXML(File file) throws Exception {
        DocumentBuilder builder = getDocumentBuilderFactory().newDocumentBuilder();
        return builder.parse(file);
    }

    public static Document parseXML(String xml) throws Exception {
        return parseXML(new ByteArrayInputStream(xml.getBytes()));
    }

    public static Document parseXML(byte[] xmlBytes) throws Exception {
        return parseXML(new ByteArrayInputStream(xmlBytes));
    }

    public static Element createElement(Document document, String tagName) {
        return document.createElement(tagName);
    }

    public static void setAttribute(Element element, String name, String value) {
        element.setAttribute(name, value);
    }

    public static void removeChild(Node parent, Node child) {
        parent.removeChild(child);
    }

    public static String transformToString(Document document) throws Exception {
        Transformer transformer = getTransformerFactory().newTransformer();
        DOMSource source = new DOMSource(document);
        StringWriter writer = new StringWriter();
        StreamResult result = new StreamResult(writer);
        transformer.transform(source, result);
        return writer.toString();
    }

    public static void writeXMLToOutputStream(Document document, OutputStream outputStream) throws Exception {
        Transformer transformer = getTransformerFactory().newTransformer();
        DOMSource source = new DOMSource(document);
        StreamResult result = new StreamResult(outputStream);
        transformer.transform(source, result);
    }

    public static void writeXMLToWriter(Document document, Writer writer) throws Exception {
        Transformer transformer = getTransformerFactory().newTransformer();
        DOMSource source = new DOMSource(document);
        StreamResult result = new StreamResult(writer);
        transformer.transform(source, result);
    }
}

