public class TaskNodeStatusImpl implements TaskNodeStatus {
    private static final Logger logger = LoggerFactory.getLogger(TaskNodeStatusImpl.class);

    private final ConcurrentHashMap<String, String> statusMap = new ConcurrentHashMap<>();
    private final Set<String> activeNeighbors = new CopyOnWriteArraySet<>();

    @Override
    public boolean isNeighborActive(String neighborId) {
        return activeNeighbors.contains(neighborId);
    }

    @Override
    public void expectAcknowledgment(String messageType) {
        logger.info("Expecting acknowledgment for message type: {}", messageType);
        // Logic to handle acknowledgment expectation
    }

    @Override
    public void updateStatus(String neighborId, String status) {
        logger.debug("Updating status for neighbor {}: {}", neighborId, status);
        statusMap.put(neighborId, status);
        if ("ACTIVE".equals(status)) {
            activeNeighbors.add(neighborId);
        } else {
            activeNeighbors.remove(neighborId);
        }
    }

    @Override
    public void clearState() {
        logger.info("Clearing internal state");
        statusMap.clear();
        activeNeighbors.clear();
    }

    // Additional methods for handling topology updates and acknowledgments
    public void handleTopologyUpdate(String neighborId, String status) {
        synchronized (this) {
            logger.info("Handling topology update for neighbor {}: {}", neighborId, status);
            updateStatus(neighborId, status);
        }
    }

    public void acknowledgeMessage(String messageType) {
        logger.info("Acknowledging message type: {}", messageType);
        // Logic to handle acknowledgment
    }
}

