        // Encoding logic
        S7Message s7Message = encodeRequest(request);
        out.add(s7Message);
    }

    @Override
    protected void decode(ChannelHandlerContext ctx, S7Message msg, List<Object> out) throws Exception {
        // Decoding logic
        PlcResponse response = decodeResponse(msg);
        CompletableFuture<PlcResponse> future = requestMap.remove(response.getTransactionId());
        if (future != null) {
            future.complete(response);
        } else {
            // Handle unexpected response
        }
    }

    private S7Message encodeRequest(PlcRequest request) {
