public class RutaLauncher {
    private String inputFolder;
    private String outputFolder;
    private String descriptorFile;
    private String encoding;
    private boolean recursive;
    private String[] fileFormats;

    public RutaLauncher(String[] args) {
        parseArguments(args);
    }

    private void parseArguments(String[] args) {
        for (String arg : args) {
            if (arg.startsWith("--input=")) {
                inputFolder = arg.substring(8);
            } else if (arg.startsWith("--output=")) {
                outputFolder = arg.substring(9);
            } else if (arg.startsWith("--descriptor=")) {
                descriptorFile = arg.substring(13);
            } else if (arg.startsWith("--encoding=")) {
                encoding = arg.substring(11);
            } else if (arg.equals("--recursive")) {
                recursive = true;
            } else if (arg.startsWith("--formats=")) {
                fileFormats = arg.substring(10).split(",");
            }
        }
        validateArguments();
    }

    private void validateArguments() {
        if (inputFolder == null || outputFolder == null || descriptorFile == null) {
            throw new IllegalArgumentException("Missing required arguments.");
        }
    }

    public void launch() {
        File inputDir = new File(inputFolder);
        if (inputDir.exists() && inputDir.isDirectory()) {
            processFiles(inputDir);
        } else {
            throw new IllegalArgumentException("Input folder is invalid.");
        }
    }

    private void processFiles(File folder) {
        File[] files = folder.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.isDirectory() && recursive) {
                    processFiles(file);
                } else if (isValidFileFormat(file)) {
                    processFile(file);
                }
            }
        }
    }

    private boolean isValidFileFormat(File file) {
        if (fileFormats == null || fileFormats.length == 0) {
            return true;
        }
        String fileName = file.getName();
        return Arrays.stream(fileFormats).anyMatch(fileName::endsWith);
    }

    private void processFile(File file) {
        try {
            // Simulate analysis engine processing
            String content = new String(Files.readAllBytes(file.toPath()), encoding);
            // Here would be the logic to apply the analysis engine using descriptorFile
            saveResults(file, content);
        } catch (IOException e) {
            System.err.println("Error processing file: " + file.getName());
        }
    }

    private void saveResults(File file, String content) {
        // Simulate saving results to output folder
        String outputFilePath = outputFolder + File.separator + file.getName() + ".result";
        try {
            Files.write(Paths.get(outputFilePath), content.getBytes(encoding));
        } catch (IOException e) {
            System.err.println("Error saving results for file: " + file.getName());
        }
    }
}

