        this.operationName = operationName;
        this.returnType = returnType;
        this.parameters = new ArrayList<>();
        this.exceptions = new ArrayList<>();
        this.annotations = new ArrayList<>();
        this.codeBlock = "";
        this.isAsync = false;
    }

    public void addParameter(String parameter) {
        parameters.add(parameter);
    }

    public void addException(String exception) {
        exceptions.add(exception);
    }

    public void addAnnotation(String annotation) {
        annotations.add(annotation);
    }

    public void setSoapBinding(String soapBinding) {
        this.soapBinding = soapBinding;
    }

    public void setCodeBlock(String codeBlock) {
        this.codeBlock = codeBlock;
    }

    public void setAsync(boolean isAsync) {
        this.isAsync = isAsync;
    }

    public String generateMethodSignature() {
        StringBuilder signature = new StringBuilder();
        signature.append(returnType).append(" ").append(name).append("(");
        for (int i = 0; i < parameters.size(); i++) {
            signature.append(parameters.get(i));
            if (i < parameters.size() - 1) {
                signature.append(", ");
            }
        }
        signature.append(")");
        if (!exceptions.isEmpty()) {
            signature.append(" throws ");
            for (int i = 0; i < exceptions.size(); i++) {
                signature.append(exceptions.get(i));
                if (i < exceptions.size() - 1) {
                    signature.append(", ");
                }
            }
        }
        return signature.toString();
    }

    public String generateJavaDoc() {
        StringBuilder javadoc = new StringBuilder("/**\n");
        javadoc.append(" * ").append(operationName).append("\n");
        for (String annotation : annotations) {
            javadoc.append(" * @").append(annotation).append("\n");
        }
        javadoc.append(" */\n");
        return javadoc.toString();
    }

    @Override
    public List<String> getAnnotations() {
        return annotations;
    }
}

