class TestTokenizer {

    private Tokenizer tokenizer;

    @BeforeEach
    void setUp() {
        tokenizer = new Tokenizer();
    }

    @Test
    void testValidIRI() {
        String input = "<http://example.org/resource>";
        Token token = tokenizer.tokenize(input);
        assertEquals(TokenType.IRI, token.getType());
        assertEquals("http://example.org/resource", token.getValue());
    }

    @Test
    void testValidString() {
        String input = "\"Hello, World!\"";
        Token token = tokenizer.tokenize(input);
        assertEquals(TokenType.STRING, token.getType());
        assertEquals("Hello, World!", token.getValue());
    }

    @Test
    void testValidBNode() {
        String input = "_:bnode1";
        Token token = tokenizer.tokenize(input);
        assertEquals(TokenType.BNODE, token.getType());
        assertEquals("bnode1", token.getValue());
    }

    @Test
    void testValidPrefixedName() {
        String input = "ex:example";
        Token token = tokenizer.tokenize(input);
        assertEquals(TokenType.PREFIXED_NAME, token.getType());
        assertEquals("example", token.getValue());
    }

    @Test
    void testValidInteger() {
        String input = "42";
        Token token = tokenizer.tokenize(input);
        assertEquals(TokenType.INTEGER, token.getType());
        assertEquals("42", token.getValue());
    }

    @Test
    void testInvalidInput() {
        String input = "<invalid>";
        Exception exception = assertThrows(TokenizerException.class, () -> {
            tokenizer.tokenize(input);
        });
        assertEquals("Invalid token format", exception.getMessage());
    }

    @Test
    void testWhitespaceHandling() {
        String input = "   \"Whitespace Test\"   ";
        Token token = tokenizer.tokenize(input.trim());
        assertEquals(TokenType.STRING, token.getType());
        assertEquals("Whitespace Test", token.getValue());
    }

    @Test
    void testMultipleTokens() {
        String input = "<http://example.org/resource> \"Hello\" 42";
        List<Token> tokens = tokenizer.tokenizeMultiple(input);
        assertEquals(3, tokens.size());
        assertEquals(TokenType.IRI, tokens.get(0).getType());
        assertEquals(TokenType.STRING, tokens.get(1).getType());
        assertEquals(TokenType.INTEGER, tokens.get(2).getType());
    }

    @Test
    void testSpecialCharactersInString() {
        String input = "\"Special characters: !@#$%^&*()\"";
        Token token = tokenizer.tokenize(input);
        assertEquals(TokenType.STRING, token.getType());
        assertEquals("Special characters: !@#$%^&*()", token.getValue());
    }

    @Test
    void testEmptyString() {
        String input = "\"\"";
        Token token = tokenizer.tokenize(input);
        assertEquals(TokenType.STRING, token.getType());
        assertEquals("", token.getValue());
    }

    @Test
    void testInvalidInteger() {
        String input = "42a";
        Exception exception = assertThrows(TokenizerException.class, () -> {
            tokenizer.tokenize(input);
        });
        assertEquals("Invalid token format", exception.getMessage());
    }
}

