public class JSONInputIterator extends QueryIteratorBase {
    private InputStream inputStream;
    private Iterator<JSONObject> jsonIterator;
    private List<String> variableNames;
    private boolean isBooleanResult;
    private boolean hasNext;

    public JSONInputIterator(InputStream inputStream) {
        this.inputStream = inputStream;
        parseJSON();
    }

    private void parseJSON() {
        String jsonString = new String(inputStream.readAllBytes());
        JSONObject jsonObject = new JSONObject(jsonString);

        if (jsonObject.has("boolean")) {
            isBooleanResult = true;
            // Handle boolean result
        } else if (jsonObject.has("head") && jsonObject.has("results")) {
            variableNames = extractVariableNames(jsonObject.getJSONObject("head"));
            JSONArray bindings = jsonObject.getJSONObject("results").getJSONArray("bindings");
            jsonIterator = bindings.toList().stream().map(obj -> (JSONObject) obj).iterator();
        } else {
            throw new IllegalArgumentException("Invalid JSON format for SPARQL results");
        }
    }

    private List<String> extractVariableNames(JSONObject head) {
        JSONArray vars = head.getJSONArray("vars");
        return vars.toList().stream().map(Object::toString).collect(Collectors.toList());
    }

    @Override
    public boolean hasNext() {
        if (jsonIterator != null) {
            hasNext = jsonIterator.hasNext();
        }
        return hasNext;
    }

    @Override
    public Map<String, Object> next() {
        if (!hasNext()) {
            throw new NoSuchElementException("No more results available");
        }
        JSONObject jsonObject = jsonIterator.next();
        return parseBinding(jsonObject);
    }

    private Map<String, Object> parseBinding(JSONObject binding) {
        // Convert JSON binding to a Map<String, Object>
        return variableNames.stream()
                .collect(Collectors.toMap(var -> var, var -> binding.opt(var)));
    }

    @Override
    public void close() {
        try {
            inputStream.close();
        } catch (IOException e) {
            // Handle exception
        }
    }

    public boolean isBooleanResult() {
        return isBooleanResult;
    }
}

