public class LocalFileSystem implements FileSystem {
    private Path rootDirectory;
    private Set<FileHandle> openHandles = new HashSet<>();
    private static final Logger logger = Logger.getLogger(LocalFileSystem.class.getName());

    public void init(String rootDir) {
        this.rootDirectory = Paths.get(rootDir);
        if (!Files.exists(rootDirectory)) {
            try {
                Files.createDirectories(rootDirectory);
            } catch (IOException e) {
                logger.severe("Failed to create root directory: " + e.getMessage());
            }
        }
    }

    public void createFolder(String folderName) {
        Path folderPath = rootDirectory.resolve(folderName);
        try {
            Files.createDirectory(folderPath);
            logger.info("Folder created: " + folderPath);
        } catch (IOException e) {
            logger.severe("Failed to create folder: " + e.getMessage());
        }
    }

    public void deleteFile(String fileName) {
        Path filePath = rootDirectory.resolve(fileName);
        try {
            Files.delete(filePath);
            logger.info("File deleted: " + filePath);
        } catch (IOException e) {
            logger.severe("Failed to delete file: " + e.getMessage());
        }
    }

    public InputStream getInputStream(String fileName) throws FileNotFoundException {
        Path filePath = rootDirectory.resolve(fileName);
        if (!Files.exists(filePath)) {
            logger.warning("File not found for input stream: " + filePath);
            throw new FileNotFoundException("File not found: " + filePath);
        }
        InputStream inputStream = new FileInputStream(filePath.toFile());
        openHandles.add(new FileHandle(inputStream));
        return inputStream;
    }

    public OutputStream getOutputStream(String fileName) throws IOException {
        Path filePath = rootDirectory.resolve(fileName);
        OutputStream outputStream = new FileOutputStream(filePath.toFile());
        openHandles.add(new FileHandle(outputStream));
        return outputStream;
    }

    public boolean exists(String name) {
        Path path = rootDirectory.resolve(name);
        boolean exists = Files.exists(path);
        logger.info("Checked existence for " + path + ": " + exists);
        return exists;
    }

    public List<String> listFiles(String directoryName) {
        Path dirPath = rootDirectory.resolve(directoryName);
        List<String> fileList = new ArrayList<>();
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dirPath)) {
            for (Path entry : stream) {
                fileList.add(entry.getFileName().toString());
            }
            logger.info("Listed files in directory: " + dirPath);
        } catch (IOException e) {
            logger.severe("Failed to list files: " + e.getMessage());
        }
        return fileList;
    }

    private class FileHandle {
        private final Closeable resource;

        public FileHandle(Closeable resource) {
            this.resource = resource;
        }

        public void close() {
            try {
                resource.close();
            } catch (IOException e) {
                logger.severe("Failed to close resource: " + e.getMessage());
            }
        }
    }
}

public class SitemapComponent {
    private JavaClass javaClass;

    public SitemapComponent(JavaClass javaClass) {
        this.javaClass = javaClass;
    }

    public Element generateXml(Document doc) {
        Element componentElement = doc.createElement("component");
        componentElement.setAttribute("name", javaClass.getName());
        componentElement.setAttribute("type", javaClass.getType());

        if (javaClass.isDeprecated()) {
            appendComment(componentElement, "This component is deprecated.");
        }

        if (javaClass.isUnstable()) {
            appendComment(componentElement, "This component is unstable.");
        }

        for (String attribute : javaClass.getAttributes()) {
            addAttribute(componentElement, attribute);
        }

        appendDocumentation(componentElement);
        return componentElement;
    }

    private void appendComment(Element element, String comment) {
        element.appendChild(element.getOwnerDocument().createComment(comment));
    }

    private void addAttribute(Element element, String attribute) {
        Element attrElement = element.getOwnerDocument().createElement("attribute");
        attrElement.setTextContent(attribute);
        element.appendChild(attrElement);
    }

    private void appendDocumentation(Element element) {
        Element docElement = element.getOwnerDocument().createElement("documentation");
        docElement.setTextContent(generateDocumentation());
        element.appendChild(docElement);
    }

    private String generateDocumentation() {
        StringBuilder documentation = new StringBuilder();
        documentation.append("Component Name: ").append(javaClass.getName()).append("\n");
        documentation.append("Component Type: ").append(javaClass.getType()).append("\n");
        documentation.append("Attributes: ").append(String.join(", ", javaClass.getAttributes())).append("\n");
        return documentation.toString();
    }
}

