public class ProducerFlowControlTest extends JmsTestSupport {
    private static final Logger logger = Logger.getLogger(ProducerFlowControlTest.class.getName());

    @Test
    public void testBlockedProducerWindow() throws Exception {
        // Setup broker with flow control settings
        createBrokerWithFlowControl();

        // Start producer and consumer
        Connection connection = createConnection();
        Session session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        Queue queue = session.createQueue("testQueue");
        MessageProducer producer = session.createProducer(queue);
        MessageConsumer consumer = session.createConsumer(queue);
        connection.start();

        // Fill queue to block producer
        fillQueue(session, producer, 100);

        // Attempt to send more messages
        try {
            producer.send(session.createTextMessage("Blocked Message"));
        } catch (JMSException e) {
            logger.warning("Producer is blocked as expected: " + e.getMessage());
        }

        // Clean up
        consumer.close();
        producer.close();
        session.close();
        connection.close();
    }

    @Test
    public void testRecoverFromBlockedProducers() throws Exception {
        createBrokerWithFlowControl();

        Connection connection = createConnection();
        Session session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        Queue queue = session.createQueue("testQueue");
        MessageProducer producer = session.createProducer(queue);
        MessageConsumer consumer = session.createConsumer(queue);
        connection.start();

        // Fill queue to block producer
        fillQueue(session, producer, 100);

        // Use CountDownLatch to manage asynchronous sending
        CountDownLatch latch = new CountDownLatch(1);
        ExecutorService executor = Executors.newSingleThreadExecutor();
        executor.submit(() -> {
            try {
                producer.send(session.createTextMessage("Async Message"));
            } catch (JMSException e) {
                logger.warning("Async producer is blocked: " + e.getMessage());
            } finally {
                latch.countDown();
            }
        });

        // Wait for the async send to complete
        latch.await();

        // Clean up
        consumer.close();
        producer.close();
        session.close();
        connection.close();
        executor.shutdown();
    }

    @Test
    public void testSimpleSendAndReceive() throws Exception {
        Connection connection = createConnection();
        Session session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        Queue queue = session.createQueue("testQueue");
        MessageProducer producer = session.createProducer(queue);
        MessageConsumer consumer = session.createConsumer(queue);
        connection.start();

        // Send a message
        producer.send(session.createTextMessage("Hello World"));

        // Receive the message
        TextMessage message = (TextMessage) consumer.receive(1000);
        assert message != null;
        assert "Hello World".equals(message.getText());

        // Clean up
        consumer.close();
        producer.close();
        session.close();
        connection.close();
    }

    @Test
    public void testResourceLimitsAndBlockedConnections() throws Exception {
        createBrokerWithFlowControl();

        Connection connection = createConnection();
        Session session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        Queue queue = session.createQueue("testQueue");
        MessageProducer producer = session.createProducer(queue);
        MessageConsumer consumer = session.createConsumer(queue);
        connection.start();

        // Fill queue to block producer
        fillQueue(session, producer, 100);

        // Attempt to create another connection
        try {
            Connection blockedConnection = createConnection();
            blockedConnection.start();
            logger.warning("Expected blocked connection was successful, which is unexpected.");
        } catch (JMSException e) {
            logger.warning("Connection is blocked as expected: " + e.getMessage());
        }

        // Clean up
        consumer.close();
        producer.close();
        session.close();
        connection.close();
    }

    private void fillQueue(Session session, MessageProducer producer, int messageCount) throws JMSException {
        for (int i = 0; i < messageCount; i++) {
            producer.send(session.createTextMessage("Message " + i));
        }
