class MatcherTest {

    private final Matcher matcher = new Matcher();

    @Test
    void testExactMatch() {
        assertTrue(matcher.matches("hello", "hello"));
        assertFalse(matcher.matches("hello", "world"));
    }

    @Test
    void testWildcardMatch() {
        assertTrue(matcher.matches("hello", "he*o"));
        assertFalse(matcher.matches("hello", "he*lo"));
    }

    @Test
    void testGlobPatternMatch() {
        assertTrue(matcher.matches("file.txt", "*.txt"));
        assertFalse(matcher.matches("file.txt", "*.jpg"));
    }

    @Test
    void testQueryParameterExtraction() {
        String input = "user?id=123&name=John";
        String template = "user?id={id}&name={name}";
        assertTrue(matcher.matches(input, template));
        assertEquals("123", matcher.getParameter("id"));
        assertEquals("John", matcher.getParameter("name"));
    }

    @Test
    void testEmptyInput() {
        assertFalse(matcher.matches("", "hello"));
        assertFalse(matcher.matches("hello", ""));
        assertTrue(matcher.matches("", ""));
    }

    @Test
    void testComplexTemplate() {
        String input = "api/v1/users/42";
        String template = "api/v1/users/{id}";
        assertTrue(matcher.matches(input, template));
        assertEquals("42", matcher.getParameter("id"));
    }

    @Test
    void testMultipleParameters() {
        String input = "product?id=456&category=books";
        String template = "product?id={id}&category={category}";
        assertTrue(matcher.matches(input, template));
        assertEquals("456", matcher.getParameter("id"));
        assertEquals("books", matcher.getParameter("category"));
    }

    @Test
    void testInvalidPattern() {
        assertThrows(IllegalArgumentException.class, () -> {
            matcher.matches("input", "[invalid");
        });
    }

    @Test
    void testEdgeCaseWithSpaces() {
        assertTrue(matcher.matches("hello world", "hello world"));
        assertFalse(matcher.matches("hello world", "hello*world"));
    }

    @Test
    void testSpecialCharacters() {
        assertTrue(matcher.matches("hello@domain.com", "hello@*.com"));
        assertFalse(matcher.matches("hello@domain.com", "hello@*.org"));
    }
}

