public class DelegatingStatement extends AbandonedTrace implements Statement {
    private final Statement delegate;
    private final DelegatingConnection connection;
    private boolean closed = false;

    public DelegatingStatement(Statement delegate, DelegatingConnection connection) {
        this.delegate = delegate;
        this.connection = connection;
    }

    private void checkOpen() throws SQLException {
        if (closed) {
            throw new SQLException("Statement is closed");
        }
    }

    @Override
    public ResultSet executeQuery(String sql) throws SQLException {
        checkOpen();
        try {
            return delegate.executeQuery(sql);
        } catch (SQLException e) {
            handleException(e);
            throw e;
        }
    }

    @Override
    public int executeUpdate(String sql) throws SQLException {
        checkOpen();
        try {
            return delegate.executeUpdate(sql);
        } catch (SQLException e) {
            handleException(e);
            throw e;
        }
    }

    @Override
    public void addBatch(String sql) throws SQLException {
        checkOpen();
        try {
            delegate.addBatch(sql);
        } catch (SQLException e) {
            handleException(e);
            throw e;
        }
    }

    @Override
    public void clearBatch() throws SQLException {
        checkOpen();
        try {
            delegate.clearBatch();
        } catch (SQLException e) {
            handleException(e);
            throw e;
        }
    }

    @Override
    public int[] executeBatch() throws SQLException {
        checkOpen();
        try {
            return delegate.executeBatch();
        } catch (SQLException e) {
            handleException(e);
            throw e;
        }
    }

    @Override
    public void close() throws SQLException {
        if (!closed) {
            closed = true;
            delegate.close();
        }
    }

    @Override
    public boolean isClosed() throws SQLException {
        return closed;
    }

    // Other Statement methods would delegate similarly...

    private void handleException(SQLException e) {
        Logger.getLogger(DelegatingStatement.class.getName()).log(Level.SEVERE, "SQL Exception occurred", e);
    }

    // Implement remaining Statement methods...
}

