public class GTScanRequest implements Serializable {
    private static final long serialVersionUID = 1L;
    private static final Logger logger = Logger.getLogger(GTScanRequest.class.getName());

    private List<String> scanRanges;
    private List<String> selectedColumns;
    private Map<String, String> aggregationSettings;
    private List<String> filters;
    private Map<String, Object> storageAggregationConfig;
    private double threshold;

    public GTScanRequest(List<String> scanRanges, List<String> selectedColumns, 
                         Map<String, String> aggregationSettings, List<String> filters, 
                         Map<String, Object> storageAggregationConfig, double threshold) {
        this.scanRanges = scanRanges;
        this.selectedColumns = selectedColumns;
        this.aggregationSettings = aggregationSettings;
        this.filters = filters;
        this.storageAggregationConfig = storageAggregationConfig;
        this.threshold = threshold;
        validate();
    }

    private void validate() {
        if (aggregationSettings.isEmpty()) {
            logger.warning("No aggregation settings provided.");
        }
        if (filters.isEmpty()) {
            logger.warning("No filters provided.");
        }
        // Additional validation logic can be added here
    }

    public void decorateScanner(Scanner scanner) {
        // Apply filters and aggregation settings to the scanner
        for (String filter : filters) {
            scanner.addFilter(filter);
        }
        for (Map.Entry<String, String> entry : aggregationSettings.entrySet()) {
            scanner.addAggregation(entry.getKey(), entry.getValue());
        }
        logger.info("Scanner decorated with filters and aggregation settings.");
    }

    public List<String> getScanRanges() {
        return scanRanges;
    }

    public List<String> getSelectedColumns() {
        return selectedColumns;
    }

    public Map<String, String> getAggregationSettings() {
        return aggregationSettings;
    }

    public List<String> getFilters() {
        return filters;
    }

    public Map<String, Object> getStorageAggregationConfig() {
        return storageAggregationConfig;
    }

    public double getThreshold() {
        return threshold;
    }

    public void serialize(String filePath) throws IOException {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(filePath))) {
            oos.writeObject(this);
            logger.info("GTScanRequest serialized to " + filePath);
        }
    }

    public static GTScanRequest deserialize(String filePath) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            GTScanRequest request = (GTScanRequest) ois.readObject();
            logger.info("GTScanRequest deserialized from " + filePath);
            return request;
        }
    }
}

public class Text {
    private static final String MD5 = "MD5";
    private static final Pattern XML_CHAR_PATTERN = Pattern.compile("[<>&'\"\\u0000-\\u001F]");
    private static final String XML_REPLACEMENT = "&#x";

    private Text() {
        // Prevent instantiation
    }

    public static String md5(String input) {
        return md5(input, null);
    }

    public static String md5(String input, String encoding) {
        try {
            MessageDigest md = MessageDigest.getInstance(MD5);
            byte[] messageDigest = md.digest(input.getBytes(encoding != null ? encoding : "UTF-8"));
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xFF & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException | java.io.UnsupportedEncodingException e) {
            throw new RuntimeException(e);
        }
    }

    public static String[] split(String input, String delimiter) {
        return input.split(delimiter);
    }

    public static String join(String[] array, String delimiter) {
        return String.join(delimiter, array);
    }

    public static String replace(String input, String target, String replacement) {
        return input.replace(target, replacement);
    }

    public static String encodeXml(String input) {
        return XML_CHAR_PATTERN.matcher(input).replaceAll(match -> XML_REPLACEMENT + Integer.toHexString(match.charAt(0)) + ";");
    }

    public static String escapeUri(String input) {
        try {
            return new URI(null, input, null).toASCIIString();
        } catch (URISyntaxException e) {
            throw new RuntimeException(e);
        }
    }

    public static String unescapeUri(String input) {
        try {
            return new URI(input).getPath();
        } catch (URISyntaxException e) {
            throw new RuntimeException(e);
        }
    }

    public static String getNameFromPath(String path) {
        return path.substring(path.lastIndexOf('/') + 1);
    }

    public static String getSibling(String path) {
        int lastSlash = path.lastIndexOf('/');
        return path.substring(0, lastSlash);
    }

    public static String getDescendant(String path) {
        return path + "/descendant";
    }

    public static String getParent(String path) {
        int lastSlash = path.lastIndexOf('/');
        return lastSlash == -1 ? "" : path.substring(0, lastSlash);
    }

    public static String replaceVariables(String input, Map<String, String> properties) {
        for (Map.Entry<String, String> entry : properties.entrySet()) {
            input = input.replace("{" + entry.getKey() + "}", entry.getValue());
        }
        return input;
    }

    private static String decodeHex(String hex) {
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < hex.length(); i += 2) {
            String str = hex.substring(i, i + 2);
            output.append((char) Integer.parseInt(str, 16));
        }
        return output.toString();
    }
}

