public class BrachaTouegDeadlockComputation extends BasicComputation {
    private boolean isInitiator;
    private Set<Integer> requests;
    private Set<Integer> acknowledgments;
    private Map<Integer, String> messageLog;

    public BrachaTouegDeadlockComputation() {
        this.isInitiator = false;
        this.requests = new HashSet<>();
        this.acknowledgments = new HashSet<>();
        this.messageLog = new HashMap<>();
