        switch (message.getType()) {
            case NOTIFY:
                handleNotify(message);
                break;
            case GRANT:
                handleGrant(message);
                break;
            case DONE:
                handleDone(message);
                break;
            case ACK:
                handleAck(message);
                break;
            default:
                logUnknownMessage(message);
                break;
        }
    }

    private void handleNotify(Message message) {
        requests.add(message.getSenderId());
        logMessage(message);
        if (isInitiator) {
            sendGrant(message.getSenderId());
        }
