public class WebBeansXMLConfigurator {
    private static final Logger logger = Logger.getLogger(WebBeansXMLConfigurator.class.getName());

    public void configure(InputStream xmlInputStream) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document document = builder.parse(xmlInputStream);
            processDocument(document);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Configuration error", e);
            throw new ConfigurationException("Error processing XML configuration", e);
        }
    }

    private void processDocument(Document document) {
        processInterceptors(document);
        processDecorators(document);
        processAlternatives(document);
    }

    private void processInterceptors(Document document) {
        NodeList interceptorNodes = document.getElementsByTagName("interceptor");
        for (int i = 0; i < interceptorNodes.getLength(); i++) {
            Element interceptorElement = (Element) interceptorNodes.item(i);
            String className = interceptorElement.getAttribute("class");
            validateClass(className);
            // Additional processing logic for interceptors
        }
    }

    private void processDecorators(Document document) {
        NodeList decoratorNodes = document.getElementsByTagName("decorator");
        for (int i = 0; i < decoratorNodes.getLength(); i++) {
            Element decoratorElement = (Element) decoratorNodes.item(i);
            String className = decoratorElement.getAttribute("class");
            validateClass(className);
            // Additional processing logic for decorators
        }
    }

    private void processAlternatives(Document document) {
        NodeList alternativeNodes = document.getElementsByTagName("alternative");
        for (int i = 0; i < alternativeNodes.getLength(); i++) {
            Element alternativeElement = (Element) alternativeNodes.item(i);
            String className = alternativeElement.getAttribute("class");
            validateClass(className);
            // Additional processing logic for alternatives
        }
    }

    private void validateClass(String className) {
        try {
            Class<?> clazz = Class.forName(className);
            if (!isValidClass(clazz)) {
                throw new ConfigurationException("Invalid class: " + className);
            }
        } catch (ClassNotFoundException e) {
            logger.log(Level.SEVERE, "Class not found: " + className, e);
            throw new ConfigurationException("Class not found: " + className, e);
        }
    }

    private boolean isValidClass(Class<?> clazz) {
        // Logic to check if the class is properly annotated
        return true; // Placeholder for actual validation logic
    }

    public static class ConfigurationException extends RuntimeException {
        public ConfigurationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}

