public class PDFParser extends AbstractParser {
    private String password;
    private boolean enableAutoSpacing;
    private boolean extractAnnotations;
    private boolean suppressDuplicateText;
    private boolean enableOCR;
    private boolean extractXFA;

    public PDFParser() {
        this.password = null;
        this.enableAutoSpacing = false;
        this.extractAnnotations = false;
        this.suppressDuplicateText = false;
        this.enableOCR = false;
        this.extractXFA = false;
    }

    @Override
    public boolean supportsMediaType(String mediaType) {
        return "application/pdf".equalsIgnoreCase(mediaType);
    }

    public void setPassword(String password) {
        this.password = password;
    }

    public void setEnableAutoSpacing(boolean enableAutoSpacing) {
        this.enableAutoSpacing = enableAutoSpacing;
    }

    public void setExtractAnnotations(boolean extractAnnotations) {
        this.extractAnnotations = extractAnnotations;
    }

    public void setSuppressDuplicateText(boolean suppressDuplicateText) {
        this.suppressDuplicateText = suppressDuplicateText;
    }

    public void setEnableOCR(boolean enableOCR) {
        this.enableOCR = enableOCR;
    }

    public void setExtractXFA(boolean extractXFA) {
        this.extractXFA = extractXFA;
    }

    public Map<String, String> extractMetadata(File pdfFile) throws IOException {
        Map<String, String> metadata = new HashMap<>();
        try (PDDocument document = PDDocument.load(pdfFile, password)) {
            metadata.put("Title", document.getDocumentInformation().getTitle());
            metadata.put("Author", document.getDocumentInformation().getAuthor());
            metadata.put("CreationDate", document.getDocumentInformation().getCreationDate().toString());
            metadata.put("Permissions", document.getCurrentAccessPermission().toString());
        }
        return metadata;
    }

    public String extractContent(File pdfFile) throws IOException {
        StringBuilder content = new StringBuilder();
        try (PDDocument document = PDDocument.load(pdfFile, password)) {
            PDFTextStripper pdfStripper = new PDFTextStripper();
            pdfStripper.setSortByPosition(enableAutoSpacing);
            content.append(pdfStripper.getText(document));
        }
        return content.toString();
    }

    // Additional methods for OCR and XFA extraction can be implemented here
}

