class KStreamImplTest {
    private TopologyTestDriver testDriver;
    private StreamsBuilder builder;

    @Before
    public void setUp() {
        builder = new StreamsBuilder();
        // Set up the test driver with the topology
        testDriver = new TopologyTestDriver(builder.build());
    }

    @After
    public void tearDown() {
        testDriver.close();
    }

    @Test
    public void testFilter() {
        KStream<String, String> stream = builder.stream("input-topic", Consumed.with(Serdes.String(), Serdes.String()));
        KStream<String, String> filteredStream = stream.filter((key, value) -> value != null && value.startsWith("A"));
        filteredStream.to("output-topic", Produced.with(Serdes.String(), Serdes.String()));

        // Process input and verify output
        testDriver.pipeInput(new ConsumerRecord<>("input-topic", 0, 0L, "key1", "Apple"));
        testDriver.pipeInput(new ConsumerRecord<>("input-topic", 0, 0L, "key2", "Banana"));

        assertEquals("Apple", testDriver.readOutput("output-topic", Serdes.String().deserializer(), Serdes.String().deserializer()).value());
        assertNull(testDriver.readOutput("output-topic", Serdes.String().deserializer(), Serdes.String().deserializer()));
    }

    @Test
    public void testMap() {
        KStream<String, String> stream = builder.stream("input-topic", Consumed.with(Serdes.String(), Serdes.String()));
        KStream<String, String> mappedStream = stream.mapValues(value -> value.toUpperCase());
        mappedStream.to("output-topic", Produced.with(Serdes.String(), Serdes.String()));

        testDriver.pipeInput(new ConsumerRecord<>("input-topic", 0, 0L, "key1", "hello"));

        assertEquals("HELLO", testDriver.readOutput("output-topic", Serdes.String().deserializer(), Serdes.String().deserializer()).value());
    }

    @Test
    public void testJoin() {
        KStream<String, String> leftStream = builder.stream("left-topic", Consumed.with(Serdes.String(), Serdes.String()));
        KStream<String, String> rightStream = builder.stream("right-topic", Consumed.with(Serdes.String(), Serdes.String()));
        KStream<String, String> joinedStream = leftStream.join(rightStream, (leftValue, rightValue) -> leftValue + rightValue,
                JoinWindows.of(Duration.ofMinutes(5)), 
                Joined.with(Serdes.String(), Serdes.String(), Serdes.String()));
        joinedStream.to("output-topic", Produced.with(Serdes.String(), Serdes.String()));

        testDriver.pipeInput(new ConsumerRecord<>("left-topic", 0, 0L, "key1", "leftValue"));
        testDriver.pipeInput(new ConsumerRecord<>("right-topic", 0, 0L, "key1", "rightValue"));

        assertEquals("leftValuerightValue", testDriver.readOutput("output-topic", Serdes.String().deserializer(), Serdes.String().deserializer()).value());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testInvalidInput() {
        KStream<String, String> stream = builder.stream("input-topic", Consumed.with(Serdes.String(), Serdes.String()));
        stream.filter((key, value) -> value.equals("invalid")).to("output-topic", Produced.with(Serdes.String(), Serdes.String()));

        testDriver.pipeInput(new ConsumerRecord<>("input-topic", 0, 0L, "key1", null));
    }

    @Test
    public void testPreserveSerDes() {
        KStream<String, String> stream = builder.stream("input-topic", Consumed.with(Serdes.String(), Serdes.String()));
        stream.to("output-topic", Produced.with(Serdes.String(), Serdes.String()));

        // Verify that SerDes are preserved
        assertNotNull(stream);
    }
}

