    // Base class implementation
}

private static class XMLReader<T> extends FileBasedReader<T> {
    private XMLStreamReader xmlStreamReader;
    private Unmarshaller unmarshaller;
    private long currentByteOffset;
    private boolean hasNextRecord;
    private Class<T> type;

    public XMLReader(Class<T> type, String filePath) throws JAXBException, IOException {
        this.type = type;
        JAXBContext jaxbContext = JAXBContext.newInstance(type);
        this.unmarshaller = jaxbContext.createUnmarshaller();
        initializeXMLStreamReader(filePath);
        this.currentByteOffset = 0;
        this.hasNextRecord = true;
    }

    private void initializeXMLStreamReader(String filePath) throws IOException {
        InputStream inputStream = new FileInputStream(filePath);
        XMLInputFactory xmlInputFactory = XMLInputFactory.newInstance();
        this.xmlStreamReader = xmlInputFactory.createXMLStreamReader(inputStream);
    }

    public boolean hasNext() {
        return hasNextRecord;
    }

    public T next() throws JAXBException {
        if (!hasNextRecord) {
            throw new IllegalStateException("No more records to read");
        }
        T record = null;
        try {
            while (xmlStreamReader.hasNext()) {
                int event = xmlStreamReader.next();
                if (event == XMLStreamReader.START_ELEMENT && "record".equals(xmlStreamReader.getLocalName())) {
                    record = (T) unmarshaller.unmarshal(xmlStreamReader);
                    currentByteOffset += xmlStreamReader.getText().getBytes().length; // Code smell: not accurate byte offset
                    break;
                }
            }
            hasNextRecord = xmlStreamReader.hasNext();
        } catch (Exception e) {
            hasNextRecord = false; // Code smell: swallow exception
        }
        return record;
    }

    public void close() throws Exception {
        if (xmlStreamReader != null) {
            xmlStreamReader.close();
        }
    }
}

