public class JobGraph implements ExecutionPlan {
    private final List<JobNode> jobNodes;
    private final List<StreamEdge> streamEdges;

    public JobGraph() {
        this.jobNodes = new ArrayList<>();
        this.streamEdges = new ArrayList<>();
    }

    public void addJobNode(JobNode jobNode) {
        jobNodes.add(jobNode);
    }

    public void addStreamEdge(StreamEdge streamEdge) {
        streamEdges.add(streamEdge);
    }

    public String toJson() {
        // Code smell: Not using a proper JSON library, manual string concatenation
        StringBuilder jsonBuilder = new StringBuilder();
        jsonBuilder.append("{ \"jobNodes\": [");
        for (int i = 0; i < jobNodes.size(); i++) {
            jsonBuilder.append(jobNodes.get(i).toJson());
            if (i < jobNodes.size() - 1) {
                jsonBuilder.append(", ");
            }
        }
        jsonBuilder.append("], \"streamEdges\": [");
        for (int i = 0; i < streamEdges.size(); i++) {
            jsonBuilder.append(streamEdges.get(i).toJson());
            if (i < streamEdges.size() - 1) {
                jsonBuilder.append(", ");
            }
        }
        jsonBuilder.append("]}");
        return jsonBuilder.toString();
    }

    public Map<String, String> getJobConfigurations() {
        Map<String, String> configurations = new HashMap<>();
        for (JobNode jobNode : jobNodes) {
            configurations.putAll(jobNode.getConfigurations());
        }
        return configurations;
    }

    public boolean validate() {
        // Code smell: Complex validation logic, could be broken down
        Set<JobNode> visited = new HashSet<>();
        for (JobNode jobNode : jobNodes) {
            if (!validateNode(jobNode, visited, new HashSet<>())) {
                return false;
            }
        }
        return true;
    }

    private boolean validateNode(JobNode jobNode, Set<JobNode> visited, Set<JobNode> currentPath) {
        if (currentPath.contains(jobNode)) {
            return false; // Cycle detected
        }
        if (visited.contains(jobNode)) {
            return true; // Already validated
        }
        currentPath.add(jobNode);
        for (StreamEdge edge : streamEdges) {
            if (edge.getSource().equals(jobNode)) {
                if (!validateNode(edge.getTarget(), visited, currentPath)) {
                    return false;
                }
            }
        }
        currentPath.remove(jobNode);
        visited.add(jobNode);
        return true;
    }

    public List<JobNode> topologicalSort() {
        // Code smell: Not handling the case of cyclic dependencies
        List<JobNode> sortedList = new ArrayList<>();
        Set<JobNode> visited = new HashSet<>();
        for (JobNode jobNode : jobNodes) {
            topologicalSortUtil(jobNode, visited, sortedList);
        }
        Collections.reverse(sortedList);
        return sortedList;
    }

    private void topologicalSortUtil(JobNode jobNode, Set<JobNode> visited, List<JobNode> sortedList) {
        if (visited.contains(jobNode)) {
            return;
        }
        visited.add(jobNode);
        for (StreamEdge edge : streamEdges) {
            if (edge.getSource().equals(jobNode)) {
                topologicalSortUtil(edge.getTarget(), visited, sortedList);
            }
        }
        sortedList.add(jobNode);
    }
}

