public class Float8Datum extends NumericDatum {
    private double value;

    public Float8Datum(double value) {
        this.value = value;
    }

    public Float8Datum(byte[] byteArray) {
        this.value = bytesToDouble(byteArray);
    }

    public char toChar() {
        return (char) value;
    }

    public short toShort() {
        return (short) value;
    }

    public int toInt() {
        return (int) value;
    }

    public long toLong() {
        return (long) value;
    }

    public float toFloat() {
        return (float) value;
    }

    public double toDouble() {
        return value;
    }

    public byte[] toByteArray() {
        return doubleToBytes(value);
    }

    public String toString() {
        return Double.toString(value);
    }

    public Float8Datum add(NumericDatum other) {
        return new Float8Datum(this.value + other.toDouble());
    }

    public Float8Datum subtract(NumericDatum other) {
        return new Float8Datum(this.value - other.toDouble());
    }

    public Float8Datum multiply(NumericDatum other) {
        return new Float8Datum(this.value * other.toDouble());
    }

    public Float8Datum divide(NumericDatum other) {
        return new Float8Datum(this.value / other.toDouble());
    }

    public Float8Datum modulus(NumericDatum other) {
        return new Float8Datum(this.value % other.toDouble());
    }

    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Float8Datum)) return false;
        Float8Datum other = (Float8Datum) obj;
        return Double.compare(this.value, other.value) == 0;
    }

    public int hashCode() {
        long bits = Double.doubleToLongBits(value);
        return (int) (bits ^ (bits >>> 32));
    }

    public int compareTo(Datum other) {
        if (other instanceof Float8Datum) {
            return Double.compare(this.value, ((Float8Datum) other).value);
        }
        return -1; // or some other logic for comparison with different Datum types
    }

    public int size() {
        return Double.BYTES;
    }

    public Float8Datum inverseSign() {
        return new Float8Datum(-this.value);
    }

    private double bytesToDouble(byte[] byteArray) {
        long bits = 0;
        for (int i = 0; i < 8; i++) {
            bits = (bits << 8) | (byteArray[i] & 0xFF);
        }
        return Double.longBitsToDouble(bits);
    }

    private byte[] doubleToBytes(double value) {
        long bits = Double.doubleToLongBits(value);
        return new byte[]{
            (byte) (bits >> 56),
            (byte) (bits >> 48),
            (byte) (bits >> 40),
            (byte) (bits >> 32),
            (byte) (bits >> 24),
            (byte) (bits >> 16),
            (byte) (bits >> 8),
            (byte) bits
        };
    }
}

