class TestSubqueries {

    @PersistenceContext
    private EntityManager entityManager;

    @Test
    public void testExistsSubquery() {
        CriteriaBuilder cb = entityManager.getCriteriaBuilder();
        CriteriaQuery<CompUser> query = cb.createQuery(CompUser.class);
        Root<CompUser> user = query.from(CompUser.class);

        query.select(user).where(cb.exists(
            cb.createQuery().select(cb.literal(1)).from(Order.class).where(cb.equal(Order_.userId, user.get("id")))
        ));

        TypedQuery<CompUser> typedQuery = entityManager.createQuery(query);
        String expectedSQL = "SELECT u FROM CompUser u WHERE EXISTS (SELECT 1 FROM Order o WHERE o.userId = u.id)";
        assertEquals(expectedSQL, typedQuery.unwrap(org.hibernate.query.Query.class).getQueryString());
    }

    @Test
    public void testNotExistsSubquery() {
        CriteriaBuilder cb = entityManager.getCriteriaBuilder();
        CriteriaQuery<CompUser> query = cb.createQuery(CompUser.class);
        Root<CompUser> user = query.from(CompUser.class);

        query.select(user).where(cb.not(cb.exists(
            cb.createQuery().select(cb.literal(1)).from(Order.class).where(cb.equal(Order_.userId, user.get("id")))
        )));

        TypedQuery<CompUser> typedQuery = entityManager.createQuery(query);
        String expectedSQL = "SELECT u FROM CompUser u WHERE NOT EXISTS (SELECT 1 FROM Order o WHERE o.userId = u.id)";
        assertEquals(expectedSQL, typedQuery.unwrap(org.hibernate.query.Query.class).getQueryString());
    }

    @Test
    public void testAnySubquery() {
        CriteriaBuilder cb = entityManager.getCriteriaBuilder();
        CriteriaQuery<CompUser> query = cb.createQuery(CompUser.class);
        Root<CompUser> user = query.from(CompUser.class);

        query.select(user).where(cb.greaterThan(user.get("salary"), cb.any(
            cb.createQuery().select(Address_.salary).from(Address.class)
        )));

        TypedQuery<CompUser> typedQuery = entityManager.createQuery(query);
        String expectedSQL = "SELECT u FROM CompUser u WHERE u.salary > ANY (SELECT a.salary FROM Address a)";
        assertEquals(expectedSQL, typedQuery.unwrap(org.hibernate.query.Query.class).getQueryString());
    }

    @Test
    public void testSubqueryWithJoin() {
        CriteriaBuilder cb = entityManager.getCriteriaBuilder();
        CriteriaQuery<Customer> query = cb.createQuery(Customer.class);
        Root<Customer> customer = query.from(Customer.class);

        query.select(customer).where(cb.exists(
            cb.createQuery().select(cb.literal(1)).from(Order.class)
            .where(cb.equal(Order_.customerId, customer.get("id")))
        ));

        TypedQuery<Customer> typedQuery = entityManager.createQuery(query);
        String expectedSQL = "SELECT c FROM Customer c WHERE EXISTS (SELECT 1 FROM Order o WHERE o.customerId = c.id)";
        assertEquals(expectedSQL, typedQuery.unwrap(org.hibernate.query.Query.class).getQueryString());
    }
}

