        messageCache.put(vertexId, message);
        logger.info("Added message for vertex ID " + vertexId + ": " + message);
    }

    public void removeMessage(int vertexId) {
        if (messageCache.containsKey(vertexId)) {
            messageCache.remove(vertexId);
            logger.info("Removed message for vertex ID " + vertexId);
        } else {
            logger.warning("No message found for vertex ID " + vertexId);
        }
