public class TreeImpl implements Tree {
    private TreeImpl parent;
    private TreeImpl root;
    private List<TreeImpl> children;
    private Map<String, Object> properties;
    private boolean isNew;
    private boolean isModified;
    private boolean isExisting;
    private boolean pendingMove;

    public TreeImpl() {
        this.children = new ArrayList<>();
        this.properties = new HashMap<>();
        this.isNew = true;
        this.isModified = false;
        this.isExisting = false;
        this.pendingMove = false;
    }

    public void addChild(TreeImpl child) {
        if (child != null) {
            child.setParent(this);
            this.children.add(child);
            this.isModified = true;
        }
    }

    public void removeChild(TreeImpl child) {
        if (child != null && this.children.remove(child)) {
            child.setParent(null);
            this.isModified = true;
        }
    }

    public Object getProperty(String key) {
        return properties.get(key);
    }

    public void setProperty(String key, Object value) {
        properties.put(key, value);
        this.isModified = true;
    }

    public boolean hasChild(TreeImpl child) {
        return children.contains(child);
    }

    public boolean isNew() {
        return isNew;
    }

    public boolean isModified() {
        return isModified;
    }

    public boolean isExisting() {
        return isExisting;
    }

    public void setParent(TreeImpl parent) {
        this.parent = parent;
        if (parent != null) {
            this.root = parent.getRoot();
            this.isExisting = true;
            this.isNew = false;
        }
    }

    public TreeImpl getParent() {
        return parent;
    }

    public TreeImpl getRoot() {
        return root;
    }

    public List<TreeImpl> getChildren() {
        return new ArrayList<>(children);
    }

    public String getPath() {
        StringBuilder path = new StringBuilder();
        TreeImpl current = this;
        while (current != null) {
            path.insert(0, "/" + current.getProperty("name"));
            current = current.getParent();
        }
        return path.toString();
    }

    public void setPendingMove(boolean pendingMove) {
        this.pendingMove = pendingMove;
    }

    public boolean isPendingMove() {
        return pendingMove;
    }
}

