class CompressionOverNetworkTest {

    private BrokerService localBroker;
    private BrokerService remoteBroker;
    private Connection connection;
    private Session session;

    @Before
    public void setUp() throws Exception {
        localBroker = new BrokerService();
        localBroker.setPersistent(false);
        localBroker.start();

        remoteBroker = new BrokerService();
        remoteBroker.setPersistent(false);
        remoteBroker.start();

        PooledConnectionFactory connectionFactory = new PooledConnectionFactory();
        connectionFactory.setBrokerURL("tcp://localhost:61616");
        connection = connectionFactory.createConnection();
        connection.start();
        session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
    }

    @After
    public void tearDown() throws Exception {
        session.close();
        connection.close();
        localBroker.stop();
        remoteBroker.stop();
    }

    @Test
    public void testTextMessageCompression() throws Exception {
        String originalMessage = "Test message for compression";
        TextMessage message = session.createTextMessage(originalMessage);
        sendMessage(message);
        TextMessage receivedMessage = receiveMessage();
        assertEquals(originalMessage, receivedMessage.getText());
    }

    @Test
    public void testBytesMessageCompression() throws Exception {
        byte[] originalMessage = "Test bytes message".getBytes();
        BytesMessage message = session.createBytesMessage();
        message.writeBytes(originalMessage);
        sendMessage(message);
        BytesMessage receivedMessage = (BytesMessage) receiveMessage();
        byte[] receivedBytes = new byte[originalMessage.length];
        receivedMessage.readBytes(receivedBytes);
        assertEquals(new String(originalMessage), new String(receivedBytes));
    }

    @Test
    public void testStreamMessageCompression() throws Exception {
        StreamMessage message = session.createStreamMessage();
        message.writeString("Test stream message");
        sendMessage(message);
        StreamMessage receivedMessage = (StreamMessage) receiveMessage();
        assertEquals("Test stream message", receivedMessage.readString());
    }

    @Test
    public void testMapMessageCompression() throws Exception {
        MapMessage message = session.createMapMessage();
        message.setString("key", "Test map message");
        sendMessage(message);
        MapMessage receivedMessage = (MapMessage) receiveMessage();
        assertEquals("Test map message", receivedMessage.getString("key"));
    }

    @Test
    public void testObjectMessageCompression() throws Exception {
        Serializable originalMessage = "Test object message";
        ObjectMessage message = session.createObjectMessage(originalMessage);
        sendMessage(message);
        ObjectMessage receivedMessage = (ObjectMessage) receiveMessage();
        assertEquals(originalMessage, receivedMessage.getObject());
    }

    private void sendMessage(Message message) throws Exception {
        Destination destination = session.createQueue("test.queue");
        MessageProducer producer = session.createProducer(destination);
        producer.send(message);
        producer.close();
    }

    private Message receiveMessage() throws Exception {
        Destination destination = session.createQueue("test.queue");
        MessageConsumer consumer = session.createConsumer(destination);
        return consumer.receive(1000);
    }
}

