class EJBQLTranslationContext {
    private Map<String, Object> compiledExpressions;
    private Map<String, Object> namedParameters;
    private Map<Integer, Object> positionalParameters;
    private Stack<String> aliasStack;
    private boolean caseSensitive;
    private StringBuilder sqlBuffer;
    private int subselectCount;

    public EJBQLTranslationContext() {
        this.compiledExpressions = new HashMap<>();
        this.namedParameters = new HashMap<>();
        this.positionalParameters = new HashMap<>();
        this.aliasStack = new Stack<>();
        this.caseSensitive = false;
        this.sqlBuffer = new StringBuilder();
        this.subselectCount = 0;
    }

    public void addCompiledExpression(String key, Object expression) {
        compiledExpressions.put(key, expression);
    }

    public void addNamedParameter(String name, Object value) {
        namedParameters.put(name, value);
    }

    public void addPositionalParameter(int index, Object value) {
        positionalParameters.put(index, value);
    }

    public void pushAlias(String alias) {
        aliasStack.push(alias);
    }

    public String popAlias() {
        return aliasStack.isEmpty() ? null : aliasStack.pop();
    }

    public void setCaseSensitive(boolean caseSensitive) {
        this.caseSensitive = caseSensitive;
    }

    public void appendToSQLBuffer(String sqlFragment) {
        sqlBuffer.append(sqlFragment);
    }

    public String getSQL() {
        return sqlBuffer.toString();
    }

    public void incrementSubselectCount() {
        subselectCount++;
    }

    public int getSubselectCount() {
        return subselectCount;
    }

    public Map<String, Object> getCompiledExpressions() {
        return compiledExpressions;
    }

    public Map<String, Object> getNamedParameters() {
        return namedParameters;
    }

    public Map<Integer, Object> getPositionalParameters() {
        return positionalParameters;
    }

    public boolean isCaseSensitive() {
        return caseSensitive;
    }
}

