public class RamFileRandomAccessContent implements RandomAccessContent {
    private byte[] buffer;
    private int pointer;

    public RamFileRandomAccessContent() {
        this.buffer = new byte[1024]; // Initial buffer size
        this.pointer = 0;
    }

    @Override
    public void seek(long position) throws IOException {
        if (position < 0 || position > buffer.length) {
            throw new IOException("Invalid seek position");
        }
        pointer = (int) position;
    }

    @Override
    public long getFilePointer() {
        return pointer;
    }

    @Override
    public void write(byte b) throws IOException {
        ensureCapacity(pointer + 1);
        buffer[pointer++] = b;
    }

    @Override
    public void write(byte[] b) throws IOException {
        ensureCapacity(pointer + b.length);
        System.arraycopy(b, 0, buffer, pointer, b.length);
        pointer += b.length;
    }

    @Override
    public byte read() throws IOException {
        if (pointer >= buffer.length) {
            throw new IOException("End of file reached");
        }
        return buffer[pointer++];
    }

    @Override
    public void read(byte[] b) throws IOException {
        if (pointer + b.length > buffer.length) {
            throw new IOException("End of file reached");
        }
        System.arraycopy(buffer, pointer, b, 0, b.length);
        pointer += b.length;
    }

    @Override
    public int available() throws IOException {
        return buffer.length - pointer;
    }

    private void ensureCapacity(int requiredCapacity) {
        if (requiredCapacity > buffer.length) {
            byte[] newBuffer = new byte[Math.max(buffer.length * 2, requiredCapacity)];
            System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
            buffer = newBuffer;
        }
    }

    public InputStream getInputStream() {
        return new InputStream() {
            @Override
            public int read() throws IOException {
                return (pointer < buffer.length) ? buffer[pointer++] : -1;
            }

            @Override
            public int read(byte[] b, int off, int len) throws IOException {
                if (pointer >= buffer.length) {
                    return -1;
                }
                int bytesRead = Math.min(len, buffer.length - pointer);
                System.arraycopy(buffer, pointer, b, off, bytesRead);
                pointer += bytesRead;
                return bytesRead;
            }
        };
    }
}

