public class ChangeSetTestCase extends AbstractTestCase {

    private ChangeSet changeSet;

    @Override
    protected void setUp() throws Exception {
        changeSet = new ChangeSet();
    }

    @Test
    public void testAddEntry() throws Exception {
        changeSet.addEntry("test.txt", new ByteArrayInputStream("Hello World".getBytes()));
        assertTrue(changeSet.containsEntry("test.txt"));
    }

    @Test
    public void testAddDuplicateEntry() throws Exception {
        changeSet.addEntry("test.txt", new ByteArrayInputStream("Hello World".getBytes()));
        changeSet.addEntry("test.txt", new ByteArrayInputStream("Hello Again".getBytes()));
        assertEquals("Hello World", readEntry("test.txt"));
    }

    @Test
    public void testDeleteEntry() throws Exception {
        changeSet.addEntry("test.txt", new ByteArrayInputStream("Hello World".getBytes()));
        changeSet.deleteEntry("test.txt");
        assertFalse(changeSet.containsEntry("test.txt"));
    }

    @Test
    public void testReplaceEntry() throws Exception {
        changeSet.addEntry("test.txt", new ByteArrayInputStream("Hello World".getBytes()));
        changeSet.replaceEntry("test.txt", new ByteArrayInputStream("Replaced Content".getBytes()));
        assertEquals("Replaced Content", readEntry("test.txt"));
    }

    @Test
    public void testAddMultipleEntries() throws Exception {
        changeSet.addEntry("file1.txt", new ByteArrayInputStream("Content 1".getBytes()));
        changeSet.addEntry("file2.txt", new ByteArrayInputStream("Content 2".getBytes()));
        assertTrue(changeSet.containsEntry("file1.txt"));
        assertTrue(changeSet.containsEntry("file2.txt"));
    }

    @Test
    public void testDeleteNonExistentEntry() throws Exception {
        changeSet.deleteEntry("nonexistent.txt");
        assertFalse(changeSet.containsEntry("nonexistent.txt"));
    }

    private String readEntry(String entryName) throws IOException {
        InputStream inputStream = changeSet.getEntryStream(entryName);
        return new BufferedReader(new InputStreamReader(inputStream))
                .lines()
                .collect(Collectors.joining("\n"));
    }
}

