public class ZkCacheBaseDataAccessor<T> implements HelixPropertyStore<T> {
    private final WriteThroughCache<T> writeThroughCache;
    private final ZkCallbackCache<T> zkCallbackCache;
    private final Lock lock = new ReentrantLock();
    private String chrootPath;

    public ZkCacheBaseDataAccessor(String chrootPath) {
        this.chrootPath = chrootPath;
        this.writeThroughCache = new WriteThroughCache<>();
        this.zkCallbackCache = new ZkCallbackCache<>();
    }

    @Override
    public T get(String path) {
        lock.lock();
        try {
            T cachedData = writeThroughCache.get(path);
            if (cachedData != null) {
                return cachedData;
            }
            T data = retrieveFromZk(path);
            writeThroughCache.put(path, data);
            return data;
        } finally {
            lock.unlock();
        }
    }

    @Override
    public void put(String path, T data) {
        lock.lock();
        try {
            writeThroughCache.put(path, data);
            updateZk(path, data);
        } finally {
            lock.unlock();
        }
    }

    @Override
    public void remove(String path) {
        lock.lock();
        try {
            writeThroughCache.remove(path);
            removeFromZk(path);
        } finally {
            lock.unlock();
        }
    }

    @Override
    public List<T> getChildren(String path) {
        lock.lock();
        try {
            return retrieveChildrenFromZk(path);
        } finally {
            lock.unlock();
        }
    }

    public void start() {
        zkCallbackCache.start();
    }

    public void stop() {
        zkCallbackCache.stop();
    }

    public void resetCache() {
        lock.lock();
        try {
            writeThroughCache.clear();
            zkCallbackCache.clear();
        } finally {
            lock.unlock();
        }
    }

    private T retrieveFromZk(String path) {
