        this.processorLifecycleListener = listener;
    }

    public void addInputDescriptor(InputDescriptor inputDescriptor) {
        if (inputDescriptors.contains(inputDescriptor)) {
            throw new IllegalArgumentException("Input descriptor already exists.");
        }
        inputDescriptors.add(inputDescriptor);
    }

    public void addOutputDescriptor(OutputDescriptor outputDescriptor) {
        if (outputDescriptors.contains(outputDescriptor)) {
            throw new IllegalArgumentException("Output descriptor already exists.");
        }
        outputDescriptors.add(outputDescriptor);
    }

    public void addTableDescriptor(TableDescriptor tableDescriptor) {
        if (tableDescriptors.contains(tableDescriptor)) {
            throw new IllegalArgumentException("Table descriptor already exists.");
        }
        tableDescriptors.add(tableDescriptor);
    }

    public void addSerde(Serde serde) {
        if (serdes.contains(serde)) {
            throw new IllegalArgumentException("Serde already exists.");
        }
        serdes.add(serde);
    }

    public ApplicationConfig getApplicationConfig() {
        return applicationConfig;
    }

    public Set<InputDescriptor> getInputDescriptors() {
        return inputDescriptors;
    }

    public Set<OutputDescriptor> getOutputDescriptors() {
        return outputDescriptors;
    }

    public Set<SystemDescriptor> getSystemDescriptors() {
        return systemDescriptors;
    }

    public Set<TableDescriptor> getTableDescriptors() {
        return tableDescriptors;
    }

    public Set<Serde> getSerdes() {
        return serdes;
    }
