        graph.traversal().V().drop().iterate();
        graph.traversal().E().drop().iterate();
    }

    public void addEdgeWithRetry(Vertex outVertex, Vertex inVertex, String label, Map<String, Object> properties, int retries, long delay) {
        for (int i = 0; i < retries; i++) {
            try {
                addEdge(outVertex, inVertex, label, properties);
                return;
            } catch (Exception e) {
                logger.error("Error adding edge, attempt " + (i + 1), e);
                try {
                    TimeUnit.MILLISECONDS.sleep(delay);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }
        logger.error("Failed to add edge after " + retries + " attempts");
