public class AlbertoAggregatorTest extends CamelTestSupport {

    @EndpointInject(uri = "mock:result")
    private MockEndpoint resultEndpoint;

    @Test
    public void testAggregator() throws Exception {
        resultEndpoint.expectedMessageCount(1);

        List<String> names = Arrays.asList("John Doe", "Jane Doe", "Jim Beam", "Jack Daniels");
        template.sendBody("direct:start", names);

        resultEndpoint.assertIsSatisfied();

        Map<String, List<String>> expected = new HashMap<>();
        expected.put("Doe", Arrays.asList("John", "Jane"));
        expected.put("Beam", Arrays.asList("Jim"));
        expected.put("Daniels", Arrays.asList("Jack"));

        Map<String, List<String>> actual = resultEndpoint.getExchanges().get(0).getIn().getBody(Map.class);
        assertEquals(expected, actual);
    }

    @Override
    protected RouteBuilder createRouteBuilder() {
        return new RouteBuilder() {
            @Override
            public void configure() {
                from("direct:start")
                    .log("Received names: ${body}")
                    .split(body())
                    .parallelProcessing()
                    .process(exchange -> {
                        String name = exchange.getIn().getBody(String.class);
                        String[] parts = name.split(" ");
                        String firstName = parts[0];
                        String surname = parts[1];
                        exchange.getIn().setHeader("surname", surname);
                        exchange.getIn().setBody(firstName);
                    })
                    .aggregate(header("surname"), new GroupByAggregationStrategy())
                    .completionSize(4)
                    .to("mock:result");
            }
        };
    }

    private static class GroupByAggregationStrategy implements org.apache.camel.AggregationStrategy {
        @Override
        public Exchange aggregate(Exchange oldExchange, Exchange newExchange) {
            String surname = newExchange.getIn().getHeader("surname", String.class);
            String firstName = newExchange.getIn().getBody(String.class);

            if (oldExchange == null) {
                Map<String, List<String>> map = new HashMap<>();
                map.put(surname, new ArrayList<>(Arrays.asList(firstName)));
                newExchange.getIn().setBody(map);
                return newExchange;
            } else {
                Map<String, List<String>> map = oldExchange.getIn().getBody(Map.class);
                map.get(surname).add(firstName);
                return oldExchange;
            }
        }
    }
}

