public class Dfp implements RealFieldElement<Dfp> {
    private BigDecimal mantissa;
    private int exponent;
    private static final Dfp NaN = new Dfp("NaN");
    private static final Dfp POSITIVE_INFINITY = new Dfp("Infinity");
    private static final Dfp NEGATIVE_INFINITY = new Dfp("-Infinity");

    public Dfp(byte value) {
        this.mantissa = BigDecimal.valueOf(value);
        this.exponent = 0;
    }

    public Dfp(int value) {
        this.mantissa = BigDecimal.valueOf(value);
        this.exponent = 0;
    }

    public Dfp(long value) {
        this.mantissa = BigDecimal.valueOf(value);
        this.exponent = 0;
    }

    public Dfp(double value) {
        if (Double.isNaN(value)) {
            this.mantissa = NaN.mantissa;
            this.exponent = NaN.exponent;
        } else if (Double.isInfinite(value)) {
            this.mantissa = value > 0 ? POSITIVE_INFINITY.mantissa : NEGATIVE_INFINITY.mantissa;
            this.exponent = 0;
        } else {
            this.mantissa = BigDecimal.valueOf(value);
            this.exponent = 0;
        }
    }

    public Dfp(String value) {
        if ("NaN".equals(value)) {
            this.mantissa = NaN.mantissa;
            this.exponent = NaN.exponent;
        } else if ("Infinity".equals(value)) {
            this.mantissa = POSITIVE_INFINITY.mantissa;
            this.exponent = 0;
        } else if ("-Infinity".equals(value)) {
            this.mantissa = NEGATIVE_INFINITY.mantissa;
            this.exponent = 0;
        } else {
            this.mantissa = new BigDecimal(value);
            this.exponent = 0;
        }
    }

    public Dfp add(Dfp other) {
        return new Dfp(this.mantissa.add(other.mantissa).toString());
    }

    public Dfp subtract(Dfp other) {
        return new Dfp(this.mantissa.subtract(other.mantissa).toString());
    }

    public Dfp multiply(Dfp other) {
        return new Dfp(this.mantissa.multiply(other.mantissa).toString());
    }

    public Dfp divide(Dfp other) {
        if (other.mantissa.compareTo(BigDecimal.ZERO) == 0) {
            return this.mantissa.signum() >= 0 ? POSITIVE_INFINITY : NEGATIVE_INFINITY;
        }
        return new Dfp(this.mantissa.divide(other.mantissa, MathContext.DECIMAL128).toString());
    }

    public boolean lessThan(Dfp other) {
        return this.mantissa.compareTo(other.mantissa) < 0;
    }

    public boolean greaterThan(Dfp other) {
        return this.mantissa.compareTo(other.mantissa) > 0;
    }

    public Dfp sqrt() {
        return new Dfp(Math.sqrt(this.mantissa.doubleValue()));
    }

    public Dfp log() {
        return new Dfp(Math.log(this.mantissa.doubleValue()));
    }

    // Additional methods for trigonometric functions can be added here

    public double toDouble() {
        return this.mantissa.doubleValue() * Math.pow(10, this.exponent);
    }

    public String toString() {
        return this.mantissa.toString() + "E" + this.exponent;
    }
}

