public class FingerprintFactory {
    private static final Logger logger = Logger.getLogger(FingerprintFactory.class.getName());
    private final StringEncryptor stringEncryptor;

    public FingerprintFactory(StringEncryptor stringEncryptor) {
        this.stringEncryptor = stringEncryptor;
    }

    public synchronized String createFingerprint(String xmlConfig) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document document = builder.parse(xmlConfig);
            return generateFingerprintFromDocument(document);
        } catch (Exception e) {
            logger.warning("Error parsing XML configuration: " + e.getMessage());
            return null;
        }
    }

    private String generateFingerprintFromDocument(Document document) {
        StringBuilder fingerprintBuilder = new StringBuilder();
        appendFlowRegistries(fingerprintBuilder, document);
        appendProcessGroups(fingerprintBuilder, document);
        appendProcessors(fingerprintBuilder, document);
        appendPorts(fingerprintBuilder, document);
        appendControllerServices(fingerprintBuilder, document);
        return fingerprintBuilder.toString();
    }

    private void appendFlowRegistries(StringBuilder builder, Document document) {
        NodeList flowRegistries = document.getElementsByTagName("flowRegistry");
        for (int i = 0; i < flowRegistries.getLength(); i++) {
            Element registry = (Element) flowRegistries.item(i);
            builder.append(getElementValue(registry, "name"));
        }
    }

    private void appendProcessGroups(StringBuilder builder, Document document) {
        NodeList processGroups = document.getElementsByTagName("processGroup");
        for (int i = 0; i < processGroups.getLength(); i++) {
            Element group = (Element) processGroups.item(i);
            builder.append(getElementValue(group, "id"));
        }
    }

    private void appendProcessors(StringBuilder builder, Document document) {
        NodeList processors = document.getElementsByTagName("processor");
        for (int i = 0; i < processors.getLength(); i++) {
            Element processor = (Element) processors.item(i);
            builder.append(getElementValue(processor, "type"));
        }
    }

    private void appendPorts(StringBuilder builder, Document document) {
        NodeList ports = document.getElementsByTagName("port");
        for (int i = 0; i < ports.getLength(); i++) {
            Element port = (Element) ports.item(i);
            builder.append(getElementValue(port, "name"));
        }
    }

    private void appendControllerServices(StringBuilder builder, Document document) {
        NodeList services = document.getElementsByTagName("controllerService");
        for (int i = 0; i < services.getLength(); i++) {
            Element service = (Element) services.item(i);
            builder.append(getElementValue(service, "id"));
        }
    }

    private String getElementValue(Element element, String tagName) {
        NodeList nodes = element.getElementsByTagName(tagName);
        if (nodes.getLength() > 0) {
            return nodes.item(0).getTextContent();
        } else {
            logger.warning("Missing tag: " + tagName);
            return "";
        }
    }
}

