public class JsonDeserializer implements ODataDeserializer {

    @Override
    public ODataEntity deserializeEntity(InputStream inputStream) {
        // Code smell: Large method, consider breaking down into smaller methods
        JsonParser parser = new JsonParser(inputStream);
        ODataEntity entity = new ODataEntity();

        while (parser.hasNext()) {
            String propertyName = parser.nextProperty();
            Object propertyValue = parseValue(parser);
            entity.addProperty(propertyName, propertyValue);
        }

        return entity;
    }

    @Override
    public ODataEntitySet deserializeEntitySet(InputStream inputStream) {
        ODataEntitySet entitySet = new ODataEntitySet();
        JsonParser parser = new JsonParser(inputStream);

        while (parser.hasNext()) {
            ODataEntity entity = deserializeEntity(parser.nextEntity());
            entitySet.addEntity(entity);
        }

        return entitySet;
    }

    private Object parseValue(JsonParser parser) {
        // Code smell: Method does too much, consider separating concerns
        switch (parser.getCurrentType()) {
            case STRING:
                return parser.nextString();
            case NUMBER:
                return parser.nextNumber();
            case BOOLEAN:
                return parser.nextBoolean();
            case OBJECT:
                return deserializeComplexType(parser.nextObject());
            case ARRAY:
                return deserializeCollectionType(parser.nextArray());
            default:
                return null;
        }
    }

    private ODataComplexType deserializeComplexType(JsonObject jsonObject) {
        ODataComplexType complexType = new ODataComplexType();
        for (String key : jsonObject.keySet()) {
            complexType.addProperty(key, parseValue(jsonObject.get(key)));
        }
        return complexType;
    }

    private List<Object> deserializeCollectionType(JsonArray jsonArray) {
        List<Object> collection = new ArrayList<>();
        for (JsonElement element : jsonArray) {
            collection.add(parseValue(element));
        }
        return collection;
    }

    @Override
    public ODataErrorResponse deserializeErrorResponse(InputStream inputStream) {
        // Code smell: Duplicate logic, consider reusing parseValue
        JsonParser parser = new JsonParser(inputStream);
        ODataErrorResponse errorResponse = new ODataErrorResponse();

        errorResponse.setCode(parser.nextString("code"));
        errorResponse.setMessage(parser.nextString("message"));

        return errorResponse;
    }

    // Additional methods for handling annotations and inline entities can be added here
}

