public class ExchangeHelper {

    public static Object getMandatoryProperty(Exchange exchange, String propertyName) {
        Object value = exchange.getProperty(propertyName);
        if (value == null) {
            throw new IllegalArgumentException("Mandatory property " + propertyName + " is missing");
        }
        return value;
    }

    public static Object getMandatoryHeader(Exchange exchange, String headerName) {
        Object value = exchange.getIn().getHeader(headerName);
        if (value == null) {
            throw new IllegalArgumentException("Mandatory header " + headerName + " is missing");
        }
        return value;
    }

    public static <T> T getMandatoryBody(Exchange exchange, Class<T> type) {
        T body = exchange.getIn().getBody(type);
        if (body == null) {
            throw new IllegalArgumentException("Mandatory body is missing");
        }
        return body;
    }

    public static <T> T convertBody(Exchange exchange, Class<T> type) {
        return exchange.getIn().getBody(type);
    }

    public static void copyResults(Exchange source, Exchange target) {
        target.getIn().setBody(source.getIn().getBody());
        target.getIn().getHeaders().putAll(source.getIn().getHeaders());
    }

    public static Map<String, Object> createVariableMap(Exchange exchange) {
        Map<String, Object> variables = new HashMap<>();
        variables.put("exchange", exchange);
        variables.put("headers", exchange.getIn().getHeaders());
        variables.put("body", exchange.getIn().getBody());
        return variables;
    }

    public static boolean hasCapability(Exchange exchange, String capability) {
        // Assuming capabilities are stored in a property
        return exchange.getProperty("capabilities", String.class).contains(capability);
    }

    public static Object lookupBean(Exchange exchange, String beanId) {
        CamelContext context = exchange.getContext();
        BeanResolver resolver = context.getBeanResolver();
        return resolver.resolveBean(beanId);
    }
}

