public class SimpleRegressionTest {
    private SimpleRegression regression;

    @BeforeEach
    public void setUp() {
        regression = new SimpleRegression();
    }

    @Test
    public void testAddData() {
        regression.addData(1, 2);
        regression.addData(2, 3);
        assertEquals(2.0, regression.getSlope(), 0.001);
        assertEquals(1.0, regression.getIntercept(), 0.001);
    }

    @Test
    public void testCalculateParameters() {
        regression.addData(1, 2);
        regression.addData(2, 3);
        regression.addData(3, 5);
        assertEquals(1.5, regression.getSlope(), 0.001);
        assertEquals(0.5, regression.getIntercept(), 0.001);
        assertEquals(0.5, regression.getRSquared(), 0.001);
    }

    @Test
    public void testHandleNaNValues() {
        regression.addData(1, 2);
        regression.addData(Double.NaN, 3);
        assertThrows(IllegalArgumentException.class, () -> regression.addData(2, Double.NaN));
    }

    @Test
    public void testRemoveData() {
        regression.addData(1, 2);
        regression.addData(2, 3);
        regression.removeData(1, 2);
        assertEquals(0.0, regression.getSlope(), 0.001);
    }

    @Test
    public void testRegressionWithoutIntercept() {
        regression.setIntercept(0);
        regression.addData(1, 1);
        regression.addData(2, 2);
        assertEquals(1.0, regression.getSlope(), 0.001);
    }

    @Test
    public void testPerformanceOnSpecificDataset() {
        for (int i = 0; i < 1000; i++) {
            regression.addData(i, 2 * i + 1);
        }
        assertEquals(2.0, regression.getSlope(), 0.001);
        assertEquals(1.0, regression.getIntercept(), 0.001);
    }

    @Test
    public void testExceptionOnEmptyData() {
        assertThrows(IllegalStateException.class, () -> regression.getSlope());
    }
}

