            assertEquals("value2", future.get());
        }

        executor.shutdown();
    }

    @Test
    public void testInvalidateDuringCallableExecution() throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Future<String> future = executor.submit(() -> {
            try {
                Thread.sleep(100); // Simulate delay
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            return cache.get("key", () -> "value3");
        });

        // Invalidate the cache entry before the callable completes
        cache.invalidate("key");

        assertEquals("value3", future.get());
        executor.shutdown();
