public class RutaFormattedPrinter extends ASTVisitor {
    private FormatterDocument document;
    private IFormatterIndentGenerator indentGenerator;
    private StringBuilder output;
    private int maxLineLength;

    public RutaFormattedPrinter(FormatterDocument document, IFormatterIndentGenerator indentGenerator, int maxLineLength) {
        this.document = document;
        this.indentGenerator = indentGenerator;
        this.output = new StringBuilder();
        this.maxLineLength = maxLineLength;
    }

    @Override
    public void visitStatement(StatementNode node) {
        appendIndent();
        output.append(node.getText());
        output.append("\n");
    }

    @Override
    public void visitExpression(ExpressionNode node) {
        appendIndent();
        output.append(node.getText());
        output.append("\n");
    }

    @Override
    public void visitDeclaration(DeclarationNode node) {
        appendIndent();
        output.append(node.getText());
        output.append("\n");
    }

    private void appendIndent() {
        output.append(indentGenerator.generateIndent());
    }

    public void appendComment(String comment) {
        output.append("// ").append(comment).append("\n");
    }

    public String getFormattedOutput() {
        return output.toString();
    }

    public void handleLongDeclaration(String declaration) {
        if (declaration.length() > maxLineLength) {
            String[] parts = declaration.split(" ");
            StringBuilder currentLine = new StringBuilder();
            for (String part : parts) {
                if (currentLine.length() + part.length() > maxLineLength) {
                    output.append(currentLine.toString().trim()).append("\n");
                    currentLine.setLength(0);
                    appendIndent();
                }
                currentLine.append(part).append(" ");
            }
            output.append(currentLine.toString().trim()).append("\n");
        } else {
            output.append(declaration).append("\n");
        }
    }
}

