    public void testEntityCaching() {
        // Create and persist an entity
        MyEntity entity = new MyEntity();
        entity.setName("Test Entity");
        entityManager.getTransaction().begin();
        entityManager.persist(entity);
        entityManager.getTransaction().commit();

        // Clear cache and assert
        clearCache();
        assertCacheIsEmpty();

        // Retrieve the entity and assert cache contains it
        entityManager.getTransaction().begin();
        MyEntity retrievedEntity = entityManager.find(MyEntity.class, entity.getId());
        entityManager.getTransaction().commit();
        assertCacheContains(MyEntity.class, entity.getId());
