public class MemTable<K, V> extends MemCollection<Pair<K, V>> implements PTable<K, V> {
    private List<Pair<K, V>> data;

    public MemTable() {
        this.data = new ArrayList<>();
    }

    public void add(Pair<K, V> pair) {
        data.add(pair);
    }

    public MemTable<K, V> union(MemTable<K, V> other) {
        MemTable<K, V> result = new MemTable<>();
        result.data.addAll(this.data);
        result.data.addAll(other.data);
        return result;
    }

    public Map<K, List<V>> groupByKey() {
        return data.stream()
                .collect(Collectors.groupingBy(Pair::getKey, 
                        Collectors.mapping(Pair::getValue, Collectors.toList())));
    }

    public void writeTo(Target target) {
        // Implementation for writing data to the target
    }

    public void cache() {
        // Caching logic
    }

    public MemTable<K, V> filterKeys(Function<K, Boolean> predicate) {
        MemTable<K, V> result = new MemTable<>();
        for (Pair<K, V> pair : data) {
            if (predicate.apply(pair.getKey())) {
                result.add(pair);
            }
        }
        return result;
    }

    public MemTable<K, V> filterValues(Function<V, Boolean> predicate) {
        MemTable<K, V> result = new MemTable<>();
        for (Pair<K, V> pair : data) {
            if (predicate.apply(pair.getValue())) {
                result.add(pair);
            }
        }
        return result;
    }

    public List<V> top(int n) {
        return data.stream()
                .map(Pair::getValue)
                .limit(n)
                .collect(Collectors.toList());
    }

    public List<V> bottom(int n) {
        return data.stream()
                .map(Pair::getValue)
                .skip(Math.max(0, data.size() - n))
                .collect(Collectors.toList());
    }

    public MemTable<K, V> join(MemTable<K, V> other) {
        // Implementation for joining with another table
        return new MemTable<>();
    }

    public MemTable<K, V> coGroup(MemTable<K, V> other) {
        // Implementation for co-grouping with another table
        return new MemTable<>();
    }

    public Set<K> extractKeys() {
        return data.stream()
                .map(Pair::getKey)
                .collect(Collectors.toSet());
    }

    public Collection<V> extractValues() {
        return data.stream()
                .map(Pair::getValue)
                .collect(Collectors.toList());
    }

    public Map<K, V> materializeToMap() {
        return data.stream()
                .collect(Collectors.toMap(Pair::getKey, Pair::getValue));
    }
}

