public class RecordBin {
    private static final Logger logger = Logger.getLogger(RecordBin.class.getName());
    private final List<FlowFile> flowFiles;
    private final int maxRecords;
    private final long maxSize;
    private final long maxAge;
    private final ReentrantReadWriteLock lock;
    private final String id;

    public RecordBin(int maxRecords, long maxSize, long maxAge) {
        this.flowFiles = new ArrayList<>();
        this.maxRecords = maxRecords;
        this.maxSize = maxSize;
        this.maxAge = maxAge;
        this.lock = new ReentrantReadWriteLock();
        this.id = generateUniqueId();
    }

    public boolean offer(FlowFile flowFile) {
        lock.writeLock().lock();
        try {
            if (isFull()) {
                logger.warning("Bin is full, cannot add more FlowFiles.");
                return false;
            }
            flowFiles.add(flowFile);
            logger.info("FlowFile added to bin: " + flowFile.getId());
            return true;
        } finally {
            lock.writeLock().unlock();
        }
    }

    public boolean isComplete() {
        lock.readLock().lock();
        try {
            return flowFiles.size() >= maxRecords || getTotalSize() >= maxSize || isAgeExceeded();
        } finally {
            lock.readLock().unlock();
        }
    }

    public void merge() {
        lock.writeLock().lock();
        try {
            if (!isComplete()) {
                logger.warning("Cannot merge, bin is not complete.");
                return;
            }
            // Merging logic here
            logger.info("Merging FlowFiles in bin: " + id);
            // Reset bin after merging
            flowFiles.clear();
        } catch (Exception e) {
            logger.severe("Error during merging: " + e.getMessage());
            rollback();
        } finally {
            lock.writeLock().unlock();
        }
    }

    private boolean isFull() {
        return flowFiles.size() >= maxRecords || getTotalSize() >= maxSize;
    }

    private long getTotalSize() {
        return flowFiles.stream().mapToLong(FlowFile::getSize).sum();
    }

    private boolean isAgeExceeded() {
        long currentTime = System.currentTimeMillis();
        return flowFiles.stream().anyMatch(flowFile -> (currentTime - flowFile.getTimestamp()) > maxAge);
    }

    private void rollback() {
        // Rollback logic here
        logger.info("Rolling back changes in bin: " + id);
    }

    private String generateUniqueId() {
        return java.util.UUID.randomUUID().toString();
    }
}

