public class TextUtils {

    public static String unsignedIntToString(int value) {
        return String.valueOf(value & 0xFFFFFFFFL);
    }

    public static String unsignedLongToString(long value) {
        return String.valueOf(value);
    }

    public static double parseDouble(String str) throws NumberFormatException {
        if ("Infinity".equals(str)) return Double.POSITIVE_INFINITY;
        if ("-Infinity".equals(str)) return Double.NEGATIVE_INFINITY;
        if ("NaN".equals(str)) return Double.NaN;
        return Double.parseDouble(str);
    }

    public static float parseFloat(String str) throws NumberFormatException {
        if ("Infinity".equals(str)) return Float.POSITIVE_INFINITY;
        if ("-Infinity".equals(str)) return Float.NEGATIVE_INFINITY;
        if ("NaN".equals(str)) return Float.NaN;
        return Float.parseFloat(str);
    }

    public static int parseInt(String str) throws NumberFormatException {
        return Integer.parseInt(str);
    }

    public static long parseLong(String str) throws NumberFormatException {
        return Long.parseLong(str);
    }

    public static boolean isHexadecimal(char ch) {
        return Character.isDigit(ch) || (ch >= 'A' && ch <= 'F') || (ch >= 'a' && ch <= 'f');
    }

    public static boolean isOctal(char ch) {
        return ch >= '0' && ch <= '7';
    }

    public static StringBuilder readFromReadable(Readable readable) throws IOException {
        StringBuilder stringBuilder = new StringBuilder();
        char[] buffer = new char[1024];
        int numCharsRead;
        while ((numCharsRead = readable.read(buffer)) != -1) {
            stringBuilder.append(buffer, 0, numCharsRead);
        }
        return stringBuilder;
    }

    public static InputStream stringToInputStream(String str, String charsetName) throws IOException {
        return new java.io.ByteArrayInputStream(str.getBytes(Charset.forName(charsetName)));
    }

    public static String escapeBytes(byte[] bytes) {
        StringBuilder escaped = new StringBuilder();
        for (byte b : bytes) {
            if (b == '\\') {
                escaped.append("\\\\");
            } else if (b == '\"') {
                escaped.append("\\\"");
            } else {
                escaped.append((char) b);
            }
        }
        return escaped.toString();
    }

    public static byte[] unescapeBytes(String str) {
        StringBuilder unescaped = new StringBuilder();
        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if (ch == '\\' && i + 1 < str.length()) {
                char nextCh = str.charAt(i + 1);
                if (nextCh == '\\' || nextCh == '\"') {
                    unescaped.append(nextCh);
                    i++;
                } else {
                    unescaped.append(ch);
                }
            } else {
                unescaped.append(ch);
            }
        }
        return unescaped.toString().getBytes();
    }
}

