public class MessageColumnIORecordConsumer extends RecordConsumer {
    private final FieldsMarker fieldsMarker;
    private final Stack<Integer> groupLevels;
    private int currentColumn;
    private boolean isMessageStarted;

    public MessageColumnIORecordConsumer(FieldsMarker fieldsMarker) {
        this.fieldsMarker = fieldsMarker;
        this.groupLevels = new Stack<>();
        this.currentColumn = -1;
        this.isMessageStarted = false;
    }

    public void startMessage() {
        if (isMessageStarted) {
            log("Message already started.");
            return;
        }
        isMessageStarted = true;
        log("Starting message.");
    }

    public void endMessage() {
        if (!isMessageStarted) {
            log("No message to end.");
            return;
        }
        isMessageStarted = false;
        log("Ending message.");
    }

    public void startGroup() {
        groupLevels.push(currentColumn);
        log("Starting group at column: " + currentColumn);
    }

    public void endGroup() {
        if (groupLevels.isEmpty()) {
            log("No group to end.");
            return;
        }
        currentColumn = groupLevels.pop();
        log("Ending group, returning to column: " + currentColumn);
    }

    public void startField(int column) {
        currentColumn = column;
        fieldsMarker.markField(column);
        log("Starting field at column: " + column);
    }

    public void endField() {
        log("Ending field at column: " + currentColumn);
    }

    public void addInteger(int value) {
        log("Adding integer: " + value);
    }

    public void addLong(long value) {
        log("Adding long: " + value);
    }

    public void addBoolean(boolean value) {
        log("Adding boolean: " + value);
    }

    public void addBinary(byte[] value) {
        log("Adding binary data.");
    }

    public void addFloat(float value) {
        log("Adding float: " + value);
    }

    public void addDouble(double value) {
        log("Adding double: " + value);
    }

    public void addNull() {
        log("Adding null value.");
    }

    private void log(String message) {
        System.out.println(message);
    }
}

