        for (Object entity : entities) {
            processEntity(entity);
            if (deleteAfterProcessing) {
                deleteEntity(entity);
            }
        }
    }

    private List<Object> fetchEntities() {
        Query query = entityManager.createQuery(queryString);
        query.setMaxResults(maxResults);
        return query.getResultList();
    }

    private void processEntity(Object entity) {
        // Processing logic here
        logger.info("Processing entity: " + entity);
    }

    private void deleteEntity(Object entity) {
        entityManager.remove(entity);
        logger.info("Deleted entity: " + entity);
    }
}

public class Asn1ObjectIdentifier extends Asn1Simple<String> {
    private String oidValue;

    public Asn1ObjectIdentifier() {
        this.oidValue = "1.2.840.113549.1.1.1"; // Default OID value
    }

    public Asn1ObjectIdentifier(String oidValue) {
        this.oidValue = oidValue;
    }

    @Override
    public byte[] toBytes() {
        String[] components = oidValue.split("\\.");
        byte[] bytes = new byte[components.length + 1];
        bytes[0] = (byte) (40 * Integer.parseInt(components[0]) + Integer.parseInt(components[1]));

        for (int i = 2; i < components.length; i++) {
            BigInteger component = new BigInteger(components[i]);
            bytes[i] = component.byteValue();
        }

        return bytes;
    }

    @Override
    public String toValue(byte[] bytes) {
        StringBuilder oidBuilder = new StringBuilder();
        int firstComponent = bytes[0] / 40;
        int secondComponent = bytes[0] % 40;
        oidBuilder.append(firstComponent).append('.').append(secondComponent);

        for (int i = 1; i < bytes.length; i++) {
            oidBuilder.append('.').append(Byte.toUnsignedInt(bytes[i]));
        }

        return oidBuilder.toString();
    }
}

