public class SetDataBuilderImpl implements SetDataBuilder {
    private ZooKeeper zooKeeper;
    private String path;
    private byte[] data;
    private int version = -1;
    private boolean compress = false;
    private ErrorListener errorListener;
    private Callback callback;
    private boolean async = false;

    public SetDataBuilderImpl(ZooKeeper zooKeeper) {
        this.zooKeeper = zooKeeper;
    }

    @Override
    public SetDataBuilder withPath(String path) {
        this.path = path;
        return this;
    }

    @Override
    public SetDataBuilder withData(byte[] data) {
        this.data = data;
        return this;
    }

    @Override
    public SetDataBuilder withVersion(int version) {
        this.version = version;
        return this;
    }

    @Override
    public SetDataBuilder withCompression(boolean compress) {
        this.compress = compress;
        return this;
    }

    @Override
    public SetDataBuilder withErrorListener(ErrorListener listener) {
        this.errorListener = listener;
        return this;
    }

    @Override
    public SetDataBuilder withCallback(Callback callback) {
        this.callback = callback;
        return this;
    }

    @Override
    public SetDataBuilder async() {
        this.async = true;
        return this;
    }

    @Override
    public void set() {
        if (async) {
            setDataAsync();
        } else {
            setDataSync();
        }
    }

    private void setDataSync() {
        try {
            Stat stat = zooKeeper.setData(path, data, version);
            if (callback != null) {
                callback.onSuccess(stat);
            }
        } catch (Exception e) {
            handleError(e);
        }
    }

    private void setDataAsync() {
        new Thread(() -> {
            try {
                Stat stat = zooKeeper.setData(path, data, version);
                if (callback != null) {
                    callback.onSuccess(stat);
                }
            } catch (Exception e) {
                handleError(e);
            }
        }).start();
    }

    private void handleError(Exception e) {
        if (errorListener != null) {
            errorListener.onError(e);
        }
    }
}

