public class SimplePrincipalCollection implements MutablePrincipalCollection, Serializable {
    private static final long serialVersionUID = 1L;
    private Map<String, Set<Object>> principalsMap;
    private String primaryRealm;

    public SimplePrincipalCollection() {
        this.principalsMap = new HashMap<>();
    }

    @Override
    public void addPrincipal(Object principal, String realm) {
        principalsMap.computeIfAbsent(realm, k -> new HashSet<>()).add(principal);
        if (primaryRealm == null) {
            primaryRealm = realm;
        }
    }

    @Override
    public Object getPrimaryPrincipal() {
        if (primaryRealm != null) {
            Set<Object> principals = principalsMap.get(primaryRealm);
            if (principals != null && !principals.isEmpty()) {
                return principals.iterator().next();
            }
        }
        return null;
    }

    @Override
    public <T> Collection<T> getPrincipals(Class<T> type) {
        List<T> result = new ArrayList<>();
        for (Set<Object> principals : principalsMap.values()) {
            for (Object principal : principals) {
                if (type.isInstance(principal)) {
                    result.add(type.cast(principal));
                }
            }
        }
        return result;
    }

    @Override
    public boolean isEmpty() {
        return principalsMap.isEmpty();
    }

    @Override
    public void clear() {
        principalsMap.clear();
        primaryRealm = null;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof SimplePrincipalCollection)) return false;
        SimplePrincipalCollection that = (SimplePrincipalCollection) o;
        return Objects.equals(principalsMap, that.principalsMap);
    }

    @Override
    public int hashCode() {
        return Objects.hash(principalsMap);
    }

    @Override
    public String toString() {
        return "SimplePrincipalCollection{" +
                "principalsMap=" + principalsMap +
                ", primaryRealm='" + primaryRealm + '\'' +
                '}';
    }

    private void writeObject(ObjectOutputStream oos) throws IOException {
        oos.defaultWriteObject();
    }

    private void readObject(ObjectInputStream ois) throws IOException, ClassNotFoundException {
        ois.defaultReadObject();
    }
}

public class SelectTypesDialog {
    private Shell shell;
    private Text typeNameInput;
    private Table typesTable;
    private List<String> availableTypes;
    private List<String> selectedTypes;
    private List<String> initialSelection;

    public SelectTypesDialog(Shell parent, List<String> availableTypes, List<String> initialSelection) {
        this.shell = new Shell(parent, SWT.DIALOG_TRIM | SWT.APPLICATION_MODAL);
        this.availableTypes = availableTypes;
        this.initialSelection = initialSelection;
        this.selectedTypes = new ArrayList<>(initialSelection);
        createDialog();
    }

    private void createDialog() {
        shell.setLayout(new GridLayout(2, false));
        shell.setText("Select Types");

        typeNameInput = new Text(shell, SWT.BORDER);
        typeNameInput.setLayoutData(new GridData(SWT.FILL, SWT.CENTER, true, false));
        typeNameInput.addListener(SWT.Modify, e -> filterTypes());

        typesTable = new Table(shell, SWT.CHECK | SWT.BORDER | SWT.V_SCROLL | SWT.H_SCROLL);
        typesTable.setLayoutData(new GridData(SWT.FILL, SWT.FILL, true, true, 2, 1));
        createTableColumns();
        populateTable(availableTypes);

        Button okButton = new Button(shell, SWT.PUSH);
        okButton.setText("OK");
        okButton.addListener(SWT.Selection, e -> confirmSelection());

        Button cancelButton = new Button(shell, SWT.PUSH);
        cancelButton.setText("Cancel");
        cancelButton.addListener(SWT.Selection, e -> shell.dispose());

        shell.pack();
        shell.open();
    }

    private void createTableColumns() {
        TableColumn column = new TableColumn(typesTable, SWT.NONE);
        column.setText("Types");
        column.setWidth(200);
    }

    private void populateTable(List<String> types) {
        typesTable.removeAll();
        for (String type : types) {
            TableItem item = new TableItem(typesTable, SWT.NONE);
            item.setText(type);
            item.setChecked(selectedTypes.contains(type));
        }
    }

    private void filterTypes() {
        String filter = typeNameInput.getText().toLowerCase();
        List<String> filteredTypes = new ArrayList<>();
        for (String type : availableTypes) {
            if (type.toLowerCase().contains(filter)) {
                filteredTypes.add(type);
            }
        }
        populateTable(filteredTypes);
    }

    private void confirmSelection() {
        selectedTypes.clear();
        for (TableItem item : typesTable.getItems()) {
            if (item.getChecked()) {
                selectedTypes.add(item.getText());
            }
        }
        shell.dispose();
    }

    public List<String> getSelectedTypes() {
        return selectedTypes;
    }
}

public abstract class BaseAlgebraVisitor implements AlgebraVisitor {
    private Stack<Object> contextStack = new Stack<>();

    public final void visit(Expression expression) {
        preHook(expression);
        if (expression instanceof Projection) {
            visitProjection((Projection) expression);
        } else if (expression instanceof Join) {
            visitJoin((Join) expression);
        } else if (expression instanceof Filter) {
            visitFilter((Filter) expression);
        } else if (expression instanceof Aggregation) {
            visitAggregation((Aggregation) expression);
        } else if (expression instanceof Literal) {
            visitLiteral((Literal) expression);
        } else {
            throw new UnsupportedOperationException("Unsupported expression type: " + expression.getClass());
        }
        postHook(expression);
    }

    protected void preHook(Expression expression) {
        // Default implementation does nothing
    }

    protected void postHook(Expression expression) {
        // Default implementation does nothing
    }

    protected abstract void visitProjection(Projection projection);

    protected abstract void visitJoin(Join join);

    protected abstract void visitFilter(Filter filter);

    protected abstract void visitAggregation(Aggregation aggregation);

    protected abstract void visitLiteral(Literal literal);
}

