        try (RDFConnection conn = getRDFConnection()) {
            conn.put(model);
            assertTrue(conn.contains(model));
        }
    }

    @Test
    public void testQueryModel() {
        try (RDFConnection conn = getRDFConnection()) {
            Model queriedModel = conn.queryModel("SELECT ?s ?p ?o WHERE { ?s ?p ?o }");
            assertEquals(model.size(), queriedModel.size());
            assertTrue(model.isIsomorphicWith(queriedModel));
        }
    }

    @Test
    public void testTransaction() {
