public class Client extends Thread {
    private Connection connection;
    private Session session;
    private TopicSubscriber subscriber;
    private ConcurrentLinkedQueue<Message> messageQueue = new ConcurrentLinkedQueue<>();
    private Set<String> processedMessageIds = new HashSet<>();
    private boolean isOnline = false;
    private long duration;

    public Client(String brokerUrl, String topicName, long duration) {
        try {
            ConnectionFactory factory = new ActiveMQConnectionFactory(brokerUrl);
            connection = factory.createConnection();
            session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
            Topic topic = session.createTopic(topicName);
            subscriber = session.createSubscriber(topic);
            this.duration = duration;
        } catch (JMSException e) {
            logError("Error initializing JMS client", e);
        }
    }

    public void subscribe() {
        try {
            connection.start();
            isOnline = true;
            subscriber.setMessageListener(this::onMessage);
        } catch (JMSException e) {
            logError("Error subscribing to topic", e);
        }
    }

    public void unsubscribe() {
        try {
            subscriber.close();
            isOnline = false;
        } catch (JMSException e) {
            logError("Error unsubscribing from topic", e);
        }
    }

    private void onMessage(Message message) {
        try {
            String messageId = message.getJMSMessageID();
            if (!processedMessageIds.contains(messageId)) {
                messageQueue.add(message);
                processedMessageIds.add(messageId);
            }
        } catch (JMSException e) {
            logError("Error processing message", e);
        }
    }

    @Override
    public void run() {
        long startTime = System.currentTimeMillis();
        while (isOnline && (System.currentTimeMillis() - startTime) < duration) {
            processMessages();
        }
        cleanup();
    }

    private void processMessages() {
        Message message;
        while ((message = messageQueue.poll()) != null) {
            try {
                // Process the message (placeholder for actual processing logic)
                System.out.println("Processing message: " + message.getBody(String.class));
            } catch (JMSException e) {
                logError("Error retrieving message body", e);
            }
        }
    }

    private void cleanup() {
        try {
            if (session != null) session.close();
            if (connection != null) connection.close();
        } catch (JMSException e) {
            logError("Error during cleanup", e);
        }
    }

    private void logError(String message, Exception e) {
        System.err.println(message + ": " + e.getMessage());
    }
}

