class TestAsyncRateLimitedTable {

    private AsyncRateLimitedTable asyncRateLimitedTable;
    private ScheduledExecutorService executorService;
    private RateLimiter readRateLimiter;
    private RateLimiter writeRateLimiter;
    private DataStore dataStore;

    @BeforeEach
    void setUp() {
        executorService = Executors.newScheduledThreadPool(1);
        readRateLimiter = mock(RateLimiter.class);
        writeRateLimiter = mock(RateLimiter.class);
        dataStore = mock(DataStore.class);
        asyncRateLimitedTable = new AsyncRateLimitedTable(executorService, readRateLimiter, writeRateLimiter, dataStore);
    }

    @Test
    void testGetAsyncCallsReadFunction() {
        String key = "key1";
        when(dataStore.get(key)).thenReturn("value1");

        asyncRateLimitedTable.getAsync(key);

        verify(dataStore, times(1)).get(key);
    }

    @Test
    void testPutAsyncCallsWriteFunction() {
        String key = "key1";
        String value = "value1";

        asyncRateLimitedTable.putAsync(key, value);

        verify(dataStore, times(1)).put(key, value);
    }

    @Test
    void testDeleteAsyncCallsDeleteFunction() {
        String key = "key1";

        asyncRateLimitedTable.deleteAsync(key);

        verify(dataStore, times(1)).delete(key);
    }

