    void testGetAsyncWithNullKeyThrowsException() {
        assertThrows(IllegalArgumentException.class, () -> asyncRateLimitedTable.getAsync(null));
    }

    @Test
    void testPutAsyncWithNullKeyThrowsException() {
        assertThrows(IllegalArgumentException.class, () -> asyncRateLimitedTable.putAsync(null, "value"));
    }

