        assertThrows(IllegalArgumentException.class, () -> new AsyncRateLimitedTable(executorService, null, null, dataStore));
    }

    @Test
    void testRateLimitingOnGetAsync() {
        String key = "key1";
        when(dataStore.get(key)).thenReturn("value1");
        when(readRateLimiter.tryAcquire()).thenReturn(true);

        asyncRateLimitedTable.getAsync(key);

        verify(readRateLimiter, times(1)).tryAcquire();
        verify(dataStore, times(1)).get(key);
    }

    @Test
    void testRateLimitingOnPutAsync() {
        String key = "key1";
        String value = "value1";
        when(writeRateLimiter.tryAcquire()).thenReturn(true);

        asyncRateLimitedTable.putAsync(key, value);

        verify(writeRateLimiter, times(1)).tryAcquire();
        verify(dataStore, times(1)).put(key, value);
    }

    @Test
    void testRateLimitingOnDeleteAsync() {
        String key = "key1";
        when(writeRateLimiter.tryAcquire()).thenReturn(true);

