        if (instance == null) {
            instance = new CarbonProperties(filePath);
        }
        return instance;
    }

    private void loadProperties(String filePath) {
        try (InputStream input = new FileInputStream(filePath)) {
            properties.load(input);
            validateProperties();
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error loading properties file: " + filePath, e);
        }
    }

    private void validateProperties() {
        // Example validation methods
        if (!isValidMemoryAllocation(getProperty("memory.allocation"))) {
            logger.warning("Invalid memory allocation, using default value.");
            properties.setProperty("memory.allocation", "512MB");
        }
        if (!isValidSortingMethod(getProperty("sorting.method"))) {
            logger.warning("Invalid sorting method, using default value.");
            properties.setProperty("sorting.method", "quick");
        }
        // Add more validations as needed
    }

    private boolean isValidMemoryAllocation(String value) {
        // Implement validation logic for memory allocation
        return value != null && value.matches("\\d+MB|\\d+GB");
    }

    private boolean isValidSortingMethod(String value) {
        // Implement validation logic for sorting method
        return value != null && (value.equals("quick") || value.equals("merge") || value.equals("bubble"));
