class StorePerDestinationTest {

    private BrokerService broker;
    private Connection connection;
    private Session session;

    @Before
    public void setUp() throws Exception {
        broker = new BrokerService();
        broker.setPersistent(true);
        broker.setUseJmx(false);
        broker.addConnector("tcp://localhost:61616");
        broker.setBrokerName("testBroker");

        // Configure multiple KahaDB persistence adapters
        PolicyEntry policyEntry = new PolicyEntry();
        policyEntry.setQueue(">");
        policyEntry.setStore(new KahaDB(new File("target/kahadb")));

        broker.setDestinationPolicy(policyEntry);
        broker.start();
        broker.waitUntilStarted();

        ConnectionFactory connectionFactory = new ActiveMQConnectionFactory("tcp://localhost:61616");
        connection = connectionFactory.createConnection();
        connection.start();
        session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
    }

    @Test
    public void testSendAndReceiveMessages() throws Exception {
        Queue queue = session.createQueue("testQueue");
        MessageProducer producer = session.createProducer(queue);
        MessageConsumer consumer = session.createConsumer(queue);

        TextMessage message = session.createTextMessage("Hello, World!");
        producer.send(message);

        TextMessage receivedMessage = (TextMessage) consumer.receive(1000);
        assertNotNull(receivedMessage);
        assertEquals("Hello, World!", receivedMessage.getText());
    }

    @Test
    public void testTransactionCommit() throws Exception {
        Queue queue = session.createQueue("transactionQueue");
        MessageProducer producer = session.createProducer(queue);
        session = connection.createSession(true, Session.SESSION_TRANSACTED);

        TextMessage message = session.createTextMessage("Transactional Message");
        producer.send(message);
        session.commit();

        MessageConsumer consumer = session.createConsumer(queue);
        TextMessage receivedMessage = (TextMessage) consumer.receive(1000);
        assertNotNull(receivedMessage);
        assertEquals("Transactional Message", receivedMessage.getText());
    }

    @Test
    public void testTransactionRollback() throws Exception {
        Queue queue = session.createQueue("rollbackQueue");
        MessageProducer producer = session.createProducer(queue);
        session = connection.createSession(true, Session.SESSION_TRANSACTED);

        TextMessage message = session.createTextMessage("Rollback Message");
        producer.send(message);
        session.rollback();

        MessageConsumer consumer = session.createConsumer(queue);
        TextMessage receivedMessage = (TextMessage) consumer.receive(1000);
        assertNull(receivedMessage);
    }

    @After
    public void tearDown() throws Exception {
        session.close();
        connection.close();
        broker.stop();
        broker.waitUntilStopped();
    }
}

public abstract class BaseGraphBuilder implements GraphBuilder, DataMapListener {
    protected JGraph graph;
    protected GraphModel model;
    protected List<GraphCell> cells;

    public BaseGraphBuilder(JGraph graph) {
        this.graph = graph;
        this.model = graph.getModel();
        this.cells = new ArrayList<>();
        initializeGraph();
    }

    private void initializeGraph() {
        graph.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                handleMouseClick(e);
            }
        });
        model.addGraphModelListener(new GraphModelListener() {
            @Override
            public void graphChanged(GraphModelEvent e) {
                updateGraph(e);
            }
        });
    }

    protected abstract void handleMouseClick(MouseEvent e);

    protected void updateGraph(GraphModelEvent e) {
        // Update graph based on model changes
    }

    public void addCell(GraphCell cell) {
        model.insert(new Object[]{cell}, null, null, null);
        cells.add(cell);
    }

    public void removeCell(GraphCell cell) {
        model.remove(new Object[]{cell});
        cells.remove(cell);
    }

    public void updateCell(GraphCell cell) {
        model.valueForCellChanged(cell, cell.getUserObject());
    }

    public void layoutGraph() {
        JGraphLayout layout = new OrganicLayout();
        layout.run(graph);
    }

    public void undoableEdit() {
        // Implement undoable edit logic
    }

    @Override
    public void onDataMapChange() {
        // Handle data map changes
    }

    public String encodeGraphToXML() {
        StringBuilder xmlBuilder = new StringBuilder();
        xmlBuilder.append("<graph>\n");
        for (GraphCell cell : cells) {
            xmlBuilder.append("\t<cell id=\"").append(cell.getId()).append("\">\n");
            xmlBuilder.append("\t\t<data>").append(cell.getUserObject()).append("</data>\n");
            xmlBuilder.append("\t</cell>\n");
        }
        xmlBuilder.append("</graph>");
        return xmlBuilder.toString();
    }
}

