class FrequencyTest {
    private Frequency frequency;

    @BeforeEach
    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testCountValues() {
        frequency.addValue("apple");
        frequency.addValue("banana");
        frequency.addValue("apple");

        assertEquals(2, frequency.getCount("apple"));
        assertEquals(1, frequency.getCount("banana"));
        assertEquals(3, frequency.getTotalCount());
    }

    @Test
    public void testCumulativeFrequencyAndPercentages() {
        frequency.addValue("apple");
        frequency.addValue("banana");
        frequency.addValue("apple");

        assertEquals(2, frequency.getCumulativeFrequency("apple"));
        assertEquals(1, frequency.getCumulativeFrequency("banana"));
        assertEquals(66.67, frequency.getPercentage("apple"), 0.01);
        assertEquals(33.33, frequency.getPercentage("banana"), 0.01);
    }

    @Test
    public void testHandlingDifferentDataTypes() {
        frequency.addValue(1);
        frequency.addValue(2L);
        frequency.addValue('a');
        frequency.addValue("string");

        assertEquals(1, frequency.getCount(1));
        assertEquals(1, frequency.getCount(2L));
        assertEquals(1, frequency.getCount('a'));
        assertEquals(1, frequency.getCount("string"));
    }

    @Test
    public void testEmptyTableBehavior() {
        assertEquals(0, frequency.getTotalCount());
        assertThrows(IllegalArgumentException.class, () -> frequency.getCount("nonexistent"));
    }

    @Test
    public void testIncrementingValues() {
        frequency.addValue("apple");
        frequency.increment("apple");

        assertEquals(2, frequency.getCount("apple"));
    }

    @Test
    public void testMergingFrequencies() {
        Frequency other = new Frequency();
        other.addValue("apple");
        other.addValue("banana");

        frequency.addValue("apple");
        frequency.merge(other);

        assertEquals(2, frequency.getCount("apple"));
        assertEquals(1, frequency.getCount("banana"));
    }

    @Test
    public void testModeCalculation() {
        frequency.addValue("apple");
        frequency.addValue("banana");
        frequency.addValue("apple");
        frequency.addValue("banana");
        frequency.addValue("banana");

        assertEquals("banana", frequency.getMode());
    }

    @Test
    public void testSerialization() throws Exception {
        frequency.addValue("apple");
        frequency.addValue("banana");

        byte[] serialized = frequency.serialize();
        Frequency deserialized = Frequency.deserialize(serialized);

        assertEquals(frequency.getCount("apple"), deserialized.getCount("apple"));
        assertEquals(frequency.getCount("banana"), deserialized.getCount("banana"));
    }

    @Test
    public void testUniqueCount() {
        frequency.addValue("apple");
        frequency.addValue("banana");
        frequency.addValue("apple");

        assertEquals(2, frequency.getUniqueCount());
    }
}

