        filterValues = new Object[columnInfos.length];
        comparators = new Comparator[columnInfos.length];

        for (int i = 0; i < columnInfos.length; i++) {
            filterValues[i] = columnInfos[i].getFilterValue();
            comparators[i] = getComparator(columnInfos[i].getDataType());
            if (filterValues[i] == null) {
                hasDefaultValues = true;
            }
        }
    }

