    public boolean isScanRequired(Object minValue, Object maxValue) {
        for (Object filterValue : filterValues) {
            if (filterValue != null) {
                if (comparators[0].compare(minValue, filterValue) > 0 || 
                    comparators[0].compare(maxValue, filterValue) < 0) {
                    return true;
                }
            }
        }
        return false;
    }

    public BitSet applyFilter(RawBlockletColumnChunk[] columnChunks) {
        BitSet resultBitSet = new BitSet();
        for (int i = 0; i < columnChunks.length; i++) {
            RawBlockletColumnChunk chunk = columnChunks[i];
            if (isChunkValid(chunk)) {
                for (int j = 0; j < chunk.getRowCount(); j++) {
                    if (matchesFilter(chunk.getValue(j))) {
                        resultBitSet.set(j);
                    }
                }
            }
        }
        return resultBitSet;
    }

