        return true; // Placeholder
    }

    private boolean matchesFilter(Object value) {
        for (Object filterValue : filterValues) {
            if (filterValue != null && comparators[0].compare(value, filterValue) <= 0) {
                return false;
            }
        }
        return true;
    }

    public boolean hasDefaultValues() {
        return hasDefaultValues;
    }
