public class MonitorRandomAccessContent implements RandomAccessContent {
    private final RandomAccessContent content;
    private boolean finished = false;

    public MonitorRandomAccessContent(RandomAccessContent content) {
        this.content = content;
    }

    @Override
    public void read(byte[] buffer, int offset, int length) throws IOException {
        content.read(buffer, offset, length);
    }

    @Override
    public void write(byte[] buffer, int offset, int length) throws IOException {
        content.write(buffer, offset, length);
    }

    @Override
    public long getFilePointer() throws IOException {
        return content.getFilePointer();
    }

    @Override
    public void seek(long position) throws IOException {
        content.seek(position);
    }

    @Override
    public long length() throws IOException {
        return content.length();
    }

    @Override
    public void close() throws IOException {
        if (!finished) {
            try {
                onClose();
            } finally {
                content.close();
                finished = true;
            }
        }
    }

    protected void onClose() {
        // Custom behavior can be implemented in subclasses
    }
}

