public abstract class InputSplitsCallable<K, V, E> implements Callable<Void> {
    protected ZooKeeper zooKeeper;
    protected Metrics metrics;
    protected int vertexCount;
    protected int edgeCount;

    public InputSplitsCallable(ZooKeeper zooKeeper) {
        this.zooKeeper = zooKeeper;
        this.metrics = initializeMetrics();
        this.vertexCount = 0;
        this.edgeCount = 0;
    }

    protected abstract Metrics initializeMetrics();

    protected abstract void readInputSplits();

    protected void logProgress() {
        // Log progress of vertices and edges loaded
        System.out.println("Vertices loaded: " + vertexCount + ", Edges loaded: " + edgeCount);
    }

    @Override
    public Void call() throws Exception {
        try {
            readInputSplits();
            while (hasMoreSplits()) {
                processNextSplit();
                logProgress();
            }
        } catch (Exception e) {
            handleException(e);
        }
        return null;
    }

    protected abstract boolean hasMoreSplits();

    protected abstract void processNextSplit();

    protected void handleException(Exception e) {
        // Handle exceptions that may occur during loading
        System.err.println("Error processing input splits: " + e.getMessage());
    }
}

