public class CsvReader {
    private String filePath;
    private char lineDelimiter;
    private char fieldDelimiter;
    private String commentPrefix;
    private Charset encoding;
    private boolean ignoreInvalidLines;
    private boolean hasHeader;
    private List<Integer> includedFields;

    public CsvReader(String filePath) {
        this.filePath = filePath;
        this.lineDelimiter = '\n';
        this.fieldDelimiter = ',';
        this.commentPrefix = "#";
        this.encoding = Charset.defaultCharset();
        this.ignoreInvalidLines = false;
        this.hasHeader = false;
        this.includedFields = new ArrayList<>();
    }

    public void setLineDelimiter(char lineDelimiter) {
        this.lineDelimiter = lineDelimiter;
    }

    public void setFieldDelimiter(char fieldDelimiter) {
        this.fieldDelimiter = fieldDelimiter;
    }

    public void setCommentPrefix(String commentPrefix) {
        this.commentPrefix = commentPrefix;
    }

    public void setEncoding(Charset encoding) {
        this.encoding = encoding;
    }

    public void setIgnoreInvalidLines(boolean ignoreInvalidLines) {
        this.ignoreInvalidLines = ignoreInvalidLines;
    }

    public void setHasHeader(boolean hasHeader) {
        this.hasHeader = hasHeader;
    }

    public void includeField(int fieldIndex) {
        includedFields.add(fieldIndex);
    }

    public List<String[]> read() throws IOException {
        List<String[]> records = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            if (hasHeader) {
                reader.readLine(); // Skip header
            }
            while ((line = reader.readLine()) != null) {
                if (line.startsWith(commentPrefix)) {
                    continue; // Skip comment lines
                }
                String[] fields = line.split(String.valueOf(fieldDelimiter));
                if (ignoreInvalidLines && fields.length < 1) {
                    continue; // Skip invalid lines
                }
                records.add(filterFields(fields));
            }
        }
        return records;
    }

    private String[] filterFields(String[] fields) {
        if (includedFields.isEmpty()) {
            return fields;
        }
        String[] filtered = new String[includedFields.size()];
        for (int i = 0; i < includedFields.size(); i++) {
            int index = includedFields.get(i);
            if (index < fields.length) {
                filtered[i] = fields[index];
            } else {
                filtered[i] = ""; // Handle missing fields
            }
        }
        return filtered;
    }
}

