public class JasperReportsResult extends StrutsResultSupport implements JasperReportConstants {
    private String reportFormat;
    private String documentName;
    private String contentDisposition;
    private JRDataSource dataSource;
    private Map<String, Object> parameters;

    public void setReportFormat(String reportFormat) {
        this.reportFormat = reportFormat;
    }

    public void setDocumentName(String documentName) {
        this.documentName = documentName;
    }

    public void setContentDisposition(String contentDisposition) {
        this.contentDisposition = contentDisposition;
    }

    public void setDataSource(JRDataSource dataSource) {
        this.dataSource = dataSource;
    }

    public void setParameters(Map<String, Object> parameters) {
        this.parameters = parameters;
    }

    @Override
    public void doExecute(String finalLocation, ActionContext context) throws Exception {
        HttpServletResponse response = (HttpServletResponse) context.get(ServletActionContext.HTTP_RESPONSE);
        response.setContentType(getContentType());
        response.setHeader("Content-Disposition", contentDisposition + "; filename=\"" + documentName + "\"");

        try (OutputStream outputStream = response.getOutputStream()) {
            JasperReport jasperReport = JasperCompileManager.compileReport(finalLocation);
            JasperPrint jasperPrint = JasperFillManager.fillReport(jasperReport, parameters, dataSource);

            if ("pdf".equalsIgnoreCase(reportFormat)) {
                JRPdfExporter exporter = new JRPdfExporter();
                exporter.setExporterInput(new SimpleExporterInput(jasperPrint));
                exporter.setExporterOutput(new SimpleOutputStreamExporterOutput(outputStream));
                exporter.exportReport();
            }
            // Additional formats can be handled here (CSV, HTML, XLS, XML, RTF)
        } catch (JRException e) {
            // Log error (code smell: catch-all exception handling)
            e.printStackTrace(); // Code smell: using printStackTrace for logging
            throw new RuntimeException("Report generation failed", e);
        }
    }

    private String getContentType() {
        switch (reportFormat.toLowerCase()) {
            case "pdf":
                return "application/pdf";
            case "csv":
                return "text/csv";
            case "html":
                return "text/html";
            case "xls":
                return "application/vnd.ms-excel";
            case "xml":
                return "application/xml";
            case "rtf":
                return "application/rtf";
            default:
                return "application/octet-stream"; // Code smell: default case handling
        }
    }
}

