public class TreeComparator {

    private final String sourceFolder;
    private final String targetFolder;

    public TreeComparator(String sourceFolder, String targetFolder) {
        this.sourceFolder = sourceFolder;
        this.targetFolder = targetFolder;
    }

    public void compareTrees(TreeNode source, TreeNode target) {
        if (source == null || target == null) {
            logError("One of the trees is null");
            return;
        }
        compareNodes(source, target);
    }

    private void compareNodes(TreeNode source, TreeNode target) {
        if (!Objects.equals(source.getName(), target.getName())) {
            logError("Node names do not match: " + source.getName() + " vs " + target.getName());
        }

        Map<String, Object> sourceProperties = source.getProperties();
        Map<String, Object> targetProperties = target.getProperties();

        for (String key : sourceProperties.keySet()) {
            if (targetProperties.containsKey(key)) {
                if (!skipBinaryProperty(key) && !Objects.equals(sourceProperties.get(key), targetProperties.get(key))) {
                    logError("Property values do not match for key: " + key);
                }
            } else {
                logError("Property missing in target: " + key);
            }
        }

        for (String key : targetProperties.keySet()) {
            if (!sourceProperties.containsKey(key)) {
                logError("Extra property in target: " + key);
            }
        }

        for (TreeNode child : source.getChildren()) {
            TreeNode matchingChild = target.getChildByName(child.getName());
            if (matchingChild != null) {
                compareNodes(child, matchingChild);
            } else {
                logError("Child node missing in target: " + child.getName());
            }
        }
    }

    private boolean skipBinaryProperty(String key) {
        // Logic to determine if the property is binary and should be skipped
        return key.endsWith("Binary");
    }

    private void logError(String message) {
        System.err.println("Error: " + message);
    }

    public void displayTree(TreeNode node, String prefix) {
        System.out.println(prefix + node.getName());
        for (TreeNode child : node.getChildren()) {
            displayTree(child, prefix + "  ");
        }
    }

    public static void main(String[] args) {
        // Example usage
        TreeNode sourceTree = createExampleTree();
        TreeNode targetTree = createComplexTree();

        TreeComparator comparator = new TreeComparator("sourceFolder", "targetFolder");
        comparator.compareTrees(sourceTree, targetTree);
        comparator.displayTree(sourceTree, "");
        comparator.displayTree(targetTree, "");
    }

    private static TreeNode createExampleTree() {
        TreeNode root = new TreeNode("Root");
        root.addProperty("property1", "value1");
        root.addChild(new TreeNode("Child1"));
        return root;
    }

    private static TreeNode createComplexTree() {
        TreeNode root = new TreeNode("Root");
        root.addProperty("property1", "value2"); // Different value
        root.addChild(new TreeNode("Child1"));
        root.addChild(new TreeNode("Child2"));
        return root;
    }
}

class TreeNode {
    private final String name;
    private final Map<String, Object> properties = new HashMap<>();
    private final List<TreeNode> children = new ArrayList<>();

    public TreeNode(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }

    public Map<String, Object> getProperties() {
        return properties;
    }

    public void addProperty(String key, Object value) {
        properties.put(key, value);
    }

    public List<TreeNode> getChildren() {
        return children;
    }

    public void addChild(TreeNode child) {
        children.add(child);
    }

    public TreeNode getChildByName(String name) {
        for (TreeNode child : children) {
            if (child.getName().equals(name)) {
                return child;
            }
        }
        return null;
    }
}

