    public void testSetVersion() {
        WebXml webXml = new WebXml();
        webXml.setVersion("3.1");
        assertEquals("3.1", webXml.getVersion());

        webXml.setVersion(null);
        assertNull(webXml.getVersion());
    }

    @Test
    public void testMergeFragments() {
        WebXml base = new WebXml();
        base.addServletMapping("servlet1", "/path1");

        WebXml fragment = new WebXml();
        fragment.addServletMapping("servlet2", "/path2");

        base.merge(fragment);
        assertEquals(2, base.getServletMappings().size());

        fragment.addServletMapping("servlet1", "/path3");
        assertThrows(IllegalArgumentException.class, () -> base.merge(fragment));
    }

    @Test
    public void testLifecycleMethods() {
        WebXml webXml = new WebXml();
        webXml.postConstruct();
        assertTrue(webXml.isPostConstructCalled());

        webXml.preDestroy();
        assertTrue(webXml.isPreDestroyCalled());
    }

    @Test
    public void testConflictOnMerging() {
        WebXml base = new WebXml();
        base.addServletMapping("servlet1", "/path1");

        WebXml fragment = new WebXml();
        fragment.addServletMapping("servlet1", "/path2");

        assertThrows(IllegalArgumentException.class, () -> base.merge(fragment));
    }

    @Test
    public void testDuplicateServletMapping() {
