public class DefaultRemoteManagerImplementation implements RemoteManager {
    private static final Logger logger = Logger.getLogger(DefaultRemoteManagerImplementation.class.getName());
    private final TransportLayer transportLayer;
    private final Map<String, MessageHandler> handlers = new HashMap<>();
    private final AtomicInteger sequenceNumberGenerator = new AtomicInteger(0);
    private boolean isActive = true;

    public DefaultRemoteManagerImplementation(TransportLayer transportLayer) {
        this.transportLayer = transportLayer;
        startReceiver();
    }

    @Override
    public void registerHandler(String messageType, MessageHandler handler) {
        handlers.put(messageType, handler);
        logger.info("Handler registered for message type: " + messageType);
    }

    @Override
    public void sendMessage(String messageType, String message) {
        if (!isActive) {
            logger.warning("Attempted to send message while manager is inactive.");
            return;
        }
        int sequenceNumber = sequenceNumberGenerator.incrementAndGet();
        transportLayer.send(messageType, message, sequenceNumber);
        logger.info("Sent message of type: " + messageType + " with sequence number: " + sequenceNumber);
    }

    private void startReceiver() {
        new Thread(() -> {
            while (isActive) {
                try {
                    Message receivedMessage = transportLayer.receive();
                    handleReceivedMessage(receivedMessage);
                } catch (Exception e) {
                    logger.severe("Error receiving message: " + e.getMessage());
                }
            }
        }).start();
    }

    private void handleReceivedMessage(Message message) {
        MessageHandler handler = handlers.get(message.getType());
        if (handler != null) {
            handler.handle(message);
            logger.info("Handled received message of type: " + message.getType());
        } else {
            logger.warning("No handler registered for message type: " + message.getType());
        }
    }

    @Override
    public void close() {
        isActive = false;
        transportLayer.close();
        logger.info("Closed DefaultRemoteManagerImplementation and released resources.");
    }
}

