public class RowImpl implements Row {
    private Object[] values;
    private String[] types;
    private boolean isFlushed;
    private boolean isNewRow;
    private String primaryKey;
    private String foreignKey;

    public RowImpl(int columnCount) {
        this.values = new Object[columnCount];
        this.types = new String[columnCount];
        this.isFlushed = false;
        this.isNewRow = true;
    }

    public void setValue(int columnIndex, Object value, String type) {
        if (columnIndex < 0 || columnIndex >= values.length) {
            throw new IndexOutOfBoundsException("Column index out of bounds");
        }
        values[columnIndex] = value;
        types[columnIndex] = type;
    }

    public Object getValue(int columnIndex) {
        if (columnIndex < 0 || columnIndex >= values.length) {
            throw new IndexOutOfBoundsException("Column index out of bounds");
        }
        return values[columnIndex];
    }

    public String getSQLInsertStatement(String tableName) {
        StringBuilder sql = new StringBuilder("INSERT INTO " + tableName + " (");
        StringBuilder valuesPart = new StringBuilder(" VALUES (");
        for (int i = 0; i < values.length; i++) {
            sql.append("column").append(i);
            valuesPart.append("?"); // Placeholder for prepared statement
            if (i < values.length - 1) {
                sql.append(", ");
                valuesPart.append(", ");
            }
        }
        sql.append(")").append(valuesPart).append(");");
        return sql.toString();
    }

    public String getSQLUpdateStatement(String tableName) {
        StringBuilder sql = new StringBuilder("UPDATE " + tableName + " SET ");
        for (int i = 0; i < values.length; i++) {
            sql.append("column").append(i).append(" = ?");
            if (i < values.length - 1) {
                sql.append(", ");
            }
        }
        sql.append(" WHERE ").append(primaryKey).append(" = ?;");
        return sql.toString();
    }

    public String getSQLDeleteStatement(String tableName) {
