        RowImpl clonedRow = new RowImpl(values.length);
        clonedRow.values = Arrays.copyOf(this.values, this.values.length);
        clonedRow.types = Arrays.copyOf(this.types, this.types.length);
        clonedRow.isFlushed = this.isFlushed;
        clonedRow.isNewRow = this.isNewRow;
