public class TestFBRules extends TestCase {

    private ForwardBackwardReasoner reasoner;
    private RDFGraph graph;

    @Override
    protected void setUp() throws Exception {
        super.setUp();
        graph = new RDFGraph();
        reasoner = new ForwardBackwardReasoner(graph);
        initializeTestData();
    }

    private void initializeTestData() {
        // Initialize RDF nodes and predicates
        RDFNode nodeA = new RDFNode("A");
        RDFNode nodeB = new RDFNode("B");
        RDFNode nodeC = new RDFNode("C");
        RDFPredicate predicateP = new RDFPredicate("P");
        RDFPredicate predicateQ = new RDFPredicate("Q");

        graph.addTriple(nodeA, predicateP, nodeB);
        graph.addTriple(nodeB, predicateQ, nodeC);
    }

    public void testRuleParsing() {
        String rule = "P(A, B) -> Q(B, C)";
        boolean parsed = reasoner.parseRule(rule);
        assertTrue(parsed);
    }

    public void testRuleMatching() {
        String rule = "P(X, Y) -> Q(Y, Z)";
        reasoner.parseRule(rule);
        boolean matches = reasoner.matchRule(rule);
        assertTrue(matches);
    }

    public void testApplyBuiltInFunction() {
        String rule = "P(X, Y) -> BuiltInFunction(X, Y)";
        reasoner.parseRule(rule);
        boolean applied = reasoner.applyBuiltInFunction("BuiltInFunction", 5, 10);
        assertTrue(applied);
    }

    public void testInferenceGraphCreation() {
        String rule = "P(X, Y) -> Q(Y, Z)";
        reasoner.parseRule(rule);
        InferenceGraph inferenceGraph = reasoner.createInferenceGraph();
        assertNotNull(inferenceGraph);
        assertTrue(inferenceGraph.hasInference("Q(B, C)"));
    }

    public void testExpectedDeductions() {
        String rule = "P(X, Y) -> Q(Y, Z)";
        reasoner.parseRule(rule);
        reasoner.applyRules();
        assertTrue(reasoner.hasDeduction("Q(B, C)"));
    }

    public void testArithmeticOperations() {
        String rule = "P(X, Y) -> Result(X + Y)";
        reasoner.parseRule(rule);
        int result = reasoner.evaluateArithmetic("Result(5 + 10)");
        assertEquals(15, result);
    }

    public void testStringManipulations() {
        String rule = "P(X, Y) -> Result(CONCAT(X, Y))";
        reasoner.parseRule(rule);
        String result = reasoner.evaluateStringManipulation("Result(CONCAT('Hello', 'World'))");
        assertEquals("HelloWorld", result);
    }

    @Override
    protected void tearDown() throws Exception {
        super.tearDown();
        graph.clear();
        reasoner = null;
    }
}

