class KTableFilterTest {

    private TopologyTestDriver testDriver;
    private ConsumerRecordFactory<String, Integer> recordFactory;

    @Before
    public void setUp() {
        Properties props = new Properties();
        props.put("application.id", "ktable-filter-test");
        props.put("bootstrap.servers", "dummy:1234");
        testDriver = new TopologyTestDriver(buildTopology(), props);
        recordFactory = new ConsumerRecordFactory<>("input-topic", new StringSerializer(), new IntegerSerializer());
    }

    private Topology buildTopology() {
        Topology topology = new Topology();
        topology.addSource("Source", "input-topic");
        topology.addProcessor("FilterProcessor", () -> new FilterProcessor(), "Source");
        topology.addSink("Sink", "output-topic", "FilterProcessor");
        return topology;
    }

    @Test
    public void testFilterEvenValues() {
        testDriver.pipeInput(recordFactory.create("input-topic", "key1", 1));
        testDriver.pipeInput(recordFactory.create("input-topic", "key2", 2));
        testDriver.pipeInput(recordFactory.create("input-topic", "key3", 3));

        OutputVerifier.compareKeyValue(testDriver.readOutput("output-topic", new StringDeserializer(), new IntegerDeserializer()), "key2", 2);
        assertEquals(null, testDriver.readOutput("output-topic", new StringDeserializer(), new IntegerDeserializer()));
    }

    @Test
    public void testFilterWithMaterialization() {
        KTable<String, Integer> kTable = builder.table("input-topic", Materialized.as("materialized-store"));
        kTable.filter((key, value) -> value % 2 == 0);

        testDriver.pipeInput(recordFactory.create("input-topic", "key1", 1));
        testDriver.pipeInput(recordFactory.create("input-topic", "key2", 2));

        OutputVerifier.compareKeyValue(testDriver.readOutput("output-topic", new StringDeserializer(), new IntegerDeserializer()), "key2", 2);
    }

    @Test
    public void testOldValueHandling() {
        testDriver.pipeInput(recordFactory.create("input-topic", "key1", 2));
        testDriver.pipeInput(recordFactory.create("input-topic", "key1", 3));

        OutputVerifier.compareKeyValue(testDriver.readOutput("output-topic", new StringDeserializer(), new IntegerDeserializer()), "key1", 3);
    }

    @Test
    public void testSkipNullValues() {
        testDriver.pipeInput(recordFactory.create("input-topic", "key1", null));
        testDriver.pipeInput(recordFactory.create("input-topic", "key2", 4));

        OutputVerifier.compareKeyValue(testDriver.readOutput("output-topic", new StringDeserializer(), new IntegerDeserializer()), "key2", 4);
        assertEquals(null, testDriver.readOutput("output-topic", new StringDeserializer(), new IntegerDeserializer()));
    }

    @After
    public void tearDown() {
        testDriver.close();
    }
}

