class TestLocalTableWrite {
    private LocalTable localTable;
    private KeyValueStore keyValueStore;
    private Metrics metrics;

    @Before
    public void setUp() {
        keyValueStore = new KeyValueStore();
        metrics = new Metrics();
        localTable = new LocalTable(keyValueStore, metrics);
    }

    @Test
    public void testPut() {
        String key = "key1";
        String value = "value1";
        localTable.put(key, value);

        assertEquals(value, keyValueStore.get(key));
        assertEquals(1, metrics.getPutCount());
        assertTrue(metrics.getPutTime() > 0);
    }

    @Test
    public void testPutAll() {
        Map<String, String> entries = new HashMap<>();
        entries.put("key1", "value1");
        entries.put("key2", "value2");
        localTable.putAll(entries);

        assertEquals("value1", keyValueStore.get("key1"));
        assertEquals("value2", keyValueStore.get("key2"));
        assertEquals(2, metrics.getPutCount());
        assertTrue(metrics.getPutTime() > 0);
    }

    @Test
    public void testDelete() {
        String key = "key1";
        localTable.put(key, "value1");
        localTable.delete(key);

        assertNull(keyValueStore.get(key));
        assertEquals(1, metrics.getDeleteCount());
        assertTrue(metrics.getDeleteTime() > 0);
    }

    @Test
    public void testDeleteAll() {
        Map<String, String> entries = new HashMap<>();
        entries.put("key1", "value1");
        entries.put("key2", "value2");
        localTable.putAll(entries);
        localTable.deleteAll(entries.keySet());

        assertNull(keyValueStore.get("key1"));
        assertNull(keyValueStore.get("key2"));
        assertEquals(2, metrics.getDeleteCount());
        assertTrue(metrics.getDeleteTime() > 0);
    }

    @Test
    public void testFlush() {
        localTable.put("key1", "value1");
        localTable.flush();

        assertEquals("value1", keyValueStore.get("key1"));
        assertEquals(1, metrics.getFlushCount());
        assertTrue(metrics.getFlushTime() > 0);
    }

    @Test
    public void testTimersDisabled() {
        metrics.setTimersEnabled(false);
        localTable.put("key1", "value1");

        assertEquals(1, metrics.getPutCount());
        assertEquals(0, metrics.getPutTime());
    }
}

public class FileUtils {
    private static final Logger logger = Logger.getLogger(FileUtils.class.getName());

    public static void closeQuietly(Closeable resource) {
        if (resource != null) {
            try {
                resource.close();
            } catch (IOException e) {
                // Log the exception quietly
                logger.warning("Failed to close resource: " + e.getMessage());
            }
        }
    }

    public static void releaseLockQuietly(FileLock lock) {
        if (lock != null) {
            try {
                lock.release();
            } catch (IOException e) {
                // Log the exception quietly
                logger.warning("Failed to release lock: " + e.getMessage());
            }
        }
    }

    public static void ensureDirectoryExists(Path path) throws IOException {
        if (!Files.exists(path)) {
            Files.createDirectories(path);
        }
        if (!Files.isReadable(path) || !Files.isWritable(path)) {
            throw new IOException("Directory does not have the necessary permissions: " + path);
        }
    }

    public static boolean deleteWithRetry(Path path, int retries) {
        for (int i = 0; i < retries; i++) {
            try {
                if (Files.isDirectory(path)) {
                    Files.walk(path)
                         .sorted(Comparator.reverseOrder())
                         .map(Path::toFile)
                         .forEach(File::delete);
                }
                return Files.deleteIfExists(path);
            } catch (IOException e) {
                logger.warning("Failed to delete " + path + ": " + e.getMessage());
            }
        }
        return false;
    }

    public static void shredFile(Path path) throws IOException {
        if (Files.exists(path)) {
            try (RandomAccessFile file = new RandomAccessFile(path.toFile(), "rw")) {
                long length = file.length();
                file.setLength(length);
                for (long i = 0; i < length; i++) {
                    file.writeByte((int) (Math.random() * 256));
                }
                file.setLength(0);
            }
            Files.delete(path);
        }
    }

    public static void copyFile(Path source, Path target, boolean move) throws IOException {
        if (move) {
            Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
        } else {
            Files.copy(source, target, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    public static boolean renameWithRetry(Path source, Path target, int retries) {
        for (int i = 0; i < retries; i++) {
            try {
                Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
                return true;
            } catch (IOException e) {
                logger.warning("Failed to rename " + source + " to " + target + ": " + e.getMessage());
            }
        }
        return false;
    }

    public static void synchronizeFiles(Path source, Path target) throws IOException {
        if (!Files.isSameFile(source, target)) {
            Files.copy(source, target, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    public static String computeMD5(Path path) throws IOException {
        try (InputStream is = Files.newInputStream(path)) {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
            StringBuilder sb = new StringBuilder();
            for (byte b : md.digest()) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IOException("MD5 algorithm not found", e);
        }
    }

    public static long getContainerCapacity(Path path) throws IOException {
        return Files.getFileStore(path).getTotalSpace();
    }

    public static long getUsableSpace(Path path) throws IOException {
        return Files.getFileStore(path).getUsableSpace();
    }
}

public class SAMLTokenRenewerTest {

    private TokenStore tokenStore;
    private CryptoFactory cryptoFactory;
    private CallbackHandler callbackHandler;
    private SAMLTokenRenewer tokenRenewer;

    @BeforeEach
    public void setUp() {
        tokenStore = new InMemoryTokenStore();
        cryptoFactory = new DefaultCryptoFactory();
        callbackHandler = new SimpleCallbackHandler();
        tokenRenewer = new SAMLTokenRenewer(tokenStore, cryptoFactory, callbackHandler);
    }

    @Test
    public void testRenewValidSAMLAssertion() {
        SAMLAssertion originalAssertion = createValidSAMLAssertion();
        tokenStore.store(originalAssertion);

        SAMLAssertion renewedAssertion = tokenRenewer.renew(originalAssertion);
        assertNotNull(renewedAssertion);
        assertNotEquals(originalAssertion.getId(), renewedAssertion.getId());
        assertTrue(renewedAssertion.isValid());
    }

    @Test
    public void testRenewExpiredSAMLAssertion() {
        SAMLAssertion expiredAssertion = createExpiredSAMLAssertion();
        tokenStore.store(expiredAssertion);

        assertThrows(TokenExpiredException.class, () -> {
            tokenRenewer.renew(expiredAssertion);
        });
    }

    @Test
    public void testRenewNotAllowedSAMLAssertion() {
        SAMLAssertion nonRenewableAssertion = createNonRenewableSAMLAssertion();
        tokenStore.store(nonRenewableAssertion);

        assertThrows(RenewalNotAllowedException.class, () -> {
            tokenRenewer.renew(nonRenewableAssertion);
        });
    }

    @Test
    public void testRenewSAMLAssertionWithInvalidSignature() {
        SAMLAssertion invalidSignatureAssertion = createSAMLAssertionWithInvalidSignature();
        tokenStore.store(invalidSignatureAssertion);

        assertThrows(InvalidSignatureException.class, () -> {
            tokenRenewer.renew(invalidSignatureAssertion);
        });
    }

    private SAMLAssertion createValidSAMLAssertion() {
        // Implementation to create a valid SAML assertion
        return new SAMLAssertion("valid-id", true, false);
    }

    private SAMLAssertion createExpiredSAMLAssertion() {
        // Implementation to create an expired SAML assertion
        return new SAMLAssertion("expired-id", false, false);
    }

    private SAMLAssertion createNonRenewableSAMLAssertion() {
        // Implementation to create a non-renewable SAML assertion
        return new SAMLAssertion("non-renewable-id", true, true);
    }

    private SAMLAssertion createSAMLAssertionWithInvalidSignature() {
        // Implementation to create a SAML assertion with an invalid signature
        return new SAMLAssertion("invalid-signature-id", true, false, false);
    }
}

