public class TestCascades extends AbstractTestCase {

    public void testPersistCascade() {
        CascadesEntity parent = new CascadesEntity();
        CascadesEntity child = new CascadesEntity();
        parent.setChild(child);
        entityManager.persist(parent);
        entityManager.flush();

        assertNotNull(child.getId());
    }

    public void testRemoveCascade() {
        CascadesEntity parent = new CascadesEntity();
        CascadesEntity child = new CascadesEntity();
        parent.setChild(child);
        entityManager.persist(parent);
        entityManager.flush();

        entityManager.remove(parent);
        entityManager.flush();

        assertNull(entityManager.find(CascadesEntity.class, child.getId()));
    }

    public void testRefreshCascade() {
        CascadesEntity parent = new CascadesEntity();
        CascadesEntity child = new CascadesEntity();
        parent.setChild(child);
        entityManager.persist(parent);
        entityManager.flush();

        child.setSomeProperty("newValue");
        entityManager.refresh(parent);

        assertEquals("newValue", child.getSomeProperty());
    }

    public void testNonCascadePersist() {
        CascadesEntity parent = new CascadesEntity();
        CascadesEntity child = new CascadesEntity();
        parent.setChild(child);
        entityManager.persist(parent);
        entityManager.flush();

        assertNotNull(entityManager.find(CascadesEntity.class, parent.getId()));
        assertNull(entityManager.find(CascadesEntity.class, child.getId()));
    }

    public void testCircularReference() {
        CascadesEntity parent = new CascadesEntity();
        CascadesEntity child = new CascadesEntity();
        parent.setChild(child);
        child.setParent(parent);
        entityManager.persist(parent);
        entityManager.flush();

        assertNotNull(entityManager.find(CascadesEntity.class, parent.getId()));
        assertNotNull(entityManager.find(CascadesEntity.class, child.getId()));
    }

    public void testTransientState() {
        CascadesEntity parent = new CascadesEntity();
        CascadesEntity child = new CascadesEntity();
        parent.setChild(child);

        entityManager.persist(parent);
        entityManager.flush();

        child.setSomeProperty("changed");
        assertEquals("changed", child.getSomeProperty());
    }

    public void testInvalidOperation() {
        try {
            CascadesEntity parent = new CascadesEntity();
            entityManager.remove(parent);
            fail("Expected an exception to be thrown");
        } catch (IllegalArgumentException e) {
            // Expected exception
        }
    }
}

