    @Test
    public void testRoundTripSerialization() throws Exception {
        Configuration config = new Configuration();
        config.setStrings(new HashSet<>(Arrays.asList("one", "two", "three")));

        // Serialize
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Encoder encoder = EncoderFactory.get().binaryEncoder(outputStream, null);
        SpecificDatumWriter<Configuration> writer = new SpecificDatumWriter<>(Configuration.class);
        writer.write(config, encoder);
        encoder.flush();

        // Deserialize
        ByteArrayInputStream inputStream = new ByteArrayInputStream(outputStream.toByteArray());
        Decoder decoder = DecoderFactory.get().binaryDecoder(inputStream, null);
        SpecificDatumReader<Configuration> reader = new SpecificDatumReader<>(Configuration.class);
        Configuration deserializedConfig = reader.read(null, decoder);

        assertEquals(config.getStrings(), deserializedConfig.getStrings());
    }
}

