public abstract class AbstractStep<S, E> {
    protected String stepId;
    protected Set<String> labels;
    protected AbstractStep<S, E> previousStep;
    protected AbstractStep<S, E> nextStep;
    protected TraversalContext<S, E> traversalContext;

    public AbstractStep() {
        this.labels = new HashSet<>();
    }

    public String getStepId() {
        return stepId;
    }

    public void setStepId(String stepId) {
        this.stepId = stepId;
    }

    public Set<String> getLabels() {
        return labels;
    }

    public void addLabel(String label) {
        labels.add(label);
    }

    public void removeLabel(String label) {
        labels.remove(label);
    }

    public void setPreviousStep(AbstractStep<S, E> previousStep) {
        this.previousStep = previousStep;
    }

    public AbstractStep<S, E> getPreviousStep() {
        return previousStep;
    }

    public void setNextStep(AbstractStep<S, E> nextStep) {
        this.nextStep = nextStep;
    }

    public AbstractStep<S, E> getNextStep() {
        return nextStep;
    }

    public void setTraversalContext(TraversalContext<S, E> traversalContext) {
        this.traversalContext = traversalContext;
    }

    public TraversalContext<S, E> getTraversalContext() {
        return traversalContext;
    }

    public abstract void addStartingTraversers(Traverser<S> traverser);

    public abstract void reset();

    public abstract boolean hasNextTraverser();

    public abstract Traverser<E> processNextTraverser();

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof AbstractStep)) return false;
        AbstractStep<?, ?> that = (AbstractStep<?, ?>) obj;
        return stepId.equals(that.stepId) && labels.equals(that.labels);
    }

    @Override
    public int hashCode() {
        int result = stepId.hashCode();
        result = 31 * result + labels.hashCode();
        return result;
    }

    @Override
    protected AbstractStep<S, E> clone() {
        try {
            return (AbstractStep<S, E>) super.clone();
        } catch (CloneNotSupportedException e) {
            throw new AssertionError(); // Can't happen
        }
    }
}

