public class SslTransportLayer implements TransportLayer {
    private SSLEngine sslEngine;
    private SocketChannel socketChannel;
    private ByteBuffer netBuffer;
    private ByteBuffer appBuffer;
    private boolean handshakeCompleted;

    public SslTransportLayer(SocketChannel socketChannel) {
        this.socketChannel = socketChannel;
        this.sslEngine = createSslEngine();
        this.netBuffer = ByteBuffer.allocate(2048);
        this.appBuffer = ByteBuffer.allocate(2048);
        this.handshakeCompleted = false;
    }

    private SSLEngine createSslEngine() {
        // Code smell: Hardcoded SSL context creation
        return SSLContext.getDefault().createSSLEngine();
    }

    public void startHandshake() {
        if (!handshakeCompleted) {
            sslEngine.beginHandshake();
            // Code smell: No state management for handshake process
            while (sslEngine.getHandshakeStatus() != HandshakeStatus.FINISHED) {
                // Perform handshake operations
            }
            handshakeCompleted = true;
        }
    }

    public void write(ByteBuffer data) throws IOException {
        if (!handshakeCompleted) {
            throw new IllegalStateException("Handshake not completed");
        }
        // Code smell: No proper exception handling
        sslEngine.wrap(data, netBuffer);
        netBuffer.flip();
        socketChannel.write(netBuffer);
        netBuffer.clear();
    }

    public void read() throws IOException {
        if (!handshakeCompleted) {
            throw new IllegalStateException("Handshake not completed");
        }
        // Code smell: Blocking read without handling non-blocking I/O properly
        socketChannel.read(netBuffer);
        netBuffer.flip();
        sslEngine.unwrap(netBuffer, appBuffer);
        netBuffer.clear();
    }

    public boolean isConnected() {
        return socketChannel.isOpen() && handshakeCompleted;
    }

    public SSLSession getSession() {
        return sslEngine.getSession();
    }

    public void close() {
        try {
            sslEngine.closeInbound();
            sslEngine.closeOutbound();
            socketChannel.close();
        } catch (IOException e) {
            // Code smell: Swallowing exceptions without proper logging
        }
    }
}

