public class NodeClusterCoordinator {
    private final Set<Node> nodes = ConcurrentHashMap.newKeySet();
    private final AtomicReference<Node> leader = new AtomicReference<>();
    private final Map<Node, NodeStatus> nodeStatuses = new ConcurrentHashMap<>();

    public void connectNode(Node node) {
        nodes.add(node);
        nodeStatuses.put(node, NodeStatus.CONNECTED);
        notifyNodeStatusChange(node, NodeStatus.CONNECTED);
        electLeader();
    }

    public void disconnectNode(Node node) {
        nodes.remove(node);
        nodeStatuses.put(node, NodeStatus.DISCONNECTED);
        notifyNodeStatusChange(node, NodeStatus.DISCONNECTED);
        electLeader();
    }

    public void offloadNode(Node node) {
        if (nodes.contains(node)) {
            nodeStatuses.put(node, NodeStatus.OFFLOADED);
            notifyNodeStatusChange(node, NodeStatus.OFFLOADED);
        }
    }

    public void reportEvent(Node node, String event) {
        // Handle event reporting logic
        System.out.println("Event from " + node.getId() + ": " + event);
    }

    private void notifyNodeStatusChange(Node node, NodeStatus status) {
        // Notify other nodes about the status change
        System.out.println("Node " + node.getId() + " status changed to " + status);
    }

    private void electLeader() {
        Node newLeader = nodes.stream()
                .filter(node -> nodeStatuses.get(node) == NodeStatus.CONNECTED)
                .findFirst()
                .orElse(null);
        if (newLeader != null) {
            leader.set(newLeader);
            System.out.println("New leader elected: " + newLeader.getId());
        }
    }

    public Node getLeader() {
        return leader.get();
    }

    public NodeStatus getNodeStatus(Node node) {
        return nodeStatuses.getOrDefault(node, NodeStatus.UNKNOWN);
    }

    public void recoverClusterState() {
        // Logic to recover the state of the cluster
    }

    public void storeClusterState() {
        // Logic to store the state of the cluster
    }

    public interface Node {
        String getId();
    }

    public enum NodeStatus {
        CONNECTED,
        DISCONNECTED,
        OFFLOADED,
        UNKNOWN
    }
}

