public class ThermometerPlot extends Plot implements ValueAxisPlotting, Zoomable, Cloneable, Serializable {
    private double minValue;
    private double maxValue;
    private double currentValue;
    private String unit;
    private Color normalColor;
    private Color warningColor;
    private Color criticalColor;
    private double warningThreshold;
    private double criticalThreshold;
    private Font labelFont;
    private double bulbHeight;
    private double columnHeight;

    public ThermometerPlot() {
        this.minValue = 0;
        this.maxValue = 100;
        this.currentValue = 0;
        this.unit = "Celsius";
        this.normalColor = Color.GREEN;
        this.warningColor = Color.YELLOW;
        this.criticalColor = Color.RED;
        this.warningThreshold = 75;
        this.criticalThreshold = 90;
        this.labelFont = new Font("Arial", Font.PLAIN, 12);
        this.bulbHeight = 20;
        this.columnHeight = 200;
    }

    public void setCurrentValue(double value) {
        if (value < minValue || value > maxValue) {
            throw new IllegalArgumentException("Value out of range");
        }
        this.currentValue = value;
        // Notify dataset change
        notifyDatasetChange();
    }

    public double getCurrentValue() {
        return currentValue;
    }

    public void setAxisRange(double min, double max) {
        this.minValue = min;
        this.maxValue = max;
    }

    public double[] getAxisRange() {
        return new double[]{minValue, maxValue};
    }

    public void draw(Graphics g) {
        Graphics2D g2d = (Graphics2D) g;
        double bulbY = calculateBulbY();
        double columnY = calculateColumnY();

        // Draw bulb
        g2d.setColor(getColorForCurrentValue());
        g2d.fillOval(50, (int) bulbY, 40, (int) bulbHeight);

        // Draw column
        g2d.fillRect(50, (int) columnY, 40, (int) columnHeight);

        // Draw label
        g2d.setFont(labelFont);
        g2d.drawString(String.format("%.1f %s", currentValue, unit), 50, (int) (columnY - 10));
    }

    private double calculateBulbY() {
        return (maxValue - currentValue) / (maxValue - minValue) * columnHeight + bulbHeight;
    }

    private double calculateColumnY() {
        return (maxValue - currentValue) / (maxValue - minValue) * columnHeight;
    }

    private Color getColorForCurrentValue() {
        if (currentValue >= criticalThreshold) {
            return criticalColor;
        } else if (currentValue >= warningThreshold) {
            return warningColor;
        } else {
            return normalColor;
        }
    }

    public ThermometerPlot clone() {
        try {
            return (ThermometerPlot) super.clone();
        } catch (CloneNotSupportedException e) {
            throw new RuntimeException("Cloning not supported", e);
        }
    }

    // Additional methods for zooming, localization, etc. can be added here
}

