public class FrenchStemmer extends AbstractSnowballStemmer {
    private int current;
    private int limit;
    private int limitBackward;
    private StringBuilder word;

    public FrenchStemmer() {
        this.word = new StringBuilder();
    }

    @Override
    public void setCurrent(String value) {
        this.word.setLength(0);
        this.word.append(value);
        this.current = value.length();
        this.limit = current;
        this.limitBackward = 0;
    }

    @Override
    public String getCurrent() {
        return word.toString();
    }

    public void stem() {
        // Apply stemming rules
        if (current > 0) {
            // Example of a suffix removal
            if (endsWith("e")) {
                limit--;
            }
            // Additional rules can be added here
        }
    }

    private boolean endsWith(String suffix) {
        int suffixLength = suffix.length();
        if (current >= suffixLength) {
            if (word.substring(current - suffixLength, current).equals(suffix)) {
                limit -= suffixLength;
                return true;
            }
        }
        return false;
    }

    private void markRegion(int start, int end) {
        limitBackward = start;
        limit = end;
    }

    private void copyState(FrenchStemmer other) {
        this.current = other.current;
        this.limit = other.limit;
        this.limitBackward = other.limitBackward;
        this.word = new StringBuilder(other.word);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof FrenchStemmer)) return false;
        FrenchStemmer other = (FrenchStemmer) obj;
        return this.word.toString().equals(other.word.toString());
    }

    @Override
    public int hashCode() {
        return word.toString().hashCode();
    }
}

