        driver.findElement(By.id("addProxyConnector")).click();
        WebElement nameField = driver.findElement(By.id("connectorName"));
        nameField.sendKeys(connectorName);
        driver.findElement(By.id("saveButton")).click();
    }

    protected void navigateToRemoteRepositories() {
        driver.findElement(By.linkText("Remote Repositories")).click();
    }

    protected void addRemoteRepository(String repoName, String url) {
        driver.findElement(By.id("addRemoteRepository")).click();
        WebElement nameField = driver.findElement(By.id("repositoryName"));
        nameField.sendKeys(repoName);
        WebElement urlField = driver.findElement(By.id("repositoryUrl"));
        urlField.sendKeys(url);
        driver.findElement(By.id("saveButton")).click();
    }

    protected void editRemoteRepository(String oldName, String newName, String newUrl) {
        WebElement editButton = driver.findElement(By.xpath("//tr[td[text()='" + oldName + "']]/td/button[contains(@class, 'edit')]"));
        editButton.click();
        WebElement nameField = driver.findElement(By.id("repositoryName"));
        nameField.clear();
        nameField.sendKeys(newName);
        WebElement urlField = driver.findElement(By.id("repositoryUrl"));
        urlField.clear();
        urlField.sendKeys(newUrl);
        driver.findElement(By.id("saveButton")).click();
