class NumberUtil {
    public static final int POWER_OF_TEN_1 = 10;
    public static final int POWER_OF_TEN_2 = 100;
    public static final int POWER_OF_TEN_3 = 1000;
    public static final int CHAR_SIZE = 8;
    public static final String UTF_8_ENCODING = "UTF-8";

    public static byte[] numberToAsciiBytes(int number) {
        return String.valueOf(number).getBytes(StandardCharsets.US_ASCII);
    }

    public static double bytesToDouble(byte[] bytes) {
        if (bytes.length != 8) throw new IllegalArgumentException("Invalid byte array length for double");
        return ByteBuffer.wrap(bytes).getDouble();
    }

    public static int bytesToInt(byte[] bytes, int radix) {
        if (bytes.length < 1 || radix < Character.MIN_RADIX || radix > Character.MAX_RADIX)
            throw new IllegalArgumentException("Invalid byte array or radix");
        return Integer.parseInt(new String(bytes, StandardCharsets.US_ASCII), radix);
    }

    public static long bytesToLong(byte[] bytes) {
        if (bytes.length != 8) throw new IllegalArgumentException("Invalid byte array length for long");
        return ByteBuffer.wrap(bytes).getLong();
    }

    public static void writeIntAsUtf8(OutputStream out, int value) throws Exception {
        out.write(String.valueOf(value).getBytes(StandardCharsets.UTF_8));
    }

    public static void writeLongAsUtf8(OutputStream out, long value) throws Exception {
        out.write(String.valueOf(value).getBytes(StandardCharsets.UTF_8));
    }

    public static byte[] floatToBytes(float value) {
        return ByteBuffer.allocate(4).putFloat(value).array();
    }

    public static byte[] doubleToBytes(double value) {
        return ByteBuffer.allocate(8).putDouble(value).array();
    }

    public static byte[] shortToBytes(short value) {
        return ByteBuffer.allocate(2).putShort(value).array();
    }

    public static BigDecimal bytesToBigDecimal(byte[] bytes) {
        return new BigDecimal(new String(bytes, StandardCharsets.UTF_8));
    }

    public static boolean compareUnsigned(int x, int y) {
        return Integer.compareUnsigned(x, y) == 0;
    }

    public static boolean compareUnsigned(long x, long y) {
        return Long.compareUnsigned(x, y) == 0;
    }

    public static byte readByteFromBuffer(ByteBuffer buffer) {
        return buffer.get();
    }

    public static void writeByteToBuffer(ByteBuffer buffer, byte value) {
        buffer.put(value);
    }

    public static byte[] intToByteArray(int value) {
        return ByteBuffer.allocate(4).putInt(value).array();
    }

    public static byte[] longToByteArray(long value) {
        return ByteBuffer.allocate(8).putLong(value).array();
    }
}

public class ProtocolStatus implements Writable {
    public static final int SUCCESS = 0;
    public static final int FAILED = 1;
    public static final int NOTFOUND = 2;

    private int statusCode;
    private String message;
    private Object[] args;
    private long lastModified;

    public static final ProtocolStatus SUCCESS_STATUS = new ProtocolStatus(SUCCESS, null, null);
    public static final ProtocolStatus FAILED_STATUS = new ProtocolStatus(FAILED, null, null);
    public static final ProtocolStatus NOTFOUND_STATUS = new ProtocolStatus(NOTFOUND, null, null);

    public ProtocolStatus() {
        this.statusCode = SUCCESS;
        this.message = "";
        this.args = new Object[0];
        this.lastModified = System.currentTimeMillis();
    }

    public ProtocolStatus(int statusCode, String message, Object[] args) {
        this.statusCode = statusCode;
        this.message = message;
        this.args = args != null ? args : new Object[0];
        this.lastModified = System.currentTimeMillis();
    }

    public int getStatusCode() {
        return statusCode;
    }

    public String getMessage() {
        return message;
    }

    public Object[] getArgs() {
        return args;
    }

    public long getLastModified() {
        return lastModified;
    }

    public boolean isSuccess() {
        return statusCode == SUCCESS;
    }

    public boolean isFailed() {
        return statusCode == FAILED;
    }

    public boolean isNotFound() {
        return statusCode == NOTFOUND;
    }

    @Override
    public void write(DataOutput out) throws IOException {
        out.writeInt(statusCode);
        out.writeUTF(message);
        out.writeInt(args.length);
        for (Object arg : args) {
            out.writeUTF(arg.toString());
        }
        out.writeLong(lastModified);
    }

    @Override
    public void readFields(DataInput in) throws IOException {
        statusCode = in.readInt();
        message = in.readUTF();
        int argsLength = in.readInt();
        args = new Object[argsLength];
        for (int i = 0; i < argsLength; i++) {
            args[i] = in.readUTF();
        }
        lastModified = in.readLong();
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof ProtocolStatus)) return false;
        ProtocolStatus other = (ProtocolStatus) obj;
        return statusCode == other.statusCode &&
               message.equals(other.message) &&
               lastModified == other.lastModified;
    }

    @Override
    public int hashCode() {
        int result = Integer.hashCode(statusCode);
        result = 31 * result + message.hashCode();
        result = 31 * result + Long.hashCode(lastModified);
        return result;
    }

    @Override
    public String toString() {
        return "ProtocolStatus{" +
               "statusCode=" + statusCode +
               ", message='" + message + '\'' +
               ", args=" + java.util.Arrays.toString(args) +
               ", lastModified=" + lastModified +
               '}';
    }
}

public class StandardControllerServiceProvider implements ControllerServiceProvider {
    private static final Logger logger = Logger.getLogger(StandardControllerServiceProvider.class.getName());
    private Map<String, ControllerServiceNode> serviceCache = new HashMap<>();

    @Override
    public void addControllerService(String id, ControllerServiceNode service) {
        serviceCache.put(id, service);
        logger.info("Added controller service: " + id);
    }

    @Override
    public void enableControllerService(String id) {
        ControllerServiceNode service = serviceCache.get(id);
        if (service != null && !service.isEnabled()) {
            // Check dependencies
            if (areDependenciesEnabled(service)) {
                service.enable();
                logger.info("Enabled controller service: " + id);
            } else {
                logger.warning("Cannot enable service " + id + " due to unmet dependencies.");
            }
        }
    }

    @Override
    public void disableControllerService(String id) {
        ControllerServiceNode service = serviceCache.get(id);
        if (service != null && service.isEnabled()) {
            service.disable();
            logger.info("Disabled controller service: " + id);
        }
    }

    @Override
    public void removeControllerService(String id) {
        ControllerServiceNode service = serviceCache.remove(id);
        if (service != null) {
            service.disable();
            logger.info("Removed controller service: " + id);
        }
    }

    private boolean areDependenciesEnabled(ControllerServiceNode service) {
        Set<String> dependencies = service.getDependencies();
        for (String dependencyId : dependencies) {
            ControllerServiceNode dependency = serviceCache.get(dependencyId);
            if (dependency == null || !dependency.isEnabled()) {
                return false;
            }
        }
        return true;
    }

    @Override
    public void verifyState() {
        for (ControllerServiceNode service : serviceCache.values()) {
            if (!service.isEnabled() && service.hasReferences()) {
                logger.warning("Service " + service.getId() + " is not enabled but has references.");
            }
        }
    }

    @Override
    public void logOperation(String message) {
        logger.info(message);
    }

    @Override
    public void manageBulletins(String message) {
        // Implementation for managing bulletins
        logger.warning("Bulletin: " + message);
    }
}

public class TestPhraseQuery extends LuceneTestCase {
    private Directory directory;
    private IndexWriter writer;

    @Before
    public void setUp() throws Exception {
        directory = new RAMDirectory();
        Analyzer analyzer = new StandardAnalyzer();
        writer = new IndexWriter(directory, new IndexWriterConfig(analyzer));
        addDocuments();
    }

    private void addDocuments() throws Exception {
        addDoc("the quick brown fox");
        addDoc("the quick brown dog");
        addDoc("the lazy dog");
        addDoc("the quick brown fox jumps over the lazy dog");
    }

    private void addDoc(String text) throws Exception {
        Document doc = new Document();
        doc.add(new StringField("content", text, Field.Store.YES));
        writer.addDocument(doc);
    }

    @Test
    public void testExactMatch() throws Exception {
        writer.commit();
        IndexSearcher searcher = new IndexSearcher(DirectoryReader.open(directory));
        PhraseQuery query = new PhraseQuery.Builder()
                .add(new Term("content", "quick"))
                .add(new Term("content", "brown"))
                .build();
        ScoreDoc[] hits = searcher.search(query, 10).scoreDocs;
        assertEquals(2, hits.length);
    }

    @Test
    public void testSlop() throws Exception {
        writer.commit();
        IndexSearcher searcher = new IndexSearcher(DirectoryReader.open(directory));
        PhraseQuery query = new PhraseQuery.Builder()
                .add(new Term("content", "quick"))
                .add(new Term("content", "fox"))
                .setSlop(1)
                .build();
        ScoreDoc[] hits = searcher.search(query, 10).scoreDocs;
        assertEquals(1, hits.length);
    }

    @Test
    public void testTermOrder() throws Exception {
        writer.commit();
        IndexSearcher searcher = new IndexSearcher(DirectoryReader.open(directory));
        PhraseQuery query = new PhraseQuery.Builder()
                .add(new Term("content", "brown"))
                .add(new Term("content", "quick"))
                .build();
        ScoreDoc[] hits = searcher.search(query, 10).scoreDocs;
        assertEquals(0, hits.length);
    }

    @Test
    public void testRepeatedFields() throws Exception {
        writer.commit();
        IndexSearcher searcher = new IndexSearcher(DirectoryReader.open(directory));
        addDoc("the quick brown fox quick");
        PhraseQuery query = new PhraseQuery.Builder()
                .add(new Term("content", "quick"))
                .add(new Term("content", "brown"))
                .build();
        ScoreDoc[] hits = searcher.search(query, 10).scoreDocs;
        assertEquals(3, hits.length);
    }

    @Test
    public void testStopWords() throws Exception {
        writer.commit();
        IndexSearcher searcher = new IndexSearcher(DirectoryReader.open(directory));
        PhraseQuery query = new PhraseQuery.Builder()
                .add(new Term("content", "the"))
                .add(new Term("content", "lazy"))
                .build();
        ScoreDoc[] hits = searcher.search(query, 10).scoreDocs;
        assertEquals(1, hits.length);
    }

    @Test
    public void testScoring() throws Exception {
        writer.commit();
        IndexSearcher searcher = new IndexSearcher(DirectoryReader.open(directory));
        PhraseQuery query = new PhraseQuery.Builder()
                .add(new Term("content", "quick"))
                .add(new Term("content", "brown"))
                .build();
        ScoreDoc[] hits = searcher.search(query, 10).scoreDocs;
        assertTrue(hits[0].score > hits[1].score);
    }
}

