    public void testCeil() {
        assertEquals(2, executeSql("SELECT CEIL(1.1)"));
        assertEquals(3, executeSql("SELECT CEIL(2.9)"));
    }

    @Test
    public void testSin() {
        assertEquals(0, executeSql("SELECT SIN(0)"), 0.0001);
        assertEquals(1, executeSql("SELECT SIN(PI()/2)"), 0.0001);
    }

