    public void testTan() {
        assertEquals(0, executeSql("SELECT TAN(0)"), 0.0001);
        assertEquals(Double.NaN, executeSql("SELECT TAN(PI()/2)"), 0.0001);
    }

    @Test
    public void testAsin() {
        assertEquals(0, executeSql("SELECT ASIN(0)"), 0.0001);
        assertEquals(PI()/2, executeSql("SELECT ASIN(1)"), 0.0001);
    }

    @Test
    public void testAcos() {
        assertEquals(PI()/2, executeSql("SELECT ACOS(0)"), 0.0001);
        assertEquals(0, executeSql("SELECT ACOS(1)"), 0.0001);
    }

