public class ELSupport {

    public static boolean compare(Object left, Object right) throws ELException {
        if (left == null || right == null) {
            throw new ELException("Comparison with null is not allowed");
        }
        if (left instanceof Number && right instanceof Number) {
            return compareNumbers((Number) left, (Number) right);
        }
        if (left instanceof String && right instanceof String) {
            return left.equals(right);
        }
        if (left instanceof Boolean && right instanceof Boolean) {
            return left.equals(right);
        }
        if (left instanceof Character && right instanceof Character) {
            return left.equals(right);
        }
        if (left.getClass() == right.getClass()) {
            return left.equals(right);
        }
        throw new ELException("Incompatible types for comparison");
    }

    private static boolean compareNumbers(Number left, Number right) {
        BigDecimal leftDecimal = toBigDecimal(left);
        BigDecimal rightDecimal = toBigDecimal(right);
        return leftDecimal.compareTo(rightDecimal) == 0;
    }

    public static boolean equals(Object left, Object right) {
        if (left == null) {
            return right == null;
        }
        return left.equals(right);
    }

    public static BigDecimal toBigDecimal(Object obj) throws ELException {
        if (obj instanceof BigDecimal) {
            return (BigDecimal) obj;
        }
        if (obj instanceof BigInteger) {
            return new BigDecimal((BigInteger) obj);
        }
        if (obj instanceof Double) {
            return BigDecimal.valueOf((Double) obj);
        }
        if (obj instanceof Long) {
            return BigDecimal.valueOf((Long) obj);
        }
        if (obj instanceof Integer) {
            return BigDecimal.valueOf((Integer) obj);
        }
        if (obj instanceof String) {
            try {
                return new BigDecimal((String) obj);
            } catch (NumberFormatException e) {
                throw new ELException("Invalid string for BigDecimal conversion", e);
            }
        }
        throw new ELException("Unsupported type for BigDecimal conversion");
    }

    public static String toString(Object obj) {
        return obj == null ? null : obj.toString();
    }

    public static Boolean toBoolean(Object obj) throws ELException {
        if (obj instanceof Boolean) {
            return (Boolean) obj;
        }
        if (obj instanceof String) {
            return Boolean.valueOf((String) obj);
        }
        throw new ELException("Unsupported type for Boolean conversion");
    }

    public static Character toCharacter(Object obj) throws ELException {
        if (obj instanceof Character) {
            return (Character) obj;
        }
        if (obj instanceof String && ((String) obj).length() == 1) {
            return ((String) obj).charAt(0);
        }
        throw new ELException("Unsupported type for Character conversion");
    }

    public static <E extends Enum<E>> E toEnum(Class<E> enumClass, Object obj) throws ELException {
        if (obj instanceof String) {
            return Enum.valueOf(enumClass, (String) obj);
        }
        throw new ELException("Unsupported type for Enum conversion");
    }
}

