public class MediaFile implements Serializable {
    private static final long serialVersionUID = 1L;

    private String id;
    private String name;
    private String description;
    private String copyrightText;
    private boolean isShared;
    private int width;
    private int height;
    private String contentType;
    private long uploadTimestamp;
    private String creator;
    private List<String> tags;

    public MediaFile(String id, String name, String description, String copyrightText, boolean isShared,
                     int width, int height, String contentType, long uploadTimestamp, String creator) {
        this.id = id;
        this.name = name;
        this.description = description;
        this.copyrightText = copyrightText;
        this.isShared = isShared;
        this.width = width;
        this.height = height;
        this.contentType = contentType;
        this.uploadTimestamp = uploadTimestamp;
        this.creator = creator;
        this.tags = new ArrayList<>();
    }

    public String getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public String getCopyrightText() {
        return copyrightText;
    }

    public void setCopyrightText(String copyrightText) {
        this.copyrightText = copyrightText;
    }

    public boolean isShared() {
        return isShared;
    }

    public void setShared(boolean shared) {
        isShared = shared;
    }

    public int getWidth() {
        return width;
    }

    public int getHeight() {
        return height;
    }

    public String getContentType() {
        return contentType;
    }

    public long getUploadTimestamp() {
        return uploadTimestamp;
    }

    public String getCreator() {
        return creator;
    }

    public List<String> getTags() {
        return tags;
    }

    public void addTag(String tag) {
        if (!tags.contains(tag)) {
            tags.add(tag);
        }
    }

    public void removeTag(String tag) {
        tags.remove(tag);
    }

    public String generateUrl() {
        return "/media/" + id;
    }

    public String generateThumbnailUrl() {
        return "/media/" + id + "/thumbnail";
    }

    public boolean isImage() {
        return contentType != null && contentType.startsWith("image/");
    }

    public int[] calculateThumbnailDimensions(int maxWidth, int maxHeight) {
        double aspectRatio = (double) width / height;
        if (width > maxWidth || height > maxHeight) {
            if (aspectRatio > 1) {
                return new int[]{maxWidth, (int) (maxWidth / aspectRatio)};
            } else {
                return new int[]{(int) (maxHeight * aspectRatio), maxHeight};
            }
        }
        return new int[]{width, height};
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof MediaFile)) return false;
        MediaFile mediaFile = (MediaFile) o;
        return Objects.equals(id, mediaFile.id);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id);
    }
}

