public class ExecutableParser extends AbstractParser implements MachineMetadata {

    private static final Set<String> SUPPORTED_TYPES = new HashSet<>();

    static {
        SUPPORTED_TYPES.add("application/x-msdownload"); // PE
        SUPPORTED_TYPES.add("application/x-executable"); // ELF
    }

    @Override
    public Set<String> getSupportedTypes() {
        return SUPPORTED_TYPES;
    }

    @Override
    public Metadata parse(InputStream inputStream) throws Exception {
        byte[] header = new byte[4];
        if (inputStream.read(header) != 4) {
            throw new IllegalArgumentException("Input stream is too short");
        }

        if (isPE(header)) {
            return parsePE(inputStream);
        } else if (isELF(header)) {
            return parseELF(inputStream);
        } else {
            throw new UnsupportedOperationException("Unsupported file type");
        }
    }

    private boolean isPE(byte[] header) {
        return header[0] == 'M' && header[1] == 'Z';
    }

    private boolean isELF(byte[] header) {
        return header[0] == 0x7F && header[1] == 'E' && header[2] == 'L' && header[3] == 'F';
    }

    private Metadata parsePE(InputStream inputStream) throws Exception {
        Metadata metadata = new Metadata();
        // Logic to extract PE metadata
        metadata.setCreationDate("PE Creation Date");
        metadata.setMachineType("PE Machine Type");
        metadata.setEndianness("PE Endianness");
        metadata.setArchitectureBits(32); // Example value
        return metadata;
    }

    private Metadata parseELF(InputStream inputStream) throws Exception {
        Metadata metadata = new Metadata();
        // Logic to extract ELF metadata
        metadata.setCreationDate("ELF Creation Date");
        metadata.setMachineType("ELF Machine Type");
        metadata.setEndianness("ELF Endianness");
        metadata.setArchitectureBits(64); // Example value
        return metadata;
    }
}

