public final class Strings {

    private Strings() {
        throw new UnsupportedOperationException("Utility class cannot be instantiated");
    }

    public static String afterFirst(String str, char separator) {
        int index = str.indexOf(separator);
        return index == -1 ? str : str.substring(index + 1);
    }

    public static String beforeLast(String str, char separator) {
        int index = str.lastIndexOf(separator);
        return index == -1 ? str : str.substring(0, index);
    }

    public static String firstPathComponent(String path) {
        return path.split("/")[0];
    }

    public static String capitalize(String str) {
        if (str == null || str.isEmpty()) return str;
        return str.substring(0, 1).toUpperCase() + str.substring(1);
    }

    public static String escapeHtml(String str) {
        if (str == null) return null;
        return str.replace("&", "&amp;")
                  .replace("<", "&lt;")
                  .replace(">", "&gt;")
                  .replace("\"", "&quot;")
                  .replace("'", "&#39;");
    }

    public static String unescapeHtml(String str) {
        if (str == null) return null;
        return str.replace("&amp;", "&")
                  .replace("&lt;", "<")
                  .replace("&gt;", ">")
                  .replace("&quot;", "\"")
                  .replace("&#39;", "'");
    }

    public static boolean isEmpty(String str) {
        return str == null || str.isEmpty();
    }

    public static boolean equals(String str1, String str2) {
        return str1 == null ? str2 == null : str1.equals(str2);
    }

    public static boolean toBoolean(String str) {
        return str != null && (str.equalsIgnoreCase("true") || str.equals("1"));
    }

    public static String join(String separator, String... elements) {
        return String.join(separator, elements);
    }

    public static String[] split(String str, char separator) {
        return str.split(String.valueOf(separator));
    }

    public static String stripEnding(String str, String ending) {
        if (str == null || ending == null) return str;
        return str.endsWith(ending) ? str.substring(0, str.length() - ending.length()) : str;
    }

    public static boolean startsWith(String str, String prefix) {
        return str != null && str.startsWith(prefix);
    }

    public static int levenshteinDistance(String s1, String s2) {
        if (s1 == null || s2 == null) return -1;
        int lenS1 = s1.length();
        int lenS2 = s2.length();
        int[][] dp = new int[lenS1 + 1][lenS2 + 1];

        for (int i = 0; i <= lenS1; i++) dp[i][0] = i;
        for (int j = 0; j <= lenS2; j++) dp[0][j] = j;

        for (int i = 1; i <= lenS1; i++) {
            for (int j = 1; j <= lenS2; j++) {
                int cost = (s1.charAt(i - 1) == s2.charAt(j - 1)) ? 0 : 1;
                dp[i][j] = Math.min(Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1), dp[i - 1][j - 1] + cost);
            }
        }
        return dp[lenS1][lenS2];
    }

    public static String toHexString(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            hexString.append(String.format("%02x", b));
        }
        return hexString.toString();
    }

    public static int byteLength(String str) {
        return str == null ? 0 : str.getBytes(StandardCharsets.UTF_8).length;
    }
}

