public class JmsBytesMessage extends JmsMessage implements BytesMessage {
    private byte[] body;
    private int readIndex;
    private int writeIndex;

    public JmsBytesMessage() {
        this.body = new byte[0];
        this.readIndex = 0;
        this.writeIndex = 0;
    }

    @Override
    public void writeBoolean(boolean value) throws JMSException {
        ensureCapacity(1);
        body[writeIndex++] = (byte) (value ? 1 : 0);
    }

    @Override
    public void writeByte(byte value) throws JMSException {
        ensureCapacity(1);
        body[writeIndex++] = value;
    }

    @Override
    public void writeShort(short value) throws JMSException {
        ensureCapacity(2);
        body[writeIndex++] = (byte) (value >> 8);
        body[writeIndex++] = (byte) value;
    }

    @Override
    public void writeInt(int value) throws JMSException {
        ensureCapacity(4);
        body[writeIndex++] = (byte) (value >> 24);
        body[writeIndex++] = (byte) (value >> 16);
        body[writeIndex++] = (byte) (value >> 8);
        body[writeIndex++] = (byte) value;
    }

    @Override
    public void writeLong(long value) throws JMSException {
        ensureCapacity(8);
        for (int i = 7; i >= 0; i--) {
            body[writeIndex++] = (byte) (value >> (i * 8));
        }
    }

    @Override
    public void writeFloat(float value) throws JMSException {
        writeInt(Float.floatToIntBits(value));
    }

    @Override
    public void writeDouble(double value) throws JMSException {
        writeLong(Double.doubleToLongBits(value));
    }

    @Override
    public void writeChar(char value) throws JMSException {
        writeShort((short) value);
    }

    @Override
    public void writeUTF(String value) throws JMSException {
        byte[] utfBytes = value.getBytes();
        writeShort((short) utfBytes.length);
        ensureCapacity(utfBytes.length);
        System.arraycopy(utfBytes, 0, body, writeIndex, utfBytes.length);
        writeIndex += utfBytes.length;
    }

    @Override
    public boolean readBoolean() throws JMSException {
        checkReadIndex(1);
        return body[readIndex++] != 0;
    }

    @Override
    public byte readByte() throws JMSException {
        checkReadIndex(1);
        return body[readIndex++];
    }

    @Override
    public short readShort() throws JMSException {
        checkReadIndex(2);
        return (short) ((body[readIndex++] << 8) | (body[readIndex++] & 0xFF));
    }

    @Override
    public int readInt() throws JMSException {
        checkReadIndex(4);
        return ((body[readIndex++] & 0xFF) << 24) |
               ((body[readIndex++] & 0xFF) << 16) |
               ((body[readIndex++] & 0xFF) << 8) |
               (body[readIndex++] & 0xFF);
    }

    @Override
    public long readLong() throws JMSException {
        checkReadIndex(8);
        long value = 0;
        for (int i = 0; i < 8; i++) {
            value = (value << 8) | (body[readIndex++] & 0xFF);
        }
        return value;
    }

    @Override
    public float readFloat() throws JMSException {
        return Float.intBitsToFloat(readInt());
    }

    @Override
    public double readDouble() throws JMSException {
        return Double.longBitsToDouble(readLong());
    }

    @Override
    public char readChar() throws JMSException {
        return (char) readShort();
    }

    @Override
    public String readUTF() throws JMSException {
        short length = readShort();
        checkReadIndex(length);
        String value = new String(body, readIndex, length);
        readIndex += length;
        return value;
    }

    @Override
    public void clearBody() throws JMSException {
        body = new byte[0];
        readIndex = 0;
        writeIndex = 0;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof JmsBytesMessage)) return false;
        JmsBytesMessage other = (JmsBytesMessage) obj;
        return Arrays.equals(body, other.body);
    }

    @Override
    public int hashCode() {
        return Arrays.hashCode(body);
    }

    @Override
    public String toString() {
        return "JmsBytesMessage{" +
                "body=" + Arrays.toString(body) +
                '}';
    }

    private void ensureCapacity(int additionalBytes) {
        if (writeIndex + additionalBytes > body.length) {
            body = Arrays.copyOf(body, writeIndex + additionalBytes);
        }
    }

    private void checkReadIndex(int bytes) throws JMSException {
        if (readIndex + bytes > writeIndex) {
            throw new JMSException("End of message body reached");
        }
    }
}

