class DateTest {

    @Test
    void testInitialization() {
        Date date = new Date(15, 8, 2023);
        assertEquals(15, date.getDay());
        assertEquals(8, date.getMonth());
        assertEquals(2023, date.getYear());
    }

    @Test
    void testGetters() {
        Date date = new Date(15, 8, 2023);
        assertEquals(15, date.getDay());
        assertEquals(8, date.getMonth());
        assertEquals(2023, date.getYear());
    }

    @Test
    void testAddDays() {
        Date date = new Date(15, 8, 2023);
        date.addDays(10);
        assertEquals(25, date.getDay());
    }

    @Test
    void testAddMonths() {
        Date date = new Date(15, 8, 2023);
        date.addMonths(5);
        assertEquals(1, date.getMonth());
        assertEquals(2024, date.getYear());
    }

    @Test
    void testAddYears() {
        Date date = new Date(15, 8, 2023);
        date.addYears(2);
        assertEquals(2025, date.getYear());
    }

    @Test
    void testEquality() {
        Date date1 = new Date(15, 8, 2023);
        Date date2 = new Date(15, 8, 2023);
        assertTrue(date1.equals(date2));
    }

    @Test
    void testLessThan() {
        Date date1 = new Date(15, 8, 2023);
        Date date2 = new Date(16, 8, 2023);
        assertTrue(date1.isLessThan(date2));
    }

    @Test
    void testSameDayOfWeek() {
        Date date1 = new Date(15, 8, 2023);
        Date date2 = new Date(22, 8, 2023);
        assertTrue(date1.isSameDayOfWeek(date2));
    }

    @Test
    void testStartAndEndOfMonth() {
        Date date = new Date(15, 8, 2023);
        assertEquals(new Date(1, 8, 2023), date.getStartOfMonth());
        assertEquals(new Date(31, 8, 2023), date.getEndOfMonth());
    }

    @Test
    void testStartAndEndOfWeek() {
        Date date = new Date(15, 8, 2023);
        assertEquals(new Date(13, 8, 2023), date.getStartOfWeek());
        assertEquals(new Date(19, 8, 2023), date.getEndOfWeek());
    }

    @Test
    void testStartAndEndOfYear() {
        Date date = new Date(15, 8, 2023);
        assertEquals(new Date(1, 1, 2023), date.getStartOfYear());
        assertEquals(new Date(31, 12, 2023), date.getEndOfYear());
    }

    @Test
    void testToJavaDate() {
        Date date = new Date(15, 8, 2023);
        java.util.Date javaDate = date.toJavaDate();
        Calendar cal = Calendar.getInstance();
        cal.setTime(javaDate);
        assertEquals(15, cal.get(Calendar.DAY_OF_MONTH));
        assertEquals(7, cal.get(Calendar.MONTH)); // Months are 0-based in Calendar
        assertEquals(2023, cal.get(Calendar.YEAR));
    }

    @Test
    void testStringRepresentation() {
        Date date = new Date(15, 8, 2023);
        assertEquals("15/08/2023", date.toString());
    }
}

