public class Template {
    private final String scheme;
    private final String username;
    private final String password;
    private final String host;
    private final int port;
    private final String path;
    private final List<String> queryParameters;
    private final String fragment;

    public Template(String scheme, String username, String password, String host, int port, String path, List<String> queryParameters, String fragment) {
        this.scheme = scheme;
        this.username = username;
        this.password = password;
        this.host = host;
        this.port = port;
        this.path = path;
        this.queryParameters = Collections.unmodifiableList(queryParameters);
        this.fragment = fragment;
    }

    public String getScheme() {
        return scheme;
    }

    public String getUsername() {
        return username;
    }

    public String getPassword() {
        return password;
    }

    public String getHost() {
        return host;
    }

    public int getPort() {
        return port;
    }

    public String getPath() {
        return path;
    }

    public List<String> getQueryParameters() {
        return queryParameters;
    }

    public String getFragment() {
        return fragment;
    }

    public String buildUri() {
        StringBuilder uriBuilder = new StringBuilder();
        uriBuilder.append(scheme).append("://");
        if (username != null && !username.isEmpty()) {
            uriBuilder.append(username);
            if (password != null && !password.isEmpty()) {
                uriBuilder.append(":").append(password);
            }
            uriBuilder.append("@");
        }
        uriBuilder.append(host);
        if (port > 0) {
            uriBuilder.append(":").append(port);
        }
        uriBuilder.append(path);
        if (!queryParameters.isEmpty()) {
            uriBuilder.append("?").append(String.join("&", queryParameters));
        }
        if (fragment != null) {
            uriBuilder.append("#").append(fragment);
        }
        return uriBuilder.toString();
    }

    @Override
    public String toString() {
        return buildUri();
    }

    @Override
    public int hashCode() {
        return Objects.hash(scheme, username, password, host, port, path, queryParameters, fragment);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Template)) return false;
        Template other = (Template) obj;
        return Objects.equals(scheme, other.scheme) &&
               Objects.equals(username, other.username) &&
               Objects.equals(password, other.password) &&
               Objects.equals(host, other.host) &&
               port == other.port &&
               Objects.equals(path, other.path) &&
               Objects.equals(queryParameters, other.queryParameters) &&
               Objects.equals(fragment, other.fragment);
    }
}

