public class EntityFactory {

    public ProcessorDiagnosticsEntity createProcessorDiagnosticsEntity(ProcessorDiagnosticsDTO dto, Map<String, Boolean> permissions, int revision) {
        checkReadPermission(permissions, "ProcessorDiagnostics");
        ProcessorDiagnosticsEntity entity = new ProcessorDiagnosticsEntity();
