public abstract class AbstractStickyAssignorTest {

    protected AbstractStickyAssignor assignor;
    protected List<String> consumers;
    protected Map<String, List<Integer>> topicPartitions;

    @Before
    public void setUp() {
        assignor = createAssignor();
        consumers = new ArrayList<>();
        topicPartitions = new HashMap<>();
    }

    protected abstract AbstractStickyAssignor createAssignor();

    protected void createTopic(String topic, int numPartitions) {
        List<Integer> partitions = new ArrayList<>();
        for (int i = 0; i < numPartitions; i++) {
            partitions.add(i);
        }
        topicPartitions.put(topic, partitions);
    }

    protected void addConsumer(String consumer) {
        consumers.add(consumer);
    }

    protected void removeConsumer(String consumer) {
        consumers.remove(consumer);
    }

    protected void verifyAssignment(Map<String, List<Integer>> assignment) {
        for (String consumer : assignment.keySet()) {
            List<Integer> assignedPartitions = assignment.get(consumer);
            for (Integer partition : assignedPartitions) {
                assertTrue("Assigned partition should belong to subscribed topics", 
                    topicPartitions.values().stream().anyMatch(partitions -> partitions.contains(partition)));
            }
        }
    }

    protected void verifyBalance(Map<String, List<Integer>> assignment) {
        int totalPartitions = topicPartitions.values().stream().mapToInt(List::size).sum();
        int expectedPartitionsPerConsumer = totalPartitions / consumers.size();
        for (List<Integer> assignedPartitions : assignment.values()) {
            assertTrue("Consumer should have balanced partitions", 
                assignedPartitions.size() <= expectedPartitionsPerConsumer + 1);
        }
    }

    @Test
    public void testAssignNoTopics() {
        Map<String, List<Integer>> assignment = assignor.assign(consumers, Collections.emptyMap());
        assertTrue("Assignment should be empty when no topics are available", assignment.isEmpty());
    }

    @Test
    public void testAssignNonexistentTopic() {
        createTopic("topic1", 3);
        addConsumer("consumer1");
        Map<String, List<Integer>> assignment = assignor.assign(consumers, Collections.singletonMap("nonexistentTopic", Collections.emptyList()));
        verifyAssignment(assignment);
    }

    @Test
    public void testAssignSingleTopicSingleConsumer() {
        createTopic("topic1", 3);
        addConsumer("consumer1");
        Map<String, List<Integer>> assignment = assignor.assign(consumers, Collections.singletonMap("topic1", topicPartitions.get("topic1")));
        verifyAssignment(assignment);
        assertEquals(3, assignment.get("consumer1").size());
    }

    @Test
    public void testAssignSingleTopicMultipleConsumers() {
        createTopic("topic1", 4);
        addConsumer("consumer1");
        addConsumer("consumer2");
        Map<String, List<Integer>> assignment = assignor.assign(consumers, Collections.singletonMap("topic1", topicPartitions.get("topic1")));
        verifyAssignment(assignment);
        verifyBalance(assignment);
    }

    @Test
    public void testAssignOnlySubscribedTopics() {
        createTopic("topic1", 2);
        createTopic("topic2", 2);
        addConsumer("consumer1");
        addConsumer("consumer2");
        Map<String, List<Integer>> assignment = assignor.assign(consumers, Collections.singletonMap("topic1", topicPartitions.get("topic1")));
        verifyAssignment(assignment);
        assertFalse("Assignment should not include partitions from unsubscribed topics", 
            assignment.values().stream().flatMap(List::stream).anyMatch(partition -> partition >= 2));
    }

    @Test
    public void testConsumerAdded() {
        createTopic("topic1", 3);
        addConsumer("consumer1");
        Map<String, List<Integer>> initialAssignment = assignor.assign(consumers, Collections.singletonMap("topic1", topicPartitions.get("topic1")));
        addConsumer("consumer2");
        Map<String, List<Integer>> newAssignment = assignor.assign(consumers, Collections.singletonMap("topic1", topicPartitions.get("topic1")));
        verifyAssignment(newAssignment);
        assertNotEquals(initialAssignment, newAssignment);
    }

    @Test
    public void testConsumerRemoved() {
        createTopic("topic1", 4);
        addConsumer("consumer1");
        addConsumer("consumer2");
        Map<String, List<Integer>> initialAssignment = assignor.assign(consumers, Collections.singletonMap("topic1", topicPartitions.get("topic1")));
        removeConsumer("consumer1");
        Map<String, List<Integer>> newAssignment = assignor.assign(consumers, Collections.singletonMap("topic1", topicPartitions.get("topic1")));
        verifyAssignment(newAssignment);
        assertNotEquals(initialAssignment, newAssignment);
    }

    @Test
    public void testStickinessInAssignments() {
        createTopic("topic1", 4);
        addConsumer("consumer1");
        addConsumer("consumer2");
        Map<String, List<Integer>> firstAssignment = assignor.assign(consumers, Collections.singletonMap("topic1", topicPartitions.get("topic1")));
        Map<String, List<Integer>> secondAssignment = assignor.assign(consumers, Collections.singletonMap("topic1", topicPartitions.get("topic1")));
        verifyAssignment(secondAssignment);
        assertEquals(firstAssignment, secondAssignment);
    }

    @Test
    public void testCorrectnessAfterChanges() {
        createTopic("topic1", 4);
        addConsumer("consumer1");
        addConsumer("consumer2");
        Map<String, List<Integer>> initialAssignment = assignor.assign(consumers, Collections.singletonMap("topic1", topicPartitions.get("topic1")));
        removeConsumer("consumer1");
        Map<String, List<Integer>> newAssignment = assignor.assign(consumers, Collections.singletonMap("topic1", topicPartitions.get("topic1")));
        verifyAssignment(newAssignment);
        assertNotEquals(initialAssignment, newAssignment);
    }
}

