public class CompareToBuilder {
    private int comparison = 0;

    public CompareToBuilder append(int lhs, int rhs) {
        if (comparison != 0) return this;
        comparison = Integer.compare(lhs, rhs);
        return this;
    }

    public CompareToBuilder append(Integer lhs, Integer rhs) {
        if (comparison != 0) return this;
        if (lhs == null && rhs == null) return this;
        if (lhs == null) {
            comparison = -1;
            return this;
        }
        if (rhs == null) {
            comparison = 1;
            return this;
        }
        comparison = lhs.compareTo(rhs);
        return this;
    }

    public CompareToBuilder append(Object lhs, Object rhs) {
        if (comparison != 0) return this;
        if (lhs == null && rhs == null) return this;
        if (lhs == null) {
            comparison = -1;
            return this;
        }
        if (rhs == null) {
            comparison = 1;
            return this;
        }
        comparison = ((Comparable) lhs).compareTo(rhs);
        return this;
    }

    public CompareToBuilder append(Object[] lhs, Object[] rhs) {
        if (comparison != 0) return this;
        if (lhs == null && rhs == null) return this;
        if (lhs == null) {
            comparison = -1;
            return this;
        }
        if (rhs == null) {
            comparison = 1;
            return this;
        }
        int minLength = Math.min(lhs.length, rhs.length);
        for (int i = 0; i < minLength; i++) {
            append(lhs[i], rhs[i]);
            if (comparison != 0) return this;
        }
        comparison = Integer.compare(lhs.length, rhs.length);
        return this;
    }

    public CompareToBuilder append(Object lhs, Object rhs, Comparator<Object> comparator) {
        if (comparison != 0) return this;
        if (lhs == null && rhs == null) return this;
        if (lhs == null) {
            comparison = -1;
            return this;
        }
        if (rhs == null) {
            comparison = 1;
            return this;
        }
        comparison = comparator.compare(lhs, rhs);
        return this;
    }

    public int toComparison() {
        return comparison;
    }
}

