public class OpenBitSet extends DocIdSet implements Cloneable, Serializable {
    private static final long serialVersionUID = 1L;
    private long[] bits;
    private int numBits;

    public OpenBitSet() {
        this(64);
    }

    public OpenBitSet(int numBits) {
        this.numBits = numBits;
        this.bits = new long[(numBits + 63) / 64];
    }

    public void set(int index) {
        ensureCapacity(index);
        bits[index / 64] |= (1L << (index % 64));
    }

    public void clear(int index) {
        ensureCapacity(index);
        bits[index / 64] &= ~(1L << (index % 64));
    }

    public void flip(int index) {
        ensureCapacity(index);
        bits[index / 64] ^= (1L << (index % 64));
    }

    public boolean get(int index) {
        if (index >= numBits) return false;
        return (bits[index / 64] & (1L << (index % 64))) != 0;
    }

    public int cardinality() {
        int count = 0;
        for (long b : bits) {
            count += Long.bitCount(b);
        }
        return count;
    }

    public OpenBitSet intersection(OpenBitSet other) {
        OpenBitSet result = new OpenBitSet(Math.max(this.numBits, other.numBits));
        for (int i = 0; i < result.bits.length; i++) {
            result.bits[i] = this.bits[i] & other.bits[i];
        }
        return result;
    }

    public OpenBitSet union(OpenBitSet other) {
        OpenBitSet result = new OpenBitSet(Math.max(this.numBits, other.numBits));
        for (int i = 0; i < result.bits.length; i++) {
            result.bits[i] = this.bits[i] | other.bits[i];
        }
        return result;
    }

    public OpenBitSet difference(OpenBitSet other) {
        OpenBitSet result = new OpenBitSet(Math.max(this.numBits, other.numBits));
        for (int i = 0; i < result.bits.length; i++) {
            result.bits[i] = this.bits[i] & ~other.bits[i];
        }
        return result;
    }

    public OpenBitSet xor(OpenBitSet other) {
        OpenBitSet result = new OpenBitSet(Math.max(this.numBits, other.numBits));
        for (int i = 0; i < result.bits.length; i++) {
            result.bits[i] = this.bits[i] ^ other.bits[i];
        }
        return result;
    }

    public boolean isEmpty() {
        for (long b : bits) {
            if (b != 0) return false;
        }
        return true;
    }

    public boolean intersects(OpenBitSet other) {
        for (int i = 0; i < Math.min(this.bits.length, other.bits.length); i++) {
            if ((this.bits[i] & other.bits[i]) != 0) return true;
        }
        return false;
    }

    private void ensureCapacity(int index) {
        if (index >= numBits) {
            int newNumBits = Math.max(numBits * 2, index + 1);
            long[] newBits = new long[(newNumBits + 63) / 64];
            System.arraycopy(bits, 0, newBits, 0, bits.length);
            bits = newBits;
            numBits = newNumBits;
        }
    }

    @Override
    public OpenBitSet clone() {
        try {
            OpenBitSet clone = (OpenBitSet) super.clone();
            clone.bits = this.bits.clone();
            return clone;
        } catch (CloneNotSupportedException e) {
            throw new RuntimeException(e);
        }
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof OpenBitSet)) return false;
        OpenBitSet other = (OpenBitSet) obj;
        return Arrays.equals(this.bits, other.bits);
    }

    @Override
    public int hashCode() {
        return Arrays.hashCode(bits);
    }
}

