public class TestInterProcessReadWriteLock {
    private CuratorFramework client;
    private InterProcessReadWriteLock lock;
    private final String lockPath = "/testLock";

    @Before
    public void setUp() throws Exception {
        client = CuratorFrameworkFactory.newClient("localhost:2181", new ExponentialBackoffRetry(1000, 3));
        client.start();
        lock = new InterProcessReadWriteLock(client, lockPath);
    }

    @After
    public void tearDown() throws Exception {
        client.close();
    }

    @Test
    public void testGetParticipantNodes() throws Exception {
        final CountDownLatch latch = new CountDownLatch(3);
        ExecutorService executor = Executors.newFixedThreadPool(3);

        executor.submit(() -> {
            lock.readLock().lock();
            latch.countDown();
            lock.readLock().unlock();
        });

        executor.submit(() -> {
            lock.writeLock().lock();
            latch.countDown();
            lock.writeLock().unlock();
        });

        executor.submit(() -> {
            lock.readLock().lock();
            latch.countDown();
            lock.readLock().unlock();
        });

        latch.await();
        assertEquals(2, lock.getParticipantNodes().size()); // Assuming 2 readers and 1 writer
    }

    @Test(expected = IllegalStateException.class)
    public void testThatUpgradingIsDisallowed() throws Exception {
        lock.readLock().lock();
        try {
            lock.writeLock().lock(); // This should throw an exception
        } finally {
            lock.readLock().unlock();
        }
    }

    @Test
    public void testThatDowngradingRespectsThreads() throws Exception {
        lock.writeLock().lock();
        try {
            // Simulate downgrading logic
            lock.readLock().lock();
            lock.writeLock().unlock(); // Downgrade
            lock.readLock().unlock();
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Test
    public void testDowngrading() throws Exception {
        lock.writeLock().lock();
        try {
            lock.readLock().lock(); // Downgrade
            lock.writeLock().unlock();
            lock.readLock().unlock();
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Test
    public void testBasic() throws Exception {
        final CountDownLatch latch = new CountDownLatch(10);
        ExecutorService executor = Executors.newFixedThreadPool(10);

        for (int i = 0; i < 5; i++) {
            executor.submit(() -> {
                lock.readLock().lock();
                try {
                    // Simulate read operation
                } finally {
                    lock.readLock().unlock();
                    latch.countDown();
                }
            });
            executor.submit(() -> {
                lock.writeLock().lock();
                try {
                    // Simulate write operation
                } finally {
                    lock.writeLock().unlock();
                    latch.countDown();
                }
            });
        }

        latch.await();
    }

    @Test
    public void testSetNodeData() throws Exception {
        lock.writeLock().lock();
        try {
            client.setData().forPath(lockPath, "testData".getBytes());
            byte[] data = client.getData().forPath(lockPath);
            assertEquals("testData", new String(data));
        } finally {
            lock.writeLock().unlock();
        }
    }
}

