public class InstructionAdapter extends MethodVisitor {

    public InstructionAdapter(MethodVisitor mv) {
        super(Opcodes.ASM9, mv);
    }

    public void loadVar(int index) {
        mv.visitVarInsn(Opcodes.ALOAD, index);
    }

    public void storeVar(int index) {
        mv.visitVarInsn(Opcodes.ASTORE, index);
    }

    public void add() {
        mv.visitInsn(Opcodes.IADD);
    }

    public void subtract() {
        mv.visitInsn(Opcodes.ISUB);
    }

    public void multiply() {
        mv.visitInsn(Opcodes.IMUL);
    }

    public void divide() {
        mv.visitInsn(Opcodes.IDIV);
    }

    public void castToInt() {
        mv.visitTypeInsn(Opcodes.CHECKCAST, "java/lang/Integer");
        mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/lang/Integer", "intValue", "()I", false);
    }

    public void jump(int label) {
        mv.visitJumpInsn(Opcodes.GOTO, label);
    }

    public void createObject(String className) {
        mv.visitTypeInsn(Opcodes.NEW, className);
        mv.visitInsn(Opcodes.DUP);
        mv.visitMethodInsn(Opcodes.INVOKESPECIAL, className, "<init>", "()V", false);
    }

    public void accessField(String owner, String name, String descriptor) {
        mv.visitFieldInsn(Opcodes.GETFIELD, owner, name, descriptor);
    }

    public void invokeMethod(String owner, String name, String descriptor) {
        mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, owner, name, descriptor, false);
    }
}

public abstract class AbstractPort implements Port {
    private String id;
    private String name;
    private String position;
    private String comment;
    private boolean isEnabled;
    private boolean isConnected;
    private int lossTolerance;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    private List<Connection> incomingConnections = new ArrayList<>();
    private List<Connection> outgoingConnections = new ArrayList<>();

    public AbstractPort(String id, String name, String position, String comment) {
        this.id = id;
        this.name = name;
        this.position = position;
        this.comment = comment;
        this.isEnabled = true;
        this.isConnected = false;
        this.lossTolerance = 0; // Default loss tolerance
    }

    public void addIncomingConnection(Connection connection) {
        lock.writeLock().lock();
        try {
            incomingConnections.add(connection);
            isConnected = true;
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void addOutgoingConnection(Connection connection) {
        lock.writeLock().lock();
        try {
            outgoingConnections.add(connection);
            isConnected = true;
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void removeIncomingConnection(Connection connection) {
        lock.writeLock().lock();
        try {
            incomingConnections.remove(connection);
            if (incomingConnections.isEmpty()) {
                isConnected = false;
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void removeOutgoingConnection(Connection connection) {
        lock.writeLock().lock();
        try {
            outgoingConnections.remove(connection);
            if (outgoingConnections.isEmpty()) {
                isConnected = false;
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void enable() {
        lock.writeLock().lock();
        try {
            isEnabled = true;
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void disable() {
        lock.writeLock().lock();
        try {
            isEnabled = false;
        } finally {
            lock.writeLock().unlock();
        }
    }

    public boolean validateState() {
        lock.readLock().lock();
        try {
            return isEnabled && isConnected;
        } finally {
            lock.readLock().unlock();
        }
    }

    public void setLossTolerance(int tolerance) {
        lock.writeLock().lock();
        try {
            this.lossTolerance = tolerance;
        } finally {
            lock.writeLock().unlock();
        }
    }

    public int getLossTolerance() {
        lock.readLock().lock();
        try {
            return lossTolerance;
        } finally {
            lock.readLock().unlock();
        }
    }

    // Getters for other properties
    public String getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getPosition() {
        return position;
    }

    public String getComment() {
        return comment;
    }

    public boolean isEnabled() {
        return isEnabled;
    }

    public boolean isConnected() {
        return isConnected;
    }

    public List<Connection> getIncomingConnections() {
        return new ArrayList<>(incomingConnections);
    }

    public List<Connection> getOutgoingConnections() {
        return new ArrayList<>(outgoingConnections);
    }
}

public class GeneratorConfig implements Serializable {
    private static final long serialVersionUID = 1L;

    // Constants
    public static final int DEFAULT_AUCTION_ID = 1;
    public static final int DEFAULT_PERSON_ID = 1;
    public static final int DEFAULT_CATEGORY_ID = 1;

    // Configuration parameters
    private int maxEvents;
    private int eventSize;
    private double personProportion;
    private double auctionProportion;
    private double bidProportion;
    private long interEventDelay; // in milliseconds
    private long stepLength; // in milliseconds

    // Constructor
    public GeneratorConfig(int maxEvents, int eventSize, double personProportion, double auctionProportion, double bidProportion, long interEventDelay, long stepLength) {
        this.maxEvents = maxEvents;
        this.eventSize = eventSize;
        this.personProportion = personProportion;
        this.auctionProportion = auctionProportion;
        this.bidProportion = bidProportion;
        this.interEventDelay = interEventDelay;
        this.stepLength = stepLength;
    }

    // Getters
    public int getMaxEvents() {
        return maxEvents;
    }

    public int getEventSize() {
        return eventSize;
    }

    public double getPersonProportion() {
        return personProportion;
    }

    public double getAuctionProportion() {
        return auctionProportion;
    }

    public double getBidProportion() {
        return bidProportion;
    }

    public long getInterEventDelay() {
        return interEventDelay;
    }

    public long getStepLength() {
        return stepLength;
    }

    // Method to copy configuration
    public GeneratorConfig copy() {
        return new GeneratorConfig(maxEvents, eventSize, personProportion, auctionProportion, bidProportion, interEventDelay, stepLength);
    }

    // Method to split configuration
    public GeneratorConfig[] split(int parts) {
        GeneratorConfig[] configs = new GeneratorConfig[parts];
        int eventsPerPart = maxEvents / parts;
        for (int i = 0; i < parts; i++) {
            configs[i] = new GeneratorConfig(eventsPerPart, eventSize, personProportion, auctionProportion, bidProportion, interEventDelay, stepLength);
        }
        return configs;
    }

    // Method to estimate memory usage
    public long estimateMemoryUsage() {
        return (long) (maxEvents * eventSize * 8); // Assuming each event takes 8 bytes
    }

    // Method to compute timestamp for an event
    public long computeTimestamp(int eventNumber) {
        return System.currentTimeMillis() + (eventNumber * interEventDelay);
    }

    // Method to compute delay for an event
    public long computeDelay(int eventNumber) {
        return eventNumber * interEventDelay;
    }

    // Method to adjust event numbers for out-of-order processing
    public int adjustEventNumber(int eventNumber, int adjustment) {
        return eventNumber + adjustment;
    }

    @Override
    public String toString() {
        return "GeneratorConfig{" +
                "maxEvents=" + maxEvents +
                ", eventSize=" + eventSize +
                ", personProportion=" + personProportion +
                ", auctionProportion=" + auctionProportion +
                ", bidProportion=" + bidProportion +
                ", interEventDelay=" + interEventDelay +
                ", stepLength=" + stepLength +
                '}';
    }
}

