public final class TarCompressionMethod extends EnumeratedAttribute {
    public static final String NONE = "none";
    public static final String GZIP = "gzip";
    public static final String BZIP2 = "bzip2";

    public TarCompressionMethod() {
        setValue(NONE);
    }

    @Override
    public String[] getValues() {
        return new String[] { NONE, GZIP, BZIP2 };
    }

    public OutputStream compress(OutputStream outputStream) throws Exception {
        String method = getValue();
        if (NONE.equals(method)) {
            return outputStream; // No compression
        } else if (GZIP.equals(method)) {
            return new GZIPOutputStream(outputStream);
        } else if (BZIP2.equals(method)) {
            outputStream.write(new byte[] { 'B', 'Z' }); // Writing header for bzip2
            return new CBZip2OutputStream(outputStream);
        }
        throw new IllegalArgumentException("Unsupported compression method: " + method);
    }
}

class ConfigurationModuleBuilder {
    private final Map<String, Object> requiredParameters = new HashMap<>();
    private final Map<String, Object> optionalParameters = new HashMap<>();
    private final Map<String, Class<?>> implementations = new HashMap<>();

    protected ConfigurationModuleBuilder() {
        // Constructor logic if needed
    }

    public abstract ConfigurationModule build();

    public ConfigurationModuleBuilder bindRequired(String name, Object value) {
        requiredParameters.put(name, value);
        return this;
    }

    public ConfigurationModuleBuilder bindOptional(String name, Object value) {
        optionalParameters.put(name, value);
        return this;
    }

    public ConfigurationModuleBuilder bindImplementation(String name, Class<?> implementation) {
        implementations.put(name, implementation);
        return this;
    }

    public ConfigurationModuleBuilder merge(ConfigurationModuleBuilder other) {
        requiredParameters.putAll(other.requiredParameters);
        optionalParameters.putAll(other.optionalParameters);
        implementations.putAll(other.implementations);
        return this;
    }

    public ConfigurationModuleBuilder deepCopy() {
        ConfigurationModuleBuilder copy = createNewInstance();
        copy.requiredParameters.putAll(this.requiredParameters);
        copy.optionalParameters.putAll(this.optionalParameters);
        copy.implementations.putAll(this.implementations);
        return copy;
    }

    protected abstract ConfigurationModuleBuilder createNewInstance();
}

