public class JavaCharStream {
    private static final int BUFFER_SIZE = 1024;
    private char[] buffer;
    private int bufferPosition;
    private int bufferEnd;
    private int line;
    private int column;
    private Reader reader;
    private InputStream inputStream;

    public JavaCharStream(Reader reader) {
        this.reader = reader;
        this.buffer = new char[BUFFER_SIZE];
        this.bufferPosition = 0;
        this.bufferEnd = 0;
        this.line = 1;
        this.column = 0;
    }

    public JavaCharStream(InputStream inputStream) {
        this.inputStream = inputStream;
        this.buffer = new char[BUFFER_SIZE];
        this.bufferPosition = 0;
        this.bufferEnd = 0;
        this.line = 1;
        this.column = 0;
    }

    public char readChar() throws IOException {
        if (bufferPosition >= bufferEnd) {
            fillBuffer();
        }
        if (bufferPosition >= bufferEnd) {
            return (char) -1; // End of stream
        }
        char ch = buffer[bufferPosition++];
        updatePosition(ch);
        return ch;
    }

    private void fillBuffer() throws IOException {
        if (reader != null) {
            bufferEnd = reader.read(buffer);
        } else if (inputStream != null) {
            bufferEnd = inputStream.read(buffer);
        }
        bufferPosition = 0;
    }

    private void updatePosition(char ch) {
        if (ch == '\n') {
            line++;
            column = 0;
        } else {
            column++;
        }
    }

    public int getLine() {
        return line;
    }

    public int getColumn() {
        return column;
    }

    public String getImage() {
        return new String(buffer, 0, bufferPosition);
    }

    public void reinitialize(Reader newReader) {
        this.reader = newReader;
        reset();
    }

    public void reinitialize(InputStream newInputStream) {
        this.inputStream = newInputStream;
        reset();
    }

    private void reset() {
        bufferPosition = 0;
        bufferEnd = 0;
        line = 1;
        column = 0;
    }

    public void close() throws IOException {
        if (reader != null) {
            reader.close();
        } else if (inputStream != null) {
            inputStream.close();
        }
    }
}

