public class UpsServices {
    private static final Logger logger = Logger.getLogger(UpsServices.class.getName());
    private String upsApiUrl;
    private String accessKey;
    private String username;
    private String password;

    public UpsServices(String upsApiUrl, String accessKey, String username, String password) {
        this.upsApiUrl = upsApiUrl;
        this.accessKey = accessKey;
        this.username = username;
        this.password = password;
    }

    public String confirmShipment(String shipmentXml) {
        return sendRequest("ConfirmShipment", shipmentXml);
    }

    public String acceptShipment(String shipmentXml) {
        return sendRequest("AcceptShipment", shipmentXml);
    }

    public String voidShipment(String shipmentId) {
        String xml = "<VoidShipment><ShipmentID>" + shipmentId + "</ShipmentID></VoidShipment>";
        return sendRequest("VoidShipment", xml);
    }

    public String trackShipment(String trackingNumber) {
        String xml = "<TrackShipment><TrackingNumber>" + trackingNumber + "</TrackingNumber></TrackShipment>";
        return sendRequest("TrackShipment", xml);
    }

    public String inquireShippingRates(String ratesXml) {
        return sendRequest("InquireShippingRates", ratesXml);
    }

    private String sendRequest(String operation, String xml) {
        String response = "";
        try {
            URL url = new URL(upsApiUrl + "/" + operation);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("POST");
            connection.setRequestProperty("Content-Type", "application/xml");
            connection.setDoOutput(true);

            try (OutputStream os = connection.getOutputStream()) {
                os.write(xml.getBytes());
                os.flush();
            }

            if (connection.getResponseCode() == HttpURLConnection.HTTP_OK) {
                response = readResponse(connection);
            } else {
                logger.log(Level.SEVERE, "Error in response: " + connection.getResponseCode());
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "IOException occurred: ", e);
        }
        return response;
    }

    private String readResponse(HttpURLConnection connection) throws IOException {
        StringBuilder response = new StringBuilder();
        try (BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
        }
        return response.toString();
    }

    // Additional methods for unit conversions and error handling can be added here
}

public class WriteJsonResult extends AbstractRecordSetWriter implements RecordSetWriter, RawRecordWriter {
    private final JsonGenerator jsonGenerator;
    private final ObjectMapper objectMapper;
    private final boolean prettyPrint;
    private final boolean suppressNulls;

    public WriteJsonResult(OutputStream outputStream, boolean prettyPrint, boolean suppressNulls) throws IOException {
        this.objectMapper = new ObjectMapper();
        this.jsonGenerator = objectMapper.getFactory().createGenerator(outputStream);
        this.prettyPrint = prettyPrint;
        this.suppressNulls = suppressNulls;
        if (prettyPrint) {
            jsonGenerator.useDefaultPrettyPrinter();
        }
        jsonGenerator.writeStartArray();
    }

    @Override
    public void writeRecord(Object record) throws IOException {
        if (suppressNulls) {
            jsonGenerator.writeObject(record);
        } else {
            jsonGenerator.writeObject(record);
        }
    }

    @Override
    public void writeRecords(List<Object> records) throws IOException {
        for (Object record : records) {
            writeRecord(record);
        }
    }

    @Override
    public void writeRawRecord(String rawRecord) throws IOException {
        jsonGenerator.writeRaw(rawRecord);
    }

    @Override
    public void flush() throws IOException {
        jsonGenerator.flush();
    }

    @Override
    public void close() throws IOException {
        jsonGenerator.writeEndArray();
        jsonGenerator.close();
    }

    @Override
    public String getMimeType() {
        return "application/json";
    }
}

