class UnixPermissionsTest {

    @Test(expected = IllegalArgumentException.class)
    public void testEmptyString() {
        UnixPermissions permissions = new UnixPermissions("");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testInvalidPermissionString() {
        UnixPermissions permissions = new UnixPermissions("0123456789");
    }

    @Test
    public void testOctalPermissions() {
        UnixPermissions permissions = new UnixPermissions("0157");
        assertTrue(permissions.hasOwnerRead());
        assertTrue(permissions.hasOwnerWrite());
        assertTrue(permissions.hasOwnerExecute());
        assertFalse(permissions.hasGroupRead());
        assertTrue(permissions.hasGroupWrite());
        assertFalse(permissions.hasGroupExecute());
        assertTrue(permissions.hasOthersRead());
        assertFalse(permissions.hasOthersWrite());
        assertTrue(permissions.hasOthersExecute());

        permissions = new UnixPermissions("0266");
        assertFalse(permissions.hasOwnerRead());
        assertTrue(permissions.hasOwnerWrite());
        assertTrue(permissions.hasOwnerExecute());
        assertTrue(permissions.hasGroupRead());
        assertTrue(permissions.hasGroupWrite());
        assertFalse(permissions.hasGroupExecute());
        assertFalse(permissions.hasOthersRead());
        assertTrue(permissions.hasOthersWrite());
        assertTrue(permissions.hasOthersExecute());
    }

    @Test
    public void testDecimalPermissions() {
        UnixPermissions permissions = new UnixPermissions("111");
        assertTrue(permissions.hasOwnerRead());
        assertTrue(permissions.hasOwnerWrite());
        assertTrue(permissions.hasOwnerExecute());
        assertFalse(permissions.hasGroupRead());
        assertFalse(permissions.hasGroupWrite());
        assertFalse(permissions.hasGroupExecute());
        assertFalse(permissions.hasOthersRead());
        assertFalse(permissions.hasOthersWrite());
        assertFalse(permissions.hasOthersExecute());

        permissions = new UnixPermissions("182");
        assertTrue(permissions.hasOwnerRead());
        assertFalse(permissions.hasOwnerWrite());
        assertTrue(permissions.hasOwnerExecute());
        assertTrue(permissions.hasGroupRead());
        assertTrue(permissions.hasGroupWrite());
        assertFalse(permissions.hasGroupExecute());
        assertFalse(permissions.hasOthersRead());
        assertFalse(permissions.hasOthersWrite());
        assertTrue(permissions.hasOthersExecute());
    }

    @Test
    public void testSymbolicPermissions() {
        UnixPermissions permissions = new UnixPermissions("---xr-xrwx");
        assertFalse(permissions.hasOwnerRead());
        assertFalse(permissions.hasOwnerWrite());
        assertTrue(permissions.hasOwnerExecute());
        assertFalse(permissions.hasGroupRead());
        assertTrue(permissions.hasGroupWrite());
        assertFalse(permissions.hasGroupExecute());
        assertTrue(permissions.hasOthersRead());
        assertTrue(permissions.hasOthersWrite());
        assertTrue(permissions.hasOthersExecute());

        permissions = new UnixPermissions("--w-rw-rw-");
        assertFalse(permissions.hasOwnerRead());
        assertTrue(permissions.hasOwnerWrite());
        assertFalse(permissions.hasOwnerExecute());
        assertTrue(permissions.hasGroupRead());
        assertTrue(permissions.hasGroupWrite());
        assertFalse(permissions.hasGroupExecute());
        assertTrue(permissions.hasOthersRead());
        assertTrue(permissions.hasOthersWrite());
        assertFalse(permissions.hasOthersExecute());
    }
}

