public final class Buffer implements Appendable, CharSequence {
    private StringBuilder buffer;
    private int capacity;
    private String format;

    public Buffer(int initialCapacity, String format) {
        this.buffer = new StringBuilder(initialCapacity);
        this.capacity = initialCapacity;
        this.format = format;
    }

    public Buffer(String format) {
        this(16, format);
    }

    @Override
    public Buffer append(CharSequence csq) throws IOException {
        if (csq == null) {
            buffer.append("null");
        } else {
            buffer.append(csq);
        }
        ensureCapacity();
        return this;
    }

    @Override
    public Buffer append(CharSequence csq, int start, int end) throws IOException {
        buffer.append(csq, start, end);
        ensureCapacity();
        return this;
    }

    @Override
    public Buffer append(char c) throws IOException {
        buffer.append(c);
        ensureCapacity();
        return this;
    }

    public void clear() {
        buffer.setLength(0);
    }

    public void writeTo(Appendable out) throws IOException {
        out.append(buffer);
    }

    public int length() {
        return buffer.length();
    }

    public char charAt(int index) {
        return buffer.charAt(index);
    }

    public CharSequence subSequence(int start, int end) {
        return buffer.subSequence(start, end);
    }

    private void ensureCapacity() {
        if (buffer.length() > capacity) {
            capacity *= 2;
            StringBuilder newBuffer = new StringBuilder(capacity);
            newBuffer.append(buffer);
            buffer = newBuffer;
        }
    }

    public String formatObject(Object obj) {
        // Code smell: This method could be improved for better formatting logic
        return format.equals("JSON") ? formatAsJson(obj) : formatAsSyslog(obj);
    }

    private String formatAsJson(Object obj) {
        // Simplistic JSON formatting
        return "{\"object\":" + obj.toString() + "}";
    }

    private String formatAsSyslog(Object obj) {
        // Simplistic Syslog formatting
        return "<34>" + obj.toString();
    }
}

