public class NodeImpl implements Node {
    private String nodeName;
    private String nodeType;
    private List<NodeImpl> childNodes;
    private Map<String, Object> properties;
    private Set<String> mixins;
    private boolean locked;
    private String version;

    public NodeImpl(String nodeName, String nodeType) {
        this.nodeName = nodeName;
        this.nodeType = nodeType;
        this.childNodes = new ArrayList<>();
        this.properties = new HashMap<>();
        this.mixins = new HashSet<>();
        this.locked = false;
        this.version = "1.0";
    }

    public void addChildNode(NodeImpl child) {
        if (locked) {
            throw new IllegalStateException("Node is locked");
        }
        childNodes.add(child);
    }

    public NodeImpl getChildNode(String name) {
        for (NodeImpl child : childNodes) {
            if (child.nodeName.equals(name)) {
                return child;
            }
        }
        return null; // Code smell: returning null can lead to NullPointerExceptions
    }

    public void setProperty(String name, Object value) {
        if (locked) {
            throw new IllegalStateException("Node is locked");
        }
        properties.put(name, value);
    }

    public Object getProperty(String name) {
        return properties.get(name); // Code smell: no validation for property existence
    }

    public void removeChildNode(String name) {
        if (locked) {
            throw new IllegalStateException("Node is locked");
        }
        childNodes.removeIf(child -> child.nodeName.equals(name));
    }

    public void lock() {
        locked = true;
    }

    public void unlock() {
        locked = false;
    }

    public void addMixin(String mixin) {
        mixins.add(mixin);
    }

    public void removeMixin(String mixin) {
        mixins.remove(mixin);
    }

    public boolean hasMixin(String mixin) {
        return mixins.contains(mixin);
    }

    public String getPath() {
        // Code smell: path resolution logic not implemented
        return "/" + nodeName;
    }

    public String getVersion() {
        return version;
    }

    public void incrementVersion() {
        // Code smell: simplistic versioning logic
        version = String.valueOf(Integer.parseInt(version) + 1);
    }

    public List<NodeImpl> getChildNodes() {
        return Collections.unmodifiableList(childNodes); // Code smell: exposing internal structure
    }

    public void cloneNode(NodeImpl sourceNode) {
        // Code smell: shallow copy, not handling deep cloning
        this.nodeName = sourceNode.nodeName;
        this.nodeType = sourceNode.nodeType;
        this.properties = new HashMap<>(sourceNode.properties);
        this.childNodes = new ArrayList<>(sourceNode.childNodes);
        this.mixins = new HashSet<>(sourceNode.mixins);
        this.version = sourceNode.version;
    }
}

