    private int line;
    private int column;
    private Reader inputStream;

    public SimpleCharStream(Reader inputStream, int bufferSize) {
        this.inputStream = inputStream;
        this.bufferSize = bufferSize;
        this.buffer = new char[bufferSize];
        this.bufferPosition = 0;
        this.line = 1;
        this.column = 0;
        fillBuffer();
    }

    private void fillBuffer() {
        try {
            int charsRead = inputStream.read(buffer);
            if (charsRead == -1) {
                buffer[0] = '\0'; // End of stream
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public char readChar() {
        if (bufferPosition >= buffer.length) {
            fillBuffer();
            bufferPosition = 0;
        }
        char ch = buffer[bufferPosition++];
        if (ch == '\n') {
            line++;
            column = 0;
        } else {
            column++;
        }
        return ch;
    }

    public void backtrack() {
        if (bufferPosition > 0) {
            bufferPosition--;
            char ch = buffer[bufferPosition];
            if (ch == '\n') {
                line--;
                // Column tracking is not accurate here, could be a code smell
            } else {
                column--;
            }
        }
    }

    public int getCurrentLine() {
        return line;
    }

    public int getCurrentColumn() {
        return column;
    }

    public String getImage() {
        return new String(buffer, 0, bufferPosition);
    }

    public void reinitialize(Reader newInputStream) {
        this.inputStream = newInputStream;
        this.bufferPosition = 0;
        this.line = 1;
        this.column = 0;
        fillBuffer();
    }

    public String getSuffix(int length) {
        if (length > buffer.length - bufferPosition) {
            length = buffer.length - bufferPosition;
        }
        return new String(buffer, bufferPosition, length);
    }
}

