public class DefaultActionPreparator {

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.FIELD)
    public @interface Option {
        String name();
        boolean required() default false;
        String description() default "";
    }

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.FIELD)
    public @interface Argument {
        String name();
        boolean required() default false;
        String description() default "";
    }

    private final Map<String, Object> options = new HashMap<>();
    private final List<String> arguments = new ArrayList<>();

    public void prepare(Object command) throws IllegalAccessException {
        Field[] fields = command.getClass().getDeclaredFields();
        for (Field field : fields) {
            if (field.isAnnotationPresent(Option.class)) {
                Option option = field.getAnnotation(Option.class);
                field.setAccessible(true);
                options.put(option.name(), field.get(command));
                if (option.required() && field.get(command) == null) {
                    throw new IllegalArgumentException("Required option " + option.name() + " is missing.");
                }
            } else if (field.isAnnotationPresent(Argument.class)) {
                Argument argument = field.getAnnotation(Argument.class);
                field.setAccessible(true);
                arguments.add((String) field.get(command));
                if (argument.required() && field.get(command) == null) {
                    throw new IllegalArgumentException("Required argument " + argument.name() + " is missing.");
                }
            }
        }
    }

    public void printUsage(Class<?> commandClass) {
        System.out.println("Usage for " + commandClass.getSimpleName() + ":");
        for (Field field : commandClass.getDeclaredFields()) {
            if (field.isAnnotationPresent(Option.class)) {
                Option option = field.getAnnotation(Option.class);
                System.out.println("--" + option.name() + ": " + option.description() + (option.required() ? " (required)" : ""));
            } else if (field.isAnnotationPresent(Argument.class)) {
                Argument argument = field.getAnnotation(Argument.class);
                System.out.println("<" + argument.name() + ">: " + argument.description() + (argument.required() ? " (required)" : ""));
            }
        }
    }

    public Map<String, Object> getOptions() {
        return options;
    }

    public List<String> getArguments() {
        return arguments;
    }
}

