public class MultiReader extends Reader {
    private List<Resource> resources;
    private int currentResourceIndex;
    private Reader currentReader;
    private StringBuilder lastChars;
    private static final int LAST_CHARS_LENGTH = 2;

    public MultiReader(List<Resource> resources) {
        this.resources = resources;
        this.currentResourceIndex = 0;
        this.lastChars = new StringBuilder();
        if (!resources.isEmpty()) {
            this.currentReader = resources.get(0).getReader();
        }
    }

    @Override
    public int read(char[] cbuf, int off, int len) throws IOException {
        int totalRead = 0;
        while (totalRead < len) {
            if (currentReader == null) {
                break;
            }
            int read = currentReader.read(cbuf, off + totalRead, len - totalRead);
            if (read == -1) {
                closeCurrentReader();
                currentResourceIndex++;
                if (currentResourceIndex < resources.size()) {
                    currentReader = resources.get(currentResourceIndex).getReader();
                    if (totalRead > 0 && !lastChars.toString().endsWith("\n")) {
                        cbuf[off + totalRead] = '\n';
                        totalRead++;
                    }
                } else {
                    currentReader = null;
                    break;
                }
            } else {
                totalRead += read;
                updateLastChars(cbuf, off + totalRead - read, read);
            }
        }
        return totalRead > 0 ? totalRead : -1;
    }

    private void updateLastChars(char[] cbuf, int start, int length) {
        for (int i = start; i < start + length; i++) {
            lastChars.append(cbuf[i]);
            if (lastChars.length() > LAST_CHARS_LENGTH) {
                lastChars.deleteCharAt(0);
            }
        }
    }

    private void closeCurrentReader() throws IOException {
        if (currentReader != null) {
            currentReader.close();
        }
    }

    @Override
    public void close() throws IOException {
        closeCurrentReader();
    }

    @Override
    public int read() throws IOException {
        char[] cbuf = new char[1];
        int result = read(cbuf, 0, 1);
        return result == -1 ? -1 : cbuf[0];
    }
}

public class OrderedCode {
    private static final byte ESCAPE1 = (byte) 0xFF;
    private static final byte ESCAPE2 = (byte) 0xFE;
    private static final byte SEPARATOR = (byte) 0x00;

    private List<byte[]> encodedData;
    private int currentPosition;

    public OrderedCode() {
        this.encodedData = new ArrayList<>();
        this.currentPosition = 0;
    }

    public void encode(byte[] data) {
        List<Byte> encodedBytes = new ArrayList<>();
        for (byte b : data) {
            if (b == ESCAPE1 || b == ESCAPE2 || b == SEPARATOR) {
                encodedBytes.add(ESCAPE1);
                encodedBytes.add(b);
            } else {
                encodedBytes.add(b);
            }
        }
        encodedBytes.add(SEPARATOR);
        byte[] encodedArray = new byte[encodedBytes.size()];
        for (int i = 0; i < encodedBytes.size(); i++) {
            encodedArray[i] = encodedBytes.get(i);
        }
        encodedData.add(encodedArray);
    }

    public byte[] decode() {
        if (currentPosition >= encodedData.size()) {
            return null;
        }
        byte[] data = encodedData.get(currentPosition++);
        List<Byte> decodedBytes = new ArrayList<>();
        for (int i = 0; i < data.length; i++) {
            if (data[i] == ESCAPE1 && i + 1 < data.length) {
                decodedBytes.add(data[i + 1]);
                i++;
            } else if (data[i] == SEPARATOR) {
                break;
            } else {
                decodedBytes.add(data[i]);
            }
        }
        byte[] result = new byte[decodedBytes.size()];
        for (int i = 0; i < decodedBytes.size(); i++) {
            result[i] = decodedBytes.get(i);
        }
        return result;
    }

    public boolean hasMoreData() {
        return currentPosition < encodedData.size();
    }

    public byte[] getCompleteEncodedData() {
        int totalLength = 0;
        for (byte[] array : encodedData) {
            totalLength += array.length;
        }
        byte[] completeData = new byte[totalLength];
        int offset = 0;
        for (byte[] array : encodedData) {
            System.arraycopy(array, 0, completeData, offset, array.length);
            offset += array.length;
        }
        return completeData;
    }

    public void writeUnsignedInt(int value) {
        // Implementation for writing unsigned int in compact format
    }

    public void writeSignedInt(int value) {
        // Implementation for writing signed int in compact format
    }

    public void handleSpecialValue(double value) {
