public class MetaPattern implements IClusterable {
    private List<MetaPattern> patterns;
    private String patternString;
    private Pattern compiledPattern;

    public MetaPattern(String patternString) {
        this.patternString = patternString;
        this.compiledPattern = Pattern.compile(patternString);
        this.patterns = new ArrayList<>();
    }

    public void addPattern(MetaPattern metaPattern) {
        patterns.add(metaPattern);
        updateCompiledPattern();
    }

    private void updateCompiledPattern() {
        StringBuilder combinedPattern = new StringBuilder();
        for (MetaPattern pattern : patterns) {
            combinedPattern.append(pattern.patternString);
        }
        this.compiledPattern = Pattern.compile(combinedPattern.toString());
    }

    public boolean matches(String input) {
        return compiledPattern.matcher(input).matches();
    }

    public static MetaPattern whitespace() {
        return new MetaPattern("\\s+");
    }

    public static MetaPattern digits() {
        return new MetaPattern("\\d+");
    }

    public static MetaPattern words() {
        return new MetaPattern("\\w+");
    }

    public static MetaPattern specialCharacters() {
        return new MetaPattern("[^a-zA-Z0-9]");
    }

    @Override
    public String toString() {
        return patternString;
    }
}

