class TestBitsInt {

    @Test
    public void testMask() {
        assertEquals(0b00000001, BitsInt.mask(0));
        assertEquals(0b00000010, BitsInt.mask(1));
        assertEquals(0b00000100, BitsInt.mask(2));
    }

    @Test
    public void testMaskZero() {
        assertEquals(0b00000000, BitsInt.maskZero(0));
        assertEquals(0b11111110, BitsInt.maskZero(1));
        assertEquals(0b11111011, BitsInt.maskZero(2));
    }

    @Test
    public void testClear() {
        assertEquals(0b00000000, BitsInt.clear(0b00000001, 0));
        assertEquals(0b00000000, BitsInt.clear(0b00000011, 0));
        assertEquals(0b00000001, BitsInt.clear(0b00000011, 1));
    }

    @Test
    public void testSet() {
        assertEquals(0b00000001, BitsInt.set(0b00000000, 0));
        assertEquals(0b00000011, BitsInt.set(0b00000001, 1));
        assertEquals(0b00000101, BitsInt.set(0b00000001, 2));
    }

    @Test
    public void testSetBit() {
        assertEquals(0b00000001, BitsInt.setBit(0b00000000, 0, true));
        assertEquals(0b00000000, BitsInt.setBit(0b00000001, 0, false));
    }

    @Test
    public void testTest() {
        assertTrue(BitsInt.test(0b00000001, 0));
        assertFalse(BitsInt.test(0b00000000, 0));
    }

    @Test
    public void testBitsTest() {
        assertTrue(BitsInt.bitsTest(0b00000011, 0b00000011));
        assertFalse(BitsInt.bitsTest(0b00000011, 0b00000111));
    }

    @Test
    public void testAccess() {
        assertEquals(1, BitsInt.access(0b00000001, 0));
        assertEquals(0, BitsInt.access(0b00000000, 0));
    }

    @Test
    public void testPack() {
        assertEquals(0b00000001, BitsInt.pack(0b00000000, 0, 1));
        assertEquals(0b00000011, BitsInt.pack(0b00000001, 0, 2));
    }

    @Test
    public void testUnpack() {
        assertEquals(1, BitsInt.unpack(0b00000001, 0));
        assertEquals(3, BitsInt.unpack(0b00000011, 0));
    }
}

