                return producerClient.sendEvent(modifiedEventData).block();
            } catch (Exception e) {
                skippedEvents.incrementAndGet();
                // Handle exception
                return null;
            }
        }).thenAccept(event -> eventCount.incrementAndGet());
    }

    @Override
    public void stop() {
        if (producerClient != null) {
            producerClient.close();
        }
