public class WeblogRequestMapper implements RequestMapper {
    private Set<String> restrictedUrls;

    public WeblogRequestMapper() {
        this.restrictedUrls = new HashSet<>();
        initializeRestrictedUrls();
    }

    private void initializeRestrictedUrls() {
        // Load restricted URLs from configuration properties
        // Code smell: Hardcoded logic for loading properties
        restrictedUrls.add("/admin");
        restrictedUrls.add("/private");
    }

    @Override
    public String mapRequest(HttpRequest request) {
        String uri = request.getUri();
        String weblogHandle = extractWeblogHandle(uri);

        if (!isValidWeblogHandle(weblogHandle) || isRestrictedUrl(uri)) {
            return handleInvalidRequest();
        }

        String locale = extractLocale(request);
        String context = extractContext(request);
        String data = extractData(request);

        return determineForwardUrl(weblogHandle, locale, context, data);
    }

    private String extractWeblogHandle(String uri) {
        // Code smell: Assumes specific URI structure
        return uri.split("/")[1];
    }

    private boolean isValidWeblogHandle(String weblogHandle) {
        // Code smell: Simple validation logic
        return weblogHandle != null && !weblogHandle.isEmpty();
    }

    private boolean isRestrictedUrl(String uri) {
        return restrictedUrls.contains(uri);
    }

    private String handleInvalidRequest() {
        // Code smell: Returning a generic error response
        return "HTTP 404 Not Found";
    }

    private String extractLocale(HttpRequest request) {
        // Code smell: Assumes locale is always present
        return request.getHeader("Accept-Language");
    }

    private String extractContext(HttpRequest request) {
        // Code smell: Context extraction logic could be more robust
        return request.getContext();
    }

    private String extractData(HttpRequest request) {
        // Code smell: Assumes data is always present
        return request.getBody();
    }

    private String determineForwardUrl(String weblogHandle, String locale, String context, String data) {
        // Code smell: Logic for determining forward URL could be simplified
        return "/weblog/" + weblogHandle + "?locale=" + locale + "&context=" + context;
    }
}

