public abstract class AbstractFileName implements FileName {
    protected String scheme;
    protected String absolutePath;
    protected String fileType;
    protected URI uri;
    protected String baseName;
    protected String rootURI;
    protected String fileExtension;

    public AbstractFileName(String scheme, String absolutePath, String fileType) {
        this.scheme = scheme;
        this.absolutePath = absolutePath;
        this.fileType = fileType;
        this.baseName = extractBaseName(absolutePath);
        this.fileExtension = extractFileExtension(baseName);
        try {
            this.uri = new URI(scheme + "://" + absolutePath);
        } catch (URISyntaxException e) {
            e.printStackTrace();
        }
    }

    private String extractBaseName(String path) {
        // Code smell: Could be improved with regex or more robust logic
        int lastSlashIndex = path.lastIndexOf('/');
        return (lastSlashIndex == -1) ? path : path.substring(lastSlashIndex + 1);
    }

    private String extractFileExtension(String baseName) {
        // Code smell: Could be improved to handle multiple dots
        int lastDotIndex = baseName.lastIndexOf('.');
        return (lastDotIndex == -1) ? "" : baseName.substring(lastDotIndex + 1);
    }

    public URI createURI() {
        return uri;
    }

    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof AbstractFileName)) return false;
        AbstractFileName other = (AbstractFileName) obj;
        return this.absolutePath.equals(other.absolutePath);
    }

    public int hashCode() {
        return absolutePath.hashCode();
    }

    public String getBaseName() {
        return baseName;
    }

    public String getAbsolutePath() {
        return absolutePath;
    }

    public boolean isAncestorOf(AbstractFileName other) {
        return other.absolutePath.startsWith(this.absolutePath);
    }

    public boolean isDescendantOf(AbstractFileName other) {
        return this.absolutePath.startsWith(other.absolutePath);
    }

    public int calculateDepth() {
        // Code smell: Could be simplified or made more efficient
        return absolutePath.split("/").length;
    }

    public String decodePath(String path) {
        // Code smell: Could use better error handling
        return path.replace("%20", " ");
    }

    public String getFileType() {
        return fileType;
    }
}

