        String actualRegex = GcsUtil.translateGlobToRegex(pattern);
        assertEquals(expectedRegex, actualRegex);
    }

    @Test
    public void testGcsOptionsCreation() {
        GcsOptions options = GcsUtil.createGcsOptions(null, 1024);
        assertNotNull(options);
        assertEquals(1024, options.getBufferSize());
    }

    @Test
    public void testConcurrency() throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(10);
        for (int i = 0; i < 10; i++) {
            executor.submit(() -> {
                GcsUtil.uploadFile("gs://bucket/file.txt", "content");
            });
        }
        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);
        assertTrue(GcsUtil.fileExists("gs://bucket/file.txt"));
    }

    @Test
    public void testFileOperations() {
        GcsUtil.uploadFile("gs://bucket/file.txt", "content");
        assertTrue(GcsUtil.fileExists("gs://bucket/file.txt"));
        GcsUtil.deleteFile("gs://bucket/file.txt");
        assertFalse(GcsUtil.fileExists("gs://bucket/file.txt"));
    }

    @Test
    public void testBucketOperations() {
        GcsUtil.createBucket("test-bucket");
        assertTrue(GcsUtil.bucketExists("test-bucket"));
        GcsUtil.deleteBucket("test-bucket");
        assertFalse(GcsUtil.bucketExists("test-bucket"));
    }

    @Test
    public void testBatchOperations() {
        GcsUtil.createBatchRequest();
        GcsUtil.addCopyOperation("source.txt", "destination.txt");
        GcsUtil.executeBatch();
        assertTrue(GcsUtil.fileExists("destination.txt"));
    }

    @Test
    public void testErrorHandling() {
        Exception exception = assertThrows(FileNotFoundException.class, () -> {
            GcsUtil.downloadFile("gs://bucket/nonexistent.txt");
        });
        assertEquals("File not found", exception.getMessage());

        exception = assertThrows(AccessDeniedException.class, () -> {
            GcsUtil.uploadFile("gs://bucket/protected.txt", "content");
        });
        assertEquals("Access denied", exception.getMessage());
    }
}

