    public static final String EDGE_PROPERTIES_KEY = "edgeProperties";
    public static final String SERVICE_PLUGIN_INFO_KEY = "servicePluginInfo";

    // Method to convert DAG plans to JSON
    public static JSONObject convertDAGPlanToJSON(DAG dag) {
        JSONObject json = new JSONObject();
        json.put(DAG_NAME_KEY, dag.getName());
        json.put(VERTEX_COUNT_KEY, dag.getVertexCount());
        json.put(EDGE_COUNT_KEY, dag.getEdgeCount());
        json.put(VERTEX_STATISTICS_KEY, convertVertexStatisticsToJSON(dag.getVertexStatistics()));
        json.put(EDGE_PROPERTIES_KEY, convertEdgePropertiesToJSON(dag.getEdgeProperties()));
        json.put(SERVICE_PLUGIN_INFO_KEY, convertServicePluginInfoToJSON(dag.getServicePluginInfo()));
        return json;
    }

    // Method to convert vertex statistics to JSON
    private static JSONObject convertVertexStatisticsToJSON(Map<String, Object> vertexStatistics) {
        JSONObject json = new JSONObject();
        for (Map.Entry<String, Object> entry : vertexStatistics.entrySet()) {
            json.put(entry.getKey(), entry.getValue());
        }
        return json;
    }

    // Method to convert edge properties to JSON
    private static JSONObject convertEdgePropertiesToJSON(Map<String, Object> edgeProperties) {
        JSONObject json = new JSONObject();
        for (Map.Entry<String, Object> entry : edgeProperties.entrySet()) {
            json.put(entry.getKey(), entry.getValue());
        }
        return json;
    }

    // Method to convert service plugin information to JSON
    private static JSONObject convertServicePluginInfoToJSON(Map<String, Object> servicePluginInfo) {
        JSONObject json = new JSONObject();
        for (Map.Entry<String, Object> entry : servicePluginInfo.entrySet()) {
            json.put(entry.getKey(), entry.getValue());
        }
        return json;
    }

    // Method to create DAG information map
    public static Map<String, Object> createDAGInfoMap(DAG dag) {
        Map<String, Object> dagInfoMap = new HashMap<>();
        dagInfoMap.put(DAG_NAME_KEY, dag.getName());
        dagInfoMap.put(VERTEX_COUNT_KEY, dag.getVertexCount());
        dagInfoMap.put(EDGE_COUNT_KEY, dag.getEdgeCount());
        return dagInfoMap;
    }
}

public abstract class AbstractDFSCarbonFile implements CarbonFile {
    protected FileSystem fileSystem;
    protected Path path;

    public AbstractDFSCarbonFile(FileSystem fileSystem, Path path) {
        this.fileSystem = fileSystem;
        this.path = path;
    }

    @Override
    public boolean create() throws CarbonFileException {
        try {
            if (!exists()) {
                fileSystem.create(path).close();
                return true;
            }
            return false;
        } catch (IOException e) {
            throw new CarbonFileException("Error creating file: " + path, e);
        }
    }

    @Override
    public boolean delete() throws CarbonFileException {
        try {
            return fileSystem.delete(path, false);
        } catch (IOException e) {
            throw new CarbonFileException("Error deleting file: " + path, e);
        }
    }

    @Override
    public boolean rename(String newName) throws CarbonFileException {
        try {
            Path newPath = new Path(path.getParent(), newName);
            return fileSystem.rename(path, newPath);
        } catch (IOException e) {
            throw new CarbonFileException("Error renaming file: " + path, e);
        }
    }

    @Override
    public boolean exists() throws CarbonFileException {
        try {
            return fileSystem.exists(path);
        } catch (IOException e) {
            throw new CarbonFileException("Error checking existence of file: " + path, e);
        }
    }

    @Override
    public InputStream open() throws CarbonFileException {
        try {
            return fileSystem.open(path);
        } catch (IOException e) {
            throw new CarbonFileException("Error opening file: " + path, e);
        }
    }

    @Override
    public OutputStream createOutputStream() throws CarbonFileException {
        try {
            return fileSystem.create(path);
        } catch (IOException e) {
            throw new CarbonFileException("Error creating output stream for file: " + path, e);
        }
    }

    @Override
    public long getSize() throws CarbonFileException {
        try {
            return fileSystem.getFileStatus(path).getLen();
        } catch (IOException e) {
            throw new CarbonFileException("Error getting size of file: " + path, e);
        }
    }

    @Override
    public long getLastModifiedTime() throws CarbonFileException {
        try {
            return fileSystem.getFileStatus(path).getModificationTime();
        } catch (IOException e) {
            throw new CarbonFileException("Error getting last modified time of file: " + path, e);
        }
    }

    @Override
    public String getAbsolutePath() {
        return path.toString();
    }

    @Override
    public List<CarbonFile> listFiles(boolean recursive) throws CarbonFileException {
        // Code smell: This method should be implemented in subclasses for specific behavior
        return null;
    }

    @Override
    public boolean setPermission(String permission) throws CarbonFileException {
        try {
            fileSystem.setPermission(path, new org.apache.hadoop.fs.permission.FsPermission(permission));
            return true;
        } catch (IOException e) {
            throw new CarbonFileException("Error setting permission for file: " + path, e);
        }
    }

    @Override
    public void setReplication(short replication) throws CarbonFileException {
        try {
            fileSystem.setReplication(path, replication);
        } catch (IOException e) {
            throw new CarbonFileException("Error setting replication for file: " + path, e);
        }
    }
}

public class SparseFieldMatrixTest {
    private SparseFieldMatrix<Fraction> matrixA;
    private SparseFieldMatrix<Fraction> matrixB;
    private SparseFieldMatrix<Fraction> identityMatrix;
    private SparseFieldMatrix<Fraction> singularMatrix;
    private SparseFieldMatrix<Fraction> resultMatrix;

    @BeforeEach
    public void setUp() {
        matrixA = new SparseFieldMatrix<>(new Fraction[][] {
            {new Fraction(1, 2), new Fraction(0)},
            {new Fraction(0), new Fraction(3, 4)}
        });

        matrixB = new SparseFieldMatrix<>(new Fraction[][] {
            {new Fraction(1, 4), new Fraction(1)},
            {new Fraction(0), new Fraction(1, 2)}
        });

        identityMatrix = SparseFieldMatrix.identity(2);
        singularMatrix = new SparseFieldMatrix<>(new Fraction[][] {
            {new Fraction(1), new Fraction(2)},
            {new Fraction(2), new Fraction(4)}
        });
    }

    @Test
    public void testMatrixAddition() {
        resultMatrix = matrixA.add(matrixB);
        SparseFieldMatrix<Fraction> expected = new SparseFieldMatrix<>(new Fraction[][] {
            {new Fraction(3, 4), new Fraction(1)},
            {new Fraction(0), new Fraction(3, 4)}
        });
        assertEquals(expected, resultMatrix);
    }

    @Test
    public void testMatrixSubtraction() {
        resultMatrix = matrixA.subtract(matrixB);
        SparseFieldMatrix<Fraction> expected = new SparseFieldMatrix<>(new Fraction[][] {
            {new Fraction(1, 4), new Fraction(-1)},
            {new Fraction(0), new Fraction(3, 4)}
        });
        assertEquals(expected, resultMatrix);
    }

    @Test
    public void testMatrixMultiplication() {
        resultMatrix = matrixA.multiply(matrixB);
        SparseFieldMatrix<Fraction> expected = new SparseFieldMatrix<>(new Fraction[][] {
            {new Fraction(1, 8), new Fraction(1, 2)},
            {new Fraction(0), new Fraction(3, 8)}
        });
        assertEquals(expected, resultMatrix);
    }

    @Test
    public void testScalarAddition() {
        resultMatrix = matrixA.add(new Fraction(1));
        SparseFieldMatrix<Fraction> expected = new SparseFieldMatrix<>(new Fraction[][] {
            {new Fraction(3, 2), new Fraction(1)},
            {new Fraction(0), new Fraction(7, 4)}
        });
        assertEquals(expected, resultMatrix);
    }

    @Test
    public void testMatrixDimensions() {
        assertEquals(2, matrixA.getRowDimension());
        assertEquals(2, matrixA.getColumnDimension());
    }

    @Test
    public void testMatrixTransposition() {
        resultMatrix = matrixA.transpose();
        SparseFieldMatrix<Fraction> expected = new SparseFieldMatrix<>(new Fraction[][] {
            {new Fraction(1, 2), new Fraction(0)},
            {new Fraction(3, 4), new Fraction(0)}
        });
        assertEquals(expected, resultMatrix);
    }

    @Test
    public void testMatrixTrace() {
        Fraction trace = matrixA.getTrace();
        assertEquals(new Fraction(1, 2).add(new Fraction(3, 4)), trace);
    }

    @Test
    public void testSingularMatrixException() {
        assertThrows(SingularMatrixException.class, () -> {
            singularMatrix.inverse();
        });
    }

    @Test
    public void testInvalidOperationException() {
        assertThrows(IllegalArgumentException.class, () -> {
            matrixA.add(null);
        });
    }
}

