public class PropertyImpl implements Property {
    private static final Logger logger = Logger.getLogger(PropertyImpl.class.getName());

    private String name;
    private List<Object> values;
    private String type;
    private boolean isMultiValued;
    private boolean isTransient;

    public PropertyImpl(String name, String type, boolean isMultiValued) {
        this.name = name;
        this.type = type;
        this.isMultiValued = isMultiValued;
        this.values = new ArrayList<>();
        this.isTransient = true; // Default to transient
    }

    public void setValue(Object value) {
        if (!isMultiValued) {
            validateValue(value);
            values.clear();
            values.add(value);
        } else {
            validateValue(value);
            values.add(value);
        }
        isTransient = false; // Set to persistent after setting value
        logger.info("Value set for property: " + name);
    }

    public List<Object> getValues() {
        return new ArrayList<>(values);
    }

    public String getName() {
        return name;
    }

    public String getType() {
        return type;
    }

    public boolean isMultiValued() {
        return isMultiValued;
    }

    public boolean isTransient() {
        return isTransient;
    }

    private void validateValue(Object value) {
        if (value == null) {
            throw new IllegalArgumentException("Value cannot be null for property: " + name);
        }
        // Additional type checks can be added here
    }

    public int getLength() {
        int length = 0;
        for (Object value : values) {
            if (value instanceof String) {
                length += ((String) value).length();
            }
        }
        return length;
    }

    public Object convertValue(String value) {
        // Simple conversion logic based on type
        switch (type) {
            case "String":
                return value;
            case "Integer":
                return Integer.valueOf(value);
            case "Boolean":
                return Boolean.valueOf(value);
            // Add more types as needed
            default:
                throw new UnsupportedOperationException("Type conversion not supported for: " + type);
        }
    }
}

