public class MicroMap<K, V> implements Map<K, V>, Serializable {
    private static final long serialVersionUID = 1L;
    private K key;
    private V value;
    private boolean isPresent;

    public MicroMap() {
        this.isPresent = false;
    }

    @Override
    public V put(K key, V value) {
        if (isPresent) {
            throw new IllegalStateException("MicroMap can only hold one key-value pair.");
        }
        this.key = key;
        this.value = value;
        this.isPresent = true;
        return null;
    }

    @Override
    public V get(Object key) {
        if (isPresent && this.key.equals(key)) {
            return value;
        }
        return null;
    }

    @Override
    public V remove(Object key) {
        if (isPresent && this.key.equals(key)) {
            V oldValue = value;
            key = null;
            value = null;
            isPresent = false;
            return oldValue;
        }
        return null;
    }

    @Override
    public void clear() {
        key = null;
        value = null;
        isPresent = false;
    }

    @Override
    public boolean containsKey(Object key) {
        return isPresent && this.key.equals(key);
    }

    @Override
    public boolean containsValue(Object value) {
        return isPresent && this.value.equals(value);
    }

    @Override
    public Set<K> keySet() {
        if (isPresent) {
            return new HashSet<>(Collections.singleton(key));
        }
        return Collections.emptySet();
    }

    @Override
    public Set<V> values() {
        if (isPresent) {
            return new HashSet<>(Collections.singleton(value));
        }
        return Collections.emptySet();
    }

    @Override
    public Set<Map.Entry<K, V>> entrySet() {
        if (isPresent) {
            return Collections.singleton(new AbstractMap.SimpleEntry<>(key, value));
        }
        return Collections.emptySet();
    }

    @Override
    public int size() {
        return isPresent ? 1 : 0;
    }

    public boolean isFull() {
        return isPresent;
    }

    public boolean isEmpty() {
        return !isPresent;
    }
}

