public class YarnDriverRuntimeRestartManager {
    private static final Logger logger = LoggerFactory.getLogger(YarnDriverRuntimeRestartManager.class);

    private EvaluatorPreserver evaluatorPreserver;
    private ApplicationMasterRegistration appMasterRegistration;
    private YarnContainerManager yarnContainerManager;

    private int maxResubmissionAttempts;
    private int currentAttempt;

    public YarnDriverRuntimeRestartManager(EvaluatorPreserver evaluatorPreserver, 
                                           ApplicationMasterRegistration appMasterRegistration, 
                                           YarnContainerManager yarnContainerManager, 
                                           int maxResubmissionAttempts) {
        this.evaluatorPreserver = evaluatorPreserver;
        this.appMasterRegistration = appMasterRegistration;
        this.yarnContainerManager = yarnContainerManager;
        this.maxResubmissionAttempts = maxResubmissionAttempts;
        this.currentAttempt = 0;
    }

    public void restartDriver() {
        if (currentAttempt >= maxResubmissionAttempts) {
            logger.warn("Maximum resubmission attempts reached. Cannot restart the driver.");
            return;
        }

        logger.info("Attempting to restart the driver. Attempt number: {}", currentAttempt + 1);

        try {
            recoverEvaluators();
            yarnContainerManager.restartContainers();
            currentAttempt++;
            logger.info("Driver restarted successfully.");
        } catch (Exception e) {
            logger.error("Failed to restart the driver: {}", e.getMessage());
        }
    }

    private void recoverEvaluators() {
        logger.info("Recovering evaluators...");
        // Logic to recover evaluators
        evaluatorPreserver.restoreEvaluators();
    }

    public int getCurrentAttempt() {
        return currentAttempt;
    }

    public void resetAttempts() {
        currentAttempt = 0;
        logger.info("Resubmission attempts have been reset.");
    }
}

