public class ArrayUtils {
    public static final int[] EMPTY_INT_ARRAY = new int[0];
    public static final String[] EMPTY_STRING_ARRAY = new String[0];
    public static final int NOT_FOUND_INDEX = -1;

    public static String arrayToString(Object[] array) {
        return Arrays.toString(nullToEmpty(array));
    }

    public static Map<Object, Integer> arrayToMap(Object[] array) {
        Map<Object, Integer> map = new HashMap<>();
        for (Object obj : nullToEmpty(array)) {
            map.put(obj, map.getOrDefault(obj, 0) + 1);
        }
        return map;
    }

    public static Object[] cloneArray(Object[] array) {
        return array == null ? EMPTY_STRING_ARRAY : array.clone();
    }

    public static <T> T[] nullToEmpty(T[] array) {
        return array == null ? (T[]) EMPTY_STRING_ARRAY : array;
    }

    public static int[] nullToEmpty(int[] array) {
        return array == null ? EMPTY_INT_ARRAY : array;
    }

    public static Object[] subArray(Object[] array, int start, int end) {
        return Arrays.copyOfRange(nullToEmpty(array), start, end);
    }

    public static boolean areSameLengthAndType(Object[] array1, Object[] array2) {
        return (array1.length == array2.length) && (array1.getClass() == array2.getClass());
    }

    public static <T> void reverseArray(T[] array) {
        for (int i = 0; i < array.length / 2; i++) {
            T temp = array[i];
            array[i] = array[array.length - 1 - i];
            array[array.length - 1 - i] = temp;
        }
    }

    public static int indexOf(Object[] array, Object element) {
        for (int i = 0; i < nullToEmpty(array).length; i++) {
            if (nullToEmpty(array)[i].equals(element)) {
                return i;
            }
        }
        return NOT_FOUND_INDEX;
    }

    public static int lastIndexOf(Object[] array, Object element) {
        for (int i = nullToEmpty(array).length - 1; i >= 0; i--) {
            if (nullToEmpty(array)[i].equals(element)) {
                return i;
            }
        }
        return NOT_FOUND_INDEX;
    }

    public static boolean contains(Object[] array, Object element) {
        return indexOf(array, element) != NOT_FOUND_INDEX;
    }

    public static int length(Object[] array) {
        return nullToEmpty(array).length;
    }

    public static boolean isEmpty(Object[] array) {
        return length(array) == 0;
    }

    public static Object[] addElement(Object[] array, Object element) {
        Object[] newArray = Arrays.copyOf(nullToEmpty(array), length(array) + 1);
        newArray[newArray.length - 1] = element;
        return newArray;
    }

    public static Object[] removeElement(Object[] array, Object element) {
        int index = indexOf(array, element);
        if (index == NOT_FOUND_INDEX) {
            return array;
        }
        Object[] newArray = new Object[length(array) - 1];
        System.arraycopy(array, 0, newArray, 0, index);
        System.arraycopy(array, index + 1, newArray, index, length(array) - index - 1);
        return newArray;
    }

    public static int[] addElement(int[] array, int element) {
        int[] newArray = Arrays.copyOf(nullToEmpty(array), length(array) + 1);
        newArray[newArray.length - 1] = element;
        return newArray;
    }

    public static int[] removeElement(int[] array, int element) {
        int index = indexOf(array, element);
        if (index == NOT_FOUND_INDEX) {
            return array;
        }
        int[] newArray = new int[length(array) - 1];
        System.arraycopy(array, 0, newArray, 0, index);
        System.arraycopy(array, index + 1, newArray, index, length(array) - index - 1);
        return newArray;
    }

    public static Integer[] toIntegerArray(int[] array) {
        Integer[] newArray = new Integer[array.length];
        for (int i = 0; i < array.length; i++) {
            newArray[i] = array[i];
        }
        return newArray;
    }

    public static int[] toIntArray(Integer[] array) {
        int[] newArray = new int[array.length];
        for (int i = 0; i < array.length; i++) {
            newArray[i] = array[i];
        }
        return newArray;
    }
}

