public class DefaultUpdateCheckManager {
    private Map<String, Long> lastUpdateCheckMap = new HashMap<>();
    private String repositoryPath;

    public DefaultUpdateCheckManager(String repositoryPath) {
        this.repositoryPath = repositoryPath;
    }

    public boolean isUpdateNeeded(String artifactId, boolean isSnapshot) {
        String key = constructKey(artifactId, isSnapshot);
        File artifactFile = new File(repositoryPath, artifactId);
        if (!artifactFile.exists()) {
            logDebug("Artifact does not exist: " + artifactId);
            return true;
        }

        long lastModified = artifactFile.lastModified();
        Long lastUpdateCheck = lastUpdateCheckMap.get(key);
        if (lastUpdateCheck == null || lastModified > lastUpdateCheck) {
            logDebug("Update needed for artifact: " + artifactId);
            return true;
        }

        logDebug("No update needed for artifact: " + artifactId);
        return false;
    }

    public void updateLastChecked(String artifactId, boolean isSnapshot) {
        String key = constructKey(artifactId, isSnapshot);
        lastUpdateCheckMap.put(key, System.currentTimeMillis());
        writeTouchFile(key);
    }

    private String constructKey(String artifactId, boolean isSnapshot) {
        return artifactId + (isSnapshot ? "-SNAPSHOT" : "-RELEASE");
    }

    private void writeTouchFile(String key) {
        Path touchFilePath = Paths.get(repositoryPath, key + ".touch");
        try {
            Files.write(touchFilePath, String.valueOf(System.currentTimeMillis()).getBytes());
        } catch (IOException e) {
            logError("Failed to write touch file for key: " + key, e);
        }
    }

    private void logDebug(String message) {
        System.out.println("DEBUG: " + message);
    }

    private void logError(String message, Exception e) {
        System.err.println("ERROR: " + message + " - " + e.getMessage());
    }
}

