public class PolygonsSetTest {

    @Test
    public void testSimplyConnectedPolygons() {
        PolygonsSet polygon = new PolygonsSet(new double[][]{{0, 0}, {1, 0}, {1, 1}, {0, 1}});
        assertTrue(polygon.contains(0.5, 0.5)); // inside
        assertFalse(polygon.contains(1.5, 0.5)); // outside
        assertTrue(polygon.onBoundary(0, 0)); // boundary
        assertArrayEquals(new double[]{0, 0}, polygon.getVertices()[0], 1e-10);
    }

    @Test
    public void testBoxShape() {
        PolygonsSet box = new PolygonsSet(new double[][]{{0, 0}, {2, 0}, {2, 1}, {0, 1}});
        assertEquals(2, box.getSize(), 1e-10);
        assertEquals(6, box.getBoundarySize(), 1e-10);
    }

    @Test
    public void testInfiniteSet() {
        PolygonsSet infiniteSet = new PolygonsSet(true);
        assertTrue(infiniteSet.contains(1, 1)); // should be always true
    }

    @Test
    public void testStairShape() {
        PolygonsSet stair = new PolygonsSet(new double[][]{{0, 0}, {1, 0}, {1, 1}, {2, 1}, {2, 2}, {0, 2}});
        assertEquals(4, stair.getSize(), 1e-10);
        assertArrayEquals(new double[]{0, 0}, stair.getVertices()[0], 1e-10);
    }

    @Test
    public void testEmptyAndFullSets() {
        PolygonsSet emptySet = new PolygonsSet(new double[][]{});
        assertFalse(emptySet.contains(0, 0)); // empty set

        PolygonsSet fullSet = new PolygonsSet(true);
        assertTrue(fullSet.contains(0, 0)); // full set
    }

    @Test
    public void testHolesInPolygons() {
        PolygonsSet polygonWithHole = new PolygonsSet(new double[][]{{0, 0}, {2, 0}, {2, 2}, {0, 2}}, new double[][]{{0.5, 0.5}, {1.5, 1.5}});
        assertFalse(polygonWithHole.contains(1, 1)); // inside hole
        assertTrue(polygonWithHole.contains(1, 0.5)); // outside hole
    }

    @Test
    public void testDisjointPolygons() {
        PolygonsSet polygon1 = new PolygonsSet(new double[][]{{0, 0}, {1, 0}, {1, 1}, {0, 1}});
        PolygonsSet polygon2 = new PolygonsSet(new double[][]{{2, 2}, {3, 2}, {3, 3}, {2, 3}});
        assertFalse(polygon1.contains(2, 2)); // disjoint
    }

    @Test
    public void testIntersectionAndUnion() {
        PolygonsSet polygon1 = new PolygonsSet(new double[][]{{0, 0}, {1, 0}, {1, 1}, {0, 1}});
        PolygonsSet polygon2 = new PolygonsSet(new double[][]{{0.5, 0.5}, {1.5, 0.5}, {1.5, 1.5}, {0.5, 1.5}});
        PolygonsSet intersection = polygon1.intersection(polygon2);
        assertTrue(intersection.contains(0.75, 0.75)); // inside intersection
        PolygonsSet union = polygon1.union(polygon2);
        assertTrue(union.contains(0.75, 0.75)); // inside union
    }

    @Test
    public void testBoundaryProjections() {
        PolygonsSet polygon = new PolygonsSet(new double[][]{{0, 0}, {1, 0}, {1, 1}, {0, 1}});
        double[] projection = polygon.projectOntoBoundary(0.5, 0.5);
        assertArrayEquals(new double[]{0.5, 0}, projection, 1e-10); // projecting onto bottom edge
    }

    @Test
    public void testVariousPolygonConfigurations() {
        PolygonsSet concentric = new PolygonsSet(new double[][]{{0, 0}, {2, 0}, {2, 2}, {0, 2}}, new double[][]{{0.5, 0.5}, {1.5, 1.5}});
        assertTrue(concentric.contains(1, 1)); // inside outer
        assertFalse(concentric.contains(1, 1)); // inside hole
        assertTrue(concentric.onBoundary(0, 0)); // boundary check
    }
}

