class JmsBytesMessageTest {
    private JmsBytesMessage message;

    @BeforeEach
    void setUp() {
        message = new JmsBytesMessage();
    }

    @Test
    void testToString() {
        assertTrue(message.toString().startsWith("JmsBytesMessage"));
    }

    @Test
    void testBodyLengthManagement() throws JMSException {
        assertEquals(0, message.getBodyLength());
        message.writeBytes(new byte[]{1, 2, 3});
        assertEquals(3, message.getBodyLength());
        message.clearBody();
        assertEquals(0, message.getBodyLength());
    }

    @Test
    void testMessageReadabilityAndWriteability() throws JMSException {
        assertTrue(message.isWritable());
        message.writeBytes(new byte[]{1, 2, 3});
        assertFalse(message.isWritable());
        assertThrows(JMSException.class, message::readBytes);
        message.clearBody();
        assertTrue(message.isWritable());
    }

    @Test
    void testReadingAndWritingBytes() throws JMSException {
        byte[] bytesToWrite = {1, 2, 3, 4, 5};
        message.writeBytes(bytesToWrite);

        byte[] bytesRead = new byte[5];
        message.reset();
        message.readBytes(bytesRead);

        assertArrayEquals(bytesToWrite, bytesRead);
    }

    @Test
    void testEndOfStreamHandling() throws JMSException {
        message.clearBody();
        byte[] bytesRead = new byte[5];
        assertEquals(-1, message.readBytes(bytesRead));
    }

    @Test
    void testClearingMessageBody() throws JMSException {
        message.writeBytes(new byte[]{1, 2, 3});
        message.clearBody();
        assertThrows(JMSException.class, () -> message.readByte());
    }

    @Test
    void testResetFunctionality() throws JMSException {
        message.writeByte((byte) 1);
        message.reset();
        assertEquals(1, message.readByte());
    }

    @Test
    void testExceptionHandling() {
        assertThrows(JMSException.class, () -> {
            message.readByte();
        });
        assertThrows(JMSException.class, () -> {
            message.writeBytes(null);
        });
    }

    @Test
    void testEqualityAndHashing() throws JMSException {
        JmsBytesMessage message1 = new JmsBytesMessage();
        JmsBytesMessage message2 = new JmsBytesMessage();

        assertEquals(message1, message2);
        assertEquals(message1.hashCode(), message2.hashCode());

        message1.setJMSMessageID("ID:123");
        assertNotEquals(message1, message2);
    }
}

