public class SimpleProcessLogger implements ComponentLog {
    private LogRepository logRepository;
    private Logger logger;
    private String componentName;

    public SimpleProcessLogger(LogRepository logRepository, Logger logger, String componentName) {
        this.logRepository = logRepository;
        this.logger = logger;
        this.componentName = componentName;
    }

    @Override
    public void debug(String message) {
        if (isDebugEnabled()) {
            String formattedMessage = formatMessage(message);
            logger.debug(formattedMessage);
            logRepository.save(formattedMessage);
        }
    }

    @Override
    public void info(String message) {
        if (isInfoEnabled()) {
            String formattedMessage = formatMessage(message);
            logger.info(formattedMessage);
            logRepository.save(formattedMessage);
        }
    }

    @Override
    public void warn(String message) {
        if (isWarnEnabled()) {
            String formattedMessage = formatMessage(message);
            logger.warn(formattedMessage);
            logRepository.save(formattedMessage);
        }
    }

    @Override
    public void error(String message, Exception e) {
        if (isErrorEnabled()) {
            String formattedMessage = formatMessage(message + " Exception: " + e.getMessage());
            logger.error(formattedMessage);
            logRepository.save(formattedMessage);
        }
    }

    @Override
    public void trace(String message) {
        if (isTraceEnabled()) {
            String formattedMessage = formatMessage(message);
            logger.trace(formattedMessage);
            logRepository.save(formattedMessage);
        }
    }

    private String formatMessage(String message) {
        return prependComponentInfo(message);
    }

    private String prependComponentInfo(String message) {
        return "[" + componentName + "] " + message;
    }

    private boolean isDebugEnabled() {
        return logger.isDebugEnabled();
    }

    private boolean isInfoEnabled() {
        return logger.isInfoEnabled();
    }

    private boolean isWarnEnabled() {
        return logger.isWarnEnabled();
    }

    private boolean isErrorEnabled() {
        return logger.isErrorEnabled();
    }

    private boolean isTraceEnabled() {
        return logger.isTraceEnabled();
    }
}

public class JavascriptUtils {
    private StringBuilder code;
    private Stack<String> indentStack;
    private String currentIndent;

    public JavascriptUtils() {
        this.code = new StringBuilder();
        this.indentStack = new Stack<>();
        this.currentIndent = "";
    }

    public void append(String str) {
        code.append(currentIndent).append(str);
    }

    public void appendExpression(String expression) {
        code.append(currentIndent).append(expression).append(";\n");
    }

    public void startIf(String condition) {
        code.append(currentIndent).append("if (").append(condition).append(") {\n");
        indentStack.push(currentIndent);
        currentIndent += "    ";
    }

    public void endIf() {
        currentIndent = indentStack.pop();
        code.append(currentIndent).append("}\n");
    }

    public void startLoop(String loop) {
        code.append(currentIndent).append(loop).append(" {\n");
        indentStack.push(currentIndent);
        currentIndent += "    ";
    }

    public void endLoop() {
        currentIndent = indentStack.pop();
        code.append(currentIndent).append("}\n");
    }

    public String getDefaultValue(String type) {
        switch (type) {
            case "string":
                return "\"\"";
            case "int":
            case "float":
                return "0";
            case "boolean":
                return "false";
            default:
                return "null";
        }
    }

    public boolean isStringType(String type) {
        return "string".equals(type);
    }

    public void escapeStringQuotes(String str) {
        code.append(str.replace("\"", "\\\""));
    }

    public void serializeXmlElement(String elementName, boolean isOptional, boolean isArray) {
        code.append("let ").append(elementName).append(" = ");
        if (isOptional) {
            code.append("null;\n");
        } else {
            code.append("new ").append(elementName).append("();\n");
        }
        if (isArray) {
            code.append(elementName).append(" = [];\n");
        }
    }

    public void handleMtom(String elementName) {
        code.append("handleMTOM(").append(elementName).append(");\n");
    }

    public void handleAnyType(String elementName) {
        code.append("handleAnyType(").append(elementName).append(");\n");
    }

    public String getGeneratedCode() {
        return code.toString();
    }
}

