public class ResizableDoubleArray implements Serializable {
    private static final long serialVersionUID = 1L;
    private double[] array;
    private int size;
    private double expansionFactor;
    private double contractionThreshold;

    public ResizableDoubleArray() {
        this(10, 2.0, 0.25);
    }

    public ResizableDoubleArray(int initialCapacity, double expansionFactor, double contractionThreshold) {
        this.array = new double[initialCapacity];
        this.size = 0;
        this.expansionFactor = expansionFactor;
        this.contractionThreshold = contractionThreshold;
    }

    public synchronized void add(double value) {
        ensureCapacity(size + 1);
        array[size++] = value;
    }

    public synchronized void addAll(double[] values) {
        ensureCapacity(size + values.length);
        System.arraycopy(values, 0, array, size, values.length);
        size += values.length;
    }

    public synchronized void substitute(double value) {
        if (size > 0) {
            array[size - 1] = value;
        }
    }

    public synchronized void discardFromStart(int count) {
        if (count >= size) {
            clear();
        } else {
            System.arraycopy(array, count, array, 0, size - count);
            size -= count;
        }
        contractIfNecessary();
    }

    public synchronized void discardFromEnd(int count) {
        if (count >= size) {
            clear();
        } else {
            size -= count;
        }
        contractIfNecessary();
    }

    public synchronized double get(int index) {
        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
        }
        return array[index];
    }

    public synchronized void clear() {
        size = 0;
    }

    public synchronized double[] toArray() {
        return Arrays.copyOf(array, size);
    }

    private void ensureCapacity(int capacity) {
        if (capacity > array.length) {
            int newCapacity = (int) (array.length * expansionFactor);
            array = Arrays.copyOf(array, newCapacity);
        }
    }

    private void contractIfNecessary() {
        if (size < array.length * contractionThreshold) {
            int newCapacity = (int) (array.length / expansionFactor);
            array = Arrays.copyOf(array, newCapacity);
        }
    }

    @Deprecated
    public synchronized void addElement(double value) {
        add(value);
    }

    @Deprecated
    public synchronized void removeLastElement() {
        if (size > 0) {
            size--;
            contractIfNecessary();
        }
    }
}

