public class FailoverTransport implements CompositeTransport {
    private List<String> transportUris;
    private int currentUriIndex;
    private boolean isConnected;
    private TransportEventListener eventListener;

    public FailoverTransport(List<String> transportUris) {
        this.transportUris = new ArrayList<>(transportUris);
        this.currentUriIndex = 0;
        this.isConnected = false;
    }

    public void start() {
        connectToCurrentUri();
    }

    public void stop() {
        disconnect();
    }

    public void dispose() {
        stop();
        transportUris.clear();
    }

    private void connectToCurrentUri() {
        if (currentUriIndex >= transportUris.size()) {
            return;
        }
        String uri = transportUris.get(currentUriIndex);
        try {
            // Simulate connection logic
            System.out.println("Connecting to " + uri);
            isConnected = true; // Assume connection is successful
            if (eventListener != null) {
                eventListener.onConnected(uri);
            }
        } catch (Exception e) {
            handleConnectionFailure();
        }
    }

    private void handleConnectionFailure() {
        isConnected = false;
        if (eventListener != null) {
            eventListener.onConnectionFailed(transportUris.get(currentUriIndex));
        }
        currentUriIndex++;
        if (currentUriIndex < transportUris.size()) {
            exponentialBackoffAndRetry();
        } else {
            System.out.println("All URIs failed to connect.");
        }
    }

    private void exponentialBackoffAndRetry() {
        try {
            Thread.sleep((long) Math.pow(2, currentUriIndex) * 1000); // Exponential backoff
            connectToCurrentUri();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void setEventListener(TransportEventListener listener) {
        this.eventListener = listener;
    }

    public void rebalanceConnections() {
        // Logic to rebalance connections among available URIs
    }

    public boolean isConnected() {
        return isConnected;
    }
}

interface CompositeTransport {
    void start();
    void stop();
    void dispose();
}

interface TransportEventListener {
    void onConnected(String uri);
    void onConnectionFailed(String uri);
}

