public final class TraversalHelper {

    private TraversalHelper() {
        // Private constructor to prevent instantiation
    }

    public static boolean hasStepOfType(Traversal traversal, Class<? extends Step> stepClass) {
        for (Step step : traversal.getSteps()) {
            if (stepClass.isInstance(step)) {
                return true;
            }
        }
        return false;
    }

    public static void insertStep(Traversal traversal, Step newStep, int position) {
        List<Step> steps = new ArrayList<>(traversal.getSteps());
        steps.add(position, newStep);
        traversal.setSteps(steps);
    }

    public static void replaceStep(Traversal traversal, Step oldStep, Step newStep) {
        List<Step> steps = new ArrayList<>(traversal.getSteps());
        int index = steps.indexOf(oldStep);
        if (index != -1) {
            steps.set(index, newStep);
            traversal.setSteps(steps);
        }
    }

    public static <T extends Step> List<T> getStepsOfType(Traversal traversal, Class<T> stepClass) {
        List<T> result = new ArrayList<>();
        for (Step step : traversal.getSteps()) {
            if (stepClass.isInstance(step)) {
                result.add(stepClass.cast(step));
            }
        }
        return result;
    }

    public static void manageLabels(Traversal traversal, String label) {
        if (!traversal.getLabels().contains(label)) {
            traversal.getLabels().add(label);
        }
    }

    public static void removeLabel(Traversal traversal, String label) {
        traversal.getLabels().remove(label);
    }

    public static void recursiveTraversal(Traversal traversal, TraversalOperation operation) {
        operation.apply(traversal);
        for (Step step : traversal.getSteps()) {
            if (step instanceof Traversal) {
                recursiveTraversal((Traversal) step, operation);
            }
        }
    }

    public interface TraversalOperation {
        void apply(Traversal traversal);
    }
}

