class VersionRangeTest {

    @Test
    void testRangeCreation() {
        VersionRange range = new VersionRange("1.0.0 - 2.0.0");
        assertNotNull(range);
        assertEquals("1.0.0", range.getLowerBound());
        assertEquals("2.0.0", range.getUpperBound());
    }

    @Test
    void testBoundaryChecks() {
        VersionRange range = new VersionRange("[1.0.0,2.0.0]");
        assertTrue(range.includes("1.0.0"));
        assertTrue(range.includes("2.0.0"));
        assertFalse(range.includes("0.9.9"));
        assertFalse(range.includes("2.0.1"));
    }

    @Test
    void testVersionContainment() {
        VersionRange range = new VersionRange("1.0.0 - 2.0.0");
        assertTrue(range.contains("1.5.0"));
        assertFalse(range.contains("2.1.0"));
        assertTrue(range.contains("1.0.0-SNAPSHOT"));
    }

    @Test
    void testInvalidRangeHandling() {
        assertThrows(IllegalArgumentException.class, () -> {
            new VersionRange("invalid-range");
        });
    }

    @Test
    void testIntersection() {
        VersionRange range1 = new VersionRange("1.0.0 - 2.0.0");
        VersionRange range2 = new VersionRange("1.5.0 - 2.5.0");
        VersionRange intersection = range1.intersect(range2);
        assertNotNull(intersection);
        assertEquals("1.5.0", intersection.getLowerBound());
        assertEquals("2.0.0", intersection.getUpperBound());
    }

    @Test
    void testRestriction() {
        VersionRange range = new VersionRange("1.0.0 - 2.0.0");
        VersionRange restricted = range.restrict("1.5.0 - 1.8.0");
        assertNotNull(restricted);
        assertEquals("1.5.0", restricted.getLowerBound());
        assertEquals("1.8.0", restricted.getUpperBound());
    }

    @Test
    void testSnapshotHandling() {
        VersionRange range = new VersionRange("1.0.0 - 2.0.0");
        assertTrue(range.contains("1.0.0-SNAPSHOT"));
        assertTrue(range.contains("1.5.0-SNAPSHOT"));
        assertFalse(range.contains("2.0.1-SNAPSHOT"));
    }
}

