        Entity entityA = new Entity(ENTITY_TYPE_A);
        entityA.addProperty(PROPERTY_A_NAME, "TestA");

        Entity entityB = new Entity(ENTITY_TYPE_B);
        entityB.addProperty(PROPERTY_B_VALUE, "TestB");

        // Establish navigation
        entityA.addNavigationProperty(NAV_PROPERTY_A_TO_B, entityB);

        // Perform deep insert
        ODataResponse response = odataService.deepInsert(entityA);

        // Validate response
        assertNotNull(response);
        assertEquals("TestA", response.getEntity().getProperty(PROPERTY_A_NAME));
