    @Test
    public void testConsistencyCheckAfterDeepInsert() {
        // Construct entities
        Entity entityA = new Entity(ENTITY_TYPE_A);
        entityA.addProperty(PROPERTY_A_NAME, "ConsistencyTestA");

        Entity entityB = new Entity(ENTITY_TYPE_B);
        entityB.addProperty(PROPERTY_B_VALUE, "ConsistencyTestB");

        // Establish navigation
        entityA.addNavigationProperty(NAV_PROPERTY_A_TO_B, entityB);

        // Perform deep insert
        odataService.deepInsert(entityA);

        // Validate consistency
        ODataResponse response = odataService.getEntity(ENTITY_TYPE_A, entityA.getId());
        assertEquals("ConsistencyTestA", response.getEntity().getProperty(PROPERTY_A_NAME));
