public class CliShell {
    private boolean running;
    private final SQLExecutor sqlExecutor;
    private final Scanner scanner;

    public CliShell(SQLExecutor sqlExecutor) {
        this.sqlExecutor = sqlExecutor;
        this.scanner = new Scanner(System.in);
        this.running = true;
    }

    public void start() {
        while (running) {
            System.out.print("SQL> ");
            String input = scanner.nextLine();
            parseCommand(input);
        }
    }

    private void parseCommand(String input) {
        String[] parts = input.trim().split("\\s+");
        String command = parts[0].toLowerCase();

        switch (command) {
            case "exit":
                running = false;
                break;
            case "clear":
                clearScreen();
                break;
            case "describe":
                describeTable(parts);
                break;
            case "insert":
                insertData(parts);
                break;
            case "list":
                listExecutions();
                break;
            case "remove":
                removeExecution(parts);
                break;
            case "stop":
                stopExecution(parts);
                break;
            case "tables":
                showTables();
                break;
            case "functions":
                showFunctions();
                break;
            case "help":
                displayHelp();
                break;
            default:
                System.out.println("Unknown command: " + command);
        }
    }

    private void clearScreen() {
        System.out.print("\033[H\033[2J");
        System.out.flush();
    }

    private void describeTable(String[] parts) {
        if (parts.length < 2) {
            System.out.println("Usage: describe <table_name>");
            return;
        }
        String tableName = parts[1];
        sqlExecutor.describeTable(tableName);
    }

    private void insertData(String[] parts) {
        if (parts.length < 3) {
            System.out.println("Usage: insert <table_name> <data>");
            return;
        }
        String tableName = parts[1];
        String data = String.join(" ", Arrays.copyOfRange(parts, 2, parts.length));
        sqlExecutor.insertData(tableName, data);
    }

    private void listExecutions() {
        sqlExecutor.listExecutions();
    }

