public final class RxThreadPoolStage<T> extends AbstractRxStage<T> {
    private final ExecutorService executorService;
    private final ExecutorService completionExecutor;
    private final LinkedBlockingQueue<T> queue;
    private final AtomicBoolean isShutdown = new AtomicBoolean(false);

    public RxThreadPoolStage(int numberOfThreads) {
        this.executorService = Executors.newFixedThreadPool(numberOfThreads);
        this.completionExecutor = Executors.newSingleThreadExecutor();
        this.queue = new LinkedBlockingQueue<>();
    }

    @Override
    public void onNext(T item) {
        if (isShutdown.get()) {
            logWarning("Task dropped: " + item);
            return;
        }
        executorService.submit(() -> processItem(item));
    }

    private void processItem(T item) {
        // Processing logic for item
    }

    @Override
    public void onError(Throwable throwable) {
        if (isShutdown.get()) {
            logWarning("Error dropped: " + throwable.getMessage());
            return;
        }
        // Handle error
    }

    @Override
    public void onCompleted() {
        if (isShutdown.get()) {
            logWarning("Completion dropped");
            return;
        }
        completionExecutor.submit(this::completeProcessing);
    }

    private void completeProcessing() {
        // Completion logic
        shutdown();
    }

    public void shutdown() {
        if (isShutdown.compareAndSet(false, true)) {
            executorService.shutdown();
            try {
                if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                    executorService.shutdownNow();
                    logWarning("ExecutorService did not terminate in the specified time.");
                }
            } catch (InterruptedException e) {
                executorService.shutdownNow();
                Thread.currentThread().interrupt();
            }
            completionExecutor.shutdown();
        }
    }

    public int getQueueLength() {
        return queue.size();
    }

    private void logWarning(String message) {
        // Logging logic for warnings
    }
}

public class ConsumerTool implements MessageListener, ExceptionListener {
    private String user;
    private String password;
    private String url;
    private String destination;
    private int numThreads;
    private boolean verboseLogging;
    private int maxMessages;
    private long timeout;
    private Session session;
    private Connection connection;
    private ExecutorService executorService;

    public ConsumerTool(String user, String password, String url, String destination, int numThreads, boolean verboseLogging, int maxMessages, long timeout) {
        this.user = user;
        this.password = password;
        this.url = url;
        this.destination = destination;
        this.numThreads = numThreads;
        this.verboseLogging = verboseLogging;
        this.maxMessages = maxMessages;
        this.timeout = timeout;
    }

    public void start() throws JMSException {
        ActiveMQConnectionFactory factory = new ActiveMQConnectionFactory(user, password, url);
        connection = factory.createConnection();
        connection.setExceptionListener(this);
        connection.start();
        session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        Destination dest = session.createQueue(destination);
        MessageConsumer consumer = session.createConsumer(dest);
        consumer.setMessageListener(this);
        executorService = Executors.newFixedThreadPool(numThreads);
    }

    @Override
    public void onMessage(Message message) {
        executorService.submit(() -> {
            try {
                processMessage(message);
            } catch (JMSException e) {
                handleException(e);
            }
        });
    }

    private void processMessage(Message message) throws JMSException {
        if (verboseLogging) {
            System.out.println("Received message: " + message.getBody(String.class));
        }
        // Process the message here
        // Acknowledge or send reply if needed
    }

    @Override
    public void onException(JMSException exception) {
        handleException(exception);
    }

    private void handleException(JMSException exception) {
        if (verboseLogging) {
            System.err.println("JMS Exception occurred: " + exception.getMessage());
        }
    }

    public void stop() throws JMSException {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(timeout, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
        session.close();
        connection.close();
    }

