public class Parameters {
    private static final Logger logger = Logger.getLogger(Parameters.class.getName());
    private Map<String, String> parameters;
    private int maxParameters;

    public Parameters(int maxParameters) {
        this.parameters = new HashMap<>();
        this.maxParameters = maxParameters;
    }

    public void setParameter(String name, String value) {
        if (parameters.size() >= maxParameters) {
            logger.warning("Maximum number of parameters reached.");
            return;
        }
        parameters.put(name, value);
    }

    public String getParameter(String name) {
        String value = parameters.get(name);
        if (value != null) {
            try {
                return URLDecoder.decode(value, StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                logger.severe("Decoding error for parameter: " + name);
                return null;
            }
        }
        return null;
    }

    public String encodeParameter(String value) {
        try {
            return URLEncoder.encode(value, StandardCharsets.UTF_8.name());
        } catch (Exception e) {
            logger.severe("Encoding error for value: " + value);
            return null;
        }
    }

    public void recycleParameters() {
        parameters.clear();
    }

    public Map<String, String> getAllParameters() {
        return new HashMap<>(parameters);
    }
}

