class PartiallyRepeatableHttpEntityTest {

    private PartiallyRepeatableHttpEntity entity;

    @BeforeEach
    void setUp() {
        String content = "This is a test content.";
        entity = new PartiallyRepeatableHttpEntity(new StringEntity(content, ContentType.TEXT_PLAIN));
    }

    @Test
    void testReadContent() throws IOException {
        byte[] buffer = new byte[10];
        int bytesRead = entity.getContent().read(buffer);
        assertEquals(10, bytesRead);
        assertEquals("This is a ", new String(buffer, 0, bytesRead));
    }

    @Test
    void testRepeatableEntity() throws IOException {
        InputStream contentStream = entity.getContent();
        byte[] buffer = new byte[10];
        contentStream.read(buffer);
        assertEquals("This is a ", new String(buffer));

        // Reset and read again
        entity.reset();
        contentStream = entity.getContent();
        contentStream.read(buffer);
        assertEquals("This is a ", new String(buffer));
    }

    @Test
    void testNonRepeatableEntity() throws IOException {
        HttpEntity nonRepeatableEntity = new InputStreamEntity(new ByteArrayInputStream("Non-repeatable".getBytes()), -1);
        PartiallyRepeatableHttpEntity nonRepeatableHttpEntity = new PartiallyRepeatableHttpEntity(nonRepeatableEntity);

        // Read once
        byte[] buffer = new byte[5];
        nonRepeatableHttpEntity.getContent().read(buffer);
        assertEquals("Non-r", new String(buffer));

        // Attempt to read again should throw IOException
        assertThrows(IOException.class, () -> nonRepeatableHttpEntity.getContent().read(buffer));
    }

    @Test
    void testContentLength() {
        assertEquals(entity.getContentLength(), "This is a test content.".length());
    }

    @Test
    void testContentType() {
        assertEquals(entity.getContentType().getValue(), ContentType.TEXT_PLAIN.getMimeType());
    }

    @Test
    void testContentEncoding() {
        assertNull(entity.getContentEncoding());
    }

    @Test
    void testIsStreaming() {
        assertTrue(entity.isStreaming());
    }

    @Test
    void testIsChunked() {
        assertFalse(entity.isChunked());
    }
}

public class InjectionPointImpl implements InjectionPoint, Serializable {
    private static final long serialVersionUID = 1L;

    private final Bean<?> owningBean;
    private final Member member;
    private final Type type;
    private final List<Annotation> qualifiers;
    private boolean isDelegate;
    private boolean isTransient;

    public InjectionPointImpl(Bean<?> owningBean, Member member, Type type) {
        this.owningBean = owningBean;
        this.member = member;
        this.type = type;
        this.qualifiers = new ArrayList<>();
        this.isDelegate = false; // default value
        this.isTransient = false; // default value
    }

    public void addQualifier(Annotation qualifier) {
        qualifiers.add(qualifier);
    }

    public Bean<?> getOwningBean() {
        return owningBean;
    }

    public Member getMember() {
        return member;
    }

    public Type getType() {
        return type;
    }

    public boolean isDelegate() {
        return isDelegate;
    }

    public void setDelegate(boolean isDelegate) {
        this.isDelegate = isDelegate;
    }

    public boolean isTransient() {
        return isTransient;
    }

    public void setTransient(boolean isTransient) {
        this.isTransient = isTransient;
    }

    public List<Annotation> getQualifiers() {
        return new ArrayList<>(qualifiers);
    }

    private void writeObject(java.io.ObjectOutputStream out) throws java.io.IOException {
        out.defaultWriteObject();
        out.writeObject(qualifiers.toArray(new Annotation[0]));
    }

    private void readObject(java.io.ObjectInputStream in) throws java.io.IOException, ClassNotFoundException {
        in.defaultReadObject();
        Annotation[] qualifiersArray = (Annotation[]) in.readObject();
        for (Annotation qualifier : qualifiersArray) {
            qualifiers.add(qualifier);
        }
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("InjectionPointImpl{");
        sb.append("owningBean=").append(owningBean);
        sb.append(", member=").append(member);
        sb.append(", type=").append(type);
        sb.append(", qualifiers=").append(qualifiers);
        sb.append(", isDelegate=").append(isDelegate);
        sb.append(", isTransient=").append(isTransient);
        sb.append('}');
        return sb.toString();
    }
}

