public class BasicLogicalPlanVisitor implements LogicalPlanVisitor {
    private Stack<Node> nodeStack = new Stack<>();

    public void visit(Node node) {
        preHook(node);
        nodeStack.push(node);

        switch (node.getType()) {
            case ROOT:
                visitRoot((RootNode) node);
                break;
            case JOIN:
                visitJoin((JoinNode) node);
                break;
            case PROJECTION:
                visitProjection((ProjectionNode) node);
                break;
            case FILTER:
                visitFilter((FilterNode) node);
                break;
            // Add more cases for other node types as needed
            default:
                throw new UnsupportedOperationException("Unsupported node type: " + node.getType());
        }

        nodeStack.pop();
        postHook(node);
    }

