public class DefaultOperationManager implements OperationManager {
    private static final Logger logger = LoggerFactory.getLogger(DefaultOperationManager.class);
    private final DirectoryService directoryService;
    private final ReadWriteLock lock = new ReentrantReadWriteLock();

    public DefaultOperationManager(DirectoryService directoryService) {
        this.directoryService = directoryService;
    }

    private void ensureServiceStarted() {
        if (!directoryService.isStarted()) {
            throw new IllegalStateException("Directory service is not started.");
        }
    }

    public void addEntry(String dn, Entry entry) {
        lock.writeLock().lock();
        try {
            ensureServiceStarted();
            long startTime = System.currentTimeMillis();
            directoryService.add(dn, entry);
            logger.info("Added entry in {} ms", System.currentTimeMillis() - startTime);
        } catch (ReferralException e) {
            logger.error("Referral exception occurred while adding entry", e);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void bind(String dn, String password) {
        lock.writeLock().lock();
        try {
            ensureServiceStarted();
            long startTime = System.currentTimeMillis();
            directoryService.bind(dn, password);
            logger.info("Bind operation completed in {} ms", System.currentTimeMillis() - startTime);
        } catch (ReferralException e) {
            logger.error("Referral exception occurred while binding", e);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public boolean compareEntry(String dn, String attribute, String value) {
        lock.readLock().lock();
        try {
            ensureServiceStarted();
            long startTime = System.currentTimeMillis();
            boolean result = directoryService.compare(dn, attribute, value);
            logger.info("Compare operation completed in {} ms", System.currentTimeMillis() - startTime);
            return result;
        } catch (ReferralException e) {
            logger.error("Referral exception occurred while comparing entry", e);
            return false;
        } finally {
            lock.readLock().unlock();
        }
    }

    public void deleteEntry(String dn) {
        lock.writeLock().lock();
        try {
            ensureServiceStarted();
            long startTime = System.currentTimeMillis();
            directoryService.delete(dn);
            logger.info("Deleted entry in {} ms", System.currentTimeMillis() - startTime);
        } catch (ReferralException e) {
            logger.error("Referral exception occurred while deleting entry", e);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void modifyEntry(String dn, Modification modification) {
        lock.writeLock().lock();
        try {
            ensureServiceStarted();
            long startTime = System.currentTimeMillis();
            directoryService.modify(dn, modification);
            logger.info("Modified entry in {} ms", System.currentTimeMillis() - startTime);
        } catch (ReferralException e) {
            logger.error("Referral exception occurred while modifying entry", e);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void moveEntry(String oldDn, String newDn) {
        lock.writeLock().lock();
        try {
            ensureServiceStarted();
            long startTime = System.currentTimeMillis();
            directoryService.move(oldDn, newDn);
            logger.info("Moved entry in {} ms", System.currentTimeMillis() - startTime);
        } catch (ReferralException e) {
            logger.error("Referral exception occurred while moving entry", e);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void renameEntry(String oldDn, String newRdn) {
        lock.writeLock().lock();
        try {
            ensureServiceStarted();
            long startTime = System.currentTimeMillis();
            directoryService.rename(oldDn, newRdn);
            logger.info("Renamed entry in {} ms", System.currentTimeMillis() - startTime);
        } catch (ReferralException e) {
            logger.error("Referral exception occurred while renaming entry", e);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void unbind(String dn) {
        lock.writeLock().lock();
        try {
            ensureServiceStarted();
            long startTime = System.currentTimeMillis();
            directoryService.unbind(dn);
            logger.info("Unbound entry in {} ms", System.currentTimeMillis() - startTime);
        } catch (ReferralException e) {
            logger.error("Referral exception occurred while unbinding entry", e);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public SearchResult search(String baseDn, String filter) {
        lock.readLock().lock();
        try {
            ensureServiceStarted();
            long startTime = System.currentTimeMillis();
            SearchResult result = directoryService.search(baseDn, filter);
            logger.info("Search operation completed in {} ms", System.currentTimeMillis() - startTime);
            return result;
        } catch (ReferralException e) {
            logger.error("Referral exception occurred while searching", e);
            return null;
        } finally {
            lock.readLock().unlock();
        }
    }
}

