public class GetFile extends AbstractProcessor {
    private static final Relationship SUCCESS = new Relationship.Builder()
            .name("success")
            .description("Successfully retrieved files")
            .build();

    private static final Set<Relationship> RELATIONSHIPS = Collections.singleton(SUCCESS);

    private String directory;
    private boolean recursive;
    private boolean deleteSourceFiles;
    private long minSize;
    private long maxSize;
    private long ageThreshold;

    @Override
    protected void init(ProcessorInitializationContext context) {
        // Initialization logic
    }

    @OnScheduled
    public void onScheduled(ProcessorContext context) {
        // Polling logic
    }

    @OnStopped
    public void onStopped() {
        // Cleanup logic
    }

    @Override
    public Set<Relationship> getRelationships() {
        return RELATIONSHIPS;
    }

    @Override
    public void onTrigger(ProcessContext context, ProcessSession session) throws ProcessException {
        File dir = new File(directory);
        if (!dir.exists() || !dir.isDirectory()) {
            getLogger().error("Directory does not exist or is not a directory: " + directory);
            return;
        }

        try {
            Files.walkFileTree(dir.toPath(), new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                    if (shouldProcessFile(file, attrs)) {
                        FlowFile flowFile = session.create();
                        flowFile = session.putAttribute(flowFile, CoreAttributes.FILENAME.key(), file.getFileName().toString());
                        // Add more attributes here
                        session.transfer(flowFile, SUCCESS);
                        if (deleteSourceFiles) {
                            Files.delete(file);
                        }
                    }
                    return FileVisitResult.CONTINUE;
                }
            });
        } catch (IOException e) {
            getLogger().error("Error processing files in directory: " + e.getMessage(), e);
        }
    }

    private boolean shouldProcessFile(Path file, BasicFileAttributes attrs) {
        long fileSize = attrs.size();
        long fileAge = System.currentTimeMillis() - attrs.lastModifiedTime().toMillis();
        return (fileSize >= minSize && fileSize <= maxSize) && (fileAge <= ageThreshold);
    }
}

