        if (contents != null && canPaste(contents)) {
            // Handle different data types
            if (contents.isDataFlavorSupported(DataFlavor.stringFlavor)) {
                pasteString(contents);
            } else if (contents.isDataFlavorSupported(DataFlavor.imageFlavor)) {
