public class ThreadOutputMuxer {
    private static final ThreadLocal<String> currentProjectSegment = ThreadLocal.withInitial(() -> null);
    private final Map<String, PrintStream> outputStreams = new HashMap<>();
    private final Map<String, PrintStream> printStreams = new HashMap<>();
    private boolean allBuildsCompleted = false;

    public void associateThreadWithSegment(String segment) {
        currentProjectSegment.set(segment);
    }

    public void markBuildComplete() {
        allBuildsCompleted = true;
    }

    public void addOutputStream(String segment, PrintStream outputStream) {
        outputStreams.put(segment, outputStream);
    }

    public void addPrintStream(String segment, PrintStream printStream) {
        printStreams.put(segment, printStream);
    }

    public void writeOutput(String message) {
        String segment = currentProjectSegment.get();
        if (segment != null && outputStreams.containsKey(segment)) {
            outputStreams.get(segment).println(message);
        }
    }

    public void startConsolePrinter() {
        new Thread(new ConsolePrinter()).start();
    }

    private class ConsolePrinter implements Runnable {
        @Override
        public void run() {
            while (!allBuildsCompleted) {
                for (String segment : outputStreams.keySet()) {
                    // Simulate writing output from each segment
                    PrintStream printStream = printStreams.get(segment);
                    if (printStream != null) {
                        printStream.flush();
                    }
                }
                try {
                    Thread.sleep(100); // Sleep to avoid busy waiting
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }
}

