public class LogicalNodeDeserializer {

    private final Map<Integer, LogicalNode> nodeMap = new HashMap<>();

    public LogicalNode deserialize(LogicalNodeProto proto) throws InvalidProtocolBufferException {
        switch (proto.getNodeType()) {
            case ROOT:
                return deserializeRoot(proto);
            case SESSION_SETTINGS:
                return deserializeSessionSettings(proto);
            case EXPRESSION:
                return deserializeExpression(proto);
            case PROJECTION:
                return deserializeProjection(proto);
            case LIMIT:
                return deserializeLimit(proto);
            case SORT:
                return deserializeSort(proto);
            case AGGREGATION:
                return deserializeAggregation(proto);
            case JOIN:
                return deserializeJoin(proto);
            case DATABASE_OPERATION:
                return deserializeDatabaseOperation(proto);
            default:
                throw new IllegalArgumentException("Unknown node type: " + proto.getNodeType());
        }
    }

    private LogicalNode deserializeRoot(LogicalNodeProto proto) {
        RootNode rootNode = new RootNode();
        // Set properties and child nodes
        for (int childId : proto.getChildIdsList()) {
            rootNode.addChild(nodeMap.get(childId));
        }
        nodeMap.put(proto.getId(), rootNode);
        return rootNode;
    }

    private LogicalNode deserializeSessionSettings(LogicalNodeProto proto) {
        SessionSettingsNode settingsNode = new SessionSettingsNode();
        // Set properties
        nodeMap.put(proto.getId(), settingsNode);
        return settingsNode;
    }

    private LogicalNode deserializeExpression(LogicalNodeProto proto) {
        ExpressionNode expressionNode = new ExpressionNode();
        // Set properties
        nodeMap.put(proto.getId(), expressionNode);
        return expressionNode;
    }

    private LogicalNode deserializeProjection(LogicalNodeProto proto) {
        ProjectionNode projectionNode = new ProjectionNode();
        // Set properties and child nodes
        for (int childId : proto.getChildIdsList()) {
            projectionNode.addChild(nodeMap.get(childId));
        }
        nodeMap.put(proto.getId(), projectionNode);
        return projectionNode;
    }

    private LogicalNode deserializeLimit(LogicalNodeProto proto) {
        LimitNode limitNode = new LimitNode();
        // Set properties
        nodeMap.put(proto.getId(), limitNode);
        return limitNode;
    }

    private LogicalNode deserializeSort(LogicalNodeProto proto) {
        SortNode sortNode = new SortNode();
        // Set properties
        nodeMap.put(proto.getId(), sortNode);
        return sortNode;
    }

    private LogicalNode deserializeAggregation(LogicalNodeProto proto) {
        AggregationNode aggregationNode = new AggregationNode();
        // Set properties
        nodeMap.put(proto.getId(), aggregationNode);
        return aggregationNode;
    }

    private LogicalNode deserializeJoin(LogicalNodeProto proto) {
        JoinNode joinNode = new JoinNode();
        // Set properties and child nodes
        for (int childId : proto.getChildIdsList()) {
            joinNode.addChild(nodeMap.get(childId));
        }
        nodeMap.put(proto.getId(), joinNode);
        return joinNode;
    }

    private LogicalNode deserializeDatabaseOperation(LogicalNodeProto proto) {
        DatabaseOperationNode dbOperationNode = new DatabaseOperationNode();
        // Set properties
        nodeMap.put(proto.getId(), dbOperationNode);
        return dbOperationNode;
    }
}

