public final class UriParser {

    private UriParser() {
        throw new UnsupportedOperationException("Utility class cannot be instantiated");
    }

    public static String appendEncodedValue(String baseUri, String value) throws UnsupportedEncodingException {
        return baseUri + (baseUri.endsWith("/") ? "" : "/") + encode(value);
    }

    public static String canonicalizePath(String path) {
        return path.replaceAll("/+", "/").replaceAll("/\\./", "/").replaceAll("/[^/]+/\\.\\./", "/");
    }

    public static boolean isUriEncoded(String uri) {
        return uri.matches(".*%[0-9A-Fa-f]{2}.*");
    }

    public static String decode(String encoded) throws UnsupportedEncodingException {
        return URLDecoder.decode(encoded, StandardCharsets.UTF_8.name());
    }

    public static String encode(String decoded) throws UnsupportedEncodingException {
        return URLEncoder.encode(decoded, StandardCharsets.UTF_8.name());
    }

    public static String extractScheme(String uri) throws URISyntaxException {
        URI parsedUri = new URI(uri);
        return parsedUri.getScheme();
    }

    public static String extractQuery(String uri) throws URISyntaxException {
        URI parsedUri = new URI(uri);
        return parsedUri.getQuery();
    }

    public static String fixSeparatorCharacters(String uri) {
        return uri.replace("\\", "/");
    }

    public static String normalizePath(String path) {
        return canonicalizePath(path);
    }

    public static String handleFileTypeSpecialCases(String uri) {
        if (uri.endsWith(".txt")) {
            return uri.replace(".txt", ".text");
        }
        return uri;
    }

    public static String validateAndDecode(String encoded) throws IllegalArgumentException {
        if (!isUriEncoded(encoded)) {
            throw new IllegalArgumentException("Invalid URI encoding");
        }
        return decode(encoded);
    }

    public static String validateAndEncode(String decoded) throws IllegalArgumentException {
        if (decoded.contains("%")) {
            throw new IllegalArgumentException("String contains invalid escape sequences");
        }
        return encode(decoded);
    }
}

