public class ListenSyslog {
    private int maxQueueSize;
    private int receiveBufferSize;
    private int maxSocketBufferSize;
    private String protocol;
    private boolean useSSL;
    private List<String> messageQueue;

    public ListenSyslog(int maxQueueSize, int receiveBufferSize, int maxSocketBufferSize, String protocol, boolean useSSL) {
        this.maxQueueSize = maxQueueSize;
        this.receiveBufferSize = receiveBufferSize;
        this.maxSocketBufferSize = maxSocketBufferSize;
        this.protocol = protocol;
        this.useSSL = useSSL;
        this.messageQueue = new ArrayList<>();
    }

    public void startListening() throws IOException {
        if ("UDP".equalsIgnoreCase(protocol)) {
            listenUDP();
        } else if ("TCP".equalsIgnoreCase(protocol)) {
            listenTCP();
        }
    }

    private void listenUDP() throws IOException {
        DatagramSocket socket = new DatagramSocket();
        socket.setReceiveBufferSize(receiveBufferSize);
        byte[] buffer = new byte[receiveBufferSize];

        while (true) {
            // Code smell: Infinite loop without exit condition
            DatagramPacket packet = new DatagramPacket(buffer, buffer.length);
            socket.receive(packet);
            processMessage(new String(packet.getData(), 0, packet.getLength()));
        }
    }

    private void listenTCP() throws IOException {
        ServerSocket serverSocket = new ServerSocket(514);
        while (true) {
            // Code smell: Infinite loop without exit condition
            Socket clientSocket = serverSocket.accept();
            handleClient(clientSocket);
        }
    }

    private void handleClient(Socket clientSocket) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(receiveBufferSize);
        int bytesRead = clientSocket.getInputStream().read(buffer.array());
        if (bytesRead > 0) {
            processMessage(new String(buffer.array(), 0, bytesRead));
        }
        clientSocket.close();
    }

    private void processMessage(String message) {
        if (isValidSyslogMessage(message)) {
            if (messageQueue.size() < maxQueueSize) {
                messageQueue.add(message);
            } else {
                // Code smell: Ignoring overflow
            }
        } else {
            // Handle invalid message
        }
    }

    private boolean isValidSyslogMessage(String message) {
        // Basic validation logic
        return message != null && !message.trim().isEmpty();
    }
}

public abstract class WriteOperation {

    protected String outputDirectory;
    protected String tempDirectory;

    public WriteOperation(String outputDirectory, String tempDirectory) {
        this.outputDirectory = outputDirectory;
        this.tempDirectory = tempDirectory;
    }

    public abstract void createWriter() throws IOException;

    public void finalizeOutput(String fileName) throws IOException {
        Path tempFilePath = Path.of(tempDirectory, fileName);
        Path finalFilePath = Path.of(outputDirectory, fileName);
        Files.move(tempFilePath, finalFilePath, StandardCopyOption.REPLACE_EXISTING);
    }

    public String generateUniqueFileName(String baseName) {
        return baseName + "_" + UUID.randomUUID().toString() + ".txt";
    }

    public void createEmptyShard(String shardName) throws IOException {
        Path emptyShardPath = Path.of(tempDirectory, shardName);
        Files.createFile(emptyShardPath);
    }

    public void cleanupTemporaryFiles() throws IOException {
        Files.walk(Path.of(tempDirectory))
                .filter(Files::isRegularFile)
                .forEach(file -> {
                    try {
                        Files.delete(file);
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                });
    }
}

