public class CgenConfiguration implements Serializable, XMLSerializable {
    private List<String> artifacts;
    private List<String> entityArtifacts;
    private List<String> embeddableArtifacts;
    private String template;
    private String outputPattern;
    private String filePath;
    private List<String> excludedEntities;
    private List<String> excludedEmbeddables;

    public CgenConfiguration() {
        this.artifacts = new ArrayList<>();
        this.entityArtifacts = new ArrayList<>();
        this.embeddableArtifacts = new ArrayList<>();
        this.excludedEntities = new ArrayList<>();
        this.excludedEmbeddables = new ArrayList<>();
    }

    public List<String> getArtifacts() {
        return artifacts;
    }

    public void setArtifacts(List<String> artifacts) {
        this.artifacts = artifacts;
    }

    public List<String> getEntityArtifacts() {
        return entityArtifacts;
    }

    public void setEntityArtifacts(List<String> entityArtifacts) {
        this.entityArtifacts = entityArtifacts;
    }

    public List<String> getEmbeddableArtifacts() {
        return embeddableArtifacts;
    }

    public void setEmbeddableArtifacts(List<String> embeddableArtifacts) {
        this.embeddableArtifacts = embeddableArtifacts;
    }

    public String getTemplate() {
        return template;
    }

    public void setTemplate(String template) {
        this.template = template;
    }

    public String getOutputPattern() {
        return outputPattern;
    }

    public void setOutputPattern(String outputPattern) {
        this.outputPattern = outputPattern;
    }

    public String getFilePath() {
        return filePath;
    }

    public void setFilePath(String filePath) {
        this.filePath = filePath;
    }

    public List<String> getExcludedEntities() {
        return excludedEntities;
    }

    public void setExcludedEntities(List<String> excludedEntities) {
        this.excludedEntities = excludedEntities;
    }

    public List<String> getExcludedEmbeddables() {
        return excludedEmbeddables;
    }

    public void setExcludedEmbeddables(List<String> excludedEmbeddables) {
        this.excludedEmbeddables = excludedEmbeddables;
    }

    public void loadEntities(List<String> entities) {
        for (String entity : entities) {
            if (!excludedEntities.contains(entity)) {
                entityArtifacts.add(entity);
            }
        }
    }

    public void loadEmbeddables(List<String> embeddables) {
        for (String embeddable : embeddables) {
            if (!excludedEmbeddables.contains(embeddable)) {
                embeddableArtifacts.add(embeddable);
            }
        }
    }

    public String buildOutputPath() {
        return filePath + "/" + outputPattern;
    }

    public String encodeToXML() {
        StringBuilder xmlBuilder = new StringBuilder();
        xmlBuilder.append("<CgenConfiguration>");
        xmlBuilder.append("<template>").append(template).append("</template>");
        xmlBuilder.append("<outputPattern>").append(outputPattern).append("</outputPattern>");
        xmlBuilder.append("<filePath>").append(filePath).append("</filePath>");
        xmlBuilder.append("<artifacts>").append(artifacts.toString()).append("</artifacts>");
        xmlBuilder.append("<entityArtifacts>").append(entityArtifacts.toString()).append("</entityArtifacts>");
        xmlBuilder.append("<embeddableArtifacts>").append(embeddableArtifacts.toString()).append("</embeddableArtifacts>");
        xmlBuilder.append("<excludedEntities>").append(excludedEntities.toString()).append("</excludedEntities>");
        xmlBuilder.append("<excludedEmbeddables>").append(excludedEmbeddables.toString()).append("</excludedEmbeddables>");
        xmlBuilder.append("</CgenConfiguration>");
        return xmlBuilder.toString();
    }
}

