public class BSPTree<S extends Space> {
    private BSPNode<S> root;

    public BSPTree() {
        this.root = null;
    }

    public void insertCut(Hyperplane<S> cut) {
        if (root == null) {
            root = new BSPNode<>(cut);
        } else {
            root.insertCut(cut);
        }
    }

    public BSPTree<S> copy() {
        BSPTree<S> newTree = new BSPTree<>();
        if (root != null) {
            newTree.root = root.copy();
        }
        return newTree;
    }

    public BSPNode<S> getRoot() {
        return root;
    }

    public BSPNode<S> getParent(BSPNode<S> node) {
        return node.getParent();
    }

    public List<BSPNode<S>> getChildren(BSPNode<S> node) {
        return node.getChildren();
    }

    public void traverse(Visitor<S> visitor) {
        if (root != null) {
            root.traverse(visitor);
        }
    }

    public BSPNode<S> findCellContainingPoint(Point<S> point) {
        if (root != null) {
            return root.findCellContainingPoint(point);
        }
        return null;
    }

    public void merge(BSPTree<S> other) {
        if (other.root != null) {
            if (root == null) {
                root = other.root;
            } else {
                root.merge(other.root);
            }
        }
    }

    public void condense() {
        if (root != null) {
            root.condense();
        }
    }

    private static class BSPNode<S extends Space> {
        private Hyperplane<S> cut;
        private BSPNode<S> front;
        private BSPNode<S> back;
