            } else {
                // Logic to determine which side to insert the cut
                if (cut.isFrontOf(this.cut)) {
                    if (front == null) {
                        front = new BSPNode<>(cut);
                        front.parent = this;
                    } else {
                        front.insertCut(cut);
                    }
                } else {
                    if (back == null) {
                        back = new BSPNode<>(cut);
                        back.parent = this;
                    } else {
                        back.insertCut(cut);
                    }
                }
            }
        }

        public BSPNode<S> copy() {
            BSPNode<S> newNode = new BSPNode<>(this.cut);
            if (front != null) {
                newNode.front = front.copy();
                newNode.front.parent = newNode;
