public class SizeLimitWrapper extends AbstractLimitWrapper {
    private int uncheckedLimit;
    private int prLimit;
    private int prTotalLimit;
    private boolean noEstimate;

    public SizeLimitWrapper(int uncheckedLimit, int prLimit, int prTotalLimit, boolean noEstimate) {
        this.uncheckedLimit = uncheckedLimit;
        this.prLimit = prLimit;
        this.prTotalLimit = prTotalLimit;
        this.noEstimate = noEstimate;
    }

    public SizeLimitWrapper(String limitString) {
        parseLimitString(limitString);
    }

    private void parseLimitString(String limitString) {
        String[] parts = limitString.split(",");
        if (parts.length >= 3) {
            this.uncheckedLimit = Integer.parseInt(parts[0].trim());
            this.prLimit = Integer.parseInt(parts[1].trim());
            this.prTotalLimit = Integer.parseInt(parts[2].trim());
            this.noEstimate = parts.length > 3 && Boolean.parseBoolean(parts[3].trim());
        }
    }

    public void clearLimits() {
        this.uncheckedLimit = 0;
        this.prLimit = 0;
        this.prTotalLimit = 0;
        this.noEstimate = false;
    }

    public int getUncheckedLimit() {
        return uncheckedLimit;
    }

    public void setUncheckedLimit(int uncheckedLimit) {
        this.uncheckedLimit = uncheckedLimit;
    }

    public int getPrLimit() {
        return prLimit;
    }

    public void setPrLimit(int prLimit) {
        this.prLimit = prLimit;
    }

    public int getPrTotalLimit() {
        return prTotalLimit;
    }

    public void setPrTotalLimit(int prTotalLimit) {
        this.prTotalLimit = prTotalLimit;
    }

    public boolean isNoEstimate() {
        return noEstimate;
    }

    public void setNoEstimate(boolean noEstimate) {
        this.noEstimate = noEstimate;
    }

    @Override
    public String toString() {
        return "SizeLimitWrapper{" +
                "uncheckedLimit=" + uncheckedLimit +
                ", prLimit=" + prLimit +
                ", prTotalLimit=" + prTotalLimit +
                ", noEstimate=" + noEstimate +
                '}';
    }
}

