public class Complex implements FieldElement<Complex>, Serializable {
    public static final Complex I = new Complex(0, 1);
    public static final Complex NaN = new Complex(Double.NaN, Double.NaN);
    public static final Complex INF = new Complex(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY);
    public static final Complex ONE = new Complex(1, 0);
    public static final Complex ZERO = new Complex(0, 0);

    private final double real;
    private final double imaginary;

    public Complex(double real, double imaginary) {
        this.real = real;
        this.imaginary = imaginary;
    }

    public Complex add(Complex other) {
        return new Complex(this.real + other.real, this.imaginary + other.imaginary);
    }

    public Complex subtract(Complex other) {
        return new Complex(this.real - other.real, this.imaginary - other.imaginary);
    }

    public Complex multiply(Complex other) {
        return new Complex(this.real * other.real - this.imaginary * other.imaginary,
                           this.real * other.imaginary + this.imaginary * other.real);
    }

    public Complex divide(Complex other) {
        if (other.isZero()) {
            return NaN; // Handle division by zero
        }
        double denominator = other.real * other.real + other.imaginary * other.imaginary;
        return new Complex((this.real * other.real + this.imaginary * other.imaginary) / denominator,
                           (this.imaginary * other.real - this.real * other.imaginary) / denominator);
    }

    public double abs() {
        return Math.sqrt(real * real + imaginary * imaginary);
    }

    public Complex conjugate() {
        return new Complex(real, -imaginary);
    }

    public Complex exp() {
        double expReal = Math.exp(real);
        return new Complex(expReal * Math.cos(imaginary), expReal * Math.sin(imaginary));
    }

    public Complex log() {
        return new Complex(Math.log(abs()), Math.atan2(imaginary, real));
    }

    public Complex sin() {
        return new Complex(Math.sin(real) * Math.cosh(imaginary), Math.cos(real) * Math.sinh(imaginary));
    }

    public Complex cos() {
        return new Complex(Math.cos(real) * Math.cosh(imaginary), -Math.sin(real) * Math.sinh(imaginary));
    }

    public Complex sinh() {
        return new Complex(Math.sinh(real) * Math.cos(imaginary), Math.cosh(real) * Math.sin(imaginary));
    }

    public Complex cosh() {
        return new Complex(Math.cosh(real) * Math.cos(imaginary), Math.sinh(real) * Math.sin(imaginary));
    }

    public boolean isNaN() {
        return Double.isNaN(real) || Double.isNaN(imaginary);
    }

    public boolean isInfinite() {
        return Double.isInfinite(real) || Double.isInfinite(imaginary);
    }

    public boolean isZero() {
        return real == 0 && imaginary == 0;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Complex)) return false;
        Complex other = (Complex) obj;
        return Double.compare(real, other.real) == 0 && Double.compare(imaginary, other.imaginary) == 0;
    }

    @Override
    public int hashCode() {
        return Double.hashCode(real) ^ Double.hashCode(imaginary);
    }

    public Complex nthRoot(int n) {
        double r = Math.pow(abs(), 1.0 / n);
        double theta = Math.atan2(imaginary, real);
        Complex[] roots = new Complex[n];
        for (int k = 0; k < n; k++) {
            double angle = (theta + 2 * Math.PI * k) / n;
            roots[k] = new Complex(r * Math.cos(angle), r * Math.sin(angle));
        }
        return roots[0]; // Return the first root for simplicity
    }

    public static Complex fromReal(double real) {
        return new Complex(real, 0);
    }

    public static Complex fromImaginary(double imaginary) {
        return new Complex(0, imaginary);
    }

    @Override
    public String toString() {
        if (isNaN()) return "NaN";
        if (isInfinite()) return "Infinity";
        return String.format("%s%+si", real, imaginary);
    }
}

public class TestUnpackContent {

    private UnpackContent unpackContent;

    @BeforeEach
    public void setUp() {
        unpackContent = new UnpackContent();
    }

    @Test
    public void testUnpackZipFile() throws IOException {
        File zipFile = createZipFile("test.zip", List.of("file1.txt", "file2.txt"));
        List<File> unpackedFiles = unpackContent.unpack(zipFile);

        assertEquals(2, unpackedFiles.size());
        assertTrue(unpackedFiles.stream().anyMatch(file -> file.getName().equals("file1.txt")));
        assertTrue(unpackedFiles.stream().anyMatch(file -> file.getName().equals("file2.txt")));
    }

    @Test
    public void testUnpackTarFile() throws IOException {
        File tarFile = createTarFile("test.tar", List.of("file1.txt", "file2.txt"));
        List<File> unpackedFiles = unpackContent.unpack(tarFile);

        assertEquals(2, unpackedFiles.size());
        assertTrue(unpackedFiles.stream().anyMatch(file -> file.getName().equals("file1.txt")));
        assertTrue(unpackedFiles.stream().anyMatch(file -> file.getName().equals("file2.txt")));
    }

    @Test
    public void testInvalidData() {
        assertThrows(IOException.class, () -> {
            unpackContent.unpack(new File("invalid.file"));
        });
    }

    @Test
    public void testFilterSpecificFiles() throws IOException {
        File zipFile = createZipFile("test.zip", List.of("file1.txt", "file2.txt", "file3.txt"));
        List<File> unpackedFiles = unpackContent.unpack(zipFile, "file1.txt");

        assertEquals(1, unpackedFiles.size());
        assertEquals("file1.txt", unpackedFiles.get(0).getName());
    }

    @Test
    public void testThreadSafety() throws InterruptedException {
        Runnable task = () -> {
            try {
                File zipFile = createZipFile("test.zip", List.of("file1.txt", "file2.txt"));
                unpackContent.unpack(zipFile);
            } catch (IOException e) {
                fail("Exception during unpacking: " + e.getMessage());
            }
        };

        Thread thread1 = new Thread(task);
        Thread thread2 = new Thread(task);
        thread1.start();
        thread2.start();
        thread1.join();
        thread2.join();
    }

    private File createZipFile(String fileName, List<String> fileContents) throws IOException {
        File zipFile = new File(fileName);
        try (FileOutputStream fos = new FileOutputStream(zipFile);
             ZipOutputStream zos = new ZipOutputStream(fos)) {
            for (String content : fileContents) {
                ZipEntry entry = new ZipEntry(content);
                zos.putNextEntry(entry);
                zos.write(content.getBytes());
                zos.closeEntry();
            }
        }
        return zipFile;
    }

    private File createTarFile(String fileName, List<String> fileContents) throws IOException {
        File tarFile = new File(fileName);
        try (FileOutputStream fos = new FileOutputStream(tarFile);
             TarOutputStream tos = new TarOutputStream(fos)) {
            for (String content : fileContents) {
                TarEntry entry = new TarEntry(content);
                tos.putNextEntry(entry);
                tos.write(content.getBytes());
                tos.closeEntry();
            }
        }
        return tarFile;
    }
}

