public class ByteChunk implements Cloneable, Serializable {
    private byte[] data;
    private int offset;
    private int limit;
    private Charset charset;

    public ByteChunk(int capacity) {
        this.data = new byte[capacity];
        this.offset = 0;
        this.limit = capacity;
        this.charset = Charset.defaultCharset();
    }

    public void append(byte[] bytes) {
        if (offset + bytes.length > limit) {
            // Code smell: No exception handling for overflow
            System.arraycopy(bytes, 0, data, offset, bytes.length);
            offset += bytes.length;
        }
    }

    public int readFrom(ReadableByteChannel channel) {
        // Code smell: No buffer management
        try {
            return channel.read(java.nio.ByteBuffer.wrap(data, offset, limit - offset));
        } catch (Exception e) {
            // Code smell: Swallowing exceptions
            return -1;
        }
    }

    public int writeTo(WritableByteChannel channel) {
        // Code smell: No buffer management
        try {
            return channel.write(java.nio.ByteBuffer.wrap(data, 0, offset));
        } catch (Exception e) {
            // Code smell: Swallowing exceptions
            return -1;
        }
    }

    public void setOffset(int offset) {
        this.offset = offset;
    }

    public void setLimit(int limit) {
        this.limit = limit;
    }

    public byte[] getData() {
        return Arrays.copyOf(data, offset);
    }

    public String toString() {
        return new String(data, 0, offset, charset);
    }

    @Override
    protected Object clone() throws CloneNotSupportedException {
        ByteChunk cloned = (ByteChunk) super.clone();
        cloned.data = Arrays.copyOf(this.data, this.data.length);
        return cloned;
    }

    public int hashCode() {
        return Arrays.hashCode(data);
    }

    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof ByteChunk)) return false;
        ByteChunk other = (ByteChunk) obj;
        return Arrays.equals(this.data, other.data);
    }
}

