public class NotificationManagerImpl implements NotificationManager {

    private static final Logger logger = LoggerFactory.getLogger(NotificationManagerImpl.class);

    @Autowired
    private UserDao userDao;

    @Autowired
    private GroupDao groupDao;

    @Autowired
    private NotificationDao notificationDao;

    @Autowired
    private ConfigDao configDao;

    private int maxRetries;

    public NotificationManagerImpl() {
        this.maxRetries = fetchMaxRetriesFromConfig();
    }

    private int fetchMaxRetriesFromConfig() {
        // Code smell: Directly accessing configuration here
        return configDao.getMaxNotificationRetries();
    }

    @Override
    public void createNotificationTask(Event event) {
        if (event == null) {
            logger.warn("Event is null, cannot create notification task.");
            return;
        }

        List<String> recipientEmails = fetchRecipientEmails(event);
        if (recipientEmails.isEmpty()) {
            logger.warn("No recipients found for event: {}", event);
            return;
        }

        NotificationTask task = new NotificationTask(event, recipientEmails);
        storeExecutionDetails(task);
        logger.info("Notification task created for event: {}", event);
    }

    private List<String> fetchRecipientEmails(Event event) {
        // Code smell: Complex logic for fetching emails
        if (event.isStaticRecipient()) {
            return userDao.getStaticRecipientEmails(event.getStaticRecipientId());
        } else {
            return groupDao.getDynamicRecipientEmails(event.getGroupId());
        }
    }

    private void storeExecutionDetails(NotificationTask task) {
        // Code smell: Method does too much
        notificationDao.saveTaskExecution(task);
        logger.info("Execution details stored for task: {}", task);
    }

    @Override
    public boolean isNotificationAvailable(Event event) {
        // Code smell: Method name could be misleading
        return notificationDao.isEventCategoryAvailable(event.getCategory());
    }
}

