public class TXTRenderer extends AbstractPathOrientedRenderer {
    private StringBuilder output;
    private int currentPage;
    private String encoding;
    private boolean isFlushed;

    public TXTRenderer(String encoding) {
        this.output = new StringBuilder();
        this.currentPage = 0;
        this.encoding = encoding;
        this.isFlushed = false;
    }

    public void addCharacter(char c) {
        output.append(c);
    }

    public void addString(String str) {
        output.append(str);
    }

    public void addImage(String image) {
        output.append("[Image: ").append(image).append("]");
    }

    public void startPage() {
        if (currentPage > 0) {
            output.append("\n--- Page ").append(currentPage).append(" End ---\n");
        }
        currentPage++;
        output.append("--- Page ").append(currentPage).append(" Start ---\n");
    }

    public void endPage() {
        output.append("\n--- Page ").append(currentPage).append(" End ---\n");
    }

    public boolean isPointWithinPage(int x, int y) {
        // Assuming page dimensions are fixed for simplicity
        return x >= 0 && x <= 80 && y >= 0 && y <= 60; // Example dimensions
    }

    public void flush(OutputStream outputStream) throws IOException {
        if (!isFlushed) {
            outputStream.write(output.toString().getBytes(encoding));
            outputStream.flush();
            isFlushed = true;
        }
    }

    public void reset() {
        output.setLength(0);
        currentPage = 0;
        isFlushed = false;
    }

    public void setBorder(String border) {
        output.append(border);
    }

    public void setBackground(String background) {
        output.append("[Background: ").append(background).append("]");
    }
}

