public class OpWriterWorker implements OpVisitor {
    private static final String NEW_LINE = System.lineSeparator();
    private IndentedWriter writer;
    private SerializationContext context;

    public OpWriterWorker(IndentedWriter writer, SerializationContext context) {
        this.writer = writer;
        this.context = context;
    }

    @Override
    public void visit(OpBGP opBGP) {
        writer.indent();
        writer.write("BGP: ");
        // Process each triple in the BGP
        for (Triple triple : opBGP.getPattern().getList()) {
            writer.write(triple.toString() + NEW_LINE);
        }
        writer.unindent();
    }

    @Override
    public void visit(OpQuadPattern quadPattern) {
        writer.indent();
        writer.write("QuadPattern: ");
        // Process each quad in the quad pattern
        for (Quad quad : quadPattern.getQuads()) {
            writer.write(quad.toString() + NEW_LINE);
        }
        writer.unindent();
    }

    @Override
    public void visit(OpJoin opJoin) {
        writer.indent();
        writer.write("Join: ");
        // Visit each operand of the join
        for (Op op : opJoin.getOperands()) {
            op.visit(this);
        }
        writer.unindent();
    }

    @Override
    public void visit(OpFilter opFilter) {
        writer.indent();
        writer.write("Filter: ");
        // Serialize the filter condition
        writer.write(opFilter.getExprs().toString() + NEW_LINE);
        opFilter.getSubOp().visit(this);
        writer.unindent();
    }

    // Additional methods for other operation types...

    @Override
    public void visit(OpUnion opUnion) {
        writer.indent();
        writer.write("Union: ");
        for (Op op : opUnion.getOperands()) {
            op.visit(this);
        }
        writer.unindent();
    }

    @Override
    public void visit(OpOrder opOrder) {
        writer.indent();
        writer.write("Order: ");
        // Serialize sorting conditions
        writer.write(opOrder.getConditions().toString() + NEW_LINE);
        opOrder.getSubOp().visit(this);
        writer.unindent();
    }

    @Override
    public void visit(OpDistinct opDistinct) {
        writer.indent();
        writer.write("Distinct: ");
        opDistinct.getSubOp().visit(this);
        writer.unindent();
    }

    @Override
    public void visit(OpReduced opReduced) {
        writer.indent();
        writer.write("Reduced: ");
        opReduced.getSubOp().visit(this);
        writer.unindent();
    }

    @Override
    public void visit(OpGroup opGroup) {
        writer.indent();
        writer.write("Group: ");
        // Serialize grouping conditions
        writer.write(opGroup.getGroupVars().toString() + NEW_LINE);
        opGroup.getSubOp().visit(this);
        writer.unindent();
    }

