public class StandardProvenanceReporter implements ProvenanceReporter {
    private static final Logger logger = LoggerFactory.getLogger(StandardProvenanceReporter.class);
    private List<ProvenanceEventRecord> eventRecords;

    public StandardProvenanceReporter() {
        this.eventRecords = new ArrayList<>();
    }

    public void receive(FlowFile flowFile) {
        ProvenanceEventRecord event = new ProvenanceEventRecord("RECEIVE", flowFile);
        eventRecords.add(event);
    }

    public void send(FlowFile flowFile) {
        ProvenanceEventRecord event = new ProvenanceEventRecord("SEND", flowFile);
        eventRecords.add(event);
    }

    public void fetch(FlowFile flowFile) {
        ProvenanceEventRecord event = new ProvenanceEventRecord("FETCH", flowFile);
        eventRecords.add(event);
    }

    public void fork(FlowFile flowFile) {
        ProvenanceEventRecord event = new ProvenanceEventRecord("FORK", flowFile);
        eventRecords.add(event);
    }

    public void join(FlowFile flowFile) {
        ProvenanceEventRecord event = new ProvenanceEventRecord("JOIN", flowFile);
        eventRecords.add(event);
    }

    public void clone(FlowFile flowFile) {
        ProvenanceEventRecord event = new ProvenanceEventRecord("CLONE", flowFile);
        eventRecords.add(event);
    }

    public void modify(FlowFile flowFile) {
        ProvenanceEventRecord event = new ProvenanceEventRecord("MODIFY", flowFile);
        eventRecords.add(event);
    }

    public void associateAlternateIdentifier(FlowFile flowFile, String identifier) {
        ProvenanceEventRecord event = new ProvenanceEventRecord("ASSOCIATE_IDENTIFIER", flowFile);
        event.setAlternateIdentifier(identifier);
        eventRecords.add(event);
    }

    public void drop(FlowFile flowFile) {
        ProvenanceEventRecord event = new ProvenanceEventRecord("DROP", flowFile);
        eventRecords.add(event);
    }

    public void handleError(FlowFile flowFile, Exception e) {
        logger.error("Error processing FlowFile: " + flowFile.getId(), e);
        ProvenanceEventRecord event = new ProvenanceEventRecord("ERROR", flowFile);
        event.setErrorMessage(e.getMessage());
        eventRecords.add(event);
    }

    public void migrateEventsToNewOwner(String newOwner) {
        for (ProvenanceEventRecord event : eventRecords) {
            event.setOwner(newOwner);
        }
    }
}

