public class StoreJanitorImpl implements StoreJanitor, Parameterizable, ThreadSafe, Runnable, Startable {
    private static final Logger logger = Logger.getLogger(StoreJanitorImpl.class.getName());

    private long minFreeMemory;
    private long maxHeapSize;
    private long cleanupInterval;
    private int threadPriority;
    private final List<Store> registeredStores = new ArrayList<>();
    private volatile boolean running = false;
    private Thread cleanupThread;

    @Override
    public void configure(long minFreeMemory, long maxHeapSize, long cleanupInterval, int threadPriority) {
        this.minFreeMemory = minFreeMemory;
        this.maxHeapSize = maxHeapSize;
        this.cleanupInterval = cleanupInterval;
        this.threadPriority = threadPriority;
    }

    @Override
    public void start() {
        running = true;
        cleanupThread = new Thread(this);
        cleanupThread.setPriority(threadPriority);
        cleanupThread.start();
    }

    @Override
    public void stop() {
        running = false;
        cleanupThread.interrupt();
    }

    @Override
    public void run() {
        while (running) {
            try {
                Thread.sleep(cleanupInterval);
                checkMemoryUsage();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void checkMemoryUsage() {
        long freeMemory = Runtime.getRuntime().freeMemory();
        if (freeMemory < minFreeMemory) {
            logger.info("Free memory is low. Performing cleanup.");
            cleanupMemory();
        }
        // Optionally invoke garbage collection
        System.gc();
    }

    private void cleanupMemory() {
        for (Store store : registeredStores) {
            store.cleanup();
        }
    }

    @Override
    public void registerStore(Store store) {
        registeredStores.add(store);
    }

    @Override
    public void unregisterStore(Store store) {
        registeredStores.remove(store);
    }
}

