public class OperationWithIndexTest {

    private LdapConnection ldapConnection;

    @Before
    public void setUp() {
        ldapConnection = new LdapConnection();
        ldapConnection.connect();
        ldapConnection.createPartition("testPartition");
        ldapConnection.createIndex("testPartition", "cn");
    }

    @After
    public void tearDown() {
        ldapConnection.deletePartition("testPartition");
        ldapConnection.disconnect();
    }

    @Test
    public void testAddPerf() {
        long startTime = System.currentTimeMillis();
        for (int i = 0; i < 1000; i++) {
            ldapConnection.addEntry("cn=entry" + i + ",ou=testPartition", "testAttribute", "testValue");
        }
        long endTime = System.currentTimeMillis();
        System.out.println("Time taken to add entries: " + (endTime - startTime) + " ms");

        startTime = System.currentTimeMillis();
        for (int i = 0; i < 1000; i++) {
            ldapConnection.search("cn=entry" + i + ",ou=testPartition");
        }
        endTime = System.currentTimeMillis();
        System.out.println("Time taken to search entries: " + (endTime - startTime) + " ms");
    }

    @Test
    public void testModify() {
        ldapConnection.addEntry("cn=modifyEntry,ou=testPartition", "testAttribute", "initialValue");
        ldapConnection.modifyEntry("cn=modifyEntry,ou=testPartition", "testAttribute", "newValue");

        String result = ldapConnection.search("cn=modifyEntry,ou=testPartition").get("testAttribute");
        assertEquals("newValue", result);
    }

    @Test
    public void testModifyReplace() {
        ldapConnection.addEntry("cn=replaceEntry,ou=testPartition", "testAttribute", "oldValue");
        ldapConnection.modifyEntry("cn=replaceEntry,ou=testPartition", "testAttribute", "replacedValue");

        String result = ldapConnection.search("cn=replaceEntry,ou=testPartition").get("testAttribute");
        assertEquals("replacedValue", result);
    }

    @Test
    public void testModifyAdd() {
        ldapConnection.addEntry("cn=addEntry,ou=testPartition", "testAttribute", "value");
        ldapConnection.addAttribute("cn=addEntry,ou=testPartition", "newAttribute", "newValue");

        String result = ldapConnection.search("cn=addEntry,ou=testPartition").get("newAttribute");
        assertEquals("newValue", result);
    }

    @Test
    public void testModifyDelete() {
        ldapConnection.addEntry("cn=deleteEntry,ou=testPartition", "testAttribute", "value");
        ldapConnection.deleteAttribute("cn=deleteEntry,ou=testPartition", "testAttribute");

        String result = ldapConnection.search("cn=deleteEntry,ou=testPartition").get("testAttribute");
        assertNull(result);
    }

    @Test
    public void testSimpleSearch() {
        ldapConnection.addEntry("cn=searchEntry,ou=testPartition", "testAttribute", "searchValue");
        String result = ldapConnection.search("testAttribute=searchValue").get("cn");
        assertEquals("searchEntry", result);
    }
}

