public abstract class AuthorizingRealm extends AuthenticatingRealm {

    private Map<Object, AuthorizationInfo> authorizationCache = new HashMap<>();
    private PermissionResolver permissionResolver;
    private RoleResolver roleResolver;

    public void setPermissionResolver(PermissionResolver permissionResolver) {
        this.permissionResolver = permissionResolver;
    }

    public void setRoleResolver(RoleResolver roleResolver) {
        this.roleResolver = roleResolver;
    }

    protected abstract AuthorizationInfo doGetAuthorizationInfo(PrincipalCollection principals);

    public AuthorizationInfo getAuthorizationInfo(PrincipalCollection principals) {
        Object primaryPrincipal = principals.getPrimaryPrincipal();
        if (authorizationCache.containsKey(primaryPrincipal)) {
            return authorizationCache.get(primaryPrincipal);
        }
        AuthorizationInfo info = doGetAuthorizationInfo(principals);
        if (info != null) {
            authorizationCache.put(primaryPrincipal, info);
        }
        return info;
    }

    public boolean isPermitted(PrincipalCollection principals, String permission) {
        AuthorizationInfo info = getAuthorizationInfo(principals);
        return info != null && info.getPermissions().contains(permission);
    }

    public boolean isPermittedAll(PrincipalCollection principals, String... permissions) {
        for (String permission : permissions) {
            if (!isPermitted(principals, permission)) {
                return false;
            }
        }
        return true;
    }

    public boolean hasRole(PrincipalCollection principals, String role) {
        AuthorizationInfo info = getAuthorizationInfo(principals);
        return info != null && info.getRoles().contains(role);
    }

    public boolean hasAllRoles(PrincipalCollection principals, Collection<String> roles) {
        for (String role : roles) {
            if (!hasRole(principals, role)) {
                return false;
            }
        }
        return true;
    }

    public void checkPermission(PrincipalCollection principals, String permission) {
        if (!isPermitted(principals, permission)) {
            throw new UnauthorizedException("User does not have permission: " + permission);
        }
    }

    public void checkRole(PrincipalCollection principals, String role) {
        if (!hasRole(principals, role)) {
            throw new UnauthorizedException("User does not have role: " + role);
        }
    }

    public void clearCachedAuthorizationInfo(PrincipalCollection principals) {
        authorizationCache.remove(principals.getPrimaryPrincipal());
    }

    public void clearAllCachedAuthorizationInfo() {
        authorizationCache.clear();
    }
}

