class ContentTypeHandlerManagerTest {

    private DefaultContentTypeHandlerManager manager;
    private HttpServletRequest request;
    private HttpServletResponse response;
    private ContentTypeHandler handler;

    @Before
    public void setUp() {
        manager = new DefaultContentTypeHandlerManager();
        request = mock(HttpServletRequest.class);
        response = mock(HttpServletResponse.class);
        handler = mock(ContentTypeHandler.class);
    }

    @Test
    public void testHandleContentType() throws Exception {
        when(request.getContentType()).thenReturn("application/json");
        when(handler.canHandle("application/json")).thenReturn(true);
        manager.registerHandler("application/json", handler);

        manager.handle(request, response);

        verify(handler).handle(request, response);
    }

    @Test
    public void testHandleUnsupportedContentType() throws Exception {
        when(request.getContentType()).thenReturn("text/plain");
        manager.registerHandler("application/json", handler);

        manager.handle(request, response);

        verify(response).sendError(HttpServletResponse.SC_UNSUPPORTED_MEDIA_TYPE);
    }

    @Test
    public void testHandleWithHttpStatusCode() throws Exception {
        when(request.getContentType()).thenReturn("application/xml");
        when(handler.canHandle("application/xml")).thenReturn(true);
        manager.registerHandler("application/xml", handler);
        when(handler.handle(request, response)).thenReturn(HttpServletResponse.SC_OK);

        manager.handle(request, response);

        verify(response).setStatus(HttpServletResponse.SC_OK);
    }

    @Test
    public void testVerifyContentLength() throws Exception {
        when(request.getContentType()).thenReturn("application/json");
        when(handler.canHandle("application/json")).thenReturn(true);
        manager.registerHandler("application/json", handler);
        when(handler.handle(request, response)).thenReturn(HttpServletResponse.SC_OK);
        when(request.getContentLength()).thenReturn(100);

        manager.handle(request, response);

        verify(response).setHeader("Content-Length", "100");
    }

    @Test
    public void testMultipleHandlers() throws Exception {
        ContentTypeHandler handler1 = mock(ContentTypeHandler.class);
        ContentTypeHandler handler2 = mock(ContentTypeHandler.class);

        when(request.getContentType()).thenReturn("application/xml");
        when(handler1.canHandle("application/xml")).thenReturn(false);
        when(handler2.canHandle("application/xml")).thenReturn(true);

        manager.registerHandler("application/xml", handler1);
        manager.registerHandler("application/xml", handler2);

        manager.handle(request, response);

        verify(handler2).handle(request, response);
    }
}

class CxfBinding {

    private CxfBinding() {
        // Private constructor to prevent instantiation
    }

    public static Object extractMessageBody(Exchange exchange) {
        return exchange.getIn().getBody();
    }

    public static Message createCxfMessage(Object body, Map<String, Object> headers) {
        SoapMessage cxfMessage = new SoapMessage();
        cxfMessage.setContent(Object.class, body);
        headers.forEach(cxfMessage::put);
        return cxfMessage;
    }

    public static void storeResponse(Exchange exchange, Object response) {
        exchange.getOut().setBody(response);
    }

    public static void storeFault(Exchange exchange, Throwable fault) {
        exchange.getOut().setFault(true);
        exchange.getOut().setBody(fault);
    }

    public static void copyMessageToCxf(Exchange exchange, Message cxfMessage) {
        cxfMessage.setContent(Object.class, exchange.getIn().getBody());
        exchange.getIn().getHeaders().forEach(cxfMessage::put);
    }

    public static void copyMessageToCamel(Message cxfMessage, Exchange exchange) {
        exchange.getIn().setBody(cxfMessage.getContent(Object.class));
        cxfMessage.getHeaders().forEach((key, value) -> exchange.getIn().setHeader(key, value));
    }

    public static void propagateContext(Exchange requestExchange, Exchange responseExchange) {
        responseExchange.getIn().setHeaders(requestExchange.getIn().getHeaders());
    }
}

