public class RemoteFileConfiguration {
    private String protocol;
    private String username;
    private String host;
    private int port;
    private String password;
    private String filePath;
    private boolean binaryMode;
    private boolean isDirectory;
    private String ftpClientConfig;
    private String sshKey;

    public RemoteFileConfiguration() {
    }

    public void configureFromURI(String uriString) throws URISyntaxException {
        URI uri = new URI(uriString);
        this.protocol = uri.getScheme();
        this.host = uri.getHost();
        this.port = uri.getPort() == -1 ? getDefaultPort(protocol) : uri.getPort();
        this.username = uri.getUserInfo() != null ? uri.getUserInfo().split(":")[0] : null;
        this.password = uri.getUserInfo() != null && uri.getUserInfo().contains(":") ? uri.getUserInfo().split(":")[1] : null;
        this.filePath = uri.getPath();
    }

    private int getDefaultPort(String protocol) {
        switch (protocol.toLowerCase()) {
            case "ftp":
                return 21;
            case "sftp":
                return 22;
            default:
                return -1;
        }
    }

    public RemoteFileConfiguration clone() {
        RemoteFileConfiguration clone = new RemoteFileConfiguration();
        clone.protocol = this.protocol;
        clone.username = this.username;
        clone.host = this.host;
        clone.port = this.port;
        clone.password = this.password;
        clone.filePath = this.filePath;
        clone.binaryMode = this.binaryMode;
        clone.isDirectory = this.isDirectory;
        clone.ftpClientConfig = this.ftpClientConfig;
        clone.sshKey = this.sshKey;
        return clone;
    }

    public String getProtocol() {
        return protocol;
    }

    public void setProtocol(String protocol) {
        this.protocol = protocol;
    }

    public String getUsername() {
        return username;
