public class NiFiOrcUtils {

    public static TypeDescription getOrcType(String type) {
        switch (type.toLowerCase()) {
            case "int":
                return TypeDescription.createInt();
            case "boolean":
                return TypeDescription.createBoolean();
            case "string":
                return TypeDescription.createString();
            case "timestamp":
                return TypeDescription.createTimestamp();
            case "date":
                return TypeDescription.createDate();
            case "array":
                return TypeDescription.createList(TypeDescription.createString());
            case "map":
                return TypeDescription.createMap(TypeDescription.createString(), TypeDescription.createString());
            case "record":
                return TypeDescription.createStruct();
            default:
                throw new IllegalArgumentException("Unsupported type: " + type);
        }
    }

    public static String generateHiveDDL(String tableName, List<String> columns) {
        StringBuilder ddl = new StringBuilder("CREATE TABLE " + normalizeTableName(tableName) + " (");
        for (String column : columns) {
            ddl.append(column).append(" STRING, ");
        }
        ddl.setLength(ddl.length() - 2); // Remove last comma and space
        ddl.append(") STORED AS ORC;");
        return ddl.toString();
    }

    public static String normalizeTableName(String tableName) {
        return tableName.toLowerCase().replaceAll("[^a-z0-9_]", "_");
    }

    public static Writer createOrcWriter(String path, TypeDescription schema) throws IOException {
        Configuration conf = new Configuration();
        Path outputPath = new Path(path);
        return OrcFile.createWriter(outputPath, OrcFile.writerOptions(conf).setSchema(schema));
    }

    public static TypeDescription getOrcSchemaFromRecordSchema(Map<String, String> recordSchema) {
        TypeDescription schema = TypeDescription.createStruct();
        for (Map.Entry<String, String> entry : recordSchema.entrySet()) {
            schema.addField(entry.getKey(), getOrcType(entry.getValue()));
        }
        return schema;
    }
}

