public class PrecedenceQueryParserTokenManager implements PrecedenceQueryParserConstants {
    private static final int EOF = 0;
    private static final int DEFAULT = 1;
    private static final int COMMENT = 2;
    private static final int STRING_LITERAL = 3;
    private static final int IDENTIFIER = 4;

    private char[] input;
    private int currentIndex;
    private int currentState;
    private StringBuilder tokenBuffer;
    private boolean debug;

    public PrecedenceQueryParserTokenManager(String input, boolean debug) {
        this.input = input.toCharArray();
        this.currentIndex = 0;
        this.currentState = DEFAULT;
        this.tokenBuffer = new StringBuilder();
        this.debug = debug;
    }

    public Token getNextToken() {
        while (currentIndex < input.length) {
            char currentChar = input[currentIndex];
            switch (currentState) {
                case DEFAULT:
                    if (Character.isWhitespace(currentChar)) {
                        currentIndex++;
                    } else if (currentChar == '/') {
                        currentState = COMMENT;
                        currentIndex++;
                    } else if (currentChar == '"') {
                        currentState = STRING_LITERAL;
                        currentIndex++;
                    } else if (Character.isJavaIdentifierStart(currentChar)) {
                        currentState = IDENTIFIER;
                        tokenBuffer.append(currentChar);
                        currentIndex++;
                    } else {
                        return new Token(TokenType.UNKNOWN, String.valueOf(currentChar));
                    }
                    break;
                case COMMENT:
                    if (currentChar == '\n') {
                        currentState = DEFAULT;
                    }
                    currentIndex++;
                    break;
                case STRING_LITERAL:
                    if (currentChar == '"') {
                        currentState = DEFAULT;
                        currentIndex++;
                        return new Token(TokenType.STRING_LITERAL, tokenBuffer.toString());
                    } else {
                        tokenBuffer.append(currentChar);
                        currentIndex++;
                    }
                    break;
                case IDENTIFIER:
                    if (Character.isJavaIdentifierPart(currentChar)) {
                        tokenBuffer.append(currentChar);
                        currentIndex++;
                    } else {
                        currentState = DEFAULT;
                        return new Token(TokenType.IDENTIFIER, tokenBuffer.toString());
                    }
                    break;
            }
        }
        return new Token(TokenType.EOF, "");
    }

    public void reset() {
        currentIndex = 0;
        currentState = DEFAULT;
        tokenBuffer.setLength(0);
    }

    public void switchState(int newState) {
        currentState = newState;
    }

    private void debug(String message) {
        if (debug) {
            System.out.println(message);
        }
    }
}

