public class JAXBContextInitializer {

    private Set<Class<?>> classes = new HashSet<>();
    private Set<Type> typeReferences = new HashSet<>();
    private Set<Object> globalAdapters = new HashSet<>();

    public void processMessagePartInfo(MessagePartInfo messagePartInfo) {
        Class<?> clazz = messagePartInfo.getType();
        if (isValidType(clazz)) {
            classes.add(clazz);
            collectTypeReferences(clazz);
            processAnnotations(clazz);
        }
    }

    private boolean isValidType(Class<?> clazz) {
        return !clazz.isInterface() && !clazz.isEnum() && !clazz.isAnnotation();
    }

    private void collectTypeReferences(Class<?> clazz) {
        for (Field field : clazz.getDeclaredFields()) {
            Type fieldType = field.getGenericType();
            if (fieldType instanceof ParameterizedType) {
                typeReferences.add(fieldType);
            } else {
                typeReferences.add(field.getType());
            }
        }
        for (Method method : clazz.getDeclaredMethods()) {
            Type returnType = method.getGenericReturnType();
            if (returnType instanceof ParameterizedType) {
                typeReferences.add(returnType);
            } else {
                typeReferences.add(method.getReturnType());
            }
        }
    }

    private void processAnnotations(Class<?> clazz) {
        if (clazz.isAnnotationPresent(XmlRootElement.class)) {
            // Handle XmlRootElement
        }
        if (clazz.isAnnotationPresent(XmlType.class)) {
            // Handle XmlType
        }
        for (Field field : clazz.getDeclaredFields()) {
            if (field.isAnnotationPresent(XmlJavaTypeAdapter.class)) {
                globalAdapters.add(field.getAnnotation(XmlJavaTypeAdapter.class));
            }
        }
    }

    public Set<Class<?>> getClasses() {
        return classes;
    }

    public Set<Type> getTypeReferences() {
        return typeReferences;
    }

    public Set<Object> getGlobalAdapters() {
        return globalAdapters;
    }
}

public class StringExtensions {

    public static String toNaturalName(String input) {
        return input.replaceAll("([A-Z])", " $1").trim();
    }

    public static String toCamelCase(String input) {
        String[] parts = input.split(" ");
        StringBuilder camelCase = new StringBuilder();
        for (String part : parts) {
            if (part.length() > 0) {
                camelCase.append(Character.toUpperCase(part.charAt(0)))
                         .append(part.substring(1).toLowerCase());
            }
        }
        return camelCase.toString();
    }

    public static String toPascalCase(String input) {
        return toCamelCase(input);
    }

    public static String toLowerDashed(String input) {
        return input.replaceAll("([A-Z])", "-$1").toLowerCase().replaceAll("^-", "");
    }

    public static String extractSimpleName(String fullyQualifiedName) {
        return fullyQualifiedName.substring(fullyQualifiedName.lastIndexOf('.') + 1);
    }

    public static String normalize(String input) {
        return input.trim().replaceAll("\\s+", " ");
    }

    public static String repeat(String input, int times) {
        return String.join("", Collections.nCopies(times, input));
    }

    public static String combinePaths(String... paths) {
        return String.join("/", paths);
    }

    public static String friendlyNameFromEnum(Enum<?> e) {
        return toNaturalName(e.name());
    }

    public static String enumNameFromFriendly(String friendlyName) {
        return friendlyName.toUpperCase().replaceAll(" ", "_");
    }

    public static String stripUnwantedCharacters(String input) {
        return input.replaceAll("[\\t\\n\\r]", "").replaceAll("^/+", "");
    }

    public static boolean startsWith(String input, String prefix) {
        return input.startsWith(prefix);
    }

    public static String pluralize(String word) {
        if (word.endsWith("s")) {
            return word;
        }
        return word + "s";
    }

    public static String capitalize(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }
        return Character.toUpperCase(input.charAt(0)) + input.substring(1);
    }

    public static String abbreviate(String input) {
        String[] words = input.split(" ");
        StringBuilder abbreviation = new StringBuilder();
        for (String word : words) {
            if (!word.isEmpty()) {
                abbreviation.append(Character.toUpperCase(word.charAt(0)));
            }
        }
        return abbreviation.toString();
    }
}

public class FileUtils {

    public static void createFile(String path) throws IOException {
        File file = new File(path);
        if (!file.exists()) {
            file.createNewFile();
        }
    }

    public static void createDirectory(String path) throws IOException {
        File directory = new File(path);
        if (!directory.exists()) {
            directory.mkdirs();
        }
    }

    public static void deleteFile(String path) {
        File file = new File(path);
        if (file.exists()) {
            file.delete();
        }
    }

    public static void deleteDirectory(String path) {
        File directory = new File(path);
        if (directory.exists()) {
            for (File file : directory.listFiles()) {
                if (file.isDirectory()) {
                    deleteDirectory(file.getAbsolutePath());
                } else {
                    file.delete();
                }
            }
            directory.delete();
        }
    }

    public static void copyFile(String source, String destination) throws IOException {
        Files.copy(Paths.get(source), Paths.get(destination), StandardCopyOption.REPLACE_EXISTING);
    }

    public static void writeFile(String path, String content, String encoding) throws IOException {
        try (BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(path), encoding))) {
            writer.write(content);
        }
    }

    public static String readFile(String path, String encoding) throws IOException {
        StringBuilder content = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(path), encoding))) {
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append(System.lineSeparator());
            }
        }
        return content.toString();
    }

    public static long getFileSize(String path) {
        return new File(path).length();
    }

    public static String convertFileSize(long size) {
        String[] units = {"Bytes", "KB", "MB", "GB"};
        int unitIndex = 0;
        double fileSize = size;
        while (fileSize >= 1024 && unitIndex < units.length - 1) {
            fileSize /= 1024;
            unitIndex++;
        }
        return String.format("%.2f %s", fileSize, units[unitIndex]);
    }

    public static String getTempDirectory() {
        return System.getProperty("java.io.tmpdir");
    }

    public static String getUserDirectory() {
        return System.getProperty("user.home");
    }

    public static List<File> listFiles(String directoryPath) {
        File directory = new File(directoryPath);
        return Arrays.asList(directory.listFiles());
    }

    public static List<File> listFilesRecursively(String directoryPath) throws IOException {
        List<File> fileList = new ArrayList<>();
        Files.walkFileTree(Paths.get(directoryPath), new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                fileList.add(file.toFile());
                return FileVisitResult.CONTINUE;
            }
        });
        return fileList;
    }

    public static boolean compareFiles(String filePath1, String filePath2) throws IOException {
        return Files.mismatch(Paths.get(filePath1), Paths.get(filePath2)) == -1;
    }

    public static String calculateChecksum(String path) throws IOException {
        return Files.readAllBytes(Paths.get(path)).toString(); // Simplified checksum
    }

    public static void moveFile(String source, String destination) throws IOException {
        Files.move(Paths.get(source), Paths.get(destination), StandardCopyOption.REPLACE_EXISTING);
    }

    public static boolean isSymbolicLink(String path) throws IOException {
        return Files.isSymbolicLink(Paths.get(path));
    }

    public static List<URL> filesToUrls(List<File> files) throws MalformedURLException {
        return files.stream().map(file -> {
            try {
                return file.toURI().toURL();
            } catch (MalformedURLException e) {
                return null;
            }
        }).collect(Collectors.toList());
    }
}

