@PrepareForTest({CouchbaseTableReadFunction.class, Cluster.class, Bucket.class})
public class TestCouchbaseTableReadFunction {

    private CouchbaseTableReadFunction couchbaseTableReadFunction;
    private Cluster mockCluster;
    private Bucket mockBucket;
    private Collection mockCollection;

    @Before
    public void setUp() {
        mockCluster = mock(Cluster.class);
        mockBucket = mock(Bucket.class);
        mockCollection = mock(Collection.class);
        when(mockCluster.bucket(anyString())).thenReturn(mockBucket);
        when(mockBucket.defaultCollection()).thenReturn(mockCollection);
        couchbaseTableReadFunction = new CouchbaseTableReadFunction(mockCluster, "testBucket", String.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstructorWithNullBucketName() {
        new CouchbaseTableReadFunction(mockCluster, null, String.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstructorWithNullCluster() {
        new CouchbaseTableReadFunction(null, "testBucket", String.class);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstructorWithNullValueClass() {
        new CouchbaseTableReadFunction(mockCluster, "testBucket", null);
    }

    @Test
    public void testIsRetriableWithTimeoutException() {
        assertTrue(couchbaseTableReadFunction.isRetriable(new TimeoutException()));
    }

    @Test
    public void testIsRetriableWithOtherException() {
        assertFalse(couchbaseTableReadFunction.isRetriable(new RuntimeException()));
    }

    @Test
    public void testGetAsyncWithNullKey() {
        try {
            couchbaseTableReadFunction.getAsync(null).join();
            fail("Expected an exception to be thrown");
        } catch (Exception e) {
            assertEquals("Key cannot be null", e.getMessage());
        }
    }

    @Test
    public void testGetAsyncWithNonExistentKey() {
        when(mockCollection.get(anyString())).thenThrow(new DocumentNotFoundException("Document not found"));
        try {
            couchbaseTableReadFunction.getAsync("nonExistentKey").join();
            fail("Expected an exception to be thrown");
        } catch (Exception e) {
            assertEquals("Document not found", e.getMessage());
        }
    }

    @Test
    public void testGetAsyncWithDeserializationFailure() {
        when(mockCollection.get(anyString())).thenReturn(mock(GetResult.class));
        when(mockCollection.get("validKey")).thenReturn(mock(GetResult.class));
        // Simulate deserialization failure
        try {
            couchbaseTableReadFunction.getAsync("validKey").join();
            fail("Expected an exception to be thrown");
        } catch (Exception e) {
            assertEquals("Deserialization failed", e.getMessage());
        }
    }

    @Test
    public void testGetAsyncWithValidKey() {
        GetResult mockGetResult = mock(GetResult.class);
        when(mockGetResult.contentAs(String.class)).thenReturn("validContent");
        when(mockCollection.get("validKey")).thenReturn(mockGetResult);

        String result = couchbaseTableReadFunction.getAsync("validKey").join();
        assertEquals("validContent", result);
    }
}

