public class TestZkCacheAsyncOpSingleThread extends ZkTestBase {
    private static final Logger logger = LoggerFactory.getLogger(TestZkCacheAsyncOpSingleThread.class);

    @Test
    public void testHappyPathExtOpZkCacheBaseDataAccessor() {
        logger.info("Starting testHappyPathExtOpZkCacheBaseDataAccessor");
        long startTime = System.currentTimeMillis();

        ZkBaseDataAccessor<String> baseDataAccessor = new ZkBaseDataAccessor<>(zkClient);
        ZkCacheBaseDataAccessor<String> cacheDataAccessor = new ZkCacheBaseDataAccessor<>(baseDataAccessor);

        String path = "/test/path";
        String data = "testData";

        // Create
        baseDataAccessor.create(path, data);
        assertEquals(data, cacheDataAccessor.get(path));

        // Update
        String updatedData = "updatedData";
        baseDataAccessor.set(path, updatedData);
        assertEquals(updatedData, cacheDataAccessor.get(path));

        // Remove
        baseDataAccessor.remove(path);
        assertNull(cacheDataAccessor.get(path));

        long endTime = System.currentTimeMillis();
        logger.info("Finished testHappyPathExtOpZkCacheBaseDataAccessor in {} ms", (endTime - startTime));
    }

    @Test
    public void testHappyPathSelfOpZkCacheBaseDataAccessor() {
        logger.info("Starting testHappyPathSelfOpZkCacheBaseDataAccessor");
        long startTime = System.currentTimeMillis();

        ZkBaseDataAccessor<String> baseDataAccessor = new ZkBaseDataAccessor<>(zkClient);
        ZkCacheBaseDataAccessor<String> cacheDataAccessor = new ZkCacheBaseDataAccessor<>(baseDataAccessor);

        String path = "/test/self/path";
        String data = "selfTestData";

        // Create
        baseDataAccessor.create(path, data);
        assertEquals(data, cacheDataAccessor.get(path));

        // Update
        String selfUpdatedData = "selfUpdatedData";
        baseDataAccessor.set(path, selfUpdatedData);
        assertEquals(selfUpdatedData, cacheDataAccessor.get(path));

        // Remove
        baseDataAccessor.remove(path);
        assertNull(cacheDataAccessor.get(path));

        long endTime = System.currentTimeMillis();
        logger.info("Finished testHappyPathSelfOpZkCacheBaseDataAccessor in {} ms", (endTime - startTime));
    }
}

