    private HttpServletRequest request;
    private HttpServletResponse response;

    @Before
    public void setUp() {
        configurableDispatch = new ConfigurableDispatch();
        request = EasyMock.createMock(HttpServletRequest.class);
        response = EasyMock.createMock(HttpServletResponse.class);
    }

    @Test
    public void testGetDispatchUrlWithEncoding() {
        EasyMock.expect(request.getRequestURI()).andReturn("/test");
        EasyMock.expect(request.getQueryString()).andReturn("param=value");
        EasyMock.replay(request);

        String url = configurableDispatch.getDispatchUrl(request, true);
        assertEquals("/test?param=value", url);

        EasyMock.verify(request);
    }

    @Test
    public void testGetDispatchUrlWithoutEncoding() {
        EasyMock.expect(request.getRequestURI()).andReturn("/test");
        EasyMock.expect(request.getQueryString()).andReturn("param=value");
        EasyMock.replay(request);

        String url = configurableDispatch.getDispatchUrl(request, false);
        assertEquals("/test?param=value", url);

        EasyMock.verify(request);
    }

    @Test
    public void testHeaderExclusion() {
        configurableDispatch.setExcludedHeaders("X-Excluded-Header");
        EasyMock.expect(request.getHeader("X-Excluded-Header")).andReturn("value");
        EasyMock.expect(request.getHeader("X-Included-Header")).andReturn("value");
        EasyMock.replay(request);

        String headerValue = configurableDispatch.getHeaderValue(request, "X-Excluded-Header");
        assertEquals(null, headerValue);

        headerValue = configurableDispatch.getHeaderValue(request, "X-Included-Header");
        assertEquals("value", headerValue);

        EasyMock.verify(request);
    }

    @Test
    public void testHeaderInclusion() {
        configurableDispatch.setExcludedHeaders("X-Excluded-Header");
        EasyMock.expect(request.getHeader("X-Excluded-Header")).andReturn("value");
        EasyMock.expect(request.getHeader("X-Included-Header")).andReturn("value");
        EasyMock.replay(request);

        String headerValue = configurableDispatch.getHeaderValue(request, "X-Included-Header");
        assertEquals("value", headerValue);

        EasyMock.verify(request);
    }
}

