    public void setUp() {
        tokenProvider = new SAMLTokenProvider();
    }

    @Test
    public void testCreateTokenWithRequestedLifetime() {
        SAMLToken token = tokenProvider.createToken(3600); // 1 hour
        assertNotNull(token);
        assertEquals(3600, token.getLifetime());
    }

    @Test
    public void testTokenProviderRespectsConfiguredLifetime() {
        tokenProvider.setConfiguredLifetime(1800); // 30 minutes
        SAMLToken token = tokenProvider.createToken(3600); // 1 hour
        assertNotNull(token);
        assertEquals(1800, token.getLifetime());
    }

    @Test
    public void testRequestedLifetimeExceedsConfiguredMaximum() {
        tokenProvider.setConfiguredLifetime(1800); // 30 minutes
        SAMLToken token = tokenProvider.createToken(7200); // 2 hours
        assertNotNull(token);
        assertEquals(1800, token.getLifetime());
    }

    @Test
    public void testLifetimeExceedsDefaultMaximum() {
        tokenProvider.setConfiguredLifetime(3600); // 1 hour
        SAMLToken token = tokenProvider.createToken(7200); // 2 hours
        assertNotNull(token);
        assertEquals(3600, token.getLifetime());
    }

    @Test
    public void testRequestedLifetimeUpdatedButExceedsMaximum() {
        tokenProvider.setConfiguredLifetime(1800); // 30 minutes
        SAMLToken token = tokenProvider.createToken(1200); // 20 minutes
        assertNotNull(token);
        assertEquals(1200, token.getLifetime());

        token = tokenProvider.createToken(3600); // 1 hour
        assertNotNull(token);
        assertEquals(1800, token.getLifetime());
    }

