public class RotationTest {

    @Test
    public void testIdentityRotation() {
        Rotation rotation = Rotation.identity();
        assertEquals(0.0, rotation.getAngle());
        assertArrayEquals(new double[]{1.0, 0.0, 0.0}, rotation.getAxis());
    }

    @Test
    public void testAxisAngleRepresentation() {
        double angle = Math.PI / 2;
        double[] axis = {0.0, 0.0, 1.0};
        Rotation rotation = new Rotation(axis, angle);
        assertEquals(angle, rotation.getAngle());
        assertArrayEquals(axis, rotation.getAxis());
    }

    @Test
    public void testRevertingRotation() {
        Rotation rotation = new Rotation(new double[]{0.0, 0.0, 1.0}, Math.PI / 2);
        Rotation reverted = rotation.revert();
        assertEquals(-rotation.getAngle(), reverted.getAngle());
        assertArrayEquals(rotation.getAxis(), reverted.getAxis());
    }

    @Test
    public void testApplyRotationToVector() {
        Rotation rotation = new Rotation(new double[]{0.0, 0.0, 1.0}, Math.PI / 2);
        double[] vector = {1.0, 0.0, 0.0};
        double[] rotatedVector = rotation.applyTo(vector);
        assertArrayEquals(new double[]{0.0, 1.0, 0.0}, rotatedVector, 1e-10);
    }

    @Test
    public void testComposeRotations() {
        Rotation rotation1 = new Rotation(new double[]{0.0, 0.0, 1.0}, Math.PI / 2);
        Rotation rotation2 = new Rotation(new double[]{1.0, 0.0, 0.0}, Math.PI / 2);
        Rotation composed = rotation1.compose(rotation2);
        assertNotNull(composed);
    }

    @Test
    public void testRotationMatrix() {
        Rotation rotation = new Rotation(new double[]{0.0, 0.0, 1.0}, Math.PI / 2);
        double[][] matrix = rotation.toMatrix();
        assertEquals(0.0, matrix[0][0]);
        assertEquals(1.0, matrix[0][1]);
        assertEquals(-1.0, matrix[1][0]);
        assertEquals(0.0, matrix[1][1]);
    }

    @Test
    public void testSingularityHandling() {
        Rotation rotation = new Rotation(new double[]{1.0, 0.0, 0.0}, Math.PI);
        assertThrows(IllegalArgumentException.class, () -> {
            rotation.toMatrix();
        });
    }
}

