public abstract class SocketClient {
    private Socket socket;
    private String host;
    private int port;
    private int timeout;
    private int bufferSize;
    private boolean tcpNoDelay;
    private boolean keepAlive;
    private Charset charset;
    private List<ProtocolCommandListener> commandListeners;

    public SocketClient(String host, int port, int timeout, int bufferSize) {
        this.host = host;
        this.port = port;
        this.timeout = timeout;
        this.bufferSize = bufferSize;
        this.tcpNoDelay = true;
        this.keepAlive = false;
        this.charset = Charset.defaultCharset();
        this.commandListeners = new ArrayList<>();
    }

    public void setTcpNoDelay(boolean tcpNoDelay) {
        this.tcpNoDelay = tcpNoDelay;
    }

    public void setKeepAlive(boolean keepAlive) {
        this.keepAlive = keepAlive;
    }

    public void setCharset(Charset charset) {
        this.charset = charset;
    }

    public void addProtocolCommandListener(ProtocolCommandListener listener) {
        commandListeners.add(listener);
    }

    public void connect() throws IOException {
        socket = new Socket();
        socket.connect(new InetSocketAddress(host, port), timeout);
        socket.setTcpNoDelay(tcpNoDelay);
        socket.setKeepAlive(keepAlive);
    }

    public void disconnect() throws IOException {
        if (socket != null && !socket.isClosed()) {
            socket.close();
        }
    }

    public boolean isConnected() {
        return socket != null && socket.isConnected() && !socket.isClosed();
    }

    public void sendData(String data) throws IOException {
        if (!isConnected()) {
            throw new IOException("Not connected to the server.");
        }
        OutputStream outputStream = socket.getOutputStream();
        outputStream.write(data.getBytes(charset));
        outputStream.flush();
    }

    public String receiveData() throws IOException {
        if (!isConnected()) {
            throw new IOException("Not connected to the server.");
        }
        InputStream inputStream = socket.getInputStream();
        byte[] buffer = new byte[bufferSize];
        int bytesRead = inputStream.read(buffer);
        return bytesRead == -1 ? null : new String(buffer, 0, bytesRead, charset);
    }

    protected void notifyCommandListeners(String command) {
        for (ProtocolCommandListener listener : commandListeners) {
            listener.onCommandReceived(command);
        }
    }

    public interface ProtocolCommandListener {
        void onCommandReceived(String command);
    }
}

