    }

    public String getSender() {
        return message.getSenderEmailAddress();
    }

    public String[] getRecipients() {
        return message.getRecipients();
    }

    public Date getSentDate() {
        return message.getSentDate();
    }

    public String getBody() throws Exception {
        String body;
        switch (message.getBodyFormat()) {
            case MAPIMessage.FORMAT_HTML:
                body = message.getHtmlBody();
                break;
            case MAPIMessage.FORMAT_RTF:
                body = message.getRtfBody();
                break;
            case MAPIMessage.FORMAT_TEXT:
            default:
                body = message.getTextBody();
                break;
        }
        return normalizeBody(body);
    }

    private String normalizeBody(String body) {
        // Normalize email body (e.g., remove unnecessary whitespace)
        return body.trim();
    }

