class QueueOutboundBridgeReconnectTest {

    private BrokerService producerBroker;
    private BrokerService consumerBroker;
    private PooledConnectionFactory connectionFactory;
    private Connection producerConnection;
    private Connection consumerConnection;
    private Session producerSession;
    private Session consumerSession;
    private Queue queue;

    @Before
    public void setUp() throws Exception {
        producerBroker = new BrokerService();
        consumerBroker = new BrokerService();
        connectionFactory = new PooledConnectionFactory();
        connectionFactory.setBrokerURL("tcp://localhost:61616");
        producerBroker.start();
        consumerBroker.start();
        producerConnection = connectionFactory.createConnection();
        consumerConnection = connectionFactory.createConnection();
        producerConnection.start();
        consumerConnection.start();
        producerSession = producerConnection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        consumerSession = consumerConnection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        queue = producerSession.createQueue("testQueue");
    }

    @After
    public void tearDown() throws Exception {
        producerSession.close();
        consumerSession.close();
        producerConnection.close();
        consumerConnection.close();
        producerBroker.stop();
        consumerBroker.stop();
    }

    private void sendMessage(String messageText) throws JMSException {
        MessageProducer producer = producerSession.createProducer(queue);
        TextMessage message = producerSession.createTextMessage(messageText);
        producer.send(message);
        producer.close();
    }

    private String receiveMessage() throws JMSException {
        MessageConsumer consumer = consumerSession.createConsumer(queue);
        consumerConnection.start();
        Message message = consumer.receive(1000);
        consumer.close();
        return message instanceof TextMessage ? ((TextMessage) message).getText() : null;
    }

    @Test
    public void testMultipleProducerBrokerRestarts() throws Exception {
        sendMessage("Message 1");
        producerBroker.stop();
        producerBroker.start();
        sendMessage("Message 2");
        String receivedMessage1 = receiveMessage();
        String receivedMessage2 = receiveMessage();
        assertEquals("Message 1", receivedMessage1);
        assertEquals("Message 2", receivedMessage2);
    }

    @Test
    public void testProducerBrokerRestartWithoutConsumer() throws Exception {
        producerBroker.stop();
        producerBroker.start();
        sendMessage("Message 3");
        consumerConnection.start();
        String receivedMessage = receiveMessage();
        assertEquals("Message 3", receivedMessage);
    }

    @Test
    public void testConsumerBrokerStartedFirst() throws Exception {
        consumerBroker.start();
        sendMessage("Message 4");
        String receivedMessage = receiveMessage();
        assertEquals("Message 4", receivedMessage);
    }

    @Test
    public void testProducerBrokerStartedFirst() throws Exception {
        producerBroker.start();
        sendMessage("Message 5");
        consumerBroker.start();
        String receivedMessage = receiveMessage();
        assertEquals("Message 5", receivedMessage);
    }

    @Test
    public void testDeliveryAfterProducerBrokerRestart() throws Exception {
        sendMessage("Message 6");
        producerBroker.stop();
        producerBroker.start();
        sendMessage("Message 7");
        String receivedMessage1 = receiveMessage();
        String receivedMessage2 = receiveMessage();
        assertEquals("Message 6", receivedMessage1);
        assertEquals("Message 7", receivedMessage2);
    }

    @Test
    public void testDeliveryAfterConsumerBrokerRestart() throws Exception {
        sendMessage("Message 8");
        consumerBroker.stop();
        consumerBroker.start();
        String receivedMessage = receiveMessage();
        assertEquals("Message 8", receivedMessage);
    }

    @Test
    public void testWithDelaysInStartingBrokers() throws Exception {
        Thread.sleep(2000);
        producerBroker.start();
        Thread.sleep(2000);
        consumerBroker.start();
        sendMessage("Message 9");
        String receivedMessage = receiveMessage();
        assertEquals("Message 9", receivedMessage);
    }
}

