public class JSSESocketFactory extends ServerSocketFactory {
    private static final Logger logger = Logger.getLogger(JSSESocketFactory.class.getName());
    private SSLContext sslContext;
    private String[] supportedProtocols;
    private String[] supportedCipherSuites;
    private boolean clientAuth;

    public JSSESocketFactory(String keyStorePath, String keyStorePassword, String trustStorePath, String trustStorePassword,
                             String[] supportedProtocols, String[] supportedCipherSuites, boolean clientAuth) {
        try {
            this.supportedProtocols = supportedProtocols;
            this.supportedCipherSuites = supportedCipherSuites;
            this.clientAuth = clientAuth;

            KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
            TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());

            KeyStore keyStore = KeyStore.getInstance("JKS");
            keyStore.load(getClass().getResourceAsStream(keyStorePath), keyStorePassword.toCharArray());
            kmf.init(keyStore, keyStorePassword.toCharArray());

            KeyStore trustStore = KeyStore.getInstance("JKS");
            trustStore.load(getClass().getResourceAsStream(trustStorePath), trustStorePassword.toCharArray());
            tmf.init(trustStore);

            sslContext = SSLContext.getInstance("TLS");
            sslContext.init(kmf.getKeyManagers(), tmf.getTrustManagers(), null);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error initializing JSSESocketFactory", e);
        }
    }

    @Override
    public SSLServerSocket createServerSocket(int port) throws IOException {
        SSLServerSocket serverSocket = (SSLServerSocket) sslContext.getServerSocketFactory().createServerSocket(port);
        serverSocket.setEnabledProtocols(supportedProtocols);
        serverSocket.setEnabledCipherSuites(supportedCipherSuites);
        serverSocket.setNeedClientAuth(clientAuth);
        return serverSocket;
    }

    @Override
    public SSLServerSocket createServerSocket(int port, int backlog) throws IOException {
        SSLServerSocket serverSocket = (SSLServerSocket) sslContext.getServerSocketFactory().createServerSocket(port, backlog);
        serverSocket.setEnabledProtocols(supportedProtocols);
        serverSocket.setEnabledCipherSuites(supportedCipherSuites);
        serverSocket.setNeedClientAuth(clientAuth);
        return serverSocket;
    }

    @Override
    public SSLServerSocket createServerSocket(int port, int backlog, java.net.InetAddress ifAddress) throws IOException {
        SSLServerSocket serverSocket = (SSLServerSocket) sslContext.getServerSocketFactory().createServerSocket(port, backlog, ifAddress);
        serverSocket.setEnabledProtocols(supportedProtocols);
        serverSocket.setEnabledCipherSuites(supportedCipherSuites);
        serverSocket.setNeedClientAuth(clientAuth);
        return serverSocket;
    }
}

