public class Float4Datum extends NumericDatum {
    private float value;

    public Float4Datum(float value) {
        this.value = value;
    }

    public Float4Datum(byte[] byteArray) {
        if (byteArray.length != 4) {
            throw new IllegalArgumentException("Byte array must be 4 bytes long.");
        }
        this.value = Float.intBitsToFloat(((byteArray[0] & 0xFF) << 24) |
                                            ((byteArray[1] & 0xFF) << 16) |
                                            ((byteArray[2] & 0xFF) << 8) |
                                            (byteArray[3] & 0xFF));
    }

    public boolean toBoolean() {
        return value != 0.0f;
    }

    public char toChar() {
        return (char) value;
    }

    public short toShort() {
        return (short) value;
    }

    public int toInt() {
        return (int) value;
    }

    public long toLong() {
        return (long) value;
    }

    public byte toByte() {
        return (byte) value;
    }

    public byte[] toByteArray() {
        return new byte[]{
            (byte) (Float.floatToIntBits(value) >> 24),
            (byte) (Float.floatToIntBits(value) >> 16),
            (byte) (Float.floatToIntBits(value) >> 8),
            (byte) (Float.floatToIntBits(value))
        };
    }

    public float toFloat() {
        return value;
    }

    public double toDouble() {
        return (double) value;
    }

    public String toString() {
        return Float.toString(value);
    }

    public Float4Datum add(NumericDatum other) {
        return new Float4Datum(this.value + other.toFloat());
    }

    public Float4Datum subtract(NumericDatum other) {
        return new Float4Datum(this.value - other.toFloat());
    }

    public Float4Datum multiply(NumericDatum other) {
        return new Float4Datum(this.value * other.toFloat());
    }

    public Float4Datum divide(NumericDatum other) {
        if (other.toFloat() == 0.0f) {
            throw new ArithmeticException("Division by zero.");
        }
        return new Float4Datum(this.value / other.toFloat());
    }

    public Float4Datum modulus(NumericDatum other) {
        return new Float4Datum(this.value % other.toFloat());
    }

    public int compareTo(NumericDatum other) {
        return Float.compare(this.value, other.toFloat());
    }

    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Float4Datum)) return false;
        Float4Datum other = (Float4Datum) obj;
        return Float.compare(this.value, other.value) == 0;
    }

    public int hashCode() {
        return Float.floatToIntBits(value);
    }

    public Float4Datum invert() {
        return new Float4Datum(-this.value);
    }
}

public class PoReader extends PoAbstract {
    private static final Logger logger = Logger.getLogger(PoReader.class.getName());
    private final TranslationsResolver translationsResolver;
    private final LocaleProvider localeProvider;
    private final Map<Locale, Map<String, String>> translationsCache = new HashMap<>();

    public PoReader(TranslationsResolver translationsResolver, LocaleProvider localeProvider) {
        this.translationsResolver = translationsResolver;
        this.localeProvider = localeProvider;
        initializeTranslations();
    }

    private void initializeTranslations() {
        Locale[] locales = localeProvider.getSupportedLocales();
        for (Locale locale : locales) {
            try {
                Map<String, String> translations = loadTranslationsForLocale(locale);
                translationsCache.put(locale, translations);
                logger.info("Loaded translations for locale: " + locale);
            } catch (IOException e) {
                logger.log(Level.WARNING, "Failed to load translations for locale: " + locale, e);
            }
        }
    }

    private Map<String, String> loadTranslationsForLocale(Locale locale) throws IOException {
        Map<String, String> translations = new HashMap<>();
        String filePath = translationsResolver.resolve(locale);
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                // Assuming the line format is "msgid: msgstr"
                String[] parts = line.split(": ", 2);
                if (parts.length == 2) {
                    translations.put(parts[0].trim(), parts[1].trim());
                }
            }
        }
        return translations;
    }

    public String translate(String key) {
        Locale currentLocale = localeProvider.getCurrentLocale();
        return translationsCache.getOrDefault(currentLocale, new HashMap<>())
                .getOrDefault(key, fallbackTranslation(key));
    }

    public String translate(String key, int count) {
        String pluralKey = key + (count == 1 ? "" : "_plural");
        return translate(pluralKey);
    }

    private String fallbackTranslation(String key) {
        Locale fallbackLocale = localeProvider.getFallbackLocale();
        return translationsCache.getOrDefault(fallbackLocale, new HashMap<>())
                .getOrDefault(key, key);
    }

    public void clearCache() {
        translationsCache.clear();
        logger.info("Cleared translation cache.");
    }
}

