public class TransactionInterceptor extends DelegateProcessor {

    private final TransactionTemplate transactionTemplate;

    public TransactionInterceptor(Processor processor, TransactionTemplate transactionTemplate) {
        super(processor);
        this.transactionTemplate = transactionTemplate;
    }

    @Override
    public void process(Exchange exchange) throws Exception {
        exchange.setProperty("transactionActive", true);
        try {
            transactionTemplate.execute(new TransactionCallback<Void>() {
                @Override
                public Void doInTransaction(TransactionStatus status) {
                    try {
                        getProcessor().process(exchange);
                    } catch (Exception e) {
                        handleException(e, status);
                    }
                    return null;
                }
            });
        } finally {
            exchange.removeProperty("transactionActive");
        }
    }

    private void handleException(Exception e, TransactionStatus status) {
        // Code smell: Catching generic Exception
        if (shouldRollback(e)) {
            status.setRollbackOnly();
        }
        // Additional handling logic can be added here
    }

    private boolean shouldRollback(Exception e) {
        // Code smell: Logic for rollback determination could be improved
        return true; // Simplified for demonstration
    }
}

public class NodeImpl implements Node {
