        }
        this.nodeType = nodeType;
        isModified = true;
    }

    public String getNodeType() {
        return nodeType;
    }

    public void addMixin(String mixin) {
        if (isLocked) {
            throw new IllegalStateException("Node is locked");
        }
        mixins.add(mixin);
        isModified = true;
    }

    public List<String> getMixins() {
        return mixins;
    }

    public void transitionLifecycle(String transition) {
        if (isLocked) {
            throw new IllegalStateException("Node is locked");
        }
        // Handle lifecycle transition logic here
        isModified = true;
    }
