public class DateTag extends SimpleTagSupport {
    private static final Logger logger = Logger.getLogger(DateTag.class.getName());
    private String dateValue;
    private String pattern;
    private boolean niceFormat;

    public void setDateValue(String dateValue) {
        this.dateValue = dateValue;
    }

    public void setPattern(String pattern) {
        this.pattern = pattern;
    }

    public void setNiceFormat(boolean niceFormat) {
        this.niceFormat = niceFormat;
    }

    @Override
    public void doTag() throws JspException, IOException {
        Date date = parseDate(dateValue);
        if (date == null) {
            return; // Early return to avoid further processing
        }

        String formattedDate;
        if (niceFormat) {
            formattedDate = formatNice(date);
        } else {
            formattedDate = formatPattern(date);
        }

        getJspContext().getOut().write(formattedDate);
    }

    private Date parseDate(String dateValue) {
        try {
            return new SimpleDateFormat("yyyy-MM-dd").parse(dateValue);
        } catch (ParseException e) {
            logger.log(Level.SEVERE, "Date parsing error: " + e.getMessage(), e);
            return null; // Returning null to indicate error
        }
    }

    private String formatNice(Date date) {
        // Placeholder for nice formatting logic
        return "Nice formatted date: " + date.toString();
    }

    private String formatPattern(Date date) {
        DateFormat dateFormat = new SimpleDateFormat(pattern, Locale.getDefault());
        return dateFormat.format(date);
    }
}

