public abstract class BaseDataStreamMarshaller implements DataStreamMarshaller {

    protected OpenWireFormat wireFormat;
    protected BooleanStream booleanStream;

    public BaseDataStreamMarshaller(OpenWireFormat wireFormat) {
        this.wireFormat = wireFormat;
        this.booleanStream = new BooleanStream();
    }

    public void tightMarshal(Object object, DataOutput dataOut) throws IOException {
        // Implementation for tight marshaling
        if (object instanceof String) {
            dataOut.writeUTF((String) object);
        } else if (object instanceof byte[]) {
            byte[] byteArray = (byte[]) object;
            dataOut.writeInt(byteArray.length);
            dataOut.write(byteArray);
        } else {
            // Handle other types
        }
    }

    public Object tightUnmarshal(DataInput dataIn) throws IOException {
        // Implementation for tight unmarshaling
        String str = dataIn.readUTF();
        return str; // Simplified for example
    }

    public void looseMarshal(Object object, DataOutput dataOut) throws IOException {
        // Implementation for loose marshaling
        if (object instanceof String) {
            dataOut.writeUTF((String) object);
        } else if (object instanceof byte[]) {
            byte[] byteArray = (byte[]) object;
            dataOut.writeInt(byteArray.length);
            dataOut.write(byteArray);
            dataOut.write(byteArray);
        } else {
            // Handle other types
        }
    }

    public Object looseUnmarshal(DataInput dataIn) throws IOException {
        // Implementation for loose unmarshaling
        String str = dataIn.readUTF();
        return str; // Simplified for example
    }

    protected void marshalException(Throwable exception, DataOutput dataOut) throws IOException {
        dataOut.writeUTF(exception.getClass().getName());
        dataOut.writeUTF(exception.getMessage());
        StackTraceElement[] stackTrace = exception.getStackTrace();
        dataOut.writeInt(stackTrace.length);
        for (StackTraceElement element : stackTrace) {
            dataOut.writeUTF(element.toString());
        }
    }

    protected Throwable unmarshalException(DataInput dataIn) throws IOException {
        String className = dataIn.readUTF();
        String message = dataIn.readUTF();
        int stackTraceLength = dataIn.readInt();
        StackTraceElement[] stackTrace = new StackTraceElement[stackTraceLength];
        for (int i = 0; i < stackTraceLength; i++) {
            stackTrace[i] = new StackTraceElement(dataIn.readUTF());
        }
        Throwable exception = new Exception(message);
        exception.setStackTrace(stackTrace);
        return exception;
    }
}

public class JavadocOutputStream extends LogOutputStream {
    private Queue<String> queuedLines = new LinkedList<>();

    @Override
    protected void processLine(String line) {
        if (line.startsWith("Generating ")) {
            queuedLines.add(line);
        } else if (line.startsWith("Building ")) {
            while (!queuedLines.isEmpty()) {
                logVerbose(queuedLines.poll());
            }
        } else {
            while (!queuedLines.isEmpty()) {
                logInfo(queuedLines.poll());
            }
            logInfo(line);
        }
    }

    @Override
    public void flush() {
        while (!queuedLines.isEmpty()) {
            logInfo(queuedLines.poll());
        }
        super.flush();
    }

    private void logInfo(String message) {
