public class ExecTask {
    private String executable;
    private String workingDirectory;
    private Map<String, String> environmentVariables;
    private long timeout;
    private boolean async;
    private boolean logOutput;
    private boolean logError;
    private StringBuilder output;
    private StringBuilder error;

    public ExecTask(String executable) {
        this.executable = executable;
        this.workingDirectory = System.getProperty("user.dir");
        this.environmentVariables = new HashMap<>();
        this.timeout = 0;
        this.async = false;
        this.logOutput = false;
        this.logError = false;
        this.output = new StringBuilder();
        this.error = new StringBuilder();
    }

    public ExecTask setWorkingDirectory(String workingDirectory) {
        this.workingDirectory = workingDirectory;
        return this;
    }

    public ExecTask setEnvironmentVariable(String key, String value) {
        this.environmentVariables.put(key, value);
        return this;
    }

    public ExecTask setTimeout(long timeout) {
        this.timeout = timeout;
        return this;
    }

    public ExecTask setAsync(boolean async) {
        this.async = async;
        return this;
    }

    public ExecTask setLogOutput(boolean logOutput) {
        this.logOutput = logOutput;
        return this;
    }

    public ExecTask setLogError(boolean logError) {
        this.logError = logError;
        return this;
    }

    public Map<String, String> execute() throws IOException, InterruptedException, TimeoutException {
        validateOS();
        ProcessBuilder processBuilder = new ProcessBuilder(executable);
        processBuilder.directory(new File(workingDirectory));
        Map<String, String> env = processBuilder.environment();
        for (Map.Entry<String, String> entry : environmentVariables.entrySet()) {
            env.put(entry.getKey(), entry.getValue());
        }

        Process process = processBuilder.start();
        Future<?> future = null;

        if (async) {
            ExecutorService executor = Executors.newSingleThreadExecutor();
            future = executor.submit(() -> {
                captureOutput(process);
            });
            executor.shutdown();
        } else {
            captureOutput(process);
        }

        if (timeout > 0) {
            if (future != null) {
                try {
                    future.get(timeout, TimeUnit.MILLISECONDS);
                } catch (TimeoutException e) {
                    process.destroy();
                    throw new TimeoutException("Process timed out");
                } catch (ExecutionException e) {
                    throw new IOException("Execution failed", e);
                }
            } else {
                process.waitFor();
            }
        } else {
            process.waitFor();
        }

        Map<String, String> results = new HashMap<>();
        results.put("output", output.toString());
        results.put("error", error.toString());
        return results;
    }

    private void captureOutput(Process process) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
             BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append(System.lineSeparator());
                if (logOutput) {
                    System.out.println(line);
                }
            }
            while ((line = errorReader.readLine()) != null) {
                error.append(line).append(System.lineSeparator());
                if (logError) {
                    System.err.println(line);
                }
            }
        }
    }

    private void validateOS() {
        String os = System.getProperty("os.name").toLowerCase();
        if (!os.contains("win") && !os.contains("nix") && !os.contains("nux") && !os.contains("mac")) {
            throw new UnsupportedOperationException("Unsupported operating system: " + os);
        }
    }
}

