class TestGroupByContainerIds {

    @Test
    void testEmptyTaskGrouping() {
        assertThrows(IllegalArgumentException.class, () -> groupTasks(new ArrayList<>(), new ArrayList<>()));
    }

    @Test
    void testImmutableGroupingResults() {
        Map<String, List<String>> result = groupTasks(Arrays.asList("task1", "task2"), Arrays.asList("container1"));
        assertThrows(UnsupportedOperationException.class, () -> result.put("container2", new ArrayList<>()));
    }

    @Test
    void testSuccessfulTaskGrouping() {
        Map<String, List<String>> result = groupTasks(Arrays.asList("task1", "task2", "task3"), Arrays.asList("container1", "container2"));
        assertEquals(2, result.size());
        assertEquals(2, result.get("container1").size());
        assertEquals(1, result.get("container2").size());
    }

    @Test
    void testHandlingNullContainerIds() {
        Map<String, List<String>> result = groupTasks(Arrays.asList("task1", "task2"), Arrays.asList((String) null));
        assertEquals(1, result.size());
        assertEquals(2, result.get(null).size());
    }

    @Test
    void testHandlingEmptyContainerIds() {
        assertThrows(IllegalArgumentException.class, () -> groupTasks(Arrays.asList("task1"), new ArrayList<>()));
    }

    @Test
    void testGroupingWithSpecificContainerIds() {
        Map<String, List<String>> result = groupTasks(Arrays.asList("task1", "task2", "task3"), Arrays.asList("container1"));
        assertEquals(1, result.size());
        assertEquals(3, result.get("container1").size());
    }

    @Test
    void testGroupingWithManyTasks() {
        List<String> tasks = new ArrayList<>();
        for (int i = 0; i < 100; i++) {
            tasks.add("task" + i);
        }
        Map<String, List<String>> result = groupTasks(tasks, Arrays.asList("container1", "container2", "container3"));
        assertEquals(3, result.size());
        assertTrue(result.get("container1").size() + result.get("container2").size() + result.get("container3").size() == 100);
    }

    @Test
    void testFewerTasksThanContainers() {
        Map<String, List<String>> result = groupTasks(Arrays.asList("task1"), Arrays.asList("container1", "container2"));
        assertEquals(2, result.size());
        assertEquals(1, result.get("container1").size());
        assertEquals(0, result.get("container2").size());
    }

    @Test
    void testTaskLocalityConsiderations() {
        Map<String, List<String>> result = groupTasksWithLocality(Arrays.asList("task1", "task2"), Arrays.asList("container1", "container2"), Arrays.asList("locality1", "locality2"));
        assertEquals(2, result.size());
        assertTrue(result.get("container1").contains("task1"));
        assertTrue(result.get("container2").contains("task2"));
    }

    @Test
    void testSingleContainerModelGeneration() {
        Map<String, List<String>> result = groupTasks(Arrays.asList("task1", "task2"), Arrays.asList("container1"));
        assertEquals(1, result.size());
        assertEquals(2, result.get("container1").size());
    }

    @Test
    void testEmptyTaskLocality() {
        Map<String, List<String>> result = groupTasksWithLocality(Arrays.asList("task1", "task2"), Arrays.asList("container1"), Collections.emptyList());
        assertEquals(1, result.size());
        assertEquals(2, result.get("container1").size());
    }

    @Test
    void testProcessorLocalityChecks() {
        assertThrows(IllegalArgumentException.class, () -> groupTasksWithLocality(Arrays.asList("task1"), Arrays.asList("container1"), null));
    }

    @Test
    void testTaskDistributionConsistency() {
        List<String> tasks = Arrays.asList("task1", "task2");
        List<String> containers = Arrays.asList("container1", "container2");
        Map<String, List<String>> firstResult = groupTasks(tasks, containers);
        Map<String, List<String>> secondResult = groupTasks(tasks, containers);
        assertEquals(firstResult, secondResult);
    }

    @Test
    void testMinimizingTaskShuffle() {
        List<String> tasks = Arrays.asList("task1", "task2");
        List<String> containers = Arrays.asList("container1", "container2");
        Map<String, List<String>> firstResult = groupTasks(tasks, containers);
        // Simulate a change in available processors
        Map<String, List<String>> secondResult = groupTasks(tasks, containers);
        assertEquals(firstResult, secondResult);
    }

    @Test
    void testMoreTasksThanProcessors() {
        List<String> tasks = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            tasks.add("task" + i);
        }
        Map<String, List<String>> result = groupTasks(tasks, Arrays.asList("container1", "container2"));
        assertTrue(result.get("container1").size() + result.get("container2").size() == 10);
    }

    private Map<String, List<String>> groupTasks(List<String> tasks, List<String> containerIds) {
        if (tasks == null || tasks.isEmpty()) {
            throw new IllegalArgumentException("Tasks cannot be empty");
        }
        if (containerIds == null || containerIds.isEmpty()) {
            throw new IllegalArgumentException("Container IDs cannot be empty");
        }

        Map<String, List<String>> groupedTasks = new HashMap<>();
        for (String containerId : containerIds) {
            groupedTasks.put(containerId, new ArrayList<>());
        }

        for (int i = 0; i < tasks.size(); i++) {
            String containerId = containerIds.get(i % containerIds.size());
            groupedTasks.get(containerId).add(tasks.get(i));
        }

        return Collections.unmodifiableMap(groupedTasks);
    }

    private Map<String, List<String>> groupTasksWithLocality(List<String> tasks, List<String> containerIds, List<String> locality) {
        if (locality == null) {
            throw new IllegalArgumentException("Locality cannot be null");
        }
        return groupTasks(tasks, containerIds);
    }
}

