public class JavaCharStream {
    private Reader reader;
    private char[] buffer;
    private int bufferSize;
    private int bufferIndex;
    private int line;
    private int column;

    public JavaCharStream(Reader reader, int bufferSize) {
        this.reader = reader;
        this.bufferSize = bufferSize;
        this.buffer = new char[bufferSize];
        this.bufferIndex = 0;
        this.line = 1;
        this.column = 0;
        fillBuffer();
    }

    private void fillBuffer() {
        try {
            int charsRead = reader.read(buffer);
            if (charsRead == -1) {
                buffer[0] = '\0'; // End of stream marker
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public char readChar() {
        if (bufferIndex >= buffer.length || buffer[bufferIndex] == '\0') {
            return '\0'; // End of stream
        }
        char ch = buffer[bufferIndex++];
        updatePosition(ch);
        return ch;
    }

    private void updatePosition(char ch) {
        if (ch == '\n') {
            line++;
            column = 0;
        } else {
            column++;
        }
    }

    public void backup(int amount) {
        bufferIndex -= amount;
        if (bufferIndex < 0) {
            bufferIndex = 0;
        }
    }

    public int getLine() {
        return line;
    }

    public int getColumn() {
        return column;
    }

    public void reinitialize(Reader newReader, int newBufferSize) {
        this.reader = newReader;
        this.bufferSize = newBufferSize;
        this.buffer = new char[newBufferSize];
        this.bufferIndex = 0;
        this.line = 1;
        this.column = 0;
        fillBuffer();
    }
}

