        }
        configurationResources.add(primer);
    }

    public void lock() {
        isLocked = true;
    }

    public void parseCommandLineOptions(String[] args) {
        if (isLocked) {
            throw new IllegalStateException("Configuration is locked and cannot be modified.");
        }
        // Parse command line options and add to configurationResources
        for (String arg : args) {
            configurationResources.add(arg);
        }
    }

