public class JdbcIOTest {
    private static final String DB_URL = "jdbc:derby:memory:testdb;create=true";
    private static final String USERNAME = "user";
    private static final String PASSWORD = "password";
    private Connection connection;

    @Before
    public void setUp() throws Exception {
        connection = DriverManager.getConnection(DB_URL, USERNAME, PASSWORD);
        try (Statement stmt = connection.createStatement()) {
            stmt.execute("CREATE TABLE test_table (id INT PRIMARY KEY, value VARCHAR(255))");
        }
    }

    @After
    public void tearDown() throws Exception {
        try (Statement stmt = connection.createStatement()) {
            stmt.execute("DROP TABLE test_table");
        }
        connection.close();
    }

    @Test
    public void testWriteAndRead() throws Exception {
        Pipeline pipeline = Pipeline.create();

        PCollection<String> input = pipeline.apply(Create.of("1,value1", "2,value2"));
        input.apply(JdbcIO.<String>write()
                .withDataSourceConfiguration(JdbcIO.DataSourceConfiguration.create("org.apache.derby.jdbc.EmbeddedDriver", DB_URL)
                        .withUsername(USERNAME)
                        .withPassword(PASSWORD))
                .withStatement("INSERT INTO test_table (id, value) VALUES (?, ?)")
                .withPreparedStatementSetter((element, statement) -> {
                    String[] parts = element.split(",");
                    statement.setInt(1, Integer.parseInt(parts[0]));
                    statement.setString(2, parts[1]);
                }));

        pipeline.run().waitUntilFinish();

        PCollection<Long> count = pipeline.apply(JdbcIO.<String>read()
                .withDataSourceConfiguration(JdbcIO.DataSourceConfiguration.create("org.apache.derby.jdbc.EmbeddedDriver", DB_URL)
                        .withUsername(USERNAME)
                        .withPassword(PASSWORD))
                .withQuery("SELECT COUNT(*) FROM test_table")
                .withRowMapper((resultSet, context) -> resultSet.getLong(1))
                .withOutputType(TypeDescriptor.of(Long.class)));

        assertEquals(Long.valueOf(2), count.apply(Count.globally()).get(0));
    }

