        assertTrue(delegatingSubject.isSessionActive());
        delegatingSubject.stopSession();
        assertFalse(delegatingSubject.isSessionActive());
        delegatingSubject.startSession();
        assertTrue(delegatingSubject.isSessionActive());
    }

    @Test
