    public void testSetValidWorkFactor() {
        throttlingExecutor.setWorkFactor(50);
        assertEquals(50, throttlingExecutor.getWorkFactor());
    }

    @Test
    public void testSetInvalidWorkFactor() {
        assertThrows(IllegalArgumentException.class, () -> {
            throttlingExecutor.setWorkFactor(-1);
        });
        assertThrows(IllegalArgumentException.class, () -> {
            throttlingExecutor.setWorkFactor(101);
        });
    }

    @Test
    public void testExecutionAtDifferentWorkRates() {
        throttlingExecutor.setWorkFactor(100);
        assertTrue(throttlingExecutor.execute());

        throttlingExecutor.setWorkFactor(50);
        assertTrue(throttlingExecutor.execute());

        throttlingExecutor.setWorkFactor(0);
        assertFalse(throttlingExecutor.execute());
    }

    @Test
    public void testSleepTimeOvershoot() {
        throttlingExecutor.setWorkFactor(50);
        long sleepTime = throttlingExecutor.calculateSleepTime(1000);
        assertTrue(sleepTime <= 1000);
    }

    @Test
    public void testSleepTimeUndershoot() {
        throttlingExecutor.setWorkFactor(100);
        long sleepTime = throttlingExecutor.calculateSleepTime(1000);
        assertEquals(0, sleepTime);
    }

