        assertThrows(ArithmeticException.class, () -> {
            throttlingExecutor.addPendingSleepNanos(1);
        });
    }

    @Test
    public void testPendingNanosNegativeValue() {
        throttlingExecutor.setPendingSleepNanos(100);
        throttlingExecutor.subtractPendingSleepNanos(150);
        assertEquals(0, throttlingExecutor.getPendingSleepNanos());
    }
