public class BigFraction implements Number, FieldElement<BigFraction>, Comparable<BigFraction>, Serializable {
    private final BigInteger numerator;
    private final BigInteger denominator;

    public BigFraction(BigInteger numerator, BigInteger denominator) {
        if (denominator.equals(BigInteger.ZERO)) {
            throw new ArithmeticException("Denominator cannot be zero");
        }
        if (denominator.signum() < 0) {
            this.numerator = numerator.negate();
            this.denominator = denominator.negate();
        } else {
            this.numerator = numerator;
            this.denominator = denominator;
        }
        reduce();
    }

    public BigFraction(int numerator) {
        this(BigInteger.valueOf(numerator), BigInteger.ONE);
    }

    public BigFraction(long numerator) {
        this(BigInteger.valueOf(numerator), BigInteger.ONE);
    }

    public BigFraction(double value) {
        // Simplified conversion, may introduce precision issues
        String str = Double.toString(value);
        String[] parts = str.split("\\.");
        BigInteger num = new BigInteger(parts[0]);
        if (parts.length > 1) {
            num = num.multiply(BigInteger.TEN.pow(parts[1].length())).add(new BigInteger(parts[1]));
        }
        BigInteger denom = BigInteger.TEN.pow(parts.length > 1 ? parts[1].length() : 0);
        this.numerator = num;
        this.denominator = denom;
        reduce();
    }

    public BigFraction(BigFraction fraction) {
        this(fraction.numerator, fraction.denominator);
    }

    private void reduce() {
        BigInteger gcd = numerator.gcd(denominator);
        numerator = numerator.divide(gcd);
        denominator = denominator.divide(gcd);
    }

    public BigFraction add(BigFraction other) {
        BigInteger newNumerator = this.numerator.multiply(other.denominator).add(other.numerator.multiply(this.denominator));
        BigInteger newDenominator = this.denominator.multiply(other.denominator);
        return new BigFraction(newNumerator, newDenominator);
    }

    public BigFraction subtract(BigFraction other) {
        BigInteger newNumerator = this.numerator.multiply(other.denominator).subtract(other.numerator.multiply(this.denominator));
        BigInteger newDenominator = this.denominator.multiply(other.denominator);
        return new BigFraction(newNumerator, newDenominator);
    }

    public BigFraction multiply(BigFraction other) {
        return new BigFraction(this.numerator.multiply(other.numerator), this.denominator.multiply(other.denominator));
    }

    public BigFraction divide(BigFraction other) {
        if (other.numerator.equals(BigInteger.ZERO)) {
            throw new ArithmeticException("Cannot divide by zero");
        }
        return new BigFraction(this.numerator.multiply(other.denominator), this.denominator.multiply(other.numerator));
    }

    public BigFraction negate() {
        return new BigFraction(this.numerator.negate(), this.denominator);
    }

    public BigFraction abs() {
        return new BigFraction(this.numerator.abs(), this.denominator.abs());
    }

    public BigFraction reciprocal() {
        if (this.numerator.equals(BigInteger.ZERO)) {
            throw new ArithmeticException("Cannot take reciprocal of zero");
        }
        return new BigFraction(this.denominator, this.numerator);
    }

    public double doubleValue() {
        return numerator.doubleValue() / denominator.doubleValue();
    }

    @Override
    public int compareTo(BigFraction other) {
        BigInteger left = this.numerator.multiply(other.denominator);
        BigInteger right = other.numerator.multiply(this.denominator);
        return left.compareTo(right);
    }

    @Override
    public String toString() {
        return numerator + "/" + denominator;
    }

    // Constants for commonly used fractions
    public static final BigFraction ZERO = new BigFraction(0);
    public static final BigFraction ONE = new BigFraction(1);
    public static final BigFraction HALF = new BigFraction(1, 2);
}

