        this.parent = parent;
        this.parsingRules = parsingRules;
        this.spanEndSubstitutions = spanEndSubstitutions;
    }

    public static LineContext intern(LineContext context) {
        String key = context.toString();
        if (!instances.containsKey(key)) {
            instances.put(key, context);
        }
        return instances.get(key);
    }

    public LineContext clone() {
        return new LineContext(this.parent, this.parsingRules.clone(), this.spanEndSubstitutions.clone());
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof LineContext)) return false;
        LineContext other = (LineContext) obj;
        return Objects.equals(parent, other.parent) &&
               Arrays.equals(parsingRules, other.parsingRules) &&
               Arrays.equals(spanEndSubstitutions, other.spanEndSubstitutions);
    }

    @Override
    public int hashCode() {
        int result = Objects.hash(parent);
        result = 31 * result + Arrays.hashCode(parsingRules);
        result = 31 * result + Arrays.hashCode(spanEndSubstitutions);
        return result;
    }

    private boolean compareCharArrays(char[] a, char[] b) {
        if (a.length != b.length) return false;
        for (int i = 0; i < a.length; i++) {
            if (a[i] != b[i]) return false;
        }
        return true;
    }
}

