public class SparseGradient implements RealFieldElement<SparseGradient>, Serializable {
    private static final long serialVersionUID = 1L;
    private final double value;
    private final Map<String, Double> derivatives;

    public SparseGradient(double value) {
        this.value = value;
        this.derivatives = new HashMap<>();
    }

    public SparseGradient(double value, Map<String, Double> derivatives) {
        this.value = value;
        this.derivatives = new HashMap<>(derivatives);
    }

    public static SparseGradient constant(double value) {
        return new SparseGradient(value);
    }

    public static SparseGradient variable(double value, String variable) {
        SparseGradient gradient = new SparseGradient(value);
        gradient.derivatives.put(variable, 1.0);
        return gradient;
    }

    public SparseGradient add(SparseGradient other) {
        SparseGradient result = new SparseGradient(this.value + other.value);
        for (Map.Entry<String, Double> entry : this.derivatives.entrySet()) {
            result.derivatives.put(entry.getKey(), entry.getValue());
        }
        for (Map.Entry<String, Double> entry : other.derivatives.entrySet()) {
            result.derivatives.merge(entry.getKey(), entry.getValue(), Double::sum);
        }
        return result;
    }

    public SparseGradient subtract(SparseGradient other) {
        SparseGradient result = new SparseGradient(this.value - other.value);
        for (Map.Entry<String, Double> entry : this.derivatives.entrySet()) {
            result.derivatives.put(entry.getKey(), entry.getValue());
        }
        for (Map.Entry<String, Double> entry : other.derivatives.entrySet()) {
            result.derivatives.merge(entry.getKey(), -entry.getValue(), Double::sum);
        }
        return result;
    }

    public SparseGradient multiply(SparseGradient other) {
        SparseGradient result = new SparseGradient(this.value * other.value);
        for (Map.Entry<String, Double> entry : this.derivatives.entrySet()) {
            result.derivatives.put(entry.getKey(), entry.getValue() * other.value);
        }
        for (Map.Entry<String, Double> entry : other.derivatives.entrySet()) {
            result.derivatives.merge(entry.getKey(), entry.getValue() * this.value, Double::sum);
        }
        return result;
    }

    public SparseGradient divide(SparseGradient other) {
        SparseGradient result = new SparseGradient(this.value / other.value);
        for (Map.Entry<String, Double> entry : this.derivatives.entrySet()) {
            result.derivatives.put(entry.getKey(), entry.getValue() / other.value);
        }
        for (Map.Entry<String, Double> entry : other.derivatives.entrySet()) {
            result.derivatives.merge(entry.getKey(), -entry.getValue() * this.value / (other.value * other.value), Double::sum);
        }
        return result;
    }

    public SparseGradient exp() {
        SparseGradient result = new SparseGradient(Math.exp(this.value));
        for (Map.Entry<String, Double> entry : this.derivatives.entrySet()) {
            result.derivatives.put(entry.getKey(), entry.getValue() * result.value);
        }
        return result;
    }

    public SparseGradient log() {
        SparseGradient result = new SparseGradient(Math.log(this.value));
        for (Map.Entry<String, Double> entry : this.derivatives.entrySet()) {
            result.derivatives.put(entry.getKey(), entry.getValue() / this.value);
        }
        return result;
    }

    public SparseGradient sin() {
        SparseGradient result = new SparseGradient(Math.sin(this.value));
        for (Map.Entry<String, Double> entry : this.derivatives.entrySet()) {
            result.derivatives.put(entry.getKey(), entry.getValue() * Math.cos(this.value));
        }
        return result;
    }

    public SparseGradient cos() {
        SparseGradient result = new SparseGradient(Math.cos(this.value));
        for (Map.Entry<String, Double> entry : this.derivatives.entrySet()) {
            result.derivatives.put(entry.getKey(), -entry.getValue() * Math.sin(this.value));
        }
        return result;
    }

    public Map<String, Double> getDerivatives() {
        return new HashMap<>(derivatives);
    }

    @Override
    public int compareTo(SparseGradient o) {
        return Double.compare(this.value, o.value);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof SparseGradient)) return false;
        SparseGradient other = (SparseGradient) obj;
        return Double.compare(this.value, other.value) == 0 && this.derivatives.equals(other.derivatives);
    }

    @Override
    public int hashCode() {
        int result = Double.hashCode(value);
        result = 31 * result + derivatives.hashCode();
        return result;
    }
}

