        row.put("column1", 1L);
        row.put("column2", 1L);
        assertFalse(notEquals.evaluate(row));

        row.put("column2", 2L);
        assertTrue(notEquals.evaluate(row));
    }

    @Test
    public void testNotEqualsWithTimestamps() {
        ColumnExpression col1 = new ColumnExpression("column1", java.sql.Timestamp.class);
        ColumnExpression col2 = new ColumnExpression("column2", java.sql.Timestamp.class);
        NotEqualsExpression notEquals = new NotEqualsExpression(col1, col2);

