        row.put("column2", java.sql.Timestamp.valueOf("2023-01-01 00:00:00"));
        assertFalse(notEquals.evaluate(row));

        row.put("column2", java.sql.Timestamp.valueOf("2023-01-02 00:00:00"));
        assertTrue(notEquals.evaluate(row));
    }

