        ColumnExpression col2 = new ColumnExpression("column2", java.math.BigDecimal.class);
        NotEqualsExpression notEquals = new NotEqualsExpression(col1, col2);

        RowImpl row = new RowImpl();
        row.put("column1", new java.math.BigDecimal("1.0"));
        row.put("column2", new java.math.BigDecimal("1.0"));
        assertFalse(notEquals.evaluate(row));

        row.put("column2", new java.math.BigDecimal("2.0"));
        assertTrue(notEquals.evaluate(row));
    }

