    public void testStringRepresentation() {
        ColumnExpression col1 = new ColumnExpression("column1", String.class);
        ColumnExpression col2 = new ColumnExpression("column2", String.class);
        NotEqualsExpression notEquals = new NotEqualsExpression(col1, col2);

