        ColumnExpression col1 = new ColumnExpression("column1", Integer.class);
        ColumnExpression col2 = new ColumnExpression("column2", Integer.class);
        NotEqualsExpression notEquals = new NotEqualsExpression(col1, col2);

        assertEquals(Boolean.class, notEquals.getResultType());
    }
}

