public class Query extends Prologue implements Cloneable, Printable {
    private String queryType;
    private List<String> resultVariables;
    private List<String> patterns;
    private int limit;
    private int offset;
    private List<String> orderBy;
    private List<String> groupBy;
    private List<String> graphURIs;
    private List<String> namedGraphURIs;
    private boolean strictEvaluation;

    public Query() {
        this.resultVariables = new ArrayList<>();
        this.patterns = new ArrayList<>();
        this.orderBy = new ArrayList<>();
        this.groupBy = new ArrayList<>();
        this.graphURIs = new ArrayList<>();
        this.namedGraphURIs = new ArrayList<>();
        this.limit = -1; // No limit by default
        this.offset = 0; // Default offset
        this.strictEvaluation = false; // Default to non-strict
    }

    public void setQueryType(String queryType) {
        this.queryType = queryType;
    }

    public void addResultVariable(String variable) {
        resultVariables.add(variable);
    }

    public void addPattern(String pattern) {
        patterns.add(pattern);
    }

    public void setLimit(int limit) {
        this.limit = limit;
    }

    public void setOffset(int offset) {
        this.offset = offset;
    }

    public void addOrderBy(String order) {
        orderBy.add(order);
    }

    public void addGroupBy(String group) {
        groupBy.add(group);
    }

    public void addGraphURI(String uri) {
        graphURIs.add(uri);
    }

    public void addNamedGraphURI(String uri) {
        namedGraphURIs.add(uri);
    }

    public void setStrictEvaluation(boolean strict) {
        this.strictEvaluation = strict;
    }

    @Override
    public Query clone() {
        try {
            Query cloned = (Query) super.clone();
            cloned.resultVariables = new ArrayList<>(this.resultVariables);
            cloned.patterns = new ArrayList<>(this.patterns);
            cloned.orderBy = new ArrayList<>(this.orderBy);
            cloned.groupBy = new ArrayList<>(this.groupBy);
            cloned.graphURIs = new ArrayList<>(this.graphURIs);
            cloned.namedGraphURIs = new ArrayList<>(this.namedGraphURIs);
            return cloned;
        } catch (CloneNotSupportedException e) {
            throw new RuntimeException("Clone not supported", e);
        }
    }

    @Override
    public String print() {
        StringBuilder sb = new StringBuilder();
        sb.append("Query Type: ").append(queryType).append("\n");
        sb.append("Result Variables: ").append(resultVariables).append("\n");
        sb.append("Patterns: ").append(patterns).append("\n");
        sb.append("Limit: ").append(limit).append("\n");
        sb.append("Offset: ").append(offset).append("\n");
        sb.append("Order By: ").append(orderBy).append("\n");
        sb.append("Group By: ").append(groupBy).append("\n");
        sb.append("Graph URIs: ").append(graphURIs).append("\n");
        sb.append("Named Graph URIs: ").append(namedGraphURIs).append("\n");
        sb.append("Strict Evaluation: ").append(strictEvaluation).append("\n");
        return sb.toString();
    }
