public class JDBCStore extends StoreBase {
    private static final Logger logger = Logger.getLogger(JDBCStore.class.getName());

    private String dataSource;
    private String driver;
    private String sessionTable = "sessions";
    private String sessionKeyColumn = "session_key";
    private String sessionDataColumn = "session_data";

    private Connection connection;
    private PropertyChangeSupport pcs = new PropertyChangeSupport(this);

    public JDBCStore(String dataSource, String driver) {
        this.dataSource = dataSource;
        this.driver = driver;
        try {
            Class.forName(driver);
            this.connection = DriverManager.getConnection(dataSource);
        } catch (ClassNotFoundException | SQLException e) {
            logger.log(Level.SEVERE, "Database connection error", e);
        }
    }

    public void saveSession(String key, String data) {
        String sql = "INSERT INTO " + sessionTable + " (" + sessionKeyColumn + ", " + sessionDataColumn + ") VALUES (?, ?) ON DUPLICATE KEY UPDATE " + sessionDataColumn + " = ?";
        try (PreparedStatement pstmt = connection.prepareStatement(sql)) {
            pstmt.setString(1, key);
            pstmt.setString(2, data);
            pstmt.setString(3, data);
            pstmt.executeUpdate();
            logger.info("Session saved: " + key);
        } catch (SQLException e) {
            logger.log(Level.SEVERE, "Error saving session", e);
        }
    }

    public String loadSession(String key) {
        String sql = "SELECT " + sessionDataColumn + " FROM " + sessionTable + " WHERE " + sessionKeyColumn + " = ?";
        try (PreparedStatement pstmt = connection.prepareStatement(sql)) {
            pstmt.setString(1, key);
            ResultSet rs = pstmt.executeQuery();
            if (rs.next()) {
                logger.info("Session loaded: " + key);
                return rs.getString(sessionDataColumn);
            }
        } catch (SQLException e) {
            logger.log(Level.SEVERE, "Error loading session", e);
        }
        return null;
    }

    public void removeSession(String key) {
        String sql = "DELETE FROM " + sessionTable + " WHERE " + sessionKeyColumn + " = ?";
        try (PreparedStatement pstmt = connection.prepareStatement(sql)) {
            pstmt.setString(1, key);
            pstmt.executeUpdate();
            logger.info("Session removed: " + key);
        } catch (SQLException e) {
            logger.log(Level.SEVERE, "Error removing session", e);
        }
    }

    public void clearSessions() {
        String sql = "DELETE FROM " + sessionTable;
        try (PreparedStatement pstmt = connection.prepareStatement(sql)) {
            pstmt.executeUpdate();
            logger.info("All sessions cleared");
        } catch (SQLException e) {
            logger.log(Level.SEVERE, "Error clearing sessions", e);
        }
    }

    public Set<String> getSessionKeys() {
        Set<String> keys = new HashSet<>();
        String sql = "SELECT " + sessionKeyColumn + " FROM " + sessionTable;
        try (PreparedStatement pstmt = connection.prepareStatement(sql);
             ResultSet rs = pstmt.executeQuery()) {
            while (rs.next()) {
                keys.add(rs.getString(sessionKeyColumn));
            }
        } catch (SQLException e) {
            logger.log(Level.SEVERE, "Error retrieving session keys", e);
        }
        return keys;
    }

    public int getSessionCount() {
        String sql = "SELECT COUNT(*) FROM " + sessionTable;
        try (PreparedStatement pstmt = connection.prepareStatement(sql);
             ResultSet rs = pstmt.executeQuery()) {
            if (rs.next()) {
                return rs.getInt(1);
            }
        } catch (SQLException e) {
            logger.log(Level.SEVERE, "Error counting sessions", e);
        }
        return 0;
    }

    public void setSessionTable(String sessionTable) {
        String oldValue = this.sessionTable;
        this.sessionTable = sessionTable;
        pcs.firePropertyChange("sessionTable", oldValue, sessionTable);
    }

    public void addPropertyChangeListener(PropertyChangeListener listener) {
        pcs.addPropertyChangeListener(listener);
    }

    public void removePropertyChangeListener(PropertyChangeListener listener) {
        pcs.removePropertyChangeListener(listener);
    }
}

public class FetcherRun {
    private final ExecutorService executorService;
    private final List<String> urls;
    private final AtomicInteger activeThreads;
    private final AtomicInteger pagesFetched;
    private final AtomicInteger bytesDownloaded;
    private final AtomicInteger errorsEncountered;
    private final long timeLimit;
    private final long bandwidthTarget;
    private final long throughputThreshold;
    private final long startTime;

    public FetcherRun(List<String> urls, int initialThreads, long timeLimit, long bandwidthTarget, long throughputThreshold) {
        this.executorService = Executors.newFixedThreadPool(initialThreads);
        this.urls = urls;
        this.activeThreads = new AtomicInteger(0);
        this.pagesFetched = new AtomicInteger(0);
        this.bytesDownloaded = new AtomicInteger(0);
        this.errorsEncountered = new AtomicInteger(0);
        this.timeLimit = timeLimit;
        this.bandwidthTarget = bandwidthTarget;
        this.throughputThreshold = throughputThreshold;
        this.startTime = System.currentTimeMillis();
    }

    public void fetch() {
        List<Future<?>> futures = new ArrayList<>();
        for (String url : urls) {
            futures.add(executorService.submit(() -> fetchUrl(url)));
        }

        for (Future<?> future : futures) {
            try {
                future.get(timeLimit, TimeUnit.MILLISECONDS);
            } catch (TimeoutException e) {
                future.cancel(true);
                errorsEncountered.incrementAndGet();
            } catch (InterruptedException | ExecutionException e) {
                errorsEncountered.incrementAndGet();
            }
        }

        executorService.shutdown();
        reportStatus();
    }

    private void fetchUrl(String url) {
        activeThreads.incrementAndGet();
        try {
            HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
            connection.setRequestMethod("GET");
            connection.connect();

            int responseCode = connection.getResponseCode();
            if (responseCode == 200) {
                int contentLength = connection.getContentLength();
                bytesDownloaded.addAndGet(contentLength);
                pagesFetched.incrementAndGet();
            } else {
                errorsEncountered.incrementAndGet();
            }
        } catch (IOException e) {
            errorsEncountered.incrementAndGet();
        } finally {
            activeThreads.decrementAndGet();
        }
    }

    private void reportStatus() {
        long elapsedTime = System.currentTimeMillis() - startTime;
        long pagesPerSecond = pagesFetched.get() * 1000 / elapsedTime;
        long bytesPerSecond = bytesDownloaded.get() * 1000 / elapsedTime;

        System.out.println("Pages Fetched: " + pagesFetched.get());
        System.out.println("Bytes Downloaded: " + bytesDownloaded.get());
        System.out.println("Errors Encountered: " + errorsEncountered.get());
        System.out.println("Active Threads: " + activeThreads.get());
        System.out.println("Throughput: " + pagesPerSecond + " pages/sec, " + bytesPerSecond + " bytes/sec");
    }

    public static void main(String[] args) {
        List<String> urls = List.of("http://example.com", "http://example.org");
        FetcherRun fetcherRun = new FetcherRun(urls, 5, 10000, 1000000, 500);
        fetcherRun.fetch();
    }
}

