public class ResultsStAX implements ResultSet, Closeable {
    private XMLStreamReader reader;
    private List<String> variableNames;
    private boolean isBooleanQuery;
    private boolean distinct;
    private boolean ordered;

    public ResultsStAX(InputStream inputStream) throws XMLStreamException {
        initializeParser(inputStream);
    }

    public ResultsStAX(Reader reader) throws XMLStreamException {
        initializeParser(reader);
    }

    private void initializeParser(InputStream inputStream) throws XMLStreamException {
        XMLInputFactory factory = XMLInputFactory.newInstance();
        this.reader = factory.createXMLStreamReader(inputStream);
        parseResults();
    }

    private void initializeParser(Reader reader) throws XMLStreamException {
        XMLInputFactory factory = XMLInputFactory.newInstance();
        this.reader = factory.createXMLStreamReader(reader);
        parseResults();
    }

    private void parseResults() throws XMLStreamException {
        // Logic to parse XML and populate variableNames, isBooleanQuery, distinct, ordered
        while (reader.hasNext()) {
            int event = reader.next();
            if (event == XMLStreamReader.START_ELEMENT) {
                String localName = reader.getLocalName();
                if ("head".equals(localName)) {
                    parseHead();
                } else if ("boolean".equals(localName)) {
                    isBooleanQuery = true;
                    parseBooleanResult();
                } else if ("results".equals(localName)) {
                    parseResultSet();
                }
            }
        }
    }

    private void parseHead() throws XMLStreamException {
        // Logic to extract variable names
        while (reader.hasNext()) {
            int event = reader.next();
            if (event == XMLStreamReader.START_ELEMENT && "variable".equals(reader.getLocalName())) {
                variableNames.add(reader.getAttributeValue(null, "name"));
            } else if (event == XMLStreamReader.END_ELEMENT && "head".equals(reader.getLocalName())) {
                break;
            }
        }
    }

    private void parseBooleanResult() throws XMLStreamException {
        // Logic to parse boolean result
        while (reader.hasNext()) {
            int event = reader.next();
            if (event == XMLStreamReader.CHARACTERS) {
                // Handle boolean value
            } else if (event == XMLStreamReader.END_ELEMENT && "boolean".equals(reader.getLocalName())) {
                break;
            }
        }
    }

    private void parseResultSet() throws XMLStreamException {
        // Logic to parse result set
        while (reader.hasNext()) {
            int event = reader.next();
            if (event == XMLStreamReader.START_ELEMENT && "result".equals(reader.getLocalName())) {
                parseResult();
            } else if (event == XMLStreamReader.END_ELEMENT && "results".equals(reader.getLocalName())) {
                break;
            }
        }
    }

    private void parseResult() throws XMLStreamException {
        // Logic to parse individual result
        while (reader.hasNext()) {
            int event = reader.next();
            if (event == XMLStreamReader.END_ELEMENT && "result".equals(reader.getLocalName())) {
                break;
            }
        }
    }

    public List<String> getVariableNames() {
        return variableNames;
    }

    public boolean isBooleanQuery() {
        return isBooleanQuery;
    }

    public boolean isDistinct() {
        return distinct;
    }

    public boolean isOrdered() {
        return ordered;
    }

    @Override
    public void close() throws IOException {
        try {
            if (reader != null) {
                reader.close();
            }
        } catch (XMLStreamException e) {
            throw new IOException("Error closing XMLStreamReader", e);
        }
    }
}

