public class BlockingEventHandlerTest {

    private BlockingEventHandler eventHandler;

    @BeforeEach
    public void setUp() {
        eventHandler = new BlockingEventHandler();
    }

    @Test
    public void testSingle() {
        eventHandler.handleEvent(5);
        assertEquals(5, eventHandler.getSum());
        assertEquals(1, eventHandler.getCount());
    }

    @Test
    public void testMultiple() {
        eventHandler.handleEvent(3);
        eventHandler.handleEvent(7);
        assertEquals(10, eventHandler.getSum());
        assertEquals(2, eventHandler.getCount());
    }

    @Test
    public void testTwoStreams() throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        CountDownLatch latch = new CountDownLatch(2);

        executor.submit(() -> {
            eventHandler.handleEvent(10);
            latch.countDown();
        });

        executor.submit(() -> {
            eventHandler.handleEvent(20);
            latch.countDown();
        });

        latch.await();
        assertEquals(30, eventHandler.getSum());
        assertEquals(2, eventHandler.getCount());
        executor.shutdown();
    }

    @Test
    public void testMultipleResets() throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        CountDownLatch latch = new CountDownLatch(4);

        executor.submit(() -> {
            eventHandler.handleEvent(5);
            latch.countDown();
        });

        executor.submit(() -> {
            eventHandler.handleEvent(15);
            latch.countDown();
        });

        executor.submit(() -> {
            eventHandler.reset();
            latch.countDown();
        });

        executor.submit(() -> {
            eventHandler.handleEvent(10);
            latch.countDown();
        });

        latch.await();
        assertEquals(10, eventHandler.getSum());
        assertEquals(1, eventHandler.getCount());
        executor.shutdown();
    }

    @Test
    public void testManyStreams() throws InterruptedException {
        int numberOfThreads = 100;
        ExecutorService executor = Executors.newFixedThreadPool(numberOfThreads);
        CountDownLatch latch = new CountDownLatch(numberOfThreads);

        for (int i = 0; i < numberOfThreads; i++) {
            final int value = i + 1;
            executor.submit(() -> {
                eventHandler.handleEvent(value);
                latch.countDown();
            });
        }

        latch.await();
        assertEquals(5050, eventHandler.getSum()); // Sum of first 100 integers
        assertEquals(100, eventHandler.getCount());
        executor.shutdown();
    }
}

