public class MetaResultSet implements ResultSet {
    private List<Map<String, Object>> rows;
    private int currentRow = -1;
    private boolean closed = false;
    private ResultSetMetaData metaData;

    public MetaResultSet(List<Map<String, Object>> rows, ResultSetMetaData metaData) {
        this.rows = rows;
        this.metaData = metaData;
    }

    @Override
    public boolean next() throws SQLException {
        checkClosed();
        if (currentRow + 1 < rows.size()) {
            currentRow++;
            return true;
        }
        return false;
    }

    @Override
    public int getInt(int columnIndex) throws SQLException {
        checkClosed();
        checkRowBounds();
        return (Integer) getValue(columnIndex);
    }

    @Override
    public String getString(int columnIndex) throws SQLException {
        checkClosed();
        checkRowBounds();
        return (String) getValue(columnIndex);
    }

    @Override
    public boolean getBoolean(int columnIndex) throws SQLException {
        checkClosed();
        checkRowBounds();
        return (Boolean) getValue(columnIndex);
    }

    @Override
    public Date getDate(int columnIndex) throws SQLException {
        checkClosed();
        checkRowBounds();
        return (Date) getValue(columnIndex);
    }

    private Object getValue(int columnIndex) throws SQLException {
        if (columnIndex < 1 || columnIndex > metaData.getColumnCount()) {
            throw new SQLException("Column index out of bounds");
        }
        String columnName = metaData.getColumnName(columnIndex);
        return rows.get(currentRow).get(columnName);
    }

    private void checkRowBounds() throws SQLException {
        if (currentRow < 0 || currentRow >= rows.size()) {
            throw new SQLException("No current row");
        }
    }

    private void checkClosed() throws SQLException {
        if (closed) {
            throw new SQLException("ResultSet is closed");
        }
    }

    @Override
    public void close() throws SQLException {
        closed = true;
    }

    // Other methods from ResultSet interface would be implemented here, throwing UnsupportedOperationException where necessary.
}

