public class ClassNodeImpl<T> extends AbstractNode implements ClassNode<T> {
    private boolean injectable;
    private boolean hasExternalConstructor;
    private List<Constructor<T>> constructors;
    private List<Class<? extends T>> knownImplementations;

    public ClassNodeImpl(boolean injectable, boolean hasExternalConstructor, List<Constructor<T>> constructors) {
        this.injectable = injectable;
        this.hasExternalConstructor = hasExternalConstructor;
        this.constructors = constructors;
        this.knownImplementations = new ArrayList<>();
    }

    @Override
    public boolean isInjectable() {
        return injectable;
    }

    @Override
    public boolean hasExternalConstructor() {
        return hasExternalConstructor;
    }

    @Override
    public List<Constructor<T>> getInjectableConstructors() {
        return constructors.stream()
                .filter(Constructor::isInjectable)
                .collect(Collectors.toList());
    }

    @Override
    public List<Constructor<T>> getAllConstructors() {
        return constructors;
    }

    public void addKnownImplementation(Class<? extends T> implementation) {
        knownImplementations.add(implementation);
    }

    @Override
    public boolean isCandidateForDependencyInjection() {
        return injectable && !hasExternalConstructor;
    }

    @Override
    public List<Constructor<T>> getConstructorsByParameterTypes(Class<?>... parameterTypes) {
        return constructors.stream()
                .filter(constructor -> Arrays.equals(constructor.getParameterTypes(), parameterTypes))
                .collect(Collectors.toList());
    }

    @Override
    public boolean isUnit() {
        return knownImplementations.isEmpty();
    }

    @Override
    public boolean implementsInterface(Class<?> iface) {
        return iface.isAssignableFrom(getType());
    }

    @Override
    public String toString() {
        return "ClassNodeImpl{" +
                "injectable=" + injectable +
                ", hasExternalConstructor=" + hasExternalConstructor +
                ", constructors=" + constructors +
                ", knownImplementations=" + knownImplementations +
                '}';
    }
}

public class CorbaObjectWriter {
    private OutputStream outputStream;

    public CorbaObjectWriter(OutputStream outputStream) {
        this.outputStream = outputStream;
    }

    public void write(CorbaObjectHandler obj) throws CorbaBindingException {
        if (obj == null) {
            writeDefaultValue();
            return;
        }

        switch (obj.getTypeCode()) {
            case BOOLEAN:
                writeBoolean(obj.getBooleanValue());
                break;
            case CHAR:
                writeChar(obj.getCharValue());
                break;
            case SHORT:
                writeShort(obj.getShortValue());
                break;
            case LONG:
                writeLong(obj.getLongValue());
                break;
            case FLOAT:
                writeFloat(obj.getFloatValue());
                break;
            case DOUBLE:
                writeDouble(obj.getDoubleValue());
                break;
            case STRING:
                writeString(obj.getStringValue());
                break;
            case ARRAY:
                writeArray(obj.getArrayValue());
                break;
            case SEQUENCE:
                writeSequence(obj.getSequenceValue());
                break;
            case STRUCT:
                writeStruct(obj.getStructValue());
                break;
            case ENUM:
                writeEnum(obj.getEnumValue());
                break;
            case EXCEPTION:
                writeException(obj.getExceptionValue());
                break;
            case UNION:
                writeUnion(obj.getUnionValue());
                break;
            case FIXED:
                writeFixed(obj.getFixedValue());
                break;
            case OBJECT:
                writeObjectReference(obj.getObjectReference());
                break;
            default:
                throw new CorbaBindingException("Unsupported type code");
