public class UtilMisc {

    // 1. Initialization and manipulation of exceptions
    public static void throwException(String message) throws Exception {
        throw new Exception(message);
    }

    // 2. Comparison methods for Comparable objects and lists
    public static <T extends Comparable<T>> int compare(T a, T b) {
        return a.compareTo(b);
    }

    public static <T extends Comparable<T>> List<T> sortList(List<T> list) {
        Collections.sort(list);
        return list;
    }

    // 3. Conversion of collections to iterators, sets, and lists
    public static <T> Iterator<T> toIterator(Collection<T> collection) {
        return collection.iterator();
    }

    public static <T> Set<T> toSet(Collection<T> collection) {
        return new HashSet<>(collection);
    }

    public static <T> List<T> toList(Collection<T> collection) {
        return new ArrayList<>(collection);
    }

    // 4. Creation of maps from key-value pairs and handling of variable-length arguments
    public static <K, V> Map<K, V> createMap(K key, V value) {
        Map<K, V> map = new HashMap<>();
        map.put(key, value);
        return map;
    }

    public static <K, V> Map<K, V> createMapFromPairs(Object... pairs) {
        Map<K, V> map = new HashMap<>();
        for (int i = 0; i < pairs.length; i += 2) {
            map.put((K) pairs[i], (V) pairs[i + 1]);
        }
        return map;
    }

    // 5. Serialization handling for maps
    public static String serializeMap(Map<?, ?> map) {
        return map.entrySet().stream()
                .map(entry -> entry.getKey() + "=" + entry.getValue())
                .collect(Collectors.joining(", "));
    }

    // 6. Sorting of lists of maps based on specified keys
    public static List<Map<String, Object>> sortMapsByKey(List<Map<String, Object>> list, String key) {
        list.sort(Comparator.comparing(m -> (Comparable) m.get(key)));
        return list;
    }

    // 7. Retrieval and manipulation of nested maps and lists
    public static Object getNestedValue(Map<String, Object> map, String... keys) {
        Object value = map;
        for (String key : keys) {
            if (value instanceof Map) {
                value = ((Map<?, ?>) value).get(key);
            } else {
                return null;
            }
        }
        return value;
    }

    // 8. Arithmetic operations on BigDecimal values stored in maps
    public static BigDecimal addBigDecimals(Map<String, BigDecimal> map, String key1, String key2) {
        return map.get(key1).add(map.get(key2));
    }

    // 9. Type conversion methods for Double, Integer, and Long
    public static Double toDouble(Object value) {
        return value instanceof Number ? ((Number) value).doubleValue() : null;
    }

    public static Integer toInteger(Object value) {
        return value instanceof Number ? ((Number) value).intValue() : null;
    }

    public static Long toLong(Object value) {
        return value instanceof Number ? ((Number) value).longValue() : null;
    }

    // 10. Locale parsing and management
    public static Locale parseLocale(String localeString) {
        String[] parts = localeString.split("_");
        return new Locale(parts[0], parts.length > 1 ? parts[1] : "");
    }

    // 11. File copying utility
    public static void copyFile(File source, File destination) throws IOException {
        try (InputStream in = new FileInputStream(source);
             OutputStream out = new FileOutputStream(destination)) {
            byte[] buffer = new byte[1024];
            int length;
            while ((length = in.read(buffer)) > 0) {
                out.write(buffer, 0, length);
            }
        }
    }

    // 12. Utility methods for creating writable collections and handling null values
    public static <T> List<T> createWritableList() {
        return new ArrayList<>();
    }

    public static <T> T defaultIfNull(T value, T defaultValue) {
        return value != null ? value : defaultValue;
    }
}

