public class ChmItsfHeader implements ChmAccessor {
    private static final int HEADER_SIZE = 64; // Example size, adjust as needed
    private String signature;
    private int version;
    private int headerLength;
    private long lastModified;
    private int languageId;
    private UUID directoryUuid;
    private UUID streamUuid;
    private int[] offsets;
    private int[] lengths;

    public ChmItsfHeader() {
        offsets = new int[10]; // Example size, adjust as needed
        lengths = new int[10]; // Example size, adjust as needed
    }

    public void parse(byte[] data) {
        if (data.length < HEADER_SIZE) {
            throw new IllegalArgumentException("Data is too short to be a valid CHM header.");
        }

        ByteBuffer buffer = ByteBuffer.wrap(data);
        buffer.order(ByteOrder.LITTLE_ENDIAN);

        signature = new String(data, 0, 4);
        version = buffer.getInt(4);
        headerLength = buffer.getInt(8);
        lastModified = buffer.getLong(12);
        languageId = buffer.getInt(20);
        directoryUuid = new UUID(buffer.getLong(24), buffer.getLong(32));
        streamUuid = new UUID(buffer.getLong(40), buffer.getLong(48));

        for (int i = 0; i < offsets.length; i++) {
            offsets[i] = buffer.getInt(56 + i * 4);
            lengths[i] = buffer.getInt(56 + (i + offsets.length) * 4);
        }
    }

    public boolean validate() {
        return signature.equals("CHM") && version > 0 && headerLength == HEADER_SIZE;
    }

    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Signature: ").append(signature).append("\n");
        sb.append("Version: ").append(version).append("\n");
        sb.append("Header Length: ").append(headerLength).append("\n");
        sb.append("Last Modified: ").append(lastModified).append("\n");
        sb.append("Language ID: ").append(languageId).append("\n");
        sb.append("Directory UUID: ").append(directoryUuid).append("\n");
        sb.append("Stream UUID: ").append(streamUuid).append("\n");
        for (int i = 0; i < offsets.length; i++) {
            sb.append("Offset ").append(i).append(": ").append(offsets[i]).append(", Length: ").append(lengths[i]).append("\n");
        }
        return sb.toString();
    }
}

