public abstract class EncodingSerializer implements Serializer, LocationTracker, Recyclable, Configurable {
    protected String encoding;
    protected OutputStream outputStream;
    protected boolean formattedOutput;
    protected int indentationLevel;

    public EncodingSerializer(String encoding, OutputStream outputStream, boolean formattedOutput) {
        this.encoding = encoding;
        this.outputStream = outputStream;
        this.formattedOutput = formattedOutput;
        this.indentationLevel = 0;
    }

    public abstract void startDocument() throws IOException;
    public abstract void endDocument() throws IOException;
    public abstract void startElement(String name) throws IOException;
    public abstract void endElement(String name) throws IOException;
    public abstract void characters(String text) throws IOException;
    public abstract void startNamespace(String prefix, String uri) throws IOException;
    public abstract void endNamespace(String prefix) throws IOException;
    public abstract void attribute(String name, String value) throws IOException;

    protected void write(String data) throws IOException {
        if (outputStream != null) {
            outputStream.write(data.getBytes(encoding));
        }
    }

    protected void handleError(IOException e) {
        // Error handling logic
    }

    public void recycle() {
        // Reset state for recycling
        encoding = null;
        outputStream = null;
        formattedOutput = false;
        indentationLevel = 0;
    }

    public void configure(Configuration config) {
        // Configuration logic
    }
}

class WatermarkManagerTest {

    @Test
    public void testWatermarkUpdate() {
        WatermarkManager manager = new WatermarkManager();
        manager.updateWatermark("transform1", 1000L);
        assertEquals(1000L, manager.getWatermark("transform1"));
    }

    @Test
    public void testWatermarkMonotonicity() {
        WatermarkManager manager = new WatermarkManager();
        manager.updateWatermark("transform1", 1000L);
        manager.updateWatermark("transform1", 900L); // should not update
        assertEquals(1000L, manager.getWatermark("transform1"));
    }

    @Test
    public void testMultiInputWatermark() {
        WatermarkManager manager = new WatermarkManager();
        manager.updateWatermark("transform1", 1000L);
        manager.updateWatermark("transform2", 1500L);
        assertEquals(1000L, manager.getWatermark("transform1"));
        assertEquals(1500L, manager.getWatermark("transform2"));
    }

    @Test
    public void testKeyedCollectionWatermark() {
        WatermarkManager manager = new WatermarkManager();
        manager.updateWatermark("keyedTransform1:key1", 1000L);
        manager.updateWatermark("keyedTransform1:key2", 1200L);
        assertEquals(1000L, manager.getWatermark("keyedTransform1:key1"));
        assertEquals(1200L, manager.getWatermark("keyedTransform1:key2"));
    }

    @Test
    public void testLateDataHandling() {
        WatermarkManager manager = new WatermarkManager();
        manager.updateWatermark("transform1", 1000L);
        manager.updateWatermark("transform1", 1100L); // valid update
        manager.updateWatermark("transform1", 900L); // late data, should not update
        assertEquals(1100L, manager.getWatermark("transform1"));
    }

    @Test
    public void testEmptyOutputs() {
        WatermarkManager manager = new WatermarkManager();
        assertEquals(-1L, manager.getWatermark("emptyTransform")); // assuming -1 indicates no watermark
    }

    @Test
    public void testFiredTimersExtraction() {
        WatermarkManager manager = new WatermarkManager();
        manager.updateWatermark("transform1", 1000L);
        manager.fireTimer("transform1", 1000L);
        assertTrue(manager.hasFiredTimers("transform1"));
    }
}

