public class BasicDynaBeanTestCase extends TestCase {
    private DynaBean dynaBean;

    @Before
    public void setUp() {
        dynaBean = new DynaBean();
        dynaBean.set("booleanProperty", true);
        dynaBean.set("doubleProperty", 1.0);
        dynaBean.set("floatProperty", 1.0f);
        dynaBean.set("integerProperty", 1);
        dynaBean.set("longProperty", 1L);
        dynaBean.set("shortProperty", (short) 1);
        dynaBean.set("stringProperty", "test");
        dynaBean.set("arrayProperty", new String[]{"value1", "value2"});
        dynaBean.set("listProperty", new ArrayList<>(Arrays.asList("item1", "item2")));
        dynaBean.set("mapProperty", new HashMap<String, String>() {{
            put("key1", "value1");
            put("key2", "value2");
        }});
    }

    @Test
    public void testGetBooleanProperty() {
        assertTrue((Boolean) dynaBean.get("booleanProperty"));
    }

    @Test
    public void testGetDoubleProperty() {
        assertEquals(1.0, (Double) dynaBean.get("doubleProperty"), 0.001);
    }

    @Test
    public void testGetFloatProperty() {
        assertEquals(1.0f, (Float) dynaBean.get("floatProperty"), 0.001);
    }

    @Test
    public void testGetIntegerProperty() {
        assertEquals(1, (Integer) dynaBean.get("integerProperty"));
    }

    @Test
    public void testGetLongProperty() {
        assertEquals(1L, (Long) dynaBean.get("longProperty"));
    }

    @Test
    public void testGetShortProperty() {
        assertEquals((short) 1, (Short) dynaBean.get("shortProperty"));
    }

    @Test
    public void testGetStringProperty() {
        assertEquals("test", dynaBean.get("stringProperty"));
    }

    @Test
    public void testGetArrayProperty() {
        String[] array = (String[]) dynaBean.get("arrayProperty");
        assertArrayEquals(new String[]{"value1", "value2"}, array);
    }

    @Test
    public void testGetListProperty() {
        List<String> list = (List<String>) dynaBean.get("listProperty");
        assertEquals(Arrays.asList("item1", "item2"), list);
    }

    @Test
    public void testGetMapProperty() {
        Map<String, String> map = (Map<String, String>) dynaBean.get("mapProperty");
        assertEquals("value1", map.get("key1"));
        assertEquals("value2", map.get("key2"));
    }

    @Test(expected = PropertyNotFoundException.class)
    public void testGetUnknownProperty() {
        dynaBean.get("unknownProperty");
    }

    @Test
    public void testSetIndexedProperty() {
        dynaBean.set("listProperty[0]", "newItem");
        List<String> list = (List<String>) dynaBean.get("listProperty");
        assertEquals("newItem", list.get(0));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testSetIndexedPropertyOutOfBounds() {
        dynaBean.set("listProperty[10]", "outOfBounds");
    }

    @Test
    public void testSerialization() throws IOException, ClassNotFoundException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(baos);
        oos.writeObject(dynaBean);
        oos.flush();

        ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
        ObjectInputStream ois = new ObjectInputStream(bais);
        DynaBean deserializedDynaBean = (DynaBean) ois.readObject();

        assertEquals(dynaBean.get("stringProperty"), deserializedDynaBean.get("stringProperty"));
    }
}

class CachingResourceStreamLocatorTest {

    private CachingResourceStreamLocator locator;

    @BeforeEach
    void setUp() {
        locator = new CachingResourceStreamLocator();
    }

    @Test
    void testLocateResourceOnce() {
        InputStream stream1 = locator.locate("resource.txt");
        InputStream stream2 = locator.locate("resource.txt");
        assertSame(stream1, stream2, "Resource should be cached and returned the same instance.");
    }

    @Test
    void testStrictAndNonStrictMatching() {
        InputStream strictStream = locator.locate("resource_en.txt");
        InputStream nonStrictStream = locator.locate("resource.txt");

        assertNotNull(strictStream, "Strict match should return a valid stream.");
        assertNotNull(nonStrictStream, "Non-strict match should return a valid stream.");

        assertNotSame(strictStream, nonStrictStream, "Strict and non-strict matches should return different instances.");
    }

    @Test
    void testFileResourceDifferentExtensions() {
        InputStream txtStream = locator.locate("resource.txt");
        InputStream jsonStream = locator.locate("resource.json");

        assertNotNull(txtStream, "TXT resource should be found.");
        assertNotNull(jsonStream, "JSON resource should be found.");

        assertNotSame(txtStream, jsonStream, "Different extensions should return different instances.");
    }

    @Test
    void testCachingForUrlResources() {
        InputStream urlStream1 = locator.locate("http://example.com/resource");
        InputStream urlStream2 = locator.locate("http://example.com/resource");

        assertSame(urlStream1, urlStream2, "URL resource should be cached and return the same instance.");
    }

    @Test
    void testLightweightResourcesHandling() {
        InputStream lightweightStream1 = locator.locate("lightweight/resource");
        InputStream lightweightStream2 = locator.locate("lightweight/resource");

        assertSame(lightweightStream1, lightweightStream2, "Lightweight resource should be cached and return the same instance.");
    }
}

