    }

    public boolean isToBeUpdated(String resourceKey) {
        return toBeUpdated.contains(resourceKey);
    }

    public boolean isToBeDeleted(String resourceKey) {
        return toBeDeleted.contains(resourceKey);
    }

    public void clearCreated() {
        toBeCreated.clear();
    }

    public void clearUpdated() {
        toBeUpdated.clear();
    }

    public void clearDeleted() {
        toBeDeleted.clear();
    }

    public void purgeDeleted() {
        toBeDeleted.clear();
    }

    public void merge(PropagationByResource other) {
        toBeCreated.addAll(other.toBeCreated);
        toBeUpdated.addAll(other.toBeUpdated);
        toBeDeleted.addAll(other.toBeDeleted);
        oldConnectionKeys.putAll(other.oldConnectionKeys);
    }

