public class MailBinding {

    private final MailEndpoint mailEndpoint;
    private final HeaderFilterStrategy headerFilterStrategy;

    public MailBinding(MailEndpoint mailEndpoint, HeaderFilterStrategy headerFilterStrategy) {
        this.mailEndpoint = mailEndpoint;
        this.headerFilterStrategy = headerFilterStrategy;
    }

    public void populateMailMessage(Exchange exchange) {
        MailMessage mailMessage = exchange.getIn(MailMessage.class);
        MimeMessage mimeMessage = mailMessage.getMimeMessage();

        setRecipients(mimeMessage, exchange);
        appendHeaders(mimeMessage, exchange);
        appendAttachments(mimeMessage, exchange);
        extractBodyContent(mimeMessage, exchange);
    }

    private void setRecipients(MimeMessage mimeMessage, Exchange exchange) {
        String to = exchange.getIn().getHeader("to", String.class);
        if (to == null) {
            to = mailEndpoint.getConfiguration().getTo();
        }
        if (to != null) {
            try {
                mimeMessage.setRecipients(MimeMessage.RecipientType.TO, to);
            } catch (Exception e) {
                // Log error
            }
        }
    }

    private void appendHeaders(MimeMessage mimeMessage, Exchange exchange) {
        Map<String, Object> headers = exchange.getIn().getHeaders();
        for (Map.Entry<String, Object> entry : headers.entrySet()) {
            if (!headerFilterStrategy.applyFilterToExternalHeaders(entry.getKey(), entry.getValue(), exchange)) {
                try {
                    mimeMessage.setHeader(entry.getKey(), entry.getValue().toString());
                } catch (Exception e) {
                    // Log error
                }
            }
        }
    }

    private void appendAttachments(MimeMessage mimeMessage, Exchange exchange) {
        List<Object> attachments = exchange.getIn().getHeader("attachments", List.class);
        if (attachments != null) {
            for (Object attachment : attachments) {
                // Logic to add attachment to mimeMessage
            }
        }
    }

    private void extractBodyContent(MimeMessage mimeMessage, Exchange exchange) {
        Object body = exchange.getIn().getBody();
        if (body != null) {
            try {
                mimeMessage.setContent(body, "text/plain");
            } catch (Exception e) {
                // Log error
            }
        }
    }
}

