public class ModelServiceReader {
    private static final Logger logger = Logger.getLogger(ModelServiceReader.class.getName());
    private Map<String, ModelService> serviceMap = new HashMap<>();

    public void loadServices(String source) {
        try {
            Document document = getXmlDocument(source);
            extractServiceDefinitions(document);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error loading services", e);
        }
    }

    private Document getXmlDocument(String source) throws Exception {
        InputStream inputStream = null;
        try {
            if (source.startsWith("http://") || source.startsWith("https://")) {
                URL url = new URL(source);
                inputStream = url.openStream();
            } else {
                inputStream = getClass().getResourceAsStream(source);
            }
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            return builder.parse(new InputSource(inputStream));
        } finally {
            if (inputStream != null) {
                inputStream.close();
            }
        }
    }

    private void extractServiceDefinitions(Document document) {
        NodeList serviceNodes = document.getElementsByTagName("service");
        for (int i = 0; i < serviceNodes.getLength(); i++) {
            String serviceName = serviceNodes.item(i).getAttributes().getNamedItem("name").getNodeValue();
            ModelService service = createService(serviceNodes.item(i));
            serviceMap.put(serviceName, service);
        }
    }

    private ModelService createService(org.w3c.dom.Node serviceNode) {
        // Implementation of service creation logic
        ModelService service = new ModelService();
        // Set service attributes based on XML node
        return service;
    }

    public Map<String, ModelService> getServiceMap() {
        return serviceMap;
    }
}

