        assertEquals(1000L, message.getJMSExpiration());
        assertEquals(5, message.getJMSPriority());
    }

    @Test
    public void testPropertyRetrieval() {
        message.setStringProperty("stringProp", "value");
        assertEquals("value", message.getStringProperty("stringProp"));

        message.setBooleanProperty("boolProp", true);
        assertTrue(message.getBooleanProperty("boolProp"));

        message.setByteProperty("byteProp", (byte) 1);
        assertEquals(1, message.getByteProperty("byteProp"));

        message.setShortProperty("shortProp", (short) 2);
        assertEquals(2, message.getShortProperty("shortProp"));

        message.setIntProperty("intProp", 3);
        assertEquals(3, message.getIntProperty("intProp"));

        message.setLongProperty("longProp", 4L);
        assertEquals(4L, message.getLongProperty("longProp"));

        message.setFloatProperty("floatProp", 5.0f);
        assertEquals(5.0f, message.getFloatProperty("floatProp"), 0.0f);

        message.setDoubleProperty("doubleProp", 6.0);
        assertEquals(6.0, message.getDoubleProperty("doubleProp"), 0.0);
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testReadOnlyProperties() {
        message.setJMSMessageID("ID:12345");
        message.setJMSMessageID("ID:67890"); // Should throw exception
    }

    @Test
    public void testEqualityAndHashCode() {
        ActiveMQMessage message1 = new ActiveMQMessage();
        ActiveMQMessage message2 = new ActiveMQMessage();
        assertEquals(message1, message2);
        assertEquals(message1.hashCode(), message2.hashCode());
    }

    @Test
    public void testCopyingProperties() {
        message.setStringProperty("prop", "value");
        ActiveMQMessage copy = message.copy();
        assertEquals("value", copy.getStringProperty("prop"));
    }

    @Test
    public void testExpirationStatus() {
        message.setJMSExpiration(System.currentTimeMillis() + 1000);
        assertFalse(message.isExpired());
        message.setJMSExpiration(System.currentTimeMillis() - 1000);
        assertTrue(message.isExpired());
    }

    @Test
    public void testPropertyNames() {
        message.setStringProperty("prop1", "value1");
        assertTrue(message.propertyExists("prop1"));
        assertFalse(message.propertyExists("prop2"));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testInvalidPropertyConversion() {
        message.setStringProperty("intProp", "notAnInt");
        message.getIntProperty("intProp"); // Should throw exception
    }
