public class RequestSessionContext implements SessionContext {
    private Map<String, String> parameters;
    private Map<String, String> headers;
    private Map<String, String> cookies;
    private Map<String, Object> attributes;
    private Document xmlDocument;

    public RequestSessionContext() {
        parameters = new HashMap<>();
        headers = new HashMap<>();
        cookies = new HashMap<>();
        attributes = new HashMap<>();
        buildXmlDocument();
    }

    private void buildXmlDocument() {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            xmlDocument = builder.newDocument();
            Element root = xmlDocument.createElement("RequestContext");
            xmlDocument.appendChild(root);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void setParameter(String key, String value) {
        parameters.put(key, value);
    }

    public String getParameter(String key) {
        return parameters.get(key);
    }

    public void setHeader(String key, String value) {
        headers.put(key, value);
    }

    public String getHeader(String key) {
        return headers.get(key);
    }

    public void setCookie(String key, String value) {
        cookies.put(key, value);
    }

    public String getCookie(String key) {
        return cookies.get(key);
    }

    public void setAttribute(String key, Object value) {
        attributes.put(key, value);
    }

    public Object getAttribute(String key) {
        return attributes.get(key);
    }

    public String getXmlRepresentation() {
        // Code smell: This method is too complex and does too much
        StringBuilder xmlBuilder = new StringBuilder();
        xmlBuilder.append("<RequestContext>");
        xmlBuilder.append("<Parameters>");
        for (Map.Entry<String, String> entry : parameters.entrySet()) {
            xmlBuilder.append("<Parameter key=\"").append(entry.getKey()).append("\">")
                      .append(entry.getValue()).append("</Parameter>");
        }
        xmlBuilder.append("</Parameters>");
        xmlBuilder.append("<Headers>");
        for (Map.Entry<String, String> entry : headers.entrySet()) {
            xmlBuilder.append("<Header key=\"").append(entry.getKey()).append("\">")
                      .append(entry.getValue()).append("</Header>");
        }
        xmlBuilder.append("</Headers>");
        xmlBuilder.append("<Cookies>");
        for (Map.Entry<String, String> entry : cookies.entrySet()) {
            xmlBuilder.append("<Cookie key=\"").append(entry.getKey()).append("\">")
                      .append(entry.getValue()).append("</Cookie>");
        }
        xmlBuilder.append("</Cookies>");
        xmlBuilder.append("</RequestContext>");
        return xmlBuilder.toString();
    }

    public String getValueByXPath(String expression) {
        try {
            XPathFactory xPathFactory = XPathFactory.newInstance();
            XPath xpath = xPathFactory.newXPath();
            return xpath.evaluate(expression, xmlDocument);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}

