public class JavaCharStream {
    private char[] buffer;
    private int bufferSize;
    private int bufferPosition;
    private int line;
    private int column;
    private InputStream inputStream;

    public JavaCharStream(InputStream inputStream, int bufferSize) {
        this.inputStream = inputStream;
        this.bufferSize = bufferSize;
        this.buffer = new char[bufferSize];
        this.bufferPosition = 0;
        this.line = 1;
        this.column = 0;
        initialize();
    }

    private void initialize() {
        try {
            fillBuffer();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void fillBuffer() throws IOException {
        int bytesRead = inputStream.read(buffer);
        if (bytesRead == -1) {
            buffer[0] = '\0'; // End of stream
        }
    }

    public char readChar() throws IOException {
        if (bufferPosition >= bufferSize) {
            fillBuffer();
            bufferPosition = 0;
        }
        char ch = buffer[bufferPosition++];
        updatePosition(ch);
        return ch;
    }

    private void updatePosition(char ch) {
        if (ch == '\n') {
            line++;
            column = 0;
        } else {
            column++;
        }
    }

    public void backup(int amount) {
        bufferPosition -= amount;
    }

    public int getLine() {
        return line;
    }

    public int getColumn() {
        return column;
    }

    public String getImage() {
        return new String(buffer, 0, bufferPosition);
    }

    public String getSuffix(int len) {
        if (bufferPosition + len > bufferSize) {
            len = bufferSize - bufferPosition;
        }
        return new String(buffer, bufferPosition, len);
    }

    public void reinitialize(InputStream newInputStream) {
        this.inputStream = newInputStream;
        this.bufferPosition = 0;
        this.line = 1;
        this.column = 0;
        initialize();
    }
}

