        logger.info("Testing indexed entry equality.");
        Entry entry1 = new Entry("1", "value1");
        Entry entry2 = new Entry("1", "value1");
        dataStore.addIndexedEntry(entry1);
        assertTrue(dataStore.equals(entry1, entry2));
    }

    @Test
    public void testNonIndexedEntryEquality() {
        logger.info("Testing non-indexed entry equality.");
        Entry entry1 = new Entry("2", "value2");
        Entry entry2 = new Entry("2", "value2");
        dataStore.addNonIndexedEntry(entry1);
        assertTrue(dataStore.equals(entry1, entry2));
    }

    @Test
    public void testRetrieveEntryById() {
