class KStreamAggregationIntegrationTest {

    private KafkaStreams streams;
    private TestInputTopic<String, Integer> inputTopic;
    private TestOutputTopic<String, Integer> outputTopic;

    @Before
    public void setUp() {
        Properties props = new Properties();
        props.put(StreamsConfig.APPLICATION_ID_CONFIG, "test-app");
        props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "dummy:1234");
        props.put(StreamsConfig.DEFAULT_KEY_SERDE_CLASS_CONFIG, "org.apache.kafka.common.serialization.Serdes$StringSerde");
        props.put(StreamsConfig.DEFAULT_VALUE_SERDE_CLASS_CONFIG, "org.apache.kafka.common.serialization.Serdes$IntegerSerde");

        StreamsBuilder builder = new StreamsBuilder();
        builder.stream("input-topic")
                .groupByKey()
                .reduce(Integer::sum)
                .toStream()
                .to("output-topic");

        Topology topology = builder.build();
        streams = new KafkaStreams(topology, props);
        streams.start();

        inputTopic = TestTopology.createInputTopic("input-topic", new StringSerializer(), new IntegerSerializer());
        outputTopic = TestTopology.createOutputTopic("output-topic", new StringDeserializer(), new IntegerDeserializer());
    }

    @Test
    public void testAggregation() {
        inputTopic.pipeInput("key1", 1);
        inputTopic.pipeInput("key1", 2);
        inputTopic.pipeInput("key2", 3);

        TestRecord<String, Integer> outputRecord1 = outputTopic.readRecord();
        TestRecord<String, Integer> outputRecord2 = outputTopic.readRecord();

        assertEquals("key1", outputRecord1.key());
        assertEquals(Integer.valueOf(3), outputRecord1.value());
        assertEquals("key2", outputRecord2.key());
        assertEquals(Integer.valueOf(3), outputRecord2.value());
    }

    @After
    public void tearDown() {
        streams.close();
    }
}

public class InjectionUtils {
    private static final Logger logger = Logger.getLogger(InjectionUtils.class.getName());

    public static boolean isConcreteClass(Class<?> clazz) {
        return !(clazz.isInterface() || Modifier.isAbstract(clazz.getModifiers()));
    }

    public static List<Type> getSuperTypes(Class<?> clazz) {
        List<Type> superTypes = new ArrayList<>();
        Type superclass = clazz.getGenericSuperclass();
        while (superclass != null) {
            superTypes.add(superclass);
            if (superclass instanceof Class<?>) {
                superclass = ((Class<?>) superclass).getGenericSuperclass();
            } else {
                break;
            }
        }
        return superTypes;
    }

    public static Type getActualTypeFromGeneric(Class<?> clazz, int index) {
        Type genericSuperclass = clazz.getGenericSuperclass();
        if (genericSuperclass instanceof ParameterizedType) {
            return ((ParameterizedType) genericSuperclass).getActualTypeArguments()[index];
        }
        return Object.class;
    }

    public static void injectField(Object target, Field field, Object value) {
        try {
            field.setAccessible(true);
            field.set(target, value);
        } catch (IllegalAccessException e) {
            logger.log(Level.SEVERE, "Failed to inject field: " + field.getName(), e);
        }
    }

    public static Object extractFieldValue(Object target, Field field) {
        try {
            field.setAccessible(true);
            return field.get(target);
        } catch (IllegalAccessException e) {
            logger.log(Level.SEVERE, "Failed to extract field value: " + field.getName(), e);
            return null;
        }
    }

    public static Object convertStringToType(String value, Class<?> targetType) {
        if (targetType.isPrimitive()) {
            if (targetType == int.class) return Integer.parseInt(value);
            if (targetType == boolean.class) return Boolean.parseBoolean(value);
            if (targetType == double.class) return Double.parseDouble(value);
            // Add other primitive types as needed
        }
        return value; // Fallback for non-primitive types
    }

    public static <T> T createInstance(Class<T> clazz) {
        try {
            return clazz.getDeclaredConstructor().newInstance();
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to create instance of: " + clazz.getName(), e);
            return null;
        }
    }

    public static void handleContextInjection(Object target) {
        for (Field field : target.getClass().getDeclaredFields()) {
            if (field.isAnnotationPresent(Context.class)) {
                Object contextValue = getContextValue(field.getType());
                injectField(target, field, contextValue);
            }
        }
    }

    private static Object getContextValue(Class<?> type) {
        // Placeholder for context retrieval logic
        return null;
    }

    public static void reportServerError(Exception e) {
        logger.log(Level.SEVERE, "Server error occurred", e);
    }

    public static <T> List<T> mergeCollections(Collection<T> first, Collection<T> second) {
        List<T> merged = new ArrayList<>(first);
        merged.addAll(second);
        return merged;
    }

    public static Object processBeanValue(Object bean, String propertyName) {
        try {
            PropertyDescriptor descriptor = new PropertyDescriptor(propertyName, bean.getClass());
            return descriptor.getReadMethod().invoke(bean);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to process bean value for property: " + propertyName, e);
            return null;
        }
    }
}

