public class GetHTTP extends AbstractProcessor {
    private ComponentLog logger;

    @Override
    protected void init(ProcessorInitializationContext context) {
        logger = context.getLogger();
    }

    @Override
    public void onTrigger(ProcessContext context, ProcessSession session) {
        FlowFile flowFile = session.get();
        if (flowFile == null) {
            return;
        }

        String url = flowFile.getAttribute("url");
        HttpURLConnection connection = null;

        try {
            URL requestUrl = new URL(url);
            connection = (HttpURLConnection) requestUrl.openConnection();
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(5000);
            connection.setReadTimeout(5000);

            // Handle ETag and Last Modified
            String eTag = flowFile.getAttribute("eTag");
            String lastModified = flowFile.getAttribute("lastModified");
            if (eTag != null) {
                connection.setRequestProperty("If-None-Match", eTag);
            }
            if (lastModified != null) {
                connection.setRequestProperty("If-Modified-Since", lastModified);
            }

            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_NOT_MODIFIED) {
                logger.info("Data has not changed for URL: " + url);
                session.transfer(flowFile, REL_SUCCESS);
                return;
            }

            // Read response
            InputStream inputStream = connection.getInputStream();
            FlowFile newFlowFile = session.create(flowFile);
            session.importFrom(inputStream, newFlowFile);
            newFlowFile = session.putAttribute(newFlowFile, "eTag", connection.getHeaderField("ETag"));
            newFlowFile = session.putAttribute(newFlowFile, "lastModified", connection.getHeaderField("Last-Modified"));
            session.transfer(newFlowFile, REL_SUCCESS);
        } catch (IOException e) {
            logger.error("Failed to fetch data from URL: " + url, e);
            session.transfer(flowFile, REL_FAILURE);
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }
}

