public class CheckMethodAdapter extends MethodVisitor {
    private int instructionCount;
    private Map<Integer, String> labelMappings;
    private int accessFlags;

    public CheckMethodAdapter(MethodVisitor methodVisitor, int accessFlags) {
        super(Opcodes.ASM9, methodVisitor);
        this.instructionCount = 0;
        this.labelMappings = new HashMap<>();
        this.accessFlags = accessFlags;
    }

    @Override
    public void visitInsn(int opcode) {
        instructionCount++;
        validateOpcode(opcode);
        super.visitInsn(opcode);
    }

    @Override
    public void visitLabel(Label label) {
        labelMappings.put(instructionCount, label.toString());
        super.visitLabel(label);
    }

    @Override
    public void visitEnd() {
        validateMethod();
        super.visitEnd();
    }

    private void validateOpcode(int opcode) {
        // Check for illegal opcodes based on method access flags
        if ((accessFlags & Opcodes.ACC_STATIC) != 0 && opcode == Opcodes.INVOKEVIRTUAL) {
            throw new IllegalStateException("Illegal opcode for static method: " + opcode);
        }
        // Additional opcode validations can be added here
    }

    private void validateMethod() {
        // Validate method annotations and local variable definitions
        if (instructionCount == 0) {
            throw new IllegalStateException("Method has no instructions.");
        }
        // Further validations can be added here
    }
}

