public class EqualsBuilder {
    private boolean isEquals = true;

    public static EqualsBuilder reflectionEquals(Object lhs, Object rhs) {
        return new EqualsBuilder();
    }

    public boolean isEquals() {
        return isEquals;
    }

    public EqualsBuilder append(long lhs, long rhs) {
        if (isEquals) {
            isEquals = (lhs == rhs);
        }
        return this;
    }

    public EqualsBuilder append(int lhs, int rhs) {
        if (isEquals) {
            isEquals = (lhs == rhs);
        }
        return this;
    }

    public EqualsBuilder append(Object lhs, Object rhs) {
        if (isEquals) {
            isEquals = (lhs == null ? rhs == null : lhs.equals(rhs));
        }
        return this;
    }

    public EqualsBuilder append(long[] lhs, long[] rhs) {
        if (isEquals) {
            if (lhs == null || rhs == null) {
                isEquals = (lhs == rhs);
            } else if (lhs.length != rhs.length) {
                isEquals = false;
            } else {
                for (int i = 0; i < lhs.length; i++) {
                    append(lhs[i], rhs[i]);
                }
            }
        }
        return this;
    }

    public EqualsBuilder append(int[] lhs, int[] rhs) {
        if (isEquals) {
            if (lhs == null || rhs == null) {
                isEquals = (lhs == rhs);
            } else if (lhs.length != rhs.length) {
                isEquals = false;
            } else {
                for (int i = 0; i < lhs.length; i++) {
                    append(lhs[i], rhs[i]);
                }
            }
        }
        return this;
    }

    // Additional methods for other types and arrays can be added here
}

public class TestMergeRecord {

    private MergeRecord mergeRecord;

    @BeforeEach
    public void setUp() {
        mergeRecord = new MergeRecord();
    }

    @Test
    public void testMergeRecordsWithValidInput() {
        List<String> records = Arrays.asList("record1,data1", "record2,data2");
        String merged = mergeRecord.merge(records);
        assertEquals("record1,data1;record2,data2", merged);
    }

    @Test
    public void testMergeRecordsWithEmptyInput() {
        List<String> records = Arrays.asList();
        String merged = mergeRecord.merge(records);
        assertEquals("", merged);
    }

    @Test
    public void testMergeRecordsWithSingleRecord() {
        List<String> records = Arrays.asList("singleRecord,data");
        String merged = mergeRecord.merge(records);
        assertEquals("singleRecord,data", merged);
    }

    @Test
    public void testMergeRecordsWithMaxSizeConstraint() {
        List<String> records = Arrays.asList("record1,data1", "record2,data2", "record3,data3");
        mergeRecord.setMaxSize(50);
        String merged = mergeRecord.merge(records);
        assertEquals("record1,data1;record2,data2;record3,data3", merged);
    }

    @Test
    public void testMergeRecordsExceedingMaxSize() {
        List<String> records = Arrays.asList("record1,data1", "record2,data2,extraData");
        mergeRecord.setMaxSize(20);
        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            mergeRecord.merge(records);
        });
        assertEquals("Merged record exceeds maximum size", exception.getMessage());
    }

    @Test
    public void testMergeRecordsWithSchemaCompatibility() {
        List<String> records = Arrays.asList("record1,data1", "record2,data2");
        mergeRecord.setSchema("record,data");
        String merged = mergeRecord.merge(records);
        assertEquals("record1,data1;record2,data2", merged);
    }

    @Test
    public void testMergeRecordsWithIncompatibleSchema() {
        List<String> records = Arrays.asList("record1,data1", "record2");
        mergeRecord.setSchema("record,data");
        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            mergeRecord.merge(records);
        });
        assertEquals("Incompatible schema for merging", exception.getMessage());
    }

    @Test
    public void testDefragmentationOfRecords() {
        List<String> records = Arrays.asList("record1,data1", "record2,data2", "record3,data3");
        String merged = mergeRecord.defragment(records);
        assertEquals("record1,data1;record2,data2;record3,data3", merged);
    }

    @Test
    public void testTimeoutHandling() {
        mergeRecord.setTimeout(100);
        List<String> records = Arrays.asList("record1,data1", "record2,data2");
        Exception exception = assertThrows(TimeoutException.class, () -> {
            mergeRecord.mergeWithTimeout(records);
        });
        assertEquals("Merge operation timed out", exception.getMessage());
    }

    @Test
    public void testConfigurationPropertiesValidation() {
        mergeRecord.setMaxSize(100);
        mergeRecord.setSchema("record,data");
        assertTrue(mergeRecord.validateConfiguration());
    }

    @Test
    public void testInvalidConfigurationProperties() {
        mergeRecord.setMaxSize(-1);
        assertFalse(mergeRecord.validateConfiguration());
    }
}

