        try {
            graphHelper.updateVertex(entity);
            transactionManager.commit();
        } catch (Exception e) {
            transactionManager.rollback();
            throw e;
        }
    }

    @Override
    public void deleteEntity(String id) {
        transactionManager.beginTransaction();
        try {
            graphHelper.removeVertex(id);
            transactionManager.commit();
        } catch (Exception e) {
            transactionManager.rollback();
            throw e;
        }
    }

    @Override
    public void addTrait(String entityId, Trait trait) {
