public class DelegatingResultSet implements ResultSet {
    private final ResultSet resultSet;
    private final Statement statement;
    private final Connection connection;

    public DelegatingResultSet(ResultSet resultSet, Statement statement, Connection connection) {
        this.resultSet = resultSet;
        this.statement = statement;
        this.connection = connection;
    }

    private void handleException(SQLException e) {
        if (statement instanceof DelegatingStatement) {
            ((DelegatingStatement) statement).handleException(e);
        } else if (connection instanceof DelegatingConnection) {
            ((DelegatingConnection) connection).handleException(e);
        }
    }

    @Override
    public boolean next() {
        try {
            return resultSet.next();
        } catch (SQLException e) {
            handleException(e);
            return false; // Code smell: returning false on exception
        }
    }

    @Override
    public void close() {
        try {
            resultSet.close();
        } catch (SQLException e) {
            handleException(e);
        }
    }

    // Implement all other ResultSet methods by delegating to resultSet

    @Override
    public boolean wasNull() {
        try {
            return resultSet.wasNull();
        } catch (SQLException e) {
            handleException(e);
            return false; // Code smell: returning false on exception
        }
    }

    @Override
    public String getString(int columnIndex) {
        try {
            return resultSet.getString(columnIndex);
        } catch (SQLException e) {
            handleException(e);
            return null; // Code smell: returning null on exception
        }
    }

    @Override
    public int getInt(int columnIndex) {
        try {
            return resultSet.getInt(columnIndex);
        } catch (SQLException e) {
            handleException(e);
            return 0; // Code smell: returning 0 on exception
        }
    }

    // Add other methods from ResultSet interface...

    // Static factory methods
    public static DelegatingResultSet fromConnection(Connection connection, ResultSet resultSet) {
        return new DelegatingResultSet(resultSet, null, connection);
    }

    public static DelegatingResultSet fromStatement(Statement statement, ResultSet resultSet) {
        return new DelegatingResultSet(resultSet, statement, null);
    }

    // Implement remaining ResultSet methods...
}

