class AvlTreeTest {
    private AvlTree<Integer> avlTree;

    @BeforeEach
    void setUp() {
        avlTree = new AvlTree<>();
    }

    @Test
    void testTreeInitialization() {
        assertNotNull(avlTree);
    }

    @Test
    void testEmptyTreeChecks() {
        assertTrue(avlTree.isEmpty());
        assertEquals(0, avlTree.size());
        assertThrows(NoSuchElementException.class, () -> avlTree.first());
        assertThrows(NoSuchElementException.class, () -> avlTree.last());
    }

    @Test
    void testInsertion() {
        avlTree.insert(10);
        assertEquals(1, avlTree.size());
        assertFalse(avlTree.isEmpty());
        avlTree.insert(20);
        avlTree.insert(30);
        assertEquals(3, avlTree.size());
        assertEquals(10, avlTree.first());
        assertEquals(30, avlTree.last());
    }

    @Test
    void testRetrieval() {
        avlTree.insert(10);
        avlTree.insert(20);
        avlTree.insert(30);
        assertEquals(10, avlTree.first());
        assertEquals(30, avlTree.last());
        assertEquals(10, avlTree.min());
        assertEquals(30, avlTree.max());
    }

    @Test
    void testRotationOperations() {
        avlTree.insert(30);
        avlTree.insert(20);
        avlTree.insert(10); // This should trigger a right rotation
        assertEquals(20, avlTree.first());
        assertEquals(30, avlTree.last());

        avlTree.insert(25); // This should trigger a left-right rotation
        assertEquals(20, avlTree.first());
        assertEquals(30, avlTree.last());
    }

    @Test
    void testRemoval() {
        avlTree.insert(10);
        avlTree.insert(20);
        avlTree.insert(30);
        avlTree.remove(20);
        assertEquals(2, avlTree.size());
        assertThrows(NoSuchElementException.class, () -> avlTree.remove(40)); // Removing non-existent element
        avlTree.remove(10);
        assertEquals(1, avlTree.size());
        avlTree.remove(30);
        assertTrue(avlTree.isEmpty());
    }

    @Test
    void testFindingElements() {
        avlTree.insert(10);
        avlTree.insert(20);
        avlTree.insert(30);
        assertTrue(avlTree.contains(20));
        assertFalse(avlTree.contains(40));
        assertEquals(10, avlTree.findLessThan(15));
        assertEquals(20, avlTree.findGreaterThan(15));
    }

    @Test
    void testLinkedNodeStructure() {
        avlTree.insert(10);
        avlTree.insert(20);
        avlTree.insert(30);
        assertNotNull(avlTree.getRoot());
        assertNotNull(avlTree.getRoot().getLeft());
        assertNotNull(avlTree.getRoot().getRight());
    }

    @Test
    void testTreeTraversal() {
        avlTree.insert(30);
        avlTree.insert(10);
        avlTree.insert(20);
        List<Integer> expectedOrder = Arrays.asList(10, 20, 30);
        assertEquals(expectedOrder, avlTree.inOrderTraversal());
    }

    @Test
    void testDebugLogging() {
