            Element rootElement = doc.createElement("Transaction");
            doc.appendChild(rootElement);

            Element typeElement = doc.createElement("Type");
            typeElement.appendChild(doc.createTextNode(transactionType));
            rootElement.appendChild(typeElement);

            if (amount != null) {
                Element amountElement = doc.createElement("Amount");
                amountElement.appendChild(doc.createTextNode(amount));
                rootElement.appendChild(amountElement);
            }

            Element referenceElement = doc.createElement("ReferenceNumber");
            referenceElement.appendChild(doc.createTextNode(referenceNumber));
            rootElement.appendChild(referenceElement);

            TransformerFactory transformerFactory = TransformerFactory.newInstance();
            Transformer transformer = transformerFactory.newTransformer();
            transformer.setOutputProperty(OutputKeys.INDENT, "yes");
            DOMSource source = new DOMSource(doc);
            StringWriter writer = new StringWriter();
            StreamResult result = new StreamResult(writer);
            transformer.transform(source, result);

            return writer.toString();
        } catch (ParserConfigurationException | TransformerException e) {
