public class DbGenerator {
    private static final Logger logger = Logger.getLogger(DbGenerator.class.getName());
    private final DbAdapter dbAdapter;
    private final DataMap dataMap;

    public DbGenerator(DbAdapter dbAdapter, DataMap dataMap) {
        this.dbAdapter = dbAdapter;
        this.dataMap = dataMap;
    }

    public void generateSchema() {
        try (Connection connection = dbAdapter.getConnection()) {
            connection.setAutoCommit(false);
            dropTables(connection);
            createTables(connection);
            connection.commit();
        } catch (SQLException e) {
            logger.log(Level.SEVERE, "Error generating schema", e);
        }
    }

    private void dropTables(Connection connection) {
        List<String> tables = dataMap.getTableNames();
        for (String table : tables) {
            String dropSql = "DROP TABLE IF EXISTS " + table;
            executeSql(connection, dropSql);
        }
    }

    private void createTables(Connection connection) {
        List<Entity> entities = dataMap.getEntities();
        for (Entity entity : entities) {
            String createSql = buildCreateTableSql(entity);
            executeSql(connection, createSql);
            createForeignKeys(connection, entity);
        }
    }

    private String buildCreateTableSql(Entity entity) {
        StringBuilder sql = new StringBuilder("CREATE TABLE " + entity.getName() + " (");
        List<Column> columns = entity.getColumns();
        for (int i = 0; i < columns.size(); i++) {
            Column column = columns.get(i);
            sql.append(column.getName()).append(" ").append(column.getType());
            if (column.isPrimaryKey()) {
                sql.append(" PRIMARY KEY");
            }
            if (i < columns.size() - 1) {
                sql.append(", ");
            }
        }
        sql.append(");");
        return sql.toString();
    }

    private void createForeignKeys(Connection connection, Entity entity) {
        List<ForeignKey> foreignKeys = entity.getForeignKeys();
        for (ForeignKey fk : foreignKeys) {
            String fkSql = "ALTER TABLE " + entity.getName() + " ADD CONSTRAINT " + fk.getName() +
                    " FOREIGN KEY (" + fk.getColumn() + ") REFERENCES " + fk.getReferencedTable() +
                    " (" + fk.getReferencedColumn() + ");";
            executeSql(connection, fkSql);
        }
    }

    private void executeSql(Connection connection, String sql) {
        try (Statement statement = connection.createStatement()) {
            statement.execute(sql);
            logger.info("Executed SQL: " + sql);
        } catch (SQLException e) {
            logger.log(Level.SEVERE, "SQL execution error: " + sql, e);
        }
    }
}

public class TraceFormatter {
    private boolean includeExchangePattern;
    private boolean includeProperties;
    private boolean includeHeaders;
    private boolean includeBody;
    private boolean includeExceptions;

    public TraceFormatter() {
        // Default configuration
        this.includeExchangePattern = true;
        this.includeProperties = true;
        this.includeHeaders = true;
        this.includeBody = true;
        this.includeExceptions = true;
    }

    public String formatTrace(Exchange exchange) {
        StringBuilder traceBuilder = new StringBuilder();

        if (includeExchangePattern) {
            traceBuilder.append("Exchange Pattern: ").append(exchange.getPattern()).append("\n");
        }
        if (includeProperties) {
            traceBuilder.append("Properties: ").append(exchange.getProperties()).append("\n");
        }
        if (includeHeaders) {
            traceBuilder.append("Headers: ").append(exchange.getMessage().getHeaders()).append("\n");
        }
        if (includeBody) {
            traceBuilder.append("Body: ").append(exchange.getMessage().getBody()).append("\n");
        }
        if (includeExceptions && exchange.hasException()) {
            traceBuilder.append("Exception: ").append(exchange.getException().getMessage()).append("\n");
        }

        return traceBuilder.toString();
    }

    public boolean isIncludeExchangePattern() {
        return includeExchangePattern;
    }

    public void setIncludeExchangePattern(boolean includeExchangePattern) {
        this.includeExchangePattern = includeExchangePattern;
    }

    public boolean isIncludeProperties() {
        return includeProperties;
    }

    public void setIncludeProperties(boolean includeProperties) {
        this.includeProperties = includeProperties;
    }

    public boolean isIncludeHeaders() {
        return includeHeaders;
    }

    public void setIncludeHeaders(boolean includeHeaders) {
        this.includeHeaders = includeHeaders;
    }

    public boolean isIncludeBody() {
        return includeBody;
    }

    public void setIncludeBody(boolean includeBody) {
        this.includeBody = includeBody;
    }

    public boolean isIncludeExceptions() {
        return includeExceptions;
    }

    public void setIncludeExceptions(boolean includeExceptions) {
        this.includeExceptions = includeExceptions;
    }
}

