public class StringFactory {
    private static final String EMPTY_PROPERTY = "No properties";
    private static final String VERTEX_PREFIX = "Vertex: ";
    private static final String EDGE_PREFIX = "Edge: ";
    private static final String GRAPH_PREFIX = "Graph: ";
    private static final String TRAVERSAL_PREFIX = "Traversal: ";

    public static String formatVertex(Object vertex) {
        if (vertex == null) {
            return EMPTY_PROPERTY;
        }
        return VERTEX_PREFIX + vertex.toString();
    }

    public static String formatEdge(Object edge) {
        if (edge == null) {
            return EMPTY_PROPERTY;
        }
        return EDGE_PREFIX + edge.toString();
    }

    public static String formatGraph(Object graph) {
        if (graph == null) {
            return EMPTY_PROPERTY;
        }
        return GRAPH_PREFIX + graph.toString();
    }

    public static String formatTraversal(Object traversal) {
        if (traversal == null) {
            return EMPTY_PROPERTY;
        }
        return TRAVERSAL_PREFIX + traversal.toString();
    }

    public static String formatProperties(Map<String, Object> properties) {
        if (properties == null || properties.isEmpty()) {
            return EMPTY_PROPERTY;
        }
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, Object> entry : properties.entrySet()) {
            sb.append(entry.getKey()).append(": ").append(entry.getValue()).append(", ");
        }
        return sb.substring(0, sb.length() - 2); // Remove last comma and space
    }

    public static String formatCollection(Collection<?> collection) {
        if (collection == null || collection.isEmpty()) {
            return EMPTY_PROPERTY;
        }
        StringBuilder sb = new StringBuilder();
        for (Object item : collection) {
            sb.append(item.toString()).append(", ");
        }
        return sb.substring(0, sb.length() - 2); // Remove last comma and space
    }

    public static String formatGraphFeatures(Object graphFeatures) {
        if (graphFeatures == null) {
            return EMPTY_PROPERTY;
        }
        return "Graph Features: " + graphFeatures.toString();
    }

    public static String formatTraversalSideEffects(Object sideEffects) {
        if (sideEffects == null) {
            return EMPTY_PROPERTY;
        }
        return "Traversal Side Effects: " + sideEffects.toString();
    }
}

