public class HttpUtils {

    private static final String DEFAULT_ENCODING = "UTF-8";
    private static final String DATE_FORMAT = "EEE, dd MMM yyyy HH:mm:ss zzz";

    public static String encode(String value) {
        try {
            return URLEncoder.encode(value, DEFAULT_ENCODING);
        } catch (UnsupportedEncodingException e) {
            // This should never happen since UTF-8 is always supported
            throw new RuntimeException(e);
        }
    }

    public static String decode(String value) {
        try {
            return URLDecoder.decode(value, DEFAULT_ENCODING);
        } catch (UnsupportedEncodingException e) {
            // This should never happen since UTF-8 is always supported
            throw new RuntimeException(e);
        }
    }

    public static boolean isPartiallyEncoded(String value) {
        return value != null && value.contains("%") && !value.matches(".*%[0-9A-Fa-f]{2}.*");
    }

    public static String formatDate(Date date) {
        SimpleDateFormat sdf = new SimpleDateFormat(DATE_FORMAT, Locale.ENGLISH);
        return sdf.format(date);
    }

    public static Date parseDate(String dateStr) throws ParseException {
        SimpleDateFormat sdf = new SimpleDateFormat(DATE_FORMAT, Locale.ENGLISH);
        return sdf.parse(dateStr);
    }

    public static long getContentLength(Map<String, String> headers) {
        String contentLength = headers.get("Content-Length");
        return contentLength != null ? Long.parseLong(contentLength) : -1;
    }

    public static String getMediaType(Map<String, String> headers) {
        String contentType = headers.get("Content-Type");
        if (contentType != null) {
            return contentType.split(";")[0].trim();
        }
        return null;
    }

    public static Charset getCharset(Map<String, String> headers) {
        String contentType = headers.get("Content-Type");
        if (contentType != null) {
            String[] params = contentType.split(";");
            for (String param : params) {
                if (param.trim().startsWith("charset=")) {
                    return Charset.forName(param.trim().substring("charset=".length()));
                }
            }
        }
        return StandardCharsets.UTF_8; // Default charset
    }
}

