    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof ArtifactTransferEvent)) return false;
        ArtifactTransferEvent that = (ArtifactTransferEvent) obj;
        return eventType == that.eventType &&
               requestType == that.requestType &&
               bytesTransferred == that.bytesTransferred &&
               offset == that.offset &&
               length == that.length &&
               (localFile != null ? localFile.equals(that.localFile) : that.localFile == null) &&
               (artifact != null ? artifact.equals(that.artifact) : that.artifact == null) &&
               (exception != null ? exception.equals(that.exception) : that.exception == null);
    }

    @Override
    public int hashCode() {
        int result = eventType;
        result = 31 * result + requestType;
        result = 31 * result + (exception != null ? exception.hashCode() : 0);
        result = 31 * result + (localFile != null ? localFile.hashCode() : 0);
        result = 31 * result + (artifact != null ? artifact.hashCode() : 0);
        result = 31 * result + (int) (bytesTransferred ^ (bytesTransferred >>> 32));
        result = 31 * result + (dataBuffer != null ? dataBuffer.hashCode() : 0);
        result = 31 * result + offset;
        result = 31 * result + length;
        return result;
    }

    @Override
    public String toString() {
        return "ArtifactTransferEvent{" +
               "eventType=" + eventType +
               ", requestType=" + requestType +
               ", exception=" + exception +
               ", localFile='" + localFile + '\'' +
               ", artifact='" + artifact + '\'' +
               ", bytesTransferred=" + bytesTransferred +
               ", offset=" + offset +
               ", length=" + length +
               '}';
    }
}

public class SummaryStatistics implements StatisticalSummary, Serializable {
    private long n = 0;
    private double sum = 0.0;
    private double sumOfSquares = 0.0;
    private double min = Double.POSITIVE_INFINITY;
    private double max = Double.NEGATIVE_INFINITY;
    private double sumLog = 0.0;

    public void addValue(double value) {
        n++;
        sum += value;
        sumOfSquares += value * value;
        if (value < min) min = value;
        if (value > max) max = value;
        if (value > 0) sumLog += Math.log(value);
    }

    public void clear() {
        n = 0;
        sum = 0.0;
        sumOfSquares = 0.0;
        min = Double.POSITIVE_INFINITY;
        max = Double.NEGATIVE_INFINITY;
        sumLog = 0.0;
    }

    public long getN() {
        return n;
    }

    public double getSum() {
        return sum;
    }

    public double getSumOfSquares() {
        return sumOfSquares;
    }

    public double getMean() {
        return n > 0 ? sum / n : Double.NaN;
    }

    public double getGeometricMean() {
        return n > 0 ? Math.exp(sumLog / n) : Double.NaN;
    }

    public double getVariance() {
        return n > 1 ? (sumOfSquares - (sum * sum) / n) / (n - 1) : Double.NaN;
    }

    public double getStandardDeviation() {
        return Math.sqrt(getVariance());
    }

    public double getMin() {
        return n > 0 ? min : Double.NaN;
    }

    public double getMax() {
        return n > 0 ? max : Double.NaN;
    }

    public void copy(SummaryStatistics other) {
        this.n = other.n;
        this.sum = other.sum;
        this.sumOfSquares = other.sumOfSquares;
        this.min = other.min;
        this.max = other.max;
        this.sumLog = other.sumLog;
    }

    @Override
    public String toString() {
        return "SummaryStatistics{" +
                "n=" + n +
                ", sum=" + sum +
                ", sumOfSquares=" + sumOfSquares +
                ", min=" + min +
                ", max=" + max +
                ", sumLog=" + sumLog +
                '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof SummaryStatistics)) return false;
        SummaryStatistics that = (SummaryStatistics) o;
        return n == that.n &&
                Double.compare(that.sum, sum) == 0 &&
                Double.compare(that.sumOfSquares, sumOfSquares) == 0 &&
                Double.compare(that.min, min) == 0 &&
                Double.compare(that.max, max) == 0 &&
                Double.compare(that.sumLog, sumLog) == 0;
    }

    @Override
    public int hashCode() {
        return Objects.hash(n, sum, sumOfSquares, min, max, sumLog);
    }
}

