public class HelixTask implements MessageTask {
    private HelixManager helixManager;
    private MessageHandler messageHandler;
    private static final int MAX_RETRIES = 3;

    public HelixTask(HelixManager helixManager, MessageHandler messageHandler) {
        this.helixManager = helixManager;
        this.messageHandler = messageHandler;
    }

    @Override
    public void execute(Message message) {
        int retries = 0;
        boolean success = false;

        while (retries < MAX_RETRIES && !success) {
            try {
                log("Starting execution for message: " + message.getId());
                messageHandler.handle(message);
                updateMessageStatus(message, "SUCCESS");
                success = true;
                log("Successfully executed message: " + message.getId());
            } catch (InterruptedException e) {
                log("Execution interrupted for message: " + message.getId());
                updateMessageStatus(message, "INTERRUPTED");
                Thread.currentThread().interrupt();
                break;
            } catch (Exception e) {
                retries++;
                log("Execution failed for message: " + message.getId() + ". Attempt: " + retries);
                if (retries >= MAX_RETRIES) {
                    updateMessageStatus(message, "FAILED");
                    log("Max retries reached for message: " + message.getId());
                }
            }
        }
        reportStatistics(message);
    }

    private void updateMessageStatus(Message message, String status) {
        helixManager.updateMessageStatus(message.getId(), status);
    }

    private void reportStatistics(Message message) {
        // Logic to report statistics related to state transitions
        log("Reporting statistics for message: " + message.getId());
    }

    private void log(String message) {
        // Logging logic
        System.out.println(message);
    }
}

public class SubList<E> {
    private final CopyOnWriteArrayList<E> list;
    private final int fromIndex;
    private final int toIndex;
    private final ReentrantLock lock = new ReentrantLock();

    public SubList(CopyOnWriteArrayList<E> list, int fromIndex, int toIndex) {
        this.list = list;
        this.fromIndex = fromIndex;
        this.toIndex = toIndex;
    }

    public E get(int index) {
        lock.lock();
        try {
            return list.get(fromIndex + index);
        } finally {
            lock.unlock();
        }
    }

    public void add(E element) {
        lock.lock();
        try {
            list.add(toIndex, element);
        } finally {
            lock.unlock();
        }
    }

    public void remove(int index) {
        lock.lock();
        try {
            list.remove(fromIndex + index);
        } finally {
            lock.unlock();
        }
    }

    public boolean contains(E element) {
        lock.lock();
        try {
            return list.subList(fromIndex, toIndex).contains(element);
        } finally {
            lock.unlock();
        }
    }

    public int size() {
        lock.lock();
        try {
            return toIndex - fromIndex;
        } finally {
            lock.unlock();
        }
    }

    public SubList<E> subList(int fromIndex, int toIndex) {
        return new SubList<>(list, this.fromIndex + fromIndex, this.fromIndex + toIndex);
    }

    public void forEach(java.util.function.Consumer<? super E> action) {
        lock.lock();
        try {
            for (int i = fromIndex; i < toIndex; i++) {
                action.accept(list.get(i));
            }
        } finally {
            lock.unlock();
        }
    }
}

public class ContextUtil {

