            return (JobContext) constructor.newInstance(conf, jobId);
        } catch (Exception e) {
            throw new RuntimeException("Failed to create JobContext", e);
        }
    }

    public static TaskAttemptContext createTaskAttemptContext(Configuration conf, int taskId) {
        try {
            Class<?> taskAttemptContextClass = Class.forName(TASK_ATTEMPT_CONTEXT_CLASS_NAME);
            Constructor<?> constructor = taskAttemptContextClass.getConstructor(Configuration.class, int.class);
            return (TaskAttemptContext) constructor.newInstance(conf, taskId);
        } catch (Exception e) {
            throw new RuntimeException("Failed to create TaskAttemptContext", e);
        }
    }

    public static Counter createCounter(JobContext jobContext, String groupName, String counterName) {
        return jobContext.getCounter(groupName, counterName);
    }

    public static void incrementCounter(JobContext jobContext, String groupName, String counterName, long increment) {
        Counter counter = createCounter(jobContext, groupName, counterName);
        counter.increment(increment);
