public class SimplexTableau implements Serializable {
    private static final long serialVersionUID = 1L;

    private double[][] tableau;
    private int numVariables;
    private int numConstraints;
    private boolean isMaximization;

    public SimplexTableau(double[][] constraints, double[] objectiveFunction, boolean isMaximization) {
        this.numConstraints = constraints.length;
        this.numVariables = objectiveFunction.length;
        this.isMaximization = isMaximization;
        initializeTableau(constraints, objectiveFunction);
    }

    private void initializeTableau(double[][] constraints, double[] objectiveFunction) {
        tableau = new double[numConstraints + 1][numVariables + numConstraints + 1];

        for (int i = 0; i < numConstraints; i++) {
            System.arraycopy(constraints[i], 0, tableau[i], 0, numVariables);
            tableau[i][numVariables + i] = 1; // Slack variable
            tableau[i][tableau[i].length - 1] = 0; // Right-hand side
        }

        if (isMaximization) {
            for (int j = 0; j < numVariables; j++) {
                tableau[numConstraints][j] = -objectiveFunction[j];
            }
        } else {
            for (int j = 0; j < numVariables; j++) {
                tableau[numConstraints][j] = objectiveFunction[j];
            }
        }
    }

    public void performRowOperation(int pivotRow, int pivotColumn) {
        double pivotValue = tableau[pivotRow][pivotColumn];
        for (int j = 0; j < tableau[pivotRow].length; j++) {
            tableau[pivotRow][j] /= pivotValue;
        }
        for (int i = 0; i < tableau.length; i++) {
            if (i != pivotRow) {
                double factor = tableau[i][pivotColumn];
                for (int j = 0; j < tableau[i].length; j++) {
                    tableau[i][j] -= factor * tableau[pivotRow][j];
                }
            }
        }
    }

    public boolean isOptimal() {
        double[] lastRow = tableau[numConstraints];
        return Arrays.stream(lastRow, 0, lastRow.length - 1).allMatch(value -> value >= 0);
    }

    public double[] getSolution() {
        double[] solution = new double[numVariables];
        for (int i = 0; i < numConstraints; i++) {
            boolean isBasic = false;
            for (int j = 0; j < numVariables; j++) {
                if (tableau[i][j] == 1) {
                    isBasic = true;
                    solution[j] = tableau[i][tableau[i].length - 1];
                    break;
                }
            }
            if (!isBasic) {
                solution[i] = 0;
            }
        }
        return solution;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof SimplexTableau)) return false;
        SimplexTableau other = (SimplexTableau) obj;
        return Arrays.deepEquals(this.tableau, other.tableau);
    }

    @Override
    public int hashCode() {
        return Arrays.deepHashCode(tableau);
    }
}

