public class ConnectionState implements Watcher, Closeable {
    private ZooKeeper zooKeeper;
    private String connectionString;
    private boolean connected;
    private List<Watcher> parentWatchers = new CopyOnWriteArrayList<>();

    public ConnectionState(String connectionString) {
        this.connectionString = connectionString;
        this.connected = false;
    }

    public void start() {
        try {
            zooKeeper = new ZooKeeper(connectionString, 30000, this);
            connected = true;
            logConnectionEvent("Connection established");
        } catch (IOException e) {
            handleException(e);
        }
    }

    public void close() {
        try {
            if (zooKeeper != null) {
                zooKeeper.close();
                connected = false;
                logConnectionEvent("Connection closed");
            }
        } catch (InterruptedException e) {
            handleException(e);
        }
    }

    public boolean isConnected() {
        return connected;
    }

    public void updateConnectionString(String newConnectionString) {
        this.connectionString = newConnectionString;
        if (connected) {
            close();
            start();
        }
    }

    @Override
    public void process(org.apache.zookeeper.WatchedEvent event) {
        // Handle session expiration and other events
        if (event.getState() == org.apache.zookeeper.Watcher.Event.KeeperState.Expired) {
            logConnectionEvent("Session expired, reconnecting...");
            close();
            start();
        }
        notifyParentWatchers(event);
    }

    private void notifyParentWatchers(org.apache.zookeeper.WatchedEvent event) {
        for (Watcher watcher : parentWatchers) {
            watcher.process(event);
        }
    }

    private void handleException(Exception e) {
        logConnectionEvent("Exception occurred: " + e.getMessage());
    }

    private void logConnectionEvent(String message) {
        System.out.println(message); // Simple logging, could be improved
    }

    public void addParentWatcher(Watcher watcher) {
        parentWatchers.add(watcher);
    }

    public void removeParentWatcher(Watcher watcher) {
        parentWatchers.remove(watcher);
    }
}

