public class LegacyToDefaultConverterTest {

    private ArtifactRepository sourceRepository;
    private ArtifactRepository targetRepository;
    private ArtifactConverter artifactConverter;

    @BeforeEach
    public void setUp() {
        sourceRepository = new ArtifactRepository("sourceRepo");
        targetRepository = new ArtifactRepository("targetRepo");
        artifactConverter = new ArtifactConverter(sourceRepository, targetRepository);
    }

    @AfterEach
    public void tearDown() {
        deleteDirectory(sourceRepository.getDirectory());
        deleteDirectory(targetRepository.getDirectory());
    }

    @Test
    public void testConvertSimpleArtifact() {
        Artifact legacyArtifact = new Artifact("legacy-artifact", "1.0.0");
        sourceRepository.addArtifact(legacyArtifact);

        artifactConverter.convert();

        Artifact convertedArtifact = targetRepository.getArtifact("legacy-artifact", "1.0.0");
        assertNotNull(convertedArtifact);
        assertEquals("legacy-artifact", convertedArtifact.getName());
        assertEquals("1.0.0", convertedArtifact.getVersion());
    }

    @Test
    public void testConvertArtifactWithMetadata() {
        Artifact legacyArtifact = new Artifact("legacy-artifact", "1.0.0");
        legacyArtifact.setMetadata("description", "A legacy artifact");
        sourceRepository.addArtifact(legacyArtifact);

        artifactConverter.convert();

        Artifact convertedArtifact = targetRepository.getArtifact("legacy-artifact", "1.0.0");
        assertNotNull(convertedArtifact);
        assertEquals("A legacy artifact", convertedArtifact.getMetadata("description"));
    }

    @Test
    public void testConvertModifiedArtifact() {
        Artifact legacyArtifact = new Artifact("legacy-artifact", "1.0.0");
        sourceRepository.addArtifact(legacyArtifact);

        artifactConverter.convert();

        legacyArtifact.setVersion("1.0.1");
        sourceRepository.addArtifact(legacyArtifact);

        artifactConverter.convert();

        Artifact convertedArtifact = targetRepository.getArtifact("legacy-artifact", "1.0.1");
        assertNotNull(convertedArtifact);
        assertEquals("1.0.1", convertedArtifact.getVersion());
    }

    @Test
    public void testDryRunConversion() {
        Artifact legacyArtifact = new Artifact("legacy-artifact", "1.0.0");
        sourceRepository.addArtifact(legacyArtifact);

        artifactConverter.setDryRun(true);
        artifactConverter.convert();

        assertNull(targetRepository.getArtifact("legacy-artifact", "1.0.0"));
    }

    @Test
    public void testHandleInvalidMetadata() {
        Artifact legacyArtifact = new Artifact("legacy-artifact", "1.0.0");
        legacyArtifact.setMetadata("invalid", null); // Invalid metadata
        sourceRepository.addArtifact(legacyArtifact);

        List<String> warnings = artifactConverter.convert();

        assertTrue(warnings.contains("Invalid metadata for artifact legacy-artifact:1.0.0"));
    }

    private void deleteDirectory(File directory) {
        if (directory.isDirectory()) {
            for (File file : directory.listFiles()) {
                deleteDirectory(file);
            }
        }
        directory.delete();
    }
}

