public class DefaultSessionManager extends AbstractValidatingSessionManager implements CacheManagerAware {
    private static final Logger logger = LoggerFactory.getLogger(DefaultSessionManager.class);

    private SessionDAO sessionDAO;
    private CacheManager cacheManager;

    public DefaultSessionManager(SessionDAO sessionDAO) {
        this.sessionDAO = sessionDAO;
    }

    @Override
    public void setCacheManager(CacheManager cacheManager) {
        this.cacheManager = cacheManager;
    }

    public Session createSession() {
        Session session = new Session();
        sessionDAO.save(session);
        logger.info("Session created: {}", session.getId());
        return session;
    }

    public Session getSession(String sessionId) {
        Session session = sessionDAO.get(sessionId);
        if (session == null) {
            logger.warn("Session not found: {}", sessionId);
        }
        return session;
    }

    public void updateSession(Session session) {
        sessionDAO.update(session);
        logger.info("Session updated: {}", session.getId());
    }

    public void deleteSession(String sessionId) {
        sessionDAO.delete(sessionId);
        logger.info("Session deleted: {}", sessionId);
    }

    public void invalidateSession(String sessionId) {
        Session session = getSession(sessionId);
        if (session != null) {
            session.invalidate();
            updateSession(session);
            logger.info("Session invalidated: {}", sessionId);
        } else {
            logger.warn("Attempted to invalidate non-existent session: {}", sessionId);
        }
    }

    public void deleteInvalidSessions() {
        for (String sessionId : sessionDAO.getAllSessionIds()) {
            Session session = getSession(sessionId);
            if (session != null && session.isExpired()) {
                deleteSession(sessionId);
                logger.info("Deleted invalid session: {}", sessionId);
            }
        }
    }
}

public class ValueLinkApi {
    private static final String ALGORITHM = "AES";
    private static final String TRANSFORMATION = "AES";
    private static final Map<String, ValueLinkApi> instanceCache = new HashMap<>();
    private SecretKey mwk; // Master Key
    private SecretKey kek; // Key Encryption Key

    private ValueLinkApi(SecretKey mwk, SecretKey kek) {
        this.mwk = mwk;
        this.kek = kek;
    }

    public static ValueLinkApi getInstance(String merchantId) {
        return instanceCache.computeIfAbsent(merchantId, id -> {
            try {
                SecretKey mwk = generateKey();
                SecretKey kek = generateKey();
                return new ValueLinkApi(mwk, kek);
            } catch (NoSuchAlgorithmException e) {
                throw new RuntimeException("Error generating keys", e);
            }
        });
    }

    private static SecretKey generateKey() throws NoSuchAlgorithmException {
        KeyGenerator keyGen = KeyGenerator.getInstance(ALGORITHM);
        keyGen.init(128, new SecureRandom());
        return keyGen.generateKey();
    }

    public String encrypt(String data) throws Exception {
        return performCipherOperation(Cipher.ENCRYPT_MODE, data);
    }

    public String decrypt(String encryptedData) throws Exception {
        return performCipherOperation(Cipher.DECRYPT_MODE, encryptedData);
    }

    private String performCipherOperation(int mode, String data) throws Exception {
        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        cipher.init(mode, mwk);
        byte[] result = cipher.doFinal(data.getBytes());
        return mode == Cipher.ENCRYPT_MODE ? Base64.getEncoder().encodeToString(result) : new String(result);
    }

    public String generateTransactionId() {
        return UUID.randomUUID().toString();
    }

