public class ZkHelixConnection implements HelixConnection, IZkStateListener {
    private ZooKeeper zooKeeper;
    private Set<ConnectionStateListener> connectionStateListeners;
    private long sessionTimeout;
    private boolean isConnected;
    private long lastDisconnectTime;

    public ZkHelixConnection(String zkAddress, long sessionTimeout) {
        this.connectionStateListeners = new HashSet<>();
        this.sessionTimeout = sessionTimeout;
        this.isConnected = false;
        this.lastDisconnectTime = 0;
        connect(zkAddress);
    }

    private void connect(String zkAddress) {
        try {
            this.zooKeeper = new ZooKeeper(zkAddress, (int) sessionTimeout, this);
            this.isConnected = true;
            notifyConnectionStateChange(true);
        } catch (Exception e) {
            handleConnectionError(e);
        }
    }

    public void disconnect() {
        if (isConnected) {
            try {
                zooKeeper.close();
                isConnected = false;
                lastDisconnectTime = System.currentTimeMillis();
                notifyConnectionStateChange(false);
            } catch (Exception e) {
                handleConnectionError(e);
            }
        }
    }

    @Override
    public void onStateChange(String state) {
        // Handle state changes
    }

    public void addConnectionStateListener(ConnectionStateListener listener) {
        connectionStateListeners.add(listener);
    }

    public void removeConnectionStateListener(ConnectionStateListener listener) {
        connectionStateListeners.remove(listener);
    }

    private void notifyConnectionStateChange(boolean isConnected) {
        for (ConnectionStateListener listener : connectionStateListeners) {
            listener.onConnectionStateChange(isConnected);
        }
    }

    private void handleConnectionError(Exception e) {
        // Log error and handle connection issues
    }

    // Additional methods for creating Helix components would go here
}

