public class TaskImpl implements Task, EventHandler<TaskEvent> {
    private enum TaskState { NEW, SCHEDULED, RUNNING, SUCCEEDED, FAILED, KILLED }

    private TaskState state;
    private int attemptCount;
    private List<TaskAttempt> attempts;
    private TaskCounters counters;
    private String diagnostics;

    public TaskImpl() {
        this.state = TaskState.NEW;
        this.attemptCount = 0;
        this.attempts = new ArrayList<>();
        this.counters = new TaskCounters();
        this.diagnostics = "";
    }

    @Override
    public void handle(TaskEvent event) {
        switch (event.getType()) {
            case SCHEDULE:
                scheduleTask();
                break;
            case ATTEMPT_SUCCEEDED:
                handleAttemptSucceeded();
                break;
            case ATTEMPT_FAILED:
                handleAttemptFailed();
                break;
            case KILL:
                killTask();
                break;
            default:
                logUnknownEvent(event);
        }
    }

    private void scheduleTask() {
        if (state == TaskState.NEW) {
            state = TaskState.SCHEDULED;
            attemptCount++;
            TaskAttempt attempt = new TaskAttempt(attemptCount);
            attempts.add(attempt);
            attempt.start();
            state = TaskState.RUNNING;
        }
    }

    private void handleAttemptSucceeded() {
        if (state == TaskState.RUNNING) {
            state = TaskState.SUCCEEDED;
            logTaskSuccess();
        }
    }

    private void handleAttemptFailed() {
        if (state == TaskState.RUNNING) {
            if (attemptCount < MAX_ATTEMPTS) {
                scheduleTask();
            } else {
                state = TaskState.FAILED;
                logTaskFailure();
            }
        }
    }

    private void killTask() {
        state = TaskState.KILLED;
        logTaskKilled();
    }

    private void logUnknownEvent(TaskEvent event) {
        // Log unknown event
    }

    private void logTaskSuccess() {
        // Log success
    }

    private void logTaskFailure() {
        // Log failure
    }

    private void logTaskKilled() {
        // Log killed
    }

    public TaskCounters getCounters() {
        return counters;
    }

    public String getDiagnostics() {
        return diagnostics;
    }

    // Additional methods for task recovery and output committing can be added here
}

