    }

    @Test
    public void testMultipleConnectionFactories() {
        ConnectionFactory stringFactory = new StringConnectionFactory();
        ConnectionFactory integerFactory = new IntegerConnectionFactory();
        NetworkConnectionService stringService = new NetworkConnectionService(stringFactory);
        NetworkConnectionService integerService = new NetworkConnectionService(integerFactory);

        stringService.sendMessage("Test String");
        integerService.sendMessage(123);
        logger.info("Sent messages using multiple connection factories.");
    }

    @Test
    public void testPerformanceSingleThreaded() {
        NetworkConnectionService service = new NetworkConnectionService(new StringCodec());
        long startTime = System.nanoTime();
        for (int i = 0; i < MESSAGE_COUNT; i++) {
            service.sendMessage("Message " + i);
        }
        long endTime = System.nanoTime();
        logger.info("Single-threaded performance: {} ms", TimeUnit.NANOSECONDS.toMillis(endTime - startTime));
    }

    @Test
    public void testPerformanceMultiThreaded() throws InterruptedException {
        NetworkConnectionService service = new NetworkConnectionService(new StringCodec());
        ExecutorService executor = Executors.newFixedThreadPool(10);
        long startTime = System.nanoTime();

        for (int i = 0; i < MESSAGE_COUNT; i++) {
            final int index = i;
            executor.submit(() -> service.sendMessage("Message " + index));
        }
        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);
        long endTime = System.nanoTime();
        logger.info("Multi-threaded performance: {} ms", TimeUnit.NANOSECONDS.toMillis(endTime - startTime));
    }

    @Test
    public void testBatchingMessageRates() {
        NetworkConnectionService service = new NetworkConnectionService(new StringCodec());
        long startTime = System.nanoTime();
        for (int i = 0; i < MESSAGE_COUNT; i++) {
            service.sendMessage("Batch Message " + i);
        }
        long endTime = System.nanoTime();
        logger.info("Batching message rate: {} ms", TimeUnit.NANOSECONDS.toMillis(endTime - startTime));
    }
