public class ResourceLogic extends AbstractTransactionalLogic<ResourceTO> {

    private final ResourceDAO resourceDAO;
    private final ConnectionDAO connectionDAO;
    private final RoleService roleService;

    public ResourceLogic(ResourceDAO resourceDAO, ConnectionDAO connectionDAO, RoleService roleService) {
        this.resourceDAO = resourceDAO;
        this.connectionDAO = connectionDAO;
        this.roleService = roleService;
    }

    @Transactional
    public void createResource(ResourceTO resource) {
        if (!roleService.hasCreatePermission()) {
            throw new AccessDeniedException("User does not have permission to create resources.");
        }
        try {
            resourceDAO.create(resource);
        } catch (Exception e) {
            throw new ResourceOperationException("Failed to create resource.", e);
        }
    }

    @Transactional
    public void updateResource(ResourceTO resource) {
        if (!roleService.hasUpdatePermission()) {
            throw new AccessDeniedException("User does not have permission to update resources.");
        }
        try {
            resourceDAO.update(resource);
        } catch (Exception e) {
            throw new ResourceOperationException("Failed to update resource.", e);
        }
    }

    @Transactional
    public void deleteResource(Long resourceId) {
        if (!roleService.hasDeletePermission()) {
            throw new AccessDeniedException("User does not have permission to delete resources.");
        }
        try {
            resourceDAO.delete(resourceId);
        } catch (Exception e) {
            throw new ResourceOperationException("Failed to delete resource.", e);
        }
    }

    public ResourceTO readResource(Long resourceId) {
        if (!roleService.hasReadPermission()) {
            throw new AccessDeniedException("User does not have permission to read resources.");
        }
        try {
            return resourceDAO.read(resourceId);
        } catch (Exception e) {
            throw new ResourceOperationException("Failed to read resource.", e);
        }
    }

    public List<ResourceTO> listResources() {
        if (!roleService.hasListPermission()) {
            throw new AccessDeniedException("User does not have permission to list resources.");
        }
        try {
            return resourceDAO.listAll();
        } catch (Exception e) {
            throw new ResourceOperationException("Failed to list resources.", e);
        }
    }

    public List<ConnectionTO> listConnections() {
        if (!roleService.hasListPermission()) {
            throw new AccessDeniedException("User does not have permission to list connections.");
        }
        try {
            return connectionDAO.listAll();
        } catch (Exception e) {
            throw new ResourceOperationException("Failed to list connections.", e);
        }
    }

    public ConnectorStatus checkConnectorStatus(Long connectorId) {
        if (!roleService.hasCheckStatusPermission()) {
            throw new AccessDeniedException("User does not have permission to check connector status.");
        }
        try {
            return connectionDAO.checkStatus(connectorId);
        } catch (Exception e) {
            throw new ResourceOperationException("Failed to check connector status.", e);
        }
    }
}

