public abstract class UIComponentTag extends TagSupport {

    protected String id;
    protected String binding;
    protected boolean rendered = true;

    protected UIComponent component;

    @Override
    public int doStartTag() throws JspException {
        FacesContext context = FacesContext.getCurrentInstance();
        component = createComponent(context);
        if (component == null) {
            throw new JspException("Component creation failed");
        }
        component.setId(id);
        component.setRendered(rendered);
        setProperties(component);
        context.getViewRoot().addChild(component);
        return EVAL_BODY_INCLUDE;
    }

    protected abstract UIComponent createComponent(FacesContext context);

    protected void setProperties(UIComponent component) {
        // Set properties like binding, etc.
    }

    @Override
    public int doEndTag() throws JspException {
        FacesContext context = FacesContext.getCurrentInstance();
        ResponseWriter writer = context.getResponseWriter();
        try {
            encodeBegin(writer);
            encodeChildren(writer);
            encodeEnd(writer);
        } catch (Exception e) {
            throw new JspException("Error encoding component", e);
        }
        return EVAL_PAGE;
    }

    protected void encodeBegin(ResponseWriter writer) throws Exception {
        writer.startElement("div", component);
        writer.writeAttribute("id", component.getClientId(), "id");
    }

    protected void encodeChildren(ResponseWriter writer) throws Exception {
        for (UIComponent child : component.getChildren()) {
            child.encodeAll(FacesContext.getCurrentInstance());
        }
    }

    protected void encodeEnd(ResponseWriter writer) throws Exception {
        writer.endElement("div");
    }

    @Override
    public void release() {
        super.release();
        id = null;
        binding = null;
        rendered = true;
        component = null;
    }

    public void setId(String id) {
        this.id = id;
    }

    public void setBinding(String binding) {
        this.binding = binding;
    }

    public void setRendered(boolean rendered) {
        this.rendered = rendered;
    }
}

