public class ConnectionDotFileInterceptor extends DotFileInterceptorSupport {
    private final ConcurrentHashMap<String, Producer> producers = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Consumer> consumers = new ConcurrentHashMap<>();
    private final ReentrantLock lock = new ReentrantLock();
    private boolean clearCacheAfterRender = false;

    public void addProducer(String producerId, Producer producer) {
        lock.lock();
        try {
            producers.put(producerId, producer);
            updateDotRepresentation();
        } finally {
            lock.unlock();
        }
    }

    public void removeProducer(String producerId) {
        lock.lock();
        try {
            producers.remove(producerId);
            updateDotRepresentation();
        } finally {
            lock.unlock();
        }
    }

    public void addConsumer(String consumerId, Consumer consumer) {
        lock.lock();
        try {
            consumers.put(consumerId, consumer);
            updateDotRepresentation();
        } finally {
            lock.unlock();
        }
    }

    public void removeConsumer(String consumerId) {
        lock.lock();
        try {
            consumers.remove(consumerId);
            updateDotRepresentation();
        } finally {
            lock.unlock();
        }
    }

    public String generateDotFile() {
        lock.lock();
        try {
            StringBuilder dotBuilder = new StringBuilder();
            dotBuilder.append("digraph ActiveMQ {\n");
            formatProducers(dotBuilder);
            formatConsumers(dotBuilder);
            dotBuilder.append("}\n");
            if (clearCacheAfterRender) {
                clearCaches();
            }
            return dotBuilder.toString();
        } finally {
            lock.unlock();
        }
    }

    private void formatProducers(StringBuilder dotBuilder) {
        for (Producer producer : producers.values()) {
            dotBuilder.append("  ").append(producer.getId()).append(" [label=\"").append(producer.getAttributes()).append("\"];\n");
        }
    }

    private void formatConsumers(StringBuilder dotBuilder) {
        for (Consumer consumer : consumers.values()) {
            dotBuilder.append("  ").append(consumer.getId()).append(" [label=\"").append(consumer.getAttributes()).append("\"];\n");
        }
    }

    private void clearCaches() {
        producers.clear();
        consumers.clear();
    }

    public void setClearCacheAfterRender(boolean clearCacheAfterRender) {
        this.clearCacheAfterRender = clearCacheAfterRender;
    }

    private void updateDotRepresentation() {
        // Logic to update the DOT representation if needed
    }
}

