        System.out.println("testRemoveNode duration: " + (endTime - startTime) + "ms");

        assertFalse(dataAccessor.exists(path));
    }

    @Test
    public void testVersionMismatch() throws Exception {
        long startTime = System.currentTimeMillis();
        String path = "/testNode";
        ZNRecord record = new ZNRecord("testRecord");
        dataAccessor.create(path, record);

        ZNRecord updatedRecord = new ZNRecord("updatedRecord");
        dataAccessor.update(path, updatedRecord);

        try {
            dataAccessor.update(path, record); // This should fail due to version mismatch
            fail("Expected version mismatch exception not thrown");
        } catch (VersionMismatchException e) {
            // Expected exception
        }
        long endTime = System.currentTimeMillis();
        System.out.println("testVersionMismatch duration: " + (endTime - startTime) + "ms");
    }

    @Test
