public class LovinsStemmer extends SnowballProgram {
    private static final Among[] a_0 = {
        new Among("ed", -1, 1),
        new Among("ing", -1, 1),
        new Among("es", -1, 1),
        new Among("s", -1, 1)
    };

    private static final Among[] a_1 = {
        new Among("ational", -1, 1),
        new Among("tional", -1, 1),
        new Among("al", -1, 1)
    };

    private static final Among[] a_2 = {
        new Among("y", -1, 1),
        new Among("ly", -1, 1),
        new Among("ily", -1, 1)
    };

    private int currentIndex;

    public LovinsStemmer() {
        super();
    }

    public String stem(String word) {
        setCurrent(word);
        currentIndex = 0;
        if (stemSuffixes()) {
            handleDoubleLetters();
            modifyWordForms();
        }
        return getCurrent();
    }

    private boolean stemSuffixes() {
        for (Among suffix : a_0) {
            if (endsWith(suffix.getString())) {
                removeSuffix(suffix.getString());
                return true;
            }
        }
        return false;
    }

    private void handleDoubleLetters() {
        if (currentIndex > 1 && getCurrent().charAt(currentIndex - 1) == getCurrent().charAt(currentIndex - 2)) {
            removeLastCharacter();
        }
    }

    private void modifyWordForms() {
        for (Among pattern : a_1) {
            if (endsWith(pattern.getString())) {
                replaceSuffix(pattern.getString(), "e");
            }
        }
    }

    private void removeSuffix(String suffix) {
        setCurrent(getCurrent().substring(0, getCurrent().length() - suffix.length()));
    }

    private void removeLastCharacter() {
        setCurrent(getCurrent().substring(0, getCurrent().length() - 1));
    }

    private void replaceSuffix(String oldSuffix, String newSuffix) {
        setCurrent(getCurrent().substring(0, getCurrent().length() - oldSuffix.length()) + newSuffix);
    }

    private boolean endsWith(String suffix) {
        return getCurrent().endsWith(suffix);
    }
}

