public class CachedOutputStream extends OutputStream {
    private ByteArrayOutputStream memoryCache;
    private File tempFile;
    private OutputStream fileOutputStream;
    private long threshold;
    private long maxSize;
    private List<Runnable> flushCallbacks;
    private List<Runnable> closeCallbacks;

    public CachedOutputStream(long threshold, long maxSize) {
        this.threshold = threshold;
        this.maxSize = maxSize;
        this.memoryCache = new ByteArrayOutputStream();
        this.flushCallbacks = new ArrayList<>();
        this.closeCallbacks = new ArrayList<>();
    }

    @Override
    public void write(int b) throws IOException {
        if (memoryCache.size() < threshold) {
            memoryCache.write(b);
        } else {
            if (fileOutputStream == null) {
                createTempFile();
            }
            fileOutputStream.write(b);
        }
        enforceSizeLimit();
    }

    private void createTempFile() throws IOException {
        tempFile = File.createTempFile("cachedOutput", ".tmp");
        fileOutputStream = new FileOutputStream(tempFile);
    }

    private void enforceSizeLimit() throws IOException {
        if (tempFile != null && tempFile.length() > maxSize) {
            throw new IOException("Exceeded maximum size limit");
        }
    }

    @Override
    public void flush() throws IOException {
        if (fileOutputStream != null) {
            fileOutputStream.flush();
        }
        for (Runnable callback : flushCallbacks) {
            callback.run();
        }
    }

    @Override
    public void close() throws IOException {
        flush();
        if (fileOutputStream != null) {
            fileOutputStream.close();
        }
        for (Runnable callback : closeCallbacks) {
            callback.run();
        }
        if (tempFile != null && tempFile.exists()) {
            tempFile.delete();
        }
    }

    public InputStream getInputStream() throws IOException {
        if (fileOutputStream != null) {
            fileOutputStream.close();
        }
        return new ByteArrayInputStream(memoryCache.toByteArray());
    }

    public byte[] toByteArray() {
        return memoryCache.toByteArray();
    }

    public void registerFlushCallback(Runnable callback) {
        flushCallbacks.add(callback);
    }

    public void deregisterFlushCallback(Runnable callback) {
        flushCallbacks.remove(callback);
    }

    public void registerCloseCallback(Runnable callback) {
        closeCallbacks.add(callback);
    }

    public void deregisterCloseCallback(Runnable callback) {
        closeCallbacks.remove(callback);
    }
}

