public abstract class XLinkPipe extends AbstractXMLPipe implements XLinkHandler {

    public static final String XLINK_NAMESPACE = "http://www.w3.org/1999/xlink";
    public static final String XLINK_TYPE = "type";
    public static final String XLINK_HREF = "href";
    public static final String XLINK_TITLE = "title";
    public static final String XLINK_ROLE = "role";
    public static final String XLINK_ARC = "arc";
    public static final String XLINK_LOCATOR = "locator";
    public static final String XLINK_RESOURCE = "resource";
    public static final String XLINK_EXTENDED = "extended";
    public static final String XLINK_SIMPLE = "simple";

    protected boolean inExtendedLink = false;

    public void startXLink(Element element) throws InvalidXLinkConfigurationException {
        String type = element.getAttribute(XLINK_TYPE);
        if (XLINK_SIMPLE.equals(type)) {
            processSimpleLink(element);
        } else if (XLINK_EXTENDED.equals(type)) {
            inExtendedLink = true;
            processExtendedLink(element);
        } else {
            throw new InvalidXLinkConfigurationException("Invalid XLink type: " + type);
        }
    }

    public void endXLink(Element element) throws InvalidXLinkConfigurationException {
        if (inExtendedLink) {
            inExtendedLink = false;
            processEndExtendedLink(element);
        } else {
            processEndSimpleLink(element);
        }
    }

    protected abstract void processSimpleLink(Element element) throws InvalidXLinkConfigurationException;

    protected abstract void processEndSimpleLink(Element element) throws InvalidXLinkConfigurationException;

    protected abstract void processExtendedLink(Element element) throws InvalidXLinkConfigurationException;

    protected abstract void processEndExtendedLink(Element element) throws InvalidXLinkConfigurationException;

    public static class InvalidXLinkConfigurationException extends Exception {
        public InvalidXLinkConfigurationException(String message) {
            super(message);
        }
    }
}

public class ItemValidator {
    private static final Logger logger = Logger.getLogger(ItemValidator.class.getName());
    private LockManager lockManager;
    private AccessManager accessManager;
    private RetentionRegistry retentionRegistry;

    public ItemValidator(LockManager lockManager, AccessManager accessManager, RetentionRegistry retentionRegistry) {
        this.lockManager = lockManager;
        this.accessManager = accessManager;
        this.retentionRegistry = retentionRegistry;
    }

    public void validateNode(Node node) throws ValidationException {
        if (node == null) {
            logger.severe("Node is null");
            throw new ValidationException("Node cannot be null");
        }
        checkPendingChanges(node);
        checkAccess(node);
        checkLocks(node);
        checkHolds(node);
        checkRetentionPolicies(node);
        checkMandatoryProperties(node);
        checkChildNodes(node);
    }

    public void validateProperty(Property property) throws ValidationException {
        if (property == null) {
            logger.severe("Property is null");
            throw new ValidationException("Property cannot be null");
        }
        checkAccess(property);
        checkMandatoryProperties(property);
    }

    private void checkPendingChanges(Node node) throws ValidationException {
        if (node.hasPendingChanges()) {
            logger.warning("Node has pending changes");
            throw new ValidationException("Node has pending changes");
        }
    }

    private void checkAccess(Node node) throws ValidationException {
        if (!accessManager.hasAccess(node)) {
            logger.warning("Access denied for node: " + node.getId());
            throw new ValidationException("Access denied");
        }
    }

    private void checkLocks(Node node) throws ValidationException {
        if (lockManager.isLocked(node)) {
            logger.warning("Node is locked: " + node.getId());
            throw new ValidationException("Node is locked");
        }
    }

    private void checkHolds(Node node) throws ValidationException {
        if (node.isOnHold()) {
            logger.warning("Node is on hold: " + node.getId());
            throw new ValidationException("Node is on hold");
        }
    }

    private void checkRetentionPolicies(Node node) throws ValidationException {
        if (retentionRegistry.isUnderRetention(node)) {
            logger.warning("Node is under retention: " + node.getId());
            throw new ValidationException("Node is under retention");
        }
    }

    private void checkMandatoryProperties(Node node) throws ValidationException {
        // Check for mandatory properties logic
    }

    private void checkChildNodes(Node node) throws ValidationException {
        // Check for required child nodes logic
    }

    private void checkMandatoryProperties(Property property) throws ValidationException {
        // Check for mandatory properties logic
    }
}

