public class InputBuffer {
    private final InputStream input;
    private final byte[] buffer;
    private int position;
    private int limit;

    public InputBuffer(InputStream input, int bufferSize) {
        this.input = input;
        this.buffer = new byte[bufferSize];
        this.position = 0;
        this.limit = 0;
    }

    public void seek(int newPosition) throws IOException {
        if (newPosition < 0) throw new IOException("Position out of bounds");
        if (newPosition >= limit) {
            input.skip(newPosition - limit);
            limit = input.read(buffer);
            position = 0;
        } else {
            position = newPosition;
        }
    }

    public int tell() {
        return position;
    }

    public boolean readBoolean() throws IOException {
        return readByte() != 0;
    }

    public byte readByte() throws IOException {
        if (position >= limit) {
            limit = input.read(buffer);
            position = 0;
            if (limit == -1) throw new IOException("End of stream");
        }
        return buffer[position++];
    }

    public int readInt() throws IOException {
        return ByteBuffer.wrap(readBytes(4)).getInt();
    }

    public String readString() throws IOException {
        int length = readInt();
        return new String(readBytes(length));
    }

    public byte[] readBytes(int length) throws IOException {
        byte[] bytes = new byte[length];
        int bytesRead = 0;
        while (bytesRead < length) {
            int result = read(bytes, bytesRead, length - bytesRead);
            if (result == -1) throw new IOException("End of stream");
            bytesRead += result;
        }
        return bytes;
    }

    private int read(byte[] b, int off, int len) throws IOException {
        if (position >= limit) {
            limit = input.read(buffer);
            position = 0;
            if (limit == -1) return -1;
        }
        int bytesToRead = Math.min(len, limit - position);
        System.arraycopy(buffer, position, b, off, bytesToRead);
        position += bytesToRead;
        return bytesToRead;
    }

    public void skip(int n) throws IOException {
        if (n < 0) throw new IOException("Negative skip not allowed");
        while (n > 0) {
            int bytesSkipped = (int) input.skip(n);
            if (bytesSkipped == 0) break;
            n -= bytesSkipped;
        }
    }

    public int readVarInt() throws IOException {
        int result = 0;
        int shift = 0;
        while (true) {
            byte b = readByte();
            result |= (b & 0x7F) << shift;
            if ((b & 0x80) == 0) break;
            shift += 7;
            if (shift > 28) throw new IOException("VarInt is too long");
        }
        return result;
    }

    public void close() throws IOException {
        input.close();
    }
}

public class FiniteDifferencesDifferentiatorTest {

    @Test
    public void testInputValidation() {
        FiniteDifferencesDifferentiator differentiator = new FiniteDifferencesDifferentiator();

        assertThrows(IllegalArgumentException.class, () -> {
            differentiator.differentiate(new double[]{1.0}, 0.1);
        });

        assertThrows(IllegalArgumentException.class, () -> {
            differentiator.differentiate(new double[]{1.0, 2.0}, -0.1);
        });
    }

    @Test
    public void testSerialization() throws IOException, ClassNotFoundException {
        FiniteDifferencesDifferentiator original = new FiniteDifferencesDifferentiator();
        ByteArrayOutputStream byteOut = new ByteArrayOutputStream();
        ObjectOutputStream out = new ObjectOutputStream(byteOut);
        out.writeObject(original);
        out.flush();

        ByteArrayInputStream byteIn = new ByteArrayInputStream(byteOut.toByteArray());
        ObjectInputStream in = new ObjectInputStream(byteIn);
        FiniteDifferencesDifferentiator deserialized = (FiniteDifferencesDifferentiator) in.readObject();

        assertEquals(original, deserialized);
    }

    @Test
    public void testDifferentiationOfFunctions() {
        FiniteDifferencesDifferentiator differentiator = new FiniteDifferencesDifferentiator();

        double[] constantFunction = {5.0, 5.0, 5.0};
        double[] linearFunction = {1.0, 2.0, 3.0};
        double[] gaussianFunction = {Math.exp(-1.0), Math.exp(-0.5), Math.exp(0)};
        double[] quinticFunction = {0.0, 1.0, 32.0};

        assertArrayEquals(new double[]{0.0, 0.0, 0.0}, differentiator.differentiate(constantFunction, 0.1));
        assertArrayEquals(new double[]{1.0, 1.0, 1.0}, differentiator.differentiate(linearFunction, 0.1));
        assertArrayEquals(new double[]{0.5 * Math.exp(-0.5), Math.exp(-0.5), 0.5 * Math.exp(0)}, differentiator.differentiate(gaussianFunction, 0.1));
        assertArrayEquals(new double[]{0.0, 10.0, 60.0}, differentiator.differentiate(quinticFunction, 0.1));
    }

    @Test
    public void testErrorHandling() {
        FiniteDifferencesDifferentiator differentiator = new FiniteDifferencesDifferentiator();

        assertThrows(IllegalArgumentException.class, () -> {
            differentiator.differentiate(new double[]{1.0, 2.0, 3.0}, 0.0);
        });

        assertThrows(IllegalArgumentException.class, () -> {
            differentiator.differentiate(new double[]{1.0, 2.0, 3.0}, 0.1, 5);
        });
    }

    @Test
    public void testBoundaryConditions() {
        FiniteDifferencesDifferentiator differentiator = new FiniteDifferencesDifferentiator();

        double[] outOfBoundsFunction = {Double.NaN, Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY};
        assertThrows(IllegalArgumentException.class, () -> {
            differentiator.differentiate(outOfBoundsFunction, 0.1);
        });
    }

    @Test
    public void testVectorAndMatrixFunctions() {
        FiniteDifferencesDifferentiator differentiator = new FiniteDifferencesDifferentiator();

        double[][] matrixFunction = {
            {1.0, 2.0},
            {3.0, 4.0}
        };

        double[] result = differentiator.differentiate(matrixFunction, 0.1);
        assertNotNull(result);
    }

    @Test
    public void testMultipleFreeParameters() {
        FiniteDifferencesDifferentiator differentiator = new FiniteDifferencesDifferentiator();

        double[] multiVarFunction = {Math.sin(0), Math.sin(0.1), Math.sin(0.2)};
        double[] result = differentiator.differentiate(multiVarFunction, 0.1);

        assertArrayEquals(new double[]{Math.cos(0), Math.cos(0.1), Math.cos(0.2)}, result, 1e-5);
    }
}

