public class StreamProducer extends DefaultProducer<Exchange> {
    private static final Logger LOG = LoggerFactory.getLogger(StreamProducer.class);
    private final String uri;
    private OutputStream outputStream;

    public StreamProducer(String uri) {
        super(null);
        this.uri = uri;
        validateUri();
        this.outputStream = resolveOutputStream();
    }

    private void validateUri() {
        if (!uri.matches("^(out|err|file|header|url):.*")) {
            throw new IllegalArgumentException("Invalid URI: " + uri);
        }
    }

    private OutputStream resolveOutputStream() {
        try {
            if (uri.startsWith("file:")) {
                return new FileOutputStream(new File(uri.substring(5)));
            } else if (uri.startsWith("url:")) {
                return createUrlOutputStream(uri.substring(4));
            } else if (uri.startsWith("header:")) {
                return System.out; // Simplified for example
            } else if (uri.equals("out")) {
                return System.out;
            } else if (uri.equals("err")) {
                return System.err;
            }
        } catch (IOException e) {
            LOG.error("Error resolving output stream for URI: " + uri, e);
        }
        return null;
    }

    private OutputStream createUrlOutputStream(String urlString) throws IOException {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setDoOutput(true);
        connection.setRequestMethod("POST");
        return connection.getOutputStream();
    }

    public void process(Exchange exchange) throws Exception {
        if (outputStream == null) {
            LOG.error("Output stream is not initialized.");
            return;
        }
        String data = exchange.getIn().getBody(String.class);
        writeData(data);
    }

    private void writeData(String data) {
        try {
            outputStream.write(data.getBytes());
            outputStream.flush();
        } catch (IOException e) {
            LOG.error("Error writing data to output stream.", e);
        }
    }

    @Override
    protected void doStart() throws Exception {
        super.doStart();
        LOG.debug("StreamProducer started with URI: " + uri);
    }

    @Override
    protected void doStop() throws Exception {
        super.doStop();
        if (outputStream != null) {
            outputStream.close();
        }
        LOG.debug("StreamProducer stopped.");
    }
}

