public class DefaultTraversalMetrics implements TraversalMetrics, Serializable {
    private final Map<String, StepMetrics> metricsMap = new HashMap<>();
    private final AtomicLong totalDuration = new AtomicLong(0);
    private boolean finalized = false;

    public void setMetrics(String stepId, long duration, int count) {
        if (finalized) {
            throw new IllegalStateException("Metrics have been finalized and cannot be modified.");
        }
        metricsMap.computeIfAbsent(stepId, k -> new StepMetrics()).addMetrics(duration, count);
        totalDuration.addAndGet(duration);
    }

    public StepMetrics getMetrics(String stepId) {
        return metricsMap.get(stepId);
    }

    public long getTotalDuration() {
        return totalDuration.get();
    }

    public void finalizeMetrics() {
        finalized = true;
    }

    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Traversal Metrics:\n");
        metricsMap.forEach((stepId, metrics) -> sb.append(stepId).append(": ").append(metrics).append("\n"));
        sb.append("Total Duration: ").append(getTotalDuration()).append(" ms");
        return sb.toString();
    }

    public static class StepMetrics implements Serializable {
        private long duration;
        private int count;

        public void addMetrics(long duration, int count) {
            this.duration += duration;
            this.count += count;
        }

        public long getDuration() {
            return duration;
        }

        public int getCount() {
            return count;
        }

        public String toString() {
            return "Duration: " + duration + " ms, Count: " + count;
        }
    }
}

