public class ClassUtils {

    public static String getShortClassName(Class<?> clazz) {
        return clazz.getSimpleName();
    }

    public static String getPackageName(Class<?> clazz) {
        return clazz.getPackage().getName();
    }

    public static Class<?> getWrapperClass(Class<?> clazz) {
        if (clazz.isPrimitive()) {
            if (clazz == boolean.class) return Boolean.class;
            if (clazz == byte.class) return Byte.class;
            if (clazz == char.class) return Character.class;
            if (clazz == double.class) return Double.class;
            if (clazz == float.class) return Float.class;
            if (clazz == int.class) return Integer.class;
            if (clazz == long.class) return Long.class;
            if (clazz == short.class) return Short.class;
        }
        return clazz;
    }

    public static boolean isAssignable(Class<?> from, Class<?> to) {
        if (to.isAssignableFrom(from)) {
            return true;
        }
        if (from.isPrimitive() && to.isPrimitive()) {
            return false;
        }
        return getWrapperClass(from).isAssignableFrom(getWrapperClass(to));
    }

    public static boolean isInnerClass(Class<?> clazz) {
        return clazz.getEnclosingClass() != null;
    }

    public static List<Class<?>> getAllSuperclassesAndInterfaces(Class<?> clazz) {
        List<Class<?>> classes = new ArrayList<>();
        while (clazz != null) {
            classes.add(clazz);
            clazz = clazz.getSuperclass();
        }
        return classes;
    }

    public static List<Class<?>> classNamesToClasses(List<String> classNames) throws ClassNotFoundException {
        List<Class<?>> classes = new ArrayList<>();
        for (String className : classNames) {
            classes.add(Class.forName(className));
        }
        return classes;
    }

    public static List<String> classesToClassNames(List<Class<?>> classes) {
        List<String> classNames = new ArrayList<>();
        for (Class<?> clazz : classes) {
            classNames.add(clazz.getName());
        }
        return classNames;
    }

    public static List<Method> getPublicMethods(Class<?> clazz) {
        List<Method> methods = new ArrayList<>();
        while (clazz != null) {
            methods.addAll(Arrays.asList(clazz.getDeclaredMethods()));
            clazz = clazz.getSuperclass();
        }
        return methods;
    }

    public static Class<?> loadClass(String className) throws ClassNotFoundException {
        return Class.forName(className);
    }

    public static Iterable<Class<?>> getClassHierarchy(Class<?> clazz, boolean includeInterfaces) {
        List<Class<?>> hierarchy = new ArrayList<>();
        while (clazz != null) {
            hierarchy.add(clazz);
            if (includeInterfaces) {
                Class<?>[] interfaces = clazz.getInterfaces();
                hierarchy.addAll(Arrays.asList(interfaces));
            }
            clazz = clazz.getSuperclass();
        }
        return hierarchy;
    }
}

