public class OutputBuffer extends ByteArrayOutputStream {
    private static final int BOOLEAN_SIZE = 1;
    private static final int INT_SIZE = 4;
    private static final int LONG_SIZE = 8;
    private static final int FLOAT_SIZE = 4;
    private static final int DOUBLE_SIZE = 8;

    public OutputBuffer() {
        super();
    }

    public void writeBoolean(boolean value) {
        ensureCapacity(BOOLEAN_SIZE);
        write(value ? 1 : 0);
    }

    public void writeInt(int value) {
        ensureCapacity(INT_SIZE);
        write(ByteBuffer.allocate(INT_SIZE).putInt(value).array());
    }

    public void writeLong(long value) {
        ensureCapacity(LONG_SIZE);
        write(ByteBuffer.allocate(LONG_SIZE).putLong(value).array());
    }

    public void writeFloat(float value) {
        ensureCapacity(FLOAT_SIZE);
        write(ByteBuffer.allocate(FLOAT_SIZE).putFloat(value).array());
    }

    public void writeDouble(double value) {
        ensureCapacity(DOUBLE_SIZE);
        write(ByteBuffer.allocate(DOUBLE_SIZE).putDouble(value).array());
    }

    public void writeString(String value) {
        byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
        writeInt(bytes.length);
        ensureCapacity(bytes.length);
        write(bytes);
    }

    public void writeBytes(byte[] bytes) {
        ensureCapacity(bytes.length);
        write(bytes);
    }

    public boolean isFull(int size) {
        return count + size > buf.length;
    }

    public ByteBuffer toByteBuffer() {
        return ByteBuffer.wrap(buf, 0, count);
    }

    private void ensureCapacity(int size) {
        if (isFull(size)) {
            // This is a code smell; ideally, we should handle resizing more gracefully.
            byte[] newBuffer = new byte[buf.length + size];
            System.arraycopy(buf, 0, newBuffer, 0, count);
            buf = newBuffer;
        }
    }
}

