public final class AvroConfigurationSerializer implements ConfigurationSerializer {

    private final Schema schema;

    public AvroConfigurationSerializer(Schema schema) {
        this.schema = schema;
    }

    @Override
    public byte[] serialize(Map<String, Object> configuration) throws IOException {
        GenericData.Record record = new GenericData.Record(schema);
        for (Map.Entry<String, Object> entry : configuration.entrySet()) {
            record.put(entry.getKey(), entry.getValue());
        }
        DatumWriter<GenericData.Record> writer = new SpecificDatumWriter<>(schema);
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Encoder encoder = EncoderFactory.get().binaryEncoder(outputStream, null);
        writer.write(record, encoder);
        encoder.flush();
        return outputStream.toByteArray();
    }

    @Override
    public Map<String, Object> deserialize(byte[] data) throws IOException {
        DatumReader<GenericData.Record> reader = new SpecificDatumReader<>(schema);
        Decoder decoder = DecoderFactory.get().binaryDecoder(data, null);
        GenericData.Record record = reader.read(null, decoder);
        return recordToMap(record);
    }

    @Override
    public void writeToFile(Map<String, Object> configuration, File file) throws IOException {
        byte[] data = serialize(configuration);
        try (FileOutputStream fos = new FileOutputStream(file)) {
            fos.write(data);
        }
    }

    @Override
    public Map<String, Object> readFromFile(File file) throws IOException {
        byte[] data = new byte[(int) file.length()];
        try (FileInputStream fis = new FileInputStream(file)) {
            fis.read(data);
        }
        return deserialize(data);
    }

    private Map<String, Object> recordToMap(GenericData.Record record) {
