public class ConfigurationWriter {
    private BrowserConnection browserConnection;
    private OpenLDAPConfig openLDAPConfig;

    public ConfigurationWriter(BrowserConnection browserConnection, OpenLDAPConfig openLDAPConfig) {
        this.browserConnection = browserConnection;
        this.openLDAPConfig = openLDAPConfig;
    }

    public String convertToLDIF() {
        StringBuilder ldifBuilder = new StringBuilder();
        List<ConfigurationBean> configBeans = openLDAPConfig.getConfigurationBeans();

        for (ConfigurationBean bean : configBeans) {
            ldifBuilder.append(createLDIFEntry(bean));
        }

        return ldifBuilder.toString();
    }

    private String createLDIFEntry(ConfigurationBean bean) {
        StringBuilder entryBuilder = new StringBuilder();
        entryBuilder.append("dn: ").append(bean.getDistinguishedName()).append("\n");
        entryBuilder.append("objectClass: ").append(String.join("\nobjectClass: ", bean.getObjectClasses())).append("\n");
        entryBuilder.append("cn: ").append(bean.getCommonName()).append("\n");

        for (String attribute : bean.getAttributes()) {
            entryBuilder.append(attribute).append(": ").append(bean.getAttributeValue(attribute)).append("\n");
        }

        entryBuilder.append("\n");
        return entryBuilder.toString();
    }

    public void writeToFile(String filePath) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(filePath))) {
            writer.write(convertToLDIF());
        } catch (IOException e) {
            handleError(e);
        }
    }

    private void handleError(Exception e) {
        System.err.println("Error during configuration conversion or file writing: " + e.getMessage());
    }
}

