public class SwappablePriorityQueue {
    private final PriorityQueue<FlowFileRecord> activeQueue;
    private final PriorityQueue<FlowFileRecord> swapQueue;
    private final FlowFileSwapManager swapManager;
    private final int threshold;
    private final Lock lock = new ReentrantLock();

    public SwappablePriorityQueue(int threshold, FlowFileSwapManager swapManager) {
        this.activeQueue = new PriorityQueue<>();
        this.swapQueue = new PriorityQueue<>();
        this.threshold = threshold;
        this.swapManager = swapManager;
    }

    public void add(FlowFileRecord record) {
        lock.lock();
        try {
            if (activeQueue.size() >= threshold) {
                swapToDisk();
            }
            activeQueue.offer(record);
        } finally {
            lock.unlock();
        }
    }

    public FlowFileRecord poll() {
        lock.lock();
        try {
            if (activeQueue.isEmpty()) {
                recoverFromDisk();
            }
            return activeQueue.poll();
        } finally {
            lock.unlock();
        }
    }

    public void acknowledge(FlowFileRecord record) {
        lock.lock();
        try {
            activeQueue.remove(record);
            // Additional logic for acknowledgment can be added here
        } finally {
            lock.unlock();
        }
    }

    private void swapToDisk() {
        while (activeQueue.size() > threshold) {
            FlowFileRecord record = activeQueue.poll();
            swapQueue.offer(record);
            swapManager.swap(record);
        }
    }

    private void recoverFromDisk() {
        while (!swapQueue.isEmpty() && activeQueue.size() < threshold) {
            FlowFileRecord record = swapQueue.poll();
            activeQueue.offer(record);
            swapManager.recover(record);
        }
    }

    public void drop(FlowFileRecord record) {
        lock.lock();
        try {
            if (activeQueue.remove(record)) {
                // Record dropped from active queue
            } else {
                swapQueue.remove(record);
                // Record dropped from swap queue
            }
        } finally {
            lock.unlock();
        }
    }

    public String diagnostics() {
        lock.lock();
        try {
            return "Active Queue Size: " + activeQueue.size() + ", Swap Queue Size: " + swapQueue.size();
        } finally {
            lock.unlock();
        }
    }
}

