public class ComposedRuleElement extends AbstractRuleElement implements RuleElementContainer {
    private List<RuleElement> ruleElements;
    private boolean isConjunctive;

    public ComposedRuleElement(boolean isConjunctive) {
        this.ruleElements = new ArrayList<>();
        this.isConjunctive = isConjunctive;
    }

    public void addRuleElement(RuleElement ruleElement) {
        ruleElements.add(ruleElement);
    }

    @Override
    public void applyRules(MatchContext context) {
        if (isConjunctive) {
            for (RuleElement element : ruleElements) {
                if (!element.startMatch(context)) {
                    return;
                }
            }
        } else {
            for (RuleElement element : ruleElements) {
                if (element.startMatch(context)) {
                    return;
                }
            }
        }
    }

    @Override
    public boolean startMatch(MatchContext context) {
        return applyRules(context);
    }

    @Override
    public boolean continueMatch(MatchContext context) {
        for (RuleElement element : ruleElements) {
            if (element.continueMatch(context)) {
                return true;
            }
        }
        return false;
    }

    public void mergeResults(MatchContext context) {
        for (RuleElement element : ruleElements) {
            element.mergeResults(context);
        }
    }

    public void evaluateConditions(MatchContext context) {
        for (RuleElement element : ruleElements) {
            element.evaluateConditions(context);
        }
    }

    public void handleFallback(MatchContext context) {
        for (RuleElement element : ruleElements) {
            element.handleFallback(context);
        }
    }

    public void applyInlinedRules(MatchContext context) {
        for (RuleElement element : ruleElements) {
            element.applyInlinedRules(context);
        }
    }
}

