public class XmlSnapshot implements Snapshot {
    private static final Logger logger = Logger.getLogger(XmlSnapshot.class.getName());
    private Document xmlDocument;
    private Document xsdDocument;
    private ObjectAdapter rootAdapter;

    public XmlSnapshot(ObjectAdapter rootAdapter) {
        this.rootAdapter = rootAdapter;
        initializeDocuments();
    }

    private void initializeDocuments() {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            xmlDocument = builder.newDocument();
            xsdDocument = builder.newDocument();
            logger.info("Documents initialized.");
        } catch (Exception e) {
            logger.severe("Error initializing documents: " + e.getMessage());
        }
    }

    public void createXmlRepresentation() {
        Element rootElement = xmlDocument.createElement(rootAdapter.getType());
        xmlDocument.appendChild(rootElement);
        appendFields(rootElement, rootAdapter);
        appendAssociations(rootElement, rootAdapter);
        logger.info("XML representation created.");
    }

    private void appendFields(Element parentElement, ObjectAdapter adapter) {
        for (String field : adapter.getFields()) {
            Element fieldElement = xmlDocument.createElement(field);
            fieldElement.setTextContent(adapter.getFieldValue(field));
            parentElement.appendChild(fieldElement);
            logger.fine("Field appended: " + field);
        }
    }

    private void appendAssociations(Element parentElement, ObjectAdapter adapter) {
        for (ObjectAdapter associated : adapter.getAssociations()) {
            Element associationElement = xmlDocument.createElement(associated.getType());
            parentElement.appendChild(associationElement);
            appendFields(associationElement, associated);
            logger.fine("Association appended: " + associated.getType());
        }
    }

    public String getXmlAsString() {
        return convertDocumentToString(xmlDocument);
    }

    public String getXsdAsString() {
        return convertDocumentToString(xsdDocument);
    }

    private String convertDocumentToString(Document doc) {
        try {
            TransformerFactory transformerFactory = TransformerFactory.newInstance();
            Transformer transformer = transformerFactory.newTransformer();
            transformer.setOutputProperty(OutputKeys.INDENT, "yes");
            DOMSource source = new DOMSource(doc);
            StreamResult result = new StreamResult(new StringWriter());
            transformer.transform(source, result);
            return result.getWriter().toString();
        } catch (Exception e) {
            logger.severe("Error converting document to string: " + e.getMessage());
            return null;
        }
    }
}

public class RendererFactory {
    private static final Logger logger = Logger.getLogger(RendererFactory.class.getName());
    private final Map<String, HandlerMaker> handlerMakers = new HashMap<>();
    private boolean preferRenderers = true;

    public void addHandlerMaker(String mimeType, HandlerMaker maker) {
        handlerMakers.put(mimeType, maker);
        logger.info("Added handler maker for MIME type: " + mimeType);
    }

    public Handler getHandler(String mimeType) {
        HandlerMaker maker = handlerMakers.get(mimeType);
        if (maker != null) {
            return maker.createHandler();
        }
        return null;
    }

    public Renderer createRenderer(String mimeType, String userAgent) {
        if (preferRenderers) {
            HandlerMaker maker = handlerMakers.get(mimeType);
            if (maker != null) {
                return maker.createRenderer(userAgent);
            }
        }
        return null;
    }

    public FOEventHandler createFOEventHandler(String mimeType) {
        HandlerMaker maker = handlerMakers.get(mimeType);
        if (maker != null) {
            return maker.createFOEventHandler();
        }
        return null;
    }

    public DocumentHandler createDocumentHandler(String mimeType) {
        HandlerMaker maker = handlerMakers.get(mimeType);
        if (maker != null) {
            return maker.createDocumentHandler();
        }
        return null;
    }

    public Set<String> listSupportedMimeTypes() {
        return handlerMakers.keySet();
    }

    public void setPreferRenderers(boolean preferRenderers) {
        this.preferRenderers = preferRenderers;
    }

    public interface HandlerMaker {
        Handler createHandler();
        Renderer createRenderer(String userAgent);
        FOEventHandler createFOEventHandler();
        DocumentHandler createDocumentHandler();
    }

    public interface Handler {}
    public interface Renderer {}
    public interface FOEventHandler {}
    public interface DocumentHandler {}
}

