    }

    public void initializeStyles(String hAlign, String vAlign, boolean wrap, int indent, Color fgColor, Color bgColor, String patColor, String dFormat) {
        this.horizontalAlignment = validateAndConvertAlignment(hAlign);
        this.verticalAlignment = validateAndConvertAlignment(vAlign);
        this.wrapText = wrap;
        this.indentation = indent;
        this.foregroundColor = fgColor;
        this.backgroundColor = bgColor;
        this.patternColor = patColor;
        this.dataFormat = dFormat;
    }

    private String validateAndConvertAlignment(String alignment) {
        if ("left".equalsIgnoreCase(alignment) || "center".equalsIgnoreCase(alignment) || "right".equalsIgnoreCase(alignment)) {
            return alignment.toLowerCase();
        }
        return "left"; // default alignment
    }

