public class ZkGrep {
    private String configFile;
    private List<String> patterns;
    private long startTime;
    private long endTime;

    public ZkGrep(String configFile, List<String> patterns, long startTime, long endTime) {
        this.configFile = configFile;
        this.patterns = patterns;
        this.startTime = startTime;
        this.endTime = endTime;
    }

    public static void main(String[] args) {
        if (args.length < 4) {
            printUsage();
            return;
        }
        String configFile = args[0];
        List<String> patterns = Arrays.asList(args[1].split(","));
        long startTime = Long.parseLong(args[2]);
        long endTime = Long.parseLong(args[3]);

        ZkGrep zkGrep = new ZkGrep(configFile, patterns, startTime, endTime);
        zkGrep.processLogs();
    }

    private void processLogs() {
        List<File> logFiles = getLogFiles();
        for (File logFile : logFiles) {
            try {
                processLogFile(logFile);
            } catch (IOException e) {
                System.err.println("Error processing file: " + logFile.getName());
            }
        }
    }

    private List<File> getLogFiles() {
        List<File> logFiles = new ArrayList<>();
        // Code smell: Reading configuration and file handling should be separated
        try {
            List<String> dataDirs = readDataDirectories(configFile);
            for (String dir : dataDirs) {
                Files.walk(Paths.get(dir))
                        .filter(Files::isRegularFile)
                        .forEach(path -> logFiles.add(path.toFile()));
            }
        } catch (IOException e) {
            System.err.println("Error reading data directories: " + e.getMessage());
        }
        return logFiles;
    }

    private List<String> readDataDirectories(String configFile) throws IOException {
        // Code smell: Hardcoded logic for reading config file
        List<String> dataDirs = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(configFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("dataDir=")) {
                    dataDirs.add(line.split("=")[1].trim());
                }
            }
        }
        return dataDirs;
    }

    private void processLogFile(File logFile) throws IOException {
        BufferedReader reader;
        if (logFile.getName().endsWith(".gz")) {
            reader = new BufferedReader(new InputStreamReader(new GZIPInputStream(new FileInputStream(logFile))));
        } else {
            reader = new BufferedReader(new FileReader(logFile));
        }

        String line;
        while ((line = reader.readLine()) != null) {
            long timestamp = extractTimestamp(line);
            if (timestamp >= startTime && timestamp <= endTime && matchesPatterns(line)) {
                System.out.println(line);
            }
        }
        reader.close();
    }

    private long extractTimestamp(String line) {
        // Code smell: Timestamp extraction logic is not robust
        // Assuming timestamp is at the start of the line
        String[] parts = line.split(" ");
        return Long.parseLong(parts[0]);
    }

    private boolean matchesPatterns(String line) {
        for (String pattern : patterns) {
            if (line.contains(pattern)) {
                return true;
            }
        }
        return false;
    }

    private static void printUsage() {
        System.out.println("Usage: ZkGrep <configFile> <patterns> <startTime> <endTime>");
        System.out.println("Example: ZkGrep zookeeper.cfg \"pattern1,pattern2\" 1622505600000 1622592000000");
    }
}

