public class TestXMLRecordReader {

    @Test
    public void testReadSimpleRecord() throws Exception {
        String xml = "<record><name>John Doe</name><age>30</age></record>";
        XMLRecordReader reader = new XMLRecordReader(new StringReader(xml));
        Record record = reader.readRecord();
        assertEquals("John Doe", record.get("name"));
        assertEquals("30", record.get("age"));
    }

    @Test
    public void testReadNestedRecord() throws Exception {
        String xml = "<record><person><name>Jane Doe</name><age>25</age></person></record>";
        XMLRecordReader reader = new XMLRecordReader(new StringReader(xml));
        Record record = reader.readRecord();
        assertEquals("Jane Doe", record.get("person.name"));
        assertEquals("25", record.get("person.age"));
    }

    @Test
    public void testReadRecordWithAttributes() throws Exception {
        String xml = "<record id='1'><name>John Doe</name></record>";
        XMLRecordReader reader = new XMLRecordReader(new StringReader(xml));
        Record record = reader.readRecord();
        assertEquals("1", record.get("id"));
        assertEquals("John Doe", record.get("name"));
    }

    @Test
    public void testReadRecordWithNamespace() throws Exception {
        String xml = "<ns:record xmlns:ns='http://example.com/ns'><ns:name>John Doe</ns:name></ns:record>";
        XMLRecordReader reader = new XMLRecordReader(new StringReader(xml));
        Record record = reader.readRecord();
        assertEquals("John Doe", record.get("ns:name"));
    }

    @Test
    public void testReadArrayOfRecords() throws Exception {
        String xml = "<records><record><name>John</name></record><record><name>Jane</name></record></records>";
        XMLRecordReader reader = new XMLRecordReader(new StringReader(xml));
        List<Record> records = reader.readRecords();
        assertEquals(2, records.size());
        assertEquals("John", records.get(0).get("name"));
        assertEquals("Jane", records.get(1).get("name"));
    }

    @Test
    public void testReadComplexNestedData() throws Exception {
        String xml = "<record><person><name>John</name><address><city>New York</city><zip>10001</zip></address></person></record>";
        XMLRecordReader reader = new XMLRecordReader(new StringReader(xml));
        Record record = reader.readRecord();
        assertEquals("John", record.get("person.name"));
        assertEquals("New York", record.get("person.address.city"));
        assertEquals("10001", record.get("person.address.zip"));
    }

