        assertEquals(FieldType.BOOLEAN, schema.getFieldType("field10"));
    }

    @Test
    public void testNestedSchema() {
        Schema nestedSchema = new Schema();
        nestedSchema.addField("nestedField1", FieldType.STRING);

        Schema mainSchema = new Schema();
        mainSchema.addField("mainField1", FieldType.INT32);
        mainSchema.addField("nested", nestedSchema);

        assertEquals(2, mainSchema.getFieldCount());
        assertEquals(FieldType.INT32, mainSchema.getFieldType("mainField1"));
        assertTrue(mainSchema.getFieldType("nested") instanceof Schema);
        assertEquals(1, ((Schema) mainSchema.getFieldType("nested")).getFieldCount());
    }

    @Test
    public void testArraySchema() {
        Schema arraySchema = new Schema();
        arraySchema.addField("arrayField", FieldType.ARRAY);

        Schema mainSchema = new Schema();
        mainSchema.addField("mainField", arraySchema);

        assertEquals(1, mainSchema.getFieldCount());
        assertEquals(FieldType.ARRAY, mainSchema.getFieldType("mainField"));
    }

    @Test
    public void testMapSchema() {
        Schema mapSchema = new Schema();
        mapSchema.addField("mapField", FieldType.MAP);

        Schema mainSchema = new Schema();
        mainSchema.addField("mainField", mapSchema);

        assertEquals(1, mainSchema.getFieldCount());
        assertEquals(FieldType.MAP, mainSchema.getFieldType("mainField"));
    }

    @Test
    public void testInvalidFieldAccess() {
        Schema schema = new Schema();
        schema.addField("field1", FieldType.STRING);

        assertThrows(IllegalArgumentException.class, () -> {
            schema.getFieldType("nonExistentField");
        });
    }

    @Test
    public void testSchemaEquivalence() {
        Schema schema1 = new Schema();
        schema1.addField("field1", FieldType.STRING);
        schema1.addField("field2", FieldType.INT32);

        Schema schema2 = new Schema();
        schema2.addField("field1", FieldType.STRING);
        schema2.addField("field2", FieldType.INT32);

        Schema schema3 = new Schema();
        schema3.addField("field1", FieldType.STRING);
        schema3.addField("field2", FieldType.FLOAT);

        assertTrue(schema1.equals(schema2));
        assertFalse(schema1.equals(schema3));
    }
