public class EmailValidatorTest extends TestCase {

    private EmailValidator emailValidator;

    @Override
    protected void setUp() throws Exception {
        super.setUp();
        emailValidator = new EmailValidator();
    }

    public void testBasicEmailFormat() {
        assertTrue(emailValidator.isValid("test@example.com"));
        assertFalse(emailValidator.isValid("invalid-email"));
    }

    public void testNumericAddresses() {
        assertTrue(emailValidator.isValid("12345@example.com"));
        assertFalse(emailValidator.isValid("12345@.com"));
    }

    public void testDifferentDomainExtensions() {
        assertTrue(emailValidator.isValid("user@domain.co.uk"));
        assertTrue(emailValidator.isValid("user@domain.info"));
        assertFalse(emailValidator.isValid("user@domain..com"));
    }

    public void testSpecialCharacters() {
        assertTrue(emailValidator.isValid("user.name+tag+sorting@example.com"));
        assertTrue(emailValidator.isValid("user-name@example.com"));
        assertFalse(emailValidator.isValid("user@domain,com"));
    }

    public void testControlCharacters() {
        assertFalse(emailValidator.isValid("user@exa\0mple.com"));
        assertFalse(emailValidator.isValid("user@exa\nmple.com"));
    }

    public void testInvalidFormats() {
        assertFalse(emailValidator.isValid("user@.com"));
        assertFalse(emailValidator.isValid("@example.com"));
        assertFalse(emailValidator.isValid("user@domain..com"));
    }

    public void testValidLocalHostAddresses() {
        assertTrue(emailValidator.isValid("user@localhost"));
        assertFalse(emailValidator.isValid("user@localhost."));
    }

    public void testEmailUsernamesWithSpecialCharacters() {
        assertTrue(emailValidator.isValid("user!#$%&'*+/=?^_`{|}~@example.com"));
        assertFalse(emailValidator.isValid("user@domain..com"));
    }

    public void testPerlEmailCases() {
        String[] validEmails = {
            "test@example.com",
            "user.name@sub.domain.com",
            "user+tag@domain.com"
        };
        String[] invalidEmails = {
            "plainaddress",
            "@missingusername.com",
            "username@.com"
        };

        for (String email : validEmails) {
            assertTrue(emailValidator.isValid(email));
        }
        for (String email : invalidEmails) {
            assertFalse(emailValidator.isValid(email));
        }
    }

    public void testValidatorRulesAndEdgeCases() {
        assertTrue(emailValidator.isValid("user@domain.com"));
        assertFalse(emailValidator.isValid("user@domain..com"));
        assertFalse(emailValidator.isValid("user@-domain.com"));
        assertFalse(emailValidator.isValid("user@domain-.com"));
    }
}

