public class JavaCharStream {
    private char[] buffer;
    private int bufferSize;
    private int bufferIndex;
    private int line;
    private int column;
    private Reader reader;
    private InputStream inputStream;
    private boolean isReader;

    public JavaCharStream(Reader reader) {
        this.reader = reader;
        this.isReader = true;
        initBuffer();
    }

    public JavaCharStream(InputStream inputStream) {
        this.inputStream = inputStream;
        this.isReader = false;
        initBuffer();
    }

    private void initBuffer() {
        bufferSize = 1024;
        buffer = new char[bufferSize];
        bufferIndex = 0;
        line = 1;
        column = 0;
    }

    public char readChar() throws IOException {
        if (bufferIndex >= buffer.length) {
            expandBuffer();
        }
        int read = isReader ? reader.read(buffer, bufferIndex, buffer.length - bufferIndex) : inputStream.read();
        if (read == -1) {
            return (char) -1;
        }
        char ch = buffer[bufferIndex++];
        updatePosition(ch);
        return ch;
    }

    private void expandBuffer() {
        char[] newBuffer = new char[buffer.length * 2];
        System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
        buffer = newBuffer;
    }

    private void updatePosition(char ch) {
        column++;
        if (ch == '\n') {
            line++;
            column = 0;
        }
    }

    public int getLine() {
        return line;
    }

    public int getColumn() {
        return column;
    }

    public String getImage() {
        return new String(buffer, 0, bufferIndex);
    }

    public void backup(int amount) {
        bufferIndex -= amount;
    }

    public void reinitialize(Reader newReader) {
        this.reader = newReader;
        initBuffer();
    }

    public void reinitialize(InputStream newInputStream) {
        this.inputStream = newInputStream;
        initBuffer();
    }

    public void close() throws IOException {
        if (isReader) {
            reader.close();
        } else {
            inputStream.close();
        }
    }
}

public class ConcatBundleResource extends AbstractResource implements IStaticCacheableResource {
    private List<AbstractResource> resources = new ArrayList<>();
    private boolean cachingEnabled = true;
    private Compressor compressor;

    public ConcatBundleResource(List<AbstractResource> resources) {
        this.resources = resources;
    }

    @Override
    public ResourceResponse getResourceResponse() {
        ResourceResponse response = new ResourceResponse();
        try {
            response.setContentType(getContentType());
            response.setLastModified(getLastModified());
            response.setData(getCombinedData());
            if (cachingEnabled) {
                response.setCacheable(true);
            }
        } catch (IOException e) {
            handleError(e);
        }
        return response;
    }

    private InputStream getCombinedData() throws IOException {
