public class BeamSqlMathUnaryExpressionTest {

    @Test
    public void testAbs() {
        List<Double> operands = Arrays.asList(-1.0, 0.0, 1.0);
        List<Double> expected = Arrays.asList(1.0, 0.0, 1.0);
        testUnaryFunction(operands, expected, "ABS");
    }

    @Test
    public void testLog() {
        List<Double> operands = Arrays.asList(1.0, Math.E, Math.pow(10, 2));
        List<Double> expected = Arrays.asList(0.0, 1.0, 2.0);
        testUnaryFunction(operands, expected, "LOG");
    }

    @Test
    public void testLog10() {
        List<Double> operands = Arrays.asList(1.0, 10.0, 100.0);
        List<Double> expected = Arrays.asList(0.0, 1.0, 2.0);
        testUnaryFunction(operands, expected, "LOG10");
    }

    @Test
    public void testExp() {
        List<Double> operands = Arrays.asList(0.0, 1.0, 2.0);
        List<Double> expected = Arrays.asList(1.0, Math.E, Math.exp(2));
        testUnaryFunction(operands, expected, "EXP");
    }

    @Test
    public void testSin() {
        List<Double> operands = Arrays.asList(0.0, Math.PI / 2, Math.PI);
        List<Double> expected = Arrays.asList(0.0, 1.0, 0.0);
        testUnaryFunction(operands, expected, "SIN");
    }

    @Test
    public void testCos() {
        List<Double> operands = Arrays.asList(0.0, Math.PI / 2, Math.PI);
        List<Double> expected = Arrays.asList(1.0, 0.0, -1.0);
        testUnaryFunction(operands, expected, "COS");
    }

    @Test
    public void testTan() {
        List<Double> operands = Arrays.asList(0.0, Math.PI / 4, Math.PI / 2);
        List<Double> expected = Arrays.asList(0.0, 1.0, Double.POSITIVE_INFINITY);
        testUnaryFunction(operands, expected, "TAN");
    }

    @Test
    public void testDegrees() {
        List<Double> operands = Arrays.asList(0.0, Math.PI / 2, Math.PI);
        List<Double> expected = Arrays.asList(0.0, 90.0, 180.0);
        testUnaryFunction(operands, expected, "DEGREES");
    }

    @Test
    public void testRadians() {
        List<Double> operands = Arrays.asList(0.0, 90.0, 180.0);
        List<Double> expected = Arrays.asList(0.0, Math.PI / 2, Math.PI);
        testUnaryFunction(operands, expected, "RADIANS");
    }

    @Test
    public void testCeil() {
        List<Double> operands = Arrays.asList(1.1, 1.5, 1.9);
        List<Double> expected = Arrays.asList(2.0, 2.0, 2.0);
        testUnaryFunction(operands, expected, "CEIL");
    }

    @Test
    public void testFloor() {
        List<Double> operands = Arrays.asList(1.1, 1.5, 1.9);
        List<Double> expected = Arrays.asList(1.0, 1.0, 1.0);
        testUnaryFunction(operands, expected, "FLOOR");
    }

    @Test
    public void testSign() {
        List<Double> operands = Arrays.asList(-1.0, 0.0, 1.0);
        List<Double> expected = Arrays.asList(-1.0, 0.0, 1.0);
        testUnaryFunction(operands, expected, "SIGN");
    }

    private void testUnaryFunction(List<Double> operands, List<Double> expected, String functionName) {
        for (int i = 0; i < operands.size(); i++) {
            double result = applyUnaryFunction(operands.get(i), functionName);
            assertEquals(expected.get(i), result, 0.0001);
        }
    }

    private double applyUnaryFunction(double operand, String functionName) {
        switch (functionName) {
            case "ABS":
                return Math.abs(operand);
            case "LOG":
                return Math.log(operand);
            case "LOG10":
                return Math.log10(operand);
            case "EXP":
                return Math.exp(operand);
            case "SIN":
                return Math.sin(operand);
            case "COS":
                return Math.cos(operand);
            case "TAN":
                return Math.tan(operand);
            case "DEGREES":
                return Math.toDegrees(operand);
            case "RADIANS":
                return Math.toRadians(operand);
            case "CEIL":
                return Math.ceil(operand);
            case "FLOOR":
                return Math.floor(operand);
            case "SIGN":
                return Double.compare(operand, 0);
            default:
                throw new IllegalArgumentException("Unknown function: " + functionName);
        }
    }
}

