public class ExpressionJsonVisitor implements ExpressionVisitor<JsonNode> {

    @Override
    public JsonNode visitBinaryExpression(BinaryExpression expression) {
        ObjectNode json = createJsonNode("BinaryExpression");
        json.put("operator", expression.getOperator().toString());
        json.set("left", expression.getLeft().accept(this));
        json.set("right", expression.getRight().accept(this));
        return json;
    }

    @Override
    public JsonNode visitUnaryExpression(UnaryExpression expression) {
        ObjectNode json = createJsonNode("UnaryExpression");
        json.put("operator", expression.getOperator().toString());
        json.set("operand", expression.getOperand().accept(this));
        return json;
    }

    @Override
    public JsonNode visitMethodCall(MethodCallExpression expression) {
        ObjectNode json = createJsonNode("MethodCall");
        json.put("methodName", expression.getMethodName());
        for (Expression arg : expression.getArguments()) {
            json.set("arguments", arg.accept(this));
        }
        return json;
    }

    @Override
    public JsonNode visitLambdaExpression(LambdaExpression expression) {
        ObjectNode json = createJsonNode("LambdaExpression");
        json.set("body", expression.getBody().accept(this));
        return json;
    }

    @Override
    public JsonNode visitLiteral(LiteralExpression expression) {
        ObjectNode json = createJsonNode("Literal");
        json.put("value", expression.getValue().toString());
        return json;
    }

    @Override
    public JsonNode visitMember(MemberExpression expression) {
        ObjectNode json = createJsonNode("MemberExpression");
        json.put("memberName", expression.getMemberName());
        return json;
    }

    @Override
    public JsonNode visitAlias(AliasExpression expression) {
        ObjectNode json = createJsonNode("Alias");
        json.put("aliasName", expression.getAliasName());
        return json;
    }

    @Override
    public JsonNode visitTypeLiteral(TypeLiteralExpression expression) {
        ObjectNode json = createJsonNode("TypeLiteral");
        json.put("typeName", expression.getTypeName());
        return json;
    }

    @Override
    public JsonNode visitLambdaReference(LambdaReferenceExpression expression) {
        ObjectNode json = createJsonNode("LambdaReference");
        json.put("referenceName", expression.getReferenceName());
        return json;
    }

    @Override
    public JsonNode visitEnum(EnumExpression expression) {
        ObjectNode json = createJsonNode("Enum");
        json.put("enumName", expression.getEnumName());
        return json;
    }

    private ObjectNode createJsonNode(String type) {
        ObjectNode json = JsonNodeFactory.instance.objectNode();
        json.put("type", type);
        return json;
    }
}

