public class JSParser {
    private static final char SINGLE_LINE_COMMENT_START = '/';
    private static final char MULTI_LINE_COMMENT_START = '/';
    private static final char MULTI_LINE_COMMENT_END = '*';
    private static final char STRING_START = '"';
    private static final char REGEX_START = '/';
    private static final char WHITESPACE = ' ';
    private static final char NEWLINE = '\n';

    public static JSTokenList parse(char[] input) {
        JSTokenList tokens = new JSTokenList();
        int length = input.length;
        boolean inSingleLineComment = false;
        boolean inMultiLineComment = false;
        boolean inString = false;
        boolean inRegex = false;
        StringBuilder currentToken = new StringBuilder();

        for (int i = 0; i < length; i++) {
            char currentChar = input[i];

            if (inSingleLineComment) {
                if (currentChar == NEWLINE) {
                    tokens.add(new JSToken(currentToken.toString(), TokenType.COMMENT));
                    currentToken.setLength(0);
                    inSingleLineComment = false;
                } else {
                    currentToken.append(currentChar);
                }
                continue;
            }

            if (inMultiLineComment) {
                if (currentChar == MULTI_LINE_COMMENT_END && i + 1 < length && input[i + 1] == SINGLE_LINE_COMMENT_START) {
                    currentToken.append(currentChar);
                    tokens.add(new JSToken(currentToken.toString(), TokenType.COMMENT));
                    currentToken.setLength(0);
                    inMultiLineComment = false;
                    i++; // Skip the next character
                } else {
                    currentToken.append(currentChar);
                }
                continue;
            }

            if (inString) {
                if (currentChar == STRING_START) {
                    currentToken.append(currentChar);
                    tokens.add(new JSToken(currentToken.toString(), TokenType.STRING));
                    currentToken.setLength(0);
                    inString = false;
                } else {
                    currentToken.append(currentChar);
                }
                continue;
            }

            if (inRegex) {
                if (currentChar == REGEX_START) {
                    currentToken.append(currentChar);
                    tokens.add(new JSToken(currentToken.toString(), TokenType.REGEX));
                    currentToken.setLength(0);
                    inRegex = false;
                } else {
                    currentToken.append(currentChar);
                }
                continue;
            }

            if (currentChar == SINGLE_LINE_COMMENT_START && i + 1 < length && input[i + 1] == SINGLE_LINE_COMMENT_START) {
                inSingleLineComment = true;
                i++; // Skip the next character
                continue;
            }

            if (currentChar == MULTI_LINE_COMMENT_START && i + 1 < length && input[i + 1] == SINGLE_LINE_COMMENT_START) {
                inMultiLineComment = true;
                i++; // Skip the next character
                continue;
            }

            if (currentChar == STRING_START) {
                inString = true;
                currentToken.append(currentChar);
                continue;
            }

            if (currentChar == REGEX_START) {
                inRegex = true;
                currentToken.append(currentChar);
                continue;
            }

            if (Character.isWhitespace(currentChar)) {
                if (currentToken.length() > 0) {
                    tokens.add(new JSToken(currentToken.toString(), TokenType.CODE));
                    currentToken.setLength(0);
                }
                continue;
            }

            currentToken.append(currentChar);
        }

        if (currentToken.length() > 0) {
            tokens.add(new JSToken(currentToken.toString(), TokenType.CODE));
        }

        return tokens;
    }

    private static boolean isIdentifierChar(char c) {
        return Character.isLetterOrDigit(c) || c == '_';
    }
}

