        demarcator.setDelimiter("|");
        List<String> tokens = demarcator.extractTokens(input);
        assertEquals(Arrays.asList("token1", "", "token2", "token3"), tokens);
    }

    @Test
    void testTokenExtractionWithNoDelimiters() {
        InputStream input = new ByteArrayInputStream("token".getBytes(StandardCharsets.UTF_8));
        demarcator.setDelimiter("|");
