        InputStream input = new ByteArrayInputStream("|token1|token2|".getBytes(StandardCharsets.UTF_8));
        demarcator.setDelimiter("|");
        List<String> tokens = demarcator.extractTokens(input);
        assertEquals(Arrays.asList("", "token1", "token2", ""), tokens);
    }

