    private int column;
    private Reader input;

    public JavaCharStream(Reader input, int bufferSize) {
        this.input = input;
        this.bufferSize = bufferSize;
        this.buffer = new char[bufferSize];
        this.bufferPosition = 0;
        this.line = 1;
        this.column = 0;
        initializeBuffer();
    }

    private void initializeBuffer() {
        try {
            int charsRead = input.read(buffer);
            if (charsRead == -1) {
                // Handle end of stream
            }
        } catch (IOException e) {
            // Handle exception
        }
    }

    public char readChar() {
        if (bufferPosition >= buffer.length) {
            expandBuffer();
        }
        char c = buffer[bufferPosition++];
        updatePosition(c);
        return c;
    }

    private void expandBuffer() {
        char[] newBuffer = new char[bufferSize * 2];
        System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
        buffer = newBuffer;
        bufferSize *= 2;
        initializeBuffer();
    }

    private void updatePosition(char c) {
        if (c == '\n') {
            line++;
            column = 0;
        } else {
            column++;
        }
    }

    public void backup(int amount) {
        bufferPosition -= amount;
    }

    public int getLine() {
        return line;
    }

    public int getColumn() {
        return column;
    }

    public String getImage() {
        return new String(buffer, 0, bufferPosition);
    }

    public String getSuffix(int length) {
        int start = Math.max(0, bufferPosition - length);
        return new String(buffer, start, bufferPosition - start);
    }

    public void reinitialize(Reader newInput) {
        this.input = newInput;
        this.bufferPosition = 0;
        this.line = 1;
        this.column = 0;
        initializeBuffer();
    }
}

