        for (NodeDefinition definition : nodeType.getChildNodeDefinitions()) {
            if (definition.isProtected() == isProtected && definition.isMandatory() == isMandatory && definition.getRequiredPrimaryTypes().contains(primaryType)) {
                definitions.add(definition);
            }
        }
        return definitions;
    }

    public List<PropertyDefinition> findPropertyDefinitions(NodeType nodeType, boolean isProtected, boolean isMandatory) {
        List<PropertyDefinition> definitions = new ArrayList<>();
        for (PropertyDefinition definition : nodeType.getPropertyDefinitions()) {
            if (definition.isProtected() == isProtected && definition.isMandatory() == isMandatory) {
                definitions.add(definition);
            }
        }
        return definitions;
    }

