    public void testExceededConfiguredMaxLifetimeButUpdated() {
        SAMLToken token = createTokenWithLifetime(70); // 70 seconds valid
        tokenRenewer.setMaxLifetime(50); // Configured max lifetime 50 seconds
        tokenRenewer.updateConditions(); // Update conditions to allow renewal
