public abstract class MessageMarshaller extends BaseCommandMarshaller {

    public abstract void marshal(Message message, OutputStream output) throws IOException;

    public abstract Message unmarshal(InputStream input) throws IOException;

    protected void marshalProperties(Message message, OutputStream output) throws IOException {
        // Marshal properties like producer ID, destination, etc.
        writeString(output, message.getProducerId());
        writeString(output, message.getDestination());
        writeString(output, message.getTransactionId());
        writeString(output, message.getMessageId());
        writeString(output, message.getGroupId());
        writeString(output, message.getCorrelationId());
        output.write(longToBytes(message.getExpiration()));
        output.write(message.getPriority());
        marshalContent(message.getContent(), output);
    }

    protected Message unmarshalProperties(InputStream input) throws IOException {
        Message message = new Message();
        message.setProducerId(readString(input));
        message.setDestination(readString(input));
        message.setTransactionId(readString(input));
        message.setMessageId(readString(input));
        message.setGroupId(readString(input));
        message.setCorrelationId(readString(input));
        message.setExpiration(bytesToLong(readBytes(input, 8)));
        message.setPriority(input.read());
        message.setContent(unmarshalContent(input));
        return message;
    }

    protected void marshalContent(Object content, OutputStream output) throws IOException {
        // Implement content marshaling logic
    }

    protected Object unmarshalContent(InputStream input) throws IOException {
        // Implement content unmarshaling logic
        return null;
    }

    private void writeString(OutputStream output, String value) throws IOException {
        if (value != null) {
            byte[] bytes = value.getBytes("UTF-8");
            output.write(intToBytes(bytes.length));
            output.write(bytes);
        } else {
            output.write(intToBytes(0));
        }
    }

    private String readString(InputStream input) throws IOException {
        int length = bytesToInt(readBytes(input, 4));
        if (length > 0) {
            byte[] bytes = readBytes(input, length);
            return new String(bytes, "UTF-8");
        }
        return null;
    }

    private byte[] readBytes(InputStream input, int length) throws IOException {
        byte[] bytes = new byte[length];
        int read = 0;
        while (read < length) {
            int result = input.read(bytes, read, length - read);
            if (result == -1) {
                throw new IOException("End of stream reached before reading expected bytes.");
            }
            read += result;
        }
        return bytes;
    }

    private int bytesToInt(byte[] bytes) {
        return ((bytes[0] & 0xFF) << 24) | ((bytes[1] & 0xFF) << 16) | ((bytes[2] & 0xFF) << 8) | (bytes[3] & 0xFF);
    }

    private byte[] intToBytes(int value) {
        return new byte[]{
            (byte) (value >> 24),
            (byte) (value >> 16),
            (byte) (value >> 8),
            (byte) value
        };
    }

    private long bytesToLong(byte[] bytes) {
        return ((long) bytes[0] << 56) | ((long) (bytes[1] & 0xFF) << 48) | ((long) (bytes[2] & 0xFF) << 40) |
               ((long) (bytes[3] & 0xFF) << 32) | ((long) (bytes[4] & 0xFF) << 24) | ((long) (bytes[5] & 0xFF) << 16) |
               ((long) (bytes[6] & 0xFF) << 8) | ((long) (bytes[7] & 0xFF));
    }

    private byte[] longToBytes(long value) {
        return new byte[]{
            (byte) (value >> 56),
            (byte) (value >> 48),
            (byte) (value >> 40),
            (byte) (value >> 32),
            (byte) (value >> 24),
            (byte) (value >> 16),
            (byte) (value >> 8),
            (byte) value
        };
    }
}

