    protected void reduce(Text key, Iterable<HostDatum> values, Context context) throws IOException, InterruptedException {
        HostDatum aggregatedHostDatum = new HostDatum();
        for (HostDatum hostDatum : values) {
            aggregateHostData(aggregatedHostDatum, hostDatum);
        }
        executorService.submit(() -> processHost(aggregatedHostDatum, context));
    }

    private void aggregateHostData(HostDatum aggregated, HostDatum current) {
