        aggregated.incrementFetchCount(current.getFetchCount());
        aggregated.updateStatus(current.getStatus());
        aggregated.addMetadata(current.getMetadata());
        // More aggregation logic...
    }

    private void processHost(HostDatum hostDatum, Context context) {
        // Processing logic with potential code smells
        try {
            // Simulate processing
            Thread.sleep(recheckInterval);
            context.write(new Text(hostDatum.getHost()), hostDatum);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    @Override
