public abstract class AbstractBuildExecutor {
    protected Logger logger = Logger.getLogger(AbstractBuildExecutor.class.getName());
    protected String projectPath;
    protected String executablePath;
    protected String buildCommand;
    protected boolean isInitialized = false;

    public void initialize(String projectPath) {
        this.projectPath = projectPath;
        this.executablePath = resolveExecutablePath();
        this.isInitialized = true;
        logger.info("Build executor initialized for project: " + projectPath);
    }

    protected abstract String resolveExecutablePath();

    public void executeBuild() {
        if (!isInitialized) {
            logger.warning("Build executor is not initialized.");
            return;
        }
        logger.info("Executing build command: " + buildCommand);
        executeShellCommand(buildCommand);
    }

    protected void executeShellCommand(String command) {
        try {
            Process process = Runtime.getRuntime().exec(command);
            process.waitFor();
            logger.info("Command executed successfully: " + command);
        } catch (Exception e) {
            logger.severe("Error executing command: " + command + " - " + e.getMessage());
        }
    }

    public void setBuildCommand(String buildCommand) {
        this.buildCommand = buildCommand;
    }

    public String getBuildCommand() {
        return buildCommand;
    }

    public void updateProject() {
        logger.info("Updating project at path: " + projectPath);
        // Code to update project
    }

    public abstract void manageProjectState();

    public boolean isInitialized() {
        return isInitialized;
    }
}

