public class WordTemplateCasEvaluator extends AbstractCasEvaluator {

    private Set<String> excludedTypes;

    public WordTemplateCasEvaluator(Set<String> excludedTypes) {
        this.excludedTypes = excludedTypes;
    }

    @Override
    public JCas evaluate(JCas testCas, JCas runCas) {
        Set<Annotation> testAnnotations = new HashSet<>();
        Set<Annotation> runAnnotations = new HashSet<>();

        // Collect annotations from test CAS
        for (Annotation annotation : testCas.getAnnotationIndex(Annotation.type)) {
            if (!excludedTypes.contains(annotation.getType().getName())) {
                testAnnotations.add(annotation);
            }
        }

        // Collect annotations from run CAS
        for (Annotation annotation : runCas.getAnnotationIndex(Annotation.type)) {
            if (!excludedTypes.contains(annotation.getType().getName())) {
                runAnnotations.add(annotation);
            }
        }

        // Evaluate annotations
        for (Annotation testAnnotation : testAnnotations) {
            if (!runAnnotations.contains(testAnnotation)) {
                createFalseNegative(runCas, testAnnotation);
            }
        }

        for (Annotation runAnnotation : runAnnotations) {
            if (!testAnnotations.contains(runAnnotation)) {
                createFalsePositive(runCas, runAnnotation);
            } else {
                createTruePositive(runCas, runAnnotation);
            }
        }

        return runCas;
