public abstract class LangTurtleBase extends LangBase {
    protected Map<String, String> prefixMap = new HashMap<>();
    protected String baseURI;
    protected Graph currentGraph;

    public LangTurtleBase() {
        this.currentGraph = new Graph();
    }

    protected abstract void emitTriple(Triple triple);

    protected abstract void processTopLevelElement(String element);

    protected void processDirective(String directive) {
        if (directive.startsWith("@prefix")) {
            processPrefixDirective(directive);
        } else if (directive.startsWith("@base")) {
            processBaseDirective(directive);
        } else {
            handleError("Unrecognized directive: " + directive);
        }
    }

    private void processPrefixDirective(String directive) {
        String[] parts = directive.split("\\s+");
        if (parts.length == 3) {
            String prefix = parts[1];
            String uri = parts[2].replaceAll("<|>", "");
            prefixMap.put(prefix, uri);
        } else {
            handleError("Invalid prefix directive: " + directive);
        }
    }

    private void processBaseDirective(String directive) {
        String[] parts = directive.split("\\s+");
        if (parts.length == 2) {
            baseURI = parts[1].replaceAll("<|>", "");
        } else {
            handleError("Invalid base directive: " + directive);
        }
    }

    protected void processTriple(String subject, String predicate, String object) {
        Triple triple = new Triple(subject, predicate, object);
        emitTriple(triple);
    }

    protected void handleError(String message) {
        throw new IllegalArgumentException(message);
    }

    // Additional methods for processing RDF constructs can be added here
}

