public final class VortexAggregateFuture<T> implements VortexFutureDelegate<T> {
    private final ExecutorService executor;
    private final BlockingQueue<T> resultsQueue;
    private final CountDownLatch latch;
    private final int totalTasks;
    private int completedTasks;
    private boolean isCompleted;

    public VortexAggregateFuture(ExecutorService executor, int totalTasks) {
        this.executor = executor;
        this.resultsQueue = new LinkedBlockingQueue<>();
        this.latch = new CountDownLatch(totalTasks);
        this.totalTasks = totalTasks;
        this.completedTasks = 0;
        this.isCompleted = false;
    }

    public void onTaskSuccess(T result) {
        resultsQueue.offer(result);
        completeTask();
    }

    public void onTaskFailure(Throwable throwable) {
        completeTask();
        // Handle failure (e.g., log or notify)
    }

    public void onTaskException(Exception exception) {
        completeTask();
        // Handle exception (e.g., log or notify)
    }

    private synchronized void completeTask() {
        completedTasks++;
        latch.countDown();
        if (completedTasks == totalTasks) {
            isCompleted = true;
            // Notify completion (e.g., callback)
        }
    }

    public List<T> getAggregatedResults() throws InterruptedException {
        latch.await();
        return new ArrayList<>(resultsQueue);
    }

    public List<T> getAggregatedResults(long timeout, TimeUnit unit) throws InterruptedException, TimeoutException {
        if (!latch.await(timeout, unit)) {
            throw new TimeoutException("Timeout while waiting for task completion");
        }
        return new ArrayList<>(resultsQueue);
    }

    public boolean isCompleted() {
        return isCompleted;
    }
}

