class RequestHandlerStackTest extends BaseRequestHandlerStackTest {

    private boolean handler1Executed;
    private boolean handler2Executed;
    private boolean handler3Executed;

    @BeforeEach
    void setUp() {
        handler1Executed = false;
        handler2Executed = false;
        handler3Executed = false;
    }

    @Test
    void test1() {
        IRequestHandler handler1 = new IRequestHandler() {
            @Override
            public void handleRequest(Request request) {
                handler1Executed = true;
                request.setResponse("Response from Handler 1");
            }
        };

        IRequestHandler handler2 = new IRequestHandler() {
            @Override
            public void handleRequest(Request request) {
                handler2Executed = true;
                request.setResponse("Response from Handler 2");
            }
        };

        RequestHandlerStack stack = new RequestHandlerStack();
        stack.addHandler(handler1);
        stack.addHandler(handler2);

        Request request = new Request();
        stack.handle(request);

        assertTrue(handler1Executed);
        assertTrue(handler2Executed);
        assertEquals("Response from Handler 2", request.getResponse());
    }

    @Test
    void test2() {
        IRequestHandler handler1 = new IRequestHandler() {
            @Override
            public void handleRequest(Request request) {
                handler1Executed = true;
                request.setResponse("Response from Handler 1");
            }
        };

        IRequestHandler handler2 = new IRequestHandler() {
            @Override
            public void handleRequest(Request request) {
                handler2Executed = true;
                request.setResponse("Response from Handler 2");
            }
        };

        RequestHandlerStack stack = new RequestHandlerStack();
        stack.addHandler(handler1);
        stack.addHandler(handler2);

        Request request = new Request();
        stack.handle(request);

        stack.detachHandler(handler1);
        handler1Executed = false; // Reset for next test

        stack.handle(request);

        assertFalse(handler1Executed);
        assertTrue(handler2Executed);
        assertEquals("Response from Handler 2", request.getResponse());
    }

    @Test
    void test3() {
        IRequestHandler handler1 = new IRequestHandler() {
            @Override
            public void handleRequest(Request request) {
                handler1Executed = true;
                request.setResponse("Response from Handler 1");
            }
        };

        IRequestHandler handler2 = new IRequestHandler() {
            @Override
            public void handleRequest(Request request) {
                handler2Executed = true;
                request.setResponse("Response from Handler 2");
            }
        };

        IRequestHandler handler3 = new IRequestHandler() {
            @Override
            public void handleRequest(Request request) {
                handler3Executed = true;
                request.setResponse("Response from Handler 3");
            }
        };

        RequestHandlerStack stack = new RequestHandlerStack();
        stack.addHandler(handler1);
        stack.addHandler(handler2);
        stack.addHandler(handler3);

        Request request = new Request();
        stack.handle(request);

        assertTrue(handler1Executed);
        assertTrue(handler2Executed);
        assertTrue(handler3Executed);
        assertEquals("Response from Handler 3", request.getResponse());
    }
}

