public class QueryEngineHTTP implements QueryExecution {
    private static final Logger logger = Logger.getLogger(QueryEngineHTTP.class.getName());
    private String endpoint;
    private String defaultGraphURI;
    private String namedGraphURI;
    private int timeout;
    private boolean useCompression;

    public QueryEngineHTTP(String endpoint) {
        this.endpoint = endpoint;
        this.timeout = 30000; // default timeout
        this.useCompression = false; // default compression
    }

    public void setDefaultGraphURI(String uri) {
        this.defaultGraphURI = uri;
    }

