        this.timeout = timeout;
    }

    public void setUseCompression(boolean useCompression) {
        this.useCompression = useCompression;
    }

    public QueryResult execute(String query) throws IOException {
        HttpURLConnection connection = null;
        try {
            URL url = new URL(endpoint + "?query=" + encodeQuery(query));
            connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(timeout);
            connection.setReadTimeout(timeout);
            if (useCompression) {
                connection.setRequestProperty("Accept-Encoding", "gzip");
            }
            connection.setRequestProperty("Accept", "application/sparql-results+json");

            int responseCode = connection.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                logger.severe("Error executing query: " + responseCode);
                throw new IOException("Error executing query: " + responseCode);
            }

            // Process response
            return processResponse(connection);
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    private String encodeQuery(String query) {
        // Simple encoding logic (could be improved)
        return query.replace(" ", "%20");
    }

