public class IteratorUtils {

    public static <T> Iterator<T> emptyIterator() {
        return Collections.emptyIterator();
    }

    public static <T> Iterator<T> singletonIterator(T item) {
        return Collections.singleton(item).iterator();
    }

    public static <T> Iterator<T> arrayIterator(T[] array) {
        return Arrays.asList(array).iterator();
    }

    public static <T> Iterator<T> chain(Iterator<T>... iterators) {
        return Arrays.stream(iterators)
                .flatMap(it -> StreamSupport.stream(((Iterable<T>) () -> it).spliterator(), false))
                .iterator();
    }

    public static <T> Iterator<T> filter(Iterator<T> iterator, Predicate<? super T> predicate) {
        return new Iterator<T>() {
            private T nextElement;
            private boolean hasNextElement = false;

            @Override
            public boolean hasNext() {
                while (!hasNextElement && iterator.hasNext()) {
                    nextElement = iterator.next();
                    if (predicate.test(nextElement)) {
                        hasNextElement = true;
                    }
                }
                return hasNextElement;
            }

            @Override
            public T next() {
                if (!hasNext()) {
                    throw new NoSuchElementException();
                }
                hasNextElement = false;
                return nextElement;
            }
        };
    }

    public static <T, R> Iterator<R> transform(Iterator<T> iterator, Function<? super T, ? extends R> function) {
        return new Iterator<R>() {
            @Override
            public boolean hasNext() {
                return iterator.hasNext();
            }

            @Override
            public R next() {
                return function.apply(iterator.next());
            }
        };
    }

    public static <T> List<T> toList(Iterator<T> iterator) {
        List<T> list = new ArrayList<>();
        iterator.forEachRemaining(list::add);
        return list;
    }

    public static <T> T[] toArray(Iterator<T> iterator, T[] array) {
        return toList(iterator).toArray(array);
    }

    public static <T> boolean isEmpty(Iterator<T> iterator) {
        return !iterator.hasNext();
    }

    public static <T> int size(Iterator<T> iterator) {
        int size = 0;
        while (iterator.hasNext()) {
            iterator.next();
            size++;
        }
        return size;
    }

    public static <T> int indexOf(Iterator<T> iterator, T element) {
        int index = 0;
        while (iterator.hasNext()) {
            if (Objects.equals(iterator.next(), element)) {
                return index;
            }
            index++;
        }
        return -1;
    }

    public static <T> Iterator<T> unmodifiableIterator(Iterator<T> iterator) {
        return Collections.unmodifiableCollection(toList(iterator)).iterator();
    }

    public static <T> Iterator<T> collate(Iterator<T>... iterators) {
        return Arrays.stream(iterators)
                .flatMap(it -> StreamSupport.stream(((Iterable<T>) () -> it).spliterator(), false))
                .iterator();
    }
}

