public class XSLTResult implements Result {
    private String stylesheetLocation;
    private TransformerFactory transformerFactory;
    private Transformer transformer;
    private boolean cacheEnabled;
    private String matchingPattern;
    private String excludingPattern;

    public XSLTResult(String stylesheetLocation, boolean cacheEnabled) {
        this.stylesheetLocation = stylesheetLocation;
        this.cacheEnabled = cacheEnabled;
        this.transformerFactory = TransformerFactory.newInstance();
        compileStylesheet();
    }

    private void compileStylesheet() {
        try {
            StreamSource source = new StreamSource(new File(stylesheetLocation));
            transformer = transformerFactory.newTransformer(source);
        } catch (TransformerConfigurationException e) {
            logError("Error compiling stylesheet: " + e.getMessage());
        }
    }

    public void setMatchingPattern(String pattern) {
        this.matchingPattern = pattern;
    }

    public void setExcludingPattern(String pattern) {
        this.excludingPattern = pattern;
    }

    public void execute(ActionContext context, HttpServletResponse response) {
        try {
            Source xmlSource = new StreamSource(new StringReader(context.getXmlData()));
            Result outputTarget = new StreamResult(response.getWriter());
            transformer.setParameter("matchingPattern", matchingPattern);
            transformer.setParameter("excludingPattern", excludingPattern);
            transformer.transform(xmlSource, outputTarget);
        } catch (TransformerException e) {
            logError("Error during transformation: " + e.getMessage());
        } catch (IOException e) {
            logError("IO Error: " + e.getMessage());
        }
    }

    private void logError(String message) {
        System.err.println(message);
    }
}

