public class DD<T extends _> extends EImp<T> implements HamletSpec.DD {

    private StringBuilder html;

    public DD() {
        this.html = new StringBuilder();
        this.html.append("<dd>");
    }

    public DD<T> id(String id) {
        appendAttribute("id", id);
        return this;
    }

    public DD<T> clazz(String clazz) {
        appendAttribute("class", clazz);
        return this;
    }

    public DD<T> title(String title) {
        appendAttribute("title", title);
        return this;
    }

    public DD<T> addChild(String childHtml) {
        this.html.append(childHtml);
        return this;
    }

    public DD<T> paragraph(String text) {
        return addChild("<p>" + text + "</p>");
    }

    public DD<T> heading(String text, int level) {
        return addChild("<h" + level + ">" + text + "</h" + level + ">");
    }

    public DD<T> list(String... items) {
        StringBuilder listHtml = new StringBuilder("<ul>");
        for (String item : items) {
            listHtml.append("<li>").append(item).append("</li>");
        }
        listHtml.append("</ul>");
        return addChild(listHtml.toString());
    }

    private void appendAttribute(String name, String value) {
        int insertPosition = this.html.indexOf(">");
        if (insertPosition != -1) {
            this.html.insert(insertPosition, " " + name + "=\"" + value + "\"");
        }
    }

    public String build() {
        this.html.append("</dd>");
        return this.html.toString();
    }
}

