public class AvlTreeImpl<K> {
    private class LinkedAvlNode<K> {
        K key;
        LinkedAvlNode<K> left, right, parent;
        int height;

        LinkedAvlNode(K key) {
            this.key = key;
            this.height = 1;
        }
    }

    private LinkedAvlNode<K> root;
    private LinkedAvlNode<K> firstNode;
    private LinkedAvlNode<K> lastNode;
    private int size;
    private Comparator<K> comparator;

    public AvlTreeImpl(Comparator<K> comparator) {
        this.comparator = comparator;
        this.size = 0;
    }

    public void insert(K key) {
        root = insert(root, key);
    }

    private LinkedAvlNode<K> insert(LinkedAvlNode<K> node, K key) {
        if (node == null) {
            size++;
            LinkedAvlNode<K> newNode = new LinkedAvlNode<>(key);
            insertInList(newNode, null, 0);
            return newNode;
        }
        if (comparator.compare(key, node.key) < 0) {
            node.left = insert(node.left, key);
            node.left.parent = node;
        } else if (comparator.compare(key, node.key) > 0) {
            node.right = insert(node.right, key);
            node.right.parent = node;
        } else {
            return node; // Duplicate keys are not allowed
        }

        node.height = 1 + Math.max(getHeight(node.left), getHeight(node.right));
        return balance(getTreePath(node));
    }

    public void remove(K key) {
        root = remove(root, key);
    }

    private LinkedAvlNode<K> remove(LinkedAvlNode<K> node, K key) {
        if (node == null) {
            return node;
        }
        if (comparator.compare(key, node.key) < 0) {
            node.left = remove(node.left, key);
        } else if (comparator.compare(key, node.key) > 0) {
            node.right = remove(node.right, key);
        } else {
            if (node.left == null || node.right == null) {
                LinkedAvlNode<K> temp = (node.left != null) ? node.left : node.right;
                if (temp == null) {
                    node = null;
                } else {
                    node = temp;
                }
                size--;
            } else {
                LinkedAvlNode<K> temp = getMinValueNode(node.right);
                node.key = temp.key;
                node.right = remove(node.right, temp.key);
            }
        }

        if (node == null) {
            return node;
        }

        node.height = 1 + Math.max(getHeight(node.left), getHeight(node.right));
        return balance(getTreePath(node));
    }

    private LinkedAvlNode<K> getMinValueNode(LinkedAvlNode<K> node) {
        while (node.left != null) {
            node = node.left;
        }
        return node;
    }

    private List<LinkedAvlNode<K>> getTreePath(LinkedAvlNode<K> node) {
        List<LinkedAvlNode<K>> path = new LinkedList<>();
        while (node != null) {
            path.add(node);
            node = node.parent;
        }
        return path;
    }

    private LinkedAvlNode<K> balance(List<LinkedAvlNode<K>> treePath) {
        // Balancing logic here
        return treePath.get(treePath.size() - 1); // Placeholder
    }

    private int getHeight(LinkedAvlNode<K> node) {
        return (node == null) ? 0 : node.height;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int getSize() {
        return size;
    }

    public void printTree() {
