public class CrawlDbReducer extends Reducer<Text, CrawlDatum, Text, CrawlDatum> {
    private static final int MAX_INLINKS = 100;
    private PriorityQueue<CrawlDatum> inlinkQueue;

    @Override
    protected void setup(Context context) throws IOException, InterruptedException {
        inlinkQueue = new PriorityQueue<>(MAX_INLINKS, (a, b) -> Double.compare(b.getScore(), a.getScore()));
    }

    @Override
    protected void reduce(Text key, Iterable<CrawlDatum> values, Context context) throws IOException, InterruptedException {
        CrawlDatum finalDatum = null;

        for (CrawlDatum datum : values) {
            if (finalDatum == null) {
                finalDatum = datum;
            } else {
                updateCrawlDatum(finalDatum, datum);
            }
            manageInlinks(datum);
        }

        if (finalDatum != null) {
            context.write(key, finalDatum);
            context.getCounter("CrawlDb", finalDatum.getStatus().toString()).increment(1);
        }
    }

    private void updateCrawlDatum(CrawlDatum finalDatum, CrawlDatum datum) {
        // Logic to update finalDatum based on datum
        if (datum.getStatus() == CrawlDatum.Status.NEW) {
            finalDatum.updateWithNew(datum);
        } else if (datum.getStatus() == CrawlDatum.Status.RETRY) {
            finalDatum.incrementRetryCount();
        }
        // Additional status handling can be added here
    }

    private void manageInlinks(CrawlDatum datum) {
        if (inlinkQueue.size() < MAX_INLINKS) {
            inlinkQueue.offer(datum);
        } else if (datum.getScore() > inlinkQueue.peek().getScore()) {
            inlinkQueue.poll();
            inlinkQueue.offer(datum);
        }
    }

    @Override
    protected void cleanup(Context context) throws IOException, InterruptedException {
        // Cleanup logic if necessary
    }
}

