public class MasterTask {
    private static final Logger logger = Logger.getLogger(MasterTask.class.getName());
    private CommunicationGroupClient communicationClient;
    private Model model;
    private double learningRate;
    private double convergenceThreshold;
    private List<Double> lossHistory;
    private int maxIterations;

    public MasterTask(CommunicationGroupClient communicationClient, Model model, double learningRate, double convergenceThreshold, int maxIterations) {
        this.communicationClient = communicationClient;
        this.model = model;
        this.learningRate = learningRate;
        this.convergenceThreshold = convergenceThreshold;
        this.maxIterations = maxIterations;
        this.lossHistory = new ArrayList<>();
    }

    public void optimize() {
        for (int iteration = 0; iteration < maxIterations; iteration++) {
            double loss = computeLoss();
            lossHistory.add(loss);
            logger.info("Iteration " + iteration + ": Loss = " + loss);

            if (checkConvergence(loss)) {
                logger.info("Convergence reached at iteration " + iteration);
                break;
            }

            double[] gradients = computeGradients();
            double[] descentDirection = computeDescentDirection(gradients);
            updateModel(descentDirection);
            broadcastModelUpdate();
        }
    }

    private double computeLoss() {
        // Implement loss computation logic
        return model.evaluateLoss();
    }

    private double[] computeGradients() {
        // Implement gradient computation logic
        return model.evaluateGradients();
    }

    private double[] computeDescentDirection(double[] gradients) {
        double[] descentDirection = new double[gradients.length];
        for (int i = 0; i < gradients.length; i++) {
            descentDirection[i] = -learningRate * gradients[i];
        }
        return descentDirection;
    }

    private void updateModel(double[] descentDirection) {
        model.updateParameters(descentDirection);
    }

    private void broadcastModelUpdate() {
        communicationClient.broadcastModel(model);
    }

    private boolean checkConvergence(double loss) {
        if (lossHistory.size() < 2) {
            return false;
        }
        double previousLoss = lossHistory.get(lossHistory.size() - 2);
        return Math.abs(previousLoss - loss) < convergenceThreshold;
    }

    public void handleTopologyChange() {
        // Implement logic to handle changes in the communication group topology
        communicationClient.updateTopology();
    }
}

public class Dom4jUtil {

    public static void addChildElement(Element parent, String childName, String value) {
        if (parent == null || childName == null || value == null) {
            throw new IllegalArgumentException("Parent element, child name, and value cannot be null");
        }
        Element child = parent.addElement(childName);
        child.setText(encodeValue(value));
    }

    public static Element getChildElement(Element parent, String childName) {
        if (parent == null || childName == null) {
            return null;
        }
        return parent.element(childName);
    }

    public static Document parseXmlString(String xml) throws Exception {
        if (xml == null || xml.isEmpty()) {
            throw new IllegalArgumentException("XML string cannot be null or empty");
        }
        SAXReader reader = new SAXReader();
        return reader.read(new StringReader(xml));
    }

    public static String documentToString(Document document) throws Exception {
        if (document == null) {
            throw new IllegalArgumentException("Document cannot be null");
        }
        StringWriter stringWriter = new StringWriter();
        XMLWriter writer = new XMLWriter(stringWriter, Format.getPrettyFormat());
        writer.write(document);
        writer.close();
        return stringWriter.toString();
    }

    private static String encodeValue(String value) {
        // Basic encoding logic (could be improved)
        return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    public enum Parseable {
        INTEGER(Integer.class) {
            @Override
            public String format(Object value) {
                return String.valueOf(value);
            }

            @Override
            public Object parse(String value) {
                return Integer.valueOf(value);
            }
        },
        DOUBLE(Double.class) {
            @Override
            public String format(Object value) {
                return String.valueOf(value);
            }

            @Override
            public Object parse(String value) {
                return Double.valueOf(value);
            }
        },
        STRING(String.class) {
            @Override
            public String format(Object value) {
                return (String) value;
            }

            @Override
            public Object parse(String value) {
                return value;
            }
        };

        private static final Map<Class<?>, Parseable> typeMap = new HashMap<>();

        static {
            for (Parseable parseable : Parseable.values()) {
                typeMap.put(parseable.type, parseable);
            }
        }

        private final Class<?> type;

        Parseable(Class<?> type) {
            this.type = type;
        }

        public abstract String format(Object value);

        public abstract Object parse(String value);

        public static Parseable forType(Class<?> type) {
            Parseable parseable = typeMap.get(type);
            if (parseable == null) {
                throw new UnsupportedOperationException("Type not supported: " + type);
            }
            return parseable;
        }
    }
}

