public class DropColumnToModelIT extends MergeCase {

    @Test
    public void testSimpleColumn() {
        // Setup: Create a database entity with two attributes
        DatabaseEntity entity = new DatabaseEntity();
        entity.addAttribute("column1");
        entity.addAttribute("column2");

        // Execute: Drop a column
        entity.dropColumn("column1");

        // Verify: Check that the column is removed from the database entity
        assertFalse(entity.hasAttribute("column1"));

        // Verify: Check that the column is removed from the object model
        ObjectEntity objectEntity = new ObjectEntity(entity);
        assertFalse(objectEntity.hasAttribute("column1"));
    }

    @Test
    public void testRemoveFKColumnWithoutRelationshipInDb() {
        // Setup: Create two database entities
        DatabaseEntity parentEntity = new DatabaseEntity();
        DatabaseEntity childEntity = new DatabaseEntity();

        // Setup: Add relationships
        parentEntity.addRelationship(childEntity);

        // Setup: Add foreign key column
        parentEntity.addForeignKey("fk_column", childEntity);

        // Execute: Drop the foreign key column
        parentEntity.dropForeignKey("fk_column");

        // Verify: Check that the foreign key column is removed
        assertFalse(parentEntity.hasForeignKey("fk_column"));

        // Verify: Check that the relationship is still intact
        assertTrue(parentEntity.hasRelationship(childEntity));

        // Verify: Check that the attributes are correctly updated
        ObjectEntity parentObjectEntity = new ObjectEntity(parentEntity);
        assertFalse(parentObjectEntity.hasAttribute("fk_column"));
    }
}

public class ValuesTest {

    private static final Map<String, String> STRING_MAP = new HashMap<>();
    private static final Map<String, Short> SHORT_MAP = new HashMap<>();
    private static final Map<String, Integer> INTEGER_MAP = new HashMap<>();
