    private static final List<Short> SHORT_LIST = new ArrayList<>();
    private static final List<Integer> INTEGER_LIST = new ArrayList<>();

    static {
        STRING_MAP.put("key1", "value1");
        SHORT_MAP.put("key2", (short) 2);
        INTEGER_MAP.put("key3", 3);
        STRING_LIST.add("item1");
        SHORT_LIST.add((short) 1);
        INTEGER_LIST.add(1);
    }

    @Test
    public void testStringToMapConversion() {
        String input = "key1:value1,key2:value2";
        Map<String, String> result = Values.convertStringToMap(input);
        assertEquals(2, result.size());
