@JsonIgnoreProperties(ignoreUnknown = true)
@JsonInclude(JsonInclude.Include.NON_NULL)
public class ZNRecord {
    private String id;
    private long creationTime;
    private long lastModifiedTime;
    private int version;
    private Map<String, String> simpleFields = new HashMap<>();
    private Map<String, Map<String, String>> mapFields = new HashMap<>();
    private Map<String, List<String>> listFields = new HashMap<>();

    public ZNRecord(String id) {
        this.id = id;
        this.creationTime = System.currentTimeMillis();
        this.lastModifiedTime = this.creationTime;
        this.version = 1;
    }

    public String getId() {
        return id;
    }

    public long getCreationTime() {
        return creationTime;
    }

    public long getLastModifiedTime() {
        return lastModifiedTime;
    }

    public int getVersion() {
        return version;
    }

    public void setSimpleField(String key, String value) {
        simpleFields.put(key, value);
        updateLastModifiedTime();
    }

    public String getSimpleField(String key) {
        return simpleFields.get(key);
    }

    public void setMapField(String key, Map<String, String> value) {
        mapFields.put(key, value);
        updateLastModifiedTime();
    }

    public Map<String, String> getMapField(String key) {
        return mapFields.get(key);
    }

    public void setListField(String key, List<String> value) {
        listFields.put(key, value);
        updateLastModifiedTime();
    }

    public List<String> getListField(String key) {
        return listFields.get(key);
    }

    public void merge(ZNRecord other) {
        if (other != null) {
            simpleFields.putAll(other.simpleFields);
            mapFields.putAll(other.mapFields);
            listFields.putAll(other.listFields);
            updateLastModifiedTime();
        }
    }

    public void subtract(ZNRecord other) {
        if (other != null) {
            simpleFields.keySet().removeAll(other.simpleFields.keySet());
            mapFields.keySet().removeAll(other.mapFields.keySet());
            listFields.keySet().removeAll(other.listFields.keySet());
            updateLastModifiedTime();
        }
    }

    private void updateLastModifiedTime() {
        this.lastModifiedTime = System.currentTimeMillis();
        this.version++;
    }

    public String serialize() {
        try {
            ObjectMapper objectMapper = new ObjectMapper();
            return objectMapper.writeValueAsString(this);
        } catch (Exception e) {
            logWarning("Serialization failed: " + e.getMessage());
            return null;
        }
    }

    public static ZNRecord deserialize(String json) {
        try {
            ObjectMapper objectMapper = new ObjectMapper();
            return objectMapper.readValue(json, ZNRecord.class);
        } catch (Exception e) {
            logWarning("Deserialization failed: " + e.getMessage());
            return null;
        }
    }

    private void logWarning(String message) {
        System.err.println("WARNING: " + message);
    }
}

