public class BuilderWithScopesTest extends CamelTestSupport {

    private List<String> executionOrder = new ArrayList<>();

    @Override
    protected CamelContext createCamelContext() throws Exception {
        return new DefaultCamelContext();
    }

    @Override
    protected RouteBuilder createRouteBuilder() throws Exception {
        return new RouteBuilder() {
            @Override
            public void configure() throws Exception {
                from("direct:start")
                    .process(new Processor() {
                        public void process(org.apache.camel.Exchange exchange) {
                            executionOrder.add("InitialProcessor");
                        }
                    })
                    .choice()
                        .when(header("condition").isEqualTo("A"))
                            .process(new Processor() {
                                public void process(org.apache.camel.Exchange exchange) {
                                    executionOrder.add("ChoiceAProcessor");
                                }
                            })
                        .when(header("condition").isEqualTo("B"))
                            .process(new Processor() {
                                public void process(org.apache.camel.Exchange exchange) {
                                    executionOrder.add("ChoiceBProcessor");
                                }
                            })
                        .otherwise()
                            .process(new Processor() {
                                public void process(org.apache.camel.Exchange exchange) {
                                    executionOrder.add("DefaultProcessor");
                                }
                            })
                    .endChoice()
                    .doTry()
                        .process(new Processor() {
                            public void process(org.apache.camel.Exchange exchange) {
                                executionOrder.add("TryProcessor");
                                throw new RuntimeException("Simulated Exception");
                            }
                        })
                    .doCatch(Exception.class)
                        .process(new Processor() {
                            public void process(org.apache.camel.Exchange exchange) {
                                executionOrder.add("CatchProcessor");
                            }
                        })
                    .doFinally()
                        .process(new Processor() {
                            public void process(org.apache.camel.Exchange exchange) {
                                executionOrder.add("FinallyProcessor");
                            }
                        });
            }
        };
    }

    @Test
    public void testRouteWithConditionA() throws Exception {
        template.sendBodyAndHeader("direct:start", "TestMessage", "condition", "A");
        assertExecutionOrder("InitialProcessor", "ChoiceAProcessor", "TryProcessor", "CatchProcessor", "FinallyProcessor");
    }

    @Test
    public void testRouteWithConditionB() throws Exception {
        template.sendBodyAndHeader("direct:start", "TestMessage", "condition", "B");
        assertExecutionOrder("InitialProcessor", "ChoiceBProcessor", "TryProcessor", "CatchProcessor", "FinallyProcessor");
    }

    @Test
    public void testRouteWithDefaultCondition() throws Exception {
        template.sendBodyAndHeader("direct:start", "TestMessage", "condition", "C");
        assertExecutionOrder("InitialProcessor", "DefaultProcessor", "TryProcessor", "CatchProcessor", "FinallyProcessor");
    }

    private void assertExecutionOrder(String... expectedOrder) {
        assertEquals(expectedOrder.length, executionOrder.size());
        for (int i = 0; i < expectedOrder.length; i++) {
            assertEquals(expectedOrder[i], executionOrder.get(i));
        }
        executionOrder.clear();
    }
