public class Time extends AbstractTime {
    private static final long UNIX_START = 0L; // Start of Unix time
    private static final String RFC1123_FORMAT = "EEE, dd MMM yyyy HH:mm:ss z";
    private static final SimpleDateFormat rfc1123Formatter = new SimpleDateFormat(RFC1123_FORMAT);

    static {
        rfc1123Formatter.setTimeZone(TimeZone.getTimeZone("GMT"));
    }

    private final Calendar calendar;

    public Time() {
        this.calendar = Calendar.getInstance();
    }

    public Time(long milliseconds) {
        this();
        this.calendar.setTimeInMillis(milliseconds);
    }

    public Time(Date date) {
        this();
        this.calendar.setTime(date);
    }

    public Time(String dateString) throws ParseException {
        this();
        Date date = rfc1123Formatter.parse(dateString);
        this.calendar.setTime(date);
    }

    public void addDuration(long milliseconds) {
        this.calendar.add(Calendar.MILLISECOND, (int) milliseconds);
    }

    public void subtractDuration(long milliseconds) {
        this.calendar.add(Calendar.MILLISECOND, (int) -milliseconds);
    }

    public int getYear() {
        return this.calendar.get(Calendar.YEAR);
    }

    public int getMonth() {
        return this.calendar.get(Calendar.MONTH) + 1; // Months are 0-based
    }

    public int getDay() {
        return this.calendar.get(Calendar.DAY_OF_MONTH);
    }

    public int getHour() {
        return this.calendar.get(Calendar.HOUR_OF_DAY);
    }

    public int getMinute() {
        return this.calendar.get(Calendar.MINUTE);
    }

    public int getSecond() {
        return this.calendar.get(Calendar.SECOND);
    }

    public String toRFC1123String() {
        return rfc1123Formatter.format(this.calendar.getTime());
    }
}

