public class AtlasKnoxSSOAuthenticationFilter implements Filter {

    private boolean ssoEnabled;
    private String jwtCookieName;
    private List<String> userAgentList;

    @Override
    public void init(FilterConfig filterConfig) throws ServletException {
        ssoEnabled = Boolean.parseBoolean(filterConfig.getInitParameter("ssoEnabled"));
        jwtCookieName = filterConfig.getInitParameter("jwtCookieName");
        // Assume userAgentList is initialized from config
    }

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {
        HttpServletRequest httpRequest = (HttpServletRequest) request;
        HttpServletResponse httpResponse = (HttpServletResponse) response;

        if (!ssoEnabled) {
            chain.doFilter(request, response);
            return;
        }

        String jwt = getJwtFromCookies(httpRequest.getCookies());

        if (jwt == null || !isValidJwt(jwt)) {
            handleInvalidJwt(httpRequest, httpResponse);
            return;
        }

        // Assume retrieveUserInfoFromJwt is a method that extracts user info from the JWT
        UserInfo userInfo = retrieveUserInfoFromJwt(jwt);
        setAuthenticationContext(userInfo);

        chain.doFilter(request, response);
    }

    private String getJwtFromCookies(Cookie[] cookies) {
        if (cookies != null) {
            for (Cookie cookie : cookies) {
                if (jwtCookieName.equals(cookie.getName())) {
                    return cookie.getValue();
                }
            }
        }
        return null;
    }

    private boolean isValidJwt(String jwt) {
        // Assume validateJwtSignatureAndExpiration is a method that checks the JWT's validity
        return validateJwtSignatureAndExpiration(jwt);
    }

    private void handleInvalidJwt(HttpServletRequest request, HttpServletResponse response) throws IOException {
        if (isAjaxRequest(request)) {
            response.setContentType("application/json");
            response.getWriter().write("{\"redirectUrl\": \"/login\"}");
        } else {
            response.sendRedirect("/login");
        }
    }

    private boolean isAjaxRequest(HttpServletRequest request) {
        String ajaxHeader = request.getHeader("X-Requested-With");
        return "XMLHttpRequest".equals(ajaxHeader);
    }

    private void setAuthenticationContext(UserInfo userInfo) {
