public class AtlasClient extends BaseClient {
    private static final String BASE_URL = "http://atlas-server/api/";
    private static final Gson gson = new Gson();

    public AtlasClient(String username, String password) {
        super(username, password);
        ClientConfig clientConfig = new ClientConfig();
        clientConfig.property(ClientProperties.CONNECT_TIMEOUT, 10000);
        clientConfig.property(ClientProperties.READ_TIMEOUT, 10000);
        this.client = JerseyClientBuilder.createClient(clientConfig);
    }

    public String getTypes() {
        return sendRequest("types");
    }

    public String getEntities() {
        return sendRequest("entities");
    }

    public String getTerms() {
        return sendRequest("terms");
    }

    public String getTaxonomies() {
        return sendRequest("taxonomies");
    }

    public String getOperations() {
        return sendRequest("operations");
    }

    private String sendRequest(String endpoint) {
        try {
            String response = client.target(BASE_URL + endpoint)
                    .request()
                    .header("Authorization", "Basic " + encodeCredentials(username, password))
                    .get(String.class);
            return response;
        } catch (Exception e) {
            logError("Error while fetching data from " + endpoint, e);
            return null;
        }
    }

    public static AtlasClient create(String username, String password) {
        return new AtlasClient(username, password);
    }

    public static boolean testConnection(String username, String password) {
        try {
            AtlasClient client = create(username, password);
            String response = client.getTypes();
            return response != null;
        } catch (Exception e) {
            logError("Connection test failed", e);
            return false;
        }
    }

    private static void logError(String message, Exception e) {
        System.err.println(message + ": " + e.getMessage());
    }

    private String encodeCredentials(String username, String password) {
        return java.util.Base64.getEncoder().encodeToString((username + ":" + password).getBytes());
    }
}

public class BPTreeNode extends BPTreePage {
    private List<Record> records;
    private List<BPTreeNode> children;
    private boolean isLeaf;
    private int maxRecords;

    public BPTreeNode(int maxRecords, boolean isLeaf) {
        this.maxRecords = maxRecords;
        this.isLeaf = isLeaf;
        this.records = new ArrayList<>();
        this.children = new ArrayList<>();
    }

    public boolean isLeaf() {
        return isLeaf;
    }

    public List<Record> getRecords() {
        return records;
    }

    public List<BPTreeNode> getChildren() {
        return children;
    }

    public void insert(Record record) {
        if (isLeaf) {
            insertInLeaf(record);
        } else {
            insertInNonLeaf(record);
        }
    }

    private void insertInLeaf(Record record) {
        records.add(record);
        records.sort(Record::compareTo);
        if (records.size() > maxRecords) {
            split();
        }
    }

    private void insertInNonLeaf(Record record) {
        int index = findChildIndex(record);
        children.get(index).insert(record);
        if (children.get(index).getRecords().size() > maxRecords) {
            splitChild(index);
        }
    }

    private int findChildIndex(Record record) {
        for (int i = 0; i < records.size(); i++) {
            if (record.compareTo(records.get(i)) < 0) {
                return i;
            }
        }
