@Converter
public final class NIOConverter {
    private static final Logger LOGGER = Logger.getLogger(NIOConverter.class.getName());

    private NIOConverter() {
        // Prevent instantiation
    }

    public static byte[] byteBufferToByteArray(ByteBuffer buffer) {
        byte[] bytes = new byte[buffer.remaining()];
        buffer.get(bytes);
        return bytes;
    }

    public static String byteBufferToString(ByteBuffer buffer) {
        return new String(byteBufferToByteArray(buffer));
    }

    public static ByteBuffer byteArrayToByteBuffer(byte[] array) {
        return ByteBuffer.wrap(array);
    }

    public static ByteBuffer stringToByteBuffer(String str) {
        return ByteBuffer.wrap(str.getBytes());
    }

    public static ByteBuffer fileToByteBuffer(String filePath) {
        try {
            byte[] bytes = Files.readAllBytes(Paths.get(filePath));
            return ByteBuffer.wrap(bytes);
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "Error reading file: " + filePath, e);
            return ByteBuffer.allocate(0); // Returning empty buffer on error
        }
    }

    public static ByteBuffer shortToByteBuffer(short value) {
        return ByteBuffer.allocate(Short.BYTES).putShort(value);
    }

    public static ByteBuffer intToByteBuffer(int value) {
        return ByteBuffer.allocate(Integer.BYTES).putInt(value);
    }

    public static ByteBuffer longToByteBuffer(long value) {
        return ByteBuffer.allocate(Long.BYTES).putLong(value);
    }

    public static ByteBuffer floatToByteBuffer(float value) {
        return ByteBuffer.allocate(Float.BYTES).putFloat(value);
    }

    public static ByteBuffer doubleToByteBuffer(double value) {
        return ByteBuffer.allocate(Double.BYTES).putDouble(value);
    }

    public static ByteArrayInputStream byteBufferToInputStream(ByteBuffer buffer) {
        return new ByteArrayInputStream(byteBufferToByteArray(buffer));
    }
}

public class turkishStemmer extends AbstractSnowballStemmer {
    private static final String[] suffixes = { "lar", "ler", "i", "e", "de", "da", "den", "dan", "in", "ın", "un", "ün", "ler", "ler", "im", "ım", "um", "üm" };
    private static final String[] vowelGroups = { "a", "e", "ı", "i", "o", "ö", "u", "ü" };

    public turkishStemmer() {
        super();
    }

    public String stem(String word) {
        if (word == null || word.isEmpty()) {
            return word;
        }
        word = applySuffixRules(word);
        return word;
    }

    private String applySuffixRules(String word) {
        for (String suffix : suffixes) {
            if (word.endsWith(suffix)) {
                word = word.substring(0, word.length() - suffix.length());
                break;
            }
        }
        return word;
    }

    private boolean checkVowelHarmony(String word) {
        for (String vowel : vowelGroups) {
            if (word.contains(vowel)) {
                return true;
            }
        }
        return false;
    }

    @Override
    public boolean equals(Object obj) {
        return obj instanceof turkishStemmer;
    }

    @Override
    public int hashCode() {
        return 31;
    }
}

public abstract class DeleteHandlerV1 {

    private static final Logger logger = Logger.getLogger(DeleteHandlerV1.class.getName());
    protected RequestContext requestContext;

    public DeleteHandlerV1(RequestContext requestContext) {
        this.requestContext = requestContext;
    }

    public void deleteEntity(Entity entity) {
        if (entity == null) {
            logger.warning("Entity to delete is null.");
            return;
        }

        logger.info("Deleting entity: " + entity.getId());
        handleSoftDelete(entity);
        deleteOwnedVertices(entity);
        deleteRelationships(entity);
        logDeletion(entity);
    }

    protected abstract void handleSoftDelete(Entity entity);

    protected abstract void deleteRelationships(Entity entity);

    protected void deleteOwnedVertices(Entity entity) {
        List<Vertex> ownedVertices = entity.getOwnedVertices();
        for (Vertex vertex : ownedVertices) {
            logger.info("Deleting owned vertex: " + vertex.getId());
            deleteVertex(vertex);
        }
    }

    protected abstract void deleteVertex(Vertex vertex);

    protected void logDeletion(Entity entity) {
        requestContext.addDeletedEntity(entity);
        logger.info("Entity deleted: " + entity.getId());
    }

    protected void handleAttributes(Map<String, Object> attributes) {
        for (Map.Entry<String, Object> entry : attributes.entrySet()) {
            Object value = entry.getValue();
            if (value instanceof List) {
                handleListAttribute(entry.getKey(), (List<?>) value);
            } else if (value instanceof Map) {
                handleMapAttribute(entry.getKey(), (Map<?, ?>) value);
            } else {
                handleSingleAttribute(entry.getKey(), value);
            }
        }
    }

    protected abstract void handleListAttribute(String key, List<?> list);

    protected abstract void handleMapAttribute(String key, Map<?, ?> map);

    protected abstract void handleSingleAttribute(String key, Object value);
}

