    @Deprecated
    public static String oldMethod() {
        return "This method is deprecated.";
    }
}

public class JsonGeneratorImpl implements JsonGenerator, JsonChars, Serializable {
    private static final long serialVersionUID = 1L;
    private Writer writer;
    private StringBuilder buffer;
    private boolean prettyPrint;
    private int indentLevel;
    private boolean inObject;
    private boolean inArray;

    public JsonGeneratorImpl(Writer writer, boolean prettyPrint) {
        this.writer = writer;
        this.prettyPrint = prettyPrint;
        this.buffer = new StringBuilder();
        this.indentLevel = 0;
        this.inObject = false;
        this.inArray = false;
    }

    @Override
    public void writeStartObject() throws IOException {
        if (inObject || inArray) {
            buffer.append(',');
        }
        buffer.append('{');
        indentLevel++;
        inObject = true;
        inArray = false;
        flushIfNeeded();
    }

    @Override
    public void writeEndObject() throws IOException {
        buffer.append('}');
        indentLevel--;
        inObject = false;
        flushIfNeeded();
    }

    @Override
    public void writeStartArray() throws IOException {
        if (inObject || inArray) {
            buffer.append(',');
        }
        buffer.append('[');
        indentLevel++;
        inArray = true;
        inObject = false;
        flushIfNeeded();
    }

    @Override
    public void writeEndArray() throws IOException {
        buffer.append(']');
        indentLevel--;
        inArray = false;
        flushIfNeeded();
    }

    @Override
    public void writeKey(String key) throws IOException {
        if (!inObject) {
            throw new IllegalStateException("Current context is not an object.");
        }
        if (buffer.length() > 1) {
            buffer.append(',');
        }
        buffer.append(escapeString(key)).append(':');
        flushIfNeeded();
    }

    @Override
    public void writeString(String value) throws IOException {
        buffer.append(escapeString(value));
        flushIfNeeded();
    }

    @Override
    public void writeNumber(Number value) throws IOException {
        buffer.append(value.toString());
        flushIfNeeded();
    }

    @Override
    public void writeBoolean(boolean value) throws IOException {
        buffer.append(value);
        flushIfNeeded();
    }

    @Override
    public void writeNull() throws IOException {
        buffer.append("null");
        flushIfNeeded();
    }

    private void flushIfNeeded() throws IOException {
        if (prettyPrint) {
            appendIndentation();
        }
        writer.write(buffer.toString());
        buffer.setLength(0);
    }

    private void appendIndentation() {
        if (prettyPrint) {
            for (int i = 0; i < indentLevel; i++) {
                buffer.append("  ");
            }
        }
    }

    private String escapeString(String value) {
        StringBuilder escaped = new StringBuilder();
        for (char c : value.toCharArray()) {
            switch (c) {
                case '"':
                    escaped.append("\\\"");
                    break;
                case '\\':
                    escaped.append("\\\\");
                    break;
                case '\b':
                    escaped.append("\\b");
                    break;
                case '\f':
                    escaped.append("\\f");
                    break;
                case '\n':
                    escaped.append("\\n");
                    break;
                case '\r':
                    escaped.append("\\r");
                    break;
                case '\t':
                    escaped.append("\\t");
                    break;
                default:
                    escaped.append(c);
            }
        }
        return escaped.toString();
    }

    public void flush() throws IOException {
        writer.flush();
    }

    public void close() throws IOException {
        writer.close();
    }
}

