public class JUnitTestRunner implements TestListener, JUnitTaskMirror.JUnitTestRunnerMirror {

    private List<RunListener> listeners = new ArrayList<>();
    private boolean haltOnError = false;
    private boolean haltOnFailure = false;
    private boolean filterStackTrace = false;

    public void addListener(RunListener listener) {
        listeners.add(listener);
    }

    public void removeListener(RunListener listener) {
        listeners.remove(listener);
    }

    public void setHaltOnError(boolean halt) {
        this.haltOnError = halt;
    }

    public void setHaltOnFailure(boolean halt) {
        this.haltOnFailure = halt;
    }

    public void setFilterStackTrace(boolean filter) {
        this.filterStackTrace = filter;
    }

    public void runTests(Class<?> testClass) {
        JUnitCore junit = new JUnitCore();
        Result result = junit.run(testClass);

        for (Failure failure : result.getFailures()) {
            reportFailure(failure);
            if (haltOnFailure) {
                break;
            }
        }

        if (result.getFailureCount() > 0 && haltOnError) {
            System.exit(1);
        }

        reportResults(result);
    }

    private void reportFailure(Failure failure) {
        for (RunListener listener : listeners) {
            try {
                listener.testFailure(failure);
            } catch (Exception e) {
                // Ignoring listener exceptions
            }
        }
    }

    private void reportResults(Result result) {
        for (RunListener listener : listeners) {
            try {
                listener.testRunFinished(result);
            } catch (Exception e) {
                // Ignoring listener exceptions
            }
        }
    }

    public static void main(String[] args) {
        JUnitTestRunner runner = new JUnitTestRunner();
        // Command line argument parsing can be added here
        runner.runTests(MyTestClass.class); // Replace MyTestClass with actual test class
    }
}

