        builder.add("/name", "John Doe");
        String expected = "[{\"op\":\"add\",\"path\":\"/name\",\"value\":\"John Doe\"}]";
        assertEquals(expected, builder.build().toString());
    }

    @Test
    public void testRemove() {
        JsonPatchBuilder builder = new JsonPatchBuilder();
        builder.remove("/name");
        String expected = "[{\"op\":\"remove\",\"path\":\"/name\"}]";
        assertEquals(expected, builder.build().toString());
    }

    @Test
    public void testReplace() {
        JsonPatchBuilder builder = new JsonPatchBuilder();
        builder.replace("/name", "Jane Doe");
        String expected = "[{\"op\":\"replace\",\"path\":\"/name\",\"value\":\"Jane Doe\"}]";
        assertEquals(expected, builder.build().toString());
    }

    @Test
    public void testMove() {
        JsonPatchBuilder builder = new JsonPatchBuilder();
        builder.move("/oldPath", "/newPath");
        String expected = "[{\"op\":\"move\",\"from\":\"/oldPath\",\"path\":\"/newPath\"}]";
        assertEquals(expected, builder.build().toString());
    }

    @Test
    public void testCopy() {
        JsonPatchBuilder builder = new JsonPatchBuilder();
        builder.copy("/sourcePath", "/destinationPath");
        String expected = "[{\"op\":\"copy\",\"from\":\"/sourcePath\",\"path\":\"/destinationPath\"}]";
        assertEquals(expected, builder.build().toString());
    }

    @Test
    public void testTest() {
        JsonPatchBuilder builder = new JsonPatchBuilder();
        builder.test("/name", "John Doe");
        String expected = "[{\"op\":\"test\",\"path\":\"/name\",\"value\":\"John Doe\"}]";
        assertEquals(expected, builder.build().toString());
    }

    @Test
    public void testInvalidPath() {
        JsonPatchBuilder builder = new JsonPatchBuilder();
        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            builder.add("", "value");
        });
        assertEquals("Path cannot be empty", exception.getMessage());
    }

    @Test
    public void testInvalidOperation() {
        JsonPatchBuilder builder = new JsonPatchBuilder();
        Exception exception = assertThrows(UnsupportedOperationException.class, () -> {
            builder.invalidOperation("/path");
        });
        assertEquals("Invalid operation", exception.getMessage());
    }

    // Additional tests for various data types
    @Test
    public void testAddInteger() {
        JsonPatchBuilder builder = new JsonPatchBuilder();
        builder.add("/age", 30);
        String expected = "[{\"op\":\"add\",\"path\":\"/age\",\"value\":30}]";
        assertEquals(expected, builder.build().toString());
    }

    @Test
    public void testAddBoolean() {
        JsonPatchBuilder builder = new JsonPatchBuilder();
        builder.add("/isActive", true);
        String expected = "[{\"op\":\"add\",\"path\":\"/isActive\",\"value\":true}]";
        assertEquals(expected, builder.build().toString());
    }

    @Test
    public void testAddJsonObject() {
        JsonPatchBuilder builder = new JsonPatchBuilder();
        Map<String, Object> jsonObject = new HashMap<>();
        jsonObject.put("key", "value");
        builder.add("/object", jsonObject);
        String expected = "[{\"op\":\"add\",\"path\":\"/object\",\"value\":{\"key\":\"value\"}}]";
        assertEquals(expected, builder.build().toString());
    }

    @Test
    public void testAddJsonArray() {
        JsonPatchBuilder builder = new JsonPatchBuilder();
        builder.add("/array", new int[]{1, 2, 3});
        String expected = "[{\"op\":\"add\",\"path\":\"/array\",\"value\":[1,2,3]}]";
        assertEquals(expected, builder.build().toString());
    }
