public class TestThrottlingScheduler {

    private ThrottlingScheduler throttlingScheduler;
    private HighResolutionClock clock;
    private ScheduledExecutorService executorService;

    @Before
    public void setUp() {
        clock = mock(HighResolutionClock.class);
        executorService = mock(ScheduledExecutorService.class);
        throttlingScheduler = new ThrottlingScheduler(clock, executorService);
    }

    @Test
    public void testInitialState() {
        assertEquals(0, throttlingScheduler.getPendingNanos());
        assertEquals(0, throttlingScheduler.getRequestedDelay());
    }

    @Test
    public void testSetWorkRate() {
        throttlingScheduler.setWorkRate(100);
        assertEquals(100, throttlingScheduler.getWorkRate());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSetNegativeWorkRate() {
        throttlingScheduler.setWorkRate(-1);
    }

    @Test
    public void testScheduleTaskWithValidWorkFactor() {
        throttlingScheduler.setWorkRate(100);
        throttlingScheduler.scheduleTask(() -> {}, 50);
        verify(executorService).schedule(any(Runnable.class), eq(50L), any(TimeUnit.class));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testScheduleTaskWithExcessiveWorkFactor() {
        throttlingScheduler.setWorkRate(100);
        throttlingScheduler.scheduleTask(() -> {}, 200);
    }

    @Test
    public void testDelayOvershoot() {
        throttlingScheduler.setWorkRate(100);
        throttlingScheduler.scheduleTask(() -> {}, 150);
        assertTrue(throttlingScheduler.getPendingNanos() > 0);
    }

    @Test
    public void testDelayUndershoot() {
        throttlingScheduler.setWorkRate(100);
        throttlingScheduler.scheduleTask(() -> {}, 50);
        assertTrue(throttlingScheduler.getPendingNanos() == 0);
    }
}

