public class ExposedByteArrayOutputStreamTest {

    @Test
    public void testWriteZeroLengthArray() {
        ExposedByteArrayOutputStream exposedStream = new ExposedByteArrayOutputStream();
        ByteArrayOutputStream standardStream = new ByteArrayOutputStream();

        exposedStream.write(new byte[0]);
        standardStream.write(new byte[0]);

        assertArrayEquals(exposedStream.toByteArray(), standardStream.toByteArray());
        assertEquals(exposedStream.size(), standardStream.size());
    }

    @Test
    public void testWriteSingleByte() {
        ExposedByteArrayOutputStream exposedStream = new ExposedByteArrayOutputStream();
        ByteArrayOutputStream standardStream = new ByteArrayOutputStream();

        byte singleByte = 5;
        exposedStream.write(singleByte);
        standardStream.write(singleByte);

        assertArrayEquals(exposedStream.toByteArray(), standardStream.toByteArray());
        assertEquals(exposedStream.size(), standardStream.size());
    }

    @Test
    public void testWriteByteArray() {
        ExposedByteArrayOutputStream exposedStream = new ExposedByteArrayOutputStream();
        ByteArrayOutputStream standardStream = new ByteArrayOutputStream();

        byte[] byteArray = {1, 2, 3, 4, 5};
        exposedStream.write(byteArray);
        standardStream.write(byteArray);

        assertArrayEquals(exposedStream.toByteArray(), standardStream.toByteArray());
        assertEquals(exposedStream.size(), standardStream.size());
    }

    @Test
    public void testWritePartialArray() {
        ExposedByteArrayOutputStream exposedStream = new ExposedByteArrayOutputStream();
        ByteArrayOutputStream standardStream = new ByteArrayOutputStream();

        byte[] byteArray = {1, 2, 3, 4, 5};
        exposedStream.write(byteArray, 1, 3);
        standardStream.write(byteArray, 1, 3);

        assertArrayEquals(exposedStream.toByteArray(), standardStream.toByteArray());
        assertEquals(exposedStream.size(), standardStream.size());
    }

    @Test
    public void testReset() {
        ExposedByteArrayOutputStream exposedStream = new ExposedByteArrayOutputStream();
        ByteArrayOutputStream standardStream = new ByteArrayOutputStream();

        byte[] byteArray = {1, 2, 3};
        exposedStream.write(byteArray);
        standardStream.write(byteArray);

        exposedStream.reset();
        standardStream.reset();

        assertArrayEquals(exposedStream.toByteArray(), standardStream.toByteArray());
        assertEquals(exposedStream.size(), standardStream.size());
    }

    @Test
    public void testEqualityAfterMultipleWrites() {
        ExposedByteArrayOutputStream exposedStream = new ExposedByteArrayOutputStream();
        ByteArrayOutputStream standardStream = new ByteArrayOutputStream();

        byte[] byteArray1 = {1, 2, 3};
        byte[] byteArray2 = {4, 5, 6};

        exposedStream.write(byteArray1);
        standardStream.write(byteArray1);
        exposedStream.write(byteArray2);
        standardStream.write(byteArray2);

        assertArrayEquals(exposedStream.toByteArray(), standardStream.toByteArray());
        assertEquals(exposedStream.size(), standardStream.size());
    }
}

