public class StaxUtilsTest {

    @Test
    public void testCreateXMLStreamReader() throws Exception {
        String xml = "<root><child>Test</child></root>";
        XMLStreamReader reader = XMLInputFactory.newInstance().createXMLStreamReader(new StringReader(xml));
        reader.next(); // Move to the first element
        assertEquals("root", reader.getLocalName());
    }

    @Test
    public void testCommentNodes() throws Exception {
        String xml = "<root><!-- Comment --><child>Test</child></root>";
        XMLStreamReader reader = XMLInputFactory.newInstance().createXMLStreamReader(new StringReader(xml));
        while (reader.hasNext()) {
            reader.next();
            if (reader.getEventType() == XMLStreamReader.COMMENT) {
                assertEquals(" Comment ", reader.getText().trim());
            }
        }
    }

    @Test
    public void testNextElement() throws Exception {
        String xml = "<root><child>Test</child></root>";
        XMLStreamReader reader = XMLInputFactory.newInstance().createXMLStreamReader(new StringReader(xml));
        reader.next(); // Move to root
        reader.next(); // Move to child
        assertEquals("child", reader.getLocalName());
    }

    @Test
    public void testCopyXMLContent() throws Exception {
        String xml = "<root><child>Test</child></root>";
        XMLStreamReader reader = XMLInputFactory.newInstance().createXMLStreamReader(new StringReader(xml));
        StringWriter stringWriter = new StringWriter();
        XMLStreamWriter writer = XMLOutputFactory.newInstance().createXMLStreamWriter(stringWriter);

        while (reader.hasNext()) {
            reader.next();
            writer.copy(reader);
        }
        writer.flush();
        assertEquals(xml, stringWriter.toString());
    }

    @Test
    public void testNamespaceAwareness() throws Exception {
        String xml = "<root xmlns:ns=\"http://example.com/ns\"><ns:child>Test</ns:child></root>";
        XMLStreamReader reader = XMLInputFactory.newInstance().createXMLStreamReader(new StringReader(xml));
        reader.next(); // Move to root
        assertEquals("http://example.com/ns", reader.getNamespaceURI("ns"));
    }

    @Test
    public void testProcessingInstructions() throws Exception {
        String xml = "<?xml version=\"1.0\"?><root><?pi Test?></root>";
        XMLStreamReader reader = XMLInputFactory.newInstance().createXMLStreamReader(new StringReader(xml));
        while (reader.hasNext()) {
            reader.next();
            if (reader.getEventType() == XMLStreamReader.PROCESSING_INSTRUCTION) {
                assertEquals("pi", reader.getPITarget());
                assertEquals(" Test", reader.getPIData());
            }
        }
    }

    @Test
    public void testEmptyNamespaces() throws Exception {
        String xml = "<root xmlns=\"\"><child>Test</child></root>";
        XMLStreamReader reader = XMLInputFactory.newInstance().createXMLStreamReader(new StringReader(xml));
        reader.next(); // Move to root
        assertEquals("", reader.getNamespaceURI());
    }

    @Test
    public void testDefaultPrefixes() throws Exception {
        String xml = "<root xmlns:ns=\"http://example.com/ns\"><ns:child>Test</ns:child></root>";
        XMLStreamReader reader = XMLInputFactory.newInstance().createXMLStreamReader(new StringReader(xml));
        reader.next(); // Move to root
        assertEquals("ns", reader.getPrefix());
    }
}

