    @BeforeEach
    public void setUp() {
        corsFilter = new CorsFilter();
        request = mock(HttpServletRequest.class);
        response = mock(HttpServletResponse.class);
        chain = mock(FilterChain.class);
    }

    @Test
    public void testSimpleGetRequest() throws Exception {
        when(request.getMethod()).thenReturn("GET");
        corsFilter.doFilter(request, response, chain);
        verify(response).setHeader("Access-Control-Allow-Origin", "*");
    }

    @Test
    public void testSimplePostRequest() throws Exception {
        when(request.getMethod()).thenReturn("POST");
        corsFilter.doFilter(request, response, chain);
        verify(response).setHeader("Access-Control-Allow-Origin", "*");
    }

    @Test
    public void testSimpleHeadRequest() throws Exception {
        when(request.getMethod()).thenReturn("HEAD");
        corsFilter.doFilter(request, response, chain);
        verify(response).setHeader("Access-Control-Allow-Origin", "*");
    }

    @Test
    public void testPreflightRequestWithValidOrigin() throws Exception {
        when(request.getMethod()).thenReturn("OPTIONS");
        when(request.getHeader("Origin")).thenReturn("http://valid-origin.com");
        corsFilter.doFilter(request, response, chain);
        verify(response).setHeader("Access-Control-Allow-Origin", "http://valid-origin.com");
        verify(response).setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
    }

