public abstract class BspService implements Watcher {
    protected ZooKeeper zooKeeper;
    protected String jobStatePath;
    protected String applicationAttemptsPath;
    protected String superstepPath;
    protected AtomicInteger currentSuperstep;
    protected AtomicInteger applicationAttempt;

    public BspService(ZooKeeper zooKeeper, String jobStatePath, String applicationAttemptsPath, String superstepPath) {
        this.zooKeeper = zooKeeper;
        this.jobStatePath = jobStatePath;
        this.applicationAttemptsPath = applicationAttemptsPath;
        this.superstepPath = superstepPath;
        this.currentSuperstep = new AtomicInteger(0);
        this.applicationAttempt = new AtomicInteger(0);
    }

    public int getCurrentSuperstep() {
        return currentSuperstep.get();
    }

    public void setCurrentSuperstep(int superstep) {
        currentSuperstep.set(superstep);
        // Update ZooKeeper with the new superstep
        updateZooKeeper(superstepPath, String.valueOf(superstep));
    }

    public int getApplicationAttempt() {
        return applicationAttempt.get();
    }

    public void setApplicationAttempt(int attempt) {
        applicationAttempt.set(attempt);
        // Update ZooKeeper with the new application attempt
        updateZooKeeper(applicationAttemptsPath, String.valueOf(attempt));
    }

    protected void updateZooKeeper(String path, String data) {
        try {
            if (zooKeeper.exists(path, false) == null) {
                zooKeeper.create(path, data.getBytes(), null, null);
            } else {
                zooKeeper.setData(path, data.getBytes(), -1);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void processEvent(WatchedEvent event) {
        // Handle events from ZooKeeper
        switch (event.getType()) {
            case NodeCreated:
                handleNodeCreated(event.getPath());
                break;
            case NodeDeleted:
                handleNodeDeleted(event.getPath());
                break;
            case NodeDataChanged:
                handleNodeDataChanged(event.getPath());
                break;
            case NodeChildrenChanged:
                handleNodeChildrenChanged(event.getPath());
                break;
            default:
                break;
        }
    }

    protected abstract void handleNodeCreated(String path);
    protected abstract void handleNodeDeleted(String path);
    protected abstract void handleNodeDataChanged(String path);
    protected abstract void handleNodeChildrenChanged(String path);

    public abstract void startJob();
    public abstract void stopJob();
    public abstract List<String> getInputSplits();
}

