public class Time extends Magnitude {
    private int hour;
    private int minute;
    private int second;

    public Time(int hour, int minute, int second) {
        setTime(hour, minute, second);
    }

    public Time(Date date) {
        this(date.getHours(), date.getMinutes(), date.getSeconds());
    }

    public Time(java.sql.Date date) {
        this(date.getHours(), date.getMinutes(), date.getSeconds());
    }

    public Time(LocalTime localTime) {
        this(localTime.getHour(), localTime.getMinute(), localTime.getSecond());
    }

    private void setTime(int hour, int minute, int second) {
        if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || second < 0 || second > 59) {
            throw new IllegalArgumentException("Invalid time values");
        }
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    public int getHour() {
        return hour;
    }

    public int getMinute() {
        return minute;
    }

    public int getSecond() {
        return second;
    }

    public long toMilliseconds() {
        return (hour * 3600 + minute * 60 + second) * 1000;
    }

    public String toString() {
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("HH:mm:ss");
        return LocalTime.of(hour, minute, second).format(formatter);
    }

    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Time)) return false;
        Time other = (Time) obj;
        return hour == other.hour && minute == other.minute && second == other.second;
    }

    public int compareTo(Time other) {
        if (this.hour != other.hour) {
            return Integer.compare(this.hour, other.hour);
        }
        if (this.minute != other.minute) {
            return Integer.compare(this.minute, other.minute);
        }
        return Integer.compare(this.second, other.second);
    }
}

