@Converter
public class IOConverter {
    private static final Logger logger = Logger.getLogger(IOConverter.class.getName());

    public static InputStream urlToInputStream(URL url) {
        try {
            return url.openStream();
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error converting URL to InputStream", e);
            return null;
        }
    }

    public static BufferedReader urlToBufferedReader(URL url) {
        return new BufferedReader(new InputStreamReader(urlToInputStream(url)));
    }

    public static InputStream stringToInputStream(String str) {
        return new ByteArrayInputStream(str.getBytes(StandardCharsets.UTF_8));
    }

    public static StringReader stringToStringReader(String str) {
        return new StringReader(str);
    }

    public static File fileToFile(File file) {
        return file;
    }

    public static BufferedOutputStream outputStreamToBufferedOutputStream(OutputStream os) {
        return new BufferedOutputStream(os);
    }

    public static BufferedWriter writerToBufferedWriter(Writer writer) {
        return new BufferedWriter(writer);
    }

    public static Reader inputStreamToReader(InputStream is) {
        return new InputStreamReader(is);
    }

    public static Writer outputStreamToWriter(OutputStream os) {
        return new OutputStreamWriter(os);
    }

    public static String byteArrayToString(byte[] bytes) {
        return new String(bytes, StandardCharsets.UTF_8);
    }

    public static byte[] stringToByteArray(String str) {
        return str.getBytes(StandardCharsets.UTF_8);
    }

    public static String readFromBufferedReader(BufferedReader reader) {
        StringBuilder sb = new StringBuilder();
        String line;
        try {
            while ((line = reader.readLine()) != null) {
                sb.append(line).append(System.lineSeparator());
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error reading from BufferedReader", e);
        }
        return sb.toString();
    }

    public static void copy(InputStream input, OutputStream output) {
        byte[] buffer = new byte[1024];
        int bytesRead;
        try {
            while ((bytesRead = input.read(buffer)) != -1) {
                output.write(buffer, 0, bytesRead);
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error copying data from InputStream to OutputStream", e);
        }
    }

    public static Object deserialize(InputStream input) {
        try (ObjectInputStream ois = new ObjectInputStream(input)) {
            return ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            logger.log(Level.SEVERE, "Error during deserialization", e);
            return null;
        }
    }

    public static void serialize(Object obj, OutputStream output) {
        try (ObjectOutputStream oos = new ObjectOutputStream(output)) {
            oos.writeObject(obj);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error during serialization", e);
        }
    }
}

