public class AsyncTaskWorker implements TaskCallbackListener {
    private TaskInstance taskInstance;
    private CallbackManager callbackManager;
    private TaskState taskState;
    private long windowInterval;
    private long commitInterval;

    public AsyncTaskWorker(TaskInstance taskInstance, long windowInterval, long commitInterval) {
        this.taskInstance = taskInstance;
        this.windowInterval = windowInterval;
        this.commitInterval = commitInterval;
        this.callbackManager = new CallbackManager();
        this.taskState = TaskState.INITIALIZED;
        schedulePeriodicOperations();
    }

    private void schedulePeriodicOperations() {
        // Schedule windowing and committing operations
        Timer windowTimer = new Timer();
        windowTimer.schedule(new TimerTask() {
            @Override
            public void run() {
                handleWindowOperation();
            }
        }, windowInterval, windowInterval);

        Timer commitTimer = new Timer();
        commitTimer.schedule(new TimerTask() {
            @Override
            public void run() {
                commitResults();
            }
        }, commitInterval, commitInterval);
    }

    public void processMessage(Message message) {
        if (taskState == TaskState.RUNNING) {
            // Process the incoming message
            taskInstance.process(message);
            logEvent("Message processed: " + message);
        } else {
            logEvent("Task is not running. Message ignored: " + message);
        }
    }

    private void handleWindowOperation() {
        if (taskState == TaskState.RUNNING) {
            // Handle window operations
            logEvent("Window operation executed.");
        }
    }

    private void commitResults() {
        if (taskState == TaskState.RUNNING) {
            // Commit results
            logEvent("Results committed.");
        }
    }

    public void onTaskComplete() {
        taskState = TaskState.COMPLETED;
        callbackManager.notifyTaskComplete();
        logEvent("Task completed.");
    }

    public void onTaskFailure(Exception e) {
        taskState = TaskState.FAILED;
        callbackManager.notifyTaskFailure(e);
        logEvent("Task failed: " + e.getMessage());
    }

    private void logEvent(String message) {
        System.out.println("LOG: " + message);
    }

    // Additional methods for managing task state and callbacks can be added here
}

