public class EventImpl implements Event {
    private final Event event;
    private final long timestamp;
    private final String type;
    private final String subtype;
    private static final Set<String> EXCLUDED_KEYS = new HashSet<>(Set.of("key1", "key2", "key3"));

    public EventImpl(Event event, long timestamp) {
        this.event = event;
        this.timestamp = (timestamp > 0) ? timestamp : System.currentTimeMillis();
        this.type = determineType(event.getTopic());
        this.subtype = extractSubtype(event.getTopic());
    }

    private String determineType(String topic) {
        if (topic.startsWith("shell")) return "shell";
        if (topic.startsWith("log")) return "log";
        if (topic.startsWith("service")) return "service";
        if (topic.startsWith("bundle")) return "bundle";
        if (topic.startsWith("login")) return "login";
        if (topic.startsWith("jmx")) return "jmx";
        if (topic.startsWith("framework")) return "framework";
        if (topic.startsWith("web")) return "web";
        if (topic.startsWith("repositories")) return "repositories";
        if (topic.startsWith("features")) return "features";
        if (topic.startsWith("blueprint")) return "blueprint";
        return "unknown";
    }

    private String extractSubtype(String topic) {
        String[] parts = topic.split("/");
        return (parts.length > 1) ? parts[1] : "default";
    }

    public long getTimestamp() {
        return timestamp;
    }

    public String getType() {
        return type;
    }

    public String getSubtype() {
        return subtype;
    }

    public Map<String, Object> getProperties() {
        return event.getProperties();
    }

    public Object getProperty(String key) {
        return event.getProperty(key);
    }

    public Iterable<String> getPropertyKeys() {
        return new Iterable<String>() {
            @Override
            public Iterator<String> iterator() {
                Set<String> keys = new HashSet<>(event.getProperties().keySet());
                keys.removeAll(EXCLUDED_KEYS);
                return keys.iterator();
            }
        };
    }
}

