public class JsonSerializer implements ODataSerializer {
    private boolean isServerMode;

    public JsonSerializer(boolean isServerMode) {
        this.isServerMode = isServerMode;
    }

    public void serialize(EntityCollection entityCollection, JsonGenerator jsonGenerator) {
        jsonGenerator.writeStartArray();
        for (Entity entity : entityCollection.getEntities()) {
            serialize(entity, jsonGenerator);
        }
        jsonGenerator.writeEnd();
    }

    public void serialize(Entity entity, JsonGenerator jsonGenerator) {
        jsonGenerator.writeStartObject();
        for (Property property : entity.getProperties()) {
            serialize(property, jsonGenerator);
        }
        for (Link link : entity.getLinks()) {
            serialize(link, jsonGenerator);
        }
        jsonGenerator.writeEnd();
    }

    public void serialize(Property property, JsonGenerator jsonGenerator) {
        jsonGenerator.write(property.getName(), property.getValue().toString());
    }

    public void serialize(Link link, JsonGenerator jsonGenerator) {
        jsonGenerator.writeStartObject();
        jsonGenerator.write("uri", link.getUri());
        jsonGenerator.writeEnd();
    }

    public void serialize(ComplexType complexType, JsonGenerator jsonGenerator) {
        jsonGenerator.writeStartObject();
        for (Property property : complexType.getProperties()) {
            serialize(property, jsonGenerator);
        }
        jsonGenerator.writeEnd();
    }

    public void serialize(GeospatialValue geospatialValue, JsonGenerator jsonGenerator) {
        jsonGenerator.write("geospatial", geospatialValue.toString());
    }

    public void serialize(Collection<?> collection, JsonGenerator jsonGenerator) {
        jsonGenerator.writeStartArray();
        for (Object item : collection) {
            if (item instanceof Entity) {
                serialize((Entity) item, jsonGenerator);
            } else if (item instanceof Property) {
                serialize((Property) item, jsonGenerator);
            }
        }
        jsonGenerator.writeEnd();
    }

    public void writeMetadata(JsonGenerator jsonGenerator) {
        if (isServerMode) {
            jsonGenerator.writeStartObject();
            jsonGenerator.write("metadata", "OData Metadata");
            jsonGenerator.writeEnd();
        }
    }
}

