public class UpdateBuilder {
    private List<String> prefixes;
    private List<String> insertStatements;
    private List<String> deleteStatements;
    private String whereClause;
    private List<String> optionalClauses;
    private List<String> filterClauses;
    private List<String> graphContexts;
    private List<String> subqueries;

    public UpdateBuilder() {
        this.prefixes = new ArrayList<>();
        this.insertStatements = new ArrayList<>();
        this.deleteStatements = new ArrayList<>();
        this.optionalClauses = new ArrayList<>();
        this.filterClauses = new ArrayList<>();
        this.graphContexts = new ArrayList<>();
        this.subqueries = new ArrayList<>();
    }

    public UpdateBuilder addPrefix(String prefix, String uri) {
        prefixes.add("PREFIX " + prefix + ": <" + uri + ">");
        return this;
    }

    public UpdateBuilder addInsert(String triple) {
        insertStatements.add("INSERT DATA { " + triple + " }");
        return this;
    }

    public UpdateBuilder addDelete(String triple) {
        deleteStatements.add("DELETE DATA { " + triple + " }");
        return this;
    }

    public UpdateBuilder setWhere(String where) {
        this.whereClause = where;
        return this;
    }

    public UpdateBuilder addOptional(String optional) {
        optionalClauses.add("OPTIONAL { " + optional + " }");
        return this;
    }

    public UpdateBuilder addFilter(String filter) {
        filterClauses.add("FILTER (" + filter + ")");
        return this;
    }

    public UpdateBuilder addGraphContext(String graph) {
        graphContexts.add("GRAPH <" + graph + "> {");
        return this;
    }

    public UpdateBuilder closeGraphContext() {
        if (!graphContexts.isEmpty()) {
            graphContexts.add("}");
        }
        return this;
    }

    public UpdateBuilder addSubquery(String subquery) {
        subqueries.add("{" + subquery + "}");
        return this;
    }

    public String build() {
        StringBuilder updateRequest = new StringBuilder();

        for (String prefix : prefixes) {
            updateRequest.append(prefix).append("\n");
        }

        if (!deleteStatements.isEmpty()) {
            updateRequest.append(String.join("\n", deleteStatements)).append("\n");
        }

        if (!insertStatements.isEmpty()) {
            updateRequest.append(String.join("\n", insertStatements)).append("\n");
        }

        if (whereClause != null) {
            updateRequest.append("WHERE { ").append(whereClause).append(" }\n");
        }

        for (String optional : optionalClauses) {
            updateRequest.append(optional).append("\n");
        }

        for (String filter : filterClauses) {
            updateRequest.append(filter).append("\n");
        }

        for (String graph : graphContexts) {
            updateRequest.append(graph).append("\n");
        }

        for (String subquery : subqueries) {
            updateRequest.append(subquery).append("\n");
        }

        return updateRequest.toString().trim();
    }
}

