public abstract class AbstractGeospatialType<T extends Geospatial> {
    private static final String SRID_PATTERN = "SRID=\\d+;";
    private static final String GEOMETRIC_TYPE_PATTERN = "([A-Za-z]+)\\((.*)\\)";

    protected String srid;
    protected String geometricType;

    public AbstractGeospatialType(String geospatialString) {
        parseGeospatialString(geospatialString);
    }

    private void parseGeospatialString(String geospatialString) {
        if (geospatialString == null || geospatialString.isEmpty()) {
            throw new IllegalArgumentException("Geospatial string cannot be null or empty");
        }

        Pattern sridPattern = Pattern.compile(SRID_PATTERN);
        Pattern geometricTypePattern = Pattern.compile(GEOMETRIC_TYPE_PATTERN);

        var sridMatcher = sridPattern.matcher(geospatialString);
        if (sridMatcher.find()) {
            this.srid = sridMatcher.group();
        }

        var geometricMatcher = geometricTypePattern.matcher(geospatialString);
        if (geometricMatcher.find()) {
            this.geometricType = geometricMatcher.group(1);
        } else {
            throw new IllegalArgumentException("Invalid geometric type in geospatial string");
        }
    }

    public abstract String toGeospatialString();

    public String getSrid() {
        return srid;
    }

    public String getGeometricType() {
        return geometricType;
    }
}

