public class BlockingSignalEventHandlerTest {

    private BlockingSignalEventHandler eventHandler;
    private AtomicInteger counter;

    @BeforeEach
    public void setUp() {
        counter = new AtomicInteger(0);
        eventHandler = new BlockingSignalEventHandler(counter);
    }

    @Test
    public void testSingleEventEmission() {
        eventHandler.handleEvent();
        assertEquals(1, counter.get());
    }

    @Test
    public void testMultipleEventEmissions() {
        eventHandler.handleEvent();
        eventHandler.handleEvent();
        eventHandler.handleEvent();
        assertEquals(3, counter.get());
    }

    @Test
    public void testConcurrentEventHandling() throws InterruptedException {
        Thread thread1 = new Thread(() -> {
            for (int i = 0; i < 100; i++) {
                eventHandler.handleEvent();
            }
        });

        Thread thread2 = new Thread(() -> {
            for (int i = 0; i < 100; i++) {
                eventHandler.handleEvent();
            }
        });

        thread1.start();
        thread2.start();
        thread1.join();
        thread2.join();

        assertEquals(200, counter.get());
    }

    @Test
    public void testResetEventHandler() {
        eventHandler.handleEvent();
        eventHandler.reset();
        assertEquals(0, counter.get());
    }
}

