public class Processor<Iface> extends AbstractNonblockingServer.Processor<Iface> {
    private final Map<String, ProcessFunction<Iface, ? extends TBase>> processMap;

    public Processor(Iface iface) {
        super(iface);
        processMap = new HashMap<>();
        processMap.put("login", new LoginProcessFunction());
        processMap.put("get", new GetProcessFunction());
        processMap.put("insert", new InsertProcessFunction());
        processMap.put("manageSchema", new ManageSchemaProcessFunction());
    }

    @Override
    public void process(TProtocol inputProtocol, TProtocol outputProtocol) throws TException {
        String methodName = inputProtocol.readString();
        ProcessFunction<Iface, ? extends TBase> processFunction = processMap.get(methodName);
        if (processFunction != null) {
            processFunction.process(inputProtocol, outputProtocol);
        } else {
            throw new TException("Unknown method: " + methodName);
        }
    }

    private abstract class ProcessFunction<Iface, T extends TBase> {
