public class ValidatorAction {
    private String name;
    private String className;
    private String methodName;
    private Map<String, Object> dependencies;
    private static final Logger logger = Logger.getLogger(ValidatorAction.class.getName());

    public ValidatorAction(String name, String className, String methodName) {
        this.name = name;
        this.className = className;
        this.methodName = methodName;
        this.dependencies = new HashMap<>();
    }

    public void addDependency(String key, Object value) {
