    }

    public Object executeValidation() {
        try {
            Class<?> clazz = Class.forName(className);
            Object instance = clazz.getDeclaredConstructor().newInstance();
            return clazz.getMethod(methodName, Map.class).invoke(instance, dependencies);
        } catch (Exception e) {
            logger.severe("Validation execution failed: " + e.getMessage());
            return null;
        }
    }

    public String getName() {
        return name;
    }

    public String getClassName() {
        return className;
    }

    public String getMethodName() {
        return methodName;
    }

    public Map<String, Object> getDependencies() {
        return dependencies;
    }
}

public class RouteDotGenerator extends GraphGeneratorSupport {

    private Map<String, String> nodeIds = new HashMap<>();

    public String generateDot(List<Route> routes) {
        StringBuilder dotBuilder = new StringBuilder();
        dotBuilder.append("digraph G {\n");

        for (Route route : routes) {
            String groupName = route.getGroupName();
            createSubgraph(dotBuilder, groupName, route.getProcessors());
        }

        dotBuilder.append("}\n");
        return dotBuilder.toString();
    }

    private void createSubgraph(StringBuilder dotBuilder, String groupName, List<Processor> processors) {
        dotBuilder.append("subgraph cluster_").append(groupName).append(" {\n");
        dotBuilder.append("label=\"").append(groupName).append("\";\n");

        for (Processor processor : processors) {
            String nodeId = getNodeId(processor);
            dotBuilder.append(nodeId).append(" [label=\"").append(processor.getName()).append("\"");
            if (processor.isMulticast()) {
                dotBuilder.append(", shape=ellipse");
            }
            dotBuilder.append("];\n");
        }

        for (Processor processor : processors) {
            List<Processor> nextProcessors = processor.getNextProcessors();
            for (Processor nextProcessor : nextProcessors) {
                String fromId = getNodeId(processor);
                String toId = getNodeId(nextProcessor);
                dotBuilder.append(fromId).append(" -> ").append(toId).append(";\n");
            }
        }

        dotBuilder.append("}\n");
    }

    private String getNodeId(Processor processor) {
        return nodeIds.computeIfAbsent(processor.getId(), id -> "node_" + id);
    }
}

