public class DBInterfaceHSQLDB extends Database implements IDBInterface {

    private Connection connection;

    public DBInterfaceHSQLDB(String dbUrl) {
        super(dbUrl);
    }

    public void connect() throws SQLException {
        if (connection == null || connection.isClosed()) {
            connection = DriverManager.getConnection(getDbUrl());
        }
    }

    public void disconnect() throws SQLException {
        if (connection != null && !connection.isClosed()) {
            connection.close();
        }
    }

    public void executeUpdate(String sql) throws SQLException {
        try (Statement stmt = connection.createStatement()) {
            stmt.executeUpdate(sql);
        }
    }

    public ResultSet executeQuery(String sql) throws SQLException {
        Statement stmt = connection.createStatement();
        return stmt.executeQuery(sql);
    }

    public void beginTransaction() throws SQLException {
        connection.setAutoCommit(false);
    }

    public void commitTransaction() throws SQLException {
        connection.commit();
        connection.setAutoCommit(true);
    }

    public void rollbackTransaction() throws SQLException {
        connection.rollback();
        connection.setAutoCommit(true);
    }

    public void createUser(String username, String password) throws SQLException {
        String sql = "CREATE USER " + username + " PASSWORD '" + password + "'";
        executeUpdate(sql);
    }

    public void deleteUser(String username) throws SQLException {
        String sql = "DROP USER " + username;
        executeUpdate(sql);
    }

    public void createDatabase(String dbName) throws SQLException {
        String sql = "CREATE SCHEMA " + dbName;
        executeUpdate(sql);
    }

    public void deleteDatabase(String dbName) throws SQLException {
        String sql = "DROP SCHEMA " + dbName + " CASCADE";
        executeUpdate(sql);
    }

    public List<String> getTableSchemas() throws SQLException {
        List<String> schemas = new ArrayList<>();
        ResultSet rs = executeQuery("SELECT * FROM INFORMATION_SCHEMA.TABLES");
        while (rs.next()) {
            schemas.add(rs.getString("TABLE_NAME"));
        }
        return schemas;
    }

    public List<String> getIndexes(String tableName) throws SQLException {
        List<String> indexes = new ArrayList<>();
        ResultSet rs = executeQuery("SELECT * FROM INFORMATION_SCHEMA.INDEXES WHERE TABLE_NAME = '" + tableName + "'");
        while (rs.next()) {
            indexes.add(rs.getString("INDEX_NAME"));
        }
        return indexes;
    }

    public void createTable(String tableName, String columns) throws SQLException {
        String sql = "CREATE TABLE " + tableName + " (" + columns + ")";
        executeUpdate(sql);
    }

    public void deleteTable(String tableName) throws SQLException {
        String sql = "DROP TABLE " + tableName;
        executeUpdate(sql);
    }

    public void recursiveDelete(File file) {
        if (file.isDirectory()) {
            for (File subFile : file.listFiles()) {
                recursiveDelete(subFile);
            }
        }
        file.delete();
    }
}

public class CapturingLogger implements Logger {
    private final Logger wrappedLogger;
    private final List<String> traceMessages = new ArrayList<>();
    private final List<String> debugMessages = new ArrayList<>();
    private final List<String> infoMessages = new ArrayList<>();
    private final List<String> warnMessages = new ArrayList<>();
    private final List<String> errorMessages = new ArrayList<>();

    public CapturingLogger(Logger wrappedLogger) {
        this.wrappedLogger = wrappedLogger;
    }

    @Override
    public void trace(String message) {
        if (isTraceEnabled()) {
            wrappedLogger.trace(message);
            traceMessages.add(message);
        }
    }

    @Override
    public void debug(String message) {
        if (isDebugEnabled()) {
            wrappedLogger.debug(message);
            debugMessages.add(message);
        }
    }

    @Override
    public void info(String message) {
        if (isInfoEnabled()) {
            wrappedLogger.info(message);
            infoMessages.add(message);
        }
    }

    @Override
    public void warn(String message) {
        if (isWarnEnabled()) {
            wrappedLogger.warn(message);
            warnMessages.add(message);
        }
    }

    @Override
    public void error(String message) {
        if (isErrorEnabled()) {
            wrappedLogger.error(message);
            errorMessages.add(message);
        }
    }

    public List<String> getTraceMessages() {
        return Collections.unmodifiableList(traceMessages);
    }

    public List<String> getDebugMessages() {
        return Collections.unmodifiableList(debugMessages);
    }

    public List<String> getInfoMessages() {
        return Collections.unmodifiableList(infoMessages);
    }

    public List<String> getWarnMessages() {
        return Collections.unmodifiableList(warnMessages);
    }

    public List<String> getErrorMessages() {
        return Collections.unmodifiableList(errorMessages);
    }

    @Override
    public boolean isTraceEnabled() {
        return wrappedLogger.isTraceEnabled();
    }

    @Override
    public boolean isDebugEnabled() {
        return wrappedLogger.isDebugEnabled();
    }

    @Override
    public boolean isInfoEnabled() {
        return wrappedLogger.isInfoEnabled();
    }

    @Override
    public boolean isWarnEnabled() {
        return wrappedLogger.isWarnEnabled();
    }

    @Override
    public boolean isErrorEnabled() {
        return wrappedLogger.isErrorEnabled();
    }
}

