public class UdpTransport extends TransportThreadSupport implements Transport, Service, Runnable {
    private DatagramChannel channel;
    private InetSocketAddress targetAddress;
    private int datagramSize;
    private boolean tracingEnabled;
    private boolean replayEnabled;

    public UdpTransport(InetSocketAddress targetAddress, int datagramSize) {
        this.targetAddress = targetAddress;
        this.datagramSize = datagramSize;
        this.tracingEnabled = false;
        this.replayEnabled = false;
    }

    public void enableTracing() {
        this.tracingEnabled = true;
    }

    public void enableReplay() {
        this.replayEnabled = true;
    }

    public void sendCommand(byte[] command) {
        try {
            channel.send(java.nio.ByteBuffer.wrap(command), targetAddress);
            if (tracingEnabled) {
                System.out.println("Sent command: " + new String(command));
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void run() {
        try {
            while (true) {
                byte[] buffer = new byte[datagramSize];
                java.nio.ByteBuffer byteBuffer = java.nio.ByteBuffer.wrap(buffer);
                InetSocketAddress senderAddress = (InetSocketAddress) channel.receive(byteBuffer);
                if (senderAddress != null) {
                    handleIncomingCommand(buffer);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void handleIncomingCommand(byte[] command) {
        if (tracingEnabled) {
            System.out.println("Received command: " + new String(command));
        }
        // Handle command processing logic here
    }

    public void bind(InetSocketAddress localAddress) {
        try {
            channel = DatagramChannel.open();
            channel.bind(localAddress);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void connect() {
        // Connection logic if needed
    }

    public void start() {
        new Thread(this).start();
    }

    public void stop() {
        try {
            channel.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

