public class MiniMap<K, V> implements Map<K, V>, Serializable {
    private static final long serialVersionUID = 1L;
    private K[] keys;
    private V[] values;
    private int size;
    private final int maxSize;

    @SuppressWarnings("unchecked")
    public MiniMap(int maxSize) {
        this.maxSize = maxSize;
        this.keys = (K[]) new Object[maxSize];
        this.values = (V[]) new Object[maxSize];
        this.size = 0;
    }

    @Override
    public V put(K key, V value) {
        if (size >= maxSize) {
            throw new IllegalStateException("Map is full");
        }
        int index = findKeyIndex(key);
        if (index != -1) {
            V oldValue = values[index];
            values[index] = value;
            return oldValue;
        }
        keys[size] = key;
        values[size] = value;
        size++;
        return null;
    }

    @Override
    public V get(Object key) {
        int index = findKeyIndex(key);
        return index != -1 ? values[index] : null;
    }

    @Override
    public boolean containsKey(Object key) {
        return findKeyIndex(key) != -1;
    }

    @Override
    public boolean containsValue(Object value) {
        for (int i = 0; i < size; i++) {
            if (values[i].equals(value)) {
                return true;
            }
        }
        return false;
    }

    @Override
    public V remove(Object key) {
        int index = findKeyIndex(key);
        if (index == -1) {
            return null;
        }
        V oldValue = values[index];
        for (int i = index; i < size - 1; i++) {
            keys[i] = keys[i + 1];
            values[i] = values[i + 1];
        }
        keys[size - 1] = null;
        values[size - 1] = null;
        size--;
        return oldValue;
    }

    @Override
    public void clear() {
        Arrays.fill(keys, null);
        Arrays.fill(values, null);
        size = 0;
    }

    @Override
    public void putAll(Map<? extends K, ? extends V> m) {
        for (Map.Entry<? extends K, ? extends V> entry : m.entrySet()) {
            put(entry.getKey(), entry.getValue());
        }
    }

    @Override
    public Set<K> keySet() {
        return new HashSet<>(Arrays.asList(keys).subList(0, size));
    }

    @Override
    public Set<V> values() {
        return new HashSet<>(Arrays.asList(values).subList(0, size));
    }

    @Override
    public Set<Map.Entry<K, V>> entrySet() {
        Set<Map.Entry<K, V>> entrySet = new HashSet<>();
        for (int i = 0; i < size; i++) {
            final int index = i;
            entrySet.add(new Map.Entry<K, V>() {
                @Override
                public K getKey() {
                    return keys[index];
                }

                @Override
                public V getValue() {
                    return values[index];
                }

                @Override
                public V setValue(V value) {
                    V oldValue = values[index];
                    values[index] = value;
                    return oldValue;
                }
            });
        }
        return entrySet;
    }

    public int size() {
        return size;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    private int findKeyIndex(Object key) {
        for (int i = 0; i < size; i++) {
            if (keys[i].equals(key)) {
                return i;
            }
        }
        return -1;
    }
}

