public class RomanianStemmer extends SnowballProgram {
    private static final Among[] a_0 = {
        new Among("e", -1, 1),
        new Among("i", -1, 1),
        new Among("u", -1, 1),
        new Among("ă", -1, 1),
        new Among("â", -1, 1),
        new Among("î", -1, 1),
        new Among("o", -1, 1),
        new Among("a", -1, 1)
    };

    private static final Among[] a_1 = {
        new Among("esc", -1, 1),
        new Among("ează", -1, 1),
        new Among("eze", -1, 1),
        new Among("ezi", -1, 1),
        new Among("ez", -1, 1)
    };

    private static final Among[] a_2 = {
        new Among("at", -1, 1),
        new Among("it", -1, 1),
        new Among("ut", -1, 1)
    };

    private int I_p1;
    private int I_p2;

    public RomanianStemmer() {
        super();
    }

    private void markRegions() {
        I_p1 = limit;
        I_p2 = limit;
        for (int i = 0; i < limit; i++) {
            if (charAt(i) == 'a' || charAt(i) == 'e' || charAt(i) == 'i' || charAt(i) == 'o' || charAt(i) == 'u') {
                if (I_p1 == limit) {
                    I_p1 = i;
                }
                I_p2 = i;
            }
        }
    }

    private boolean r_vowel_suffix() {
        if (I_p1 < limit) {
            return false;
        }
        for (Among suffix : a_0) {
            if (endsWith(suffix.getString())) {
                deleteSuffix(suffix.getString());
                return true;
            }
        }
        return false;
    }

    private boolean r_verb_suffix() {
        if (I_p2 < limit) {
            return false;
        }
        for (Among suffix : a_1) {
            if (endsWith(suffix.getString())) {
                deleteSuffix(suffix.getString());
                return true;
            }
        }
        return false;
    }

    private boolean r_noun_suffix() {
        if (I_p2 < limit) {
            return false;
        }
        for (Among suffix : a_2) {
            if (endsWith(suffix.getString())) {
                deleteSuffix(suffix.getString());
                return true;
            }
        }
        return false;
    }

    public void stem() {
        markRegions();
        r_vowel_suffix();
        r_verb_suffix();
        r_noun_suffix();
    }
}

