public class HandleHttpRequest {

    private HttpServer server;
    private boolean requireAuth;
    private Set<String> validPaths;
    private int port;

    public HandleHttpRequest(int port, boolean requireAuth, Set<String> validPaths) throws IOException {
        this.port = port;
        this.requireAuth = requireAuth;
        this.validPaths = validPaths;
        this.server = HttpServer.create(new InetSocketAddress(port), 0);
        this.server.createContext("/", new RequestHandler());
    }

    public void start() {
        server.setExecutor(null);
        server.start();
    }

    public void stop() {
        server.stop(0);
    }

    private class RequestHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            String requestMethod = exchange.getRequestMethod();
            String requestPath = exchange.getRequestURI().getPath();

            if (!validPaths.contains(requestPath)) {
                sendResponse(exchange, 404, "Not Found");
                return;
            }

            if (requireAuth && !isAuthenticated(exchange)) {
                sendResponse(exchange, 401, "Unauthorized");
                return;
            }

            switch (requestMethod) {
                case "GET":
                    handleGet(exchange);
                    break;
                case "POST":
                    handlePost(exchange);
                    break;
                case "PUT":
                    handlePut(exchange);
                    break;
                case "DELETE":
                    handleDelete(exchange);
                    break;
                case "HEAD":
                    handleHead(exchange);
                    break;
                case "OPTIONS":
                    handleOptions(exchange);
                    break;
                default:
                    sendResponse(exchange, 405, "Method Not Allowed");
                    break;
            }
        }

        private void handleGet(HttpExchange exchange) throws IOException {
            String response = "GET request processed";
            sendResponse(exchange, 200, response);
        }

        private void handlePost(HttpExchange exchange) throws IOException {
            InputStream inputStream = exchange.getRequestBody();
            String response = "POST request processed";
            sendResponse(exchange, 200, response);
            // Process multipart form data if necessary
        }

        private void handlePut(HttpExchange exchange) throws IOException {
            String response = "PUT request processed";
            sendResponse(exchange, 200, response);
        }

        private void handleDelete(HttpExchange exchange) throws IOException {
            String response = "DELETE request processed";
            sendResponse(exchange, 200, response);
        }

        private void handleHead(HttpExchange exchange) throws IOException {
            exchange.sendResponseHeaders(200, -1); // No body
        }

        private void handleOptions(HttpExchange exchange) throws IOException {
            exchange.getResponseHeaders().add("Allow", "GET, POST, PUT, DELETE, HEAD, OPTIONS");
            sendResponse(exchange, 200, "Options processed");
        }

        private boolean isAuthenticated(HttpExchange exchange) {
            // Implement authentication logic here
            return true; // Placeholder
        }

        private void sendResponse(HttpExchange exchange, int statusCode, String response) throws IOException {
            exchange.sendResponseHeaders(statusCode, response.length());
            OutputStream os = exchange.getResponseBody();
            os.write(response.getBytes());
            os.close();
        }
    }

    public static void main(String[] args) throws IOException {
        Set<String> validPaths = new HashSet<>(Arrays.asList("/api/resource"));
        HandleHttpRequest server = new HandleHttpRequest(8080, true, validPaths);
        server.start();
        System.out.println("Server started on port 8080");
    }
}

