public class Text {

    // MD5 Hashing
    public static String md5(String input) {
        return md5(input, StandardCharsets.UTF_8.name());
    }

    public static String md5(String input, String encoding) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes(encoding));
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException | java.io.UnsupportedEncodingException e) {
            throw new RuntimeException(e);
        }
    }

    // String Splitting and Joining
    public static String[] split(String input, String delimiter) {
        return input.split(Pattern.quote(delimiter));
    }

    public static String join(String[] array, String delimiter) {
        return String.join(delimiter, array);
    }

    // String Replacement
    public static String replace(String input, String target, String replacement) {
        return input.replace(target, replacement);
    }

    // XML Character Encoding
    public static String encodeXml(String input) {
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&apos;");
    }

    // URI Escaping
    public static String escapeUri(String input) {
        try {
            return URLEncoder.encode(input, StandardCharsets.UTF_8.name());
        } catch (java.io.UnsupportedEncodingException e) {
            throw new RuntimeException(e);
        }
    }

    public static String unescapeUri(String input) {
        try {
            return URLDecoder.decode(input, StandardCharsets.UTF_8.name());
        } catch (java.io.UnsupportedEncodingException e) {
            throw new RuntimeException(e);
        }
    }

    // Path Manipulation
    public static String getNameFromPath(String path) {
        return path.substring(path.lastIndexOf('/') + 1);
    }

    public static boolean isSibling(String path1, String path2) {
        return getParentPath(path1).equals(getParentPath(path2));
    }

    public static boolean isDescendant(String parentPath, String childPath) {
        return childPath.startsWith(parentPath + "/");
    }

    public static String getParentPath(String path) {
        return path.substring(0, path.lastIndexOf('/'));
    }

    public static String getParentPath(String path, int levels) {
        for (int i = 0; i < levels; i++) {
            path = getParentPath(path);
        }
        return path;
    }

    // Variable Replacement
    public static String replaceVariables(String input, Properties properties, boolean ignoreMissing) {
        for (String key : properties.stringPropertyNames()) {
            String value = properties.getProperty(key);
            if (input.contains("${" + key + "}")) {
                input = input.replace("${" + key + "}", value);
            } else if (!ignoreMissing) {
                throw new IllegalArgumentException("Missing variable: " + key);
            }
        }
        return input;
    }

    // Character Decoding
    private static char decodeHexChar(String hex) {
        return (char) Integer.parseInt(hex, 16);
    }
}

