class SparseGradientTest {

    @Test
    public void testConstantGradient() {
        SparseGradient constant = SparseGradient.constant(5.0);
        assertEquals(5.0, constant.getValue(), 0.001);
        assertEquals(0.0, constant.getDerivative(), 0.001);
    }

    @Test
    public void testVariableGradient() {
        SparseGradient variable = SparseGradient.variable(3.0);
        assertEquals(3.0, variable.getValue(), 0.001);
        assertEquals(1.0, variable.getDerivative(), 0.001);
    }

    @Test
    public void testAddition() {
        SparseGradient a = SparseGradient.constant(2.0);
        SparseGradient b = SparseGradient.variable(3.0);
        SparseGradient result = a.add(b);
        assertEquals(5.0, result.getValue(), 0.001);
        assertEquals(1.0, result.getDerivative(), 0.001);
    }

    @Test
    public void testSubtraction() {
        SparseGradient a = SparseGradient.variable(5.0);
        SparseGradient b = SparseGradient.constant(2.0);
        SparseGradient result = a.subtract(b);
        assertEquals(3.0, result.getValue(), 0.001);
        assertEquals(1.0, result.getDerivative(), 0.001);
    }

    @Test
    public void testMultiplication() {
        SparseGradient a = SparseGradient.constant(2.0);
        SparseGradient b = SparseGradient.variable(3.0);
        SparseGradient result = a.multiply(b);
        assertEquals(6.0, result.getValue(), 0.001);
        assertEquals(2.0, result.getDerivative(), 0.001);
    }

    @Test
    public void testDivision() {
        SparseGradient a = SparseGradient.variable(6.0);
        SparseGradient b = SparseGradient.constant(2.0);
        SparseGradient result = a.divide(b);
        assertEquals(3.0, result.getValue(), 0.001);
        assertEquals(0.5, result.getDerivative(), 0.001);
    }

    @Test
    public void testExponentialFunction() {
        SparseGradient a = SparseGradient.variable(1.0);
        SparseGradient result = a.exp();
        assertEquals(Math.exp(1.0), result.getValue(), 0.001);
        assertEquals(Math.exp(1.0), result.getDerivative(), 0.001);
    }

    @Test
    public void testLogarithmicFunction() {
        SparseGradient a = SparseGradient.variable(Math.E);
        SparseGradient result = a.log();
        assertEquals(1.0, result.getValue(), 0.001);
        assertEquals(1.0 / Math.E, result.getDerivative(), 0.001);
    }

    @Test
    public void testTrigonometricFunction() {
        SparseGradient a = SparseGradient.variable(Math.PI / 2);
        SparseGradient result = a.sin();
        assertEquals(1.0, result.getValue(), 0.001);
        assertEquals(0.0, result.getDerivative(), 0.001);
    }

    @Test
    public void testTaylorSeriesExpansion() {
        SparseGradient a = SparseGradient.variable(0.1);
        SparseGradient result = a.taylorExpand(5);
        assertEquals(0.1, result.getValue(), 0.001);
        assertEquals(1.0, result.getDerivative(), 0.001);
    }

    @Test
    public void testLinearCombination() {
        SparseGradient a = SparseGradient.variable(2.0);
        SparseGradient b = SparseGradient.variable(3.0);
        SparseGradient result = a.add(b.multiply(2));
        assertEquals(8.0, result.getValue(), 0.001);
        assertEquals(1.0 + 2.0, result.getDerivative(), 0.001);
    }

    @Test
    public void testSpecialCases() {
        SparseGradient zero = SparseGradient.constant(0.0);
        assertEquals(0.0, zero.getValue(), 0.001);
        assertEquals(0.0, zero.getDerivative(), 0.001);
    }
}

