public class TestParquetStorer {

    @Test
    public void testStorer() {
        // Setup: Create a dataset with 1000 rows of character array tuples
        String[][] dataset = new String[1000][];
        for (int i = 0; i < 1000; i++) {
            dataset[i] = new String[]{"row" + i, "data" + i};
        }

        // Action: Store dataset in Parquet format
        String parquetFilePath = "testStorer.parquet";
        ParquetStorer.store(dataset, parquetFilePath);

        // Verify: Load the data back and check integrity
        String[][] loadedData = ParquetLoader.load(parquetFilePath);
        assertArrayEquals(dataset, loadedData);
    }

    @Test
