        // Setup: Create two datasets with different schemas
        String[][] dataset1 = {{"row1", "data1"}, {"row2", "data2"}};
        String[][] dataset2 = {{"rowA", "dataA", "extraA"}, {"rowB", "dataB", "extraB"}};

        // Action: Store datasets in separate Parquet files
        String parquetFilePath1 = "testMultipleSchema1.parquet";
        String parquetFilePath2 = "testMultipleSchema2.parquet";
