    public void testConstructorValidInput() {
        BigFraction fraction = new BigFraction(1, 2);
        assertEquals("1/2", fraction.toString());
    }

    @Test
    public void testConstructorInvalidInput() {
        assertThrows(IllegalArgumentException.class, () -> new BigFraction(1, 0));
    }

    @Test
    public void testAddition() {
        BigFraction fraction1 = new BigFraction(1, 2);
        BigFraction fraction2 = new BigFraction(1, 3);
        BigFraction result = fraction1.add(fraction2);
        assertEquals("5/6", result.toString());
    }

    @Test
    public void testSubtraction() {
        BigFraction fraction1 = new BigFraction(1, 2);
        BigFraction fraction2 = new BigFraction(1, 3);
        BigFraction result = fraction1.subtract(fraction2);
        assertEquals("1/6", result.toString());
    }

    @Test
    public void testMultiplication() {
        BigFraction fraction1 = new BigFraction(1, 2);
        BigFraction fraction2 = new BigFraction(1, 3);
        BigFraction result = fraction1.multiply(fraction2);
        assertEquals("1/6", result.toString());
    }

    @Test
    public void testDivision() {
        BigFraction fraction1 = new BigFraction(1, 2);
        BigFraction fraction2 = new BigFraction(1, 3);
        BigFraction result = fraction1.divide(fraction2);
        assertEquals("3/2", result.toString());
    }

    @Test
    public void testComparison() {
        BigFraction fraction1 = new BigFraction(1, 2);
        BigFraction fraction2 = new BigFraction(2, 4);
        assertTrue(fraction1.equals(fraction2));
        assertTrue(fraction1.compareTo(fraction2) == 0);
    }

    @Test
    public void testConversionToInt() {
        BigFraction fraction = new BigFraction(3, 2);
        assertEquals(1, fraction.intValue());
    }

    @Test
    public void testConversionToLong() {
        BigFraction fraction = new BigFraction(5, 2);
        assertEquals(2L, fraction.longValue());
    }

    @Test
    public void testConversionToDouble() {
        BigFraction fraction = new BigFraction(1, 3);
        assertEquals(0.3333333333333333, fraction.doubleValue(), 0.0000000000001);
    }

    @Test
    public void testConversionToFloat() {
        BigFraction fraction = new BigFraction(1, 4);
        assertEquals(0.25f, fraction.floatValue(), 0.0001f);
    }

    @Test
    public void testConversionToBigDecimal() {
        BigFraction fraction = new BigFraction(1, 7);
        assertEquals(new BigDecimal("0.142857142857142857142857142857"), fraction.toBigDecimal());
    }

    @Test
    public void testInvalidInputHandling() {
        assertThrows(IllegalArgumentException.class, () -> new BigFraction(1, -1));
    }
}

