public class SparseFieldVectorTest {

    @Test
    public void testAddition() {
        SparseFieldVector<Fraction> vector1 = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 2), new Fraction(0), new Fraction(3, 4)});
        SparseFieldVector<Fraction> vector2 = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 4), new Fraction(1, 2), new Fraction(0)});
        SparseFieldVector<Fraction> result = vector1.add(vector2);
        SparseFieldVector<Fraction> expected = new SparseFieldVector<>(new Fraction[]{new Fraction(3, 4), new Fraction(1, 2), new Fraction(3, 4)});
        assertEquals(expected, result);
    }

    @Test
    public void testSubtraction() {
        SparseFieldVector<Fraction> vector1 = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 2), new Fraction(1), new Fraction(3, 4)});
        SparseFieldVector<Fraction> vector2 = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 4), new Fraction(1, 2), new Fraction(0)});
        SparseFieldVector<Fraction> result = vector1.subtract(vector2);
        SparseFieldVector<Fraction> expected = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 4), new Fraction(1, 2), new Fraction(3, 4)});
        assertEquals(expected, result);
    }

    @Test
    public void testMultiplication() {
        SparseFieldVector<Fraction> vector = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 2), new Fraction(1), new Fraction(3, 4)});
        Fraction scalar = new Fraction(2);
        SparseFieldVector<Fraction> result = vector.multiply(scalar);
        SparseFieldVector<Fraction> expected = new SparseFieldVector<>(new Fraction[]{new Fraction(1), new Fraction(2), new Fraction(3/2)});
        assertEquals(expected, result);
    }

    @Test
    public void testDivision() {
        SparseFieldVector<Fraction> vector = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 2), new Fraction(1), new Fraction(3, 4)});
        Fraction scalar = new Fraction(2);
        SparseFieldVector<Fraction> result = vector.divide(scalar);
        SparseFieldVector<Fraction> expected = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 4), new Fraction(1/2), new Fraction(3/8)});
        assertEquals(expected, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testDimensionMismatchAddition() {
        SparseFieldVector<Fraction> vector1 = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 2)});
        SparseFieldVector<Fraction> vector2 = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 2), new Fraction(1)});
        vector1.add(vector2);
    }

    @Test
    public void testInversion() {
        SparseFieldVector<Fraction> vector = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 2), new Fraction(1), new Fraction(3, 4)});
        SparseFieldVector<Fraction> result = vector.inverse();
        SparseFieldVector<Fraction> expected = new SparseFieldVector<>(new Fraction[]{new Fraction(2), new Fraction(1), new Fraction(4/3)});
        assertEquals(expected, result);
    }

    @Test
    public void testMappingFunction() {
        SparseFieldVector<Fraction> vector = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 2), new Fraction(1), new Fraction(3, 4)});
        SparseFieldVector<Fraction> result = vector.map(fraction -> fraction.multiply(new Fraction(2)));
        SparseFieldVector<Fraction> expected = new SparseFieldVector<>(new Fraction[]{new Fraction(1), new Fraction(2), new Fraction(3/2)});
        assertEquals(expected, result);
    }

    @Test
    public void testOuterProduct() {
        SparseFieldVector<Fraction> vector1 = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 2), new Fraction(1)});
        SparseFieldVector<Fraction> vector2 = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 4), new Fraction(1)});
        SparseFieldMatrix<Fraction> result = vector1.outerProduct(vector2);
        SparseFieldMatrix<Fraction> expected = new SparseFieldMatrix<>(new Fraction[][]{
            {new Fraction(1, 8), new Fraction(1, 2)},
            {new Fraction(1, 4), new Fraction(1)}
        });
        assertEquals(expected, result);
    }

    @Test
    public void testVisitor() {
        SparseFieldVector<Fraction> vector = new SparseFieldVector<>(new Fraction[]{new Fraction(1, 2), new Fraction(1), new Fraction(3, 4)});
        vector.visit(new VectorVisitor<Fraction>() {
            @Override
            public void visit(int index, Fraction value) {
                assertNotNull(value);
            }
        });
    }
}

