public class IsisSessionFilter implements Filter {

    private static final String LOGIN_PAGE = "/login";
    private static final String UNAUTHORIZED_PAGE = "/unauthorized";
    private static final Set<String> RESTRICTED_PATHS = Set.of("/admin", "/user");
    private static final Set<String> IGNORED_EXTENSIONS = Set.of(".css", ".js", ".png", ".jpg");

    public enum NoSessionAction {
        REDIRECT_TO_LOGIN,
        SHOW_UNAUTHORIZED,
        PASS_THROUGH
    }

    private NoSessionAction noSessionAction;

    @Override
    public void init(FilterConfig filterConfig) throws ServletException {
        String action = filterConfig.getInitParameter("noSessionAction");
        noSessionAction = NoSessionAction.valueOf(action.toUpperCase());
    }

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {
        HttpServletRequest httpRequest = (HttpServletRequest) request;
        HttpServletResponse httpResponse = (HttpServletResponse) response;

        String path = httpRequest.getRequestURI();
        if (isIgnored(path) || isSessionValid(httpRequest)) {
            chain.doFilter(request, response);
        } else {
            handleNoSession(httpRequest, httpResponse);
        }
    }

    private boolean isIgnored(String path) {
        return IGNORED_EXTENSIONS.stream().anyMatch(path::endsWith);
    }

    private boolean isSessionValid(HttpServletRequest request) {
        HttpSession session = request.getSession(false);
        return session != null && session.getAttribute("user") != null;
    }

    private void handleNoSession(HttpServletRequest request, HttpServletResponse response) throws IOException {
        switch (noSessionAction) {
            case REDIRECT_TO_LOGIN:
                response.sendRedirect(LOGIN_PAGE);
                break;
            case SHOW_UNAUTHORIZED:
                response.sendRedirect(UNAUTHORIZED_PAGE);
                break;
            case PASS_THROUGH:
                // Do nothing, just pass through
                break;
        }
    }

    @Override
    public void destroy() {
        // Cleanup resources if needed
    }
}

