public class Registry implements RegistryMBean, MBeanRegistration {
    private static final Logger logger = Logger.getLogger(Registry.class.getName());
    private final Map<String, Object> mBeanRegistry = new HashMap<>();
    private MBeanServer mBeanServer;

    public void registerMBean(Object mBean, String name) {
        try {
            ObjectName objectName = new ObjectName(name);
            mBeanServer.registerMBean(mBean, objectName);
            mBeanRegistry.put(name, mBean);
        } catch (Exception e) {
            logger.severe("Error registering MBean: " + e.getMessage());
        }
    }

    public void unregisterMBean(String name) {
        try {
            ObjectName objectName = new ObjectName(name);
            mBeanServer.unregisterMBean(objectName);
            mBeanRegistry.remove(name);
        } catch (Exception e) {
            logger.severe("Error unregistering MBean: " + e.getMessage());
        }
    }

    public Object invokeMBeanOperation(String name, String operationName, Object[] params, String[] signature) {
        try {
            ObjectName objectName = new ObjectName(name);
            return mBeanServer.invoke(objectName, operationName, params, signature);
        } catch (Exception e) {
            logger.severe("Error invoking MBean operation: " + e.getMessage());
            return null;
        }
    }

    public void setMBeanServer(MBeanServer server) {
        this.mBeanServer = server;
    }

    public Object getMBeanAttribute(String name, String attribute) {
        try {
            ObjectName objectName = new ObjectName(name);
            return mBeanServer.getAttribute(objectName, attribute);
        } catch (Exception e) {
            logger.severe("Error getting MBean attribute: " + e.getMessage());
            return null;
        }
    }

    public void setMBeanAttribute(String name, String attribute, Object value) {
        try {
            ObjectName objectName = new ObjectName(name);
            mBeanServer.setAttribute(objectName, new javax.management.Attribute(attribute, value));
        } catch (Exception e) {
            logger.severe("Error setting MBean attribute: " + e.getMessage());
        }
    }

    @Override
    public Object preRegister(MBeanServer server, ObjectName name) {
        this.mBeanServer = server;
        return name;
    }

    @Override
    public void postRegister(Boolean registrationDone) {}

    @Override
    public void preDeregister() {}

    @Override
    public void postDeregister() {}
}

