        double refundAmount = calculateReturnItemCost(returnId);
        ReturnHeader returnHeader = delegator.getReturnHeader(returnId);
        PaymentService.processRefund(returnHeader.getCustomerId(), refundAmount);
    }

    public void handleReturnAdjustment(String returnId, List<ReturnAdjustment> adjustments) {
        for (ReturnAdjustment adjustment : adjustments) {
            delegator.updateReturnAdjustment(returnId, adjustment);
        }
    }

    public void manageReplacementOrder(String returnId, ReplacementOrder replacementOrder) {
        ReturnHeader returnHeader = delegator.getReturnHeader(returnId);
        replacementOrder.setOriginalOrderId(returnHeader.getOrderId());
        delegator.createReplacementOrder(replacementOrder);
    }

    public boolean validateReturnableQuantity(String returnId, String itemId, int quantity) {
        ReturnItem returnItem = delegator.getReturnItem(returnId, itemId);
        return returnItem.getReturnableQuantity() >= quantity;
    }

    public void createOrUpdateReturnItem(String returnId, ReturnItem returnItem) {
        if (delegator.returnItemExists(returnId, returnItem.getItemId())) {
            delegator.updateReturnItem(returnId, returnItem);
        } else {
            delegator.createReturnItem(returnId, returnItem);
        }
    }

    public void createOrUpdateReturnAdjustment(String returnId, ReturnAdjustment adjustment) {
        if (delegator.returnAdjustmentExists(returnId, adjustment.getAdjustmentId())) {
            delegator.updateReturnAdjustment(returnId, adjustment);
        } else {
            delegator.createReturnAdjustment(returnId, adjustment);
        }
    }
}

