public class BitUtil {
    private static final byte[] ntzTable = new byte[256];

    static {
        for (int i = 0; i < 256; i++) {
            ntzTable[i] = (byte) Integer.numberOfTrailingZeros(i);
        }
    }

    public static int pop(long value) {
        value = value - ((value >>> 1) & 0x5555555555555555L);
        value = (value & 0x3333333333333333L) + ((value >>> 2) & 0x3333333333333333L);
        value = (value + (value >>> 4)) & 0x0F0F0F0F0F0F0F0FL;
        value = value + (value >>> 8);
        value = value + (value >>> 16);
        value = value + (value >>> 32);
        return (int) (value & 0x7F);
    }

    public static int pop_array(long[] array, int start, int end) {
        int count = 0;
        for (int i = start; i < end; i++) {
            count += pop(array[i]);
        }
        return count;
    }

    public static int pop_intersect(long[] a, long[] b) {
        int count = 0;
        for (long valueA : a) {
            for (long valueB : b) {
                count += pop(valueA & valueB);
            }
        }
        return count;
    }

    public static int pop_union(long[] a, long[] b) {
        int count = 0;
        for (long valueA : a) {
            count += pop(valueA);
        }
        for (long valueB : b) {
            count += pop(valueB);
        }
        return count;
    }

    public static int pop_andnot(long[] a, long[] b) {
        int count = 0;
        for (long valueA : a) {
            for (long valueB : b) {
                count += pop(valueA & ~valueB);
            }
        }
        return count;
    }

    public static int pop_xor(long[] a, long[] b) {
        int count = 0;
        for (long valueA : a) {
            for (long valueB : b) {
                count += pop(valueA ^ valueB);
            }
        }
        return count;
    }

    public static int ntz(long value) {
        if (value == 0) return 64; // Assuming 64-bit long
        return Long.numberOfTrailingZeros(value);
    }

    public static int ntz2(long value) {
        return ntz(value);
    }

    public static int ntz3(long value) {
        return ntz(value);
    }

    public static boolean isPowerOfTwo(int value) {
        return value > 0 && (value & (value - 1)) == 0;
    }

    public static boolean isPowerOfTwo(long value) {
        return value > 0 && (value & (value - 1)) == 0;
    }

    public static int nextHighestPowerOfTwo(int value) {
        if (value <= 1) return 1;
        value--;
        value |= value >> 1;
        value |= value >> 2;
        value |= value >> 4;
        value |= value >> 8;
        value |= value >> 16;
        return value + 1;
    }

    public static long nextHighestPowerOfTwo(long value) {
        if (value <= 1) return 1;
        value--;
        value |= value >> 1;
        value |= value >> 2;
        value |= value >> 4;
        value |= value >> 8;
        value |= value >> 16;
        value |= value >> 32;
        return value + 1;
    }
}

