public class GenerateSQLVisitor {

    private StringBuilder sqlBuilder;
    private int indentLevel;

    public GenerateSQLVisitor() {
        this.sqlBuilder = new StringBuilder();
        this.indentLevel = 0;
    }

    public String generateSql(SqlNode node) {
        if (node instanceof SqlSelectBlock) {
            visitSelectBlock((SqlSelectBlock) node);
        } else if (node instanceof SqlJoin) {
            visitJoin((SqlJoin) node);
        } else if (node instanceof SqlTable) {
            visitTable((SqlTable) node);
        } else {
            throw new IllegalArgumentException("Unexpected SQL node type: " + node.getClass().getSimpleName());
        }
        return sqlBuilder.toString();
    }

    private void visitSelectBlock(SqlSelectBlock selectBlock) {
        appendIndentation();
        sqlBuilder.append("SELECT ");
        if (selectBlock.isDistinct()) {
            sqlBuilder.append("DISTINCT ");
        }
        appendColumns(selectBlock.getColumns());
        appendFromClause(selectBlock.getFrom());
        appendWhereClause(selectBlock.getWhere());
        appendGroupByClause(selectBlock.getGroupBy());
        appendOrderByClause(selectBlock.getOrderBy());
        appendLimitOffset(selectBlock.getLimit(), selectBlock.getOffset());
    }

    private void visitJoin(SqlJoin join) {
        appendIndentation();
        sqlBuilder.append("JOIN ").append(join.getTable()).append(" ON ").append(join.getCondition());
    }

    private void visitTable(SqlTable table) {
        appendIndentation();
        sqlBuilder.append(table.getName());
    }

    private void appendColumns(List<String> columns) {
        sqlBuilder.append(String.join(", ", columns)).append(" ");
    }

    private void appendFromClause(String from) {
        if (from != null) {
            sqlBuilder.append("FROM ").append(from).append(" ");
        }
    }

    private void appendWhereClause(String where) {
        if (where != null) {
            sqlBuilder.append("WHERE ").append(where).append(" ");
        }
    }

    private void appendGroupByClause(String groupBy) {
        if (groupBy != null) {
            sqlBuilder.append("GROUP BY ").append(groupBy).append(" ");
        }
    }

    private void appendOrderByClause(String orderBy) {
        if (orderBy != null) {
            sqlBuilder.append("ORDER BY ").append(orderBy).append(" ");
        }
    }

    private void appendLimitOffset(Integer limit, Integer offset) {
        if (limit != null) {
            sqlBuilder.append("LIMIT ").append(limit).append(" ");
        }
        if (offset != null) {
            sqlBuilder.append("OFFSET ").append(offset).append(" ");
        }
    }

    private void appendIndentation() {
        for (int i = 0; i < indentLevel; i++) {
            sqlBuilder.append("    ");
        }
    }

    public void increaseIndent() {
        indentLevel++;
    }

    public void decreaseIndent() {
        if (indentLevel > 0) {
            indentLevel--;
        }
    }
}

