public class NodeState extends ItemState {
    private String id;
    private String parentId;
    private String nodeType;
    private Set<String> mixinTypes;
    private Map<String, NodeState> childNodes;
    private Map<String, Object> properties;
    private final ReentrantLock lock = new ReentrantLock();
    private List<NodeStateListener> listeners;

    public NodeState(String id, String parentId, String nodeType) {
        this.id = id;
        this.parentId = parentId;
        this.nodeType = nodeType;
        this.mixinTypes = new HashSet<>();
        this.childNodes = new HashMap<>();
        this.properties = new HashMap<>();
        this.listeners = new ArrayList<>();
    }

    public void addChildNode(NodeState child) {
        lock.lock();
        try {
            childNodes.put(child.getId(), child);
            notifyListeners();
        } finally {
            lock.unlock();
        }
    }

    public void removeChildNode(String childId) {
        lock.lock();
        try {
            childNodes.remove(childId);
            notifyListeners();
        } finally {
            lock.unlock();
        }
    }

    public void renameChildNode(String oldId, String newId) {
        lock.lock();
        try {
            NodeState child = childNodes.remove(oldId);
            if (child != null) {
                childNodes.put(newId, child);
                notifyListeners();
            }
        } finally {
            lock.unlock();
        }
    }

    public void addProperty(String key, Object value) {
        lock.lock();
        try {
            properties.put(key, value);
            notifyListeners();
        } finally {
            lock.unlock();
        }
    }

    public void removeProperty(String key) {
        lock.lock();
        try {
            properties.remove(key);
            notifyListeners();
        } finally {
            lock.unlock();
        }
    }

    public void addMixinType(String mixinType) {
        lock.lock();
        try {
            mixinTypes.add(mixinType);
            notifyListeners();
        } finally {
            lock.unlock();
        }
    }

    public void removeMixinType(String mixinType) {
        lock.lock();
        try {
            mixinTypes.remove(mixinType);
            notifyListeners();
        } finally {
            lock.unlock();
        }
    }

    public void addListener(NodeStateListener listener) {
        lock.lock();
        try {
            listeners.add(listener);
        } finally {
            lock.unlock();
        }
    }

    public void removeListener(NodeStateListener listener) {
        lock.lock();
        try {
            listeners.remove(listener);
        } finally {
            lock.unlock();
        }
    }

    private void notifyListeners() {
        for (NodeStateListener listener : listeners) {
            listener.onNodeStateChanged(this);
        }
    }

    public int calculateMemoryFootprint() {
        int footprint = Integer.BYTES * (1 + childNodes.size() + properties.size() + mixinTypes.size());
        return footprint;
    }

    public String getId() {
        return id;
    }

    public String getParentId() {
        return parentId;
    }

    public String getNodeType() {
        return nodeType;
    }

    public Set<String> getMixinTypes() {
        return Collections.unmodifiableSet(mixinTypes);
    }

    public Map<String, NodeState> getChildNodes() {
        return Collections.unmodifiableMap(childNodes);
    }

    public Map<String, Object> getProperties() {
        return Collections.unmodifiableMap(properties);
    }
}

interface NodeStateListener {
    void onNodeStateChanged(NodeState nodeState);
}

