public class EdmProviderImpl extends AbstractEdm {
    private final CsdlEdmProvider csdlEdmProvider;
    private final Map<String, Action> actionsCache = Collections.synchronizedMap(new HashMap<>());
    private final Map<String, Function> functionsCache = Collections.synchronizedMap(new HashMap<>());

    public EdmProviderImpl(CsdlEdmProvider csdlEdmProvider) {
        this.csdlEdmProvider = csdlEdmProvider;
    }

    public Action getAction(String actionName) {
        return actionsCache.computeIfAbsent(actionName, this::loadAction);
    }

    public Function getFunction(String functionName) {
        return functionsCache.computeIfAbsent(functionName, this::loadFunction);
    }

    private Action loadAction(String actionName) {
        try {
            return csdlEdmProvider.getAction(actionName);
        } catch (Exception e) {
            handleException(e);
            return null; // Code smell: returning null can lead to NullPointerExceptions
        }
    }

    private Function loadFunction(String functionName) {
        try {
            return csdlEdmProvider.getFunction(functionName);
        } catch (Exception e) {
            handleException(e);
            return null; // Code smell: returning null can lead to NullPointerExceptions
        }
