class CodeValidatorTest {

    @Test
    void testCheckDigitValidationWithCheckDigit() {
        CodeValidator validator = new CodeValidator(true);
        assertTrue(validator.isValid("4006381333931")); // Valid EAN-13 with check digit
        assertFalse(validator.isValid("4006381333930")); // Invalid EAN-13
    }

    @Test
    void testCheckDigitValidationWithoutCheckDigit() {
        CodeValidator validator = new CodeValidator(false);
        assertTrue(validator.isValid("400638133393")); // Valid EAN-13 without check digit
        assertFalse(validator.isValid("400638133390")); // Invalid EAN-13
    }

    @Test
    void testLengthValidation() {
        CodeValidator validator = new CodeValidator(12, 13);
        assertTrue(validator.isValid("400638133393")); // Valid length
        assertFalse(validator.isValid("40063813339")); // Too short
        assertFalse(validator.isValid("4006381333931")); // Too long
    }

    @Test
    void testRegexValidation() {
        CodeValidator validator = new CodeValidator("^[0-9]{12,13}$");
        assertTrue(validator.isValid("400638133393"));
        assertFalse(validator.isValid("40063813339A")); // Invalid character
    }

    @Test
    void testNoInputHandling() {
        CodeValidator validator = new CodeValidator();
        assertFalse(validator.isValid(null)); // Null input
        assertFalse(validator.isValid("")); // Empty input
        assertFalse(validator.isValid("   ")); // Whitespace input
    }

    @Test
    void testConstructorWithRegex() {
        CodeValidator validator = new CodeValidator("^[0-9]{12,13}$", 12, 13, true);
        assertEquals("^[0-9]{12,13}$", validator.getRegex());
        assertEquals(12, validator.getMinLength());
        assertEquals(13, validator.getMaxLength());
        assertTrue(validator.isCheckDigitEnabled());
    }

    @Test
    void testConstructorWithLength() {
        CodeValidator validator = new CodeValidator(8, 10, false);
        assertEquals(8, validator.getMinLength());
        assertEquals(10, validator.getMaxLength());
        assertFalse(validator.isCheckDigitEnabled());
    }
}

