public class LocalCarbonFile implements CarbonFile {
    private static final Logger logger = Logger.getLogger(LocalCarbonFile.class.getName());
    private File file;

    public LocalCarbonFile(String path) {
        this.file = new File(path);
    }

    public String getAbsolutePath() {
        return file.getAbsolutePath();
    }

    public String getName() {
        return file.getName();
    }

    public long getSize() {
        return file.length();
    }

    public long getLastModifiedTime() {
        return file.lastModified();
    }

    public boolean exists() {
        return file.exists();
    }

    public boolean isDirectory() {
        return file.isDirectory();
    }

    public List<CarbonFile> listFiles() {
        return listFiles(null, false);
    }

    public List<CarbonFile> listFiles(String filter, boolean recursive) {
        List<CarbonFile> carbonFiles = new ArrayList<>();
        if (file.isDirectory()) {
            File[] files = file.listFiles();
            if (files != null) {
                for (File f : files) {
                    if (filter == null || f.getName().contains(filter)) {
                        carbonFiles.add(new LocalCarbonFile(f.getAbsolutePath()));
                    }
                    if (recursive && f.isDirectory()) {
                        carbonFiles.addAll(new LocalCarbonFile(f.getAbsolutePath()).listFiles(filter, true));
                    }
                }
            }
        }
        return carbonFiles;
    }

    public boolean create() {
        try {
            return file.createNewFile();
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error creating file: " + e.getMessage(), e);
            return false;
        }
    }

    public boolean rename(String newName) {
        File newFile = new File(file.getParent(), newName);
        return file.renameTo(newFile);
    }

    public boolean delete() {
        return file.delete();
    }

    public byte[] read() {
        try {
            return Files.readAllBytes(Paths.get(file.getAbsolutePath()));
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error reading file: " + e.getMessage(), e);
            return null;
        }
    }

    public void write(byte[] data) {
        try {
            Files.write(Paths.get(file.getAbsolutePath()), data);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error writing to file: " + e.getMessage(), e);
        }
    }

    public void truncate() {
        try {
            new FileOutputStream(file, false).close();
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error truncating file: " + e.getMessage(), e);
        }
    }

    public boolean isModified(long lastCheckedTime) {
