class TestStringOperatorsAndFunctions {

    @Test
    public void testStringConcatenation() {
        String result = concatenate("Hello", "World");
        assertEquals("HelloWorld", result);
    }

    @Test
    public void testTrimLeft() {
        String result = trimLeft("   Hello");
        assertEquals("Hello", result);
    }

    @Test
    public void testTrimRight() {
        String result = trimRight("Hello   ");
        assertEquals("Hello", result);
    }

    @Test
    public void testTrimBoth() {
        String result = trimBoth("   Hello   ");
        assertEquals("Hello", result);
    }

    @Test
    public void testSubstring() {
        String result = substring("HelloWorld", 1, 5);
        assertEquals("elloW", result);
    }

    @Test
    public void testStringLength() {
        int result = stringLength("Hello");
        assertEquals(5, result);
    }

    @Test
    public void testCharacterEncoding() {
        String result = encode("Hello");
        assertEquals("SGVsbG8=", result);
    }

    @Test
    public void testCharacterDecoding() {
        String result = decode("SGVsbG8=");
        assertEquals("Hello", result);
    }

    @Test
    public void testCaseInsensitivity() {
        String result = concatenate("Hello", "World").toLowerCase();
        assertEquals("helloworld", result);
    }

    @Test
    public void testNullHandling() {
        String result = concatenate(null, "World");
        assertNull(result);
    }

    private String concatenate(String str1, String str2) {
        if (str1 == null || str2 == null) return null;
        return str1 + str2;
    }

    private String trimLeft(String str) {
        if (str == null) return null;
        return str.replaceAll("^\\s+", "");
    }

    private String trimRight(String str) {
        if (str == null) return null;
        return str.replaceAll("\\s+$", "");
    }

    private String trimBoth(String str) {
        if (str == null) return null;
        return str.trim();
    }

    private String substring(String str, int start, int end) {
        if (str == null) return null;
        return str.substring(start, end);
    }

    private int stringLength(String str) {
        if (str == null) return 0;
        return str.length();
    }

    private String encode(String str) {
        if (str == null) return null;
        return java.util.Base64.getEncoder().encodeToString(str.getBytes());
    }

    private String decode(String str) {
        if (str == null) return null;
        return new String(java.util.Base64.getDecoder().decode(str));
    }
}

