public class ConversationPropagator {

    private static final Logger logger = LoggerFactory.getLogger(ConversationPropagator.class);

    @Inject
    private Conversation conversation;

    @Inject
    private HttpServletRequest request;

    @Inject
    private HttpServletResponse response;

    public void onRequestStart(@Observes RequestStartEvent event) {
        logger.info("Request started: {}", event.getRequestURI());
        String conversationId = request.getParameter("cid");
        if (conversationId != null) {
            conversation.setId(conversationId);
            logger.debug("Conversation activated with ID: {}", conversationId);
        } else {
            conversation.begin();
            logger.debug("New conversation started with ID: {}", conversation.getId());
        }
    }

    public void onRequestEnd(@Observes RequestEndEvent event) {
        logger.info("Request ended: {}", event.getRequestURI());
        if (conversation.isTransient()) {
            logger.warn("Ending transient conversation");
            conversation.end();
        } else {
            logger.debug("Conversation with ID: {} is still active", conversation.getId());
        }
    }

    public void handleException(@Observes ExceptionEvent event) {
        logger.error("Exception occurred during conversation handling", event.getThrowable());
        if (!conversation.isTransient()) {
            conversation.end();
            logger.debug("Conversation ended due to exception with ID: {}", conversation.getId());
        }
    }
}

