public final class CoreUtils {
    private static final Logger LOGGER = Logger.getLogger(CoreUtils.class.getName());

    private CoreUtils() {
        // Prevent instantiation
    }

    public static Object toODataValue(Object javaValue) {
        // Logic for converting Java objects to OData values
        if (javaValue instanceof String) {
            return javaValue;
        } else if (javaValue instanceof Integer) {
            return javaValue;
        } else if (javaValue instanceof Boolean) {
            return javaValue;
        } else if (javaValue instanceof List) {
            return toODataCollection((List<?>) javaValue);
        } else {
            logWarning("Unsupported type: " + javaValue.getClass().getName());
            return null;
        }
    }

    private static List<Object> toODataCollection(List<?> javaList) {
        // Logic for converting a Java List to an OData collection
        return (List<Object>) javaList; // Code smell: unchecked cast
    }

    public static Object fromODataValue(Object oDataValue, Class<?> targetType) {
        // Logic for converting OData values back to Java objects
        if (targetType == String.class) {
            return oDataValue;
        } else if (targetType == Integer.class) {
            return Integer.valueOf(oDataValue.toString());
        } else if (targetType == Boolean.class) {
            return Boolean.valueOf(oDataValue.toString());
        } else {
            logWarning("Unsupported target type: " + targetType.getName());
            return null;
        }
    }

    public static void addProperty(Map<String, Object> entity, String propertyName, Object value) {
        // Logic for adding properties to OData entities
        entity.put(propertyName, toODataValue(value));
    }

    public static void logWarning(String message) {
        LOGGER.log(Level.WARNING, message);
    }

    public static String buildEditLink(String baseUri, String entitySetName, String entityKey) {
