public class GenerateVisitor extends Node.Visitor {
    private ServletWriter writer;
    private Tag currentTag;
    private int variableCount;

    public GenerateVisitor(ServletWriter writer) {
        this.writer = writer;
        this.variableCount = 0;
    }

    @Override
    public void visit(ExpressionNode node) {
        try {
            writer.write("out.print(" + node.getExpression() + ");");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    @Override
    public void visit(ScriptletNode node) {
        try {
            writer.write(node.getScriptlet());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    @Override
    public void visit(CustomTagNode node) {
        currentTag = node.getTagHandler();
        try {
            writer.write("Tag " + currentTag.getClass().getSimpleName() + " = new " + currentTag.getClass().getSimpleName() + "();");
            writer.write("if (" + currentTag.getClass().getSimpleName() + ".doStartTag() != Tag.SKIP_BODY) {");
            visit(node.getBody());
            writer.write(currentTag.getClass().getSimpleName() + ".doEndTag();");
            writer.write("}");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    @Override
    public void visit(AttributeNode node) {
        try {
            writer.write("String " + node.getName() + " = " + node.getValue() + ";");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void visit(Node node) {
        if (node instanceof ExpressionNode) {
            visit((ExpressionNode) node);
        } else if (node instanceof ScriptletNode) {
            visit((ScriptletNode) node);
        } else if (node instanceof CustomTagNode) {
            visit((CustomTagNode) node);
        } else if (node instanceof AttributeNode) {
            visit((AttributeNode) node);
        }
    }

    public void generate() {
        // Logic to start processing nodes
        // This method should iterate over nodes and call visit on each
    }
}

