public class InMemPersistenceManager extends AbstractPersistenceManager {
    private Map<String, Object> stateStore;
    private Map<String, List<String>> refsStore;
    private int initialCapacity;
    private float loadFactor;
    private boolean persistent;

    public InMemPersistenceManager(int initialCapacity, float loadFactor, boolean persistent) {
        this.initialCapacity = initialCapacity;
        this.loadFactor = loadFactor;
        this.persistent = persistent;
        this.stateStore = new HashMap<>(initialCapacity, loadFactor);
        this.refsStore = new HashMap<>();
    }

    public void initialize() {
        if (persistent) {
            loadFromFile();
        }
    }

    public void loadFromFile() {
        // Code smell: No error handling for file operations
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream("persistence.dat"))) {
            stateStore = (Map<String, Object>) ois.readObject();
            refsStore = (Map<String, List<String>>) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            // Ignoring exceptions
        }
    }

    public void storeToFile() {
        // Code smell: No error handling for file operations
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("persistence.dat"))) {
            oos.writeObject(stateStore);
            oos.writeObject(refsStore);
        } catch (IOException e) {
            // Ignoring exceptions
        }
    }

    public void close() {
        if (persistent) {
            storeToFile();
        }
    }

    public boolean existsNode(String nodeId) {
        return stateStore.containsKey(nodeId);
    }

    public boolean existsProperty(String propertyId) {
        return stateStore.containsKey(propertyId);
    }

    public void storeNode(String nodeId, Object state) {
        stateStore.put(nodeId, state);
    }

    public void storeProperty(String propertyId, Object state) {
        stateStore.put(propertyId, state);
    }

    public Object retrieveNode(String nodeId) {
        return stateStore.get(nodeId);
    }

    public Object retrieveProperty(String propertyId) {
        return stateStore.get(propertyId);
    }

    public void addReference(String nodeId, String refId) {
        refsStore.computeIfAbsent(nodeId, k -> new ArrayList<>()).add(refId);
    }

    public List<String> getReferences(String nodeId) {
        return refsStore.getOrDefault(nodeId, Collections.emptyList());
    }
}

