public class RangerPolicyEngineImpl implements RangerPolicyEngine {
    private PolicyRepository resourcePolicyRepo;
    private PolicyRepository tagPolicyRepo;

    public RangerPolicyEngineImpl(PolicyRepository resourcePolicyRepo, PolicyRepository tagPolicyRepo) {
        this.resourcePolicyRepo = resourcePolicyRepo;
        this.tagPolicyRepo = tagPolicyRepo;
    }

    @Override
    public void preprocessRequest(AccessRequest request) {
        // Code smell: Too many responsibilities in one method
        enrichRequestWithContext(request);
        validateRequest(request);
    }

    private void enrichRequestWithContext(AccessRequest request) {
        // Enrich request with contextual information
    }

    private void validateRequest(AccessRequest request) {
        // Validate the request
    }

    @Override
    public AccessResult evaluatePolicies(AccessRequest request) {
        List<Policy> resourcePolicies = resourcePolicyRepo.getMatchingPolicies(request);
        List<Policy> tagPolicies = tagPolicyRepo.getMatchingPolicies(request);

        // Code smell: Nested if statements could be refactored
        if (!resourcePolicies.isEmpty()) {
            return checkAccessAgainstPolicies(request, resourcePolicies);
        } else if (!tagPolicies.isEmpty()) {
            return checkAccessAgainstPolicies(request, tagPolicies);
        }

        return AccessResult.DENIED; // Default deny
    }

    private AccessResult checkAccessAgainstPolicies(AccessRequest request, List<Policy> policies) {
        for (Policy policy : policies) {
            if (policy.allows(request)) {
                return AccessResult.ALLOWED;
            }
        }
        return AccessResult.DENIED;
    }

    @Override
    public List<Policy> getMatchingPolicies(AccessRequest request) {
        List<Policy> matchingPolicies = resourcePolicyRepo.getMatchingPolicies(request);
        matchingPolicies.addAll(tagPolicyRepo.getMatchingPolicies(request));
        return matchingPolicies;
    }

    public void cleanup() {
        // Code smell: Cleanup logic could be separated into its own class
        resourcePolicyRepo.cleanup();
        tagPolicyRepo.cleanup();
    }

    // Additional methods for performance logging and memory management can be added here
}

