public class TestWatcherRemovalManager {

    private TestingServer testingServer;
    private CuratorFramework client;

    @Before
    public void setUp() throws Exception {
        testingServer = new TestingServer();
        client = CuratorFrameworkFactory.newClient(testingServer.getConnectString(), new RetryOneTime(1));
        client.start();
    }

    @After
    public void tearDown() throws Exception {
        client.close();
        testingServer.close();
    }

    @Test
    public void testWatcherRemovalOnNodeCreation() throws Exception {
        final CountDownLatch latch = new CountDownLatch(1);
        String path = "/testNode";

        Watcher watcher = new Watcher() {
            @Override
            public void process(WatchedEvent event) {
                if (event.getType() == EventType.NodeCreated) {
                    latch.countDown();
                }
            }
        };

        client.getData().usingWatcher(watcher).forPath(path);
        client.create().forPath(path);
        latch.await();

        // Remove the watcher
        client.getData().usingWatcher(watcher).forPath(path);
        client.delete().forPath(path);
        assertTrue("Watcher should be removed", latch.getCount() == 0);
    }

    @Test
    public void testWatcherRemovalOnDataChange() throws Exception {
        final CountDownLatch latch = new CountDownLatch(1);
        String path = "/testNode";

        client.create().forPath(path, "data".getBytes());

        Watcher watcher = new Watcher() {
            @Override
            public void process(WatchedEvent event) {
                if (event.getType() == EventType.NodeDataChanged) {
                    latch.countDown();
                }
            }
        };

        client.getData().usingWatcher(watcher).forPath(path);
        client.setData().forPath(path, "newData".getBytes());
        latch.await();

        // Remove the watcher
        client.getData().usingWatcher(watcher).forPath(path);
        assertTrue("Watcher should be removed", latch.getCount() == 0);
    }

    @Test
    public void testWatcherBehaviorOnNodeMissing() throws Exception {
        final CountDownLatch latch = new CountDownLatch(1);
        String path = "/nonExistentNode";

        Watcher watcher = new Watcher() {
            @Override
            public void process(WatchedEvent event) {
                if (event.getType() == EventType.NodeDeleted) {
                    latch.countDown();
                }
            }
        };

        client.getData().usingWatcher(watcher).forPath(path);
        // Simulate node deletion
        latch.await();
        assertTrue("Watcher should not trigger on missing node", latch.getCount() == 1);
    }

    @Test
    public void testWatcherRemovalInBackground() throws Exception {
        final CountDownLatch latch = new CountDownLatch(1);
        String path = "/testNode";

        client.create().forPath(path);

        Watcher watcher = new Watcher() {
            @Override
            public void process(WatchedEvent event) {
                if (event.getType() == EventType.NodeDeleted) {
                    latch.countDown();
                }
            }
        };

        client.getData().usingWatcher(watcher).forPath(path);
        client.delete().inBackground((client, event) -> {
            // Background deletion
        }).forPath(path);
        latch.await();

        // Remove the watcher
        client.getData().usingWatcher(watcher).forPath(path);
        assertTrue("Watcher should be removed", latch.getCount() == 0);
    }

    @Test
    public void testMultipleWatchersOnSamePath() throws Exception {
        final CountDownLatch latch1 = new CountDownLatch(1);
        final CountDownLatch latch2 = new CountDownLatch(1);
        String path = "/testNode";

        client.create().forPath(path);

        Watcher watcher1 = new Watcher() {
            @Override
            public void process(WatchedEvent event) {
                if (event.getType() == EventType.NodeDeleted) {
                    latch1.countDown();
                }
            }
        };

        Watcher watcher2 = new Watcher() {
            @Override
            public void process(WatchedEvent event) {
                if (event.getType() == EventType.NodeDeleted) {
                    latch2.countDown();
                }
            }
        };

        client.getData().usingWatcher(watcher1).forPath(path);
        client.getData().usingWatcher(watcher2).forPath(path);
        client.delete().forPath(path);
        latch1.await();
        latch2.await();

        // Remove the watchers
        client.getData().usingWatcher(watcher1).forPath(path);
