        try {
            XPathFactory xPathFactory = XPathFactory.newInstance();
            XPath xpath = xPathFactory.newXPath();
            String value = xpath.evaluate(xpathExpr, node);
            return value.isEmpty() ? defaultValue : value;
        } catch (XPathExpressionException e) {
            return defaultValue;
        }
    }

    public static void setValue(Node node, String xpathExpr, String value) {
        try {
            XPathFactory xPathFactory = XPathFactory.newInstance();
            XPath xpath = xPathFactory.newXPath();
            Node targetNode = (Node) xpath.evaluate(xpathExpr, node, XPathConstants.NODE);
            if (targetNode != null) {
                targetNode.setTextContent(value);
            }
        } catch (XPathExpressionException e) {
            // Handle exception
        }
    }

    public static Document createDocument(InputStream inputStream) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        return builder.parse(inputStream);
    }

    public static String serializeNode(Node node) {
        try {
            TransformerFactory transformerFactory = TransformerFactory.newInstance();
            Transformer transformer = transformerFactory.newTransformer();
            DOMSource source = new DOMSource(node);
            StringWriter writer = new StringWriter();
            StreamResult result = new StreamResult(writer);
            transformer.transform(source, result);
            return writer.toString();
        } catch (TransformerException e) {
            return null;
        }
    }

    public static NodeList selectNodes(Node node, String xpathExpr) {
        try {
            XPathFactory xPathFactory = XPathFactory.newInstance();
            XPath xpath = xPathFactory.newXPath();
            return (NodeList) xpath.evaluate(xpathExpr, node, XPathConstants.NODESET);
        } catch (XPathExpressionException e) {
            return null;
        }
    }

    public static Document createNewDocument() throws ParserConfigurationException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        return builder.newDocument();
    }

    public static boolean compareAttributes(Element element1, Element element2, String attributeName) {
        String attr1 = element1.getAttribute(attributeName);
        String attr2 = element2.getAttribute(attributeName);
        return attr1.equals(attr2);
    }

    public static void buildParametersFromXML(Node node, Map<String, String> params) {
        NodeList childNodes = node.getChildNodes();
        for (int i = 0; i < childNodes.getLength(); i++) {
            Node child = childNodes.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                params.put(child.getNodeName(), child.getTextContent());
            }
        }
    }

    public static void createNodeFromData(Document doc, String nodeName, Object data) {
        Element element = doc.createElement(nodeName);
        if (data instanceof String) {
            element.setTextContent((String) data);
        } else if (data instanceof Collection) {
            for (Object item : (Collection<?>) data) {
                Element itemElement = doc.createElement("item");
                itemElement.setTextContent(item.toString());
                element.appendChild(itemElement);
            }
        } else if (data instanceof Map) {
            for (Map.Entry<?, ?> entry : ((Map<?, ?>) data).entrySet()) {
                Element entryElement = doc.createElement(entry.getKey().toString());
                entryElement.setTextContent(entry.getValue().toString());
                element.appendChild(entryElement);
            }
        }
        doc.appendChild(element);
    }
}

public abstract class FileResourceConsumer implements Callable<Void> {
    private static final Logger logger = Logger.getLogger(FileResourceConsumer.class.getName());
    private final BlockingQueue<FileResource> queue;
    private int resourcesConsumed = 0;
    private int exceptionsHandled = 0;
    private volatile boolean running = true;

    public FileResourceConsumer(BlockingQueue<FileResource> queue) {
        this.queue = queue;
    }

    @Override
    public Void call() {
        while (running) {
            try {
                FileResource resource = queue.take();
                if (isPoisonPill(resource)) {
                    break;
                }
                processResource(resource);
                resourcesConsumed++;
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            } catch (Exception e) {
                handleException(e);
            }
        }
        logShutdown();
        return null;
    }

    protected abstract void processResource(FileResource resource);

    private void handleException(Exception e) {
        exceptionsHandled++;
        logger.severe("Exception while processing resource: " + e.getMessage());
    }

    private void logShutdown() {
        logger.info(String.format("Consumer shutting down. Resources consumed: %d, Exceptions handled: %d", 
                                   resourcesConsumed, exceptionsHandled));
    }

    private boolean isPoisonPill(FileResource resource) {
        return resource == null; // Assuming null is the poison pill
    }

    public void shutdown() {
        running = false;
    }
}

