        converter = null;
        immediate = false;
        required = false;
        validator = null;
        value = null;
        listener = null;
    }
}

public class GraphSONTypeSerializerV3d0 extends AbstractGraphSONTypeSerializer {

    @Override
    public void writeTypePrefix(JsonGenerator jsonGenerator, Object value) throws IOException {
        if (value instanceof Map) {
            jsonGenerator.writeStartObject();
        } else if (value instanceof List || value instanceof Set) {
            jsonGenerator.writeStartArray();
        } else if (value instanceof Vertex) {
            jsonGenerator.writeStartObject();
            jsonGenerator.writeFieldName("vertex");
        } else if (value instanceof Edge) {
            jsonGenerator.writeStartObject();
            jsonGenerator.writeFieldName("edge");
        } else {
            throw new IOException("Unsupported type for serialization: " + value.getClass().getName());
        }
    }

    @Override
    public void writeTypeSuffix(JsonGenerator jsonGenerator, Object value) throws IOException {
        if (value instanceof Map || value instanceof Vertex || value instanceof Edge) {
            jsonGenerator.writeEndObject();
        } else if (value instanceof List || value instanceof Set) {
            jsonGenerator.writeEndArray();
        } else {
            throw new IOException("Unsupported type for serialization: " + value.getClass().getName());
        }
    }

    @Override
    public void serializeValue(JsonGenerator jsonGenerator, Object value) throws IOException {
        if (value instanceof Map) {
            serializeMap(jsonGenerator, (Map<?, ?>) value);
        } else if (value instanceof List) {
            serializeList(jsonGenerator, (List<?>) value);
        } else if (value instanceof Set) {
            serializeSet(jsonGenerator, (Set<?>) value);
        } else if (value instanceof Vertex) {
            serializeVertex(jsonGenerator, (Vertex) value);
        } else if (value instanceof Edge) {
            serializeEdge(jsonGenerator, (Edge) value);
        } else {
            throw new IOException("Unsupported type for serialization: " + value.getClass().getName());
        }
    }

    private void serializeMap(JsonGenerator jsonGenerator, Map<?, ?> map) throws IOException {
        for (Map.Entry<?, ?> entry : map.entrySet()) {
            jsonGenerator.writeFieldName(entry.getKey().toString());
            serializeValue(jsonGenerator, entry.getValue());
        }
    }

    private void serializeList(JsonGenerator jsonGenerator, List<?> list) throws IOException {
        for (Object item : list) {
            serializeValue(jsonGenerator, item);
        }
    }

    private void serializeSet(JsonGenerator jsonGenerator, Set<?> set) throws IOException {
        for (Object item : set) {
            serializeValue(jsonGenerator, item);
        }
    }

    private void serializeVertex(JsonGenerator jsonGenerator, Vertex vertex) throws IOException {
        jsonGenerator.writeStringField("id", vertex.getId().toString());
        jsonGenerator.writeStringField("label", vertex.getLabel());
        // Additional vertex properties can be serialized here
    }

    private void serializeEdge(JsonGenerator jsonGenerator, Edge edge) throws IOException {
        jsonGenerator.writeStringField("id", edge.getId().toString());
        jsonGenerator.writeStringField("label", edge.getLabel());
        // Additional edge properties can be serialized here
    }
}

