        if (!specificationCache.containsKey(serviceId)) {
            Object specification = programmingModel.loadSpecification(serviceId);
            facetProcessor.process(specification);
            specificationCache.put(serviceId, specification);
        }
    }

    public void loadMixinSpecification(String mixinId) {
        if (!specificationCache.containsKey(mixinId)) {
            Object specification = programmingModel.loadSpecification(mixinId);
            facetProcessor.process(specification);
            specificationCache.put(mixinId, specification);
        }
    }

    public void validateModel() {
        for (Object specification : specificationCache.values()) {
