public class Memento implements Serializable {
    private static final Logger logger = Logger.getLogger(Memento.class.getName());
    private Map<String, Object> state;
    private Map<String, Object> transientObjects;

    public Memento() {
        state = new HashMap<>();
        transientObjects = new HashMap<>();
    }

    public void captureState(ObjectAdapter adapter) {
        logger.info("Capturing state of ObjectAdapter");
        state.put("field1", adapter.getField1());
        state.put("field2", adapter.getField2());
        // Capture associations
        state.put("associations", adapter.getAssociations());
        // Handle collections
        state.put("collection", adapter.getCollection());
    }

    public void restoreState(ObjectAdapter adapter) {
        logger.info("Restoring state of ObjectAdapter");
        adapter.setField1((String) state.get("field1"));
        adapter.setField2((String) state.get("field2"));
        // Restore associations
        adapter.setAssociations((Map<String, Object>) state.get("associations"));
        // Restore collections
        adapter.setCollection((Collection<Object>) state.get("collection"));
    }

    public void updateField(String key, Object value) {
        logger.info("Updating field: " + key);
        state.put(key, value);
    }

    public void addTransientObject(String key, Object value) {
        logger.info("Adding transient object: " + key);
        transientObjects.put(key, value);
    }

    public Object getTransientObject(String key) {
        return transientObjects.get(key);
    }

    public void clearTransientObjects() {
        logger.info("Clearing transient objects");
        transientObjects.clear();
    }
}

