public class JobNodeConfigurationGenerator {
    private static final Logger logger = LoggerFactory.getLogger(JobNodeConfigurationGenerator.class);

    public JobConfiguration generateJobConfiguration(JobNode jobNode, ExecutionPlan executionPlan) {
        JobConfiguration jobConfig = new JobConfiguration();

        // Validate job ID and name
        if (!isValidJobId(jobNode.getJobId())) {
            logger.error("Invalid Job ID: {}", jobNode.getJobId());
            throw new IllegalArgumentException("Invalid Job ID");
        }

        if (!isValidJobName(jobNode.getJobName())) {
            logger.error("Invalid Job Name: {}", jobNode.getJobName());
            throw new IllegalArgumentException("Invalid Job Name");
        }

        jobConfig.setJobId(jobNode.getJobId());
        jobConfig.setJobName(jobNode.getJobName());

        // Handle input and output streams
        jobConfig.setInputStreams(executionPlan.getInputStreams());
        jobConfig.setOutputStreams(executionPlan.getOutputStreams());

        // Handle stateful operators
        if (jobNode.isStateful()) {
            jobConfig.setStateful(true);
            jobConfig.setStateBackend(jobNode.getStateBackend());
        }

        // Handle window intervals
        jobConfig.setWindowInterval(jobNode.getWindowInterval());

        // Handle SerDe configurations
        jobConfig.setSerializationConfig(jobNode.getSerializationConfig());
        jobConfig.setDeserializationConfig(jobNode.getDeserializationConfig());

        // Manage broadcast inputs
        if (jobNode.hasBroadcastInputs()) {
            jobConfig.setBroadcastInputs(jobNode.getBroadcastInputs());
        }

        // Manage table configurations
        if (jobNode.hasTableConfig()) {
            jobConfig.setTableConfig(jobNode.getTableConfig());
        }

        logger.info("Generated Job Configuration: {}", jobConfig);
        return jobConfig;
    }

    private boolean isValidJobId(String jobId) {
        return jobId != null && !jobId.trim().isEmpty();
    }

    private boolean isValidJobName(String jobName) {
        return jobName != null && !jobName.trim().isEmpty();
    }

    public JobConfiguration mergeConfigurations(JobConfiguration originalConfig, JobConfiguration newConfig) {
        // Merge logic with potential code smells
        if (originalConfig.getJobId() != null && !originalConfig.getJobId().equals(newConfig.getJobId())) {
            logger.warn("Job ID mismatch: original={}, new={}", originalConfig.getJobId(), newConfig.getJobId());
        }

        if (originalConfig.getJobName() != null && !originalConfig.getJobName().equals(newConfig.getJobName())) {
            logger.warn("Job Name mismatch: original={}, new={}", originalConfig.getJobName(), newConfig.getJobName());
        }

        // Merging other configurations
        originalConfig.setInputStreams(newConfig.getInputStreams());
        originalConfig.setOutputStreams(newConfig.getOutputStreams());
        originalConfig.setStateful(newConfig.isStateful());
        originalConfig.setWindowInterval(newConfig.getWindowInterval());
        originalConfig.setSerializationConfig(newConfig.getSerializationConfig());
        originalConfig.setDeserializationConfig(newConfig.getDeserializationConfig());
        originalConfig.setBroadcastInputs(newConfig.getBroadcastInputs());
        originalConfig.setTableConfig(newConfig.getTableConfig());

        logger.info("Merged Job Configuration: {}", originalConfig);
        return originalConfig;
    }
}

