public class Asn1Choice extends AbstractAsn1Type implements Asn1Dumpable {
    private Asn1FieldInfo[] fieldInfos;
    private int chosenFieldIndex = -1;
    private Object chosenValue;

    public Asn1Choice(Asn1FieldInfo[] fieldInfos) {
        this.fieldInfos = fieldInfos;
    }

    public void encode(Asn1OutputStream out) {
        if (chosenFieldIndex < 0 || chosenFieldIndex >= fieldInfos.length) {
            throw new IllegalStateException("No field chosen for encoding.");
        }
        fieldInfos[chosenFieldIndex].encode(chosenValue, out);
    }

    public void decode(Asn1InputStream in) {
        chosenFieldIndex = in.readFieldIndex();
        if (chosenFieldIndex < 0 || chosenFieldIndex >= fieldInfos.length) {
            throw new IllegalArgumentException("Invalid field index.");
        }
        chosenValue = fieldInfos[chosenFieldIndex].decode(in);
    }

    public void setChosenField(int index, Object value) {
        if (index < 0 || index >= fieldInfos.length) {
            throw new IllegalArgumentException("Invalid field index.");
        }
        chosenFieldIndex = index;
        chosenValue = value;
    }

    public Object getChosenValue() {
        return chosenValue;
    }

    public int getChosenFieldIndex() {
        return chosenFieldIndex;
    }

    @Override
    public String dump() {
        StringBuilder sb = new StringBuilder();
        sb.append("Asn1Choice: \n");
        sb.append("Chosen Field Index: ").append(chosenFieldIndex).append("\n");
        sb.append("Chosen Value: ").append(chosenValue).append("\n");
        sb.append("Available Fields: ").append(Arrays.toString(fieldInfos)).append("\n");
        return sb.toString();
    }
}

