public class JMSUtils {

    public static void setMessageProperty(Message jmsMessage, String propertyName, Object value) {
        try {
            jmsMessage.setObjectProperty(propertyName, value);
        } catch (JMSException e) {
            e.printStackTrace(); // Code smell: Swallowing exceptions
        }
    }

    public static Object getMessageProperty(Message jmsMessage, String propertyName) {
        try {
            return jmsMessage.getObjectProperty(propertyName);
        } catch (JMSException e) {
            e.printStackTrace(); // Code smell: Swallowing exceptions
            return null; // Code smell: Returning null on error
        }
    }

    public static Message createTextMessage(Session session, String text) throws JMSException {
        return session.createTextMessage(text);
    }

    public static Message createBytesMessage(Session session, byte[] bytes) throws JMSException {
        BytesMessage bytesMessage = session.createBytesMessage();
        bytesMessage.writeBytes(bytes);
        return bytesMessage;
    }

    public static Message createObjectMessage(Session session, Serializable object) throws JMSException {
        return session.createObjectMessage(object);
    }

    public static void setTimeToLive(Message message, long timeToLive) {
        try {
            message.setLongProperty("JMS_TTL", timeToLive);
        } catch (JMSException e) {
            e.printStackTrace(); // Code smell: Swallowing exceptions
        }
    }

    public static void populateMessageFromContext(Message jmsMessage, Map<String, Object> context) {
        for (Map.Entry<String, Object> entry : context.entrySet()) {
            setMessageProperty(jmsMessage, entry.getKey(), entry.getValue());
        }
    }

    public static String getContentType(Message jmsMessage) {
        return (String) getMessageProperty(jmsMessage, "Content-Type");
    }

    public static void setContentType(Message jmsMessage, String contentType) {
        setMessageProperty(jmsMessage, "Content-Type", contentType);
    }

    public static Message buildJMSMessageFromCXFMessage(Message cxfMessage, Session session) throws JMSException {
        Message jmsMessage = createTextMessage(session, (String) cxfMessage.getContent(String.class));
        populateMessageFromContext(jmsMessage, cxfMessage.getProperties());
        return jmsMessage;
    }

    public static String createCorrelationId() {
        return UUID.randomUUID().toString();
    }

