public class ManagementContext implements Service {
    private static final Logger logger = Logger.getLogger(ManagementContext.class.getName());
    private MBeanServer mBeanServer;
    private JMXConnectorServer connectorServer;
    private String domain;
    private String host;
    private int port;
    private String path;

    public ManagementContext(String domain, String host, int port, String path) {
        this.domain = domain;
        this.host = host;
        this.port = port;
        this.path = path;
    }

    public void start() {
        try {
            createMBeanServer();
            createConnectorServer();
            connectorServer.start();
            logger.log(Level.INFO, "JMX Connector Server started at {0}:{1}{2}", new Object[]{host, port, path});
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to start JMX Connector Server", e);
        }
    }

    public void stop() {
        try {
            if (connectorServer != null) {
                connectorServer.stop();
                logger.log(Level.INFO, "JMX Connector Server stopped");
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Failed to stop JMX Connector Server", e);
        }
    }

    private void createMBeanServer() {
        mBeanServer = java.lang.management.ManagementFactory.getPlatformMBeanServer();
    }

    private void createConnectorServer() throws Exception {
        Registry registry = LocateRegistry.createRegistry(port);
        Map<String, Object> environment = new HashMap<>();
        environment.put("jmx.remote.server.address", host);
        connectorServer = JMXConnectorServerFactory.newJMXConnectorServer(new ObjectName(domain + ":type=connector"), environment, mBeanServer);
    }

    public void registerMBean(Object mBean, String objectName) {
        try {
            mBeanServer.registerMBean(mBean, new ObjectName(objectName));
            logger.log(Level.INFO, "Registered MBean: {0}", objectName);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to register MBean: " + objectName, e);
        }
    }

    public void unregisterMBean(String objectName) {
        try {
            mBeanServer.unregisterMBean(new ObjectName(objectName));
            logger.log(Level.INFO, "Unregistered MBean: {0}", objectName);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to unregister MBean: " + objectName, e);
        }
    }

    public Object getAttribute(String objectName, String attribute) {
        try {
            return mBeanServer.getAttribute(new ObjectName(objectName), attribute);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to get attribute: " + attribute + " from MBean: " + objectName, e);
            return null;
        }
    }

    public void setAttribute(String objectName, String attribute, Object value) {
        try {
            mBeanServer.setAttribute(new ObjectName(objectName), attribute, value);
            logger.log(Level.INFO, "Set attribute: {0} of MBean: {1} to {2}", new Object[]{attribute, objectName, value});
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to set attribute: " + attribute + " of MBean: " + objectName, e);
        }
    }
}

