public abstract class CachingSessionDAO extends AbstractSessionDAO implements CacheManagerAware {

    private CacheManager cacheManager;
    private Cache<String, Session> activeSessionCache;

    @Override
    public void setCacheManager(CacheManager cacheManager) {
        this.cacheManager = cacheManager;
        this.activeSessionCache = cacheManager.getCache("activeSessionCache");
    }

    protected Cache<String, Session> getActiveSessionCache() {
        if (activeSessionCache == null) {
            activeSessionCache = cacheManager.getCache("activeSessionCache");
        }
        return activeSessionCache;
    }

    @Override
    protected Serializable doCreate(Session session) {
        Serializable sessionId = generateSessionId(session);
        assignSessionId(session, sessionId);
        getActiveSessionCache().put(sessionId.toString(), session);
        return sessionId;
    }

    @Override
    protected Session doReadSession(Serializable sessionId) {
        return getActiveSessionCache().get(sessionId.toString());
    }

    @Override
    public void update(Session session) {
        if (session != null && session.getId() != null) {
            getActiveSessionCache().put(session.getId().toString(), session);
        }
    }

    @Override
    public void delete(Session session) {
        if (session != null && session.getId() != null) {
            getActiveSessionCache().remove(session.getId().toString());
        }
    }

    public Collection<Session> getActiveSessions() {
        return Collections.unmodifiableCollection(getActiveSessionCache().values());
    }

    protected boolean isValid(Session session) {
        return session != null && !session.isExpired();
    }

    protected void validateAndCacheSession(Session session) {
        if (isValid(session)) {
            update(session);
        } else {
            delete(session);
        }
    }
}

