        }
        double temp = x + 5.5;
        double ser = 1.000000000190015;
        for (int i = 0; i < lanczosCoefficients.length; i++) {
            ser += lanczosCoefficients[i] / (x + i);
        }
        return Math.log(ser) + (x + 0.5) * Math.log(temp) - temp;
    }

    public double regularizedGammaP(double a, double x) {
        // Implementation of regularized lower incomplete gamma function
        // Code smells: No checks for a <= 0 or x < 0
        if (x < 0 || a <= 0) {
            return Double.NaN; // Not handling invalid inputs properly
        }
        double sum = 1.0 / a;
        double term = sum;
        for (int n = 1; n < 100; n++) {
            term *= x / (a + n);
            sum += term;
            if (term < 1e-10) break; // Arbitrary convergence threshold
        }
        return sum * Math.exp(-x + a * Math.log(x));
    }

    public double regularizedGammaQ(double a, double x) {
        // Implementation of regularized upper incomplete gamma function
        // Code smells: No checks for a <= 0 or x < 0
        if (x < 0 || a <= 0) {
            return Double.NaN; // Not handling invalid inputs properly
        }
        return 1.0 - regularizedGammaP(a, x);
    }

    public double digamma(double x) {
        // Implementation of digamma function
        // Code smells: No checks for x <= 0
        if (x <= 0) {
            return Double.NaN; // Not handling invalid inputs properly
        }
        double result = 0.0;
        while (x < 7) {
            result -= 1.0 / x;
            x++;
        }
        double y = 1.0 / (x * x);
        result += Math.log(x) - 0.5 * y;
        return result + y * (1.0 / 12 - y * (1.0 / 120 - y * (1.0 / 252)));
    }

    public double trigamma(double x) {
        // Implementation of trigamma function
        // Code smells: No checks for x <= 0
        if (x <= 0) {
            return Double.NaN; // Not handling invalid inputs properly
        }
        return 1.0 / (x * x) + 0.5 * trigamma(x + 1);
    }

    public double lanczos(double x) {
        // Implementation of Lanczos approximation
        // Code smells: No checks for x <= 0
        if (x <= 0) {
            return Double.NaN; // Not handling invalid inputs properly
        }
        double z = x + 0.5;
        double sum = 0.0;
        for (int i = 0; i < lanczosCoefficients.length; i++) {
            sum += lanczosCoefficients[i] / (x + i);
        }
        return Math.sqrt(2 * Math.PI) * Math.pow(z, x + 0.5) * Math.exp(-z) * sum;
    }

    public double invGamma1pm1(double x) {
        // Implementation of inverse of regularized gamma function
        // Code smells: No checks for x <= 0 or x >= 1
        if (x <= 0 || x >= 1) {
            return Double.NaN; // Not handling invalid inputs properly
        }
        // Placeholder for actual implementation
        return 0.0; // Not implemented
    }

    public double logGamma1p(double x) {
        // Implementation of logarithm of regularized gamma function
        // Code smells: No checks for x < 0
        if (x < 0) {
            return Double.NaN; // Not handling invalid inputs properly
        }
        return logGamma(x + 1);
    }

    public double gamma(double x) {
        // Implementation of gamma function
        // Code smells: No checks for x <= 0
