class ArcsSetTest {

    private ArcsSet arcsSet;

    @BeforeEach
    void setUp() {
        arcsSet = new ArcsSet();
    }

    @Test
    void testCreateArc() {
        Arc arc = new Arc(1.0, 2.0, 0.1);
        arcsSet.addArc(arc);
        assertEquals(1, arcsSet.size());
        assertEquals(0.1, arc.getTolerance());
    }

    @Test
    void testArcSize() {
        arcsSet.addArc(new Arc(1.0, 2.0, 0.1));
        arcsSet.addArc(new Arc(3.0, 4.0, 0.2));
        assertEquals(2, arcsSet.size());
    }

    @Test
    void testPointLocation() {
        arcsSet.addArc(new Arc(1.0, 2.0, 0.1));
        assertTrue(arcsSet.containsPoint(1.5));
        assertFalse(arcsSet.containsPoint(3.0));
        assertTrue(arcsSet.containsPoint(1.0));
        assertTrue(arcsSet.containsPoint(2.0));
    }

    @Test
    void testWrapAroundBoundary() {
        arcsSet.addArc(new Arc(5.0, 1.0, 0.1));
        assertTrue(arcsSet.containsPoint(0.5));
        assertTrue(arcsSet.containsPoint(5.5));
        assertFalse(arcsSet.containsPoint(3.0));
    }

    @Test
    void testSplitArcs() {
        Arc arc = new Arc(1.0, 5.0, 0.1);
        Set<Arc> splitArcs = arcsSet.splitArc(arc, 3.0);
        assertEquals(2, splitArcs.size());
        assertTrue(splitArcs.contains(new Arc(1.0, 3.0, 0.1)));
        assertTrue(splitArcs.contains(new Arc(3.0, 5.0, 0.1)));
    }

    @Test
    void testEmptySet() {
        assertEquals(0, arcsSet.size());
        assertFalse(arcsSet.containsPoint(1.0));
    }

    @Test
    void testFullCircle() {
        arcsSet.addArc(new Arc(0.0, 2 * Math.PI, 0.1));
        assertTrue(arcsSet.containsPoint(Math.PI));
        assertTrue(arcsSet.containsPoint(0.0));
        assertTrue(arcsSet.containsPoint(2 * Math.PI));
    }

    @Test
    void testSinglePoint() {
        arcsSet.addArc(new Arc(1.0, 1.0, 0.0));
        assertTrue(arcsSet.containsPoint(1.0));
        assertFalse(arcsSet.containsPoint(1.1));
    }

    @Test
    void testUnion() {
        arcsSet.addArc(new Arc(1.0, 2.0, 0.1));
        arcsSet.addArc(new Arc(2.0, 3.0, 0.1));
        ArcsSet unionSet = arcsSet.union(new ArcsSet());
        assertEquals(3, unionSet.size());
    }

    @Test
    void testIntersection() {
        arcsSet.addArc(new Arc(1.0, 3.0, 0.1));
        ArcsSet otherSet = new ArcsSet();
        otherSet.addArc(new Arc(2.0, 4.0, 0.1));
        ArcsSet intersectionSet = arcsSet.intersection(otherSet);
        assertEquals(1, intersectionSet.size());
        assertTrue(intersectionSet.containsArc(new Arc(2.0, 3.0, 0.1)));
    }

    @Test
    void testDifference() {
        arcsSet.addArc(new Arc(1.0, 3.0, 0.1));
        ArcsSet otherSet = new ArcsSet();
        otherSet.addArc(new Arc(2.0, 4.0, 0.1));
        ArcsSet differenceSet = arcsSet.difference(otherSet);
        assertEquals(1, differenceSet.size());
        assertTrue(differenceSet.containsArc(new Arc(1.0, 2.0, 0.1)));
    }

    @Test
    void testOverlappingArcs() {
        arcsSet.addArc(new Arc(1.0, 3.0, 0.1));
        arcsSet.addArc(new Arc(2.0, 4.0, 0.1));
        assertEquals(2, arcsSet.size());
    }

    @Test
    void testEmbeddedArcs() {
        arcsSet.addArc(new Arc(1.0, 5.0, 0.1));
        arcsSet.addArc(new Arc(2.0, 3.0, 0.1));
        assertEquals(2, arcsSet.size());
    }

    @Test
    void testEdgeCases() {
        assertThrows(IllegalArgumentException.class, () -> {
            arcsSet.addArc(new Arc(2.0, 1.0, 0.1)); // Invalid arc
        });
    }
}

