public class NodeImpl implements Node {
    private String nodeName;
    private Map<String, Object> properties;
    private Map<String, NodeImpl> childNodes;
    private boolean isCheckedOut;
    private boolean isLocked;
    private String primaryType;
    private String[] mixinTypes;

    public NodeImpl(String nodeName, String primaryType) {
        this.nodeName = nodeName;
        this.primaryType = primaryType;
        this.properties = new HashMap<>();
        this.childNodes = new HashMap<>();
        this.isCheckedOut = true;
        this.isLocked = false;
    }

    public void addProperty(String name, Object value) {
        if (!isCheckedOut) {
            throw new IllegalStateException("Node is not checked out");
        }
        properties.put(name, value);
    }

    public Object getProperty(String name) {
        return properties.get(name);
    }

    public void addChildNode(String childNodeName, String childNodeType) {
        if (!isCheckedOut) {
            throw new IllegalStateException("Node is not checked out");
        }
        if (childNodes.containsKey(childNodeName)) {
            throw new IllegalArgumentException("Child node already exists");
        }
        childNodes.put(childNodeName, new NodeImpl(childNodeName, childNodeType));
    }

    public NodeImpl getChildNode(String childNodeName) {
        return childNodes.get(childNodeName);
    }

    public void checkIn() {
        if (isLocked) {
            throw new IllegalStateException("Node is locked");
        }
        isCheckedOut = false;
    }

    public void checkOut() {
        if (isLocked) {
            throw new IllegalStateException("Node is locked");
        }
        isCheckedOut = true;
    }

    public void lock() {
        if (isCheckedOut) {
            throw new IllegalStateException("Node must be checked out to lock");
        }
        isLocked = true;
    }

    public void unlock() {
        isLocked = false;
    }

    public void restore(NodeImpl previousVersion) {
        if (isCheckedOut) {
            throw new IllegalStateException("Node must be checked in to restore");
        }
        this.properties = previousVersion.properties;
        this.childNodes = previousVersion.childNodes;
        this.primaryType = previousVersion.primaryType;
        this.mixinTypes = previousVersion.mixinTypes;
    }

    public boolean hasChildNode(String childNodeName) {
        return childNodes.containsKey(childNodeName);
    }

    public boolean hasProperty(String name) {
        return properties.containsKey(name);
    }

    public String getNodeName() {
        return nodeName;
    }

    public String getPrimaryType() {
        return primaryType;
    }

    public String[] getMixinTypes() {
        return mixinTypes;
    }

    public void setMixinTypes(String[] mixinTypes) {
        if (!isCheckedOut) {
            throw new IllegalStateException("Node is not checked out");
        }
        this.mixinTypes = mixinTypes;
    }
}

