        interceptors.remove(interceptor);
    }

    public List<Policy> aggregatePolicies(List<String> providerNames) {
        List<Policy> aggregatedPolicies = new ArrayList<>();
        for (String name : providerNames) {
            PolicyProvider provider = getPolicyProvider(name);
            if (provider != null) {
                aggregatedPolicies.addAll(provider.getPolicies());
            }
        }
        return aggregatedPolicies;
    }

    public EffectivePolicy createEffectivePolicy(Endpoint endpoint, BindingOperation operation) {
        // Code smell: Method too long, could be broken down into smaller methods
        EffectivePolicy effectivePolicy = new EffectivePolicy();
        if (policyProcessingEnabled) {
            List<Policy> policies = aggregatePolicies(endpoint.getPolicyProviderNames());
            effectivePolicy.applyPolicies(policies);
        }
        return effectivePolicy;
    }

    public void initializeEndpointPolicies(Endpoint endpoint) {
        // Code smell: Method does too much, could be split into smaller methods
        if (policyProcessingEnabled) {
            EffectivePolicy effectivePolicy = createEffectivePolicy(endpoint, endpoint.getBindingOperation());
            endpoint.setEffectivePolicy(effectivePolicy);
        }
    }

