public abstract class Usage {
    private final List<UsageListener> listeners = new ArrayList<>();
    private final List<Usage> children = new ArrayList<>();
    private int limit;
    private int currentUsage;
    private boolean tracking;

    public Usage(int limit) {
        this.limit = limit;
        this.currentUsage = 0;
        this.tracking = false;
    }

    public synchronized void addListener(UsageListener listener) {
        listeners.add(listener);
    }

    public synchronized void removeListener(UsageListener listener) {
        listeners.remove(listener);
    }

    public synchronized void addChild(Usage child) {
        children.add(child);
    }

    public synchronized void removeChild(Usage child) {
        children.remove(child);
    }

    public synchronized void startTracking() {
        tracking = true;
    }

    public synchronized void stopTracking() {
        tracking = false;
    }

    public synchronized void setLimit(int limit) {
        this.limit = limit;
        notifyListeners();
    }

    public synchronized void adjustUsage(int amount) {
        currentUsage += amount;
        if (currentUsage > limit) {
            currentUsage = limit;
        }
        notifyListeners();
        if (currentUsage == limit) {
            waitForAvailableSpace();
        }
    }

    public synchronized int getCurrentUsage() {
        return currentUsage;
    }

    public synchronized int getLimit() {
        return limit;
    }

    private void notifyListeners() {
        for (UsageListener listener : listeners) {
            listener.onUsageChanged(this);
        }
    }

    private void waitForAvailableSpace() {
        while (currentUsage >= limit) {
            try {
                wait();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public synchronized void releaseUsage(int amount) {
        currentUsage -= amount;
        if (currentUsage < 0) {
            currentUsage = 0;
        }
        notifyListeners();
        notifyAll();
    }

    public interface UsageListener {
        void onUsageChanged(Usage usage);
    }
}

