public class ArrayRealVector extends RealVector implements Serializable {
    private static final long serialVersionUID = 1L;
    private final double[] data;

    public ArrayRealVector(int size) {
        this.data = new double[size];
    }

    public ArrayRealVector(double[] array) {
        this.data = Arrays.copyOf(array, array.length);
    }

    public ArrayRealVector(ArrayRealVector vector) {
        this.data = Arrays.copyOf(vector.data, vector.data.length);
    }

    @Override
    public RealVector add(RealVector v) {
        checkVectorDimensions(v);
        double[] result = new double[data.length];
        for (int i = 0; i < data.length; i++) {
            result[i] = data[i] + v.getEntry(i);
        }
        return new ArrayRealVector(result);
    }

    @Override
    public RealVector subtract(RealVector v) {
        checkVectorDimensions(v);
        double[] result = new double[data.length];
        for (int i = 0; i < data.length; i++) {
            result[i] = data[i] - v.getEntry(i);
        }
        return new ArrayRealVector(result);
    }

    @Override
    public RealVector mapAdd(double d) {
        double[] result = new double[data.length];
        for (int i = 0; i < data.length; i++) {
            result[i] = data[i] + d;
        }
        return new ArrayRealVector(result);
    }

    @Override
    public RealVector mapMultiply(double d) {
        double[] result = new double[data.length];
        for (int i = 0; i < data.length; i++) {
            result[i] = data[i] * d;
        }
        return new ArrayRealVector(result);
    }

    @Override
    public double dotProduct(RealVector v) {
        checkVectorDimensions(v);
        double sum = 0;
        for (int i = 0; i < data.length; i++) {
            sum += data[i] * v.getEntry(i);
        }
        return sum;
    }

    @Override
    public double getEntry(int index) {
        checkIndex(index);
        return data[index];
    }

    @Override
    public void setEntry(int index, double value) {
        checkIndex(index);
        data[index] = value;
    }

    public void append(double value) {
        double[] newData = Arrays.copyOf(data, data.length + 1);
        newData[newData.length - 1] = value;
        this.data = newData;
    }

    public void append(ArrayRealVector vector) {
        double[] newData = Arrays.copyOf(data, data.length + vector.data.length);
        System.arraycopy(vector.data, 0, newData, data.length, vector.data.length);
        this.data = newData;
    }

    private void checkVectorDimensions(RealVector v) {
        if (v.getDimension() != data.length) {
            throw new IllegalArgumentException("Dimension mismatch");
        }
    }

    private void checkIndex(int index) {
        if (index < 0 || index >= data.length) {
            throw new ArrayIndexOutOfBoundsException("Index: " + index + ", Size: " + data.length);
        }
    }

    public int getDimension() {
        return data.length;
    }

    public boolean isNaN() {
        for (double value : data) {
            if (Double.isNaN(value)) {
                return true;
            }
        }
        return false;
    }

    public boolean isInfinite() {
        for (double value : data) {
            if (Double.isInfinite(value)) {
                return true;
            }
        }
        return false;
    }
}

class SummaryStatisticsTest {

    private SummaryStatistics stats;

    @BeforeEach
    void setUp() {
        stats = new SummaryStatistics();
    }

    @Test
    void testAddValue() {
        stats.addValue(5);
        stats.addValue(10);
        assertEquals(7.5, stats.getMean(), 0.001);
        assertEquals(25.0, stats.getVariance(), 0.001);
        assertEquals(Math.sqrt(25.0), stats.getStandardDeviation(), 0.001);
    }

    @Test
    void testNoValues() {
        assertThrows(IllegalStateException.class, stats::getMean);
        assertThrows(IllegalStateException.class, stats::getVariance);
        assertThrows(IllegalStateException.class, stats::getStandardDeviation);
    }

    @Test
    void testClear() {
        stats.addValue(5);
        stats.addValue(10);
        stats.clear();
        assertThrows(IllegalStateException.class, stats::getMean);
    }

    @Test
    void testGeometricMean() {
        stats.addValue(1);
        stats.addValue(4);
        stats.addValue(16);
        assertEquals(2.828427, stats.getGeometricMean(), 0.000001);
    }

    @Test
    void testSerialization() throws IOException, ClassNotFoundException {
        stats.addValue(5);
        stats.addValue(10);

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(baos);
        oos.writeObject(stats);
        oos.close();

        ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
        ObjectInputStream ois = new ObjectInputStream(bais);
        SummaryStatistics deserializedStats = (SummaryStatistics) ois.readObject();

        assertEquals(stats.getMean(), deserializedStats.getMean(), 0.001);
        assertEquals(stats.getVariance(), deserializedStats.getVariance(), 0.001);
    }

    @Test
    void testEqualsAndHashCode() {
        SummaryStatistics stats1 = new SummaryStatistics();
        SummaryStatistics stats2 = new SummaryStatistics();

        stats1.addValue(5);
        stats2.addValue(5);

        assertEquals(stats1, stats2);
        assertEquals(stats1.hashCode(), stats2.hashCode());

        stats2.addValue(10);
        assertNotEquals(stats1, stats2);
    }

    @Test
    void testOverrideMethods() {
        SummaryStatistics customStats = new SummaryStatistics() {
            @Override
            public double getMean() {
                return super.getMean() * 2; // Custom behavior
            }
        };

        customStats.addValue(5);
        customStats.addValue(10);
        assertEquals(15.0, customStats.getMean(), 0.001);
    }
}

