public class WildCardRuleElement extends AbstractRuleElement {
    private List<Condition> conditions;
    private List<Action> actions;

    public WildCardRuleElement() {
        this.conditions = new ArrayList<>();
        this.actions = new ArrayList<>();
    }

    public void addCondition(Condition condition) {
        conditions.add(condition);
    }

    public void addAction(Action action) {
        actions.add(action);
    }

    public void startMatching(DataStream dataStream) {
        while (dataStream.hasNext()) {
            Data data = dataStream.next();
            if (matches(data)) {
                handleMatch(data);
            }
        }
    }

    private boolean matches(Data data) {
        for (Condition condition : conditions) {
            if (!condition.evaluate(data)) {
                return false;
            }
        }
        return true;
    }

    private void handleMatch(Data data) {
        for (Action action : actions) {
            action.execute(data);
        }
    }

    public void continueMatching(DataStream dataStream) {
        while (dataStream.hasNext()) {
            Data data = dataStream.next();
            if (matches(data)) {
                handleMatch(data);
            }
        }
    }

    // Nested rule elements handling
    public void processNestedRuleElements(List<WildCardRuleElement> nestedElements, DataStream dataStream) {
        for (WildCardRuleElement element : nestedElements) {
            element.startMatching(dataStream);
        }
    }
}

public class InvocationContextImpl implements InvocationContext {
    private Map<String, Object> contextData = new HashMap<>();
    private Method method;
    private Object[] parameters;
    private Object target;
    private Object interceptorData;

    public InvocationContextImpl(Method method, Object[] parameters, Object target, Object interceptorData) {
        this.method = method;
        this.parameters = parameters;
        this.target = target;
        this.interceptorData = interceptorData;
    }

    @Override
    public Object proceed() throws Exception {
        // Security check for method accessibility
        if (!method.isAccessible()) {
            method.setAccessible(true);
        }
        return method.invoke(target, parameters);
    }

    @Override
    public Map<String, Object> getContextData() {
        return contextData;
    }

    @Override
    public Method getMethod() {
        return method;
    }

    @Override
    public Object[] getParameters() {
        return parameters;
    }

    @Override
    public Object getTarget() {
        return target;
    }

    @Override
    public Object getInterceptorData() {
        return interceptorData;
    }

    @Override
    public void setParameters(Object[] parameters) {
        this.parameters = parameters;
    }

