        });
        assertEquals("Invalid artifact type", exception.getMessage());
    }

    @Test
    void testValidPathWithClassifier() {
        String path = "com/example/artifact/1.0.0/artifact-1.0.0-sources.jar";
        ArtifactReference artifact = parser.parse(path);
        assertNotNull(artifact);
        assertEquals("sources", artifact.getClassifier());
    }

    @Test
    void testInvalidVersionFormat() {
        String path = "com/example/artifact/1.0/artifact-1.0.jar";
        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            parser.parse(path);
        });
