public class ExternalParser extends AbstractParser {
    private String command;
    private List<String> supportedMediaTypes;
    private String metadataPattern;
    private LineConsumer lineConsumer;

    public ExternalParser() {
        this.supportedMediaTypes = new ArrayList<>();
    }

    public void setCommand(String command) {
        this.command = command;
    }

    public String getCommand() {
        return command;
    }

    public void addSupportedMediaType(String mediaType) {
        this.supportedMediaTypes.add(mediaType);
    }

    public List<String> getSupportedMediaTypes() {
        return supportedMediaTypes;
    }

    public void setMetadataPattern(String pattern) {
        this.metadataPattern = pattern;
    }

    public String getMetadataPattern() {
        return metadataPattern;
    }

    public void setLineConsumer(LineConsumer consumer) {
        this.lineConsumer = consumer;
    }

    public void execute(InputStream input) throws IOException {
        ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
        Process process = processBuilder.start();

        try (OutputStream outputStream = process.getOutputStream();
             BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
             BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

            // Send input to the process
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = input.read(buffer)) != -1) {
                outputStream.write(buffer, 0, bytesRead);
            }
            outputStream.close();

            // Handle output
            String line;
            while ((line = reader.readLine()) != null) {
                if (lineConsumer != null) {
                    lineConsumer.consume(line);
                }
            }

            // Handle errors
            while ((line = errorReader.readLine()) != null) {
                System.err.println(line);
            }

        } finally {
            process.waitFor();
            process.destroy();
        }
    }
}

public class Pair<K, V> implements IndexedRecord, Comparable<Pair<K, V>>, SchemaConstructable {
    private K key;
    private V value;
    private static Schema pairSchema;

    public Pair(K key, V value) {
        this.key = key;
        this.value = value;
    }

    public static void validateSchema(Schema schema) {
        if (!schema.isPairSchema()) {
            throw new IllegalArgumentException("Provided schema is not a pair schema.");
        }
    }

    public static Schema getPairSchema() {
        if (pairSchema == null) {
            pairSchema = Schema.createPairSchema();
        }
        return pairSchema;
    }

    public K getKey() {
        return key;
    }

    public void setKey(K key) {
        this.key = key;
    }

    public V getValue() {
        return value;
    }

    public void setValue(V value) {
        this.value = value;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Pair)) return false;
        Pair<?, ?> pair = (Pair<?, ?>) o;
        return Objects.equals(key, pair.key) && Objects.equals(value, pair.value);
    }

    @Override
    public int hashCode() {
        return Objects.hash(key, value);
    }

    @Override
    public int compareTo(Pair<K, V> other) {
        int keyComparison = compareKeys(this.key, other.key);
        if (keyComparison != 0) {
            return keyComparison;
        }
        return compareValues(this.value, other.value);
    }

    private int compareKeys(K key1, K key2) {
        // Assuming K implements Comparable
        return ((Comparable<K>) key1).compareTo(key2);
    }

    private int compareValues(V value1, V value2) {
        // Assuming V implements Comparable
        return ((Comparable<V>) value1).compareTo(value2);
    }

    @Override
    public void construct(Schema schema) {
        validateSchema(schema);
        // Additional construction logic can be added here
    }
}

