        Files.createFile(dir.resolve("subDir1/file1.txt"));
        Files.writeString(dir.resolve("subDir1/file1.txt"), "Content of file1");
    }

    private Path zipDirectory(Path sourceDir) throws IOException {
        Path zipFile = Files.createTempFile("testZip", ".zip");
        try (ZipOutputStream zos = new ZipOutputStream(new FileOutputStream(zipFile.toFile()))) {
            zipDirectoryRecursively(sourceDir, sourceDir, zos);
        }
        return zipFile;
    }

    private void zipDirectoryRecursively(Path sourceDir, Path currentDir, ZipOutputStream zos) throws IOException {
        Files.walk(currentDir).forEach(path -> {
            ZipEntry zipEntry = new ZipEntry(sourceDir.relativize(path).toString());
            try {
                if (Files.isDirectory(path)) {
                    zipEntry = new ZipEntry(zipEntry.getName() + "/");
                }
                zos.putNextEntry(zipEntry);
                if (!Files.isDirectory(path)) {
                    Files.copy(path, zos);
                }
                zos.closeEntry();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        });
    }

    private Path unzip(Path zipFile) throws IOException {
        Path outputDir = Files.createTempDirectory("unzipped");
        unzipToDirectory(zipFile, outputDir);
        return outputDir;
    }

    private void unzipToDirectory(Path zipFile, Path outputDir) throws IOException {
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile.toFile()))) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                Path newPath = outputDir.resolve(entry.getName());
                if (entry.isDirectory()) {
                    Files.createDirectories(newPath);
                } else {
                    Files.createDirectories(newPath.getParent());
                    try (OutputStream os = new FileOutputStream(newPath.toFile())) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            os.write(buffer, 0, len);
                        }
                    }
                }
                zis.closeEntry();
            }
        }
    }

    private boolean areDirectoriesEqual(Path dir1, Path dir2) throws IOException {
        // Implement directory comparison logic
        return true; // Placeholder
    }

    private void zipDirectoryToOutputStream(Path sourceDir, ByteArrayOutputStream outputStream) throws IOException {
        try (ZipOutputStream zos = new ZipOutputStream(outputStream)) {
            zipDirectoryRecursively(sourceDir, sourceDir, zos);
        }
    }

    private void createDirectoryWithFailure(Path dir) throws IOException {
        throw new IOException("Simulated directory creation failure");
    }
}

