final class SemanticPropUtil {

    private static final Pattern FIELD_PATTERN = Pattern.compile("^[a-zA-Z0-9_.]+$");

    private SemanticPropUtil() {
        // Prevent instantiation
    }

    public static void validateField(String field) {
        if (!FIELD_PATTERN.matcher(field).matches()) {
            throw new IllegalArgumentException("Invalid field: " + field);
        }
    }

    public static String createSingleInputSemanticProperty(String field) {
        validateField(field);
        return "SingleInput:" + field;
    }

    public static String createDualInputSemanticProperty(String field1, String field2) {
        validateField(field1);
        validateField(field2);
        return "DualInput:" + field1 + "," + field2;
    }

    public static String parseForwardedFields(String annotation) {
        // Assume annotation is a comma-separated list of fields
        String[] fields = annotation.split(",");
        StringBuilder result = new StringBuilder();
        for (String field : fields) {
            validateField(field.trim());
            result.append(field.trim()).append(";");
        }
        return result.toString();
    }

    public static String parseNonForwardedFields(String annotation) {
        // Assume annotation is a comma-separated list of fields
        String[] fields = annotation.split(",");
        StringBuilder result = new StringBuilder();
        for (String field : fields) {
            validateField(field.trim());
            result.append(field.trim()).append(";");
        }
        return result.toString();
    }

    public static String parseReadFields(String annotation) {
        // Assume annotation is a comma-separated list of fields
        String[] fields = annotation.split(",");
        StringBuilder result = new StringBuilder();
        for (String field : fields) {
            validateField(field.trim());
            result.append(field.trim()).append(";");
        }
        return result.toString();
    }
}

public abstract class PersistentDescriptorFactory {
    protected ClassDescriptorMap classDescriptorMap;
    protected Map<String, PersistentDescriptor> descriptorCache = new HashMap<>();

    public PersistentDescriptorFactory(ClassDescriptorMap classDescriptorMap) {
        this.classDescriptorMap = classDescriptorMap;
    }

    public PersistentDescriptor getDescriptor(String entityName) {
        if (descriptorCache.containsKey(entityName)) {
            return descriptorCache.get(entityName);
        }
        PersistentDescriptor descriptor = createDescriptor(entityName);
        if (descriptor == null) {
            throw new IllegalArgumentException("Entity not mapped: " + entityName);
        }
        descriptorCache.put(entityName, descriptor);
        return descriptor;
    }

    protected abstract PersistentDescriptor createDescriptor(String entityName);

    protected void validateEntityMapping(String entityName) {
        if (!classDescriptorMap.contains(entityName)) {
            throw new IllegalArgumentException("Entity not mapped: " + entityName);
        }
    }

    protected List<PropertyDescriptor> createProperties(EntityDescriptor entityDescriptor) {
        List<PropertyDescriptor> properties = new ArrayList<>();
        for (AttributeDescriptor attribute : entityDescriptor.getAttributes()) {
            properties.add(createProperty(attribute));
        }
        properties.sort(Comparator.comparing(PropertyDescriptor::getName));
        return properties;
    }

    protected PropertyDescriptor createProperty(AttributeDescriptor attribute) {
        // Logic to create property descriptor
        return new PropertyDescriptor(attribute.getName(), attribute.getType());
    }

    protected void handleEntityInheritance(PersistentDescriptor descriptor) {
        // Logic to handle inheritance
    }

    protected void indexSubclassDescriptors(PersistentDescriptor descriptor) {
        // Logic to index subclass descriptors
    }

    protected void manageRootEntities(PersistentDescriptor descriptor) {
        // Logic to manage root entities
    }

    protected void manageAdditionalEntities(PersistentDescriptor descriptor) {
        // Logic to manage additional entities
    }

    protected void enforceCollectionConstraints(Collection<?> collection) {
        if (!(collection instanceof List) && !(collection instanceof Set)) {
            throw new UnsupportedOperationException("Unsupported collection type: " + collection.getClass().getName());
        }
    }
}

