public class VersionRange {
    private String recommendedVersion;
    private List<VersionRestriction> restrictions;

    public VersionRange(String recommendedVersion) {
        this.recommendedVersion = recommendedVersion;
        this.restrictions = new ArrayList<>();
    }

    public void addRestriction(String versionSpec) {
        restrictions.add(new VersionRestriction(versionSpec));
    }

    public VersionRange clone() {
        VersionRange cloned = new VersionRange(this.recommendedVersion);
        cloned.restrictions = new ArrayList<>(this.restrictions);
        return cloned;
    }

    public void restrict(VersionRange other) {
        this.restrictions.retainAll(other.restrictions);
    }

    public boolean contains(String version) {
        for (VersionRestriction restriction : restrictions) {
            if (restriction.isInRange(version)) {
                return true;
            }
        }
        return false;
    }

    public String getRecommendedVersion() {
        return recommendedVersion;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof VersionRange)) return false;
        VersionRange that = (VersionRange) o;
        return Objects.equals(recommendedVersion, that.recommendedVersion) &&
                Objects.equals(restrictions, that.restrictions);
    }

    @Override
    public int hashCode() {
        return Objects.hash(recommendedVersion, restrictions);
    }

    @Override
    public String toString() {
        return "VersionRange{" +
                "recommendedVersion='" + recommendedVersion + '\'' +
                ", restrictions=" + restrictions +
                '}';
    }

    private static class VersionRestriction {
        private String minVersion;
        private String maxVersion;
        private boolean inclusiveMin;
        private boolean inclusiveMax;

        public VersionRestriction(String versionSpec) {
            parseVersionSpec(versionSpec);
        }

        private void parseVersionSpec(String versionSpec) {
            Pattern pattern = Pattern.compile("(<=|<|>=|>)(\\d+\\.\\d+\\.\\d+)");
            Matcher matcher = pattern.matcher(versionSpec);
            if (matcher.find()) {
                String operator = matcher.group(1);
                String version = matcher.group(2);
                if (operator.equals("<=")) {
                    this.maxVersion = version;
                    this.inclusiveMax = true;
                } else if (operator.equals("<")) {
                    this.maxVersion = version;
                    this.inclusiveMax = false;
                } else if (operator.equals(">=")) {
                    this.minVersion = version;
                    this.inclusiveMin = true;
                } else if (operator.equals(">")) {
                    this.minVersion = version;
                    this.inclusiveMin = false;
                }
            }
        }

        public boolean isInRange(String version) {
            boolean minCheck = (minVersion == null || compareVersions(version, minVersion) > 0 || 
                                (inclusiveMin && compareVersions(version, minVersion) == 0));
            boolean maxCheck = (maxVersion == null || compareVersions(version, maxVersion) < 0 || 
                                (inclusiveMax && compareVersions(version, maxVersion) == 0));
            return minCheck && maxCheck;
        }

        private int compareVersions(String version1, String version2) {
            String[] v1Parts = version1.split("\\.");
            String[] v2Parts = version2.split("\\.");
            for (int i = 0; i < Math.max(v1Parts.length, v2Parts.length); i++) {
                int v1 = i < v1Parts.length ? Integer.parseInt(v1Parts[i]) : 0;
                int v2 = i < v2Parts.length ? Integer.parseInt(v2Parts[i]) : 0;
                if (v1 != v2) {
                    return Integer.compare(v1, v2);
                }
            }
            return 0;
        }

        @Override
        public String toString() {
            return (inclusiveMin ? ">=" : ">") + (minVersion != null ? minVersion : "") +
                   " and " + (inclusiveMax ? "<=" : "<") + (maxVersion != null ? maxVersion : "");
        }
    }
}

public abstract class BaseDataStreamMarshaller implements DataStreamMarshaller {

    protected abstract void tightMarshal(Object o, DataOutput dataOutput) throws IOException;

    protected abstract Object tightUnmarshal(DataInput dataInput) throws IOException;

    protected abstract void looseMarshal(Object o, DataOutput dataOutput) throws IOException;

    protected abstract Object looseUnmarshal(DataInput dataInput) throws IOException;

    protected void marshalException(Throwable exception, DataOutput dataOutput) throws IOException {
        dataOutput.writeUTF(exception.getClass().getName());
        dataOutput.writeUTF(exception.getMessage());
        StackTraceElement[] stackTrace = exception.getStackTrace();
        dataOutput.writeInt(stackTrace.length);
        for (StackTraceElement element : stackTrace) {
            dataOutput.writeUTF(element.toString());
        }
    }

    protected Throwable unmarshalException(DataInput dataInput) throws IOException {
        String className = dataInput.readUTF();
        String message = dataInput.readUTF();
        int stackTraceLength = dataInput.readInt();
        StackTraceElement[] stackTrace = new StackTraceElement[stackTraceLength];
        for (int i = 0; i < stackTraceLength; i++) {
            stackTrace[i] = createStackTraceElement(dataInput.readUTF());
        }
        Throwable exception = new Exception(message);
        exception.setStackTrace(stackTrace);
        return exception;
    }

    private StackTraceElement createStackTraceElement(String element) {
        // This method could be improved to parse the string into a StackTraceElement
        return new StackTraceElement(element, "", "", -1);
    }

    protected void marshalString(String str, DataOutput dataOutput) throws IOException {
        dataOutput.writeUTF(str);
    }

    protected String unmarshalString(DataInput dataInput) throws IOException {
        return dataInput.readUTF();
    }

    protected void marshalByteArray(byte[] array, DataOutput dataOutput) throws IOException {
        dataOutput.writeInt(array.length);
        dataOutput.write(array);
    }

    protected byte[] unmarshalByteArray(DataInput dataInput) throws IOException {
        int length = dataInput.readInt();
        byte[] array = new byte[length];
        dataInput.readFully(array);
        return array;
    }

    // Additional methods for handling other data types can be added here
}

public class IniFilterChainResolverFactory extends IniFactorySupport {
    private static final Logger logger = LoggerFactory.getLogger(IniFilterChainResolverFactory.class);
    private FilterChainManager filterChainManager;

    public IniFilterChainResolverFactory() {
        this.filterChainManager = new DefaultFilterChainManager();
    }

    public void createFilterChains(Ini ini) {
        Section section = ini.getSection("urls");
        if (section == null) {
            logger.warn("No 'urls' section found in INI file.");
            return;
        }

        for (String url : section.keySet()) {
            String filterChain = section.get(url);
            registerFilterChain(url, filterChain);
        }

        checkForDeprecatedSections(ini);
    }

    private void registerFilterChain(String url, String filterChain) {
        if (filterChain == null || filterChain.isEmpty()) {
            logger.warn("Filter chain for URL '{}' is empty or null.", url);
            return;
        }
        filterChainManager.createChain(url, filterChain);
    }

    private void checkForDeprecatedSections(Ini ini) {
        if (ini.containsKey("deprecatedSection")) {
            logger.warn("The 'deprecatedSection' is deprecated and should be removed.");
        }
    }

    public FilterChainManager getFilterChainManager() {
        return filterChainManager;
    }
}

public class PathNode {
    private String key;
    private String criteria;

    public static final PathNode NULL = new PathNode("", "");

    public PathNode(String key, String criteria) {
        this.key = key;
        this.criteria = criteria;
    }

    public static PathNode parse(String path) {
        String[] parts = path.split("\\.");
        if (parts.length == 0) {
            return NULL;
        }
        String key = parts[0];
        String criteria = parts.length > 1 ? parts[1] : "";
        return new PathNode(key, criteria);
    }

    public boolean matches(JSONObject json) {
        if (!json.has(key)) {
            return false;
        }
        Object value = json.get(key);
        return value.toString().equals(criteria);
    }

    public String getKey() {
        return key;
    }

    public String getCriteria() {
        return criteria;
    }

    public boolean hasCriteria() {
        return !criteria.isEmpty();
    }

    @Override
    public int hashCode() {
        return key.hashCode() + criteria.hashCode();
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof PathNode)) return false;
        PathNode other = (PathNode) obj;
        return key.equals(other.key) && criteria.equals(other.criteria);
    }

    @Override
    public String toString() {
        return "PathNode{" +
                "key='" + key + '\'' +
                ", criteria='" + criteria + '\'' +
                '}';
    }
}

public class FetcherThread extends Thread {
    private final BlockingQueue<String> urlQueue;
    private final Pattern urlFilter;
    private final AtomicInteger errorCount;
    private final int maxRetries;
    private final long crawlDelay;
    private final String userAgent;

    public FetcherThread(BlockingQueue<String> urlQueue, Pattern urlFilter, int maxRetries, long crawlDelay, String userAgent) {
        this.urlQueue = urlQueue;
        this.urlFilter = urlFilter;
        this.errorCount = new AtomicInteger(0);
        this.maxRetries = maxRetries;
        this.crawlDelay = crawlDelay;
        this.userAgent = userAgent;
    }

    @Override
    public void run() {
        while (true) {
            try {
                String urlToFetch = urlQueue.take();
                if (!urlFilter.matcher(urlToFetch).matches()) {
                    continue;
                }
                fetchUrl(urlToFetch);
                Thread.sleep(crawlDelay);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    private void fetchUrl(String urlString) {
        int attempts = 0;
        while (attempts < maxRetries) {
            try {
                URL url = new URL(urlString);
