                    urlString = connection.getHeaderField("Location");
                } else {
                    errorCount.incrementAndGet();
                }
            } catch (IOException e) {
                errorCount.incrementAndGet();
            }
            attempts++;
        }
    }

    private void processResponse(HttpURLConnection connection) throws IOException {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            StringBuilder content = new StringBuilder();
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            // Store content or publish event here
            System.out.println("Fetched content: " + content.toString());
        }
    }

