        return new Property<>(name + " IN (" + String.join(", ", values.toString()) + ")");
    }

    public Property<E> mapValue(Map<String, E> map, String key) {
        return new Property<>(map.get(key) != null ? map.get(key).toString() : null);
    }

    public E getValueFromBean(Object bean) {
        try {
            return (E) bean.getClass().getMethod("get" + capitalize(name)).invoke(bean);
        } catch (Exception e) {
            throw new RuntimeException("Error retrieving property value", e);
        }
    }

    public void setValueToBean(Object bean, E value) {
        try {
            bean.getClass().getMethod("set" + capitalize(name), value.getClass()).invoke(bean, value);
        } catch (Exception e) {
            throw new RuntimeException("Error setting property value", e);
        }
    }

    private String capitalize(String str) {
        if (str == null || str.isEmpty()) {
            return str;
        }
        return str.substring(0, 1).toUpperCase() + str.substring(1);
    }

    @Override
    public String toString() {
        return name;
    }
