    public void customizeDocumentCommand(IDocument document, DocumentCommand command) {
        super.customizeDocumentCommand(document, command);
        handleSmartPaste(document, command);
        handleAutoClosing(document, command);
    }

    private void handleSmartPaste(IDocument document, DocumentCommand command) {
        if (command.text.startsWith(" ")) {
            command.text = command.text.trim();
        }
    }

    private void handleAutoClosing(IDocument document, DocumentCommand command) {
        if (command.text.equals("(")) {
            command.text += ")";
        } else if (command.text.equals("\"")) {
            command.text += "\"";
        }
    }

    @Override
    protected int calculateIndentation(IDocument document, int line) {
        try {
            String lineContent = document.get(line);
            return calculateIndentationBasedOnContent(lineContent);
        } catch (BadLocationException e) {
            return 0;
        }
    }

    private int calculateIndentationBasedOnContent(String lineContent) {
        // Code smell: This method could be more modular
        if (lineContent.trim().isEmpty()) {
            return 0;
        }
        return lineContent.indexOf(lineContent.trim());
    }

    public void reIndentLines(IDocument document, int startLine, int endLine) {
        for (int i = startLine; i <= endLine; i++) {
            try {
                int indentation = calculateIndentation(document, i);
                document.replace(document.getLineOffset(i), 0, " ".repeat(indentation));
            } catch (BadLocationException e) {
                // Code smell: Swallowing exceptions without handling
            }
        }
    }

