public class HSLFExtractor extends AbstractPOIFSExtractor {
    private HSLFSlideShow slideShow;

    public HSLFExtractor(File file) throws IOException {
        super(new POIFSFileSystem(new FileInputStream(file)));
        this.slideShow = new HSLFSlideShow(new POIFSFileSystem(new FileInputStream(file)));
    }

    public String extract() {
        StringBuilder xhtml = new StringBuilder();
        xhtml.append("<html><body>");

        for (HSLFSlide slide : slideShow.getSlides()) {
            xhtml.append("<div class='slide'>");
            extractSlideContent(slide, xhtml);
            xhtml.append("</div>");
        }

        xhtml.append("</body></html>");
        return xhtml.toString();
    }

    private void extractSlideContent(HSLFSlide slide, StringBuilder xhtml) {
        for (HSLFShape shape : slide.getShapes()) {
            if (shape instanceof HSLFTextShape) {
                xhtml.append("<p>").append(((HSLFTextShape) shape).getText()).append("</p>");
            } else if (shape instanceof HSLFTable) {
                extractTable((HSLFTable) shape, xhtml);
            } else if (shape instanceof HSLFPictureData) {
                xhtml.append("<img src='").append(((HSLFPictureData) shape).getPackagePart().getPartName()).append("'/>");
            }
        }
        extractNotes(slide.getNotes(), xhtml);
    }

    private void extractTable(HSLFTable table, StringBuilder xhtml) {
        xhtml.append("<table>");
        for (int i = 0; i < table.getRowCount(); i++) {
            xhtml.append("<tr>");
            for (int j = 0; j < table.getColumnCount(); j++) {
                xhtml.append("<td>").append(table.getCell(i, j).getText()).append("</td>");
            }
            xhtml.append("</tr>");
        }
        xhtml.append("</table>");
    }

    private void extractNotes(HSLFNotes notes, StringBuilder xhtml) {
        if (notes != null) {
            xhtml.append("<div class='notes'>").append(notes.getText()).append("</div>");
        }
    }

    @Override
    public void close() throws IOException {
        super.close();
        slideShow.close();
    }
}

