public class XSDFuncOp {

    public static NodeValue add(NodeValue a, NodeValue b) {
        if (!isNumeric(a) || !isNumeric(b)) {
            throw new IllegalArgumentException("Both arguments must be numeric.");
        }
        return new NodeValue(a.getNumericValue() + b.getNumericValue());
    }

    public static NodeValue subtract(NodeValue a, NodeValue b) {
        if (!isNumeric(a) || !isNumeric(b)) {
            throw new IllegalArgumentException("Both arguments must be numeric.");
        }
        return new NodeValue(a.getNumericValue() - b.getNumericValue());
    }

    public static NodeValue multiply(NodeValue a, NodeValue b) {
        if (!isNumeric(a) || !isNumeric(b)) {
            throw new IllegalArgumentException("Both arguments must be numeric.");
        }
        return new NodeValue(a.getNumericValue() * b.getNumericValue());
    }

    public static NodeValue divide(NodeValue a, NodeValue b) {
        if (!isNumeric(a) || !isNumeric(b)) {
            throw new IllegalArgumentException("Both arguments must be numeric.");
        }
        if (b.getNumericValue() == 0) {
            throw new ArithmeticException("Division by zero.");
        }
        return new NodeValue(a.getNumericValue() / b.getNumericValue());
    }

    public static NodeValue substring(NodeValue str, int start, int length) {
        if (!isString(str)) {
            throw new IllegalArgumentException("Argument must be a string.");
        }
        String result = str.getStringValue().substring(start, start + length);
        return new NodeValue(result);
    }

    public static NodeValue concatenate(NodeValue a, NodeValue b) {
        if (!isString(a) || !isString(b)) {
            throw new IllegalArgumentException("Both arguments must be strings.");
        }
        return new NodeValue(a.getStringValue() + b.getStringValue());
    }

    public static NodeValue replace(NodeValue str, String target, String replacement) {
        if (!isString(str)) {
            throw new IllegalArgumentException("Argument must be a string.");
        }
        String result = str.getStringValue().replace(target, replacement);
        return new NodeValue(result);
    }

    public static int getYear(NodeValue date) {
        if (!isDate(date)) {
            throw new IllegalArgumentException("Argument must be a date.");
        }
        return date.getDateValue().getYear();
    }

    public static int getMonth(NodeValue date) {
        if (!isDate(date)) {
            throw new IllegalArgumentException("Argument must be a date.");
        }
        return date.getDateValue().getMonth();
    }

    public static int getDay(NodeValue date) {
        if (!isDate(date)) {
            throw new IllegalArgumentException("Argument must be a date.");
        }
        return date.getDateValue().getDay();
    }

    public static String formatNumber(NodeValue number) {
        if (!isNumeric(number)) {
            throw new IllegalArgumentException("Argument must be numeric.");
        }
        return String.format("%.2f", number.getNumericValue());
    }

    private static boolean isNumeric(NodeValue value) {
        return value.isInteger() || value.isDecimal() || value.isFloat() || value.isDouble();
    }

    private static boolean isString(NodeValue value) {
        return value.isString();
    }

    private static boolean isDate(NodeValue value) {
        return value.isDate();
    }
}

