class Roundtrip {

    public InteractionDto newInteractionDtoWithActionInvocation(String transactionId, int sequence, String targetBookmark, String actionId, String user) {
        InteractionDto interactionDto = new InteractionDto();
        interactionDto.setTransactionId(transactionId);
        interactionDto.setSequence(sequence);
        interactionDto.setTargetBookmark(targetBookmark);
        interactionDto.setActionId(actionId);
        interactionDto.setUser(user);
        return interactionDto;
    }

    public void happyCase() throws JAXBException {
        InteractionDto dto = newInteractionDtoWithActionInvocation("txn123", 1, "bookmark1", "action1", "user1");
        Map<String, Object> parameters = new HashMap<>();
        parameters.put("paramString", "value");
        parameters.put("paramInteger", 123);
        parameters.put("paramBoolean", true);
        dto.setParameters(parameters);

        String xml = serializeToXml(dto);
        InteractionDto deserializedDto = deserializeFromXml(xml);

        assert dto.getTransactionId().equals(deserializedDto.getTransactionId());
        assert dto.getSequence() == deserializedDto.getSequence();
        assert dto.getTargetBookmark().equals(deserializedDto.getTargetBookmark());
        assert dto.getActionId().equals(deserializedDto.getActionId());
        assert dto.getUser().equals(deserializedDto.getUser());
        assert dto.getParameters().equals(deserializedDto.getParameters());
    }

    private String serializeToXml(InteractionDto dto) throws JAXBException {
        JAXBContext context = JAXBContext.newInstance(InteractionDto.class);
        Marshaller marshaller = context.createMarshaller();
        StringWriter writer = new StringWriter();
        marshaller.marshal(dto, writer);
        return writer.toString();
    }

    private InteractionDto deserializeFromXml(String xml) throws JAXBException {
        JAXBContext context = JAXBContext.newInstance(InteractionDto.class);
        Unmarshaller unmarshaller = context.createUnmarshaller();
        return (InteractionDto) unmarshaller.unmarshal(new StringReader(xml));
    }
}

