public class ASMifier extends Printer {
    private String className;

    public ASMifier() {
        super(Opcodes.ASM9);
    }

    public void generate(String className) throws IOException {
        this.className = className;
        ClassReader classReader = new ClassReader(className);
        classReader.accept(new ClassVisitor(Opcodes.ASM9) {
            @Override
            public void visit(int version, int access, String name, String signature, String superName, String[] interfaces) {
                printClassHeader(name, access, superName, interfaces);
            }

            @Override
            public void visitField(int access, String name, String descriptor, String signature, Object value) {
                printField(name, access, descriptor);
            }

            @Override
            public MethodVisitor visitMethod(int access, String name, String descriptor, String signature, String[] exceptions) {
                return new MethodVisitor(Opcodes.ASM9) {
                    @Override
                    public void visitCode() {
                        printMethodHeader(name, access, descriptor);
                    }

                    @Override
                    public void visitInsn(int opcode) {
                        printInstruction(opcode);
                    }

                    @Override
                    public void visitEnd() {
                        printMethodEnd();
                    }
                };
            }

            @Override
            public void visitEnd() {
                printClassEnd();
            }
        }, 0);
    }

    private void printClassHeader(String name, int access, String superName, String[] interfaces) {
        // Code to print class header
    }

    private void printField(String name, int access, String descriptor) {
        // Code to print field
    }

    private void printMethodHeader(String name, int access, String descriptor) {
        // Code to print method header
    }

    private void printInstruction(int opcode) {
