    }

    public static Expression property(String propertyName) {
        // Code smell: Lack of validation for propertyName
        return new PropertyExpression(propertyName);
    }

    public static Expression body() {
        return new BodyExpression();
    }

    public static Expression concat(Expression... expressions) {
        // Code smell: Varargs can lead to performance issues if too many expressions are passed
        return new ConcatExpression(expressions);
    }

    public static Expression tokenize(String input, String delimiter) {
        // Code smell: No check for null or empty input
        return new TokenizeExpression(input, delimiter);
    }

