public class InetAddressValidatorTest extends TestCase {

    public void testValidIPv4Addresses() {
        assertTrue(InetAddressValidator.isValid("192.168.1.1"));
        assertTrue(InetAddressValidator.isValid("255.255.255.255"));
        assertTrue(InetAddressValidator.isValid("0.0.0.0"));
        assertTrue(InetAddressValidator.isValid("127.0.0.1"));
    }

    public void testInvalidIPv4Addresses() {
        assertFalse(InetAddressValidator.isValid("256.256.256.256"));
        assertFalse(InetAddressValidator.isValid("192.168.1.256"));
        assertFalse(InetAddressValidator.isValid("192.168.01.1"));
        assertFalse(InetAddressValidator.isValid("192.168.1"));
        assertFalse(InetAddressValidator.isValid("192.168.1.1.1"));
        assertFalse(InetAddressValidator.isValid("abc.def.ghi.jkl"));
    }

    public void testReservedIPv4Addresses() {
        assertTrue(InetAddressValidator.isValid("localhost"));
        assertTrue(InetAddressValidator.isValid("127.0.0.1"));
        assertTrue(InetAddressValidator.isValid("255.255.255.255")); // Broadcast
    }

    public void testValidIPv6Addresses() {
        assertTrue(InetAddressValidator.isValidInet6Address("2001:0db8:85a3:0000:0000:8a2e:0370:7334"));
        assertTrue(InetAddressValidator.isValidInet6Address("::1"));
        assertTrue(InetAddressValidator.isValidInet6Address("2001:db8::ff00:42:8329"));
        assertTrue(InetAddressValidator.isValidInet6Address("::"));
    }

    public void testInvalidIPv6Addresses() {
        assertFalse(InetAddressValidator.isValidInet6Address("2001:db8:85a3:0:0:8a2e:0370:7334:1234"));
        assertFalse(InetAddressValidator.isValidInet6Address("2001:db8::g:1"));
        assertFalse(InetAddressValidator.isValidInet6Address("2001:db8:::1"));
        assertFalse(InetAddressValidator.isValidInet6Address("::1:2:3:4:5:6:7:8"));
    }

    public void testEdgeCases() {
        assertFalse(InetAddressValidator.isValid("192.168.1.01")); // Leading zero
        assertFalse(InetAddressValidator.isValid("192.168.1.-1")); // Negative number
        assertFalse(InetAddressValidator.isValid("192.168.1.1.1")); // Too many groups
        assertFalse(InetAddressValidator.isValidInet6Address("::g")); // Invalid character
    }
}

