        assertEquals("B", chunkList.get(1));
    }

    @Test
    void testRemove() {
        chunkList.add("A");
        chunkList.add("B");
        assertEquals("A", chunkList.remove(0));
        assertEquals(1, chunkList.size());
        assertEquals("B", chunkList.get(0));
    }

    @Test
    void testRemoveOutOfBounds() {
        assertThrows(IndexOutOfBoundsException.class, () -> chunkList.remove(0));
    }

    @Test
    void testGetOutOfBounds() {
        assertThrows(IndexOutOfBoundsException.class, () -> chunkList.get(0));
    }

    @Test
    void testClear() {
        chunkList.add("A");
        chunkList.add("B");
        chunkList.clear();
        assertEquals(0, chunkList.size());
    }

    @Test
    void testAddNull() {
        chunkList.add(null);
        assertEquals(1, chunkList.size());
        assertNull(chunkList.get(0));
    }

    @Test
    void testIterator() {
        chunkList.add("A");
        chunkList.add("B");
        Iterator<String> iterator = chunkList.iterator();
        assertTrue(iterator.hasNext());
        assertEquals("A", iterator.next());
        assertTrue(iterator.hasNext());
        assertEquals("B", iterator.next());
        assertFalse(iterator.hasNext());
    }

    @Test
    void testIteratorRemove() {
        chunkList.add("A");
        chunkList.add("B");
        Iterator<String> iterator = chunkList.iterator();
        iterator.next();
        iterator.remove();
        assertEquals(1, chunkList.size());
        assertEquals("B", chunkList.get(0));
    }

    @Test
    void testIteratorRemoveWithoutNext() {
        Iterator<String> iterator = chunkList.iterator();
        assertThrows(IllegalStateException.class, iterator::remove);
    }

    @Test
    void testRandomConditions() {
