        chunkList.add("B");
        Iterator<String> iterator = chunkList.iterator();
        chunkList.add("C");
        assertThrows(IllegalStateException.class, iterator::next);
    }
}

public class EnglishStemmer extends AbstractSnowballStemmer {
    private static final String[] suffixes = { "ed", "ing", "ly", "s", "es", "er", "est", "ness", "ment", "tion", "ity", "ful", "able", "ible" };
    private static final String[] irregulars = { "went", "gone", "being", "been" };

    public EnglishStemmer() {
        super();
    }

    @Override
    public String stem(String word) {
        if (isIrregular(word)) {
            return handleIrregular(word);
        }
        word = applySuffixRules(word);
        return word;
    }

    private boolean isIrregular(String word) {
        for (String irregular : irregulars) {
            if (word.equals(irregular)) {
                return true;
            }
        }
        return false;
    }

    private String handleIrregular(String word) {
        switch (word) {
            case "went":
                return "go";
            case "gone":
                return "go";
            case "being":
                return "be";
            case "been":
                return "be";
            default:
                return word;
        }
    }

    private String applySuffixRules(String word) {
        for (String suffix : suffixes) {
            if (word.endsWith(suffix)) {
                return word.substring(0, word.length() - suffix.length());
            }
        }
        return word;
    }
}

