public class SimpleRegression implements Serializable {
    private static final long serialVersionUID = 1L;

    private List<Double> xData;
    private List<Double> yData;
    private boolean includeIntercept;
    private double slope;
    private double intercept;
    private double rSquared;
    private double meanSquareError;

    public SimpleRegression() {
        this(true);
    }

    public SimpleRegression(boolean includeIntercept) {
        this.includeIntercept = includeIntercept;
        this.xData = new ArrayList<>();
        this.yData = new ArrayList<>();
    }

    public void addDataPoint(double x, double y) {
        xData.add(x);
        yData.add(y);
        calculateRegressionParameters();
    }

    public void addDataPoints(double[] x, double[] y) {
        if (x.length != y.length) {
            throw new IllegalArgumentException("X and Y arrays must have the same length.");
        }
        for (int i = 0; i < x.length; i++) {
            addDataPoint(x[i], y[i]);
        }
    }

    public void clearData() {
        xData.clear();
        yData.clear();
    }

    public void append(SimpleRegression other) {
        this.xData.addAll(other.xData);
        this.yData.addAll(other.yData);
        calculateRegressionParameters();
    }

    public double predict(double x) {
        return includeIntercept ? intercept + slope * x : slope * x;
    }

    public double getSlope() {
        return slope;
    }

    public double getIntercept() {
        return intercept;
    }

    public double getRSquared() {
        return rSquared;
    }

    public double getMeanSquareError() {
        return meanSquareError;
    }

    private void calculateRegressionParameters() {
        int n = xData.size();
        if (n < 2) {
            slope = intercept = rSquared = meanSquareError = Double.NaN;
            return;
        }

        double sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
        for (int i = 0; i < n; i++) {
            double x = xData.get(i);
            double y = yData.get(i);
            sumX += x;
            sumY += y;
            sumXY += x * y;
            sumX2 += x * x;
        }

        if (includeIntercept) {
            double meanX = sumX / n;
            double meanY = sumY / n;
            slope = (sumXY - n * meanX * meanY) / (sumX2 - n * meanX * meanX);
            intercept = meanY - slope * meanX;
        } else {
            slope = sumXY / sumX2;
            intercept = 0;
        }

        double totalSumOfSquares = 0;
        double residualSumOfSquares = 0;
        for (int i = 0; i < n; i++) {
            double y = yData.get(i);
            double predictedY = predict(xData.get(i));
            totalSumOfSquares += Math.pow(y - (sumY / n), 2);
            residualSumOfSquares += Math.pow(y - predictedY, 2);
        }

        rSquared = 1 - (residualSumOfSquares / totalSumOfSquares);
        meanSquareError = residualSumOfSquares / n;
    }
}

public class ScriptParser {
    private final Map<String, Command> commands = new HashMap<>();
    private final Map<String, Object> context = new HashMap<>();

    public interface Command {
        void execute(String[] args);
    }

    public void addCommand(String name, Command command) {
        commands.put(name, command);
    }

    public void parse(String script) {
        String[] lines = script.split("\n");
        for (String line : lines) {
            line = line.trim();
            if (line.isEmpty() || line.startsWith("//")) {
                continue; // Skip empty lines and comments
            }
            try {
                executeCommand(line);
            } catch (Exception e) {
                System.err.println("Error executing line: " + line + " - " + e.getMessage());
            }
        }
    }

    private void executeCommand(String line) {
        String[] parts = line.split("\\s+");
        String commandName = parts[0];
        Command command = commands.get(commandName);
        if (command != null) {
            command.execute(Arrays.copyOfRange(parts, 1, parts.length));
        } else {
            throw new IllegalArgumentException("Unknown command: " + commandName);
        }
    }

    public void setVariable(String name, Object value) {
        context.put(name, value);
    }

    public Object getVariable(String name) {
        return context.get(name);
    }

    public static String httpResponseToString(HttpResponse response) {
        // Convert HTTP response to string (implementation depends on HttpResponse class)
        return response.toString();
    }

    public static void main(String[] args) {
        ScriptParser parser = new ScriptParser();
        parser.addCommand("print", args1 -> {
            for (String arg : args1) {
                System.out.print(arg + " ");
            }
            System.out.println();
        });
        parser.addCommand("set", args1 -> {
            if (args1.length != 2) {
                throw new IllegalArgumentException("set command requires 2 arguments");
            }
            parser.setVariable(args1[0], args1[1]);
        });
        parser.addCommand("get", args1 -> {
            if (args1.length != 1) {
                throw new IllegalArgumentException("get command requires 1 argument");
            }
            System.out.println(parser.getVariable(args1[0]));
        });

        if (args.length > 0) {
            try (BufferedReader reader = new BufferedReader(new FileReader(args[0]))) {
                StringBuilder script = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    script.append(line).append("\n");
                }
                parser.parse(script.toString());
            } catch (IOException e) {
                System.err.println("Error reading script file: " + e.getMessage());
            }
        } else {
            System.out.println("Please provide a script file as an argument.");
        }
    }
}

