public class DebugTabUri implements DebugTab {
    private UriInfo uriInfo;

    public DebugTabUri(UriInfo uriInfo) {
        this.uriInfo = uriInfo;
    }

    @Override
    public void appendJson(JsonGenerator jsonGenerator) {
        jsonGenerator.writeStartObject();
        jsonGenerator.write("kind", getKind());
        jsonGenerator.write("resourceParts", getResourceParts());
        jsonGenerator.write("queryOptions", getQueryOptions());
        jsonGenerator.writeEnd();
    }

    private String getKind() {
        // Logic to determine the kind of URI
        return uriInfo.getPath();
    }

    private String getResourceParts() {
        // Logic to extract resource parts from the URI
        return String.join(", ", uriInfo.getPathSegments());
    }

    private String getQueryOptions() {
        // Logic to extract query options
        StringBuilder queryOptions = new StringBuilder();
        uriInfo.getQueryParameters().forEach((key, values) -> {
            queryOptions.append(key).append(": ").append(String.join(", ", values)).append("; ");
        });
        return queryOptions.toString();
    }

    public String generateHtml() {
        StringBuilder htmlBuilder = new StringBuilder();
        htmlBuilder.append("<div>");
        htmlBuilder.append("<h2>URI Debug Information</h2>");
        htmlBuilder.append("<p>Kind: ").append(getKind()).append("</p>");
        htmlBuilder.append("<p>Resource Parts: ").append(getResourceParts()).append("</p>");
        htmlBuilder.append("<p>Query Options: ").append(getQueryOptions()).append("</p>");
        htmlBuilder.append("</div>");
        return htmlBuilder.toString();
    }
}

