public class PredicateBuilder {

    public static Predicate<Exchange> isEqual(String field, Object value) {
        return exchange -> value.equals(exchange.getField(field));
    }

    public static Predicate<Exchange> isNotEqual(String field, Object value) {
        return exchange -> !value.equals(exchange.getField(field));
    }

    public static Predicate<Exchange> isGreaterThan(String field, Comparable<?> value) {
        return exchange -> ((Comparable<Object>) exchange.getField(field)).compareTo(value) > 0;
    }

    public static Predicate<Exchange> isLessThan(String field, Comparable<?> value) {
        return exchange -> ((Comparable<Object>) exchange.getField(field)).compareTo(value) < 0;
    }

    public static Predicate<Exchange> and(Predicate<Exchange>... predicates) {
        return exchange -> {
            for (Predicate<Exchange> predicate : predicates) {
                if (!predicate.test(exchange)) {
                    return false;
                }
            }
            return true;
        };
    }

    public static Predicate<Exchange> or(Predicate<Exchange>... predicates) {
        return exchange -> {
            for (Predicate<Exchange> predicate : predicates) {
                if (predicate.test(exchange)) {
                    return true;
                }
            }
            return false;
        };
    }

    public static Predicate<Exchange> not(Predicate<Exchange> predicate) {
        return exchange -> !predicate.test(exchange);
    }

    public static Predicate<Exchange> contains(String field, String value) {
