        ErrorTO errorTO = new ErrorTO();
        Response.Status status;

        if (exception instanceof AccessDeniedException) {
            status = Response.Status.FORBIDDEN;
            errorTO.setMessage("Access Denied");
        } else if (exception instanceof SyncopeClientException) {
            status = Response.Status.BAD_REQUEST;
            errorTO.setMessage("Client Error");
        } else if (exception instanceof EntityExistsException) {
            status = Response.Status.CONFLICT;
            errorTO.setMessage("Entity Already Exists");
        } else {
            status = Response.Status.INTERNAL_SERVER_ERROR;
            errorTO.setMessage("Internal Server Error");
        }

        logger.error("Exception occurred: {}", exception.getMessage(), exception);
        errorTO.setStatus(status.getStatusCode());
        errorTO.setErrorType(getClientExceptionType(exception));

        return Response.status(status)
                .entity(errorTO)
                .header("X-Error-Code", status.getStatusCode())
                .build();
    }

    private ClientExceptionType getClientExceptionType(Exception exception) {
