public class HiveJdbcCommon {

    public static final String MIME_TYPE_AVRO = "application/avro";
    public static final String MIME_TYPE_CSV = "text/csv";
    private static final String AVRO_NAME_NORMALIZATION_PROPERTY = "avro.name.normalization";

    public Schema createAvroSchema(ResultSet resultSet) throws SQLException {
        List<Schema.Field> fields = new ArrayList<>();
        int columnCount = resultSet.getMetaData().getColumnCount();
        for (int i = 1; i <= columnCount; i++) {
            String columnName = normalizeAvroName(resultSet.getMetaData().getColumnName(i));
            Schema.Type columnType = getAvroType(resultSet.getMetaData().getColumnType(i));
            fields.add(new Schema.Field(columnName, Schema.create(columnType), null, null));
        }
        return Schema.createRecord("Record", null, null, false, fields);
    }

    public List<GenericRecord> convertResultSetToAvro(ResultSet resultSet, Schema schema) throws SQLException {
        List<GenericRecord> records = new ArrayList<>();
        while (resultSet.next()) {
            GenericRecord record = new GenericData.Record(schema);
            for (Schema.Field field : schema.getFields()) {
                record.put(field.name(), resultSet.getObject(field.name()));
            }
            records.add(record);
        }
        return records;
    }

    public String convertResultSetToCSV(ResultSet resultSet, boolean includeHeader) throws SQLException {
        StringBuilder csvBuilder = new StringBuilder();
        if (includeHeader) {
            int columnCount = resultSet.getMetaData().getColumnCount();
            for (int i = 1; i <= columnCount; i++) {
                csvBuilder.append(resultSet.getMetaData().getColumnName(i)).append(",");
            }
            csvBuilder.setLength(csvBuilder.length() - 1); // Remove last comma
            csvBuilder.append("\n");
        }
        while (resultSet.next()) {
            int columnCount = resultSet.getMetaData().getColumnCount();
            for (int i = 1; i <= columnCount; i++) {
                csvBuilder.append(resultSet.getObject(i)).append(",");
            }
            csvBuilder.setLength(csvBuilder.length() - 1); // Remove last comma
            csvBuilder.append("\n");
        }
        return csvBuilder.toString();
    }

    private String normalizeAvroName(String name) {
        // Normalize name logic here
        return name.replaceAll("[^a-zA-Z0-9_]", "_");
    }

    private Schema.Type getAvroType(int sqlType) {
        switch (sqlType) {
            case java.sql.Types.INTEGER:
                return Schema.Type.INT;
            case java.sql.Types.BIGINT:
                return Schema.Type.LONG;
            case java.sql.Types.VARCHAR:
            case java.sql.Types.CHAR:
                return Schema.Type.STRING;
            case java.sql.Types.FLOAT:
                return Schema.Type.FLOAT;
            case java.sql.Types.DOUBLE:
                return Schema.Type.DOUBLE;
            case java.sql.Types.BOOLEAN:
                return Schema.Type.BOOLEAN;
            default:
                return Schema.Type.NULL; // Default to NULL for unsupported types
        }
    }

    public Properties loadHiveConfiguration(String configFilePath) throws IOException {
        Properties properties = new Properties();
        try (java.io.InputStream input = new java.io.FileInputStream(configFilePath)) {
            properties.load(input);
        }
        return properties;
    }
}

@Mojo(name = "generate-code", defaultPhase = LifecyclePhase.GENERATE_SOURCES)
public abstract class AbstractCodeGeneratorMojo extends AbstractMojo {

    @Parameter(defaultValue = "${project.build.directory}/generated-sources")
    protected File outputDirectory;

    @Parameter(defaultValue = "${project.build.directory}/marker")
    protected File markerFile;

    protected abstract void generateCode() throws MojoExecutionException;

    public void execute() throws MojoExecutionException, MojoFailureException {
        if (shouldRerun()) {
            try {
                generateCode();
                createMarkerFile();
            } catch (IOException e) {
                throw new MojoExecutionException("Error during code generation", e);
            }
        } else {
            getLog().info("Code generation is up to date.");
        }
    }

    protected boolean shouldRerun() {
        if (!markerFile.exists()) {
            return true;
        }
        long lastRunTime = markerFile.lastModified();
        return Files.walk(Paths.get(outputDirectory.getPath()))
                .filter(Files::isRegularFile)
                .anyMatch(path -> path.toFile().lastModified() > lastRunTime);
    }

    protected void createMarkerFile() throws IOException {
        if (!markerFile.getParentFile().exists()) {
            markerFile.getParentFile().mkdirs();
        }
        markerFile.createNewFile();
        markerFile.setLastModified(System.currentTimeMillis());
    }

    protected void deleteDirectory(File directory) {
        if (directory.exists()) {
            for (File file : directory.listFiles()) {
                if (file.isDirectory()) {
                    deleteDirectory(file);
                }
                file.delete();
            }
            directory.delete();
        }
    }
}

