public abstract class AbstractCachingProcessingPipeline<T, R> extends BaseCachingProcessingPipeline<T, R> {
    private Map<String, R> cache = new HashMap<>();
    private boolean smartCachingEnabled;

    public AbstractCachingProcessingPipeline(boolean smartCachingEnabled) {
        this.smartCachingEnabled = smartCachingEnabled;
    }

    protected abstract String generateCacheKey(T input);

    protected abstract boolean isCacheValid(R cachedResponse);

    protected abstract R processInput(T input);

    public void setSmartCachingEnabled(boolean smartCachingEnabled) {
        this.smartCachingEnabled = smartCachingEnabled;
    }

    public R process(T input) {
        String cacheKey = generateCacheKey(input);
        if (smartCachingEnabled && cache.containsKey(cacheKey)) {
            R cachedResponse = cache.get(cacheKey);
            if (isCacheValid(cachedResponse)) {
                return cachedResponse;
            }
        }

        R result = processInput(input);
        if (smartCachingEnabled) {
            cache.put(cacheKey, result);
        }
        return result;
    }

    public void clearCache() {
        cache.clear();
    }

    public void configureCachingSettings(boolean smartCaching) {
        this.smartCachingEnabled = smartCaching;
    }

    // Additional methods for setting up components, parameterizing settings, etc.
}

