            fos.write(data);
        }
    }

    public static byte[] reverseByteArray(byte[] array) {
        assertNonNull(array);
        byte[] reversed = new byte[array.length];
        for (int i = 0; i < array.length; i++) {
            reversed[i] = array[array.length - 1 - i];
        }
        return reversed;
    }

    public static boolean searchPatternInBytes(byte[] data, byte[] pattern) {
        assertNonNull(data);
        assertNonNull(pattern);
        for (int i = 0; i <= data.length - pattern.length; i++) {
            boolean found = true;
            for (int j = 0; j < pattern.length; j++) {
                if (data[i + j] != pattern[j]) {
                    found = false;
                    break;
                }
            }
            if (found) {
                return true;
            }
