public class CredentialCache implements KrbCredentialCache {
    private List<Credential> credentials;
    private String primaryPrincipal;
    private static final int CACHE_VERSION = 1;

    public CredentialCache() {
        this.credentials = new ArrayList<>();
    }

    public CredentialCache(Credential credential) {
        this();
        addCredential(credential);
    }

    public CredentialCache(List<Credential> credentials) {
        this.credentials = credentials;
    }

    public void addCredential(Credential credential) {
        credentials.add(credential);
    }

    public void removeCredential(Credential credential) {
        credentials.remove(credential);
    }

    public Credential getCredential(String principal) {
        for (Credential credential : credentials) {
            if (credential.getPrincipal().equals(principal)) {
                return credential;
            }
        }
        return null;
    }

    public void setPrimaryPrincipal(String principal) {
        this.primaryPrincipal = principal;
    }

    public String getPrimaryPrincipal() {
        return primaryPrincipal;
    }

    public void loadFromFile(String filename) throws IOException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filename))) {
            int version = ois.readInt();
            if (version != CACHE_VERSION) {
                throw new IOException("Unsupported cache version: " + version);
            }
            credentials = (List<Credential>) ois.readObject();
            primaryPrincipal = (String) ois.readObject();
        } catch (ClassNotFoundException e) {
            throw new IOException("Failed to load credentials", e);
        }
    }

    public void saveToFile(String filename) throws IOException {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(filename))) {
            oos.writeInt(CACHE_VERSION);
            oos.writeObject(credentials);
            oos.writeObject(primaryPrincipal);
        }
    }

    public void dumpCache() {
        System.out.println("Primary Principal: " + primaryPrincipal);
        for (Credential credential : credentials) {
            System.out.println(credential);
        }
    }

    public static void main(String[] args) {
        CredentialCache cache = new CredentialCache();
        // Example usage
        cache.dumpCache();
    }
}

