public class NNTP extends SocketClient {
    private boolean postingAllowed;
    private BufferedReader reader;
    private PrintWriter writer;

    public NNTP(String server, int port) throws IOException {
        super(server, port);
        this.reader = new BufferedReader(new InputStreamReader(getInputStream()));
        this.writer = new PrintWriter(getOutputStream(), true);
        this.postingAllowed = false;
    }

    public void connect() throws IOException {
        String response = readResponse();
        if (!response.startsWith("200")) {
            throw new IOException("Failed to connect: " + response);
        }
    }

    public void authenticate(String username, String password) throws IOException {
        sendCommand("AUTHINFO USER " + username);
        String response = readResponse();
        if (!response.startsWith("381")) {
            throw new IOException("Authentication failed: " + response);
        }
        sendCommand("AUTHINFO PASS " + password);
        response = readResponse();
        if (!response.startsWith("281")) {
            throw new IOException("Authentication failed: " + response);
        }
    }

    public void group(String newsgroup) throws IOException {
        sendCommand("GROUP " + newsgroup);
        String response = readResponse();
        if (response.startsWith("411")) {
            throw new IOException("No such newsgroup: " + newsgroup);
        }
        postingAllowed = response.startsWith("211");
    }

    public String article(int articleId) throws IOException {
        sendCommand("ARTICLE " + articleId);
        return readResponse();
    }

    public String body(int articleId) throws IOException {
        sendCommand("BODY " + articleId);
        return readResponse();
    }

    public String head(int articleId) throws IOException {
        sendCommand("HEAD " + articleId);
        return readResponse();
    }

    public void post(String article) throws IOException {
        if (!postingAllowed) {
            throw new IOException("Posting not allowed.");
        }
        sendCommand("POST");
        writer.println(article);
        String response = readResponse();
        if (!response.startsWith("240")) {
            throw new IOException("Failed to post article: " + response);
        }
    }

    public void quit() throws IOException {
        sendCommand("QUIT");
        readResponse();
        close();
    }

    private void sendCommand(String command) {
        writer.println(command);
    }

    private String readResponse() throws IOException {
        return reader.readLine();
    }

    @Deprecated
    public String article(String articleId) throws IOException {
        return article(Integer.parseInt(articleId));
    }

    @Deprecated
    public String body(String articleId) throws IOException {
        return body(Integer.parseInt(articleId));
    }

    @Deprecated
    public String head(String articleId) throws IOException {
        return head(Integer.parseInt(articleId));
    }
}

