    private BrokerService broker;
    private Connection connection;
    private Session session;
    private Queue queue;
    private PooledConnectionFactory connectionFactory;

    @Before
    public void setUp() throws Exception {
        broker = new BrokerService();
        broker.setPersistent(false);
        broker.start();

        connectionFactory = new PooledConnectionFactory();
        connectionFactory.setBrokerURL("vm://localhost");
        connection = connectionFactory.createConnection();
        connection.setExceptionListener(this);
        connection.start();

        session = connection.createSession(true, Session.SESSION_TRANSACTED);
        queue = session.createQueue("test.queue");
    }

    @After
    public void tearDown() throws Exception {
        session.close();
        connection.close();
        broker.stop();
    }

    @Test
    public void testSingleConsumer() throws Exception {
        sendMessages(5);
        MessageConsumer consumer = session.createConsumer(queue);
        Message message = consumer.receive(1000);
        assertNotNull(message);
        session.commit();
        assertQueueIsEmpty();
    }

    @Test
    public void testMultipleConsumers() throws Exception {
        sendMessages(10);
        MessageConsumer consumer1 = session.createConsumer(queue);
        MessageConsumer consumer2 = session.createConsumer(queue);

        Message message1 = consumer1.receive(1000);
        Message message2 = consumer2.receive(1000);
        assertNotNull(message1);
        assertNotNull(message2);
        session.commit();
        assertQueueLength(8);
    }

    private void sendMessages(int count) throws JMSException {
        MessageProducer producer = session.createProducer(queue);
        for (int i = 0; i < count; i++) {
            producer.send(session.createTextMessage("Message " + i));
        }
        session.commit();
    }

    private void assertQueueIsEmpty() throws JMSException {
        QueueBrowser browser = session.createBrowser(queue);
        assertFalse(browser.getEnumeration().hasMoreElements());
    }

    private void assertQueueLength(int expectedLength) throws JMSException {
        QueueBrowser browser = session.createBrowser(queue);
        int actualLength = 0;
        while (browser.getEnumeration().hasMoreElements()) {
            browser.getEnumeration().nextElement();
            actualLength++;
        }
        assertEquals(expectedLength, actualLength);
    }

    @Override
    public void onException(JMSException exception) {
        // Handle JMS exceptions
    }
}

