public class Array2DRowRealMatrix {
    private final double[][] data;
    private final int rowDimension;
    private final int columnDimension;

    public Array2DRowRealMatrix(int rows, int columns) {
        if (rows <= 0 || columns <= 0) {
            throw new IllegalArgumentException("Matrix dimensions must be positive.");
        }
        this.rowDimension = rows;
        this.columnDimension = columns;
        this.data = new double[rows][columns];
    }

    public Array2DRowRealMatrix(double[][] array) {
        if (array == null) {
            throw new NullArgumentException();
        }
        this.rowDimension = array.length;
        this.columnDimension = array[0].length;
        this.data = new double[rowDimension][columnDimension];
        for (int i = 0; i < rowDimension; i++) {
            if (array[i].length != columnDimension) {
                throw new DimensionMismatchException(array[i].length, columnDimension);
            }
            System.arraycopy(array[i], 0, this.data[i], 0, columnDimension);
        }
    }

    public double getEntry(int row, int column) {
        checkIndex(row, column);
        return data[row][column];
    }

    public void setEntry(int row, int column, double value) {
        checkIndex(row, column);
        data[row][column] = value;
    }

    public Array2DRowRealMatrix add(Array2DRowRealMatrix m) {
        checkMatrixDimensions(m);
        Array2DRowRealMatrix result = new Array2DRowRealMatrix(rowDimension, columnDimension);
        for (int i = 0; i < rowDimension; i++) {
            for (int j = 0; j < columnDimension; j++) {
                result.setEntry(i, j, this.getEntry(i, j) + m.getEntry(i, j));
            }
        }
        return result;
    }

    public Array2DRowRealMatrix subtract(Array2DRowRealMatrix m) {
        checkMatrixDimensions(m);
        Array2DRowRealMatrix result = new Array2DRowRealMatrix(rowDimension, columnDimension);
        for (int i = 0; i < rowDimension; i++) {
            for (int j = 0; j < columnDimension; j++) {
                result.setEntry(i, j, this.getEntry(i, j) - m.getEntry(i, j));
            }
        }
        return result;
    }

    public Array2DRowRealMatrix multiply(Array2DRowRealMatrix m) {
        if (this.columnDimension != m.rowDimension) {
            throw new DimensionMismatchException(this.columnDimension, m.rowDimension);
        }
        Array2DRowRealMatrix result = new Array2DRowRealMatrix(this.rowDimension, m.columnDimension);
        for (int i = 0; i < this.rowDimension; i++) {
            for (int j = 0; j < m.columnDimension; j++) {
                double sum = 0;
                for (int k = 0; k < this.columnDimension; k++) {
                    sum += this.getEntry(i, k) * m.getEntry(k, j);
                }
                result.setEntry(i, j, sum);
            }
        }
        return result;
    }

    private void checkIndex(int row, int column) {
        if (row < 0 || row >= rowDimension || column < 0 || column >= columnDimension) {
            throw new IndexOutOfBoundsException("Index out of bounds.");
        }
    }

    private void checkMatrixDimensions(Array2DRowRealMatrix m) {
        if (this.rowDimension != m.rowDimension || this.columnDimension != m.columnDimension) {
            throw new DimensionMismatchException(this.rowDimension, m.rowDimension);
        }
    }

    public int getRowDimension() {
        return rowDimension;
    }

    public int getColumnDimension() {
        return columnDimension;
    }
}

