        StringBuilder sb = new StringBuilder();
        sb.append("<select name='").append(name).append("'")
          .append(required ? " required" : "").append(" class='").append(cssClass).append("'")
          .append(tooltip != null ? " title='" + tooltip + "'" : "").append(">");
        for (String option : options) {
            sb.append("<option value='").append(option).append("'")
              .append(option.equals(selectedValue) ? " selected" : "").append(">")
              .append(option).append("</option>");
        }
        sb.append("</select>");
        return sb.toString();
    }

    public String renderCheckbox(String name, boolean checked, String label, String tooltip, String cssClass) {
        StringBuilder sb = new StringBuilder();
        sb.append("<label class='").append(cssClass).append("'>")
          .append("<input type='checkbox' name='").append(name).append("'")
          .append(checked ? " checked" : "").append(" title='").append(tooltip).append("' />")
          .append(label).append("</label>");
        return sb.toString();
    }

    public String renderRadioButton(String name, String value, boolean checked, String label, String tooltip, String cssClass) {
        StringBuilder sb = new StringBuilder();
        sb.append("<label class='").append(cssClass).append("'>")
          .append("<input type='radio' name='").append(name).append("' value='").append(value).append("'")
          .append(checked ? " checked" : "").append(" title='").append(tooltip).append("' />")
          .append(label).append("</label>");
        return sb.toString();
