        StringBuilder sb = new StringBuilder();
        sb.append("<div class='pagination'>");
        for (int i = 1; i <= totalPages; i++) {
            sb.append("<a href='?page=").append(i).append("'")
              .append(i == currentPage ? " class='active'" : "").append(">")
              .append(i).append("</a>");
        }
        sb.append("</div>");
        return sb.toString();
    }

