        db.execute("ALTER TABLE partitioned_table ADD PARTITION (date='2023-01-01')");
        db.execute("ALTER TABLE partitioned_table RECOVER PARTITIONS");
        assertEquals(1, db.getPartitionCount("partitioned_table"));
    }
