public class ConcurrentLongLongPairHashMapTest {
    private ConcurrentLongLongPairHashMap map;

    @BeforeEach
    public void setUp() {
        map = new ConcurrentLongLongPairHashMap(16, 0.75f);
    }

    @Test
    public void testConstructorValidation() {
        assertThrows(IllegalArgumentException.class, () -> new ConcurrentLongLongPairHashMap(-1, 0.75f));
        assertThrows(IllegalArgumentException.class, () -> new ConcurrentLongLongPairHashMap(16, -0.1f));
    }

    @Test
    public void testBasicInsertionAndRetrieval() {
        assertTrue(map.isEmpty());
        assertEquals(0, map.size());

        map.put(1L, 100L);
        assertFalse(map.isEmpty());
        assertEquals(1, map.size());
        assertEquals(100L, map.get(1L));
    }

    @Test
    public void testRemovalOperations() {
        map.put(1L, 100L);
        assertEquals(100L, map.remove(1L));
        assertNull(map.get(1L));
        assertEquals(0, map.size());

        assertNull(map.remove(2L)); // Non-existent key
    }

    @Test
    public void testBucketCountAfterInsertionsAndDeletions() {
        for (long i = 0; i < 100; i++) {
            map.put(i, i * 10);
        }
        assertTrue(map.getUsedBuckets() > 0);

        for (long i = 0; i < 50; i++) {
            map.remove(i);
        }
        assertTrue(map.getUsedBuckets() > 0);
    }

    @Test
    public void testRehashingBehavior() {
        for (long i = 0; i < 16; i++) {
            map.put(i, i * 10);
        }
        assertEquals(16, map.size());

        for (long i = 0; i < 16; i++) {
            map.remove(i);
        }
        assertEquals(0, map.size());
    }

    @Test
    public void testConcurrentInsertions() throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(10);
        AtomicInteger successfulInserts = new AtomicInteger(0);

        for (long i = 0; i < 1000; i++) {
            final long key = i;
            executor.submit(() -> {
                map.put(key, key * 10);
                successfulInserts.incrementAndGet();
            });
        }
        executor.shutdown();
        while (!executor.isTerminated()) {}

        assertEquals(1000, successfulInserts.get());
        assertEquals(1000, map.size());
    }

    @Test
    public void testIterationOverKeysAndValues() {
        map.put(1L, 100L);
        map.put(2L, 200L);

        assertTrue(map.keySet().contains(1L));
        assertTrue(map.keySet().contains(2L));
        assertEquals(100L, map.values().get(1L));
        assertEquals(200L, map.values().get(2L));
    }

    @Test
    public void testPutIfAbsent() {
        map.put(1L, 100L);
        assertEquals(100L, map.putIfAbsent(1L, 200L));
        assertEquals(100L, map.get(1L));
    }

    @Test
    public void testInvalidKeys() {
        assertThrows(IllegalArgumentException.class, () -> map.put(null, 100L));
        assertThrows(IllegalArgumentException.class, () -> map.get(null));
        assertThrows(IllegalArgumentException.class, () -> map.remove(null));
    }

    @Test
    public void testComparisonWithStandardMap() {
        java.util.Map<Long, Long> standardMap = new java.util.HashMap<>();
        map.put(1L, 100L);
        map.put(2L, 200L);
        standardMap.put(1L, 100L);
        standardMap.put(2L, 200L);

        assertEquals(standardMap.size(), map.size());
        assertEquals(standardMap.get(1L), map.get(1L));
        assertEquals(standardMap.get(2L), map.get(2L));
    }
}

public final class UnicodeClasses {

    private UnicodeClasses() {
        // Private constructor to prevent instantiation
    }

    public static void generateFromJavaChars(String outputFile, boolean includeHex) throws IOException {
        try (FileWriter writer = new FileWriter(outputFile)) {
            writer.write("<!-- Generated Unicode Character Classes -->\n");
            for (char c = 0; c < Character.MAX_VALUE; c++) {
                if (Character.isLetter(c)) {
                    writeCharacter(writer, c, includeHex);
                }
            }
        }
    }

    public static void generateFromUCD(String ucdFile, String outputFile, boolean includeHex) throws IOException {
        List<String> lines = Files.readAllLines(Paths.get(ucdFile));
        try (FileWriter writer = new FileWriter(outputFile)) {
            writer.write("<!-- Generated from Unicode Character Database -->\n");
            for (String line : lines) {
                // Assume line format is known and valid
                char c = (char) Integer.parseInt(line.split(";")[0], 16);
                writeCharacter(writer, c, includeHex);
            }
        }
    }

    public static void generateFromTeX(String texFile, String outputFile, boolean includeHex) throws IOException {
        List<String> lines = Files.readAllLines(Paths.get(texFile));
        try (FileWriter writer = new FileWriter(outputFile)) {
            writer.write("<!-- Generated from TeX input -->\n");
            for (String line : lines) {
                char c = line.charAt(0); // Simplified for example
                writeCharacter(writer, c, includeHex);
            }
        }
    }

    private static void writeCharacter(FileWriter writer, char c, boolean includeHex) throws IOException {
        writer.write("<character>");
        writer.write(c);
        if (includeHex) {
            writer.write(String.format(" (0x%04X)", (int) c));
        }
        writer.write("</character>\n");
    }

    public static void main(String[] args) {
        if (args.length < 3) {
            System.out.println("Usage: UnicodeClasses <sourceType> <inputFile> <outputFile> [includeHex]");
            return;
        }
        String sourceType = args[0];
        String inputFile = args[1];
        String outputFile = args[2];
        boolean includeHex = args.length > 3 && Boolean.parseBoolean(args[3]);

        try {
            switch (sourceType.toLowerCase()) {
                case "javachars":
                    generateFromJavaChars(outputFile, includeHex);
                    break;
                case "ucd":
                    generateFromUCD(inputFile, outputFile, includeHex);
                    break;
                case "tex":
                    generateFromTeX(inputFile, outputFile, includeHex);
                    break;
                default:
                    System.out.println("Unknown source type: " + sourceType);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

public class RedeliveryPolicy extends DelayPolicy {
    private int maxRedeliveries;
    private long initialDelay;
    private long maxDelay;
    private boolean exponentialBackoff;
    private boolean collisionAvoidance;

    public RedeliveryPolicy() {
        this.maxRedeliveries = 3; // default value
        this.initialDelay = 1000; // default value in milliseconds
        this.maxDelay = 30000; // default value in milliseconds
        this.exponentialBackoff = true; // default value
        this.collisionAvoidance = false; // default value
    }

    public boolean shouldRedeliver(int attempt) {
        return attempt < maxRedeliveries;
    }

    public long calculateDelay(int attempt) {
        if (exponentialBackoff) {
            long delay = initialDelay * (1 << attempt); // Exponential backoff
            return Math.min(delay, maxDelay);
        }
        return initialDelay; // Fixed delay
    }

    public void logRetryAttempt(int attempt) {
        System.out.println("Retry attempt: " + attempt);
    }

    public void logExhaustion() {
        System.out.println("Max redelivery attempts exhausted.");
    }

    public void setMaxRedeliveries(int maxRedeliveries) {
        this.maxRedeliveries = maxRedeliveries;
    }

    public void setInitialDelay(long initialDelay) {
        this.initialDelay = initialDelay;
    }

    public void setMaxDelay(long maxDelay) {
        this.maxDelay = maxDelay;
    }

    public void setExponentialBackoff(boolean exponentialBackoff) {
        this.exponentialBackoff = exponentialBackoff;
    }

    public void setCollisionAvoidance(boolean collisionAvoidance) {
        this.collisionAvoidance = collisionAvoidance;
    }

    public RedeliveryPolicy copy() {
        RedeliveryPolicy copy = new RedeliveryPolicy();
        copy.maxRedeliveries = this.maxRedeliveries;
        copy.initialDelay = this.initialDelay;
        copy.maxDelay = this.maxDelay;
        copy.exponentialBackoff = this.exponentialBackoff;
        copy.collisionAvoidance = this.collisionAvoidance;
        return copy;
    }

    @Override
    public String toString() {
        return "RedeliveryPolicy{" +
                "maxRedeliveries=" + maxRedeliveries +
                ", initialDelay=" + initialDelay +
                ", maxDelay=" + maxDelay +
                ", exponentialBackoff=" + exponentialBackoff +
                ", collisionAvoidance=" + collisionAvoidance +
                '}';
    }
}

