class ShardReadersPoolTest {

    private ShardReadersPool shardReadersPool;
    private KinesisClient kinesisClient;
    private ShardIteratorProvider iteratorProvider;

    @Before
    public void setUp() {
        kinesisClient = mock(KinesisClient.class);
        iteratorProvider = mock(ShardIteratorProvider.class);
        shardReadersPool = new ShardReadersPool(kinesisClient, iteratorProvider);
    }

    @Test
    public void testFetchAllRecordsFromMultipleIterators() {
        // Setup mock behavior
        when(iteratorProvider.getIterators()).thenReturn(Collections.singletonList("iterator1"));
        when(kinesisClient.getRecords("iterator1")).thenReturn(createMockRecords());

        List<Record> records = shardReadersPool.fetchAllRecords();

        assertFalse(records.isEmpty());
        verify(kinesisClient).getRecords("iterator1");
    }

    @Test
    public void testHandleNoRecordsAvailable() {
        when(iteratorProvider.getIterators()).thenReturn(Collections.singletonList("iterator1"));
        when(kinesisClient.getRecords("iterator1")).thenReturn(Collections.emptyList());

        List<Record> records = shardReadersPool.fetchAllRecords();

        assertTrue(records.isEmpty());
        verify(kinesisClient).getRecords("iterator1");
    }

    @Test
    public void testAcknowledgeReadRecords() {
        Record record = new Record("data");
        when(iteratorProvider.getIterators()).thenReturn(Collections.singletonList("iterator1"));
        when(kinesisClient.getRecords("iterator1")).thenReturn(Collections.singletonList(record));

        shardReadersPool.fetchAllRecords();
        shardReadersPool.acknowledgeRecords(Collections.singletonList(record));

        verify(kinesisClient).checkpoint(record);
    }

    @Test
    public void testInterruptReadingOperations() throws InterruptedException {
        when(iteratorProvider.getIterators()).thenReturn(Collections.singletonList("iterator1"));
        when(kinesisClient.getRecords("iterator1")).thenReturn(createMockRecords());

        Thread readingThread = new Thread(() -> shardReadersPool.startReading());
        readingThread.start();
        Thread.sleep(100); // Simulate some reading time
        shardReadersPool.stopReading();
        readingThread.join();

        assertTrue(shardReadersPool.isStopped());
    }

    @Test
    public void testCheckAllShardsUpToDate() {
        when(iteratorProvider.getIterators()).thenReturn(Collections.singletonList("iterator1"));
        when(kinesisClient.isShardUpToDate("iterator1")).thenReturn(true);

        boolean allUpToDate = shardReadersPool.checkAllShardsUpToDate();

        assertTrue(allUpToDate);
        verify(kinesisClient).isShardUpToDate("iterator1");
    }

    @Test
    public void testHandleShardClosureExceptions() {
        when(iteratorProvider.getIterators()).thenReturn(Collections.singletonList("iterator1"));
        when(kinesisClient.getRecords("iterator1")).thenThrow(new ShardClosedException());

        shardReadersPool.fetchAllRecords();

        verify(iteratorProvider).transitionToNextShard();
    }

    @Test
    public void testNoIteratorsAvailable() {
        when(iteratorProvider.getIterators()).thenReturn(Collections.emptyList());

        List<Record> records = shardReadersPool.fetchAllRecords();

        assertTrue(records.isEmpty());
        verify(kinesisClient, never()).getRecords(anyString());
    }

    @Test
    public void testManageClosedShardIterators() {
        when(iteratorProvider.getIterators()).thenReturn(Collections.singletonList("iterator1"));
        when(kinesisClient.getRecords("iterator1")).thenThrow(new ShardClosedException());

        shardReadersPool.fetchAllRecords();
        shardReadersPool.closeClosedIterators();

        assertTrue(shardReadersPool.getClosedIterators().isEmpty());
    }

    private List<Record> createMockRecords() {
        return Collections.singletonList(new Record("mockData"));
    }
}

