public class RexLiteral {
    private final Object value;
    private final Class<?> type;
    private final String sqlTypeName;

    public RexLiteral(Object value, Class<?> type, String sqlTypeName) {
        this.value = value;
        this.type = type;
        this.sqlTypeName = sqlTypeName;
    }

    public boolean isNull() {
        return value == null;
    }

    public String getDigest() {
        return value != null ? value.toString() : "NULL";
    }

    public static RexLiteral fromJdbcString(String jdbcString, Class<?> type, String sqlTypeName) {
        Object value = null;
        if (jdbcString != null) {
            if (type == Integer.class) {
                value = Integer.valueOf(jdbcString);
            } else if (type == String.class) {
                value = jdbcString;
            } else if (type == Date.class) {
                value = Date.valueOf(jdbcString);
            } else if (type == Time.class) {
                value = Time.valueOf(jdbcString);
            } else if (type == Timestamp.class) {
                value = Timestamp.valueOf(jdbcString);
            }
            // Additional types can be added here
        }
        return new RexLiteral(value, type, sqlTypeName);
    }

    public Object getValue() {
        return value;
    }

    public Integer getAsInteger() {
        return (Integer) value;
    }

    public String getAsString() {
        return (String) value;
    }

    public Date getAsDate() {
        return (Date) value;
    }

    public Time getAsTime() {
        return (Time) value;
    }

    public Timestamp getAsTimestamp() {
        return (Timestamp) value;
    }

    public void accept(RexVisitor visitor) {
        visitor.visit(this);
    }

    @Override
    public String toString() {
        return "RexLiteral{" +
                "value=" + value +
                ", type=" + type +
                ", sqlTypeName='" + sqlTypeName + '\'' +
                '}';
    }
}

interface RexVisitor {
    void visit(RexLiteral literal);
}

