@Processor
@Capability("Executes an external command")
public class ExecuteStreamCommand extends AbstractProcessor {

    public static final PropertyDescriptor COMMAND_PATH = new PropertyDescriptor.Builder()
            .name("Command Path")
            .description("The path to the command to execute")
            .required(true)
            .addValidator(StandardValidators.NON_EMPTY_VALIDATOR)
            .build();

    public static final PropertyDescriptor ARGUMENTS = new PropertyDescriptor.Builder()
            .name("Arguments")
            .description("Arguments to pass to the command")
            .required(false)
            .addValidator(StandardValidators.NON_EMPTY_VALIDATOR)
            .build();

    public static final PropertyDescriptor WORKING_DIRECTORY = new PropertyDescriptor.Builder()
            .name("Working Directory")
            .description("The directory in which to execute the command")
            .required(false)
            .addValidator(StandardValidators.NON_EMPTY_VALIDATOR)
            .build();

    public static final Relationship SUCCESS = new Relationship.Builder()
            .name("success")
            .description("Successfully executed commands")
            .build();

    public static final Relationship FAILURE = new Relationship.Builder()
            .name("failure")
            .description("Failed command executions")
            .build();

    private Set<Relationship> relationships;

    @Override
    protected void init(ProcessorInitializationContext context) {
        relationships = new HashSet<>();
        relationships.add(SUCCESS);
        relationships.add(FAILURE);
    }

    @OnScheduled
    public void onScheduled(ProcessorContext context) {
        // Initialization logic if needed
    }

    @OnStopped
    public void onStopped() {
        // Cleanup logic if needed
    }

    @Override
    public Set<Relationship> getRelationships() {
        return relationships;
    }

    @Override
    public void onTrigger(ProcessContext context, ProcessSession session) throws ProcessException {
        FlowFile flowFile = session.get();
        if (flowFile == null) {
            return;
        }

        String commandPath = context.getProperty(COMMAND_PATH).getValue();
        String arguments = context.getProperty(ARGUMENTS).getValue();
        String workingDirectory = context.getProperty(WORKING_DIRECTORY).getValue();

        List<String> command = new ArrayList<>();
        command.add(commandPath);
        if (arguments != null) {
            for (String arg : arguments.split(" ")) {
                command.add(arg);
            }
        }

        ProcessBuilder processBuilder = new ProcessBuilder(command);
        if (workingDirectory != null) {
            processBuilder.directory(new File(workingDirectory));
        }

        try {
            Process process = processBuilder.start();
            OutputStream outputStream = process.getOutputStream();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));

            // Handle standard input if needed
            // Write to outputStream if necessary

            int exitCode = process.waitFor();
            StringBuilder output = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            if (exitCode == 0) {
                flowFile = session.putAttribute(flowFile, "command.output", output.toString());
                session.transfer(flowFile, SUCCESS);
            } else {
                getLogger().error("Command failed with exit code " + exitCode);
                session.transfer(flowFile, FAILURE);
            }
        } catch (Exception e) {
            getLogger().error("Error executing command", e);
            session.transfer(flowFile, FAILURE);
        }
    }
}

public class NodeTypeRegistry implements Dumpable {
    private final Map<String, NodeType> registeredNodeTypes = new HashMap<>();
    private final List<NodeTypeChangeListener> listeners = new ArrayList<>();

    public void registerNodeType(NodeType nodeType) {
        if (registeredNodeTypes.containsKey(nodeType.getName())) {
            throw new IllegalArgumentException("Node type already registered: " + nodeType.getName());
        }
        validateNodeType(nodeType);
        registeredNodeTypes.put(nodeType.getName(), nodeType);
        notifyListeners(nodeType, true);
    }

    public void unregisterNodeType(String nodeTypeName) {
        NodeType removedNodeType = registeredNodeTypes.remove(nodeTypeName);
        if (removedNodeType != null) {
            notifyListeners(removedNodeType, false);
        }
    }

    public NodeType getNodeType(String nodeTypeName) {
        return registeredNodeTypes.get(nodeTypeName);
    }

    public List<NodeType> getEffectiveNodeTypes() {
        return new ArrayList<>(registeredNodeTypes.values());
    }

    public void addNodeTypeChangeListener(NodeTypeChangeListener listener) {
        listeners.add(listener);
    }

    public void removeNodeTypeChangeListener(NodeTypeChangeListener listener) {
        listeners.remove(listener);
    }

    private void notifyListeners(NodeType nodeType, boolean isRegistered) {
        for (NodeTypeChangeListener listener : listeners) {
            if (isRegistered) {
                listener.onNodeTypeRegistered(nodeType);
            } else {
                listener.onNodeTypeUnregistered(nodeType);
            }
        }
    }

    private void validateNodeType(NodeType nodeType) {
        // Check for circular dependencies
        if (hasCircularDependency(nodeType)) {
            throw new IllegalArgumentException("Circular dependency detected for node type: " + nodeType.getName());
        }
