public class ASTReference {
    private String reference;
    private boolean strict;
    private boolean quiet;
    private boolean runtime;
    private Map<String, Object> context;

    public ASTReference(String reference, boolean strict, boolean quiet, boolean runtime, Map<String, Object> context) {
        this.reference = reference;
        this.strict = strict;
        this.quiet = quiet;
        this.runtime = runtime;
        this.context = context;
    }

    public Object getValue() {
        Object value = context.get(reference);
        if (value == null && strict) {
            logNullReference(reference);
            throw new NullPointerException("Reference " + reference + " is null");
        }
        return value;
    }

    public String render() {
        Object value = getValue();
        if (value != null) {
            return escapeSpecialCharacters(value.toString());
        } else if (quiet) {
            return "";
        }
        return null;
    }

    private void logNullReference(String reference) {
        System.err.println("Null reference: " + reference);
    }

    private String escapeSpecialCharacters(String value) {
        return value.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&apos;");
    }

    public void setValue(Object value) {
        context.put(reference, value);
    }

    public boolean evaluateBooleanExpression() {
        Object value = getValue();
        if (value instanceof Boolean) {
            return (Boolean) value;
        }
        return false;
    }

    public void executeChildNodes() {
        // Logic for executing child nodes would go here
    }
}

