class CustomDateTime {
    private DateTime dateTime;

    public CustomDateTime() {
        this.dateTime = new DateTime();
    }

    public CustomDateTime(Date date) {
        this.dateTime = new DateTime(date);
    }

    public CustomDateTime(long milliseconds) {
        this.dateTime = new DateTime(milliseconds);
    }

    public CustomDateTime(int year, int month, int day, int hour, int minute, int second) {
        this.dateTime = new DateTime(year, month, day, hour, minute, second);
    }

    public void addDays(int days) {
        this.dateTime = this.dateTime.plusDays(days);
    }

    public void addHours(int hours) {
        this.dateTime = this.dateTime.plusHours(hours);
    }

    public int getYear() {
        return this.dateTime.getYear();
    }

    public int getMonth() {
        return this.dateTime.getMonthOfYear();
    }

    public int getDay() {
        return this.dateTime.getDayOfMonth();
    }

    public int getHour() {
        return this.dateTime.getHourOfDay();
    }

    public int getMinute() {
        return this.dateTime.getMinuteOfHour();
    }

    public int getSecond() {
        return this.dateTime.getSecondOfMinute();
    }

    public Date toDate() {
        return this.dateTime.toDate();
    }

    public Calendar toCalendar() {
        Calendar calendar = Calendar.getInstance();
        calendar.setTime(this.toDate());
        return calendar;
    }

    public boolean isSameDay(CustomDateTime other) {
        return this.dateTime.toLocalDate().equals(other.dateTime.toLocalDate());
    }

    public boolean isSameWeek(CustomDateTime other) {
        return this.dateTime.getWeekyear() == other.dateTime.getWeekyear() &&
               this.dateTime.getWeekOfWeekyear() == other.dateTime.getWeekOfWeekyear();
    }

    public boolean isSameMonth(CustomDateTime other) {
        return this.dateTime.getYear() == other.dateTime.getYear() &&
               this.dateTime.getMonthOfYear() == other.dateTime.getMonthOfYear();
    }

    public boolean isSameYear(CustomDateTime other) {
        return this.dateTime.getYear() == other.dateTime.getYear();
    }

    public DateTime startOfWeek() {
        return this.dateTime.withTimeAtStartOfDay().withDayOfWeek(1);
    }

    public DateTime startOfMonth() {
        return this.dateTime.withTimeAtStartOfDay().withDayOfMonth(1);
    }

    public DateTime startOfYear() {
        return this.dateTime.withTimeAtStartOfDay().withDayOfYear(1);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof CustomDateTime)) return false;
        CustomDateTime other = (CustomDateTime) obj;
        return this.dateTime.equals(other.dateTime);
    }

    @Override
    public int hashCode() {
        return this.dateTime.hashCode();
    }

    @Override
    public String toString() {
        return this.dateTime.toString();
    }
