public abstract class AbstractGryoClassResolver implements ClassResolver {
    private final Map<Class<?>, Registration> classToRegistration = new HashMap<>();
    private final Map<Integer, Registration> idToRegistration = new HashMap<>();
    private final Map<String, Class<?>> nameToClass = new HashMap<>();
    private boolean isReset = false;

    public void register(Class<?> type, Registration registration) {
        classToRegistration.put(type, registration);
        idToRegistration.put(registration.getId(), registration);
        nameToClass.put(type.getName(), type);
    }

    public Registration resolveRegistration(Class<?> type) {
        if (isReset) {
            resetMemoization();
        }
        return classToRegistration.get(type);
    }

    public Registration resolveRegistrationById(int id) {
        if (isReset) {
            resetMemoization();
        }
        return idToRegistration.get(id);
    }

    public Class<?> resolveClassByName(String name) {
        if (isReset) {
            resetMemoization();
        }
        return nameToClass.get(name);
    }

    public void reset() {
        isReset = true;
    }

    private void resetMemoization() {
        isReset = false;
    }

    protected abstract Class<?> coerceType(Class<?> type);
}

