public class ActionResultReprRenderer extends ReprRendererAbstract {
    private boolean includeSelfLink;
    private ObjectMapper objectMapper;

    public ActionResultReprRenderer() {
        this.objectMapper = new ObjectMapper();
    }

    public void setIncludeSelfLink(boolean includeSelfLink) {
        this.includeSelfLink = includeSelfLink;
    }

    public String render(ActionInvocationContext context) throws Exception {
        Object result = context.getReturnedAdapter();
        String jsonResult;

        if (result == null) {
            jsonResult = "{\"resultType\": \"void\"}";
        } else if (result instanceof List) {
            jsonResult = objectMapper.writeValueAsString(result);
            jsonResult = "{\"resultType\": \"list\", \"results\": " + jsonResult + "}";
        } else if (result instanceof String || result instanceof Number || result instanceof Boolean) {
            jsonResult = "{\"resultType\": \"scalar\", \"result\": " + objectMapper.writeValueAsString(result) + "}";
        } else {
            jsonResult = objectMapper.writeValueAsString(result);
            jsonResult = "{\"resultType\": \"domainObject\", \"result\": " + jsonResult + "}";
        }

        if (includeSelfLink) {
            String selfLink = generateSelfLink(context);
            jsonResult = addSelfLinkToJson(jsonResult, selfLink);
        }

        return jsonResult;
    }

    private String generateSelfLink(ActionInvocationContext context) {
        // Generate self-link based on the context
        return context.getBaseUrl() + "/" + context.getActionName();
    }

    private String addSelfLinkToJson(String jsonResult, String selfLink) {
        return jsonResult.substring(0, jsonResult.length() - 1) + ", \"selfLink\": \"" + selfLink + "\"}";
    }
}

public class NameServerImpl implements NameServer {
    private static final Logger logger = Logger.getLogger(NameServerImpl.class.getName());
    private final Map<String, InetSocketAddress> registry = new HashMap<>();
    private final int port;

    public NameServerImpl(int port) {
        this.port = port;
        initializeTransportLayer();
    }

    private void initializeTransportLayer() {
        // Initialize transport layer for communication
        logger.info("Transport layer initialized on port: " + port);
    }

    @Override
    public synchronized void register(String identifier, InetSocketAddress address) {
        registry.put(identifier, address);
        logger.info("Registered identifier: " + identifier + " with address: " + address);
    }

    @Override
    public synchronized void unregister(String identifier) {
        registry.remove(identifier);
        logger.info("Unregistered identifier: " + identifier);
    }

    @Override
    public synchronized InetSocketAddress lookup(String identifier) {
        InetSocketAddress address = registry.get(identifier);
        logger.info("Lookup for identifier: " + identifier + " returned: " + address);
        return address;
    }

    @Override
    public synchronized List<InetSocketAddress> lookupMultiple(List<String> identifiers) {
        List<InetSocketAddress> addresses = identifiers.stream()
                .map(this::lookup)
                .toList();
        logger.info("Lookup for multiple identifiers: " + identifiers + " returned: " + addresses);
        return addresses;
    }

    @Override
    public int getPort() {
        logger.info("Server is listening on port: " + port);
        return port;
    }

    @Override
    public void close() {
        // Close transport connection
        logger.info("Closing transport connection.");
    }
}

