public class MemCollection<S> implements PCollection<S> {
    private final List<S> elements;
    private final String name;

    public MemCollection(Iterable<S> source, String name) {
        this.elements = new ArrayList<>();
        source.forEach(elements::add);
        this.name = name;
    }

    @Override
    public PCollection<S> union(PCollection<S> other) {
        MemCollection<S> otherCollection = (MemCollection<S>) other;
        List<S> combined = new ArrayList<>(this.elements);
        combined.addAll(otherCollection.elements);
        return new MemCollection<>(combined, this.name + " union " + otherCollection.name);
    }

    @Override
    public <T> PCollection<T> apply(DoFn<S, T> fn) {
        List<T> results = new ArrayList<>();
        for (S element : elements) {
            results.add(fn.process(element));
        }
        return new MemCollection<>(results, this.name + " applied " + fn.getClass().getSimpleName());
    }

    @Override
    public PCollection<S> filter(Predicate<S> predicate) {
        List<S> filtered = new ArrayList<>();
        for (S element : elements) {
            if (predicate.test(element)) {
                filtered.add(element);
            }
        }
        return new MemCollection<>(filtered, this.name + " filtered");
    }

    @Override
    public long count() {
        return elements.size();
    }

    @Override
    public S min() {
        return Collections.min(elements, null);
    }

    @Override
    public S max() {
        return Collections.max(elements, null);
    }

    @Override
    public int length() {
        return elements.size();
    }

    @Override
    public void writeTo(Target target) {
        // Implementation for writing to a target
    }

    @Override
    public MemCollection<S> materialize() {
        return this;
    }

    @Override
    public long size() {
        return elements.size();
    }

    @Override
    public String getName() {
        return name;
    }

    public <K, V> PTable<K, V> toPTable() {
        // Implementation for converting to PTable
        return null; // Placeholder
    }

    @Override
    public Iterator<S> iterator() {
        return elements.iterator();
    }
}

