    public SchedulerBroker(BrokerFilter next) {
        super(next);
        this.jobSchedulerStore = new JobSchedulerStore();
        this.jobScheduler = new JobScheduler(jobSchedulerStore);
    }

    public void startScheduler() {
        try {
            jobScheduler.start();
            LOG.info("Job scheduler started.");
        } catch (JobSchedulerException e) {
            LOG.error("Failed to start job scheduler.", e);
        }
    }

    public void stopScheduler() {
        try {
            jobScheduler.stop();
            LOG.info("Job scheduler stopped.");
        } catch (JobSchedulerException e) {
            LOG.error("Failed to stop job scheduler.", e);
        }
    }

    public void sendScheduledMessage(String destination, String message, String cronExpression) {
        Job job = new Job(destination, message, cronExpression);
        jobScheduler.scheduleJob(job);
        LOG.info("Scheduled message sent to {} with cron expression {}", destination, cronExpression);
    }

    public void browseJobs() {
        for (Job job : jobSchedulerStore.getAllJobs()) {
            LOG.info("Job found: {}", job);
        }
    }

    public void removeJob(String jobId) {
        jobSchedulerStore.removeJob(jobId);
        LOG.info("Job with ID {} removed.", jobId);
    }

