public class TestInformationSchemaColumns {
    private Connection connection;
    private Statement statement;

    @Before
    public void setUp() throws Exception {
        Driver driver = new Driver();
        connection = driver.connect("jdbc:drill:zk=local", null);
        statement = connection.createStatement();
        createTemporaryView();
    }

    private void createTemporaryView() throws Exception {
        String createViewSQL = "CREATE VIEW temp_view AS " +
                "SELECT " +
                "CAST(1 AS INTEGER) AS int_col, " +
                "CAST('text' AS VARCHAR) AS varchar_col, " +
                "CAST(1.0 AS FLOAT) AS float_col, " +
                "CAST(NULL AS INTEGER) AS nullable_int_col " +
                "FROM (VALUES(1)) AS t(x)";
        statement.execute(createViewSQL);
    }

    @Test
    public void testColumnCount() throws Exception {
        ResultSet resultSet = statement.executeQuery("SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'temp_view'");
        resultSet.next();
        assertEquals(4, resultSet.getInt(1));
    }

    @Test
    public void testColumnDataTypes() throws Exception {
        ResultSet resultSet = statement.executeQuery("SELECT COLUMN_NAME, DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'temp_view'");
        while (resultSet.next()) {
            String columnName = resultSet.getString("COLUMN_NAME");
            String dataType = resultSet.getString("DATA_TYPE");
            if ("int_col".equals(columnName)) {
                assertEquals("INTEGER", dataType);
            } else if ("varchar_col".equals(columnName)) {
                assertEquals("VARCHAR", dataType);
            } else if ("float_col".equals(columnName)) {
                assertEquals("FLOAT", dataType);
            } else if ("nullable_int_col".equals(columnName)) {
                assertEquals("INTEGER", dataType);
            }
        }
    }

    @Test
    public void testColumnNullability() throws Exception {
        ResultSet resultSet = statement.executeQuery("SELECT COLUMN_NAME, IS_NULLABLE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'temp_view'");
        while (resultSet.next()) {
            String columnName = resultSet.getString("COLUMN_NAME");
            String isNullable = resultSet.getString("IS_NULLABLE");
            if ("nullable_int_col".equals(columnName)) {
                assertEquals("YES", isNullable);
            } else {
                assertEquals("NO", isNullable);
            }
        }
    }

    @After
    public void tearDown() throws Exception {
        statement.execute("DROP VIEW temp_view");
        statement.close();
        connection.close();
    }
}

