public final class ScatterSender<T> implements Scatter.Sender<T>, EventHandler<GroupCommunicationMessage> {
    private static final Logger logger = Logger.getLogger(ScatterSender.class.getName());
    private CommunicationGroup communicationGroup;
    private Codec<T> codec;
    private List<SlaveTask> activeSlaveTasks;

    public ScatterSender(CommunicationGroup communicationGroup, Codec<T> codec) {
        this.communicationGroup = communicationGroup;
        this.codec = codec;
        this.activeSlaveTasks = communicationGroup.getActiveSlaveTasks();
        logger.info("ScatterSender initialized with communication group and codec.");
    }

    public void sendElements(List<T> elements) {
        for (T element : elements) {
            byte[] encodedData = codec.encode(element);
            for (SlaveTask task : activeSlaveTasks) {
                task.send(encodedData);
                logger.fine("Sent data to task: " + task.getId());
            }
        }
    }

    @Override
    public void handleEvent(GroupCommunicationMessage message) {
        logger.info("Received message: " + message);
        // Handle incoming message logic
    }

    public void maintainTopology() {
        // Logic to maintain the topology of the operator
        logger.info("Maintaining topology of the operator.");
    }
}

