public class TestXSDFuncOp {

    private XSDFuncOp xsdFuncOp = new XSDFuncOp();

    @Test
    public void testLexicalRepresentationOfDecimal() {
        assertEquals("123.45", xsdFuncOp.lexicalRepresentation(new BigDecimal("123.45")));
        assertEquals("-123.45", xsdFuncOp.lexicalRepresentation(new BigDecimal("-123.45")));
    }

    @Test
    public void testArithmeticOperations() {
        assertEquals(new BigDecimal("5.0"), xsdFuncOp.add(new BigDecimal("2.5"), new BigDecimal("2.5")));
        assertEquals(new BigDecimal("0.0"), xsdFuncOp.subtract(new BigDecimal("2.5"), new BigDecimal("2.5")));
        assertEquals(new BigDecimal("6.25"), xsdFuncOp.multiply(new BigDecimal("2.5"), new BigDecimal("2.5")));
        assertEquals(new BigDecimal("2.0"), xsdFuncOp.divide(new BigDecimal("5.0"), new BigDecimal("2.5")));
    }

    @Test
    public void testDivisionByZero() {
        Exception exception = assertThrows(ArithmeticException.class, () -> {
            xsdFuncOp.divide(new BigDecimal("5.0"), BigDecimal.ZERO);
        });
        assertEquals("Division by zero", exception.getMessage());
    }

    @Test
    public void testComparisonOperations() {
        assertTrue(xsdFuncOp.compare(new BigDecimal("5.0"), new BigDecimal("2.5")) > 0);
        assertTrue(xsdFuncOp.compare(new BigDecimal("2.5"), new BigDecimal("2.5")) == 0);
        assertTrue(xsdFuncOp.compare(new BigDecimal("2.5"), new BigDecimal("5.0")) < 0);
        assertTrue(xsdFuncOp.compare("apple", "banana") < 0);
        assertTrue(xsdFuncOp.compare("banana", "banana") == 0);
        assertTrue(xsdFuncOp.compare("banana", "apple") > 0);
    }

    @Test
    public void testTypeCasting() {
        assertEquals("2023-10-01", xsdFuncOp.castToDate("2023-10-01T10:00:00"));
        assertEquals("10:00:00", xsdFuncOp.castToTime("2023-10-01T10:00:00"));
        assertEquals("2023-10-01T10:00:00", xsdFuncOp.castToDateTime("2023-10-01"));
    }

    @Test
    public void testErrorHandling() {
        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            xsdFuncOp.someFunctionThatMightFail(null);
        });
        assertEquals("Input cannot be null", exception.getMessage());
    }
}

