public class JPATaskDAO extends AbstractDAO<Task> implements TaskDAO {

    @PersistenceContext
    private EntityManager entityManager;

    @Override
    public List<Task> findTasksByType(TaskType taskType) {
        String jpql = "SELECT t FROM Task t WHERE t.type = :taskType";
        TypedQuery<Task> query = entityManager.createQuery(jpql, Task.class);
        query.setParameter("taskType", taskType);
        return query.getResultList();
    }

    @Override
    public List<Task> findTasksToExecute() {
        String jpql = "SELECT t FROM Task t WHERE t.status = 'PENDING'";
        TypedQuery<Task> query = entityManager.createQuery(jpql, Task.class);
        return query.getResultList();
    }

    @Override
    public long countTasks() {
        String jpql = "SELECT COUNT(t) FROM Task t";
        return entityManager.createQuery(jpql, Long.class).getSingleResult();
    }

    @Override
    @Transactional
    public void save(Task task) {
        entityManager.persist(task);
    }

    @Override
    @Transactional
    public void delete(Task task) {
        if (entityManager.contains(task)) {
            entityManager.remove(task);
        } else {
            entityManager.remove(entityManager.merge(task));
        }
    }

    public List<Task> findTasksWithPagination(int pageNumber, int pageSize) {
        String jpql = "SELECT t FROM Task t";
        TypedQuery<Task> query = entityManager.createQuery(jpql, Task.class);
        query.setFirstResult(pageNumber * pageSize);
        query.setMaxResults(pageSize);
        return query.getResultList();
    }

    public List<Task> findTasksOrderedBy(String orderBy) {
        String jpql = "SELECT t FROM Task t ORDER BY t." + orderBy;
        TypedQuery<Task> query = entityManager.createQuery(jpql, Task.class);
        return query.getResultList();
    }
}

