    private Runnable successCallback;
    private Runnable failureCallback;

    public DeleteBuilderImpl(ZooKeeper zooKeeper) {
        this.zooKeeper = zooKeeper;
    }

    public DeleteBuilderImpl withPath(String path) {
        this.path = path;
        return this;
    }

    public DeleteBuilderImpl inBackground(Runnable callback) {
        this.isBackground = true;
        this.successCallback = callback;
        return this;
    }

    public DeleteBuilderImpl deleteChildren(boolean deleteChildren) {
        this.deleteChildren = deleteChildren;
        return this;
    }

    public DeleteBuilderImpl withVersion(int version) {
        this.version = version;
        return this;
    }

    public void delete() throws KeeperException, InterruptedException {
        if (isBackground) {
            CompletableFuture.runAsync(() -> {
                try {
                    performDeletion();
                    if (successCallback != null) {
                        successCallback.run();
                    }
                } catch (Exception e) {
                    if (failureCallback != null) {
                        failureCallback.run();
                    }
                }
            });
        } else {
            performDeletion();
        }
    }

    private void performDeletion() throws KeeperException, InterruptedException {
        if (deleteChildren) {
            // Logic to delete children nodes (not implemented for brevity)
        }
        zooKeeper.delete(path, version);
    }

    public void onFailure(Runnable callback) {
        this.failureCallback = callback;
    }
}

