public class WebXml {
    private int majorVersion;
    private int minorVersion;
    private String publicId;
    private List<String> ordering = new ArrayList<>();
    private Map<String, String> contextParams = new HashMap<>();
    private Map<String, String> servlets = new HashMap<>();
    private Map<String, String> filters = new HashMap<>();
    private List<String> listeners = new ArrayList<>();
    private int sessionTimeout;
    private String sessionCookie;
    private Map<String, String> errorPages = new HashMap<>();
    private Map<String, Set<String>> securityConstraints = new HashMap<>();
    private Map<String, String> resourceReferences = new HashMap<>();
    private List<Runnable> postConstructCallbacks = new ArrayList<>();
    private List<Runnable> preDestroyCallbacks = new ArrayList<>();

    public WebXml(int majorVersion, int minorVersion) {
        this.majorVersion = majorVersion;
        this.minorVersion = minorVersion;
    }

    public void setPublicId(String publicId) {
        this.publicId = publicId;
    }

    public String getPublicId() {
        return publicId;
    }

    public void addOrdering(String fragment) {
        if (!ordering.contains(fragment)) {
            ordering.add(fragment);
        }
    }

    public void addContextParam(String name, String value) {
        contextParams.put(name, value);
    }

    public String getContextParam(String name) {
        return contextParams.get(name);
    }

    public void addServlet(String name, String className) {
        servlets.put(name, className);
    }

    public void addFilter(String name, String className) {
        filters.put(name, className);
    }

    public void addListener(String listener) {
        if (!listeners.contains(listener)) {
            listeners.add(listener);
        }
    }

    public void setSessionTimeout(int timeout) {
        this.sessionTimeout = timeout;
    }

    public void setSessionCookie(String cookie) {
        this.sessionCookie = cookie;
    }

    public void addErrorPage(String errorCode, String location) {
        errorPages.put(errorCode, location);
    }

    public void addSecurityConstraint(String role, String urlPattern) {
        securityConstraints.computeIfAbsent(role, k -> new HashSet<>()).add(urlPattern);
    }

    public void addResourceReference(String name, String reference) {
        resourceReferences.put(name, reference);
    }

    public void addPostConstructCallback(Runnable callback) {
        postConstructCallbacks.add(callback);
    }

    public void addPreDestroyCallback(Runnable callback) {
        preDestroyCallbacks.add(callback);
    }

    public String toXml() {
        StringBuilder xml = new StringBuilder();
        xml.append("<web-app version=\"").append(majorVersion).append(".").append(minorVersion).append("\">\n");
        // Add other elements to XML representation
        xml.append("</web-app>");
        return xml.toString();
    }

    public void merge(WebXml other) {
        // Merge logic with potential conflicts
        other.contextParams.forEach(this::addContextParam);
        other.servlets.forEach(this::addServlet);
        other.filters.forEach(this::addFilter);
        other.listeners.forEach(this::addListener);
        other.errorPages.forEach(this::addErrorPage);
        other.securityConstraints.forEach((role, patterns) -> patterns.forEach(pattern -> addSecurityConstraint(role, pattern)));
        other.resourceReferences.forEach(this::addResourceReference);
    }
}

