public class UtilCache<K, V> {
    private final ConcurrentHashMap<K, CacheEntry<V>> cacheMap;
    private final File storageFile;
    private final long expirationTime;
    private final List<Consumer<K>> evictionListeners;
    private int hitCount;
    private int missCount;

    public UtilCache(File storageFile, long expirationTime) {
        this.cacheMap = new ConcurrentHashMap<>();
        this.storageFile = storageFile;
        this.expirationTime = expirationTime;
        this.evictionListeners = new ArrayList<>();
        this.hitCount = 0;
        this.missCount = 0;
        loadFromFile();
    }

    public void put(K key, V value) {
        cacheMap.put(key, new CacheEntry<>(value, System.currentTimeMillis()));
        saveToFile();
    }

    public V get(K key) {
        CacheEntry<V> entry = cacheMap.get(key);
        if (entry == null || isExpired(entry)) {
            missCount++;
            return null;
        }
        hitCount++;
        return entry.value;
    }

    public void remove(K key) {
        cacheMap.remove(key);
        notifyEvictionListeners(key);
        saveToFile();
    }

    public void addEvictionListener(Consumer<K> listener) {
        evictionListeners.add(listener);
    }

    public int getHitCount() {
        return hitCount;
    }

    public int getMissCount() {
        return missCount;
    }

    private boolean isExpired(CacheEntry<V> entry) {
        return System.currentTimeMillis() - entry.timestamp > expirationTime;
    }

    private void notifyEvictionListeners(K key) {
        for (Consumer<K> listener : evictionListeners) {
            listener.accept(key);
        }
    }

    private void loadFromFile() {
        // Implement loading from file using JDBM
    }

    private void saveToFile() {
        // Implement saving to file using JDBM
    }

    private static class CacheEntry<V> {
        V value;
        long timestamp;

        CacheEntry(V value, long timestamp) {
            this.value = value;
            this.timestamp = timestamp;
        }
    }

    public static <K, V> UtilCache<K, V> create(File storageFile, long expirationTime) {
        return new UtilCache<>(storageFile, expirationTime);
    }
}

