public class UserDao {

    @PersistenceContext
    private EntityManager entityManager;

    private static final Logger logger = Logger.getLogger(UserDao.class.getName());

    @Transactional
    public void createUser(User user) {
        entityManager.persist(user);
        logger.info("User created: " + user);
    }

    public User getUserById(Long id) {
        User user = entityManager.find(User.class, id);
        logger.info("Retrieved user: " + user);
        return user;
    }

    @Transactional
    public void updateUser(User user) {
        entityManager.merge(user);
        logger.info("User updated: " + user);
    }

    @Transactional
    public void deleteUser(Long id) {
        User user = getUserById(id);
        if (user != null) {
            entityManager.remove(user);
            logger.info("User deleted: " + user);
        }
    }

    public List<User> searchUsers(String criteria) {
        TypedQuery<User> query = entityManager.createQuery("SELECT u FROM User u WHERE u.name LIKE :criteria", User.class);
        query.setParameter("criteria", "%" + criteria + "%");
        List<User> users = query.getResultList();
        logger.info("Users found: " + users.size());
        return users;
    }

    public long countUsers() {
        TypedQuery<Long> query = entityManager.createQuery("SELECT COUNT(u) FROM User u", Long.class);
        long count = query.getSingleResult();
        logger.info("Total users count: " + count);
        return count;
    }

    public boolean checkLoginExists(String login) {
        TypedQuery<Long> query = entityManager.createQuery("SELECT COUNT(u) FROM User u WHERE u.login = :login", Long.class);
        query.setParameter("login", login);
        long count = query.getSingleResult();
        logger.info("Login exists: " + (count > 0));
        return count > 0;
    }

    public boolean checkEmailExists(String email) {
        TypedQuery<Long> query = entityManager.createQuery("SELECT COUNT(u) FROM User u WHERE u.email = :email", Long.class);
        query.setParameter("email", email);
        long count = query.getSingleResult();
        logger.info("Email exists: " + (count > 0));
        return count > 0;
    }

    public User getUserByActivationHash(String activationHash) {
        TypedQuery<User> query = entityManager.createQuery("SELECT u FROM User u WHERE u.activationHash = :activationHash", User.class);
        query.setParameter("activationHash", activationHash);
        User user = query.getSingleResult();
        logger.info("User retrieved by activation hash: " + user);
        return user;
    }

    public List<User> getUserContacts(Long userId) {
        TypedQuery<User> query = entityManager.createQuery("SELECT c FROM User u JOIN u.contacts c WHERE u.id = :userId", User.class);
        query.setParameter("userId", userId);
        List<User> contacts = query.getResultList();
        logger.info("Contacts retrieved for user ID " + userId + ": " + contacts.size());
        return contacts;
    }

    // Additional methods for user authentication and password management can be added here
}

