public abstract class AbstractDatabaseAction {

    protected Connection connection;
    protected PreparedStatement preparedStatement;
    protected ResultSet resultSet;
    protected Map<String, Object> requestAttributes = new HashMap<>();

    private static final Map<Class<?>, String> typeMapping = new HashMap<>();

    static {
        typeMapping.put(String.class, "VARCHAR");
        typeMapping.put(Integer.class, "INTEGER");
        typeMapping.put(Long.class, "BIGINT");
        typeMapping.put(Double.class, "DOUBLE");
        // Add more mappings as needed
    }

    public AbstractDatabaseAction(Connection connection) {
        this.connection = connection;
    }

    protected abstract void executeAction() throws SQLException;

    protected void setRequestAttribute(String key, Object value) {
        requestAttributes.put(key, value);
    }

    protected Object getRequestAttribute(String key) {
        return requestAttributes.get(key);
    }

    protected void prepareStatement(String sql) throws SQLException {
        preparedStatement = connection.prepareStatement(sql);
    }

    protected void setParameter(int index, Object value) throws SQLException {
        if (value instanceof String) {
            preparedStatement.setString(index, (String) value);
        } else if (value instanceof Integer) {
            preparedStatement.setInt(index, (Integer) value);
        } else if (value instanceof Long) {
            preparedStatement.setLong(index, (Long) value);
        } else if (value instanceof Double) {
            preparedStatement.setDouble(index, (Double) value);
        } else {
            // Handle other types or throw an exception
        }
    }

    protected ResultSet executeQuery() throws SQLException {
        resultSet = preparedStatement.executeQuery();
        return resultSet;
    }

    protected void executeUpdate() throws SQLException {
        preparedStatement.executeUpdate();
    }

    protected void closeResources() {
        try {
            if (resultSet != null) resultSet.close();
            if (preparedStatement != null) preparedStatement.close();
            if (connection != null) connection.close();
        } catch (SQLException e) {
            // Log exception
        }
    }

    protected String getSqlType(Class<?> clazz) {
        return typeMapping.get(clazz);
    }
}

public class MockConsumer<K, V> {
    private final Set<String> subscriptions = ConcurrentHashMap.newKeySet();
    private final Map<String, List<ConsumerRecord<K, V>>> records = new HashMap<>();
    private final Map<String, Long> offsets = new HashMap<>();
    private final Map<String, Exception> exceptions = new HashMap<>();
    private boolean paused = false;

    public void subscribe(List<String> topics) {
        subscriptions.addAll(topics);
    }

    public void assign(List<String> partitions) {
        // Code smell: No validation of partitions
        for (String partition : partitions) {
            records.putIfAbsent(partition, new ArrayList<>());
            offsets.putIfAbsent(partition, 0L);
        }
    }

    public void addRecord(String topic, K key, V value) {
        records.computeIfAbsent(topic, k -> new ArrayList<>()).add(new ConsumerRecord<>(topic, key, value));
    }

    public List<ConsumerRecord<K, V>> poll() {
        if (paused) {
            return Collections.emptyList();
        }
        List<ConsumerRecord<K, V>> polledRecords = new ArrayList<>();
        for (String topic : subscriptions) {
            List<ConsumerRecord<K, V>> topicRecords = records.getOrDefault(topic, Collections.emptyList());
