public class ZkCallbackHandler implements IZkChildListener, IZkDataListener {
    private final Map<ChangeType, ChildDataListener> childListeners = new HashMap<>();
    private final Map<ChangeType, DataListener> dataListeners = new HashMap<>();
    private long lastNotificationTimestamp;

    public ZkCallbackHandler() {
        // Initialization logic
    }

    @Override
    public void handleChildChange(String parentPath, List<String> currentChilds) throws Exception {
        // Handle child change notifications
        for (ChangeType type : ChangeType.values()) {
            ChildDataListener listener = childListeners.get(type);
            if (listener != null) {
                listener.childChanged(parentPath, currentChilds);
            }
        }
        updateLastNotificationTimestamp();
    }

    @Override
    public void handleDataChange(String dataPath, byte[] data) throws Exception {
        // Handle data change notifications
        for (ChangeType type : ChangeType.values()) {
            DataListener listener = dataListeners.get(type);
            if (listener != null) {
                listener.dataChanged(dataPath, data);
            }
        }
        updateLastNotificationTimestamp();
    }

    public void subscribeToChildChanges(ChangeType type, ChildDataListener listener) {
        childListeners.put(type, listener);
    }

    public void subscribeToDataChanges(ChangeType type, DataListener listener) {
        dataListeners.put(type, listener);
    }

    public void unsubscribeFromChildChanges(ChangeType type) {
        childListeners.remove(type);
    }

    public void unsubscribeFromDataChanges(ChangeType type) {
        dataListeners.remove(type);
    }

    private void updateLastNotificationTimestamp() {
        lastNotificationTimestamp = System.currentTimeMillis();
    }

    public long getLastNotificationTimestamp() {
        return lastNotificationTimestamp;
    }

    public void reset() {
        childListeners.clear();
        dataListeners.clear();
        lastNotificationTimestamp = 0;
    }
}

