public class SegmentWriter {
    private final SegmentStore segmentStore;
    private final ReentrantLock lock = new ReentrantLock();
    private final StringBuilder buffer = new StringBuilder();
    private int recordId;

    public SegmentWriter(SegmentStore segmentStore) {
        this.segmentStore = segmentStore;
        this.recordId = 0;
    }

    public void writeString(String data) {
        lock.lock();
        try {
            buffer.append(data);
            checkFlush();
        } finally {
            lock.unlock();
        }
    }

    public void writeList(List<String> dataList) {
        lock.lock();
        try {
            for (String data : dataList) {
                buffer.append(data);
            }
            checkFlush();
        } finally {
            lock.unlock();
        }
    }

    public void writeMap(Map<String, String> dataMap) {
        lock.lock();
        try {
            for (Map.Entry<String, String> entry : dataMap.entrySet()) {
                buffer.append(entry.getKey()).append(entry.getValue());
            }
            checkFlush();
        } finally {
            lock.unlock();
        }
    }

    public void writeNode(Node node) {
        lock.lock();
        try {
            buffer.append(node.toString());
            checkFlush();
        } finally {
            lock.unlock();
        }
    }

    private void checkFlush() {
        if (buffer.length() >= 1024) {
            flush();
        }
    }

    private void flush() {
        segmentStore.storeSegment(recordId++, buffer.toString());
        buffer.setLength(0);
    }

    public void close() {
        lock.lock();
        try {
            if (buffer.length() > 0) {
                flush();
            }
        } finally {
            lock.unlock();
        }
    }
}

public class ElasticRestIndexWriter implements IndexWriter {
    private static final Logger logger = LoggerFactory.getLogger(ElasticRestIndexWriter.class);
    private JestClient client;
    private List<Action> bulkActions;
    private int bulkLimit;
    private String host;
    private int port;
    private String username;
    private String password;
    private boolean sslEnabled;

    public ElasticRestIndexWriter(String host, int port, String username, String password, boolean sslEnabled, int bulkLimit) {
        this.host = host;
        this.port = port;
        this.username = username;
        this.password = password;
        this.sslEnabled = sslEnabled;
        this.bulkLimit = bulkLimit;
        this.bulkActions = new ArrayList<>();
        openConnection();
    }

    private void openConnection() {
        JestClientFactory factory = new JestClientFactory();
        // Code smell: Hardcoded SSL configuration
        factory.setHttpClientConfig(new HttpClientConfig.Builder(getUrl())
                .multiThreaded(true)
                .defaultCredentials(username, password)
                .sslSocketFactory(sslEnabled ? getSslSocketFactory() : null)
                .build());
        client = factory.getObject();
        logger.info("Connected to Elasticsearch at {}", getUrl());
    }

    private String getUrl() {
        return (sslEnabled ? "https://" : "http://") + host + ":" + port;
    }

    public void writeDocument(String index, String type, String id, String json) {
        Action action = new Index.Builder(json).index(index).type(type).id(id).build();
        addAction(action);
    }

    public void updateDocument(String index, String type, String id, String json) {
        Action action = new Update.Builder(json).index(index).type(type).id(id).build();
        addAction(action);
    }

    public void deleteDocument(String index, String type, String id) {
        Action action = new Delete.Builder(id).index(index).type(type).build();
        addAction(action);
    }

    private void addAction(Action action) {
        bulkActions.add(action);
        if (bulkActions.size() >= bulkLimit) {
            commitBulk();
        }
    }

    public void commitBulk() {
        if (!bulkActions.isEmpty()) {
            Bulk bulk = new Bulk.Builder().addAction(bulkActions).build();
            try {
                JestResult result = client.execute(bulk);
                if (result.isSucceeded()) {
                    logger.info("Bulk operation succeeded");
                } else {
                    logger.error("Bulk operation failed: {}", result.getErrorMessage());
                }
            } catch (Exception e) {
                logger.error("Error executing bulk operation", e);
            } finally {
                bulkActions.clear();
            }
        }
    }

    public void close() {
        if (client != null) {
            client.shutdownClient();
            logger.info("Elasticsearch client closed");
        }
    }
}

