public final class AnnotationUtil {

    private AnnotationUtil() {
        throw new UnsupportedOperationException("Utility class cannot be instantiated");
    }

    public static boolean hasAnnotation(Method method, Class<? extends Annotation> annotationClass) {
        return method.isAnnotationPresent(annotationClass);
    }

    public static <T extends Annotation> T getAnnotation(Method method, Class<T> annotationClass) {
        return method.getAnnotation(annotationClass);
    }

    public static boolean hasParameterAnnotation(Method method, int parameterIndex, Class<? extends Annotation> annotationClass) {
        Parameter[] parameters = method.getParameters();
        if (parameterIndex < 0 || parameterIndex >= parameters.length) {
            throw new IndexOutOfBoundsException("Parameter index out of bounds");
        }
        return parameters[parameterIndex].isAnnotationPresent(annotationClass);
    }

    public static <T extends Annotation> T getParameterAnnotation(Method method, int parameterIndex, Class<T> annotationClass) {
        Parameter[] parameters = method.getParameters();
        if (parameterIndex < 0 || parameterIndex >= parameters.length) {
            throw new IndexOutOfBoundsException("Parameter index out of bounds");
        }
        return parameters[parameterIndex].getAnnotation(annotationClass);
    }

    public static Set<Annotation> getAnnotations(Method method) {
        Set<Annotation> annotations = new HashSet<>();
        for (Annotation annotation : method.getAnnotations()) {
            annotations.add(annotation);
        }
        return annotations;
    }

    public static boolean areAnnotationsEqual(Annotation a1, Annotation a2) {
        if (a1 == null || a2 == null) {
            return false;
        }
        return a1.annotationType().equals(a2.annotationType()) && a1.equals(a2);
    }

    public static Set<Annotation> extractAnnotationsFromSet(Set<Method> methods) {
        Set<Annotation> allAnnotations = new HashSet<>();
        for (Method method : methods) {
            for (Annotation annotation : method.getAnnotations()) {
                allAnnotations.add(annotation);
            }
        }
        return allAnnotations;
    }
}

public class BlockRealMatrix extends AbstractRealMatrix implements Serializable {
    private double[][] blocks;
    private int blockSize;
    private int rows;
    private int columns;

    public BlockRealMatrix(int rows, int columns, int blockSize) {
        this.rows = rows;
        this.columns = columns;
        this.blockSize = blockSize;
        this.blocks = new double[(rows + blockSize - 1) / blockSize][(columns + blockSize - 1) / blockSize][blockSize][blockSize];
    }

    public BlockRealMatrix(double[][] data) {
        this.rows = data.length;
        this.columns = data[0].length;
        this.blockSize = 2; // Default block size
        this.blocks = new double[(rows + blockSize - 1) / blockSize][(columns + blockSize - 1) / blockSize][blockSize][blockSize];
        // Fill blocks from data
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                setEntry(i, j, data[i][j]);
            }
        }
    }

    @Override
    public double getEntry(int row, int column) {
        int blockRow = row / blockSize;
        int blockColumn = column / blockSize;
        int indexInBlockRow = row % blockSize;
        int indexInBlockColumn = column % blockSize;
        return blocks[blockRow][blockColumn][indexInBlockRow][indexInBlockColumn];
    }

    @Override
    public void setEntry(int row, int column, double value) {
        int blockRow = row / blockSize;
        int blockColumn = column / blockSize;
        int indexInBlockRow = row % blockSize;
        int indexInBlockColumn = column % blockSize;
        blocks[blockRow][blockColumn][indexInBlockRow][indexInBlockColumn] = value;
    }

    public BlockRealMatrix add(BlockRealMatrix m) {
        checkMatrixDimensions(m);
        BlockRealMatrix result = new BlockRealMatrix(rows, columns, blockSize);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                result.setEntry(i, j, this.getEntry(i, j) + m.getEntry(i, j));
            }
        }
        return result;
    }

    public BlockRealMatrix subtract(BlockRealMatrix m) {
        checkMatrixDimensions(m);
        BlockRealMatrix result = new BlockRealMatrix(rows, columns, blockSize);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                result.setEntry(i, j, this.getEntry(i, j) - m.getEntry(i, j));
            }
        }
        return result;
    }

    public BlockRealMatrix multiply(BlockRealMatrix m) {
        checkMatrixMultiplicationDimensions(m);
        BlockRealMatrix result = new BlockRealMatrix(rows, m.columns, blockSize);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < m.columns; j++) {
                double sum = 0;
                for (int k = 0; k < columns; k++) {
                    sum += this.getEntry(i, k) * m.getEntry(k, j);
                }
                result.setEntry(i, j, sum);
            }
        }
        return result;
    }

    public double frobeniusNorm() {
        double sum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                sum += Math.pow(getEntry(i, j), 2);
            }
        }
        return Math.sqrt(sum);
    }

    public BlockRealMatrix transpose() {
        BlockRealMatrix result = new BlockRealMatrix(columns, rows, blockSize);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                result.setEntry(j, i, this.getEntry(i, j));
            }
        }
        return result;
    }

    private void checkMatrixDimensions(BlockRealMatrix m) {
        if (this.rows != m.rows || this.columns != m.columns) {
            throw new IllegalArgumentException("Matrix dimensions do not match.");
        }
    }

    private void checkMatrixMultiplicationDimensions(BlockRealMatrix m) {
        if (this.columns != m.rows) {
            throw new IllegalArgumentException("Matrix dimensions do not allow multiplication.");
        }
    }
}

