public class AutoRebalanceTester {
    private final int maxPartitionsPerNode;
    private final Set<String> liveNodes;
    private final Map<String, List<String>> nodePartitions;
    private final Random random;
    private final AtomicInteger iterationCounter;

    public AutoRebalanceTester(int maxPartitionsPerNode) {
        this.maxPartitionsPerNode = maxPartitionsPerNode;
        this.liveNodes = new HashSet<>();
        this.nodePartitions = new HashMap<>();
        this.random = new Random();
        this.iterationCounter = new AtomicInteger(0);
    }

    public void addNode(String nodeId) {
        liveNodes.add(nodeId);
        nodePartitions.putIfAbsent(nodeId, new ArrayList<>());
    }

    public void removeNode(String nodeId) {
        liveNodes.remove(nodeId);
        nodePartitions.remove(nodeId);
    }

    public void resurrectNode(String nodeId) {
        if (!liveNodes.contains(nodeId)) {
            liveNodes.add(nodeId);
            nodePartitions.putIfAbsent(nodeId, new ArrayList<>());
        }
    }

    public void rebalance() {
        List<String> partitions = new ArrayList<>();
        for (int i = 0; i < 100; i++) {
            partitions.add("partition-" + i);
        }

        for (String node : liveNodes) {
            nodePartitions.get(node).clear();
        }

        for (String partition : partitions) {
            String assignedNode = getRandomLiveNode();
            if (assignedNode != null) {
                nodePartitions.get(assignedNode).add(partition);
            }
        }

        logResults();
    }

    private String getRandomLiveNode() {
        List<String> nodes = new ArrayList<>(liveNodes);
        if (nodes.isEmpty()) return null;
        return nodes.get(random.nextInt(nodes.size()));
    }

    private void logResults() {
        int iteration = iterationCounter.incrementAndGet();
        System.out.println("Iteration " + iteration + ":");
        for (Map.Entry<String, List<String>> entry : nodePartitions.entrySet()) {
            String node = entry.getKey();
            List<String> partitions = entry.getValue();
            System.out.println("Node " + node + " has partitions: " + partitions);
            if (partitions.size() > maxPartitionsPerNode) {
                System.out.println("Error: Node " + node + " exceeds max partitions.");
            }
        }
        System.out.println();
    }

    public static void main(String[] args) {
        AutoRebalanceTester tester = new AutoRebalanceTester(5);
        tester.addNode("node1");
        tester.addNode("node2");
        tester.addNode("node3");

        for (int i = 0; i < 10; i++) {
            tester.rebalance();
            if (i % 3 == 0) {
                tester.removeNode("node" + (i % 3 + 1));
            }
            if (i % 4 == 0) {
                tester.resurrectNode("node" + (i % 3 + 1));
            }
        }
    }
}

