public class TelnetInputStream extends BufferedInputStream implements Runnable {
    private final Queue<Character> charQueue = new ConcurrentLinkedQueue<>();
    private volatile boolean running = true;
    private final TelnetClient telnetClient;

    public TelnetInputStream(InputStream in, TelnetClient client) {
        super(in);
        this.telnetClient = client;
    }

    @Override
    public void run() {
        try {
            while (running) {
                int readByte = read();
                if (readByte == -1) {
                    break;
                }
                processByte((char) readByte);
            }
        } catch (IOException e) {
            handleError(e);
        } finally {
            closeStream();
        }
    }

    private void processByte(char readByte) {
        if (readByte == (char) 255) { // IAC
            handleIAC();
        } else {
            charQueue.offer(readByte);
            telnetClient.notifyInputEvent(readByte);
        }
    }

    private void handleIAC() {
        // Handle IAC commands and suboptions
        // Code smells: This method could become too complex if not managed properly
    }

    private void handleError(IOException e) {
        // Error handling logic
        // Code smells: Error handling could be more robust
    }

    public synchronized char readChar() throws IOException {
        while (charQueue.isEmpty()) {
            try {
                wait();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new IOException("Thread interrupted", e);
            }
        }
        return charQueue.poll();
    }

    public void stop() {
        running = false;
        interrupt();
    }

    private void closeStream() {
        try {
            super.close();
        } catch (IOException e) {
            handleError(e);
        }
    }
}

