        paintings.add(painting1);
        paintings.remove(painting1);
        assertEquals(0, paintings.size());
        assertFalse(paintings.contains(painting1));
    }

    @Test
    void testAddMultiplePaintings() {
        paintings.add(painting1);
        paintings.add(painting2);
