public class MetadataDocumentXmlSerializer {

    private XMLStreamWriter xmlWriter;

    public MetadataDocumentXmlSerializer(XMLStreamWriter xmlWriter) {
        this.xmlWriter = xmlWriter;
    }

    public void serialize(ServiceMetadata metadata) throws Exception {
        xmlWriter.writeStartDocument();
        xmlWriter.writeStartElement("edmx:Edmx");
        writeVersion();
        writeDataServices(metadata);
        xmlWriter.writeEndElement(); // edmx:Edmx
        xmlWriter.writeEndDocument();
    }

    private void writeVersion() throws Exception {
        xmlWriter.writeStartElement("edmx:Version");
        xmlWriter.writeCharacters("4.0");
        xmlWriter.writeEndElement(); // edmx:Version
    }

    private void writeDataServices(ServiceMetadata metadata) throws Exception {
        xmlWriter.writeStartElement("edmx:DataServices");
        writeSchemas(metadata.getSchemas());
        xmlWriter.writeEndElement(); // edmx:DataServices
    }

    private void writeSchemas(List<Schema> schemas) throws Exception {
        for (Schema schema : schemas) {
            xmlWriter.writeStartElement("Schema");
            xmlWriter.writeAttribute("Namespace", schema.getNamespace());
            writeEntityTypes(schema.getEntityTypes());
            writeComplexTypes(schema.getComplexTypes());
            writeActions(schema.getActions());
            writeFunctions(schema.getFunctions());
            writeAnnotations(schema.getAnnotations());
            xmlWriter.writeEndElement(); // Schema
        }
    }

    private void writeEntityTypes(List<EntityType> entityTypes) throws Exception {
        for (EntityType entityType : entityTypes) {
            xmlWriter.writeStartElement("EntityType");
            xmlWriter.writeAttribute("Name", entityType.getName());
            writeProperties(entityType.getProperties());
            writeNavigationProperties(entityType.getNavigationProperties());
            xmlWriter.writeEndElement(); // EntityType
        }
    }

    private void writeProperties(List<Property> properties) throws Exception {
        for (Property property : properties) {
            xmlWriter.writeStartElement("Property");
            xmlWriter.writeAttribute("Name", property.getName());
            xmlWriter.writeAttribute("Type", property.getType());
            xmlWriter.writeEndElement(); // Property
        }
    }

    private void writeNavigationProperties(List<NavigationProperty> navigationProperties) throws Exception {
        for (NavigationProperty navProperty : navigationProperties) {
            xmlWriter.writeStartElement("NavigationProperty");
            xmlWriter.writeAttribute("Name", navProperty.getName());
            xmlWriter.writeAttribute("Type", navProperty.getType());
            xmlWriter.writeEndElement(); // NavigationProperty
        }
    }

    private void writeComplexTypes(List<ComplexType> complexTypes) throws Exception {
        for (ComplexType complexType : complexTypes) {
            xmlWriter.writeStartElement("ComplexType");
            xmlWriter.writeAttribute("Name", complexType.getName());
            writeProperties(complexType.getProperties());
            xmlWriter.writeEndElement(); // ComplexType
        }
    }

    private void writeActions(List<Action> actions) throws Exception {
        for (Action action : actions) {
            xmlWriter.writeStartElement("Action");
            xmlWriter.writeAttribute("Name", action.getName());
            xmlWriter.writeEndElement(); // Action
        }
    }

    private void writeFunctions(List<Function> functions) throws Exception {
        for (Function function : functions) {
            xmlWriter.writeStartElement("Function");
            xmlWriter.writeAttribute("Name", function.getName());
            xmlWriter.writeEndElement(); // Function
        }
    }

    private void writeAnnotations(List<Annotation> annotations) throws Exception {
        for (Annotation annotation : annotations) {
            xmlWriter.writeStartElement("Annotation");
            xmlWriter.writeAttribute("Term", annotation.getTerm());
            xmlWriter.writeCharacters(annotation.getValue());
            xmlWriter.writeEndElement(); // Annotation
        }
    }
}

