public class CpioArchiveEntry implements ArchiveEntry {
    private String name;
    private long fileSize;
    private int fileType;
    private long modificationTime;
    private int uid;
    private int gid;
    private int headerSize;
    private int alignmentBoundary;
    private int checksum;
    private String fileFormat;

    public CpioArchiveEntry(String name, long fileSize) {
        this.name = name;
        this.fileSize = fileSize;
        this.fileType = 0; // Default to regular file
        this.modificationTime = System.currentTimeMillis();
        this.uid = 0; // Default UID
        this.gid = 0; // Default GID
        this.headerSize = 0; // Default header size
        this.alignmentBoundary = 4; // Default alignment boundary
        this.checksum = 0; // Default checksum
        this.fileFormat = "default"; // Default file format
    }

    public CpioArchiveEntry(String name, long fileSize, int fileType) {
        this(name, fileSize);
        this.fileType = fileType;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public long getFileSize() {
        return fileSize;
    }

    public void setFileSize(long fileSize) {
        this.fileSize = fileSize;
    }

    public int getFileType() {
        return fileType;
    }

    public void setFileType(int fileType) {
        this.fileType = fileType;
    }

    public long getModificationTime() {
        return modificationTime;
    }

    public void setModificationTime(long modificationTime) {
        this.modificationTime = modificationTime;
    }

    public int getUid() {
        return uid;
    }

    public void setUid(int uid) {
        this.uid = uid;
    }

    public int getGid() {
        return gid;
    }

    public void setGid(int gid) {
        this.gid = gid;
    }

    public int getHeaderSize() {
        return headerSize;
    }

    public void setHeaderSize(int headerSize) {
        this.headerSize = headerSize;
    }

    public int getAlignmentBoundary() {
        return alignmentBoundary;
    }

    public void setAlignmentBoundary(int alignmentBoundary) {
        this.alignmentBoundary = alignmentBoundary;
    }

    public int getChecksum() {
        return checksum;
    }

    public void setChecksum(int checksum) {
        this.checksum = checksum;
    }

    public String getFileFormat() {
        return fileFormat;
    }

    public void setFileFormat(String fileFormat) {
        this.fileFormat = fileFormat;
    }

    public boolean isDirectory() {
        return (fileType & 0x4000) != 0; // Check for directory type
    }

    public boolean isRegularFile() {
        return (fileType & 0x8000) != 0; // Check for regular file type
    }

    public boolean isSymbolicLink() {
        return (fileType & 0xA000) != 0; // Check for symbolic link type
    }

    public int calculatePadding() {
        return (int) ((alignmentBoundary - (headerSize % alignmentBoundary)) % alignmentBoundary);
    }

    @Override
    public int hashCode() {
        return name.hashCode();
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof CpioArchiveEntry)) return false;
        CpioArchiveEntry other = (CpioArchiveEntry) obj;
        return name.equals(other.name);
    }
}

