public class URL implements Serializable {
    private static final long serialVersionUID = 1L;

    private String protocol;
    private String host;
    private int port;
    private String path;
    private String query;
    private String reference;

    @Deprecated
    public URL(String url) throws MalformedURLException {
        // Deprecated constructor for backward compatibility
        parse(url);
    }

    public URL(String protocol, String host, int port, String path, String query, String reference) {
        this.protocol = protocol;
        this.host = host;
        this.port = port;
        this.path = normalizePath(path);
        this.query = query;
        this.reference = reference;
    }

    private void parse(String url) throws MalformedURLException {
        // Parsing logic (simplified)
        String[] parts = url.split("\\?");
        String[] urlParts = parts[0].split("://");
        if (urlParts.length != 2) throw new MalformedURLException("Invalid URL format");

        this.protocol = urlParts[0];
        String[] hostParts = urlParts[1].split("/", 2);
        String[] hostPort = hostParts[0].split(":");
        this.host = hostPort[0];
        this.port = hostPort.length > 1 ? Integer.parseInt(hostPort[1]) : -1;
        this.path = hostParts.length > 1 ? "/" + hostParts[1] : "";
        this.query = parts.length > 1 ? parts[1] : null;
    }

    private String normalizePath(String path) {
        // Normalization logic (simplified)
        return path.replaceAll("//+", "/");
    }

    public String getProtocol() {
        return protocol;
    }

    public String getHost() {
        return host;
    }

    public int getPort() {
        return port;
    }

    public String getPath() {
        return path;
    }

    public String getQuery() {
        return query;
    }

    public String getReference() {
        return reference;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof URL)) return false;
        URL other = (URL) obj;
        return protocol.equals(other.protocol) && host.equals(other.host) && port == other.port &&
               path.equals(other.path) && (query == null ? other.query == null : query.equals(other.query)) &&
               (reference == null ? other.reference == null : reference.equals(other.reference));
    }

    @Override
    public int hashCode() {
        int result = protocol.hashCode();
        result = 31 * result + host.hashCode();
        result = 31 * result + port;
        result = 31 * result + path.hashCode();
        result = 31 * result + (query != null ? query.hashCode() : 0);
        result = 31 * result + (reference != null ? reference.hashCode() : 0);
        return result;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append(protocol).append("://").append(host);
        if (port != -1) sb.append(":").append(port);
        sb.append(path);
        if (query != null) sb.append("?").append(query);
        if (reference != null) sb.append("#").append(reference);
        return sb.toString();
    }
}

