public abstract class BaseDataStreamMarshaller implements DataStreamMarshaller {

    private Map<Class<?>, byte[]> cache = new HashMap<>();

    protected byte[] marshal(Object obj) throws IOException {
        if (obj == null) {
            return null;
        }
        if (cache.containsKey(obj.getClass())) {
            return cache.get(obj.getClass());
        }
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(obj);
            byte[] data = baos.toByteArray();
            cache.put(obj.getClass(), data);
            return data;
        }
    }

    protected Object unmarshal(byte[] data, Class<?> clazz) throws IOException, ClassNotFoundException {
        if (data == null) {
            return null;
        }
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            return clazz.cast(ois.readObject());
        }
    }

    protected byte[] marshalException(Exception e) throws IOException {
        return marshal(e);
    }

    protected Exception unmarshalException(byte[] data) throws IOException, ClassNotFoundException {
        return (Exception) unmarshal(data, Exception.class);
    }

    protected byte[] marshalStackTrace(Throwable t) throws IOException {
        return marshal(t.getStackTrace());
    }

    protected StackTraceElement[] unmarshalStackTrace(byte[] data) throws IOException, ClassNotFoundException {
        return (StackTraceElement[]) unmarshal(data, StackTraceElement[].class);
    }

    // Abstract methods to be implemented by subclasses
    public abstract void tightMarshal(Object obj, byte[] output) throws IOException;

    public abstract Object tightUnmarshal(byte[] input) throws IOException, ClassNotFoundException;

    public abstract void looseMarshal(Object obj, byte[] output) throws IOException;

    public abstract Object looseUnmarshal(byte[] input) throws IOException, ClassNotFoundException;
}

