class FailoverUriPoolTest {
    private FailoverUriPool uriPool;

    @Before
    public void setUp() {
        uriPool = new FailoverUriPool();
    }

    @Test
    public void testEmptyPool() {
        assertTrue(uriPool.isEmpty());
    }

    @Test
    public void testAddUri() {
        uriPool.add("http://example.com");
        assertFalse(uriPool.isEmpty());
    }

    @Test
    public void testRemoveUri() {
        uriPool.add("http://example.com");
        uriPool.remove("http://example.com");
        assertTrue(uriPool.isEmpty());
    }

    @Test
    public void testAddDuplicateUri() {
        uriPool.add("http://example.com");
        uriPool.add("http://example.com");
        assertEquals(1, uriPool.size());
    }

    @Test
    public void testRandomizedBehavior() {
        uriPool.add("http://example.com");
        uriPool.add("http://example.org");
        uriPool.setRandomized(true);
        String uri = uriPool.getNextUri();
        assertTrue(uri.equals("http://example.com") || uri.equals("http://example.org"));
    }

    @Test
    public void testNonRandomizedBehavior() {
        uriPool.add("http://example.com");
        uriPool.add("http://example.org");
