public class UriBuilderImpl extends UriBuilder {
    private String scheme;
    private String host;
    private int port = -1;
    private String userInfo;
    private StringBuilder path = new StringBuilder();
    private Map<String, String> queryParams = new LinkedHashMap<>();
    private String fragment;

    @Override
    public UriBuilderImpl clone() {
        UriBuilderImpl clone = new UriBuilderImpl();
        clone.scheme = this.scheme;
        clone.host = this.host;
        clone.port = this.port;
        clone.userInfo = this.userInfo;
        clone.path = new StringBuilder(this.path);
        clone.queryParams.putAll(this.queryParams);
        clone.fragment = this.fragment;
        return clone;
    }

    @Override
    public UriBuilder scheme(String scheme) {
        this.scheme = scheme;
        return this;
    }

    @Override
    public UriBuilder host(String host) {
        this.host = host;
        return this;
    }

    @Override
    public UriBuilder port(int port) {
        this.port = port;
        return this;
    }

    @Override
    public UriBuilder userInfo(String userInfo) {
        this.userInfo = userInfo;
        return this;
    }

    @Override
    public UriBuilder path(String path) {
        if (this.path.length() > 0) {
            this.path.append("/");
        }
        this.path.append(path);
        return this;
    }

    @Override
    public UriBuilder queryParam(String name, String value) {
        queryParams.put(name, value);
        return this;
    }

    @Override
    public UriBuilder fragment(String fragment) {
        this.fragment = fragment;
        return this;
    }

    public URI build() throws URISyntaxException {
        StringBuilder uriString = new StringBuilder();
        if (scheme != null) {
            uriString.append(scheme).append("://");
        }
        if (userInfo != null) {
            uriString.append(userInfo).append("@");
        }
        if (host != null) {
            uriString.append(host);
        }
        if (port != -1) {
            uriString.append(":").append(port);
        }
        if (path.length() > 0) {
            uriString.append(path);
        }
        if (!queryParams.isEmpty()) {
            uriString.append("?");
            queryParams.forEach((key, value) -> uriString.append(key).append("=").append(value).append("&"));
            uriString.setLength(uriString.length() - 1); // Remove last '&'
        }
        if (fragment != null) {
            uriString.append("#").append(fragment);
        }
        return new URI(uriString.toString());
    }
}

