    @Test
    void testSerializationDeserialization() {
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        record.serialize(buffer);
        buffer.flip();

        DefaultRecord deserializedRecord = DefaultRecord.deserialize(buffer);
        assertEquals(record.getOffset(), deserializedRecord.getOffset());
        assertEquals(record.getSequence(), deserializedRecord.getSequence());
        assertEquals(record.getTimestamp(), deserializedRecord.getTimestamp());
        assertArrayEquals(record.getKey(), deserializedRecord.getKey());
        assertArrayEquals(record.getValue(), deserializedRecord.getValue());
        assertEquals(record.getHeaders(), deserializedRecord.getHeaders());
    }

