public class NetworkBrokerDetachTest {

    private BrokerService primaryBroker;
    private BrokerService networkedBroker;
    private Connection primaryConnection;
    private Connection networkedConnection;
    private Session primarySession;
    private Session networkedSession;
    private static final String QUEUE_NAME = "testQueue";

    @Before
    public void setUp() throws Exception {
        primaryBroker = createBroker("tcp://localhost:61616");
        networkedBroker = createBroker("tcp://localhost:61617");

        primaryBroker.start();
        networkedBroker.start();

        primaryConnection = createConnection("tcp://localhost:61616");
        networkedConnection = createConnection("tcp://localhost:61617");

        primarySession = primaryConnection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        networkedSession = networkedConnection.createSession(false, Session.AUTO_ACKNOWLEDGE);

        primaryConnection.start();
        networkedConnection.start();
    }

    private BrokerService createBroker(String uri) throws Exception {
        BrokerService broker = new BrokerService();
        broker.addConnector(uri);
        return broker;
    }

    private Connection createConnection(String uri) throws JMSException {
        ActiveMQConnectionFactory factory = new ActiveMQConnectionFactory(uri);
        return factory.createConnection();
    }

    @After
    public void tearDown() throws Exception {
        if (primaryConnection != null) {
            primaryConnection.close();
        }
        if (networkedConnection != null) {
            networkedConnection.close();
        }
        if (primaryBroker != null) {
            primaryBroker.stop();
        }
        if (networkedBroker != null) {
            networkedBroker.stop();
        }
    }

    @Test
    public void testDetachConsumers() throws Exception {
        // Create a consumer on the networked broker
        MessageConsumer consumer = networkedSession.createConsumer(new ActiveMQQueue(QUEUE_NAME));

        // Send a message from the primary broker
        MessageProducer producer = primarySession.createProducer(new ActiveMQQueue(QUEUE_NAME));
        producer.send(primarySession.createTextMessage("Test Message"));

        // Verify consumer count
        assertEquals(1, getConsumerCount(networkedBroker, QUEUE_NAME));

        // Detach consumer
        consumer.close();

        // Verify consumer count after detachment
        assertEquals(0, getConsumerCount(networkedBroker, QUEUE_NAME));
    }

    @Test
    public void testDurableSubscription() throws Exception {
        String clientId = "testClient";
        networkedConnection.setClientID(clientId);
        Topic topic = networkedSession.createTopic("testTopic");
        MessageConsumer durableConsumer = networkedSession.createDurableSubscriber(topic, "durableSub");

        // Send a message to the topic
        MessageProducer producer = primarySession.createProducer(topic);
        producer.send(primarySession.createTextMessage("Durable Message"));

        // Close the connection and restart the broker
        networkedConnection.close();
        networkedBroker.stop();
        networkedBroker.start();
        networkedConnection = createConnection("tcp://localhost:61617");
        networkedConnection.setClientID(clientId);
        networkedConnection.start();

        // Receive the message
        Message message = durableConsumer.receive(1000);
        assertEquals("Durable Message", ((TextMessage) message).getText());
    }

    private int getConsumerCount(BrokerService broker, String queueName) throws Exception {
        return broker.getDestination(new ActiveMQQueue(queueName)).getConsumerCount();
    }
}

