public class GlyphSequence {
    private IntBuffer glyphs;
    private IntBuffer associations;
    private IntBuffer predications;

    public GlyphSequence(int size) {
        glyphs = IntBuffer.allocate(size);
        associations = IntBuffer.allocate(size);
        predications = IntBuffer.allocate(size);
    }

    public int getGlyph(int index) {
        return glyphs.get(index);
    }

    public void setGlyph(int index, int glyph) {
        glyphs.put(index, glyph);
    }

    public int getAssociation(int index) {
        return associations.get(index);
    }

    public void setAssociation(int index, int association) {
        associations.put(index, association);
    }

    public int getPredication(int index) {
        return predications.get(index);
    }

    public void setPredication(int index, int predication) {
        predications.put(index, predication);
    }

    public GlyphSequence clone() {
        GlyphSequence cloned = new GlyphSequence(glyphs.capacity());
        cloned.glyphs.put(glyphs);
        cloned.associations.put(associations);
        cloned.predications.put(predications);
        return cloned;
    }

    public boolean compareGlyphs(int index1, int index2) {
        return glyphs.get(index1) == glyphs.get(index2);
    }

    public GlyphSequence concatenate(GlyphSequence other) {
        GlyphSequence concatenated = new GlyphSequence(this.glyphs.capacity() + other.glyphs.capacity());
        concatenated.glyphs.put(this.glyphs);
        concatenated.glyphs.put(other.glyphs);
        concatenated.associations.put(this.associations);
        concatenated.associations.put(other.associations);
        concatenated.predications.put(this.predications);
        concatenated.predications.put(other.predications);
        return concatenated;
    }

    public int[] toGlyphArray() {
        int[] array = new int[glyphs.remaining()];
        glyphs.get(array);
        return array;
    }

    public int[] toAssociationArray() {
        int[] array = new int[associations.remaining()];
        associations.get(array);
        return array;
    }

    public int[] toPredicationArray() {
        int[] array = new int[predications.remaining()];
        predications.get(array);
        return array;
    }

    public void createIdentityAssociations() {
        for (int i = 0; i < glyphs.capacity(); i++) {
            associations.put(i, i);
        }
    }
}

public class Poller implements Runnable {
    private final List<Socket> activeSockets = new ArrayList<>();
    private volatile boolean running = true;
    private final long timeout;

    public Poller(long timeout) {
        this.timeout = timeout;
    }

    public synchronized void addSocket(Socket socket) {
        activeSockets.add(socket);
    }

    public synchronized void removeSocket(Socket socket) {
        activeSockets.remove(socket);
    }

    public synchronized int getConnectionCount() {
        return activeSockets.size();
    }

    public void stop() {
        running = false;
    }

    @Override
    public void run() {
        while (running) {
            checkSockets();
            try {
                Thread.sleep(100); // Polling interval
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        cleanup();
    }

    private synchronized void checkSockets() {
        Iterator<Socket> iterator = activeSockets.iterator();
        while (iterator.hasNext()) {
            Socket socket = iterator.next();
            try {
                if (socket.getSoTimeout() > timeout) {
                    // Handle timeout logic
                    iterator.remove();
                    socket.close();
                } else {
                    // Process socket events (read/write)
                }
            } catch (IOException e) {
                iterator.remove();
                try {
                    socket.close();
                } catch (IOException ex) {
                    // Log error
                }
            }
        }
    }

    private synchronized void cleanup() {
        for (Socket socket : activeSockets) {
            try {
                socket.close();
            } catch (IOException e) {
                // Log error
            }
        }
        activeSockets.clear();
    }
}

public class BasicEvalNodeVisitor implements EvalNodeVisitor2 {

    private Stack<Object> contextStack = new Stack<>();

    @Override
    public Object visitConstant(ConstantEvalNode node) {
        return node.getValue();
    }

    @Override
    public Object visitBinaryOperation(BinaryOperationEvalNode node) {
        Object left = node.getLeft().accept(this);
        Object right = node.getRight().accept(this);
        switch (node.getOperator()) {
            case ADD:
                return (Double) left + (Double) right;
            case SUBTRACT:
                return (Double) left - (Double) right;
            case MULTIPLY:
                return (Double) left * (Double) right;
            case DIVIDE:
                return (Double) left / (Double) right;
            default:
                throw new UnsupportedOperationException("Unsupported operator: " + node.getOperator());
        }
    }

    @Override
    public Object visitUnaryOperation(UnaryOperationEvalNode node) {
        Object operand = node.getOperand().accept(this);
        switch (node.getOperator()) {
            case NEGATE:
                return -(Double) operand;
            default:
                throw new UnsupportedOperationException("Unsupported operator: " + node.getOperator());
        }
    }

    @Override
    public Object visitPredicate(PredicateEvalNode node) {
        Object left = node.getLeft().accept(this);
        Object right = node.getRight().accept(this);
        switch (node.getOperator()) {
            case EQUAL:
                return left.equals(right);
            case LESS_THAN:
                return (Double) left < (Double) right;
            case GREATER_THAN:
                return (Double) left > (Double) right;
            default:
                throw new UnsupportedOperationException("Unsupported operator: " + node.getOperator());
        }
    }

    @Override
    public Object visitFunctionCall(FunctionCallEvalNode node) {
        // Assuming function names are simple and known
        switch (node.getFunctionName()) {
            case "SUM":
                return node.getArguments().stream().map(arg -> arg.accept(this)).reduce(0.0, (a, b) -> (Double) a + (Double) b);
            default:
                throw new UnsupportedOperationException("Unsupported function: " + node.getFunctionName());
        }
    }

    @Override
    public Object visitCase(CaseEvalNode node) {
        for (CaseWhenEvalNode when : node.getWhenClauses()) {
            if ((Boolean) when.getCondition().accept(this)) {
                return when.getResult().accept(this);
            }
        }
        return node.getElseResult() != null ? node.getElseResult().accept(this) : null;
    }

    @Override
    public Object visitSubquery(SubqueryEvalNode node) {
        // Handle subquery evaluation logic
        return node.getQuery().accept(this);
    }
}

