public class AppendRecord extends AbstractRecord {
    private static final int BUFFER_SIZE = 1024;
    private byte[] buffer;
    private int currentSize;
    private String journal;
    private String producerId;
    private int revision;
    private OutputStream outputStream;

    public AppendRecord(String journal, String producerId, int revision) {
        this.journal = journal;
        this.producerId = producerId;
        this.revision = revision;
        this.buffer = new byte[BUFFER_SIZE];
        this.currentSize = 0;
        this.outputStream = null;
    }

    public void writeByte(byte value) throws JournalException {
        writeData(new byte[]{value});
    }

    public void writeChar(char value) throws JournalException {
        writeData(new byte[]{(byte) value});
    }

    public void writeBoolean(boolean value) throws JournalException {
        writeData(new byte[]{(byte) (value ? 1 : 0)});
    }

    public void writeInt(int value) throws JournalException {
        writeData(intToByteArray(value));
    }

    public void writeLong(long value) throws JournalException {
        writeData(longToByteArray(value));
    }

    public void writeString(String value) throws JournalException {
        writeData(value.getBytes());
    }

    public void writeByteArray(byte[] value) throws JournalException {
        writeData(value);
    }

    private void writeData(byte[] data) throws JournalException {
        if (currentSize + data.length > BUFFER_SIZE) {
            flushBuffer();
        }
        System.arraycopy(data, 0, buffer, currentSize, data.length);
        currentSize += data.length;
    }

    private void flushBuffer() throws JournalException {
        try {
            if (outputStream == null) {
                outputStream = new BufferedOutputStream(new FileOutputStream(journal, true));
            }
            outputStream.write(buffer, 0, currentSize);
            currentSize = 0;
        } catch (IOException e) {
            throw new JournalException("Error writing to journal", e);
        }
    }

    public void cancel() {
        currentSize = 0;
        if (outputStream != null) {
            try {
                outputStream.close();
            } catch (IOException e) {
                // Ignored
            }
            outputStream = null;
        }
    }

    public void close() throws JournalException {
        if (currentSize > 0) {
            flushBuffer();
        }
        if (outputStream != null) {
            try {
                outputStream.close();
            } catch (IOException e) {
                throw new JournalException("Error closing output stream", e);
            }
        }
    }

    private byte[] intToByteArray(int value) {
        return new byte[]{
            (byte) (value >> 24),
            (byte) (value >> 16),
            (byte) (value >> 8),
            (byte) value
        };
    }

    private byte[] longToByteArray(long value) {
        return new byte[]{
            (byte) (value >> 56),
            (byte) (value >> 48),
            (byte) (value >> 40),
            (byte) (value >> 32),
            (byte) (value >> 24),
            (byte) (value >> 16),
            (byte) (value >> 8),
            (byte) value
        };
    }

    public void read() throws JournalException {
        throw new JournalException("Reading from an appended record is not supported.");
    }
}

