public abstract class AbstractExecutable implements Executable, Idempotent {
    public enum State {
        RUNNING, SUCCEED, ERROR
    }

    private State state;
    private long startTime;
    private long endTime;
    private Map<String, Object> parameters;
    private Map<String, Object> metadata;

    public AbstractExecutable() {
        this.state = State.RUNNING;
        this.parameters = new HashMap<>();
        this.metadata = new HashMap<>();
    }

    public State getState() {
        return state;
    }

    public long getStartTime() {
        return startTime;
    }

    public long getEndTime() {
        return endTime;
    }

    public long getDuration() {
        return endTime - startTime;
    }

    public void setParameter(String key, Object value) {
        parameters.put(key, value);
    }

    public Object getParameter(String key) {
        return parameters.get(key);
    }

    public void setMetadata(String key, Object value) {
        metadata.put(key, value);
    }

    public Object getMetadata(String key) {
        return metadata.get(key);
    }

    public void execute() {
        try {
            startTime = System.currentTimeMillis();
            doWork();
            state = State.SUCCEED;
        } catch (Exception e) {
            state = State.ERROR;
            handleError(e);
        } finally {
            endTime = System.currentTimeMillis();
            notifyUsers();
        }
    }

    protected abstract void doWork() throws Exception;

    private void handleError(Exception e) {
        // Handle error logic, e.g., logging, retrying, etc.
    }

    private void notifyUsers() {
        // Notify users about the execution state change
    }

    @Override
    public boolean isIdempotent() {
        // Implement idempotency logic if needed
        return true;
    }
}

