public class Query {
    private Connection connection;
    private PreparedStatement preparedStatement;
    private CallableStatement callableStatement;
    private ResultSet resultSet;
    private String sql;
    private Map<Integer, Object> inputParameters = new HashMap<>();
    private Map<Integer, Integer> outputParameters = new HashMap<>();
    private static final Logger logger = Logger.getLogger(Query.class.getName());

    public Query(Connection connection) {
        this.connection = connection;
    }

    public void setSql(String sql) {
        this.sql = sql;
    }

    public void setInputParameter(int index, Object value) {
        inputParameters.put(index, value);
    }

    public void registerOutputParameter(int index, int sqlType) {
        outputParameters.put(index, sqlType);
    }

    public void execute() throws SQLException {
        try {
            if (sql.trim().toLowerCase().startsWith("call")) {
                callableStatement = connection.prepareCall(sql);
                for (Map.Entry<Integer, Object> entry : inputParameters.entrySet()) {
                    callableStatement.setObject(entry.getKey(), entry.getValue());
                }
                for (Map.Entry<Integer, Integer> entry : outputParameters.entrySet()) {
                    callableStatement.registerOutParameter(entry.getKey(), entry.getValue());
                }
                callableStatement.execute();
            } else {
                preparedStatement = connection.prepareStatement(sql);
                for (Map.Entry<Integer, Object> entry : inputParameters.entrySet()) {
                    preparedStatement.setObject(entry.getKey(), entry.getValue());
                }
                preparedStatement.executeUpdate();
            }
        } catch (SQLException e) {
            logger.log(Level.SEVERE, "SQL Error: " + e.getMessage(), e);
            throw e;
        } finally {
            closeResources();
        }
    }

    public ResultSet getResultSet() throws SQLException {
        if (preparedStatement != null) {
            resultSet = preparedStatement.getResultSet();
        } else if (callableStatement != null) {
            resultSet = callableStatement.getResultSet();
        }
        return resultSet;
    }

    public Object getOutputParameter(int index) throws SQLException {
        if (callableStatement != null) {
            return callableStatement.getObject(index);
        }
        return null;
    }

    public String serializeResultsToXML() throws SQLException {
        StringBuilder xmlBuilder = new StringBuilder();
        xmlBuilder.append("<results>");
        while (resultSet.next()) {
            xmlBuilder.append("<row>");
            ResultSetMetaData metaData = resultSet.getMetaData();
            for (int i = 1; i <= metaData.getColumnCount(); i++) {
                xmlBuilder.append("<").append(metaData.getColumnName(i)).append(">")
                          .append(resultSet.getString(i)).append("</").append(metaData.getColumnName(i)).append(">");
            }
            xmlBuilder.append("</row>");
        }
        xmlBuilder.append("</results>");
        return xmlBuilder.toString();
    }

    private void closeResources() {
        try {
            if (resultSet != null) resultSet.close();
            if (preparedStatement != null) preparedStatement.close();
            if (callableStatement != null) callableStatement.close();
        } catch (SQLException e) {
            logger.log(Level.WARNING, "Error closing resources: " + e.getMessage(), e);
        }
    }
}

