public class spanishStemmer extends AbstractSnowballStemmer {
    private static final String[] suffixes = { "ando", "iendo", "ar", "er", "ir", "ado", "ido", "ón", "ción", "sión", "mente" };

    public spanishStemmer() {
        super();
    }

    @Override
    public boolean equals(Object obj) {
        return obj instanceof spanishStemmer;
    }

    @Override
    public int hashCode() {
        return 31; // Arbitrary constant for hash code
    }

    public String stem(String word) {
        for (String suffix : suffixes) {
            if (word.endsWith(suffix)) {
                return applySuffixRule(word, suffix);
            }
        }
        return word; // No suffix matched
    }

    private String applySuffixRule(String word, String suffix) {
        int suffixLength = suffix.length();
        return word.substring(0, word.length() - suffixLength); // Remove suffix
    }

