        this.cite = cite;
        return this;
    }

    public DEL datetime(String datetime) {
        this.datetime = datetime;
        return this;
    }

    public DEL id(String id) {
        this.id = id;
        return this;
    }

    public DEL className(String className) {
        this.className = className;
        return this;
    }

    public DEL addContent(String content) {
        htmlContent.append(content);
        return this;
    }

    public DEL addElement(String element) {
        htmlContent.append("<").append(element).append("></").append(element).append(">");
        return this;
    }

    public DEL onclick(String onclick) {
        htmlContent.append(" onclick=\"").append(onclick).append("\"");
        return this;
    }

    public DEL onmouseover(String onmouseover) {
        htmlContent.append(" onmouseover=\"").append(onmouseover).append("\"");
        return this;
    }

    public String build() {
        StringBuilder result = new StringBuilder();
        result.append("<del");
        if (cite != null) result.append(" cite=\"").append(cite).append("\"");
        if (datetime != null) result.append(" datetime=\"").append(datetime).append("\"");
        if (id != null) result.append(" id=\"").append(id).append("\"");
        if (className != null) result.append(" class=\"").append(className).append("\"");
        result.append(">");
        result.append(htmlContent);
        result.append("</del>");
        return result.toString();
    }
}

public abstract class SymlinkBaseTest {

    protected Path targetFile;
    protected Path symlink;

    @Before
    public void setUp() throws IOException {
        targetFile = Files.createTempFile("targetFile", ".txt");
        Files.writeString(targetFile, "Sample content");
        symlink = Paths.get(targetFile.toString() + "_symlink");
    }

    @After
    public void tearDown() throws IOException {
        if (Files.exists(symlink)) {
            Files.delete(symlink);
        }
        if (Files.exists(targetFile)) {
            Files.delete(targetFile);
        }
    }

    @Test
    public void testCreateSymlink() throws IOException {
        Files.createSymbolicLink(symlink, targetFile);
        assert Files.isSymbolicLink(symlink);
        assert Files.readString(symlink).equals("Sample content");
    }

    @Test
    public void testDanglingSymlink() throws IOException {
        Files.createSymbolicLink(symlink, Paths.get("non_existent_file.txt"));
        assert !Files.exists(symlink);
    }

    @Test
    public void testDeleteSymlink() throws IOException {
        Files.createSymbolicLink(symlink, targetFile);
        Files.delete(symlink);
        assert !Files.exists(symlink);
    }

    @Test
    public void testRenameSymlink() throws IOException {
        Files.createSymbolicLink(symlink, targetFile);
        Path renamedSymlink = Paths.get(symlink.toString() + "_renamed");
        Files.move(symlink, renamedSymlink);
        assert Files.exists(renamedSymlink);
        assert Files.readString(renamedSymlink).equals("Sample content");
    }

    @Test
    public void testLinkToDirectory() throws IOException {
        Path dir = Files.createTempDirectory("testDir");
        Path dirSymlink = Paths.get(dir.toString() + "_symlink");
        Files.createSymbolicLink(dirSymlink, dir);
        assert Files.isSymbolicLink(dirSymlink);
        assert Files.exists(dirSymlink);
    }

    @Test
    public void testLinkExists() throws IOException {
        Files.createSymbolicLink(symlink, targetFile);
        try {
            Files.createSymbolicLink(symlink, targetFile);
        } catch (IOException e) {
            assert e.getMessage().contains("already exists");
        }
    }

    @Test
    public void testCheckSymlinkProperties() throws IOException {
        Files.createSymbolicLink(symlink, targetFile);
        assert Files.isSymbolicLink(symlink);
        assert Files.readAttributes(symlink, "basic:lastModifiedTime") != null;
    }
}

