public class IDLLexer extends CharScanner implements IDLTokenTypes, TokenStream {
    private Hashtable<String, Integer> literals;

    public IDLLexer(InputStream in) {
        super(in);
        initializeLiterals();
    }

    public IDLLexer(Reader in) {
        super(in);
        initializeLiterals();
    }

    public IDLLexer(InputBuffer buf) {
        super(buf);
        initializeLiterals();
    }

    private void initializeLiterals() {
        literals = new Hashtable<>();
        literals.put("switch", SWITCH);
        literals.put("typeprefix", TYPEPREFIX);
        literals.put("case", CASE);
        // Add other keywords as needed
    }

    public Token nextToken() {
        while (true) {
            int c = nextChar();
            switch (c) {
                case EOF:
                    return makeToken(EOF_TYPE);
                case ';':
                    return makeToken(SEMICOLON);
                case '(':
                    return makeToken(LPAREN);
                case ')':
                    return makeToken(RPAREN);
                // Add other cases for different token types
                default:
                    if (isWhitespace(c)) {
                        continue;
                    } else if (isIdentifierStart(c)) {
                        return identifier();
                    } else if (isLiteralStart(c)) {
                        return literal();
                    } else if (isCommentStart(c)) {
                        comment();
                        continue;
                    } else {
                        throw new RuntimeException("Unrecognized character: " + (char) c);
                    }
            }
        }
    }

    private Token identifier() {
        StringBuilder id = new StringBuilder();
        int c;
        while (isIdentifierPart(c = nextChar())) {
            id.append((char) c);
        }
        // Check if it's a keyword
        Integer tokenType = literals.get(id.toString());
        return makeToken(tokenType != null ? tokenType : IDENTIFIER, id.toString());
    }

    private Token literal() {
        StringBuilder lit = new StringBuilder();
        int c;
        while (isLiteralPart(c = nextChar())) {
            lit.append((char) c);
        }
        return makeToken(LITERAL, lit.toString());
    }

    private void comment() {
        // Logic to skip comments
        while (true) {
            int c = nextChar();
            if (c == EOF || c == '\n') {
                break;
            }
        }
    }

    private boolean isWhitespace(int c) {
        return Character.isWhitespace(c);
    }

    private boolean isIdentifierStart(int c) {
        return Character.isJavaIdentifierStart(c);
    }

    private boolean isIdentifierPart(int c) {
        return Character.isJavaIdentifierPart(c);
    }

    private boolean isLiteralStart(int c) {
