public class ServletWebRequest extends WebRequest {
    private static final Logger logger = Logger.getLogger(ServletWebRequest.class.getName());
    private final HttpServletRequest request;
    private final HttpServletResponse response;
    private final String filterPrefix;

    public ServletWebRequest(HttpServletRequest request, HttpServletResponse response, String filterPrefix) {
        this.request = request;
        this.response = response;
        this.filterPrefix = filterPrefix;
    }

    public String getClientUrl() {
        String url = request.getRequestURL().toString();
        logger.info("Client URL: " + url);
        return url;
    }

    public String getHeader(String name) {
        String header = request.getHeader(name);
        logger.info("Header: " + name + " = " + header);
        return header;
    }

    public String getParameter(String name) {
        String parameter = request.getParameter(name);
        logger.info("Parameter: " + name + " = " + parameter);
        return parameter;
    }

    public Map<String, String[]> getParameters() {
        Map<String, String[]> parameters = new HashMap<>();
        Enumeration<String> parameterNames = request.getParameterNames();
        while (parameterNames.hasMoreElements()) {
            String paramName = parameterNames.nextElement();
            parameters.put(paramName, request.getParameterValues(paramName));
        }
        logger.info("Parameters: " + parameters);
        return parameters;
    }

    public String getCookie(String name) {
        if (request.getCookies() != null) {
            for (javax.servlet.http.Cookie cookie : request.getCookies()) {
                if (cookie.getName().equals(name)) {
                    logger.info("Cookie: " + name + " = " + cookie.getValue());
                    return cookie.getValue();
                }
            }
        }
        logger.info("Cookie: " + name + " not found");
        return null;
    }

    public void setAttribute(String name, Object value) {
        request.setAttribute(name, value);
        logger.info("Attribute set: " + name + " = " + value);
    }

    public Object getAttribute(String name) {
        Object attribute = request.getAttribute(name);
        logger.info("Attribute: " + name + " = " + attribute);
        return attribute;
    }

    public boolean isAjaxRequest() {
        String ajaxHeader = request.getHeader("X-Requested-With");
        boolean isAjax = "XMLHttpRequest".equals(ajaxHeader);
        logger.info("Is AJAX request: " + isAjax);
        return isAjax;
    }

    public String getContextRelativeUrl(String relativeUrl) {
        String contextUrl = request.getContextPath() + filterPrefix + relativeUrl;
        logger.info("Context-relative URL: " + contextUrl);
        return contextUrl;
    }

    public boolean isMultipart() {
        boolean isMultipart = request.getContentType() != null && request.getContentType().startsWith("multipart/");
        logger.info("Is multipart request: " + isMultipart);
        return isMultipart;
    }
}

