public class HttpSendCompressedMessagesTest {

    private BrokerService broker;
    private Connection tcpConnection;
    private Connection httpConnection;
    private Session tcpSession;
    private Session httpSession;
    private Destination tcpDestination;
    private Destination httpDestination;

    @Before
    public void setUp() throws Exception {
        broker = new BrokerService();
        broker.addConnector("tcp://localhost:61616");
        broker.addConnector("http://localhost:8161");
        broker.start();

        ActiveMQConnectionFactory tcpFactory = new ActiveMQConnectionFactory("tcp://localhost:61616");
        ActiveMQConnectionFactory httpFactory = new ActiveMQConnectionFactory("http://localhost:8161");

        tcpConnection = tcpFactory.createConnection();
        httpConnection = httpFactory.createConnection();
        tcpConnection.start();
        httpConnection.start();

        tcpSession = tcpConnection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        httpSession = httpConnection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        tcpDestination = tcpSession.createQueue("testQueue");
        httpDestination = httpSession.createQueue("testQueue");
    }

    @After
    public void tearDown() throws Exception {
        tcpSession.close();
        httpSession.close();
        tcpConnection.close();
        httpConnection.close();
        broker.stop();
    }

    @Test
    public void testSendCompressedTextMessage() throws Exception {
        String originalMessage = "Hello, World!";
        byte[] compressedMessage = compress(originalMessage.getBytes());

        sendMessage(tcpSession, tcpDestination, compressedMessage);
        byte[] receivedMessage = receiveMessage(httpSession, httpDestination);

        assertNotNull(receivedMessage);
        assertEquals(originalMessage.length(), decompress(receivedMessage).length);
        assertEquals(originalMessage, new String(decompress(receivedMessage)));
    }

    @Test
    public void testSendCompressedBytesMessage() throws Exception {
        byte[] originalMessage = "Hello, Bytes!".getBytes();
        byte[] compressedMessage = compress(originalMessage);

        sendMessage(tcpSession, tcpDestination, compressedMessage);
        byte[] receivedMessage = receiveMessage(httpSession, httpDestination);

        assertNotNull(receivedMessage);
        assertEquals(originalMessage.length, decompress(receivedMessage).length);
        assertEquals(new String(originalMessage), new String(decompress(receivedMessage)));
    }

    @Test
    public void testSendCompressedStreamMessage() throws Exception {
        // Stream message test logic here
    }

    @Test
    public void testSendCompressedMapMessage() throws Exception {
        // Map message test logic here
    }

    private void sendMessage(Session session, Destination destination, byte[] messageContent) throws JMSException {
        MessageProducer producer = session.createProducer(destination);
        BytesMessage message = session.createBytesMessage();
        message.writeBytes(messageContent);
        producer.send(message);
        producer.close();
    }

    private byte[] receiveMessage(Session session, Destination destination) throws JMSException, IOException {
        MessageConsumer consumer = session.createConsumer(destination);
        BytesMessage message = (BytesMessage) consumer.receive(5000);
        consumer.close();

        if (message != null) {
            byte[] buffer = new byte[(int) message.getBodyLength()];
            message.readBytes(buffer);
            return buffer;
        }
        return null;
    }

    private byte[] compress(byte[] data) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        try (GZIPOutputStream gzipOutputStream = new GZIPOutputStream(byteArrayOutputStream)) {
            gzipOutputStream.write(data);
        }
        return byteArrayOutputStream.toByteArray();
    }

    private byte[] decompress(byte[] compressedData) throws IOException {
        ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(compressedData);
        try (GZIPInputStream gzipInputStream = new GZIPInputStream(byteArrayInputStream)) {
            return gzipInputStream.readAllBytes();
        }
    }
}

public abstract class ProcessSessionWrap {
    protected ProcessSession session;
    protected List<FlowFile> failedFiles = new ArrayList<>();
    protected List<FlowFile> droppedFiles = new ArrayList<>();

    public ProcessSessionWrap(ProcessSession session) {
        this.session = session;
    }

    public FlowFile wrap(FlowFile flowFile) {
        // Logic to wrap FlowFile
        return flowFile;
    }

    public FlowFile unwrap(FlowFile flowFile) {
        // Logic to unwrap FlowFile
        return flowFile;
    }

    public void trackFailedFile(FlowFile flowFile) {
        failedFiles.add(flowFile);
    }

    public void trackDroppedFile(FlowFile flowFile) {
        droppedFiles.add(flowFile);
    }

    public void clearTrackedFiles() {
        failedFiles.clear();
        droppedFiles.clear();
    }

    public FlowFile createFlowFile() {
        return session.create();
    }

    public FlowFile cloneFlowFile(FlowFile flowFile) {
        return session.clone(flowFile);
    }

    public FlowFile modifyFlowFile(FlowFile flowFile) {
        // Logic to modify FlowFile
        return flowFile;
    }

    public void transferFlowFile(FlowFile flowFile) {
        session.transfer(flowFile);
    }

    public void removeFlowFile(FlowFile flowFile) {
        session.remove(flowFile);
    }

    public void commit() {
        session.commit();
    }

    public void rollback() {
        session.rollback();
    }

    public void handleError(Exception e, FlowFile flowFile) {
        String errorMessage = e.getMessage();
        String stackTrace = getStackTrace(e);
        flowFile = session.putAttribute(flowFile, "error.message", errorMessage);
        flowFile = session.putAttribute(flowFile, "error.stacktrace", stackTrace);
        trackFailedFile(flowFile);
    }

    private String getStackTrace(Exception e) {
        StringBuilder sb = new StringBuilder();
        for (StackTraceElement element : e.getStackTrace()) {
            sb.append(element.toString()).append("\n");
        }
        return sb.toString();
    }
}

