public class PropertyUtilsBean {
    private Map<Class<?>, PropertyDescriptor[]> propertyDescriptorCache = new HashMap<>();

    public Object getProperty(Object bean, String name) throws Exception {
        if (bean == null) {
            throw new IllegalArgumentException("Bean must not be null");
        }
        PropertyDescriptor descriptor = getPropertyDescriptor(bean.getClass(), name);
        if (descriptor == null) {
            throw new NoSuchMethodException("No property '" + name + "' found for bean: " + bean.getClass());
        }
        Method readMethod = descriptor.getReadMethod();
        if (readMethod == null) {
            throw new NoSuchMethodException("No getter method for property '" + name + "'");
        }
        return readMethod.invoke(bean);
    }

    public void setProperty(Object bean, String name, Object value) throws Exception {
        if (bean == null) {
            throw new IllegalArgumentException("Bean must not be null");
        }
        PropertyDescriptor descriptor = getPropertyDescriptor(bean.getClass(), name);
        if (descriptor == null) {
            throw new NoSuchMethodException("No property '" + name + "' found for bean: " + bean.getClass());
        }
        Method writeMethod = descriptor.getWriteMethod();
        if (writeMethod == null) {
            throw new NoSuchMethodException("No setter method for property '" + name + "'");
        }
        writeMethod.invoke(bean, value);
    }

    private PropertyDescriptor getPropertyDescriptor(Class<?> beanClass, String propertyName) throws IntrospectionException {
        PropertyDescriptor[] descriptors = propertyDescriptorCache.computeIfAbsent(beanClass, this::introspect);
        for (PropertyDescriptor descriptor : descriptors) {
            if (descriptor.getName().equals(propertyName)) {
                return descriptor;
            }
        }
        return null;
    }

    private PropertyDescriptor[] introspect(Class<?> beanClass) {
        try {
            return Introspector.getBeanInfo(beanClass).getPropertyDescriptors();
        } catch (IntrospectionException e) {
            throw new RuntimeException("Failed to introspect bean class: " + beanClass, e);
        }
    }

    public void copyProperties(Object dest, Object orig) throws Exception {
        if (dest == null || orig == null) {
            throw new IllegalArgumentException("Destination and origin beans must not be null");
        }
        PropertyDescriptor[] origDescriptors = introspect(orig.getClass());
        for (PropertyDescriptor origDescriptor : origDescriptors) {
            String name = origDescriptor.getName();
            if (getPropertyDescriptor(dest.getClass(), name) != null) {
                Object value = getProperty(orig, name);
                setProperty(dest, name, value);
            }
        }
    }
}

