    @Override
    protected void populateItem(ListItem<T> item) {
        super.populateItem(item);
        String choice = item.getModelObject().toString();
        WebMarkupContainer container = new WebMarkupContainer("container");
        item.add(container);

        Label label = new Label("label", choice);
        label.setOutputMarkupId(true);
        container.add(label);

        if (labelPosition == LabelPosition.BEFORE) {
            container.add(new Label("prefix", prefix));
            container.add(item.get("checkbox"));
            container.add(new Label("suffix", suffix));
        } else if (labelPosition == LabelPosition.AFTER) {
            container.add(item.get("checkbox"));
            container.add(new Label("prefix", prefix));
            container.add(new Label("suffix", suffix));
        } else if (labelPosition == LabelPosition.WRAP) {
            container.add(new Label("prefix", prefix));
            container.add(item.get("checkbox"));
            container.add(new Label("suffix", suffix));
        }
    }

