public class ProducerMethodBean<T> extends AbstractProducerBean<T> {
    private Method creatorMethod;
    private Method disposalMethod;

    public ProducerMethodBean(Class<T> beanClass) {
        super(beanClass);
    }

    public void setCreatorMethod(Method creatorMethod) {
        this.creatorMethod = creatorMethod;
    }

    public void setDisposalMethod(Method disposalMethod) {
        this.disposalMethod = disposalMethod;
    }

    @Override
    public T createInstance() {
        try {
            T instance = (T) creatorMethod.invoke(null);
            if (instance == null) {
                throw new IllegalStateException("Created instance cannot be null");
            }
            return instance;
        } catch (Exception e) {
            throw new RuntimeException("Error creating instance", e);
        }
    }

    @Override
    public void disposeInstance(T instance) {
        if (disposalMethod != null) {
            try {
                disposalMethod.invoke(null, instance);
            } catch (Exception e) {
                throw new RuntimeException("Error disposing instance", e);
            }
        } else {
            throw new IllegalStateException("No disposal method defined");
        }
    }

    @Override
    public void validate() {
        if (creatorMethod == null) {
            throw new IllegalStateException("Creator method not set");
        }
        if (disposalMethod != null && disposalMethod.getParameterCount() != 1) {
            throw new IllegalStateException("Disposal method must have one parameter");
        }
    }
}

