public class JAXRSOutInterceptor extends AbstractOutDatabindingInterceptor {

    public JAXRSOutInterceptor() {
        super(Phase.MARSHAL);
    }

    @Override
    public void handleMessage(Message message) {
        try {
            MessageContext context = (MessageContext) message.get(MessageContext.class);
            Response response = (Response) message.getContent(Response.class);
            OutputStream outputStream = message.getContent(OutputStream.class);
            processResponse(response, outputStream, context);
        } catch (Exception e) {
            handleSerializationException(e, message);
        } finally {
            cleanupResources(message);
        }
    }

    private void processResponse(Response response, OutputStream outputStream, MessageContext context) throws Exception {
        setResponseHeaders(response, context);
        serializeResponseEntity(response, outputStream);
    }

    private void setResponseHeaders(Response response, MessageContext context) {
        // Set headers based on response metadata
        context.getHeaders().put("Content-Type", List.of(getContentType(response)));
        context.getHeaders().put("Status", List.of(String.valueOf(response.getStatus())));
    }

    private String getContentType(Response response) {
        MediaType mediaType = response.getMediaType();
        return mediaType != null ? mediaType.toString() : MediaType.APPLICATION_JSON;
    }

    private void serializeResponseEntity(Response response, OutputStream outputStream) throws Exception {
        Object entity = response.getEntity();
        if (entity != null) {
            // Serialization logic here (e.g., using a JSON library)
            // Example: outputStream.write(serialize(entity));
        }
    }

    private void handleSerializationException(Exception e, Message message) {
        // Write error message to output stream
        try {
            OutputStream outputStream = message.getContent(OutputStream.class);
            outputStream.write(("Error: " + e.getMessage()).getBytes());
        } catch (Exception ex) {
            // Log error
        }
    }

    private void cleanupResources(Message message) {
        // Clean up resources if necessary
    }
}

