public class TesterResultSet implements ResultSet {
    private int type;
    private int concurrency;
    private Object[][] data;
    private int currentRow = -1;
    private Statement statement;
    private boolean closed = false;

    public TesterResultSet(int type, int concurrency, Object[][] data, Statement statement) {
        this.type = type;
        this.concurrency = concurrency;
        this.data = data;
        this.statement = statement;
    }

    @Override
    public boolean next() throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        if (currentRow + 1 < data.length) {
            currentRow++;
            return true;
        }
        return false;
    }

    @Override
    public int getInt(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        return (int) data[currentRow][columnIndex - 1];
    }

    @Override
    public String getString(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        return (String) data[currentRow][columnIndex - 1];
    }

    @Override
    public BigDecimal getBigDecimal(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        return (BigDecimal) data[currentRow][columnIndex - 1];
    }

    @Override
    public boolean isClosed() throws SQLException {
        return closed;
    }

    @Override
    public void close() throws SQLException {
        closed = true;
    }

    @Override
    public boolean isBeforeFirst() throws SQLException {
        return currentRow == -1;
    }

    @Override
    public boolean isAfterLast() throws SQLException {
        return currentRow >= data.length;
    }

    @Override
    public boolean isFirst() throws SQLException {
        return currentRow == 0;
    }

    @Override
    public boolean isLast() throws SQLException {
        return currentRow == data.length - 1;
    }

    // Other methods from ResultSet interface are not implemented or return default values
    // Code smells: many methods not implemented, returning default values, and not handling all edge cases.
}

