public class HtmlDocumentParser {
    private static final Pattern TAG_PATTERN = Pattern.compile("<(/?)(\\w+)([^>]*)>");
    private static final Pattern COMMENT_PATTERN = Pattern.compile("<!--(.*?)-->", Pattern.DOTALL);
    private static final Pattern TEXT_PATTERN = Pattern.compile(">([^<]+)<");

    private String document;
    private int position;

    public HtmlDocumentParser(String document) {
        this.document = document;
        this.position = 0;
    }

    public List<String> getTags() {
        List<String> tags = new ArrayList<>();
        Matcher matcher = TAG_PATTERN.matcher(document);
        while (matcher.find(position)) {
            tags.add(matcher.group());
            position = matcher.end();
        }
        return tags;
    }

    public List<String> getComments() {
        List<String> comments = new ArrayList<>();
        Matcher matcher = COMMENT_PATTERN.matcher(document);
        while (matcher.find(position)) {
            comments.add(matcher.group());
            position = matcher.end();
        }
        return comments;
    }

    public List<String> getText() {
        List<String> texts = new ArrayList<>();
        Matcher matcher = TEXT_PATTERN.matcher(document);
        while (matcher.find(position)) {
            texts.add(matcher.group(1).trim());
            position = matcher.end();
        }
        return texts;
    }

    public Map<String, List<String>> getAttributes(String tag) {
        Map<String, List<String>> attributes = new HashMap<>();
        Matcher matcher = TAG_PATTERN.matcher(tag);
        if (matcher.find()) {
            String attrString = matcher.group(3);
            String[] attrPairs = attrString.trim().split("\\s+");
            for (String pair : attrPairs) {
                String[] keyValue = pair.split("=");
                if (keyValue.length == 2) {
                    String key = keyValue[0].trim();
                    String value = keyValue[1].replaceAll("\"", "").trim();
                    attributes.computeIfAbsent(key, k -> new ArrayList<>()).add(value);
                }
            }
        }
        return attributes;
    }

    public void logUnexpectedMarkup(String markup) {
        System.err.println("Unexpected markup encountered: " + markup);
    }

    public static void main(String[] args) {
        String html = "<html><!-- Comment --><body><h1>Title</h1><p class=\"text\">Hello World!</p></body></html>";
        HtmlDocumentParser parser = new HtmlDocumentParser(html);

        System.out.println("Tags: " + parser.getTags());
        System.out.println("Comments: " + parser.getComments());
        System.out.println("Text: " + parser.getText());

        String tag = "<p class=\"text\">";
        System.out.println("Attributes: " + parser.getAttributes(tag));
    }
}

