public class PubsubTestClient extends PubsubClient {
    private Set<String> expectedTopics = ConcurrentHashMap.newKeySet();
    private Map<String, List<String>> outgoingMessages = new ConcurrentHashMap<>();
    private Map<String, List<String>> subscriptions = new ConcurrentHashMap<>();
    private Map<String, List<String>> incomingMessages = new ConcurrentHashMap<>();
    private boolean simulateError = false;

    public static PubsubTestClient createPublisher(String topic) {
        PubsubTestClient client = new PubsubTestClient();
        client.expectedTopics.add(topic);
        return client;
    }

    public static PubsubTestClient createPuller(String subscription) {
        PubsubTestClient client = new PubsubTestClient();
        client.subscriptions.put(subscription, new ArrayList<>());
        return client;
    }

    public static PubsubTestClient createSubscription(String topic, String subscription) {
        PubsubTestClient client = new PubsubTestClient();
        client.expectedTopics.add(topic);
        client.subscriptions.put(subscription, new ArrayList<>());
        return client;
    }

    public void publish(String topic, String message) {
        if (!expectedTopics.contains(topic)) {
            throw new IllegalStateException("Unexpected topic: " + topic);
        }
        if (simulateError) {
            throw new RuntimeException("Simulated error during publish");
        }
        outgoingMessages.computeIfAbsent(topic, k -> new ArrayList<>()).add(message);
    }

    public List<String> pull(String subscription) {
        if (!subscriptions.containsKey(subscription)) {
            throw new IllegalStateException("Unknown subscription: " + subscription);
        }
        List<String> messages = incomingMessages.getOrDefault(subscription, new ArrayList<>());
        incomingMessages.put(subscription, messages);
        return messages;
    }

    public void acknowledge(String subscription, String message) {
        if (!subscriptions.containsKey(subscription)) {
            throw new IllegalStateException("Unknown subscription: " + subscription);
        }
        List<String> messages = incomingMessages.get(subscription);
        if (messages.contains(message)) {
            messages.remove(message);
        } else {
            throw new IllegalStateException("Message not found: " + message);
        }
    }

    public void modifyAckDeadline(String subscription, String message, long seconds) {
        // Simulate modifying acknowledgment deadline (no-op for this test client)
    }

    public void simulateError(boolean simulate) {
        this.simulateError = simulate;
    }

    public void addIncomingMessage(String subscription, String message) {
        if (!subscriptions.containsKey(subscription)) {
            throw new IllegalStateException("Unknown subscription: " + subscription);
        }
        incomingMessages.computeIfAbsent(subscription, k -> new ArrayList<>()).add(message);
    }

    public void clearState() {
        expectedTopics.clear();
        outgoingMessages.clear();
        subscriptions.clear();
        incomingMessages.clear();
        simulateError = false;
    }
}

