public class ApplicationContextFacade implements ServletContext {
    private final ApplicationContext applicationContext;
    private final Map<String, Method> methodCache = new HashMap<>();

    public ApplicationContextFacade(ApplicationContext applicationContext) {
        this.applicationContext = applicationContext;
    }

    private Method getMethod(String methodName, Class<?>... parameterTypes) {
        String key = methodName + "_" + parameterTypes.length;
        return methodCache.computeIfAbsent(key, k -> {
            try {
                return applicationContext.getClass().getMethod(methodName, parameterTypes);
            } catch (NoSuchMethodException e) {
                throw new RuntimeException(e);
            }
        });
    }

    private Object invokeMethod(String methodName, Object... args) {
        try {
            Method method = getMethod(methodName, getParameterTypes(args));
            return AccessController.doPrivileged((PrivilegedAction<Object>) () -> {
                try {
                    return method.invoke(applicationContext, args);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            });
        } catch (RuntimeException e) {
            // Log error
            return null;
        }
    }

    private Class<?>[] getParameterTypes(Object... args) {
        return args == null ? new Class<?>[0] : new Class<?>[args.length];
    }

    @Override
    public String getContextPath() {
        return (String) invokeMethod("getContextPath");
    }

    @Override
    public Object getAttribute(String name) {
        return invokeMethod("getAttribute", name);
    }

    @Override
    public void setAttribute(String name, Object object) {
        invokeMethod("setAttribute", name, object);
    }

    @Override
    public void removeAttribute(String name) {
        invokeMethod("removeAttribute", name);
    }

    // Other ServletContext methods would be implemented similarly...

    // Note: Additional methods like getServlet, getFilter, etc., would also be implemented here.
}

