public class JmsStreamMessage extends JmsMessage implements StreamMessage {
    private byte[] body;
    private int readIndex = 0;
    private int writeIndex = 0;
    private boolean isReadOnly = false;

    public JmsStreamMessage() {
        body = new byte[1024]; // Arbitrary size for the message body
    }

    @Override
    public void writeBoolean(boolean value) throws JMSException {
        checkWriteState();
        body[writeIndex++] = (byte) (value ? 1 : 0);
    }

    @Override
    public boolean readBoolean() throws JMSException {
        checkReadState();
        return body[readIndex++] != 0;
    }

    @Override
    public void writeByte(byte value) throws JMSException {
        checkWriteState();
        body[writeIndex++] = value;
    }

    @Override
    public byte readByte() throws JMSException {
        checkReadState();
        return body[readIndex++];
    }

    @Override
    public void writeShort(short value) throws JMSException {
        checkWriteState();
        body[writeIndex++] = (byte) (value >> 8);
        body[writeIndex++] = (byte) value;
    }

    @Override
    public short readShort() throws JMSException {
        checkReadState();
        return (short) ((body[readIndex++] << 8) | (body[readIndex++]));
    }

    @Override
    public void writeChar(char value) throws JMSException {
        checkWriteState();
        body[writeIndex++] = (byte) (value >> 8);
        body[writeIndex++] = (byte) value;
    }

    @Override
    public char readChar() throws JMSException {
        checkReadState();
        return (char) ((body[readIndex++] << 8) | (body[readIndex++]));
    }

    @Override
    public void writeInt(int value) throws JMSException {
        checkWriteState();
        body[writeIndex++] = (byte) (value >> 24);
        body[writeIndex++] = (byte) (value >> 16);
        body[writeIndex++] = (byte) (value >> 8);
        body[writeIndex++] = (byte) value;
    }

    @Override
    public int readInt() throws JMSException {
        checkReadState();
        return (body[readIndex++] << 24) | (body[readIndex++] << 16) | (body[readIndex++] << 8) | (body[readIndex++]);
    }

    @Override
    public void writeLong(long value) throws JMSException {
        checkWriteState();
        for (int i = 7; i >= 0; i--) {
            body[writeIndex++] = (byte) (value >> (i * 8));
        }
    }

    @Override
    public long readLong() throws JMSException {
        checkReadState();
        long value = 0;
        for (int i = 0; i < 8; i++) {
            value = (value << 8) | (body[readIndex++] & 0xFF);
        }
        return value;
    }

    @Override
    public void writeFloat(float value) throws JMSException {
        checkWriteState();
        writeInt(Float.floatToIntBits(value));
    }

    @Override
    public float readFloat() throws JMSException {
        checkReadState();
        return Float.intBitsToFloat(readInt());
    }

    @Override
    public void writeDouble(double value) throws JMSException {
        checkWriteState();
        writeLong(Double.doubleToLongBits(value));
    }

    @Override
    public double readDouble() throws JMSException {
        checkReadState();
        return Double.longBitsToDouble(readLong());
    }

    @Override
    public void writeString(String value) throws JMSException {
        checkWriteState();
        byte[] strBytes = value.getBytes();
        writeInt(strBytes.length);
        for (byte b : strBytes) {
            writeByte(b);
        }
    }

    @Override
    public String readString() throws JMSException {
        checkReadState();
        int length = readInt();
        byte[] strBytes = new byte[length];
        for (int i = 0; i < length; i++) {
            strBytes[i] = readByte();
        }
        return new String(strBytes);
    }

    @Override
    public void clearBody() throws JMSException {
        writeIndex = 0;
        readIndex = 0;
        isReadOnly = false;
    }

    @Override
    public void reset() throws JMSException {
        readIndex = 0;
        isReadOnly = false;
    }

    private void checkWriteState() throws JMSException {
        if (isReadOnly) {
            throw new JMSException("Message is in read-only state");
        }
    }

    private void checkReadState() throws JMSException {
        if (writeIndex > 0 && readIndex >= writeIndex) {
            throw new JMSException("No more data to read");
        }
    }

    // Additional methods for copying messages can be added here
}

