        // Code smells: Duplicate code, unclear variable names
        for (int i = 0; i < 10; i++) {
            LdapConnection connection = connectionPool.getConnection();
            connectionPool.releaseConnection(connection);
        }
    }

    @Test
    public void testConcurrentConnectionManagement() throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(THREAD_COUNT);
        Thread[] threads = new Thread[THREAD_COUNT];

        for (int i = 0; i < THREAD_COUNT; i++) {
            threads[i] = new Thread(() -> {
                for (int j = 0; j < ITERATIONS; j++) {
                    LdapConnection connection = connectionPool.getConnection();
                    connection.bind();
                    connection.unbind();
                    connectionPool.releaseConnection(connection);
                }
                latch.countDown();
            });
            threads[i].start();
        }

        latch.await();
    }

    @Test
    public void testConnectionManagementTime() {
        long startTime = System.currentTimeMillis();
        LdapConnection connection = connectionPool.getConnection();
        connection.bind();
        connection.unbind();
        connectionPool.releaseConnection(connection);
        long endTime = System.currentTimeMillis();
        long duration = endTime - startTime;
        assertTrue("Connection management took too long", duration < 1000);
    }

    @Test
    public void testDifferentConfigurations() throws InterruptedException {
        // Test logic for varying thread counts and iterations
        // Code smells: Lack of parameterization, hardcoded values
        for (int i = 0; i < 5; i++) {
            testConcurrentConnectionManagement();
        }
    }

    private class ConnectionTask implements Runnable {
        @Override
        public void run() {
            for (int j = 0; j < ITERATIONS; j++) {
                LdapConnection connection = connectionPool.getConnection();
                connection.bind();
                connection.unbind();
                connectionPool.releaseConnection(connection);
            }
        }
    }
