public abstract class ActionInvocationFacetForDomainEventAbstract {

    protected CommandService commandService;
    protected PersistenceService persistenceService;
    protected InteractionContext interactionContext;

    public ActionInvocationFacetForDomainEventAbstract(CommandService commandService, 
                                                        PersistenceService persistenceService, 
                                                        InteractionContext interactionContext) {
        this.commandService = commandService;
        this.persistenceService = persistenceService;
        this.interactionContext = interactionContext;
    }

    public abstract void invokeAction(Action action);

    protected void handleTransaction(Runnable action) {
        try {
            interactionContext.beginTransaction();
            action.run();
            interactionContext.commitTransaction();
        } catch (Exception e) {
            interactionContext.rollbackTransaction();
            throw e;
        }
    }

    protected <T> T cacheResult(String key, ResultProvider<T> provider) {
        // Code smell: potential for caching logic to be mixed with action invocation
        if (cacheContains(key)) {
            return getCachedResult(key);
        } else {
            T result = provider.get();
            cacheResult(key, result);
            return result;
        }
    }

    protected void publishEvent(DomainEvent event) {
        // Code smell: direct publishing logic could be abstracted
        EventBus.publish(event);
    }

    protected List<ViewModel> filterResults(List<ViewModel> results) {
        // Code smell: filtering logic could be more modular
        return results.stream()
                      .filter(this::isVisible)
                      .toList();
    }

    protected boolean isVisible(ViewModel viewModel) {
        // Code smell: visibility logic could be extracted to a separate service
        return viewModel.isVisible();
    }

    protected ViewModel cloneViewModel(ViewModel viewModel) {
        // Code smell: cloning logic could be more robust
        return new ViewModel(viewModel);
    }

    protected interface ResultProvider<T> {
        T get();
    }
}

public class JPAUserManagerImpl implements UserManager {

    @PersistenceContext
    private EntityManager entityManager;

    private static final Logger logger = Logger.getLogger(JPAUserManagerImpl.class.getName());
    private Map<String, User> usernameCache = new HashMap<>();

    @Override
    public void addUser(User user) {
        if (isUsernameTaken(user.getUsername())) {
            logger.warning("Username already taken: " + user.getUsername());
            throw new IllegalArgumentException("Username already taken");
        }
        entityManager.persist(user);
        usernameCache.put(user.getUsername(), user);
        logger.info("User added: " + user.getUsername());
    }

    @Override
    public void saveUser(User user) {
        entityManager.merge(user);
