    }

    @Override
    public void removeUser(User user) {
        user = entityManager.find(User.class, user.getId());
        if (user != null) {
            entityManager.remove(user);
            usernameCache.remove(user.getUsername());
            logger.info("User removed: " + user.getUsername());
        }
    }

    @Override
    public User getUserByUsername(String username) {
        if (usernameCache.containsKey(username)) {
            return usernameCache.get(username);
        }
        TypedQuery<User> query = entityManager.createQuery("SELECT u FROM User u WHERE u.username = :username", User.class);
        query.setParameter("username", username);
        User user = query.getSingleResult();
        usernameCache.put(username, user);
        return user;
    }

    @Override
    public User getUserByOpenId(String openId) {
        TypedQuery<User> query = entityManager.createQuery("SELECT u FROM User u WHERE u.openId = :openId", User.class);
