        query.setParameter("activationCode", activationCode);
        return query.getSingleResult();
    }

    @Override
    public void grantPermission(User user, Weblog weblog) {
        user.getPermissions().add(weblog);
        logger.info("Permission granted to user: " + user.getUsername() + " for weblog: " + weblog.getName());
    }

    @Override
    public void revokePermission(User user, Weblog weblog) {
        user.getPermissions().remove(weblog);
        logger.info("Permission revoked from user: " + user.getUsername() + " for weblog: " + weblog.getName());
    }

    @Override
    public void confirmPermission(User user, Weblog weblog) {
        // Implementation for confirming permission
        logger.info("Permission confirmed for user: " + user.getUsername() + " for weblog: " + weblog.getName());
    }

    @Override
    public List<User> getUsersByEnabledStatus(boolean enabled) {
        TypedQuery<User> query = entityManager.createQuery("SELECT u FROM User u WHERE u.enabled = :enabled", User.class);
        query.setParameter("enabled", enabled);
        return query.getResultList();
    }

    @Override
    public void grantRole(User user, Role role) {
        user.getRoles().add(role);
        logger.info("Role granted to user: " + user.getUsername() + " role: " + role.getName());
    }

    @Override
    public void revokeRole(User user, Role role) {
        user.getRoles().remove(role);
        logger.info("Role revoked from user: " + user.getUsername() + " role: " + role.getName());
    }

    private boolean isUsernameTaken(String username) {
        TypedQuery<Long> query = entityManager.createQuery("SELECT COUNT(u) FROM User u WHERE u.username = :username", Long.class);
        query.setParameter("username", username);
        return query.getSingleResult() > 0;
