public class SearchGenerator extends ServiceableGenerator implements Contextualizable, Disposable {
    private Context context;
    private LuceneCocoonSearcher searcher;
    private int startIndex;
    private int pageLength;
    private String queryString;

    public void contextualize(Context context) {
        this.context = context;
        // Code smell: context is directly assigned, consider using a setter
    }

    public void generate() throws IOException {
        // Code smell: method too long, consider breaking into smaller methods
        startIndex = getStartIndex();
        pageLength = getPageLength();
        queryString = getQueryString();

        Query query = searcher.createQuery(queryString);
        IndexSearcher indexSearcher = searcher.getIndexSearcher();
        ScoreDoc[] hits = indexSearcher.search(query, startIndex + pageLength).scoreDocs;

        // Output XML
        startDocument();
        startElement("searchResults");
        for (int i = startIndex; i < Math.min(hits.length, startIndex + pageLength); i++) {
            ScoreDoc hit = hits[i];
            // Code smell: too many responsibilities, consider separating XML formatting
            startElement("result");
            addElement("score", String.valueOf(hit.score));
            addElement("uri", searcher.getURI(hit.doc));
            endElement("result");
        }
        endElement("searchResults");
        endDocument();
    }

    private int getStartIndex() {
        // Code smell: method could be more descriptive
        return 0; // Placeholder
    }

    private int getPageLength() {
        // Code smell: magic number, consider using a constant
        return 10; // Placeholder
    }

    private String getQueryString() {
        // Code smell: method could be more descriptive
        return ""; // Placeholder
    }

    public void dispose() {
        // Code smell: resource cleanup could be more robust
        if (searcher != null) {
            searcher.close();
        }
    }
