public class TestLeaderSelector {
    private CuratorFramework client;
    private LeaderSelector leaderSelector;
    private CountDownLatch latch;
    private Semaphore semaphore;

    @Before
    public void setUp() throws Exception {
        client = CuratorFrameworkFactory.newClient("localhost:2181", new ExponentialBackoffRetry(1000, 3));
        client.start();
        latch = new CountDownLatch(1);
        semaphore = new Semaphore(1);
    }

    @After
    public void tearDown() throws Exception {
        if (leaderSelector != null) {
            leaderSelector.close();
        }
        client.close();
    }

    @Test
    public void testLeaderAcquisition() throws Exception {
        leaderSelector = new LeaderSelector(client, "/leader", (client1, leaderPath) -> {
            try {
                latch.countDown();
                semaphore.acquire();
                // Simulate leadership work
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                semaphore.release();
            }
        });
        leaderSelector.autoRequeue();
        leaderSelector.start();

        assertTrue(latch.await(5, TimeUnit.SECONDS));
    }

    @Test
    public void testLeaderInterruption() throws Exception {
        leaderSelector = new LeaderSelector(client, "/leader", (client1, leaderPath) -> {
            try {
                latch.countDown();
                semaphore.acquire();
                // Simulate leadership work
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                semaphore.release();
            }
        });
        leaderSelector.autoRequeue();
        leaderSelector.start();

        assertTrue(latch.await(5, TimeUnit.SECONDS));
        leaderSelector.close();
        assertTrue(semaphore.tryAcquire(1, TimeUnit.SECONDS));
    }

    @Test
    public void testLeaderElectionOnSessionExpiration() throws Exception {
        leaderSelector = new LeaderSelector(client, "/leader", (client1, leaderPath) -> {
            try {
                latch.countDown();
                semaphore.acquire();
                // Simulate leadership work
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                semaphore.release();
            }
        });
        leaderSelector.autoRequeue();
        leaderSelector.start();

        assertTrue(latch.await(5, TimeUnit.SECONDS));
        client.close(); // Simulate session expiration

        // Wait for a new leader to be elected
        latch = new CountDownLatch(1);
        assertTrue(latch.await(5, TimeUnit.SECONDS));
    }

    @Test
    public void testLeaderElectionOnServerFailure() throws Exception {
        leaderSelector = new LeaderSelector(client, "/leader", (client1, leaderPath) -> {
            try {
                latch.countDown();
                semaphore.acquire();
                // Simulate leadership work
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                semaphore.release();
            }
        });
        leaderSelector.autoRequeue();
        leaderSelector.start();

        assertTrue(latch.await(5, TimeUnit.SECONDS));
        // Simulate server failure
        client.close();

        // Wait for a new leader to be elected
        latch = new CountDownLatch(1);
        assertTrue(latch.await(5, TimeUnit.SECONDS));
    }
}

