            FileSystem fs = FileSystem.get(conf);
            List<String> results = listFiles(fs, new Path(hdfsPath), recurse, includeRegex, excludeRegex, ignoreHidden);

            if (results.isEmpty()) {
                context.transfer(flowFile, NOT_FOUND);
            } else {
                // Logic to store results as attributes or content
                context.transfer(flowFile, SUCCESS);
            }
        } catch (IOException e) {
            logger.error("Failed to access HDFS", e);
            context.transfer(flowFile, FAILURE);
        }
    }

    private List<String> listFiles(FileSystem fs, Path path, boolean recurse, String includeRegex, String excludeRegex, boolean ignoreHidden) throws IOException {
        List<String> fileList = new ArrayList<>();
        Pattern includePattern = Pattern.compile(includeRegex);
        Pattern excludePattern = Pattern.compile(excludeRegex);

        if (fs.exists(path)) {
            for (org.apache.hadoop.fs.FileStatus status : fs.listStatus(path)) {
                if (ignoreHidden && status.getPath().getName().startsWith(".")) {
                    continue;
                }
                if (includePattern.matcher(status.getPath().getName()).matches() &&
                        !excludePattern.matcher(status.getPath().getName()).matches()) {
                    fileList.add(status.getPath().toString());
                }
                if (recurse && status.isDirectory()) {
                    fileList.addAll(listFiles(fs, status.getPath(), recurse, includeRegex, excludeRegex, ignoreHidden));
                }
            }
        }
        return fileList;
    }
}

