public class StartpointManager {
    private boolean isActive;
    private final Map<SystemStreamPartition, Startpoint> readWriteStore;
    private final Map<TaskName, Startpoint> fanOutStore;
    private final long expirationDuration;

    public StartpointManager(long expirationDuration) {
        this.isActive = false;
        this.readWriteStore = new HashMap<>();
        this.fanOutStore = new HashMap<>();
        this.expirationDuration = expirationDuration;
    }

    public void start() {
        this.isActive = true;
    }

    public void stop() {
        this.isActive = false;
    }

    public void writeStartpoint(SystemStreamPartition ssp, TaskName taskName, Startpoint startpoint) {
        if (!isActive || ssp == null || taskName == null || startpoint == null) {
            return;
        }
        readWriteStore.put(ssp, startpoint);
        fanOutStore.put(taskName, startpoint);
    }

    public Startpoint readStartpoint(SystemStreamPartition ssp) {
        if (!isActive || ssp == null) {
            return null;
        }
        return readWriteStore.get(ssp);
    }

    public void deleteStartpoint(SystemStreamPartition ssp) {
        if (!isActive || ssp == null) {
            return;
        }
        readWriteStore.remove(ssp);
    }

    public void fanOutStartpoint(TaskName sourceTask, TaskName targetTask) {
        if (!isActive || sourceTask == null || targetTask == null) {
            return;
        }
        Startpoint sourceStartpoint = fanOutStore.get(sourceTask);
        if (sourceStartpoint != null) {
            fanOutStore.put(targetTask, sourceStartpoint);
        }
    }

    public Startpoint getFanOutStartpoint(TaskName taskName) {
        if (!isActive || taskName == null) {
            return null;
        }
        return fanOutStore.get(taskName);
    }

    public void expireStartpoints() {
        long currentTime = System.currentTimeMillis();
        readWriteStore.entrySet().removeIf(entry -> 
            currentTime - entry.getValue().getTimestamp() > expirationDuration);
        fanOutStore.entrySet().removeIf(entry -> 
            currentTime - entry.getValue().getTimestamp() > expirationDuration);
    }
}

