public final class ReflectionUtilities {

    private ReflectionUtilities() {
        // Prevent instantiation
    }

    public static Class<?> boxPrimitive(Class<?> clazz) {
        if (clazz.isPrimitive()) {
            if (clazz == boolean.class) return Boolean.class;
            if (clazz == byte.class) return Byte.class;
            if (clazz == char.class) return Character.class;
            if (clazz == double.class) return Double.class;
            if (clazz == float.class) return Float.class;
            if (clazz == int.class) return Integer.class;
            if (clazz == long.class) return Long.class;
            if (clazz == short.class) return Short.class;
        }
        return clazz;
    }

    public static List<Class<?>> getClassHierarchy(Class<?> clazz) {
        List<Class<?>> hierarchy = new ArrayList<>();
        while (clazz != null) {
            hierarchy.add(clazz);
            clazz = clazz.getSuperclass();
        }
        return hierarchy;
    }

    public static boolean canCoerce(Class<?> from, Class<?> to) {
        if (to.isAssignableFrom(from)) {
            return true;
        }
        if (from.isPrimitive() && to.isPrimitive()) {
            return false;
        }
        if (from.isPrimitive()) {
            from = boxPrimitive(from);
        }
        if (to.isPrimitive()) {
            to = boxPrimitive(to);
        }
        return to.isAssignableFrom(from);
    }

    public static Class<?> loadClass(String className, ClassLoader classLoader) throws ClassNotFoundException {
        if (className == null) {
            throw new ClassNotFoundException("Class name cannot be null");
        }
        return Class.forName(className, true, classLoader);
    }

    public static String getSimpleName(Class<?> clazz) {
        return clazz.getSimpleName();
    }

    public static String getFullName(Class<?> clazz) {
        return clazz.getName();
    }

    public static Class<?> extractTargetTypeFromParameterizedInterface(Class<?> clazz, Class<?> interfaceClass) {
        Type[] genericInterfaces = clazz.getGenericInterfaces();
        for (Type type : genericInterfaces) {
            if (type instanceof ParameterizedType) {
                ParameterizedType parameterizedType = (ParameterizedType) type;
                if (parameterizedType.getRawType().equals(interfaceClass)) {
                    return (Class<?>) parameterizedType.getActualTypeArguments()[0];
                }
            }
        }
        return null;
    }

    public static void validateNamedParameter(Class<?> clazz) {
        if (!clazz.isAnnotationPresent(NamedParameter.class)) {
            throw new IllegalArgumentException("Class must be annotated with @NamedParameter");
        }
        // Additional validation logic can be added here
    }

    public static Class<?> getRawClass(Type type) {
        if (type instanceof Class<?>) {
            return (Class<?>) type;
        }
        if (type instanceof ParameterizedType) {
            return getRawClass(((ParameterizedType) type).getRawType());
        }
        return null;
    }
}

