    private static final Logger logger = Logger.getLogger(Web3RfcTransformer.class.getName());

    public void processDocument(Node document) {
        try {
            if (document.getNodeType() == Node.ELEMENT_NODE) {
                Element element = (Element) document;
                handleStartElement(element);
                NodeList children = element.getChildNodes();
                for (int i = 0; i < children.getLength(); i++) {
                    processDocument(children.item(i));
                }
                handleEndElement(element);
            }
        } catch (Exception e) {
            logger.severe("Error processing document: " + e.getMessage());
        }
    }

    private void handleStartElement(Element element) {
        String tagName = element.getTagName();
        switch (tagName) {
            case "INCLUDE":
                handleInclude(element);
                break;
            case "IMPORT":
                handleImport(element);
                break;
            case "FIELD":
                handleField(element);
                break;
            case "STRUCTURE":
                handleStructure(element);
                break;
            case "TABLES":
                handleTables(element);
                break;
            case "ROW":
                handleRow(element);
                break;
            default:
                logger.warning("Unhandled start element: " + tagName);
