    }

    @Test
    public void testClearMappings() {
        prefixMapping.setPrefix("ex", "http://example.org/");
        prefixMapping.clear();
        assertNull(prefixMapping.getNamespace("ex"));
    }

    @Test
    public void testEqualityOfMappings() {
        PrefixMapping anotherMapping = createPrefixMapping();
        prefixMapping.setPrefix("ex", "http://example.org/");
        anotherMapping.setPrefix("ex", "http://example.org/");
        assertEquals(prefixMapping, anotherMapping);
    }

    @Test
    public void testLockingBehavior() {
        prefixMapping.setPrefix("ex", "http://example.org/");
        prefixMapping.lock();
        assertThrows(IllegalStateException.class, () -> {
            prefixMapping.setPrefix("ex2", "http://example2.org/");
        });
    }

    @Test
    public void testUnlockingBehavior() {
        prefixMapping.setPrefix("ex", "http://example.org/");
        prefixMapping.lock();
        prefixMapping.unlock();
        prefixMapping.setPrefix("ex2", "http://example2.org/");
        assertEquals("http://example2.org/", prefixMapping.getNamespace("ex2"));
    }
}

