    public void testPurgeMessagesWithSimpleSelector() throws JMSException {
        sendMessage("TestMessage1", "type=important");
        sendMessage("TestMessage2", "type=normal");
        purgeMessages("type=important");
        assertMessageCount(1);
    }

    @Test
    public void testPurgeMessagesWithComplexSelector() throws JMSException {
        sendMessage("TestMessage3", "type=important;priority=high");
        sendMessage("TestMessage4", "type=important;priority=low");
        purgeMessages("type=important AND priority=high");
        assertMessageCount(1);
    }

    private void sendMessage(String messageBody, String properties) throws JMSException {
        MessageProducer producer = session.createProducer(queue);
        TextMessage message = session.createTextMessage(messageBody);
        // Assuming properties are set here
        producer.send(message);
        logger.info("Sent message: " + messageBody + " with properties: " + properties);
        producer.close();
    }

    private void purgeMessages(String selector) throws JMSException {
        MessageConsumer consumer = session.createConsumer(queue, selector);
        while (consumer.receiveNoWait() != null) {
            // Purging messages
        }
        logger.info("Purged messages with selector: " + selector);
        consumer.close();
    }

    private void assertMessageCount(int expectedCount) throws JMSException {
        QueueBrowser browser = session.createBrowser(queue);
        int count = 0;
        Enumeration<?> messages = browser.getEnumeration();
        while (messages.hasMoreElements()) {
            messages.nextElement();
            count++;
        }
        browser.close();
        if (count != expectedCount) {
            logger.warning("Expected message count: " + expectedCount + ", but found: " + count);
        }
    }
