public class ClassGenerationAction {
    private VelocityEngine velocityEngine;
    private Map<String, Template> templateCache;
    private String outputDirectory;

    public ClassGenerationAction(String outputDirectory) {
        this.outputDirectory = outputDirectory;
        this.velocityEngine = new VelocityEngine();
        this.templateCache = new HashMap<>();
        validateOutputDirectory();
    }

    private void validateOutputDirectory() {
        File dir = new File(outputDirectory);
        if (!dir.exists() || !dir.isDirectory()) {
            throw new IllegalArgumentException("Output directory is invalid: " + outputDirectory);
        }
    }

    public void prepareArtifacts(String entityType, Map<String, Object> contextData) {
        String templateName = getTemplateName(entityType);
        Template template = getTemplate(templateName);
        generateClassFile(template, contextData);
    }

    private String getTemplateName(String entityType) {
        switch (entityType) {
            case "single":
                return "SingleClassTemplate.vm";
            case "subclass":
                return "SubclassTemplate.vm";
            case "embeddable":
                return "EmbeddableClassTemplate.vm";
            case "dataMap":
                return "DataMapTemplate.vm";
            default:
                return "DefaultTemplate.vm";
        }
    }

    private Template getTemplate(String templateName) {
        if (!templateCache.containsKey(templateName)) {
            Template template = velocityEngine.getTemplate(templateName);
            templateCache.put(templateName, template);
        }
        return templateCache.get(templateName);
    }

    private void generateClassFile(Template template, Map<String, Object> contextData) {
        Context context = new org.apache.velocity.VelocityContext(contextData);
        String outputFileName = contextData.get("className") + ".java";
        File outputFile = new File(outputDirectory, outputFileName);

        try (FileWriter writer = new FileWriter(outputFile)) {
            template.merge(context, writer);
        } catch (IOException | VelocityException e) {
            e.printStackTrace();
        }
    }

    public void executeGeneration(String entityType, Map<String, Object> contextData) {
        prepareArtifacts(entityType, contextData);
    }
}

