    private CounterFactory counterFactory;
    private Counter<Integer> intCounter;
    private Counter<Double> doubleCounter;

    @BeforeEach
    public void setUp() {
        counterFactory = new CounterFactory();
        intCounter = counterFactory.createIntegerCounter();
        doubleCounter = counterFactory.createDoubleCounter();
    }

    @Test
    public void testIntegerCounterSum() {
        intCounter.add(5);
        intCounter.add(10);
        assertEquals(15, intCounter.getSum());
    }

    @Test
    public void testDoubleCounterSum() {
        doubleCounter.add(5.5);
        doubleCounter.add(10.5);
        assertEquals(16.0, doubleCounter.getSum());
    }

    @Test
    public void testIntegerCounterMax() {
        intCounter.add(5);
        intCounter.add(10);
        intCounter.add(3);
        assertEquals(10, intCounter.getMax());
    }

    @Test
    public void testDoubleCounterMax() {
        doubleCounter.add(5.5);
        doubleCounter.add(10.5);
        doubleCounter.add(3.3);
        assertEquals(10.5, doubleCounter.getMax());
    }

    @Test
    public void testIntegerCounterMin() {
        intCounter.add(5);
        intCounter.add(10);
        intCounter.add(3);
        assertEquals(3, intCounter.getMin());
    }

    @Test
    public void testDoubleCounterMin() {
        doubleCounter.add(5.5);
        doubleCounter.add(10.5);
        doubleCounter.add(3.3);
        assertEquals(3.3, doubleCounter.getMin());
    }

    @Test
    public void testIntegerCounterMean() {
        intCounter.add(5);
        intCounter.add(10);
        assertEquals(7.5, intCounter.getMean());
    }

    @Test
    public void testDoubleCounterMean() {
        doubleCounter.add(5.5);
        doubleCounter.add(10.5);
        assertEquals(8.0, doubleCounter.getMean());
    }

    @Test
    public void testIntegerCounterReset() {
        intCounter.add(5);
        intCounter.reset();
        assertEquals(0, intCounter.getSum());
    }

    @Test
    public void testDoubleCounterReset() {
        doubleCounter.add(5.5);
        doubleCounter.reset();
        assertEquals(0.0, doubleCounter.getSum());
    }

    @Test
    public void testIntegerCounterState() {
        intCounter.add(5);
        assertTrue(intCounter.isDirty());
        intCounter.commit();
        assertFalse(intCounter.isDirty());
    }

    @Test
    public void testDoubleCounterState() {
        doubleCounter.add(5.5);
        assertTrue(doubleCounter.isDirty());
        doubleCounter.commit();
        assertFalse(doubleCounter.isDirty());
    }

    @Test
    public void testCounterCompatibility() {
        Counter<Integer> anotherIntCounter = counterFactory.createIntegerCounter();
        anotherIntCounter.add(5);
        intCounter.add(10);
        assertNotEquals(intCounter.getSum(), anotherIntCounter.getSum());
    }

    @Test
    public void testCounterDistribution() {
        intCounter.add(1);
        intCounter.add(2);
        intCounter.add(2);
        intCounter.add(3);
        assertArrayEquals(new int[]{1, 2, 3}, intCounter.getDistribution());
    }

    @Test
    public void testDoubleCounterDistribution() {
        doubleCounter.add(1.1);
        doubleCounter.add(2.2);
        doubleCounter.add(2.2);
        doubleCounter.add(3.3);
        assertArrayEquals(new double[]{1.1, 2.2, 3.3}, doubleCounter.getDistribution());
    }
}

