    public PropagationManagerImpl(UserDao userDao, GroupDao groupDao, TaskGenerator taskGenerator, AttributeHandler attributeHandler) {
        this.userDao = userDao;
        this.groupDao = groupDao;
        this.taskGenerator = taskGenerator;
        this.attributeHandler = attributeHandler;
    }

    public void createPropagationTask(String entityType, String entityId, String operation) {
        logger.info("Creating propagation task for entityType: {}, entityId: {}, operation: {}", entityType, entityId, operation);

        if ("USER".equals(entityType)) {
            User user = userDao.findById(entityId);
            if (user != null) {
                taskGenerator.generateTask(user, operation);
            } else {
                logger.warn("User not found for id: {}", entityId);
            }
        } else if ("GROUP".equals(entityType)) {
            Group group = groupDao.findById(entityId);
            if (group != null) {
                taskGenerator.generateTask(group, operation);
            } else {
                logger.warn("Group not found for id: {}", entityId);
            }
        } else {
            logger.error("Unsupported entity type: {}", entityType);
        }
    }

    public void updatePropagationTask(String entityType, String entityId, String operation) {
        logger.info("Updating propagation task for entityType: {}, entityId: {}, operation: {}", entityType, entityId, operation);

        if ("USER".equals(entityType)) {
            User user = userDao.findById(entityId);
            if (user != null) {
                taskGenerator.updateTask(user, operation);
            } else {
                logger.warn("User not found for id: {}", entityId);
