            } else {
                logger.warn("Group not found for id: {}", entityId);
            }
        } else {
            logger.error("Unsupported entity type: {}", entityType);
        }
    }

    public void deletePropagationTask(String entityType, String entityId) {
        logger.info("Deleting propagation task for entityType: {}, entityId: {}", entityType, entityId);

        if ("USER".equals(entityType)) {
            User user = userDao.findById(entityId);
            if (user != null) {
                taskGenerator.deleteTask(user);
            } else {
                logger.warn("User not found for id: {}", entityId);
            }
        } else if ("GROUP".equals(entityType)) {
            Group group = groupDao.findById(entityId);
            if (group != null) {
