public class ObjectHelper {
    private static final Logger logger = Logger.getLogger(ObjectHelper.class.getName());

    public static boolean equals(Object a, Object b) {
        if (a instanceof byte[] && b instanceof byte[]) {
            return java.util.Arrays.equals((byte[]) a, (byte[]) b);
        }
        return Objects.equals(a, b);
    }

    public static int compare(Object a, Object b) {
        if (a instanceof Comparable && b instanceof Comparable) {
            return ((Comparable) a).compareTo(b);
        }
        throw new IllegalArgumentException("Objects are not comparable");
    }

    public static Boolean toBoolean(Object value) {
        if (value instanceof Boolean) {
            return (Boolean) value;
        }
        return null;
    }

    public static boolean isNullOrEmpty(String value) {
        return value == null || value.isEmpty();
    }

    public static void validateNotNullOrEmpty(String value) {
        if (isNullOrEmpty(value)) {
            throw new IllegalArgumentException("String cannot be null or empty");
        }
    }

    public static String[] splitString(String value, String delimiter) {
        return value.split(delimiter);
    }

    public static String removeStartingCharacters(String value, int count) {
        return value.length() > count ? value.substring(count) : value;
    }

    public static String capitalize(String value) {
        if (isNullOrEmpty(value)) {
            return value;
        }
        return value.substring(0, 1).toUpperCase() + value.substring(1);
    }

    public static boolean contains(Collection<?> collection, Object value) {
        return collection != null && collection.contains(value);
    }

    public static boolean contains(Object[] array, Object value) {
        return array != null && java.util.Arrays.asList(array).contains(value);
    }

    public static <T> Iterator<T> iterator(Collection<T> collection) {
        return collection != null ? collection.iterator() : null;
    }

    public static <T> Iterator<T> iterator(T[] array) {
        return array != null ? java.util.Arrays.asList(array).iterator() : null;
    }

    public static Object invokeMethod(Object obj, String methodName, Class<?>[] parameterTypes, Object... args) {
        try {
            Method method = obj.getClass().getMethod(methodName, parameterTypes);
            return method.invoke(obj, args);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Method invocation failed", e);
            throw new RuntimeException(e);
        }
    }

    public static boolean isAssignable(Class<?> from, Class<?> to) {
        return to.isAssignableFrom(from);
    }

    public static Class<?> wrapPrimitive(Class<?> primitive) {
        if (primitive == boolean.class) return Boolean.class;
        if (primitive == byte.class) return Byte.class;
        if (primitive == short.class) return Short.class;
        if (primitive == int.class) return Integer.class;
        if (primitive == long.class) return Long.class;
        if (primitive == float.class) return Float.class;
        if (primitive == double.class) return Double.class;
        if (primitive == char.class) return Character.class;
        return primitive;
    }

    public static boolean isValidJavaIdentifier(String identifier) {
        if (isNullOrEmpty(identifier)) return false;
        return identifier.matches("^[a-zA-Z_$][a-zA-Z_$0-9]*$");
    }

    public static void wrapAndThrow(Exception e) {
        logger.log(Level.SEVERE, "Exception occurred", e);
        throw new RuntimeException(e);
    }
}

