public class ClassPathScanImplementationLookup implements ImplementationLookup {
    private static final Logger logger = LoggerFactory.getLogger(ClassPathScanImplementationLookup.class);

    private final Map<Class<?>, String> jwtSsoProviders = new HashMap<>();
    private final Map<Class<?>, String> reportlets = new HashMap<>();
    private final Map<Class<?>, String> accountRules = new HashMap<>();
    private final Map<Class<?>, String> passwordRules = new HashMap<>();

    private final ClassPathScanningCandidateComponentProvider scanner;

    public ClassPathScanImplementationLookup(String basePackage) {
        this.scanner = new ClassPathScanningCandidateComponentProvider(false);
        this.scanner.addIncludeFilter(new AssignableTypeFilter(JwtSsoProvider.class));
        this.scanner.addIncludeFilter(new AssignableTypeFilter(Reportlet.class));
        this.scanner.addIncludeFilter(new AssignableTypeFilter(AccountRule.class));
        this.scanner.addIncludeFilter(new AssignableTypeFilter(PasswordRule.class));
        this.scanner.addIncludeFilter(new AnnotationTypeFilter(RequiredConfiguration.class));

        scanPackage(basePackage);
    }

    private void scanPackage(String basePackage) {
        Set<BeanDefinition> candidates = scanner.findCandidateComponents(basePackage);
        for (BeanDefinition candidate : candidates) {
            try {
                Class<?> clazz = Class.forName(candidate.getBeanClassName());
                if (clazz.isAnnotationPresent(RequiredConfiguration.class)) {
                    registerImplementation(clazz);
                } else {
                    logger.warn("Class {} lacks required configuration annotations.", clazz.getName());
                }
            } catch (ClassNotFoundException e) {
                logger.error("Class not found: {}", e.getMessage());
            }
        }
    }

    private void registerImplementation(Class<?> clazz) {
        if (JwtSsoProvider.class.isAssignableFrom(clazz)) {
            jwtSsoProviders.put(clazz, clazz.getName());
        } else if (Reportlet.class.isAssignableFrom(clazz)) {
            reportlets.put(clazz, clazz.getName());
        } else if (AccountRule.class.isAssignableFrom(clazz)) {
            accountRules.put(clazz, clazz.getName());
        } else if (PasswordRule.class.isAssignableFrom(clazz)) {
            passwordRules.put(clazz, clazz.getName());
        }
    }

    public Map<Class<?>, String> getJwtSsoProviders() {
        return jwtSsoProviders;
    }

    public Map<Class<?>, String> getReportlets() {
        return reportlets;
    }

    public Map<Class<?>, String> getAccountRules() {
        return accountRules;
    }

    public Map<Class<?>, String> getPasswordRules() {
        return passwordRules;
    }
}

