    private String image;
    private String label;
    private String shape;
    private String edgeLabel;
    private String tooltip;
    private String nodeType;
    private String url;

    public NodeData(Object node) {
        if (node instanceof ProcessorType) {
            ProcessorType processor = (ProcessorType) node;
            this.id = processor.getId();
            this.image = processor.getImage();
            this.label = processor.getLabel();
            this.shape = processor.getShape();
            this.edgeLabel = processor.getEdgeLabel();
            this.tooltip = processor.getTooltip();
            this.nodeType = "Processor";
            this.url = processor.getUrl();
        } else if (node instanceof FromType) {
            FromType from = (FromType) node;
            this.id = from.getId();
            this.image = from.getImage();
            this.label = from.getLabel();
            this.shape = from.getShape();
            this.edgeLabel = from.getEdgeLabel();
            this.tooltip = from.getTooltip();
            this.nodeType = "From";
            this.url = from.getUrl();
        } else if (node instanceof ToType) {
            ToType to = (ToType) node;
            this.id = to.getId();
            this.image = to.getImage();
            this.label = to.getLabel();
            this.shape = to.getShape();
            this.edgeLabel = to.getEdgeLabel();
            this.tooltip = to.getTooltip();
            this.nodeType = "To";
            this.url = to.getUrl();
        } else {
            throw new IllegalArgumentException("Unsupported node type");
        }
    }

    public String removeQueryString(String url) {
        int questionMarkIndex = url.indexOf("?");
        return questionMarkIndex == -1 ? url : url.substring(0, questionMarkIndex);
    }

    public String insertSpaces(String camelCase) {
        return camelCase.replaceAll("([a-z])([A-Z])", "$1 $2");
    }

    // Getters and Setters
    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getImage() {
        return image;
    }

    public void setImage(String image) {
        this.image = image;
    }

    public String getLabel() {
        return label;
    }

    public void setLabel(String label) {
        this.label = label;
    }

    public String getShape() {
        return shape;
    }

    public void setShape(String shape) {
        this.shape = shape;
    }

    public String getEdgeLabel() {
        return edgeLabel;
    }

    public void setEdgeLabel(String edgeLabel) {
        this.edgeLabel = edgeLabel;
    }

    public String getTooltip() {
        return tooltip;
    }

    public void setTooltip(String tooltip) {
        this.tooltip = tooltip;
    }

    public String getNodeType() {
        return nodeType;
    }

    public void setNodeType(String nodeType) {
        this.nodeType = nodeType;
    }

    public String getUrl() {
        return url;
    }

    public void setUrl(String url) {
        this.url = url;
    }
}

