public class FtpResponse {
    private String originalUrl;
    private String baseUrl;
    private String responseContent;
    private int responseCode;
    private Map<String, String> headers;

    public FtpResponse(String originalUrl, String baseUrl) {
        this.originalUrl = originalUrl;
        this.baseUrl = baseUrl;
        this.headers = new HashMap<>();
    }

    public void fetchResponse(String ftpHost, String user, String pass, String remotePath) {
        FTPClient ftpClient = new FTPClient();
        try {
            ftpClient.connect(ftpHost);
            int replyCode = ftpClient.getReplyCode();
            if (!FTPReply.isPositiveCompletion(replyCode)) {
                responseCode = replyCode;
                return;
            }

            if (ftpClient.login(user, pass)) {
                ftpClient.setFileType(FTP.BINARY_FILE_TYPE);
                ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
                InputStream inputStream = ftpClient.retrieveFileStream(remotePath);

                if (inputStream != null) {
                    byte[] buffer = new byte[4096];
                    int bytesRead;
                    while ((bytesRead = inputStream.read(buffer)) != -1) {
                        outputStream.write(buffer, 0, bytesRead);
                    }
                    responseContent = outputStream.toString("UTF-8");
                    responseCode = 200; // OK
                    headers.put("Content-Type", "application/octet-stream");
                } else {
                    responseCode = 404; // Not Found
                }
                ftpClient.completePendingCommand();
                inputStream.close();
            } else {
                responseCode = 530; // Not logged in
            }
        } catch (IOException e) {
            responseCode = 500; // Internal Server Error
            e.printStackTrace();
        } finally {
            try {
                ftpClient.logout();
                ftpClient.disconnect();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public int getResponseCode() {
        return responseCode;
    }

    public Map<String, String> getHeaders() {
        return headers;
    }

    public String getResponseContent() {
        return responseContent;
    }

    public String getOriginalUrl() {
        return originalUrl;
    }

    public String getBaseUrl() {
        return baseUrl;
    }
}

