public class SourceRepository {
    private static SourceRepository instance;
    private final Map<String, Document> documents = new ConcurrentHashMap<>();
    private final Set<String> modifiableSources = ConcurrentHashMap.newKeySet();

    private SourceRepository() {}

    public static synchronized SourceRepository getInstance() {
        if (instance == null) {
            instance = new SourceRepository();
        }
        return instance;
    }

    public void saveDocument(String id, InputStream inputStream) throws IOException {
        if (!isModifiable(id)) {
            throw new IllegalStateException("Document is not modifiable.");
        }
        Document document = new Document(id, inputStream);
        documents.put(id, document);
    }

    public InputStream getDocumentStream(String id) throws IOException {
        Document document = documents.get(id);
        if (document == null) {
            throw new FileNotFoundException("Document not found.");
        }
        return new ByteArrayInputStream(document.getContent());
    }

    public void deleteDocument(String id) {
        if (!isModifiable(id)) {
            throw new IllegalStateException("Document is not modifiable.");
        }
        documents.remove(id);
    }

    public void copyDocument(String sourceId, String targetId) throws IOException {
        Document sourceDocument = documents.get(sourceId);
        if (sourceDocument == null) {
            throw new FileNotFoundException("Source document not found.");
        }
        saveDocument(targetId, new ByteArrayInputStream(sourceDocument.getContent()));
    }

    public void revertToVersion(String id, int version) throws IOException {
        Document document = documents.get(id);
        if (document == null || !document.hasVersion(version)) {
            throw new IllegalArgumentException("Version not found.");
        }
        saveDocument(id, new ByteArrayInputStream(document.getVersionContent(version)));
    }

    public List<Integer> listVersions(String id) {
        Document document = documents.get(id);
        if (document == null) {
            return Collections.emptyList();
        }
        return document.getVersions();
    }

    public void registerModifiableSource(String id) {
        modifiableSources.add(id);
    }

    public void unregisterModifiableSource(String id) {
        modifiableSources.remove(id);
    }

    private boolean isModifiable(String id) {
        return modifiableSources.contains(id);
    }

    private static class Document {
        private final String id;
        private final List<byte[]> versions = new ArrayList<>();

        public Document(String id, InputStream inputStream) throws IOException {
            this.id = id;
            saveVersion(inputStream);
        }

        public void saveVersion(InputStream inputStream) throws IOException {
            byte[] content = inputStream.readAllBytes();
            versions.add(content);
        }

        public byte[] getContent() {
            return versions.get(versions.size() - 1);
        }

        public boolean hasVersion(int version) {
            return version >= 0 && version < versions.size();
        }

        public byte[] getVersionContent(int version) {
            return versions.get(version);
        }

        public List<Integer> getVersions() {
            List<Integer> versionList = new ArrayList<>();
            for (int i = 0; i < versions.size(); i++) {
                versionList.add(i);
            }
            return versionList;
        }
    }
}

public class TestPerUserPoolDataSource extends TestConnectionPool {

    private PerUserPoolDataSource dataSource;

    @Before
    public void setUp() {
        dataSource = new PerUserPoolDataSource();
        // Initialize dataSource with default settings
