public class DefaultHashService implements ConfigurableHashService {
    private static final String DEFAULT_ALGORITHM = "SHA-512";
    private String algorithm = DEFAULT_ALGORITHM;
    private int iterations = 1000;
    private byte[] privateSalt;
    private boolean generatePublicSalt = false;

    public String computeHash(HashRequest request) {
        try {
            byte[] salt = combineSalts(request.getSalt());
            MessageDigest digest = MessageDigest.getInstance(algorithm);
            digest.reset();
            digest.update(salt);
            byte[] hash = digest.digest(request.getSourceData());

            for (int i = 0; i < iterations; i++) {
                hash = digest.digest(hash);
            }

            return Base64.getEncoder().encodeToString(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Hashing algorithm not found", e);
        }
    }

    private byte[] combineSalts(byte[] publicSalt) {
        if (generatePublicSalt) {
            byte[] generatedPublicSalt = new byte[16];
            new SecureRandom().nextBytes(generatedPublicSalt);
            return concatenate(privateSalt, generatedPublicSalt);
        }
        return privateSalt;
    }

    private byte[] concatenate(byte[] first, byte[] second) {
        byte[] result = new byte[first.length + second.length];
        System.arraycopy(first, 0, result, 0, first.length);
        System.arraycopy(second, 0, result, first.length, second.length);
        return result;
    }

    public String getAlgorithm() {
        return algorithm;
    }

    public void setAlgorithm(String algorithm) {
        this.algorithm = algorithm;
    }

    public int getIterations() {
        return iterations;
    }

    public void setIterations(int iterations) {
        this.iterations = iterations;
    }

    public byte[] getPrivateSalt() {
        return privateSalt;
    }

    public void setPrivateSalt(byte[] privateSalt) {
        this.privateSalt = privateSalt;
    }

    public boolean isGeneratePublicSalt() {
        return generatePublicSalt;
    }

    public void setGeneratePublicSalt(boolean generatePublicSalt) {
        this.generatePublicSalt = generatePublicSalt;
    }
}

