public abstract class ParserTestCase {

    protected Options options;
    protected CommandLineParser parser;

    @BeforeEach
    public void setUp() {
        options = new Options();
        parser = new DefaultParser();
        setupOptions(options);
    }

    protected abstract void setupOptions(Options options);

    @Test
    public void testShortOption() throws Exception {
        String[] args = {"-a"};
        CommandLine cmd = parser.parse(options, args);
        assertTrue(cmd.hasOption("a"));
    }

    @Test
    public void testLongOption() throws Exception {
        String[] args = {"--option"};
        CommandLine cmd = parser.parse(options, args);
        assertTrue(cmd.hasOption("option"));
    }

    @Test
    public void testOptionWithArgument() throws Exception {
        String[] args = {"-o", "value"};
        CommandLine cmd = parser.parse(options, args);
        assertTrue(cmd.hasOption("o"));
        assertEquals("value", cmd.getOptionValue("o"));
    }

    @Test
    public void testMultipleOptions() throws Exception {
        String[] args = {"-a", "-b", "--option"};
        CommandLine cmd = parser.parse(options, args);
        assertTrue(cmd.hasOption("a"));
        assertTrue(cmd.hasOption("b"));
        assertTrue(cmd.hasOption("option"));
    }

    @Test
    public void testUnrecognizedOption() {
        String[] args = {"-x"};
        Exception exception = assertThrows(ParseException.class, () -> {
            parser.parse(options, args);
        });
        assertEquals("Unrecognized option: -x", exception.getMessage());
    }

    @Test
    public void testMissingArgument() {
        String[] args = {"-o"};
        Exception exception = assertThrows(ParseException.class, () -> {
            parser.parse(options, args);
        });
        assertEquals("Missing argument for option: -o", exception.getMessage());
    }

    @Test
    public void testDoubleDash() throws Exception {
        String[] args = {"--", "unexpected"};
        CommandLine cmd = parser.parse(options, args);
        assertFalse(cmd.hasOption("unexpected"));
        List<String> remainingArgs = Arrays.asList(cmd.getArgs());
        assertEquals(1, remainingArgs.size());
        assertEquals("unexpected", remainingArgs.get(0));
    }

    @Test
    public void testRequiredOption() {
        String[] args = {};
        Exception exception = assertThrows(ParseException.class, () -> {
            parser.parse(options, args);
        });
        assertEquals("Missing required option: -r", exception.getMessage());
    }

    @Test
    public void testOptionGroup() throws Exception {
        String[] args = {"-a", "-b"};
        CommandLine cmd = parser.parse(options, args);
        assertTrue(cmd.hasOption("a"));
        assertFalse(cmd.hasOption("b"));
    }

    @Test
    public void testAmbiguousOption() {
        String[] args = {"-a", "-ab"};
        Exception exception = assertThrows(ParseException.class, () -> {
            parser.parse(options, args);
        });
        assertEquals("Ambiguous option: -ab", exception.getMessage());
    }

    @Test
    public void testPropertiesHandling() throws Exception {
        String[] args = {"-Dproperty=value"};
        CommandLine cmd = parser.parse(options, args);
        assertEquals("value", System.getProperty("property"));
    }
}

