    private PropagationManager propagationManager;

    public void setPullExecutor(PullExecutor pullExecutor) {
        this.pullExecutor = pullExecutor;
    }

    @Override
    public void handleDeltas(List<Delta> deltas) {
        for (Delta delta : deltas) {
            try {
                switch (delta.getType()) {
                    case CREATE:
                        createRealm(delta);
                        break;
                    case UPDATE:
                        updateRealm(delta);
                        break;
                    case LINK:
                        linkRealm(delta);
                        break;
                    case UNLINK:
                        unlinkRealm(delta);
                        break;
                    case DELETE:
                        deleteRealm(delta);
                        break;
                    default:
                        // Ignore unknown delta types
                        break;
                }
            } catch (ProvisioningException e) {
                // Log and ignore specific provisioning exceptions
                log.error("Provisioning exception occurred: {}", e.getMessage());
            } catch (Throwable t) {
                // Handle other exceptions
                log.error("Unexpected error occurred: {}", t.getMessage());
                throw t; // Rollback transaction
            }
        }
        finalizeOperations();
    }

    private void createRealm(Delta delta) {
        // Logic to create realm
        realmDAO.create(delta.getRealm());
        propagationManager.propagateCreate(delta.getRealm());
    }

    private void updateRealm(Delta delta) {
        // Logic to update realm
        realmDAO.update(delta.getRealm());
