public class HashBin {
    private LinkedList<HashEntry> entries;
    private HashPageInfo overflowPage;
    private int maxEntries;
    private int size;

    public HashBin(int maxEntries) {
        this.entries = new LinkedList<>();
        this.overflowPage = null;
        this.maxEntries = maxEntries;
        this.size = 0;
    }

    public void addEntry(HashEntry entry) {
        if (size < maxEntries) {
            entries.add(entry);
            size++;
        } else {
            handleOverflow(entry);
        }
    }

    public HashEntry findEntry(String key) {
        for (HashEntry entry : entries) {
            if (entry.getKey().equals(key)) {
                return entry;
            }
        }
        return overflowPage != null ? overflowPage.findEntry(key) : null;
    }

    public void removeEntry(String key) {
        HashEntry toRemove = null;
        for (HashEntry entry : entries) {
            if (entry.getKey().equals(key)) {
                toRemove = entry;
                break;
            }
        }
        if (toRemove != null) {
            entries.remove(toRemove);
            size--;
        }
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public void dumpContents() {
        for (HashEntry entry : entries) {
            System.out.println(entry);
        }
        if (overflowPage != null) {
            overflowPage.dumpContents();
        }
    }

    private void handleOverflow(HashEntry entry) {
        if (overflowPage == null) {
            overflowPage = new HashPageInfo();
        }
        overflowPage.addEntry(entry);
    }

    @Override
    public String toString() {
        return "HashBin{" +
                "entries=" + entries +
                ", overflowPage=" + overflowPage +
                ", maxEntries=" + maxEntries +
                ", size=" + size +
                '}';
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof HashBin)) return false;
        HashBin other = (HashBin) obj;
        return size == other.size && entries.equals(other.entries);
    }

    @Override
    public int hashCode() {
        int result = entries.hashCode();
        result = 31 * result + size;
        return result;
    }
}

