public abstract class TaskImpl implements Task, EventHandler<TaskEvent> {
    protected enum State {
        NEW, SCHEDULED, RUNNING, SUCCEEDED, FAILED, KILLED
    }

    private State state;
    private List<TaskAttempt> attempts;
    private int currentAttempt;
    private TaskConfig config;

    public TaskImpl(TaskConfig config) {
        this.config = config;
        this.state = State.NEW;
        this.attempts = new ArrayList<>();
        this.currentAttempt = 0;
    }

    public void handle(TaskEvent event) {
        switch (event.getType()) {
            case SCHEDULE:
                schedule();
                break;
            case COMPLETE:
                complete(event.getAttemptId());
                break;
            case FAIL:
                fail(event.getAttemptId());
                break;
            case KILL:
                kill();
                break;
            default:
                break;
        }
    }

    private void schedule() {
        if (state == State.NEW) {
            state = State.SCHEDULED;
            // Logic to schedule the task
        }
    }

    private void complete(int attemptId) {
        if (state == State.RUNNING) {
            state = State.SUCCEEDED;
            // Logic to handle successful completion
        }
    }

    private void fail(int attemptId) {
        if (state == State.RUNNING) {
            state = State.FAILED;
            // Logic to handle failure
            if (currentAttempt < config.getMaxAttempts()) {
                retry();
            }
        }
    }

    private void kill() {
        state = State.KILLED;
        // Logic to handle task killing
    }

    private void retry() {
        currentAttempt++;
        // Logic to retry the task
        state = State.NEW; // Reset state for new attempt
    }

    public State getState() {
        return state;
    }

    public List<TaskAttempt> getAttempts() {
        return attempts;
    }

    public TaskConfig getConfig() {
        return config;
    }

    public abstract void reportStatus();
    public abstract void reportProgress();
    public abstract void reportCounters();
}

