public class Zip64SupportIT {

    private static final int LARGE_FILE_SIZE = 5 * 1024 * 1024 * 1024; // 5GB
    private static final int NUMBER_OF_FILES = 100_000;

    @Test
    public void testZip64AlwaysMode() throws IOException {
        File zipFile = createTemporaryZipFile();
        writeLargeFilesToZip(zipFile, Zip64Mode.ALWAYS);
        verifyZipFile(zipFile);
    }

    @Test
    public void testZip64AsNeededMode() throws IOException {
        File zipFile = createTemporaryZipFile();
        writeLargeFilesToZip(zipFile, Zip64Mode.AS_NEEDED);
        verifyZipFile(zipFile);
    }

    @Test
    public void testZip64NeverMode() throws IOException {
        File zipFile = createTemporaryZipFile();
        writeLargeFilesToZip(zipFile, Zip64Mode.NEVER);
        verifyZipFile(zipFile);
    }

    private File createTemporaryZipFile() throws IOException {
        Path tempFile = Files.createTempFile("testZip", ".zip");
        return tempFile.toFile();
    }

    private void writeLargeFilesToZip(File zipFile, Zip64Mode mode) throws IOException {
        try (ZipOutputStream zos = new ZipOutputStream(Files.newOutputStream(zipFile.toPath()))) {
            for (int i = 0; i < NUMBER_OF_FILES; i++) {
                ZipEntry entry = new ZipEntry("file" + i);
                zos.putNextEntry(entry);
                byte[] data = new byte[LARGE_FILE_SIZE];
                zos.write(data);
                zos.closeEntry();
            }
        }
    }

    private void verifyZipFile(File zipFile) throws IOException {
        try (ZipInputStream zis = new ZipInputStream(Files.newInputStream(zipFile.toPath()))) {
            ZipEntry entry;
            int count = 0;
            while ((entry = zis.getNextEntry()) != null) {
                assertEquals(LARGE_FILE_SIZE, entry.getSize());
                zis.closeEntry();
                count++;
            }
            assertEquals(NUMBER_OF_FILES, count);
        }
    }

    private enum Zip64Mode {
        ALWAYS, AS_NEEDED, NEVER
    }
}

