public class UdfAnalyzer {
    private static final Logger logger = Logger.getLogger(UdfAnalyzer.class.getName());

    private Class<?> inputType;
    private Class<?> outputType;
    private boolean isBinary;
    private boolean isIterable;
    private boolean hasCollector;
    private List<String> analysisResults;
    private boolean hasNullReturn;
    private boolean invalidTupleAccess;

    public UdfAnalyzer() {
        this.analysisResults = new ArrayList<>();
        this.hasNullReturn = false;
        this.invalidTupleAccess = false;
    }

    public void analyzeUdf(Class<?> inputType, Class<?> outputType, boolean isBinary, boolean isIterable, boolean hasCollector) {
        this.inputType = inputType;
        this.outputType = outputType;
        this.isBinary = isBinary;
        this.isIterable = isIterable;
        this.hasCollector = hasCollector;

        logAnalysis();
        generateSemanticProperties();
    }

    private void logAnalysis() {
        StringBuilder result = new StringBuilder("UDF Analysis Results:\n");
        result.append("Input Type: ").append(inputType.getName()).append("\n");
        result.append("Output Type: ").append(outputType.getName()).append("\n");
        result.append("Is Binary: ").append(isBinary).append("\n");
        result.append("Is Iterable: ").append(isIterable).append("\n");
        result.append("Has Collector: ").append(hasCollector).append("\n");

        logger.log(Level.INFO, result.toString());
        analysisResults.add(result.toString());
