    private static final Logger logger = LoggerFactory.getLogger(UploadContentAndImage.class);
    private static final String UPLOAD_DIRECTORY = "uploads";

    public void uploadContent(HttpServletRequest request, HttpServletResponse response) {
        if (!ServletFileUpload.isMultipartContent(request)) {
            logger.error("Request is not multipart, please upload files.");
            return;
        }

        DiskFileItemFactory factory = new DiskFileItemFactory();
        ServletFileUpload upload = new ServletFileUpload(factory);

        try {
            List<FileItem> items = upload.parseRequest(request);
            String content = null;
            String imagePath = null;

            for (FileItem item : items) {
                if (item.isFormField()) {
                    if ("content".equals(item.getFieldName())) {
                        content = item.getString();
                    }
                } else {
                    String fileName = item.getName();
                    Path uploadPath = Paths.get(UPLOAD_DIRECTORY, fileName);
                    File uploadDir = new File(UPLOAD_DIRECTORY);
                    if (!uploadDir.exists()) {
                        uploadDir.mkdir();
                    }
                    item.write(uploadPath.toFile());
                    imagePath = uploadPath.toString();
                }
