                response.getWriter().write("Upload successful!");
            } else {
                logger.error("Validation failed for content or image.");
                response.getWriter().write("Upload failed: Invalid input.");
            }
        } catch (Exception e) {
            logger.error("Error during file upload", e);
            response.getWriter().write("Upload failed: " + e.getMessage());
        }
    }

