class TarEntry {
    private String name;
    private int mode;
    private int uid;
    private int gid;
    private long size;
    private long mtime;
    private byte linkFlag;
    private String userName;
    private String groupName;

    public TarEntry(String name) {
        this.name = name;
        this.mode = 0; // Default mode
        this.uid = 0; // Default UID
        this.gid = 0; // Default GID
        this.size = 0; // Default size
        this.mtime = System.currentTimeMillis() / 1000; // Current time
        this.linkFlag = 0; // Default link flag
    }

    public TarEntry(File file) throws IOException {
        this.name = file.getName();
        PosixFileAttributes attrs = Files.readAttributes(file.toPath(), PosixFileAttributes.class);
        this.mode = attrs.permissions().stream().mapToInt(p -> p.ordinal()).reduce(0, (a, b) -> a | b);
        this.uid = attrs.owner().hashCode(); // Simplified UID
        this.gid = attrs.group().hashCode(); // Simplified GID
        this.size = attrs.size();
        this.mtime = attrs.lastModifiedTime().toMillis() / 1000;
        this.linkFlag = 0; // Default link flag
        this.userName = attrs.owner().getName();
        this.groupName = attrs.group().getName();
    }

    public TarEntry(String name, int mode, int uid, int gid, long size, long mtime, byte linkFlag) {
        this.name = name;
        this.mode = mode;
        this.uid = uid;
        this.gid = gid;
        this.size = size;
        this.mtime = mtime;
        this.linkFlag = linkFlag;
    }

    public boolean isDirectory() {
        return name.endsWith("/");
    }

    public byte[] writeHeader() {
        byte[] header = new byte[512];
        System.arraycopy(name.getBytes(StandardCharsets.UTF_8), 0, header, 0, Math.min(name.length(), 100));
        // Add other fields like mode, uid, gid, size, mtime, linkFlag, etc.
        return header;
    }

    public static TarEntry parseHeader(byte[] header) {
        String name = new String(header, 0, 100, StandardCharsets.UTF_8).trim();
        // Parse other fields from the header
        return new TarEntry(name);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof TarEntry)) return false;
        TarEntry other = (TarEntry) obj;
        return name.equals(other.name) && mode == other.mode && uid == other.uid && gid == other.gid;
    }

    @Override
    public int hashCode() {
        return name.hashCode() ^ mode ^ uid ^ gid;
    }

    public String getUserName() {
        return userName;
    }

    public String getGroupName() {
        return groupName;
    }

    public int getUid() {
        return uid;
    }

    public int getGid() {
        return gid;
    }

    public long getSize() {
        return size;
    }

    public long getMtime() {
        return mtime;
    }

    public String getName() {
        return name;
    }

    public int getMode() {
        return mode;
    }

    public byte getLinkFlag() {
        return linkFlag;
    }
}

