public abstract class AbstractTestRangeIndex {

    protected RangeIndex<Integer> rangeIndex;

    protected abstract RangeIndex<Integer> makeRangeIndex();

    @Before
    public void setUp() {
        rangeIndex = makeRangeIndex();
    }

    @After
    public void tearDown() {
        rangeIndex.clear();
    }

    @Test
    public void testIsEmptyInitially() {
        assertTrue(rangeIndex.isEmpty());
    }

    @Test
    public void testInsertAndCheckPresence() {
        rangeIndex.insert(10);
        assertFalse(rangeIndex.isEmpty());
        assertTrue(rangeIndex.contains(10));
    }

    @Test
    public void testInsertMultipleKeys() {
        rangeIndex.insert(5);
        rangeIndex.insert(15);
        rangeIndex.insert(10);
        assertEquals(5, rangeIndex.getMin().intValue());
        assertEquals(15, rangeIndex.getMax().intValue());
        assertTrue(rangeIndex.contains(10));
        assertTrue(rangeIndex.contains(5));
        assertTrue(rangeIndex.contains(15));
    }

    @Test
    public void testDeleteKey() {
        rangeIndex.insert(20);
        rangeIndex.delete(20);
        assertFalse(rangeIndex.contains(20));
        assertTrue(rangeIndex.isEmpty());
    }

    @Test
    public void testDeleteNonExistentKey() {
        rangeIndex.insert(30);
        rangeIndex.delete(40); // Key 40 does not exist
        assertTrue(rangeIndex.contains(30));
    }

    @Test
    public void testClearIndex() {
        rangeIndex.insert(25);
        rangeIndex.clear();
        assertTrue(rangeIndex.isEmpty());
    }

    @Test
    public void testRandomInsertionsAndDeletions() {
        Random random = new Random();
        for (int i = 0; i < 100; i++) {
            int key = random.nextInt(100);
            rangeIndex.insert(key);
            assertTrue(rangeIndex.contains(key));
        }
        for (int i = 0; i < 50; i++) {
            int key = random.nextInt(100);
            rangeIndex.delete(key);
            // Check that the key is not present if it was deleted
            assertFalse(rangeIndex.contains(key));
        }
    }

    @Test
    public void testMinMaxAfterInsertions() {
        rangeIndex.insert(1);
        rangeIndex.insert(3);
        rangeIndex.insert(2);
        assertEquals(1, rangeIndex.getMin().intValue());
        assertEquals(3, rangeIndex.getMax().intValue());
    }

    @Test
    public void testIterateOverKeys() {
        rangeIndex.insert(1);
        rangeIndex.insert(2);
        rangeIndex.insert(3);
        int count = 0;
        for (Integer key : rangeIndex) {
            count++;
            assertTrue(key >= 1 && key <= 3);
        }
        assertEquals(3, count);
    }
}

