        List<Token> tokens = tokenizer.tokenize(input);
        assertEquals(1, tokens.size());
        assertEquals(TokenType.EXTERNAL_LINK, tokens.get(0).getType());
        assertEquals("External Link", tokens.get(0).getValue());
    }

    @Test
    public void testCategory() {
        String input = "[[Category:Example]]";
        List<Token> tokens = tokenizer.tokenize(input);
        assertEquals(1, tokens.size());
        assertEquals(TokenType.CATEGORY, tokens.get(0).getType());
        assertEquals("Example", tokens.get(0).getValue());
    }

    @Test
    public void testCitation() {
        String input = "<ref>This is a citation</ref>";
        List<Token> tokens = tokenizer.tokenize(input);
        assertEquals(1, tokens.size());
        assertEquals(TokenType.CITATION, tokens.get(0).getType());
        assertEquals("This is a citation", tokens.get(0).getValue());
    }

    @Test
    public void testBoldText() {
        String input = "'''''Bold Text'''''";
        List<Token> tokens = tokenizer.tokenize(input);
        assertEquals(1, tokens.size());
        assertEquals(TokenType.BOLD, tokens.get(0).getType());
        assertEquals("Bold Text", tokens.get(0).getValue());
    }

    @Test
    public void testItalicText() {
