        List<Token> tokens = tokenizer.tokenize(input);
        assertEquals(1, tokens.size());
        assertEquals(TokenType.ITALIC, tokens.get(0).getType());
        assertEquals("Italic Text", tokens.get(0).getValue());
    }

    @Test
    public void testMixedContent() {
        String input = "This is a [[Link]] and ''italic'' and '''bold''' text.";
        List<Token> tokens = tokenizer.tokenize(input);
        assertEquals(5, tokens.size());
        assertEquals(TokenType.TEXT, tokens.get(0).getType());
        assertEquals("This is a ", tokens.get(0).getValue());
        assertEquals(TokenType.INTERNAL_LINK, tokens.get(1).getType());
        assertEquals("Link", tokens.get(1).getValue());
        assertEquals(TokenType.TEXT, tokens.get(2).getType());
        assertEquals(" and ", tokens.get(2).getValue());
        assertEquals(TokenType.ITALIC, tokens.get(3).getType());
        assertEquals("italic", tokens.get(3).getValue());
        assertEquals(TokenType.TEXT, tokens.get(4).getType());
        assertEquals(" and ", tokens.get(4).getValue());
        assertEquals(TokenType.BOLD, tokens.get(5).getType());
        assertEquals("bold", tokens.get(5).getValue());
        assertEquals(TokenType.TEXT, tokens.get(6).getType());
        assertEquals(" text.", tokens.get(6).getValue());
    }
}

