public class RutaBasic extends Annotation {
    private Map<String, List<Annotation>> annotationsMap;
    private Map<String, Integer> annotationCounts;
    private String replacement;

    public RutaBasic() {
        annotationsMap = new HashMap<>();
        annotationCounts = new HashMap<>();
        replacement = "";
    }

    public void addAnnotation(String type, Annotation annotation) {
        annotationsMap.computeIfAbsent(type, k -> new ArrayList<>()).add(annotation);
        annotationCounts.put(type, annotationCounts.getOrDefault(type, 0) + 1);
    }

    public void removeAnnotation(String type, Annotation annotation) {
        List<Annotation> annotations = annotationsMap.get(type);
        if (annotations != null) {
            annotations.remove(annotation);
            if (annotations.isEmpty()) {
                annotationsMap.remove(type);
                annotationCounts.remove(type);
            } else {
                annotationCounts.put(type, annotations.size());
            }
        }
    }

    public boolean hasAnnotations(String type) {
        return annotationCounts.containsKey(type) && annotationCounts.get(type) > 0;
    }

    public List<Annotation> getAnnotations(String type) {
        return annotationsMap.getOrDefault(type, new ArrayList<>());
    }

    public boolean isEmpty() {
        return annotationsMap.isEmpty();
    }

    public void clear() {
        annotationsMap.clear();
        annotationCounts.clear();
    }

    public String getReplacement() {
        return replacement;
    }

    public void setReplacement(String replacement) {
        this.replacement = replacement;
    }

    // Additional methods for parent-child relationships can be added here
}

