    }

    @Override
    public void process(Exchange exchange) throws Exception {
        HttpUriRequest request = createHttpRequest(exchange);
        try (CloseableHttpResponse response = httpClient.execute(request)) {
            handleResponse(exchange, response);
        } catch (IOException e) {
            throw new RuntimeException("HTTP request failed", e);
        }
    }

    private HttpUriRequest createHttpRequest(Exchange exchange) {
        // Logic to create HttpUriRequest based on exchange
        // Code smells: Too many responsibilities in one method
        return null; // Placeholder for actual request creation logic
    }

    private void handleResponse(Exchange exchange, HttpResponse response) throws IOException {
        // Logic to handle response
        // Code smells: Handling response and logging in the same method
        int statusCode = response.getStatusLine().getStatusCode();
        if (statusCode >= 400) {
            throw new RuntimeException("HTTP error: " + statusCode);
        }
        String responseBody = EntityUtils.toString(response.getEntity());
        exchange.getIn().setBody(responseBody);
    }

