public class MarkupStream {
    private List<String> elements;
    private int currentIndex;

    public MarkupStream(String markupFragment) {
        this.elements = parseMarkup(markupFragment);
        this.currentIndex = 0;
    }

    private List<String> parseMarkup(String markupFragment) {
        // Simple parsing logic for demonstration purposes
        List<String> parsedElements = new ArrayList<>();
        String[] splitElements = markupFragment.split("(?=<)|(?<=>)");
        for (String element : splitElements) {
            if (!element.trim().isEmpty()) {
                parsedElements.add(element.trim());
            }
        }
        return parsedElements;
    }

    public String getCurrentElement() {
        if (currentIndex < elements.size()) {
            return elements.get(currentIndex);
        }
        return null;
    }

    public String getNextElement() {
        if (currentIndex + 1 < elements.size()) {
            return elements.get(currentIndex + 1);
        }
        return null;
    }

    public boolean isOpenTag(String tag) {
        return tag.startsWith("<") && !tag.startsWith("</") && !tag.endsWith("/>");
    }

    public boolean isCloseTag(String tag) {
        return tag.startsWith("</");
    }

    public boolean isOpenCloseTag(String tag) {
        return tag.endsWith("/>");
    }

    public boolean compareTags(String tag1, String tag2) {
        String name1 = tag1.replaceAll("[</>]", "").split(" ")[0];
        String name2 = tag2.replaceAll("[</>]", "").split(" ")[0];
        return name1.equals(name2);
    }

    public void skipUntil(String tagName) throws MarkupException {
        while (currentIndex < elements.size()) {
            String currentElement = getCurrentElement();
            if (currentElement != null && currentElement.contains(tagName)) {
                break;
            }
            currentIndex++;
        }
        if (currentIndex >= elements.size()) {
            throw new MarkupException("End of stream reached without finding tag: " + tagName);
        }
    }

    public void moveToNext() {
        if (currentIndex < elements.size()) {
            currentIndex++;
        }
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("MarkupStream:\n");
        for (int i = 0; i < elements.size(); i++) {
            sb.append(i == currentIndex ? "> " : "  ").append(elements.get(i)).append("\n");
        }
        return sb.toString();
    }

    public static class MarkupException extends Exception {
        public MarkupException(String message) {
            super(message);
        }
    }
}

public class ShoppingListEvents {
    private Map<String, List<String>> userShoppingLists = new HashMap<>();
    private Map<String, List<String>> guestShoppingLists = new HashMap<>();
    private Map<String, List<String>> userSessions = new HashMap<>();
    private Map<String, List<String>> cartItems = new HashMap<>();

    public String addItemsToShoppingList(String userId, List<String> items, String listName, boolean createNew) {
        if (createNew) {
            userShoppingLists.put(listName, new ArrayList<>(items));
            return "New shopping list created and items added.";
        } else {
            if (userShoppingLists.containsKey(listName)) {
                userShoppingLists.get(listName).addAll(items);
                return "Items added to existing shopping list.";
            } else {
                return "Error: Shopping list does not exist.";
            }
        }
    }

    public String addItemsToCartFromList(String userId, String listName, boolean includeChildLists, int quantity) {
        if (userShoppingLists.containsKey(listName)) {
            List<String> items = userShoppingLists.get(listName);
            List<String> cart = cartItems.getOrDefault(userId, new ArrayList<>());
            for (String item : items) {
                for (int i = 0; i < quantity; i++) {
                    cart.add(item);
                }
            }
            cartItems.put(userId, cart);
            return "Items added to cart from shopping list.";
        } else {
            return "Error: Shopping list does not exist.";
