public class IsisJdoSupportImpl implements IsisJdoSupport {

    private final IsisSessionFactory sessionFactory;
    private final ServicesInjector servicesInjector;

    public IsisJdoSupportImpl(IsisSessionFactory sessionFactory, ServicesInjector servicesInjector) {
        this.sessionFactory = sessionFactory;
        this.servicesInjector = servicesInjector;
    }

    @Override
    public void refresh(Object domainObject) {
        PersistenceManager pm = sessionFactory.getCurrentPersistenceManager();
        pm.makePersistent(domainObject);
    }

    @Override
    public void ensureLoaded(Collection<?> collection) {
        for (Object obj : collection) {
            refresh(obj);
        }
    }

    @Override
    public List<?> executeQuery(String query, Object... params) {
        PersistenceManager pm = sessionFactory.getCurrentPersistenceManager();
        Query jdoQuery = pm.newQuery(query);
        return (List<?>) jdoQuery.executeWithArray(params);
    }

    @Override
    public void executeUpdate(String query, Object... params) {
        PersistenceManager pm = sessionFactory.getCurrentPersistenceManager();
        Transaction tx = pm.currentTransaction();
        try {
            tx.begin();
            Query jdoQuery = pm.newQuery(query);
            jdoQuery.executeWithArray(params);
            tx.commit();
        } catch (Exception e) {
            if (tx.isActive()) {
                tx.rollback();
            }
            throw new RuntimeException("Error executing update", e);
        }
    }

    @Override
    public void deleteAll(Class<?> persistentClass) {
        PersistenceManager pm = sessionFactory.getCurrentPersistenceManager();
        Transaction tx = pm.currentTransaction();
        try {
            tx.begin();
            Query jdoQuery = pm.newQuery(persistentClass);
            jdoQuery.deletePersistentAll();
            tx.commit();
        } catch (Exception e) {
            if (tx.isActive()) {
                tx.rollback();
            }
            throw new RuntimeException("Error deleting all instances", e);
        }
    }

    @Override
    public <T> List<T> createQuery(String query, Class<T> resultClass) {
        PersistenceManager pm = sessionFactory.getCurrentPersistenceManager();
        Query jdoQuery = pm.newQuery(query);
        return (List<T>) jdoQuery.execute();
    }
}

