public class PersistenceSession implements TransactionManager, SessionScope, LifecycleEvents {

    private boolean isOpen;
    private Transaction currentTransaction;
    private Map<Class<?>, Adapter<?>> adapterMap;
    private CommandHandler commandHandler;
    private EventBus eventBus;
    private Metrics metrics;

    public PersistenceSession(CommandHandler commandHandler, EventBus eventBus, Metrics metrics) {
        this.commandHandler = commandHandler;
        this.eventBus = eventBus;
        this.metrics = metrics;
        this.adapterMap = new HashMap<>();
        this.isOpen = false;
    }

    public void open() {
        if (isOpen) {
            throw new IllegalStateException("Session is already open");
        }
        // Logic to open a session
        isOpen = true;
    }

    public void close() {
        if (!isOpen) {
            throw new IllegalStateException("Session is not open");
        }
        // Logic to close a session
        isOpen = false;
    }

    public void beginTransaction() {
        if (currentTransaction != null) {
            throw new IllegalStateException("Transaction is already in progress");
        }
        currentTransaction = new Transaction();
        // Logic to begin transaction
    }

    public void commitTransaction() {
        if (currentTransaction == null) {
            throw new IllegalStateException("No transaction in progress");
        }
        // Logic to commit transaction
        currentTransaction = null;
    }

    public void rollbackTransaction() {
        if (currentTransaction == null) {
            throw new IllegalStateException("No transaction in progress");
        }
        // Logic to rollback transaction
        currentTransaction = null;
    }

    public <T> void persist(T entity) {
        if (!isOpen) {
            throw new IllegalStateException("Session is not open");
        }
        // Logic to persist entity
        Adapter<T> adapter = (Adapter<T>) adapterMap.get(entity.getClass());
        if (adapter == null) {
            throw new IllegalArgumentException("No adapter found for entity type");
        }
        adapter.save(entity);
    }

    public <T> T find(Class<T> entityClass, Object id) {
        if (!isOpen) {
            throw new IllegalStateException("Session is not open");
        }
        // Logic to find entity
        Adapter<T> adapter = (Adapter<T>) adapterMap.get(entityClass);
        if (adapter == null) {
            throw new IllegalArgumentException("No adapter found for entity type");
        }
        return adapter.find(id);
    }

    public void registerAdapter(Class<?> entityClass, Adapter<?> adapter) {
        adapterMap.put(entityClass, adapter);
    }

    public void installFixtures() {
        // Logic to install fixtures for testing
    }

    public void onLifecycleEvent(LifecycleEvent event) {
        // Handle lifecycle events
    }
}

