public class KrbError extends KerberosMessage {
    private static final Logger logger = Logger.getLogger(KrbError.class.getName());

    private long cTime;
    private long sTime;
    private int cusec;
    private int susec;
    private int errorCode;
    private String cName;
    private String sName;
    private String eText;
    private byte[] eData;

    public long getCTime() {
        return cTime;
    }

    public void setCTime(long cTime) {
        this.cTime = cTime;
    }

    public long getSTime() {
        return sTime;
    }

    public void setSTime(long sTime) {
        this.sTime = sTime;
    }

    public int getCusec() {
        return cusec;
    }

    public void setCusec(int cusec) {
        this.cusec = cusec;
    }

    public int getSusec() {
        return susec;
    }

    public void setSusec(int susec) {
        this.susec = susec;
    }

    public int getErrorCode() {
        return errorCode;
    }

    public void setErrorCode(int errorCode) {
        this.errorCode = errorCode;
    }

    public String getCName() {
        return cName;
    }

    public void setCName(String cName) {
        this.cName = cName;
    }

    public String getSName() {
        return sName;
    }

    public void setSName(String sName) {
        this.sName = sName;
    }

    public String getEText() {
        return eText;
    }

    public void setEText(String eText) {
        this.eText = eText;
    }

    public byte[] getEData() {
        return eData;
    }

    public void setEData(byte[] eData) {
        this.eData = eData;
    }

    public int computeLength() {
        int length = Long.BYTES * 2 + Integer.BYTES * 2 + Integer.BYTES; // cTime, sTime, cusec, susec, errorCode
        length += (cName != null ? cName.length() : 0);
        length += (sName != null ? sName.length() : 0);
        length += (eText != null ? eText.length() : 0);
        length += (eData != null ? eData.length : 0);
        logger.info("Computed length: " + length);
        return length;
    }

    public ByteBuffer encode() {
        ByteBuffer buffer = ByteBuffer.allocate(computeLength());
        buffer.putLong(cTime);
        buffer.putLong(sTime);
        buffer.putInt(cusec);
        buffer.putInt(susec);
        buffer.putInt(errorCode);
        buffer.put(cName.getBytes());
        buffer.put(sName.getBytes());
        buffer.put(eText.getBytes());
        buffer.put(eData);
        logger.info("Encoded KrbError message");
        return buffer;
    }

    @Override
    public String toString() {
        return "KrbError{" +
                "cTime=" + cTime +
                ", sTime=" + sTime +
                ", cusec=" + cusec +
                ", susec=" + susec +
                ", errorCode=" + errorCode +
                ", cName='" + cName + '\'' +
                ", sName='" + sName + '\'' +
                ", eText='" + eText + '\'' +
                '}';
    }
}

