public class DefaultRestletBinding implements RestletBinding, HeaderFilterStrategyAware {
    private DefaultHeaderFilterStrategy headerFilterStrategy;

    @Override
    public void populateExchangeFromRequest(Exchange exchange, Request request) {
        // Populate exchange from request
        for (Header header : request.getHeaders()) {
            if (headerFilterStrategy.applyFilterToCamelHeaders(header.getName(), header.getValue())) {
                exchange.getIn().setHeader(header.getName(), header.getValue());
            }
        }
        exchange.getIn().setBody(request.getEntity().getText());
        // Log debug information
        System.out.println("Populated exchange from request: " + exchange);
    }

    @Override
    public void populateRequestFromExchange(Request request, Exchange exchange) {
        // Populate request from exchange
        for (String headerName : exchange.getIn().getHeaders().keySet()) {
            if (headerFilterStrategy.applyFilterToRestletHeaders(headerName, exchange.getIn().getHeader(headerName))) {
                request.getHeaders().add(headerName, exchange.getIn().getHeader(headerName));
            }
        }
        request.setEntity(exchange.getIn().getBody(String.class));
        // Log debug information
        System.out.println("Populated request from exchange: " + request);
    }

    @Override
    public void populateResponseFromExchange(Response response, Exchange exchange) {
        // Populate response from exchange
        for (String headerName : exchange.getOut().getHeaders().keySet()) {
            if (headerFilterStrategy.applyFilterToRestletHeaders(headerName, exchange.getOut().getHeader(headerName))) {
                response.getHeaders().add(headerName, exchange.getOut().getHeader(headerName));
            }
        }
        response.setEntity(exchange.getOut().getBody(String.class));
        // Log debug information
        System.out.println("Populated response from exchange: " + response);
    }

    @Override
    public void populateExchangeFromResponse(Exchange exchange, Response response) {
        // Populate exchange from response
        for (Header header : response.getHeaders()) {
            if (headerFilterStrategy.applyFilterToCamelHeaders(header.getName(), header.getValue())) {
                exchange.getOut().setHeader(header.getName(), header.getValue());
            }
        }
        exchange.getOut().setBody(response.getEntity().getText());
        // Log debug information
        System.out.println("Populated exchange from response: " + exchange);
    }

    @Override
    public void setHeaderFilterStrategy(DefaultHeaderFilterStrategy strategy) {
        this.headerFilterStrategy = strategy;
    }

    @Override
    public DefaultHeaderFilterStrategy getHeaderFilterStrategy() {
        return headerFilterStrategy;
    }
}

