public class ArithmeticUtils {

    public static int add(int a, int b) {
        if (b > 0 && a > Integer.MAX_VALUE - b) {
            throw new ArithmeticException("Integer overflow on addition");
        }
        if (b < 0 && a < Integer.MIN_VALUE - b) {
            throw new ArithmeticException("Integer underflow on addition");
        }
        return a + b;
    }

    public static int subtract(int a, int b) {
        if (b > 0 && a < Integer.MIN_VALUE + b) {
            throw new ArithmeticException("Integer underflow on subtraction");
        }
        if (b < 0 && a > Integer.MAX_VALUE + b) {
            throw new ArithmeticException("Integer overflow on subtraction");
        }
        return a - b;
    }

    public static int multiply(int a, int b) {
        if (a > 0 && b > 0 && a > Integer.MAX_VALUE / b) {
            throw new ArithmeticException("Integer overflow on multiplication");
        }
        if (a < 0 && b < 0 && a < Integer.MAX_VALUE / b) {
            throw new ArithmeticException("Integer overflow on multiplication");
        }
        if ((a > 0 && b < 0 && b < Integer.MIN_VALUE / a) || (a < 0 && b > 0 && a < Integer.MIN_VALUE / b)) {
            throw new ArithmeticException("Integer underflow on multiplication");
        }
        return a * b;
    }

    public static int divide(int a, int b) {
        if (b == 0) {
            throw new ArithmeticException("Division by zero");
        }
        return a / b;
    }

    public static long add(long a, long b) {
        if (b > 0 && a > Long.MAX_VALUE - b) {
            throw new ArithmeticException("Long overflow on addition");
        }
        if (b < 0 && a < Long.MIN_VALUE - b) {
            throw new ArithmeticException("Long underflow on addition");
        }
        return a + b;
    }

    public static long subtract(long a, long b) {
        if (b > 0 && a < Long.MIN_VALUE + b) {
            throw new ArithmeticException("Long underflow on subtraction");
        }
        if (b < 0 && a > Long.MAX_VALUE + b) {
            throw new ArithmeticException("Long overflow on subtraction");
        }
        return a - b;
    }

    public static long multiply(long a, long b) {
        if (a > 0 && b > 0 && a > Long.MAX_VALUE / b) {
            throw new ArithmeticException("Long overflow on multiplication");
        }
        if (a < 0 && b < 0 && a < Long.MAX_VALUE / b) {
            throw new ArithmeticException("Long overflow on multiplication");
        }
        if ((a > 0 && b < 0 && b < Long.MIN_VALUE / a) || (a < 0 && b > 0 && a < Long.MIN_VALUE / b)) {
            throw new ArithmeticException("Long underflow on multiplication");
        }
        return a * b;
    }

    public static long divide(long a, long b) {
        if (b == 0) {
            throw new ArithmeticException("Division by zero");
        }
        return a / b;
    }

    public static int gcd(int a, int b) {
        if (a < 0 || b < 0) {
            throw new IllegalArgumentException("GCD inputs must be non-negative");
        }
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static int lcm(int a, int b) {
        if (a < 0 || b < 0) {
            throw new IllegalArgumentException("LCM inputs must be non-negative");
        }
        return (a / gcd(a, b)) * b;
    }

    public static int binomialCoefficient(int n, int k) {
        if (n < 0 || k < 0 || k > n) {
            throw new IllegalArgumentException("Invalid inputs for binomial coefficient");
        }
        if (k > n - k) {
            k = n - k;
        }
        int result = 1;
        for (int i = 0; i < k; i++) {
            result = multiply(result, n - i);
            result = divide(result, i + 1);
        }
        return result;
    }

    public static long factorial(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Factorial input must be non-negative");
        }
        long result = 1;
        for (int i = 2; i <= n; i++) {
            result = multiply(result, i);
        }
        return result;
    }

    @Deprecated
    public static int oldMethod() {
        // This method is outdated and should be replaced
        return 0;
    }

    public static double power(double base, int exponent) {
        if (exponent < 0) {
            throw new IllegalArgumentException("Exponent must be non-negative");
        }
        double result = 1;
        for (int i = 0; i < exponent; i++) {
            result *= base;
            if (result == Double.POSITIVE_INFINITY) {
                throw new ArithmeticException("Overflow in exponentiation");
            }
        }
        return result;
    }
}

