public class MultiTreeWordList implements RutaWordList {
    private Map<String, Set<String>> wordTree;

    public MultiTreeWordList() {
        this.wordTree = new HashMap<>();
    }

    public void loadWordsFromFile(File file) throws IOException {
        BufferedReader reader = new BufferedReader(new FileReader(file));
        String line;
        while ((line = reader.readLine()) != null) {
            addWord(line.trim(), "default");
        }
        reader.close();
    }

    public void addWord(String word, String type) {
        wordTree.computeIfAbsent(word, k -> new HashSet<>()).add(type);
    }

    public Set<String> getTypes(String word) {
        return wordTree.getOrDefault(word, Collections.emptySet());
    }

    public List<String> search(String fragment, boolean caseSensitive, boolean ignoreCharacters) {
        List<String> results = new ArrayList<>();
        for (String word : wordTree.keySet()) {
            if (matches(word, fragment, caseSensitive, ignoreCharacters)) {
                results.add(word);
            }
        }
        return results;
    }

    private boolean matches(String word, String fragment, boolean caseSensitive, boolean ignoreCharacters) {
        String processedWord = ignoreCharacters ? word.replaceAll("[^a-zA-Z]", "") : word;
        String processedFragment = ignoreCharacters ? fragment.replaceAll("[^a-zA-Z]", "") : fragment;
        return caseSensitive ? processedWord.contains(processedFragment) : processedWord.toLowerCase().contains(processedFragment.toLowerCase());
    }

    public boolean isWithinEditDistance(String word, String target, int distance) {
        return editDistance(word, target) <= distance;
    }

    private int editDistance(String a, String b) {
        int[][] dp = new int[a.length() + 1][b.length() + 1];
        for (int i = 0; i <= a.length(); i++) {
            for (int j = 0; j <= b.length(); j++) {
                if (i == 0) {
                    dp[i][j] = j;
                } else if (j == 0) {
                    dp[i][j] = i;
                } else {
                    dp[i][j] = Math.min(dp[i - 1][j] + 1, Math.min(dp[i][j - 1] + 1, dp[i - 1][j - 1] + (a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1)));
                }
            }
        }
        return dp[a.length()][b.length()];
    }

    public List<String> createAnnotations(String text) {
        List<String> annotations = new ArrayList<>();
        for (String word : wordTree.keySet()) {
            if (text.contains(word)) {
                annotations.add(word + " : " + String.join(", ", getTypes(word)));
            }
        }
        return annotations;
    }

    public void saveToFile(File file) throws IOException {
        BufferedWriter writer = new BufferedWriter(new FileWriter(file));
        for (Map.Entry<String, Set<String>> entry : wordTree.entrySet()) {
            writer.write(entry.getKey() + "\t" + String.join(",", entry.getValue()));
            writer.newLine();
        }
        writer.close();
    }

    public void loadFromCustomFormat(File file) throws IOException {
        BufferedReader reader = new BufferedReader(new FileReader(file));
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split("\t");
            if (parts.length == 2) {
                String word = parts[0];
                String[] types = parts[1].split(",");
                for (String type : types) {
                    addWord(word, type.trim());
                }
