public class InterpolateObjectAction {
    private final Object target;
    private final List<ValueSource> valueSources;
    private final List<PostProcessor> postProcessors;
    private final ModelInterpolator modelInterpolator;
    private final ModelProblemCollector problemCollector;
    private final Set<Class<?>> processedClasses = new HashSet<>();

    public InterpolateObjectAction(Object target, List<ValueSource> valueSources, 
                                    List<PostProcessor> postProcessors, ModelInterpolator modelInterpolator, 
                                    ModelProblemCollector problemCollector) {
        this.target = target;
        this.valueSources = valueSources;
        this.postProcessors = postProcessors;
        this.modelInterpolator = modelInterpolator;
        this.problemCollector = problemCollector;
    }

    public void interpolate() {
        processObject(target);
    }

    private void processObject(Object obj) {
        if (obj == null || processedClasses.contains(obj.getClass())) {
            return;
        }
        processedClasses.add(obj.getClass());

        Class<?> clazz = obj.getClass();
        while (clazz != null) {
            for (Field field : clazz.getDeclaredFields()) {
                if (isEligibleForInterpolation(field)) {
                    processField(obj, field);
                }
            }
            clazz = clazz.getSuperclass();
        }
    }

    private boolean isEligibleForInterpolation(Field field) {
        return !field.getType().isPrimitive() && !Collection.class.isAssignableFrom(field.getType()) 
               && !Map.class.isAssignableFrom(field.getType());
    }

    private void processField(Object obj, Field field) {
        field.setAccessible(true);
        try {
            Object value = field.get(obj);
            if (value instanceof String) {
                String interpolatedValue = modelInterpolator.interpolate((String) value, valueSources);
                field.set(obj, applyPostProcessors(interpolatedValue));
            } else if (value instanceof Object[]) {
                processArray((Object[]) value);
            } else if (value != null) {
                processObject(value);
            }
        } catch (IllegalAccessException e) {
            problemCollector.addProblem("Access error on field: " + field.getName());
        } catch (Exception e) {
            problemCollector.addProblem("Interpolation error on field: " + field.getName());
        }
    }

    private void processArray(Object[] array) {
        for (Object element : array) {
            if (element != null) {
                processObject(element);
            }
        }
    }

    private String applyPostProcessors(String value) {
        for (PostProcessor postProcessor : postProcessors) {
            value = postProcessor.process(value);
        }
        return value;
    }
}

