public class BufferedHttpServletResponse implements HttpServletResponse {
    private final HttpServletResponse response;
    private final StringBuilder contentBuffer = new StringBuilder();
    private final List<Cookie> cookies = new ArrayList<>();
    private final Map<String, List<String>> headers = new HashMap<>();
    private int status = HttpServletResponse.SC_OK;
    private boolean committed = false;

    public BufferedHttpServletResponse(HttpServletResponse response) {
        this.response = response;
    }

    public void addCookie(Cookie cookie) {
        if (!committed) {
            cookies.add(cookie);
        }
    }

    public void addHeader(String name, String value) {
        if (!committed) {
            headers.computeIfAbsent(name, k -> new ArrayList<>()).add(value);
        }
    }

    public void setHeader(String name, String value) {
        if (!committed) {
            List<String> values = new ArrayList<>();
            values.add(value);
            headers.put(name, values);
        }
    }

    public void setStatus(int status) {
        if (!committed) {
            this.status = status;
        }
    }

    public void setContentType(String type) {
        if (!committed) {
            response.setContentType(type);
        }
    }

    public void setCharacterEncoding(String charset) {
        if (!committed) {
            response.setCharacterEncoding(charset);
        }
    }

    public void setLocale(Locale locale) {
        if (!committed) {
            response.setLocale(locale);
        }
    }

    public PrintWriter getWriter() throws IOException {
        if (committed) {
            throw new IllegalStateException("Response already committed");
        }
        return new PrintWriter(new BufferedWriter(new StringWriter() {
            @Override
            public void write(String str) {
                contentBuffer.append(str);
            }
        }));
    }

    public void flushBuffer() throws IOException {
        if (!committed) {
            committed = true;
            for (Cookie cookie : cookies) {
                response.addCookie(cookie);
            }
            for (Map.Entry<String, List<String>> entry : headers.entrySet()) {
                for (String value : entry.getValue()) {
                    response.addHeader(entry.getKey(), value);
                }
            }
            response.setStatus(status);
            response.getWriter().write(contentBuffer.toString());
            response.flushBuffer();
        }
    }

    public boolean isCommitted() {
        return committed;
    }

    // Other HttpServletResponse methods would delegate to the underlying response
    // For brevity, they are not implemented here
}

