class MimeMessageParserTest {

    @Test
    public void testParseSimpleEmail() {
        String rawEmail = "From: sender@example.com\n" +
                          "To: recipient@example.com\n" +
                          "Subject: Test Email\n" +
                          "\n" +
                          "This is a test email.";
        MimeMessageParser parser = new MimeMessageParser();
        ParsedEmail parsedEmail = parser.parse(rawEmail);

        assertEquals("sender@example.com", parsedEmail.getFrom());
        assertEquals("recipient@example.com", parsedEmail.getTo());
        assertEquals("Test Email", parsedEmail.getSubject());
        assertEquals("This is a test email.", parsedEmail.getBody());
    }

    @Test
    public void testParseReplyEmail() {
        String rawEmail = "From: reply@example.com\n" +
                          "To: original@example.com\n" +
                          "Subject: Re: Original Email\n" +
                          "\n" +
                          "This is a reply.";
        MimeMessageParser parser = new MimeMessageParser();
        ParsedEmail parsedEmail = parser.parse(rawEmail);

        assertEquals("reply@example.com", parsedEmail.getFrom());
        assertEquals("original@example.com", parsedEmail.getTo());
        assertEquals("Re: Original Email", parsedEmail.getSubject());
        assertEquals("This is a reply.", parsedEmail.getBody());
    }

    @Test
    public void testParseHtmlEmail() {
        String rawEmail = "From: html@example.com\n" +
                          "To: recipient@example.com\n" +
                          "Subject: HTML Email\n" +
                          "Content-Type: text/html\n" +
                          "\n" +
                          "<html><body><p>This is an HTML email.</p></body></html>";
        MimeMessageParser parser = new MimeMessageParser();
        ParsedEmail parsedEmail = parser.parse(rawEmail);

        assertEquals("html@example.com", parsedEmail.getFrom());
        assertEquals("recipient@example.com", parsedEmail.getTo());
        assertEquals("HTML Email", parsedEmail.getSubject());
        assertEquals("<html><body><p>This is an HTML email.</p></body></html>", parsedEmail.getBody());
    }

    @Test
    public void testParseMultipartEmail() {
        String rawEmail = "From: multipart@example.com\n" +
                          "To: recipient@example.com\n" +
                          "Subject: Multipart Email\n" +
                          "Content-Type: multipart/mixed; boundary=\"boundary\"\n" +
                          "\n" +
                          "--boundary\n" +
                          "Content-Type: text/plain\n" +
                          "\n" +
                          "This is the plain text part.\n" +
                          "--boundary\n" +
                          "Content-Type: text/html\n" +
                          "\n" +
                          "<html><body><p>This is the HTML part.</p></body></html>\n" +
                          "--boundary--";
        MimeMessageParser parser = new MimeMessageParser();
        ParsedEmail parsedEmail = parser.parse(rawEmail);

        assertEquals("multipart@example.com", parsedEmail.getFrom());
        assertEquals("recipient@example.com", parsedEmail.getTo());
        assertEquals("Multipart Email", parsedEmail.getSubject());
        assertEquals("This is the plain text part.\n<html><body><p>This is the HTML part.</p></body></html>", parsedEmail.getBody());
    }

    @Test
    public void testParseEmailWithAttachments() {
        String rawEmail = "From: sender@example.com\n" +
                          "To: recipient@example.com\n" +
                          "Subject: Email with Attachment\n" +
                          "Content-Type: multipart/mixed; boundary=\"boundary\"\n" +
                          "\n" +
                          "--boundary\n" +
                          "Content-Type: text/plain\n" +
                          "\n" +
                          "This is the email body.\n" +
                          "--boundary\n" +
                          "Content-Disposition: attachment; filename=\"file.txt\"\n" +
                          "Content-Type: text/plain\n" +
                          "\n" +
                          "This is the attachment content.\n" +
                          "--boundary--";
