public class ClientFaultConverter extends AbstractPhaseInterceptor<Message> {

    public ClientFaultConverter() {
        super(Phase.PRE_PROTOCOL);
    }

    @Override
    public void handleMessage(Message message) {
        // Check for fault details in the message
        if (message.getContent(Exception.class) != null) {
            Exception faultException = message.getContent(Exception.class);
            Throwable cause = faultException.getCause();
            if (cause != null) {
                // Determine fault mode
                if (isUncheckedException(cause)) {
                    throw new UncheckedApplicationFault(convertToUncheckedException(cause));
                } else {
                    throw new CheckedApplicationFault(convertToCheckedException(cause));
                }
            }
        }
    }

    private boolean isUncheckedException(Throwable throwable) {
        // Logic to determine if the exception is unchecked
        return throwable instanceof RuntimeException;
    }

    private RuntimeException convertToUncheckedException(Throwable throwable) {
        // Process fault detail to extract relevant information
        return new RuntimeException("Unchecked fault: " + throwable.getMessage(), throwable);
    }

    private Exception convertToCheckedException(Throwable throwable) {
        // Process fault detail to extract relevant information
        return new Exception("Checked fault: " + throwable.getMessage(), throwable);
    }
}

