public class XMLChar {
    private static final byte[] VALID_XML_CHAR = new byte[256]; // Simplified for example

    static {
        // Initialize VALID_XML_CHAR array based on XML character rules
    }

    public static boolean isValid(char ch) {
        return ch < VALID_XML_CHAR.length && VALID_XML_CHAR[ch] != 0;
    }

    public static boolean isInvalid(char ch) {
        return !isValid(ch);
    }

    public static boolean isSpace(char ch) {
        return ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r';
    }

    public static boolean isNameStart(char ch) {
        return Character.isLetter(ch) || ch == '_' || ch == ':';
    }

    public static boolean isName(char[] name, int start, int length) {
        if (length == 0 || !isNameStart(name[start])) {
            return false;
        }
        for (int i = start + 1; i < start + length; i++) {
            if (!isValid(name[i])) {
                return false;
            }
        }
        return true;
    }

    public static boolean isNCName(char[] name, int start, int length) {
        if (length == 0 || !isNameStart(name[start]) || name[start] == ':') {
            return false;
        }
        for (int i = start + 1; i < start + length; i++) {
            if (!isValid(name[i]) || name[i] == ':') {
                return false;
            }
        }
        return true;
    }

    public static boolean isNmtoken(char[] token, int start, int length) {
        if (length == 0) {
            return false;
        }
        for (int i = start; i < start + length; i++) {
            if (!isValid(token[i])) {
                return false;
            }
        }
        return true;
    }

    public static boolean isPublicIdentifier(char[] identifier, int start, int length) {
        // Simplified check for public identifiers
        return isNmtoken(identifier, start, length);
    }

    public static boolean isSupplementaryCharacter(char high, char low) {
        return Character.isHighSurrogate(high) && Character.isLowSurrogate(low);
    }

    public static boolean isSurrogatePair(char high, char low) {
        return isSupplementaryCharacter(high, low);
    }

