public class FacetProcessor {
    private List<FacetFactory> factories;
    private Map<Class<?>, List<Method>> cachedMethods;

    public FacetProcessor() {
        this.factories = new ArrayList<>();
        this.cachedMethods = new HashMap<>();
    }

    public void registerFactory(FacetFactory factory) {
        factories.add(factory);
    }

    public void processClass(Class<?> clazz) {
        List<Method> methods = getCachedMethods(clazz);
        for (Method method : methods) {
            processMethod(method);
        }
    }

    private List<Method> getCachedMethods(Class<?> clazz) {
        if (!cachedMethods.containsKey(clazz)) {
            List<Method> methods = new ArrayList<>();
            for (Method method : clazz.getDeclaredMethods()) {
                if (isValidMethod(method)) {
                    methods.add(method);
                }
            }
            cachedMethods.put(clazz, methods);
        }
        return cachedMethods.get(clazz);
    }

    private boolean isValidMethod(Method method) {
        // Code smell: This method could be more complex and may need refactoring
        return method.getName().startsWith("get") || method.getName().startsWith("set");
    }

    private void processMethod(Method method) {
        for (FacetFactory factory : factories) {
            factory.process(method);
        }
    }

    public void removeMethodAccessor(Class<?> clazz, String methodName) {
        List<Method> methods = cachedMethods.get(clazz);
        if (methods != null) {
            methods.removeIf(method -> method.getName().equals(methodName));
        }
    }
}

