public class Reflection {
    private static final Map<Class<?>, Map<String, Method>> getterCache = new HashMap<>();
    private static final Map<Class<?>, Map<String, Method>> setterCache = new HashMap<>();

    public static Object getFieldValue(Object obj, String fieldName) {
        try {
            Field field = obj.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            return field.get(obj);
        } catch (NoSuchFieldException | IllegalAccessException e) {
            throw new RuntimeException("Error accessing field value", e);
        }
    }

    public static void setFieldValue(Object obj, String fieldName, Object value) {
        try {
            Field field = obj.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(obj, value);
        } catch (NoSuchFieldException | IllegalAccessException e) {
            throw new RuntimeException("Error setting field value", e);
        }
    }

    public static Method getGetter(Class<?> clazz, String propertyName) {
        return getterCache.computeIfAbsent(clazz, k -> new HashMap<>()).computeIfAbsent(propertyName, k -> {
            String getterName = "get" + capitalize(propertyName);
            try {
                Method method = clazz.getMethod(getterName);
                method.setAccessible(true);
                return method;
            } catch (NoSuchMethodException e) {
                throw new RuntimeException("Getter not found", e);
            }
        });
    }

    public static Method getSetter(Class<?> clazz, String propertyName) {
        return setterCache.computeIfAbsent(clazz, k -> new HashMap<>()).computeIfAbsent(propertyName, k -> {
            String setterName = "set" + capitalize(propertyName);
            try {
                Method method = clazz.getMethod(setterName, getFieldType(clazz, propertyName));
                method.setAccessible(true);
                return method;
            } catch (NoSuchMethodException e) {
                throw new RuntimeException("Setter not found", e);
            }
        });
    }

    public static String[] getBeanPropertyNames(Class<?> clazz) {
        List<String> propertyNames = new ArrayList<>();
        for (Method method : clazz.getDeclaredMethods()) {
            if (isGetter(method)) {
                propertyNames.add(getPropertyName(method));
            }
        }
        return propertyNames.toArray(new String[0]);
    }

    public static String[] getPublicFieldNames(Class<?> clazz) {
        Field[] fields = clazz.getFields();
        String[] fieldNames = new String[fields.length];
        for (int i = 0; i < fields.length; i++) {
            fieldNames[i] = fields[i].getName();
        }
        return fieldNames;
    }

    private static boolean isGetter(Method method) {
        return method.getName().startsWith("get") && method.getParameterCount() == 0;
    }

    private static String getPropertyName(Method method) {
        String name = method.getName().substring(3);
        return decapitalize(name);
    }

    private static Class<?> getFieldType(Class<?> clazz, String propertyName) {
        try {
            Field field = clazz.getDeclaredField(propertyName);
            return field.getType();
        } catch (NoSuchFieldException e) {
            throw new RuntimeException("Field not found", e);
        }
    }

    private static String capitalize(String str) {
        return str.substring(0, 1).toUpperCase() + str.substring(1);
    }

    private static String decapitalize(String str) {
        return str.substring(0, 1).toLowerCase() + str.substring(1);
    }
}

