            solver.solve(objective, constraints);
        });
    }

    @Test
    public void testTrivialModel() {
        double[] objective = {1};
        double[][] constraints = {
            {1, 1}
        };
        double[] solution = solver.solve(objective, constraints);
        assertArrayEquals(new double[]{0}, solution);
    }

    @Test
    public void testLargeModel() {
        double[] objective = {1, 1, 1, 1, 1};
        double[][] constraints = new double[100][6];
        for (int i = 0; i < 100; i++) {
            constraints[i][0] = 1;
            constraints[i][1] = 1;
            constraints[i][2] = 1;
            constraints[i][3] = 1;
            constraints[i][4] = 1;
            constraints[i][5] = 10;
        }
        double[] solution = solver.solve(objective, constraints);
        assertNotNull(solution);
    }

    @Test
    public void testValidationOfSolutions() {
        double[] objective = {2, 3};
        double[][] constraints = {
            {1, 2, 6},
            {2, 1, 8}
        };
