public class SparseFieldVector<T extends FieldElement<T>> implements FieldVector<T>, Serializable {
    private final int dimension;
    private final Field<T> field;
    private final Map<Integer, T> entries;

    public SparseFieldVector(Field<T> field, int dimension) {
        if (dimension <= 0) {
            throw new IllegalArgumentException("Dimension must be positive.");
        }
        this.field = field;
        this.dimension = dimension;
        this.entries = new HashMap<>();
    }

    public SparseFieldVector(Field<T> field, T[] values) {
        this(field, values.length);
        for (int i = 0; i < values.length; i++) {
            if (!values[i].isZero()) {
                entries.put(i, values[i]);
            }
        }
    }

    @Override
    public SparseFieldVector<T> add(FieldVector<T> v) {
        checkVectorDimensions(v);
        SparseFieldVector<T> result = new SparseFieldVector<>(field, dimension);
        for (Map.Entry<Integer, T> entry : entries.entrySet()) {
            result.setEntry(entry.getKey(), entry.getValue().add(v.getEntry(entry.getKey())));
        }
        return result;
    }

    @Override
    public SparseFieldVector<T> subtract(FieldVector<T> v) {
        checkVectorDimensions(v);
        SparseFieldVector<T> result = new SparseFieldVector<>(field, dimension);
        for (Map.Entry<Integer, T> entry : entries.entrySet()) {
            result.setEntry(entry.getKey(), entry.getValue().subtract(v.getEntry(entry.getKey())));
        }
        return result;
    }

    @Override
    public SparseFieldVector<T> scalarMultiply(T scalar) {
        SparseFieldVector<T> result = new SparseFieldVector<>(field, dimension);
        for (Map.Entry<Integer, T> entry : entries.entrySet()) {
            result.setEntry(entry.getKey(), entry.getValue().multiply(scalar));
        }
        return result;
    }

    @Override
    public T dotProduct(FieldVector<T> v) {
        checkVectorDimensions(v);
        T sum = field.getZero();
        for (Map.Entry<Integer, T> entry : entries.entrySet()) {
            sum = sum.add(entry.getValue().multiply(v.getEntry(entry.getKey())));
        }
        return sum;
    }

    @Override
    public SparseFieldVector<T> outerProduct(FieldVector<T> v) {
        SparseFieldVector<T> result = new SparseFieldVector<>(field, dimension * v.getDimension());
        for (Map.Entry<Integer, T> entry : entries.entrySet()) {
            for (int j = 0; j < v.getDimension(); j++) {
                result.setEntry(entry.getKey() * v.getDimension() + j, entry.getValue().multiply(v.getEntry(j)));
            }
        }
        return result;
    }

    public void append(T value) {
        entries.put(dimension++, value);
    }

    public T getEntry(int index) {
        checkIndex(index);
        return entries.getOrDefault(index, field.getZero());
    }

    public void setEntry(int index, T value) {
        checkIndex(index);
        if (value.isZero()) {
            entries.remove(index);
        } else {
            entries.put(index, value);
        }
    }

    private void checkIndex(int index) {
        if (index < 0 || index >= dimension) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Dimension: " + dimension);
        }
    }

    private void checkVectorDimensions(FieldVector<T> v) {
        if (v.getDimension() != dimension) {
            throw new IllegalArgumentException("Vector dimensions do not match.");
        }
    }

    @Override
    public int getDimension() {
        return dimension;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof SparseFieldVector)) return false;
        SparseFieldVector<?> that = (SparseFieldVector<?>) o;
        return dimension == that.dimension && Objects.equals(field, that.field) && Objects.equals(entries, that.entries);
    }

    @Override
    public int hashCode() {
        return Objects.hash(dimension, field, entries);
    }

    @Override
    public Iterator<T> iterator() {
        return new Iterator<T>() {
            private final Iterator<Map.Entry<Integer, T>> it = entries.entrySet().iterator();
            private int currentIndex = 0;

            @Override
            public boolean hasNext() {
                return it.hasNext() || currentIndex < dimension;
            }

            @Override
            public T next() {
                if (it.hasNext()) {
                    Map.Entry<Integer, T> entry = it.next();
                    currentIndex = entry.getKey() + 1;
                    return entry.getValue();
                } else {
                    return field.getZero();
                }
            }
        };
    }
}

