        assertEquals("defaultDomain", permission.getDomain());
        assertArrayEquals(new String[]{"read"}, permission.getActions());
        assertNull(permission.getTargets());
        assertArrayEquals(new String[]{"defaultDomain", "read"}, permission.getParts());
    }

    @Test
    void testMultipleActionsConstructor() {
        DomainPermission permission = new DomainPermission(new String[]{"read", "write"});
        assertEquals("defaultDomain", permission.getDomain());
        assertArrayEquals(new String[]{"read", "write"}, permission.getActions());
        assertNull(permission.getTargets());
        assertArrayEquals(new String[]{"defaultDomain", "read", "write"}, permission.getParts());
    }

    @Test
    void testSingleActionAndTargetConstructor() {
        DomainPermission permission = new DomainPermission("read", "file.txt");
        assertEquals("defaultDomain", permission.getDomain());
        assertArrayEquals(new String[]{"read"}, permission.getActions());
        assertArrayEquals(new String[]{"file.txt"}, permission.getTargets());
        assertArrayEquals(new String[]{"defaultDomain", "read", "file.txt"}, permission.getParts());
    }

    @Test
    void testMultipleActionsAndTargetsConstructor() {
