public class DataRowStore implements Serializable {
    private static final long serialVersionUID = 1L;
    private static final Logger logger = Logger.getLogger(DataRowStore.class.getName());

    private final Map<ObjectId, DataRowSnapshot> snapshotStore;
    private final int maxSize;
    private final List<Consumer<DataRowEvent>> listeners;
    private final ReentrantLock lock;

    public DataRowStore(int maxSize) {
        this.snapshotStore = new ConcurrentHashMap<>();
        this.maxSize = maxSize;
        this.listeners = new ArrayList<>();
        this.lock = new ReentrantLock();
    }

    public void addSnapshot(ObjectId id, DataRowSnapshot snapshot) {
        lock.lock();
        try {
            if (snapshotStore.size() >= maxSize) {
                evictSnapshot();
            }
            snapshotStore.put(id, snapshot);
            notifyListeners(new DataRowEvent(DataRowEventType.ADDED, id));
        } finally {
            lock.unlock();
        }
    }

    public DataRowSnapshot getSnapshot(ObjectId id) {
        return snapshotStore.get(id);
    }

    public void updateSnapshot(ObjectId id, DataRowSnapshot snapshot) {
        lock.lock();
        try {
            if (snapshotStore.containsKey(id)) {
                snapshotStore.put(id, snapshot);
                notifyListeners(new DataRowEvent(DataRowEventType.UPDATED, id));
            }
        } finally {
            lock.unlock();
        }
    }

    public void removeSnapshot(ObjectId id) {
        lock.lock();
        try {
            if (snapshotStore.remove(id) != null) {
                notifyListeners(new DataRowEvent(DataRowEventType.REMOVED, id));
            }
        } finally {
            lock.unlock();
        }
    }

    public void processRemoteEvent(DataRowEvent event) {
        switch (event.getType()) {
            case ADDED:
                // Handle added event
                break;
            case UPDATED:
                // Handle updated event
                break;
            case REMOVED:
                // Handle removed event
                break;
        }
    }

    public void addListener(Consumer<DataRowEvent> listener) {
        listeners.add(listener);
    }

    public void removeListener(Consumer<DataRowEvent> listener) {
        listeners.remove(listener);
    }

    private void notifyListeners(DataRowEvent event) {
        for (Consumer<DataRowEvent> listener : listeners) {
            listener.accept(event);
        }
    }

    private void evictSnapshot() {
        // Implement eviction logic (e.g., remove oldest snapshot)
        Optional<ObjectId> oldestId = snapshotStore.keySet().stream().findFirst();
        oldestId.ifPresent(this::removeSnapshot);
    }

    public void serialize(String filePath) {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(filePath))) {
            oos.writeObject(this);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Serialization error", e);
        }
    }

    public static DataRowStore deserialize(String filePath) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            return (DataRowStore) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            logger.log(Level.SEVERE, "Deserialization error", e);
            return null;
        }
    }
}

