public class KrbCredInfo implements Asn1Object {
    private byte[] encryptionKey;
    private List<String> principalNames;
    private int ticketFlags;
    private long authTime;
    private long startTime;
    private long endTime;
    private List<String> clientAddresses;

    public KrbCredInfo(byte[] encryptionKey, List<String> principalNames, int ticketFlags, long authTime, long startTime, long endTime, List<String> clientAddresses) {
        this.encryptionKey = encryptionKey;
        this.principalNames = principalNames;
        this.ticketFlags = ticketFlags;
        this.authTime = authTime;
        this.startTime = startTime;
        this.endTime = endTime;
        this.clientAddresses = clientAddresses;
    }

    public int computeLength() {
        // Code smell: Length calculation logic is not encapsulated
        int length = 0;
        length += encryptionKey.length;
        length += principalNames.stream().mapToInt(String::length).sum();
        length += Integer.BYTES; // ticketFlags
        length += Long.BYTES * 3; // authTime, startTime, endTime
        length += clientAddresses.stream().mapToInt(String::length).sum();
        return length;
    }

    public ByteBuffer encode() {
        // Code smell: Encoding logic is not separated from the data structure
        ByteBuffer buffer = ByteBuffer.allocate(computeLength());
        buffer.put(encryptionKey);
        for (String name : principalNames) {
            buffer.put(name.getBytes());
        }
        buffer.putInt(ticketFlags);
        buffer.putLong(authTime);
        buffer.putLong(startTime);
        buffer.putLong(endTime);
        for (String address : clientAddresses) {
            buffer.put(address.getBytes());
        }
        return buffer;
    }

    public byte[] getEncryptionKey() {
        return encryptionKey;
    }

    public void setEncryptionKey(byte[] encryptionKey) {
        this.encryptionKey = encryptionKey;
    }

    public List<String> getPrincipalNames() {
