public class SubAnt extends Task {
    private String buildFile;
    private boolean verbose;
    private boolean failOnError;
    private List<String> targets = new ArrayList<>();
    private List<String> buildPath = new ArrayList<>();
    private Project project;

    public void setBuildFile(String buildFile) {
        this.buildFile = buildFile;
    }

    public void setVerbose(boolean verbose) {
        this.verbose = verbose;
    }

    public void setFailOnError(boolean failOnError) {
        this.failOnError = failOnError;
    }

    public void addTarget(String target) {
        targets.add(target);
    }

    public void addBuildPath(String path) {
        buildPath.add(path);
    }

    @Override
    public void execute() {
        project = new Project();
        project.setUserProperty("ant.file", buildFile);
        project.setVerbose(verbose);
        project.init();

        ProjectHelper helper = ProjectHelper.getProjectHelper();
        project.addReference("ant.projectHelper", helper);
        helper.parse(project, new File(buildFile));

        for (String dir : buildPath) {
            File directory = new File(dir);
            if (directory.exists() && directory.isDirectory()) {
                project.setBaseDir(directory);
                for (String target : targets) {
                    try {
                        project.executeTarget(target);
                    } catch (Exception e) {
                        if (failOnError) {
                            throw new RuntimeException("Error executing target: " + target, e);
                        }
                    }
                }
            } else {
                log("Directory does not exist: " + dir);
            }
        }
    }
}

