public class HostManagerServlet extends HttpServlet {

    private StringManager stringManager;
    private int debugLevel;

    @Override
    public void init() throws ServletException {
        super.init();
        stringManager = new StringManager();
        debugLevel = 1; // Default debug level
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String command = request.getParameter("command");
        PrintWriter writer = response.getWriter();

        switch (command) {
            case "add":
                addHost(request, writer);
                break;
            case "remove":
                removeHost(request, writer);
                break;
            case "list":
                listHosts(writer);
                break;
            case "start":
                startHost(request, writer);
                break;
            case "stop":
                stopHost(request, writer);
                break;
            default:
                writer.println(stringManager.getString("invalidCommand"));
                break;
        }
    }

    private void addHost(HttpServletRequest request, PrintWriter writer) {
        String hostName = request.getParameter("hostName");
        // Logic to add host
        writer.println(stringManager.getString("hostAdded", hostName));
    }

    private void removeHost(HttpServletRequest request, PrintWriter writer) {
        String hostName = request.getParameter("hostName");
        // Logic to remove host
        writer.println(stringManager.getString("hostRemoved", hostName));
    }

    private void listHosts(PrintWriter writer) {
        // Logic to list hosts
