    }

    private void startHost(HttpServletRequest request, PrintWriter writer) {
        String hostName = request.getParameter("hostName");
        // Logic to start host
        writer.println(stringManager.getString("hostStarted", hostName));
    }

    private void stopHost(HttpServletRequest request, PrintWriter writer) {
