public class FailoverTransactionTest {

    private BrokerService broker;
    private Connection connection;
    private Session session;
    private MessageProducer producer;
    private MessageConsumer consumer;
    private static final String BROKER_URL = "tcp://localhost:61616";
    private static final String QUEUE_NAME = "testQueue";

    @Before
    public void setUp() throws Exception {
        broker = new BrokerService();
        broker.setPersistent(false);
        broker.addConnector(BROKER_URL);
        broker.start();

        ActiveMQConnectionFactory connectionFactory = new ActiveMQConnectionFactory(BROKER_URL);
        connection = connectionFactory.createConnection();
        connection.start();
        session = connection.createSession(true, Session.SESSION_TRANSACTED);
        Queue queue = session.createQueue(QUEUE_NAME);
        producer = session.createProducer(queue);
        consumer = session.createConsumer(queue);
    }

    @After
    public void tearDown() throws Exception {
        if (session != null) {
            session.close();
        }
        if (connection != null) {
            connection.close();
        }
        if (broker != null) {
            broker.stop();
        }
    }

    @Test
    public void testTransactionCommit() throws Exception {
        TextMessage message = session.createTextMessage("Test Message");
        producer.send(message);
        session.commit();

        // Simulate broker failure
        broker.stop();
        broker.start();

        // Verify message consumption
        TextMessage receivedMessage = (TextMessage) consumer.receive(1000);
        assertNotNull(receivedMessage);
        assertEquals("Test Message", receivedMessage.getText());
    }

    @Test
    public void testTransactionRollback() throws Exception {
        TextMessage message = session.createTextMessage("Test Message");
        producer.send(message);
        session.rollback();

        // Simulate broker failure
        broker.stop();
        broker.start();

        // Verify no message consumption
        TextMessage receivedMessage = (TextMessage) consumer.receive(1000);
        assertNull(receivedMessage);
    }

    @Test
    public void testProducerConsumerDuringBrokerRestart() throws Exception {
        TextMessage message = session.createTextMessage("Test Message");
        producer.send(message);
        session.commit();

        // Simulate broker restart
        broker.stop();
        broker.start();

        // Verify message consumption
        TextMessage receivedMessage = (TextMessage) consumer.receive(1000);
        assertNotNull(receivedMessage);
        assertEquals("Test Message", receivedMessage.getText());
    }

    @Test
    public void testMultipleTransactions() throws Exception {
        for (int i = 0; i < 5; i++) {
            TextMessage message = session.createTextMessage("Message " + i);
            producer.send(message);
        }
        session.commit();

        // Simulate broker failure
        broker.stop();
        broker.start();

        for (int i = 0; i < 5; i++) {
            TextMessage receivedMessage = (TextMessage) consumer.receive(1000);
            assertNotNull(receivedMessage);
            assertEquals("Message " + i, receivedMessage.getText());
        }
    }
}

public class MillerUpdatingRegression {
    private int n; // number of observations
    private int p; // number of predictors
    private double[] coefficients; // regression coefficients
    private double[] residuals; // residuals
    private double rss; // residual sum of squares
    private double tolerance; // tolerance for numerical stability
    private boolean includeIntercept; // flag for intercept inclusion

    public MillerUpdatingRegression(int numPredictors, boolean includeIntercept) {
        this.p = numPredictors;
        this.includeIntercept = includeIntercept;
        this.n = 0;
        this.coefficients = new double[numPredictors + (includeIntercept ? 1 : 0)];
        this.residuals = new double[numPredictors + (includeIntercept ? 1 : 0)];
        this.rss = 0.0;
        this.tolerance = 1e-10;
    }

    public void addObservation(double[] x, double y) {
        if (x.length != p) {
            throw new IllegalArgumentException("Incorrect number of predictors.");
        }
        n++;
        double[] xWithIntercept = includeIntercept ? new double[p + 1] : x;
        if (includeIntercept) {
            xWithIntercept[0] = 1.0; // intercept term
            System.arraycopy(x, 0, xWithIntercept, 1, p);
        }
        updateCoefficients(xWithIntercept, y);
    }

    private void updateCoefficients(double[] x, double y) {
        double predicted = predict(x);
        double residual = y - predicted;
        rss += residual * residual;
        for (int i = 0; i < coefficients.length; i++) {
            coefficients[i] += (residual / n) * x[i];
        }
    }

    public double predict(double[] x) {
        double[] xWithIntercept = includeIntercept ? new double[p + 1] : x;
        if (includeIntercept) {
            xWithIntercept[0] = 1.0; // intercept term
            System.arraycopy(x, 0, xWithIntercept, 1, p);
        }
        double prediction = 0.0;
        for (int i = 0; i < coefficients.length; i++) {
            prediction += coefficients[i] * xWithIntercept[i];
        }
        return prediction;
    }

    public double getRss() {
        return rss;
    }

    public double[] getCoefficients() {
        return Arrays.copyOf(coefficients, coefficients.length);
    }

    public int getNumberOfObservations() {
        return n;
    }

    public double getAdjustedR2() {
        return 1 - (1 - (1 - (rss / n))) * (n - 1) / (n - p - 1);
    }

    public double[][] getCovarianceMatrix() {
        double[][] covarianceMatrix = new double[coefficients.length][coefficients.length];
        // Placeholder for covariance matrix calculation
        return covarianceMatrix;
    }

    public double[] getPartialCorrelations() {
        double[] partialCorrelations = new double[coefficients.length];
        // Placeholder for partial correlation calculation
        return partialCorrelations;
    }
}

public class GeneralizedTimeValueDialog extends JDialog {
    private JSpinner hourSpinner;
    private JSpinner minuteSpinner;
    private JSpinner secondSpinner;
    private JComboBox<String> timezoneComboBox;
    private JTextField rawValueField;
    private JCheckBox discardFractionalSecondsCheckBox;
    private JButton okButton;
    private JButton cancelButton;
    private GeneralizedTime generalizedTime;

    public GeneralizedTimeValueDialog(Frame owner, GeneralizedTime generalizedTime) {
        super(owner, "Edit Generalized Time", true);
        this.generalizedTime = generalizedTime;
        initializeComponents();
        configureDialog();
        populateFields();
    }

    private void initializeComponents() {
        hourSpinner = new JSpinner(new SpinnerNumberModel(0, 0, 23, 1));
        minuteSpinner = new JSpinner(new SpinnerNumberModel(0, 0, 59, 1));
        secondSpinner = new JSpinner(new SpinnerNumberModel(0, 0, 59, 1));
        timezoneComboBox = new JComboBox<>(TimeZone.getAvailableIDs());
        rawValueField = new JTextField(20);
        discardFractionalSecondsCheckBox = new JCheckBox("Discard Fractional Seconds");
        okButton = new JButton("OK");
        cancelButton = new JButton("Cancel");

        okButton.addActionListener(new ActionListener() {
            public void actionPerformed(ActionEvent e) {
                if (validateRawValue()) {
                    updateGeneralizedTime();
                    dispose();
                } else {
                    JOptionPane.showMessageDialog(GeneralizedTimeValueDialog.this, "Invalid raw value format.", "Error", JOptionPane.ERROR_MESSAGE);
                }
            }
        });

        cancelButton.addActionListener(new ActionListener() {
            public void actionPerformed(ActionEvent e) {
                dispose();
            }
        });
    }

    private void configureDialog() {
        setLayout(new GridLayout(0, 2));
        add(new JLabel("Hour:"));
        add(hourSpinner);
        add(new JLabel("Minute:"));
        add(minuteSpinner);
        add(new JLabel("Second:"));
        add(secondSpinner);
        add(new JLabel("Timezone:"));
        add(timezoneComboBox);
        add(new JLabel("Raw Value:"));
        add(rawValueField);
        add(discardFractionalSecondsCheckBox);
        add(okButton);
        add(cancelButton);
        pack();
        setLocationRelativeTo(getOwner());
    }

    private void populateFields() {
        // Populate fields based on the generalizedTime object
        // Assuming GeneralizedTime has appropriate getter methods
        hourSpinner.setValue(generalizedTime.getHour());
        minuteSpinner.setValue(generalizedTime.getMinute());
        secondSpinner.setValue(generalizedTime.getSecond());
        timezoneComboBox.setSelectedItem(generalizedTime.getTimeZone().getID());
        rawValueField.setText(generalizedTime.getRawValue());
        discardFractionalSecondsCheckBox.setSelected(generalizedTime.isDiscardFractionalSeconds());
    }

    private boolean validateRawValue() {
        String rawValue = rawValueField.getText();
        // Simple validation for the raw value format
        return rawValue.matches("\\d{8}(\\.\\d{1,3})?Z");
    }

    private void updateGeneralizedTime() {
        generalizedTime.setHour((Integer) hourSpinner.getValue());
        generalizedTime.setMinute((Integer) minuteSpinner.getValue());
        generalizedTime.setSecond((Integer) secondSpinner.getValue());
        generalizedTime.setTimeZone(TimeZone.getTimeZone((String) timezoneComboBox.getSelectedItem()));
        generalizedTime.setRawValue(rawValueField.getText());
        generalizedTime.setDiscardFractionalSeconds(discardFractionalSecondsCheckBox.isSelected());
    }
}

