public class SourceCodeBuilder {
    private ConstantPool constantPool;
    private boolean showLineNumbers;
    private boolean showVersionInfo;

    public SourceCodeBuilder(ConstantPool constantPool, boolean showLineNumbers, boolean showVersionInfo) {
        this.constantPool = constantPool;
        this.showLineNumbers = showLineNumbers;
        this.showVersionInfo = showVersionInfo;
    }

    public String toString(JavaClass javaClass) {
        StringBuilder sb = new StringBuilder();
        if (showVersionInfo) {
            sb.append("Version: ").append(javaClass.getVersion()).append("\n");
        }
        sb.append("Class: ").append(javaClass.getName()).append("\n");
        sb.append("Access Flags: ").append(javaClass.getAccessFlags()).append("\n");

        appendFields(sb, javaClass.getFields());
        appendMethods(sb, javaClass.getMethods());
        appendAttributes(sb, javaClass.getAttributes());

        return sb.toString();
    }

    private void appendFields(StringBuilder sb, List<Field> fields) {
        for (Field field : fields) {
            sb.append("Field: ").append(field.getName()).append(" ")
              .append(field.getType()).append("\n");
        }
    }

    private void appendMethods(StringBuilder sb, List<Method> methods) {
        for (Method method : methods) {
            sb.append("Method: ").append(method.getName()).append("(")
              .append(formatParameters(method.getParameters())).append(") ")
              .append(method.getReturnType()).append("\n");
            appendExceptions(sb, method.getExceptions());
        }
    }

    private String formatParameters(List<String> parameters) {
        return String.join(", ", parameters);
    }

    private void appendExceptions(StringBuilder sb, List<String> exceptions) {
        if (!exceptions.isEmpty()) {
            sb.append("Throws: ").append(String.join(", ", exceptions)).append("\n");
        }
    }

    private void appendAttributes(StringBuilder sb, List<Attribute> attributes) {
        for (Attribute attribute : attributes) {
            sb.append("Attribute: ").append(attribute.getName()).append("\n");
            if (attribute instanceof LineNumberTable && showLineNumbers) {
                appendLineNumberTable(sb, (LineNumberTable) attribute);
            }
            // Other attribute types can be handled here
        }
    }

    private void appendLineNumberTable(StringBuilder sb, LineNumberTable lineNumberTable) {
        for (LineNumber lineNumber : lineNumberTable.getLineNumbers()) {
            sb.append("Line: ").append(lineNumber.getLineNumber()).append(" at ")
              .append(lineNumber.getStartPC()).append("\n");
        }
    }
}

public class JspReader {
    private List<File> sourceFiles;
    private BufferedReader currentReader;
    private int currentPosition;
    private ErrorDispatcher errorDispatcher;
    private Stack<Integer> markStack;

    public JspReader(ErrorDispatcher errorDispatcher) {
        this.sourceFiles = new ArrayList<>();
        this.currentPosition = 0;
        this.errorDispatcher = errorDispatcher;
        this.markStack = new Stack<>();
    }

    public void registerSourceFile(File file) {
        sourceFiles.add(file);
        if (currentReader == null) {
            openNextFile();
        }
    }

    public void unregisterSourceFile(File file) {
        sourceFiles.remove(file);
        if (currentReader == null && !sourceFiles.isEmpty()) {
            openNextFile();
        }
    }

    private void openNextFile() {
        if (!sourceFiles.isEmpty()) {
            try {
                currentReader = new BufferedReader(new FileReader(sourceFiles.get(0)));
            } catch (FileNotFoundException e) {
                errorDispatcher.reportError("File not found: " + sourceFiles.get(0).getName());
            }
        }
    }

    public String readNextToken() {
        StringBuilder token = new StringBuilder();
        try {
            int ch;
            while ((ch = currentReader.read()) != -1) {
                currentPosition++;
                if (Character.isWhitespace(ch)) {
                    if (token.length() > 0) {
                        break;
                    }
                } else {
                    token.append((char) ch);
                }
            }
            if (token.length() == 0 && ch == -1) {
                closeCurrentReader();
            }
        } catch (IOException e) {
            errorDispatcher.reportError("Error reading file: " + e.getMessage());
        }
        return token.toString();
    }

    public void markPosition() {
        markStack.push(currentPosition);
    }

    public void resetToMark() {
        if (!markStack.isEmpty()) {
            currentPosition = markStack.pop();
            try {
                currentReader.reset();
            } catch (IOException e) {
                errorDispatcher.reportError("Error resetting reader: " + e.getMessage());
            }
        }
    }

    private void closeCurrentReader() {
        try {
            if (currentReader != null) {
                currentReader.close();
                currentReader = null;
            }
        } catch (IOException e) {
            errorDispatcher.reportError("Error closing reader: " + e.getMessage());
        }
    }

    public void skipWhitespace() {
        try {
            while (currentReader.ready()) {
                int ch = currentReader.read();
                currentPosition++;
                if (!Character.isWhitespace(ch)) {
                    currentReader.unread(ch);
                    break;
                }
            }
        } catch (IOException e) {
            errorDispatcher.reportError("Error skipping whitespace: " + e.getMessage());
        }
    }
}

