    @Before
    public void setUp() throws Exception {
        zkConnection = new ZooKeeperConnection();
        zkConnection.connect("localhost");
        manager = new LedgerUnderreplicationManager(zkConnection);
    }

    @After
    public void tearDown() throws Exception {
        manager.cleanup();
        zkConnection.close();
    }

    @Test
    public void testMarkLedgerUnderreplicated() {
        long ledgerId = 12345L;
        manager.markLedgerUnderreplicated(ledgerId);
        assertTrue(manager.isLedgerUnderreplicated(ledgerId));
    }

    @Test
    public void testRetrieveLedgersForReplication() {
        long ledgerId1 = 12345L;
        long ledgerId2 = 67890L;
        manager.markLedgerUnderreplicated(ledgerId1);
        manager.markLedgerUnderreplicated(ledgerId2);

        List<Long> ledgers = manager.retrieveLedgersForReplication();
        assertTrue(ledgers.contains(ledgerId1));
        assertTrue(ledgers.contains(ledgerId2));
    }

    @Test
    public void testLockingMechanism() {
        long ledgerId = 12345L;
        manager.markLedgerUnderreplicated(ledgerId);
        assertTrue(manager.lockLedger(ledgerId));
        assertFalse(manager.lockLedger(ledgerId)); // Should fail to lock again
    }

    @Test
    public void testCleanupUnderreplicatedLedgers() {
        long ledgerId = 12345L;
        manager.markLedgerUnderreplicated(ledgerId);
        manager.cleanupUnderreplicatedLedgers();
        assertFalse(manager.isLedgerUnderreplicated(ledgerId));
    }

    @Test
    public void testReplicationEnabledBehavior() {
        manager.setReplicationEnabled(true);
        long ledgerId = 12345L;
        manager.markLedgerUnderreplicated(ledgerId);
        assertTrue(manager.isLedgerUnderreplicated(ledgerId));
    }

    @Test
    public void testReplicationDisabledBehavior() {
        manager.setReplicationEnabled(false);
        long ledgerId = 12345L;
        manager.markLedgerUnderreplicated(ledgerId);
        assertFalse(manager.isLedgerUnderreplicated(ledgerId)); // Should not mark as under-replicated
    }

    @Test
    public void testDuplicateEntriesForMissingReplicas() {
        long ledgerId = 12345L;
        manager.markLedgerUnderreplicated(ledgerId);
        manager.markLedgerUnderreplicated(ledgerId); // Duplicate mark
        List<Long> ledgers = manager.retrieveLedgersForReplication();
        assertEquals(1, ledgers.size()); // Should only be one entry
    }
}

