        cluster.stop();
    }

    @Test
    public void testKilledServerWithEnsembleProvider() {
        // Simulate multiple clients trying to acquire a semaphore
        for (SemaphoreClient client : clients) {
            client.acquireSemaphore();
        }

        // Stop the cluster
        cluster.stop();

        // Restart the cluster
        cluster.start();

        // Verify that clients can still acquire semaphores
        for (SemaphoreClient client : clients) {
            assertTrue(client.tryAcquireSemaphore());
        }
    }

    @Test
    public void testCluster() {
        // Submit multiple operations that require semaphore access
        for (SemaphoreClient client : clients) {
            client.submitOperation();
        }

        // Stop the cluster
        cluster.stop();

        // Restart the cluster
        cluster.start();

        // Verify that operations are processed correctly after recovery
        for (SemaphoreClient client : clients) {
            assertEquals(client.getExpectedOperationCount(), client.getActualOperationCount());
