public class OrderedCode {
    private static final byte ESCAPE_BYTE = (byte) 0xFF;
    private static final byte INFINITY_BYTE = (byte) 0xFE;
    private List<byte[]> encodedBytes = new ArrayList<>();
    private int currentIndex = 0;

    public void writeBytes(byte[] bytes) {
        for (byte b : bytes) {
            if (b == ESCAPE_BYTE || b == INFINITY_BYTE) {
                encodedBytes.add(new byte[]{ESCAPE_BYTE, b});
            } else {
                encodedBytes.add(new byte[]{b});
            }
        }
    }

    public void writeUnsignedInt(int value) {
        if (value == Integer.MAX_VALUE) {
            encodedBytes.add(new byte[]{INFINITY_BYTE});
        } else {
            encodedBytes.add(intToBytes(value));
        }
    }

    public void writeSignedInt(int value) {
        writeUnsignedInt(value >= 0 ? value : -value);
        if (value < 0) {
            encodedBytes.add(new byte[]{ESCAPE_BYTE});
        }
    }

    public byte[] readBytes() {
        if (currentIndex >= encodedBytes.size()) {
            return null;
        }
        byte[] bytes = encodedBytes.get(currentIndex++);
        if (bytes[0] == ESCAPE_BYTE && currentIndex < encodedBytes.size()) {
            byte nextByte = encodedBytes.get(currentIndex++)[0];
            return new byte[]{nextByte};
        }
        return bytes;
    }

    public int readUnsignedInt() {
        byte[] bytes = readBytes();
        if (bytes == null || bytes[0] == INFINITY_BYTE) {
            return Integer.MAX_VALUE;
        }
        return bytesToInt(bytes);
    }

    public int readSignedInt() {
        int value = readUnsignedInt();
        if (currentIndex < encodedBytes.size() && encodedBytes.get(currentIndex - 1)[0] == ESCAPE_BYTE) {
            return -value;
        }
        return value;
    }

    public byte[] getEncodedBytes() {
        return encodedBytes.stream().flatMap(byteArray -> java.util.Arrays.stream(byteArray)).collect(java.util.stream.Collectors.toList()).toArray(new byte[0]);
    }

    public boolean hasRemaining() {
        return currentIndex < encodedBytes.size();
    }

    private byte[] intToBytes(int value) {
        return new byte[]{
                (byte) (value >> 24),
                (byte) (value >> 16),
                (byte) (value >> 8),
                (byte) value
        };
    }

    private int bytesToInt(byte[] bytes) {
        return ((bytes[0] & 0xFF) << 24) |
               ((bytes[1] & 0xFF) << 16) |
               ((bytes[2] & 0xFF) << 8) |
               (bytes[3] & 0xFF);
    }
}

