        assertEquals("10.0.0.0", subnetUtils.getNetworkAddress());
        assertEquals("10.0.0.1", subnetUtils.getLowAddress());
        assertEquals("10.255.255.254", subnetUtils.getHighAddress());
        assertEquals(16777214, subnetUtils.getUsableAddressCount());
    }

