    public void testEdgeCase31() {
        SubnetUtils subnetUtils = new SubnetUtils("192.168.1.0/31");
        assertEquals("192.168.1.1", subnetUtils.getBroadcastAddress());
        assertEquals("192.168.1.0", subnetUtils.getNetworkAddress());
        assertEquals("192.168.1.0", subnetUtils.getLowAddress());
        assertEquals("192.168.1.1", subnetUtils.getHighAddress());
        assertEquals(0, subnetUtils.getUsableAddressCount());
    }

    @Test
    public void testEdgeCase32() {
        SubnetUtils subnetUtils = new SubnetUtils("192.168.1.1/32");
        assertEquals("192.168.1.1", subnetUtils.getBroadcastAddress());
        assertEquals("192.168.1.1", subnetUtils.getNetworkAddress());
        assertEquals("192.168.1.1", subnetUtils.getLowAddress());
        assertEquals("192.168.1.1", subnetUtils.getHighAddress());
        assertEquals(0, subnetUtils.getUsableAddressCount());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testInvalidNetmask() {
        new SubnetUtils("192.168.1.0/33");
    }

    @Test
    public void testInclusiveHostCount() {
        SubnetUtils subnetUtils = new SubnetUtils("192.168.1.0/24");
        assertEquals(256, subnetUtils.getTotalHostCount());
    }

    @Test
    public void testExclusiveHostCount() {
        SubnetUtils subnetUtils = new SubnetUtils("192.168.1.0/24");
        assertEquals(254, subnetUtils.getUsableAddressCount());
    }

    @Test
    public void testAddressRange() {
        SubnetUtils subnetUtils = new SubnetUtils("192.168.1.0/24");
        assertTrue(subnetUtils.isInRange("192.168.1.100"));
