    public static void main(String[] args) {
        if (args.length < 1) {
            printHelp();
            return;
        }

        String algorithm = DEFAULT_ALGORITHM;
        int iterations = DEFAULT_ITERATIONS;
        boolean useSalt = false;
        String input = null;

        for (String arg : args) {
            switch (arg) {
                case "-a":
                    algorithm = args[++i];
                    break;
                case "-i":
                    iterations = Integer.parseInt(args[++i]);
                    break;
                case "-s":
                    useSalt = true;
                    break;
                case "-f":
                    input = args[++i];
                    break;
                default:
                    input = arg;
                    break;
            }
        }

        try {
            String hash = generateHash(input, algorithm, iterations, useSalt);
            System.out.println("Hash: " + hash);
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
    }

    private static String generateHash(String input, String algorithm, int iterations, boolean useSalt) throws Exception {
        byte[] salt = useSalt ? generateSalt() : new byte[0];
        byte[] hash = hashPassword(input.getBytes(StandardCharsets.UTF_8), salt, algorithm, iterations);
        return formatOutput(hash, salt);
    }

    private static byte[] hashPassword(byte[] password, byte[] salt, String algorithm, int iterations) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance(algorithm);
        digest.update(salt);
        byte[] hash = digest.digest(password);
        for (int i = 1; i < iterations; i++) {
            hash = digest.digest(hash);
        }
        return hash;
    }

    private static byte[] generateSalt() {
        byte[] salt = new byte[SALT_LENGTH];
        new SecureRandom().nextBytes(salt);
        return salt;
    }

    private static String formatOutput(byte[] hash, byte[] salt) {
        StringBuilder sb = new StringBuilder();
        if (salt.length > 0) {
            sb.append(Base64.getEncoder().encodeToString(salt)).append(":");
        }
        sb.append(Base64.getEncoder().encodeToString(hash));
        return sb.toString();
    }

    private static void printHelp() {
        System.out.println("Usage: java Hasher [options] <input>");
        System.out.println("Options:");
        System.out.println("  -a <algorithm>  Specify hashing algorithm (default: SHA-256)");
        System.out.println("  -i <iterations> Specify number of iterations (default: 1000)");
        System.out.println("  -s              Use salt for hashing");
        System.out.println("  -f <file>       Read input from file");
        System.out.println("  <input>         Input value to hash");
    }
}

