public class TestTypesafeCriteria extends CriteriaTest {

    @Test
    public void testLiteralValues() {
        CriteriaQuery<Boolean> query = criteriaBuilder.createQuery(Boolean.class);
        Root<Entity> root = query.from(Entity.class);
        query.select(criteriaBuilder.literal(true));
        assertEquals("SELECT true FROM Entity", entityManager.createQuery(query).getSingleResult());
    }

    @Test
    public void testDefaultLogicalOperations() {
        CriteriaQuery<Boolean> query = criteriaBuilder.createQuery(Boolean.class);
        Root<Entity> root = query.from(Entity.class);
        query.select(criteriaBuilder.and(criteriaBuilder.equal(root.get("attribute"), "value"), 
                                          criteriaBuilder.isTrue(root.get("flag"))));
        assertEquals("SELECT CASE WHEN (entity.attribute = 'value' AND entity.flag = true) THEN true ELSE false END FROM Entity entity", entityManager.createQuery(query).getSingleResult());
    }

    @Test
    public void testExpressionsAndProjections() {
        CriteriaQuery<String> query = criteriaBuilder.createQuery(String.class);
        Root<Entity> root = query.from(Entity.class);
        query.select(criteriaBuilder.concat(root.get("firstName"), " ", root.get("lastName")));
        assertEquals("SELECT CONCAT(entity.firstName, ' ', entity.lastName) FROM Entity entity", entityManager.createQuery(query).getSingleResult());
    }

    @Test
    public void testJoinsAndSubqueries() {
        CriteriaQuery<String> query = criteriaBuilder.createQuery(String.class);
        Root<Entity> root = query.from(Entity.class);
        Join<Entity, RelatedEntity> join = root.join("relatedEntities");
        query.select(join.get("name"));
        assertEquals("SELECT relatedEntity.name FROM Entity entity JOIN entity.relatedEntities relatedEntity", entityManager.createQuery(query).getSingleResult());
    }

    @Test
    public void testAggregateFunctionsAndGrouping() {
        CriteriaQuery<Long> query = criteriaBuilder.createQuery(Long.class);
        Root<Entity> root = query.from(Entity.class);
        query.select(criteriaBuilder.count(root)).groupBy(root.get("groupAttribute"));
        assertEquals("SELECT COUNT(entity) FROM Entity entity GROUP BY entity.groupAttribute", entityManager.createQuery(query).getSingleResult());
    }

    @Test
    public void testParameterizedQueries() {
        CriteriaQuery<Entity> query = criteriaBuilder.createQuery(Entity.class);
        Root<Entity> root = query.from(Entity.class);
        query.select(root).where(criteriaBuilder.equal(root.get("attribute"), criteriaBuilder.parameter(String.class, "param")));
        assertEquals("SELECT entity FROM Entity entity WHERE entity.attribute = :param", entityManager.createQuery(query).getSingleResult());
    }

    @Test
    public void testHandlingOfExpressions() {
        CriteriaQuery<Integer> query = criteriaBuilder.createQuery(Integer.class);
        Root<Entity> root = query.from(Entity.class);
        query.select(criteriaBuilder.size(root.get("collectionAttribute")));
        assertEquals("SELECT SIZE(entity.collectionAttribute) FROM Entity entity", entityManager.createQuery(query).getSingleResult());
    }

    @Test
    public void testFunctionsAndAliases() {
        CriteriaQuery<Double> query = criteriaBuilder.createQuery(Double.class);
        Root<Entity> root = query.from(Entity.class);
        query.select(criteriaBuilder.avg(root.get("numericAttribute"))).alias("average");
        assertEquals("SELECT AVG(entity.numericAttribute) AS average FROM Entity entity", entityManager.createQuery(query).getSingleResult());
    }

    @Test
    public void testEmptyCollections() {
        CriteriaQuery<Boolean> query = criteriaBuilder.createQuery(Boolean.class);
        Root<Entity> root = query.from(Entity.class);
        query.select(criteriaBuilder.isEmpty(root.get("collectionAttribute")));
        assertEquals("SELECT CASE WHEN entity.collectionAttribute IS EMPTY THEN true ELSE false END FROM Entity entity", entityManager.createQuery(query).getSingleResult());
    }

    @Test
    public void testDistinctCounts() {
        CriteriaQuery<Long> query = criteriaBuilder.createQuery(Long.class);
        Root<Entity> root = query.from(Entity.class);
        query.select(criteriaBuilder.countDistinct(root.get("attribute")));
        assertEquals("SELECT COUNT(DISTINCT entity.attribute) FROM Entity entity", entityManager.createQuery(query).getSingleResult());
    }
}

