public class PigRelOpVisitor extends PigRelOpWalker.PlanPreVisitor {
    private PigRelBuilder relBuilder;
    private Object currentRoot;

    public PigRelOpVisitor(PigRelBuilder relBuilder) {
        this.relBuilder = relBuilder;
    }

    @Override
    public void visitLoad(LoadOperator load) {
        currentRoot = relBuilder.load(load.getFileName());
    }

    @Override
    public void visitFilter(FilterOperator filter) {
        relBuilder.filter(currentRoot, filter.getCondition());
    }

    @Override
    public void visitForeach(ForeachOperator foreach) {
        currentRoot = relBuilder.foreach(currentRoot, foreach.getTransformations());
    }

    @Override
    public void visitCogroup(CogroupOperator cogroup) {
        currentRoot = relBuilder.cogroup(currentRoot, cogroup.getGroupKeys());
    }

    @Override
    public void visitJoin(JoinOperator join) {
        currentRoot = relBuilder.join(currentRoot, join.getJoinKeys());
    }

    @Override
    public void visitRank(RankOperator rank) {
        currentRoot = relBuilder.rank(currentRoot, rank.getRankCriteria());
    }

    @Override
    public void visitDistinct(DistinctOperator distinct) {
        currentRoot = relBuilder.distinct(currentRoot);
    }

    @Override
    public void visitUnion(UnionOperator union) {
        currentRoot = relBuilder.union(currentRoot, union.getInputs());
    }

    @Override
    public void visitSort(SortOperator sort) {
        currentRoot = relBuilder.sort(currentRoot, sort.getSortKeys());
    }

    @Override
    public void visitGroup(GroupOperator group) {
        if (group.isCube()) {
            currentRoot = relBuilder.cube(currentRoot, group.getGroupKeys());
        } else if (group.isRollup()) {
            currentRoot = relBuilder.rollup(currentRoot, group.getGroupKeys());
        } else {
            currentRoot = relBuilder.group(currentRoot, group.getGroupKeys());
        }
    }

    @Override
    public void visitUnsupported(UnsupportedOperator unsupported) {
        throw new UnsupportedOperationException("Unsupported operation: " + unsupported.getClass().getSimpleName());
    }

    public Object getCurrentRoot() {
        return currentRoot;
    }
}

public class Conversion {

    public static int hexToInt(String hex) {
        return Integer.parseUnsignedInt(hex, 16);
    }

    public static String intToHex(int value) {
        return Integer.toHexString(value);
    }

    public static byte[] hexToBinary(String hex) {
        int len = hex.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            data[i / 2] = (byte) ((Character.digit(hex.charAt(i), 16) << 4)
                                 + Character.digit(hex.charAt(i + 1), 16));
        }
        return data;
    }

    public static String binaryToHex(byte[] binary) {
        StringBuilder sb = new StringBuilder();
        for (byte b : binary) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static int binaryToInt(byte[] binary) {
        return ByteBuffer.wrap(binary).getInt();
    }

    public static short binaryToShort(byte[] binary) {
        return ByteBuffer.wrap(binary).getShort();
    }

    public static byte[] intToBinary(int value) {
        return ByteBuffer.allocate(4).putInt(value).array();
    }

    public static byte[] shortToBinary(short value) {
        return ByteBuffer.allocate(2).putShort(value).array();
    }

    public static long hexToLong(String hex) {
        return Long.parseUnsignedLong(hex, 16);
    }

    public static byte[] longToBinary(long value) {
        return ByteBuffer.allocate(8).putLong(value).array();
    }

    public static UUID bytesToUUID(byte[] bytes) {
        ByteBuffer bb = ByteBuffer.wrap(bytes);
        long mostSigBits = bb.getLong();
        long leastSigBits = bb.getLong();
        return new UUID(mostSigBits, leastSigBits);
    }

    public static byte[] uuidToBytes(UUID uuid) {
        ByteBuffer bb = ByteBuffer.allocate(16);
        bb.putLong(uuid.getMostSignificantBits());
        bb.putLong(uuid.getLeastSignificantBits());
        return bb.array();
    }

    public static byte[] intToBytes(int value) {
        return ByteBuffer.allocate(4).putInt(value).array();
    }

    public static int bytesToInt(byte[] bytes) {
        return ByteBuffer.wrap(bytes).getInt();
    }

    public static byte[] shortToBytes(short value) {
        return ByteBuffer.allocate(2).putShort(value).array();
    }

    public static short bytesToShort(byte[] bytes) {
        return ByteBuffer.wrap(bytes).getShort();
    }

    public static byte[] longToBytes(long value) {
        return ByteBuffer.allocate(8).putLong(value).array();
    }

    public static long bytesToLong(byte[] bytes) {
        return ByteBuffer.wrap(bytes).getLong();
    }

    public static byte[] hexToBytes(String hex) {
        return hexToBinary(hex);
    }

    public static String bytesToHex(byte[] bytes) {
        return binaryToHex(bytes);
    }
}

