        initializeTempDir();
    }

    private void initializeTempDir() {
        if (!tempDir.exists()) {
            tempDir.mkdirs();
        }
    }

    public void loadDocuments() throws IOException {
        Files.walk(inputDir.toPath())
                .filter(Files::isRegularFile)
                .forEach(path -> exampleDocuments.add(path.toFile()));
    }

    public void processDocuments() {
        for (File document : exampleDocuments) {
            try {
                processDocument(document);
                processedDocumentsCount++;
            } catch (Exception e) {
                handleError(e, document);
            }
        }
    }

    protected abstract void processDocument(File document) throws Exception;

    public void testRules() {
        for (File document : exampleDocuments) {
            testDocumentAgainstRules(document);
        }
    }

    protected abstract void testDocumentAgainstRules(File document);

    protected void handleError(Exception e, File document) {
        System.err.println("Error processing document " + document.getName() + ": " + e.getMessage());
    }

    public void addInducedRule(String rule) {
        inducedRules.add(rule);
    }

    public List<String> getInducedRules() {
        return inducedRules;
    }

    public int getProcessedDocumentsCount() {
        return processedDocumentsCount;
    }

    public void clearTemporaryFiles() throws IOException {
        Files.walk(tempDir.toPath())
                .map(Path::toFile)
                .forEach(File::delete);
    }

    public void updateStatus(String message) {
        System.out.println("Status: " + message);
    }

    public void setAnalysisEngine(AnalysisEngine analysisEngine) {
        this.analysisEngine = analysisEngine;
    }
}

interface AnalysisEngine {
    void analyze(File document) throws Exception;
}

