class TestACLManager {
    private ACLManager aclManager;

    @BeforeEach
    public void setUp() {
        aclManager = new ACLManager();
    }

    @Test
    public void testCurrentUserACLChecks() {
        User currentUser = new User("currentUser", true);
        aclManager.addUser(currentUser);
        aclManager.setResourceACL("resource1", currentUser, ACL.READ | ACL.WRITE);

        assertTrue(aclManager.canView(currentUser, "resource1"));
        assertTrue(aclManager.canModify(currentUser, "resource1"));

        User otherUser = new User("otherUser", false);
        aclManager.addUser(otherUser);
        assertFalse(aclManager.canView(otherUser, "resource1"));
        assertFalse(aclManager.canModify(otherUser, "resource1"));
    }

    @Test
    public void testOtherUserACLChecks() {
        User user1 = new User("user1", true);
        User user2 = new User("user2", true);
        Group group = new Group("group1");
        group.addUser(user1);
        aclManager.addGroup(group);
        aclManager.setResourceACL("resource2", group, ACL.READ);

        assertTrue(aclManager.canView(user1, "resource2"));
        assertFalse(aclManager.canView(user2, "resource2"));
    }

