        User adminUser = new User("adminUser", true);
        aclManager.addUser(adminUser);
        aclManager.setResourceACL("amResource", adminUser, ACL.READ | ACL.WRITE);

        assertTrue(aclManager.canView(adminUser, "amResource"));
        assertTrue(aclManager.canModify(adminUser, "amResource"));

        User regularUser = new User("regularUser", false);
        aclManager.addUser(regularUser);
        assertFalse(aclManager.canView(regularUser, "amResource"));
