class TestPollingScanDiskSpaceMonitor {
    private PollingScanDiskSpaceMonitor monitor;
    private Path tempDir;

    @Before
    public void setUp() throws IOException {
        tempDir = Files.createTempDirectory("testDir");
        monitor = new PollingScanDiskSpaceMonitor(tempDir.toString());
    }

    @After
    public void tearDown() throws IOException {
        monitor.stop();
        Files.walk(tempDir)
                .sorted((a, b) -> b.compareTo(a)) // reverse order for deletion
                .map(Path::toFile)
                .forEach(File::delete);
    }

    @Test
    public void testSingleFileDiskSpace() throws IOException {
        File testFile = new File(tempDir.toFile(), "testFile.txt");
        Files.write(testFile.toPath(), "Hello World".getBytes());
        monitor.start();

        long usedSpace = monitor.getUsedSpace();
        assertEquals(testFile.length(), usedSpace);
    }

    @Test
    public void testDisjointDirectories() throws IOException {
        Path dir1 = Files.createDirectory(tempDir.resolve("dir1"));
        Path dir2 = Files.createDirectory(tempDir.resolve("dir2"));
        Files.write(dir1.resolve("file1.txt"), "File in dir1".getBytes());
        Files.write(dir2.resolve("file2.txt"), "File in dir2".getBytes());
        monitor.start();

        long usedSpace = monitor.getUsedSpace();
        assertEquals(Files.size(dir1.resolve("file1.txt")) + Files.size(dir2.resolve("file2.txt")), usedSpace);
    }

    @Test
    public void testOverlappingDirectories() throws IOException {
        Path dir1 = Files.createDirectory(tempDir.resolve("dir1"));
        Path dir2 = Files.createDirectory(tempDir.resolve("dir1/dir2"));
        Files.write(dir1.resolve("file1.txt"), "File in dir1".getBytes());
        Files.write(dir2.resolve("file2.txt"), "File in dir2".getBytes());
        monitor.start();

        long usedSpace = monitor.getUsedSpace();
        assertEquals(Files.size(dir1.resolve("file1.txt")) + Files.size(dir2.resolve("file2.txt")), usedSpace);
    }

    @Test
    public void testSymlinkHandling() throws IOException {
        Path targetFile = Files.createFile(tempDir.resolve("targetFile.txt"));
        Files.write(targetFile, "Target File".getBytes());
        Path symlink = Files.createSymbolicLink(tempDir.resolve("symlinkToTarget"), targetFile);
        monitor.start();

        long usedSpace = monitor.getUsedSpace();
        assertEquals(Files.size(targetFile), usedSpace);
    }

    @Test
    public void testMissingDirectory() {
        monitor.start();
        monitor.setDirectory(tempDir.resolve("missingDir").toString());
        long usedSpace = monitor.getUsedSpace();
        assertEquals(0, usedSpace);
    }

    @Test
    public void testListenerRegistration() {
        DiskSpaceListener listener = new DiskSpaceListener();
        monitor.registerListener(listener);
        monitor.start();
        assertTrue(monitor.isListenerRegistered(listener));
    }

    @Test
    public void testMonitorStartStop() {
        monitor.start();
        assertTrue(monitor.isRunning());
        monitor.stop();
        assertFalse(monitor.isRunning());
    }
}

