public class FailoverTest extends AbstractBusClientServerTestBase {
    private static final Logger LOG = LoggerFactory.getLogger(FailoverTest.class);
    private static final String PORT1 = allocatePort(FailoverTest.class);
    private static final String PORT2 = allocatePort(FailoverTest.class);
    private List<Greeter> greeterServices = new ArrayList<>();
    private Random random = new Random();

    @Before
    public void setUp() throws Exception {
        // Initialize server replicas
        startServer(PORT1);
        startServer(PORT2);
        greeterServices.add(createGreeterService("http://localhost:" + PORT1 + "/Greeter"));
        greeterServices.add(createGreeterService("http://localhost:" + PORT2 + "/Greeter"));
    }

    private void startServer(String port) {
        JaxWsServerFactoryBean factory = new JaxWsServerFactoryBean();
        factory.setAddress("http://localhost:" + port + "/Greeter");
        factory.setServiceClass(Greeter.class);
        factory.setServiceBean(new GreeterImpl());
        factory.create();
    }

    private Greeter createGreeterService(String address) {
        JaxWsProxyFactoryBean factory = new JaxWsProxyFactoryBean();
        factory.setServiceClass(Greeter.class);
        factory.setAddress(address);
        return (Greeter) factory.create();
    }

    @After
    public void tearDown() throws Exception {
        greeterServices.clear();
    }

    @Test
    public void testFailoverSequential() {
        // Simulate failure of the first server
        stopServer(PORT1);
        String response = greeterServices.get(1).greet("World");
        assertEquals("Hello, World", response);
    }

    @Test
    public void testFailoverRandom() {
        // Randomly stop one of the servers
        int indexToStop = random.nextInt(greeterServices.size());
        stopServer(indexToStop == 0 ? PORT1 : PORT2);
        String response = greeterServices.get(1 - indexToStop).greet("World");
        assertEquals("Hello, World", response);
    }

    @Test(expected = RuntimeException.class)
    public void testFailoverExceptionHandling() {
        stopServer(PORT1);
        greeterServices.get(0).greet("World");
    }

    @Test
    public void testEndpointSpecificSettings() {
        // Ensure settings do not persist across failovers
        String response1 = greeterServices.get(0).greet("World");
        assertEquals("Hello, World", response1);
        stopServer(PORT1);
        String response2 = greeterServices.get(1).greet("World");
        assertEquals("Hello, World", response2);
    }
}

