public class DefaultRecord implements Record {
    private final int size;
    private final long offset;
    private final long timestamp;
    private final long sequenceNumber;
    private final String key;
    private final String value;
    private final Map<String, String> headers;

    public DefaultRecord(int size, long offset, long timestamp, long sequenceNumber, String key, String value, Map<String, String> headers) {
        this.size = size;
        this.offset = offset;
        this.timestamp = timestamp;
        this.sequenceNumber = sequenceNumber;
        this.key = key;
        this.value = value;
        this.headers = headers != null ? new HashMap<>(headers) : new HashMap<>();
    }

    public int getSize() {
        return size;
    }

    public long getOffset() {
        return offset;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public long getSequenceNumber() {
        return sequenceNumber;
    }

    public String getKey() {
        return key;
    }

    public String getValue() {
        return value;
    }

    public Map<String, String> getHeaders() {
        return new HashMap<>(headers);
    }

    public boolean validate() {
        return key != null && value != null && !headers.isEmpty();
    }

    public void writeTo(OutputStream outputStream) throws IOException {
        DataOutputStream dataOutputStream = new DataOutputStream(outputStream);
        dataOutputStream.writeInt(size);
        dataOutputStream.writeLong(offset);
        dataOutputStream.writeLong(timestamp);
        dataOutputStream.writeLong(sequenceNumber);
        dataOutputStream.writeUTF(key);
        dataOutputStream.writeUTF(value);
        dataOutputStream.writeInt(headers.size());
        for (Map.Entry<String, String> entry : headers.entrySet()) {
            dataOutputStream.writeUTF(entry.getKey());
            dataOutputStream.writeUTF(entry.getValue());
        }
    }

    public static DefaultRecord readFrom(InputStream inputStream) throws IOException {
        DataInputStream dataInputStream = new DataInputStream(inputStream);
        int size = dataInputStream.readInt();
        long offset = dataInputStream.readLong();
        long timestamp = dataInputStream.readLong();
        long sequenceNumber = dataInputStream.readLong();
        String key = dataInputStream.readUTF();
        String value = dataInputStream.readUTF();
        int headersSize = dataInputStream.readInt();
        Map<String, String> headers = new HashMap<>();
        for (int i = 0; i < headersSize; i++) {
            String headerKey = dataInputStream.readUTF();
            String headerValue = dataInputStream.readUTF();
            headers.put(headerKey, headerValue);
        }
        return new DefaultRecord(size, offset, timestamp, sequenceNumber, key, value, headers);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof DefaultRecord)) return false;
        DefaultRecord that = (DefaultRecord) o;
        return size == that.size &&
                offset == that.offset &&
                timestamp == that.timestamp &&
                sequenceNumber == that.sequenceNumber &&
                Objects.equals(key, that.key) &&
                Objects.equals(value, that.value) &&
                Objects.equals(headers, that.headers);
    }

    @Override
    public int hashCode() {
        return Objects.hash(size, offset, timestamp, sequenceNumber, key, value, headers);
    }
}

