        this.activityRule = activityRule;
    }

    public T loadEntity(String correlationKey) {
        lock.lock();
        try {
            return entityManager.createQuery("SELECT e FROM " + entityClass.getSimpleName() + " e WHERE e." + correlationKeyPropertyName + " = :correlationKey", entityClass)
                    .setParameter("correlationKey", correlationKey)
                    .getSingleResult();
        } finally {
            lock.unlock();
        }
    }

    public void createEntity(T entity) {
        lock.lock();
        try {
            entityManager.persist(entity);
        } finally {
            lock.unlock();
        }
    }

