        return size;
    }

    public void setCharset(Charset charset) {
        this.charset = charset;
    }

    public Charset getCharset() {
        return charset;
    }

    public void addFileData(byte[] data) throws IOException {
        if (size + data.length > sizeThreshold) {
            createTempFile();
        }
        try (FileOutputStream fos = new FileOutputStream(tempFile, true)) {
            fos.write(data);
            size += data.length;
        }
    }

