public class StringUtils {

    public static boolean isEmpty(String str) {
        return str == null || str.isEmpty();
    }

    public static boolean isBlank(String str) {
        return str == null || str.trim().isEmpty();
    }

    public static String trim(String str) {
        return str == null ? null : str.trim();
    }

    public static String strip(String str) {
        return str == null ? null : str.replaceAll("^\\s+|\\s+$", "");
    }

    public static int compare(String str1, String str2) {
        return str1 == null ? (str2 == null ? 0 : -1) : (str2 == null ? 1 : str1.compareTo(str2));
    }

    public static boolean contains(String str, String searchStr) {
        return str != null && searchStr != null && str.contains(searchStr);
    }

    public static String padStart(String str, int length, char padChar) {
        if (str == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder(length);
        for (int i = str.length(); i < length; i++) {
            sb.append(padChar);
        }
        sb.append(str);
        return sb.toString();
    }

    public static String padEnd(String str, int length, char padChar) {
        if (str == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder(str);
        while (sb.length() < length) {
            sb.append(padChar);
        }
        return sb.toString();
    }

    public static String join(String delimiter, String... elements) {
        if (elements == null || elements.length == 0) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (String element : elements) {
            if (sb.length() > 0) {
                sb.append(delimiter);
            }
            sb.append(element);
        }
        return sb.toString();
    }

    public static String replace(String str, String target, String replacement) {
        if (str == null || target == null || replacement == null) {
            return str;
        }
        return str.replace(target, replacement);
    }

    public static String format(String format, Object... args) {
        return String.format(format, args);
    }

    public static String toUpperCase(String str) {
        return str == null ? null : str.toUpperCase();
    }

    public static String toLowerCase(String str) {
        return str == null ? null : str.toLowerCase();
    }

    public static int levenshteinDistance(String s1, String s2) {
        if (s1 == null || s2 == null) {
            return -1;
        }
        int lenS1 = s1.length();
        int lenS2 = s2.length();
        int[][] dp = new int[lenS1 + 1][lenS2 + 1];

        for (int i = 0; i <= lenS1; i++) {
            for (int j = 0; j <= lenS2; j++) {
                if (i == 0) {
                    dp[i][j] = j;
                } else if (j == 0) {
                    dp[i][j] = i;
                } else {
                    dp[i][j] = Math.min(Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1),
                            dp[i - 1][j - 1] + (s1.charAt(i - 1) == s2.charAt(j - 1) ? 0 : 1));
                }
            }
        }
        return dp[lenS1][lenS2];
    }

    public static boolean isAlphanumeric(String str) {
        return str != null && str.matches("[a-zA-Z0-9]+");
    }

    public static boolean isNumeric(String str) {
        return str != null && str.matches("[0-9]+");
    }

    public static String substring(String str, int start, int end) {
        if (str == null) {
            return null;
        }
        return str.substring(Math.max(0, start), Math.min(end, str.length()));
    }
}

public class NumberHelper {

    public static <T extends Number> T add(T a, T b) {
        return operate(a, b, (x, y) -> x.doubleValue() + y.doubleValue());
    }

    public static <T extends Number> T subtract(T a, T b) {
        return operate(a, b, (x, y) -> x.doubleValue() - y.doubleValue());
    }

    public static <T extends Number> T multiply(T a, T b) {
        return operate(a, b, (x, y) -> x.doubleValue() * y.doubleValue());
    }

    public static <T extends Number> T divide(T a, T b) {
        return operate(a, b, (x, y) -> x.doubleValue() / y.doubleValue());
    }

    public static <T extends Number> T min(T a, T b) {
        return operate(a, b, Math::min);
    }

    public static <T extends Number> T max(T a, T b) {
        return operate(a, b, Math::max);
    }

    public static <T extends Number> int compare(T a, T b) {
        return Double.compare(a.doubleValue(), b.doubleValue());
    }

    private static <T extends Number> T operate(T a, T b, BiFunction<Number, Number, Double> operation) {
        return (T) Double.valueOf(operation.apply(a, b));
    }

    public static boolean isValidNumber(String value) {
        try {
            Double.parseDouble(value);
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    public static Byte toByte(Number number) {
        return number.byteValue();
    }

    public static Short toShort(Number number) {
        return number.shortValue();
    }

    public static Integer toInteger(Number number) {
        return number.intValue();
    }

    public static Long toLong(Number number) {
        return number.longValue();
    }

    public static BigInteger toBigInteger(Number number) {
        return BigInteger.valueOf(number.longValue());
    }

    public static Float toFloat(Number number) {
        return number.floatValue();
    }

    public static Double toDouble(Number number) {
        return number.doubleValue();
    }

    public static BigDecimal toBigDecimal(Number number) {
        return BigDecimal.valueOf(number.doubleValue());
    }
}

