public final class ProjectedTraverser<S, E> implements Traverser.Admin<S, E> {
    private final Traverser.Admin<S, E> baseTraverser;
    private final List<Projection<E>> projections;

    public ProjectedTraverser(Traverser.Admin<S, E> baseTraverser, List<Projection<E>> projections) {
        this.baseTraverser = baseTraverser;
        this.projections = projections;
    }

    @Override
    public Traverser.Admin<S, E> split() {
        return new ProjectedTraverser<>(baseTraverser.split(), projections);
    }

    @Override
    public void merge(Traverser.Admin<S, E> other) {
        baseTraverser.merge(other);
    }

    @Override
    public S get() {
        return baseTraverser.get();
    }

    @Override
    public E getSideEffect() {
        return baseTraverser.getSideEffect();
    }

    @Override
    public void set(S value) {
        baseTraverser.set(value);
    }

    @Override
    public void setSideEffect(E sideEffect) {
        baseTraverser.setSideEffect(sideEffect);
    }

    @Override
    public Traverser.Admin<S, E> clone() {
        return new ProjectedTraverser<>(baseTraverser.clone(), projections);
    }

    public List<Projection<E>> getProjections() {
        return projections;
    }

    public Traverser.Admin<S, E> unwrap() {
        return baseTraverser;
    }
}

