public class FunctionUtils {

    // Function Composition
    public static <T, R> Function<T, R> compose(Function<T, R>... functions) {
        return x -> {
            Object result = x;
            for (Function<T, R> function : functions) {
                result = function.apply((T) result);
            }
            return (R) result;
        };
    }

    // Function Addition
    public static Function<Double, Double> add(Function<Double, Double>... functions) {
        return x -> {
            double sum = 0;
            for (Function<Double, Double> function : functions) {
                sum += function.apply(x);
            }
            return sum;
        };
    }

    // Function Multiplication
    public static Function<Double, Double> multiply(Function<Double, Double>... functions) {
        return x -> {
            double product = 1;
            for (Function<Double, Double> function : functions) {
                product *= function.apply(x);
            }
            return product;
        };
    }

    // Combining Functions
    public static Function<Double, Double> combine(Function<Double, Double> f1, Function<Double, Double> f2, BiFunction<Double, Double, Double> operation) {
        return x -> operation.apply(f1.apply(x), f2.apply(x));
    }

    // Sampling Functions
    public static double[] sample(Function<Double, Double> function, double start, double end, int numSamples) {
        return DoubleStream.rangeClosed(0, numSamples - 1)
                .mapToDouble(i -> function.apply(start + (end - start) * i / (numSamples - 1)))
                .toArray();
    }

    // Fixing Function Arguments
    public static Function<Double, Double> fixArgument(BiFunction<Double, Double, Double> biFunction, double fixedArg) {
        return x -> biFunction.apply(x, fixedArg);
    }

    // Gradient Calculation (for univariate functions)
    public static Function<Double, Double> derivative(Function<Double, Double> function, double delta) {
        return x -> (function.apply(x + delta) - function.apply(x - delta)) / (2 * delta);
    }

    // Gradient Calculation (for multivariate functions)
    public static Function<double[], Double> gradient(BiFunction<Double, Double, Double> function, double delta) {
        return point -> {
            double[] grad = new double[point.length];
            for (int i = 0; i < point.length; i++) {
                double[] pointPlusDelta = point.clone();
                double[] pointMinusDelta = point.clone();
                pointPlusDelta[i] += delta;
                pointMinusDelta[i] -= delta;
                grad[i] = (function.apply(pointPlusDelta[0], pointPlusDelta[1]) - function.apply(pointMinusDelta[0], pointMinusDelta[1])) / (2 * delta);
            }
            return grad[0]; // Return the first gradient for simplicity
        };
    }

    // Deprecated methods (for older function types)
    @Deprecated
    public static Function<Double, Double> oldAdd(Function<Double, Double> f1, Function<Double, Double> f2) {
        return add(f1, f2);
    }

    @Deprecated
    public static Function<Double, Double> oldMultiply(Function<Double, Double> f1, Function<Double, Double> f2) {
        return multiply(f1, f2);
    }
}

public class IsisTransactionManager {
    private static final Logger logger = LoggerFactory.getLogger(IsisTransactionManager.class);

    private boolean transactionActive;
    private int transactionLevel;

    public IsisTransactionManager() {
        this.transactionActive = false;
        this.transactionLevel = 0;
    }

    public void open() {
        logger.debug("Opening transaction manager.");
        // Logic to open a session
    }

    public void close() {
        logger.debug("Closing transaction manager.");
        // Logic to close a session
    }

    public void startTransaction() {
        if (transactionActive) {
            logger.warn("Transaction already active. Level: {}", transactionLevel);
            return;
        }
        transactionActive = true;
        transactionLevel++;
        logger.debug("Transaction started. Level: {}", transactionLevel);
    }

    public void endTransaction() {
        if (!transactionActive) {
            logger.warn("No active transaction to end.");
            return;
        }
        transactionLevel--;
        if (transactionLevel == 0) {
            commitTransaction();
        }
        logger.debug("Transaction ended. Level: {}", transactionLevel);
    }

    public void abortTransaction() {
        if (!transactionActive) {
            logger.warn("No active transaction to abort.");
            return;
        }
        transactionActive = false;
        transactionLevel = 0;
        logger.debug("Transaction aborted.");
        // Logic to abort the transaction
    }

    public void executeInTransaction(Runnable operation) {
        try {
            startTransaction();
            operation.run();
            endTransaction();
        } catch (Exception e) {
            logger.error("Exception during transaction execution: {}", e.getMessage());
            abortTransaction();
        }
    }

    private void commitTransaction() {
        logger.debug("Committing transaction.");
        // Logic to commit the transaction
        transactionActive = false;
    }
}

