public class FastMathTest {

    private static final double TOLERANCE = 1e-10;

    @Test
    public void testMinDouble() {
        assertEquals(Math.min(1.0, 2.0), FastMath.min(1.0, 2.0), TOLERANCE);
        assertEquals(Math.min(-1.0, -2.0), FastMath.min(-1.0, -2.0), TOLERANCE);
    }

    @Test
    public void testMaxDouble() {
        assertEquals(Math.max(1.0, 2.0), FastMath.max(1.0, 2.0), TOLERANCE);
        assertEquals(Math.max(-1.0, -2.0), FastMath.max(-1.0, -2.0), TOLERANCE);
    }

    @Test
    public void testSin() {
        for (double angle = -Math.PI; angle <= Math.PI; angle += 0.1) {
            assertEquals(Math.sin(angle), FastMath.sin(angle), TOLERANCE);
        }
    }

    @Test
    public void testCos() {
        for (double angle = -Math.PI; angle <= Math.PI; angle += 0.1) {
            assertEquals(Math.cos(angle), FastMath.cos(angle), TOLERANCE);
        }
    }

    @Test
    public void testLog() {
        assertEquals(Math.log(1.0), FastMath.log(1.0), TOLERANCE);
        assertEquals(Math.log(Math.E), FastMath.log(Math.E), TOLERANCE);
    }

    @Test
    public void testExp() {
        assertEquals(Math.exp(0.0), FastMath.exp(0.0), TOLERANCE);
        assertEquals(Math.exp(1.0), FastMath.exp(1.0), TOLERANCE);
    }

    @Test
    public void testPow() {
        assertEquals(Math.pow(2.0, 3.0), FastMath.pow(2.0, 3.0), TOLERANCE);
        assertEquals(Math.pow(5.0, 0.0), FastMath.pow(5.0, 0.0), TOLERANCE);
    }

    @Test
    public void testSinh() {
        assertEquals(Math.sinh(0.0), FastMath.sinh(0.0), TOLERANCE);
        assertEquals(Math.sinh(1.0), FastMath.sinh(1.0), TOLERANCE);
    }

    @Test
    public void testCosh() {
        assertEquals(Math.cosh(0.0), FastMath.cosh(0.0), TOLERANCE);
        assertEquals(Math.cosh(1.0), FastMath.cosh(1.0), TOLERANCE);
    }

    @Test
    public void testSpecialCases() {
        assertEquals(Math.sqrt(4.0), FastMath.sqrt(4.0), TOLERANCE);
        assertEquals(Math.sqrt(0.0), FastMath.sqrt(0.0), TOLERANCE);
        assertTrue(Double.isNaN(FastMath.sqrt(-1.0)));
    }
}

