public class ExclusiveConsumerTest {
    private Connection connection;
    private Session session;
    private MessageProducer producer;
    private static final String QUEUE_NAME = "testQueue";

    @Before
    public void setUp() throws JMSException {
        ActiveMQConnectionFactory factory = new ActiveMQConnectionFactory("tcp://localhost:61616");
        connection = factory.createConnection();
        connection.start();
        session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        Queue queue = session.createQueue(QUEUE_NAME);
        producer = session.createProducer(queue);
    }

    @After
    public void tearDown() throws JMSException {
        if (producer != null) {
            producer.close();
        }
        if (session != null) {
            session.close();
        }
        if (connection != null) {
            connection.close();
        }
    }

    @Test
    public void testExclusiveConsumerReceivesMessagesFirst() throws JMSException {
        Queue queue = session.createQueue(QUEUE_NAME);
        MessageConsumer exclusiveConsumer = session.createConsumer(queue, "JMSPriority = 9");
        MessageConsumer fallbackConsumer = session.createConsumer(queue);

        producer.send(session.createTextMessage("Message 1"));

        TextMessage receivedMessage = (TextMessage) exclusiveConsumer.receive(1000);
        assertEquals("Message 1", receivedMessage.getText());

        receivedMessage = (TextMessage) fallbackConsumer.receive(1000);
        assertEquals(null, receivedMessage);

        exclusiveConsumer.close();
        fallbackConsumer.close();
    }

    @Test
    public void testExclusiveConsumerReceivesMessagesAfterFallback() throws JMSException {
        Queue queue = session.createQueue(QUEUE_NAME);
        MessageConsumer fallbackConsumer = session.createConsumer(queue);
        MessageConsumer exclusiveConsumer = session.createConsumer(queue, "JMSPriority = 9");

        producer.send(session.createTextMessage("Message 2"));

        TextMessage receivedMessage = (TextMessage) fallbackConsumer.receive(1000);
        assertEquals(null, receivedMessage);

        receivedMessage = (TextMessage) exclusiveConsumer.receive(1000);
        assertEquals("Message 2", receivedMessage.getText());

        exclusiveConsumer.close();
        fallbackConsumer.close();
    }

    @Test
    public void testFailoverBehavior() throws JMSException {
        Queue queue = session.createQueue(QUEUE_NAME);
        MessageConsumer exclusiveConsumer1 = session.createConsumer(queue, "JMSPriority = 9");
        producer.send(session.createTextMessage("Message 3"));

        exclusiveConsumer1.close();

        MessageConsumer exclusiveConsumer2 = session.createConsumer(queue, "JMSPriority = 9");
        TextMessage receivedMessage = (TextMessage) exclusiveConsumer2.receive(1000);
        assertEquals("Message 3", receivedMessage.getText());

        exclusiveConsumer2.close();
    }

    @Test
    public void testExclusiveVsNonExclusiveConsumers() throws JMSException {
        Queue queue = session.createQueue(QUEUE_NAME);
        MessageConsumer exclusiveConsumer = session.createConsumer(queue, "JMSPriority = 9");
        MessageConsumer nonExclusiveConsumer = session.createConsumer(queue);

        producer.send(session.createTextMessage("Message 4"));

        TextMessage receivedMessage = (TextMessage) exclusiveConsumer.receive(1000);
        assertEquals("Message 4", receivedMessage.getText());

        receivedMessage = (TextMessage) nonExclusiveConsumer.receive(1000);
        assertEquals(null, receivedMessage);

        exclusiveConsumer.close();
        nonExclusiveConsumer.close();
    }

    @Test
    public void testFallbackToExclusiveConsumer() throws JMSException {
        Queue queue = session.createQueue(QUEUE_NAME);
        MessageConsumer exclusiveConsumer = session.createConsumer(queue, "JMSPriority = 9");
        MessageConsumer fallbackConsumer = session.createConsumer(queue);

        producer.send(session.createTextMessage("Message 5"));
        exclusiveConsumer.close();

        TextMessage receivedMessage = (TextMessage) fallbackConsumer.receive(1000);
        assertEquals("Message 5", receivedMessage.getText());

        fallbackConsumer.close();
    }
}

