public class FieldVector3DTest {

    @Test
    public void testConstructor() {
        FieldVector3D vector = new FieldVector3D(1.0, 2.0, 3.0);
        assertNotNull(vector);
        assertEquals(1.0, vector.getX());
        assertEquals(2.0, vector.getY());
        assertEquals(3.0, vector.getZ());
    }

    @Test
    public void testEqualityAndHashCode() {
        FieldVector3D vector1 = new FieldVector3D(1.0, 2.0, 3.0);
        FieldVector3D vector2 = new FieldVector3D(1.0, 2.0, 3.0);
        assertEquals(vector1, vector2);
        assertEquals(vector1.hashCode(), vector2.hashCode());
    }

    @Test
    public void testSpecialValues() {
        FieldVector3D vectorNaN = new FieldVector3D(Double.NaN, 1.0, 1.0);
        FieldVector3D vectorInf = new FieldVector3D(Double.POSITIVE_INFINITY, 1.0, 1.0);
        assertTrue(vectorNaN.isNaN());
        assertTrue(vectorInf.isInfinite());
    }

    @Test
    public void testStringRepresentation() {
        FieldVector3D vector = new FieldVector3D(1.0, 2.0, 3.0);
        assertEquals("FieldVector3D{x=1.0, y=2.0, z=3.0}", vector.toString());
    }

    @Test
    public void testDimensionMismatch() {
        FieldVector3D vector1 = new FieldVector3D(1.0, 2.0, 3.0);
        FieldVector3D vector2 = new FieldVector3D(1.0, 2.0);
        assertThrows(IllegalArgumentException.class, () -> vector1.add(vector2));
    }

    @Test
    public void testGetCoordinates() {
        FieldVector3D vector = new FieldVector3D(1.0, 2.0, 3.0);
        double[] coords = vector.getCoordinates();
        assertArrayEquals(new double[]{1.0, 2.0, 3.0}, coords);
    }

    @Test
    public void testNorms() {
        FieldVector3D vector = new FieldVector3D(1.0, 2.0, 2.0);
        assertEquals(5.0, vector.normL1());
        assertEquals(3.0, vector.normL2());
        assertEquals(2.0, vector.normInfinity());
    }

    @Test
    public void testDistanceCalculations() {
        FieldVector3D vector1 = new FieldVector3D(1.0, 2.0, 3.0);
        FieldVector3D vector2 = new FieldVector3D(4.0, 5.0, 6.0);
        assertEquals(9.0, vector1.distanceL1(vector2));
        assertEquals(Math.sqrt(27), vector1.distanceL2(vector2));
        assertEquals(3.0, vector1.distanceInfinity(vector2));
    }

    @Test
    public void testVectorAddition() {
        FieldVector3D vector1 = new FieldVector3D(1.0, 2.0, 3.0);
        FieldVector3D vector2 = new FieldVector3D(4.0, 5.0, 6.0);
        FieldVector3D result = vector1.add(vector2);
        assertEquals(new FieldVector3D(5.0, 7.0, 9.0), result);
    }

    @Test
    public void testVectorSubtraction() {
        FieldVector3D vector1 = new FieldVector3D(4.0, 5.0, 6.0);
        FieldVector3D vector2 = new FieldVector3D(1.0, 2.0, 3.0);
        FieldVector3D result = vector1.subtract(vector2);
        assertEquals(new FieldVector3D(3.0, 3.0, 3.0), result);
    }

    @Test
    public void testScalarMultiplication() {
        FieldVector3D vector = new FieldVector3D(1.0, 2.0, 3.0);
        FieldVector3D result = vector.scalarMultiply(2.0);
        assertEquals(new FieldVector3D(2.0, 4.0, 6.0), result);
    }

    @Test
    public void testDotProduct() {
        FieldVector3D vector1 = new FieldVector3D(1.0, 2.0, 3.0);
        FieldVector3D vector2 = new FieldVector3D(4.0, 5.0, 6.0);
        assertEquals(32.0, vector1.dotProduct(vector2));
    }

    @Test
    public void testCrossProduct() {
        FieldVector3D vector1 = new FieldVector3D(1.0, 2.0, 3.0);
        FieldVector3D vector2 = new FieldVector3D(4.0, 5.0, 6.0);
        FieldVector3D result = vector1.crossProduct(vector2);
        assertEquals(new FieldVector3D(-3.0, 6.0, -3.0), result);
    }

    @Test
    public void testNormalization() {
        FieldVector3D vector = new FieldVector3D(1.0, 2.0, 2.0);
        FieldVector3D normalized = vector.normalize();
        assertEquals(1.0, normalized.normL2(), 1e-10);
    }

    @Test
    public void testOrthogonalVectorGeneration() {
        FieldVector3D vector = new FieldVector3D(1.0, 0.0, 0.0);
        FieldVector3D orthogonal = vector.getOrthogonal();
        assertEquals(new FieldVector3D(0.0, 1.0, 0.0), orthogonal);
    }

    @Test
    public void testAngularCalculations() {
        FieldVector3D vector1 = new FieldVector3D(1.0, 0.0, 0.0);
        FieldVector3D vector2 = new FieldVector3D(0.0, 1.0, 0.0);
        double angle = vector1.angleWith(vector2);
        assertEquals(Math.PI / 2, angle, 1e-10);
    }

    @Test
    public void testHighPrecisionDotProduct() {
        FieldVector3D vector1 = new FieldVector3D(1.0000000001, 2.0000000001, 3.0000000001);
        FieldVector3D vector2 = new FieldVector3D(4.0000000001, 5.0000000001, 6.0000000001);
        assertEquals(32.0000000003, vector1.dotProduct(vector2), 1e-10);
    }
}

