public class RegexTest {

    @Rule
    public final TestPipeline pipeline = TestPipeline.create();

    @Test
    public void testFindMatches() {
        List<String> input = Arrays.asList("abc", "def", "abc123", "123abc");
        List<String> expected = Arrays.asList("abc", "abc123", "123abc");

        PAssert.that(pipeline.apply("CreateInput", Create.of(input))
                .apply(ParDo.of(new SimpleFunction<String, String>() {
                    @Override
                    public String apply(String input) {
                        return Regex.find(input, "abc");
                    }
                })))
                .containsInAnyOrder(expected);

        pipeline.run().waitUntilFinish();
    }

    @Test
    public void testGroupMatches() {
        List<String> input = Arrays.asList("key1=value1", "key2=value2");
        List<String> expected = Arrays.asList("value1", "value2");

        PAssert.that(pipeline.apply("CreateInput", Create.of(input))
                .apply(ParDo.of(new SimpleFunction<String, String>() {
                    @Override
                    public String apply(String input) {
                        return Regex.group(input, "(?<key>\\w+)=(?<value>\\w+)", "value");
                    }
                })))
                .containsInAnyOrder(expected);

        pipeline.run().waitUntilFinish();
    }

    @Test
    public void testReplaceMatches() {
        List<String> input = Arrays.asList("abc123", "def456");
        List<String> expected = Arrays.asList("abcXYZ", "defXYZ");

        PAssert.that(pipeline.apply("CreateInput", Create.of(input))
                .apply(ParDo.of(new SimpleFunction<String, String>() {
                    @Override
                    public String apply(String input) {
                        return Regex.replace(input, "\\d+", "XYZ");
                    }
                })))
                .containsInAnyOrder(expected);

        pipeline.run().waitUntilFinish();
    }

    @Test
    public void testSplitString() {
        List<String> input = Arrays.asList("one,two,three", "four,five");
        List<List<String>> expected = Arrays.asList(Arrays.asList("one", "two", "three"), Arrays.asList("four", "five"));

        PAssert.that(pipeline.apply("CreateInput", Create.of(input))
                .apply(ParDo.of(new SimpleFunction<String, List<String>>() {
                    @Override
                    public List<String> apply(String input) {
                        return Arrays.asList(Regex.split(input, ","));
                    }
                })))
                .containsInAnyOrder(expected);

        pipeline.run().waitUntilFinish();
    }
}

public class ShellGraph {
    private Model graph;
    private String graphName;
    private Dataset datasetGraph;

    public ShellGraph(Model graph, String graphName, Dataset datasetGraph) {
        this.graph = graph;
        this.graphName = graphName;
        this.datasetGraph = datasetGraph;
    }

    public List<Resource> findLists() {
        List<Resource> lists = new ArrayList<>();
        StmtIterator iter = graph.listStatements();
        while (iter.hasNext()) {
            Statement stmt = iter.nextStatement();
            if (stmt.getObject().isResource()) {
                Resource resource = stmt.getResource();
                if (resource.isAnon()) {
                    lists.add(resource);
                }
            }
        }
        return lists;
    }

    public List<Resource> findBlankNodes() {
        List<Resource> blankNodes = new ArrayList<>();
        StmtIterator iter = graph.listStatements();
        while (iter.hasNext()) {
            Statement stmt = iter.nextStatement();
            if (stmt.getObject().isAnon()) {
                blankNodes.add(stmt.getObject().asResource());
            }
        }
        return blankNodes;
    }

    public int countTriples() {
        return graph.size();
    }

    public void traverseGraph() {
        StmtIterator iter = graph.listStatements();
        while (iter.hasNext()) {
            Statement stmt = iter.nextStatement();
            System.out.println(stmt);
        }
    }

    public void writeGraphData() {
        graph.write(System.out, "TURTLE");
    }

    public void prettyPrintNode(Resource resource) {
        System.out.println("Node: " + resource.getURI());
        StmtIterator iter = graph.listStatements(resource, null, (RDFNode) null);
        while (iter.hasNext()) {
            Statement stmt = iter.nextStatement();
            System.out.println(" - " + stmt.getPredicate() + " " + stmt.getObject());
        }
    }

    public void prettyPrintList(List<Resource> resources) {
        for (Resource resource : resources) {
            prettyPrintNode(resource);
        }
    }

    public void debugPrint() {
        System.out.println("Graph Name: " + graphName);
        System.out.println("Total Triples: " + countTriples());
        System.out.println("Blank Nodes: " + findBlankNodes());
        System.out.println("Lists: " + findLists());
        traverseGraph();
    }
}

