public class LDAPQuery {
    private String serverUrl;
    private int port;
    private String username;
    private String password;
    private String baseDN;
    private String searchScope;
    private DirContext context;

    public LDAPQuery(String serverUrl, int port, String username, String password, String baseDN, String searchScope) {
        this.serverUrl = serverUrl;
        this.port = port;
        this.username = username;
        this.password = password;
        this.baseDN = baseDN;
        this.searchScope = searchScope;
    }

    public void connect() throws NamingException {
        Hashtable<String, String> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.ldap.LdapCtxFactory");
        env.put(Context.PROVIDER_URL, "ldap://" + serverUrl + ":" + port);
        env.put(Context.SECURITY_AUTHENTICATION, "simple");
        env.put(Context.SECURITY_PRINCIPAL, username);
        env.put(Context.SECURITY_CREDENTIALS, password);
        context = new InitialDirContext(env);
    }

    public void disconnect() throws NamingException {
        if (context != null) {
            context.close();
        }
    }

    public List<String> search(String filter) throws NamingException {
        List<String> results = new ArrayList<>();
        String searchFilter = "(&" + filter + ")";
        SearchControls searchControls = new SearchControls();
        searchControls.setSearchScope(getSearchScope());
        NamingEnumeration<SearchResult> searchResults = context.search(baseDN, searchFilter, searchControls);

        while (searchResults.hasMore()) {
            SearchResult result = searchResults.next();
            results.add(result.getNameInNamespace());
        }
        return results;
    }

    public void add(String dn, Attributes attributes) throws NamingException {
        context.createSubcontext(dn, attributes);
    }

    public void replace(String dn, Attributes attributes) throws NamingException {
        context.modifyAttributes(dn, DirContext.REPLACE_ATTRIBUTE, attributes);
    }

    public void increment(String dn, String attributeName, int incrementValue) throws NamingException {
        ModificationItem[] mods = new ModificationItem[1];
        mods[0] = new ModificationItem(DirContext.REPLACE_ATTRIBUTE, new BasicAttribute(attributeName, incrementValue));
        context.modifyAttributes(dn, mods);
    }

    private int getSearchScope() {
        switch (searchScope.toLowerCase()) {
            case "subtree":
                return SearchControls.SUBTREE_SCOPE;
            case "onelevel":
                return SearchControls.ONELEVEL_SCOPE;
            case "object":
                return SearchControls.OBJECT_SCOPE;
            default:
                throw new IllegalArgumentException("Invalid search scope: " + searchScope);
        }
    }

    public void setBaseDN(String baseDN) {
        this.baseDN = baseDN;
    }

    public void setSearchScope(String searchScope) {
        this.searchScope = searchScope;
    }

    public void setUsername(String username) {
        this.username = username;
    }

    public void setPassword(String password) {
        this.password = password;
    }

    public void setServerUrl(String serverUrl) {
        this.serverUrl = serverUrl;
    }

    public void setPort(int port) {
        this.port = port;
    }
}

