        return name;
    }

    public Pipeline getPipeline() {
        return pipeline;
    }

    public void addDependency(PCollection<S> dependency) {
        dependencies.add(dependency);
        depth = Math.max(depth, dependency.getDepth() + 1);
    }

    public int getDepth() {
        return depth;
    }

    public void materialize() {
        if (!isMaterialized) {
            // Logic to materialize the collection
            isMaterialized = true;
        }
    }

    public void cache() {
        // Logic to cache the collection
    }

    public <T> PCollection<T> parallelDo(DoFn<S, T> fn) {
        // Logic for parallel processing
        return new PCollectionImpl<T>(name + "_parallelDo", pipeline) {};
    }

    public PCollection<S> filter(FilterFn<S> fn) {
        // Logic for filtering
        return new PCollectionImpl<S>(name + "_filtered", pipeline) {};
    }

