public class WeblogPageRequest extends WeblogRequest {
    private static final Logger logger = Logger.getLogger(WeblogPageRequest.class.getName());

    private String context;
    private String weblogAnchor;
    private String pageName;
    private String categoryName;
    private String date;
    private String tags;
    private int currentPageNumber;
    private Map<String, String> customParameters;
    private boolean isWebsitePage;

    public WeblogPageRequest() {
        this.customParameters = new HashMap<>();
        this.currentPageNumber = 1; // Default page number
    }

    public void parseRequest(HttpRequest request) {
        this.context = request.getParameter("context");
        this.weblogAnchor = request.getParameter("weblogAnchor");
        this.pageName = request.getParameter("pageName");
        this.categoryName = request.getParameter("categoryName");
        this.date = request.getParameter("date");
        this.tags = request.getParameter("tags");
        this.currentPageNumber = Integer.parseInt(request.getParameter("pageNumber", "1"));
        this.isWebsitePage = request.getParameter("isWebsitePage", "false").equals("true");

        validateRequest();
        logRequestDetails();
    }

    private void validateRequest() {
        if (weblogAnchor == null || weblogAnchor.isEmpty()) {
            logger.warning("Invalid weblog anchor.");
        }
        if (!isValidDate(date)) {
            logger.warning("Invalid date format.");
        }
    }

    private boolean isValidDate(String date) {
        // Simple date validation logic (could be improved)
        return date != null && date.matches("\\d{4}-\\d{2}-\\d{2}");
    }

    private void logRequestDetails() {
        logger.info("Request parsed: " + this.toString());
    }

    public String getContext() {
        return context;
    }

    public void setContext(String context) {
        this.context = context;
    }

    public String getWeblogAnchor() {
        return weblogAnchor;
    }

    public void setWeblogAnchor(String weblogAnchor) {
        this.weblogAnchor = weblogAnchor;
    }

    public String getPageName() {
        return pageName;
    }

    public void setPageName(String pageName) {
        this.pageName = pageName;
    }

    public String getCategoryName() {
        return categoryName;
    }

    public void setCategoryName(String categoryName) {
        this.categoryName = categoryName;
    }

    public String getDate() {
        return date;
    }

    public void setDate(String date) {
        this.date = date;
    }

    public String getTags() {
        return tags;
    }

    public void setTags(String tags) {
        this.tags = tags;
    }

    public int getCurrentPageNumber() {
        return currentPageNumber;
    }

    public void setCurrentPageNumber(int currentPageNumber) {
        this.currentPageNumber = currentPageNumber;
    }

    public Map<String, String> getCustomParameters() {
        return customParameters;
    }

    public void setCustomParameter(String key, String value) {
        this.customParameters.put(key, value);
    }

    public boolean isWebsitePage() {
        return isWebsitePage;
    }

    public void setWebsitePage(boolean websitePage) {
