public class JsonSchemaValidatorTest {
    private JsonSchemaValidator validator;

    @Before
    public void setUp() {
        validator = new JsonSchemaValidator();
    }

    @After
    public void tearDown() {
        validator.close();
    }

    @Test
    public void testRequiredFields() {
        String schema = "{ \"type\": \"object\", \"required\": [\"name\"] }";
        String json = "{ \"name\": \"John\" }";
        assertTrue(validator.validate(schema, json).isValid());

        json = "{}";
        assertFalse(validator.validate(schema, json).isValid());
    }

    @Test
    public void testDataTypes() {
        String schema = "{ \"type\": \"object\", \"properties\": { \"age\": { \"type\": \"integer\" } } }";
        String json = "{ \"age\": 30 }";
        assertTrue(validator.validate(schema, json).isValid());

        json = "{ \"age\": \"thirty\" }";
        assertFalse(validator.validate(schema, json).isValid());
    }

    @Test
    public void testNestedObjects() {
        String schema = "{ \"type\": \"object\", \"properties\": { \"address\": { \"type\": \"object\", \"properties\": { \"city\": { \"type\": \"string\" } } } } }";
        String json = "{ \"address\": { \"city\": \"New York\" } }";
        assertTrue(validator.validate(schema, json).isValid());

        json = "{ \"address\": {} }";
        assertFalse(validator.validate(schema, json).isValid());
    }

    @Test
    public void testEnumerations() {
        String schema = "{ \"type\": \"object\", \"properties\": { \"color\": { \"type\": \"string\", \"enum\": [\"red\", \"green\", \"blue\"] } } }";
        String json = "{ \"color\": \"red\" }";
        assertTrue(validator.validate(schema, json).isValid());

        json = "{ \"color\": \"yellow\" }";
        assertFalse(validator.validate(schema, json).isValid());
    }

    @Test
    public void testNumericalConstraints() {
        String schema = "{ \"type\": \"object\", \"properties\": { \"age\": { \"type\": \"integer\", \"minimum\": 18, \"maximum\": 65 } } }";
        String json = "{ \"age\": 30 }";
        assertTrue(validator.validate(schema, json).isValid());

        json = "{ \"age\": 17 }";
        assertFalse(validator.validate(schema, json).isValid());
    }

    @Test
    public void testStringConstraints() {
        String schema = "{ \"type\": \"object\", \"properties\": { \"username\": { \"type\": \"string\", \"minLength\": 3, \"maxLength\": 15 } } }";
        String json = "{ \"username\": \"user123\" }";
        assertTrue(validator.validate(schema, json).isValid());

        json = "{ \"username\": \"us\" }";
        assertFalse(validator.validate(schema, json).isValid());
    }

    @Test
    public void testArrayConstraints() {
        String schema = "{ \"type\": \"object\", \"properties\": { \"tags\": { \"type\": \"array\", \"minItems\": 1, \"uniqueItems\": true } } }";
        String json = "{ \"tags\": [\"tag1\", \"tag2\"] }";
        assertTrue(validator.validate(schema, json).isValid());

        json = "{ \"tags\": [] }";
        assertFalse(validator.validate(schema, json).isValid());
    }

    @Test
    public void testPropertiesConstraints() {
        String schema = "{ \"type\": \"object\", \"minProperties\": 2, \"maxProperties\": 5 }";
        String json = "{ \"name\": \"John\", \"age\": 30 }";
        assertTrue(validator.validate(schema, json).isValid());

        json = "{ \"name\": \"John\" }";
        assertFalse(validator.validate(schema, json).isValid());
    }
}

