class AvlTreeMapTest {
    private AvlTreeMapImpl<Integer, String> avlTreeMap;

    @Before
    public void setUp() {
        avlTreeMap = new AvlTreeMapImpl<>(Comparator.naturalOrder());
    }

    @Test
    public void testInsertAndRetrieve() {
        avlTreeMap.put(1, "One");
        assertEquals("One", avlTreeMap.get(1));
        avlTreeMap.put(2, "Two");
        assertEquals("Two", avlTreeMap.get(2));
    }

    @Test
    public void testRemove() {
        avlTreeMap.put(1, "One");
        avlTreeMap.remove(1);
        assertNull(avlTreeMap.get(1));
    }

    @Test
    public void testDuplicateInsert() {
        avlTreeMap.put(1, "One");
        avlTreeMap.put(1, "Uno");
        assertEquals("Uno", avlTreeMap.get(1));
    }

    @Test
    public void testIsEmpty() {
        assertTrue(avlTreeMap.isEmpty());
        avlTreeMap.put(1, "One");
        assertFalse(avlTreeMap.isEmpty());
    }

    @Test
    public void testSize() {
        assertEquals(0, avlTreeMap.size());
        avlTreeMap.put(1, "One");
        avlTreeMap.put(2, "Two");
        assertEquals(2, avlTreeMap.size());
        avlTreeMap.remove(1);
        assertEquals(1, avlTreeMap.size());
    }

    @Test
    public void testGetFirst() {
        avlTreeMap.put(2, "Two");
        avlTreeMap.put(1, "One");
        assertEquals("One", avlTreeMap.getFirst());
    }

    @Test
    public void testGetLast() {
        avlTreeMap.put(1, "One");
        avlTreeMap.put(2, "Two");
        assertEquals("Two", avlTreeMap.getLast());
    }

    @Test
    public void testRemoveAll() {
        avlTreeMap.put(1, "One");
        avlTreeMap.put(2, "Two");
        avlTreeMap.removeAll();
        assertTrue(avlTreeMap.isEmpty());
    }

    @Test
    public void testBalanceAfterInsertions() {
        avlTreeMap.put(3, "Three");
        avlTreeMap.put(2, "Two");
        avlTreeMap.put(1, "One");
        assertEquals(2, avlTreeMap.size());
        assertEquals("Two", avlTreeMap.get(2));
    }
}

