public class DataManagerImpl implements DataManager {
    private final Map<String, File> dataFiles = new HashMap<>();
    private File currentWriteFile;
    private long currentFileSize = 0;
    private final long maxFileSize;
    private final ReentrantLock lock = new ReentrantLock();
    private Marshaller marshaller;

    public DataManagerImpl(long maxFileSize, Marshaller marshaller) {
        this.maxFileSize = maxFileSize;
        this.marshaller = marshaller;
        createNewFile();
    }

    private void createNewFile() {
        try {
            currentWriteFile = new File("data_" + System.currentTimeMillis() + ".dat");
            currentWriteFile.createNewFile();
            dataFiles.put(currentWriteFile.getName(), currentWriteFile);
            currentFileSize = 0;
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    @Override
    public void storeData(String key, Object data) {
        lock.lock();
        try {
            if (currentFileSize + marshaller.size(data) > maxFileSize) {
                createNewFile();
            }
            try (FileOutputStream fos = new FileOutputStream(currentWriteFile, true);
                 ObjectOutputStream oos = new ObjectOutputStream(fos)) {
                oos.writeObject(data);
                currentFileSize += marshaller.size(data);
            } catch (IOException e) {
                e.printStackTrace();
            }
        } finally {
            lock.unlock();
        }
    }

    @Override
    public Object readData(String key) {
        lock.lock();
        try {
            for (File file : dataFiles.values()) {
                try (FileInputStream fis = new FileInputStream(file);
                     ObjectInputStream ois = new ObjectInputStream(fis)) {
                    Object data = ois.readObject();
                    // Assuming key is part of the data object
                    if (data instanceof DataItem && ((DataItem) data).getKey().equals(key)) {
                        return data;
                    }
                } catch (IOException | ClassNotFoundException e) {
                    e.printStackTrace();
                }
            }
        } finally {
            lock.unlock();
        }
        return null;
    }

    @Override
    public void updateData(String key, Object newData) {
        lock.lock();
        try {
            // Logic to update data
            // This is a placeholder for the actual update logic
            storeData(key, newData);
        } finally {
            lock.unlock();
        }
    }

