public abstract class Email {
    private String sender;
    private List<String> recipients;
    private List<String> ccRecipients;
    private List<String> bccRecipients;
    private String subject;
    private String content;
    private List<String> attachments;
    private String replyTo;
    private boolean useTLS;
    private boolean useSSL;
    private String username;
    private String password;

    public Email() {
        this.recipients = new ArrayList<>();
        this.ccRecipients = new ArrayList<>();
        this.bccRecipients = new ArrayList<>();
        this.attachments = new ArrayList<>();
    }

    public void setSender(String sender) {
        this.sender = sender;
    }

    public void addRecipient(String recipient) {
        this.recipients.add(recipient);
    }

    public void addCCRecipient(String ccRecipient) {
        this.ccRecipients.add(ccRecipient);
    }

    public void addBCCRecipient(String bccRecipient) {
        this.bccRecipients.add(bccRecipient);
    }

    public void setSubject(String subject) {
        this.subject = subject;
    }

    public void setContent(String content) {
        this.content = content;
    }

    public void addAttachment(String attachment) {
        this.attachments.add(attachment);
    }

    public void setReplyTo(String replyTo) {
        this.replyTo = replyTo;
    }

    public void setTLS(boolean useTLS) {
        this.useTLS = useTLS;
    }

    public void setSSL(boolean useSSL) {
        this.useSSL = useSSL;
    }

    public void setCredentials(String username, String password) {
        this.username = username;
        this.password = password;
    }

    protected Session createSession() {
        Properties props = new Properties();
        props.put("mail.smtp.auth", "true");
        props.put("mail.smtp.starttls.enable", useTLS);
        props.put("mail.smtp.ssl.enable", useSSL);
        props.put("mail.smtp.host", "smtp.example.com"); // Replace with actual SMTP host
        props.put("mail.smtp.port", "587"); // Replace with actual SMTP port

        return Session.getInstance(props, new Authenticator() {
            protected PasswordAuthentication getPasswordAuthentication() {
                return new PasswordAuthentication(username, password);
            }
        });
    }

    public void sendEmail() throws MessagingException {
        Session session = createSession();
        MimeMessage message = new MimeMessage(session);
        message.setFrom(new InternetAddress(sender));

        for (String recipient : recipients) {
            message.addRecipient(Message.RecipientType.TO, new InternetAddress(recipient));
        }

        for (String ccRecipient : ccRecipients) {
            message.addRecipient(Message.RecipientType.CC, new InternetAddress(ccRecipient));
        }

        for (String bccRecipient : bccRecipients) {
            message.addRecipient(Message.RecipientType.BCC, new InternetAddress(bccRecipient));
        }

        if (replyTo != null) {
            message.setReplyTo(InternetAddress.parse(replyTo));
        }

        message.setSubject(subject);
        message.setText(content);

        // Handle attachments if any
        if (!attachments.isEmpty()) {
            Multipart multipart = new MimeMultipart();
            BodyPart messageBodyPart = new MimeBodyPart();
            messageBodyPart.setText(content);
            multipart.addBodyPart(messageBodyPart);

            for (String attachment : attachments) {
                BodyPart attachmentBodyPart = new MimeBodyPart();
                attachmentBodyPart.attachFile(attachment);
                multipart.addBodyPart(attachmentBodyPart);
            }

            message.setContent(multipart);
        }

        Transport.send(message);
    }
}

