public class BlockSort {
    private static final int SMALL_DATA_THRESHOLD = 100;
    private static final int WORK_LIMIT = 1000;

    private int[] data;
    private int[] stack;
    private int stackPointer;
    private int workDone;

    public BlockSort(int[] data) {
        this.data = data;
        this.stack = new int[data.length];
        this.stackPointer = 0;
        this.workDone = 0;
    }

    public void sort() {
        if (data.length <= SMALL_DATA_THRESHOLD) {
            simpleSort(data);
        } else {
            quickSort(data, 0, data.length - 1);
        }
    }

    private void quickSort(int[] array, int low, int high) {
        if (low < high) {
            int pivotIndex = partition(array, low, high);
            quickSort(array, low, pivotIndex - 1);
            quickSort(array, pivotIndex + 1, high);
        }
        trackWork();
        if (workDone > WORK_LIMIT) {
            fallbackSort(array);
        }
    }

    private int partition(int[] array, int low, int high) {
        int pivot = array[high];
        int i = low - 1;
        for (int j = low; j < high; j++) {
            if (array[j] < pivot) {
                i++;
                swap(array, i, j);
            }
        }
        swap(array, i + 1, high);
        return i + 1;
    }

    private void simpleSort(int[] array) {
        for (int i = 0; i < array.length - 1; i++) {
            for (int j = 0; j < array.length - i - 1; j++) {
                if (array[j] > array[j + 1]) {
                    swap(array, j, j + 1);
                }
            }
        }
    }

    private void fallbackSort(int[] array) {
        // Implement a fallback sorting method, e.g., insertion sort
        for (int i = 1; i < array.length; i++) {
            int key = array[i];
            int j = i - 1;
            while (j >= 0 && array[j] > key) {
                array[j + 1] = array[j];
                j--;
            }
            array[j + 1] = key;
        }
    }

    private void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    private void trackWork() {
        workDone++;
    }
}

