class DefaultVortexMasterTest {

    private DefaultVortexMaster vortexMaster;

    @BeforeEach
    void setUp() {
        vortexMaster = new DefaultVortexMaster();
    }

    @Test
    void testSingleTaskletSuccess() throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(1);
        vortexMaster.submitTasklet(() -> {
            latch.countDown();
            return "Success";
        });

        latch.await(1, TimeUnit.SECONDS);
        // Verify tasklet success
        assertTrue(vortexMaster.isTaskletSuccessful());
    }

    @Test
    void testSingleTaskletFailure() throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(1);
        vortexMaster.submitTasklet(() -> {
            latch.countDown();
            throw new RuntimeException("Tasklet failed");
        });

        latch.await(1, TimeUnit.SECONDS);
        // Verify tasklet failure
        assertTrue(vortexMaster.isTaskletFailed());
    }

    @Test
    void testMultipleTaskletsManagement() throws InterruptedException {
        CountDownLatch latch1 = new CountDownLatch(1);
        CountDownLatch latch2 = new CountDownLatch(1);

        vortexMaster.submitTasklet(() -> {
            latch1.countDown();
            return "Tasklet 1 Success";
        });

        vortexMaster.submitTasklet(() -> {
            latch2.countDown();
            throw new RuntimeException("Tasklet 2 failed");
        });

        latch1.await(1, TimeUnit.SECONDS);
        latch2.await(1, TimeUnit.SECONDS);

        // Verify tasklet outcomes
        assertTrue(vortexMaster.isTasklet1Successful());
        assertTrue(vortexMaster.isTasklet2Failed());
    }

    @Test
    void testTaskletExceptionHandling() throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(1);
        vortexMaster.submitTasklet(() -> {
            latch.countDown();
            throw new IllegalArgumentException("Illegal argument");
        });

        latch.await(1, TimeUnit.SECONDS);
        // Verify exception handling
        assertTrue(vortexMaster.isTaskletExceptionHandled());
    }

    @Test
    void testCancelTaskletAfterLaunch() throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(1);
        vortexMaster.submitTasklet(() -> {
            try {
                latch.await();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            return "Tasklet should not complete";
        });

        vortexMaster.cancelTasklet();
        latch.countDown(); // Release the latch to simulate tasklet completion

        // Verify tasklet cancellation
        assertTrue(vortexMaster.isTaskletCancelled());
    }

    @Test
    void testCancelTaskletBeforeLaunch() {
        vortexMaster.submitTasklet(() -> {
            return "Tasklet should not run";
        });

        vortexMaster.cancelTasklet();

        // Verify tasklet cancellation before execution
        assertTrue(vortexMaster.isTaskletCancelledBeforeLaunch());
    }
}

