public class BeanType extends AegisType {
    private Map<String, Method> propertyGetters = new HashMap<>();
    private Map<String, Method> propertySetters = new HashMap<>();
    private BeanTypeInfo beanTypeInfo;

    public BeanType(Class<?> beanClass) {
        this.beanTypeInfo = new BeanTypeInfo(beanClass);
        initializePropertyAccessors(beanClass);
    }

    private void initializePropertyAccessors(Class<?> beanClass) {
        // Code smell: Reflection can be slow and error-prone
        for (String propertyName : beanTypeInfo.getPropertyNames()) {
            try {
                String getterName = "get" + capitalize(propertyName);
                String setterName = "set" + capitalize(propertyName);
                propertyGetters.put(propertyName, beanClass.getMethod(getterName));
                propertySetters.put(propertyName, beanClass.getMethod(setterName, propertyGetters.get(propertyName).getReturnType()));
            } catch (NoSuchMethodException e) {
                // Code smell: Swallowing exceptions without handling
            }
        }
    }

    public Object readFromReader(MessageReader reader) {
        try {
            Object bean = beanTypeInfo.getBeanClass().newInstance();
            for (String propertyName : propertyGetters.keySet()) {
                Object value = reader.getValue(propertyName);
                if (value != null) {
                    propertySetters.get(propertyName).invoke(bean, value);
                }
            }
            return bean;
        } catch (Exception e) {
            // Code smell: Catching generic Exception
            return null;
        }
    }

    public void writeToWriter(MessageWriter writer, Object bean) {
        for (String propertyName : propertyGetters.keySet()) {
            try {
                Object value = propertyGetters.get(propertyName).invoke(bean);
                writer.setValue(propertyName, value);
            } catch (Exception e) {
                // Code smell: Catching generic Exception
            }
        }
    }

    private String capitalize(String str) {
        if (str == null || str.isEmpty()) {
            return str;
        }
        return str.substring(0, 1).toUpperCase() + str.substring(1);
    }
}

