public class ArrayType extends AegisType {
    private String componentName;
    private int minOccurs;
    private int maxOccurs;
    private boolean isFlat;

    public ArrayType(String componentName, int minOccurs, int maxOccurs, boolean isFlat) {
        this.componentName = componentName;
        this.minOccurs = minOccurs;
        this.maxOccurs = maxOccurs;
        this.isFlat = isFlat;
    }

    public Object[] readArray(MessageReader reader) {
        List<Object> list = new ArrayList<>();
        while (reader.hasNext() && list.size() < maxOccurs) {
            Object obj = reader.readObject(componentName);
            if (obj != null) {
                list.add(obj);
            }
        }
        if (list.size() < minOccurs) {
            throw new IllegalStateException("Minimum occurrences not met");
        }
        return list.toArray();
    }

    public void writeArray(MessageWriter writer, Object[] array) {
        if (array.length < minOccurs || array.length > maxOccurs) {
            throw new IllegalArgumentException("Occurrences out of bounds");
        }
        for (Object obj : array) {
            writer.writeObject(componentName, obj);
        }
    }

    public String generateSchema() {
        StringBuilder schema = new StringBuilder();
        schema.append("<xs:element name=\"").append(componentName).append("\" minOccurs=\"")
              .append(minOccurs).append("\" maxOccurs=\"").append(maxOccurs).append("\"/>");
        return schema.toString();
    }

    public String getComponentName() {
        return componentName;
    }

    public int getMinOccurs() {
        return minOccurs;
    }

    public int getMaxOccurs() {
        return maxOccurs;
    }

    public boolean isFlat() {
        return isFlat;
    }
}

public abstract class JmsTransactionTestSupport extends TestSupport implements MessageListener {

    protected Connection connection;
    protected Session session;
    protected MessageProducer producer;
    protected MessageConsumer consumer;
    protected Destination destination;

    protected void setUp() throws Exception {
        InitialContext context = new InitialContext();
        ConnectionFactory connectionFactory = (ConnectionFactory) context.lookup("ConnectionFactory");
        destination = (Destination) context.lookup("queue/testQueue");

        connection = connectionFactory.createConnection();
        session = connection.createSession(true, Session.SESSION_TRANSACTED);
        producer = session.createProducer(destination);
        consumer = session.createConsumer(destination);
        connection.start();
    }

    protected void tearDown() throws Exception {
        if (producer != null) {
            producer.close();
        }
        if (consumer != null) {
            consumer.close();
        }
        if (session != null) {
            session.close();
        }
        if (connection != null) {
            connection.close();
        }
    }

    protected void sendMessage(String text) throws JMSException {
        TextMessage message = session.createTextMessage(text);
        producer.send(message);
    }

    protected String receiveMessage() throws JMSException {
        return ((TextMessage) consumer.receive(1000)).getText();
    }

    protected void commitTransaction() throws JMSException {
        session.commit();
    }

    protected void rollbackTransaction() throws JMSException {
        session.rollback();
    }

    public void onMessage(Message message) {
        // Implement message processing logic here
    }

    // Test methods for various scenarios
    public void testSendAndReceiveMessage() throws Exception {
        sendMessage("Hello, JMS!");
        commitTransaction();

        String receivedMessage = receiveMessage();
        assertEquals("Hello, JMS!", receivedMessage);
    }

    public void testRollbackTransaction() throws Exception {
        sendMessage("Message to be rolled back");
        // Do not commit, just rollback
        rollbackTransaction();

        String receivedMessage = receiveMessage();
        assertNull(receivedMessage);
    }

    public void testMessageAcknowledgment() throws Exception {
        sendMessage("Acknowledged Message");
        commitTransaction();

        String receivedMessage = receiveMessage();
        assertEquals("Acknowledged Message", receivedMessage);
    }

    public void testBatchingMessages() throws Exception {
        for (int i = 0; i < 10; i++) {
            sendMessage("Batch Message " + i);
        }
