public class TokenTest {
    private static final String SECRET_KEY = "mySecretKey";
    private static final String SUBJECT = "user123";
    private static final String ISSUER = "myApp";
    private static final String AUDIENCE = "myAudience";
    private static final String GROUP = "myGroup";
    private static final String ROLE = "admin";
    private static final long EXPIRATION_TIME = 1000 * 60 * 5; // 5 minutes
    private static final long NOT_BEFORE_TIME = 1000 * 60; // 1 minute

    private String token;

    @BeforeEach
    public void setUp() {
        Date now = new Date();
        Date expirationDate = new Date(now.getTime() + EXPIRATION_TIME);
        Date notBeforeDate = new Date(now.getTime() + NOT_BEFORE_TIME);

        token = Jwts.builder()
                .setSubject(SUBJECT)
                .setIssuer(ISSUER)
                .setAudience(AUDIENCE)
                .claim("group", GROUP)
                .claim("role", ROLE)
                .setIssuedAt(now)
                .setNotBefore(notBeforeDate)
                .setExpiration(expirationDate)
                .signWith(SignatureAlgorithm.HS256, SECRET_KEY)
                .compact();
    }

    @Test
    public void testTokenEncoding() {
        assertNotNull(token);
        assertFalse(token.isEmpty());
    }

    @Test
    public void testTokenDecoding() {
        Claims claims = Jwts.parser()
                .setSigningKey(SECRET_KEY)
                .parseClaimsJws(token)
                .getBody();

        assertEquals(SUBJECT, claims.getSubject());
        assertEquals(ISSUER, claims.getIssuer());
        assertEquals(AUDIENCE, claims.getAudience());
        assertEquals(GROUP, claims.get("group"));
        assertEquals(ROLE, claims.get("role"));
    }

    @Test
    public void testTokenExpiration() {
        try {
            Thread.sleep(EXPIRATION_TIME + 1000); // Wait for token to expire
            Jwts.parser().setSigningKey(SECRET_KEY).parseClaimsJws(token);
            fail("Expected exception not thrown");
        } catch (Exception e) {
            assertTrue(e.getMessage().contains("JWT expired"));
        }
    }

    @Test
    public void testTokenNotBefore() {
        try {
            Thread.sleep(NOT_BEFORE_TIME - 500); // Wait before not before time
            Jwts.parser().setSigningKey(SECRET_KEY).parseClaimsJws(token);
            fail("Expected exception not thrown");
        } catch (Exception e) {
