    protected Map<String, String> dynamicAttributes;
    protected String tooltip;

    public UIBean() {
        eventHandlers = new HashMap<>();
        dynamicAttributes = new HashMap<>();
    }

    public abstract String render();

    protected String evaluateParameters(String input) {
        // Code smell: This method could be more robust in handling parameters
        return input.replace("${theme}", theme)
                    .replace("${cssStyle}", cssStyle)
                    .replace("${tooltip}", tooltip);
    }

    public void setTemplate(String template) {
        this.template = template;
    }

    public void setTheme(String theme) {
        this.theme = theme;
    }

    public void setCssStyle(String cssStyle) {
        this.cssStyle = cssStyle;
    }

    public void addEventHandler(String event, String handler) {
        eventHandlers.put(event, handler);
    }

    public void setDynamicAttribute(String key, String value) {
        dynamicAttributes.put(key, value);
    }

    public void setTooltip(String tooltip) {
        this.tooltip = tooltip;
    }

    protected String renderTemplate() {
        // Code smell: This method could be simplified or refactored
        String rendered = template;
        for (Map.Entry<String, String> entry : dynamicAttributes.entrySet()) {
            rendered = rendered.replace("${" + entry.getKey() + "}", entry.getValue());
        }
        return evaluateParameters(rendered);
    }
}

