public abstract class AbstractLimitDialog<E> extends JDialog {
    protected JTextField softLimitField;
    protected JTextField hardLimitField;
    protected JTextField globalLimitField;
    protected JCheckBox unlimitedSoftCheckBox;
    protected JCheckBox unlimitedHardCheckBox;
    protected JCheckBox unlimitedGlobalCheckBox;
    protected JButton okButton;
    protected LimitWrapper<E> limitWrapper;

    public AbstractLimitDialog(LimitWrapper<E> limitWrapper) {
        this.limitWrapper = limitWrapper;
        initializeDialog();
    }

    private void initializeDialog() {
        setLayout(new GridLayout(0, 2));
        softLimitField = new JTextField();
        hardLimitField = new JTextField();
        globalLimitField = new JTextField();
        unlimitedSoftCheckBox = new JCheckBox("Unlimited Soft Limit");
        unlimitedHardCheckBox = new JCheckBox("Unlimited Hard Limit");
        unlimitedGlobalCheckBox = new JCheckBox("Unlimited Global Limit");
        okButton = new JButton("OK");

        add(new JLabel("Soft Limit:"));
        add(softLimitField);
        add(unlimitedSoftCheckBox);
        add(new JLabel("Hard Limit:"));
        add(hardLimitField);
        add(unlimitedHardCheckBox);
        add(new JLabel("Global Limit:"));
        add(globalLimitField);
        add(unlimitedGlobalCheckBox);
        add(okButton);

        okButton.setEnabled(false);
        addListeners();
        loadExistingLimits();
        validateInput();
    }

    private void addListeners() {
        ActionListener listener = new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                validateInput();
            }
        };
        softLimitField.addActionListener(listener);
        hardLimitField.addActionListener(listener);
        globalLimitField.addActionListener(listener);
        unlimitedSoftCheckBox.addActionListener(listener);
        unlimitedHardCheckBox.addActionListener(listener);
        unlimitedGlobalCheckBox.addActionListener(listener);
    }

    private void loadExistingLimits() {
        softLimitField.setText(String.valueOf(limitWrapper.getSoftLimit()));
        hardLimitField.setText(String.valueOf(limitWrapper.getHardLimit()));
        globalLimitField.setText(String.valueOf(limitWrapper.getGlobalLimit()));
        unlimitedSoftCheckBox.setSelected(limitWrapper.isUnlimitedSoft());
        unlimitedHardCheckBox.setSelected(limitWrapper.isUnlimitedHard());
        unlimitedGlobalCheckBox.setSelected(limitWrapper.isUnlimitedGlobal());
    }

    protected void validateInput() {
        boolean isValid = true;
        if (!unlimitedSoftCheckBox.isSelected()) {
            isValid &= validateLimit(softLimitField.getText());
        }
        if (!unlimitedHardCheckBox.isSelected()) {
            isValid &= validateLimit(hardLimitField.getText());
        }
        if (!unlimitedGlobalCheckBox.isSelected()) {
            isValid &= validateLimit(globalLimitField.getText());
        }
        okButton.setEnabled(isValid);
    }

    protected boolean validateLimit(String limit) {
        try {
            Integer.parseInt(limit);
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    public String getNewLimits() {
        return String.format("Soft: %s, Hard: %s, Global: %s",
                unlimitedSoftCheckBox.isSelected() ? "Unlimited" : softLimitField.getText(),
                unlimitedHardCheckBox.isSelected() ? "Unlimited" : hardLimitField.getText(),
                unlimitedGlobalCheckBox.isSelected() ? "Unlimited" : globalLimitField.getText());
    }
}

