public class JmsTransactedConsumerTest extends AmqpTestSupport {

    private Connection connection;
    private Session session;
    private MessageConsumer consumer;
    private Queue queue;

    @Override
    public void setUp() throws Exception {
        super.setUp();
        connection = createConnection();
        session = connection.createSession(true, Session.SESSION_TRANSACTED);
        queue = session.createQueue("testQueue");
        consumer = session.createConsumer(queue);
        connection.start();
    }

    @Test
    public void testConsumeAndAcknowledge() throws Exception {
        // Send a message
        sendMessage("Hello World");

        // Consume the message
        Message message = consumer.receive(1000);
        assertNotNull(message);

        // Acknowledge the message
        session.commit();

        // Verify queue size
        assertEquals(0, getQueueSize(queue));
    }

    @Test
    public void testRollbackBehavior() throws Exception {
        sendMessage("Rollback Test");

        Message message = consumer.receive(1000);
        assertNotNull(message);

        // Rollback the session
        session.rollback();

        // Verify message redelivery
        Message redeliveredMessage = consumer.receive(1000);
        assertNotNull(redeliveredMessage);
        assertTrue(redeliveredMessage.getJMSRedelivered());
    }

    @Test
    public void testConsumerClosedBeforeCommit() throws Exception {
        sendMessage("Close Before Commit");

        Message message = consumer.receive(1000);
        assertNotNull(message);

        // Close the consumer before committing
        consumer.close();
        session.commit();

        // Verify message still exists in the queue
        assertEquals(1, getQueueSize(queue));
    }

    @Test
    public void testMessageOrderingAndPriority() throws Exception {
        sendMessageWithPriority("Low Priority", 0);
        sendMessageWithPriority("High Priority", 9);

        Message message1 = consumer.receive(1000);
        assertNotNull(message1);
        assertEquals("High Priority", ((TextMessage) message1).getText());

        Message message2 = consumer.receive(1000);
        assertNotNull(message2);
        assertEquals("Low Priority", ((TextMessage) message2).getText());

        session.commit();
    }

    @Test
    public void testAllMessagesInSingleTransaction() throws Exception {
        for (int i = 0; i < 5; i++) {
            sendMessage("Message " + i);
        }

        for (int i = 0; i < 5; i++) {
            Message message = consumer.receive(1000);
            assertNotNull(message);
        }

        // Commit all messages
        session.commit();

        // Verify queue size
        assertEquals(0, getQueueSize(queue));
    }

    private void sendMessage(String text) throws JMSException {
        MessageProducer producer = session.createProducer(queue);
        TextMessage message = session.createTextMessage(text);
        producer.send(message);
        producer.close();
    }

    private void sendMessageWithPriority(String text, int priority) throws JMSException {
        MessageProducer producer = session.createProducer(queue);
        TextMessage message = session.createTextMessage(text);
        producer.send(message, DeliveryMode.PERSISTENT, priority, Message.DEFAULT_TIME_TO_LIVE);
        producer.close();
    }

    private int getQueueSize(Queue queue) {
        // Implementation to get the queue size
        return 0; // Placeholder
    }

    @Override
    public void tearDown() throws Exception {
        if (consumer != null) {
            consumer.close();
        }
        if (session != null) {
            session.close();
        }
        if (connection != null) {
            connection.close();
        }
        super.tearDown();
    }
