public class AssignedStreamsTasks extends AssignedTasks<StreamTask> implements RestoringTasks {
    private final Set<StreamTask> suspendedTasks = new HashSet<>();
    private final Set<StreamTask> restoringTasks = new HashSet<>();
    private final Set<StreamTask> previouslyActiveTasks = new HashSet<>();

    public Collection<StreamTask> getSuspendedTasks() {
        return suspendedTasks;
    }

    public Collection<StreamTask> getRestoringTasks() {
        return restoringTasks;
    }

    public Collection<StreamTask> getPreviouslyActiveTasks() {
        return previouslyActiveTasks;
    }

    public boolean areAllTasksRunning() {
        return getAllTasks().stream().allMatch(StreamTask::isRunning);
    }

    public void suspendTask(StreamTask task) {
        if (task.isRunning()) {
            task.suspend();
            suspendedTasks.add(task);
            log("Task suspended: " + task);
        }
    }

    public void closeTask(StreamTask task) {
        task.close();
        log("Task closed: " + task);
    }

    public void restoreTask(StreamTask task) {
        if (!restoringTasks.contains(task)) {
            restoringTasks.add(task);
            log("Task restoring: " + task);
        }
    }

    public void resumeTask(StreamTask task) {
        if (suspendedTasks.contains(task)) {
            task.resume();
            suspendedTasks.remove(task);
            log("Task resumed: " + task);
        }
    }

    public void updateRestoredPartitions(Collection<TopicPartition> partitions) {
        for (TopicPartition partition : partitions) {
            StreamTask task = getTaskForPartition(partition);
            if (task != null) {
                restoreTask(task);
            }
        }
    }

    public void commitUserRequest() {
        // Logic for committing user requests
        log("User request committed.");
    }

    @Override
    public void shutdown() {
        for (StreamTask task : getAllTasks()) {
            closeTask(task);
        }
        log("All tasks shut down.");
    }

    private void log(String message) {
        // Placeholder for logging logic
        System.out.println(message);
    }
}

