public class JoinProjection {
    private final List<Integer> ds1FieldIndexes;
    private final List<Integer> ds2FieldIndexes;

    public JoinProjection(List<Integer> ds1FieldIndexes, List<Integer> ds2FieldIndexes) {
        if ((ds1FieldIndexes == null || ds1FieldIndexes.isEmpty()) && 
            (ds2FieldIndexes == null || ds2FieldIndexes.isEmpty())) {
            throw new IllegalArgumentException("At least one field index must be provided.");
        }
        if (ds1FieldIndexes.size() + ds2FieldIndexes.size() > 22) {
            throw new IllegalArgumentException("A maximum of 22 field indexes can be specified.");
        }
        this.ds1FieldIndexes = ds1FieldIndexes != null ? new ArrayList<>(ds1FieldIndexes) : new ArrayList<>();
        this.ds2FieldIndexes = ds2FieldIndexes != null ? new ArrayList<>(ds2FieldIndexes) : new ArrayList<>();
    }

    public Object[] projectFromDs1(Object[] ds1) {
        return project(ds1, ds1FieldIndexes);
    }

    public Object[] projectFromDs2(Object[] ds2) {
        return project(ds2, ds2FieldIndexes);
    }

    private Object[] project(Object[] dataSet, List<Integer> fieldIndexes) {
        Object[] projectedData = new Object[fieldIndexes.size()];
        for (int i = 0; i < fieldIndexes.size(); i++) {
            int index = fieldIndexes.get(i);
            if (index < 0 || index >= dataSet.length) {
                throw new IndexOutOfBoundsException("Field index " + index + " is out of bounds for dataset.");
            }
            projectedData[i] = dataSet[index];
        }
        return projectedData;
    }

    public static <T> Tuple<T> createTuple(Object... fields) {
        if (fields.length > 25) {
            throw new IllegalArgumentException("A tuple can have a maximum of 25 fields.");
        }
        return new Tuple<>(fields);
    }

    public static class Tuple<T> {
        private final Object[] fields;

        public Tuple(Object... fields) {
            this.fields = fields;
        }

        public Object[] getFields() {
            return fields;
        }
    }
}

public class LocalDictColumnPage extends ColumnPage {
    private PageLevelDictionary dictionary;
    private boolean localDictionaryEnabled;
    private byte[] actualData;
    private byte[] encodedData;

    public LocalDictColumnPage() {
        this.dictionary = new PageLevelDictionary();
        this.localDictionaryEnabled = true;
        this.actualData = new byte[0];
        this.encodedData = new byte[0];
    }

    public byte[] getEncodedData() {
        if (localDictionaryEnabled) {
            return encodedData;
        } else {
            throw new UnsupportedOperationException("Local dictionary encoding is disabled.");
        }
    }

    public byte[] getActualData() {
        return actualData;
    }

    public void insertBytes(byte[] bytes) {
        // Code smell: No validation on input bytes
        actualData = concatenate(actualData, bytes);
        if (localDictionaryEnabled) {
            encodedData = dictionary.encode(actualData);
        }
    }

    public void disableLocalDictionary() {
        localDictionaryEnabled = false;
    }

    public void freeMemory() {
        actualData = null;
        encodedData = null;
        dictionary.clear();
    }

    @Override
    public void unsupportedMethod() {
        throw new UnsupportedOperationException("This method is not supported in LocalDictColumnPage.");
    }

    private byte[] concatenate(byte[] array1, byte[] array2) {
        byte[] result = new byte[array1.length + array2.length];
        System.arraycopy(array1, 0, result, 0, array1.length);
        System.arraycopy(array2, 0, result, array1.length, array2.length);
        return result;
    }
}

public class DataSourcePreferences {
    private Map<String, DataSource> dataSources;
    private DataSourceView view;

    public DataSourcePreferences(DataSourceView view) {
        this.view = view;
        this.dataSources = new HashMap<>();
        initializeView();
    }

    private void initializeView() {
        view.setAddAction(e -> addDataSource());
        view.setDuplicateAction(e -> duplicateDataSource());
        view.setRemoveAction(e -> removeDataSource());
        view.setTestAction(e -> testConnection());
    }

    private void addDataSource() {
        String name = view.getNewDataSourceName();
        if (!dataSources.containsKey(name)) {
            DataSource dataSource = new DataSource(name);
            dataSources.put(name, dataSource);
            view.updateDataSourceList(dataSources.keySet());
            fireDataSourceChanged();
        } else {
            view.showError("Data source already exists.");
        }
    }

    private void duplicateDataSource() {
        String selectedName = view.getSelectedDataSourceName();
        if (dataSources.containsKey(selectedName)) {
            DataSource original = dataSources.get(selectedName);
            DataSource duplicate = new DataSource(original);
            dataSources.put(duplicate.getName(), duplicate);
            view.updateDataSourceList(dataSources.keySet());
            fireDataSourceChanged();
        } else {
            view.showError("Selected data source does not exist.");
        }
    }

    private void removeDataSource() {
        String selectedName = view.getSelectedDataSourceName();
        if (dataSources.remove(selectedName) != null) {
            view.updateDataSourceList(dataSources.keySet());
            fireDataSourceChanged();
        } else {
            view.showError("Selected data source does not exist.");
        }
    }

    private void testConnection() {
        String selectedName = view.getSelectedDataSourceName();
        if (dataSources.containsKey(selectedName)) {
            DataSource dataSource = dataSources.get(selectedName);
            boolean success = dataSource.testConnection();
            if (success) {
                view.showMessage("Connection successful.");
            } else {
                view.showError("Connection failed.");
            }
        } else {
            view.showError("Selected data source does not exist.");
        }
    }

    private void fireDataSourceChanged() {
        // Notify other components about the data source change
    }
}

