public class JmsSession implements Session {
    private final Connection connection;
    private final int acknowledgeMode;
    private final ConcurrentHashMap<String, MessageConsumer> consumers = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, MessageProducer> producers = new ConcurrentHashMap<>();
    private final Lock lock = new ReentrantLock();
    private boolean isStarted = false;

    public JmsSession(Connection connection, int acknowledgeMode) {
        this.connection = connection;
        this.acknowledgeMode = acknowledgeMode;
    }

    public void start() throws JMSException {
        lock.lock();
        try {
            if (!isStarted) {
                connection.start();
                isStarted = true;
            }
        } finally {
            lock.unlock();
        }
    }

    public void stop() throws JMSException {
        lock.lock();
        try {
            if (isStarted) {
                connection.stop();
                isStarted = false;
            }
        } finally {
            lock.unlock();
        }
    }

    public MessageProducer createProducer(Destination destination) throws JMSException {
        lock.lock();
        try {
            MessageProducer producer = connection.createSession(false, acknowledgeMode).createProducer(destination);
            producers.put(destination.toString(), producer);
            return producer;
        } finally {
            lock.unlock();
        }
    }

    public MessageConsumer createConsumer(Destination destination) throws JMSException {
        lock.lock();
        try {
            MessageConsumer consumer = connection.createSession(false, acknowledgeMode).createConsumer(destination);
            consumers.put(destination.toString(), consumer);
            return consumer;
        } finally {
            lock.unlock();
        }
    }

    public void commit() throws JMSException {
        lock.lock();
        try {
            connection.commit();
        } finally {
            lock.unlock();
        }
    }

    public void rollback() throws JMSException {
        lock.lock();
        try {
            connection.rollback();
        } finally {
            lock.unlock();
        }
    }

    public void close() throws JMSException {
        lock.lock();
        try {
            for (MessageConsumer consumer : consumers.values()) {
                consumer.close();
            }
            for (MessageProducer producer : producers.values()) {
                producer.close();
            }
            connection.close();
        } finally {
            lock.unlock();
        }
    }

    public TextMessage createTextMessage(String text) throws JMSException {
        return connection.createSession(false, acknowledgeMode).createTextMessage(text);
    }

    public BytesMessage createBytesMessage() throws JMSException {
        return connection.createSession(false, acknowledgeMode).createBytesMessage();
    }

    public ObjectMessage createObjectMessage(Serializable object) throws JMSException {
        return connection.createSession(false, acknowledgeMode).createObjectMessage(object);
    }

    // Additional methods for handling message listeners and asynchronous delivery can be added here.
}

