public class DistributedResultSet implements ResultSet {
    private List<ResultSet> comps;
    private int currentIndex;

    public DistributedResultSet(List<ResultSet> comps) {
        this.comps = comps;
        this.currentIndex = -1;
    }

    @Override
    public boolean next() throws SQLException {
        if (currentIndex < comps.size() - 1) {
            currentIndex++;
            return true;
        }
        return false;
    }

    @Override
    public boolean previous() throws SQLException {
        if (currentIndex > 0) {
            currentIndex--;
            return true;
        }
        return false;
    }

    @Override
    public boolean first() throws SQLException {
        if (!comps.isEmpty()) {
            currentIndex = 0;
            return true;
        }
        return false;
    }

    @Override
    public boolean last() throws SQLException {
        if (!comps.isEmpty()) {
            currentIndex = comps.size() - 1;
            return true;
        }
        return false;
    }

    @Override
    public int getInt(int columnIndex) throws SQLException {
        return comps.get(currentIndex).getInt(columnIndex);
    }

    @Override
    public String getString(int columnIndex) throws SQLException {
        return comps.get(currentIndex).getString(columnIndex);
    }

    @Override
    public boolean updateRow() throws SQLException {
        throw new UnsupportedOperationException("Update operation not supported.");
    }

    @Override
    public boolean insertRow() throws SQLException {
        throw new UnsupportedOperationException("Insert operation not supported.");
    }

    @Override
    public void close() throws SQLException {
        for (ResultSet rs : comps) {
            rs.close();
        }
    }

    @Override
    public SQLWarning getWarnings() throws SQLException {
        SQLWarning warnings = null;
        for (ResultSet rs : comps) {
            SQLWarning warning = rs.getWarnings();
            if (warning != null) {
                warnings = warning;
            }
        }
        return warnings;
    }

    // Other methods from ResultSet interface would be implemented here,
    // but many would throw UnsupportedOperationException as per requirement.
}

