        assertEquals(ZERO, POSITIVE_ONE.add(NEGATIVE_ONE));
        assertEquals(POSITIVE_INFINITY, POSITIVE_ONE.add(POSITIVE_INFINITY));
    }

    @Test
    public void testSubtraction() {
        assertEquals(ZERO, POSITIVE_ONE.subtract(POSITIVE_ONE));
        assertEquals(NEGATIVE_ONE, POSITIVE_ONE.subtract(POSITIVE_TWO));
        assertEquals(NEGATIVE_INFINITY, NEGATIVE_ONE.subtract(POSITIVE_ONE));
    }

