public class InstancePlugin {

    private static final Logger logger = LoggerFactory.getLogger(InstancePlugin.class);
    private InstanceService instanceService;

    public InstancePlugin(InstanceService instanceService) {
        this.instanceService = instanceService;
    }

    public void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String action = request.getParameter("action");
        switch (action) {
            case "list":
                listInstances(response);
                break;
            case "status":
                getInstanceStatus(request, response);
                break;
            default:
                renderHome(response);
                break;
        }
    }

    public void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String action = request.getParameter("action");
        switch (action) {
            case "create":
                createInstance(request, response);
                break;
            case "start":
                startInstance(request, response);
                break;
            case "stop":
                stopInstance(request, response);
                break;
            case "destroy":
                destroyInstance(request, response);
                break;
            default:
                response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid action");
                break;
        }
    }

    private void listInstances(HttpServletResponse response) throws IOException {
        List<Instance> instances = instanceService.getAllInstances();
        response.setContentType("application/json");
        response.getWriter().write(JsonUtil.toJson(instances));
    }

    private void getInstanceStatus(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String instanceId = request.getParameter("id");
        Instance instance = instanceService.getInstance(instanceId);
        if (instance != null) {
            response.setContentType("application/json");
            response.getWriter().write(JsonUtil.toJson(instance));
        } else {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "Instance not found");
        }
    }

    private void createInstance(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String instanceName = request.getParameter("name");
        Instance instance = instanceService.createInstance(instanceName);
        logger.info("Created instance: {}", instance);
        response.setContentType("application/json");
        response.getWriter().write(JsonUtil.toJson(instance));
    }

    private void startInstance(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String instanceId = request.getParameter("id");
        boolean success = instanceService.startInstance(instanceId);
        if (success) {
            logger.info("Started instance: {}", instanceId);
            response.setStatus(HttpServletResponse.SC_OK);
        } else {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Failed to start instance");
        }
    }

    private void stopInstance(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String instanceId = request.getParameter("id");
        boolean success = instanceService.stopInstance(instanceId);
        if (success) {
            logger.info("Stopped instance: {}", instanceId);
            response.setStatus(HttpServletResponse.SC_OK);
        } else {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Failed to stop instance");
        }
    }

    private void destroyInstance(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String instanceId = request.getParameter("id");
        boolean success = instanceService.destroyInstance(instanceId);
        if (success) {
            logger.info("Destroyed instance: {}", instanceId);
            response.setStatus(HttpServletResponse.SC_OK);
        } else {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Failed to destroy instance");
        }
    }

    private void renderHome(HttpServletResponse response) throws IOException {
        response.setContentType("text/html");
        response.getWriter().write("<h1>Instance Management</h1>");
        response.getWriter().write("<p>Use the API to manage instances.</p>");
    }
}

