public class ListMultipleChoice<T> extends AbstractChoice<Collection<T>, T> {
    private int maxRows;

    public ListMultipleChoice(String id, List<? extends T> choices) {
        super(id, choices);
    }

    public ListMultipleChoice(String id, List<? extends T> choices, int maxRows) {
        super(id, choices);
        this.maxRows = maxRows;
    }

    public ListMultipleChoice(String id, List<? extends T> choices, IModel<Collection<T>> model) {
        super(id, choices, model);
    }

    public ListMultipleChoice(String id, List<? extends T> choices, IModel<Collection<T>> model, IChoiceRenderer<? super T> renderer) {
        super(id, choices, model, renderer);
    }

    public String getSelectedValuesAsString() {
        Collection<T> selectedValues = getModelObject();
        return selectedValues != null ? String.join(", ", selectedValues.toString()) : "";
    }

    public boolean isChoiceSelected(T choice) {
        Collection<T> selectedValues = getModelObject();
        return selectedValues != null && selectedValues.contains(choice);
    }

    protected T convertChoiceIdToChoice(String choiceId) {
        for (T choice : getChoices()) {
            if (getChoiceRenderer().getIdValue(choice, 0).equals(choiceId)) {
                return choice;
            }
        }
        return null;
