class BasicIOTest {

    private TemporaryFolder tempFolder;
    private TextIO textIO;

    @Before
    public void setUp() throws IOException {
        tempFolder = new TemporaryFolder();
        tempFolder.create();
        textIO = new TextIO();
    }

    @After
    public void tearDown() throws IOException {
        tempFolder.delete();
    }

    @Test
    public void testReadWriteWithCommaDelimiter() throws IOException {
        File inputFile = tempFolder.newFile("input.csv");
        File outputFile = tempFolder.newFile("output.csv");
        String content = "name,age\nAlice,30\nBob,25";
        textIO.write(inputFile, content);
        String result = textIO.read(outputFile);
        assertEquals(content, result);
    }

    @Test
    public void testReadWriteWithTabDelimiter() throws IOException {
        File inputFile = tempFolder.newFile("input.tsv");
        File outputFile = tempFolder.newFile("output.tsv");
        String content = "name\tage\nAlice\t30\nBob\t25";
        textIO.write(inputFile, content);
        String result = textIO.read(outputFile);
        assertEquals(content, result);
    }

    @Test
    public void testReadEmptyFile() throws IOException {
        File emptyFile = tempFolder.newFile("empty.txt");
        String result = textIO.read(emptyFile);
        assertEquals("", result);
    }

    @Test
    public void testReadCompressedFile() throws IOException {
        File compressedFile = tempFolder.newFile("compressed.gz");
        String content = "name,age\nAlice,30\nBob,25";
        textIO.writeCompressed(compressedFile, content);
        String result = textIO.readCompressed(compressedFile);
        assertEquals(content, result);
    }

    @Test
    public void testMonitorNewFile() throws IOException {
        File monitoredFile = tempFolder.newFile("monitor.txt");
        textIO.monitorFile(monitoredFile);
        String content = "New content";
        textIO.write(monitoredFile, content);
        String result = textIO.read(monitoredFile);
        assertEquals(content, result);
    }
}

