    public void storeItem(Item item) {
        try {
            validateItem(item);
            // Perform store operation
            logger.info("Item stored: " + item.getId());
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error storing item: " + item.getId(), e);
        }
    }

    public void destroyItem(Item item) {
        try {
            validateItem(item);
            // Perform destroy operation
            logger.info("Item destroyed: " + item.getId());
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error destroying item: " + item.getId(), e);
        }
    }

    public void updateItemState(Item item, ItemState newState) {
        try {
            validateItem(item);
            stateManager.updateState(item, newState);
            logger.info("Item state updated: " + item.getId() + " to " + newState);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error updating item state: " + item.getId(), e);
        }
    }

    public void cloneItem(Item item) {
        try {
            validateItem(item);
            // Perform clone operation
            logger.info("Item cloned: " + item.getId());
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error cloning item: " + item.getId(), e);
        }
    }

    public void copyItem(Item source, Item destination) {
        try {
            validateItem(source);
            // Perform copy operation
            logger.info("Item copied from: " + source.getId() + " to " + destination.getId());
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error copying item from: " + source.getId() + " to " + destination.getId(), e);
        }
    }

    public void moveItem(Item item, String newLocation) {
        try {
            validateItem(item);
            // Perform move operation
            logger.info("Item moved: " + item.getId() + " to " + newLocation);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error moving item: " + item.getId(), e);
        }
    }

    public void removeItem(Item item) {
        try {
            validateItem(item);
            // Perform remove operation
            logger.info("Item removed: " + item.getId());
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error removing item: " + item.getId(), e);
        }
    }

    private void validateItem(Item item) throws Exception {
        if (item.isCheckedOut()) {
            throw new Exception("Item is checked out: " + item.getId());
        }
        if (item.isLocked()) {
            throw new Exception("Item is locked: " + item.getId());
        }
        if (item.isProtected()) {
            throw new Exception("Item is protected: " + item.getId());
        }
        // Additional validation logic can be added here
    }
}

