        } else {
            logger.warning("Attempted to add null or empty security token.");
        }
    }

    public void addSignature(String signature) {
        if (signature != null && !signature.isEmpty()) {
            signatures.add(signature);
            logger.info("Added signature: " + signature);
        } else {
            logger.warning("Attempted to add null or empty signature.");
        }
    }

    public void addEncryptionPart(String part) {
