public class HBaseScanner implements Scanner {
    private Connection connection;
    private Table table;
    private ResultScanner resultScanner;
    private Scan scan;
    private List<String> columnMappings;
    private boolean isInitialized = false;
    private int scannedRows = 0;

    public HBaseScanner(String tableName, List<String> columnMappings) {
        this.columnMappings = columnMappings;
        this.scan = new Scan();
        try {
            this.connection = ConnectionFactory.createConnection();
            this.table = connection.getTable(TableName.valueOf(tableName));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void initialize() {
        if (!isInitialized) {
            try {
                resultScanner = table.getScanner(scan);
                isInitialized = true;
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public Object[] fetchNext() {
        if (resultScanner == null) {
            return null;
        }
        Result result = resultScanner.next();
        if (result == null) {
            return null;
        }
        scannedRows++;
        return mapResultToTuple(result);
    }

    private Object[] mapResultToTuple(Result result) {
        Object[] tuple = new Object[columnMappings.size()];
        for (int i = 0; i < columnMappings.size(); i++) {
            tuple[i] = result.getValue(columnMappings.get(i).getBytes(), null);
        }
        return tuple;
    }

    public void reset() {
        close();
        initialize();
    }

    public void close() {
        try {
            if (resultScanner != null) {
                resultScanner.close();
            }
            if (table != null) {
                table.close();
            }
            if (connection != null) {
                connection.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public int getScannedRows() {
        return scannedRows;
    }
}

