public abstract class ItemImpl implements Item {
    protected String path;
    protected String name;
    protected ItemImpl parent;
    protected boolean isNew;
    protected boolean isModified;
    protected boolean isRemoved;
    protected List<ItemLifecycleListener> listeners = new ArrayList<>();

    public ItemImpl(String path, String name, ItemImpl parent) {
        this.path = path;
        this.name = name;
        this.parent = parent;
        this.isNew = true;
        this.isModified = false;
        this.isRemoved = false;
    }

    public String getPath() {
        return path;
    }

    public String getName() {
        return name;
    }

    public ItemImpl getParent() {
        return parent;
    }

    public boolean isNew() {
        return isNew;
    }

    public boolean isModified() {
        return isModified;
    }

    public boolean isRemoved() {
        return isRemoved;
    }

    public void addLifecycleListener(ItemLifecycleListener listener) {
        listeners.add(listener);
    }

    public void removeLifecycleListener(ItemLifecycleListener listener) {
        listeners.remove(listener);
    }

    protected void notifyListeners() {
        for (ItemLifecycleListener listener : listeners) {
            listener.onItemChanged(this);
        }
    }

    public void save() {
        if (isRemoved) {
            throw new IllegalStateException("Cannot save a removed item.");
        }
        // Save logic here
        isNew = false;
        isModified = false;
        notifyListeners();
    }

    public void refresh() {
        if (isRemoved) {
            throw new IllegalStateException("Cannot refresh a removed item.");
        }
        // Refresh logic here
        notifyListeners();
    }

    public void remove() {
        if (isRemoved) {
            throw new IllegalStateException("Item is already removed.");
        }
        isRemoved = true;
        notifyListeners();
    }

    public void markModified() {
        if (!isRemoved) {
            isModified = true;
            notifyListeners();
        }
    }
}

