public class BOMNode {
    private String productId;
    private String productName;
    private int quantity;
    private boolean isManufactured;
    private boolean isWarehouseManaged;
    private List<BOMNode> children;
    private BOMNode parent;

    public BOMNode(String productId, String productName, int quantity, boolean isManufactured, boolean isWarehouseManaged) {
        this.productId = productId;
        this.productName = productName;
        this.quantity = quantity;
        this.isManufactured = isManufactured;
        this.isWarehouseManaged = isWarehouseManaged;
        this.children = new ArrayList<>();
    }

    public void addChild(BOMNode child) {
        child.setParent(this);
        this.children.add(child);
    }

    public void setParent(BOMNode parent) {
        this.parent = parent;
    }

    public List<BOMNode> getChildren() {
        return children;
    }

    public BOMNode getParent() {
        return parent;
    }

    public void applySubstitutionRule(String productId, BOMNode substitute) {
        for (BOMNode child : children) {
            if (child.productId.equals(productId)) {
                child = substitute;
                break;
            }
        }
    }

    public int calculateTotalQuantity() {
        int total = this.quantity;
        for (BOMNode child : children) {
            total += child.calculateTotalQuantity();
        }
        return total;
    }

    public void createManufacturingOrder() {
        if (isManufactured) {
            System.out.println("Creating manufacturing order for: " + productName + " (ID: " + productId + ")");
        }
        for (BOMNode child : children) {
            child.createManufacturingOrder();
        }
    }

    public void printBOMStructure(String prefix) {
        System.out.println(prefix + productName + " (ID: " + productId + ", Qty: " + quantity + ")");
        for (BOMNode child : children) {
            child.printBOMStructure(prefix + "  ");
        }
    }

    public boolean isManufactured() {
        return isManufactured;
    }

    public boolean isWarehouseManaged() {
        return isWarehouseManaged;
    }

    public static void main(String[] args) {
        BOMNode root = new BOMNode("1", "Root Product", 1, true, false);
        BOMNode child1 = new BOMNode("2", "Child Product 1", 2, false, true);
        BOMNode child2 = new BOMNode("3", "Child Product 2", 3, true, false);

        root.addChild(child1);
        root.addChild(child2);

        root.printBOMStructure("");
        System.out.println("Total Quantity: " + root.calculateTotalQuantity());
        root.createManufacturingOrder();
    }
}

