public final class AnnotatorUtil {

    private AnnotatorUtil() {
        // Prevent instantiation
    }

    public static String getStringFeature(Annotation annotation, String featureName) {
        return getFeatureValue(annotation, featureName, String.class);
    }

    public static Integer getIntegerFeature(Annotation annotation, String featureName) {
        return getFeatureValue(annotation, featureName, Integer.class);
    }

    public static Float getFloatFeature(Annotation annotation, String featureName) {
        return getFeatureValue(annotation, featureName, Float.class);
    }

    public static Boolean getBooleanFeature(Annotation annotation, String featureName) {
        return getFeatureValue(annotation, featureName, Boolean.class);
    }

    private static <T> T getFeatureValue(Annotation annotation, String featureName, Class<T> type) {
        try {
            TypeDescription typeDescription = annotation.getType();
            FeatureDescription featureDescription = typeDescription.getFeatureByBaseName(featureName);
            if (featureDescription == null) {
                throw new IllegalArgumentException("Feature '" + featureName + "' not found in type '" + typeDescription.getName() + "'");
            }
            Object value = annotation.getFeatureValue(featureDescription);
            if (value != null && type.isInstance(value)) {
                return type.cast(value);
            } else {
                throw new IllegalArgumentException("Feature '" + featureName + "' is not of type '" + type.getSimpleName() + "'");
            }
        } catch (Exception e) {
            throw new RuntimeException("Error retrieving feature value: " + e.getMessage(), e);
        }
    }

    public static void validateRequiredFeature(Annotation annotation, String featureName) {
        TypeDescription typeDescription = annotation.getType();
        FeatureDescription featureDescription = typeDescription.getFeatureByBaseName(featureName);
        if (featureDescription == null || annotation.getFeatureValue(featureDescription) == null) {
            throw new IllegalArgumentException("Required feature '" + featureName + "' is missing in type '" + typeDescription.getName() + "'");
        }
    }

