public class BeanConfigurator {

    private CocoonBean cocoonBean;

    public BeanConfigurator(CocoonBean cocoonBean) {
        this.cocoonBean = cocoonBean;
    }

    public String configure(File xmlFile) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parse(xmlFile);
        document.getDocumentElement().normalize();

        Element root = document.getDocumentElement();
        validateRootElement(root);

        setVerbosity(root);
        setDirectoryPaths(root);
        setLoggingOptions(root);
        processUriFile(root);
        processBrokenLinks(root);
        processIncludesExcludes(root);

        return cocoonBean.getDestinationDirectory();
    }

    private void validateRootElement(Element root) throws Exception {
        if (!"cocoonConfig".equals(root.getNodeName())) {
            throw new Exception("Invalid root element: " + root.getNodeName());
        }
    }

    private void setVerbosity(Element root) {
        String verbosity = root.getAttribute("verbosity");
        cocoonBean.setVerbosity(verbosity);
    }

    private void setDirectoryPaths(Element root) {
        String sourceDir = root.getAttribute("sourceDir");
        String destDir = root.getAttribute("destDir");
        cocoonBean.setSourceDirectory(sourceDir);
        cocoonBean.setDestinationDirectory(destDir);
    }

    private void setLoggingOptions(Element root) {
        String loggingEnabled = root.getAttribute("loggingEnabled");
        cocoonBean.setLoggingEnabled(Boolean.parseBoolean(loggingEnabled));
    }

    private void processUriFile(Element root) throws Exception {
        NodeList uriFiles = root.getElementsByTagName("uriFile");
        for (int i = 0; i < uriFiles.getLength(); i++) {
            Element uriFileElement = (Element) uriFiles.item(i);
            String uriFilePath = uriFileElement.getTextContent();
            cocoonBean.addTargetUri(uriFilePath);
        }
    }

    private void processBrokenLinks(Element root) {
        NodeList brokenLinks = root.getElementsByTagName("brokenLink");
        for (int i = 0; i < brokenLinks.getLength(); i++) {
            Element brokenLinkElement = (Element) brokenLinks.item(i);
            String link = brokenLinkElement.getTextContent();
            cocoonBean.addBrokenLink(link);
        }
    }

    private void processIncludesExcludes(Element root) {
        NodeList includes = root.getElementsByTagName("include");
        for (int i = 0; i < includes.getLength(); i++) {
            Element includeElement = (Element) includes.item(i);
            String pattern = includeElement.getTextContent();
            cocoonBean.addIncludePattern(pattern);
        }

        NodeList excludes = root.getElementsByTagName("exclude");
        for (int i = 0; i < excludes.getLength(); i++) {
            Element excludeElement = (Element) excludes.item(i);
            String pattern = excludeElement.getTextContent();
            cocoonBean.addExcludePattern(pattern);
        }
    }
}

