    private int retries;

    @Parameter(property = "karaf.sshKey")
    private String sshKey;

    public void execute() throws MojoExecutionException {
        try {
            if (useJmx) {
                deployViaJmx();
            } else {
                deployViaSsh();
            }
        } catch (Exception e) {
            getLog().error("Deployment failed: " + e.getMessage(), e);
            throw new MojoExecutionException("Deployment failed", e);
        }
    }

    private void deployViaJmx() throws Exception {
        for (int attempt = 0; attempt < retries; attempt++) {
            try {
                // JMX deployment logic
                getLog().info("Deploying via JMX to " + host + ":" + port);
                // Simulated deployment code
                break; // Exit loop on success
            } catch (Exception e) {
                getLog().warn("JMX deployment attempt " + (attempt + 1) + " failed: " + e.getMessage());
                if (attempt == retries - 1) {
                    throw e; // Rethrow on last attempt
                }
            }
        }
    }

    private void deployViaSsh() throws Exception {
        for (int attempt = 0; attempt < retries; attempt++) {
            try {
                // SSH deployment logic
                getLog().info("Deploying via SSH to " + host + ":" + port);
                // Simulated deployment code
                break; // Exit loop on success
            } catch (Exception e) {
                getLog().warn("SSH deployment attempt " + (attempt + 1) + " failed: " + e.getMessage());
                if (attempt == retries - 1) {
                    throw e; // Rethrow on last attempt
                }
            }
        }
    }
}

