public class InterceptorUtil {

    public static boolean isBusinessMethod(Method method) {
        return method.isAnnotationPresent(Interceptor.class) || method.getModifiers() == (method.getModifiers() | java.lang.reflect.Modifier.PUBLIC);
    }

    public static Class<? extends Annotation> getInterceptorAnnotation(Class<?> interceptionType) {
        if (interceptionType.equals(BusinessInterceptor.class)) {
            return BusinessInterceptor.class;
        } else if (interceptionType.equals(LifecycleInterceptor.class)) {
            return LifecycleInterceptor.class;
        }
        return null;
    }

    public static boolean isBusinessMethodInterceptor(Method method) {
        return method.isAnnotationPresent(BusinessInterceptor.class);
    }

    public static boolean isLifecycleMethodInterceptor(Method method) {
        return method.isAnnotationPresent(LifecycleInterceptor.class);
    }

    public static void validateInterceptorConditions(Class<?> clazz) {
        if (!clazz.isAnnotationPresent(Interceptor.class)) {
            throw new IllegalArgumentException("Class must be annotated with @Interceptor");
        }
    }

    public static List<Interceptor> filterInterceptors(List<Interceptor> interceptors) {
        List<Interceptor> filtered = new ArrayList<>();
        for (Interceptor interceptor : interceptors) {
            if (!filtered.contains(interceptor)) {
                filtered.add(interceptor);
            }
        }
        return filtered;
    }

    public static Object aroundInvoke(Method method, Object target, Object[] args) throws Exception {
        return method.invoke(target, args);
    }

    public static boolean checkInterceptorHierarchy(Class<?> interceptorClass, Class<?> candidateClass) {
        return interceptorClass.isAssignableFrom(candidateClass);
    }
}

