public class MergerOptions {
    private JFrame frame;
    private JButton generateButton;
    private JButton saveButton;
    private JTextArea sqlOutputArea;
    private DatabaseAdapter databaseAdapter;
    private List<String> migrationTokens;

    public MergerOptions() {
        initializeView();
        bindActions();
        databaseAdapter = new DatabaseAdapter();
        migrationTokens = databaseAdapter.loadMigrationTokens();
    }

    private void initializeView() {
        frame = new JFrame("Database Migration Options");
        generateButton = new JButton("Generate SQL");
        saveButton = new JButton("Save SQL");
        sqlOutputArea = new JTextArea(20, 50);

        frame.setLayout(new BoxLayout(frame.getContentPane(), BoxLayout.Y_AXIS));
        frame.add(generateButton);
        frame.add(saveButton);
        frame.add(new JScrollPane(sqlOutputArea));
        frame.pack();
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setVisible(true);
    }

    private void bindActions() {
        generateButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                generateSQL();
            }
        });

        saveButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                saveSQL();
            }
        });
    }

    private void generateSQL() {
        StringBuilder sqlBuilder = new StringBuilder();
        for (String token : migrationTokens) {
            sqlBuilder.append("ALTER TABLE ").append(token).append(";\n");
        }
        sqlOutputArea.setText(sqlBuilder.toString());
    }

    private void saveSQL() {
        String sql = sqlOutputArea.getText();
        if (sql.isEmpty()) {
            JOptionPane.showMessageDialog(frame, "No SQL to save!", "Error", JOptionPane.ERROR_MESSAGE);
            return;
        }
        // Code to save SQL to a file (omitted for brevity)
        JOptionPane.showMessageDialog(frame, "SQL saved successfully!", "Success", JOptionPane.INFORMATION_MESSAGE);
    }

    public void close() {
        frame.dispose();
    }
}

