class JmsStreamMessageTest {

    private JmsStreamMessage message;

    @BeforeEach
    void setUp() throws JMSException {
        message = new JmsStreamMessage();
    }

    @Test
    void testToString() {
        assertNotNull(message.toString());
    }

    @Test
    void testReadFromEmptyStream() {
        assertThrows(MessageEOFException.class, () -> {
            message.readBoolean();
        });
    }

    @Test
    void testClearBody() throws JMSException {
        message.writeInt(42);
        message.clearBody();
        assertThrows(MessageNotReadableException.class, () -> {
            message.readInt();
        });
    }

    @Test
    void testNewMessageIsWriteOnly() {
        assertThrows(MessageNotReadableException.class, () -> {
            message.readBoolean();
        });
    }

    @Test
    void testIllegalTypeConversions() throws JMSException {
        message.writeInt(10);
        int initialPosition = message.getStreamPosition();
        assertThrows(MessageNotReadableException.class, () -> {
            message.readDouble();
        });
        assertEquals(initialPosition, message.getStreamPosition());
    }

    @Test
    void testWriteReadVariousDataTypes() throws JMSException {
        message.writeBoolean(true);
        assertTrue(message.readBoolean());

        message.writeByte((byte) 1);
        assertEquals(1, message.readByte());

        message.writeShort((short) 2);
        assertEquals(2, message.readShort());

        message.writeInt(3);
        assertEquals(3, message.readInt());

        message.writeLong(4L);
        assertEquals(4L, message.readLong());

        message.writeFloat(5.0f);
        assertEquals(5.0f, message.readFloat());

        message.writeDouble(6.0);
        assertEquals(6.0, message.readDouble());

        message.writeString("Hello");
        assertEquals("Hello", message.readString());
    }

    @Test
    void testReadBytes() throws JMSException {
        byte[] bytes = {1, 2, 3};
        message.writeBytes(bytes);
        byte[] readBytes = new byte[3];
        message.readBytes(readBytes);
        assertArrayEquals(bytes, readBytes);
    }

    @Test
    void testClearBodyAndReset() throws JMSException {
        message.writeInt(10);
        message.clearBody();
        assertThrows(MessageNotReadableException.class, () -> {
            message.readInt();
        });
        message.reset();
        assertThrows(MessageNotReadableException.class, () -> {
            message.readInt();
        });
    }

    @Test
    void testWriteReadObject() throws JMSException {
        message.writeObject("Test Object");
        assertEquals("Test Object", message.readObject());

        message.writeObject(null);
        assertNull(message.readObject());
    }

    @Test
    void testWriteReadObjectTypeMismatch() throws JMSException {
        message.writeObject("String");
        assertThrows(ClassCastException.class, () -> {
            Integer obj = (Integer) message.readObject();
        });
    }
}

public abstract class AbstractFieldMatrix<T extends FieldElement<T>> {

    protected final int rows;
    protected final int columns;

    protected AbstractFieldMatrix(int rows, int columns) {
        this.rows = rows;
        this.columns = columns;
    }

    public abstract T getEntry(int row, int column);

    public abstract void setEntry(int row, int column, T value);

    public int getRowDimension() {
        return rows;
    }

    public int getColumnDimension() {
        return columns;
    }

    public AbstractFieldMatrix<T> add(AbstractFieldMatrix<T> matrix) {
        checkDimensions(matrix);
        AbstractFieldMatrix<T> result = createMatrix(rows, columns);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                result.setEntry(i, j, getEntry(i, j).add(matrix.getEntry(i, j)));
            }
        }
        return result;
    }

    public AbstractFieldMatrix<T> subtract(AbstractFieldMatrix<T> matrix) {
        checkDimensions(matrix);
        AbstractFieldMatrix<T> result = createMatrix(rows, columns);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                result.setEntry(i, j, getEntry(i, j).subtract(matrix.getEntry(i, j)));
            }
        }
        return result;
    }

    public AbstractFieldMatrix<T> scalarMultiply(T scalar) {
        AbstractFieldMatrix<T> result = createMatrix(rows, columns);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                result.setEntry(i, j, getEntry(i, j).multiply(scalar));
            }
        }
        return result;
    }

    public AbstractFieldMatrix<T> multiply(AbstractFieldMatrix<T> matrix) {
        if (columns != matrix.getRowDimension()) {
            throw new IllegalArgumentException("Matrix dimensions do not match for multiplication.");
        }
        AbstractFieldMatrix<T> result = createMatrix(rows, matrix.getColumnDimension());
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < matrix.getColumnDimension(); j++) {
                T sum = getEntry(i, 0).getField().getZero();
                for (int k = 0; k < columns; k++) {
                    sum = sum.add(getEntry(i, k).multiply(matrix.getEntry(k, j)));
                }
                result.setEntry(i, j, sum);
            }
        }
        return result;
    }

    public AbstractFieldMatrix<T> power(int exponent) {
        if (rows != columns) {
            throw new IllegalArgumentException("Matrix must be square for power operation.");
        }
        AbstractFieldMatrix<T> result = createIdentityMatrix(rows);
        AbstractFieldMatrix<T> base = this;
        while (exponent > 0) {
            if (exponent % 2 == 1) {
                result = result.multiply(base);
            }
            base = base.multiply(base);
            exponent /= 2;
        }
        return result;
    }

    public AbstractFieldMatrix<T> transpose() {
        AbstractFieldMatrix<T> result = createMatrix(columns, rows);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                result.setEntry(j, i, getEntry(i, j));
            }
        }
        return result;
    }

    protected void checkDimensions(AbstractFieldMatrix<T> matrix) {
        if (rows != matrix.getRowDimension() || columns != matrix.getColumnDimension()) {
            throw new IllegalArgumentException("Matrix dimensions do not match.");
        }
    }

    protected abstract AbstractFieldMatrix<T> createMatrix(int rows, int columns);

    protected abstract AbstractFieldMatrix<T> createIdentityMatrix(int size);

    public T[] getRow(int row) {
        validateRowIndex(row);
        T[] rowArray = (T[]) new FieldElement[columns];
        for (int j = 0; j < columns; j++) {
            rowArray[j] = getEntry(row, j);
        }
        return rowArray;
    }

    public T[] getColumn(int column) {
        validateColumnIndex(column);
        T[] columnArray = (T[]) new FieldElement[rows];
        for (int i = 0; i < rows; i++) {
            columnArray[i] = getEntry(i, column);
        }
        return columnArray;
    }

    private void validateRowIndex(int row) {
        if (row < 0 || row >= rows) {
            throw new IndexOutOfBoundsException("Row index out of bounds.");
        }
    }

    private void validateColumnIndex(int column) {
        if (column < 0 || column >= columns) {
            throw new IndexOutOfBoundsException("Column index out of bounds.");
        }
    }
}

interface FieldElement<T> {
    T add(T other);
