public abstract class SnowballProgram {
    protected StringBuilder current;
    protected int cursor;

    public SnowballProgram() {
        this.current = new StringBuilder();
        this.cursor = 0;
    }

    public void setCurrent(String value) {
        this.current.setLength(0);
        this.current.append(value);
        this.cursor = 0;
    }

    public String getCurrent() {
        return current.toString();
    }

    public boolean inGroup(char ch, String group) {
        return group.indexOf(ch) >= 0;
    }

    public boolean inGroup(char ch, String group1, String group2) {
        return inGroup(ch, group1) || inGroup(ch, group2);
    }

    public boolean inGroup(char ch, String group1, String group2, String group3) {
        return inGroup(ch, group1) || inGroup(ch, group2) || inGroup(ch, group3);
    }

    public boolean equals(String str, int start, int length) {
        return current.substring(start, start + length).equals(str);
    }

    public void slice(int start, int end) {
        current.delete(start, end);
        cursor = Math.min(cursor, current.length());
    }

    public void insert(int position, String str) {
        current.insert(position, str);
        cursor = position + str.length();
    }

    public void setCursor(int position) {
        if (position >= 0 && position <= current.length()) {
            cursor = position;
        }
    }

    public int getCursor() {
        return cursor;
    }

    public void moveCursorForward() {
        if (cursor < current.length()) {
            cursor++;
        }
    }

    public void moveCursorBackward() {
        if (cursor > 0) {
            cursor--;
        }
    }

    public int getLength() {
        return current.length();
    }

    public abstract void stem();
}

