class IterableUtilsTest {

    private List<String> testList;

    @BeforeEach
    public void setUp() {
        testList = Arrays.asList("a", "b", "c", "d");
    }

    @Test
    public void testForEach() {
        StringBuilder result = new StringBuilder();
        IterableUtils.forEach(testList, result::append);
        assertEquals("abcd", result.toString());
    }

    @Test
    public void testForEachButLast() {
        StringBuilder result = new StringBuilder();
        IterableUtils.forEachButLast(testList, result::append);
        assertEquals("abc", result.toString());
    }

    @Test
    public void testContainsWithEquator() {
        assertTrue(IterableUtils.containsWithEquator(testList, "b", String::equals));
        assertFalse(IterableUtils.containsWithEquator(testList, "e", String::equals));
    }

    @Test
    public void testFrequency() {
        List<String> listWithDuplicates = Arrays.asList("a", "b", "a", "c", "a");
        assertEquals(3, IterableUtils.frequency(listWithDuplicates, "a"));
        assertEquals(0, IterableUtils.frequency(listWithDuplicates, "d"));
    }

    @Test
    public void testFind() {
        String result = IterableUtils.find(testList, s -> s.equals("c"));
        assertEquals("c", result);
        assertNull(IterableUtils.find(testList, s -> s.equals("e")));
    }

    @Test
    public void testIndexOf() {
        int index = IterableUtils.indexOf(testList, s -> s.equals("b"));
        assertEquals(1, index);
        assertEquals(-1, IterableUtils.indexOf(testList, s -> s.equals("e")));
    }

    @Test
    public void testCountMatches() {
        long count = IterableUtils.countMatches(testList, s -> s.equals("a"));
        assertEquals(1, count);
    }

    @Test
    public void testMatchesAny() {
        assertTrue(IterableUtils.matchesAny(testList, s -> s.equals("a")));
        assertFalse(IterableUtils.matchesAny(testList, s -> s.equals("e")));
    }

    @Test
    public void testMatchesAll() {
        assertFalse(IterableUtils.matchesAll(testList, s -> s.equals("a")));
        assertTrue(IterableUtils.matchesAll(Arrays.asList("a", "a", "a"), s -> s.equals("a")));
    }

    @Test
    public void testGetFromIterable() {
        assertEquals("b", IterableUtils.getFromIterable(testList, 1));
        assertThrows(IndexOutOfBoundsException.class, () -> IterableUtils.getFromIterable(testList, 4));
    }

    @Test
    public void testFirstFromIterable() {
        assertEquals("a", IterableUtils.firstFromIterable(testList));
    }

    @Test
    public void testPartition() {
        List<List<String>> partitions = IterableUtils.partition(testList, s -> s.compareTo("b") < 0);
        assertEquals(2, partitions.size());
        assertEquals(Arrays.asList("a"), partitions.get(0));
        assertEquals(Arrays.asList("b", "c", "d"), partitions.get(1));
    }

    @Test
    public void testToString() {
        String result = IterableUtils.toString(testList, ", ");
        assertEquals("a, b, c, d", result);
    }
}

