        this.algorithm = algorithm;
        this.provider = provider;
        this.salt = salt;
        this.iterationCount = iterationCount;
        this.keyLength = keyLength;
        this.encoding = encoding;
        validateParameters();
        logSupportedAlgorithms();
    }

    private void validateParameters() {
        if (algorithm == null || provider == null || salt == null || encoding == null) {
            throw new IllegalArgumentException("Invalid encryption parameters");
        }
    }

    private void logSupportedAlgorithms() {
        logger.info("Supported Algorithm: " + algorithm);
        logger.info("Supported Provider: " + provider);
    }

    public String encrypt(String data, String password) {
        try {
            SecretKey key = generateKey(password);
            Cipher cipher = Cipher.getInstance(algorithm);
            cipher.init(Cipher.ENCRYPT_MODE, key);
            byte[] encryptedData = cipher.doFinal(data.getBytes());
            return encode(encryptedData);
        } catch (Exception e) {
            throw new RuntimeException("Encryption failed", e);
        }
    }

    public String decrypt(String encryptedData, String password) {
        try {
            SecretKey key = generateKey(password);
            Cipher cipher = Cipher.getInstance(algorithm);
            cipher.init(Cipher.DECRYPT_MODE, key);
            byte[] decodedData = decode(encryptedData);
            byte[] originalData = cipher.doFinal(decodedData);
            return new String(originalData);
        } catch (Exception e) {
            throw new RuntimeException("Decryption failed", e);
        }
    }

    private SecretKey generateKey(String password) throws Exception {
        PBEKeySpec spec = new PBEKeySpec(password.toCharArray(), salt, iterationCount, keyLength);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        byte[] keyBytes = factory.generateSecret(spec).getEncoded();
        return new SecretKeySpec(keyBytes, algorithm);
    }

    private String encode(byte[] data) {
        if ("BASE64".equalsIgnoreCase(encoding)) {
            return Base64.getEncoder().encodeToString(data);
        } else if ("HEX".equalsIgnoreCase(encoding)) {
            StringBuilder hexString = new StringBuilder();
            for (byte b : data) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        }
        throw new IllegalArgumentException("Unsupported encoding format");
    }

    private byte[] decode(String data) {
        if ("BASE64".equalsIgnoreCase(encoding)) {
            return Base64.getDecoder().decode(data);
        } else if ("HEX".equalsIgnoreCase(encoding)) {
            int len = data.length();
            byte[] result = new byte[len / 2];
            for (int i = 0; i < len; i += 2) {
                result[i / 2] = (byte) ((Character.digit(data.charAt(i), 16) << 4)
                        + Character.digit(data.charAt(i + 1), 16));
            }
            return result;
        }
        throw new IllegalArgumentException("Unsupported encoding format");
    }
}

