public class GenericTypeValidator implements Serializable {
    private static final Logger logger = Logger.getLogger(GenericTypeValidator.class.getName());

    public static Byte validateByte(String input, Locale locale) {
        return parseNumber(input, Byte.class, locale);
    }

    public static Short validateShort(String input, Locale locale) {
        return parseNumber(input, Short.class, locale);
    }

    public static Integer validateInteger(String input, Locale locale) {
        return parseNumber(input, Integer.class, locale);
    }

    public static Long validateLong(String input, Locale locale) {
        return parseNumber(input, Long.class, locale);
    }

    public static Float validateFloat(String input, Locale locale) {
        return parseNumber(input, Float.class, locale);
    }

    public static Double validateDouble(String input, Locale locale) {
        return parseNumber(input, Double.class, locale);
    }

    public static Date validateDate(String input, String dateFormat) {
        SimpleDateFormat sdf = new SimpleDateFormat(dateFormat);
        try {
            return sdf.parse(input);
        } catch (ParseException e) {
            logger.log(Level.WARNING, "Invalid date format: " + input, e);
            return null;
        }
    }

    public static boolean validateCreditCard(String cardNumber) {
        // Simple Luhn algorithm implementation
        int sum = 0;
        boolean alternate = false;
        for (int i = cardNumber.length() - 1; i >= 0; i--) {
            int n = Integer.parseInt(cardNumber.substring(i, i + 1));
            if (alternate) {
                n *= 2;
                if (n > 9) {
                    n = n % 10 + 1;
                }
            }
            sum += n;
            alternate = !alternate;
        }
        return (sum % 10 == 0);
    }

    private static <T extends Number> T parseNumber(String input, Class<T> type, Locale locale) {
        try {
            NumberFormat format = NumberFormat.getInstance(locale);
            Number number = format.parse(input);
            return type.cast(number);
        } catch (ParseException e) {
            logger.log(Level.WARNING, "Invalid number format: " + input, e);
            return null;
        }
    }
}

public class GroupCommunicationMessage {
    private String groupName;
    private String operationName;
    private String messageType;
    private String sourceId;
    private String destinationId;
    private int sourceVersion;
    private int destinationVersion;
    private Object data;

    public GroupCommunicationMessage(String groupName, String operationName, String messageType, 
                                      String sourceId, String destinationId, 
                                      int sourceVersion, int destinationVersion, Object data) {
        this.groupName = groupName;
        this.operationName = operationName;
        this.messageType = messageType;
        this.sourceId = sourceId;
        this.destinationId = destinationId;
        this.sourceVersion = sourceVersion;
        this.destinationVersion = destinationVersion;
        this.data = data;
    }

    public String getGroupName() {
        return groupName;
    }

    public String getOperationName() {
        return operationName;
    }

    public String getMessageType() {
        return messageType;
    }

    public String getSourceId() {
        return sourceId;
    }

    public String getDestinationId() {
        return destinationId;
    }

    public int getSourceVersion() {
        return sourceVersion;
    }

    public int getDestinationVersion() {
        return destinationVersion;
    }

    public Object getData() {
        return data;
    }

    public boolean isSourceVersionGreaterThan(int version) {
        return this.sourceVersion > version;
    }

    public boolean isDestinationVersionGreaterThan(int version) {
        return this.destinationVersion > version;
    }

    public int getDataMessageCount() {
        if (data instanceof Iterable) {
            int count = 0;
            for (Object item : (Iterable<?>) data) {
                count++;
            }
            return count;
        }
        return data != null ? 1 : 0;
    }

    @Override
    public String toString() {
        return "GroupCommunicationMessage{" +
                "groupName='" + groupName + '\'' +
                ", operationName='" + operationName + '\'' +
                ", messageType='" + messageType + '\'' +
                ", sourceId='" + sourceId + '\'' +
                ", destinationId='" + destinationId + '\'' +
                ", sourceVersion=" + sourceVersion +
                ", destinationVersion=" + destinationVersion +
                ", data=" + data +
                '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof GroupCommunicationMessage)) return false;
        GroupCommunicationMessage that = (GroupCommunicationMessage) o;
        return sourceVersion == that.sourceVersion &&
                destinationVersion == that.destinationVersion &&
                Objects.equals(groupName, that.groupName) &&
                Objects.equals(operationName, that.operationName) &&
                Objects.equals(messageType, that.messageType) &&
                Objects.equals(sourceId, that.sourceId) &&
                Objects.equals(destinationId, that.destinationId) &&
                Objects.equals(data, that.data);
    }

    @Override
    public int hashCode() {
        return Objects.hash(groupName, operationName, messageType, sourceId, destinationId, sourceVersion, destinationVersion, data);
    }
}

