public class TrevniKeyPipelineIT {

    private File tempDir;
    private Schema schema;

    @Before
    public void setUp() throws IOException {
        tempDir = createTempDir();
        schema = new Schema.Parser().parse(getClass().getResourceAsStream("/person.avsc"));
    }

    @After
    public void tearDown() {
        deleteTempDir(tempDir);
    }

    @Test
    public void testWriteAndReadTrevni() throws IOException {
        GenericRecord person = createPersonRecord("John", "Doe", 30);
        File avroFile = new File(tempDir, "person.avro");
        writeAvroFile(avroFile, person);

        File trevniFile = new File(tempDir, "person.trevni");
        writeTrevniFile(trevniFile, avroFile);

        GenericRecord retrievedPerson = readTrevniFile(trevniFile);
        assertEquals(person, retrievedPerson);
    }

    @Test
    public void testWriteMultipleRecordsAndRead() throws IOException {
        GenericRecord person1 = createPersonRecord("Jane", "Doe", 25);
        GenericRecord person2 = createPersonRecord("Alice", "Smith", 28);
        File avroFile = new File(tempDir, "people.avro");
        writeAvroFile(avroFile, person1, person2);

        File trevniFile = new File(tempDir, "people.trevni");
        writeTrevniFile(trevniFile, avroFile);

        GenericRecord[] retrievedPeople = readTrevniFile(trevniFile);
        assertEquals(person1, retrievedPeople[0]);
        assertEquals(person2, retrievedPeople[1]);
    }

    private GenericRecord createPersonRecord(String firstName, String lastName, int age) {
        GenericRecord record = new GenericData.Record(schema);
        record.put("firstName", firstName);
        record.put("lastName", lastName);
        record.put("age", age);
        return record;
    }

    private void writeAvroFile(File file, GenericRecord... records) throws IOException {
        DatumWriter<GenericRecord> writer = new SpecificDatumWriter<>(schema);
        try (DataFileWriter<GenericRecord> dataFileWriter = new DataFileWriter<>(writer)) {
            dataFileWriter.create(schema, file);
            for (GenericRecord record : records) {
                dataFileWriter.append(record);
            }
        }
    }

    private void writeTrevniFile(File trevniFile, File avroFile) throws IOException {
        try (TrevniWriter<GenericRecord> writer = TrevniContainer.createWriter(trevniFile, schema)) {
            try (DataFileReader<GenericRecord> dataFileReader = new DataFileReader<>(avroFile, new SpecificDatumReader<>())) {
                while (dataFileReader.hasNext()) {
                    writer.write(dataFileReader.next());
                }
            }
        }
    }

    private GenericRecord readTrevniFile(File trevniFile) throws IOException {
        try (TrevniContainer<GenericRecord> reader = TrevniContainer.openReader(trevniFile)) {
            return reader.read();
        }
    }

    private GenericRecord[] readTrevniFile(File trevniFile) throws IOException {
        // This method is a duplicate and should be refactored to avoid code smells
        try (TrevniContainer<GenericRecord> reader = TrevniContainer.openReader(trevniFile)) {
            return reader.readAll().toArray(new GenericRecord[0]);
        }
    }

    private File createTempDir() {
        // Implementation to create a temporary directory
        return new File(System.getProperty("java.io.tmpdir"), "tempDir");
    }

    private void deleteTempDir(File dir) {
        // Implementation to delete the temporary directory
    }
}

