public class NNTPClient extends NNTP {
    private Socket socket;
    private PrintWriter out;
    private BufferedReader in;

    public NNTPClient(String server, int port) throws IOException {
        socket = new Socket(server, port);
        out = new PrintWriter(socket.getOutputStream(), true);
        in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
    }

    public void authenticate(String username, String password) throws IOException {
        sendCommand("AUTHINFO USER " + username);
        readResponse();
        sendCommand("AUTHINFO PASS " + password);
        readResponse();
    }

    public List<String> listNewsgroups() throws IOException {
        sendCommand("LIST");
        return parseNewsgroupList();
    }

    public void selectNewsgroup(String newsgroup) throws IOException {
        sendCommand("GROUP " + newsgroup);
        readResponse();
    }

    public String retrieveArticle(int articleNumber) throws IOException {
        sendCommand("ARTICLE " + articleNumber);
        return readResponse();
    }

    public String retrieveHeader(int articleNumber) throws IOException {
        sendCommand("HEAD " + articleNumber);
        return readResponse();
    }

    public String retrieveBody(int articleNumber) throws IOException {
        sendCommand("BODY " + articleNumber);
        return readResponse();
    }

    public void postArticle(String article) throws IOException {
        sendCommand("POST");
        out.println(article);
        out.flush();
        readResponse();
    }

    public List<String> newArticles(String newsgroup) throws IOException {
        selectNewsgroup(newsgroup);
        sendCommand("NEWNEWS " + newsgroup + " " + "0");
        return parseNewArticleList();
    }

    private void sendCommand(String command) {
        out.println(command);
        out.flush();
    }

    private String readResponse() throws IOException {
        StringBuilder response = new StringBuilder();
        String line;
        while ((line = in.readLine()) != null) {
            response.append(line).append("\n");
            if (line.startsWith(".")) break; // End of response
        }
        return response.toString();
    }

    private List<String> parseNewsgroupList() throws IOException {
        List<String> newsgroups = new ArrayList<>();
        String response;
        while (!(response = readResponse()).isEmpty()) {
            newsgroups.add(response);
        }
        return newsgroups;
    }

    private List<String> parseNewArticleList() throws IOException {
        List<String> articles = new ArrayList<>();
        String response;
        while (!(response = readResponse()).isEmpty()) {
            articles.add(response);
        }
        return articles;
    }

    public void close() throws IOException {
        sendCommand("QUIT");
        in.close();
        out.close();
        socket.close();
    }

    // Deprecated methods for backward compatibility
    @Deprecated
    public String getArticle(int articleNumber) throws IOException {
        return retrieveArticle(articleNumber);
    }

    @Deprecated
    public String getHeader(int articleNumber) throws IOException {
        return retrieveHeader(articleNumber);
    }

    @Deprecated
    public String getBody(int articleNumber) throws IOException {
        return retrieveBody(articleNumber);
    }
}

