    public void addSubscriber(String subscriberId) {
        subscriberMessages.putIfAbsent(subscriberId, new ArrayList<>());
    }

    @Override
    public void deleteSubscriber(String subscriberId) {
        subscriberMessages.remove(subscriberId);
    }

    @Override
    public void acknowledge(String subscriberId, MessageReference messageReference) {
        List<MessageReference> messages = subscriberMessages.get(subscriberId);
        if (messages != null) {
            messages.remove(messageReference);
            acknowledgmentMessages.add(new Acknowledgment(subscriberId, messageReference));
        }
    }

    @Override
    public List<MessageReference> getMessageReferences(String subscriberId) {
        return subscriberMessages.getOrDefault(subscriberId, new ArrayList<>());
