public class SimpleCookie implements Cookie {
    private static final Logger logger = Logger.getLogger(SimpleCookie.class.getName());

    private String name;
    private String value;
    private String comment;
    private String domain;
    private String path;
    private int maxAge;
    private int version;
    private boolean secure;
    private boolean httpOnly;

    public SimpleCookie(String name, String value) {
        this.name = name;
        this.value = value;
        this.maxAge = -1; // default to session cookie
        this.version = 0; // default version
        logger.info("Cookie created: " + name);
    }

    public void setComment(String comment) {
        this.comment = comment;
        logger.info("Comment set for cookie " + name + ": " + comment);
    }

    public void setDomain(String domain) {
        this.domain = domain;
        logger.info("Domain set for cookie " + name + ": " + domain);
    }

    public void setPath(String path) {
        this.path = path;
        logger.info("Path set for cookie " + name + ": " + path);
    }

    public void setMaxAge(int maxAge) {
        this.maxAge = maxAge;
        logger.info("Max age set for cookie " + name + ": " + maxAge);
    }

    public void setVersion(int version) {
        this.version = version;
        logger.info("Version set for cookie " + name + ": " + version);
    }

    public void setSecure(boolean secure) {
        this.secure = secure;
        logger.info("Secure flag set for cookie " + name + ": " + secure);
    }

    public void setHttpOnly(boolean httpOnly) {
        this.httpOnly = httpOnly;
        logger.info("HttpOnly flag set for cookie " + name + ": " + httpOnly);
    }

    public String getName() {
        return name;
    }

    public String getValue() {
        return value;
    }

    public String getComment() {
        return comment;
    }

    public String getDomain() {
        return domain;
    }

    public String getPath() {
        return path;
    }

    public int getMaxAge() {
        return maxAge;
    }

    public int getVersion() {
        return version;
    }

    public boolean isSecure() {
        return secure;
    }

    public boolean isHttpOnly() {
        return httpOnly;
    }

    public String toHeader() {
        StringBuilder header = new StringBuilder();
        header.append(name).append("=").append(value);
        if (comment != null) header.append("; Comment=").append(comment);
        if (domain != null) header.append("; Domain=").append(domain);
        if (path != null) header.append("; Path=").append(path);
        if (maxAge >= 0) header.append("; Max-Age=").append(maxAge);
        header.append("; Version=").append(version);
        if (secure) header.append("; Secure");
        if (httpOnly) header.append("; HttpOnly");
        logger.info("Cookie header generated: " + header.toString());
        return header.toString();
    }

    public void remove() {
        this.value = "";
        this.maxAge = 0;
        logger.info("Cookie " + name + " removed");
    }

    public static String readCookie(String cookieHeader, String cookieName) {
        Map<String, String> cookies = new HashMap<>();
        String[] cookiePairs = cookieHeader.split("; ");
        for (String pair : cookiePairs) {
            String[] keyValue = pair.split("=");
            if (keyValue.length == 2) {
                cookies.put(keyValue[0], keyValue[1]);
            }
        }
        String value = cookies.get(cookieName);
        logger.info("Cookie read: " + cookieName + " = " + value);
        return value;
    }
}

class ErrorHandlingTest {

    private ProxyConnector proxyConnector;
    private Repository repository;

    @BeforeEach
    void setUp() {
        proxyConnector = Mockito.mock(ProxyConnector.class);
        repository = new Repository(proxyConnector);
    }

    @Test
    void testDownloadArtifactWithStopPolicy() {
        when(proxyConnector.download("artifact-1")).thenThrow(new TransferFailedException("Transfer failed"));

        Exception exception = assertThrows(TransferFailedException.class, () -> {
            repository.downloadArtifact("artifact-1", ErrorPolicy.STOP);
        });

        assertEquals("Transfer failed", exception.getMessage());
    }

    @Test
    void testDownloadArtifactWithQueuePolicy() {
        when(proxyConnector.download("artifact-2")).thenThrow(new ResourceNotFoundException("Resource not found"));

        repository.downloadArtifact("artifact-2", ErrorPolicy.QUEUE);

        verify(proxyConnector, times(1)).download("artifact-2");
        assertTrue(repository.hasPendingDownloads());
    }

    @Test
    void testDownloadArtifactWithIgnorePolicy() {
        when(proxyConnector.download("artifact-3")).thenThrow(new TransferFailedException("Transfer failed"));

        repository.downloadArtifact("artifact-3", ErrorPolicy.IGNORE);

        verify(proxyConnector, times(1)).download("artifact-3");
        assertFalse(repository.hasPendingDownloads());
    }

    @Test
    void testSuccessfulDownload() {
        when(proxyConnector.download("artifact-4")).thenReturn("Download successful");

        String result = repository.downloadArtifact("artifact-4", ErrorPolicy.STOP);

        assertEquals("Download successful", result);
    }

    @Test
    void testMultipleDownloadsWithMixedPolicies() {
        when(proxyConnector.download("artifact-5")).thenThrow(new TransferFailedException("Transfer failed"));
        when(proxyConnector.download("artifact-6")).thenReturn("Download successful");

        repository.downloadArtifact("artifact-5", ErrorPolicy.QUEUE);
        repository.downloadArtifact("artifact-6", ErrorPolicy.STOP);

        assertTrue(repository.hasPendingDownloads());
        assertEquals("Download successful", repository.downloadArtifact("artifact-6", ErrorPolicy.IGNORE));
    }
}

