public class DefaultGraphBuilder implements GraphBuilder {
    private static final Logger logger = LoggerFactory.getLogger(DefaultGraphBuilder.class);
    private ProjectBuilder projectBuilder;

    public DefaultGraphBuilder(ProjectBuilder projectBuilder) {
        this.projectBuilder = projectBuilder;
    }

    @Override
    public Graph buildGraph(MavenSession session) {
        if (session.getProjectDependencyGraph() != null) {
            logger.info("Using existing project dependency graph.");
            return session.getProjectDependencyGraph();
        }

        logger.info("Building new project dependency graph.");
        Graph graph = new Graph();

        for (MavenProject project : session.getProjects()) {
            if (shouldProcessProject(project, session)) {
                try {
                    graph.addProject(project);
                } catch (CyclicDependencyException e) {
                    logger.warn("Cyclic dependency detected for project: " + project.getId());
                    return createErrorGraph("Cyclic dependency detected.");
                } catch (DuplicateProjectException e) {
                    logger.warn("Duplicate project detected: " + project.getId());
                    return createErrorGraph("Duplicate project detected.");
                }
            }
        }

        validatePlugins(graph);
        session.setProjectDependencyGraph(graph);
        return graph;
    }

