public class MmrTester {
    private static final Logger logger = Logger.getLogger(MmrTester.class.getName());
    private DirContext[] ldapContexts;
    private String[] ldapUrls;

    public MmrTester(String[] ldapUrls) {
        this.ldapUrls = ldapUrls;
        this.ldapContexts = new DirContext[ldapUrls.length];
    }

    public void connect() throws NamingException {
        for (int i = 0; i < ldapUrls.length; i++) {
            Hashtable<String, String> env = new Hashtable<>();
            env.put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.ldap.LdapCtxFactory");
            env.put(Context.PROVIDER_URL, ldapUrls[i]);
            env.put(Context.SECURITY_AUTHENTICATION, "simple");
            env.put(Context.SECURITY_PRINCIPAL, "cn=admin,dc=example,dc=com");
            env.put(Context.SECURITY_CREDENTIALS, "password");

            ldapContexts[i] = new InitialDirContext(env);
            logger.log(Level.INFO, "Connected to LDAP server: " + ldapUrls[i]);
        }
    }

    public void addEntry(String dn, Attributes attrs) throws NamingException {
        for (DirContext context : ldapContexts) {
            context.createSubcontext(dn, attrs);
            logger.log(Level.INFO, "Added entry: " + dn);
        }
    }

    public void modifyEntry(String dn, ModificationItem[] mods) throws NamingException {
        for (DirContext context : ldapContexts) {
            context.modifyAttributes(dn, mods);
            logger.log(Level.INFO, "Modified entry: " + dn);
        }
    }

    public void deleteEntry(String dn) throws NamingException {
        for (DirContext context : ldapContexts) {
            context.destroySubcontext(dn);
            logger.log(Level.INFO, "Deleted entry: " + dn);
        }
    }

    public void compareEntries(String dn) throws NamingException {
        for (int i = 0; i < ldapContexts.length; i++) {
            Attributes attrs = ldapContexts[i].getAttributes(dn);
            logger.log(Level.INFO, "Entry from server " + ldapUrls[i] + ": " + attrs);
        }
    }

    public void close() {
        for (DirContext context : ldapContexts) {
            if (context != null) {
                try {
                    context.close();
                } catch (NamingException e) {
                    logger.log(Level.SEVERE, "Failed to close context", e);
                }
            }
        }
    }

    public static void main(String[] args) {
        String[] ldapUrls = {"ldap://localhost:389", "ldap://localhost:390"};
        MmrTester tester = new MmrTester(ldapUrls);

        try {
            tester.connect();

            // Example operations
            Attributes attrs = new BasicAttributes();
            attrs.put("objectClass", "inetOrgPerson");
            attrs.put("cn", "John Doe");
            attrs.put("sn", "Doe");
            tester.addEntry("cn=John Doe,dc=example,dc=com", attrs);

            ModificationItem[] mods = new ModificationItem[1];
            mods[0] = new ModificationItem(DirContext.REPLACE_ATTRIBUTE, new BasicAttribute("sn", "Smith"));
            tester.modifyEntry("cn=John Doe,dc=example,dc=com", mods);

            tester.compareEntries("cn=John Doe,dc=example,dc=com");

            tester.deleteEntry("cn=John Doe,dc=example,dc=com");

        } catch (NamingException e) {
            logger.log(Level.SEVERE, "LDAP operation failed", e);
        } finally {
            tester.close();
        }
    }
}

