public class JDBCTypeConversions {

    private static final Map<Integer, String> SQL_TYPE_MAP = new HashMap<>();

    static {
        SQL_TYPE_MAP.put(Types.CLOB, "CLOB");
        SQL_TYPE_MAP.put(Types.VARCHAR, "VARCHAR");
        SQL_TYPE_MAP.put(Types.INTEGER, "INTEGER");
        // Add more SQL types as needed
    }

    public static Object getValue(ResultSet resultSet, int columnIndex, int sqlType) throws SQLException {
        switch (sqlType) {
            case Types.CLOB:
                return resultSet.getClob(columnIndex);
            case Types.VARCHAR:
                return resultSet.getString(columnIndex);
            case Types.INTEGER:
                return resultSet.getInt(columnIndex);
            // Handle more SQL types as needed
            default:
                return resultSet.getObject(columnIndex);
        }
    }

    public static void setValue(PreparedStatement preparedStatement, int parameterIndex, Object value, int sqlType) throws SQLException {
        switch (sqlType) {
            case Types.CLOB:
                preparedStatement.setClob(parameterIndex, (java.sql.Clob) value);
                break;
            case Types.VARCHAR:
                preparedStatement.setString(parameterIndex, (String) value);
                break;
            case Types.INTEGER:
                preparedStatement.setInt(parameterIndex, (Integer) value);
                break;
            // Handle more SQL types as needed
            default:
                preparedStatement.setObject(parameterIndex, value);
                break;
        }
    }

    public static String getSQLTypeName(int sqlType) {
        return SQL_TYPE_MAP.getOrDefault(sqlType, "UNKNOWN");
    }
}

