public class RestClient {
    private String host;
    private int port;
    private String username;
    private String password;
    private boolean cacheEnabled;

    public RestClient(String host, int port, String username, String password) {
        this.host = host;
        this.port = port;
        this.username = username;
        this.password = password;
        this.cacheEnabled = false;
    }

    private String buildUri(String endpoint) {
        return String.format("http://%s:%d/%s", host, port, endpoint);
    }

    private HttpURLConnection createConnection(String endpoint, String method) throws IOException {
        URL url = new URL(buildUri(endpoint));
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod(method);
        connection.setRequestProperty("Authorization", "Basic " + Base64.getEncoder().encodeToString((username + ":" + password).getBytes(StandardCharsets.UTF_8)));
        connection.setConnectTimeout(5000);
        connection.setReadTimeout(5000);
        return connection;
    }

    public String get(String endpoint) throws IOException {
        HttpURLConnection connection = createConnection(endpoint, "GET");
        return handleResponse(connection);
    }

    public String post(String endpoint, String body) throws IOException {
        HttpURLConnection connection = createConnection(endpoint, "POST");
        connection.setDoOutput(true);
        try (OutputStream os = connection.getOutputStream()) {
            os.write(body.getBytes(StandardCharsets.UTF_8));
        }
        return handleResponse(connection);
    }

    public String put(String endpoint, String body) throws IOException {
        HttpURLConnection connection = createConnection(endpoint, "PUT");
        connection.setDoOutput(true);
        try (OutputStream os = connection.getOutputStream()) {
            os.write(body.getBytes(StandardCharsets.UTF_8));
        }
        return handleResponse(connection);
    }

    public void enableCache() {
        cacheEnabled = true;
    }

    public void disableCache() {
        cacheEnabled = false;
    }

    public void wipeCache(String entity) throws IOException {
        post("cache/wipe/" + entity, "");
    }

    public String buildCube(String cubeName) throws IOException {
        return post("cubes/" + cubeName + "/build", "");
    }

    public String enableCube(String cubeName) throws IOException {
        return put("cubes/" + cubeName + "/enable", "");
    }

    public String disableCube(String cubeName) throws IOException {
        return put("cubes/" + cubeName + "/disable", "");
    }

    public String purgeCube(String cubeName) throws IOException {
        return post("cubes/" + cubeName + "/purge", "");
    }

    public String query(String sql) throws IOException {
        return post("query", sql);
    }

    public String getKylinProperties() throws IOException {
        return get("properties");
    }

    private String handleResponse(HttpURLConnection connection) throws IOException {
        int responseCode = connection.getResponseCode();
        StringBuilder response = new StringBuilder();
        try (BufferedReader in = new BufferedReader(new InputStreamReader(responseCode >= 200 && responseCode < 300 ? connection.getInputStream() : connection.getErrorStream()))) {
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                response.append(inputLine);
            }
        }
        connection.disconnect();
        return response.toString();
    }
}

