public class DbImportTree extends JTree {
    private ReverseEngineering reverseEngineering;

    public DbImportTree(ReverseEngineering reverseEngineering) {
        this.reverseEngineering = reverseEngineering;
        populateTree();
    }

    private void populateTree() {
        DefaultMutableTreeNode root = new DefaultMutableTreeNode("Database");
        for (Catalog catalog : reverseEngineering.getCatalogs()) {
            DefaultMutableTreeNode catalogNode = new DefaultMutableTreeNode(catalog.getName());
            for (Schema schema : catalog.getSchemas()) {
                DefaultMutableTreeNode schemaNode = new DefaultMutableTreeNode(schema.getName());
                for (Table table : schema.getTables()) {
                    DefaultMutableTreeNode tableNode = new DefaultMutableTreeNode(table.getName());
                    for (Column column : table.getColumns()) {
                        tableNode.add(new DefaultMutableTreeNode(column.getName()));
                    }
                    schemaNode.add(tableNode);
                }
                catalogNode.add(schemaNode);
            }
            root.add(catalogNode);
        }
        setModel(new DefaultTreeModel(root));
    }

    public void updateTree() {
        populateTree();
    }

    public DefaultMutableTreeNode findNode(String nodeName) {
        return findNode((DefaultMutableTreeNode) getModel().getRoot(), nodeName);
    }

    private DefaultMutableTreeNode findNode(DefaultMutableTreeNode node, String nodeName) {
        if (node.getUserObject().equals(nodeName)) {
            return node;
        }
        for (int i = 0; i < node.getChildCount(); i++) {
            DefaultMutableTreeNode childNode = (DefaultMutableTreeNode) node.getChildAt(i);
            DefaultMutableTreeNode result = findNode(childNode, nodeName);
            if (result != null) {
                return result;
            }
        }
        return null;
    }

    public void expandNode(DefaultMutableTreeNode node) {
        TreePath path = new TreePath(node.getPath());
        expandPath(path);
    }

    public void collapseNode(DefaultMutableTreeNode node) {
        TreePath path = new TreePath(node.getPath());
        collapsePath(path);
    }

    public boolean isTransferable() {
        return true; // Placeholder for actual logic
    }
}

