public class PriorityMessageQueueTest {
    private PriorityMessageQueue queue;

    @Before
    public void setUp() {
        queue = new PriorityMessageQueue();
    }

    @Test
    public void testInitialization() {
        assertTrue(queue.isEmpty());
        assertFalse(queue.isClosed());
        assertTrue(queue.isRunning());
    }

    @Test
    public void testEnqueue() {
        queue.enqueue(new Message("Low priority", 1));
        queue.enqueue(new Message("High priority", 10));
        assertEquals("High priority", queue.dequeue().getContent());
    }

    @Test
    public void testDequeueWhenClosed() {
        queue.close();
        assertNull(queue.dequeue());
    }

    @Test
    public void testClear() {
        queue.enqueue(new Message("Message 1", 1));
        queue.enqueue(new Message("Message 2", 2));
        queue.clear();
        assertTrue(queue.isEmpty());
    }

    @Test
    public void testRemoveAll() {
        queue.enqueue(new Message("Message 1", 1));
        queue.enqueue(new Message("Message 2", 2));
        queue.removeAll();
        assertTrue(queue.isEmpty());
    }

    @Test
    public void testPeek() {
        queue.enqueue(new Message("Message 1", 1));
        assertEquals("Message 1", queue.peek().getContent());
        assertFalse(queue.isEmpty());
    }

    @Test
    public void testTimedWait() throws InterruptedException {
        Thread consumer = new Thread(() -> {
            try {
                Thread.sleep(100);
                queue.enqueue(new Message("Delayed Message", 1));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        consumer.start();
        Message message = queue.dequeue(200);
        assertEquals("Delayed Message", message.getContent());
    }

    @Test
    public void testStop() {
        queue.stop();
        assertFalse(queue.isRunning());
        assertNull(queue.dequeue());
    }
}

