public class TestOntTools extends TestCase {
    private OntModel model;
    private OntTools ontTools;

    @Override
    protected void setUp() throws Exception {
        super.setUp();
        model = ModelFactory.createOntologyModel(OntModelSpec.OWL_MEM);
        createOntology();
        ontTools = new OntTools(model);
    }

    private void createOntology() {
        OntClass A = model.createClass("http://example.org/A");
        OntClass B = model.createClass("http://example.org/B");
        OntClass C = model.createClass("http://example.org/C");
        OntClass D = model.createClass("http://example.org/D");
        OntClass E = model.createClass("http://example.org/E");
        OntClass F = model.createClass("http://example.org/F");
        OntClass G = model.createClass("http://example.org/G");
        OntClass topClass = model.createClass("http://example.org/TopClass");

        A.addSuperClass(topClass);
        B.addSuperClass(A);
        C.addSuperClass(A);
        D.addSuperClass(B);
        E.addSuperClass(B);
        F.addSuperClass(C);
        G.addSuperClass(C);
    }

    @Test
    public void testGetLCA_A_B() {
        OntClass lca = ontTools.getLCA(model.getOntClass("http://example.org/A"), model.getOntClass("http://example.org/B"));
        assertEquals(model.getOntClass("http://example.org/A"), lca);
    }

    @Test
    public void testGetLCA_D_E() {
        OntClass lca = ontTools.getLCA(model.getOntClass("http://example.org/D"), model.getOntClass("http://example.org/E"));
        assertEquals(model.getOntClass("http://example.org/B"), lca);
    }

    @Test
    public void testGetLCA_F_G() {
        OntClass lca = ontTools.getLCA(model.getOntClass("http://example.org/F"), model.getOntClass("http://example.org/G"));
        assertEquals(model.getOntClass("http://example.org/C"), lca);
    }

    @Test
    public void testFindShortestPath_A_D() {
        List<OntClass> path = ontTools.findShortestPath(model.getOntClass("http://example.org/A"), model.getOntClass("http://example.org/D"));
        assertEquals(2, path.size());
        assertEquals(model.getOntClass("http://example.org/A"), path.get(0));
        assertEquals(model.getOntClass("http://example.org/B"), path.get(1));
    }

    @Test
    public void testNamedHierarchyRoots() {
        List<OntClass> roots = ontTools.namedHierarchyRoots();
        assertTrue(roots.contains(model.getOntClass("http://example.org/TopClass")));
    }
}

