        T expected = createElement(1.0 * 1.0 + 2.0 * 2.0 + 3.0 * 3.0);
        assertEquals(expected, linearCombination(coefficients, elements), TOLERANCE);
    }

    private T linearCombination(double[] coefficients, T[] elements) {
        T result = getField().getZero();
        for (int i = 0; i < coefficients.length; i++) {
            result = result.add(elements[i].multiply(createElement(coefficients[i])));
        }
        return result;
    }
