public class AppendingStringBuffer implements CharSequence, Serializable {
    private char[] buffer;
    private int length;

    public AppendingStringBuffer() {
        this.buffer = new char[16];
        this.length = 0;
    }

    public AppendingStringBuffer append(String str) {
        return append(str.toCharArray(), 0, str.length());
    }

    public AppendingStringBuffer append(char[] str, int offset, int len) {
        ensureCapacity(length + len);
        System.arraycopy(str, offset, buffer, length, len);
        length += len;
        return this;
    }

    public AppendingStringBuffer append(boolean b) {
        return append(String.valueOf(b));
    }

    public AppendingStringBuffer append(int i) {
        return append(String.valueOf(i));
    }

    public AppendingStringBuffer append(long l) {
        return append(String.valueOf(l));
    }

    public AppendingStringBuffer append(float f) {
        return append(String.valueOf(f));
    }

    public AppendingStringBuffer append(double d) {
        return append(String.valueOf(d));
    }

    public AppendingStringBuffer insert(int index, String str) {
        return insert(index, str.toCharArray(), 0, str.length());
    }

    public AppendingStringBuffer insert(int index, char[] str, int offset, int len) {
        if (index < 0 || index > length) throw new IndexOutOfBoundsException();
        ensureCapacity(length + len);
        System.arraycopy(buffer, index, buffer, index + len, length - index);
        System.arraycopy(str, offset, buffer, index, len);
        length += len;
        return this;
    }

    public AppendingStringBuffer delete(int start, int end) {
        if (start < 0 || end > length || start > end) throw new IndexOutOfBoundsException();
        int numMoved = length - end;
        System.arraycopy(buffer, end, buffer, start, numMoved);
        length -= (end - start);
        return this;
    }

    public AppendingStringBuffer replace(int start, int end, String str) {
        delete(start, end);
        insert(start, str);
        return this;
    }

    public String substring(int start) {
        return substring(start, length);
    }

    public String substring(int start, int end) {
        if (start < 0 || end > length || start > end) throw new IndexOutOfBoundsException();
        return new String(buffer, start, end - start);
    }

    public int indexOf(String str) {
        return indexOf(str, 0);
    }

    public int indexOf(String str, int fromIndex) {
        if (fromIndex < 0) fromIndex = 0;
        for (int i = fromIndex; i <= length - str.length(); i++) {
            if (substring(i, i + str.length()).equals(str)) {
                return i;
            }
        }
        return -1;
    }

    public boolean startsWith(String prefix) {
        return substring(0, prefix.length()).equals(prefix);
    }

    public boolean endsWith(String suffix) {
        return substring(length - suffix.length(), length).equals(suffix);
    }

    public int length() {
        return length;
    }

    public char charAt(int index) {
        if (index < 0 || index >= length) throw new IndexOutOfBoundsException();
        return buffer[index];
    }

    public CharSequence subSequence(int start, int end) {
        return substring(start, end);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof AppendingStringBuffer)) return false;
        AppendingStringBuffer other = (AppendingStringBuffer) obj;
        return this.toString().equals(other.toString());
    }

    @Override
    public int hashCode() {
        return toString().hashCode();
    }

    @Override
    public String toString() {
        return new String(buffer, 0, length);
    }

    private void ensureCapacity(int minimumCapacity) {
        if (minimumCapacity - buffer.length > 0) {
            int newCapacity = Math.max(buffer.length * 2, minimumCapacity);
            char[] newBuffer = new char[newCapacity];
            System.arraycopy(buffer, 0, newBuffer, 0, length);
            buffer = newBuffer;
        }
    }
}

