public class DefaultModelValidator implements ModelValidator {
    private static final String ID_REGEX = "^[a-z0-9_\\-\\.]+$";
    private static final Pattern ID_PATTERN = Pattern.compile(ID_REGEX);

    @Override
    public List<ValidationProblem> validate(Model model) {
        List<ValidationProblem> problems = new ArrayList<>();

        validateRequiredFields(model, problems);
        validateDependencies(model, problems);
        validatePlugins(model, problems);
        validateRepositories(model, problems);
        validateProfiles(model, problems);

        return problems;
    }

    private void validateRequiredFields(Model model, List<ValidationProblem> problems) {
        if (isEmpty(model.getGroupId())) {
            problems.add(new ValidationProblem("groupId is required", Severity.ERROR));
        }
        if (isEmpty(model.getArtifactId())) {
            problems.add(new ValidationProblem("artifactId is required", Severity.ERROR));
        }
        if (isEmpty(model.getVersion())) {
            problems.add(new ValidationProblem("version is required", Severity.ERROR));
        }
        if (isEmpty(model.getPackaging())) {
            problems.add(new ValidationProblem("packaging is required", Severity.ERROR));
        }
    }

    private void validateDependencies(Model model, List<ValidationProblem> problems) {
        // Validate dependencies for uniqueness and illegal characters
        // Code smells: could be extracted to a separate method for clarity
        List<Dependency> dependencies = model.getDependencies();
        for (Dependency dependency : dependencies) {
            if (!isValidId(dependency.getGroupId())) {
                problems.add(new ValidationProblem("Invalid groupId in dependency: " + dependency.getGroupId(), Severity.WARNING));
            }
            if (!isValidId(dependency.getArtifactId())) {
                problems.add(new ValidationProblem("Invalid artifactId in dependency: " + dependency.getArtifactId(), Severity.WARNING));
            }
        }
    }

    private void validatePlugins(Model model, List<ValidationProblem> problems) {
        // Similar validation logic for plugins
        List<Plugin> plugins = model.getPlugins();
        for (Plugin plugin : plugins) {
            if (!isValidId(plugin.getGroupId())) {
                problems.add(new ValidationProblem("Invalid groupId in plugin: " + plugin.getGroupId(), Severity.WARNING));
            }
            if (!isValidId(plugin.getArtifactId())) {
                problems.add(new ValidationProblem("Invalid artifactId in plugin: " + plugin.getArtifactId(), Severity.WARNING));
            }
        }
    }

    private void validateRepositories(Model model, List<ValidationProblem> problems) {
        // Similar validation logic for repositories
        List<Repository> repositories = model.getRepositories();
        for (Repository repository : repositories) {
            if (!isValidId(repository.getId())) {
                problems.add(new ValidationProblem("Invalid repository id: " + repository.getId(), Severity.WARNING));
            }
        }
    }

    private void validateProfiles(Model model, List<ValidationProblem> problems) {
        // Similar validation logic for profiles
        List<Profile> profiles = model.getProfiles();
        for (Profile profile : profiles) {
            if (!isValidId(profile.getId())) {
                problems.add(new ValidationProblem("Invalid profile id: " + profile.getId(), Severity.WARNING));
            }
        }
    }

    private boolean isValidId(String id) {
        return id != null && ID_PATTERN.matcher(id).matches();
    }

    private boolean isEmpty(String str) {
        return str == null || str.trim().isEmpty();
    }
}

