public abstract class AbstractBaseResourceService<T extends XXDBBase, V extends VXDataObject> {

    protected abstract T createEntity();
    protected abstract V mapToView(T entity);
    protected abstract T mapToEntity(V view);
    protected abstract void validate(V view);
    protected abstract void checkPermissions(String operation);
    protected abstract List<T> searchEntities(String criteria, String sortBy);
    protected abstract void handleError(Exception e);
    protected abstract void saveEntity(T entity);
    protected abstract void deleteEntity(T entity);
    protected abstract T findEntityById(Long id);

    public V createResource(V view) {
        checkPermissions("CREATE");
        validate(view);
        T entity = mapToEntity(view);
        saveEntity(entity);
        return mapToView(entity);
    }

    public V readResource(Long id) {
        checkPermissions("READ");
        T entity = findEntityById(id);
        return mapToView(entity);
    }

    public V updateResource(Long id, V view) {
        checkPermissions("UPDATE");
        validate(view);
        T entity = findEntityById(id);
        entity = mapToEntity(view);
        saveEntity(entity);
        return mapToView(entity);
    }

    public void deleteResource(Long id) {
        checkPermissions("DELETE");
        T entity = findEntityById(id);
        deleteEntity(entity);
    }

    public List<V> searchResources(String criteria, String sortBy) {
        List<T> entities = searchEntities(criteria, sortBy);
        return entities.stream().map(this::mapToView).toList();
    }
}

