public class QueryFormat implements QueryNodeVisitor {
    private final NameResolver nameResolver;
    private final List<Exception> exceptions = new ArrayList<>();

    public QueryFormat(NameResolver nameResolver) {
        this.nameResolver = nameResolver;
    }

    public String format(QueryRootNode rootNode) throws InvalidQueryException {
        StringBuilder queryString = new StringBuilder();
        try {
            rootNode.accept(this);
        } catch (Exception e) {
            exceptions.add(e);
        }
        if (!exceptions.isEmpty()) {
            throw new InvalidQueryException("Errors occurred during query formatting", exceptions);
        }
        return queryString.toString();
    }

    @Override
    public void visit(OrQueryNode orNode) {
        // Code smell: Concatenating strings in a loop without using StringBuilder
        String queryPart = "";
        for (QueryNode child : orNode.getChildren()) {
            child.accept(this);
            queryPart += child.toString() + " OR ";
        }
        // Remove trailing " OR "
        if (queryPart.endsWith(" OR ")) {
            queryPart = queryPart.substring(0, queryPart.length() - 4);
        }
        // Code smell: Directly manipulating the query string
        queryString.append("(").append(queryPart).append(")");
    }

    @Override
    public void visit(AndQueryNode andNode) {
        String queryPart = "";
        for (QueryNode child : andNode.getChildren()) {
            child.accept(this);
            queryPart += child.toString() + " AND ";
        }
        if (queryPart.endsWith(" AND ")) {
            queryPart = queryPart.substring(0, queryPart.length() - 5);
        }
        queryString.append("(").append(queryPart).append(")");
    }

    @Override
    public void visit(ExactQueryNode exactNode) {
        String name = nameResolver.resolve(exactNode.getName());
        queryString.append(name);
    }

    // Other visit methods for different QueryNode types can be added here
}

public class UrlValidator implements Serializable {
    private static final long serialVersionUID = 1L;
    private static final String SCHEME_REGEX = "^[a-zA-Z][a-zA-Z\\d+.-]*$";
    private static final String AUTHORITY_REGEX = "^(\\w+\\.)?\\w+\\.\\w+(:\\d+)?$";
    private static final String PATH_REGEX = "(/[^\\s]*)?";
    private static final String QUERY_REGEX = "(\\?[^\\s]*)?";
    private static final String FRAGMENT_REGEX = "(#.*)?";

    private final Set<String> allowedSchemes;
    private final boolean allowAllSchemes;
    private final boolean allowMultipleSlashes;

    public UrlValidator(String[] schemes, boolean allowAllSchemes, boolean allowMultipleSlashes) {
        this.allowedSchemes = new HashSet<>();
        for (String scheme : schemes) {
            allowedSchemes.add(scheme.toLowerCase());
        }
        this.allowAllSchemes = allowAllSchemes;
        this.allowMultipleSlashes = allowMultipleSlashes;
    }

    public boolean isValid(String url) {
        if (url == null) {
            return false;
        }
        String[] components = url.split("://", 2);
        if (components.length != 2) {
            return false;
        }
        String scheme = components[0];
        String authorityPath = components[1];

        if (!isValidScheme(scheme)) {
            return false;
        }

        String[] authorityAndRest = authorityPath.split("/", 2);
        String authority = authorityAndRest[0];
        String path = authorityAndRest.length > 1 ? "/" + authorityAndRest[1] : "";

        if (!isValidAuthority(authority)) {
            return false;
        }

        if (!isValidPath(path)) {
            return false;
        }

        return true;
    }

    private boolean isValidScheme(String scheme) {
        return allowAllSchemes || allowedSchemes.contains(scheme.toLowerCase());
    }

    private boolean isValidAuthority(String authority) {
        return Pattern.matches(AUTHORITY_REGEX, authority);
    }

    private boolean isValidPath(String path) {
        if (!allowMultipleSlashes) {
            return !path.contains("//") && Pattern.matches(PATH_REGEX, path);
        }
        return Pattern.matches(PATH_REGEX, path);
    }
}

