public class MavenRepositoryURL {
    private String url;
    private String id;
    private boolean enableSnapshots;
    private boolean enableReleases;
    private String updatePolicy;
    private String checksumPolicy;
    private boolean multiVersioned;

    public enum FROM {
        FILE,
        URL,
        OTHER
    }

    public MavenRepositoryURL(String specification) {
        parseSpecification(specification);
    }

    private void parseSpecification(String specification) {
        String[] segments = specification.split(";");
        for (String segment : segments) {
            String[] keyValue = segment.split("=");
            if (keyValue.length != 2) {
                logWarning("Malformed segment: " + segment);
                continue;
            }
            String key = keyValue[0].trim();
            String value = keyValue[1].trim();
            switch (key) {
                case "url":
                    this.url = value;
                    break;
                case "id":
                    this.id = value;
                    break;
                case "enableSnapshots":
                    this.enableSnapshots = Boolean.parseBoolean(value);
                    break;
                case "enableReleases":
                    this.enableReleases = Boolean.parseBoolean(value);
                    break;
                case "updatePolicy":
                    this.updatePolicy = value;
                    break;
                case "checksumPolicy":
                    this.checksumPolicy = value;
                    break;
                case "multiVersioned":
                    this.multiVersioned = Boolean.parseBoolean(value);
                    break;
                default:
                    logWarning("Unknown key: " + key);
            }
        }
    }

    private void logWarning(String message) {
        System.err.println("Warning: " + message);
    }

    public String getUrl() {
        return url;
    }

    public void setUrl(String url) {
        this.url = url;
    }

    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public boolean isEnableSnapshots() {
        return enableSnapshots;
    }

    public void setEnableSnapshots(boolean enableSnapshots) {
        this.enableSnapshots = enableSnapshots;
    }

    public boolean isEnableReleases() {
        return enableReleases;
    }

    public void setEnableReleases(boolean enableReleases) {
        this.enableReleases = enableReleases;
    }

    public String getUpdatePolicy() {
        return updatePolicy;
    }

    public void setUpdatePolicy(String updatePolicy) {
        this.updatePolicy = updatePolicy;
    }

    public String getChecksumPolicy() {
        return checksumPolicy;
    }

    public void setChecksumPolicy(String checksumPolicy) {
        this.checksumPolicy = checksumPolicy;
    }

    public boolean isMultiVersioned() {
        return multiVersioned;
    }

    public void setMultiVersioned(boolean multiVersioned) {
        this.multiVersioned = multiVersioned;
    }

    public String toSpecification() {
        StringBuilder sb = new StringBuilder();
        sb.append("url=").append(url).append(";");
        sb.append("id=").append(id).append(";");
        sb.append("enableSnapshots=").append(enableSnapshots).append(";");
        sb.append("enableReleases=").append(enableReleases).append(";");
        sb.append("updatePolicy=").append(updatePolicy).append(";");
        sb.append("checksumPolicy=").append(checksumPolicy).append(";");
        sb.append("multiVersioned=").append(multiVersioned);
        return sb.toString();
    }

    @Override
    public String toString() {
        return "MavenRepositoryURL{" +
                "url='" + url + '\'' +
                ", id='" + id + '\'' +
                ", enableSnapshots=" + enableSnapshots +
                ", enableReleases=" + enableReleases +
                ", updatePolicy='" + updatePolicy + '\'' +
                ", checksumPolicy='" + checksumPolicy + '\'' +
