public class BasicHttpAuthenticationFilter extends AuthenticatingFilter {

    private String authScheme = "Basic";
    private String applicationName;

    @Override
    protected boolean isLoginAttempt(HttpServletRequest request) {
        String authHeader = request.getHeader("Authorization");
        return authHeader != null && authHeader.startsWith(authScheme);
    }

    @Override
    protected void processAuthentication(HttpServletRequest request, HttpServletResponse response) throws IOException, ServletException {
        String authHeader = request.getHeader("Authorization");
        if (authHeader != null) {
            String base64Credentials = authHeader.substring(authScheme.length()).trim();
            String credentials = new String(Base64.getDecoder().decode(base64Credentials));
            String[] values = credentials.split(":", 2);
            String username = values[0];
            String password = values[1];
            // Authenticate user with username and password
            authenticateUser(username, password);
        } else {
            sendChallenge(response);
        }
    }

    private void sendChallenge(HttpServletResponse response) throws IOException {
        response.setHeader("WWW-Authenticate", authScheme + " realm=\"" + applicationName + "\"");
        response.sendError(HttpServletResponse.SC_UNAUTHORIZED, "Unauthorized");
    }

    public void setAuthScheme(String authScheme) {
        this.authScheme = authScheme;
    }

    public String getAuthScheme() {
        return authScheme;
    }

    public void setApplicationName(String applicationName) {
        this.applicationName = applicationName;
    }

    public String getApplicationName() {
        return applicationName;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain) throws ServletException, IOException {
        if (isLoginAttempt(request)) {
            processAuthentication(request, response);
        } else {
            chain.doFilter(request, response);
        }
    }
