public class AMQMessageStore extends AbstractMessageStore {
    private AMQPersistenceAdapter persistenceAdapter;
    private ReferenceStore referenceStore;
    private boolean asyncWriteEnabled;
    private boolean transactionManagementEnabled;
    private boolean recoveryEnabled;

    public AMQMessageStore(AMQPersistenceAdapter adapter, ReferenceStore store) {
        this.persistenceAdapter = adapter;
        this.referenceStore = store;
        this.asyncWriteEnabled = true; // default value
        this.transactionManagementEnabled = true; // default value
        this.recoveryEnabled = true; // default value
    }

    public void addMessage(Message message) {
        if (asyncWriteEnabled) {
            // Asynchronous write logic
            new Thread(() -> {
                persistenceAdapter.writeMessage(message);
                referenceStore.addReference(message.getId());
                log("Message added asynchronously: " + message.getId());
            }).start();
        } else {
            persistenceAdapter.writeMessage(message);
            referenceStore.addReference(message.getId());
            log("Message added: " + message.getId());
        }
    }

    public void removeMessage(String messageId) {
        if (transactionManagementEnabled) {
            // Transaction logic
            beginTransaction();
            try {
                persistenceAdapter.deleteMessage(messageId);
                referenceStore.removeReference(messageId);
                commitTransaction();
                log("Message removed: " + messageId);
            } catch (Exception e) {
                rollbackTransaction();
                log("Failed to remove message: " + messageId);
            }
        } else {
            persistenceAdapter.deleteMessage(messageId);
            referenceStore.removeReference(messageId);
            log("Message removed: " + messageId);
        }
    }

    public void flush() {
        persistenceAdapter.flush();
        log("Data flushed to persistence layer.");
    }

    public void recoverMessages() {
        if (recoveryEnabled) {
            List<Message> messages = persistenceAdapter.readAllMessages();
            for (Message message : messages) {
                referenceStore.addReference(message.getId());
                log("Recovered message: " + message.getId());
            }
        }
    }

    private void beginTransaction() {
        // Transaction begin logic
        log("Transaction started.");
    }

    private void commitTransaction() {
        // Transaction commit logic
        log("Transaction committed.");
    }

    private void rollbackTransaction() {
        // Transaction rollback logic
        log("Transaction rolled back.");
    }

    private void log(String message) {
        System.out.println(message); // Simple logging mechanism
    }
}

public class ActionModel extends BookmarkableModel<ObjectAdapter> implements FormExecutorContext {

    private final ObjectAdapter target;
    private final Action action;
    private final List<ActionArgumentModel> argumentModels;
    private final ServiceInjector serviceInjector;

    public ActionModel(ObjectAdapter target, Action action, ServiceInjector serviceInjector) {
        this.target = target;
        this.action = action;
        this.serviceInjector = serviceInjector;
        this.argumentModels = createArgumentModels();
    }

    private List<ActionArgumentModel> createArgumentModels() {
        List<ActionArgumentModel> models = new ArrayList<>();
        for (ActionArgument argument : action.getArguments()) {
            models.add(new ActionArgumentModel(argument));
        }
        return models;
    }

    @Override
    public boolean isVisible() {
        return action.isVisible(target);
    }

    @Override
    public boolean isUsable() {
        return action.isUsable(target);
    }

    public String getTitle() {
        return action.getTitle();
    }

    public void execute() {
        if (!isUsable()) {
            throw new IllegalStateException("Action is not usable");
        }
        List<Object> args = collectArguments();
        action.execute(target, args);
    }

    private List<Object> collectArguments() {
        List<Object> args = new ArrayList<>();
        for (ActionArgumentModel model : argumentModels) {
            args.add(model.getValue());
        }
        return args;
    }

    public String encodeArguments() {
        StringBuilder encoded = new StringBuilder();
        for (ActionArgumentModel model : argumentModels) {
            encoded.append(model.encode()).append("&");
        }
        return encoded.toString();
    }

    public void decodeArguments(String encoded) {
        String[] pairs = encoded.split("&");
        for (String pair : pairs) {
            String[] keyValue = pair.split("=");
            for (ActionArgumentModel model : argumentModels) {
                if (model.getName().equals(keyValue[0])) {
                    model.decode(keyValue[1]);
                }
            }
        }
    }

    public ActionModel copy() {
        return new ActionModel(target, action, serviceInjector);
    }

    public List<ActionArgumentModel> getArgumentModels() {
        return argumentModels;
    }
}

