        DeadLetterChannel deadLetterChannel = new DeadLetterChannel();
        deadLetterChannel.setRedeliveryPolicy(new CustomRedeliveryPolicy());
        routingFramework.setErrorHandler(deadLetterChannel);
        Route route = routingFramework.createRoute("customRedeliveryRoute");

        assertNotNull(route);
        assertTrue(route.getErrorHandler() instanceof DeadLetterChannel);
        assertTrue(((DeadLetterChannel) route.getErrorHandler()).getRedeliveryPolicy() instanceof CustomRedeliveryPolicy);
