public class PathChildrenCache implements Closeable, Watcher {
    private final ZooKeeper zooKeeper;
    private final String path;
    private final Map<String, byte[]> cache = new ConcurrentHashMap<>();
    private boolean cacheData;
    private boolean running;
    private final List<ChildDataListener> listeners;

    public PathChildrenCache(ZooKeeper zooKeeper, String path, boolean cacheData) {
        this.zooKeeper = zooKeeper;
        this.path = path;
        this.cacheData = cacheData;
        this.listeners = new CopyOnWriteArrayList<>();
    }

    public void start() throws KeeperException, InterruptedException {
        if (running) {
            return;
        }
        running = true;
        rebuildCache();
    }

    private void rebuildCache() throws KeeperException, InterruptedException {
        List<String> children = zooKeeper.getChildren(path, this);
        for (String child : children) {
            if (cacheData) {
                byte[] data = zooKeeper.getData(path + "/" + child, false, new Stat());
                cache.put(child, data);
            } else {
                cache.put(child, null);
            }
        }
    }

    public void clearCache() {
        cache.clear();
    }

    public void addListener(ChildDataListener listener) {
        listeners.add(listener);
    }

    public void removeListener(ChildDataListener listener) {
        listeners.remove(listener);
    }

    @Override
    public void process(WatchedEvent event) {
        if (event.getType() == Event.EventType.NodeChildrenChanged && event.getPath().equals(path)) {
            try {
                rebuildCache();
                notifyListeners();
            } catch (KeeperException | InterruptedException e) {
                // Handle exceptions
            }
        }
    }

    private void notifyListeners() {
        for (ChildDataListener listener : listeners) {
            listener.childDataChanged(path, cache);
        }
    }

    @Override
    public void close() throws IOException {
        running = false;
        clearCache();
    }

    public interface ChildDataListener {
        void childDataChanged(String path, Map<String, byte[]> cache);
    }
}

public class ParquetHiveSerDe implements SerDe {
    private List<String> columnNames;
    private List<ObjectInspector> columnOIs;
    private MessageType schema;
    private SimpleGroupFactory groupFactory;

    @Override
    public void initialize(Configuration conf, Properties tbl) throws SerDeException {
        // Initialize column names and types
        this.columnNames = new ArrayList<>();
        this.columnOIs = new ArrayList<>();
        // Assume schema is set from properties
        this.schema = getSchemaFromProperties(tbl);
        this.groupFactory = new SimpleGroupFactory(schema);
        for (Type type : schema.getFields()) {
            columnNames.add(type.getName());
            columnOIs.add(PrimitiveObjectInspectorFactory.getPrimitiveJavaObjectInspector(type.getPrimitiveTypeName()));
        }
    }

    @Override
    public Object deserialize(BytesWritable bytes) throws SerDeException {
        // Deserialize logic
        try {
            ParquetReader<Group> reader = ParquetReader.builder(new ExampleInputFormat(), new Path(bytes.toString())).build();
            Group group = reader.read();
            return group;
        } catch (IOException e) {
            throw new SerDeException(e);
        }
    }

    @Override
    public Class<? extends Writable> getSerializedClass() {
        return BytesWritable.class;
    }

    @Override
    public ObjectInspector getObjectInspector() throws SerDeException {
        return ObjectInspectorFactory.getStandardStructObjectInspector(columnNames, columnOIs);
    }

    @Override
    public Writable serialize(Object obj, ObjectInspector objInspector) throws SerDeException {
        // Serialize logic
        Group group = groupFactory.newGroup();
        // Assume obj is a structured object
        for (int i = 0; i < columnNames.size(); i++) {
            Object field = objInspector.getStructFieldData(obj, objInspector.getAllStructFieldRefs().get(i));
            group.append(columnNames.get(i), field);
        }
        return new BytesWritable(group.toByteArray());
    }

