public class TestAvroSystemConsumer implements SystemConsumer {
    private int numberOfMessages;
    private boolean includeNullForeignKeys;
    private boolean includeSimpleRecords;
    private long sleepDuration;
    private Set<String> simplePartitions;
    private Set<String> profilePartitions;
    private Set<String> companyPartitions;
    private Set<String> pageViewPartitions;
    private Map<String, Integer> currentMessageCount;

    public TestAvroSystemConsumer(int numberOfMessages, boolean includeNullForeignKeys, boolean includeSimpleRecords, long sleepDuration) {
        this.numberOfMessages = numberOfMessages;
        this.includeNullForeignKeys = includeNullForeignKeys;
        this.includeSimpleRecords = includeSimpleRecords;
        this.sleepDuration = sleepDuration;
        this.simplePartitions = new HashSet<>();
        this.profilePartitions = new HashSet<>();
        this.companyPartitions = new HashSet<>();
        this.pageViewPartitions = new HashSet<>();
        this.currentMessageCount = new HashMap<>();
    }

    public Map<String, Object> poll() {
        Map<String, Object> messageEnvelopes = new HashMap<>();
        for (String partition : simplePartitions) {
            messageEnvelopes.put(partition, createSimpleRecord(partition));
        }
        for (String partition : profilePartitions) {
            messageEnvelopes.put(partition, createProfileRecord(partition));
        }
        for (String partition : companyPartitions) {
            messageEnvelopes.put(partition, createCompanyRecord(partition));
        }
        for (String partition : pageViewPartitions) {
            messageEnvelopes.put(partition, createPageViewRecord(partition));
        }
        try {
            Thread.sleep(sleepDuration);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return messageEnvelopes;
    }

    private Object createSimpleRecord(String partition) {
        if (includeSimpleRecords) {
            return new SimpleRecord("simple-" + currentMessageCount.getOrDefault(partition, 0));
        }
        return null;
    }

    private Object createProfileRecord(String partition) {
        return new ProfileRecord("profile-" + currentMessageCount.getOrDefault(partition, 0));
    }

    private Object createCompanyRecord(String partition) {
        return new CompanyRecord("company-" + currentMessageCount.getOrDefault(partition, 0));
    }

    private Object createPageViewRecord(String partition) {
        return new PageViewRecord("pageview-" + currentMessageCount.getOrDefault(partition, 0));
    }

    // Additional methods to manage partitions and message counts
    public void addSimplePartition(String partition) {
        simplePartitions.add(partition);
        currentMessageCount.put(partition, 0);
    }

    public void addProfilePartition(String partition) {
        profilePartitions.add(partition);
        currentMessageCount.put(partition, 0);
    }

    public void addCompanyPartition(String partition) {
        companyPartitions.add(partition);
        currentMessageCount.put(partition, 0);
    }

    public void addPageViewPartition(String partition) {
        pageViewPartitions.add(partition);
        currentMessageCount.put(partition, 0);
    }

    public void incrementMessageCount(String partition) {
        currentMessageCount.put(partition, currentMessageCount.getOrDefault(partition, 0) + 1);
    }
}

