public abstract class NodeValue {
    public static final NodeValue TRUE = new NodeValueBoolean(true);
    public static final NodeValue FALSE = new NodeValueBoolean(false);
    public static final NodeValue ZERO = new NodeValueInteger(0);

    public static NodeValue createInteger(int value) {
        return new NodeValueInteger(value);
    }

    public static NodeValue createFloat(float value) {
        return new NodeValueFloat(value);
    }

    public static NodeValue createString(String value) {
        return new NodeValueString(value);
    }

    public static NodeValue createDate(Date value) {
        return new NodeValueDate(value);
    }

    public static NodeValue createBoolean(boolean value) {
        return value ? TRUE : FALSE;
    }

    public abstract boolean isTrue();
    public abstract boolean isFalse();
    public abstract int compareTo(NodeValue other);
    public abstract String getType();
    public abstract String getLanguageTag();

    // Parsing logic
    public static NodeValue parse(String str) {
        // Code smell: could be improved with better error handling
        if (str.equalsIgnoreCase("true")) return TRUE;
        if (str.equalsIgnoreCase("false")) return FALSE;
        try {
            return createInteger(Integer.parseInt(str));
        } catch (NumberFormatException e) {
            // Ignored for simplicity, could lead to silent failures
        }
        try {
            return createFloat(Float.parseFloat(str));
        } catch (NumberFormatException e) {
            // Ignored for simplicity, could lead to silent failures
        }
        return createString(str);
    }
}

