public class StandardTokenizerImpl {
    private String input;
    private int currentIndex;
    private List<String> tokens;
    private StringBuilder buffer;

    public StandardTokenizerImpl(String input) {
        this.input = input;
        this.currentIndex = 0;
        this.tokens = new ArrayList<>();
        this.buffer = new StringBuilder();
    }

    public void reset() {
        currentIndex = 0;
        tokens.clear();
        buffer.setLength(0);
    }

    public String nextToken() {
        while (currentIndex < input.length()) {
            char currentChar = input.charAt(currentIndex);
            if (Character.isWhitespace(currentChar)) {
                if (buffer.length() > 0) {
                    String token = buffer.toString();
                    buffer.setLength(0);
                    return token;
                }
            } else {
                buffer.append(currentChar);
            }
            currentIndex++;
        }
        if (buffer.length() > 0) {
            return buffer.toString();
        }
        return null;
    }

    public void pushBack() {
        if (currentIndex > 0) {
            currentIndex--;
            if (buffer.length() > 0) {
                buffer.setLength(buffer.length() - 1);
            }
        }
    }

    public List<String> getTokens() {
        return tokens;
    }

    public void processInput() {
        String token;
        while ((token = nextToken()) != null) {
            tokens.add(token);
        }
    }

    public static void main(String[] args) {
        StandardTokenizerImpl tokenizer = new StandardTokenizerImpl("This is a test input.");
        tokenizer.processInput();
        for (String token : tokenizer.getTokens()) {
            System.out.println(token);
        }
    }
}

