public class TestCSVRecordReader {

    private final CSVRecordReader csvRecordReader = Mockito.mock(CSVRecordReader.class);

    @Test
    public void testParseSimpleCSV() throws IOException {
        String csvData = "name,age\nJohn,30\nJane,25";
        List<Record> records = csvRecordReader.parse(csvData);
        assertEquals(2, records.size());
        assertEquals("John", records.get(0).getName());
        assertEquals(30, records.get(0).getAge());
    }

    @Test
    public void testParseCSVWithSpecialCharacters() throws IOException {
        String csvData = "name,age\nO'Reilly,40\nSmith,35";
        List<Record> records = csvRecordReader.parse(csvData);
        assertEquals("O'Reilly", records.get(0).getName());
    }

    @Test
    public void testParseCSVWithDateField() throws IOException {
        String csvData = "name,birthdate\nJohn,1990-01-01\nJane,1995-05-05";
        List<Record> records = csvRecordReader.parse(csvData);
        assertEquals("1990-01-01", records.get(0).getBirthdate());
    }

    @Test
    public void testHandleMissingFields() throws IOException {
        String csvData = "name,age\nJohn,\n,25";
        List<Record> records = csvRecordReader.parse(csvData);
        assertEquals(2, records.size());
        assertEquals("John", records.get(0).getName());
        assertEquals(null, records.get(0).getAge());
    }

    @Test
    public void testHandleExtraWhitespace() throws IOException {
        String csvData = "name, age\n John , 30 \n Jane , 25 ";
        List<Record> records = csvRecordReader.parse(csvData);
        assertEquals("John", records.get(0).getName().trim());
        assertEquals(30, records.get(0).getAge());
    }

    @Test
    public void testHandleDifferentFieldNames() throws IOException {
        String csvData = "full_name,years\nJohn Doe,30\nJane Doe,25";
        List<Record> records = csvRecordReader.parse(csvData);
        assertEquals("John Doe", records.get(0).getFullName());
        assertEquals(30, records.get(0).getYears());
    }

    @Test
    public void testParseEmptyCSV() throws IOException {
        String csvData = "";
        List<Record> records = csvRecordReader.parse(csvData);
        assertEquals(0, records.size());
    }

    @Test
    public void testParseCSVWithInvalidData() {
        String csvData = "name,age\nJohn,thirty";
        assertThrows(IOException.class, () -> {
            csvRecordReader.parse(csvData);
        });
    }
}

public class UnsafeFixLengthColumnPage extends ColumnPage {
    private static final Unsafe unsafe = getUnsafe();
    private long baseOffset;
    private int totalLength;
    private int pageSize;

    public UnsafeFixLengthColumnPage(int columnSize, int pageSize) {
        this.pageSize = pageSize;
        this.totalLength = columnSize * getTypeSize();
        this.baseOffset = allocateMemory(totalLength);
    }

    private long allocateMemory(int size) {
        return unsafe.allocateMemory(size);
    }

    public void setByte(int index, byte value) {
        checkIndex(index);
        unsafe.putByte(baseOffset + index, value);
    }

    public byte getByte(int index) {
        checkIndex(index);
        return unsafe.getByte(baseOffset + index);
    }

    public void setShort(int index, short value) {
        checkIndex(index);
        unsafe.putShort(baseOffset + index * 2, value);
    }

    public short getShort(int index) {
        checkIndex(index);
        return unsafe.getShort(baseOffset + index * 2);
    }

    public void setInt(int index, int value) {
        checkIndex(index);
        unsafe.putInt(baseOffset + index * 4, value);
    }

    public int getInt(int index) {
        checkIndex(index);
        return unsafe.getInt(baseOffset + index * 4);
    }

    public void setLong(int index, long value) {
        checkIndex(index);
        unsafe.putLong(baseOffset + index * 8, value);
    }

    public long getLong(int index) {
        checkIndex(index);
        return unsafe.getLong(baseOffset + index * 8);
    }

    public void setFloat(int index, float value) {
        checkIndex(index);
        unsafe.putFloat(baseOffset + index * 4, value);
    }

    public float getFloat(int index) {
        checkIndex(index);
        return unsafe.getFloat(baseOffset + index * 4);
    }

    public void setDouble(int index, double value) {
        checkIndex(index);
        unsafe.putDouble(baseOffset + index * 8, value);
    }

    public double getDouble(int index) {
        checkIndex(index);
        return unsafe.getDouble(baseOffset + index * 8);
    }

    private void checkIndex(int index) {
        if (index < 0 || index >= totalLength) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + totalLength);
        }
    }

    private int getTypeSize() {
        // Assuming a fixed type size for demonstration purposes
        return 8; // Example for long
    }

    @Override
    protected void finalize() throws Throwable {
        unsafe.freeMemory(baseOffset);
        super.finalize();
    }

    private static Unsafe getUnsafe() {
        try {
            java.lang.reflect.Field field = Unsafe.class.getDeclaredField("theUnsafe");
            field.setAccessible(true);
            return (Unsafe) field.get(null);
        } catch (Exception e) {
            throw new RuntimeException("Unable to access Unsafe", e);
        }
    }
}

