    public void testLeaderPathManagement() {
        // Setup two reapers competing for leadership
        Reaper reaper1 = new Reaper(client, "/leaderPath");
        Reaper reaper2 = new Reaper(client, "/leaderPath");

        reaper1.start();
        reaper2.start();

        // Verify only one reaper is active
        assertTrue(reaper1.isActive() ^ reaper2.isActive());

        reaper1.stop();
        reaper2.stop();
    }

    @Test
    public void testLeaderLatchManagement() throws Exception {
        LeaderLatch latch1 = new LeaderLatch(client, "/leaderLatch");
        LeaderLatch latch2 = new LeaderLatch(client, "/leaderLatch");

        latch1.start();
        latch2.start();

        // Verify only one reaper processes paths
        assertTrue(latch1.hasLeadership() ^ latch2.hasLeadership());

        latch1.close();
        latch2.close();
    }

    @Test
    public void testManualLeadership() throws Exception {
        LeaderSelector selector = new LeaderSelector(client, "/manualLeader", new LeaderSelectorListenerAdapter() {
            @Override
            public void takeLeadership(CuratorFramework client) {
                reaper.processPaths();
            }
        });

        selector.start();
        // Verify reaper handles paths correctly
        assertTrue(reaper.isProcessing());

        selector.close();
    }

    @Test
    public void testSparseUseWithoutReaping() {
        reaper.addPath("/path1");
        reaper.removePath("/path1");

        // Ensure no premature reaping
        assertFalse(reaper.hasReaped("/path1"));
    }

    @Test
    public void testReapingUntilDelete() {
        reaper.addPath("/pathToReap");
        reaper.reapUntilDeleted("/pathToReap");

        // Verify path is removed
        assertFalse(reaper.pathExists("/pathToReap"));
    }

    @Test
    public void testReapingUntilGone() {
        reaper.addPath("/pathToReap");
        reaper.reapUntilGone("/pathToReap");

        // Verify path is completely gone
        assertFalse(reaper.pathExists("/pathToReap"));
    }

    @Test
    public void testPathRemoval() {
        reaper.addPath("/removablePath");
        reaper.removePath("/removablePath");

        // Verify non-existence
        assertFalse(reaper.pathExists("/removablePath"));
    }

