public class ObjectActionReprRenderer extends AbstractObjectMemberReprRenderer {

    private final ObjectAction objectAction;

    public ObjectActionReprRenderer(ObjectAction objectAction) {
        this.objectAction = objectAction;
    }

    public JSONObject render() {
        JSONObject json = new JSONObject();
        json.put("name", objectAction.getName());
        json.put("description", objectAction.getDescription());
        json.put("parameters", renderParameters());
        json.put("mutatorLinks", renderMutatorLinks());
        json.put("metadata", renderMetadata());
        json.put("isStandalone", objectAction.isStandalone());
        return json;
    }

    private JSONArray renderParameters() {
        JSONArray parametersJson = new JSONArray();
        for (Parameter parameter : objectAction.getParameters()) {
            JSONObject paramJson = new JSONObject();
            paramJson.put("name", parameter.getName());
            paramJson.put("type", parameter.getType());
            paramJson.put("defaultValue", parameter.getDefaultValue());
            paramJson.put("choices", parameter.getChoices());
            parametersJson.put(paramJson);
        }
        return parametersJson;
    }

    private JSONArray renderMutatorLinks() {
        JSONArray linksJson = new JSONArray();
        for (String link : objectAction.getMutatorLinks()) {
            linksJson.put(link);
        }
        return linksJson;
    }

    private JSONObject renderMetadata() {
        JSONObject metadataJson = new JSONObject();
        metadataJson.put("createdBy", objectAction.getCreatedBy());
        metadataJson.put("createdDate", objectAction.getCreatedDate());
        metadataJson.put("updatedBy", objectAction.getUpdatedBy());
        metadataJson.put("updatedDate", objectAction.getUpdatedDate());
        return metadataJson;
    }
}

