class MongoMKBranchMergeTest {

    private MongoMK mongoMK;

    @Before
    public void setUp() {
        mongoMK = new MongoMK();
    }

    @Test
    public void testAddNode() {
        String branch = mongoMK.createBranch("testBranch");
        mongoMK.addNode(branch, "node1", "parentNode");
        assertTrue(mongoMK.nodeExists(branch, "node1"));
    }

    @Test
    public void testRemoveNode() {
        String branch = mongoMK.createBranch("testBranch");
        mongoMK.addNode(branch, "node1", "parentNode");
        mongoMK.removeNode(branch, "node1");
        assertFalse(mongoMK.nodeExists(branch, "node1"));
    }

    @Test
    public void testChangeProperty() {
        String branch = mongoMK.createBranch("testBranch");
        mongoMK.addNode(branch, "node1", "parentNode");
        mongoMK.setProperty(branch, "node1", "property1", "value1");
        assertEquals("value1", mongoMK.getProperty(branch, "node1", "property1"));
    }

    @Test
    public void testMergeBranches() {
        String branchA = mongoMK.createBranch("branchA");
        String branchB = mongoMK.createBranch("branchB");
        mongoMK.addNode(branchA, "node1", "parentNode");
        mongoMK.addNode(branchB, "node1", "parentNode");
        mongoMK.setProperty(branchB, "node1", "property1", "valueB");

        mongoMK.merge(branchA, branchB);
        assertEquals("valueB", mongoMK.getProperty(branchA, "node1", "property1"));
    }

    @Test
    public void testConflictResolution() {
        String branchA = mongoMK.createBranch("branchA");
        String branchB = mongoMK.createBranch("branchB");
        mongoMK.addNode(branchA, "node1", "parentNode");
        mongoMK.addNode(branchB, "node1", "parentNode");
        mongoMK.setProperty(branchA, "node1", "property1", "valueA");
        mongoMK.setProperty(branchB, "node1", "property1", "valueB");

        mongoMK.merge(branchA, branchB);
        assertNotEquals("valueA", mongoMK.getProperty(branchA, "node1", "property1"));
        assertNotEquals("valueB", mongoMK.getProperty(branchA, "node1", "property1"));
    }

    @Test
    public void testIntegrityAfterMerge() {
        String branchA = mongoMK.createBranch("branchA");
        String branchB = mongoMK.createBranch("branchB");
        mongoMK.addNode(branchA, "node1", "parentNode");
        mongoMK.addNode(branchB, "node2", "parentNode");

        mongoMK.merge(branchA, branchB);
        assertTrue(mongoMK.nodeExists(branchA, "node1"));
        assertTrue(mongoMK.nodeExists(branchA, "node2"));
    }
}

