class DiagonalMatrixTest {

    @Test
    void testConstructorWithValidDiagonal() {
        double[] diagonal = {1.0, 2.0, 3.0};
        DiagonalMatrix matrix = new DiagonalMatrix(diagonal);
        assertArrayEquals(diagonal, matrix.getDiagonalEntries());
    }

    @Test
    void testConstructorWithInvalidDiagonal() {
        assertThrows(IllegalArgumentException.class, () -> {
            new DiagonalMatrix(new double[]{});
        });
    }

    @Test
    void testAddition() {
        DiagonalMatrix matrix1 = new DiagonalMatrix(new double[]{1.0, 2.0, 3.0});
        DiagonalMatrix matrix2 = new DiagonalMatrix(new double[]{4.0, 5.0, 6.0});
        DiagonalMatrix result = matrix1.add(matrix2);
        assertArrayEquals(new double[]{5.0, 7.0, 9.0}, result.getDiagonalEntries());
    }

    @Test
    void testSubtraction() {
        DiagonalMatrix matrix1 = new DiagonalMatrix(new double[]{5.0, 6.0, 7.0});
        DiagonalMatrix matrix2 = new DiagonalMatrix(new double[]{1.0, 2.0, 3.0});
        DiagonalMatrix result = matrix1.subtract(matrix2);
        assertArrayEquals(new double[]{4.0, 4.0, 4.0}, result.getDiagonalEntries());
    }

    @Test
    void testMultiplication() {
        DiagonalMatrix matrix1 = new DiagonalMatrix(new double[]{1.0, 2.0, 3.0});
        DiagonalMatrix matrix2 = new DiagonalMatrix(new double[]{4.0, 5.0, 6.0});
        DiagonalMatrix result = matrix1.multiply(matrix2);
        assertArrayEquals(new double[]{4.0, 10.0, 18.0}, result.getDiagonalEntries());
    }

    @Test
    void testDimensionMismatchAddition() {
        DiagonalMatrix matrix1 = new DiagonalMatrix(new double[]{1.0, 2.0});
        DiagonalMatrix matrix2 = new DiagonalMatrix(new double[]{1.0, 2.0, 3.0});
        assertThrows(IllegalArgumentException.class, () -> {
            matrix1.add(matrix2);
        });
    }

    @Test
    void testDimensionMismatchSubtraction() {
        DiagonalMatrix matrix1 = new DiagonalMatrix(new double[]{1.0, 2.0});
        DiagonalMatrix matrix2 = new DiagonalMatrix(new double[]{1.0, 2.0, 3.0});
        assertThrows(IllegalArgumentException.class, () -> {
            matrix1.subtract(matrix2);
        });
    }

    @Test
    void testDimensionMismatchMultiplication() {
        DiagonalMatrix matrix1 = new DiagonalMatrix(new double[]{1.0, 2.0});
        DiagonalMatrix matrix2 = new DiagonalMatrix(new double[]{1.0, 2.0, 3.0});
        assertThrows(IllegalArgumentException.class, () -> {
            matrix1.multiply(matrix2);
        });
    }

    @Test
    void testSetAndGetEntry() {
        DiagonalMatrix matrix = new DiagonalMatrix(new double[]{1.0, 2.0, 3.0});
        matrix.setEntry(1, 5.0);
        assertEquals(5.0, matrix.getEntry(1));
    }

    @Test
    void testSetNonDiagonalEntry() {
        DiagonalMatrix matrix = new DiagonalMatrix(new double[]{1.0, 2.0, 3.0});
        assertThrows(IllegalArgumentException.class, () -> {
            matrix.setEntry(0, 4.0); // Trying to set a non-diagonal entry
        });
    }

    @Test
    void testInversion() {
        DiagonalMatrix matrix = new DiagonalMatrix(new double[]{1.0, 2.0, 3.0});
        DiagonalMatrix inverse = matrix.invert();
        assertArrayEquals(new double[]{1.0, 0.5, 0.3333333333333333}, inverse.getDiagonalEntries());
    }

    @Test
    void testInversionWithZeroDiagonal() {
        DiagonalMatrix matrix = new DiagonalMatrix(new double[]{1.0, 0.0, 3.0});
        assertThrows(ArithmeticException.class, () -> {
            matrix.invert();
        });
    }
}

