public class FilenameUtils {

    public static String normalize(String path) {
        if (path == null) {
            return null;
        }
        return path.replace("\\", "/");
    }

    public static String concat(String base, String relative) {
        if (base == null || relative == null) {
            return null;
        }
        return normalize(base + "/" + relative);
    }

    public static boolean directoryContainsFile(String directory, String fileName) {
        if (directory == null || fileName == null) {
            return false;
        }
        File dir = new File(directory);
        if (!dir.isDirectory()) {
            return false;
        }
        String[] files = dir.list();
        if (files != null) {
            for (String file : files) {
                if (file.equals(fileName)) {
                    return true;
                }
            }
        }
        return false;
    }

    public static String convertToUnix(String path) {
        if (path == null) {
            return null;
        }
        return path.replace("\\", "/");
    }

    public static String convertToWindows(String path) {
        if (path == null) {
            return null;
        }
        return path.replace("/", "\\");
    }

    public static String getFileName(String path) {
        if (path == null) {
            return null;
        }
        return new File(path).getName();
    }

    public static String getFileExtension(String path) {
        if (path == null) {
            return null;
        }
        String name = getFileName(path);
        int lastDotIndex = name.lastIndexOf('.');
        return (lastDotIndex == -1) ? "" : name.substring(lastDotIndex + 1);
    }

    public static String getBaseName(String path) {
        if (path == null) {
            return null;
        }
        String name = getFileName(path);
        int lastDotIndex = name.lastIndexOf('.');
        return (lastDotIndex == -1) ? name : name.substring(0, lastDotIndex);
    }

    public static boolean compareFileNames(String name1, String name2, boolean caseSensitive) {
        if (name1 == null || name2 == null) {
            return false;
        }
        return caseSensitive ? name1.equals(name2) : name1.equalsIgnoreCase(name2);
    }

    public static boolean matchesWildcard(String fileName, String wildcard) {
        if (fileName == null || wildcard == null) {
            return false;
        }
        String regex = wildcard.replace("?", ".?").replace("*", ".*");
        return fileName.matches(regex);
    }

    public static String sanitizePath(String path) {
        if (path == null) {
            return null;
        }
        if (path.contains("\0")) {
            throw new IllegalArgumentException("Path contains null byte");
        }
        return path;
    }
}

