public class WatermarkHold<T> {
    private Map<Long, T> elementHolds;
    private Map<Long, T> extraHolds;
    private long currentWatermark;

    public WatermarkHold() {
        this.elementHolds = new HashMap<>();
        this.extraHolds = new HashMap<>();
        this.currentWatermark = Long.MIN_VALUE;
    }

    public void addElementHold(long timestamp, T element) {
        if (timestamp > currentWatermark) {
            elementHolds.put(timestamp, element);
        }
    }

    public void addGarbageCollectionHold(long timestamp, T element) {
        if (timestamp > currentWatermark) {
            extraHolds.put(timestamp, element);
        }
    }

    public void mergeStates(WatermarkHold<T> other) {
        for (Map.Entry<Long, T> entry : other.elementHolds.entrySet()) {
            addElementHold(entry.getKey(), entry.getValue());
        }
        for (Map.Entry<Long, T> entry : other.extraHolds.entrySet()) {
            addGarbageCollectionHold(entry.getKey(), entry.getValue());
        }
    }

    public void updateWatermark(long newWatermark) {
        if (newWatermark > currentWatermark) {
            currentWatermark = newWatermark;
            cleanUpHolds();
        }
    }

    private void cleanUpHolds() {
        elementHolds.entrySet().removeIf(entry -> entry.getKey() <= currentWatermark);
        extraHolds.entrySet().removeIf(entry -> entry.getKey() <= currentWatermark);
    }

    public Map<Long, T> extractHolds() {
        return new HashMap<>(elementHolds);
    }

    public void releaseHolds() {
        elementHolds.clear();
        extraHolds.clear();
    }
}

