public class RoomDao {
    @PersistenceContext
    private EntityManager entityManager;

    private static final Logger logger = Logger.getLogger(RoomDao.class.getName());

    @Transactional
    public Room getRoomById(Long id) {
        logger.info("Fetching room with ID: " + id);
        return entityManager.find(Room.class, id);
    }

    @Transactional
    public List<Room> searchRooms(String searchTerm, int offset, int limit) {
        logger.info("Searching rooms with term: " + searchTerm);
        TypedQuery<Room> query = entityManager.createQuery("SELECT r FROM Room r WHERE r.name LIKE :searchTerm", Room.class);
        query.setParameter("searchTerm", "%" + searchTerm + "%");
        query.setFirstResult(offset);
        query.setMaxResults(limit);
        return query.getResultList();
    }

    @Transactional
    public void updateRoom(Room room) {
        logger.info("Updating room: " + room);
        entityManager.merge(room);
    }

    @Transactional
    public void deleteRoom(Long id) {
        logger.info("Deleting room with ID: " + id);
        Room room = getRoomById(id);
        if (room != null) {
            entityManager.remove(room);
        }
    }

    @Transactional
    public List<Room> getRoomsByUserId(Long userId, int offset, int limit) {
        logger.info("Fetching rooms for user ID: " + userId);
        TypedQuery<Room> query = entityManager.createQuery("SELECT r FROM Room r JOIN r.users u WHERE u.id = :userId", Room.class);
        query.setParameter("userId", userId);
        query.setFirstResult(offset);
        query.setMaxResults(limit);
        return query.getResultList();
    }

    @Transactional
    public void manageSipConfiguration(Room room, SipConfiguration sipConfig) {
        logger.info("Managing SIP configuration for room: " + room);
        room.setSipConfiguration(sipConfig);
        updateRoom(room);
    }
}

public abstract class AbstractInactivityMonitor {
    private Timer timer;
    private long inactivityTimeout;
    private long keepAliveInterval;
    private boolean monitoring;

    public AbstractInactivityMonitor(long inactivityTimeout, long keepAliveInterval) {
        this.inactivityTimeout = inactivityTimeout;
        this.keepAliveInterval = keepAliveInterval;
        this.monitoring = false;
    }

    public synchronized void startMonitoring() {
        if (!monitoring) {
            monitoring = true;
            timer = new Timer(true);
            timer.schedule(new InactivityCheckTask(), inactivityTimeout, inactivityTimeout);
            timer.schedule(new KeepAliveTask(), keepAliveInterval, keepAliveInterval);
        }
    }

    public synchronized void stopMonitoring() {
        if (monitoring) {
            monitoring = false;
            timer.cancel();
        }
    }

    protected abstract void onInactivityDetected();

    protected abstract void sendKeepAlive();

    public synchronized void handleIncomingCommand() {
        resetInactivityTimer();
    }

    private void resetInactivityTimer() {
        // Logic to reset inactivity timer
    }

    private class InactivityCheckTask extends TimerTask {
        @Override
        public void run() {
            onInactivityDetected();
        }
    }

    private class KeepAliveTask extends TimerTask {
        @Override
        public void run() {
            sendKeepAlive();
        }
    }
}

