public class UserManagerImpl implements UserManager {
    private UserProvider userProvider;
    private MembershipProvider membershipProvider;
    private SecurityProvider securityProvider;

    public UserManagerImpl(UserProvider userProvider, MembershipProvider membershipProvider, SecurityProvider securityProvider) {
        this.userProvider = userProvider;
        this.membershipProvider = membershipProvider;
        this.securityProvider = securityProvider;
    }

    @Override
    public void createUser(String userId, String password) {
        if (userId == null || password == null) {
            throw new IllegalArgumentException("User ID and password cannot be null");
        }
        if (userProvider.userExists(userId)) {
            throw new UserAlreadyExistsException("User already exists: " + userId);
        }
        userProvider.createUser(userId, password);
    }

    @Override
    public void createGroup(String groupId) {
        if (groupId == null) {
            throw new IllegalArgumentException("Group ID cannot be null");
        }
        if (userProvider.groupExists(groupId)) {
            throw new GroupAlreadyExistsException("Group already exists: " + groupId);
        }
        userProvider.createGroup(groupId);
    }

    @Override
    public Authorizable getUser(String userId) {
        return userProvider.getUser(userId);
    }

    @Override
    public Authorizable getGroup(String groupId) {
        return userProvider.getGroup(groupId);
    }

    @Override
    public void addUserToGroup(String userId, String groupId) {
        if (!userProvider.userExists(userId)) {
            throw new UserNotFoundException("User not found: " + userId);
        }
        if (!userProvider.groupExists(groupId)) {
            throw new GroupNotFoundException("Group not found: " + groupId);
        }
        membershipProvider.addUserToGroup(userId, groupId);
    }

    @Override
    public void removeUserFromGroup(String userId, String groupId) {
        if (!userProvider.userExists(userId)) {
            throw new UserNotFoundException("User not found: " + userId);
        }
        if (!userProvider.groupExists(groupId)) {
            throw new GroupNotFoundException("Group not found: " + groupId);
        }
        membershipProvider.removeUserFromGroup(userId, groupId);
    }

    @Override
    public List<Authorizable> queryUsers(String query) {
        return userProvider.queryUsers(query);
    }

    @Override
    public List<Authorizable> queryGroups(String query) {
        return userProvider.queryGroups(query);
    }

    @Override
    public void validateUser(String userId) {
        if (!userProvider.userExists(userId)) {
            throw new UserNotFoundException("User not found: " + userId);
        }
    }

    @Override
    public void validateGroup(String groupId) {
        if (!userProvider.groupExists(groupId)) {
            throw new GroupNotFoundException("Group not found: " + groupId);
        }
    }

    @Override
    public void changePassword(String userId, String newPassword) {
        if (!userProvider.userExists(userId)) {
            throw new UserNotFoundException("User not found: " + userId);
        }
        userProvider.changePassword(userId, newPassword);
    }

    @Override
    public void removeUser(String userId) {
        if (!userProvider.userExists(userId)) {
