public class SnowballProgram {
    private StringBuilder current;
    private int cursor;

    public SnowballProgram() {
        this.current = new StringBuilder();
        this.cursor = 0;
    }

    public void setCurrent(String str) {
        this.current = new StringBuilder(str);
        this.cursor = 0;
    }

    public String getCurrent() {
        return this.current.toString();
    }

    public void insert(int position, String str) {
        if (position < 0 || position > current.length()) {
            throw new IndexOutOfBoundsException("Position out of bounds");
        }
        current.insert(position, str);
    }

    public void slice(int start, int end) {
        if (start < 0 || end > current.length() || start > end) {
            throw new IndexOutOfBoundsException("Invalid slice range");
        }
        current = new StringBuilder(current.substring(start, end));
        cursor = 0;
    }

    public void replace(int start, int end, String str) {
        if (start < 0 || end > current.length() || start > end) {
            throw new IndexOutOfBoundsException("Invalid replace range");
        }
        current.replace(start, end, str);
    }

    public void moveCursorForward(int steps) {
        cursor = Math.min(cursor + steps, current.length());
    }

    public void moveCursorBackward(int steps) {
        cursor = Math.max(cursor - steps, 0);
    }

    public char charAt(int index) {
        if (index < 0 || index >= current.length()) {
            throw new IndexOutOfBoundsException("Index out of bounds");
        }
        return current.charAt(index);
    }

    public boolean compareSubstring(int start, String str) {
        if (start < 0 || start + str.length() > current.length()) {
            throw new IndexOutOfBoundsException("Invalid comparison range");
        }
        return current.substring(start, start + str.length()).equals(str);
    }

    public void groupCharacters(char[] chars) {
        // Implementation for grouping characters
    }

    public boolean inRange(char ch, char start, char end) {
        return ch >= start && ch <= end;
    }
}

