public class StructInstance implements ITypedStruct {
    private String typeName;
    private Map<String, Object> attributes;
    private Map<String, Boolean> nullFlags;
    private Map<String, Boolean> explicitSetFlags;

    public StructInstance(String typeName, Map<String, Object> fieldMappings) {
        this.typeName = typeName;
        this.attributes = new HashMap<>(fieldMappings);
        this.nullFlags = new HashMap<>();
        this.explicitSetFlags = new HashMap<>();
        for (String key : fieldMappings.keySet()) {
            nullFlags.put(key, true);
            explicitSetFlags.put(key, false);
        }
    }

    public void setBoolean(String key, Boolean value) {
        setValue(key, value);
    }

    public void setByte(String key, Byte value) {
        setValue(key, value);
