        setValue(key, value);
    }

    public void setStruct(String key, StructInstance value) {
        setValue(key, value);
    }

    private void setValue(String key, Object value) {
        if (attributes.containsKey(key)) {
            attributes.put(key, value);
            nullFlags.put(key, value == null);
            explicitSetFlags.put(key, true);
        }
