public abstract class AbstractProvisioningJobDelegate<T extends ProvisioningTask> {

    protected abstract List<T> getProvisioningTasks();

    protected abstract void executeProvisioningTask(T task);

    protected abstract void generateReport(List<T> tasks);

    public void runProvisioningJob() {
        List<T> tasks = getProvisioningTasks();
        for (T task : tasks) {
            try {
                executeProvisioningTask(task);
            } catch (Exception e) {
                // Log the exception
                System.err.println("Error executing task: " + e.getMessage());
            }
        }
        generateReport(tasks);
    }

    protected boolean shouldRegisterResult(TaskResult result) {
        return result.isSuccess() || result.isIgnored();
    }

    protected void logResult(TaskResult result) {
        if (shouldRegisterResult(result)) {
            // Log success or ignored result
            System.out.println("Task result: " + result);
        } else {
            // Log failure
            System.err.println("Task failed: " + result);
        }
    }
}

