public abstract class TajoResultSetBase implements ResultSet {
    protected boolean closed = false;
    protected int currentRow = -1;
    protected int rowCount = 0;
    protected TimeZone timeZone;
    protected Object[] currentTuple;

    public TajoResultSetBase(TimeZone timeZone) {
        this.timeZone = timeZone;
    }

    public abstract boolean fetchNextTuple();

    @Override
    public boolean next() throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        if (fetchNextTuple()) {
            currentRow++;
            return true;
        }
        return false;
    }

    @Override
    public boolean first() throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        beforeFirst();
        return next();
    }

    @Override
    public boolean last() throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        while (next()) {}
        return currentRow >= 0;
    }

    @Override
    public void beforeFirst() throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        currentRow = -1;
    }

    @Override
    public void afterLast() throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        currentRow = rowCount;
    }

    @Override
    public boolean wasNull() throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        return currentTuple == null;
    }

    @Override
    public boolean getBoolean(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        checkColumnIndex(columnIndex);
        return (Boolean) currentTuple[columnIndex - 1];
    }

    @Override
    public byte getByte(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        checkColumnIndex(columnIndex);
        return (Byte) currentTuple[columnIndex - 1];
    }

    @Override
    public int getInt(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        checkColumnIndex(columnIndex);
        return (Integer) currentTuple[columnIndex - 1];
    }

    @Override
    public long getLong(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        checkColumnIndex(columnIndex);
        return (Long) currentTuple[columnIndex - 1];
    }

    @Override
    public float getFloat(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        checkColumnIndex(columnIndex);
        return (Float) currentTuple[columnIndex - 1];
    }

    @Override
    public double getDouble(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        checkColumnIndex(columnIndex);
        return (Double) currentTuple[columnIndex - 1];
    }

    @Override
    public String getString(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        checkColumnIndex(columnIndex);
        return (String) currentTuple[columnIndex - 1];
    }

    @Override
    public Date getDate(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        checkColumnIndex(columnIndex);
        return (Date) currentTuple[columnIndex - 1];
    }

    @Override
    public Time getTime(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        checkColumnIndex(columnIndex);
        return (Time) currentTuple[columnIndex - 1];
    }

    @Override
    public Timestamp getTimestamp(int columnIndex) throws SQLException {
        if (closed) throw new SQLException("ResultSet is closed.");
        checkColumnIndex(columnIndex);
        return (Timestamp) currentTuple[columnIndex - 1];
    }

    private void checkColumnIndex(int columnIndex) throws SQLException {
        if (columnIndex < 1 || columnIndex > currentTuple.length) {
            throw new SQLException("Column index out of bounds.");
        }
    }

    @Override
    public void close() throws SQLException {
        closed = true;
    }

    @Override
    public boolean isClosed() throws SQLException {
        return closed;
    }

    // Other methods from ResultSet interface are not implemented and will throw SQLException if called.
}

class TestKafkaSystemAdminWithMock {

    private KafkaSystemAdmin kafkaSystemAdmin;
    private Consumer<String, String> mockConsumer;

    @BeforeEach
    void setUp() {
        Properties props = new Properties();
        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        mockConsumer = Mockito.mock(KafkaConsumer.class);
        kafkaSystemAdmin = new KafkaSystemAdmin(mockConsumer);
    }

    @Test
    void testGetSystemStreamMetadata_ValidTopic() {
        String topic = "valid-topic";
        when(mockConsumer.partitionsFor(topic)).thenReturn(Collections.singletonList(null)); // Mocked response

        var metadata = kafkaSystemAdmin.getSystemStreamMetadata(topic);
        assertNotNull(metadata);
        assertEquals(topic, metadata.getTopic());
    }

    @Test
    void testGetSystemStreamMetadata_InvalidTopic() {
        String topic = "invalid-topic";
        when(mockConsumer.partitionsFor(topic)).thenThrow(new TopicAuthorizationException("Unauthorized"));

        assertThrows(TopicAuthorizationException.class, () -> kafkaSystemAdmin.getSystemStreamMetadata(topic));
    }

    @Test
    void testGetSystemStreamMetadata_NoMessages() {
        String topic = "empty-topic";
        when(mockConsumer.partitionsFor(topic)).thenReturn(Collections.emptyList());

        var metadata = kafkaSystemAdmin.getSystemStreamMetadata(topic);
        assertNotNull(metadata);
        assertTrue(metadata.getPartitions().isEmpty());
    }

    @Test
    void testGetSSPMetadata_WithRetry() {
        String topic = "retry-topic";
        when(mockConsumer.partitionsFor(topic))
                .thenThrow(new RuntimeException("Temporary failure"))
                .thenReturn(Collections.singletonList(null)); // Mocked response on retry

        var metadata = kafkaSystemAdmin.getSSPMetadata(topic);
        assertNotNull(metadata);
        assertEquals(topic, metadata.getTopic());
        verify(mockConsumer, times(2)).partitionsFor(topic); // Verify retry happened
    }

    @Test
    void testGetSSPMetadata_Failure() {
        String topic = "failure-topic";
        when(mockConsumer.partitionsFor(topic)).thenThrow(new RuntimeException("Permanent failure"));

        assertThrows(RuntimeException.class, () -> kafkaSystemAdmin.getSSPMetadata(topic));
    }
}

