public class TestReadingWritingDataInEvolvedSchemas {

    private static final String SCHEMA_JSON_DOUBLE = "{\"type\":\"record\",\"name\":\"TestRecord\",\"fields\":[{\"name\":\"value\",\"type\":\"double\"}]}";
    private static final String SCHEMA_JSON_FLOAT = "{\"type\":\"record\",\"name\":\"TestRecord\",\"fields\":[{\"name\":\"value\",\"type\":\"float\"}]}";
    private static final String SCHEMA_JSON_LONG = "{\"type\":\"record\",\"name\":\"TestRecord\",\"fields\":[{\"name\":\"value\",\"type\":\"long\"}]}";
    private static final String SCHEMA_JSON_INT = "{\"type\":\"record\",\"name\":\"TestRecord\",\"fields\":[{\"name\":\"value\",\"type\":\"int\"}]}";
    private static final String SCHEMA_JSON_STRING = "{\"type\":\"record\",\"name\":\"TestRecord\",\"fields\":[{\"name\":\"value\",\"type\":\"string\"}]}";
    private static final String SCHEMA_JSON_BYTES = "{\"type\":\"record\",\"name\":\"TestRecord\",\"fields\":[{\"name\":\"value\",\"type\":\"bytes\"}]}";
    private static final String SCHEMA_JSON_ENUM = "{\"type\":\"record\",\"name\":\"TestRecord\",\"fields\":[{\"name\":\"value\",\"type\":{\"type\":\"enum\",\"name\":\"TestEnum\",\"symbols\":[\"A\",\"B\"]}}]}";

    private static Stream<String> encodingTypes() {
        return Stream.of("binary", "json");
    }

    @ParameterizedTest
    @MethodSource("encodingTypes")
    public void testDoubleToFloatConversion(String encoding) throws IOException {
        Schema schema = new Schema.Parser().parse(SCHEMA_JSON_DOUBLE);
        GenericRecord record = new GenericData.Record(schema);
        record.put("value", 1.23);

        byte[] data = serialize(record, encoding);
        GenericRecord deserializedRecord = deserialize(data, SCHEMA_JSON_FLOAT, encoding);

        assertEquals(1.23f, deserializedRecord.get("value"));
    }

    @ParameterizedTest
    @MethodSource("encodingTypes")
    public void testFloatToIntConversion(String encoding) throws IOException {
        Schema schema = new Schema.Parser().parse(SCHEMA_JSON_FLOAT);
        GenericRecord record = new GenericData.Record(schema);
        record.put("value", 1.23f);

        byte[] data = serialize(record, encoding);
        GenericRecord deserializedRecord = deserialize(data, SCHEMA_JSON_INT, encoding);

        assertEquals(1, deserializedRecord.get("value"));
    }

    @ParameterizedTest
    @MethodSource("encodingTypes")
    public void testStringToBytesConversion(String encoding) throws IOException {
        Schema schema = new Schema.Parser().parse(SCHEMA_JSON_STRING);
        GenericRecord record = new GenericData.Record(schema);
        record.put("value", "test");

        byte[] data = serialize(record, encoding);
        GenericRecord deserializedRecord = deserialize(data, SCHEMA_JSON_BYTES, encoding);

        assertArrayEquals("test".getBytes(), (byte[]) deserializedRecord.get("value"));
    }

    private byte[] serialize(GenericRecord record, String encoding) throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        Encoder encoder = encoding.equals("binary") ? EncoderFactory.get().binaryEncoder(outputStream, null) : EncoderFactory.get().jsonEncoder(record.getSchema(), outputStream);
        SpecificDatumWriter<GenericRecord> writer = new SpecificDatumWriter<>(record.getSchema());
        writer.write(record, encoder);
        encoder.flush();
        return outputStream.toByteArray();
    }

    private GenericRecord deserialize(byte[] data, String schemaJson, String encoding) throws IOException {
        Schema schema = new Schema.Parser().parse(schemaJson);
        Decoder decoder = encoding.equals("binary") ? DecoderFactory.get().binaryDecoder(data, null) : DecoderFactory.get().jsonDecoder(schema, data);
        SpecificDatumReader<GenericRecord> reader = new SpecificDatumReader<>(schema);
        return reader.read(null, decoder);
    }
}

