public abstract class AbstractTestRangeIndex extends Assert {

    protected abstract RangeIndex<Integer> createRangeIndex();

    @Test
    public void testInsertAndMinMax() {
        RangeIndex<Integer> rangeIndex = createRangeIndex();
        rangeIndex.insert(10);
        rangeIndex.insert(20);
        rangeIndex.insert(5);

        assertEquals(Integer.valueOf(5), rangeIndex.minKey());
        assertEquals(Integer.valueOf(20), rangeIndex.maxKey());
    }

    @Test
    public void testDelete() {
        RangeIndex<Integer> rangeIndex = createRangeIndex();
        rangeIndex.insert(10);
        rangeIndex.insert(20);
        rangeIndex.insert(5);

        rangeIndex.delete(10);
        assertNull(rangeIndex.find(10));
        assertEquals(Integer.valueOf(5), rangeIndex.minKey());
        assertEquals(Integer.valueOf(20), rangeIndex.maxKey());
    }

    @Test
    public void testIteration() {
        RangeIndex<Integer> rangeIndex = createRangeIndex();
        rangeIndex.insert(10);
        rangeIndex.insert(20);
        rangeIndex.insert(5);

        Iterator<Integer> iterator = rangeIndex.iterator();
        assertTrue(iterator.hasNext());
        assertEquals(Integer.valueOf(5), iterator.next());
        assertEquals(Integer.valueOf(10), iterator.next());
        assertEquals(Integer.valueOf(20), iterator.next());
        assertFalse(iterator.hasNext());
    }

    @Test
    public void testClear() {
        RangeIndex<Integer> rangeIndex = createRangeIndex();
        rangeIndex.insert(10);
        rangeIndex.insert(20);
        rangeIndex.clear();

        assertTrue(rangeIndex.isEmpty());
    }

    @Test
    public void testRandomInsertDelete() {
        RangeIndex<Integer> rangeIndex = createRangeIndex();
        Random random = new Random();

        for (int i = 0; i < 100; i++) {
            int value = random.nextInt(100);
            rangeIndex.insert(value);
        }

        for (int i = 0; i < 50; i++) {
            int value = random.nextInt(100);
            rangeIndex.delete(value);
        }

        assertNotNull(rangeIndex.minKey());
        assertNotNull(rangeIndex.maxKey());
    }

    @Test
    public void testEdgeCases() {
        RangeIndex<Integer> rangeIndex = createRangeIndex();

        assertNull(rangeIndex.minKey());
        assertNull(rangeIndex.maxKey());

        rangeIndex.insert(1);
        assertEquals(Integer.valueOf(1), rangeIndex.minKey());
        assertEquals(Integer.valueOf(1), rangeIndex.maxKey());

        rangeIndex.delete(1);
        assertNull(rangeIndex.minKey());
        assertNull(rangeIndex.maxKey());
    }
}

