public class JmsFactory {

    public static final String JMS_QUEUE = "queue";
    public static final String JMS_TOPIC = "topic";

    public static Connection createConnection(String clientId, String username, String password) throws JMSException, NamingException {
        ConnectionFactory connectionFactory = (ConnectionFactory) new InitialContext().lookup("ConnectionFactory");
        Connection connection = connectionFactory.createConnection(username, password);
        if (clientId != null) {
            connection.setClientID(clientId);
        }
        return connection;
    }

    public static String generateClientId() {
        return UUID.randomUUID().toString();
    }

    public static Session createSession(Connection connection, int acknowledgeMode) throws JMSException {
        return connection.createSession(false, acknowledgeMode);
    }

    public static MessageConsumer createConsumer(Session session, String destinationName, boolean durable, String subscriptionName) throws JMSException, NamingException {
        Destination destination = createDestination(destinationName);
        if (durable) {
            return session.createDurableSubscriber((Topic) destination, subscriptionName);
        } else {
            return session.createConsumer(destination);
        }
    }

    public static MessageProducer createProducer(Session session, String destinationName) throws JMSException, NamingException {
        Destination destination = createDestination(destinationName);
        return session.createProducer(destination);
    }

    public static byte[] convertMessageToBytes(Message message) throws JMSException {
        return message.getBody(byte[].class);
    }

    public static Destination createDestination(String destinationName) throws NamingException {
        if (destinationName.startsWith(JMS_QUEUE)) {
            return (Destination) new InitialContext().lookup(destinationName);
        } else if (destinationName.startsWith(JMS_TOPIC)) {
            return (Destination) new InitialContext().lookup(destinationName);
        }
        throw new IllegalArgumentException("Invalid destination name");
    }

    public static Map<String, Object> extractMessageProperties(Message message) throws JMSException {
        Map<String, Object> properties = new HashMap<>();
        for (Enumeration<?> e = message.getPropertyNames(); e.hasMoreElements(); ) {
            String propertyName = (String) e.nextElement();
            properties.put(propertyName, message.getObjectProperty(propertyName));
        }
        return properties;
    }

    public static ConnectionFactory createConnectionFactory(boolean ssl) throws NamingException {
        if (ssl) {
            return (ConnectionFactory) new InitialContext().lookup("SslConnectionFactory");
        } else {
            return (ConnectionFactory) new InitialContext().lookup("ConnectionFactory");
        }
    }
}

public class TestBasicLP extends TestCase {

    private Model model;
    private Reasoner reasoner;

    @Override
    protected void setUp() throws Exception {
        super.setUp();
        model = ModelFactory.createDefaultModel();
        reasoner = ReasonerRegistry.getRDFSReasoner();
    }

    public void testBasicInference() {
        String ns = "http://example.org/";
        Resource subject = model.createResource(ns + "subject");
        Property predicate = model.createProperty(ns + "predicate");
        Resource object = model.createResource(ns + "object");

        model.add(subject, predicate, object);

        InfModel infModel = ModelFactory.createInfModel(reasoner, model);
        StmtIterator iter = infModel.listStatements(subject, predicate, (RDFNode) null);

        assertTrue(iter.hasNext());
        Statement stmt = iter.nextStatement();
        assertEquals(object, stmt.getObject());
    }

    public void testBacktracking() {
        String ns = "http://example.org/";
        Resource subject1 = model.createResource(ns + "subject1");
        Resource subject2 = model.createResource(ns + "subject2");
        Property predicate = model.createProperty(ns + "predicate");
        Resource object = model.createResource(ns + "object");

        model.add(subject1, predicate, object);
        model.add(subject2, predicate, object);

        InfModel infModel = ModelFactory.createInfModel(reasoner, model);
        Set<Statement> results = infModel.listStatements(null, predicate, object).toSet();

        assertEquals(2, results.size());
    }

    public void testBuiltInFunctions() {
        String ns = "http://example.org/";
        Resource subject = model.createResource(ns + "subject");
        Property predicate = model.createProperty(ns + "predicate");
        Literal object = model.createTypedLiteral(42);

        model.add(subject, predicate, object);

        InfModel infModel = ModelFactory.createInfModel(reasoner, model);
        assertTrue(infModel.contains(subject, predicate, object));
    }

    public void testRDFSInference() {
        String ns = "http://example.org/";
        Resource classA = model.createResource(ns + "ClassA");
        Resource classB = model.createResource(ns + "ClassB");
        Property subClassOf = RDFS.subClassOf;

        model.add(classB, subClassOf, classA);
        Resource individual = model.createResource(ns + "individual");
        model.add(individual, RDF.type, classB);

        InfModel infModel = ModelFactory.createInfModel(reasoner, model);
        assertTrue(infModel.contains(individual, RDF.type, classA));
    }

    public void testOWLInference() {
        String ns = "http://example.org/";
        Resource classA = model.createResource(ns + "ClassA");
        Resource classB = model.createResource(ns + "ClassB");
        Property equivalentClass = OWL.equivalentClass;

        model.add(classA, equivalentClass, classB);
        Resource individual = model.createResource(ns + "individual");
        model.add(individual, RDF.type, classA);

        InfModel infModel = ModelFactory.createInfModel(reasoner, model);
        assertTrue(infModel.contains(individual, RDF.type, classB));
    }

    @Override
    protected void tearDown() throws Exception {
        model.close();
        super.tearDown();
    }
}

