public class DefaultInstrumentationAgent implements InstrumentationAgent {
    private static final Logger logger = Logger.getLogger(DefaultInstrumentationAgent.class.getName());
    private MBeanServer mBeanServer;
    private JMXConnectorServer connectorServer;
    private String defaultDomain;
    private int registryPort;
    private int connectorPort;
    private String serviceUrlPath;

    public DefaultInstrumentationAgent() {
        initializeSettings();
        mBeanServer = ManagementFactory.getPlatformMBeanServer();
    }

    private void initializeSettings() {
        defaultDomain = System.getProperty("jmx.default.domain", "defaultDomain");
        registryPort = Integer.parseInt(System.getProperty("jmx.registry.port", "1099"));
        connectorPort = Integer.parseInt(System.getProperty("jmx.connector.port", "1099"));
        serviceUrlPath = System.getProperty("jmx.service.url.path", "/jmxrmi");
    }

    public void registerMBean(Object mBean, String name) {
        try {
            ObjectName objectName = new ObjectName(defaultDomain + ":type=" + name);
            mBeanServer.registerMBean(mBean, objectName);
            logger.log(Level.INFO, "Registered MBean: " + objectName);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to register MBean: " + name, e);
        }
    }

    public void unregisterMBean(String name) {
        try {
            ObjectName objectName = new ObjectName(defaultDomain + ":type=" + name);
            mBeanServer.unregisterMBean(objectName);
            logger.log(Level.INFO, "Unregistered MBean: " + objectName);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to unregister MBean: " + name, e);
        }
    }

    public void start() {
        try {
            Map<String, Object> environment = new HashMap<>();
            JMXServiceURL serviceURL = new JMXServiceURL("service:jmx:rmi:///jndi/rmi://localhost:" + registryPort + serviceUrlPath);
            connectorServer = JMXConnectorServerFactory.createJMXConnectorServer(serviceURL, environment, mBeanServer);
            connectorServer.start();
            logger.log(Level.INFO, "JMX Agent started on port: " + registryPort);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to start JMX Agent", e);
        }
    }

    public void stop() {
        try {
            if (connectorServer != null) {
                connectorServer.stop();
                logger.log(Level.INFO, "JMX Agent stopped");
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to stop JMX Agent", e);
        }
    }
}

