public class UrlEncoder {
    public static final UrlEncoder QUERY = new UrlEncoder(new BitSet());
    public static final UrlEncoder PATH = new UrlEncoder(new BitSet());
    public static final UrlEncoder FULL_PATH = new UrlEncoder(new BitSet());

    private final BitSet safeCharacters;

    private UrlEncoder(BitSet safeCharacters) {
        this.safeCharacters = safeCharacters;
        // Initialize safeCharacters based on the encoding type
        // This is a placeholder for actual initialization logic
    }

    public String encode(String input, Charset charset) {
        if (input == null) {
            return null;
        }
        StringBuilder encoded = new StringBuilder();
        byte[] bytes = input.getBytes(charset);
        for (byte b : bytes) {
            if (safeCharacters.get(b)) {
                encoded.append((char) b);
            } else {
                encoded.append('%');
                encoded.append(String.format("%02X", b));
            }
        }
        return encoded.toString();
    }

    public String encode(String input) {
        return encode(input, StandardCharsets.UTF_8);
    }
}

public class ScriptParser {
    private Map<String, Command> commands = new HashMap<>();
    private Map<String, Operation> operations = new HashMap<>();
    private Map<String, Object> variables = new HashMap<>();
    private List<String> tokenStream = new ArrayList<>();

    public void addCommand(String name, Command command) {
        commands.put(name, command);
    }

    public void addOperation(String name, Operation operation) {
        operations.put(name, operation);
    }

    public void setVariable(String name, Object value) {
        variables.put(name, value);
    }

    public Object getVariable(String name) {
        return variables.get(name);
    }

    public void parse(String script) {
        tokenStream = Arrays.asList(script.split("\\s+"));
        executeTokens();
    }

    private void executeTokens() {
        for (String token : tokenStream) {
            if (commands.containsKey(token)) {
                commands.get(token).execute(this);
            } else if (operations.containsKey(token)) {
                operations.get(token).execute(this);
            } else {
                handleVariable(token);
            }
        }
    }

    private void handleVariable(String token) {
        // Code smell: Implicit variable handling without clear context
        if (variables.containsKey(token)) {
            System.out.println(variables.get(token));
        } else {
            System.err.println("Undefined variable: " + token);
        }
    }

    public static void main(String[] args) {
        ScriptParser parser = new ScriptParser();
        // Code smell: No validation for command and operation addition
        parser.addCommand("print", new PrintCommand());
        parser.addOperation("add", new AddOperation());

        String script = "print x add y";
        parser.setVariable("x", "Hello");
        parser.setVariable("y", 5);
        parser.parse(script);
    }
}

interface Command {
    void execute(ScriptParser parser);
}

