public class ProxyManagerImpl implements ProxyManager {
    private Set<Class<?>> unproxyableClasses = new HashSet<>();
    private Map<Class<?>, ProxyType> proxyTypes = new HashMap<>();

    @Override
    public <T> T createProxy(Class<T> clazz) {
        if (isProxyable(clazz)) {
            // Logic to create proxy
            return createNewProxyInstance(clazz);
        }
        throw new IllegalArgumentException("Class is not proxyable: " + clazz.getName());
    }

    @Override
    public <T> T copy(T object) {
        if (object instanceof Collection) {
            return (T) copyCollection((Collection<?>) object);
        } else if (object instanceof Map) {
            return (T) copyMap((Map<?, ?>) object);
        } else if (object instanceof Date) {
            return (T) new Date(((Date) object).getTime());
        } else if (object instanceof Calendar) {
            return (T) copyCalendar((Calendar) object);
        }
        return null;
    }

    @Override
    public void registerProxyType(Class<?> clazz, ProxyType proxyType) {
        proxyTypes.put(clazz, proxyType);
    }

    @Override
    public void configureUnproxyableClass(Class<?> clazz) {
        unproxyableClasses.add(clazz);
    }

    private boolean isProxyable(Class<?> clazz) {
        return !unproxyableClasses.contains(clazz) && proxyTypes.containsKey(clazz);
    }

    private <T> T createNewProxyInstance(Class<T> clazz) {
        // Logic to generate proxy bytecode
        return null; // Placeholder for actual proxy instance
    }

    private Collection<?> copyCollection(Collection<?> collection) {
        return new ArrayList<>(collection);
    }

    private Map<?, ?> copyMap(Map<?, ?> map) {
        return new HashMap<>(map);
    }

    private Calendar copyCalendar(Calendar calendar) {
        Calendar newCalendar = Calendar.getInstance();
        newCalendar.setTime(calendar.getTime());
        return newCalendar;
    }
}

