public class DataTypeUtils {
    private static final Logger logger = Logger.getLogger(DataTypeUtils.class.getName());

    public static BigDecimal toBigInt(Object value) {
        if (value instanceof Number) {
            return BigDecimal.valueOf(((Number) value).longValue());
        }
        logError("Cannot convert to BigInt: " + value);
        return null;
    }

    public static Boolean toBoolean(Object value) {
        if (value instanceof Boolean) {
            return (Boolean) value;
        }
        logError("Cannot convert to Boolean: " + value);
        return null;
    }

    public static Byte toByte(Object value) {
        if (value instanceof Number) {
            return ((Number) value).byteValue();
        }
        logError("Cannot convert to Byte: " + value);
        return null;
    }

    public static Character toChar(Object value) {
        if (value instanceof String && ((String) value).length() == 1) {
            return ((String) value).charAt(0);
        }
        logError("Cannot convert to Char: " + value);
        return null;
    }

    public static Date toDate(Object value) {
        if (value instanceof Date) {
            return (Date) value;
        }
        logError("Cannot convert to Date: " + value);
        return null;
    }

    public static Double toDouble(Object value) {
        if (value instanceof Number) {
            return ((Number) value).doubleValue();
        }
        logError("Cannot convert to Double: " + value);
        return null;
    }

    public static Float toFloat(Object value) {
        if (value instanceof Number) {
            return ((Number) value).floatValue();
        }
        logError("Cannot convert to Float: " + value);
        return null;
    }

    public static Integer toInt(Object value) {
        if (value instanceof Number) {
            return ((Number) value).intValue();
        }
        logError("Cannot convert to Int: " + value);
        return null;
    }

    public static Long toLong(Object value) {
        if (value instanceof Number) {
            return ((Number) value).longValue();
        }
        logError("Cannot convert to Long: " + value);
        return null;
    }

    public static Short toShort(Object value) {
        if (value instanceof Number) {
            return ((Number) value).shortValue();
        }
        logError("Cannot convert to Short: " + value);
        return null;
    }

    public static String toString(Object value) {
        return value != null ? value.toString() : null;
    }

    public static List<Object> toArray(Object value) {
        if (value instanceof Collection) {
            return new ArrayList<>((Collection<?>) value);
        }
        logError("Cannot convert to Array: " + value);
        return null;
    }

    public static Map<String, Object> toMap(Object value) {
        if (value instanceof Map) {
            return new HashMap<>((Map<?, ?>) value);
        }
        logError("Cannot convert to Map: " + value);
        return null;
    }

    public static boolean isCompatible(Object value, Class<?> type) {
        if (type.isInstance(value)) {
            return true;
        }
        logError("Incompatible type: " + value + " for " + type);
        return false;
    }

    private static void logError(String message) {
        logger.severe(message);
    }
}

