public class WritableUtils {

    public static <T extends Writable> T createWritable(Class<T> clazz) {
        try {
            Constructor<T> constructor = clazz.getDeclaredConstructor();
            constructor.setAccessible(true);
            return constructor.newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Unable to create writable instance", e);
        }
    }

    public static byte[] writeWritable(Writable writable) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        DataOutputStream dataOutputStream = new DataOutputStream(byteArrayOutputStream);
        writable.write(dataOutputStream);
        dataOutputStream.close();
        return byteArrayOutputStream.toByteArray();
    }

    public static Writable readWritable(byte[] bytes, Writable writable) throws IOException {
        ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(bytes);
        DataInputStream dataInputStream = new DataInputStream(byteArrayInputStream);
        writable.readFields(dataInputStream);
        dataInputStream.close();
        return writable;
    }

    public static void writeToZNode(ZooKeeper zooKeeper, String zNodePath, Writable writable) throws Exception {
        byte[] data = writeWritable(writable);
        zooKeeper.create(zNodePath, data, null, null);
    }

    public static Writable readFromZNode(ZooKeeper zooKeeper, String zNodePath, Writable writable) throws Exception {
        byte[] data = zooKeeper.getData(zNodePath, false, null);
        return readWritable(data, writable);
    }

    public static byte[] writeWritableList(List<? extends Writable> writables) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        DataOutputStream dataOutputStream = new DataOutputStream(byteArrayOutputStream);
        dataOutputStream.writeInt(writables.size());
        for (Writable writable : writables) {
            byte[] data = writeWritable(writable);
            dataOutputStream.writeInt(data.length);
            dataOutputStream.write(data);
        }
        dataOutputStream.close();
        return byteArrayOutputStream.toByteArray();
    }

    public static List<Writable> readWritableList(byte[] bytes) throws IOException {
        List<Writable> writables = new ArrayList<>();
        ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(bytes);
        DataInputStream dataInputStream = new DataInputStream(byteArrayInputStream);
        int size = dataInputStream.readInt();
        for (int i = 0; i < size; i++) {
            int length = dataInputStream.readInt();
            byte[] data = new byte[length];
            dataInputStream.readFully(data);
            Writable writable = createWritable(Writable.class); // Code smell: using Writable.class directly
            readWritable(data, writable);
            writables.add(writable);
        }
        dataInputStream.close();
        return writables;
    }

    public static void writeIntArray(DataOutputStream out, int[] array) throws IOException {
        out.writeInt(array.length);
        for (int value : array) {
            out.writeInt(value);
        }
    }

    public static int[] readIntArray(DataInputStream in) throws IOException {
        int length = in.readInt();
        int[] array = new int[length];
        for (int i = 0; i < length; i++) {
            array[i] = in.readInt();
        }
        return array;
    }

    public static void writeLongArray(DataOutputStream out, long[] array) throws IOException {
        out.writeInt(array.length);
        for (long value : array) {
            out.writeLong(value);
        }
    }

    public static long[] readLongArray(DataInputStream in) throws IOException {
        int length = in.readInt();
        long[] array = new long[length];
        for (int i = 0; i < length; i++) {
            array[i] = in.readLong();
        }
        return array;
    }
}

