public class ReleasePrepareAction {
    private String user;
    private String projectGroup;
    private ProjectConfig projectConfig;
    private DistributedReleaseManager distributedReleaseManager;

    public ReleasePrepareAction(String user, String projectGroup, ProjectConfig projectConfig, DistributedReleaseManager distributedReleaseManager) {
        this.user = user;
        this.projectGroup = projectGroup;
        this.projectConfig = projectConfig;
        this.distributedReleaseManager = distributedReleaseManager;
    }

    public void prepareRelease() {
        if (!isAuthorized()) {
            throw new UnauthorizedException("User does not have permission to build projects in this group.");
        }

        ProjectDetails projectDetails = retrieveProjectDetails();
        String scmTag = constructScmTag(projectDetails);
        String tagBase = constructTagBase(projectDetails);

        prepareReleaseProcess(scmTag, tagBase);

        if (distributedReleaseManager.isEnabled()) {
            distributedReleaseManager.executeDistributedBuild(scmTag);
        } else {
            executeRelease(scmTag);
        }

        viewResults();
        checkProgress();
    }

    private boolean isAuthorized() {
        // Code smell: This method could be more modular and reusable
        return AuthorizationService.hasPermission(user, projectGroup);
    }

    private ProjectDetails retrieveProjectDetails() {
        // Code smell: This method could be split into smaller methods for clarity
        return projectConfig.getProjectDetails();
    }

    private String constructScmTag(ProjectDetails projectDetails) {
        // Code smell: Tag construction logic could be extracted to a utility class
        return sanitizeTag(projectDetails.getVersion());
    }

    private String constructTagBase(ProjectDetails projectDetails) {
        // Code smell: Similar logic to constructScmTag, consider refactoring
        return sanitizeTag(projectDetails.getTagBase());
    }

    private void prepareReleaseProcess(String scmTag, String tagBase) {
        // Code smell: This method does too much; consider breaking it down
        ReleaseParameters parameters = new ReleaseParameters();
        parameters.setGoals("deploy");
        parameters.setArguments("--batch-mode");
        parameters.setScmTag(scmTag);
        parameters.setTagBase(tagBase);
        // Additional parameters can be set here
    }

    private void executeRelease(String scmTag) {
        try {
            // Code smell: Error handling could be more robust
            ReleaseExecutor.execute(scmTag);
            logReleaseId(scmTag);
        } catch (Exception e) {
            handleError(e);
        }
    }

    private void viewResults() {
        // Code smell: This method could be more descriptive
        ResultViewer.displayResults();
    }

    private void checkProgress() {
        // Code smell: Progress checking could be more detailed
        ProgressMonitor.monitor();
    }

    private String sanitizeTag(String tag) {
        // Code smell: Sanitization logic could be centralized
        return tag.replaceAll("[^a-zA-Z0-9._-]", "_");
    }

    private void logReleaseId(String scmTag) {
        // Code smell: Logging could be more structured
        System.out.println("Release ID: " + scmTag);
    }

    private void handleError(Exception e) {
        // Code smell: Error handling could be more informative
        System.err.println("Error during release execution: " + e.getMessage());
    }
}

