public class Requestor implements MessageListener {
    private final Map<String, Message> requestMap = new ConcurrentHashMap<>();
    private final Map<String, Message> replyMap = new ConcurrentHashMap<>();
    private final ScheduledExecutorService executorService = Executors.newScheduledThreadPool(1);
    private final long maxRequestTimeout;

    public Requestor(long maxRequestTimeout) {
        this.maxRequestTimeout = maxRequestTimeout;
    }

    @Override
    public void onMessage(Message message) {
        try {
            String correlationId = message.getJMSCorrelationID();
            replyMap.put(correlationId, message);
        } catch (JMSException e) {
            e.printStackTrace();
        }
    }

    public void sendRequest(Session session, Destination destination, Message request) throws JMSException {
        String correlationId = request.getJMSCorrelationID();
        requestMap.put(correlationId, request);
        MessageProducer producer = session.createProducer(destination);
        producer.send(request);
        scheduleTimeout(correlationId);
    }

    private void scheduleTimeout(String correlationId) {
        executorService.schedule(() -> {
            if (requestMap.containsKey(correlationId)) {
                requestMap.remove(correlationId);
                // Handle timeout logic here
            }
        }, maxRequestTimeout, TimeUnit.MILLISECONDS);
    }

    public Message getReply(String correlationId) {
        return replyMap.remove(correlationId);
    }

    public long getMaxRequestTimeout() {
        return maxRequestTimeout;
    }
}

