public class DefaultTypeMapping implements TypeMapping {
    private static final Logger logger = Logger.getLogger(DefaultTypeMapping.class.getName());

    private final Map<Class<?>, AegisType> class2Type = new HashMap<>();
    private final Map<QName, AegisType> xml2Type = new HashMap<>();
    private final Map<Class<?>, QName> class2xml = new HashMap<>();
    private TypeMapping next;

    public void setNext(TypeMapping next) {
