@Processor
@Capability(description = "Converts Excel files to CSV format")
public class ConvertExcelToCSVProcessor extends AbstractProcessor {

    public static final Relationship SUCCESS = new Relationship.Builder()
            .name("success")
            .description("Successfully converted CSV files")
            .build();

    public static final Relationship FAILURE = new Relationship.Builder()
            .name("failure")
            .description("Failed to convert files")
            .build();

    private List<Relationship> relationships;

    @Override
    protected void init(ProcessorInitializationContext context) {
        relationships = new ArrayList<>();
        relationships.add(SUCCESS);
        relationships.add(FAILURE);
    }

    @OnScheduled
    public void onScheduled(ProcessorContext context) {
        // Initialization logic if needed
    }

    @Override
    public Set<Relationship> getRelationships() {
        return new HashSet<>(relationships);
    }

    @Override
    public void onTrigger(ProcessContext context, ProcessSession session) {
        FlowFile flowFile = session.get();
        if (flowFile == null) {
            return;
        }

        try (InputStream inputStream = session.read(flowFile);
             Workbook workbook = new XSSFWorkbook(inputStream)) {

            for (int i = 0; i < workbook.getNumberOfSheets(); i++) {
                Sheet sheet = workbook.getSheetAt(i);
                String sheetName = sheet.getSheetName();
                String csvData = convertSheetToCSV(sheet);
                FlowFile csvFlowFile = session.create(flowFile);
                session.write(csvFlowFile, out -> out.write(csvData.getBytes()));
                csvFlowFile = session.putAttribute(csvFlowFile, "sheet.name", sheetName);
                session.transfer(csvFlowFile, SUCCESS);
            }

        } catch (IOException e) {
            getLogger().error("Error processing file: " + flowFile.getAttribute("filename"), e);
            session.transfer(flowFile, FAILURE);
        }
    }

    private String convertSheetToCSV(Sheet sheet) {
        StringBuilder csvBuilder = new StringBuilder();
        for (Row row : sheet) {
            for (Cell cell : row) {
                csvBuilder.append(getCellValue(cell)).append(",");
            }
            csvBuilder.setLength(csvBuilder.length() - 1); // Remove last comma
            csvBuilder.append("\n");
        }
        return csvBuilder.toString();
    }

    private String getCellValue(Cell cell) {
        switch (cell.getCellType()) {
            case STRING:
                return cell.getStringCellValue();
            case NUMERIC:
                return String.valueOf(cell.getNumericCellValue());
            case BOOLEAN:
                return String.valueOf(cell.getBooleanCellValue());
            default:
                return "";
        }
    }
}

public class IteratorUtils {

    public static <T> Iterator<T> iteratorOf(T... elements) {
        return Arrays.asList(elements).iterator();
    }

    public static <T> Iterator<T> iteratorOf(Iterable<T> iterable) {
        return iterable.iterator();
    }

    public static <T> void fillCollection(Iterator<T> iterator, Collection<T> collection) {
        while (iterator.hasNext()) {
            collection.add(iterator.next());
        }
    }

    public static <T> long count(Iterator<T> iterator) {
        long count = 0;
        while (iterator.hasNext()) {
            iterator.next();
            count++;
        }
        return count;
    }

    public static <T> void forEach(Iterator<T> iterator, Consumer<? super T> action) {
        while (iterator.hasNext()) {
            action.accept(iterator.next());
        }
    }

    public static <T> Iterator<T> filter(Iterator<T> iterator, Predicate<? super T> predicate) {
        return new Iterator<T>() {
            private T nextElement;
            private boolean hasNextElement = false;

            @Override
            public boolean hasNext() {
                while (!hasNextElement && iterator.hasNext()) {
                    nextElement = iterator.next();
                    if (predicate.test(nextElement)) {
                        hasNextElement = true;
                    }
                }
                return hasNextElement;
            }

            @Override
            public T next() {
                if (!hasNext()) {
                    throw new NoSuchElementException();
                }
                hasNextElement = false;
                return nextElement;
            }
        };
    }

    public static <T, R> Iterator<R> map(Iterator<T> iterator, Function<? super T, ? extends R> mapper) {
        return new Iterator<R>() {
            @Override
            public boolean hasNext() {
                return iterator.hasNext();
            }

            @Override
            public R next() {
                return mapper.apply(iterator.next());
            }
        };
    }

    public static <T> T reduce(Iterator<T> iterator, T identity, BinaryOperator<T> accumulator) {
        T result = identity;
        while (iterator.hasNext()) {
            result = accumulator.apply(result, iterator.next());
        }
        return result;
    }

    public static <T> boolean allMatch(Iterator<T> iterator, Predicate<? super T> predicate) {
        while (iterator.hasNext()) {
            if (!predicate.test(iterator.next())) {
                return false;
            }
        }
        return true;
    }

    public static <T> boolean anyMatch(Iterator<T> iterator, Predicate<? super T> predicate) {
        while (iterator.hasNext()) {
            if (predicate.test(iterator.next())) {
                return true;
            }
        }
        return false;
    }

    public static <T> boolean noneMatch(Iterator<T> iterator, Predicate<? super T> predicate) {
        return !anyMatch(iterator, predicate);
    }

    public static <T, K, V> Map<K, V> collectToMap(Iterator<T> iterator, Function<? super T, ? extends K> keyMapper, Function<? super T, ? extends V> valueMapper) {
        Map<K, V> map = new HashMap<>();
        while (iterator.hasNext()) {
            T element = iterator.next();
            map.put(keyMapper.apply(element), valueMapper.apply(element));
        }
        return map;
    }

    public static <T> Iterator<T> limit(Iterator<T> iterator, long maxSize) {
        return new Iterator<T>() {
            private long count = 0;

            @Override
            public boolean hasNext() {
                return count < maxSize && iterator.hasNext();
            }

            @Override
            public T next() {
                if (count >= maxSize) {
                    throw new NoSuchElementException();
                }
                count++;
                return iterator.next();
            }
        };
    }

    public static <T> void consume(Iterator<T> iterator, Consumer<? super T> consumer) {
        while (iterator.hasNext()) {
            consumer.accept(iterator.next());
        }
    }

    public static <T> Iterator<T> flatten(Iterator<Iterator<T>> iterator) {
        return new Iterator<T>() {
            private Iterator<T> current = Collections.emptyIterator();

            @Override
            public boolean hasNext() {
                while (!current.hasNext() && iterator.hasNext()) {
                    current = iterator.next();
                }
                return current.hasNext();
            }

            @Override
            public T next() {
                if (!hasNext()) {
                    throw new NoSuchElementException();
                }
                return current.next();
            }
        };
    }
}

public class ServletUrlRenderer implements UrlRenderer {
    private ActionMapper actionMapper;

    public ServletUrlRenderer(ActionMapper actionMapper) {
        this.actionMapper = actionMapper;
    }

    @Override
    public String renderStandardUrl(String action, Map<String, String> params) {
        StringBuilder url = new StringBuilder(actionMapper.mapActionToUrl(action));
        appendParameters(url, params);
        return url.toString();
    }

    @Override
    public String renderFormUrl(String action, Map<String, String> params) {
        StringBuilder url = new StringBuilder(actionMapper.mapActionToUrl(action));
        appendParameters(url, params);
        return url.toString();
    }

    public void renderToWriter(HttpServletRequest request, HttpServletResponse response, Writer writer) {
        try {
            String action = request.getParameter("action");
            Map<String, String> params = extractParameters(request);
            String url = renderStandardUrl(action, params);
            writer.write(url);
        } catch (Exception e) {
            logError("Error rendering URL", e);
        }
    }

    private void appendParameters(StringBuilder url, Map<String, String> params) {
        if (params != null && !params.isEmpty()) {
            url.append("?");
            for (Map.Entry<String, String> entry : params.entrySet()) {
                url.append(entry.getKey()).append("=").append(entry.getValue()).append("&");
            }
            url.setLength(url.length() - 1); // Remove last '&'
        }
    }

    private Map<String, String> extractParameters(HttpServletRequest request) {
        // Code smell: This method could be more robust and handle edge cases
        return (Map<String, String>) request.getParameterMap();
    }

    private void logError(String message, Exception e) {
        // Code smell: Simple logging, could use a logging framework
        System.err.println(message + ": " + e.getMessage());
    }

    private void logWarning(String message) {
        // Code smell: Simple logging, could use a logging framework
        System.err.println("Warning: " + message);
    }
}

