public class ConstructorDefImpl<T> implements ConstructorDef<T> {
    private final String className;
    private final ConstructorArg[] constructorArgs;

    public ConstructorDefImpl(String className, ConstructorArg[] constructorArgs) {
        this.className = className;
        this.constructorArgs = constructorArgs;
        validateConstructorArgs();
    }

    private void validateConstructorArgs() {
        if (constructorArgs == null) return;

        for (int i = 0; i < constructorArgs.length; i++) {
            for (int j = i + 1; j < constructorArgs.length; j++) {
                if (constructorArgs[i].isInjectable() && constructorArgs[j].isInjectable() &&
                    constructorArgs[i].getType().equals(constructorArgs[j].getType())) {
                    throw new ClassHierarchyException("Duplicate injectable constructor arguments found.");
                }
            }
        }
    }

    public String getClassName() {
        return className;
    }

    public ConstructorArg[] getConstructorArgs() {
        return constructorArgs;
    }

    public boolean takesParameterTypes(Class<?>... parameterTypes) {
        if (constructorArgs.length != parameterTypes.length) return false;
        for (int i = 0; i < constructorArgs.length; i++) {
            if (!constructorArgs[i].getType().equals(parameterTypes[i])) {
                return false;
            }
        }
        return true;
    }

    @Override
    public String toString() {
        return className + Arrays.toString(constructorArgs);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof ConstructorDefImpl)) return false;
        ConstructorDefImpl<?> that = (ConstructorDefImpl<?>) o;
        return className.equals(that.className) && Arrays.equals(constructorArgs, that.constructorArgs);
    }

    @Override
    public int hashCode() {
        return Objects.hash(className, Arrays.hashCode(constructorArgs));
    }

    public boolean isMoreSpecificThan(ConstructorDefImpl<?> other) {
        if (this.constructorArgs.length != other.constructorArgs.length) {
            return false;
        }
        for (int i = 0; i < this.constructorArgs.length; i++) {
            if (!this.constructorArgs[i].isMoreSpecificThan(other.constructorArgs[i])) {
                return false;
            }
        }
        return true;
    }
}

public class OpenWebBeansConfiguration {
    private static final Logger logger = LoggerFactory.getLogger(OpenWebBeansConfiguration.class);
    private final Properties properties = new Properties();
    private final Lock lock = new ReentrantLock();
    private final Set<Class<?>> ignoredInterfaces;

    public OpenWebBeansConfiguration(String configFilePath) {
        loadDefaultProperties(configFilePath);
        loadSystemProperties();
        ignoredInterfaces = new HashSet<>();
    }

    private void loadDefaultProperties(String configFilePath) {
        try (InputStream input = new FileInputStream(configFilePath)) {
            properties.load(input);
        } catch (IOException e) {
            logger.error("Failed to load properties from file: " + configFilePath, e);
        }
    }

    private void loadSystemProperties() {
        for (String key : System.getProperties().stringPropertyNames()) {
            properties.setProperty(key, System.getProperty(key));
        }
    }

    public String getProperty(String key) {
        lock.lock();
        try {
            return properties.getProperty(key);
        } finally {
            lock.unlock();
        }
    }

    public void setProperty(String key, String value) {
        lock.lock();
        try {
            properties.setProperty(key, value);
        } finally {
            lock.unlock();
        }
    }

    public boolean isJspApplication() {
        return Boolean.parseBoolean(getProperty("jsp.application"));
    }

    public boolean supportsConversations() {
        return Boolean.parseBoolean(getProperty("supports.conversations"));
    }

    public void addIgnoredInterface(Class<?> ignoredInterface) {
        lock.lock();
        try {
            ignoredInterfaces.add(ignoredInterface);
        } finally {
            lock.unlock();
        }
    }

    public Set<Class<?>> getIgnoredInterfaces() {
        lock.lock();
        try {
            return new HashSet<>(ignoredInterfaces);
        } finally {
            lock.unlock();
        }
    }
}

