public class IntrospectionSupport {

    public static Map<String, Object> getProperties(Object bean) {
        Map<String, Object> properties = new HashMap<>();
        try {
            for (PropertyDescriptor descriptor : java.beans.Introspector.getBeanInfo(bean.getClass()).getPropertyDescriptors()) {
                Method getter = descriptor.getReadMethod();
                if (getter != null) {
                    properties.put(descriptor.getName(), getter.invoke(bean));
                }
            }
        } catch (Exception e) {
            // Code smell: Catching generic Exception
            e.printStackTrace();
        }
        return properties;
    }

    public static void setProperties(Object bean, Map<String, Object> properties) {
        try {
            for (Map.Entry<String, Object> entry : properties.entrySet()) {
                PropertyDescriptor descriptor = new PropertyDescriptor(entry.getKey(), bean.getClass());
                Method setter = descriptor.getWriteMethod();
                if (setter != null) {
                    setter.invoke(bean, entry.getValue());
                }
            }
        } catch (Exception e) {
            // Code smell: Catching generic Exception
            e.printStackTrace();
        }
    }

    public static Map<String, Object> extractPropertiesWithPrefix(Object bean, String prefix) {
        Map<String, Object> properties = getProperties(bean);
        Map<String, Object> filteredProperties = new HashMap<>();
        for (String key : properties.keySet()) {
            if (key.startsWith(prefix)) {
                filteredProperties.put(key, properties.get(key));
            }
        }
        return filteredProperties;
    }

    public static String toString(Object bean) {
        StringBuilder sb = new StringBuilder();
        try {
            for (PropertyDescriptor descriptor : java.beans.Introspector.getBeanInfo(bean.getClass()).getPropertyDescriptors()) {
                Method getter = descriptor.getReadMethod();
                if (getter != null) {
                    sb.append(descriptor.getName()).append(": ").append(getter.invoke(bean)).append(", ");
                }
            }
        } catch (Exception e) {
            // Code smell: Catching generic Exception
            e.printStackTrace();
        }
        return sb.toString();
    }

    public static <T> T convertValue(Object value, Class<T> targetType) {
        if (value == null) {
            return null;
        }
        if (targetType.isInstance(value)) {
            return targetType.cast(value);
        }
        // Code smell: No specific handling for conversion
        return null;
    }
}

