public class Message extends HelixProperty {
    private String messageType;
    private String state;
    private long creationTime;
    private long lastUpdatedTime;
    private String sourceSessionId;
    private String targetSessionId;
    private String resourceName;
    private String partitionId;

    public static final String NEW = "NEW";
    public static final String READ = "READ";
    public static final String UNPROCESSABLE = "UNPROCESSABLE";

    public Message(String id) {
        super(id);
        this.creationTime = System.currentTimeMillis();
        this.state = NEW;
    }

    public String getMessageType() {
        return messageType;
    }

    public void setMessageType(String messageType) {
        this.messageType = messageType;
    }

    public String getState() {
        return state;
    }

    public void setState(String state) {
        if (isValidState(state)) {
            this.state = state;
            this.lastUpdatedTime = System.currentTimeMillis();
        }
    }

    public long getCreationTime() {
        return creationTime;
    }

    public long getLastUpdatedTime() {
        return lastUpdatedTime;
    }

    public String getSourceSessionId() {
        return sourceSessionId;
    }

    public void setSourceSessionId(String sourceSessionId) {
        this.sourceSessionId = sourceSessionId;
    }

    public String getTargetSessionId() {
        return targetSessionId;
    }

    public void setTargetSessionId(String targetSessionId) {
        this.targetSessionId = targetSessionId;
    }

    public String getResourceName() {
        return resourceName;
    }

    public void setResourceName(String resourceName) {
        this.resourceName = resourceName;
    }

    public String getPartitionId() {
        return partitionId;
    }

    public void setPartitionId(String partitionId) {
        this.partitionId = partitionId;
    }

    public Message createReplyMessage() {
        Message replyMessage = new Message(this.getId() + "_reply");
        replyMessage.setSourceSessionId(this.targetSessionId);
        replyMessage.setTargetSessionId(this.sourceSessionId);
        replyMessage.setResourceName(this.resourceName);
        replyMessage.setPartitionId(this.partitionId);
        replyMessage.setMessageType("REPLY");
        return replyMessage;
    }

    private boolean isValidState(String state) {
        return state.equals(NEW) || state.equals(READ) || state.equals(UNPROCESSABLE);
    }
}

