public class TreeIndex {
    private static final int PAGE_SIZE = 4096; // Default page size
    private static final int KEY_SIZE = 128; // Default key size
    private RandomAccessFile file;
    private long rootPage;
    private Set<Long> freePages;
    private boolean useCache;
    private Map<Long, byte[]> pageCache;

    public TreeIndex(String filename, boolean useCache) throws IOException {
        this.file = new RandomAccessFile(filename, "rw");
        this.freePages = new HashSet<>();
        this.useCache = useCache;
        this.pageCache = new HashMap<>();
        this.rootPage = -1; // Indicates no root page
    }

    public void load() throws IOException {
        // Load the index from the file
        file.seek(0);
        rootPage = file.readLong();
        // Load free pages
        int freePageCount = file.readInt();
        for (int i = 0; i < freePageCount; i++) {
            freePages.add(file.readLong());
        }
    }

    public void unload() throws IOException {
        // Unload the index to the file
        file.seek(0);
        file.writeLong(rootPage);
        file.writeInt(freePages.size());
        for (Long page : freePages) {
            file.writeLong(page);
        }
        file.close();
    }

    public void store(String key, byte[] value) throws IOException {
        // Store a key-value pair
        long page = allocatePage();
        byte[] pageData = new byte[PAGE_SIZE];
        System.arraycopy(key.getBytes(), 0, pageData, 0, Math.min(key.length(), KEY_SIZE));
        System.arraycopy(value, 0, pageData, KEY_SIZE, value.length);
        writePage(page, pageData);
    }

    public byte[] retrieve(String key) throws IOException {
        // Retrieve a value by key
        long page = findPageForKey(key);
        if (page == -1) return null;
        return readPage(page);
    }

    public void remove(String key) throws IOException {
        // Remove a key-value pair
        long page = findPageForKey(key);
        if (page != -1) {
            freePages.add(page);
        }
    }

    public void clear() throws IOException {
        // Clear all entries
        freePages.clear();
        rootPage = -1;
    }

    private long allocatePage() throws IOException {
        if (!freePages.isEmpty()) {
            return freePages.iterator().next();
        }
        return file.length() / PAGE_SIZE;
    }

    private void writePage(long page, byte[] data) throws IOException {
        file.seek(page * PAGE_SIZE);
        file.write(data);
        if (useCache) {
            pageCache.put(page, data);
        }
    }

    private byte[] readPage(long page) throws IOException {
        if (useCache && pageCache.containsKey(page)) {
            return pageCache.get(page);
        }
        byte[] data = new byte[PAGE_SIZE];
        file.seek(page * PAGE_SIZE);
        file.readFully(data);
        return data;
    }

    private long findPageForKey(String key) throws IOException {
        // Simplified search for the key
        for (long page = 0; page < file.length() / PAGE_SIZE; page++) {
            byte[] data = readPage(page);
            String storedKey = new String(data, 0, KEY_SIZE).trim();
            if (storedKey.equals(key)) {
                return page;
            }
        }
        return -1;
    }
}

