public class CubeMetaExtractor {
    private static final Logger logger = Logger.getLogger(CubeMetaExtractor.class.getName());
    private MetadataManager metadataManager;
    private ProjectManager projectManager;
    private String exportDirectory;
    private boolean includeSegments;
    private boolean includeJobInfo;
    private String cubeName;
    private String hybridName;
    private String storageType;
    private String engineType;

    public CubeMetaExtractor(MetadataManager metadataManager, ProjectManager projectManager, String exportDirectory) {
        this.metadataManager = metadataManager;
        this.projectManager = projectManager;
        this.exportDirectory = exportDirectory;
    }

    public void setIncludeSegments(boolean includeSegments) {
        this.includeSegments = includeSegments;
    }

    public void setIncludeJobInfo(boolean includeJobInfo) {
        this.includeJobInfo = includeJobInfo;
    }

    public void setCubeName(String cubeName) {
        this.cubeName = cubeName;
    }

    public void setHybridName(String hybridName) {
        this.hybridName = hybridName;
    }

    public void setStorageType(String storageType) {
        this.storageType = storageType;
    }

    public void setEngineType(String engineType) {
        this.engineType = engineType;
    }

    public void extract() {
        try {
            logger.info("Starting metadata extraction...");
            String metadata = gatherMetadata();
            saveMetadata(metadata);
            logger.info("Metadata extraction completed successfully.");
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error during metadata extraction", e);
        }
    }

    private String gatherMetadata() {
        StringBuilder metadataBuilder = new StringBuilder();
        if (cubeName != null) {
            metadataBuilder.append(metadataManager.getCubeMetadata(cubeName));
        }
        if (hybridName != null) {
            metadataBuilder.append(metadataManager.getHybridMetadata(hybridName));
        }
        if (includeSegments) {
            metadataBuilder.append(metadataManager.getSegmentsMetadata(cubeName));
        }
        if (includeJobInfo) {
            metadataBuilder.append(metadataManager.getJobMetadata(cubeName));
        }
        return metadataBuilder.toString();
    }

    private void saveMetadata(String metadata) throws IOException {
        File exportDir = new File(exportDirectory);
        if (!exportDir.exists()) {
            exportDir.mkdirs();
        }
        File metadataFile = new File(exportDir, "metadata.txt");
        try (FileWriter writer = new FileWriter(metadataFile)) {
            writer.write(metadata);
            if (storageType != null) {
                writer.write("\nStorage Type: " + storageType);
            }
            if (engineType != null) {
                writer.write("\nEngine Type: " + engineType);
            }
        }
        logger.info("Metadata saved to " + metadataFile.getAbsolutePath());
    }
}

