public class CachedModeledFrameworkImpl implements CachedModeledFramework {
    private ModeledFramework client;
    private ModeledCacheImpl cache;

    public CachedModeledFrameworkImpl(ModeledFramework client, ModeledCacheImpl cache) {
        this.client = client;
        this.cache = cache;
    }

    @Override
    public CompletableFuture<Model> readModel(String modelId) {
        return cache.getModel(modelId)
            .thenCompose(model -> {
                if (model != null) {
                    return CompletableFuture.completedFuture(model);
                } else {
                    return client.readModel(modelId)
                        .thenApply(fetchedModel -> {
                            cache.putModel(fetchedModel);
                            return fetchedModel;
                        });
                }
            });
    }

    @Override
    public CompletableFuture<Void> writeModel(Model model) {
        return client.writeModel(model)
            .thenRun(() -> cache.putModel(model));
    }

    @Override
    public CompletableFuture<Void> updateModel(Model model) {
        return client.updateModel(model)
            .thenRun(() -> cache.updateModel(model));
    }

    @Override
    public CompletableFuture<Void> deleteModel(String modelId) {
        return client.deleteModel(modelId)
            .thenRun(() -> cache.removeModel(modelId));
    }

    @Override
    public CompletableFuture<List<Model>> getAllModels() {
        return cache.getAllModels()
            .thenCompose(models -> {
                if (models.isEmpty()) {
                    return client.getAllModels()
                        .thenApply(fetchedModels -> {
                            cache.putAllModels(fetchedModels);
                            return fetchedModels;
                        });
                } else {
                    return CompletableFuture.completedFuture(models);
                }
            });
    }

    @Override
    public void addChangeListener(ChangeListener listener) {
        cache.addChangeListener(listener);
        client.addChangeListener(listener);
    }

    @Override
    public void removeChangeListener(ChangeListener listener) {
        cache.removeChangeListener(listener);
        client.removeChangeListener(listener);
    }

    @Override
    public CompletableFuture<Void> handleParentChildRelationship(String parentId, String childId) {
        return client.handleParentChildRelationship(parentId, childId)
            .thenRun(() -> cache.updateParentChildRelationship(parentId, childId));
    }

    @Override
    public CompletableFuture<Void> performTransaction(Transaction transaction) {
        return client.performTransaction(transaction)
            .thenRun(() -> cache.updateAfterTransaction(transaction));
    }
}

