class CharacterModel {
    public static final boolean SWITCH_OFF = false;

    public boolean isNormalizedNFC(String input) {
        if (SWITCH_OFF) return false;
        return Normalizer.isNormalized(input, Normalizer.Form.NFC);
    }

    public boolean startsWithComposingCharacter(String input) {
        if (SWITCH_OFF) return false;
        if (input == null || input.isEmpty()) return false;
        return isComposingCharacter(input.charAt(0));
    }

    public boolean isFullyNormalizedWithoutComposing(String input) {
        if (SWITCH_OFF) return false;
        return isNormalizedNFC(input) && !startsWithComposingCharacter(input);
    }

    public boolean isComposingCharacter(char character) {
        if (SWITCH_OFF) return false;
        return Character.UnicodeScript.of(character) == Character.UnicodeScript.COMMON ||
               (character >= 0x0300 && character <= 0x036F);
    }

    public boolean isCombiningCharacter(char character) {
        if (SWITCH_OFF) return false;
        return (character >= 0x0300 && character <= 0x036F) || 
               (character >= 0x1AB0 && character <= 0x1AFF) || 
               (character >= 0x1DC0 && character <= 0x1DFF);
    }
}

public abstract class AbstractValidatorAction extends AbstractComplementaryConfigurableAction implements Configurable {
    private static final Logger logger = Logger.getLogger(AbstractValidatorAction.class.getName());

    protected abstract Map<String, Object> createParameterMap();

    protected abstract boolean isStringEncoded(String parameter);

    public ValidationResult validateParameters() {
        Map<String, Object> parameters = createParameterMap();
        ValidationResult result = new ValidationResult();

        for (Map.Entry<String, Object> entry : parameters.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();

            if (value instanceof String) {
                validateString(key, (String) value, result);
            } else if (value instanceof Long) {
                validateLong(key, (Long) value, result);
            } else if (value instanceof Double) {
                validateDouble(key, (Double) value, result);
            } else {
                logger.warning("Unsupported data type for key: " + key);
                result.addError(key, "Unsupported data type");
            }
        }

        return result;
    }

    protected void validateString(String key, String value, ValidationResult result) {
