public class StandardWrapperValve {

    private long totalProcessingTime;
    private long requestCount;
    private long errorCount;
    private long maxProcessingTime;
    private long minProcessingTime = Long.MAX_VALUE;

    public void invoke(Request request, Response response) {
        long startTime = System.currentTimeMillis();
        try {
            if (!isServletContextAvailable() || !isServletAvailable()) {
                throw new ServletException("Servlet context or servlet not available");
            }
            // Process the request
            processRequest(request, response);
        } catch (Exception e) {
            errorCount++;
            logError(e);
        } finally {
            long processingTime = System.currentTimeMillis() - startTime;
            totalProcessingTime += processingTime;
            requestCount++;
            updateProcessingTimeStats(processingTime);
        }
    }

    private void processRequest(Request request, Response response) {
        // Logic to process the request
    }

    private boolean isServletContextAvailable() {
        // Check if servlet context is available
