public class ParallelBuildsManager {
    private final Queue<Project> buildQueue;
    private final Queue<Project> checkoutQueue;
    private final ExecutorService executorService;
    private final Map<Project, Future<?>> buildTasks;
    private final Map<Project, Future<?>> checkoutTasks;

    public ParallelBuildsManager(int maxConcurrentTasks) {
        this.buildQueue = new LinkedList<>();
        this.checkoutQueue = new LinkedList<>();
        this.executorService = Executors.newFixedThreadPool(maxConcurrentTasks);
        this.buildTasks = new ConcurrentHashMap<>();
        this.checkoutTasks = new ConcurrentHashMap<>();
    }

    public synchronized void addProjectToBuildQueue(Project project) {
        buildQueue.offer(project);
        processBuildQueue();
    }

    public synchronized void addProjectToCheckoutQueue(Project project) {
        checkoutQueue.offer(project);
        processCheckoutQueue();
    }

    public synchronized void cancelBuild(Project project) {
        Future<?> task = buildTasks.remove(project);
        if (task != null) {
            task.cancel(true);
        }
    }

    public synchronized void cancelCheckout(Project project) {
        Future<?> task = checkoutTasks.remove(project);
        if (task != null) {
            task.cancel(true);
        }
    }

    public synchronized String getBuildStatus(Project project) {
        return buildTasks.containsKey(project) ? "Building" : "Not Building";
    }

    public synchronized String getCheckoutStatus(Project project) {
        return checkoutTasks.containsKey(project) ? "Checking Out" : "Not Checking Out";
    }

    private void processBuildQueue() {
        while (!buildQueue.isEmpty()) {
            Project project = buildQueue.poll();
            if (project != null) {
                Future<?> task = executorService.submit(() -> {
                    // Simulate build process
                    project.build();
                    buildTasks.remove(project);
                });
                buildTasks.put(project, task);
            }
        }
    }

    private void processCheckoutQueue() {
        while (!checkoutQueue.isEmpty()) {
            Project project = checkoutQueue.poll();
            if (project != null) {
                Future<?> task = executorService.submit(() -> {
                    // Simulate checkout process
                    project.checkout();
                    checkoutTasks.remove(project);
                });
                checkoutTasks.put(project, task);
            }
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}

