public class CommandLineOptions {
    private String inputFormat;
    private String outputFormat;
    private boolean cacheEnabled;
    private Map<String, String> userDefinedConfigs;

    public CommandLineOptions() {
        userDefinedConfigs = new HashMap<>();
    }

    public void parseArguments(String[] args) {
        for (String arg : args) {
            if (arg.startsWith("--input=")) {
                inputFormat = arg.substring(8);
            } else if (arg.startsWith("--output=")) {
                outputFormat = arg.substring(9);
            } else if (arg.equals("--cache")) {
                cacheEnabled = true;
            } else {
                String[] config = arg.split("=");
                if (config.length == 2) {
                    userDefinedConfigs.put(config[0], config[1]);
                }
            }
        }
    }

    public void configureSettings() {
        // Code smells: Too many responsibilities in one method
        if (inputFormat == null || outputFormat == null) {
            throw new IllegalArgumentException("Input and output formats must be specified.");
        }
        // Additional configuration logic can be added here
    }

    public void validate() {
        // Code smells: Validation logic could be separated into its own method
        if (!isValidFormat(inputFormat)) {
            throw new IllegalArgumentException("Invalid input format: " + inputFormat);
        }
        if (!isValidFormat(outputFormat)) {
            throw new IllegalArgumentException("Invalid output format: " + outputFormat);
        }
    }

    private boolean isValidFormat(String format) {
        return format.equals("xml") || format.equals("fo") || format.equals("pdf") || format.equals("rtf") || format.equals("tiff");
    }

    public String getInputFormat() {
        return inputFormat;
    }

    public String getOutputFormat() {
        return outputFormat;
    }

    public boolean isCacheEnabled() {
        return cacheEnabled;
    }

    public Map<String, String> getUserDefinedConfigs() {
        return userDefinedConfigs;
    }
}

