public abstract class FSMainOperationsBaseTest extends FileSystemTestHelper {

    protected static final String TEST_DIR = "/testDir";
    protected static final String TEST_FILE = "/testDir/testFile.txt";
    protected static final String TEST_DIR_RENAME = "/testDirRenamed";
    protected static final String TEST_FILE_NON_EXISTENT = "/testDir/nonExistentFile.txt";

    protected FileSystem fs;

    @Before
    public void setUp() throws IOException {
        Configuration conf = new Configuration();
        fs = FileSystem.get(conf);
        setupTestDirectories();
    }

    protected void setupTestDirectories() throws IOException {
        fs.mkdirs(new Path(TEST_DIR));
        fs.create(new Path(TEST_FILE)).close();
    }

    @After
    public void tearDown() throws IOException {
        fs.delete(new Path(TEST_DIR), true);
    }

    @Test
    public void testCreateFile() throws IOException {
        fs.create(new Path(TEST_DIR + "/newFile.txt")).close();
        assertTrue(fs.exists(new Path(TEST_DIR + "/newFile.txt")));
    }

    @Test
    public void testReadFile() throws IOException {
        String content = "Hello, World!";
        fs.create(new Path(TEST_FILE)).write(content.getBytes());
        fs.close();

        byte[] buffer = new byte[content.length()];
        fs.open(new Path(TEST_FILE)).readFully(0, buffer);
        assertEquals(content, new String(buffer));
    }

    @Test
    public void testDeleteFile() throws IOException {
        fs.delete(new Path(TEST_FILE), false);
        assertFalse(fs.exists(new Path(TEST_FILE)));
    }

    @Test(expected = IOException.class)
    public void testReadNonExistentFile() throws IOException {
        fs.open(new Path(TEST_FILE_NON_EXISTENT));
    }

    @Test
    public void testRenameFile() throws IOException {
        fs.rename(new Path(TEST_FILE), new Path(TEST_DIR_RENAME + "/renamedFile.txt"));
        assertTrue(fs.exists(new Path(TEST_DIR_RENAME + "/renamedFile.txt")));
        assertFalse(fs.exists(new Path(TEST_FILE)));
    }

    @Test
    public void testGlobPattern() throws IOException {
        fs.create(new Path(TEST_DIR + "/file1.txt")).close();
        fs.create(new Path(TEST_DIR + "/file2.txt")).close();
        FileStatus[] statuses = fs.globStatus(new Path(TEST_DIR + "/*.txt"));
        assertEquals(2, statuses.length);
    }

    @Test
    public void testFileStatus() throws IOException {
        FileStatus status = fs.getFileStatus(new Path(TEST_FILE));
        assertEquals(TEST_FILE, status.getPath().toString());
        assertTrue(status.isFile());
    }
}

public class DoubleByteBuf extends AbstractReferenceCountedByteBuf {
    private final ByteBuf b1;
    private final ByteBuf b2;

    public DoubleByteBuf(ByteBuf b1, ByteBuf b2) {
        super(Integer.MAX_VALUE);
        this.b1 = b1;
        this.b2 = b2;
    }

    @Override
    public boolean isDirect() {
        return b1.isDirect() || b2.isDirect();
    }

    @Override
    public int capacity() {
        return b1.capacity() + b2.capacity();
    }

    @Override
    public int readableBytes() {
        return b1.readableBytes() + b2.readableBytes();
    }

    @Override
    protected byte _getByte(int index) {
        if (index < b1.readableBytes()) {
            return b1.getByte(index);
        } else {
            return b2.getByte(index - b1.readableBytes());
        }
    }

    @Override
    protected void _setByte(int index, int value) {
        throw new UnsupportedOperationException();
    }

    @Override
    protected void _setBytes(int index, ByteBuf src, int srcIndex, int length) {
        throw new UnsupportedOperationException();
    }

    @Override
    protected void _setBytes(int index, byte[] src, int srcIndex, int length) {
        throw new UnsupportedOperationException();
    }

    @Override
    protected void _setBytes(int index, ByteBuf src, int length) {
        throw new UnsupportedOperationException();
    }

    @Override
    protected void _setBytes(int index, byte[] src) {
        throw new UnsupportedOperationException();
    }

    @Override
    protected void _setBytes(int index, ByteBuf src) {
        throw new UnsupportedOperationException();
    }

    @Override
    protected void _readBytes(ByteBuf dst, int length) {
        if (length <= b1.readableBytes()) {
            b1.readBytes(dst, length);
        } else {
            int firstPart = b1.readableBytes();
            b1.readBytes(dst, firstPart);
            b2.readBytes(dst, length - firstPart);
        }
    }

    @Override
    protected void _writeBytes(ByteBuf src, int length) {
        throw new UnsupportedOperationException();
    }

    @Override
    protected void _writeBytes(byte[] src, int srcIndex, int length) {
