public class ElementHelper {

    public static boolean validateLabel(String label) {
        return label != null && !label.isEmpty() && !label.startsWith("_");
    }

    public static boolean validatePropertyKey(String key) {
        return key != null && !key.isEmpty() && !key.startsWith("_");
    }

    public static boolean validateMixedElementId(String id) {
        return id != null && !id.isEmpty();
    }

    public static void attachProperty(Map<String, Object> properties, String key, Object value) {
        if (validatePropertyKey(key)) {
            properties.put(key, value);
        }
    }

    public static void upsertProperty(Map<String, Object> properties, String key, Object value) {
        if (validatePropertyKey(key)) {
            properties.put(key, value);
        }
    }

    public static void replaceKey(Map<String, Object> properties, String oldKey, String newKey) {
        if (properties.containsKey(oldKey) && validatePropertyKey(newKey)) {
            Object value = properties.remove(oldKey);
            properties.put(newKey, value);
        }
    }

    public static Map<String, Object> getPropertiesAsMap(Map<String, Object> properties) {
        return new HashMap<>(properties);
    }

    public static List<Object> getPropertiesAsList(Map<String, Object> properties) {
        return List.copyOf(properties.values());
    }

    public static boolean compareElements(String id1, String id2) {
        return id1 != null && id1.equals(id2);
    }

    public static boolean compareProperties(Map<String, Object> properties1, Map<String, Object> properties2) {
        return properties1.equals(properties2);
    }

    public static boolean containsKey(Map<String, Object> properties, String key) {
        return properties.containsKey(key);
    }

    public static boolean containsId(List<String> ids, String id) {
        return ids.contains(id);
    }

    public static Map<String, Object> convertToMap(List<Map.Entry<String, Object>> entries) {
        Map<String, Object> map = new HashMap<>();
        for (Map.Entry<String, Object> entry : entries) {
            map.put(entry.getKey(), entry.getValue());
        }
        return map;
    }

    public static List<Object> convertToList(Map<String, Object> map) {
        return List.copyOf(map.values());
    }
}

public class PluginDescriptor {
    private String groupId;
    private String artifactId;
    private String version;
    private String goalPrefix;
    private List<MojoDescriptor> mojoDescriptors;
    private Map<String, MojoDescriptor> mojoDescriptorMap;
    private List<Artifact> artifacts;

    public PluginDescriptor() {
        this.mojoDescriptors = new ArrayList<>();
        this.mojoDescriptorMap = new HashMap<>();
        this.artifacts = new ArrayList<>();
    }

    public String getGroupId() {
        return groupId;
    }

    public void setGroupId(String groupId) {
        this.groupId = groupId;
    }

    public String getArtifactId() {
        return artifactId;
    }

    public void setArtifactId(String artifactId) {
        this.artifactId = artifactId;
    }

    public String getVersion() {
        return version;
    }

    public void setVersion(String version) {
        this.version = version;
    }

    public String getGoalPrefix() {
        return goalPrefix;
    }

    public void setGoalPrefix(String goalPrefix) {
        this.goalPrefix = goalPrefix;
    }

    public List<MojoDescriptor> getMojoDescriptors() {
        return new ArrayList<>(mojoDescriptors);
    }

    public void addMojoDescriptor(MojoDescriptor mojoDescriptor) {
        if (!mojoDescriptorMap.containsKey(mojoDescriptor.getGoal())) {
            mojoDescriptors.add(mojoDescriptor);
            mojoDescriptorMap.put(mojoDescriptor.getGoal(), mojoDescriptor);
        }
    }

    public List<Artifact> getArtifacts() {
        return new ArrayList<>(artifacts);
    }

    public void addArtifact(Artifact artifact) {
        artifacts.add(artifact);
    }

    public PluginDescriptor clone() {
        PluginDescriptor cloned = new PluginDescriptor();
        cloned.setGroupId(this.groupId);
        cloned.setArtifactId(this.artifactId);
        cloned.setVersion(this.version);
        cloned.setGoalPrefix(this.goalPrefix);
        for (MojoDescriptor mojo : this.mojoDescriptors) {
            cloned.addMojoDescriptor(mojo.clone());
        }
        for (Artifact artifact : this.artifacts) {
            cloned.addArtifact(artifact.clone());
        }
        return cloned;
    }
}

