public class UrlTest {

    @Test
    public void testParseAbsoluteUrl() {
        Url url = new Url("https://www.example.com:8080/path/to/resource?query=param#fragment");
        assertEquals("https", url.getProtocol());
        assertEquals("www.example.com", url.getHost());
        assertEquals(8080, url.getPort());
        assertEquals("/path/to/resource", url.getPath());
        assertEquals("query=param", url.getQuery());
        assertEquals("fragment", url.getFragment());
    }

    @Test
    public void testParseRelativeUrl() {
        Url url = new Url("/path/to/resource?query=param#fragment");
        assertNull(url.getProtocol());
        assertNull(url.getHost());
        assertEquals("/path/to/resource", url.getPath());
        assertEquals("query=param", url.getQuery());
        assertEquals("fragment", url.getFragment());
    }

    @Test
    public void testEncodeSpecialCharacters() {
        Url url = new Url("https://www.example.com/path/to/resource?query=param with spaces");
        String encodedUrl = url.encode();
        assertTrue(encodedUrl.contains("%20"));
    }

    @Test
    public void testDecodeSpecialCharacters() {
        Url url = new Url("https://www.example.com/path/to/resource?query=param%20with%20spaces");
        assertEquals("param with spaces", url.getQueryParameter("query"));
    }

    @Test
    public void testEmptySegments() {
        Url url = new Url("https://www.example.com//path//to//resource");
        assertEquals("/path/to/resource", url.getPath());
    }

    @Test
    public void testMalformedUrl() {
        assertThrows(IllegalArgumentException.class, () -> {
            new Url("htp://invalid-url");
        });
    }

    @Test
    public void testAddQueryParameter() {
        Url url = new Url("https://www.example.com/path");
        url.addQueryParameter("key", "value");
        assertEquals("key=value", url.getQuery());
    }

    @Test
    public void testRemoveQueryParameter() {
        Url url = new Url("https://www.example.com/path?key=value&key2=value2");
        url.removeQueryParameter("key");
        assertEquals("key2=value2", url.getQuery());
    }

    @Test
    public void testGetPathSegments() {
        Url url = new Url("https://www.example.com/path/to/resource");
        String[] segments = url.getPathSegments();
        assertArrayEquals(new String[]{"path", "to", "resource"}, segments);
    }

    @Test
    public void testFragmentHandling() {
        Url url = new Url("https://www.example.com/path#section");
        assertEquals("section", url.getFragment());
    }

    @Test
    public void testPortHandling() {
        Url url = new Url("https://www.example.com:3000/path");
        assertEquals(3000, url.getPort());
    }

    @Test
    public void testDefaultPortForHttp() {
        Url url = new Url("http://www.example.com/path");
        assertEquals(80, url.getPort());
    }

    @Test
    public void testDefaultPortForHttps() {
        Url url = new Url("https://www.example.com/path");
        assertEquals(443, url.getPort());
    }
}

