class BasicHttpFilterAuthenticationTest {

    private BasicHttpAuthenticationFilter filter = new BasicHttpAuthenticationFilter();

    @Test
    public void testCreateToken_NoAuthorizationHeader() {
        HttpServletRequest request = createMockRequest(null);
        assertThrows(IllegalArgumentException.class, () -> filter.createToken(request));
    }

    @Test
    public void testCreateToken_NoUsername() {
        HttpServletRequest request = createMockRequest("Basic " + encodeBase64(":password"));
        assertThrows(IllegalArgumentException.class, () -> filter.createToken(request));
    }

    @Test
    public void testCreateToken_NoPassword() {
        HttpServletRequest request = createMockRequest("Basic " + encodeBase64("username:"));
        assertThrows(IllegalArgumentException.class, () -> filter.createToken(request));
    }

    @Test
    public void testCreateToken_PasswordContainsColon() {
        HttpServletRequest request = createMockRequest("Basic " + encodeBase64("username:pass:word"));
        String token = filter.createToken(request);
        assertNotNull(token);
        assertEquals("username:pass:word", decodeToken(token));
    }

    @Test
    public void testIsAccessAllowed_MethodRequiresAuth() {
        HttpServletRequest request = createMockRequest("GET");
        assertFalse(filter.isAccessAllowed(request));
    }

    @Test
    public void testIsAccessAllowed_MethodDoesNotRequireAuth() {
        HttpServletRequest request = createMockRequest("OPTIONS");
        assertTrue(filter.isAccessAllowed(request));
    }

    private HttpServletRequest createMockRequest(String authHeader) {
        HttpServletRequest request = org.mockito.Mockito.mock(HttpServletRequest.class);
        org.mockito.Mockito.when(request.getHeader("Authorization")).thenReturn(authHeader);
        return request;
    }

    private HttpServletRequest createMockRequest(String method) {
        HttpServletRequest request = org.mockito.Mockito.mock(HttpServletRequest.class);
        org.mockito.Mockito.when(request.getMethod()).thenReturn(method);
        return request;
    }

    private String encodeBase64(String value) {
        return java.util.Base64.getEncoder().encodeToString(value.getBytes());
    }

    private String decodeToken(String token) {
        String decoded = new String(java.util.Base64.getDecoder().decode(token));
        return decoded;
    }
}

