public class SimpleAccount implements Account, MergableAuthenticationInfo, SaltedAuthenticationInfo, Serializable {
    private static final long serialVersionUID = 1L;

    private Object principal;
    private Object credentials;
    private Collection<String> roles;
    private Collection<String> permissions;
    private boolean locked;
    private boolean credentialsExpired;

    public SimpleAccount(Object principal, Object credentials) {
        this(principal, credentials, new HashSet<>(), new HashSet<>(), false, false);
    }

    public SimpleAccount(Object principal, Object credentials, Collection<String> roles) {
        this(principal, credentials, roles, new HashSet<>(), false, false);
    }

    public SimpleAccount(Object principal, Object credentials, Collection<String> roles, Collection<String> permissions) {
        this(principal, credentials, roles, permissions, false, false);
    }

    public SimpleAccount(Object principal, Object credentials, Collection<String> roles, Collection<String> permissions, boolean locked, boolean credentialsExpired) {
        this.principal = principal;
        this.credentials = credentials;
        this.roles = roles;
        this.permissions = permissions;
        this.locked = locked;
        this.credentialsExpired = credentialsExpired;
    }

    public Object getPrincipal() {
        return principal;
    }

    public Object getCredentials() {
        return credentials;
    }

    public Collection<String> getRoles() {
        return roles;
    }

    public Collection<String> getPermissions() {
        return permissions;
    }

    public boolean isLocked() {
        return locked;
    }

    public boolean isCredentialsExpired() {
        return credentialsExpired;
    }

    public void setLocked(boolean locked) {
        this.locked = locked;
    }

    public void setCredentialsExpired(boolean credentialsExpired) {
        this.credentialsExpired = credentialsExpired;
    }

    public void merge(MergableAuthenticationInfo other) {
        if (other instanceof SimpleAccount) {
            SimpleAccount otherAccount = (SimpleAccount) other;
            this.roles.addAll(otherAccount.getRoles());
            this.permissions.addAll(otherAccount.getPermissions());
            this.locked = this.locked || otherAccount.isLocked();
            this.credentialsExpired = this.credentialsExpired || otherAccount.isCredentialsExpired();
        }
    }

    @Override
    public int hashCode() {
        return Objects.hash(principal, credentials, roles, permissions, locked, credentialsExpired);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof SimpleAccount)) return false;
        SimpleAccount other = (SimpleAccount) obj;
        return Objects.equals(principal, other.principal) &&
               Objects.equals(credentials, other.credentials) &&
               Objects.equals(roles, other.roles) &&
               Objects.equals(permissions, other.permissions) &&
               locked == other.locked &&
               credentialsExpired == other.credentialsExpired;
    }

    @Override
    public String toString() {
        return "SimpleAccount{" +
               "principal=" + principal +
               ", credentials=" + credentials +
               ", roles=" + roles +
               ", permissions=" + permissions +
               ", locked=" + locked +
               ", credentialsExpired=" + credentialsExpired +
               '}';
    }
}

