public class SimpleCharStream {
    private char[] buffer;
    private int bufferSize;
    private int bufferPosition;
    private int line;
    private int column;
    private Reader reader;

    public SimpleCharStream(Reader reader, int bufferSize) {
        this.reader = reader;
        this.bufferSize = bufferSize;
        this.buffer = new char[bufferSize];
        this.bufferPosition = 0;
        this.line = 1;
        this.column = 0;
        fillBuffer();
    }

    private void fillBuffer() {
        try {
            int charsRead = reader.read(buffer);
            if (charsRead == -1) {
                buffer[0] = '\0'; // End of stream
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public char readChar() {
        if (bufferPosition >= buffer.length) {
            fillBuffer();
            bufferPosition = 0;
        }
        char c = buffer[bufferPosition++];
        if (c == '\n') {
            line++;
            column = 0;
        } else {
            column++;
        }
        return c;
    }

    public String getCurrentTokenImage() {
        return new String(buffer, 0, bufferPosition);
    }

    public void backtrack(int steps) {
        bufferPosition -= steps;
        if (bufferPosition < 0) {
            bufferPosition = 0;
        }
    }

    public void reinitialize(Reader newReader, int newBufferSize) {
        this.reader = newReader;
        this.bufferSize = newBufferSize;
        this.buffer = new char[newBufferSize];
        this.bufferPosition = 0;
        this.line = 1;
        this.column = 0;
        fillBuffer();
    }

    public int getLine() {
        return line;
    }

    public int getColumn() {
        return column;
    }
}

