public class Frame {
    public static final int INT_TYPE = 0;
    public static final int FLOAT_TYPE = 1;
    public static final int DOUBLE_TYPE = 2;
    public static final int LONG_TYPE = 3;
    public static final int OBJECT_TYPE = 4;

    private Object[] localVariables;
    private Stack<Object> operandStack;

    public Frame(int maxLocals) {
        this.localVariables = new Object[maxLocals];
        this.operandStack = new Stack<>();
    }

    public void setLocalVariable(int index, Object value) {
        if (index < 0 || index >= localVariables.length) {
            throw new IndexOutOfBoundsException("Invalid local variable index");
        }
        localVariables[index] = value;
    }

    public Object getLocalVariable(int index) {
        if (index < 0 || index >= localVariables.length) {
            throw new IndexOutOfBoundsException("Invalid local variable index");
        }
        return localVariables[index];
    }

    public void push(Object value) {
        operandStack.push(value);
    }

    public Object pop() {
        if (operandStack.isEmpty()) {
            throw new EmptyStackException();
        }
        return operandStack.pop();
    }

    public void merge(Frame other) {
