    private List<NetworkConnector> networkConnectors;
    private List<JmsConnector> jmsConnectors;
    private JmxManagement jmxManagement;
    private PersistenceAdapter persistenceAdapter;
    private Statistics statistics;
    private SystemUsage systemUsage;

    public BrokerService() {
        this.transportConnectors = new ArrayList<>();
        this.networkConnectors = new ArrayList<>();
        this.jmsConnectors = new ArrayList<>();
        this.jmxManagement = new JmxManagement();
        this.persistenceAdapter = new PersistenceAdapter();
        this.statistics = new Statistics();
        this.systemUsage = new SystemUsage();
        this.isRunning = false;
    }

    public void start() {
        if (isRunning) {
            return; // Code smell: early return could be improved with logging
        }
        // Start transport connectors
        for (TransportConnector connector : transportConnectors) {
            connector.start();
        }
        // Start network connectors
        for (NetworkConnector connector : networkConnectors) {
            connector.start();
        }
        // Start JMS connectors
        for (JmsConnector connector : jmsConnectors) {
            connector.start();
        }
        isRunning = true;
    }

    public void stop() {
        if (!isRunning) {
            return; // Code smell: early return could be improved with logging
        }
        // Stop JMS connectors
        for (JmsConnector connector : jmsConnectors) {
            connector.stop();
        }
        // Stop network connectors
        for (NetworkConnector connector : networkConnectors) {
            connector.stop();
        }
        // Stop transport connectors
        for (TransportConnector connector : transportConnectors) {
            connector.stop();
        }
        isRunning = false;
    }

