public class SimplePerceptronSequenceTrainer extends AbstractEventModelSequenceTrainer {
    private int iterations;
    private List<EventSequence> eventSequences;
    private List<Integer> outcomes;
    private boolean useAverageParameters;
    private double[] weights;
    private double[] averageWeights;
    private int weightUpdateCount;

    public SimplePerceptronSequenceTrainer(int iterations, boolean useAverageParameters) {
        this.iterations = iterations;
        this.useAverageParameters = useAverageParameters;
        this.weightUpdateCount = 0;
    }

    @Override
    public void validateTrainingConfiguration() {
        if (eventSequences == null || eventSequences.isEmpty()) {
            throw new IllegalArgumentException("Event sequences cannot be null or empty.");
        }
        if (outcomes == null || outcomes.size() != eventSequences.size()) {
            throw new IllegalArgumentException("Outcomes must match the number of event sequences.");
        }
        // Additional validation logic can be added here
    }

    @Override
    public void train() {
        initializeWeights();
        for (int i = 0; i < iterations; i++) {
            for (int j = 0; j < eventSequences.size(); j++) {
                EventSequence sequence = eventSequences.get(j);
                int predicted = predict(sequence);
                int actual = outcomes.get(j);
                updateWeights(sequence, predicted, actual);
            }
        }
        if (useAverageParameters) {
            finalizeAverageWeights();
        }
    }

    private void initializeWeights() {
        int featureSize = getFeatureSize();
        weights = new double[featureSize];
        averageWeights = new double[featureSize];
    }

    private int predict(EventSequence sequence) {
        double activation = 0.0;
        for (int i = 0; i < sequence.getFeatures().length; i++) {
            activation += weights[i] * sequence.getFeatures()[i];
        }
        return activation >= 0 ? 1 : 0; // Binary classification
    }

    private void updateWeights(EventSequence sequence, int predicted, int actual) {
        int error = actual - predicted;
        for (int i = 0; i < sequence.getFeatures().length; i++) {
            weights[i] += error * sequence.getFeatures()[i];
            if (useAverageParameters) {
                averageWeights[i] += weights[i];
            }
        }
        weightUpdateCount++;
    }

    private void finalizeAverageWeights() {
        for (int i = 0; i < averageWeights.length; i++) {
            averageWeights[i] /= weightUpdateCount;
        }
        weights = averageWeights; // Use average weights as final weights
    }

    public void setEventSequences(List<EventSequence> eventSequences) {
        this.eventSequences = eventSequences;
    }

    public void setOutcomes(List<Integer> outcomes) {
        this.outcomes = outcomes;
    }

    public double[] getWeights() {
        return weights;
    }
}

