public class PolicyAnnotationListener implements FactoryBeanListener {
    private Map<String, Policy> policies = new HashMap<>();

    @Override
    public void onEvent(Event event) {
        switch (event.getType()) {
            case INTERFACE_CREATED:
                handleInterfaceCreated(event);
                break;
            case ENDPOINT_SELECTED:
                handleEndpointSelected(event);
                break;
            case SERVER_CREATED:
                handleServerCreated(event);
                break;
            case INTERFACE_OPERATION_BOUND:
                handleInterfaceOperationBound(event);
                break;
            default:
                break;
        }
    }

    private void handleInterfaceCreated(Event event) {
        // Logic to handle interface creation
        Class<?> serviceInterface = event.getServiceInterface();
        addPoliciesFromAnnotations(serviceInterface);
    }

    private void handleEndpointSelected(Event event) {
        // Logic to handle endpoint selection
        Endpoint endpoint = event.getEndpoint();
        addPoliciesFromAnnotations(endpoint.getClass());
    }

    private void handleServerCreated(Event event) {
        // Logic to handle server creation
        Server server = event.getServer();
        addPoliciesFromAnnotations(server.getClass());
    }

    private void handleInterfaceOperationBound(Event event) {
        // Logic to handle operation binding
        Method operation = event.getOperation();
        addPoliciesFromAnnotations(operation);
    }

    private void addPoliciesFromAnnotations(AnnotatedElement element) {
        Policy policy = element.getAnnotation(Policy.class);
        Policies policiesAnnotation = element.getAnnotation(Policies.class);

        if (policy != null) {
            addPolicy(policy);
        }

        if (policiesAnnotation != null) {
            for (Policy p : policiesAnnotation.value()) {
                addPolicy(p);
            }
        }
    }

    private void addPolicy(Policy policy) {
        String key = generatePolicyKey(policy);
        if (!policies.containsKey(key)) {
            policies.put(key, policy);
        }
    }

    private String generatePolicyKey(Policy policy) {
        // Generate a unique key for the policy based on its attributes
        return policy.name() + ":" + policy.scope();
    }
}

