class QuaternionTest {

    @Test
    void testAccessorMethods() {
        Quaternion q = new Quaternion(1, 2, 3, 4);
        assertEquals(1, q.getScalarPart());
        assertArrayEquals(new double[]{2, 3, 4}, q.getVectorPart());
    }

    @Test
    void testConjugate() {
        Quaternion q = new Quaternion(1, 2, 3, 4);
        Quaternion conjugate = q.conjugate();
        assertEquals(1, conjugate.getScalarPart());
        assertArrayEquals(new double[]{-2, -3, -4}, conjugate.getVectorPart());
    }

    @Test
    void testQuaternionMultiplication() {
        Quaternion q1 = new Quaternion(1, 2, 3, 4);
        Quaternion q2 = new Quaternion(5, 6, 7, 8);
        Quaternion result = q1.multiply(q2);
        assertEquals(-60, result.getScalarPart());
        assertArrayEquals(new double[]{12, 30, 24}, result.getVectorPart());
    }

    @Test
    void testQuaternionVectorMultiplication() {
        Quaternion q = new Quaternion(1, 2, 3, 4);
        double[] vector = {1, 0, 0};
        double[] result = q.multiplyVector(vector);
        assertArrayEquals(new double[]{1, 4, -3}, result);
    }

    @Test
    void testDotProduct() {
        Quaternion q1 = new Quaternion(1, 2, 3, 4);
        Quaternion q2 = new Quaternion(5, 6, 7, 8);
        double dotProduct = q1.dot(q2);
        assertEquals(70, dotProduct);
    }

    @Test
    void testScalarMultiplication() {
        Quaternion q = new Quaternion(1, 2, 3, 4);
        Quaternion result = q.multiply(2);
        assertEquals(2, result.getScalarPart());
        assertArrayEquals(new double[]{4, 6, 8}, result.getVectorPart());
    }

    @Test
    void testAddition() {
        Quaternion q1 = new Quaternion(1, 2, 3, 4);
        Quaternion q2 = new Quaternion(5, 6, 7, 8);
        Quaternion result = q1.add(q2);
        assertEquals(6, result.getScalarPart());
        assertArrayEquals(new double[]{8, 9, 11}, result.getVectorPart());
    }

    @Test
    void testSubtraction() {
        Quaternion q1 = new Quaternion(5, 6, 7, 8);
        Quaternion q2 = new Quaternion(1, 2, 3, 4);
        Quaternion result = q1.subtract(q2);
        assertEquals(4, result.getScalarPart());
        assertArrayEquals(new double[]{4, 5, 5}, result.getVectorPart());
    }

    @Test
    void testNorm() {
        Quaternion q = new Quaternion(1, 2, 3, 4);
        double norm = q.norm();
        assertEquals(Math.sqrt(30), norm, 1e-10);
    }

    @Test
    void testNormalization() {
        Quaternion q = new Quaternion(1, 2, 3, 4);
        Quaternion normalized = q.normalize();
        assertEquals(1, normalized.norm(), 1e-10);
    }

    @Test
    void testEquality() {
        Quaternion q1 = new Quaternion(1, 2, 3, 4);
        Quaternion q2 = new Quaternion(1, 2, 3, 4);
        assertTrue(q1.equals(q2));
    }

    @Test
    void testEqualityWithTolerance() {
        Quaternion q1 = new Quaternion(1.00001, 2, 3, 4);
        Quaternion q2 = new Quaternion(1, 2, 3, 4);
        assertTrue(q1.equals(q2, 0.0001));
    }

    @Test
    void testIsUnitQuaternion() {
        Quaternion q = new Quaternion(0, 1, 0, 0);
        assertTrue(q.isUnitQuaternion());
    }

    @Test
    void testIsPureQuaternion() {
        Quaternion q = new Quaternion(0, 1, 2, 3);
        assertTrue(q.isPureQuaternion());
    }

    @Test
    void testToPolarForm() {
        Quaternion q = new Quaternion(1, 2, 3, 4);
        PolarForm polar = q.toPolarForm();
        assertNotNull(polar);
    }

    @Test
    void testInverse() {
        Quaternion q = new Quaternion(1, 2, 3, 4);
        Quaternion inverse = q.inverse();
        assertEquals(0.033333, inverse.getScalarPart(), 1e-6);
        assertArrayEquals(new double[]{-0.066667, -0.1, -0.13333}, inverse.getVectorPart(), 1e-6);
    }

    @Test
    void testStringRepresentation() {
        Quaternion q = new Quaternion(1, 2, 3, 4);
        assertEquals("1.0 + 2.0i + 3.0j + 4.0k", q.toString());
    }
}

