public class TaggedValue extends BasicValue {
    public enum Tag {
        REGULAR, INPUT, CONTAINER, INT_CONSTANT
    }

    public enum Input {
        TEXT, NUMBER, BOOLEAN
    }

    private Tag tag;
    private Input input;
    private String flatFieldExpr;
    private Map<String, TaggedValue> containers = new HashMap<>();
    private Map<String, String> frames = new HashMap<>();

    public TaggedValue(Tag tag, Input input, String flatFieldExpr) {
        this.tag = tag;
        this.input = input;
        this.flatFieldExpr = flatFieldExpr;
    }

    public Tag getTag() {
        return tag;
    }

    public Input getInput() {
        return input;
    }

    public String getFlatFieldExpr() {
        return flatFieldExpr;
    }

    public void addContainer(String key, TaggedValue value) {
        containers.put(key, value);
    }

    public TaggedValue getContainer(String key) {
        return containers.get(key);
    }

    public void addFrame(String key, String value) {
        frames.put(key, value);
    }

    public String getFrame(String key) {
        return frames.get(key);
    }

    public boolean isRegular() {
        return tag == Tag.REGULAR;
    }

    public boolean isInput() {
        return tag == Tag.INPUT;
    }

    public boolean isContainer() {
        return tag == Tag.CONTAINER;
    }

    public boolean isIntConstant() {
        return tag == Tag.INT_CONSTANT;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof TaggedValue)) return false;
        TaggedValue that = (TaggedValue) o;
        return tag == that.tag &&
                input == that.input &&
                Objects.equals(flatFieldExpr, that.flatFieldExpr) &&
                Objects.equals(containers, that.containers) &&
                Objects.equals(frames, that.frames);
    }

    @Override
    public int hashCode() {
        return Objects.hash(tag, input, flatFieldExpr, containers, frames);
    }

    @Override
    public String toString() {
        return "TaggedValue{" +
                "tag=" + tag +
                ", input=" + input +
                ", flatFieldExpr='" + flatFieldExpr + '\'' +
                ", containers=" + containers +
                ", frames=" + frames +
                '}';
    }

    public TaggedValue copy() {
        TaggedValue copy = new TaggedValue(tag, input, flatFieldExpr);
        copy.containers.putAll(this.containers);
        copy.frames.putAll(this.frames);
        return copy;
    }
}

