public class StandardProcessScheduler implements ProcessScheduler {
    private final ScheduledExecutorService executorService;
    private final Map<String, ComponentState> componentStates;

    public StandardProcessScheduler() {
        this.executorService = Executors.newScheduledThreadPool(10);
        this.componentStates = new HashMap<>();
    }

    @Override
    public void startComponent(String componentId) {
        if (componentStates.get(componentId) == ComponentState.STOPPED) {
            // Code smell: No validation for component existence
            executorService.schedule(() -> {
                // Start logic
                componentStates.put(componentId, ComponentState.RUNNING);
            }, 0, TimeUnit.SECONDS);
        }
    }

    @Override
    public void stopComponent(String componentId) {
        if (componentStates.get(componentId) == ComponentState.RUNNING) {
            // Code smell: No validation for component existence
            executorService.schedule(() -> {
                // Stop logic
                componentStates.put(componentId, ComponentState.STOPPED);
            }, 0, TimeUnit.SECONDS);
        }
    }

    @Override
    public void enableComponent(String componentId) {
        // Code smell: No validation for component existence
        componentStates.put(componentId, ComponentState.ENABLED);
    }

    @Override
    public void disableComponent(String componentId) {
        // Code smell: No validation for component existence
        componentStates.put(componentId, ComponentState.DISABLED);
    }

    @Override
    public void handleError(String componentId, Exception e) {
        // Code smell: No logging or error handling strategy
        System.err.println("Error in component " + componentId + ": " + e.getMessage());
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    private enum ComponentState {
        RUNNING,
        STOPPED,
        ENABLED,
        DISABLED
    }
}

