public class ArrayFieldVector<T extends FieldElement<T>> implements FieldVector<T>, Serializable {
    private static final long serialVersionUID = 1L;
    private final T[] data;

    public ArrayFieldVector(T[] data) {
        this.data = Arrays.copyOf(data, data.length);
    }

    public ArrayFieldVector(ArrayFieldVector<T> vector) {
        this.data = Arrays.copyOf(vector.data, vector.data.length);
    }

    public ArrayFieldVector(int dimension) {
        this.data = (T[]) new FieldElement[dimension];
        for (int i = 0; i < dimension; i++) {
            data[i] = null; // Code smell: using null to represent uninitialized elements
        }
    }

    public T getEntry(int index) {
        if (index < 0 || index >= data.length) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + data.length);
        }
        return data[index];
    }

    public void setEntry(int index, T value) {
        if (index < 0 || index >= data.length) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + data.length);
        }
        data[index] = value;
    }

    public ArrayFieldVector<T> add(ArrayFieldVector<T> other) {
        if (other.data.length != this.data.length) {
            throw new DimensionMismatchException(this.data.length, other.data.length);
        }
        T[] result = (T[]) new FieldElement[this.data.length];
        for (int i = 0; i < data.length; i++) {
            result[i] = this.data[i].add(other.data[i]);
        }
        return new ArrayFieldVector<>(result);
    }

    public ArrayFieldVector<T> subtract(ArrayFieldVector<T> other) {
        if (other.data.length != this.data.length) {
            throw new DimensionMismatchException(this.data.length, other.data.length);
        }
        T[] result = (T[]) new FieldElement[this.data.length];
        for (int i = 0; i < data.length; i++) {
            result[i] = this.data[i].subtract(other.data[i]);
        }
        return new ArrayFieldVector<>(result);
    }

    public ArrayFieldVector<T> scalarMultiply(T scalar) {
        T[] result = (T[]) new FieldElement[this.data.length];
        for (int i = 0; i < data.length; i++) {
            result[i] = this.data[i].multiply(scalar);
        }
        return new ArrayFieldVector<>(result);
    }

    public T dotProduct(ArrayFieldVector<T> other) {
        if (other.data.length != this.data.length) {
            throw new DimensionMismatchException(this.data.length, other.data.length);
        }
        T sum = other.data[0].getField().getZero(); // Code smell: initializing sum with zero
        for (int i = 0; i < data.length; i++) {
            sum = sum.add(this.data[i].multiply(other.data[i]));
        }
        return sum;
    }

    public ArrayFieldVector<T> getSubVector(int index, int n) {
        if (index < 0 || index + n > data.length) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + data.length);
        }
        T[] subVector = (T[]) new FieldElement[n];
        System.arraycopy(data, index, subVector, 0, n);
        return new ArrayFieldVector<>(subVector);
    }

    public ArrayFieldVector<T> append(T value) {
        T[] newData = Arrays.copyOf(data, data.length + 1);
        newData[data.length] = value;
        return new ArrayFieldVector<>(newData);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof ArrayFieldVector)) return false;
        ArrayFieldVector<?> other = (ArrayFieldVector<?>) obj;
        return Arrays.equals(data, other.data);
    }

    @Override
    public int hashCode() {
        return Arrays.hashCode(data);
    }
}

