public class JmsProducerClient extends AbstractJmsMeasurableClient {
    private static final Logger logger = LoggerFactory.getLogger(JmsProducerClient.class);
    private Connection connection;
    private Session session;
    private MessageProducer producer;
    private String destinationName;
    private int messageCount;
    private long duration;
    private boolean persistent;
    private int messageSize;

    public JmsProducerClient(String destinationName, int messageCount, long duration, boolean persistent, int messageSize) {
        this.destinationName = destinationName;
        this.messageCount = messageCount;
        this.duration = duration;
        this.persistent = persistent;
        this.messageSize = messageSize;
    }

    public void start() throws JMSException {
        ConnectionFactory factory = createConnectionFactory();
        connection = factory.createConnection();
        session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        Destination destination = session.createQueue(destinationName);
        producer = session.createProducer(destination);
        producer.setDeliveryMode(persistent ? DeliveryMode.PERSISTENT : DeliveryMode.NON_PERSISTENT);
        connection.start();
        sendMessages();
    }

    private void sendMessages() {
        long startTime = System.currentTimeMillis();
        int sentMessages = 0;

        try {
            while (sentMessages < messageCount && (System.currentTimeMillis() - startTime) < duration) {
                TextMessage message = createTextMessage();
                producer.send(message);
                sentMessages++;
                logger.info("Sent message: {}", message.getText());
                Thread.sleep(100); // Simulate delay
            }
        } catch (JMSException | InterruptedException e) {
            logger.error("Error sending messages", e);
        } finally {
            cleanup();
        }
    }

    private TextMessage createTextMessage() throws JMSException {
        StringBuilder messageContent = new StringBuilder();
        for (int i = 0; i < messageSize; i++) {
            messageContent.append("A");
        }
