public class GermanStemmer extends SnowballProgram {
    private static final String[] suffixes = { "en", "e", "er", "es", "s", "em", "e", "n" };
    private String word;
    private int currentIndex;

    public GermanStemmer() {
        this.word = "";
        this.currentIndex = 0;
    }

    public void setCurrent(String word) {
        this.word = word;
        this.currentIndex = word.length();
    }

    public String getCurrent() {
        return word;
    }

    public boolean stem() {
        if (currentIndex == 0) return false;
        markRegions();
        applySuffixRemoval();
        return true;
    }

    private void markRegions() {
        // Logic to mark regions of interest in the word
        // This could be a code smell if not properly implemented
    }

    private void applySuffixRemoval() {
        for (String suffix : suffixes) {
            if (word.endsWith(suffix)) {
                word = word.substring(0, word.length() - suffix.length());
                break; // Avoid removing multiple suffixes
            }
        }
    }
}

