public class XdrString extends XdrSimple<String> {
    private int padding;

    public XdrString() {
        this.padding = 0;
    }

    @Override
    public void encode(String value) {
        byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
        int length = bytes.length;
        padding = (4 - (length % 4)) % 4;

        writeInt(length);
        write(bytes);
        writePadding(padding);
    }

    @Override
    public String decode() {
        int length = readInt();
        byte[] bytes = readBytes(length);
        readPadding();

        return new String(bytes, StandardCharsets.UTF_8);
    }

    private void writePadding(int padding) {
        for (int i = 0; i < padding; i++) {
            write((byte) 0);
        }
    }

    private void readPadding() {
        for (int i = 0; i < padding; i++) {
            readByte();
        }
    }

    public String toUpperCase(String value) {
        return value.toUpperCase();
    }

    public String toLowerCase(String value) {
        return value.toLowerCase();
    }

    public String[] split(String value, String delimiter) {
        return value.split(delimiter);
    }

    public boolean validatePadding(byte[] bytes) {
        for (int i = 0; i < padding; i++) {
            if (bytes[bytes.length - 1 - i] != 0) {
                return false;
            }
        }
        return true;
    }
}

public class JSONTokener {
    private Reader reader;
    private int currentChar;
    private int index;
    private int line;
    private int character;

    public JSONTokener(Reader reader) {
        this.reader = reader;
        this.currentChar = 0;
        this.index = 0;
        this.line = 1;
        this.character = 0;
    }

    public JSONTokener(InputStream inputStream) {
        this.reader = new InputStreamReader(inputStream);
        this.currentChar = 0;
        this.index = 0;
        this.line = 1;
        this.character = 0;
    }

    public JSONTokener(String string) {
        this.reader = new StringReader(string);
        this.currentChar = 0;
        this.index = 0;
        this.line = 1;
        this.character = 0;
    }

    public char next() throws IOException {
        char c = (char) read();
        if (c == '\n') {
            line++;
            character = 0;
        } else {
            character++;
        }
        return c;
    }

    public String nextString(char quote) throws IOException {
        StringBuilder sb = new StringBuilder();
        while (true) {
            char c = next();
            if (c == quote) {
                return sb.toString();
            } else if (c == '\\') {
                c = next();
                switch (c) {
                    case 'n': sb.append('\n'); break;
                    case 't': sb.append('\t'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'r': sb.append('\r'); break;
                    case 'u': 
                        String hex = "" + next() + next() + next() + next();
                        sb.append((char) Integer.parseInt(hex, 16));
                        break;
                    default: sb.append(c); break;
                }
            } else {
                sb.append(c);
            }
        }
    }

    public void skipTo(char to) throws IOException {
        while (true) {
            char c = next();
            if (c == to) {
                return;
            }
        }
    }

    public int read() throws IOException {
        currentChar = reader.read();
        index++;
        return currentChar;
    }

    public int getIndex() {
        return index;
    }

    public int getLine() {
        return line;
    }

    public int getCharacter() {
        return character;
    }

    public void back() throws IOException {
        if (index > 0) {
            index--;
            reader.reset();
        }
    }
}

