public class ComposedRuleElementMatch extends RuleElementMatch {
    private Map<String, RuleElementMatch> innerMatches;
    private boolean baseConditionMatched;

    public ComposedRuleElementMatch() {
        this.innerMatches = new HashMap<>();
        this.baseConditionMatched = false;
    }

    public void addInnerMatch(String key, RuleElementMatch match) {
        innerMatches.put(key, match);
    }

    public boolean evaluateConditions() {
        for (RuleElementMatch match : innerMatches.values()) {
            if (!match.evaluateConditions()) {
                return false;
            }
        }
        baseConditionMatched = true;
        return true;
    }

    public void enforceUpdates() {
        for (RuleElementMatch match : innerMatches.values()) {
            match.enforceUpdates();
        }
    }

    public ComposedRuleElementMatch createCopyWithUpdatedMatches() {
        ComposedRuleElementMatch copy = new ComposedRuleElementMatch();
        for (Map.Entry<String, RuleElementMatch> entry : innerMatches.entrySet()) {
            copy.addInnerMatch(entry.getKey(), entry.getValue().createCopyWithUpdatedMatches());
        }
        copy.baseConditionMatched = this.baseConditionMatched;
        return copy;
    }

    public boolean isBaseConditionMatched() {
        return baseConditionMatched;
    }

    public String getMatchedTexts() {
        StringBuilder matchedTexts = new StringBuilder();
        for (RuleElementMatch match : innerMatches.values()) {
            matchedTexts.append(match.getMatchedTexts()).append(" ");
        }
        return matchedTexts.toString().trim();
    }
}

