public class SsfDialog extends JDialog {
    private SsfWrapper ssfWrapper;
    private JComboBox<String> featureComboBox;
    private JCheckBox strengthOption1;
    private JCheckBox strengthOption2;
    private JTextField additionalValueField;
    private JButton okButton;

    public SsfDialog(SsfWrapper ssfWrapper) {
        this.ssfWrapper = ssfWrapper;
        setTitle("Configure Security Strength Factors");
        setLayout(new GridLayout(5, 2));
        initializeComponents();
        setupListeners();
        loadExistingValues();
        validateInputs();
        pack();
        setVisible(true);
    }

    private void initializeComponents() {
        featureComboBox = new JComboBox<>(new String[]{"Feature1", "Feature2", "Feature3"});
        strengthOption1 = new JCheckBox("Strength Option 1");
        strengthOption2 = new JCheckBox("Strength Option 2");
        additionalValueField = new JTextField();
        okButton = new JButton("OK");
        okButton.setEnabled(false);

        add(new JLabel("Select Feature:"));
        add(featureComboBox);
        add(strengthOption1);
        add(strengthOption2);
        add(new JLabel("Additional Value:"));
        add(additionalValueField);
        add(okButton);
    }

    private void setupListeners() {
        featureComboBox.addActionListener(e -> validateInputs());
        strengthOption1.addActionListener(e -> validateInputs());
        strengthOption2.addActionListener(e -> validateInputs());
        additionalValueField.addCaretListener(e -> validateInputs());
        okButton.addActionListener(new ActionListener() {
            public void actionPerformed(ActionEvent e) {
                saveValues();
                dispose();
            }
        });
    }

    private void loadExistingValues() {
        featureComboBox.setSelectedItem(ssfWrapper.getFeature());
        strengthOption1.setSelected(ssfWrapper.isStrengthOption1());
        strengthOption2.setSelected(ssfWrapper.isStrengthOption2());
        additionalValueField.setText(ssfWrapper.getAdditionalValue());
    }

    private void validateInputs() {
        boolean isValid = !additionalValueField.getText().trim().isEmpty() &&
                          featureComboBox.getSelectedItem() != null &&
                          (strengthOption1.isSelected() || strengthOption2.isSelected());
        okButton.setEnabled(isValid);
    }

    private void saveValues() {
        ssfWrapper.setFeature((String) featureComboBox.getSelectedItem());
        ssfWrapper.setStrengthOption1(strengthOption1.isSelected());
        ssfWrapper.setStrengthOption2(strengthOption2.isSelected());
        ssfWrapper.setAdditionalValue(additionalValueField.getText().trim());
    }
}

public class FarmWarDeployer implements ClusterListener, DeploymentManager, FileChangeMonitor {
    private static final Logger logger = Logger.getLogger(FarmWarDeployer.class.getName());
    private String deploymentDir;
    private String tempDir;

    public FarmWarDeployer(String deploymentDir, String tempDir) {
        this.deploymentDir = deploymentDir;
        this.tempDir = tempDir;
    }

    @Override
    public void onDeploymentMessage(String warFile) {
        try {
            deployWar(warFile);
        } catch (IOException e) {
            logger.severe("Deployment failed: " + e.getMessage());
        }
    }

    @Override
    public void onUndeploymentMessage(String appName) {
        undeployApp(appName);
    }

    @Override
    public void monitorFileChanges() {
        try {
            WatchService watchService = FileSystems.getDefault().newWatchService();
            Paths.get(deploymentDir).register(watchService, StandardWatchEventKinds.ENTRY_MODIFY);
            while (true) {
                WatchKey key = watchService.take();
                for (WatchEvent<?> event : key.pollEvents()) {
                    if (event.kind() == StandardWatchEventKinds.ENTRY_MODIFY) {
                        deployWar(event.context().toString());
                    }
                }
                key.reset();
            }
        } catch (IOException | InterruptedException e) {
            logger.severe("File monitoring failed: " + e.getMessage());
        }
    }

    private void deployWar(String warFile) throws IOException {
        File source = new File(tempDir, warFile);
        File destination = new File(deploymentDir, warFile);
        Files.copy(source.toPath(), destination.toPath(), StandardCopyOption.REPLACE_EXISTING);
        logger.info("Deployed: " + warFile);
    }

    private void undeployApp(String appName) {
        File appFile = new File(deploymentDir, appName);
        if (appFile.exists()) {
            appFile.delete();
            logger.info("Undeployed: " + appName);
        } else {
            logger.warning("App not found for undeployment: " + appName);
        }
    }

    private void logError(String message) {
        logger.severe(message);
    }

    private void logInfo(String message) {
        logger.info(message);
    }
}

