public class WritableUtils {

    public static Writable createWritableInstance(Class<? extends Writable> writableClass) throws IllegalAccessException, InstantiationException {
        return writableClass.newInstance();
    }

    public static byte[] writeWritable(Writable writable) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        ObjectOutputStream objectOutputStream = new ObjectOutputStream(byteArrayOutputStream);
        writable.write(objectOutputStream);
        objectOutputStream.close();
        return byteArrayOutputStream.toByteArray();
    }

    public static Writable readWritable(byte[] data, Writable writable) throws IOException {
        ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(data);
        ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream);
        writable.readFields(objectInputStream);
        objectInputStream.close();
        return writable;
    }

    public static void writeToZNode(ZooKeeper zooKeeper, String path, Writable writable) throws Exception {
        byte[] data = writeWritable(writable);
        zooKeeper.create(path, data, null, null);
    }

    public static Writable readFromZNode(ZooKeeper zooKeeper, String path, Writable writable) throws Exception {
        byte[] data = zooKeeper.getData(path, false, null);
        return readWritable(data, writable);
    }

    public static byte[] serializeWritableList(List<Writable> writables) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        ObjectOutputStream objectOutputStream = new ObjectOutputStream(byteArrayOutputStream);
        objectOutputStream.writeInt(writables.size());
        for (Writable writable : writables) {
            writeWritable(writable);
        }
        objectOutputStream.close();
        return byteArrayOutputStream.toByteArray();
    }

    public static List<Writable> deserializeWritableList(byte[] data, Writable writable) throws IOException {
        List<Writable> writables = new ArrayList<>();
        ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(data);
        ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream);
        int size = objectInputStream.readInt();
        for (int i = 0; i < size; i++) {
            Writable instance = createWritableInstance(writable.getClass());
            writables.add(readWritable(data, instance));
        }
        objectInputStream.close();
        return writables;
    }

