public class FormatterElement extends FormatterBase implements ElementVisitor {

    private static final String INDENT = "    ";
    private static final boolean PRETTY_PRINT = true;
    private StringBuilder output;
    private int indentLevel;

    public FormatterElement() {
        this.output = new StringBuilder();
        this.indentLevel = 0;
    }

    public String format(Element element) {
        element.visit(this);
        return output.toString();
    }

    @Override
    public void visit(Triple triple) {
        appendIndented(triple.toString());
    }

    @Override
    public void visit(PathBlock pathBlock) {
        appendIndented("PathBlock:");
        indentLevel++;
        for (Path path : pathBlock.getPaths()) {
            appendIndented(path.toString());
        }
        indentLevel--;
    }

    @Override
    public void visit(Filter filter) {
        appendIndented("Filter: " + filter.getCondition());
    }

    @Override
    public void visit(Union union) {
        appendIndented("Union:");
        indentLevel++;
        for (Element element : union.getElements()) {
            element.visit(this);
        }
        indentLevel--;
    }

    @Override
    public void visit(Optional optional) {
        appendIndented("Optional:");
        indentLevel++;
        optional.getElement().visit(this);
        indentLevel--;
    }

    @Override
    public void visit(NamedGraph namedGraph) {
        appendIndented("Named Graph: " + namedGraph.getGraphName());
    }

    @Override
    public void visit(Service service) {
        appendIndented("Service: " + service.getServiceName());
    }

    private void appendIndented(String text) {
        if (PRETTY_PRINT) {
            for (int i = 0; i < indentLevel; i++) {
                output.append(INDENT);
            }
        }
        output.append(text).append(System.lineSeparator());
    }
}

