class TestExtractText {

    @Test
    public void testExtractWithSingleCaptureGroup() {
        String input = "Hello World";
        String regex = "(\\w+) (\\w+)";
        ExtractText processor = new ExtractText(regex);
        FlowFile result = processor.process(input);

        assertNotNull(result);
        assertEquals("Hello", result.getAttribute("group1"));
        assertEquals("World", result.getAttribute("group2"));
    }

    @Test
    public void testExtractWithMultipleCaptureGroups() {
        String input = "Java 101 Programming";
        String regex = "(\\w+) (\\d+) (\\w+)";
        ExtractText processor = new ExtractText(regex);
        FlowFile result = processor.process(input);

        assertNotNull(result);
        assertEquals("Java", result.getAttribute("group1"));
        assertEquals("101", result.getAttribute("group2"));
        assertEquals("Programming", result.getAttribute("group3"));
    }

    @Test
    public void testExtractWithNoMatches() {
        String input = "No Match Here";
        String regex = "(\\d+)";
        ExtractText processor = new ExtractText(regex);
        FlowFile result = processor.process(input);

        assertNotNull(result);
        assertNull(result.getAttribute("group1"));
    }

    @Test
    public void testExtractWithMultiline() {
        String input = "Line1\nLine2\nLine3";
        String regex = "(Line\\d)";
        ExtractText processor = new ExtractText(regex);
        FlowFile result = processor.process(input);

        assertNotNull(result);
        assertEquals("Line1", result.getAttribute("group1"));
    }

    @Test
    public void testExtractWithDotallMode() {
        String input = "Start\nMiddle\nEnd";
        String regex = "(Start.*End)";
        ExtractText processor = new ExtractText(regex, true); // Enable dotall mode
        FlowFile result = processor.process(input);

        assertNotNull(result);
        assertEquals("Start\nMiddle\nEnd", result.getAttribute("group1"));
    }

    @Test
    public void testExtractWithZeroCaptureGroups() {
        String input = "No Groups";
        String regex = "No Groups";
        ExtractText processor = new ExtractText(regex);
        FlowFile result = processor.process(input);

        assertNotNull(result);
        assertNull(result.getAttribute("group1")); // No capture groups defined
    }

    @Test
    public void testExtractWithSpecificPropertySet() {
        String input = "Extract This";
        String regex = "(Extract) (This)";
        ExtractText processor = new ExtractText(regex);
        processor.setProperty("propertyName", "propertyValue");
        FlowFile result = processor.process(input);

        assertNotNull(result);
        assertEquals("Extract", result.getAttribute("group1"));
        assertEquals("This", result.getAttribute("group2"));
        assertEquals("propertyValue", result.getAttribute("propertyName"));
    }
}

