    private static final Logger logger = LoggerFactory.getLogger(GetDataBuilderImpl.class);
    private ZooKeeper zooKeeper;
    private String path;
    private boolean watch;
    private boolean background;
    private AsyncCallback.DataCallback callback;
    private Object context;

    public GetDataBuilderImpl(ZooKeeper zooKeeper) {
        this.zooKeeper = zooKeeper;
    }

    @Override
    public GetDataBuilder forPath(String path) {
        this.path = path;
        return this;
    }

    @Override
    public GetDataBuilder withWatcher(Watcher watcher) {
        this.watch = true;
        return this;
    }

    @Override
    public GetDataBuilder inBackground(AsyncCallback.DataCallback callback, Object context) {
        this.background = true;
        this.callback = callback;
        this.context = context;
        return this;
    }

    @Override
    public byte[] getData() throws KeeperException, InterruptedException {
        if (background) {
            logger.warn("Synchronous getData called while background operation is set.");
        }
        return retrieveData();
    }

    @Override
    public void getDataAsync() {
        if (!background) {
            logger.warn("Asynchronous getData called without background operation set.");
            return;
        }
        retrieveDataAsync();
    }

    private byte[] retrieveData() throws KeeperException, InterruptedException {
        byte[] data = zooKeeper.getData(path, watch ? new Watcher() {
            @Override
            public void process(WatchedEvent event) {
                logger.info("Node {} changed: {}", path, event);
            }
        } : null, null);
        return decompressData(data);
    }

    private void retrieveDataAsync() {
        zooKeeper.getData(path, watch ? new Watcher() {
            @Override
            public void process(WatchedEvent event) {
                logger.info("Node {} changed: {}", path, event);
            }
        } : null, callback, context);
    }

    private byte[] decompressData(byte[] data) {
        // Decompression logic here (placeholder)
        return data;
    }
}

public class GroupReportlet extends AbstractReportlet {
    private static final Logger logger = LoggerFactory.getLogger(GroupReportlet.class);

    private GroupDAO groupDAO;
    private AttributeDAO attributeDAO;
    private ResourceDAO resourceDAO;
    private Configuration configuration;

    public GroupReportlet(GroupDAO groupDAO, AttributeDAO attributeDAO, ResourceDAO resourceDAO, Configuration configuration) {
        this.groupDAO = groupDAO;
        this.attributeDAO = attributeDAO;
        this.resourceDAO = resourceDAO;
        this.configuration = configuration;
    }

    @Override
    public void generateReport(ContentHandler contentHandler) {
        if (!isValidConfiguration(configuration)) {
            logger.error("Invalid configuration for group reporting.");
            return;
        }

        int pageSize = configuration.getPageSize();
        int pageNumber = configuration.getPageNumber();
        List<Group> groups = groupDAO.getGroups(pageSize, pageNumber);

        for (Group group : groups) {
            try {
                processGroup(contentHandler, group);
            } catch (Exception e) {
                logger.error("Error processing group: " + group.getId(), e);
            }
        }
    }

    private void processGroup(ContentHandler contentHandler, Group group) throws Exception {
        contentHandler.startElement("", "group", "group", null);

        // Process attributes
        processAttributes(contentHandler, group);

        // Process derived attributes
        processDerivedAttributes(contentHandler, group);

        // Process virtual attributes
        processVirtualAttributes(contentHandler, group);

        // Process associated resources
        processResources(contentHandler, group);

        contentHandler.endElement("", "group", "group");
    }

    private void processAttributes(ContentHandler contentHandler, Group group) throws Exception {
        List<Attribute> attributes = attributeDAO.getAttributesForGroup(group.getId());
        for (Attribute attribute : attributes) {
            if (attribute == null) {
                logger.debug("Attribute not found for group: " + group.getId());
                continue;
            }
            // Output attribute to contentHandler
        }
    }

    private void processDerivedAttributes(ContentHandler contentHandler, Group group) throws Exception {
        // Implementation for derived attributes
    }

    private void processVirtualAttributes(ContentHandler contentHandler, Group group) throws Exception {
        // Implementation for virtual attributes
    }

    private void processResources(ContentHandler contentHandler, Group group) throws Exception {
        List<Resource> resources = resourceDAO.getResourcesForGroup(group.getId());
        for (Resource resource : resources) {
            if (resource == null) {
                logger.debug("Resource not found for group: " + group.getId());
                continue;
            }
            // Output resource to contentHandler
        }
    }

    private boolean isValidConfiguration(Configuration configuration) {
        return configuration != null && configuration.getPageSize() > 0 && configuration.getPageNumber() >= 0;
    }
}

