public class ReduceSender<T> implements Reduce.Sender<T>, EventHandler<GroupCommunicationMessage> {
    private final Group group;
    private final ReduceFunction<T> reduceFunction;
    private final NetworkService networkService;
    private boolean isInitialized = false;

    public ReduceSender(Group group, ReduceFunction<T> reduceFunction, NetworkService networkService) {
        this.group = group;
        this.reduceFunction = reduceFunction;
        this.networkService = networkService;
    }

    public void initialize() {
        if (!isInitialized) {
            try {
                // Initialize communication with the group
                networkService.connect(group);
                isInitialized = true;
            } catch (Exception e) {
                // Handle exception related to parent node availability
                System.err.println("Failed to initialize communication: " + e.getMessage());
            }
        }
    }

    @Override
    public void send(T data) {
        if (!isInitialized) {
            initialize();
        }
        try {
            // Perform reduction operation
            T reducedData = reduceFunction.reduce(data);
            // Encode data for transmission
            byte[] encodedData = encode(reducedData);
            // Send the encoded data
            networkService.send(encodedData, group);
        } catch (Exception e) {
            System.err.println("Error during sending data: " + e.getMessage());
        }
    }

    @Override
    public void handle(GroupCommunicationMessage message) {
        // Handle incoming messages
        // Logic to process the message
    }

    private byte[] encode(T data) {
        // Encoding logic
        return data.toString().getBytes(); // Simplistic encoding
    }
}

public abstract class AbstractMQTTTest {

    protected MqttClient client;
    protected String brokerUrl = "tcp://localhost:1883";
    protected String clientId = "testClient";
    protected CountDownLatch latch;

    public abstract void setup() throws MqttException;

    public abstract void teardown() throws MqttException;

    protected void connect() throws MqttException {
        MqttConnectOptions options = new MqttConnectOptions();
        options.setCleanSession(true);
        client = new MqttClient(brokerUrl, clientId);
        client.connect(options);
    }

    protected void disconnect() throws MqttException {
        if (client != null && client.isConnected()) {
            client.disconnect();
        }
    }

    protected void publish(String topic, String payload, int qos) throws MqttException {
        MqttMessage message = new MqttMessage(payload.getBytes());
        message.setQos(qos);
        client.publish(topic, message);
    }

    protected void subscribe(String topic, MqttCallback callback) throws MqttException {
        client.setCallback(callback);
        client.subscribe(topic);
    }

    protected void waitForMessage() throws InterruptedException {
        latch.await();
    }

    protected void messageReceived() {
        latch.countDown();
    }

