public class Int2Datum extends NumericDatum {
    private short value;

    public Int2Datum(short value) {
        this.value = value;
    }

    public Int2Datum(byte[] byteArray) {
        if (byteArray.length != 2) {
            throw new IllegalArgumentException("Byte array must be of length 2");
        }
        this.value = (short) ((byteArray[0] << 8) | (byteArray[1] & 0xFF));
    }

    public char toChar() {
        return (char) value;
    }

    public int toInt() {
        return value;
    }

    public float toFloat() {
        return (float) value;
    }

    public double toDouble() {
        return (double) value;
    }

    public Int2Datum add(Datum other) {
        if (other instanceof Int2Datum) {
            return new Int2Datum((short) (this.value + ((Int2Datum) other).value));
        }
        throw new UnsupportedOperationException("Addition not supported for this type");
    }

    public Int2Datum subtract(Datum other) {
        if (other instanceof Int2Datum) {
            return new Int2Datum((short) (this.value - ((Int2Datum) other).value));
        }
        throw new UnsupportedOperationException("Subtraction not supported for this type");
    }

    public Int2Datum multiply(Datum other) {
        if (other instanceof Int2Datum) {
            return new Int2Datum((short) (this.value * ((Int2Datum) other).value));
        }
        throw new UnsupportedOperationException("Multiplication not supported for this type");
    }

    public Int2Datum divide(Datum other) {
        if (other instanceof Int2Datum) {
            if (((Int2Datum) other).value == 0) {
                throw new ArithmeticException("Division by zero");
            }
            return new Int2Datum((short) (this.value / ((Int2Datum) other).value));
        }
        throw new UnsupportedOperationException("Division not supported for this type");
    }

    public Int2Datum modulus(Datum other) {
        if (other instanceof Int2Datum) {
            if (((Int2Datum) other).value == 0) {
                throw new ArithmeticException("Modulus by zero");
            }
            return new Int2Datum((short) (this.value % ((Int2Datum) other).value));
        }
        throw new UnsupportedOperationException("Modulus not supported for this type");
    }

    public boolean equals(Datum other) {
        if (other instanceof Int2Datum) {
            return this.value == ((Int2Datum) other).value;
        }
        return false;
    }

    public int hashCode() {
        return Short.hashCode(value);
    }

    public byte[] toByteArray() {
        return new byte[] { (byte) (value >> 8), (byte) value };
    }
}

