public class WorkspaceInfo implements UpdateEventListener {
    protected FileSystem fileSystem;
    protected PersistenceManager persistenceManager;
    protected ItemStateManager itemStateManager;
    protected ObservationDispatcher observationDispatcher;
    protected SearchManager searchManager;
    protected LockManager lockManager;
    protected RetentionRegistry retentionRegistry;
    private final Lock lock = new ReentrantLock();
    private boolean isIdle = true;

    public WorkspaceInfo() {
        initializeComponents();
    }

    protected void initializeComponents() {
        fileSystem = new FileSystem();
        persistenceManager = new PersistenceManager();
        itemStateManager = new ItemStateManager();
        observationDispatcher = new ObservationDispatcher();
        searchManager = new SearchManager();
        lockManager = new LockManager();
        retentionRegistry = new RetentionRegistry();
    }

    public void dispose() {
        lock.lock();
        try {
            if (!isIdle) {
                // Dispose logic here
                fileSystem.dispose();
                persistenceManager.dispose();
                itemStateManager.dispose();
                observationDispatcher.dispose();
                searchManager.dispose();
                lockManager.dispose();
                retentionRegistry.dispose();
                isIdle = true;
            }
        } finally {
            lock.unlock();
        }
    }

    public void updateEventOccurred(UpdateEvent event) {
        lock.lock();
        try {
            // Handle the update event
            processEvent(event);
            isIdle = false;
        } finally {
            lock.unlock();
        }
    }

    protected void processEvent(UpdateEvent event) {
        // Event processing logic
    }

    public void markAsIdle() {
        lock.lock();
        try {
            isIdle = true;
        } finally {
            lock.unlock();
        }
    }

    public boolean isIdle() {
        lock.lock();
        try {
            return isIdle;
        } finally {
            lock.unlock();
        }
    }
}

