        initializeProperties(columnSchemas);
        computeFingerprint();
    }

    private void initializeProperties(List<ColumnSchema> columnSchemas) {
        for (ColumnSchema schema : columnSchemas) {
            if (schema.isDimension()) {
                dimensions.add(schema.getName());
                dimensionOrdinalToChunkIndex.put(schema.getName(), schema.getChunkIndex());
            } else if (schema.isComplexDimension()) {
                complexDimensions.add(schema.getName());
            } else if (schema.isMeasure()) {
                measures.add(schema.getName());
                measureOrdinalToChunkIndex.put(schema.getName(), schema.getChunkIndex());
            }
        }
    }

    private void computeFingerprint() {
        StringBuilder sb = new StringBuilder();
        for (String dimension : dimensions) {
            sb.append(dimension);
        }
        for (String measure : measures) {
            sb.append(measure);
        }
        fingerprint = sb.toString();
    }

    public int getDimensionCount() {
        return dimensions.size();
    }

    public int getMeasureCount() {
        return measures.size();
    }

    public Map<String, Integer> getDimensionMappings() {
        return dimensionOrdinalToChunkIndex;
    }

    public Map<String, Integer> getMeasureMappings() {
        return measureOrdinalToChunkIndex;
    }

    public List<String> getComplexDimensions() {
        return complexDimensions;
    }

    public String getFingerprint() {
        return fingerprint;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof SegmentProperties)) return false;
        SegmentProperties that = (SegmentProperties) o;
        return dimensions.size() == that.dimensions.size() && fingerprint.equals(that.fingerprint);
    }

    @Override
    public int hashCode() {
        return Objects.hash(dimensions.size(), fingerprint);
    }

    public int[] createColumnValueLengths(String dataType) {
        // Placeholder for actual implementation based on data type
        return new int[0];
    }
