public class UrlValidator implements IValidator<String> {
    private static final String SCHEME_REGEX = "^(http|https|ftp)://";
    private static final String AUTHORITY_REGEX = "([a-zA-Z0-9.-]+(:[0-9]+)?)";
    private static final String PATH_REGEX = "(/[^\\s]*)?";
    private static final String QUERY_REGEX = "(\\?[a-zA-Z0-9=&]*)?";
    private static final String FRAGMENT_REGEX = "(#[a-zA-Z0-9]*)?";

    private final boolean allowAllSchemes;
    private final boolean allowMultipleSlashes;

    public UrlValidator(boolean allowAllSchemes, boolean allowMultipleSlashes) {
        this.allowAllSchemes = allowAllSchemes;
        this.allowMultipleSlashes = allowMultipleSlashes;
    }

    @Override
    public boolean validate(String url) {
        String scheme = allowAllSchemes ? "([a-zA-Z][a-zA-Z0-9+.-]*)://" : SCHEME_REGEX;
        String regex = scheme + AUTHORITY_REGEX + (allowMultipleSlashes ? "(/.*)?" : PATH_REGEX) + QUERY_REGEX + FRAGMENT_REGEX;
        Pattern pattern = Pattern.compile(regex);
        return pattern.matcher(url).matches();
    }

    public String getErrorMessage(String url) {
        if (!validate(url)) {
            return "Invalid URL format.";
        }
        return "URL is valid.";
    }
}

