public class FlatTopology implements Topology {
    private static final Logger logger = Logger.getLogger(FlatTopology.class.getName());
    private ConcurrentHashMap<String, TaskNode> taskNodes;
    private TaskNode rootTaskNode;

    public FlatTopology() {
        this.taskNodes = new ConcurrentHashMap<>();
    }

    public void addTask(String taskId, TaskNode taskNode) {
        if (taskNodes.putIfAbsent(taskId, taskNode) == null) {
            logger.info("Task added: " + taskId);
        } else {
            logger.warning("Task already exists: " + taskId);
        }
    }

    public void removeTask(String taskId) {
        if (taskNodes.remove(taskId) != null) {
            logger.info("Task removed: " + taskId);
        } else {
            logger.warning("Task not found: " + taskId);
        }
    }

    public void setRootTaskNode(TaskNode rootTaskNode) {
        this.rootTaskNode = rootTaskNode;
        logger.info("Root task node set: " + rootTaskNode.getId());
    }

    public void handleTopologyChange(String message) {
        logger.info("Handling topology change: " + message);
        // Process the message related to topology changes
    }

    public void updateTaskState(String taskId, TaskState state) {
        TaskNode taskNode = taskNodes.get(taskId);
        if (taskNode != null) {
            taskNode.setState(state);
            logger.info("Updated task state: " + taskId + " to " + state);
        } else {
            logger.warning("Task not found for state update: " + taskId);
        }
    }

    public TaskNode getTaskNode(String taskId) {
        return taskNodes.get(taskId);
    }

    public void logTaskSpecifications() {
        taskNodes.forEach((id, node) -> logger.info("Task ID: " + id + ", Specifications: " + node.getSpecifications()));
    }
}

public class WrapTokenV1 {
    private static final String ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final int IV_SIZE = 16;
    private static final int KEY_SIZE = 16; // 128 bits
    private byte[] wrappedToken;
    private byte[] confounder;
    private int paddingLength;

    public WrapTokenV1(byte[] data, byte[] key) throws Exception {
        this.confounder = generateConfounder();
        this.wrappedToken = wrap(data, key);
    }

    public WrapTokenV1(InputStream inputStream, byte[] key) throws IOException, Exception {
        byte[] data = inputStream.readAllBytes();
        this.confounder = generateConfounder();
        this.wrappedToken = wrap(data, key);
    }

    private byte[] generateConfounder() {
        byte[] confounder = new byte[IV_SIZE];
        new SecureRandom().nextBytes(confounder);
        return confounder;
    }

    private byte[] wrap(byte[] data, byte[] key) throws Exception {
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        SecretKeySpec secretKey = new SecretKeySpec(key, "AES");
        IvParameterSpec ivParams = new IvParameterSpec(confounder);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivParams);
        byte[] encryptedData = cipher.doFinal(data);
        this.paddingLength = calculatePaddingLength(encryptedData.length);
        return encryptedData;
    }

    private int calculatePaddingLength(int length) {
        return (length % 16 == 0) ? 0 : 16 - (length % 16);
    }

    public byte[] unwrap(byte[] key) throws Exception {
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        SecretKeySpec secretKey = new SecretKeySpec(key, "AES");
        IvParameterSpec ivParams = new IvParameterSpec(confounder);
        cipher.init(Cipher.DECRYPT_MODE, secretKey, ivParams);
        byte[] decryptedData = cipher.doFinal(wrappedToken);
        return removePadding(decryptedData);
    }

    private byte[] removePadding(byte[] data) {
        if (paddingLength > 0) {
            byte[] unpaddedData = new byte[data.length - paddingLength];
            System.arraycopy(data, 0, unpaddedData, 0, unpaddedData.length);
            return unpaddedData;
        }
        return data;
    }

    public byte[] getWrappedToken() {
        return wrappedToken;
    }

    public byte[] getConfounder() {
        return confounder;
    }

    public int getPaddingLength() {
        return paddingLength;
    }
}

