public class WorkerProgress {
    private static WorkerProgress instance;
    private int loadedVertices;
    private int computedVertices;
    private int storedVertices;
    private int loadedEdges;
    private int computedEdges;
    private int storedEdges;
    private int inputSplitsProcessed;
    private int currentSuperstep;

    private WorkerProgress() {
        // Private constructor to prevent instantiation
    }

    public static synchronized WorkerProgress getInstance() {
        if (instance == null) {
            instance = new WorkerProgress();
        }
        return instance;
    }

    public synchronized void updateLoadedVertices(int count) {
        loadedVertices += count;
    }

    public synchronized void updateComputedVertices(int count) {
        computedVertices += count;
    }

    public synchronized void updateStoredVertices(int count) {
        storedVertices += count;
    }

    public synchronized void updateLoadedEdges(int count) {
        loadedEdges += count;
    }

    public synchronized void updateComputedEdges(int count) {
        computedEdges += count;
    }

    public synchronized void updateStoredEdges(int count) {
        storedEdges += count;
    }

    public synchronized void updateInputSplitsProcessed(int count) {
        inputSplitsProcessed += count;
    }

    public synchronized void setCurrentSuperstep(int superstep) {
        currentSuperstep = superstep;
    }

    public synchronized int getLoadedVertices() {
        return loadedVertices;
    }

    public synchronized int getComputedVertices() {
        return computedVertices;
    }

    public synchronized int getStoredVertices() {
        return storedVertices;
    }

    public synchronized int getLoadedEdges() {
        return loadedEdges;
    }

    public synchronized int getComputedEdges() {
        return computedEdges;
    }

    public synchronized int getStoredEdges() {
        return storedEdges;
    }

    public synchronized int getInputSplitsProcessed() {
        return inputSplitsProcessed;
    }

    public synchronized int getCurrentSuperstep() {
        return currentSuperstep;
    }

    public synchronized boolean isLoadingComplete() {
        return loadedVertices > 0 && loadedEdges > 0;
    }

    public synchronized boolean isComputationComplete() {
        return computedVertices == loadedVertices && computedEdges == loadedEdges;
    }

    public synchronized void reset() {
        loadedVertices = 0;
        computedVertices = 0;
        storedVertices = 0;
        loadedEdges = 0;
        computedEdges = 0;
        storedEdges = 0;
        inputSplitsProcessed = 0;
        currentSuperstep = 0;
    }
}

