        if (value < this.value) {
            if (left == null) {
                left = new AVLNode(value);
            } else {
                left.insert(value);
            }
        } else {
            if (right == null) {
                right = new AVLNode(value);
            } else {
                right.insert(value);
            }
        }
        balance();
    }

    public void remove(int value) {
        // Removal logic (not fully implemented)
        balance();
    }

    public AVLNode findMin() {
        return left == null ? this : left.findMin();
    }

    public AVLNode findMax() {
