public class GeneratorAdapter extends LocalVariablesSorter {

    public GeneratorAdapter(int api, MethodVisitor methodVisitor) {
        super(api, methodVisitor);
    }

    public void pushBoolean(boolean value) {
        mv.visitInsn(value ? Opcodes.ICONST_1 : Opcodes.ICONST_0);
    }

    public void pushInt(int value) {
        if (value >= -1 && value <= 5) {
            mv.visitInsn(Opcodes.ICONST_0 + value);
        } else if (value >= Byte.MIN_VALUE && value <= Byte.MAX_VALUE) {
            mv.visitIntInsn(Opcodes.BIPUSH, value);
        } else {
            mv.visitIntInsn(Opcodes.SIPUSH, value);
        }
    }

    public void pushLong(long value) {
        if (value == 0L) {
            mv.visitInsn(Opcodes.LCONST_0);
        } else if (value == 1L) {
            mv.visitInsn(Opcodes.LCONST_1);
        } else {
            mv.visitLdcInsn(value);
        }
    }

    public void pushFloat(float value) {
        if (value == 0.0f) {
            mv.visitInsn(Opcodes.FCONST_0);
        } else if (value == 1.0f) {
            mv.visitInsn(Opcodes.FCONST_1);
        } else if (value == 2.0f) {
            mv.visitInsn(Opcodes.FCONST_2);
        } else {
            mv.visitLdcInsn(value);
        }
    }

    public void pushDouble(double value) {
        if (value == 0.0) {
            mv.visitInsn(Opcodes.DCONST_0);
        } else if (value == 1.0) {
            mv.visitInsn(Opcodes.DCONST_1);
        } else {
            mv.visitLdcInsn(value);
        }
    }

    public void pushString(String value) {
        mv.visitLdcInsn(value);
    }

    public void loadLocal(int index) {
        mv.visitVarInsn(Opcodes.ALOAD, index);
    }

    public void storeLocal(int index) {
        mv.visitVarInsn(Opcodes.ASTORE, index);
    }

    public void add() {
        mv.visitInsn(Opcodes.IADD);
    }

    public void subtract() {
        mv.visitInsn(Opcodes.ISUB);
    }

    public void multiply() {
        mv.visitInsn(Opcodes.IMUL);
    }

    public void divide() {
        mv.visitInsn(Opcodes.IDIV);
    }

    public void castToInt() {
        mv.visitInsn(Opcodes.I2D);
    }

    public void boxInt() {
        mv.visitMethodInsn(Opcodes.INVOKESTATIC, "java/lang/Integer", "valueOf", "(I)Ljava/lang/Integer;", false);
    }

    public void unboxInt() {
        mv.visitTypeInsn(Opcodes.CHECKCAST, "java/lang/Integer");
        mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/lang/Integer", "intValue", "()I", false);
    }

    public void invokeStatic(String owner, String name, String descriptor) {
        mv.visitMethodInsn(Opcodes.INVOKESTATIC, owner, name, descriptor, false);
    }

    public void invokeVirtual(String owner, String name, String descriptor) {
        mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, owner, name, descriptor, false);
    }

    public void invokeConstructor(String owner, String descriptor) {
        mv.visitMethodInsn(Opcodes.INVOKESPECIAL, owner, "<init>", descriptor, false);
    }

    public void ifZJump(int label) {
        mv.visitJumpInsn(Opcodes.IFEQ, label);
    }

    public void switchStatement(int[] keys, int[] labels) {
        mv.visitTableSwitchInsn(keys[0], keys[keys.length - 1], labels[0], labels);
    }

    public void tryCatchBlock(int start, int end, int handler, String type) {
        mv.visitTryCatchBlock(start, end, handler, type);
    }
}

