class AvlTreeMapNoDupsCursorTest {
    private AvlTreeMapNoDups<Integer, String> treeMap;
    private AvlTreeMapNoDupsCursor<Integer, String> cursor;

    @Before
    public void setUp() {
        treeMap = new AvlTreeMapNoDups<>();
        cursor = treeMap.cursor();
    }

    @After
    public void tearDown() {
        treeMap = null;
        cursor = null;
    }

    @Test
    public void testCursorOnEmptyTree() {
        assertFalse(cursor.hasNext());
        assertFalse(cursor.hasPrevious());
        assertThrows(IllegalStateException.class, cursor::next);
        assertThrows(IllegalStateException.class, cursor::previous);
    }

    @Test
    public void testCursorOnSingleEntry() {
        treeMap.put(1, "A");
        cursor = treeMap.cursor();
        assertTrue(cursor.hasNext());
        assertEquals("A", cursor.next().getValue());
        assertFalse(cursor.hasNext());
        assertTrue(cursor.hasPrevious());
        assertEquals("A", cursor.previous().getValue());
        assertFalse(cursor.hasPrevious());
    }

    @Test
    public void testCursorOnMultipleEntries() {
        treeMap.put(1, "A");
        treeMap.put(2, "B");
        treeMap.put(3, "C");
        cursor = treeMap.cursor();

        assertTrue(cursor.hasNext());
        assertEquals("A", cursor.next().getValue());
        assertTrue(cursor.hasNext());
        assertEquals("B", cursor.next().getValue());
        assertTrue(cursor.hasNext());
        assertEquals("C", cursor.next().getValue());
        assertFalse(cursor.hasNext());

        assertTrue(cursor.hasPrevious());
        assertEquals("C", cursor.previous().getValue());
        assertEquals("B", cursor.previous().getValue());
        assertEquals("A", cursor.previous().getValue());
        assertFalse(cursor.hasPrevious());
    }

    @Test
    public void testCursorInvalidPosition() {
        treeMap.put(1, "A");
        cursor = treeMap.cursor();
        cursor.next();
        cursor.next(); // Move cursor beyond the last element

        assertThrows(IllegalStateException.class, cursor::next);
        assertThrows(IllegalStateException.class, cursor::previous);
    }

    @Test
    public void testCursorWithDuplicateValues() {
        treeMap.put(1, "A");
        treeMap.put(2, "A"); // Duplicate value, should not be allowed
        cursor = treeMap.cursor();

        assertTrue(cursor.hasNext());
        assertEquals("A", cursor.next().getValue());
        assertFalse(cursor.hasNext());
    }

    @Test
    public void testUnsupportedOperations() {
        assertThrows(UnsupportedOperationException.class, cursor::remove);
        assertThrows(UnsupportedOperationException.class, cursor::set);
    }
}

