public class StringUtils {
    public static final String EMPTY_STRING = "";
    public static final String DEFAULT_DELIMITER = ",";
    public static final char QUOTE_CHAR = '"';

    public static boolean hasText(String str) {
        return str != null && !str.trim().isEmpty();
    }

    public static boolean startsWithIgnoreCase(String str, String prefix) {
        if (str == null || prefix == null) {
            return false;
        }
        return str.toLowerCase().startsWith(prefix.toLowerCase());
    }

    public static String cleanAndTrim(String str) {
        return str == null ? null : str.trim();
    }

    public static String join(Collection<?> elements, String delimiter) {
        if (elements == null || elements.isEmpty()) {
            return EMPTY_STRING;
        }
        StringBuilder sb = new StringBuilder();
        String sep = "";
        for (Object element : elements) {
            sb.append(sep).append(element);
            sep = delimiter;
        }
        return sb.toString();
    }

    public static String[] tokenize(String str, String delimiter) {
        if (str == null || delimiter == null) {
            return new String[0];
        }
        return str.split(delimiter);
    }

    public static Set<String> toSet(String str, String delimiter) {
        Set<String> set = new HashSet<>();
        String[] tokens = tokenize(str, delimiter);
        for (String token : tokens) {
            set.add(token.trim());
        }
        return set;
    }

    public static String[] splitKeyValue(String str, String delimiter) {
        if (str == null || delimiter == null) {
            return new String[0];
        }
        return str.split(delimiter, 2);
    }

    public static String[] splitWithQuotes(String str, String delimiter) {
        if (str == null || delimiter == null) {
            return new String[0];
        }
        List<String> result = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        boolean inQuotes = false;
        for (char ch : str.toCharArray()) {
            if (ch == QUOTE_CHAR) {
                inQuotes = !inQuotes;
            } else if (String.valueOf(ch).equals(delimiter) && !inQuotes) {
                result.add(current.toString().trim());
                current.setLength(0);
            } else {
                current.append(ch);
            }
        }
        result.add(current.toString().trim());
        return result.toArray(new String[0]);
    }

    public static String join(Iterator<?> iterator, String separator) {
        if (iterator == null) {
            return EMPTY_STRING;
        }
        StringBuilder sb = new StringBuilder();
        String sep = "";
        while (iterator.hasNext()) {
            sb.append(sep).append(iterator.next());
            sep = separator;
        }
        return sb.toString();
    }

    public static String capitalizeFirstCharacter(String str) {
        if (str == null || str.isEmpty()) {
            return str;
        }
        return Character.toUpperCase(str.charAt(0)) + str.substring(1);
    }
}

