public class PolynomialsUtilsTest {

    @Test
    public void testChebyshevPolynomials() {
        assertEquals(1, ChebyshevPolynomial.T(0).evaluate(0));
        assertEquals(0, ChebyshevPolynomial.T(1).evaluate(0));
        assertEquals(1, ChebyshevPolynomial.T(2).evaluate(0));
        assertEquals(-1, ChebyshevPolynomial.T(2).evaluate(1));
    }

    @Test
    public void testHermitePolynomials() {
        assertEquals(1, HermitePolynomial.H(0).evaluate(0));
        assertEquals(2, HermitePolynomial.H(1).evaluate(0));
        assertEquals(4, HermitePolynomial.H(2).evaluate(0));
    }

    @Test
    public void testLaguerrePolynomials() {
        assertEquals(1, LaguerrePolynomial.L(0).evaluate(0));
        assertEquals(-x + 1, LaguerrePolynomial.L(1).evaluate(0));
        assertEquals(0.5 * x * x - 2 * x + 1, LaguerrePolynomial.L(2).evaluate(0));
    }

    @Test
    public void testLegendrePolynomials() {
        assertEquals(1, LegendrePolynomial.P(0).evaluate(0));
        assertEquals(0.5 * (3 * x - 1), LegendrePolynomial.P(1).evaluate(0));
        assertEquals(0.5 * (5 * x * x - 3), LegendrePolynomial.P(2).evaluate(0));
    }

    @Test
    public void testJacobiPolynomials() {
        assertEquals(1, JacobiPolynomial.J(0, 0, 0).evaluate(0));
        assertEquals(0.5 * (2 * x + 1), JacobiPolynomial.J(1, 0, 0).evaluate(0));
    }

    @Test
    public void testPolynomialDifferentiation() {
        Polynomial p = ChebyshevPolynomial.T(3);
        Polynomial dp = p.differentiate();
        assertEquals(0, dp.evaluate(1));
    }

    @Test
    public void testOrthogonality() {
        assertTrue(OrthogonalityTest.isOrthogonal(ChebyshevPolynomial.T(0), ChebyshevPolynomial.T(1), -1, 1));
        assertTrue(OrthogonalityTest.isOrthogonal(LegendrePolynomial.P(0), LegendrePolynomial.P(1), -1, 1));
    }

    @Test
    public void testChebyshevBounds() {
        for (double x = -1; x <= 1; x += 0.1) {
            assertTrue(Math.abs(ChebyshevPolynomial.T(5).evaluate(x)) <= 1);
        }
    }

    @Test
    public void testHighDegreeLegendre() {
        double[] expectedCoefficients = {1, 0, -0.5, 0, 0.5, 0, -0.5};
        assertArrayEquals(expectedCoefficients, LegendrePolynomial.P(5).getCoefficients());
    }

    @Test
    public void testPolynomialShifting() {
        Polynomial p = ChebyshevPolynomial.T(2);
        Polynomial shifted = p.shift(1);
        assertEquals(shifted.evaluate(0), p.evaluate(-1));
    }
}

