public class TestMemoryRowBlock {
    private MemoryRowBlock memoryRowBlock;

    @BeforeEach
    public void setUp() {
        memoryRowBlock = new MemoryRowBlock();
    }

    @Test
    public void testAllocationAndValidation() {
        memoryRowBlock.allocate(10);
        for (int i = 0; i < 10; i++) {
            memoryRowBlock.setRow(i, new Object[]{true, i, (float) i * 1.5, "text" + i});
        }
        for (int i = 0; i < 10; i++) {
            Object[] row = memoryRowBlock.getRow(i);
            assertEquals(true, row[0]);
            assertEquals(i, row[1]);
            assertEquals((float) i * 1.5, row[2]);
            assertEquals("text" + i, row[3]);
        }
    }

    @Test
    public void testNullityHandling() {
        memoryRowBlock.allocate(5);
        memoryRowBlock.setRow(0, new Object[]{null, null, null, null});
        Object[] row = memoryRowBlock.getRow(0);
        assertNull(row[0]);
        assertNull(row[1]);
        assertNull(row[2]);
        assertNull(row[3]);
    }

    @Test
    public void testEmptyRowHandling() {
        memoryRowBlock.allocate(1);
        memoryRowBlock.setRow(0, new Object[]{});
        Object[] row = memoryRowBlock.getRow(0);
        assertArrayEquals(new Object[]{}, row);
    }

    @Test
    public void testSorting() {
        memoryRowBlock.allocate(5);
        for (int i = 0; i < 5; i++) {
            memoryRowBlock.setRow(i, new Object[]{i});
        }
        long startTime = System.nanoTime();
        memoryRowBlock.sortByColumn(0);
        long endTime = System.nanoTime();
        System.out.println("Sorting time: " + (endTime - startTime) + " ns");
    }

    @Test
    public void testVTupleOperations() {
        memoryRowBlock.allocate(3);
        VTuple vTuple1 = new VTuple(new Object[]{1, "tuple1"});
        memoryRowBlock.setRow(0, vTuple1);
        VTuple vTuple2 = (VTuple) memoryRowBlock.getRow(0);
        assertEquals(vTuple1, vTuple2);
    }

    @Test
    public void testSerializationDeserialization() {
        memoryRowBlock.allocate(2);
        memoryRowBlock.setRow(0, new Object[]{1, "test"});
        byte[] serialized = memoryRowBlock.serialize();
        MemoryRowBlock deserializedBlock = MemoryRowBlock.deserialize(serialized);
        Object[] row = deserializedBlock.getRow(0);
        assertEquals(1, row[0]);
        assertEquals("test", row[1]);
    }

    @Test
    public void testErrorHandling() {
        memoryRowBlock.allocate(1);
        memoryRowBlock.setRow(0, new Object[]{1});
        Exception exception = assertThrows(IllegalStateException.class, () -> {
            memoryRowBlock.setRow(1, new Object[]{2});
        });
        assertEquals("Memory limit exceeded", exception.getMessage());
    }
}

