public class N3JenaWriterCommon implements RDFWriter {
    private Map<String, String> prefixMappings = new HashMap<>();
    private boolean prettyPrint = false;
    private boolean useCompactNotation = false;

    public void setPrefix(String prefix, String uri) {
        prefixMappings.put(prefix, uri);
    }

    public void setPrettyPrint(boolean prettyPrint) {
        this.prettyPrint = prettyPrint;
    }

    public void setUseCompactNotation(boolean useCompactNotation) {
        this.useCompactNotation = useCompactNotation;
    }

    public void write(Model model, OutputStream output) {
        PrintWriter writer = new PrintWriter(output);
        try {
            writeModel(model, writer);
        } catch (Exception e) {
            handleError(e);
        } finally {
            writer.close();
        }
    }

    private void writeModel(Model model, PrintWriter writer) {
        if (prettyPrint) {
            writer.println("@prefix : <" + model.getNsPrefixURI("") + "> .");
            for (String prefix : prefixMappings.keySet()) {
                writer.println("@prefix " + prefix + ": <" + prefixMappings.get(prefix) + "> .");
            }
        }

        StmtIterator it = model.listStatements();
        while (it.hasNext()) {
            Statement stmt = it.nextStatement();
            writer.print(formatResource(stmt.getSubject()) + " ");
            writer.print(formatProperty(stmt.getPredicate()) + " ");
            writer.print(formatValue(stmt.getObject()) + " .\n");
        }
    }

    private String formatResource(Resource resource) {
        return useCompactNotation ? compactResource(resource) : resource.toString();
    }

    private String formatProperty(Property property) {
        return useCompactNotation ? compactProperty(property) : property.toString();
    }

    private String formatValue(Literal value) {
        return value.toString();
    }

    private String compactResource(Resource resource) {
        // Logic for compacting resource
        return resource.toString();
    }

    private String compactProperty(Property property) {
        // Logic for compacting property
        return property.toString();
    }

    private void handleError(Exception e) {
        // Handle error (e.g., log it)
        System.err.println("Error writing RDF: " + e.getMessage());
    }
}

