public class DelegatingBroker implements Broker {
    private final Broker delegate;
    private final RuntimeExceptionTranslator exceptionTranslator;
    private final Broker innermostDelegate;

    public DelegatingBroker(Broker delegate, RuntimeExceptionTranslator exceptionTranslator) {
        this.delegate = delegate;
        this.exceptionTranslator = exceptionTranslator;
        this.innermostDelegate = getInnermostDelegate(delegate);
    }

    private Broker getInnermostDelegate(Broker broker) {
        while (broker instanceof DelegatingBroker) {
            broker = ((DelegatingBroker) broker).delegate;
        }
        return broker;
    }

    @Override
    public void beginTransaction() {
        try {
            delegate.beginTransaction();
        } catch (RuntimeException e) {
            throw exceptionTranslator.translate(e);
        }
    }

    @Override
    public void commitTransaction() {
        try {
            delegate.commitTransaction();
        } catch (RuntimeException e) {
            throw exceptionTranslator.translate(e);
        }
    }

    @Override
    public void rollbackTransaction() {
        try {
            delegate.rollbackTransaction();
        } catch (RuntimeException e) {
            throw exceptionTranslator.translate(e);
        }
    }

    @Override
    public Object retrieve(Object id) {
        try {
            return delegate.retrieve(id);
        } catch (RuntimeException e) {
            throw exceptionTranslator.translate(e);
        }
    }

    @Override
    public void persist(Object object) {
        try {
            delegate.persist(object);
        } catch (RuntimeException e) {
            throw exceptionTranslator.translate(e);
        }
    }

    @Override
    public void configure(Configuration configuration) {
        try {
            delegate.configure(configuration);
        } catch (RuntimeException e) {
            throw exceptionTranslator.translate(e);
        }
    }

    @Override
    public int hashCode() {
        return innermostDelegate.hashCode();
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof DelegatingBroker)) return false;
        DelegatingBroker other = (DelegatingBroker) obj;
        return innermostDelegate.equals(other.innermostDelegate);
    }
}

