public class TestFetchGroups {

    private EntityManager entityManager;

    @Before
    public void setUp() {
        entityManager = Persistence.createEntityManagerFactory("testPU").createEntityManager();
        createTestData();
    }

    private void createTestData() {
        EntityTransaction transaction = entityManager.getTransaction();
        transaction.begin();

        // Create and persist managers and employees
        Manager manager = new Manager("John Doe");
        Employee employee1 = new Employee("Jane Smith", manager);
        Employee employee2 = new Employee("Bob Johnson", manager);

        entityManager.persist(manager);
        entityManager.persist(employee1);
        entityManager.persist(employee2);

        // Create and persist addresses and departments
        Address address = new Address("123 Main St", "Anytown", "12345");
        Department department = new Department("Engineering");

        entityManager.persist(address);
        entityManager.persist(department);

        transaction.commit();
    }

    @Test
    public void testDefaultFetchPlan() {
        Employee employee = entityManager.find(Employee.class, 1);
        Assert.assertNotNull(employee);
        Assert.assertNotNull(employee.getManager());
    }

    @Test
    public void testAddFetchGroup() {
        entityManager.getEntityManagerFactory().getCache().evictAll();
        entityManager.setProperty("openjpa.FetchGroup", "employeeWithAddress");

        Employee employee = entityManager.find(Employee.class, 1);
        Assert.assertNotNull(employee.getAddress());
    }

    @Test
    public void testRemoveFetchGroup() {
        entityManager.getEntityManagerFactory().getCache().evictAll();
        entityManager.setProperty("openjpa.FetchGroup", null);

        Employee employee = entityManager.find(Employee.class, 1);
        Assert.assertNull(employee.getAddress());
    }

    @Test
    public void testFetchGroupIntegrity() {
        List<Employee> employees = entityManager.createQuery("SELECT e FROM Employee e", Employee.class).getResultList();
        Assert.assertEquals(2, employees.size());
        for (Employee employee : employees) {
            Assert.assertNotNull(employee.getManager());
        }
    }
}

