public class BrachaTouegDeadlockComputation extends BasicComputation {
    private Map<String, VertexState> vertexStates;
    private String initiator;

    public BrachaTouegDeadlockComputation(String initiator) {
        this.initiator = initiator;
        this.vertexStates = new HashMap<>();
    }

    @Override
    public void initialize() {
        for (String vertex : getVertices()) {
            vertexStates.put(vertex, VertexState.FREE);
        }
        notifyVertices();
    }

    private void notifyVertices() {
        for (String vertex : getVertices()) {
            if (!vertex.equals(initiator)) {
                sendMessage(vertex, MessageType.NOTIFY);
            }
        }
    }

    @Override
    public void processMessage(String sender, MessageType messageType) {
        switch (messageType) {
            case NOTIFY:
                handleNotify(sender);
                break;
            case GRANT:
                handleGrant(sender);
                break;
            case DONE:
                handleDone(sender);
                break;
            case ACK:
                handleAck(sender);
                break;
            default:
                break;
        }
    }

    private void handleNotify(String sender) {
        vertexStates.put(sender, VertexState.NOTIFIED);
        sendMessage(sender, MessageType.GRANT);
    }

    private void handleGrant(String sender) {
        vertexStates.put(sender, VertexState.PENDING);
        if (allVerticesNotified()) {
            sendMessage(initiator, MessageType.DONE);
        }
    }

    private void handleDone(String sender) {
        vertexStates.put(sender, VertexState.FREE);
        sendMessage(sender, MessageType.ACK);
    }

    private void handleAck(String sender) {
        vertexStates.put(sender, VertexState.FREE);
    }

    private boolean allVerticesNotified() {
        return vertexStates.values().stream().allMatch(state -> state == VertexState.NOTIFIED || state == VertexState.FREE);
    }

    private enum VertexState {
        FREE,
        NOTIFIED,
        PENDING
    }
}

