        assertFalse(electorService.isActive());
    }
}

public class JSPCompiler {

    static class SecondPassVisitor extends Node.Visitor implements TagConstants {
        private StringBuilder xmlBuffer;

        public SecondPassVisitor() {
            xmlBuffer = new StringBuilder();
        }

        public void visitRootNode(RootNode rootNode) {
            appendXMLProlog();
            for (Node child : rootNode.getChildren()) {
                child.accept(this);
            }
        }

        public void visitDirectiveNode(DirectiveNode directiveNode) {
            xmlBuffer.append("<directive name=\"").append(escapeXML(directiveNode.getName())).append("\">")
                     .append(directiveNode.getContent())
                     .append("</directive>");
        }

        public void visitExpressionNode(ExpressionNode expressionNode) {
            xmlBuffer.append("<expression>").append(escapeXML(expressionNode.getExpression())).append("</expression>");
        }

        public void visitScriptletNode(ScriptletNode scriptletNode) {
            xmlBuffer.append("<scriptlet><![CDATA[").append(scriptletNode.getContent()).append("]]></scriptlet>");
        }

        public void visitCustomTagNode(CustomTagNode customTagNode) {
            xmlBuffer.append("<customTag name=\"").append(escapeXML(customTagNode.getTagName())).append("\">");
            for (Attribute attribute : customTagNode.getAttributes()) {
                xmlBuffer.append("<attribute name=\"").append(escapeXML(attribute.getName())).append("\" value=\"")
                         .append(escapeXML(attribute.getValue())).append("\"/>");
            }
            xmlBuffer.append("</customTag>");
        }

        private void appendXMLProlog() {
            xmlBuffer.append("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
        }

        private String escapeXML(String content) {
            if (content == null) return null;
            return content.replace("&", "&amp;")
                          .replace("<", "&lt;")
                          .replace(">", "&gt;")
                          .replace("\"", "&quot;")
                          .replace("'", "&apos;");
        }

        public String getXML() {
            return xmlBuffer.toString();
        }
    }
}

